    private val gen2CommonPCItemIds=gen2OrdinaryItemIds+gen2BallItemIds+gen2PCMachineItemIds+gen2PCKeyItemIds
    private fun gen2PCItemIds(profile:Gen2Profile):Set<Int> = if(profile.key=="C")gen2CommonPCItemIds+gen2CrystalOnlyPCItemIds else gen2CommonPCItemIds

    private fun gen2TMHMStorageBase(profile:Gen2Profile):Int = if(profile.key=="C")0x23E7 else 0x23E6

    private fun parseGen2TMHMStorage(data:ByteArray,profile:Gen2Profile):List<Int>?{
        val base=gen2TMHMStorageBase(profile);if(base<0||base+57>data.size)return null;val out=ArrayList<Int>()
        for(i in 0 until 57){val quantity=data[base+i].toInt()and 0xFF;val max=if(i<50)99 else 1;if(quantity !in 0..max)return null;out.add(quantity)}
        return out
    }

    private fun writeGen2TMHMStorage(data:ByteArray,profile:Gen2Profile,quantities:List<Int>){
        require(quantities.size==57){"The Gen 2 TM/HM pocket must contain exactly 57 fixed slots."};require(quantities.withIndex().all{(i,q)->q in 0..(if(i<50)99 else 1)}){"A Gen 2 TM or HM quantity is invalid."}
        val base=gen2TMHMStorageBase(profile);require(base+57<=data.size){"The Gen 2 TM/HM pocket is outside the save."};for((i,q)in quantities.withIndex())data[base+i]=q.toByte()
    }

    private fun showGen2TMHMStorageEditor(){
        val openedUri=currentSourceUri;val openedLabel=currentSourceLabel
        phoneBackAction={showGen2InventoryEditor()};val file=importedFile?:return;val opened=runCatching{file.readBytes()}.getOrNull()?:return
        fun bound()=importedFile?.absolutePath==file.absolutePath&&currentSourceUri==openedUri&&currentSourceLabel==openedLabel
        val openedProfile=detectGen2Profile(opened)?:run{showDialog("Gen 2 TMs / HMs","This editor requires a valid Pokémon Gold, Silver or Crystal save.");return};val base=gen2TMHMStorageBase(openedProfile);val openedStorage=opened.copyOfRange(base,base+57)
        val quantities=parseGen2TMHMStorage(opened,openedProfile)?.toMutableList()?:run{showDialog("Gen 2 TMs / HMs","The TM/HM pocket structure is invalid. Nothing was changed.");return}
        val root=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(dp(18),dp(52),dp(18),dp(28));setBackgroundColor(BG)}
        root.addView(TextView(this).apply{text="Gen 2 TMs / HMs";textSize=30f;typeface=Typeface.DEFAULT_BOLD;setTextColor(TEXT)})
        addMutedLine(root,"Edit quantities or remove existing machines for Gold, Silver and Crystal. TM01–TM50 allow quantities of 1–99; HM01–HM07 are ownership flags and remain capped at 1.")
        addMutedLine(root,"Add an unowned machine by fixed slot: 1–50 are TM01–TM50 and 51–57 are HM01–HM07. HMs are ownership flags and must use quantity 1.")
        root.addView(TextView(this).apply{text="Owned machines: ${quantities.count{it>0}} / 57";textSize=16f;typeface=Typeface.DEFAULT_BOLD;setTextColor(TEXT);setPadding(0,dp(12),0,dp(8))})
        var consumed=false
        fun save(next:List<Int>){
            if(consumed){showDialog("Gen 2 TMs / HMs","This edit was already submitted. Reopen TMs / HMs before saving again.");return}
            if(importedFile?.absolutePath!=file.absolutePath){showDialog("Gen 2 TM/HM edit failed","The active save changed. Reopen Items before editing TMs / HMs. Nothing was changed.");return}
            if(!bound()){showDialog("Gen 2 TM/HM edit failed","The source identity changed. Reopen TMs / HMs before editing. Nothing was changed.");return}
            consumed=true
            val fresh=runCatching{file.readBytes()}.getOrElse{showDialog("Gen 2 TM/HM edit failed","The fresh Gen 2 save could not be read. Nothing was changed.");return}
            var safetyBackup:File?=null
            var writeStarted=false
            try{
                require(bound()&&verifyGen2SaveIntegrity(fresh).first){"The confirmed Gen 2 source identity or full save integrity changed."}
                val profile=detectGen2Profile(fresh)?:error("The fresh Gen 2 save failed checksum or structural validation.");require(profile.key==openedProfile.key){"The Gen 2 game profile changed while TMs / HMs was open."};val freshBase=gen2TMHMStorageBase(profile);require(fresh.copyOfRange(freshBase,freshBase+57).contentEquals(openedStorage)){"The TM/HM pocket changed after this screen was opened. Reopen Items and try again."};require(parseGen2TMHMStorage(fresh,profile)!=null){"The fresh TM/HM pocket structure is invalid."}
                val expected=next.toList();val work=fresh.copyOf();writeGen2TMHMStorage(work,profile,expected);updateGen2PrimaryChecksum(work,profile);require(parseGen2TMHMStorage(work,profile)==expected){"The staged TM/HM pocket did not verify exactly."}
                require(work.indices.all{it in freshBase until freshBase+57||it in profile.checksumOffset..profile.checksumOffset+1||work[it]==fresh[it]}){"The Gen 2 TM/HM edit changed unrelated save data."}
                val stagedProfile=detectGen2Profile(work)?:error("The staged Gen 2 save failed checksum or structural verification.");require(stagedProfile.key==profile.key&&gen2ChecksumValid(work,stagedProfile)&&parseGen2TMHMStorage(work,stagedProfile)==expected){"The staged Gen 2 TM/HM pocket did not verify exactly."}
                require(verifyGen2SaveIntegrity(work).first){"The complete staged Gen 2 save failed integrity validation."}
                require(importedFile?.absolutePath==file.absolutePath&&file.readBytes().contentEquals(fresh)){"The Gen 2 source changed while the TM/HM edit was staged. Nothing was written."}
                require(bound()){"The confirmed Gen 2 source identity changed before backup."}
                val backup=File.createTempFile(backupGameName(file)+"_PreGen2TMHM_",".backup",backupsDir());safetyBackup=backup
                backup.writeBytes(fresh);require(backup.readBytes().contentEquals(fresh)){"The exact pre-edit recovery backup could not be verified."}
                retainGen2SafetyBackup(backup,fresh)
                require(bound()&&isBackupKept(backup)&&backup.readBytes().contentEquals(fresh)&&file.readBytes().contentEquals(fresh)){"The confirmed source or retained recovery backup changed before writing."}
                writeStarted=true
                file.writeBytes(work);val persisted=file.readBytes();require(persisted.contentEquals(work)){"The Gen 2 save changed while the TM/HM pocket was written."};val persistedProfile=detectGen2Profile(persisted)?:error("The persisted Gen 2 save failed checksum or structural verification.");require(persistedProfile.key==profile.key&&gen2ChecksumValid(persisted,persistedProfile)&&parseGen2TMHMStorage(persisted,persistedProfile)==expected){"The persisted Gen 2 TM/HM pocket did not match the staged edit."}
                require(bound()&&verifyGen2SaveIntegrity(persisted).first&&file.readBytes().contentEquals(work)){"The persisted Gen 2 source identity or complete save verification failed."}
            }catch(e:Exception){
                val restored=writeStarted&&runCatching{file.writeBytes(fresh)}.isSuccess&&runCatching{file.readBytes().contentEquals(fresh)}.getOrDefault(false)
                val recovery=if(!writeStarted)"Nothing was written to the save." else  if(restored)"The complete fresh working save was restored." else  "Automatic restore could not be verified. Stop editing this save and restore a verified backup."
                showDialog("Gen 2 TM/HM edit failed",(e.message?:"Unknown error")+"\n\n$recovery"+(safetyBackup?.let{"\n\nRecovery backup: "+it.name}?:""));return
            }
            Toast.makeText(this,"Gen 2 TMs / HMs updated and verified",Toast.LENGTH_LONG).show();showGen2InventoryEditor()
        }
        val addCard=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(dp(12),dp(10),dp(12),dp(10));background=roundedBg(CARD,Color.rgb(25,75,100),12)}
        addCard.addView(TextView(this).apply{text="Add unowned TM / HM";textSize=17f;typeface=Typeface.DEFAULT_BOLD;setTextColor(TEXT)})
        addMutedLine(addCard,"Slots use the exact Gen 2 TM/HM move mapping; owned machine cards show the corresponding move name.")
        val newQuantity=EditText(this).apply{hint="TM quantity 1–99; HM quantity is fixed at 1";inputType=android.text.InputType.TYPE_CLASS_NUMBER;setTextColor(TEXT);setHintTextColor(MUTED)}
        var newSlotValue:Int?=null;val newMachine=selectorButton("Machine","Choose an unowned TM / HM").also{addCard.addView(it.first)}.second
        newMachine.setOnClickListener{val choices=canonicalGen2TMHMChoices().filter{quantities[it.id-1]==0};if(choices.isEmpty())showDialog("All machines owned","Every Gen 2 TM/HM slot is already owned.")else showSearchableChoiceDialog("Choose an unowned Gen 2 TM / HM",choices){chosen->newSlotValue=chosen.id;newMachine.text=chosen.toString();if(chosen.id>50)newQuantity.setText("1")}}
        addCard.addView(newQuantity)
        addCard.addView(Button(this).apply{text="Add machine";setAllCaps(false);setOnClickListener{val slotValue=newSlotValue;val quantityValue=newQuantity.text.toString().toIntOrNull();val indexValue=(slotValue?:0)-1;if(slotValue==null||slotValue !in 1..57)showDialog("Choose a machine","Choose an unowned TM or HM from the verified Gen 2 machine catalogue.")else if(quantities[indexValue]>0)showDialog("Machine already owned","Edit the existing machine instead of adding it again.")else if(indexValue>=50&&quantityValue!=1)showDialog("Invalid HM quantity","HM ownership must use quantity 1.")else if(indexValue<50&&(quantityValue==null||quantityValue !in 1..99))showDialog("Invalid TM quantity","TM quantity must be 1–99.")else{val next=quantities.toMutableList();next[indexValue]=if(indexValue>=50)1 else quantityValue!!;save(next)}}});root.addView(addCard,LinearLayout.LayoutParams(-1,-2).apply{bottomMargin=dp(12)})
        for((index,stored)in quantities.withIndex()){
            if(stored==0)continue;val isHM=index>=50;val label=if(isHM)"HM"+(index-49).toString().padStart(2,'0') else "TM"+(index+1).toString().padStart(2,'0')
            val card=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(dp(12),dp(10),dp(12),dp(10));background=roundedBg(CARD,Color.rgb(25,75,100),12)}
            card.addView(TextView(this).apply{text="$label • ${gen2MachineMoveName(index)?:"Unknown move"}";textSize=17f;typeface=Typeface.DEFAULT_BOLD;setTextColor(TEXT)});card.addView(TextView(this).apply{text=if(isHM)"Owned • fixed quantity 1" else "Quantity $stored";textSize=13f;setTextColor(MUTED)});val actions=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL}
            if(!isHM){val quantity=EditText(this).apply{setText(stored.toString());hint="Quantity 1–99";inputType=android.text.InputType.TYPE_CLASS_NUMBER;setTextColor(TEXT);setHintTextColor(MUTED)};card.addView(quantity);actions.addView(Button(this).apply{text="Save quantity";setAllCaps(false);setOnClickListener{val value=quantity.text.toString().toIntOrNull();if(value==null||value !in 1..99)showDialog("Invalid quantity","TM quantity must be 1–99.")else{val next=quantities.toMutableList();next[index]=value;save(next)}}},LinearLayout.LayoutParams(0,dp(48),1f))}
            actions.addView(Button(this).apply{text="Remove";setAllCaps(false);setOnClickListener{val next=quantities.toMutableList();next[index]=0;save(next)}},LinearLayout.LayoutParams(0,dp(48),1f));card.addView(actions);root.addView(card,LinearLayout.LayoutParams(-1,-2).apply{bottomMargin=dp(8)})
        }
        addMutedLine(root,"PSE preserves all 57 fixed slots, rebuilds the Gen 2 checksum, rejects stale state without writing, verifies exact persistence, and verifies any attempted restore after a write failure. A retained recovery backup is required before saving.")
        addButton(root,"←  Gen 2 Items"){showGen2InventoryEditor()};setContentView(ScrollView(this).apply{addView(root)})
    }

    private fun gen2PCItemStorageBase(profile:Gen2Profile):Int = if(profile.key=="C")0x247F else 0x247E

    private fun parseGen2PCItemStorage(data:ByteArray,profile:Gen2Profile):List<Pair<Int,Int>>?{
        val base=gen2PCItemStorageBase(profile);if(base<0||base+102>data.size)return null;val count=data[base].toInt()and 0xFF;if(count !in 0..50)return null
        if((data[base+1+count*2].toInt()and 0xFF)!=0xFF)return null;val out=ArrayList<Pair<Int,Int>>()
        for(i in 0 until count){val id=data[base+1+i*2].toInt()and 0xFF;val quantity=data[base+2+i*2].toInt()and 0xFF;if(id !in 1..254||quantity !in 1..99)return null;out.add(id to quantity)}
        return out
    }

    private fun writeGen2PCItemStorage(data:ByteArray,profile:Gen2Profile,items:List<Pair<Int,Int>>){
        require(items.size<=50){"The Gen 2 PC item storage exceeds its 50-stack capacity."};require(items.all{it.first in 1..254&&it.second in 1..99}){"A Gen 2 PC item ID or quantity is invalid."}
        val base=gen2PCItemStorageBase(profile);require(base+102<=data.size){"The Gen 2 PC item storage is outside the save."};data[base]=items.size.toByte();java.util.Arrays.fill(data,base+1,base+102,0.toByte())
        for((i,item)in items.withIndex()){data[base+1+i*2]=item.first.toByte();data[base+2+i*2]=item.second.toByte()};data[base+1+items.size*2]=0xFF.toByte()
    }

