                val expected=next.map{it.id to it.quantity};val work=fresh.copyOf();writeGen2PCItemStorage(work,profile,expected);updateGen2PrimaryChecksum(work,profile);require(parseGen2PCItemStorage(work,profile)==expected){"The staged PC item storage did not verify exactly."}
                require(work.indices.all{it in freshBase until freshBase+102||it in profile.checksumOffset..profile.checksumOffset+1||work[it]==fresh[it]}){"The Gen 2 PC item edit changed unrelated save data."}
                val stagedProfile=detectGen2Profile(work)?:error("The staged Gen 2 save failed checksum or structural verification.");require(stagedProfile.key==profile.key&&gen2ChecksumValid(work,stagedProfile)&&parseGen2PCItemStorage(work,stagedProfile)==expected){"The staged Gen 2 PC item storage did not verify exactly."}
                require(verifyGen2SaveIntegrity(work).first){"The complete staged Gen 2 save failed integrity validation."}
                require(importedFile?.absolutePath==file.absolutePath&&file.readBytes().contentEquals(fresh)){"The Gen 2 source changed while the PC item edit was staged. Nothing was written."}
