                val backup=File.createTempFile(backupGameName(file)+"_PreGen2PCItems_",".backup",backupsDir());safetyBackup=backup
                backup.writeBytes(fresh);require(backup.readBytes().contentEquals(fresh)){"The exact pre-edit recovery backup could not be verified."}
                retainGen2SafetyBackup(backup,fresh)
                require(bound()&&isBackupKept(backup)&&backup.readBytes().contentEquals(fresh)&&file.readBytes().contentEquals(fresh)){"The confirmed source or retained recovery backup changed before writing."}
                writeStarted=true
                file.writeBytes(work);val persisted=file.readBytes();require(persisted.contentEquals(work)){"The Gen 2 save changed while PC item storage was written."};val persistedProfile=detectGen2Profile(persisted)?:error("The persisted Gen 2 save failed checksum or structural verification.");require(persistedProfile.key==profile.key&&gen2ChecksumValid(persisted,persistedProfile)&&parseGen2PCItemStorage(persisted,persistedProfile)==expected){"The persisted Gen 2 PC item storage did not match the staged edit."}
