    private fun gen2KeyItemPocketIds(profile:Gen2Profile):Set<Int> = if(profile.key=="C")gen2PCKeyItemIds+gen2CrystalOnlyPCItemIds else gen2PCKeyItemIds

    private fun gen2KeyItemPocketBase(profile:Gen2Profile):Int = if(profile.key=="C")0x244A else 0x2449

    private fun parseGen2KeyItemPocket(data:ByteArray,profile:Gen2Profile):List<Int>?{
        val base=gen2KeyItemPocketBase(profile);if(base<0||base+27>data.size)return null;val count=data[base].toInt()and 0xFF;if(count !in 0..25)return null
        if((data[base+1+count].toInt()and 0xFF)!=0xFF)return null;val out=ArrayList<Int>()
        for(i in 0 until count){val id=data[base+1+i].toInt()and 0xFF;if(id !in 1..254)return null;out.add(id)}
        return out
    }

    private fun writeGen2KeyItemPocket(data:ByteArray,profile:Gen2Profile,items:List<Int>){
        require(items.size<=25){"The Gen 2 Key Item Pocket exceeds its 25-item capacity."};require(items.all{it in 1..254}){"A Gen 2 key-item ID is invalid."}
        val base=gen2KeyItemPocketBase(profile);require(base+27<=data.size){"The Gen 2 Key Item Pocket is outside the save."};data[base]=items.size.toByte();java.util.Arrays.fill(data,base+1,base+27,0.toByte())
        for((i,id)in items.withIndex())data[base+1+i]=id.toByte();data[base+1+items.size]=0xFF.toByte()
    }

