        val openedUri=currentSourceUri;val openedLabel=currentSourceLabel
        phoneBackAction={showGen2InventoryEditor()};val file=importedFile?:return;val opened=runCatching{file.readBytes()}.getOrNull()?:return
        fun bound()=importedFile?.absolutePath==file.absolutePath&&currentSourceUri==openedUri&&currentSourceLabel==openedLabel
        val openedProfile=detectGen2Profile(opened)?:run{showDialog("Gen 2 Key Items","This editor requires a valid Pokémon Gold, Silver or Crystal save.");return};val base=gen2KeyItemPocketBase(openedProfile);val openedPocket=opened.copyOfRange(base,base+27)
        val items=parseGen2KeyItemPocket(opened,openedProfile)?.toMutableList()?:run{showDialog("Gen 2 Key Items","The Key Item Pocket structure is invalid. Nothing was changed.");return};val allowedKeyItemIds=gen2KeyItemPocketIds(openedProfile)
        val root=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(dp(18),dp(52),dp(18),dp(28));setBackgroundColor(BG)}
