        root.addView(TextView(this).apply{text="Key Items: ${items.size} / 25";textSize=16f;typeface=Typeface.DEFAULT_BOLD;setTextColor(TEXT);setPadding(0,dp(12),0,dp(8))})
        var consumed=false
        fun save(next:List<Int>){
            if(consumed){showDialog("Gen 2 Key Items","This edit was already submitted. Reopen Key Items before saving again.");return}
            if(importedFile?.absolutePath!=file.absolutePath){showDialog("Gen 2 Key Item edit failed","The active save changed. Reopen Items before editing Key Items. Nothing was changed.");return}
            if(!bound()){showDialog("Gen 2 Key Item edit failed","The source identity changed. Reopen Key Items before editing. Nothing was changed.");return}
            consumed=true
            val fresh=runCatching{file.readBytes()}.getOrElse{showDialog("Gen 2 Key Item edit failed","The fresh Gen 2 save could not be read. Nothing was changed.");return}
            var safetyBackup:File?=null
            var writeStarted=false
            try{
                require(bound()&&verifyGen2SaveIntegrity(fresh).first){"The confirmed Gen 2 source identity or full save integrity changed."}
                val profile=detectGen2Profile(fresh)?:error("The fresh Gen 2 save failed checksum or structural validation.");require(profile.key==openedProfile.key){"The Gen 2 game profile changed while Key Items was open."};val freshBase=gen2KeyItemPocketBase(profile);require(fresh.copyOfRange(freshBase,freshBase+27).contentEquals(openedPocket)){"The Key Item Pocket changed after this screen was opened. Reopen Items and try again."};require(parseGen2KeyItemPocket(fresh,profile)!=null){"The fresh Key Item Pocket structure is invalid."}
                val expected=next.toList();val work=fresh.copyOf();writeGen2KeyItemPocket(work,profile,expected);updateGen2PrimaryChecksum(work,profile);require(parseGen2KeyItemPocket(work,profile)==expected){"The staged Key Item Pocket did not verify exactly."}
                require(work.indices.all{it in freshBase until freshBase+27||it in profile.checksumOffset..profile.checksumOffset+1||work[it]==fresh[it]}){"The Gen 2 Key Item edit changed unrelated save data."}
                val stagedProfile=detectGen2Profile(work)?:error("The staged Gen 2 save failed checksum or structural verification.");require(stagedProfile.key==profile.key&&gen2ChecksumValid(work,stagedProfile)&&parseGen2KeyItemPocket(work,stagedProfile)==expected){"The staged Gen 2 Key Item Pocket did not verify exactly."}
                require(verifyGen2SaveIntegrity(work).first){"The complete staged Gen 2 save failed integrity validation."}
                require(importedFile?.absolutePath==file.absolutePath&&file.readBytes().contentEquals(fresh)){"The Gen 2 source changed while the Key Item edit was staged. Nothing was written."}
                require(bound()){"The confirmed Gen 2 source identity changed before backup."}
                val backup=File.createTempFile(backupGameName(file)+"_PreGen2KeyItems_",".backup",backupsDir());safetyBackup=backup
                backup.writeBytes(fresh);require(backup.readBytes().contentEquals(fresh)){"The exact pre-edit recovery backup could not be verified."}
                retainGen2SafetyBackup(backup,fresh)
                require(bound()&&isBackupKept(backup)&&backup.readBytes().contentEquals(fresh)&&file.readBytes().contentEquals(fresh)){"The confirmed source or retained recovery backup changed before writing."}
                writeStarted=true
                file.writeBytes(work);val persisted=file.readBytes();require(persisted.contentEquals(work)){"The Gen 2 save changed while the Key Item Pocket was written."};val persistedProfile=detectGen2Profile(persisted)?:error("The persisted Gen 2 save failed checksum or structural verification.");require(persistedProfile.key==profile.key&&gen2ChecksumValid(persisted,persistedProfile)&&parseGen2KeyItemPocket(persisted,persistedProfile)==expected){"The persisted Gen 2 Key Item Pocket did not match the staged edit."}
                require(bound()&&verifyGen2SaveIntegrity(persisted).first&&file.readBytes().contentEquals(work)){"The persisted Gen 2 source identity or complete save verification failed."}
            }catch(e:Exception){
                val restored=writeStarted&&runCatching{file.writeBytes(fresh)}.isSuccess&&runCatching{file.readBytes().contentEquals(fresh)}.getOrDefault(false)
                val recovery=if(!writeStarted)"Nothing was written to the save." else  if(restored)"The complete fresh working save was restored." else  "Automatic restore could not be verified. Stop editing this save and restore a verified backup."
                showDialog("Gen 2 Key Item edit failed",(e.message?:"Unknown error")+"\n\n$recovery"+(safetyBackup?.let{"\n\nRecovery backup: "+it.name}?:""));return
            }
            Toast.makeText(this,"Gen 2 Key Items updated and verified",Toast.LENGTH_LONG).show();showGen2InventoryEditor()
        }
        val addCard=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(dp(12),dp(10),dp(12),dp(10));background=roundedBg(CARD,Color.rgb(25,75,100),12)}
        addCard.addView(TextView(this).apply{text="Add verified Key Item";textSize=17f;typeface=Typeface.DEFAULT_BOLD;setTextColor(TEXT)})
        var newKeyItemId:Int?=null;val newKeyItem=selectorButton("Key Item","Choose verified ${openedProfile.displayName} Key Item").also{addCard.addView(it.first)}.second
        newKeyItem.setOnClickListener{val choices=canonicalGen2ItemChoices(allowedKeyItemIds).filter{it.id !in items};if(choices.isEmpty())showDialog("No Key Items available","Every verified Key Item for ${openedProfile.displayName} is already in this pocket.")else showSearchableChoiceDialog("Choose ${openedProfile.displayName} Key Item",choices){chosen->newKeyItemId=chosen.id;newKeyItem.text=chosen.toString()}}
        addCard.addView(Button(this).apply{text="Add Key Item";setAllCaps(false);setOnClickListener{val idValue=newKeyItemId;if(idValue==null||idValue !in allowedKeyItemIds)showDialog("Choose a Key Item","Choose an item from the verified Key Item Pocket catalogue for ${openedProfile.displayName}.")else if(items.size>=25)showDialog("Key Item Pocket full","The Gen 2 Key Item Pocket already contains 25 entries.")else if(items.contains(idValue))showDialog("Key Item already present","The Key Item Pocket already contains item #$idValue.")else{val next=items.toMutableList();next.add(idValue);save(next)}}});root.addView(addCard,LinearLayout.LayoutParams(-1,-2).apply{bottomMargin=dp(12)})
        for((index,id)in items.withIndex()){
            val card=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL;gravity=Gravity.CENTER_VERTICAL;setPadding(dp(12),dp(10),dp(12),dp(10));background=roundedBg(CARD,Color.rgb(25,75,100),12)}
            card.addView(TextView(this).apply{text="${gen2ItemName(id)?:"Unknown item"} (#$id)\nStored ID $id";textSize=16f;setTextColor(TEXT)},LinearLayout.LayoutParams(0,-2,1f))
            card.addView(Button(this).apply{text="Remove";setAllCaps(false);setOnClickListener{val next=items.toMutableList();next.removeAt(index);save(next)}},LinearLayout.LayoutParams(dp(110),dp(48)));root.addView(card,LinearLayout.LayoutParams(-1,-2).apply{bottomMargin=dp(8)})
        }
        addMutedLine(root,"PSE compacts the ordered list, clears its stale tail, rebuilds the Gen 2 checksum, rejects stale state without writing, verifies exact persistence, and verifies any attempted restore after a write failure. A retained recovery backup is required before saving.")
        addButton(root,"←  Gen 2 Items"){showGen2InventoryEditor()};setContentView(ScrollView(this).apply{addView(root)})
    }

    private fun gen2BallPocketBase(profile:Gen2Profile):Int = if(profile.key=="C")0x2465 else 0x2464

    private fun parseGen2BallPocket(data:ByteArray,profile:Gen2Profile):List<Pair<Int,Int>>?{
        val base=gen2BallPocketBase(profile);if(base<0||base+26>data.size)return null;val count=data[base].toInt()and 0xFF;if(count !in 0..12)return null
        if((data[base+1+count*2].toInt()and 0xFF)!=0xFF)return null;val out=ArrayList<Pair<Int,Int>>()
        for(i in 0 until count){val id=data[base+1+i*2].toInt()and 0xFF;val quantity=data[base+2+i*2].toInt()and 0xFF;if(id !in 1..254||quantity !in 1..99)return null;out.add(id to quantity)}
        return out
    }

    private fun writeGen2BallPocket(data:ByteArray,profile:Gen2Profile,balls:List<Pair<Int,Int>>){
        require(balls.size<=12){"The Gen 2 Ball Pocket exceeds its 12-stack capacity."};require(balls.all{it.first in 1..254&&it.second in 1..99}){"A Gen 2 ball ID or quantity is invalid."}
        val base=gen2BallPocketBase(profile);require(base+26<=data.size){"The Gen 2 Ball Pocket is outside the save."};data[base]=balls.size.toByte();java.util.Arrays.fill(data,base+1,base+26,0.toByte())
        for((i,ball)in balls.withIndex()){data[base+1+i*2]=ball.first.toByte();data[base+2+i*2]=ball.second.toByte()};data[base+1+balls.size*2]=0xFF.toByte()
    }

    private fun showGen2InventoryEditor(){
        val inventorySource=currentSourceUri;val inventoryLabel=currentSourceLabel
        phoneBackAction={showHome()};val file=importedFile?:return;val data=runCatching{file.readBytes()}.getOrNull()?:return
        val profile=detectGen2Profile(data)?:run{showDialog("Gen 2 Items","This editor requires a valid Pokémon Gold, Silver or Crystal save.");return}
        fun verifiedInventorySource():Boolean {
            if(gen2ListSnapshotMatches(file,data,inventorySource,inventoryLabel))return true
            showDialog("Gen 2 Items","The save identity, bytes or integrity changed while Items was open. Reopen Items. Nothing was changed.");return false
        }
        val tmhm=parseGen2TMHMStorage(data,profile);val ordinary=parseGen2ItemPocket(data,profile);val keys=parseGen2KeyItemPocket(data,profile);val balls=parseGen2BallPocket(data,profile);val pc=parseGen2PCItemStorage(data,profile)
        val root=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(dp(18),dp(52),dp(18),dp(28));setBackgroundColor(BG)}
        root.addView(TextView(this).apply{text="Gen 2 Items";textSize=30f;typeface=Typeface.DEFAULT_BOLD;setTextColor(TEXT)})
        addMutedLine(root,"Choose a verified Gold, Silver or Crystal inventory pocket. Each pocket is edited independently and transactionally.")
        addButton(root,"TMs / HMs  •  ${tmhm?.count{it>0}?:0} / 57 owned"){if(!verifiedInventorySource())return@addButton;if(tmhm==null)showDialog("Gen 2 Items","The TM/HM pocket structure is invalid. Nothing was changed.")else showGen2TMHMStorageEditor()}
        addButton(root,"Item Pocket  •  ${ordinary?.size?:0} / 20 stacks"){if(!verifiedInventorySource())return@addButton;if(ordinary==null)showDialog("Gen 2 Items","The ordinary Item Pocket structure is invalid. Nothing was changed.")else showGen2ItemPocketEditor()}
        addButton(root,"Key Items  •  ${keys?.size?:0} / 25"){if(!verifiedInventorySource())return@addButton;if(keys==null)showDialog("Gen 2 Items","The Key Item Pocket structure is invalid. Nothing was changed.")else showGen2KeyItemPocketEditor()}
        addButton(root,"Ball Pocket  •  ${balls?.size?:0} / 12 stacks"){if(!verifiedInventorySource())return@addButton;if(balls==null)showDialog("Gen 2 Items","The Ball Pocket structure is invalid. Nothing was changed.")else showGen2BallPocketEditor()}
        addButton(root,"PC Item Storage  •  ${pc?.size?:0} / 50 stacks"){if(!verifiedInventorySource())return@addButton;if(pc==null)showDialog("Gen 2 Items","The PC item-storage structure is invalid. Nothing was changed.")else showGen2PCItemStorageEditor()}
        addMutedLine(root,"Each pocket uses its verified Gen 2 layout. Adding unowned machines or arbitrary item IDs remains locked.")
        addButton(root,"Apricorns / Kurt recipes  •  Read-only"){showGen2ApricornInventory(file,data,inventorySource,inventoryLabel)}
        if(profile.key=="GS")addButton(root,"Kurt batch  •  Mark finished (Gold / Silver)"){confirmGen2GoldSilverKurtFinish(file,data,inventorySource,inventoryLabel)}
        if(profile.key=="C")addButton(root,"Kurt batch  •  Mark finished (Crystal)"){confirmGen2CrystalKurtFinish(file,data,inventorySource,inventoryLabel)}
        addButton(root,"←  Home"){showHome()};setContentView(ScrollView(this).apply{addView(root)})
    }

    // Canonical recipe/item IDs: pret/pokecrystal 3bc8daa4173e96a7f4011dad3922eb6fa5dad5c6
    // data/items/apricorn_balls.asm + constants/item_constants.asm; Gold/Silver recipes
    // cross-checked in pret/pokegold ef0201d8daf47e8b3ea1518eacf890f37d4cd5e8 maps/KurtsHouse.asm.
    private val gen2ApricornRecipes=listOf(0x55 to 0x9F,0x59 to 0xA0,0x5C to 0xA5,0x5D to 0xA4,0x61 to 0xA1,0x63 to 0x9D,0x65 to 0xA6)

    // Western EventFlag bases: PKHeX 641c26ba100225f3605e5a44b61b3b16e15a3774 SAV2Offsets.cs.
    // Kurt hand-in flags 600..606: pinned pokegold/pokecrystal constants/event_flags.asm,
    // in the same Red/Blue/Yellow/Green/White/Black/Pink order as gen2ApricornRecipes.
    private fun gen2KurtHandInRecipes(data:ByteArray,profile:Gen2Profile):List<Pair<Int,Int>> {
        require(verifyGen2SaveIntegrity(data).first&&detectGen2Profile(data)?.key==profile.key){"The Gen 2 save/profile is not verified."}
        val base=when(profile.key){"GS"->0x261F;"C"->0x2600;else->error("Unsupported Gen 2 hand-in flag profile.")}
        val offset=base+600/8
        require(offset in data.indices){"The Gen 2 hand-in flags are outside the save."}
        val flags=data[offset].toInt()and 0xFF
        return gen2ApricornRecipes.filterIndexed{index,_->flags and(1 shl index)!=0}
    }

    // Saved player-data layout: pinned pret/pokegold/pokecrystal ram/wram.asm,
    // anchored at PKHeX Western wCurBox offsets 0x2724/0x2700 (+0xAC to wDailyFlags1).
    // Crystal quantity: wBlueCardBalance 0x27D9 +0x59 = wKurtApricornQuantity 0x2832.
    // DAILYFLAGS1_KURT_MAKING_BALLS_F is bit0; Gold/Silver has no quantity field.
    private data class Gen2KurtSavedWork(val making:Boolean,val quantity:Int?)

    private fun gen2KurtSavedWork(data:ByteArray,profile:Gen2Profile):Gen2KurtSavedWork {
        require(verifyGen2SaveIntegrity(data).first&&detectGen2Profile(data)?.key==profile.key){"The Gen 2 save/profile is not verified."}
        val offset=when(profile.key){"GS"->0x27D0;"C"->0x27AC;else->error("Unsupported Gen 2 saved crafting profile.")}
        require(offset in data.indices){"The Gen 2 saved crafting flag is outside the save."}
        val making=(data[offset].toInt()and 1)!=0
        val quantity=if(profile.key=="C"){
            require(0x2832 in data.indices){"The Crystal Apricorn quantity is outside the save."}
            (data[0x2832].toInt()and 0xFF).also{require(it in 0..99){"The saved Crystal Apricorn quantity is invalid."}}
        }else null
        return Gen2KurtSavedWork(making,quantity)
    }

    private fun showGen2ApricornInventory(file:File,opened:ByteArray,openedSource:Uri?,openedLabel:String?) {
        fun bound()=importedFile?.absolutePath==file.absolutePath&&currentSourceUri==openedSource&&currentSourceLabel==openedLabel
        val profile=detectGen2Profile(opened)?:run{showDialog("Gen 2 Apricorns","A verified Gold, Silver or Crystal save is required. Nothing was changed.");return}
        val bag=runCatching{
            require(profile.key in setOf("GS","C"))
            require(bound()&&file.readBytes().contentEquals(opened)&&verifyGen2SaveIntegrity(opened).first&&bound())
            parseGen2ItemPocket(opened,profile)?:error("The carried Item Pocket is invalid.")
        }.getOrElse{showDialog("Gen 2 Apricorns","The verified source, save or carried Item Pocket changed or is invalid. Reopen Items. Nothing was changed.");return}
        val recorded=runCatching{gen2KurtHandInRecipes(opened,profile)}.getOrElse{showDialog("Gen 2 Apricorns","The saved Kurt hand-in flags could not be verified. Nothing was changed.");return}
        val work=runCatching{gen2KurtSavedWork(opened,profile)}.getOrElse{showDialog("Gen 2 Apricorns","The saved crafting flag or Crystal quantity could not be verified. Nothing was changed.");return}
        val root=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(dp(18),dp(52),dp(18),dp(28));setBackgroundColor(BG)}
        addSectionTitle(root,"Apricorns / Kurt recipes")
        addMutedLine(root,"Gold / Silver / Crystal • Read-only carried inventory. Recipes do not start or finish Kurt's job.")
        for((apricorn,ball)in gen2ApricornRecipes){
            val count=bag.filter{it.first==apricorn}.sumOf{it.second}
            addDetailSection(root,"${gen2ItemName(apricorn)?:("#"+apricorn)} → ${gen2ItemName(ball)?:("#"+ball)}")
            addDetailLine(root,"Carried Apricorns",count.toString())
        }
        addDetailSection(root,"Saved Kurt hand-in flags • Read-only")
        if(recorded.isEmpty())addMutedLine(root,"None of the seven saved Apricorn hand-in flags is set. This alone does not prove Kurt is idle.")
        else for((apricorn,ball)in recorded)addDetailLine(root,"Recorded hand-in","${gen2ItemName(apricorn)} → ${gen2ItemName(ball)}")
        if(recorded.size>1)addMutedLine(root,"Several hand-in flags are set. PSE will not infer a single active job.")
        addDetailLine(root,"Saved making-Balls flag",if(work.making)"Set" else "Clear")
        addDetailLine(root,"Saved Apricorn quantity (Crystal)",work.quantity?.toString()?:"Not stored in Gold / Silver")
        addMutedLine(root,"Counts include all carried Item Pocket stacks, not PC storage or Apricorns already given to Kurt. The hand-in flags, saved making flag and Crystal quantity byte are read only. Remaining time and live job readiness are not calculated. Stored quantity can remain after collection and does not prove an active batch. Craft with Kurt in-game; no items, save bytes or timers are changed here.")
        addButton(root,"←  Items"){showGen2InventoryEditor()}
        phoneBackAction={showGen2InventoryEditor()}
        setContentView(ScrollView(this).apply{addView(root)})
    }

    // Gold/Silver maps/KurtsHouse.asm: each unique hand-in checks the making flag
    // before giving one Ball. This edits only that saved flag, not daily timers.
    private fun gen2GoldSilverKurtBatch(data:ByteArray,profile:Gen2Profile):Pair<Int,Int> {
        require(profile.key=="GS"&&verifyGen2SaveIntegrity(data).first&&detectGen2Profile(data)?.key=="GS"){"A verified Gold or Silver save is required. Crystal crafting edits remain locked."}
        val recorded=gen2KurtHandInRecipes(data,profile)
        require(recorded.size==1&&gen2KurtSavedWork(data,profile).making){"Exactly one recorded Apricorn hand-in and a set making flag are required. No batch was changed."}
        return recorded.single()
    }

    private fun confirmGen2GoldSilverKurtFinish(file:File,opened:ByteArray,openedSource:Uri?,openedLabel:String?) {
        fun bound()=importedFile?.absolutePath==file.absolutePath&&currentSourceUri==openedSource&&currentSourceLabel==openedLabel
        val recipe=runCatching{
            require(bound()&&file.readBytes().contentEquals(opened)&&bound()){"The active save changed. Reopen Items."}
            val profile=detectGen2Profile(opened)?:error("The Gen 2 save is invalid.")
            gen2GoldSilverKurtBatch(opened,profile)
        }.getOrElse{showDialog("Kurt batch edit unavailable",it.message?:"The saved batch could not be verified. Nothing was changed.");return}
        AlertDialog.Builder(this).setTitle("Mark Gold / Silver batch finished?")
            .setMessage("Recorded hand-in: ${gen2ItemName(recipe.first)} → ${gen2ItemName(recipe.second)} (one Ball). This deliberately clears only Kurt's saved making flag in PSE's working copy. It does not measure elapsed time, grant a Ball, consume an Apricorn, clear the hand-in, or change the clock. Collect from Kurt in-game after Save & Replace and reload; leaving and re-entering his house may be needed. A verified kept recovery backup is required before writing. Crystal is not supported by this edit.")
            .setNegativeButton("Cancel",null)
            .setPositiveButton("Mark finished"){_,_->finishGen2GoldSilverKurtBatch(file,opened,openedSource,openedLabel,recipe)}
            .show()
    }

    private fun finishGen2GoldSilverKurtBatch(file:File,opened:ByteArray,openedSource:Uri?,openedLabel:String?,expectedRecipe:Pair<Int,Int>) {
        fun bound()=importedFile?.absolutePath==file.absolutePath&&currentSourceUri==openedSource&&currentSourceLabel==openedLabel
        var writeStarted=false
        var safetyBackup:File?=null
        try{
            require(bound()){"The active save identity changed after confirmation."}
            val fresh=file.readBytes()
            require(fresh.contentEquals(opened)){"The complete working save changed after confirmation. Reopen Items."}
            val profile=detectGen2Profile(fresh)?:error("The fresh Gen 2 save is invalid.")
            require(gen2GoldSilverKurtBatch(fresh,profile)==expectedRecipe){"The recorded Gold / Silver batch changed."}
            val work=fresh.copyOf()
            work[0x27D0]=(work[0x27D0].toInt()and 0xFE).toByte()
            updateGen2PrimaryChecksum(work,profile)
            require(work.indices.all{it==0x27D0||it in profile.checksumOffset..profile.checksumOffset+1||work[it]==fresh[it]}){"Unrelated save data changed during staging."}
            require(verifyGen2SaveIntegrity(work).first&&detectGen2Profile(work)?.key=="GS"&&!gen2KurtSavedWork(work,profile).making&&gen2KurtHandInRecipes(work,profile)==listOf(expectedRecipe)){"The staged batch finish did not verify."}
            val backup=File.createTempFile(backupGameName(file)+"_PreKurtFinish_",".backup",backupsDir());safetyBackup=backup
            backup.writeBytes(fresh);require(backup.readBytes().contentEquals(fresh)){"The recovery backup did not persist exactly."}
            retainGen2SafetyBackup(backup,fresh)
            require(bound()&&file.readBytes().contentEquals(fresh)&&backup.readBytes().contentEquals(fresh)&&isBackupKept(backup)){"The save, source identity or retained backup changed before writing."}
            writeStarted=true
            file.writeBytes(work)
            val persisted=file.readBytes()
            require(bound()&&persisted.contentEquals(work)&&verifyGen2SaveIntegrity(persisted).first&&detectGen2Profile(persisted)?.key=="GS"&&!gen2KurtSavedWork(persisted,profile).making&&gen2KurtHandInRecipes(persisted,profile)==listOf(expectedRecipe)){"The complete persisted batch finish did not verify."}
        }catch(e:Exception){
