            val recovery=if(!writeStarted)"Nothing was written to the working save." else  if(restored)"The exact previous working save was restored and verified." else  "Automatic rollback could not be verified. Stop editing and restore the kept recovery backup."
            showDialog("Kurt batch edit failed",(e.message?:"Could not safely finish the saved batch")+"\n\n"+recovery+(safetyBackup?.let{"\n\nRecovery backup: "+it.name}?:""));return
        }
        Toast.makeText(this,"Saved Kurt making flag cleared and verified; collect in-game",Toast.LENGTH_LONG).show()
        showGen2InventoryEditor()
    }

    // Crystal GS Ball quest uses the same making flag. Event IDs190..192 from
    // pinned pokecrystal constants/event_flags.asm; Western event base0x2600.
    private data class Gen2CrystalKurtBatch(val recipe:Pair<Int,Int>,val quantity:Int)

    private fun gen2CrystalKurtBatch(data:ByteArray,profile:Gen2Profile):Gen2CrystalKurtBatch {
        require(profile.key=="C"&&verifyGen2SaveIntegrity(data).first&&detectGen2Profile(data)?.key=="C"){"A verified Crystal save is required."}
        require(0x2618 in data.indices){"The Crystal GS Ball quest flags are outside the save."}
        require((data[0x2617].toInt()and 0xC0)==0&&(data[0x2618].toInt()and 1)==0){"A GS Ball quest flag is set. Finish the GS Ball sequence in-game before editing an Apricorn batch."}
        val recorded=gen2KurtHandInRecipes(data,profile)
        val saved=gen2KurtSavedWork(data,profile)
        val quantity=requireNotNull(saved.quantity){"The Crystal batch quantity is unavailable."}
        require(recorded.size==1&&saved.making&&quantity in 1..99){"Exactly one hand-in, a set making flag and a quantity of 1–99 are required."}
        return Gen2CrystalKurtBatch(recorded.single(),quantity)
    }

    private fun confirmGen2CrystalKurtFinish(file:File,opened:ByteArray,openedSource:Uri?,openedLabel:String?) {
        fun bound()=importedFile?.absolutePath==file.absolutePath&&currentSourceUri==openedSource&&currentSourceLabel==openedLabel
        val batch=runCatching{
            require(bound()&&file.readBytes().contentEquals(opened)&&bound()){"The active save changed. Reopen Items."}
            val profile=detectGen2Profile(opened)?:error("The Gen 2 save is invalid.")
            gen2CrystalKurtBatch(opened,profile)
        }.getOrElse{showDialog("Crystal Kurt edit unavailable",it.message?:"The saved batch could not be verified. Nothing was changed.");return}
        AlertDialog.Builder(this).setTitle("Mark Crystal batch finished?")
            .setMessage("Recorded hand-in: ${gen2ItemName(batch.recipe.first)} → ${gen2ItemName(batch.recipe.second)} ×${batch.quantity}. This deliberately clears only the saved making flag in PSE's working copy. It does not measure elapsed time, grant Balls, consume Apricorns, change the quantity or hand-in, or advance the GS Ball quest. All three GS Ball quest flags must be clear. Collect from Kurt in-game after Save & Replace and reload; leaving and re-entering his house may be needed. A verified kept recovery backup is required before writing.")
            .setNegativeButton("Cancel",null)
            .setPositiveButton("Mark finished"){_,_->finishGen2CrystalKurtBatch(file,opened,openedSource,openedLabel,batch)}
            .show()
    }

    private fun finishGen2CrystalKurtBatch(file:File,opened:ByteArray,openedSource:Uri?,openedLabel:String?,expected:Gen2CrystalKurtBatch) {
        fun bound()=importedFile?.absolutePath==file.absolutePath&&currentSourceUri==openedSource&&currentSourceLabel==openedLabel
        var writeStarted=false
        var safetyBackup:File?=null
        try{
            require(bound()){"The active save identity changed after confirmation."}
            val fresh=file.readBytes()
            require(fresh.contentEquals(opened)){"The complete working save changed after confirmation. Reopen Items."}
            val profile=detectGen2Profile(fresh)?:error("The fresh Crystal save is invalid.")
            require(gen2CrystalKurtBatch(fresh,profile)==expected){"The recorded Crystal batch or GS Ball quest state changed."}
            val work=fresh.copyOf()
            work[0x27AC]=(work[0x27AC].toInt()and 0xFE).toByte()
            updateGen2PrimaryChecksum(work,profile)
            require(work.indices.all{it==0x27AC||it in profile.checksumOffset..profile.checksumOffset+1||work[it]==fresh[it]}){"Unrelated save data changed during staging."}
            require(verifyGen2SaveIntegrity(work).first&&detectGen2Profile(work)?.key=="C"&&gen2KurtSavedWork(work,profile)==Gen2KurtSavedWork(false,expected.quantity)&&gen2KurtHandInRecipes(work,profile)==listOf(expected.recipe)){"The staged Crystal batch finish did not verify."}
            val backup=File.createTempFile(backupGameName(file)+"_PreCrystalKurtFinish_",".backup",backupsDir());safetyBackup=backup
            backup.writeBytes(fresh);require(backup.readBytes().contentEquals(fresh)){"The recovery backup did not persist exactly."}
            retainGen2SafetyBackup(backup,fresh)
            require(bound()&&file.readBytes().contentEquals(fresh)&&backup.readBytes().contentEquals(fresh)&&isBackupKept(backup)){"The save, source identity or retained backup changed before writing."}
            writeStarted=true
            file.writeBytes(work)
            val persisted=file.readBytes()
            require(bound()&&persisted.contentEquals(work)&&verifyGen2SaveIntegrity(persisted).first&&detectGen2Profile(persisted)?.key=="C"&&gen2KurtSavedWork(persisted,profile)==Gen2KurtSavedWork(false,expected.quantity)&&gen2KurtHandInRecipes(persisted,profile)==listOf(expected.recipe)){"The complete persisted Crystal batch finish did not verify."}
        }catch(e:Exception){
            val restored=writeStarted&&runCatching{file.writeBytes(opened);require(file.readBytes().contentEquals(opened)&&verifyGen2SaveIntegrity(opened).first)}.isSuccess
            val recovery=if(!writeStarted)"Nothing was written to the working save." else  if(restored)"The exact previous working save was restored and verified." else  "Automatic rollback could not be verified. Stop editing and restore the kept recovery backup."
            showDialog("Crystal Kurt edit failed",(e.message?:"Could not safely finish the saved batch")+"\n\n"+recovery+(safetyBackup?.let{"\n\nRecovery backup: "+it.name}?:""));return
        }
        Toast.makeText(this,"Saved Crystal making flag cleared and verified; collect in-game",Toast.LENGTH_LONG).show()
        showGen2InventoryEditor()
    }

