    private fun gen2ItemPocketBase(profile:Gen2Profile):Int = if(profile.key=="C")0x2420 else 0x241F

    private fun parseGen2ItemPocket(data:ByteArray,profile:Gen2Profile):List<Pair<Int,Int>>?{
        val base=gen2ItemPocketBase(profile);if(base<0||base+42>data.size)return null;val count=data[base].toInt()and 0xFF;if(count !in 0..20)return null
        if((data[base+1+count*2].toInt()and 0xFF)!=0xFF)return null;val out=ArrayList<Pair<Int,Int>>()
        for(i in 0 until count){val id=data[base+1+i*2].toInt()and 0xFF;val quantity=data[base+2+i*2].toInt()and 0xFF;if(id !in 1..254||quantity !in 1..99)return null;out.add(id to quantity)}
        return out
    }

    private fun writeGen2ItemPocket(data:ByteArray,profile:Gen2Profile,items:List<Pair<Int,Int>>){
        require(items.size<=20){"The Gen 2 Item Pocket exceeds its 20-stack capacity."};require(items.all{it.first in 1..254&&it.second in 1..99}){"A Gen 2 item ID or quantity is invalid."}
        val base=gen2ItemPocketBase(profile);require(base+42<=data.size){"The Gen 2 Item Pocket is outside the save."};data[base]=items.size.toByte();java.util.Arrays.fill(data,base+1,base+42,0.toByte())
        for((i,item)in items.withIndex()){data[base+1+i*2]=item.first.toByte();data[base+2+i*2]=item.second.toByte()};data[base+1+items.size*2]=0xFF.toByte()
    }

