        addButton(root,"＋  Add to Bag"){val id=validIds[picker.selectedItemPosition];val q=qBox.text.toString().toIntOrNull();when{items.size>=20->showDialog("Bag full","The Gen 1 Bag already has 20 item stacks.");q==null||q !in 1..99->showDialog("Invalid quantity","Quantity must be 1–99.");items.any{it.id==id}->showDialog("Already in Bag",gen1ItemName(id)+" is already in the Bag. Change its quantity above instead.");else->{val n=items.map{BagItem(it.id,it.qty)}.toMutableList();n.add(BagItem(id,q));saveBag(n)}}}
