        val pcBase=0x27E6
        val pcRawCount=bytes[pcBase].toInt()and 255
        // Gen 1 saves can leave the PC item-list region uninitialised until it is used.
        // Never clamp an invalid count: 0xFF must mean an empty/uninitialised list, not 50 items.
        val pcUninitialised=pcRawCount==0xFF
        val parsedPc=parseGen1ItemList(bytes,pcBase,50,true)
