                val integrity=verifyGen1SaveIntegrity(fresh);require(integrity.first){integrity.second}
                require(fresh.copyOfRange(pcBase,pcBase+102).contentEquals(bytes.copyOfRange(pcBase,pcBase+102))){"PC item storage changed after this screen was opened. Reopen Items and try again."}
                require(parseGen1ItemList(fresh,pcBase,50,true)!=null){"The fresh PC item storage structure is invalid."}
                val expected=next.map{it.id to it.qty};val work=fresh.copyOf();writeGen1ItemList(work,pcBase,50,expected);updateGen1MainChecksum(work)
                require(parseGen1ItemList(work,pcBase,50)==expected){"The staged PC item list did not verify exactly."}
                require(work.indices.all{it in pcBase until pcBase+102||it==GEN1_CHECKSUM_OFFSET||work[it]==fresh[it]}){"The PC item edit changed unrelated save data."}
                val pre=verifyGen1WriteState(work,null);require(pre.first){pre.second};f.writeBytes(work)
                val verify=f.readBytes();require(verify.contentEquals(work)){"The save changed while PC items were being written."};val post=verifyGen1WriteState(verify,null);require(post.first){post.second};require(parseGen1ItemList(verify,pcBase,50)==expected){"The persisted PC item list did not verify exactly."}
                Toast.makeText(this,"Gen 1 PC items updated and verified",Toast.LENGTH_LONG).show();redraw()
            }catch(e:Exception){runCatching{f.writeBytes(fresh)};showDialog("PC item edit failed",(e.message?:"Unknown error")+"\n\nThe fresh working save was restored.")}
        }
        for((idx,it)in pcItems.withIndex()){
            val card=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(dp(12),dp(10),dp(12),dp(10));background=roundedBg(CARD,Color.rgb(25,75,100),12)}
