    private fun buildBottomNav(active: String): LinearLayout {
        val nav = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.CENTER
            minimumHeight = dp(64)
            setPadding(dp(8), dp(5), dp(8), dp(5))
            background = roundedBg(Color.rgb(9, 25, 36), Color.rgb(25, 55, 72), 0)
            setOnApplyWindowInsetsListener { v, insets ->
                @Suppress("DEPRECATION")
                val bottomInset = insets.systemWindowInsetBottom
                v.setPadding(dp(8), dp(5), dp(8), dp(5) + bottomInset)
                insets
            }
        }
        fun item(key: String, icon: String, label: String, action: () -> Unit) {
            val selected = active == key
            val box = LinearLayout(this).apply {
                orientation = LinearLayout.VERTICAL
                gravity = Gravity.CENTER
                setOnClickListener { action() }
            }
            box.addView(TextView(this).apply {
                text = icon
                textSize = 20f
                gravity = Gravity.CENTER
                setTextColor(if (selected) Color.rgb(45, 185, 255) else Color.rgb(125, 145, 158))
            })
            box.addView(TextView(this).apply {
                text = label
                textSize = 10f
                gravity = Gravity.CENTER
                typeface = if (selected) Typeface.DEFAULT_BOLD else Typeface.DEFAULT
                setTextColor(if (selected) Color.rgb(70, 190, 255) else Color.rgb(145, 160, 170))
            })
            nav.addView(box, LinearLayout.LayoutParams(0, -1, 1f))
        }
        item("home", "⌂", "Home") { showHome() }
        item("pokemon", "◉", "Pokémon") { showPokemonViewer() }
        item("bank", "▣", "Bank") { showBank() }
        item("backups", "▤", "Backups") { showSafeBackups() }
        return nav
    }

