    private fun updateStatus() {
        activeSwitchSave?.let {
            statusText.text = "${it.detectedGame} • Read-only source selected"
            statusText.setTextColor(GOOD)
            return
        }
        val file = importedFile
        if (file == null) {
            statusText.text = "No save imported yet"
            statusText.setTextColor(MUTED)
            return
        }
        val a = analyzeSave(file)
        if (a.structurallyValid && a.trainer?.gameMatchesFamily == true) {
            statusText.text = "Valid ${a.trainer.exactGame} save detected • trainer data parsed"
            statusText.setTextColor(GOOD)
        } else if (a.structurallyValid) {
            statusText.text = "Valid 3DS save structure • game ID needs attention"
            statusText.setTextColor(WARN)
        } else {
            statusText.text = "Imported file needs attention • tap Inspect Current Save"
            statusText.setTextColor(WARN)
        }
    }

