    private fun dp(value: Int): Int = (value * resources.displayMetrics.density).toInt()

    private fun rememberedSavePrefs() = getSharedPreferences("pse_remembered_saves", MODE_PRIVATE)

    private fun loadRememberedSaves(): MutableList<RememberedSave> {
        val raw = rememberedSavePrefs().getString("items", "[]") ?: "[]"
        return try {
            val arr = JSONArray(raw)
            val out = mutableListOf<RememberedSave>()
            for (i in 0 until arr.length()) {
                val o = arr.optJSONObject(i) ?: continue
                val uri = o.optString("uri")
                if (uri.isBlank()) continue
                out.add(RememberedSave(
                    uri = uri,
                    displayName = o.optString("displayName", "save"),
                    relativePath = o.optString("relativePath", o.optString("displayName", "save")),
                    detectedGame = o.optString("detectedGame", "Pokémon save"),
                    generation = o.optInt("generation", 0),
                    lastSeen = o.optLong("lastSeen", 0L),
                    trainerName = o.optString("trainerName", ""),
                    baselineHash = o.optString("baselineHash", ""),
                    status = o.optString("status", "Ready"),
                    switchFamily = o.optString("switchFamily", "")
                ))
            }
            out
        } catch (_: Exception) { mutableListOf() }
    }

    private fun writeRememberedSaves(items: List<RememberedSave>) {
        val arr = JSONArray()
        items.sortedByDescending { it.lastSeen }.forEach { item ->
            arr.put(JSONObject().apply {
                put("uri", item.uri)
                put("displayName", item.displayName)
                put("relativePath", item.relativePath)
                put("detectedGame", item.detectedGame)
                put("generation", item.generation)
                put("lastSeen", item.lastSeen)
                put("trainerName", item.trainerName)
                put("baselineHash", item.baselineHash)
                put("status", item.status)
                put("switchFamily", item.switchFamily)
            })
        }
        rememberedSavePrefs().edit().putString("items", arr.toString()).apply()
    }

    private fun rememberScannedSaves(found: List<ScannedSave>) {
        if (found.isEmpty()) return
        val existing = loadRememberedSaves().associateBy { it.uri }.toMutableMap()
        val now = System.currentTimeMillis()
        found.forEachIndexed { index, s ->
            // A provider can expose the same physical save under a new document URI after
            // permission is re-granted. Remove an older verified entry with identical save
            // contents so rescans repair the rail instead of accumulating duplicates.
            if (s.analysis.sha256.isNotBlank()) {
                existing.entries.removeAll { (_, old) ->
                    old.uri != s.uri.toString() && old.generation == s.generation &&
                        old.baselineHash.isNotBlank() && old.baselineHash == s.analysis.sha256
                }
            }
            existing[s.uri.toString()] = RememberedSave(
                uri = s.uri.toString(),
                displayName = s.displayName,
                relativePath = s.relativePath,
                detectedGame = if (s.generation == 4) (gen4NameHint(s.relativePath) ?: gen4NameHint(s.displayName) ?: gen4NameHint(s.uri.toString()) ?: s.detectedGame) else s.detectedGame,
                generation = s.generation,
                lastSeen = now - index,
                trainerName = s.analysis.trainer?.trainerName ?: existing[s.uri.toString()]?.trainerName.orEmpty(),
                baselineHash = s.analysis.sha256,
                status = if (s.switchFamily.isNotBlank()) "Ready • Read-only" else "Ready",
                switchFamily = s.switchFamily
            )
        }
        writeRememberedSaves(existing.values.toList())
    }

    private fun gen4NameHint(text: String): String? {
        val x = text.lowercase(Locale.US).replace(Regex("[^a-z0-9]+"), " ").trim()
        return when {
            "heartgold" in x || "heart gold" in x || Regex("\\bhg(ss)?\\b").containsMatchIn(x) -> "Pokémon HeartGold"
            "soulsilver" in x || "soul silver" in x || Regex("\\bss\\b").containsMatchIn(x) -> "Pokémon SoulSilver"
            "platinum" in x || Regex("\\bpt\\b").containsMatchIn(x) -> "Pokémon Platinum"
            "diamond" in x || Regex("\\bpokemon d\\b").containsMatchIn(x) || Regex("\\bpkmn d\\b").containsMatchIn(x) -> "Pokémon Diamond"
            "pearl" in x || Regex("\\bpokemon p\\b").containsMatchIn(x) || Regex("\\bpkmn p\\b").containsMatchIn(x) -> "Pokémon Pearl"
            else -> null
        }
    }

    private fun rememberedCardGame(item: RememberedSave): String {
        if (item.generation != 4) return item.detectedGame
        val exact = gen4NameHint(item.relativePath) ?: gen4NameHint(item.displayName) ?: gen4NameHint(item.uri)
        if (exact != null) return exact
        return when {
            item.detectedGame.contains("Diamond", true) && !item.detectedGame.contains("Pearl", true) -> "Pokémon Diamond"
            item.detectedGame.contains("Pearl", true) && !item.detectedGame.contains("Diamond", true) -> "Pokémon Pearl"
            item.detectedGame.contains("Platinum", true) && !item.detectedGame.contains("Diamond", true) -> "Pokémon Platinum"
            item.detectedGame.contains("HeartGold", true) && !item.detectedGame.contains("SoulSilver", true) -> "Pokémon HeartGold"
            item.detectedGame.contains("SoulSilver", true) && !item.detectedGame.contains("HeartGold", true) -> "Pokémon SoulSilver"
            item.detectedGame.contains("Diamond / Pearl", true) -> "Pokémon Diamond / Pearl"
            item.detectedGame.contains("HeartGold / SoulSilver", true) -> "Pokémon HeartGold / SoulSilver"
            else -> "Pokémon Gen 4 save"
        }
    }

    private fun normalizeRememberedFileKey(item: RememberedSave): String {
        val base = item.displayName.ifBlank { item.relativePath.substringAfterLast('/') }
        return base.lowercase(Locale.US).replace(Regex("[^a-z0-9]"), "")
    }

    private fun visibleRememberedSaves(items: List<RememberedSave>): List<RememberedSave> {
        // Saved Games is a list of games, not a history of every URI PSE has ever seen.
        // Gen 4 scans can rediscover the same .sav through a new Android document URI, so
        // collapse verified duplicates by content hash and prefer the usable/newest pointer.
        val grouped = items.groupBy { "${it.generation}:${it.switchFamily}:${normalizeRememberedFileKey(it)}" }
        fun exactGen4Name(x: RememberedSave): Boolean {
            if (x.generation != 4) return false
            return gen4NameHint(x.relativePath) != null || gen4NameHint(x.displayName) != null ||
                gen4NameHint(x.uri) != null ||
                listOf("Diamond", "Pearl", "Platinum", "HeartGold", "SoulSilver").any { n ->
                    x.detectedGame.contains(n, true) &&
                        !x.detectedGame.contains("Diamond / Pearl", true) &&
                        !x.detectedGame.contains("HeartGold / SoulSilver", true)
                }
        }

        val preferredGen4ByHash = items
            .filter { it.generation == 4 && it.baselineHash.isNotBlank() }
            .groupBy { it.baselineHash }
            .mapValues { (_, peers) ->
                peers.maxWithOrNull(
                    compareBy<RememberedSave>(
                        { if (currentSourceUri?.toString() == it.uri) 4 else 0 },
                        { if (it.status != "Needs permission") 2 else 0 },
                        { if (exactGen4Name(it)) 1 else 0 },
                        { it.lastSeen }
                    )
                )
            }

        return items.filter { item ->
            if (item.generation == 4 && item.baselineHash.isNotBlank()) {
                val preferred = preferredGen4ByHash[item.baselineHash]
                if (preferred != null && preferred.uri != item.uri) return@filter false
            }

            if (item.status == "Needs permission") {
                val peers = grouped["${item.generation}:${item.switchFamily}:${normalizeRememberedFileKey(item)}"].orEmpty()
                if (peers.any { it.uri != item.uri && it.status != "Needs permission" }) return@filter false

                // A legacy Gen 4 pointer may have lost its file-name key but still describe
                // the same named game. If there is a working card with the same verified hash,
                // or the same normalized source name, hide the stale pointer instead of making
                // the user tap into an avoidable "Saved game unavailable" dialog.
                if (item.generation == 4) {
                    val sameGame = rememberedCardGame(item)
                    val replacement = items.any { peer ->
                        peer.uri != item.uri && peer.generation == 4 && peer.status != "Needs permission" &&
                            ((item.baselineHash.isNotBlank() && peer.baselineHash == item.baselineHash) ||
                             (normalizeRememberedFileKey(item).isNotBlank() && normalizeRememberedFileKey(peer) == normalizeRememberedFileKey(item))) &&
                            rememberedCardGame(peer) == sameGame
                    }
                    if (replacement) return@filter false
                }
            }

            if (item.generation == 4 && !exactGen4Name(item) && item.baselineHash.isNotBlank()) {
                val better = items.any { peer ->
                    peer !== item && peer.generation == 4 && peer.status != "Needs permission" &&
                        peer.baselineHash.isNotBlank() && peer.baselineHash == item.baselineHash && exactGen4Name(peer)
                }
                if (better) return@filter false
            }
            true
        }
    }

    private fun migrateLegacyGen4RememberedTitles() {
        val items = loadRememberedSaves()
        // Older Gen 4 remembered cards were created before trainer parsing was connected to
        // the DS scanner. Re-read only cards that still need either a proper title or trainer
        // name, so existing installs are upgraded automatically without requiring a rescan.
        if (items.none { it.generation == 4 && (rememberedCardGame(it) == "Pokémon Gen 4 save" || it.trainerName.isBlank()) }) return

        var changed = false
        val refreshed = items.map { item ->
            if (item.generation != 4 || (rememberedCardGame(item) != "Pokémon Gen 4 save" && item.trainerName.isNotBlank())) return@map item
            try {
                val raw = contentResolver.openInputStream(Uri.parse(item.uri))?.use { it.readBytes() } ?: return@map item
                if (raw.size != SIZE_G4) return@map item
                val profile = detectGen4Profile(raw) ?: return@map item
                val exactHint = gen4NameHint(item.relativePath) ?: gen4NameHint(item.displayName) ?: gen4NameHint(item.uri)
                val resolved = if (rememberedCardGame(item) == "Pokémon Gen 4 save") (exactHint ?: "Pokémon ${profile.family}") else item.detectedGame
                val trainer = parseTrainerGen4(raw)
                val resolvedTrainer = trainer?.trainerName?.takeIf { it.isNotBlank() } ?: item.trainerName
                val next = item.copy(
                    detectedGame = resolved,
                    trainerName = resolvedTrainer,
                    baselineHash = sha256(raw),
                    status = "Ready"
                )
                if (next != item) changed = true
                next
            } catch (_: Exception) { item }
        }.toMutableList()

        // If the same physical save was previously learned under an exact title, reuse that
        // title for legacy generic cards with the same verified content hash. This is the only
        // safe way to split Diamond from Pearl or HeartGold from SoulSilver when the file/path
        // itself is anonymous, because those paired games share the same save layout.
        val exactByHash = refreshed.filter { it.generation == 4 && it.baselineHash.isNotBlank() }
            .mapNotNull { r ->
                val detectedExact = if (r.detectedGame.contains(" / ")) null else gen4NameHint(r.detectedGame)
                val exact = detectedExact ?: gen4NameHint(r.relativePath) ?: gen4NameHint(r.displayName) ?: gen4NameHint(r.uri)
                exact?.let { r.baselineHash to it }
            }.toMap()
        for (i in refreshed.indices) {
            val r = refreshed[i]
            if (r.generation != 4 || r.baselineHash.isBlank()) continue
            val exact = exactByHash[r.baselineHash] ?: continue
            if (r.detectedGame != exact) {
                refreshed[i] = r.copy(detectedGame = exact)
                changed = true
            }
        }
        if (changed) writeRememberedSaves(refreshed)
    }

    private fun migrateLegacyGen5RememberedTrainerNames() {
        val items = loadRememberedSaves()
        if (items.none { it.generation == 5 && it.trainerName.isBlank() }) return

        var changed = false
        val refreshed = items.map { item ->
            if (item.generation != 5 || item.trainerName.isNotBlank()) return@map item
            try {
                val raw = contentResolver.openInputStream(Uri.parse(item.uri))?.use { it.readBytes() } ?: return@map item
                if (raw.size != SIZE_G5 || detectGen5Profile(raw) == null) return@map item
                val trainer = parseTrainerGen5(raw) ?: return@map item
                val resolvedTrainer = trainer.trainerName.takeIf { it.isNotBlank() && !it.equals("Trainer", true) } ?: return@map item
                val next = item.copy(
                    trainerName = resolvedTrainer,
                    baselineHash = sha256(raw),
                    status = "Ready"
                )
                if (next != item) changed = true
                next
            } catch (_: Exception) { item }
        }
        if (changed) writeRememberedSaves(refreshed)
    }

    private fun addRememberedSavesSection(root: LinearLayout) {
        migrateLegacyGen4RememberedTitles()
        migrateLegacyGen5RememberedTrainerNames()
        val saves = visibleRememberedSaves(loadRememberedSaves())
        if (saves.isEmpty()) return

        val heading = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.CENTER_VERTICAL
            setPadding(dp(4), 0, dp(4), dp(8))
        }
        heading.addView(TextView(this).apply {
            text = "SAVED GAMES"
            textSize = 13f
            typeface = Typeface.DEFAULT_BOLD
            setTextColor(ACCENT)
        }, LinearLayout.LayoutParams(0, -2, 1f))
        heading.addView(TextView(this).apply {
            text = "${saves.size} SAVE${if (saves.size == 1) "" else "S"}  ›"
            textSize = 12f
            typeface = Typeface.DEFAULT_BOLD
            setTextColor(MUTED)
        })
        heading.setOnClickListener { showAllRememberedSaves() }
        root.addView(heading)
        if (saves.size > 40) addButton(root, "View all ${saves.size} saved games") { showAllRememberedSaves() }

        val saveSearch = EditText(this).apply {
            hint = "Search saved games"
            setHintTextColor(MUTED); setTextColor(TEXT); textSize = 14f
            setSingleLine(true); setPadding(dp(14), dp(8), dp(14), dp(8))
            background = roundedBg(Color.rgb(12,35,51), Color.rgb(25,75,100), 12)
        }
        root.addView(saveSearch, LinearLayout.LayoutParams(-1, dp(48)).apply { bottomMargin=dp(8) })

        val scroller = HorizontalScrollView(this).apply {
            isHorizontalScrollBarEnabled = false
            overScrollMode = View.OVER_SCROLL_NEVER
        }
        val rail = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.CENTER_VERTICAL
            setPadding(dp(2), dp(2), dp(2), dp(4))
        }

        saves.take(40).forEach { item ->
            val isCurrent = currentSourceUri?.toString() == item.uri
            val displayedStatus = if (isCurrent) "Current" else item.status
            val border = when (displayedStatus) {
                "Current" -> Color.rgb(45, 185, 255)
                "Changed externally" -> WARN
                "Needs permission" -> Color.rgb(220, 95, 95)
                else -> Color.rgb(25, 75, 100)
            }
            val statusColor = when (displayedStatus) {
                "Current" -> GOOD
                "Changed externally" -> WARN
                "Needs permission" -> Color.rgb(245, 120, 120)
                else -> GOOD
            }
            val card = LinearLayout(this).apply {
                orientation = LinearLayout.VERTICAL
                gravity = Gravity.CENTER_HORIZONTAL
                setPadding(dp(12), dp(10), dp(10), dp(10))
                background = roundedBg(Color.rgb(12, 35, 51), border, 15)
                isClickable = true
                isFocusable = true
                setOnClickListener { openRememberedSave(item) }
            }

            val top = LinearLayout(this).apply {
                orientation = LinearLayout.HORIZONTAL
                gravity = Gravity.CENTER_VERTICAL
            }
            top.addView(TextView(this).apply {
                text = if (item.switchFamily.isNotBlank()) "GEN ${item.generation} • SWITCH • READ-ONLY" else if (item.generation > 0) "GEN ${item.generation}" else "SAVE"
                textSize = 10f
                typeface = Typeface.DEFAULT_BOLD
                setTextColor(if (isCurrent) Color.rgb(95, 215, 255) else ACCENT)
                gravity = Gravity.CENTER_VERTICAL
            }, LinearLayout.LayoutParams(0, dp(28), 1f))
            top.addView(TextView(this).apply {
                text = "⋮"
                textSize = 23f
                gravity = Gravity.CENTER
                setTextColor(TEXT)
                setOnClickListener { showRememberedSaveMenu(item, this) }
            }, LinearLayout.LayoutParams(dp(34), dp(30)))
            card.addView(top, LinearLayout.LayoutParams(-1, dp(30)))

            card.addView(TextView(this).apply {
                text = rememberedCardGame(item).removePrefix("Pokémon ")
                textSize = 16f
                typeface = Typeface.DEFAULT_BOLD
                setTextColor(TEXT)
                maxLines = 2
                gravity = Gravity.CENTER
                ellipsize = android.text.TextUtils.TruncateAt.END
                setPadding(0, dp(6), 0, 0)
            }, LinearLayout.LayoutParams(-1, dp(44)))

            card.addView(TextView(this).apply {
                text = if (item.trainerName.isBlank()) "Trainer —" else "Trainer ${item.trainerName}"
                textSize = 10f
                setTextColor(MUTED)
                gravity = Gravity.CENTER
                maxLines = 1
                ellipsize = android.text.TextUtils.TruncateAt.END
            }, LinearLayout.LayoutParams(-1, dp(20)))

            card.addView(TextView(this).apply {
                text = "●  ${displayedStatus.uppercase(Locale.US)}"
                textSize = 9f
                typeface = Typeface.DEFAULT_BOLD
                setTextColor(statusColor)
                gravity = Gravity.CENTER
            }, LinearLayout.LayoutParams(-1, dp(24)))

            card.tag = listOf(rememberedCardGame(item), item.trainerName, item.displayName, item.relativePath, "Gen ${item.generation}").joinToString(" ").lowercase(Locale.US)
            rail.addView(card, LinearLayout.LayoutParams(dp(166), dp(128)).apply { rightMargin = dp(9) })
        }
        saveSearch.addTextChangedListener(object: android.text.TextWatcher {
            override fun beforeTextChanged(x:CharSequence?,a:Int,b:Int,c:Int){}
            override fun onTextChanged(x:CharSequence?,a:Int,b:Int,c:Int){
                val q=x?.toString()?.trim()?.lowercase(Locale.US).orEmpty()
                for(i in 0 until rail.childCount){ val v=rail.getChildAt(i); v.visibility=if(q.isBlank() || (v.tag as? String)?.contains(q)==true) View.VISIBLE else View.GONE }
            }
            override fun afterTextChanged(x:android.text.Editable?){}
        })

        scroller.addView(rail)
        root.addView(scroller, LinearLayout.LayoutParams(-1, dp(138)).apply { bottomMargin = dp(4) })
        root.addView(TextView(this).apply {
            text = "Swipe sideways • tap a save to open • ⋮ for more"
            textSize = 11f
            setTextColor(MUTED)
            setPadding(dp(4), 0, 0, dp(14))
        })
    }

    private fun showRememberedSaveMenu(item: RememberedSave, anchor: View) {
        val popup = android.widget.PopupMenu(this, anchor)
        popup.menu.add("Open")
        popup.menu.add("Refresh status")
        popup.menu.add("Source info")
        popup.menu.add("Remove from PSE")
        popup.setOnMenuItemClickListener { menuItem ->
            when (menuItem.title.toString()) {
                "Open" -> openRememberedSave(item)
                "Refresh status" -> refreshRememberedSaveStatus(item)
                "Source info" -> showDialog(
                    "Saved game source",
                    "Game: ${rememberedCardGame(item)}\n" +
                        "Generation: ${item.generation}\n" +
                        (if (item.trainerName.isBlank()) "" else "Trainer: ${item.trainerName}\n") +
                        "Status: ${item.status}\n\n" +
                        "File: ${item.displayName}\n" +
                        "Source: ${item.relativePath}"
                )
                "Remove from PSE" -> confirmRemoveRememberedSave(item)
            }
            true
        }
        popup.show()
    }

    private fun confirmRemoveRememberedSave(item: RememberedSave) {
        AlertDialog.Builder(this)
            .setTitle("Remove saved game?")
            .setMessage("This only removes ${item.detectedGame} from PSE's Saved Games bar. The emulator save file will not be deleted.")
            .setPositiveButton("Remove") { _, _ -> removeRememberedSave(item.uri) }
            .setNegativeButton("Cancel", null)
            .show()
    }

    private fun updateRememberedSave(updated: RememberedSave) {
        val items = loadRememberedSaves().map { if (it.uri == updated.uri) updated else it }
        writeRememberedSaves(items)
    }

    private fun showRememberedSaveUnavailable(item: RememberedSave) {
        AlertDialog.Builder(this)
            .setTitle("Saved game unavailable")
            .setMessage("PSE could not read or validate this remembered save. The file may have moved, permission may have changed, or the save may have been replaced.")
            .setPositiveButton("Grant permission / Relocate save") { _, _ -> repairRememberedSave(item) }
            .setNeutralButton("Remove save") { _, _ -> confirmRemoveRememberedSave(item) }
            .setNegativeButton("Cancel", null)
            .show()
    }

    private fun repairRememberedSave(item: RememberedSave) {
        rememberedSaveRepairTarget = item
        val intent = Intent(Intent.ACTION_OPEN_DOCUMENT).apply {
            addCategory(Intent.CATEGORY_OPENABLE)
            type = "*/*"
            addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION or Intent.FLAG_GRANT_WRITE_URI_PERMISSION or Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION)
        }
        startActivityForResult(intent, REPAIR_REMEMBERED_SAVE)
    }

    private fun finishRememberedSaveRepair(target: RememberedSave, uri: Uri, displayName: String) {
        val relativePath = displayName
        val scanned = inspectRememberedSource(target, uri, displayName, relativePath)

        if (scanned == null || scanned.generation != target.generation || scanned.switchFamily != target.switchFamily) {
            showDialog("Save does not match", "That file does not match the remembered save's generation and platform. The existing Saved Games card was left unchanged.")
            return
        }

        val repaired = target.copy(
            uri = uri.toString(),
            displayName = displayName,
            relativePath = relativePath,
            detectedGame = if (scanned.generation == 4) (gen4NameHint(displayName) ?: scanned.detectedGame) else scanned.detectedGame,
            generation = scanned.generation,
            lastSeen = System.currentTimeMillis(),
            trainerName = scanned.analysis.trainer?.trainerName ?: target.trainerName,
            baselineHash = scanned.analysis.sha256,
            status = "Ready"
        )

        // Replace the stale card in-place and collapse any card that points to the same
        // document or verified save contents. Re-selecting/scanning a save must not create
        // another Saved Games entry.
        val deduped = loadRememberedSaves().filterNot { existing ->
            existing.uri == target.uri || existing.uri == repaired.uri ||
                (repaired.baselineHash.isNotBlank() && existing.baselineHash == repaired.baselineHash && existing.generation == repaired.generation)
        }.toMutableList()
        deduped.add(repaired)
        writeRememberedSaves(deduped)
        showHome()
        Toast.makeText(this, "Saved game reconnected", Toast.LENGTH_LONG).show()
    }

    private fun refreshRememberedSaveStatus(item: RememberedSave) {
        val uri = runCatching { Uri.parse(item.uri) }.getOrNull() ?: run {
            updateRememberedSave(item.copy(status = "Needs permission"))
            showHome()
            return
        }
        val progress = AlertDialog.Builder(this)
            .setTitle("Refreshing ${item.detectedGame}")
            .setMessage("Checking the original save source…")
            .setCancelable(false)
            .create()
        progress.show()
        imageExecutor.execute {
            val scanned = inspectRememberedSource(item, uri, item.displayName, item.relativePath)
            mainHandler.post {
                progress.dismiss()
                if (scanned == null) {
                    updateRememberedSave(item.copy(status = "Needs permission"))
                    showHome()
                    Toast.makeText(this, "Save source is unavailable", Toast.LENGTH_LONG).show()
                } else {
                    val changed = item.baselineHash.isNotBlank() && scanned.analysis.sha256 != item.baselineHash
                    updateRememberedSave(item.copy(
                        detectedGame = scanned.detectedGame,
                        generation = scanned.generation,
                        trainerName = scanned.analysis.trainer?.trainerName ?: item.trainerName,
                        lastSeen = System.currentTimeMillis(),
                        status = if (changed) "Changed externally" else "Ready"
                    ))
                    showHome()
                    Toast.makeText(this, if (changed) "Save changed outside PSE" else "Save is ready", Toast.LENGTH_SHORT).show()
                }
            }
        }
    }

    private fun removeRememberedSave(uri: String) {
        writeRememberedSaves(loadRememberedSaves().filterNot { it.uri == uri })
        showHome()
    }

    private fun openRememberedSave(item: RememberedSave) {
        val uri = runCatching { Uri.parse(item.uri) }.getOrNull() ?: run {
            showDialog("Saved game", "The remembered source address is no longer valid.")
            return
        }
        val progress = AlertDialog.Builder(this).setTitle("Opening ${rememberedCardGame(item)}").setMessage("Revalidating the original save source…").setCancelable(false).create()
        progress.show()
        imageExecutor.execute {
            val scanned = inspectRememberedSource(item, uri, item.displayName, item.relativePath)
            mainHandler.post {
                progress.dismiss()
                if (scanned == null) {
                    updateRememberedSave(item.copy(status = "Needs permission"))
                    showHome()
                    showRememberedSaveUnavailable(item.copy(status = "Needs permission"))
                } else importRoutedSave(scanned)
            }
        }
    }

    private fun showEmulatorScanner() {
        // AlertDialog can suppress its list when a message and list are both configured
        // on some Android builds/themes. Keep this as a pure list dialog so the
        // emulator choice is always visible.
        val choices = arrayOf(
            "📁  Scan a full folder • All supported generations",
            "🎮  Nintendo Switch • Gen 7–9 • Read-only",
            "🎮  Nintendo 3DS • Gen 6/7",
            "🎮  Nintendo DS • Gen 4/5",
            "🕹️  Game Boy & Game Boy Color • Gen 1/2",
            "🎮  Game Boy Advance • Gen 3"
        )
        android.app.AlertDialog.Builder(this)
            .setTitle("Scan Emulator Saves")
            .setItems(choices) { _, which ->
                when (which) {
                    0 -> openUnifiedSourceScanner(false)
                    1 -> openUnifiedSourceScanner(true)
                    2 -> openAzaharScanner()
                    3 -> openDsScanner()
                    4 -> openPizzaBoyCScanner()
                    5 -> openGbaScanner()
                }
            }
            .setNegativeButton("Cancel", null)
            .show()
    }

    private fun boundedSourceBytes(uri: Uri): ByteArray? = try {
        val input = contentResolver.openInputStream(uri) ?: throw java.io.IOException("Source unavailable")
        SwitchReadSnapshot.readFrom(SwitchGameFamily.LETS_GO_PIKACHU_EEVEE, input).bytesCopy()
    } catch (_: Exception) { null }

    private fun inspectSwitchScannedSave(uri: Uri, name: String, path: String): ScannedSave? = try {
        val input = contentResolver.openInputStream(uri) ?: throw java.io.IOException("Source unavailable")
        val snapshot = SwitchReadSnapshot.readFrom(SwitchGameFamily.LETS_GO_PIKACHU_EEVEE, input)
        val identity = SwitchSaveDiscovery.inspect(snapshot)
        if (identity == null) null else ScannedSave(uri, name, path,
            SaveAnalysis(identity.family.displayName, true, identity.byteCount, identity.byteCount, true, identity.sha256,
                "Native Switch identity and integrity passed. Read-only source; editing is locked.", null),
            identity.game, identity.family.generation, identity.family.name)
    } catch (_: Exception) { null }

    private fun inspectRememberedSource(item: RememberedSave, uri: Uri, name: String, path: String): ScannedSave? =
        if (item.switchFamily.isNotBlank()) inspectSwitchScannedSave(uri, name, path)?.takeIf { it.switchFamily == item.switchFamily }
        else if (item.generation == 1 || item.generation == 2) inspectGen1ScannedSave(uri, name, path)
        else if (item.generation == 3) inspectGen3ScannedSave(uri, name, path)
        else if (item.generation == 4 || item.generation == 5) inspectDsScannedSave(uri, name, path)
        else inspectScannedSave(uri, name, path)

    private fun openSwitchSource(source: ScannedSave) {
        require(source.switchFamily.isNotBlank())
        rememberScannedSaves(listOf(source))
        // Switch source bytes never enter importedFile or any legacy writer.
        importedFile = null
        pendingGen2SaveExport = null
        pendingGen6UiSource = null
        pendingGen6UiExport = null
        activeSwitchSave = source
        currentSourceUri = source.uri
        currentSourceLabel = source.relativePath
        resetPokemonSelection()
        showHome()
        openActiveSwitchSection("overview")
    }

    private fun openActiveSwitchSection(section: String): Boolean {
        val source = activeSwitchSave ?: return false
        startActivity(Intent(this, SwitchReadOnlyActivity::class.java).apply {
            data = source.uri
            putExtra("pse.switch.family", source.switchFamily)
            putExtra("pse.switch.sha256", source.analysis.sha256)
            putExtra("pse.switch.section", section)
            addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION or Intent.FLAG_GRANT_WRITE_URI_PERMISSION)
        })
        return true
    }

    private fun blockSwitchWrite(): Boolean {
        if (activeSwitchSave == null) return false
        showDialog("Switch save • Read-only", "Editing, export and Save & Replace stay locked until the write phase is authorised. The original save has not been changed.")
        return true
    }

    private fun openUnifiedSourceScanner(switchOnly: Boolean) {
        val prefs = getSharedPreferences("pse_scanner", MODE_PRIVATE)
        val saved = prefs.getString(if (switchOnly) "switch_tree" else "all_tree", null)
        val labels = mutableListOf<String>()
        if (switchOnly) labels.add("Select a Nintendo Switch save file • Read-only")
        labels.add("Choose a full folder • Include subfolders")
        if (!saved.isNullOrBlank()) labels.add("Scan remembered folder • Include subfolders")
        AlertDialog.Builder(this).setTitle(if (switchOnly) "Nintendo Switch • Gen 7–9" else "All supported saves • Folder scan")
            .setItems(labels.toTypedArray()) { _, index ->
                val action = if (switchOnly) index - 1 else index
                if (action == -1) {
                    startActivityForResult(Intent(Intent.ACTION_OPEN_DOCUMENT).apply {
                        type = "*/*"; addCategory(Intent.CATEGORY_OPENABLE)
                        addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION or Intent.FLAG_GRANT_WRITE_URI_PERMISSION or Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION)
                    }, PICK_SWITCH_SOURCE)
                } else if (action == 0) {
                    startActivityForResult(Intent(Intent.ACTION_OPEN_DOCUMENT_TREE).apply {
                        addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION or Intent.FLAG_GRANT_WRITE_URI_PERMISSION or Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION or Intent.FLAG_GRANT_PREFIX_URI_PERMISSION)
                    }, if (switchOnly) PICK_SWITCH_SOURCE_TREE else PICK_ALL_SOURCE_TREE)
                } else if (saved != null) scanUnifiedSourceTree(Uri.parse(saved), switchOnly)
            }.setNegativeButton("Cancel", null).show()
    }

    private fun scanUnifiedSourceTree(treeUri: Uri, switchOnly: Boolean) {
        sourceScanCancellation?.set(true)
        val cancellation = java.util.concurrent.atomic.AtomicBoolean(false)
        sourceScanCancellation = cancellation
        val progress = AlertDialog.Builder(this).setTitle("Scanning folder and subfolders")
            .setMessage("Checking accessible files by their native save contents. Originals remain unchanged.")
            .setNegativeButton("Cancel") { _, _ -> cancellation.set(true) }.setCancelable(false).create()
        progress.show()
        imageExecutor.execute {
            val result = try {
                val rootId = DocumentsContract.getTreeDocumentId(treeUri)
                val rootUri = DocumentsContract.buildDocumentUriUsingTree(treeUri, rootId)
                ReadOnlySaveFolderScan<ScannedSave>().scan(
                    ReadOnlySaveFolderScan.Node(rootUri.toString(), "Selected folder", "Selected folder", true),
                    cancelled = { cancellation.get() },
                    children = { node ->
                        val childUri = DocumentsContract.buildChildDocumentsUriUsingTree(treeUri, DocumentsContract.getDocumentId(Uri.parse(node.id)))
                        val projection = arrayOf(DocumentsContract.Document.COLUMN_DOCUMENT_ID, DocumentsContract.Document.COLUMN_DISPLAY_NAME,
                            DocumentsContract.Document.COLUMN_MIME_TYPE, DocumentsContract.Document.COLUMN_SIZE)
                        val children = mutableListOf<ReadOnlySaveFolderScan.Node>()
                        val cursor = contentResolver.query(childUri, projection, null, null, null) ?: throw java.io.IOException("Folder unavailable")
                        cursor.use { c ->
                            while (!cancellation.get() && children.size <= 50000 && c.moveToNext()) {
                                val id = c.getString(0) ?: continue; val name = c.getString(1) ?: "(unnamed)"
                                children.add(ReadOnlySaveFolderScan.Node(DocumentsContract.buildDocumentUriUsingTree(treeUri, id).toString(), name,
                                    node.path + "/" + name, c.getString(2) == DocumentsContract.Document.MIME_TYPE_DIR,
                                    if (c.isNull(3)) null else c.getLong(3)))
                            }
                        }
                        children
                    },
                    inspect = { node ->
                        val uri = Uri.parse(node.id)
                        if (switchOnly) inspectSwitchScannedSave(uri, node.name, node.path)
                        else inspectAnySupportedPickedSave(uri, node.name, node.path)
                    })
            } catch (_: Exception) { null }
            mainHandler.post {
                if (isFinishing || isDestroyed || sourceScanCancellation !== cancellation) return@post
                progress.dismiss()
                if (cancellation.get() || result?.cancelled == true) {
                    Toast.makeText(this, "Scan cancelled. Previous saved games are unchanged.", Toast.LENGTH_LONG).show()
                } else if (result == null) showDialog("Folder unavailable", "Choose an accessible folder using Android’s document picker. The previous library is unchanged.")
                else {
                    val found = result.saves.distinctBy { it.uri.toString() }.sortedWith(compareBy<ScannedSave> { it.generation }.thenBy { it.detectedGame }.thenBy { it.relativePath })
                    rememberScannedSaves(found)
                    showHome()
                    val summary = "${found.size} verified saves • ${result.filesChecked} files checked\n" +
                        "${result.inaccessible} inaccessible branches/files • ${result.skippedLarge} empty/oversized files skipped" +
                        (if (result.limited) "\nPartial scan: reached a safety limit (50,000 entries, 64 folder levels or 2,000 saves). Choose a smaller subfolder to continue." else "") +
                        "\n\nAndroid must grant access to each chosen folder. Encrypted console backups must be extracted first."
                    if (found.isEmpty()) showDialog("Folder scan finished", summary)
                    else AlertDialog.Builder(this).setTitle(if (result.limited || result.inaccessible > 0) "Partial folder scan (${found.size} saves)" else "Saved games added (${found.size})")
                        .setItems((listOf(if (result.limited || result.inaccessible > 0) "Partial scan • View limits and inaccessible folders" else "Scan summary") + found.map { "${it.detectedGame} • Gen ${it.generation}" + if (it.switchFamily.isNotBlank()) " • Switch • Read-only" else "" }).toTypedArray()) { _, index ->
                            if (index == 0) showDialog("Folder scan summary", summary) else importRoutedSave(found[index - 1])
                        }.setNegativeButton("Close", null).show()
                }
            }
        }
    }

    private fun showAllRememberedSaves() {
        val all = visibleRememberedSaves(loadRememberedSaves())
        var shown = all.toList()
        val root = LinearLayout(this).apply { orientation = LinearLayout.VERTICAL; setPadding(dp(18), 0, dp(18), 0) }
        val search = EditText(this).apply { hint = "Search all saved games" }
        val adapter = ArrayAdapter<String>(this, android.R.layout.simple_list_item_1, shown.map { "${it.detectedGame} • Gen ${it.generation}" + if (it.switchFamily.isNotBlank()) " • Switch • Read-only" else "" }.toMutableList())
        val list = ListView(this).apply { this.adapter = adapter }
        root.addView(search); root.addView(list, LinearLayout.LayoutParams(-1, dp(380)))
        val dialog = AlertDialog.Builder(this).setTitle("All saved games (${all.size})").setView(root).setNegativeButton("Close", null).create()
        list.setOnItemClickListener { _, _, index, _ -> val selected = shown.getOrNull(index) ?: return@setOnItemClickListener; dialog.dismiss(); openRememberedSave(selected) }
        search.addTextChangedListener(object : android.text.TextWatcher {
            override fun beforeTextChanged(s: CharSequence?, start: Int, count: Int, after: Int) { }
            override fun afterTextChanged(s: android.text.Editable?) { }
            override fun onTextChanged(s: CharSequence?, start: Int, before: Int, count: Int) {
                val q = s?.toString().orEmpty()
                shown = all.filter { (it.detectedGame + " " + it.relativePath + " " + it.displayName + " " + it.switchFamily).contains(q, true) }
                adapter.clear(); adapter.addAll(shown.map { "${it.detectedGame} • Gen ${it.generation}" + if (it.switchFamily.isNotBlank()) " • Switch • Read-only" else "" }); adapter.notifyDataSetChanged()
            }
        })
        dialog.show()
    }

