    private fun scanDsTree(treeUri: Uri) {
        val progress = AlertDialog.Builder(this).setTitle("Scanning Nintendo DS")
            .setMessage("Looking for Pokémon Gen 4 and Gen 5 Nintendo DS saves…")
            .setCancelable(false).create(); progress.show()
        imageExecutor.execute {
            val found = try { findGen4SavesInTree(treeUri) } catch (_: Exception) { emptyList() }
            mainHandler.post { progress.dismiss(); showDsResults(found) }
        }
    }

    private fun findGen4SavesInTree(treeUri: Uri): List<ScannedSave> {
        val out = mutableListOf<ScannedSave>()
        val rootId = DocumentsContract.getTreeDocumentId(treeUri)
        val root = DocumentsContract.buildDocumentUriUsingTree(treeUri, rootId)
        scanDsDirectory(treeUri, root, "Nintendo DS", out, 0)
        return out.sortedWith(compareBy<ScannedSave> { it.detectedGame }.thenBy { it.relativePath })
    }

    private fun scanDsDirectory(treeUri: Uri, dir: Uri, path: String, out: MutableList<ScannedSave>, depth: Int) {
        if (depth > 12 || out.size >= 100) return
        val parentId = DocumentsContract.getDocumentId(dir)
        val children = DocumentsContract.buildChildDocumentsUriUsingTree(treeUri, parentId)
        val projection = arrayOf(DocumentsContract.Document.COLUMN_DOCUMENT_ID, DocumentsContract.Document.COLUMN_DISPLAY_NAME, DocumentsContract.Document.COLUMN_MIME_TYPE, DocumentsContract.Document.COLUMN_SIZE)
        contentResolver.query(children, projection, null, null, null)?.use { c ->
            val ic = c.getColumnIndex(DocumentsContract.Document.COLUMN_DOCUMENT_ID)
            val nc = c.getColumnIndex(DocumentsContract.Document.COLUMN_DISPLAY_NAME)
            val mc = c.getColumnIndex(DocumentsContract.Document.COLUMN_MIME_TYPE)
            val sc = c.getColumnIndex(DocumentsContract.Document.COLUMN_SIZE)
            while (c.moveToNext()) {
                val id = if (ic >= 0) c.getString(ic) else continue
                val name = if (nc >= 0) c.getString(nc) ?: "(unnamed)" else "(unnamed)"
                val mime = if (mc >= 0) c.getString(mc) else null
                val size = if (sc >= 0 && !c.isNull(sc)) c.getLong(sc) else -1L
                val child = DocumentsContract.buildDocumentUriUsingTree(treeUri, id)
                val childPath = "$path/$name"
                if (mime == DocumentsContract.Document.MIME_TYPE_DIR) scanDsDirectory(treeUri, child, childPath, out, depth + 1)
                else if (size < 0 || size == SIZE_G4.toLong()) inspectDsScannedSave(child, name, childPath)?.let { out.add(it) }
                if (out.size >= 100) return
            }
        }
    }

    private fun detectGen4GameFromPath(path: String): String {
        return gen4NameHint(path) ?: "Pokémon Gen 4"
    }

    private fun inspectDsScannedSave(uri: Uri, displayName: String, path: String): ScannedSave? {
        return try {
            val raw = boundedSourceBytes(uri) ?: return null
            if (raw.size != SIZE_G4) return null
            val g4 = detectGen4Profile(raw)
            if (g4 != null) return inspectGen4ScannedSave(uri, displayName, path)
            val g5 = detectGen5Profile(raw) ?: return null
            val game = gen5GameNameFromPath(path, g5)
            val analysis = SaveAnalysis(
                "Nintendo DS • Gen 4/5", true, SIZE_G5, SIZE_G5, true, sha256(raw),
                "Generation 5 Nintendo DS save validated as ${g5.family}. PK5 Party + all 24 PC Boxes are enabled in the first Gen 5 implementation.", null
            )
            ScannedSave(uri, displayName, path, analysis, game, 5)
        } catch (_: Exception) { null }
    }

    private fun inspectGen4ScannedSave(uri: Uri, displayName: String, path: String): ScannedSave? {
        return try {
            val raw = boundedSourceBytes(uri) ?: return null
            if (raw.size != SIZE_G4) return null
            val data = raw
            val profile = detectGen4Profile(data) ?: return null
            val pathGame = detectGen4GameFromPath(path)
            val game = if (pathGame == "Pokémon Gen 4") "Pokémon ${profile.family}" else pathGame
            val trainer = parseTrainerGen4(data)
            val analysis = SaveAnalysis(
                "Nintendo DS • Gen 4/5", true, SIZE_G4, SIZE_G4, true, sha256(data),
                "Generation 4 Nintendo DS save validated as ${profile.family}. PK4 Party + PC Box viewing is enabled read-only in Stage 3 verification.", trainer
            )
            ScannedSave(uri, displayName, path, analysis, game, 4)
        } catch (_: Exception) { null }
    }

    private fun showDsResults(found: List<ScannedSave>) {
        if (found.isEmpty()) {
            showDialog("Nintendo DS Scan", "No supported Gen 4 / Gen 5 Pokémon saves were found. PSE looks for standard 512 KB Diamond/Pearl/Platinum/HeartGold/SoulSilver and Black/White/Black 2/White 2 .sav images.")
            return
        }
        rememberScannedSaves(found); showHome()
        val labels = found.map { "${it.detectedGame}\nGen ${it.generation} • ${it.displayName}" as CharSequence }.toTypedArray()
        AlertDialog.Builder(this).setTitle("Nintendo DS Saves Found (${found.size})").setItems(labels) { _, which -> importDsSave(found[which]) }.setNegativeButton("Cancel", null).show()
    }

    private fun importDsSave(scanned: ScannedSave) {
        rememberScannedSaves(listOf(scanned))
        try {
            val raw = contentResolver.openInputStream(scanned.uri)?.use { it.readBytes() } ?: throw IllegalStateException("Could not open detected save")
            if (raw.size != SIZE_G4) throw IllegalStateException("Unexpected DS save size")
            val d = File(filesDir, "imports").apply { mkdirs() }
            val safe = scanned.displayName.replace(Regex("[^A-Za-z0-9._-]"), "_")
            val dest = File(d, "${SimpleDateFormat("yyyyMMdd_HHmmss", Locale.US).format(Date())}_DS_$safe")
            // Work on the exact 512 KiB SRAM image. The original source remains untouched until explicit replacement.
            dest.writeBytes(raw)
            activeSwitchSave = null
            importedFile = dest; resetPokemonSelection(); rememberCurrentSource(scanned.uri, scanned.relativePath)
            Toast.makeText(this, "${scanned.detectedGame} imported from Nintendo DS", Toast.LENGTH_LONG).show(); showHome()
        } catch (e: Exception) { showDialog("Nintendo DS Import", "Could not import this save: ${e.message}") }
    }

