    private fun findGen1SavesInTree(treeUri: Uri): List<ScannedSave> {
        val results = mutableListOf<ScannedSave>()
        val rootId = DocumentsContract.getTreeDocumentId(treeUri)
        val rootUri = DocumentsContract.buildDocumentUriUsingTree(treeUri, rootId)
        scanGen1DocumentDirectory(treeUri, rootUri, "Game Boy & Game Boy Color", results, 0)
        return results.sortedWith(compareBy<ScannedSave> { it.detectedGame }.thenBy { it.relativePath })
    }

    private fun scanGen1DocumentDirectory(
        treeUri: Uri,
        directoryUri: Uri,
        path: String,
        results: MutableList<ScannedSave>,
        depth: Int
    ) {
        if (depth > 12 || results.size >= 100) return
        val parentId = DocumentsContract.getDocumentId(directoryUri)
        val childrenUri = DocumentsContract.buildChildDocumentsUriUsingTree(treeUri, parentId)
        val projection = arrayOf(
            DocumentsContract.Document.COLUMN_DOCUMENT_ID,
            DocumentsContract.Document.COLUMN_DISPLAY_NAME,
            DocumentsContract.Document.COLUMN_MIME_TYPE,
            DocumentsContract.Document.COLUMN_SIZE
        )
        contentResolver.query(childrenUri, projection, null, null, null)?.use { cursor ->
            val idCol = cursor.getColumnIndex(DocumentsContract.Document.COLUMN_DOCUMENT_ID)
            val nameCol = cursor.getColumnIndex(DocumentsContract.Document.COLUMN_DISPLAY_NAME)
            val mimeCol = cursor.getColumnIndex(DocumentsContract.Document.COLUMN_MIME_TYPE)
            val sizeCol = cursor.getColumnIndex(DocumentsContract.Document.COLUMN_SIZE)
            while (cursor.moveToNext()) {
                val docId = if (idCol >= 0) cursor.getString(idCol) else continue
                val name = if (nameCol >= 0) cursor.getString(nameCol) ?: "(unnamed)" else "(unnamed)"
                val mime = if (mimeCol >= 0) cursor.getString(mimeCol) else null
                val size = if (sizeCol >= 0 && !cursor.isNull(sizeCol)) cursor.getLong(sizeCol) else -1L
                val childUri = DocumentsContract.buildDocumentUriUsingTree(treeUri, docId)
                val childPath = "$path/$name"
                if (mime == DocumentsContract.Document.MIME_TYPE_DIR) {
                    scanGen1DocumentDirectory(treeUri, childUri, childPath, results, depth + 1)
                } else if (size >= SIZE_G1.toLong() && size <= (SIZE_G1 + 4096).toLong()) {
                    // Some GBC emulators append RTC/trailer bytes to the 32 KiB SRAM image (especially Crystal).
                    // Validate the Gen 1/2 save from the SRAM portion while preserving the complete source file.
                    inspectGen1ScannedSave(childUri, name, childPath)?.let { results.add(it) }
                }
                if (results.size >= 100) return
            }
        }
    }

    private fun inspectGen1ScannedSave(uri: Uri, displayName: String, path: String): ScannedSave? {
        val temp = File(cacheDir, "scan_g1_${System.nanoTime()}.sav")
        return try {
            val bounded = boundedSourceBytes(uri) ?: return null
            temp.writeBytes(bounded)
            val analysis = analyzeSave(temp)
            if (!analysis.structurallyValid || analysis.trainer == null) null
            else {
                val raw = temp.readBytes()
                val g2 = detectGen2Profile(raw)
                if (g2 != null) {
                    ScannedSave(uri, displayName, path, analysis, detectGen2GameFromPath(path, g2), 2)
                } else if (raw.size == SIZE_G1) {
                    ScannedSave(uri, displayName, path, analysis, detectGen1GameFromPath(path), 1)
                } else null
            }
        } catch (_: Exception) {
            null
        } finally {
            temp.delete()
        }
    }

    private fun inspectPickedGen1Save(uri: Uri): ScannedSave? {
        val displayName = queryDisplayName(uri) ?: "selected.sav"
        return inspectGen1ScannedSave(uri, displayName, displayName)
    }

    private fun detectGen1GameFromPath(path: String): String {
        val p = path.lowercase(Locale.US)
        return when {
            "yellow" in p || "pikachu" in p -> "Pokémon Yellow"
            "blue" in p -> "Pokémon Blue"
            "red" in p -> "Pokémon Red"
            else -> "Pokémon Red / Blue / Yellow"
        }
    }

    private fun detectGen2GameFromPath(path: String, profile: Gen2Profile): String {
        if (profile.key == "C") return "Pokémon Crystal"
        val normalizedPath = path.replace('\\', '/')
        val filename = normalizedPath.substringAfterLast('/').lowercase(Locale.US)
        val directory = normalizedPath.substringBeforeLast('/', "").lowercase(Locale.US)
        return when {
            "silver" in filename && "gold" !in filename -> "Pokémon Silver"
            "gold" in filename && "silver" !in filename -> "Pokémon Gold"
            "silver" in filename && "gold" in filename -> "Pokémon Gold / Silver"
            "silver" in directory && "gold" !in directory -> "Pokémon Silver"
            "gold" in directory && "silver" !in directory -> "Pokémon Gold"
            else -> "Pokémon Gold / Silver"
        }
    }

    private fun showPizzaBoyCResults(found: List<ScannedSave>) {
        if (found.isEmpty()) {
            showDialog(
                "Game Boy & Game Boy Color Scan",
                "No valid supported Pokémon saves were found in that folder.\n\nChoose the Game Boy & Game Boy Color folder that contains your .sav battery-save files. PSE recognises supported 32 KB Gen 1 and Gen 2 saves after checksum validation."
            )
            return
        }
        rememberScannedSaves(found)
        // Refresh the Home screen immediately so newly discovered saves appear in the Saved Games rail behind this dialog.
        showHome()
        val labels: Array<CharSequence> = found.map { scanned ->
            "${scanned.detectedGame}\nGen ${scanned.generation} • ${scanned.displayName}" as CharSequence
        }.toTypedArray()

        val builder = android.app.AlertDialog.Builder(this)
        builder.setTitle("Game Boy & Game Boy Color Saves Found (${found.size})")
        builder.setItems(labels, android.content.DialogInterface.OnClickListener { _, which ->
            importPizzaBoyCSave(found[which])
        })
        builder.setNegativeButton("Cancel", android.content.DialogInterface.OnClickListener { dialog, _ ->
            dialog.dismiss()
        })
        builder.show()
    }

    private fun importPizzaBoyCSave(scanned: ScannedSave) {
        rememberScannedSaves(listOf(scanned))
        try {
            val importsDir = File(filesDir, "imports").apply { mkdirs() }
            val safeName = scanned.displayName.replace(Regex("[^A-Za-z0-9._-]"), "_")
            val stamp = SimpleDateFormat("yyyyMMdd_HHmmss", Locale.US).format(Date())
            val destination = File(importsDir, "${stamp}_PizzaBoyC_$safeName")
            contentResolver.openInputStream(scanned.uri).use { input ->
                val source = requireNotNull(input) { "Could not open detected save" }
                destination.outputStream().use { output -> source.copyTo(output) }
            }
            val check = analyzeSave(destination)
            if (!check.structurallyValid || (check.actualSize != SIZE_G1 && detectGen2Profile(destination.readBytes()) == null)) {
                destination.delete()
                showDialog("Import stopped", "The detected Game Boy / Game Boy Color save changed or failed checksum validation. Nothing was imported.")
                return
            }
            activeSwitchSave = null
            importedFile = destination
            resetPokemonSelection()
            rememberCurrentSource(scanned.uri, scanned.relativePath)
            refreshSaveCard()
            Toast.makeText(this, "${scanned.detectedGame} imported from Game Boy & Game Boy Color", Toast.LENGTH_LONG).show()
            showHome()
        } catch (e: Exception) {
            showDialog("Game Boy & Game Boy Color Import", "Could not import this save: ${e.message}")
        }
    }

