        return results.sortedWith(compareBy<ScannedSave> { it.detectedGame }.thenBy { it.relativePath })
    }

    private fun scanDocumentDirectory(
        treeUri: Uri,
        directoryUri: Uri,
        path: String,
        results: MutableList<ScannedSave>,
        depth: Int
    ) {
        if (depth > 16 || results.size >= 100) return
        val parentId = DocumentsContract.getDocumentId(directoryUri)
        val childrenUri = DocumentsContract.buildChildDocumentsUriUsingTree(treeUri, parentId)
        val projection = arrayOf(
            DocumentsContract.Document.COLUMN_DOCUMENT_ID,
            DocumentsContract.Document.COLUMN_DISPLAY_NAME,
            DocumentsContract.Document.COLUMN_MIME_TYPE,
            DocumentsContract.Document.COLUMN_SIZE
        )
        contentResolver.query(childrenUri, projection, null, null, null)?.use { cursor ->
            val idCol = cursor.getColumnIndex(DocumentsContract.Document.COLUMN_DOCUMENT_ID)
            val nameCol = cursor.getColumnIndex(DocumentsContract.Document.COLUMN_DISPLAY_NAME)
            val mimeCol = cursor.getColumnIndex(DocumentsContract.Document.COLUMN_MIME_TYPE)
            val sizeCol = cursor.getColumnIndex(DocumentsContract.Document.COLUMN_SIZE)
            while (cursor.moveToNext()) {
                val docId = if (idCol >= 0) cursor.getString(idCol) else continue
                val name = if (nameCol >= 0) cursor.getString(nameCol) ?: "(unnamed)" else "(unnamed)"
                val mime = if (mimeCol >= 0) cursor.getString(mimeCol) else null
                val size = if (sizeCol >= 0 && !cursor.isNull(sizeCol)) cursor.getLong(sizeCol) else -1L
                val childUri = DocumentsContract.buildDocumentUriUsingTree(treeUri, docId)
                val childPath = "$path/$name"

                if (mime == DocumentsContract.Document.MIME_TYPE_DIR) {
                    scanDocumentDirectory(treeUri, childUri, childPath, results, depth + 1)
                } else if (
                    size == SIZE_G6_XY.toLong() ||
                    size == SIZE_G6_ORAS.toLong() ||
                    size == SIZE_G7_SM.toLong() ||
                    size == SIZE_G7_USUM.toLong()
                ) {
                    inspectScannedSave(childUri, name, childPath)?.let { results.add(it) }
                }
                if (results.size >= 100) return
            }
        }
    }

    private fun inspectScannedSave(uri: Uri, displayName: String, path: String): ScannedSave? {
        val temp = File(cacheDir, "scan_${System.nanoTime()}.bin")
        return try {
            val bounded = boundedSourceBytes(uri) ?: return null
            temp.writeBytes(bounded)
            val analysis = analyzeSave(temp)
            when (analysis.actualSize) {
                SIZE_G6_XY, SIZE_G6_ORAS -> {
                    if (analysis.structurallyValid && analysis.trainer?.gameMatchesFamily == true) {
                        ScannedSave(uri, displayName, path, analysis, analysis.trainer!!.exactGame, 6)
                    } else null
                }
                SIZE_G7_SM, SIZE_G7_USUM -> {
                    if (!analysis.footerValid) null
                    else {
                        val game = analysis.trainer?.takeIf { it.gameMatchesFamily }?.exactGame
                            ?: detectGen7GameFromAzaharPath(path, analysis.actualSize)
                        ScannedSave(uri, displayName, path, analysis, game, 7)
                    }
                }
                else -> null
            }
        } catch (_: Exception) {
            null
        } finally {
            temp.delete()
        }
    }

