    }

    private fun detectGen7GameFromAzaharPath(path: String, size: Int): String {
        val p = path.lowercase(Locale.US)
        return when {
            p.contains("00164800") -> "Pokémon Sun"
            p.contains("00175e00") -> "Pokémon Moon"
            p.contains("001b5000") -> "Pokémon Ultra Sun"
            p.contains("001b5100") -> "Pokémon Ultra Moon"
            size == SIZE_G7_SM -> "Pokémon Sun / Pokémon Moon"
            size == SIZE_G7_USUM -> "Pokémon Ultra Sun / Pokémon Ultra Moon"
            else -> "Pokémon Gen 7"
        }
    }

    private fun importScannedSave(scanned: ScannedSave) {
        rememberScannedSaves(listOf(scanned))
        try {
            val importsDir = File(filesDir, "imports").apply { mkdirs() }
            val safeName = scanned.displayName.replace(Regex("[^A-Za-z0-9._-]"), "_")
            val stamp = SimpleDateFormat("yyyyMMdd_HHmmss", Locale.US).format(Date())
            val destination = File(importsDir, "${stamp}_Azahar_$safeName")
            contentResolver.openInputStream(scanned.uri).use { input ->
                val source = requireNotNull(input) { "Could not open detected save" }
                destination.outputStream().use { output -> source.copyTo(output) }
            }
            val check = analyzeSave(destination)
            if (!check.structurallyValid || check.trainer?.gameMatchesFamily != true) {
                destination.delete()
                showDialog("Import stopped", "The detected file changed or failed validation. Nothing was imported.")
                return
            }
            activeSwitchSave = null
            importedFile = destination
            resetPokemonSelection()
            rememberCurrentSource(scanned.uri, scanned.relativePath)
            refreshSaveCard()
            Toast.makeText(this, "${check.trainer?.exactGame ?: check.family} imported from Azahar", Toast.LENGTH_LONG).show()
            showHome()
        } catch (e: Exception) {
            showDialog("Azahar Import", "Could not import this save: ${e.message}")
        }
    }


    private fun showGen6ConvertSave() {
        val sourceFile = importedFile
        if (sourceFile == null) {
            showDialog("Convert Save", "Load a Generation 6 save first.")
            return
        }
        val sourceBytes = runCatching { sourceFile.readBytes() }.getOrElse {
            showDialog("Convert Save", "PSE could not read the loaded save.")
            return
        }
        val preview = runCatching {
            Gen6ConvertSaveWorkflow.preview(
                sourceBytes,
                currentSourceLabel ?: sourceFile.name
            )
        }.getOrElse {
            showDialog("Convert Save", it.message ?: "This save cannot be converted.")
            return
        }

        val root = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(dp(18), dp(42), dp(18), dp(28))
            setBackgroundColor(BG)
        }
        root.addView(TextView(this).apply {
            text = "Convert Save"
            textSize = 30f
            typeface = Typeface.DEFAULT_BOLD
            setTextColor(TEXT)
        })
        addMutedLine(
            root,
            "${preview.sourceTitle} → ${preview.destinationTitle}"
        )
        root.addView(TextView(this).apply {
            text = "A new destination save will be exported. The loaded source and the selected destination template will remain unchanged."
            textSize = 15f
            setTextColor(GOOD)
            setPadding(0, dp(14), 0, dp(12))
        })
        root.addView(TextView(this).apply {
            text = "Transferred"
            textSize = 17f
            typeface = Typeface.DEFAULT_BOLD
            setTextColor(ACCENT)
        })
        preview.preserved.forEach { addMutedLine(root, "✓  $it") }
        root.addView(TextView(this).apply {
            text = "Not copied from the source"
            textSize = 17f
            typeface = Typeface.DEFAULT_BOLD
            setTextColor(WARN)
            setPadding(0, dp(14), 0, 0)
        })
        preview.omitted.forEach { addMutedLine(root, "•  $it") }
        root.addView(TextView(this).apply {
            text = preview.versionExclusiveAvailabilityNotice()
            textSize = 14f
            setTextColor(
                if (preview.canOfferVersionExclusives) ACCENT else MUTED
            )
            setPadding(0, dp(12), 0, 0)
        })
        root.addView(TextView(this).apply {
            text = preview.compatibilityNotice
            textSize = 14f
            setTextColor(WARN)
            setPadding(0, dp(14), 0, dp(8))
        })
        addMutedLine(
            root,
            "Choose your own valid ${preview.destinationTitle} save as the destination baseline. PSE does not bundle game saves."
        )
        val baselineConsent = CheckBox(this).apply {
            text = "I understand that destination progress comes from the selected template and the listed source progress will not be copied."
            textSize = 14f
            setTextColor(TEXT)
            setPadding(0, dp(12), 0, dp(12))
        }
        root.addView(baselineConsent)
        val chooseTemplateButton = addButton(
            root,
            "Choose ${preview.destinationTitle} template"
        ) {
            pendingGen6UiSource = PendingGen6UiSource(
                sourceFile.absolutePath,
                sourceBytes.copyOf(),
                currentSourceUri?.toString(),
                preview
            )
            val intent = Intent(Intent.ACTION_OPEN_DOCUMENT).apply {
                addCategory(Intent.CATEGORY_OPENABLE)
                type = "*/*"
                addFlags(
                    Intent.FLAG_GRANT_READ_URI_PERMISSION or
                        Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION
                )
            }
            startActivityForResult(intent, PICK_GEN6_CONVERTER_TEMPLATE)
        }
        chooseTemplateButton.isEnabled = false
        baselineConsent.setOnCheckedChangeListener { _, accepted ->
            chooseTemplateButton.isEnabled = accepted
        }
        addButton(root, "Cancel") {
            pendingGen6UiSource = null
            pendingGen6UiExport = null
            showHome()
        }
        setContentView(ScrollView(this).apply { addView(root) })
        phoneBackAction = { showHome() }
    }

    private fun handleGen6ConverterTemplate(uri: Uri) {
        val pending = pendingGen6UiSource ?: return
        try {
            require(!Gen6DocumentIdentity.sameDocument(uri.toString(), pending.sourceUri)) {
                "The destination template cannot be the original source save."
            }
            val current = importedFile
                ?: error("The loaded source is no longer available.")
            require(current.absolutePath == pending.filePath &&
                current.readBytes().contentEquals(pending.sourceBytes)
            ) {
                "The loaded source changed after the conversion preview opened."
            }
            val templateBytes = contentResolver.openInputStream(uri).use { input ->
                requireNotNull(input) {
                    "Could not open the selected destination template."
                }.readBytes()
            }
            val destinationPreview = Gen6ConvertSaveWorkflow.previewDestination(
                pending.sourceBytes.copyOf(),
                templateBytes,
                currentSourceLabel ?: current.name
            )
            require(destinationPreview.canPrepare) {
                destinationPreview.capacityNotice()
            }
            val prepared = Gen6ConvertSaveWorkflow.prepare(
                pending.sourceBytes.copyOf(),
                templateBytes,
                currentSourceLabel ?: current.name,
                destinationBaselineAccepted = true
            )
            require(current.readBytes().contentEquals(pending.sourceBytes)) {
                "The loaded source changed while conversion was prepared."
            }
            pendingGen6UiExport = PendingGen6UiExport(
                pending.filePath,
                pending.sourceBytes.copyOf(),
                pending.sourceUri,
                uri.toString(),
                templateBytes.copyOf(),
                prepared
            )
            pendingGen6UiSource = null
            val intent = Intent(Intent.ACTION_CREATE_DOCUMENT).apply {
                addCategory(Intent.CATEGORY_OPENABLE)
                type = "application/octet-stream"
                putExtra(Intent.EXTRA_TITLE, prepared.preview.suggestedFilename)
            }
            startActivityForResult(intent, EXPORT_GEN6_CONVERTED_SAVE)
        } catch (e: Exception) {
            showDialog(
                "Conversion template rejected",
                (e.message ?: "The destination template is invalid.") +
                    "\n\nNothing was written and the source remains unchanged."
            )
        }
    }

    private fun handleGen6ConvertedExport(uri: Uri) {
        val pending = pendingGen6UiExport ?: return
        try {
            require(!Gen6DocumentIdentity.sameDocument(uri.toString(), pending.sourceUri)) {
                "The converted save cannot replace the original source."
            }
            require(!Gen6DocumentIdentity.sameDocument(uri.toString(), pending.templateUri)) {
                "The converted save cannot replace the destination template."
            }
            val current = importedFile
                ?: error("The loaded source is no longer available.")
            require(current.absolutePath == pending.filePath &&
                current.readBytes().contentEquals(pending.sourceBytes)
            ) {
                "The loaded source changed before export."
            }
            Gen6DocumentExportTransaction.exportNew(
                destinationBytes = pending.prepared.bytes,
                expectedGame = pending.prepared.preview.request.destination,
                target = object : Gen6DocumentExportTarget {
                    override fun readBeforeWrite(): ByteArray =
                        contentResolver.openInputStream(uri).use { input ->
                            requireNotNull(input) {
                                "Could not verify that the destination document is new and empty."
                            }.readBytes()
                        }

                    override fun write(bytes: ByteArray) {
                        contentResolver.openOutputStream(uri, "w").use { output ->
                            requireNotNull(output) {
                                "Could not open the new destination document."
                            }.write(bytes)
                        }
                    }

                    override fun read(): ByteArray =
                        contentResolver.openInputStream(uri).use { input ->
                            requireNotNull(input) {
                                "Could not reopen the converted destination."
                            }.readBytes()
                        }

                    override fun delete(): Boolean =
                        contentResolver.delete(uri, null, null) > 0
                },
                sourceUnchanged = {
                    current.absolutePath == pending.filePath &&
                        current.readBytes().contentEquals(pending.sourceBytes)
                },
                templateUnchanged = {
                    contentResolver.openInputStream(
                        Uri.parse(pending.templateUri)
                    ).use { input ->
                        requireNotNull(input) {
                            "Could not reopen the destination template for preservation verification."
                        }.readBytes().contentEquals(pending.templateBytes)
                    }
                }
            )
            val acceptance =
                Gen6ConversionAcceptance.automatedOnly(
                    pending.prepared.preview.request
                )
            pendingGen6UiExport = null
            showHome()
            showDialog(
                "Converted save exported",
                "${pending.prepared.preview.destinationTitle} was exported as a new file.\n\n" +
                    acceptance.userNotice()
            )
        } catch (e: Exception) {
            showDialog(
                "Convert Save failed",
                (e.message ?: "The converted destination could not be exported.") +
                    "\n\nThe loaded source and destination template were not changed by PSE."
            )
        }
    }

    private fun pickSave() {
        val intent = Intent(Intent.ACTION_OPEN_DOCUMENT).apply {
            addCategory(Intent.CATEGORY_OPENABLE)
            type = "*/*"
            addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION or Intent.FLAG_GRANT_WRITE_URI_PERMISSION or Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION)
        }
        startActivityForResult(intent, PICK_SAVE)
    }

    /**
     * Format-first router for a manually selected save. A picker label only describes
     * the UI path the user came from; it must never decide the save generation.
     * Every detector below performs its own structural/checksum validation.
     */
    private fun inspectAnySupportedPickedSave(uri: Uri, displayName: String, path: String): ScannedSave? {
        inspectSwitchScannedSave(uri, displayName, path)?.let { return it }
        // Gen 3 first: 128 KiB GBA saves are a common source of ambiguous .sav files,
        // and a valid section table/checksum set is authoritative regardless of filename.
        inspectGen3ScannedSave(uri, displayName, path)?.let { return it }
        inspectGen1ScannedSave(uri, displayName, path)?.let { return it }
        inspectDsScannedSave(uri, displayName, path)?.let { return it }
        inspectScannedSave(uri, displayName, path)?.let { return it }
        return null
    }

    private fun importRoutedSave(scanned: ScannedSave) {
        if (scanned.switchFamily.isNotBlank()) { openSwitchSource(scanned); return }
        when (scanned.generation) {
            1, 2 -> importPizzaBoyCSave(scanned)
            3 -> importGbaSave(scanned)
            4, 5 -> importDsSave(scanned)
            6, 7 -> importScannedSave(scanned)
            else -> showDialog("Save not recognised", "That file does not match a currently supported Pokémon save format.")
        }
    }

    private fun persistGrantedUriPermission(uri: Uri, flags: Int) {
        val read = Intent.FLAG_GRANT_READ_URI_PERMISSION
        val write = Intent.FLAG_GRANT_WRITE_URI_PERMISSION
        when (flags and (read or write)) {
            read -> contentResolver.takePersistableUriPermission(uri, Intent.FLAG_GRANT_READ_URI_PERMISSION)
            write -> contentResolver.takePersistableUriPermission(uri, Intent.FLAG_GRANT_WRITE_URI_PERMISSION)
            (read or write) -> contentResolver.takePersistableUriPermission(uri,
                Intent.FLAG_GRANT_READ_URI_PERMISSION or Intent.FLAG_GRANT_WRITE_URI_PERMISSION)
        }
    }

    @Deprecated("Deprecated in Android API, retained for minSdk-compatible prototype")
    override fun onActivityResult(requestCode: Int, resultCode: Int, data: Intent?) {
        super.onActivityResult(requestCode, resultCode, data)
        if (requestCode in setOf(PICK_SWITCH_SOURCE, PICK_SWITCH_SOURCE_TREE, PICK_ALL_SOURCE_TREE)) {
            if (resultCode != RESULT_OK) return
            val uri = data?.data ?: return
            if (uri.scheme != "content") { showDialog("Save source", "Choose an Android document or folder."); return }
            try {
                persistGrantedUriPermission(
                    uri,
                    data.flags and (Intent.FLAG_GRANT_READ_URI_PERMISSION or Intent.FLAG_GRANT_WRITE_URI_PERMISSION)
                )
            } catch (_: Exception) { }
            if (requestCode == PICK_SWITCH_SOURCE) {
                val name = queryDisplayName(uri) ?: "save"
                val progress = AlertDialog.Builder(this).setTitle("Reading Switch save").setMessage("Validating the original source…").setCancelable(false).create()
                progress.show()
                imageExecutor.execute {
                    val found = inspectSwitchScannedSave(uri, name, name)
                    mainHandler.post {
                        if (isFinishing || isDestroyed) return@post
                        progress.dismiss()
                        if (found == null) showDialog("Switch save not recognised", "No supported, integrity-verified extracted Switch save was found. The previous selection is unchanged.")
                        else openSwitchSource(found)
                    }
                }
            } else {
                val switchOnly = requestCode == PICK_SWITCH_SOURCE_TREE
                getSharedPreferences("pse_scanner", MODE_PRIVATE).edit().putString(if (switchOnly) "switch_tree" else "all_tree", uri.toString()).apply()
                scanUnifiedSourceTree(uri, switchOnly)
            }
            return
        }
        if(requestCode==EXPORT_GEN2_SAVE){
            val pending=pendingGen2SaveExport
            pendingGen2SaveExport=null
            if(resultCode!=RESULT_OK||pending==null)return
            val uri=data?.data?:run{showDialog("Export blocked","No export destination was returned. Nothing was written.");return}
            finishGen2SaveExport(pending,uri)
            return
        }
        if (resultCode != RESULT_OK) {
            when (requestCode) {
                PICK_GEN6_CONVERTER_TEMPLATE -> pendingGen6UiSource = null
                EXPORT_GEN6_CONVERTED_SAVE -> pendingGen6UiExport = null
            }
            return
        }

        if (requestCode == PICK_GEN6_CONVERTER_TEMPLATE) {
            val uri = data?.data ?: return
            val flags = data.flags and Intent.FLAG_GRANT_READ_URI_PERMISSION
            try {
                persistGrantedUriPermission(uri, flags)
            } catch (_: Exception) { }
            handleGen6ConverterTemplate(uri)
            return
        }

        if (requestCode == EXPORT_GEN6_CONVERTED_SAVE) {
            val uri = data?.data ?: return
            handleGen6ConvertedExport(uri)
            return
        }

        if (requestCode == REPAIR_REMEMBERED_SAVE) {
            val target = rememberedSaveRepairTarget ?: return
            rememberedSaveRepairTarget = null
            val uri = data?.data ?: return
            val flags = data.flags and (Intent.FLAG_GRANT_READ_URI_PERMISSION or Intent.FLAG_GRANT_WRITE_URI_PERMISSION)
            try { persistGrantedUriPermission(uri, flags) } catch (_: Exception) { }
            val name = queryDisplayName(uri) ?: target.displayName
            val progress = AlertDialog.Builder(this)
                .setTitle("Reconnecting ${rememberedCardGame(target)}")
                .setMessage("Validating the selected save…")
                .setCancelable(false)
                .create()
            progress.show()
            imageExecutor.execute {
                mainHandler.post {
                    progress.dismiss()
                    finishRememberedSaveRepair(target, uri, name)
                }
            }
            return
        }

        if (requestCode == PICK_DS_SAVE) {
            val uri = data?.data ?: return
            val flags = data.flags and (Intent.FLAG_GRANT_READ_URI_PERMISSION or Intent.FLAG_GRANT_WRITE_URI_PERMISSION)
            try { persistGrantedUriPermission(uri, flags) } catch (_: Exception) { }
            val name = queryDisplayName(uri) ?: "selected.sav"
            val scanned = inspectDsScannedSave(uri, name, name)
            if (scanned == null) showDialog("Nintendo DS save not recognised", "That file is not a supported standard 512 KB Gen 4 / Gen 5 Pokémon .sav image.") else importDsSave(scanned)
            return
        }
        if (requestCode == PICK_DS_TREE) {
            val uri = data?.data ?: return
            val flags = data.flags and (Intent.FLAG_GRANT_READ_URI_PERMISSION or Intent.FLAG_GRANT_WRITE_URI_PERMISSION)
            try { persistGrantedUriPermission(uri, flags) } catch (_: Exception) { }
            getSharedPreferences("pse_scanner", MODE_PRIVATE).edit().putString("ds_tree", uri.toString()).apply(); scanDsTree(uri); return
        }

        if (requestCode == PICK_GBA_SAVE) {
            val uri=data?.data?:return;val flags=data.flags and (Intent.FLAG_GRANT_READ_URI_PERMISSION or Intent.FLAG_GRANT_WRITE_URI_PERMISSION);try{persistGrantedUriPermission(uri, flags)}catch(_:Exception){}
            val name=queryDisplayName(uri)?:"selected.sav"
            val scanned=inspectGen3ScannedSave(uri,name,name)
            if(scanned!=null) importGbaSave(scanned)
            else {
                val routed=inspectAnySupportedPickedSave(uri,name,name)
                if(routed!=null) importRoutedSave(routed)
                else showDialog("Gen 3 save not recognised","That file does not contain a valid Pokémon Ruby, Sapphire, Emerald, FireRed or LeafGreen Gen 3 save region with valid section checksums.")
            }
            return
        }
        if (requestCode == PICK_GBA_TREE) {
            val uri=data?.data?:return;val flags=data.flags and (Intent.FLAG_GRANT_READ_URI_PERMISSION or Intent.FLAG_GRANT_WRITE_URI_PERMISSION);try{persistGrantedUriPermission(uri, flags)}catch(_:Exception){};getSharedPreferences("pse_scanner",MODE_PRIVATE).edit().putString("gba_tree",uri.toString()).apply();scanGbaTree(uri);return
        }

        if (requestCode == PICK_PIZZABOYC_SAVE) {
            val uri = data?.data ?: return
            val flags = data.flags and (
                Intent.FLAG_GRANT_READ_URI_PERMISSION or Intent.FLAG_GRANT_WRITE_URI_PERMISSION
            )
            try { persistGrantedUriPermission(uri, flags) } catch (_: Exception) { }
            val scanned = inspectPickedGen1Save(uri)
            if (scanned == null) {
                // Do not trust the picker path as the format. If a user selects a Ruby,
                // DS or 3DS save here, route it by its validated structure instead of
                // incorrectly reporting a Gen 1 checksum error.
                val name = queryDisplayName(uri) ?: "selected.sav"
                val routed = inspectAnySupportedPickedSave(uri, name, name)
                if (routed != null) importRoutedSave(routed)
                else showDialog(
                    "Save not recognised",
                    "That file does not match a supported Pokémon save format. PSE checked Gen 1/2, Gen 3, Gen 4/5 and Gen 6/7 structures rather than assuming the generation from the picker used."
                )
            } else {
                importPizzaBoyCSave(scanned)
            }
            return
        }

        if (requestCode == PICK_PIZZABOYC_TREE) {
            val treeUri = data?.data ?: return
            val flags = data.flags and (
                Intent.FLAG_GRANT_READ_URI_PERMISSION or Intent.FLAG_GRANT_WRITE_URI_PERMISSION
            )
            try { persistGrantedUriPermission(treeUri, flags) } catch (_: Exception) { }
            getSharedPreferences("pse_scanner", MODE_PRIVATE).edit().putString("pizzaboyc_tree", treeUri.toString()).apply()
            scanPizzaBoyCTree(treeUri)
            return
        }

        if (requestCode == PICK_AZAHAR_TREE) {
            val treeUri = data?.data ?: return
            val flags = data.flags and (
                Intent.FLAG_GRANT_READ_URI_PERMISSION or Intent.FLAG_GRANT_WRITE_URI_PERMISSION
            )
            try {
                persistGrantedUriPermission(treeUri, flags)
            } catch (_: Exception) { }
            getSharedPreferences("pse_scanner", MODE_PRIVATE).edit().putString("azahar_tree", treeUri.toString()).apply()
            scanAzaharTree(treeUri)
            return
        }

        if (requestCode == PICK_SAFE_FOLDER) {
            val treeUri = data?.data ?: return
            val flags = data.flags and (
                Intent.FLAG_GRANT_READ_URI_PERMISSION or Intent.FLAG_GRANT_WRITE_URI_PERMISSION
            )
            try {
                persistGrantedUriPermission(treeUri, flags)
            } catch (_: Exception) { }
            getSharedPreferences("pse_safe_files", MODE_PRIVATE).edit()
                .putString("tree_uri", treeUri.toString())
                .apply()
            Toast.makeText(this, "PSE Safe Backups folder set", Toast.LENGTH_LONG).show()
            showSafeBackups()
            return
        }

        if (requestCode == EXPORT_SAVE) {
            val uri = data?.data ?: return
            val file = importedFile ?: return
            if(runCatching{detectGen2ChecksumProfile(file.readBytes())!=null}.getOrDefault(false)){
                showDialog("Export blocked","This older export request is not bound to the current Gen 2 save. Reopen Export. Nothing was written.")
                return
            }
            try {
                contentResolver.openOutputStream(uri, "w").use { output ->
                    val out = requireNotNull(output) { "Could not open export destination" }
                    file.inputStream().use { input -> input.copyTo(out) }
                }
                Toast.makeText(this, "Current save exported successfully", Toast.LENGTH_LONG).show()
            } catch (e: Exception) {
                Toast.makeText(this, "Could not export save: ${e.message}", Toast.LENGTH_LONG).show()
            }
            return
        }

        if (requestCode != PICK_SAVE) return
        val uri = data?.data ?: return

        try {
            contentResolver.takePersistableUriPermission(uri, Intent.FLAG_GRANT_READ_URI_PERMISSION or Intent.FLAG_GRANT_WRITE_URI_PERMISSION)
        } catch (_: Exception) { }

        try {
            val displayName = queryDisplayName(uri) ?: "main"

            // Generic Import is also format-first. If PSE can structurally identify the
            // save, hand it to the generation-specific importer so normalization,
            // remembered-source metadata and safety checks are applied consistently.
            val routed = inspectAnySupportedPickedSave(uri, displayName, displayName)
            if (routed != null) {
                importRoutedSave(routed)
                return
            }

            val importsDir = File(filesDir, "imports").apply { mkdirs() }
            val safeName = displayName.replace(Regex("[^A-Za-z0-9._-]"), "_")
            val stamp = SimpleDateFormat("yyyyMMdd_HHmmss", Locale.US).format(Date())
            val destination = File(importsDir, "${stamp}_$safeName")

            contentResolver.openInputStream(uri).use { input ->
                val inputStream = requireNotNull(input) { "Could not open selected file" }
                destination.outputStream().use { output -> inputStream.copyTo(output) }
            }

            activeSwitchSave = null

            importedFile = destination
            resetPokemonSelection()
            rememberCurrentSource(uri, displayName)
            refreshSaveCard()
            Toast.makeText(this, "Save imported safely", Toast.LENGTH_LONG).show()
            showHome()
        } catch (e: Exception) {
            Toast.makeText(this, "Could not import save: ${e.message}", Toast.LENGTH_LONG).show()
        }
    }

    private fun sourceGameIdentity(file: File, label: String? = currentSourceLabel): String? {
        val bytes = runCatching { file.readBytes() }.getOrNull() ?: return null
        val gen2 = detectGen2Profile(bytes)
        if (gen2 != null) return detectGen2GameFromPath(label ?: file.name, gen2)
        val analysis = runCatching { analyzeSave(file) }.getOrNull() ?: return null
        return analysis.trainer?.exactGame ?: analysis.family
    }

    private fun rememberCurrentSource(uri: Uri, label: String) {
        currentSourceUri = uri
        currentSourceLabel = label
        val working = importedFile
        val analysis = working?.let { runCatching { analyzeSave(it) }.getOrNull() }
        getSharedPreferences("pse_current_source", MODE_PRIVATE).edit()
            .putString("uri", uri.toString())
            .putString("label", label)
            .putString("baseline_hash", analysis?.sha256)
            .putString("source_game", working?.let { sourceGameIdentity(it, label) })
            .putLong("source_size", working?.length() ?: 0L)
            .putLong("bound_at", System.currentTimeMillis())
            .apply()
    }

    private fun clearCurrentSourceBinding() {
        currentSourceUri = null
        currentSourceLabel = null
        getSharedPreferences("pse_current_source", MODE_PRIVATE).edit().clear().apply()
    }

    private fun updateSourceBaseline(hash: String, game: String?, size: Long) {
        getSharedPreferences("pse_current_source", MODE_PRIVATE).edit()
            .putString("baseline_hash", hash)
            .putString("source_game", game)
            .putLong("source_size", size)
            .putLong("bound_at", System.currentTimeMillis())
            .apply()
    }

    private fun reconcileCurrentSourceBinding() {
        val source = currentSourceUri ?: return
        val working = importedFile ?: run { clearCurrentSourceBinding(); return }
        val workingAnalysis = runCatching { analyzeSave(working) }.getOrNull()
        if (workingAnalysis?.structurallyValid != true || workingAnalysis.trainer?.gameMatchesFamily != true) {
            clearCurrentSourceBinding()
            return
        }
        val workingGame = sourceGameIdentity(working, currentSourceLabel) ?: run { clearCurrentSourceBinding(); return }
        val prefs = getSharedPreferences("pse_current_source", MODE_PRIVATE)
        val storedGame = prefs.getString("source_game", null)
        if (!storedGame.isNullOrBlank() && storedGame != workingGame) {
            clearCurrentSourceBinding()
            return
        }
        if (prefs.getString("baseline_hash", null).isNullOrBlank()) {
            val snapshot = readSourceSnapshot(source) ?: run { clearCurrentSourceBinding(); return }
            val sourceGame = sourceGameIdentity(snapshot.first, currentSourceLabel)
            if (!snapshot.second.structurallyValid || snapshot.second.trainer?.gameMatchesFamily != true || sourceGame != workingGame) {
                snapshot.first.delete()
                clearCurrentSourceBinding()
                return
            }
            updateSourceBaseline(snapshot.second.sha256, sourceGame, snapshot.first.length())
            snapshot.first.delete()
        }
    }

    private fun readSourceSnapshot(uri: Uri): Pair<File, SaveAnalysis>? {
        return try {
            val temp = File(cacheDir, "pse_source_check_${System.currentTimeMillis()}.sav")
            contentResolver.openInputStream(uri).use { input ->
                val src = requireNotNull(input) { "Could not read current emulator source" }
                temp.outputStream().use { output -> src.copyTo(output) }
            }
            temp to analyzeSave(temp)
        } catch (_: Exception) {
            null
        }
    }

    private fun sourceIsWritable(uri: Uri): Boolean {
        return try {
            val descriptor = contentResolver.openFileDescriptor(uri, "rw") ?: return false
            descriptor.use { }
            true
        } catch (_: Exception) {
            false
        }
    }

    private fun validateCurrentSource(): SourceValidation {
        val source = currentSourceUri ?: return SourceValidation(
            false, false, false, false, false, false, null, null,
            "No emulator source is bound to the current working copy."
        )
        val working = importedFile ?: return SourceValidation(
            false, false, false, false, false, false, null, null,
            "No working save is loaded."
        )
        val workingAnalysis = runCatching { analyzeSave(working) }.getOrNull()
            ?: return SourceValidation(false, false, false, false, false, false, null, null, "The working save could not be analysed.")
        val snapshot = readSourceSnapshot(source)
            ?: return SourceValidation(false, false, sourceIsWritable(source), false, false, false, null, null, "PSE can no longer read the bound emulator save. Re-scan or import it again.")
        val sourceFile = snapshot.first
        val sourceAnalysis = snapshot.second
        val sourceGame = sourceGameIdentity(sourceFile, currentSourceLabel)
        val workingGame = sourceGameIdentity(working, currentSourceLabel)
        val gameMatches = sourceGame != null && sourceGame == workingGame && sourceAnalysis.trainer?.gameMatchesFamily == true
        val prefs = getSharedPreferences("pse_current_source", MODE_PRIVATE)
        val baselineHash = prefs.getString("baseline_hash", null)
        val changed = !baselineHash.isNullOrBlank() && baselineHash != sourceAnalysis.sha256
        val writable = sourceIsWritable(source)
        val structural = sourceAnalysis.structurallyValid
        val ok = structural && gameMatches && !changed && writable
        val message = when {
            !structural -> "The emulator source no longer passes PSE structural validation."
            !gameMatches -> "The bound emulator source is a different game from the loaded working copy."
            changed -> "The emulator save changed outside PSE after it was loaded. Re-import the source before overwriting it."
            !writable -> "PSE can read this source but no longer has write access to it."
            else -> "Source is unchanged, game-matched, readable and writable."
        }
        sourceFile.delete()
        return SourceValidation(ok, true, writable, structural, gameMatches, changed, sourceAnalysis.sha256, sourceGame, message)
    }

    private fun showSourceManager() {
        activeSwitchSave?.let {
            showDialog("Switch save source • Read-only", "${it.detectedGame}\n${it.relativePath}\n\nSHA-256: ${it.analysis.sha256}\n\nThe original document is reopened and validated for each read. Editing, export and replacement are locked.")
            return
        }
        phoneBackAction = { showHome() }
        val root = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(dp(18), dp(42), dp(18), dp(24))
            setBackgroundColor(BG)
        }
        val scroll = ScrollView(this).apply { setBackgroundColor(BG); addView(root) }
        root.addView(TextView(this).apply {
            text = "Current Source"
            textSize = 28f
            typeface = Typeface.DEFAULT_BOLD
            setTextColor(TEXT)
        })
        root.addView(TextView(this).apply {
            text = "PSE checks this emulator target before every Save & Replace."
            textSize = 14f
            setTextColor(MUTED)
            setPadding(0, dp(4), 0, dp(18))
        })

        val working = importedFile
        val workingAnalysis = working?.let { runCatching { analyzeSave(it) }.getOrNull() }
        val validation = if (working != null && currentSourceUri != null) validateCurrentSource() else null
        val prefs = getSharedPreferences("pse_current_source", MODE_PRIVATE)
        val baseline = prefs.getString("baseline_hash", null)
        val boundAt = prefs.getLong("bound_at", 0L)

        val card = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(dp(16), dp(14), dp(16), dp(14))
            background = roundedBg(CARD, Color.rgb(20, 95, 135), 14)
        }
        fun line(textValue: String, strong: Boolean = false, color: Int = TEXT) {
            card.addView(TextView(this).apply {
                text = textValue
                textSize = if (strong) 16f else 14f
                typeface = if (strong) Typeface.DEFAULT_BOLD else Typeface.DEFAULT
                setTextColor(color)
                setPadding(0, dp(3), 0, dp(3))
            })
        }
        val workingGame = working?.let { sourceGameIdentity(it, currentSourceLabel) }
            ?: workingAnalysis?.trainer?.exactGame ?: workingAnalysis?.family ?: "No save loaded"
        line(workingGame, true, ACCENT)
        line("Target: ${currentSourceLabel ?: "No source bound"}")
        if (currentSourceUri != null) {
            line("Read access: ${if (validation?.readable == true) "OK" else "FAILED"}", color = if (validation?.readable == true) GOOD else WARN)
            line("Write access: ${if (validation?.writable == true) "OK" else "FAILED"}", color = if (validation?.writable == true) GOOD else WARN)
            line("Game match: ${if (validation?.gameMatches == true) "PASS" else "FAIL"}", color = if (validation?.gameMatches == true) GOOD else WARN)
            line("External change check: ${if (validation?.changedExternally == true) "CHANGED" else "UNCHANGED"}", color = if (validation?.changedExternally == true) WARN else GOOD)
            baseline?.let { line("Baseline: ${it.take(16)}…") }
            validation?.sourceHash?.let { line("Current:  ${it.take(16)}…") }
            if (boundAt > 0L) line("Bound: ${SimpleDateFormat("dd MMM yyyy • HH:mm:ss", Locale.US).format(Date(boundAt))}")
            line(validation?.message ?: "Source could not be checked.", true, if (validation?.ok == true) GOOD else WARN)
        } else {
            line("No emulator source is currently bound.", true, WARN)
        }
        root.addView(card, LinearLayout.LayoutParams(-1, -2).apply { bottomMargin = dp(14) })

        addButton(root, "↻  Revalidate Source") { showSourceManager() }
        if (currentSourceUri != null) {
            addButton(root, "↓  Re-import Current Source") { confirmReimportCurrentSource() }
            addButton(root, "✕  Clear Source Binding") { confirmClearCurrentSourceBinding() }
        }
        addButton(root, "←  Back to Home") { showHome() }

        val shell = LinearLayout(this).apply { orientation = LinearLayout.VERTICAL; setBackgroundColor(BG) }
        shell.addView(scroll, LinearLayout.LayoutParams(-1, 0, 1f))
        shell.addView(buildBottomNav("home"), LinearLayout.LayoutParams(-1, -2))
        setContentView(shell)
    }

    private fun confirmClearCurrentSourceBinding() {
        val openedPath=importedFile?.absolutePath
        val openedSource=currentSourceUri
        val openedLabel=currentSourceLabel
        val prefs=getSharedPreferences("pse_current_source",MODE_PRIVATE)
        val openedHash=prefs.getString("baseline_hash",null)
        val openedAt=prefs.getLong("bound_at",0L)
        val openedGame=prefs.getString("source_game",null)
        val openedStoredUri=prefs.getString("uri",null)
        val openedStoredLabel=prefs.getString("label",null)
        val openedSize=prefs.getLong("source_size",0L)
        fun gen2Binding(game:String?,file:File?):Boolean =
            game in setOf("Pokémon Gold","Pokémon Silver","Pokémon Crystal","Pokémon Gold / Silver")||
                file?.let{runCatching{detectGen2ChecksumProfile(it.readBytes())!=null}.getOrDefault(false)}==true
        val openedGen2=gen2Binding(openedGame,importedFile)
        AlertDialog.Builder(this)
            .setTitle("Clear source binding?")
            .setMessage("This does not delete either save. PSE will simply stop allowing Save & Replace until you scan/import an emulator save again.")
            .setNegativeButton("Cancel",null)
            .setPositiveButton("Clear"){_,_->
                val currentGame=prefs.getString("source_game",null)
                if(openedGen2||gen2Binding(currentGame,importedFile)){
                    val sameBinding=openedGen2&&importedFile?.absolutePath==openedPath&&currentSourceUri==openedSource&&currentSourceLabel==openedLabel&&prefs.getString("baseline_hash",null)==openedHash&&prefs.getLong("bound_at",0L)==openedAt&&currentGame==openedGame&&prefs.getString("uri",null)==openedStoredUri&&prefs.getString("label",null)==openedStoredLabel&&prefs.getLong("source_size",0L)==openedSize
                    if(!sameBinding){showDialog("Clear binding blocked","The active Gen 2 save or source binding changed after confirmation. Reopen Current Source. Nothing was cleared.");return@setPositiveButton}
                }
                clearCurrentSourceBinding()
                showHome()
            }.show()
    }

    private fun confirmReimportCurrentSource() {
        val source = currentSourceUri ?: return
        val openedFile=importedFile
        val openedWorking=openedFile?.let{runCatching{it.readBytes()}.getOrNull()}
        val profile=openedWorking?.let{detectGen2ChecksumProfile(it)}
        if(profile!=null){
            val file=requireNotNull(openedFile);val working=requireNotNull(openedWorking);val label=currentSourceLabel
            val integrity=verifyGen2SaveIntegrity(working)
            if(!integrity.first){showDialog("Re-import blocked",integrity.second);return}
            val openedSource=runCatching{contentResolver.openInputStream(source).use{requireNotNull(it).readBytes()}}.getOrElse{showDialog("Re-import blocked","Could not read the emulator source. Nothing was changed.");return}
            if(!verifyGen2SaveIntegrity(openedSource).first||detectGen2Profile(openedSource)?.key!=profile.key){showDialog("Re-import blocked","The emulator source is not a valid matching Gen 2 save. Nothing was changed.");return}
            val game=sourceGameIdentity(file,label)?:run{showDialog("Re-import blocked","Could not establish the loaded Gen 2 title. Nothing was changed.");return}
            AlertDialog.Builder(this).setTitle("Re-import Gen 2 emulator source?")
                .setMessage("PSE will load this confirmed emulator snapshot into a new verified working copy. The emulator and previous working file will not be overwritten. Unsaved edits will also be kept in a separate safety backup.\n\nGame: "+game+"\nSource snapshot: "+sha256(openedSource).take(12))
                .setNegativeButton("Cancel",null)
                .setPositiveButton("Re-import"){_,_->reimportGen2CurrentSource(file,source,label,working,openedSource,profile.key,game)}
                .show()
            return
        }
        AlertDialog.Builder(this)
            .setTitle("Re-import emulator source?")
            .setMessage("This replaces PSE's current working copy with the emulator save as it exists right now. Any edits in the working copy that have not been written with Save & Replace will be discarded.")
            .setNegativeButton("Cancel", null)
            .setPositiveButton("Re-import") { _, _ ->
                if(importedFile?.let{runCatching{detectGen2ChecksumProfile(it.readBytes())!=null}.getOrDefault(false)}==true){
                    showDialog("Re-import blocked","This older confirmation is not bound to the active Gen 2 save. Reopen Current Source. Nothing was changed.")
                    return@setPositiveButton
                }
                reimportCurrentSource(source)
            }
            .show()
    }

    private fun reimportGen2CurrentSource(openedFile:File,source:Uri,openedLabel:String?,openedWorking:ByteArray,openedSource:ByteArray,profileKey:String,expectedGame:String) {
        fun bound()=importedFile?.absolutePath==openedFile.absolutePath&&currentSourceUri==source&&currentSourceLabel==openedLabel
        if(!bound()){showDialog("Re-import blocked","The active Gen 2 save or source identity changed. Reopen Current Source. Nothing was changed.");return}
        var safetyBackup:File?=null
        val destination:File
        try{
            require(openedFile.readBytes().contentEquals(openedWorking)){"The working copy changed after confirmation."}
            for(bytes in listOf(openedWorking,openedSource)){
                require(verifyGen2SaveIntegrity(bytes).first&&detectGen2Profile(bytes)?.key==profileKey){"A confirmed Gen 2 image failed integrity or profile validation."}
            }
            require(sourceGameIdentity(openedFile,openedLabel)==expectedGame){"The loaded Gen 2 game identity changed."}
            val fresh=contentResolver.openInputStream(source).use{requireNotNull(it){"Could not re-read the emulator source"}.readBytes()}
            require(fresh.contentEquals(openedSource)){"The emulator source changed after confirmation. Reopen Re-import to review it."}
            val backup=File.createTempFile(backupGameName(openedFile)+"_PreReimport_",".backup",backupsDir());safetyBackup=backup
            backup.writeBytes(openedWorking);require(backup.readBytes().contentEquals(openedWorking)){"The unsaved-edit safety backup did not persist exactly."}
            retainGen2SafetyBackup(backup,openedWorking)
            val importsDir=File(filesDir,"imports").apply{mkdirs()}
            destination=File.createTempFile(backupGameName(openedFile)+"_SourceRefresh_",".sav",importsDir)
            require(destination.absolutePath!=openedFile.absolutePath){"The new working copy must be separate from the previous save."}
            destination.writeBytes(openedSource)
            val persisted=destination.readBytes()
            require(persisted.contentEquals(openedSource)&&verifyGen2SaveIntegrity(persisted).first&&detectGen2Profile(persisted)?.key==profileKey){"The new Gen 2 working copy did not persist exactly with valid integrity."}
            require(sourceGameIdentity(destination,openedLabel)==expectedGame){"The new working copy did not preserve the expected Gen 2 title."}
            val finalSource=contentResolver.openInputStream(source).use{requireNotNull(it).readBytes()}
            require(finalSource.contentEquals(openedSource)&&bound()&&openedFile.readBytes().contentEquals(openedWorking)&&backup.readBytes().contentEquals(openedWorking)){"The emulator, working save, source identity or safety backup changed while re-import was staged."}
        }catch(e:Exception){
            showDialog("Re-import failed",(e.message?:"Could not safely stage the Gen 2 source")+"\n\nPSE did not write to the emulator or previous working file. No staged working copy was activated."+(safetyBackup?.let{"\n\nSafety backup kept: "+it.name}?:""));return
        }
        // Activate only the verified new copy; failures in baseline/UI must never rewrite the old save.
        activeSwitchSave = null
        importedFile=destination
        try{
            updateSourceBaseline(sha256(openedSource),expectedGame,openedSource.size.toLong())
            resetPokemonSelection()
        }catch(e:Exception){
            clearCurrentSourceBinding()
            showDialog("Re-import needs rebinding","The verified new Gen 2 working copy is active, but source setup did not complete. The source binding was cleared for safety. Re-import the emulator save before using Save & Replace. The previous working file and safety backup were kept.");return
        }
        Toast.makeText(this,"Gen 2 source re-imported and verified",Toast.LENGTH_LONG).show()
        showDialog("Re-import complete","The confirmed emulator snapshot was loaded into a separate verified working copy. The emulator and previous working file were not changed.\n\nUnsaved-edit safety backup kept: "+requireNotNull(safetyBackup).name)
        showHome()
    }

    private fun reimportCurrentSource(source: Uri) {
        try {
            val snapshot = readSourceSnapshot(source) ?: error("Could not read the emulator source")
            val temp = snapshot.first
            val analysis = snapshot.second
            if (!analysis.structurallyValid || analysis.trainer?.gameMatchesFamily != true) {
                temp.delete()
                error("The emulator source did not pass validation")
            }
            val importsDir = File(filesDir, "imports").apply { mkdirs() }
            val stamp = SimpleDateFormat("yyyyMMdd_HHmmss", Locale.US).format(Date())
            val destination = File(importsDir, "${stamp}_SourceRefresh_main")
            temp.copyTo(destination, overwrite = true)
            temp.delete()
            activeSwitchSave = null
            importedFile = destination
            resetPokemonSelection()
            updateSourceBaseline(analysis.sha256, sourceGameIdentity(destination, currentSourceLabel), destination.length())
            Toast.makeText(this, "Source re-imported and baseline refreshed", Toast.LENGTH_LONG).show()
            showHome()
        } catch (e: Exception) {
            showDialog("Re-import failed", e.message ?: "Could not re-import the current emulator source.")
        }
    }

    private fun confirmReplaceCurrentSave() {
        if (blockSwitchWrite()) return
        val file = importedFile
        if (file == null) {
            showDialog("Save & Replace Current Save", "No save is loaded yet. Import or scan an emulator save first.")
            return
        }
        val source = currentSourceUri
        if (source == null) {
            showDialog(
                "Save & Replace Current Save",
                "PSE does not know the original location for this loaded copy. Scan/import the emulator save again, or use Export Current Save."
            )
            return
        }
        val sourceValidation = validateCurrentSource()
        if (!sourceValidation.ok) {
            AlertDialog.Builder(this)
                .setTitle("Write blocked")
                .setMessage(sourceValidation.message + "\n\nOpen Current Source Manager to revalidate or re-import the emulator save.")
                .setNegativeButton("Cancel", null)
                .setPositiveButton("Source Manager") { _, _ -> showSourceManager() }
                .show()
            return
        }
        val analysis = analyzeSave(file)
        if (!analysis.structurallyValid || analysis.trainer?.gameMatchesFamily != true) {
            showDialog(
                "Write blocked",
                "The edited save did not pass PSE's structural validation, so the emulator file was not changed."
            )
            return
        }
        val openedEdited=runCatching{file.readBytes()}.getOrNull()?:return showDialog("Write blocked","The confirmed working copy could not be read. Nothing was written.")
        if(sha256(openedEdited)!=analysis.sha256)return showDialog("Write blocked","The working copy changed during confirmation validation. Nothing was written.")
        val gen2Replace=detectGen2Profile(openedEdited)!=null
        val openedLabel=currentSourceLabel
        AlertDialog.Builder(this)
            .setTitle("Replace emulator save?")
            .setMessage(
                "PSE will create exactly one safety backup of the emulator save as it exists right now, then write the currently edited save and verify it.\n\n" +
                "Target: ${currentSourceLabel ?: "current emulator save"}\n" +
                "Game: ${sourceGameIdentity(file, currentSourceLabel) ?: analysis.trainer?.exactGame ?: analysis.family}\n\n" +
                "Close the game/emulator before continuing so it cannot overwrite the file while PSE is writing."
            )
            .setNegativeButton("Cancel", null)
            .setPositiveButton("Backup & Replace") { _, _ ->
                if(gen2Replace){replaceGen2CurrentSave(file,source,openedLabel,requireNotNull(openedEdited),sourceValidation.sourceHash);return@setPositiveButton}
                replaceCurrentSave()
            }
            .show()
    }

    private fun replaceCurrentSave() {
        if (blockSwitchWrite()) return
        val edited = importedFile ?: return
        val source = currentSourceUri ?: return
        var rollbackBackup: File? = null
        try {
            val sourceValidation = validateCurrentSource()
            if (!sourceValidation.ok) error("Write blocked before backup: ${sourceValidation.message}")
            rollbackBackup = createPreWriteBackupFromUri(source)

            if (rollbackBackup.length() <= 0L) error("The pre-write backup is empty")
            val originalCheck = analyzeSave(rollbackBackup)
            if (!originalCheck.structurallyValid) {
                deleteBackupEverywhere(rollbackBackup)
                error("The emulator save backup could not be validated, so nothing was replaced")
            }

            contentResolver.openOutputStream(source, "wt").use { output ->
                val out = requireNotNull(output) { "The selected emulator location is not writable" }
                edited.inputStream().use { input -> input.copyTo(out) }
                out.flush()
            }

            val verifyFile = File(cacheDir, "pse_write_verify_${System.currentTimeMillis()}.sav")
            contentResolver.openInputStream(source).use { input ->
                val src = requireNotNull(input) { "Could not re-open the written emulator save" }
                verifyFile.outputStream().use { output -> src.copyTo(output) }
            }
            val expectedHash = sha256(edited.readBytes())
            val actualHash = sha256(verifyFile.readBytes())
            val verifyAnalysis = analyzeSave(verifyFile)
            val verifyGame = sourceGameIdentity(verifyFile, currentSourceLabel)
            verifyFile.delete()

            if (expectedHash != actualHash || !verifyAnalysis.structurallyValid) {
                try {
                    contentResolver.openOutputStream(source, "wt").use { output ->
                        val out = requireNotNull(output)
                        rollbackBackup.inputStream().use { input -> input.copyTo(out) }
                        out.flush()
                    }
                } catch (_: Exception) { }
                error("Verification failed after writing. PSE attempted to restore the pre-write backup.")
            }

            updateSourceBaseline(expectedHash, verifyGame, edited.length())
            pruneRollingBackups(backupGameName(), 10)
            val safeFolderNote = if (safeFolderUri() != null) {
                "\nSafe copy folder: configured"
            } else {
                "\nTip: tap PSE Safe Backups to choose an external folder for protected copies."
            }
            Toast.makeText(this, "Save replaced and verified successfully", Toast.LENGTH_LONG).show()
            showDialog(
                "Save replaced",
                "The edited save was written back successfully and verified byte-for-byte.\n\n" +
                "Backup created before replacement: ${rollbackBackup.name}$safeFolderNote\n\nYou can now reopen the emulator."
            )
            refreshSaveCard()
        } catch (e: Exception) {
            showDialog(
                "Could not replace save",
                "The emulator save was not safely replaced.\n\n${e.message ?: "Unknown error"}" +
                    (rollbackBackup?.let { "\n\nBackup kept: ${it.name}" } ?: "")
            )
        }
    }

    private fun replaceGen2CurrentSave(openedFile:File,openedSource:Uri,openedLabel:String?,openedEdited:ByteArray,openedSourceHash:String?){
        fun bound():Boolean=importedFile?.absolutePath==openedFile.absolutePath&&currentSourceUri==openedSource&&currentSourceLabel==openedLabel
        if(!bound()){showDialog("Write blocked","The active Gen 2 save or emulator source changed after confirmation. Reopen Save & Replace. Nothing was written.");return}
        var writeStarted=false;var safetyBackup:File?=null;var originalSource:ByteArray?=null;var expectedGame:String?=null
        try{
            val baseline=requireNotNull(openedSourceHash){"The confirmed emulator baseline is unavailable. Nothing was written."}
            require(openedFile.readBytes().contentEquals(openedEdited)){"The edited Gen 2 working copy changed after confirmation. Nothing was written."}
            val integrity=verifyGen2SaveIntegrity(openedEdited);require(integrity.first){integrity.second}
            val profile=detectGen2Profile(openedEdited)?:error("The confirmed working copy is not a valid Gen 2 save.")
            val validation=validateCurrentSource();require(validation.ok&&validation.sourceHash==baseline){"The emulator source changed or failed validation after confirmation. Nothing was written."}
            expectedGame=sourceGameIdentity(openedFile,openedLabel)
            require(expectedGame!=null&&expectedGame==validation.sourceGame){"The Gen 2 working copy and emulator title identity no longer match."}
            val original=contentResolver.openInputStream(openedSource).use{requireNotNull(it){"Could not read the confirmed emulator source."}.readBytes()}
            require(sha256(original)==baseline){"The emulator source changed before backup. Nothing was written."}
            val originalIntegrity=verifyGen2SaveIntegrity(original);require(originalIntegrity.first){originalIntegrity.second}
            require(detectGen2Profile(original)?.key==profile.key){"The emulator source and working copy have different Gen 2 profiles."}
            originalSource=original
            val backup=File.createTempFile(backupGameName(openedFile)+"_",".backup",backupsDir());safetyBackup=backup
            backup.writeBytes(original);require(backup.readBytes().contentEquals(original)){"The safety backup could not be verified. The emulator was not written."}
            retainGen2SafetyBackup(backup,original)
            mirrorBackupToSafeFolder(backup)
            require(bound()&&openedFile.readBytes().contentEquals(openedEdited)&&backup.readBytes().contentEquals(original)){"The active save, working copy or safety backup changed during staging. Nothing was written to the emulator."}
            val freshSource=contentResolver.openInputStream(openedSource).use{requireNotNull(it){"Could not re-read the emulator before writing."}.readBytes()}
            require(freshSource.contentEquals(original)){"The emulator source changed during staging. Nothing was written."}
            writeStarted=true
            contentResolver.openOutputStream(openedSource,"wt").use{output->val out=requireNotNull(output){"The confirmed emulator source is not writable."};out.write(openedEdited);out.flush()}
            val persisted=contentResolver.openInputStream(openedSource).use{requireNotNull(it){"Could not reopen the written emulator save."}.readBytes()}
            require(persisted.contentEquals(openedEdited)){"The Gen 2 emulator write did not persist byte-for-byte."}
            val persistedIntegrity=verifyGen2SaveIntegrity(persisted);require(persistedIntegrity.first){persistedIntegrity.second}
            require(detectGen2Profile(persisted)?.key==profile.key){"The persisted Gen 2 game profile changed."}
            require(bound()&&openedFile.readBytes().contentEquals(openedEdited)){"The active Gen 2 save or working copy changed during persistence."}
        }catch(e:Exception){
            val original=originalSource
            val restored=writeStarted&&original!=null&&runCatching{
                contentResolver.openOutputStream(openedSource,"wt").use{output->val out=requireNotNull(output);out.write(original);out.flush()}
                val recovered=contentResolver.openInputStream(openedSource).use{requireNotNull(it).readBytes()}
                require(recovered.contentEquals(original)){"The emulator rollback did not persist byte-for-byte."}
                require(verifyGen2SaveIntegrity(recovered).first){"The emulator rollback failed Gen 2 integrity validation."}
            }.isSuccess
            val recovery=if(!writeStarted)"Nothing was written to the emulator source." else  if(restored)"The exact pre-write emulator save was restored and verified." else  "PSE could not verify emulator rollback. Keep the safety backup, stop the emulator and do not use the target until it has been recovered from a verified backup."
            showDialog("Could not replace Gen 2 save",(e.message?:"Unknown error")+"\n\n"+recovery+(safetyBackup?.let{"\n\nSafety backup kept: "+it.name}?:""));return
        }
        updateSourceBaseline(sha256(openedEdited),expectedGame,openedEdited.size.toLong())
        Toast.makeText(this,"Gen 2 save replaced and verified",Toast.LENGTH_LONG).show()
        showDialog("Save replaced","The Gen 2 emulator save was written and reopened byte-for-byte with integrity verified.\n\nSafety backup kept: "+requireNotNull(safetyBackup).name)
        refreshSaveCard()
    }

    private fun exportCurrentSave() {
        if (blockSwitchWrite()) return
        if(pendingGen2SaveExport!=null){showDialog("Export pending","Finish or cancel the current Gen 2 export before starting another.");return}
        val file = importedFile
        if (file == null) {
            showDialog("Export Current Save", "No save is loaded yet. Import a save first.")
            return
        }
        val opened=runCatching{file.readBytes()}.getOrElse{showDialog("Export blocked","The working copy could not be read. Nothing was written.");return}
        val profile=detectGen2ChecksumProfile(opened)
        if(profile!=null){
            val integrity=verifyGen2SaveIntegrity(opened)
            if(!integrity.first){showDialog("Export blocked",integrity.second);return}
            val pending=PendingGen2SaveExport(file,currentSourceUri,currentSourceLabel,opened.copyOf(),profile.key)
            pendingGen2SaveExport=pending
            val gen2Intent=Intent(Intent.ACTION_CREATE_DOCUMENT).apply{
                addCategory(Intent.CATEGORY_OPENABLE);type="application/octet-stream"
                putExtra(Intent.EXTRA_TITLE,backupGameName(file)+"_Export.sav")
            }
            try{startActivityForResult(gen2Intent,EXPORT_GEN2_SAVE)}
            catch(e:Exception){pendingGen2SaveExport=null;showDialog("Export failed",e.message?:"Could not open the export picker. Nothing was written.")}
            return
        }
        val intent = Intent(Intent.ACTION_CREATE_DOCUMENT).apply {
            addCategory(Intent.CATEGORY_OPENABLE)
            type = "application/octet-stream"
            putExtra(Intent.EXTRA_TITLE, "main")
        }
        startActivityForResult(intent, EXPORT_SAVE)
    }

    private fun finishGen2SaveExport(pending:PendingGen2SaveExport,destination:Uri) {
        fun bound()=importedFile?.absolutePath==pending.file.absolutePath&&currentSourceUri==pending.sourceUri&&currentSourceLabel==pending.sourceLabel
        if(!bound()){showDialog("Export blocked","The active Gen 2 save or source identity changed while the picker was open. Nothing was written.");return}
        var writeStarted=false
        try{
            require(destination!=pending.sourceUri){"Export must create a separate copy, not replace the emulator source."}
            require(pending.file.readBytes().contentEquals(pending.bytes)){"The selected Gen 2 working copy changed while the picker was open."}
            require(verifyGen2SaveIntegrity(pending.bytes).first&&detectGen2Profile(pending.bytes)?.key==pending.profileKey){"The captured Gen 2 save failed integrity validation."}
            val empty=contentResolver.openInputStream(destination).use{requireNotNull(it){"PSE could not verify that the export destination is empty"}.read()==-1}
            require(empty){"The export destination already contains data. Choose a new file; existing files will not be overwritten."}
            require(bound()&&pending.file.readBytes().contentEquals(pending.bytes)){"The active Gen 2 save changed during destination validation."}
            writeStarted=true
            contentResolver.openOutputStream(destination,"wt").use{output->val out=requireNotNull(output){"Could not open the new export destination"};out.write(pending.bytes);out.flush()}
            val persisted=contentResolver.openInputStream(destination).use{requireNotNull(it){"Could not reopen the exported save"}.readBytes()}
            require(persisted.contentEquals(pending.bytes)&&verifyGen2SaveIntegrity(persisted).first&&detectGen2Profile(persisted)?.key==pending.profileKey){"The exported Gen 2 save did not persist exactly with valid integrity."}
            require(bound()&&pending.file.readBytes().contentEquals(pending.bytes)){"The active Gen 2 save changed while export was being verified."}
        }catch(e:Exception){
            val result=if(!writeStarted)"Nothing was written." else  "The new export may be incomplete or unverified. Do not use it; choose a new file for another export."
            showDialog("Export failed",(e.message?:"Could not verify the exported Gen 2 save")+"\n\n"+result+"\n\nPSE did not write to the working copy or emulator source.");return
        }
        Toast.makeText(this,"Gen 2 save exported and verified",Toast.LENGTH_LONG).show()
        showDialog("Export complete","A separate Gen 2 save copy was written and reopened byte-for-byte with integrity verified. The working copy and emulator source were not changed.")
    }

    private fun queryDisplayName(uri: Uri): String? {
        val projection = arrayOf("_display_name")
        contentResolver.query(uri, projection, null, null, null)?.use { cursor ->
            if (cursor.moveToFirst()) return cursor.getString(0)
        }
        return uri.lastPathSegment
    }

    private fun backupsDir(): File = File(filesDir, "backups").apply { mkdirs() }

    private fun sourceKey(label: String? = currentSourceLabel, uri: Uri? = currentSourceUri): String {
        val seed = (uri?.toString() ?: "") + "|" + (label ?: "unsourced")
        return sha256(seed.toByteArray()).take(10).ifBlank { "unsourced" }
    }

    private fun backupGameName(file: File? = importedFile): String {
        val raw = file?.let { candidate ->
            runCatching {
                val bytes=candidate.readBytes();val profile=detectGen2Profile(bytes)
                if(profile!=null)detectGen2GameFromPath(if(candidate==importedFile)(currentSourceLabel?:candidate.name)else candidate.name,profile)
                else analyzeSave(candidate).trainer?.exactGame ?: analyzeSave(candidate).family
            }.getOrNull()
        } ?: "Pokemon"
        return raw.replace("Pokémon", "Pokemon")
            .replace(Regex("[^A-Za-z0-9]+"), "")
            .ifBlank { "Pokemon" }
    }

    private fun gen2VersionHint(label:String?):String? {
        val value=label?.lowercase(Locale.US)?:return null
        if("crystal" in value)return "Crystal"
        val gold="gold" in value;val silver="silver" in value
        return when{gold&&!silver->"Gold";silver&&!gold->"Silver";else->null}
    }

    private fun verifyGen2BackupRestoreIdentity(backup:File,current:File,backupLabel:String):Pair<Boolean,String> {
        val backupData=runCatching{backup.readBytes()}.getOrNull()?:return false to "PSE could not read the selected backup."
        val currentData=runCatching{current.readBytes()}.getOrNull()?:return false to "PSE could not read the current Gen 2 save."
        val backupProfile=detectGen2Profile(backupData);val currentProfile=detectGen2Profile(currentData)
        if(backupProfile==null&&currentProfile==null)return true to "No Gen 2 identity check was required."
        if(backupProfile==null||currentProfile==null)return false to "The backup and current save are not from the same generation. Nothing was changed."
        if(backupProfile.key!=currentProfile.key)return false to "The backup and current save are different Gen 2 game families. Nothing was changed."
        if(currentProfile.key=="C")return true to "Pokémon Crystal identity verified."
        val currentVersion=gen2VersionHint(currentSourceLabel)?:gen2VersionHint(current.name)
        val backupVersion=gen2VersionHint(backupLabel)
        if(currentVersion==null||backupVersion==null)return false to "PSE could not prove whether this Gold / Silver backup matches the loaded game. Re-import the exact game save and use a newly created version-labelled backup. Nothing was changed."
        if(currentVersion!=backupVersion)return false to "This is a Pokémon $backupVersion backup, but the loaded target is Pokémon $currentVersion. Nothing was changed."
        return true to "Pokémon $currentVersion identity verified."
    }

    private fun backupStamp(): String =
        SimpleDateFormat("yyyy-MM-dd_HH-mm-ss", Locale.US).format(Date())

    private fun backupIsProtected(file: File): Boolean =
        file.name.startsWith("ORIGINAL_") || file.name.contains("_ORIGINAL_")

    private fun keptBackupNames(): MutableSet<String> {
        val raw = getSharedPreferences("pse_backup_state", MODE_PRIVATE).getStringSet("kept", emptySet()) ?: emptySet()
        return raw.toMutableSet()
    }

    private fun setBackupKept(file: File, keep: Boolean) {
        if (backupIsProtected(file)) return
        val names = keptBackupNames()
        if (keep) names.add(file.name) else names.remove(file.name)
        getSharedPreferences("pse_backup_state", MODE_PRIVATE).edit().putStringSet("kept", names).apply()
    }

    private fun retainGen2SafetyBackup(file:File,expected:ByteArray) {
        require(file.isFile&&file.readBytes().contentEquals(expected)&&verifyGen2SaveIntegrity(expected).first){"The Gen 2 recovery backup could not be verified before retention."}
        val names=keptBackupNames().apply{add(file.name)}
        val prefs=getSharedPreferences("pse_backup_state",MODE_PRIVATE)
        require(prefs.edit().putStringSet("kept",names).commit()){"The recovery backup Keep pin could not be saved. No save write or activation is allowed."}
        require(prefs.getStringSet("kept",emptySet())?.contains(file.name)==true&&file.readBytes().contentEquals(expected)){"The retained Gen 2 backup or its Keep pin could not be rechecked."}
    }

    private fun isBackupKept(file: File): Boolean = backupIsProtected(file) || keptBackupNames().contains(file.name)

    private fun safeFolderUri(): Uri? =
        getSharedPreferences("pse_safe_files", MODE_PRIVATE).getString("tree_uri", null)
            ?.let { runCatching { Uri.parse(it) }.getOrNull() }

    private fun pickSafeFolder() {
        val intent = Intent(Intent.ACTION_OPEN_DOCUMENT_TREE).apply {
            addFlags(
                Intent.FLAG_GRANT_READ_URI_PERMISSION or
                    Intent.FLAG_GRANT_WRITE_URI_PERMISSION or
                    Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION or
                    Intent.FLAG_GRANT_PREFIX_URI_PERMISSION
            )
            safeFolderUri()?.let { putExtra(DocumentsContract.EXTRA_INITIAL_URI, it) }
        }
        startActivityForResult(intent, PICK_SAFE_FOLDER)
    }

    private fun safeBackupGameKey(name: String): String {
        val clean = name.removeSuffix(".backup")
        val cleanMatch = Regex("^(Pokemon[A-Za-z0-9]+)_\\d{4}-\\d{2}-\\d{2}_\\d{2}-\\d{2}-\\d{2}$").find(clean)
        if (cleanMatch != null) return cleanMatch.groupValues[1]
        val legacy = gameNameFromBackupName(name)
        return legacy ?: clean.substringBefore('_').ifBlank { "Pokemon" }
    }

    private fun displayBackupGameName(key: String): String = when (key) {
        "PokemonX" -> "Pokémon X"
        "PokemonY" -> "Pokémon Y"
        "PokemonOmegaRuby" -> "Pokémon Omega Ruby"
        "PokemonAlphaSapphire" -> "Pokémon Alpha Sapphire"
        "PokemonSun" -> "Pokémon Sun"
        "PokemonMoon" -> "Pokémon Moon"
        "PokemonUltraSun" -> "Pokémon Ultra Sun"
        "PokemonUltraMoon" -> "Pokémon Ultra Moon"
        else -> key.replace("Pokemon", "Pokémon ").replace(Regex("(?<=[a-z])(?=[A-Z])"), " ").trim()
    }

    private fun showSafeBackups() {
        phoneBackAction = { showHome() }
        val scroll = ScrollView(this).apply { setBackgroundColor(BG) }
        val rootLayout = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(dp(16), dp(42), dp(16), dp(24))
            setBackgroundColor(BG)
        }
        scroll.addView(rootLayout)

        val topRow = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.CENTER_VERTICAL
        }
        val back = Button(this).apply {
            text = "← Home"
            setOnClickListener { showHome() }
        }
        topRow.addView(back, LinearLayout.LayoutParams(-2, -2))
        topRow.addView(TextView(this).apply {
            text = "PSE Safe Backups"
            textSize = 25f
            typeface = Typeface.DEFAULT_BOLD
            setTextColor(TEXT)
            setPadding(dp(14), 0, 0, 0)
        }, LinearLayout.LayoutParams(0, -2, 1f))
        rootLayout.addView(topRow)

        rootLayout.addView(TextView(this).apply {
            text = "These are the safety copies PSE created immediately before Save & Replace. Opening this screen never creates a backup."
            textSize = 14f
            setTextColor(MUTED)
            setPadding(0, dp(10), 0, dp(16))
        })

        val uri = safeFolderUri()
        if (uri == null) {
            rootLayout.addView(TextView(this).apply {
                text = "No backup folder is configured yet."
                textSize = 17f
                setTextColor(TEXT)
                setPadding(0, dp(12), 0, dp(12))
            })
            addButton(rootLayout, "📁  Choose Backup Folder") { pickSafeFolder() }
            setContentView(scroll)
            return
        }

        val folder = try { DocumentFile.fromTreeUri(this, uri) } catch (_: Exception) { null }
        if (folder == null || !folder.exists() || !folder.isDirectory) {
            rootLayout.addView(TextView(this).apply {
                text = "PSE can no longer access the selected backup folder."
                textSize = 17f
                setTextColor(TEXT)
                setPadding(0, dp(12), 0, dp(12))
            })
            addButton(rootLayout, "📁  Choose Backup Folder Again") { pickSafeFolder() }
            setContentView(scroll)
            return
        }

        val files = try {
            folder.listFiles().filter { it.isFile && (it.name?.endsWith(".backup", true) == true) }
                .sortedByDescending { it.lastModified() }
        } catch (_: Exception) { emptyList() }

        rootLayout.addView(TextView(this).apply {
            text = "${files.size} backup${if (files.size == 1) "" else "s"}"
            textSize = 15f
            typeface = Typeface.DEFAULT_BOLD
            setTextColor(ACCENT)
            setPadding(0, 0, 0, dp(8))
        })

        if (files.isEmpty()) {
            rootLayout.addView(TextView(this).apply {
                text = "No safety backups yet. A backup is created only when Save & Replace Current Save is used."
                textSize = 16f
                setTextColor(MUTED)
                setPadding(0, dp(10), 0, dp(18))
            })
        } else {
            val grouped = files.groupBy { safeBackupGameKey(it.name ?: "Pokemon") }
                .entries.sortedByDescending { entry -> entry.value.maxOfOrNull { it.lastModified() } ?: 0L }
            grouped.forEach { (gameKey, gameFiles) ->
                rootLayout.addView(TextView(this).apply {
                    text = displayBackupGameName(gameKey)
                    textSize = 20f
                    typeface = Typeface.DEFAULT_BOLD
                    setTextColor(ACCENT)
                    setPadding(0, dp(14), 0, dp(8))
                })

                gameFiles.sortedByDescending { it.lastModified() }.forEach { doc ->
                    val name = doc.name ?: "Backup"
                    val protected = name.startsWith("ORIGINAL_")
                    val card = LinearLayout(this).apply {
                        orientation = LinearLayout.VERTICAL
                        setPadding(dp(16), dp(14), dp(16), dp(14))
                        background = roundedBg(CARD, Color.rgb(25, 55, 72), 14)
                    }

                    card.addView(TextView(this).apply {
                        text = if (protected) "⭐ Protected backup" else "💾 Safety backup"
                        textSize = 14f
                        typeface = Typeface.DEFAULT_BOLD
                        setTextColor(if (protected) ACCENT else TEXT)
                    })
                    card.addView(TextView(this).apply {
                        val whenText = if (doc.lastModified() > 0L) {
                            SimpleDateFormat("dd MMM yyyy • HH:mm:ss", Locale.getDefault()).format(Date(doc.lastModified()))
                        } else "Date unknown"
                        text = whenText
                        textSize = 17f
                        typeface = Typeface.DEFAULT_BOLD
                        setTextColor(TEXT)
                        setPadding(0, dp(5), 0, dp(3))
                    })
                    card.addView(TextView(this).apply {
                        text = formatBytes(doc.length())
                        textSize = 14f
                        setTextColor(MUTED)
                        setPadding(0, 0, 0, dp(10))
                    })

                    val restore = Button(this).apply {
                        text = "↩️  Restore This Save"
                        setOnClickListener { restoreSafeBackupToEmulator(doc) }
                    }
                    card.addView(restore, LinearLayout.LayoutParams(-1, -2))

                    if (!protected) {
                        val delete = Button(this).apply {
                            text = "🗑️  Delete Backup"
                            setOnClickListener { confirmDeleteSafeBackup(doc) }
                        }
                        card.addView(delete, LinearLayout.LayoutParams(-1, -2).apply { topMargin = dp(6) })
                    }

                    rootLayout.addView(card, LinearLayout.LayoutParams(-1, -2).apply { bottomMargin = dp(10) })
                }
            }
        }

        addButton(rootLayout, "📁  Change Backup Folder") { pickSafeFolder() }
        addButton(rootLayout, "←  Back to Home") { showHome() }
        val shell = LinearLayout(this).apply { orientation = LinearLayout.VERTICAL; setBackgroundColor(BG) }
        shell.addView(scroll, LinearLayout.LayoutParams(-1, 0, 1f))
        shell.addView(buildBottomNav("backups"), LinearLayout.LayoutParams(-1, -2))
        setContentView(shell)
    }

    private fun restoreSafeBackupToEmulator(doc: DocumentFile) {
        val source = currentSourceUri
        if (source == null) {
            showDialog(
                "Restore backup",
                "PSE does not currently know which emulator save should be restored. Scan or import the emulator save first, then return to PSE Safe Backups."
            )
            return
        }

        val openedFile = importedFile
        val openedLabel = currentSourceLabel
        val backupUri = doc.uri
        val backupName = doc.name ?: "Backup"
        val backupTemp = File(cacheDir, "pse_restore_backup_${System.currentTimeMillis()}.sav")
        val rollbackTemp = File(cacheDir, "pse_restore_rollback_${System.currentTimeMillis()}.sav")
        try {
            contentResolver.openInputStream(doc.uri).use { input ->
                val src = requireNotNull(input) { "Could not read this backup" }
                backupTemp.outputStream().use { output -> src.copyTo(output) }
            }
            val backupCheck = analyzeSave(backupTemp)
            if (!backupCheck.structurallyValid) error("This backup did not pass PSE structural validation")

            contentResolver.openInputStream(source).use { input ->
                val src = requireNotNull(input) { "Could not read the current emulator save" }
                rollbackTemp.outputStream().use { output -> src.copyTo(output) }
            }
            val currentCheck = analyzeSave(rollbackTemp)
            if (!currentCheck.structurallyValid) error("The current emulator save could not be validated")

            val gen2Identity=verifyGen2BackupRestoreIdentity(backupTemp,rollbackTemp,doc.name?:"Backup")
            if(!gen2Identity.first)error(gen2Identity.second)

            val backupGame = sourceGameIdentity(backupTemp, doc.name) ?: backupCheck.trainer?.exactGame ?: backupCheck.family
            val currentGame = sourceGameIdentity(rollbackTemp, currentSourceLabel) ?: currentCheck.trainer?.exactGame ?: currentCheck.family
            if (backupGame != currentGame) {
                error("Backup is $backupGame but the current emulator target is $currentGame")
            }

            val openedBackup=backupTemp.readBytes()
            val openedSource=rollbackTemp.readBytes()
            val gen2Restore=detectGen2Profile(openedSource)!=null
            val openedWorking=if(gen2Restore)requireNotNull(openedFile){"Re-import the Gen 2 emulator save before restoring."}.readBytes()else null
            if(gen2Restore)require(verifyGen2SaveIntegrity(requireNotNull(openedWorking)).first){"The loaded Gen 2 working copy failed integrity validation."}

            AlertDialog.Builder(this)
                .setTitle("Restore this save?")
                .setMessage(
                    "PSE will restore this backup directly to the current emulator save and verify it byte-for-byte.\n\n" +
                    "Backup: ${doc.name ?: "Backup"}\n" +
                    "Game: $backupGame\n" +
                    "Target: ${currentSourceLabel ?: "current emulator save"}\n\n" +
                    "Close the game/emulator before restoring."
                )
                .setNegativeButton("Cancel") { _, _ ->
                    backupTemp.delete()
                    rollbackTemp.delete()
                }
                .setPositiveButton("Restore Save") { _, _ ->
                    if(gen2Restore){
                        restoreGen2SafeBackup(requireNotNull(openedFile),source,openedLabel,backupUri,backupName,backupTemp,rollbackTemp,openedBackup,openedSource,requireNotNull(openedWorking))
                        return@setPositiveButton
                    }
                    performDirectBackupRestore(source, doc.name ?: "Backup", backupTemp, rollbackTemp)
                }
                .show()
        } catch (e: Exception) {
            backupTemp.delete()
            rollbackTemp.delete()
            showDialog("Restore blocked", e.message ?: "Could not validate this backup")
        }
    }

    private fun restoreGen2SafeBackup(openedFile:File,source:Uri,openedLabel:String?,backupUri:Uri,backupName:String,backupTemp:File,rollbackTemp:File,openedBackup:ByteArray,openedSource:ByteArray,openedWorking:ByteArray) {
        fun bound()=importedFile?.absolutePath==openedFile.absolutePath&&currentSourceUri==source&&currentSourceLabel==openedLabel
        if(!bound()){showDialog("Restore blocked","The active Gen 2 save or source identity changed. Reopen Safe Backups. Nothing was written.");return}
        var sourceWriteStarted=false;var workingWriteStarted=false
        var sourceSafety:File?=null;var workingSafety:File?=null
        var restoredGame:String?=null
        try{
            require(backupUri!=source){"The backup must be separate from the emulator target."}
            require(backupTemp.readBytes().contentEquals(openedBackup)&&rollbackTemp.readBytes().contentEquals(openedSource)&&openedFile.readBytes().contentEquals(openedWorking)){"The confirmed backup, rollback image or working copy changed."}
            val profile=requireNotNull(detectGen2Profile(openedSource)){"The emulator snapshot is not a supported Gen 2 save."}
            for(bytes in listOf(openedBackup,openedSource,openedWorking)){
                require(verifyGen2SaveIntegrity(bytes).first&&detectGen2Profile(bytes)?.key==profile.key){"A Gen 2 restore image failed integrity or game-family validation."}
            }
            val identity=verifyGen2BackupRestoreIdentity(backupTemp,rollbackTemp,backupName)
            require(identity.first){identity.second}
            restoredGame=sourceGameIdentity(backupTemp,backupName)
            require(restoredGame!=null&&restoredGame==sourceGameIdentity(rollbackTemp,openedLabel)&&restoredGame==sourceGameIdentity(openedFile,openedLabel)){"The backup, emulator snapshot and working save are not the same Gen 2 title."}
            val selected=contentResolver.openInputStream(backupUri).use{requireNotNull(it){"Could not re-read the selected backup"}.readBytes()}
            require(selected.contentEquals(openedBackup)){"The selected external backup changed after confirmation."}
            val sourceBackup=File.createTempFile(backupGameName(openedFile)+"_PreRestoreEmulator_",".backup",backupsDir());sourceSafety=sourceBackup
            sourceBackup.writeBytes(openedSource);require(sourceBackup.readBytes().contentEquals(openedSource)){"The emulator safety backup did not persist exactly."}
            retainGen2SafetyBackup(sourceBackup,openedSource)
            val workingBackup=File.createTempFile(backupGameName(openedFile)+"_PreRestoreWorking_",".backup",backupsDir());workingSafety=workingBackup
            workingBackup.writeBytes(openedWorking);require(workingBackup.readBytes().contentEquals(openedWorking)){"The working-copy safety backup did not persist exactly."}
            retainGen2SafetyBackup(workingBackup,openedWorking)
            require(bound()&&openedFile.readBytes().contentEquals(openedWorking)&&backupTemp.readBytes().contentEquals(openedBackup)&&rollbackTemp.readBytes().contentEquals(openedSource)&&sourceBackup.readBytes().contentEquals(openedSource)&&workingBackup.readBytes().contentEquals(openedWorking)){"The confirmed restore state changed during staging."}
            val freshSource=contentResolver.openInputStream(source).use{requireNotNull(it){"Could not re-read the emulator target"}.readBytes()}
            require(freshSource.contentEquals(openedSource)){"The emulator save changed after confirmation. Nothing was written."}
            val freshBackup=contentResolver.openInputStream(backupUri).use{requireNotNull(it).readBytes()}
            require(freshBackup.contentEquals(openedBackup)&&bound()&&openedFile.readBytes().contentEquals(openedWorking)){"The selected backup or active Gen 2 save changed before writing."}
            sourceWriteStarted=true
            contentResolver.openOutputStream(source,"wt").use{output->val out=requireNotNull(output){"The emulator location is not writable"};out.write(openedBackup);out.flush()}
            val persistedSource=contentResolver.openInputStream(source).use{requireNotNull(it){"Could not re-open the restored emulator save"}.readBytes()}
            require(persistedSource.contentEquals(openedBackup)&&verifyGen2SaveIntegrity(persistedSource).first&&detectGen2Profile(persistedSource)?.key==profile.key){"The restored emulator save did not persist exactly with valid integrity."}
            require(bound()&&openedFile.readBytes().contentEquals(openedWorking)){"The active Gen 2 save or working copy changed while the emulator was restored."}
            workingWriteStarted=true
            openedFile.writeBytes(openedBackup)
            val persistedWorking=openedFile.readBytes()
            require(persistedWorking.contentEquals(openedBackup)&&verifyGen2SaveIntegrity(persistedWorking).first&&detectGen2Profile(persistedWorking)?.key==profile.key&&bound()){"The restored Gen 2 working copy did not persist exactly."}
            val finalSource=contentResolver.openInputStream(source).use{requireNotNull(it).readBytes()}
            require(finalSource.contentEquals(openedBackup)&&verifyGen2SaveIntegrity(finalSource).first&&bound()){"The emulator save changed while the working copy was restored."}
        }catch(e:Exception){
            val workingRecovered=!workingWriteStarted||runCatching{
                openedFile.writeBytes(openedWorking)
                val recovered=openedFile.readBytes()
                require(recovered.contentEquals(openedWorking)&&verifyGen2SaveIntegrity(recovered).first)
            }.isSuccess
            // Recover each captured target independently; working recovery failure must not skip emulator recovery.
            val sourceRecovered=!sourceWriteStarted||runCatching{
                contentResolver.openOutputStream(source,"wt").use{output->val out=requireNotNull(output);out.write(openedSource);out.flush()}
                val recovered=contentResolver.openInputStream(source).use{requireNotNull(it).readBytes()}
                require(recovered.contentEquals(openedSource)&&verifyGen2SaveIntegrity(recovered).first)
            }.isSuccess
            val recovery=if(!sourceWriteStarted&&!workingWriteStarted)"Nothing was written to the emulator or working save." else  if(sourceRecovered&&workingRecovered)"The exact previous emulator and working-save bytes were restored and verified." else  "PSE could not verify complete rollback. Keep the safety backups, stop the emulator and do not use either target until recovered."
            showDialog("Restore failed",(e.message?:"Could not safely restore the Gen 2 backup")+"\n\n"+recovery+"\n\nSafety backups kept: "+listOfNotNull(sourceSafety?.name,workingSafety?.name).joinToString(", "));return
        }
        updateSourceBaseline(sha256(openedBackup),restoredGame,openedBackup.size.toLong())
        backupTemp.delete();rollbackTemp.delete()
        Toast.makeText(this,"Gen 2 backup restored and verified",Toast.LENGTH_LONG).show()
        showDialog("Save restored",backupName+" was restored to the captured Gen 2 emulator save and working copy, then reopened byte-for-byte with integrity verified. Both pre-restore safety backups were kept.")
        refreshSaveCard()
    }

    private fun performDirectBackupRestore(source: Uri, backupName: String, backupTemp: File, rollbackTemp: File) {
        try {
            contentResolver.openOutputStream(source, "wt").use { output ->
                val out = requireNotNull(output) { "The emulator save location is not writable" }
                backupTemp.inputStream().use { input -> input.copyTo(out) }
                out.flush()
            }

            val verifyFile = File(cacheDir, "pse_restore_verify_${System.currentTimeMillis()}.sav")
            contentResolver.openInputStream(source).use { input ->
                val src = requireNotNull(input) { "Could not re-open the restored emulator save" }
                verifyFile.outputStream().use { output -> src.copyTo(output) }
            }
            val expectedHash = sha256(backupTemp.readBytes())
            val actualHash = sha256(verifyFile.readBytes())
            val verifyCheck = analyzeSave(verifyFile)
            verifyFile.delete()

            if (expectedHash != actualHash || !verifyCheck.structurallyValid) {
                try {
                    contentResolver.openOutputStream(source, "wt").use { output ->
                        val out = requireNotNull(output)
                        rollbackTemp.inputStream().use { input -> input.copyTo(out) }
                        out.flush()
                    }
                } catch (_: Exception) { }
                error("Restore verification failed. PSE attempted to put the previous emulator save back.")
            }

            importedFile?.let { backupTemp.copyTo(it, overwrite = true) }
            updateSourceBaseline(expectedHash, sourceGameIdentity(backupTemp, currentSourceLabel), backupTemp.length())
            backupTemp.delete()
            rollbackTemp.delete()
            Toast.makeText(this, "Backup restored and verified", Toast.LENGTH_LONG).show()
            AlertDialog.Builder(this)
                .setTitle("Save restored")
                .setMessage("$backupName was restored directly to the emulator save and verified byte-for-byte.\n\nYou can now reopen the emulator.")
                .setPositiveButton("OK", null)
                .show()
        } catch (e: Exception) {
            backupTemp.delete()
            rollbackTemp.delete()
            showDialog("Restore failed", e.message ?: "The backup could not be safely restored")
        }
    }

    private fun confirmDeleteSafeBackup(doc: DocumentFile) {
        val opened=runCatching{contentResolver.openInputStream(doc.uri).use{requireNotNull(it).readBytes()}}.getOrNull()
        val knownGame=getSharedPreferences("pse_current_source",MODE_PRIVATE).getString("source_game",null)
        val gen2Delete=opened?.let{detectGen2ChecksumProfile(it)!=null}==true||
            knownGame in setOf("Pokémon Gold","Pokémon Silver","Pokémon Crystal","Pokémon Gold / Silver")||
            importedFile?.let{runCatching{detectGen2ChecksumProfile(it.readBytes())!=null}.getOrDefault(false)}==true
        if(gen2Delete){
            if(opened==null){showDialog("Delete blocked","PSE could not snapshot the selected Gen 2 backup. Nothing was deleted.");return}
            confirmGen2SafeBackupDelete(doc,opened)
            return
        }
        val name = doc.name ?: "this backup"
        AlertDialog.Builder(this)
            .setTitle("Delete backup?")
            .setMessage("Delete $name from PSE Safe Backups?")
            .setNegativeButton("Cancel", null)
            .setPositiveButton("Delete") { _, _ ->
                if (doc.delete()) Toast.makeText(this, "Backup deleted", Toast.LENGTH_SHORT).show()
                else Toast.makeText(this, "Could not delete backup", Toast.LENGTH_LONG).show()
                showSafeBackups()
            }
            .show()
    }

    private fun confirmGen2SafeBackupDelete(doc:DocumentFile,opened:ByteArray) {
        val openedUri=doc.uri;val openedName=doc.name
        val openedPath=importedFile?.absolutePath;val openedSource=currentSourceUri;val openedLabel=currentSourceLabel
        val openedFolder=safeFolderUri()
        fun protectedName(name:String?)=name?.let{it.startsWith("ORIGINAL_")||it.contains("_ORIGINAL_")}?:true
        fun bound()=importedFile?.absolutePath==openedPath&&currentSourceUri==openedSource&&currentSourceLabel==openedLabel&&safeFolderUri()==openedFolder
        if(openedFolder==null||protectedName(openedName)||openedUri==openedSource){
            showDialog("Delete blocked","Protected ORIGINAL backups and emulator-source documents cannot be deleted here. Nothing was deleted.");return
        }
        AlertDialog.Builder(this).setTitle("Delete this Gen 2 backup?")
            .setMessage("Delete only "+openedName+" from PSE Safe Backups? The emulator, working save and other backups will not be written or deleted.")
            .setNegativeButton("Cancel",null)
            .setPositiveButton("Delete"){_,_->
                if(!bound()){showDialog("Delete blocked","The active save, source identity or configured folder changed. Reopen Safe Backups. Nothing was deleted.");return@setPositiveButton}
                var deleteStarted=false
                try{
                    require(doc.uri==openedUri&&doc.exists()&&doc.isFile&&doc.name==openedName&&!protectedName(doc.name)&&doc.uri!=currentSourceUri){"The selected document changed, became protected or aliases the emulator source."}
                    val fresh=contentResolver.openInputStream(openedUri).use{requireNotNull(it).readBytes()}
                    require(fresh.contentEquals(opened)){"The selected backup bytes changed after confirmation."}
                    require(bound()&&doc.uri==openedUri&&doc.exists()&&doc.isFile&&doc.name==openedName&&!protectedName(doc.name)&&doc.uri!=currentSourceUri){"The confirmed backup or active context changed before deletion."}
                    val finalBytes=contentResolver.openInputStream(openedUri).use{requireNotNull(it).readBytes()}
                    require(finalBytes.contentEquals(opened)&&bound()&&doc.uri==openedUri&&doc.exists()&&doc.isFile&&doc.name==openedName&&!protectedName(doc.name)&&doc.uri!=currentSourceUri){"The selected backup changed during the final deletion check."}
                    deleteStarted=true
                    val deleted=doc.delete()
                    require(deleted&&!doc.exists()){"PSE could not verify that the selected backup was removed."}
                }catch(e:Exception){
                    val outcome=if(!deleteStarted)"Nothing was deleted." else  "The deletion result could not be verified. Refresh Safe Backups before taking further action."
                    showDialog("Delete not completed",(e.message?:"Could not verify backup deletion")+"\n\n"+outcome+"\n\nPSE did not write to the emulator, working save or any other backup.");return@setPositiveButton
                }
                Toast.makeText(this,"Selected Gen 2 backup deletion verified",Toast.LENGTH_SHORT).show()
                showSafeBackups()
            }.show()
    }

    private fun mirrorBackupToSafeFolder(file: File): Boolean {
        val opened=runCatching{file.readBytes()}.getOrNull()
        val gen2=opened?.let{detectGen2ChecksumProfile(it)}
        if(gen2!=null)return mirrorGen2BackupToSafeFolder(file,requireNotNull(opened),gen2.key)
        val treeUri = safeFolderUri() ?: return false
        return try {
            val root = DocumentFile.fromTreeUri(this, treeUri) ?: return false
            val existing = root.findFile(file.name)
            if (existing != null && existing.length() == file.length()) return true
            existing?.delete()
            val doc = root.createFile("application/octet-stream", file.name) ?: return false
            contentResolver.openOutputStream(doc.uri, "w").use { output ->
                val out = requireNotNull(output)
                file.inputStream().use { input -> input.copyTo(out) }
                out.flush()
            }
            true
        } catch (_: Exception) { false }
    }

    private fun mirrorGen2BackupToSafeFolder(file:File,opened:ByteArray,profileKey:String):Boolean {
        val folderUri=safeFolderUri()?:return false
        val protectedSource=currentSourceUri
        return try{
            require(file.isFile&&file.readBytes().contentEquals(opened)){"The selected Gen 2 safety backup changed."}
            require(verifyGen2SaveIntegrity(opened).first&&detectGen2Profile(opened)?.key==profileKey){"The Gen 2 safety backup failed integrity validation."}
            val root=DocumentFile.fromTreeUri(this,folderUri)?:return false
            require(root.exists()&&root.isDirectory){"The Safe Backups folder is unavailable."}
            val existing=root.findFile(file.name)
            if(existing!=null){
                require(existing.uri!=protectedSource&&existing.uri!=Uri.fromFile(file)){"The backup document aliases a protected source."}
                val same=runCatching{contentResolver.openInputStream(existing.uri).use{requireNotNull(it).readBytes()}.contentEquals(opened)}.getOrDefault(false)
                if(same){
                    require(file.readBytes().contentEquals(opened)&&safeFolderUri()==folderUri){"The selected backup or configured folder changed during mirror verification."}
                    return true
                }
            }
            // A name/size match is not content proof. Keep every conflicting document.
            val outputName=if(existing==null)file.name else file.nameWithoutExtension+"_Copy_"+java.util.UUID.randomUUID().toString()+".backup"
            val doc=root.createFile("application/octet-stream",outputName)?:return false
            require(doc.uri!=protectedSource&&doc.uri!=Uri.fromFile(file)&&doc.uri!=existing?.uri){"The new mirror must not alias an existing backup or protected source."}
            val empty=contentResolver.openInputStream(doc.uri).use{requireNotNull(it).read()==-1}
            require(empty){"The proposed mirror already contains data and will not be overwritten."}
            require(file.readBytes().contentEquals(opened)&&safeFolderUri()==folderUri){"The selected backup or configured folder changed before mirroring."}
            contentResolver.openOutputStream(doc.uri,"wt").use{output->val out=requireNotNull(output);out.write(opened);out.flush()}
            val persisted=contentResolver.openInputStream(doc.uri).use{requireNotNull(it).readBytes()}
            require(persisted.contentEquals(opened)&&verifyGen2SaveIntegrity(persisted).first&&detectGen2Profile(persisted)?.key==profileKey){"The new Gen 2 mirror did not reopen exactly with valid integrity."}
            require(file.readBytes().contentEquals(opened)&&safeFolderUri()==folderUri){"The source backup or configured folder changed while mirroring."}
            true
        }catch(_:Exception){false}
    }

    private fun deleteExternalBackup(name: String) {
        val treeUri = safeFolderUri() ?: return
        try { DocumentFile.fromTreeUri(this, treeUri)?.findFile(name)?.delete() } catch (_: Exception) { }
    }

    private fun syncAllBackupsToSafeFolder(): Int {
        if (safeFolderUri() == null) return 0
        var copied = 0
        backupsDir().listFiles()?.filter { it.isFile }?.forEach { if (mirrorBackupToSafeFolder(it)) copied++ }
        return copied
    }

    private fun ensureProtectedOriginal(source: Uri, safeLabel: String): Pair<File, Boolean> {
        val key = sourceKey(currentSourceLabel, source)
        val prefs = getSharedPreferences("pse_original_map", MODE_PRIVATE)
        val remembered = prefs.getString(key, null)?.let { File(backupsDir(), it) }
        if (remembered?.isFile == true) {
            mirrorBackupToSafeFolder(remembered)
            return remembered to false
        }
        val game = backupGameName()
        val original = File(backupsDir(), "ORIGINAL_${game}_${backupStamp()}.backup")
        contentResolver.openInputStream(source).use { input ->
            val src = requireNotNull(input) { "Could not read the original emulator save" }
            original.outputStream().use { output -> src.copyTo(output) }
        }
        if (original.length() <= 0L) { original.delete(); error("The protected ORIGINAL backup is empty") }
        val check = analyzeSave(original)
        if (!check.structurallyValid) { original.delete(); error("The protected ORIGINAL backup failed validation") }
        prefs.edit().putString(key, original.name).apply()
        mirrorBackupToSafeFolder(original)
        return original to true
    }

    private fun createRollingBackupFromUri(source: Uri, safeLabel: String, kind: String = "AUTO"): File {
        val game = backupGameName()
        val backup = File(backupsDir(), "${kind}_${game}_${backupStamp()}.backup")
        contentResolver.openInputStream(source).use { input ->
            val src = requireNotNull(input) { "Could not read source for backup" }
            backup.outputStream().use { output -> src.copyTo(output) }
        }
        mirrorBackupToSafeFolder(backup)
        pruneRollingBackups(game, 10)
        return backup
    }

    private fun createPreWriteBackupFromUri(source: Uri): File {
        val game = backupGameName()
        val backup = File(backupsDir(), "${game}_${backupStamp()}.backup")
        contentResolver.openInputStream(source).use { input ->
            val src = requireNotNull(input) { "Could not read emulator save for backup" }
            backup.outputStream().use { output -> src.copyTo(output) }
        }
        if (backup.length() <= 0L) {
            backup.delete()
            error("The pre-write backup is empty")
        }
        mirrorBackupToSafeFolder(backup)
        pruneRollingBackups(game, 10)
        return backup
    }

