        // v0.22.5: imports/restores/opening Safe Files never create safety copies.
        // The emulator source is untouched until Save & Replace, where exactly one backup is created.
    }

    private fun pruneRollingBackups(game: String, keepLatest: Int) {
        val keepSet = keptBackupNames()
        val rolling = backupsDir().listFiles()?.filter {
            it.isFile && it.name.startsWith("${game}_") && it.name.endsWith(".backup") && !keepSet.contains(it.name)
        }?.sortedByDescending { it.lastModified() } ?: emptyList()
        rolling.drop(keepLatest).forEach { deleteBackupEverywhere(it) }
    }

    private fun deleteBackupEverywhere(file: File) {
        if (backupIsProtected(file)) return
        setBackupKept(file, false)
        deleteExternalBackup(file.name)
        file.delete()
    }

    private fun latestImportedFile(): File? {
        val dir = File(filesDir, "imports")
        return dir.listFiles()?.filter { it.isFile }?.maxByOrNull { it.lastModified() }
    }

    private fun refreshSaveCard() {
        saveCard.removeAllViews()
        activeSwitchSave?.let {
            addCardLine(it.detectedGame, true)
            addCardLine("Generation ${it.generation} • Nintendo Switch")
            addCardLine("● Loaded & validated • Read-only", true, GOOD)
            addCardLine(it.displayName)
            updateStatus()
            return
        }
        val file = importedFile
        if (file == null) {
            addCardLine("NO SAVE LOADED", true)
            addCardLine("No save loaded.")
            updateStatus()
            return
        }

        val a = analyzeSave(file)
        val gen = generationForSize(a.actualSize)
        val game = when (gen) {
            1 -> detectGen1GameFromPath(currentSourceLabel ?: file.name)
            2 -> detectGen2Profile(file.readBytes())?.let { detectGen2GameFromPath(currentSourceLabel ?: file.name, it) } ?: (a.trainer?.exactGame ?: a.family)
            else -> (a.trainer?.exactGame ?: a.family)
        }
        addCardLine(game, true)
        val sourcePlatform = when(gen){1,2->"Game Boy & Game Boy Color";3->"Game Boy Advance";4->"Nintendo DS • Gen 4/5";else->"Azahar (Nintendo 3DS)"}
        addCardLine("Generation $gen • $sourcePlatform")
        addCardLine(if (a.structurallyValid) "● Loaded & validated" else "⚠ Save needs attention", true,
            if (a.structurallyValid) GOOD else WARN)
        a.trainer?.let {
            addCardLine("Trainer  ${it.trainerName.ifBlank { "(blank)" }}    •    TID ${it.tid.toString().padStart(5, '0')}")
            addCardLine("Play time  ${it.playedHours}:${it.playedMinutes.toString().padStart(2, '0')}")
        }

        updateStatus()
    }

    private fun inspectCurrentSave() {
        if (openActiveSwitchSection("overview")) return
        val file = importedFile
        if (file == null) {
            showDialog("Save Inspector", "No save is loaded yet. Tap Import 3DS Save first.")
            return
        }
        val a = analyzeSave(file)
        val inspectedGeneration = generationForSize(a.actualSize)
        val inspectedGame = sourceGameIdentity(file, currentSourceLabel) ?: a.trainer?.exactGame ?: a.family
        val expected = a.expectedSize?.let { "$it bytes (0x${it.toString(16).uppercase(Locale.US)})" } ?: "Unknown"
        val message = buildString {
            append("Detected family: ${a.family}\n")
            if (a.trainer != null) {
                append("Exact title: $inspectedGame\n")
                append("Stored game ID: ${a.trainer.gameId}\n")
                append("Game/family check: ${if (a.trainer.gameMatchesFamily) "PASS" else "FAIL"}\n")
            }
            append("\nActual size: ${a.actualSize} bytes\n")
            append("Expected size: $expected\n")
            if (inspectedGeneration == 1 || inspectedGeneration == 2) {
                append("Generation $inspectedGeneration save integrity: ${if (a.footerValid) "PASS" else "FAIL"}\n")
                a.validationDetail?.let { append("Integrity detail: $it\n") }
            } else append("Gen $inspectedGeneration BEEF footer: ${if (a.footerValid) "PASS" else "FAIL"}\n")
            append("Structural validation: ${if (a.structurallyValid) "PASS" else "FAIL"}\n\n")
            append("SHA-256:\n${a.sha256}\n\n")
            append(a.note)
        }
        showDialog("Save Inspector", message)
    }

    private fun gen2DayCareBytes(data:ByteArray,profile:Gen2Profile):ByteArray{val base=gen2DayCareBase(profile);require(base+165<data.size){"The Gen 2 Day Care block is outside the save."};return data.copyOfRange(base,base+166)}

    private fun gen2DayCarePayload(data:ByteArray,profile:Gen2Profile,slot:Int):ByteArray{
        require(slot in 0..1){"Only a Day Care parent can be withdrawn."};val state=gen2DayCareState(data,profile);val parent=if(slot==0)state.firstParent else state.secondParent;require(parent!=null){"The selected Day Care parent slot is empty."}
        val raw=gen2DayCareBase(profile)+if(slot==0)1 else 58;return ByteArray(55).also{out->out[0]=parent.species.toByte();data.copyOfRange(raw+22,raw+54).copyInto(out,1);data.copyOfRange(raw+11,raw+22).copyInto(out,33);data.copyOfRange(raw,raw+11).copyInto(out,44)}
    }

    private val GEN2_MAIL_ITEM_IDS=setOf(0x9e,0xb5,0xb6,0xb7,0xb8,0xb9,0xba,0xbb,0xbc,0xbd)

    private fun gen2DayCareDepositPayload(data:ByteArray,profile:Gen2Profile,mon:Gen2Pokemon):ByteArray{
        require(mon.slot>=0){"The selected party slot is invalid."}
        val partyBase=profile.partyOffset
        val mons=partyBase+8
        val record=mons+mon.slot*48
        val ots=mons+6*48
        val nicks=ots+6*11
        val ot=ots+mon.slot*11
        val nick=nicks+mon.slot*11
        require(record+32<=data.size&&ot+11<=data.size&&nick+11<=data.size){"The selected party record is outside the save."}
        val out=ByteArray(54)
        data.copyOfRange(nick,nick+11).copyInto(out,0)
        data.copyOfRange(ot,ot+11).copyInto(out,11)
        data.copyOfRange(record,record+32).copyInto(out,22)
        return out
    }

