    private fun gen2CanonicalEggGroups(species:Int):Set<Int>?=GEN2_CANONICAL_EGG_GROUPS[species]

    private fun gen2CanonicalGender(mon:Gen2Pokemon):Int?{
        if(mon.species in GEN2_GENDERLESS_SPECIES)return null
        if(mon.species in GEN2_MALE_ONLY_SPECIES)return 1
        if(mon.species in GEN2_FEMALE_ONLY_SPECIES)return 0
        val ratio=when(mon.species){
            in GEN2_GENDER_F12_5_SPECIES->31
            in GEN2_GENDER_F25_SPECIES->63
            in GEN2_GENDER_F50_SPECIES->127
            in GEN2_GENDER_F75_SPECIES->191
            else->return null
        }
        val genderValue=((mon.dvs[1]and 15)shl 4)or(mon.dvs[3]and 15)
        return if(ratio<genderValue)1 else 0
    }

    private fun gen2DayCarePairCannotInitializeBreeding(first:Gen2Pokemon,second:Gen2Pokemon):Boolean{
        if(first.isEgg||second.isEgg)return false
        if(first.species in GEN2_NO_EGGS_SPECIES||second.species in GEN2_NO_EGGS_SPECIES)return true
        if(first.species==132&&second.species==132)return true
        if(first.species!=132&&second.species!=132){
            if(first.species in GEN2_GENDERLESS_SPECIES||second.species in GEN2_GENDERLESS_SPECIES)return true
            if(first.species in GEN2_MALE_ONLY_SPECIES&&second.species in GEN2_MALE_ONLY_SPECIES)return true
            if(first.species in GEN2_FEMALE_ONLY_SPECIES&&second.species in GEN2_FEMALE_ONLY_SPECIES)return true
            val firstGender=gen2CanonicalGender(first);val secondGender=gen2CanonicalGender(second)
            if(firstGender!=null&&firstGender==secondGender)return true
            if(firstGender!=null&&secondGender!=null&&firstGender!=secondGender){
                val firstGroups=gen2CanonicalEggGroups(first.species);val secondGroups=gen2CanonicalEggGroups(second.species)
                if(firstGroups!=null&&secondGroups!=null&&firstGroups.intersect(secondGroups).isEmpty())return true
            }
        }
        return first.dvs[2]==second.dvs[2]&&(first.dvs[4]and 7)==(second.dvs[4]and 7)
    }

    private val gen2BreedingDataCache=HashMap<String,Map<Int,Gen2Breeding.Species>>()
    private fun gen2BreedingData(profile:Gen2Profile):Map<Int,Gen2Breeding.Species> = gen2BreedingDataCache.getOrPut(profile.key){
        val name=if(profile.key=="C")"crystal" else "gold"
        val json=JSONObject(assets.open("gen2_breeding_$name.json").bufferedReader(Charsets.UTF_8).use{it.readText()})
        fun ints(a:JSONArray):Set<Int> = (0 until a.length()).map{a.getInt(it)}.toSet()
        (1..251).associateWith{id->
            val row=json.getJSONArray(id.toString());val groups=row.getJSONArray(3);val learns=row.getJSONArray(4)
            Gen2Breeding.Species(row.getInt(0),row.getInt(1),row.getInt(2),
                (0 until groups.length()).map{groups.getString(it)}.toSet(),
                (0 until learns.length()).map{val move=learns.getJSONArray(it);move.getInt(0) to move.getInt(1)},
                ints(row.getJSONArray(5)),ints(row.getJSONArray(6)))
        }
    }
    private fun gen2BreedingParent(mon:Gen2Pokemon)=Gen2Breeding.Parent(mon.species,mon.dvs.copyOf(),mon.moves.copyOf())

    private fun gen2InitialEggPayload(data:ByteArray,egg:Gen2Breeding.Egg):ByteArray{
        val raw=ByteArray(32);raw[0]=egg.species.toByte();raw[31]=5
        for(i in 0..3){raw[2+i]=egg.moves[i].toByte();raw[23+i]=(if(egg.moves[i]==0)0 else requireNotNull(gen2MoveBasePp(egg.moves[i]))).toByte()}
        writeU16BE(raw,6,readU16BE(data,0x2009))
        val growth=canonicalGen2Growth(egg.species)?:error("Verified Gen 2 Egg growth data is missing.")
        writeU24BE(raw,8,gen2ExperienceForLevel(growth,5))
        raw[21]=((egg.dvs[1] shl 4) or egg.dvs[2]).toByte();raw[22]=((egg.dvs[3] shl 4) or egg.dvs[4]).toByte()
        raw[27]=egg.cycles.toByte()
        val result=ByteArray(54)
        writeGen1Text(result,0,11,"EGG")
        data.copyInto(result,11,0x200B,0x2016);raw.copyInto(result,22)
        return result
    }

    private fun confirmGen2DayCareBreedingDeposit(opened:ByteArray,profile:Gen2Profile,openedFile:File){
        val openedUri=currentSourceUri;val openedLabel=currentSourceLabel
        fun bound()=importedFile?.absolutePath==openedFile.absolutePath&&currentSourceUri==openedUri&&currentSourceLabel==openedLabel
        if(!bound()){showDialog("Gen 2 Day Care","The active save identity changed. Reopen Day Care. Nothing was changed.");return}
        if(importedFile?.absolutePath!=openedFile.absolutePath){showDialog("Gen 2 Day Care","The active save changed. Reopen Day Care before depositing a breeding parent. Nothing was changed.");return}
        val file=openedFile
        try{
            val state=gen2DayCareState(opened,profile)
            val existing=listOfNotNull(state.firstParent,state.secondParent).single()
            require(state.egg==null&&(state.firstFlags and 0x60)==0){"An Egg or breeding state already exists."}
            val tables=gen2BreedingData(profile);val party=parseGen2Party(opened,profile)
            val eligible=party.filter{candidate->!candidate.isEgg&&candidate.heldItem !in GEN2_MAIL_ITEM_IDS&&
                Gen2Breeding.compatible(gen2BreedingParent(existing),gen2BreedingParent(candidate),tables)&&
                party.any{it.slot!=candidate.slot&&!it.isEgg&&gen2PartyCurrentHp(opened,profile,it.slot)>0}}
            if(eligible.isEmpty()){showDialog("Gen 2 Day Care","No compatible party Pokémon can be deposited. Gen 2 rejects Eggs, Mail, No Eggs-group species, two Ditto, incompatible genders/Egg Groups and matching Defense plus low Special DVs. At least one usable party Pokémon must remain.");return}
            val target=if(state.firstParent==null)0 else 1
            var breedingDepositConsumed=false
            AlertDialog.Builder(this).setTitle("Deposit second parent").setItems(eligible.map{"${it.nickname} • Lv.${it.level}"}.toTypedArray()){_,which->
                if(importedFile?.absolutePath!=openedFile.absolutePath){showDialog("Gen 2 Day Care","The active save changed while the breeding-parent picker was open. Nothing was changed.");return@setItems}
                if(breedingDepositConsumed){showDialog("Gen 2 Day Care","This breeding deposit was already submitted. Reopen Day Care before trying again.");return@setItems}
                if(!bound()||!runCatching{openedFile.readBytes().contentEquals(opened)}.getOrDefault(false)){showDialog("Gen 2 Day Care","The active save changed while the breeding-parent picker was open. Nothing was changed.");return@setItems}
                try{
                    val selected=eligible[which];val first=if(target==0)selected else existing;val second=if(target==1)selected else existing
                    val random=java.security.SecureRandom()
                    val egg=Gen2Breeding.initialise(gen2BreedingParent(first),gen2BreedingParent(second),tables){random.nextInt(it)}
                    val eggPayload=gen2InitialEggPayload(opened,egg)
                    AlertDialog.Builder(this).setTitle("Deposit ${selected.nickname} for breeding?")
                        .setMessage("Move this Pokémon into Parent ${target+1} and initialise normal Gen 2 breeding? The Egg species, inherited moves/DVs and step counter follow this game's rules. Walk in the game for the Day Care to make the Egg ready; collect it there. Existing Pokémon and unrelated save data are preserved. A verified kept recovery backup is required before writing. If writing starts and then fails, PSE attempts and verifies a complete restore. An unverified restore requires restoring the retained backup.")
                        .setNegativeButton("Cancel",null).setPositiveButton("Deposit"){_,_->
                            if(breedingDepositConsumed){showDialog("Gen 2 Day Care","This breeding deposit was already submitted. Reopen Day Care before trying again.");return@setPositiveButton}
                            breedingDepositConsumed=true
                            depositGen2DayCareBreeding(file,opened,profile,selected,target,egg,eggPayload,openedUri,openedLabel)
                        }.show()
                }catch(e:Exception){showDialog("Gen 2 breeding unavailable",e.message?:"Verified breeding data could not be loaded. Nothing was changed.")}
            }.setNegativeButton("Cancel",null).show()
        }catch(e:Exception){showDialog("Gen 2 breeding unavailable",e.message?:"The Day Care state is invalid. Nothing was changed.")}
    }

    private fun depositGen2DayCareBreeding(file:File,opened:ByteArray,openedProfile:Gen2Profile,mon:Gen2Pokemon,target:Int,egg:Gen2Breeding.Egg,eggPayload:ByteArray,openedUri:Uri?,openedLabel:String?){
        fun bound()=importedFile?.absolutePath==file.absolutePath&&currentSourceUri==openedUri&&currentSourceLabel==openedLabel
        var original:ByteArray?=null;var writeStarted=false
        var safetyBackup:File?=null
        try{
            require(bound()){"The active save identity changed. Nothing was changed."}
            require(importedFile?.absolutePath==file.absolutePath){"The active save changed."}
            val fresh=file.readBytes();original=fresh
            require(bound()&&verifyGen2SaveIntegrity(fresh).first){"The active save changed or failed full Gen 2 integrity validation."}
            require(fresh.contentEquals(opened)){"The save changed after confirmation. Nothing was changed."}
            val profile=detectGen2Profile(fresh)?:error("The fresh save failed checksum or structure validation.")
            require(profile.key==openedProfile.key&&target in 0..1&&eggPayload.size==54){"The prepared destination is invalid."}
            val state=gen2DayCareState(fresh,profile)
            val existing=if(target==0)state.secondParent else state.firstParent
            require(existing!=null&&(if(target==0)state.firstParent else state.secondParent)==null&&state.egg==null&&(state.firstFlags and 0x60)==0){"The Day Care is no longer ready for a second parent."}
            val party=parseGen2Party(fresh,profile);val current=party.firstOrNull{it.slot==mon.slot}
            require(current!=null&&sameGen2BankRecord(current,mon)&&!current.isEgg&&current.heldItem !in GEN2_MAIL_ITEM_IDS){"The selected Pokémon changed or cannot be deposited."}
            require(party.size>1&&party.any{it.slot!=mon.slot&&!it.isEgg&&gen2PartyCurrentHp(fresh,profile,it.slot)>0}){"At least one usable party Pokémon must remain."}
            require(Gen2Breeding.compatible(gen2BreedingParent(existing),gen2BreedingParent(current),gen2BreedingData(profile))){"The pair cannot breed."}
            val before=gen2LocationPayloads(fresh,"Party",profile)
            val remaining=before.filterIndexed{i,_->i!=mon.slot}
            val deposited=gen2DayCareDepositPayload(fresh,profile,current)
            val existingPayload=gen2DayCarePayload(fresh,profile,1-target)
            val base=gen2DayCareBase(profile);val work=fresh.copyOf()
            removeGen2ForBank(work,current,"Party")
            deposited.copyInto(work,base+if(target==0)1 else 58)
            val flags=base+if(target==0)0 else 55
            work[flags]=(work[flags].toInt() or 0x81).toByte()
            work[base]=(work[base].toInt() or 0x20).toByte()
            work[base+56]=egg.steps.toByte();work[base+57]=egg.motherSlot.toByte();eggPayload.copyInto(work,base+112)
            updateGen2PrimaryChecksum(work,profile)
            val p=profile.partyOffset;val count=before.size;val mons=p+8;val ots=mons+6*48;val nicks=ots+6*11
            val allowed=mutableSetOf(p,profile.checksumOffset,profile.checksumOffset+1)
            for(i in p+1+mon.slot..p+count)allowed.add(i)
            for(i in mons+mon.slot*48 until mons+count*48)allowed.add(i)
            for(i in ots+mon.slot*11 until ots+count*11)allowed.add(i)
            for(i in nicks+mon.slot*11 until nicks+count*11)allowed.add(i)
            for(i in base until base+166)allowed.add(i)
            require(fresh.indices.all{it in allowed||fresh[it]==work[it]}){"Breeding changed unrelated save data."}
            val expectedDayCare=gen2DayCareBytes(work,profile)
            fun verify(bytes:ByteArray){
                require(bound()&&verifyGen2SaveIntegrity(bytes).first){"The breeding save failed full integrity or source identity verification."}
                val checked=detectGen2Profile(bytes)?:error("Breeding save failed checksum or structure validation.")
                require(checked.key==profile.key&&sameGen2PayloadList(gen2LocationPayloads(bytes,"Party",checked),remaining)&&gen2DayCareBytes(bytes,checked).contentEquals(expectedDayCare)){"Breeding or party data did not persist exactly."}
                val result=gen2DayCareState(bytes,checked);val depositedParent=if(target==0)result.firstParent else result.secondParent
                require(depositedParent!=null&&sameGen2BankRecord(depositedParent,current)&&gen2DayCarePayload(bytes,checked,1-target).contentEquals(existingPayload)){"A parent changed during breeding initialisation."}
                require((result.firstFlags and 0x20)!=0&&(result.firstFlags and 0x40)==0&&result.stepsUntilEgg==egg.steps&&result.dittoParentState==egg.motherSlot){"The breeding flags or counter did not verify."}
                require(bytes.copyOfRange(base+112,base+166).contentEquals(eggPayload)){"The initial Egg record did not verify exactly."}
            }
            verify(work)
            require(importedFile?.absolutePath==file.absolutePath&&file.readBytes().contentEquals(fresh)){"The save changed before writing."}
            val backup=File.createTempFile(backupGameName(file)+"_PreGen2BreedingDayCareDeposit_",".backup",backupsDir());safetyBackup=backup
            backup.writeBytes(fresh);require(backup.readBytes().contentEquals(fresh)){"The recovery backup did not verify exactly."}
            retainGen2SafetyBackup(backup,fresh)
            require(bound()&&isBackupKept(backup)&&backup.readBytes().contentEquals(fresh)&&file.readBytes().contentEquals(fresh)){"The active save or retained recovery backup changed before writing."}
            writeStarted=true;file.writeBytes(work)
            val persisted=file.readBytes();require(persisted.contentEquals(work)){"The breeding write did not persist exactly."};verify(persisted)
            require(bound()&&verifyGen2SaveIntegrity(persisted).first&&file.readBytes().contentEquals(work)){"The persisted breeding deposit failed full integrity or final source verification."}
        }catch(e:Exception){
            val rollback=original
            val restored=if(writeStarted&&rollback!=null)runCatching{file.writeBytes(rollback);require(file.readBytes().contentEquals(rollback)&&verifyGen2SaveIntegrity(rollback).first)}.isSuccess else false
            val recovery=if(!writeStarted)"Nothing was written to the working save." else  if(restored)"The complete fresh working save was restored and verified; no partial breeding or Egg update was kept." else  "Restoration failed. Automatic restore could not be verified. Restore the retained recovery backup before continuing."
            showDialog("Day Care deposit failed",(e.message?:"Unknown error")+"\n\n"+recovery+(safetyBackup?.let{"\n\nRecovery backup: "+it.name}?:""));return
        }
        Toast.makeText(this,"Second parent deposited; breeding initialised",Toast.LENGTH_LONG).show();showGen2DayCare()
    }

    private fun confirmGen2DayCareNonBreedingSecondParentDeposit(openedSource:ByteArray,openedProfile:Gen2Profile,openedFile:File,openedUri:Uri?,openedLabel:String?){
        fun bound()=importedFile?.absolutePath==openedFile.absolutePath&&currentSourceUri==openedUri&&currentSourceLabel==openedLabel
        if(!bound()){showDialog("Gen 2 Day Care","The active save identity changed. Reopen Day Care. Nothing was changed.");return}
        if(importedFile?.absolutePath!=openedFile.absolutePath){showDialog("Gen 2 Day Care","The active save changed. Reopen Day Care before depositing a second parent. Nothing was changed.");return}
        val openedDayCare=runCatching{gen2DayCareBytes(openedSource,openedProfile)}.getOrElse{showDialog("Gen 2 Day Care",it.message?:"The Day Care block could not be read.");return};val state=runCatching{gen2DayCareState(openedSource,openedProfile)}.getOrElse{showDialog("Gen 2 Day Care",it.message?:"The Day Care state could not be read.");return};val party=parseGen2Party(openedSource,openedProfile);val openedParty=runCatching{gen2LocationPayloads(openedSource,"Party",openedProfile)}.getOrElse{showDialog("Gen 2 Day Care",it.message?:"The party could not be read.");return}
        val occupied=listOfNotNull(state.firstParent,state.secondParent);if(occupied.size!=1||state.egg!=null||(state.firstFlags and 0x60)!=0){showDialog("Gen 2 Day Care","This bounded deposit requires exactly one parent, no pending Egg, and no active compatibility state. Nothing was changed.");return};if(party.size<2){showDialog("Gen 2 Day Care","Generation 2 must keep at least one Pokémon in the party. Nothing was changed.");return}
        val existing=occupied.single();val existingSlot=if(state.firstParent!=null)0 else 1;val targetSlot=1-existingSlot;val openedExistingPayload=runCatching{gen2DayCarePayload(openedSource,openedProfile,existingSlot)}.getOrElse{showDialog("Gen 2 Day Care",it.message?:"The existing parent could not be read.");return}
        val eligible=party.filter{candidate->!candidate.isEgg&&candidate.heldItem !in GEN2_MAIL_ITEM_IDS&&gen2DayCarePairCannotInitializeBreeding(existing,candidate)&&party.any{other->other.slot!=candidate.slot&&!other.isEgg&&gen2PartyCurrentHp(openedSource,openedProfile,other.slot)>0}}
        if(eligible.isEmpty()){showDialog("Gen 2 Day Care","No party Pokémon is eligible for this conservative second-parent deposit. PSE currently accepts an exact Gen 2 No Eggs-group species, two Ditto, or the forbidden-DV relationship, plus genderless non-Ditto, same fixed-gender, exact same DV-derived gender pairs, and opposite-gender non-Ditto pairs with known disjoint canonical Egg Groups, because those cases cannot initialize breeding or Egg state.");return}
        var secondDepositConsumed=false
        val slotLabel="Parent ${targetSlot+1}";AlertDialog.Builder(this).setTitle("Choose verified non-breeding $slotLabel").setItems(eligible.map{"${it.nickname.ifBlank{"Pokémon #${it.species}"}} • Lv.${it.level}"}.toTypedArray()){_,which->if(importedFile?.absolutePath!=openedFile.absolutePath){showDialog("Gen 2 Day Care","The active save changed while the second-parent picker was open. Nothing was changed.");return@setItems};if(secondDepositConsumed){showDialog("Gen 2 Day Care","This deposit was already submitted. Reopen Day Care before trying again.");return@setItems};if(!bound()||!runCatching{openedFile.readBytes().contentEquals(openedSource)}.getOrDefault(false)){showDialog("Gen 2 Day Care","The active save changed while the second-parent picker was open. Nothing was changed.");return@setItems};val selected=eligible[which];val expected=runCatching{gen2DayCareDepositPayload(openedSource,openedProfile,selected)}.getOrElse{showDialog("Gen 2 Day Care",it.message?:"The selected parent could not be prepared.");return@setItems};AlertDialog.Builder(this).setTitle("Deposit ${selected.nickname.ifBlank{"Pokémon #${selected.species}"}} into $slotLabel?").setMessage("The original Gen 2 egg-group, Ditto or DV rules prove this pair cannot breed. The engine gender rules also reject genderless non-Ditto and same fixed-gender pairs. Exact Attack and Speed DVs are re-evaluated for every other gendered pair. Opposite-gender non-Ditto pairs are accepted only when both canonical Egg Group sets are known and disjoint. PSE will move the exact party record into the empty parent slot while leaving compatibility, Egg data, step counters and the existing parent byte-exact. Other second-parent pairs remain locked. A verified kept recovery backup is required before writing. If writing starts and then fails, PSE attempts and verifies a complete restore. An unverified restore requires restoring the retained backup.").setNegativeButton("Cancel",null).setPositiveButton("Deposit"){_,_->
                if(secondDepositConsumed){showDialog("Gen 2 Day Care","This deposit was already submitted. Reopen Day Care before trying again.");return@setPositiveButton}
                secondDepositConsumed=true
                depositGen2DayCareNonBreedingSecondParent(existing,selected,targetSlot,openedSource,openedProfile,openedDayCare,openedParty,openedExistingPayload,expected,openedFile,openedUri,openedLabel)
            }.show()}.setNegativeButton("Cancel",null).show()
    }

    private fun depositGen2DayCareNonBreedingSecondParent(existing:Gen2Pokemon,mon:Gen2Pokemon,targetSlot:Int,openedSource:ByteArray,openedProfile:Gen2Profile,openedDayCare:ByteArray,openedParty:List<ByteArray>,openedExistingPayload:ByteArray,expectedPayload:ByteArray,openedFile:File,openedUri:Uri?,openedLabel:String?){
        fun bound()=importedFile?.absolutePath==openedFile.absolutePath&&currentSourceUri==openedUri&&currentSourceLabel==openedLabel
        if(!bound()){showDialog("Gen 2 Day Care","The active save identity changed. Reopen Day Care. Nothing was changed.");return}
        if(importedFile?.absolutePath!=openedFile.absolutePath){showDialog("Gen 2 Day Care","The active save changed. Reopen Day Care before depositing a second parent. Nothing was changed.");return}
