            val state=gen2DayCareState(fresh,profile);val existingSlot=1-targetSlot;val liveExisting=if(existingSlot==0)state.firstParent else state.secondParent;val liveTarget=if(targetSlot==0)state.firstParent else state.secondParent;require(liveExisting!=null&&sameGen2BankRecord(liveExisting,existing)&&liveTarget==null&&state.egg==null&&(state.firstFlags and 0x60)==0){"The one-parent Day Care state changed or can no longer be handled without breeding."};require(gen2DayCarePayload(fresh,profile,existingSlot).contentEquals(openedExistingPayload)){"The exact existing parent payload changed after confirmation."}
            val current=parseGen2Party(fresh,profile).firstOrNull{it.slot==mon.slot};require(current!=null&&sameGen2BankRecord(current,mon)&&!current.isEgg){"The selected party Pokémon or Egg state changed."};require(current.heldItem !in GEN2_MAIL_ITEM_IDS){"Pokémon holding Mail cannot be deposited."};require(gen2DayCarePairCannotInitializeBreeding(liveExisting,current)){"The selected pair is no longer provably non-breeding."};require(parseGen2Party(fresh,profile).any{it.slot!=current.slot&&!it.isEgg&&gen2PartyCurrentHp(fresh,profile,it.slot)>0}){"At least one other usable party Pokémon must remain."};require(gen2DayCareDepositPayload(fresh,profile,current).contentEquals(expectedPayload)){"The exact selected party payload changed after confirmation."}
            val sourcePayload=partyBefore[current.slot];val expectedParentPayload=gen2DuplicateBoxPayload(sourcePayload,true);val expectedParty=partyBefore.filterIndexed{index,_->index!=current.slot};val work=fresh.copyOf();removeGen2ForBank(work,current,"Party");val dayCareBase=gen2DayCareBase(profile);val targetFlagOffset=dayCareBase+if(targetSlot==0)0 else 55;val targetPayloadOffset=dayCareBase+if(targetSlot==0)1 else 58;expectedPayload.copyInto(work,targetPayloadOffset);work[targetFlagOffset]=(work[targetFlagOffset].toInt()or 0x81).toByte();updateGen2PrimaryChecksum(work,profile)
            val partyBase=profile.partyOffset;val count=partyBefore.size;val mons=partyBase+8;val ots=mons+6*48;val nicks=ots+6*11;val allowed=HashSet<Int>();allowed.add(partyBase);for(i in partyBase+1+current.slot..partyBase+count)allowed.add(i);for(i in mons+current.slot*48 until mons+count*48)allowed.add(i);for(i in ots+current.slot*11 until ots+count*11)allowed.add(i);for(i in nicks+current.slot*11 until nicks+count*11)allowed.add(i);allowed.add(targetFlagOffset);for(i in targetPayloadOffset until targetPayloadOffset+54)allowed.add(i);for(i in profile.checksumOffset..profile.checksumOffset+1)allowed.add(i);require(work.indices.all{it in allowed||work[it]==fresh[it]}){"The second-parent deposit changed unrelated save data."}
            val stagedProfile=detectGen2Profile(work)?:error("The staged Gen 2 save failed structural validation.");val stagedState=gen2DayCareState(work,stagedProfile);val stagedTarget=if(targetSlot==0)stagedState.firstParent else stagedState.secondParent;val stagedExisting=if(existingSlot==0)stagedState.firstParent else stagedState.secondParent;val expectedFirstFlags=if(targetSlot==0)(state.firstFlags or 0x81)else state.firstFlags;val expectedSecondFlags=if(targetSlot==1)(state.secondFlags or 0x81)else state.secondFlags;require(stagedTarget?.let{sameGen2BankRecord(it,current)}==true&&stagedExisting?.let{sameGen2BankRecord(it,liveExisting)}==true&&stagedState.egg==null&&(stagedState.firstFlags and 0x60)==0&&stagedState.firstFlags==expectedFirstFlags&&stagedState.secondFlags==expectedSecondFlags&&stagedState.stepsUntilEgg==state.stepsUntilEgg&&stagedState.dittoParentState==state.dittoParentState){"The staged non-breeding pair, flags, or counters did not verify."};require(gen2DayCarePayload(work,stagedProfile,targetSlot).contentEquals(expectedParentPayload)&&gen2DayCarePayload(work,stagedProfile,existingSlot).contentEquals(openedExistingPayload)){"A staged Day Care parent payload changed."};require(sameGen2PayloadList(gen2LocationPayloads(work,"Party",stagedProfile),expectedParty)){"A surviving party record changed during second-parent staging."}
            require(verifyGen2SaveIntegrity(work).first){"The staged non-breeding Day Care deposit failed full Gen 2 integrity validation."}
            require(importedFile?.absolutePath==openedFile.absolutePath&&file.readBytes().contentEquals(fresh)){"The Gen 2 source changed while the non-breeding second-parent deposit was staged. Nothing was written."}
            val backup=File.createTempFile(backupGameName(file)+"_PreGen2NonBreedingDayCareDeposit_",".backup",backupsDir());safetyBackup=backup
            backup.writeBytes(fresh);require(backup.readBytes().contentEquals(fresh)){"The recovery backup did not verify exactly."}
            retainGen2SafetyBackup(backup,fresh)
            require(bound()&&isBackupKept(backup)&&backup.readBytes().contentEquals(fresh)&&file.readBytes().contentEquals(fresh)){"The active save or retained recovery backup changed before writing."}
            writeStarted=true
            file.writeBytes(work);val persisted=file.readBytes();require(persisted.contentEquals(work)){"The Gen 2 save changed while the second-parent deposit was written."};val persistedProfile=detectGen2Profile(persisted)?:error("The persisted Gen 2 save failed structural validation.");val persistedState=gen2DayCareState(persisted,persistedProfile);val persistedTarget=if(targetSlot==0)persistedState.firstParent else persistedState.secondParent;val persistedExisting=if(existingSlot==0)persistedState.firstParent else persistedState.secondParent;require(gen2DayCareBytes(persisted,persistedProfile).contentEquals(gen2DayCareBytes(work,stagedProfile))&&sameGen2PayloadList(gen2LocationPayloads(persisted,"Party",persistedProfile),expectedParty)){"The persisted Day Care or party state did not match the staged transaction."};require(persistedTarget?.let{sameGen2BankRecord(it,current)}==true&&persistedExisting?.let{sameGen2BankRecord(it,liveExisting)}==true&&gen2DayCarePayload(persisted,persistedProfile,targetSlot).contentEquals(expectedParentPayload)&&gen2DayCarePayload(persisted,persistedProfile,existingSlot).contentEquals(openedExistingPayload)){"The persisted non-breeding pair did not preserve both exact parents."}
            require(bound()&&verifyGen2SaveIntegrity(persisted).first&&file.readBytes().contentEquals(work)){"The persisted non-breeding deposit failed full integrity or final source verification."}
        }catch(e:Exception){
            val restored=writeStarted&&runCatching{file.writeBytes(fresh)}.isSuccess&&runCatching{file.readBytes().contentEquals(fresh)&&verifyGen2SaveIntegrity(fresh).first}.getOrDefault(false)
            val recovery=if(!writeStarted)"Nothing was written to the save." else  if(restored)"The complete fresh working save was restored and verified." else  "Automatic restore could not be verified. Restore the retained recovery backup before continuing."
            showDialog("Gen 2 Day Care deposit failed","${e.message?:"Unknown error"}\n\n$recovery"+(safetyBackup?.let{"\n\nRecovery backup: "+it.name}?:""));return
        }
        Toast.makeText(this,"Verified non-breeding Day Care pair deposited",Toast.LENGTH_LONG).show();showGen2DayCare()
    }

    private fun confirmGen2DayCareFirstParentDeposit(openedSource:ByteArray,openedProfile:Gen2Profile,targetSlot:Int,openedFile:File,openedUri:Uri?,openedLabel:String?){
        fun bound()=importedFile?.absolutePath==openedFile.absolutePath&&currentSourceUri==openedUri&&currentSourceLabel==openedLabel
        if(!bound()){showDialog("Gen 2 Day Care","The active save identity changed. Reopen Day Care. Nothing was changed.");return}
        if(importedFile?.absolutePath!=openedFile.absolutePath){showDialog("Gen 2 Day Care","The active save changed. Reopen Day Care before depositing a parent. Nothing was changed.");return}
        if(targetSlot !in 0..1){showDialog("Gen 2 Day Care","The selected Day Care parent slot is invalid.");return}
        val openedDayCare=runCatching{gen2DayCareBytes(openedSource,openedProfile)}.getOrElse{showDialog("Gen 2 Day Care",it.message?:"The Day Care block could not be read.");return}
        val state=runCatching{gen2DayCareState(openedSource,openedProfile)}.getOrElse{showDialog("Gen 2 Day Care",it.message?:"The Day Care state could not be read.");return}
        if(state.firstParent!=null||state.secondParent!=null||state.egg!=null||(state.firstFlags and 0x61)!=0||(state.secondFlags and 1)!=0){showDialog("Gen 2 Day Care","The Day Care must be completely empty before an initial parent is deposited. Nothing was changed.");return}
        val party=parseGen2Party(openedSource,openedProfile)
        if(party.size<2){showDialog("Gen 2 Day Care","Generation 2 must keep at least one Pokémon in the party. Nothing was changed.");return}
        val eligible=party.filter{candidate->!candidate.isEgg&&candidate.heldItem !in GEN2_MAIL_ITEM_IDS&&party.any{other->other.slot!=candidate.slot&&!other.isEgg&&gen2PartyCurrentHp(openedSource,openedProfile,other.slot)>0}}
        if(eligible.isEmpty()){showDialog("Gen 2 Day Care","No eligible party Pokémon remain after Egg, Mail, party-survival, and usable-party checks.");return}
        var initialDepositConsumed=false
        val slotLabel="Parent ${targetSlot+1}"
        AlertDialog.Builder(this).setTitle("Choose initial $slotLabel").setItems(eligible.map{"${it.nickname.ifBlank{"Pokémon #${it.species}"}} • Lv.${it.level}"}.toTypedArray()){_,which->
            if(initialDepositConsumed){showDialog("Gen 2 Day Care","This deposit was already submitted. Reopen Day Care before trying again.");return@setItems}
            if(!bound()||!runCatching{openedFile.readBytes().contentEquals(openedSource)}.getOrDefault(false)){showDialog("Gen 2 Day Care","The active save changed while the parent picker was open. Nothing was changed.");return@setItems}
            if(importedFile?.absolutePath!=openedFile.absolutePath){showDialog("Gen 2 Day Care","The active save changed while the parent picker was open. Nothing was changed.");return@setItems}
            val selected=eligible[which]
            val expected=runCatching{gen2DayCareDepositPayload(openedSource,openedProfile,selected)}.getOrElse{showDialog("Gen 2 Day Care",it.message?:"The selected parent could not be prepared.");return@setItems}
            AlertDialog.Builder(this).setTitle("Deposit ${selected.nickname.ifBlank{"Pokémon #${selected.species}"}} into $slotLabel?").setMessage("PSE will move the exact party record into the requested empty parent slot. Breeding compatibility and Egg generation remain untouched. A verified kept recovery backup is required before writing. If writing starts and then fails, PSE attempts and verifies a complete restore. An unverified restore requires restoring the retained backup.").setNegativeButton("Cancel",null).setPositiveButton("Deposit"){_,_->
                if(initialDepositConsumed){showDialog("Gen 2 Day Care","This deposit was already submitted. Reopen Day Care before trying again.");return@setPositiveButton}
                initialDepositConsumed=true
                depositGen2DayCareFirstParent(selected,targetSlot,openedSource,openedProfile,openedDayCare,expected,openedFile,openedUri,openedLabel)
            }.show()
        }.setNegativeButton("Cancel",null).show()
    }

    private fun depositGen2DayCareFirstParent(mon:Gen2Pokemon,targetSlot:Int,openedSource:ByteArray,openedProfile:Gen2Profile,openedDayCare:ByteArray,expectedPayload:ByteArray,openedFile:File,openedUri:Uri?,openedLabel:String?){
        fun bound()=importedFile?.absolutePath==openedFile.absolutePath&&currentSourceUri==openedUri&&currentSourceLabel==openedLabel
        if(!bound()){showDialog("Gen 2 Day Care","The active save identity changed. Reopen Day Care. Nothing was changed.");return}
        if(importedFile?.absolutePath!=openedFile.absolutePath){showDialog("Gen 2 Day Care","The active save changed. Reopen Day Care before depositing a parent. Nothing was changed.");return}
        val file=openedFile
        val fresh=runCatching{file.readBytes()}.getOrNull()?:return
        var writeStarted=false
        var safetyBackup:File?=null
        try{
            require(bound()&&verifyGen2SaveIntegrity(fresh).first){"The active save changed or failed full Gen 2 integrity validation."}
            require(targetSlot in 0..1){"The selected Day Care parent slot is invalid."}
            require(fresh.contentEquals(openedSource)){"The Gen 2 save changed after the Day Care screen opened."}
            val profile=detectGen2Profile(fresh)?:error("The fresh Gen 2 save failed structural validation.")
            require(profile.key==openedProfile.key&&gen2ChecksumValid(fresh,profile)){"The Gen 2 profile or checksum changed."}
            require(gen2DayCareBytes(fresh,profile).contentEquals(openedDayCare)){"The Day Care state changed after confirmation."}
            val partyBefore=gen2LocationPayloads(fresh,"Party",profile)
            require(partyBefore.size>1){"Generation 2 must keep at least one Pokémon in the party."}
            val state=gen2DayCareState(fresh,profile)
            require(state.firstParent==null&&state.secondParent==null&&state.egg==null){"The Day Care is no longer empty."}
            require((state.firstFlags and 0x61)==0&&(state.secondFlags and 1)==0){"The Day Care compatibility state changed before confirmation."}
            val current=parseGen2Party(fresh,profile).firstOrNull{it.slot==mon.slot}
            require(current!=null&&sameGen2BankRecord(current,mon)&&!current.isEgg){"The selected party Pokémon or Egg state changed."}
            require(current.heldItem !in GEN2_MAIL_ITEM_IDS){"Pokémon holding Mail cannot be deposited."}
            require(parseGen2Party(fresh,profile).any{it.slot!=current.slot&&!it.isEgg&&gen2PartyCurrentHp(fresh,profile,it.slot)>0}){"At least one other usable party Pokémon must remain."}
            require(gen2DayCareDepositPayload(fresh,profile,current).contentEquals(expectedPayload)){"The exact nickname, OT and box-core payload changed after confirmation."}

            val sourcePayload=partyBefore[current.slot]
            val expectedParentPayload=gen2DuplicateBoxPayload(sourcePayload,true)
            val expectedParty=partyBefore.filterIndexed{index,_->index!=current.slot}
            val work=fresh.copyOf()
            removeGen2ForBank(work,current,"Party")
            val dayCareBase=gen2DayCareBase(profile)
            val targetFlagOffset=dayCareBase+if(targetSlot==0)0 else 55
            val targetPayloadOffset=dayCareBase+if(targetSlot==0)1 else 58
            expectedPayload.copyInto(work,targetPayloadOffset)
            work[targetFlagOffset]=(work[targetFlagOffset].toInt()or 0x81).toByte()
            updateGen2PrimaryChecksum(work,profile)

            val partyBase=profile.partyOffset
            val count=partyBefore.size
            val mons=partyBase+8
            val ots=mons+6*48
            val nicks=ots+6*11
            val allowed=HashSet<Int>()
            allowed.add(partyBase)
            for(i in partyBase+1+current.slot..partyBase+count)allowed.add(i)
            for(i in mons+current.slot*48 until mons+count*48)allowed.add(i)
            for(i in ots+current.slot*11 until ots+count*11)allowed.add(i)
            for(i in nicks+current.slot*11 until nicks+count*11)allowed.add(i)
            allowed.add(targetFlagOffset)
            for(i in targetPayloadOffset until targetPayloadOffset+54)allowed.add(i)
            for(i in profile.checksumOffset..profile.checksumOffset+1)allowed.add(i)
            require(work.indices.all{it in allowed||work[it]==fresh[it]}){"The Day Care deposit changed unrelated save data."}

            val stagedProfile=detectGen2Profile(work)?:error("The staged Gen 2 save failed structural validation.")
            val stagedState=gen2DayCareState(work,stagedProfile)
            val stagedTarget=if(targetSlot==0)stagedState.firstParent else stagedState.secondParent
            val stagedOther=if(targetSlot==0)stagedState.secondParent else stagedState.firstParent
            val expectedFirstFlags=if(targetSlot==0)(state.firstFlags or 0x81)else state.firstFlags
            val expectedSecondFlags=if(targetSlot==1)(state.secondFlags or 0x81)else state.secondFlags
            require(stagedTarget?.let{sameGen2BankRecord(it,current)}==true&&stagedOther==null){"The staged parent identity or empty slot did not verify."}
            require(stagedState.egg==null&&stagedState.firstFlags==expectedFirstFlags&&stagedState.secondFlags==expectedSecondFlags&&stagedState.stepsUntilEgg==state.stepsUntilEgg&&stagedState.dittoParentState==state.dittoParentState){"Breeding compatibility and Egg generation remain untouched."}
            require(gen2DayCarePayload(work,stagedProfile,targetSlot).contentEquals(expectedParentPayload)){"The staged Day Care payload changed."}
            require(sameGen2PayloadList(gen2LocationPayloads(work,"Party",stagedProfile),expectedParty)){"A surviving party record changed during initial-parent staging."}

            require(verifyGen2SaveIntegrity(work).first){"The staged initial Day Care deposit failed full Gen 2 integrity validation."}
            require(importedFile?.absolutePath==openedFile.absolutePath&&file.readBytes().contentEquals(fresh)){"The Gen 2 source changed while the initial Day Care deposit was staged. Nothing was written."}
            val backup=File.createTempFile(backupGameName(file)+"_PreGen2InitialDayCareDeposit_",".backup",backupsDir());safetyBackup=backup
            backup.writeBytes(fresh);require(backup.readBytes().contentEquals(fresh)){"The recovery backup did not verify exactly."}
            retainGen2SafetyBackup(backup,fresh)
            require(bound()&&isBackupKept(backup)&&backup.readBytes().contentEquals(fresh)&&file.readBytes().contentEquals(fresh)){"The active save or retained recovery backup changed before writing."}
            writeStarted=true
            file.writeBytes(work)
            val persisted=file.readBytes()
            require(persisted.contentEquals(work)){"The Gen 2 save changed while the Day Care deposit was written."}
            val persistedProfile=detectGen2Profile(persisted)?:error("The persisted Gen 2 save failed structural validation.")
            val persistedState=gen2DayCareState(persisted,persistedProfile)
            val persistedTarget=if(targetSlot==0)persistedState.firstParent else persistedState.secondParent
            val persistedOther=if(targetSlot==0)persistedState.secondParent else persistedState.firstParent
            require(persistedTarget?.let{sameGen2BankRecord(it,current)}==true&&persistedOther==null){"The persisted parent identity or empty slot did not verify."}
            require(gen2DayCareBytes(persisted,persistedProfile).contentEquals(gen2DayCareBytes(work,stagedProfile))&&sameGen2PayloadList(gen2LocationPayloads(persisted,"Party",persistedProfile),expectedParty)){"The persisted Day Care or party state did not match the staged transaction."}
            require(bound()&&verifyGen2SaveIntegrity(persisted).first&&file.readBytes().contentEquals(work)){"The persisted initial deposit failed full integrity or final source verification."}
        }catch(e:Exception){
            val restored=writeStarted&&runCatching{file.writeBytes(fresh)}.isSuccess&&runCatching{file.readBytes().contentEquals(fresh)&&verifyGen2SaveIntegrity(fresh).first}.getOrDefault(false)
            val recovery=if(!writeStarted)"Nothing was written to the save." else  if(restored)"The complete fresh working save was restored and verified." else  "Automatic restore could not be verified. Restore the retained recovery backup before continuing."
            showDialog("Gen 2 Day Care deposit failed","${e.message?:"Unknown error"}\n\n$recovery"+(safetyBackup?.let{"\n\nRecovery backup: "+it.name}?:""))
            return
        }
        Toast.makeText(this,"Verified initial Day Care parent deposited",Toast.LENGTH_LONG).show()
        showGen2DayCare()
    }

    private fun confirmGen2DayCareParentWithdrawal(parent:Gen2Pokemon,openedSource:ByteArray,openedProfile:Gen2Profile,openedFile:File,openedUri:Uri?,openedLabel:String?){
        fun bound()=importedFile?.absolutePath==openedFile.absolutePath&&currentSourceUri==openedUri&&currentSourceLabel==openedLabel
        if(!bound()){showDialog("Gen 2 Day Care","The active save identity changed. Reopen Day Care. Nothing was changed.");return}
        if(importedFile?.absolutePath!=openedFile.absolutePath){showDialog("Gen 2 Day Care","The active save changed. Reopen Day Care before withdrawing a parent. Nothing was changed.");return}
        if(parent.slot !in 0..1){showDialog("Gen 2 Day Care","Only an occupied parent slot can be withdrawn.");return}
        val openedDayCare=runCatching{gen2DayCareBytes(openedSource,openedProfile)}.getOrElse{showDialog("Gen 2 Day Care",it.message?:"The Day Care block could not be read.");return};val openedParty=runCatching{gen2LocationPayloads(openedSource,"Party",openedProfile)}.getOrElse{showDialog("Gen 2 Day Care",it.message?:"The party could not be read.");return};val openedState=runCatching{gen2DayCareState(openedSource,openedProfile)}.getOrElse{showDialog("Gen 2 Day Care",it.message?:"The Day Care state could not be read.");return}
        if(openedState.egg!=null){showDialog("Gen 2 Day Care","A pending Egg must be collected or declined in-game before a parent can be withdrawn. Nothing was changed.");return};if(openedParty.size>=6){showDialog("Gen 2 Day Care","The party is full. Nothing was changed.");return};val expectedPayload=runCatching{gen2DayCarePayload(openedSource,openedProfile,parent.slot)}.getOrElse{showDialog("Gen 2 Day Care",it.message?:"The parent record could not be prepared.");return}
        var withdrawalConsumed=false
        loadGen2PartyTransferMeta(listOf(parent)){metaMap->
            if(withdrawalConsumed)return@loadGen2PartyTransferMeta
            if(!bound()||!runCatching{openedFile.readBytes().contentEquals(openedSource)}.getOrDefault(false)){showDialog("Gen 2 Day Care","The active save changed while species data was loading. Nothing was changed.");return@loadGen2PartyTransferMeta}
            if(importedFile?.absolutePath!=openedFile.absolutePath){showDialog("Gen 2 Day Care","The active save changed while species data was loading. Nothing was changed.");return@loadGen2PartyTransferMeta}
            val meta=metaMap?.get(parent.species);if(!validGen2PartyTransferMeta(meta)){showDialog("Gen 2 Day Care","PSE could not load the verified species data needed to rebuild party battle stats. Nothing was changed.");return@loadGen2PartyTransferMeta}
            AlertDialog.Builder(this).setTitle("Withdraw ${parent.nickname.ifBlank{"Pokémon #${parent.species}"}}?").setMessage("PSE will copy the complete Day Care parent record into the party, rebuild valid battle stats, clear only that slot's occupied flag, verify every staged and persisted byte. A verified kept recovery backup is required before writing. If writing starts and then fails, PSE attempts and verifies a complete restore. An unverified restore requires restoring the retained backup.").setNegativeButton("Cancel",null).setPositiveButton("Withdraw"){_,_->
                if(withdrawalConsumed){showDialog("Gen 2 Day Care","This withdrawal was already submitted. Reopen Day Care before trying again.");return@setPositiveButton}
                withdrawalConsumed=true
                withdrawGen2DayCareParent(parent,openedSource,openedProfile,openedDayCare,openedParty,expectedPayload,requireNotNull(meta),openedFile,openedUri,openedLabel)
            }.show()
        }
    }

    private fun withdrawGen2DayCareParent(parent:Gen2Pokemon,openedSource:ByteArray,openedProfile:Gen2Profile,openedDayCare:ByteArray,openedParty:List<ByteArray>,expectedPayload:ByteArray,meta:Gen2SpeciesMeta,openedFile:File,openedUri:Uri?,openedLabel:String?){
        fun bound()=importedFile?.absolutePath==openedFile.absolutePath&&currentSourceUri==openedUri&&currentSourceLabel==openedLabel
        if(!bound()){showDialog("Gen 2 Day Care","The active save identity changed. Reopen Day Care. Nothing was changed.");return}
        if(importedFile?.absolutePath!=openedFile.absolutePath){showDialog("Gen 2 Day Care","The active save changed. Reopen Day Care before withdrawing a parent. Nothing was changed.");return}
        val file=openedFile;val fresh=runCatching{file.readBytes()}.getOrNull()?:return
        var writeStarted=false
        var safetyBackup:File?=null
        try{
            require(bound()&&verifyGen2SaveIntegrity(fresh).first){"The active save changed or failed full Gen 2 integrity validation."}
            require(fresh.contentEquals(openedSource)){"The Gen 2 save changed after the Day Care screen opened."};val profile=detectGen2Profile(fresh)?:error("The fresh Gen 2 save failed structural validation.");require(profile.key==openedProfile.key&&gen2ChecksumValid(fresh,profile)){"The Gen 2 profile or checksum changed."};require(gen2DayCareBytes(fresh,profile).contentEquals(openedDayCare)){"The Day Care state changed after confirmation."};val partyBefore=gen2LocationPayloads(fresh,"Party",profile);require(sameGen2PayloadList(partyBefore,openedParty)&&partyBefore.size<6){"The party changed or became full after confirmation."}
            val state=gen2DayCareState(fresh,profile);require(state.egg==null){"An Egg became pending after confirmation."};val live=if(parent.slot==0)state.firstParent else state.secondParent;require(live!=null&&sameGen2BankRecord(live,parent)){"The selected Day Care parent changed after confirmation."};require(gen2DayCarePayload(fresh,profile,parent.slot).contentEquals(expectedPayload)){"The exact Day Care parent payload changed after confirmation."};require(validGen2PartyTransferMeta(meta)&&meta.species==parent.species){"Verified species data is unavailable."}
            val work=fresh.copyOf();val addedSlot=appendGen2PartyPayload(work,expectedPayload,meta);val dayCareBase=gen2DayCareBase(profile);val flagOffset=dayCareBase+if(parent.slot==0)0 else 55;work[flagOffset]=(work[flagOffset].toInt()and 0xFE).toByte();work[dayCareBase]=(work[dayCareBase].toInt()and 0xDF).toByte();updateGen2PrimaryChecksum(work,profile)
            val partyBase=profile.partyOffset;val mons=partyBase+8;val ots=mons+6*48;val nicks=ots+6*11;val allowed=HashSet<Int>();allowed.add(partyBase);allowed.add(partyBase+1+partyBefore.size);allowed.add(partyBase+2+partyBefore.size);for(i in mons+partyBefore.size*48 until mons+(partyBefore.size+1)*48)allowed.add(i);for(i in ots+partyBefore.size*11 until ots+(partyBefore.size+1)*11)allowed.add(i);for(i in nicks+partyBefore.size*11 until nicks+(partyBefore.size+1)*11)allowed.add(i);allowed.add(flagOffset);allowed.add(dayCareBase);for(i in profile.checksumOffset..profile.checksumOffset+1)allowed.add(i);require(work.indices.all{it in allowed||work[it]==fresh[it]}){"The Day Care withdrawal changed unrelated save data."}
            val stagedProfile=detectGen2Profile(work)?:error("The staged Gen 2 save failed structural validation.");val stagedState=gen2DayCareState(work,stagedProfile);val stagedRemoved=if(parent.slot==0)stagedState.firstParent else stagedState.secondParent;val stagedOther=if(parent.slot==0)stagedState.secondParent else stagedState.firstParent;val originalOther=if(parent.slot==0)state.secondParent else state.firstParent;val sameOptional={a:Gen2Pokemon?,b:Gen2Pokemon?->(a==null&&b==null)||(a!=null&&b!=null&&sameGen2BankRecord(a,b))};require(stagedRemoved==null&&sameOptional(stagedOther,originalOther)&&stagedState.egg==null&&(stagedState.firstFlags and 0x20)==0&&stagedState.stepsUntilEgg==state.stepsUntilEgg&&stagedState.dittoParentState==state.dittoParentState){"The staged Day Care state did not preserve the other parent and counters while clearing compatibility."}
            val stagedPartyPayloads=gen2LocationPayloads(work,"Party",stagedProfile);val stagedParty=parseGen2Party(work,stagedProfile);require(stagedPartyPayloads.size==partyBefore.size+1&&sameGen2PayloadList(stagedPartyPayloads.take(partyBefore.size),partyBefore)){"An existing party record changed during withdrawal."};require(stagedParty.getOrNull(addedSlot)?.let{sameGen2BankRecord(it,parent)&&gen2DuplicateBoxPayload(stagedPartyPayloads[addedSlot],true).contentEquals(expectedPayload)&&verifyGen2PartyTransferStats(work,it,meta)}==true){"The staged parent record or rebuilt party stats did not verify."}
            require(verifyGen2SaveIntegrity(work).first){"The staged Day Care withdrawal failed full Gen 2 integrity validation."}
            require(importedFile?.absolutePath==openedFile.absolutePath&&file.readBytes().contentEquals(fresh)){"The Gen 2 source changed while the Day Care withdrawal was staged. Nothing was written."}
            val backup=File.createTempFile(backupGameName(file)+"_PreGen2DayCareWithdrawal_",".backup",backupsDir());safetyBackup=backup
            backup.writeBytes(fresh);require(backup.readBytes().contentEquals(fresh)){"The recovery backup did not verify exactly."}
            retainGen2SafetyBackup(backup,fresh)
            require(bound()&&isBackupKept(backup)&&backup.readBytes().contentEquals(fresh)&&file.readBytes().contentEquals(fresh)){"The active save or retained recovery backup changed before writing."}
            writeStarted=true
            file.writeBytes(work);val persisted=file.readBytes();require(persisted.contentEquals(work)){"The Gen 2 save changed while the Day Care withdrawal was written."};val persistedProfile=detectGen2Profile(persisted)?:error("The persisted Gen 2 save failed structural validation.");require(gen2DayCareBytes(persisted,persistedProfile).contentEquals(gen2DayCareBytes(work,stagedProfile))&&sameGen2PayloadList(gen2LocationPayloads(persisted,"Party",persistedProfile),stagedPartyPayloads)){"The persisted Day Care or party state did not match the staged transaction."};val persistedParent=parseGen2Party(persisted,persistedProfile).getOrNull(addedSlot);require(persistedParent!=null&&sameGen2BankRecord(persistedParent,parent)&&verifyGen2PartyTransferStats(persisted,persistedParent,meta)){"The persisted parent record or party stats did not verify."}
            require(bound()&&verifyGen2SaveIntegrity(persisted).first&&file.readBytes().contentEquals(work)){"The persisted withdrawal failed full integrity or final source verification."}
        }catch(e:Exception){
            val restored=writeStarted&&runCatching{file.writeBytes(fresh)}.isSuccess&&runCatching{file.readBytes().contentEquals(fresh)&&verifyGen2SaveIntegrity(fresh).first}.getOrDefault(false)
            val recovery=if(!writeStarted)"Nothing was written to the save." else  if(restored)"The complete fresh working save was restored and verified." else  "Automatic restore could not be verified. Restore the retained recovery backup before continuing."
            showDialog("Gen 2 Day Care withdrawal failed",(e.message?:"Unknown error")+"\n\n$recovery"+(safetyBackup?.let{"\n\nRecovery backup: "+it.name}?:""));return
        }
        Toast.makeText(this,"Day Care parent withdrawn and verified",Toast.LENGTH_LONG).show();showGen2DayCare()
    }

    private fun gen2DayCarePokemonSummary(p:Gen2Pokemon):String{
        val speciesName=GEN2_NATIONAL_NAMES.getOrElse(p.species-1){"Species #${p.species}"}
        val heldItem=if(p.heldItem==0)"None" else gen2HeldItemName(p.heldItem)?.let{"$it (#${p.heldItem})"}?:"Unknown / unverified (#${p.heldItem})"
        val pokerus=decodeGen2Pokerus(p.pokerus)?.let{details->when(details.status){"Active"->"Active • strain ${details.strain} • ${details.daysRemaining} day(s) remaining";"Cured / immune"->"Cured / immune • strain ${details.strain}";else->details.status}}?:"Unknown"
        val caught=decodeGen2CaughtData(p.caughtData)?.let{details->"${details.level} • ${details.time} • ${details.location} • OT ${details.otGender}"}?:"Not recorded"
        val gender=when{p.species in GEN2_GENDERLESS_SPECIES->"Genderless";gen2CanonicalGender(p)==1->"Male";gen2CanonicalGender(p)==0->"Female";else->"Unknown"}
        return "#${p.species.toString().padStart(3,'0')} $speciesName${if(p.isEgg)" • Egg" else ""}\nNickname: ${p.nickname} • OT: ${p.otName} • TID: ${p.tid}\n${if(p.isEgg)"Egg state: ${p.happiness} hatch cycle(s) remaining" else "Level: ${p.level} • EXP: ${p.experience} • Happiness: ${p.happiness}"}\nHeld item: $heldItem\nPokérus: $pokerus\nCaught/met: $caught\nDVs HP/Atk/Def/Spd/Spc: ${p.dvs.joinToString("/")} • $gender • ${if(p.shiny)"Shiny" else "Not shiny"}"
    }

    private fun showGen2DayCare(){
        val dayCareUri=currentSourceUri;val dayCareLabel=currentSourceLabel
        val file=importedFile?:return;val data=runCatching{file.readBytes()}.getOrNull()?:return
        val profile=detectGen2Profile(data)?:run{showDialog("Gen 2 Day Care","This viewer requires a structurally valid Pokémon Gold, Silver or Crystal save.");return}
        val state=runCatching{gen2DayCareState(data,profile)}.getOrElse{showDialog("Gen 2 Day Care",it.message?:"The Day Care state could not be read.");return}
        val root=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(dp(18),dp(36),dp(18),dp(24));setBackgroundColor(BG)}
        root.addView(TextView(this).apply{text="Gen 2 Day Care";textSize=28f;typeface=Typeface.DEFAULT_BOLD;setTextColor(TEXT)})
        root.addView(TextView(this).apply{text="${profile.displayName} • two parent slots and the pending Egg record";textSize=14f;setTextColor(MUTED);setPadding(0,dp(4),0,dp(14))})
        root.addView(TextView(this).apply{text="Parents: ${listOf(state.firstParent,state.secondParent).count{it!=null}} / 2    •    Egg available: ${if(state.egg!=null)"Yes" else "No"}    •    Steps counter: ${state.stepsUntilEgg}";textSize=14f;setTextColor(TEXT);setPadding(dp(4),dp(4),dp(4),dp(12))})
        fun addEntry(title:String,p:Gen2Pokemon?){
            val card=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;background=roundedBg(CARD,Color.rgb(20,95,135),14);setPadding(dp(12),dp(10),dp(12),dp(10))}
            card.addView(TextView(this).apply{text=title;textSize=18f;typeface=Typeface.DEFAULT_BOLD;setTextColor(TEXT)})
            if(p==null)card.addView(TextView(this).apply{text="Empty";textSize=14f;setTextColor(MUTED);setPadding(0,dp(4),0,0)}) else {
                card.addView(TextView(this).apply{text=gen2DayCarePokemonSummary(p);textSize=13f;setTextColor(TEXT);setPadding(0,dp(5),0,0)})
                if(!p.isEgg)addButton(card,"Withdraw Parent to Party"){confirmGen2DayCareParentWithdrawal(p,data,profile,file,dayCareUri,dayCareLabel)}
            }
            root.addView(card,LinearLayout.LayoutParams(-1,-2).apply{bottomMargin=dp(8)})
        }
        addEntry("Parent 1",state.firstParent);addEntry("Parent 2",state.secondParent);addEntry("Pending Egg",state.egg)
        if(state.firstParent==null&&state.secondParent==null&&state.egg==null){addButton(root,"Deposit initial parent into Parent 1"){confirmGen2DayCareFirstParentDeposit(data,profile,0,file,dayCareUri,dayCareLabel)};addButton(root,"Deposit initial parent into Parent 2"){confirmGen2DayCareFirstParentDeposit(data,profile,1,file,dayCareUri,dayCareLabel)}}
        else if(listOfNotNull(state.firstParent,state.secondParent).size==1&&state.egg==null&&(state.firstFlags and 0x60)==0){
            addButton(root,"Deposit second parent"){
                if(importedFile?.absolutePath!=file.absolutePath||currentSourceUri!=dayCareUri||currentSourceLabel!=dayCareLabel){showDialog("Gen 2 Day Care","The active save identity changed. Reopen Day Care. Nothing was changed.");return@addButton}
                confirmGen2DayCareBreedingDeposit(data,profile,file)
            }
            addButton(root,"Deposit verified non-breeding second parent"){confirmGen2DayCareNonBreedingSecondParentDeposit(data,profile,file,dayCareUri,dayCareLabel)}
        }
        if((state.firstFlags and 0x20)!=0)addMutedLine(root,"Breeding is active. Walk in the game to make the Egg ready and collect it from the Day Care man.")
        addMutedLine(root,"Deposit a second compatible parent to start normal breeding, including Ditto pairs. Generation 2 Egg Groups, gender and DV restrictions are checked locally. The game handles walking, parent growth and Egg readiness; collect Eggs in-game. Non-breeding pairs can also be deposited separately. Every deposit verifies both parents, the remaining party, checksum and persisted save, with rollback if a write fails.")
        addButton(root,"Back to Home"){showHome()};setContentView(ScrollView(this).apply{addView(root)});phoneBackAction={showHome()}
    }

    private fun gen1ReadName(data:ByteArray,off:Int,max:Int=7):String{
        val out=StringBuilder()
        for(i in 0 until max){val b=data.getOrNull(off+i)?.toInt()?.and(0xFF)?:break;if(b==0x50)break
            when{b in 0x80..0x99->out.append(('A'.code+b-0x80).toChar());b in 0xA0..0xB9->out.append(('a'.code+b-0xA0).toChar());b in 0xF6..0xFF->out.append(if(b==0xFF)' ' else ('0'.code+b-0xF6).toChar());else->out.append('?')}
        };return out.toString().trim()
    }
    private fun gen1EncodeName(name:String,max:Int=7):ByteArray{
        val out=ByteArray(max+1){0x50.toByte()};for((i,c) in name.take(max).withIndex()){out[i]=when(c){in 'A'..'Z'->(0x80+c.code-'A'.code).toByte();in 'a'..'z'->(0xA0+c.code-'a'.code).toByte();in '0'..'9'->(0xF6+c.code-'0'.code).toByte();' '->0x7F.toByte();else->0xE6.toByte()}};return out
    }
    private fun gen1BcdMoney(data:ByteArray):Int{val o=0x25F3;var n=0;for(i in 0..2){val b=data[o+i].toInt()and 0xFF;n=n*100+((b shr 4)*10+(b and 15))};return n}
    private fun gen1WriteBcdMoney(data:ByteArray,value:Int){val digits=value.coerceIn(0,999999).toString().padStart(6,'0');for(i in 0..2)data[0x25F3+i]=(((digits[i*2]-'0')*16)+(digits[i*2+1]-'0')).toByte()}
    private fun ensureGen1TrainerToolIntegrity(data:ByteArray,title:String):Boolean{
        val integrity=verifyGen1SaveIntegrity(data)
        if(!integrity.first){showDialog(title,integrity.second+" Nothing was changed.");return false}
        return true
    }
    private fun showGen1ProgressEditor(){
        val file=importedFile?:return;val data=runCatching{file.readBytes()}.getOrNull()?:return
        if(data.size!=0x8000){showDialog("Progress Editor","This editor is for Gen 1 Red / Blue / Yellow saves.");return}
        if(!hasValidGen1MainChecksum(data)){showDialog("Progress Editor","This editor requires a valid Gen 1 save checksum.");return}
        if(!ensureGen1TrainerToolIntegrity(data,"Progress Editor"))return
        val root=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(dp(18),dp(36),dp(18),dp(24));setBackgroundColor(BG)}
        root.addView(TextView(this).apply{text="Gen 1 Progress Editor";textSize=28f;typeface=Typeface.DEFAULT_BOLD;setTextColor(TEXT)})
        root.addView(TextView(this).apply{text="Safely edit a small set of well-understood progression values. Unknown story/event flags remain untouched.";textSize=14f;setTextColor(MUTED);setPadding(0,dp(4),0,dp(14))})
        val badges=data[0x2602].toInt()and 255
        root.addView(TextView(this).apply{text="Gym Badges";textSize=18f;typeface=Typeface.DEFAULT_BOLD;setTextColor(TEXT)})
        root.addView(TextView(this).apply{text="Current badge flags: ${Integer.bitCount(badges and 0xFF)} / 8\nToggle individual Kanto badges without changing unrelated event data.";textSize=13f;setTextColor(MUTED);setPadding(0,0,0,dp(6))})
        val names=arrayOf("Boulder","Cascade","Thunder","Rainbow","Soul","Marsh","Volcano","Earth");val checks=ArrayList<CheckBox>()
        for(i in 0..7){val c=CheckBox(this).apply{text=names[i]+" Badge";setTextColor(TEXT);isChecked=(badges and(1 shl i))!=0};checks.add(c);root.addView(c)}
        root.addView(TextView(this).apply{text="Badge presets";textSize=18f;typeface=Typeface.DEFAULT_BOLD;setTextColor(TEXT);setPadding(0,dp(12),0,dp(4))})
        root.addView(TextView(this).apply{text="Quickly select all badges or clear them before saving. These buttons only change the eight badge checkboxes above.";textSize=13f;setTextColor(MUTED);setPadding(0,0,0,dp(6))})
        val badgePresetRow=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL}
        badgePresetRow.addView(Button(this).apply{text="All 8";setAllCaps(false);setOnClickListener{for(c in checks)c.isChecked=true}},LinearLayout.LayoutParams(0,dp(48),1f))
        badgePresetRow.addView(Button(this).apply{text="Clear all";setAllCaps(false);setOnClickListener{for(c in checks)c.isChecked=false}},LinearLayout.LayoutParams(0,dp(48),1f))
        root.addView(badgePresetRow)
        root.addView(TextView(this).apply{text="Validated progression values";textSize=18f;typeface=Typeface.DEFAULT_BOLD;setTextColor(TEXT);setPadding(0,dp(14),0,dp(4))})
        root.addView(TextView(this).apply{text="Gym Badges are currently the only story-progression value enabled for writing. Trainer money, play time, Pokédex and Bag data are already handled by their dedicated verified editors. PSE will add another progression value here only after its exact Red/Blue/Yellow behavior is independently validated.";textSize=13f;setTextColor(MUTED);setPadding(0,0,0,dp(8))})
        root.addView(TextView(this).apply{text="Progress protection";textSize=18f;typeface=Typeface.DEFAULT_BOLD;setTextColor(TEXT);setPadding(0,dp(14),0,dp(4))})
        root.addView(TextView(this).apply{text="PSE deliberately does not expose raw event bytes, arbitrary map warps, or unknown story flags here. Those can strand a save or break progression. This screen only writes values PSE can validate safely.";textSize=13f;setTextColor(MUTED);setPadding(0,0,0,dp(10))})
        addButton(root,"Save Progress"){
            val original=runCatching{file.readBytes()}.getOrElse{showDialog("Progress edit failed","The fresh Gen 1 save could not be read. Nothing was changed.");return@addButton}
            try{
                val progressIntegrity=verifyGen1SaveIntegrity(original);require(progressIntegrity.first){progressIntegrity.second}
                require(original.size==SIZE_G1&&hasValidGen1MainChecksum(original)){"The fresh Gen 1 save is invalid."}
                require(original[0x2602]==data[0x2602]){"Badge data changed after this screen was opened. Reopen the editor and try again."}
                val work=original.copyOf()
                var b=0
                for(i in 0..7)if(checks[i].isChecked)b=b or(1 shl i)
                work[0x2602]=b.toByte()
                updateGen1MainChecksum(work)
                val pre=verifyGen1WriteState(work,null)
                require(pre.first){pre.second}
                file.writeBytes(work)
                val verify=file.readBytes()
                val post=verifyGen1WriteState(verify,null)
                require(post.first){post.second}
                require((verify[0x2602].toInt()and 255)==b)
                require(work.indices.all{it==0x2602||it==GEN1_CHECKSUM_OFFSET||work[it]==original[it]}){"The progress edit changed unrelated save data."}
                require(verify.contentEquals(work)){"The save changed while progress data was being written."}
                Toast.makeText(this,"Gen 1 progress updated and verified",Toast.LENGTH_LONG).show()
                showGen1ProgressEditor()
            }catch(e:Exception){
                runCatching{file.writeBytes(original)}
                showDialog("Progress edit failed",(e.message?:"Unknown error")+"\n\nThe fresh working save was restored.")
            }
        }
        addButton(root,"Back to Trainer Data"){showTrainerData()};setContentView(ScrollView(this).apply{addView(root)});phoneBackAction={showTrainerData()}
    }

    private fun showGen1DayCare(){
        val file=importedFile?:return;val data=runCatching{file.readBytes()}.getOrNull()?:return
        if(data.size!=0x8000){showDialog("Day Care","This viewer is for Gen 1 Red / Blue / Yellow saves.");return}
        if(!ensureGen1TrainerToolIntegrity(data,"Day Care"))return
        val root=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(dp(18),dp(36),dp(18),dp(24));setBackgroundColor(BG)}
        root.addView(TextView(this).apply{text="Gen 1 Day Care";textSize=28f;typeface=Typeface.DEFAULT_BOLD;setTextColor(TEXT)})
        root.addView(TextView(this).apply{text="Reads the game's dedicated Day Care slot directly. Red, Blue and Yellow use the same validated save layout for this data.";textSize=14f;setTextColor(MUTED);setPadding(0,dp(4),0,dp(14))})
        val inUse=(data[0x2CF4].toInt()and 255)==1
        if(!inUse){
            root.addView(TextView(this).apply{text="Day Care is empty";textSize=20f;typeface=Typeface.DEFAULT_BOLD;setTextColor(TEXT)})
            root.addView(TextView(this).apply{text="No Pokémon is currently deposited in the Gen 1 Day Care. You can safely deposit one party Pokémon here.";textSize=14f;setTextColor(MUTED);setPadding(0,dp(4),0,dp(12))})
            addButton(root,"Deposit Pokémon from Party"){
                val initial=runCatching{file.readBytes()}.getOrNull()?:return@addButton
                if(initial.size!=SIZE_G1||!hasValidGen1MainChecksum(initial)){showDialog("Day Care","The fresh Gen 1 save is invalid. Nothing was changed.");return@addButton}
                if((initial[0x2CF4].toInt() and 255)!=0){showDialog("Day Care","Day Care is already occupied. Nothing was changed.");return@addButton}
                val party=parseGen1Party(initial)
                if(party.size<=1){showDialog("Day Care","Generation 1 must keep at least one Pokémon in the party. Nothing was changed.");return@addButton}
                val labels=party.map{"${it.nickname.ifBlank{"Pokémon"}} • Lv ${it.level} • Party slot ${it.slot+1}"}.toTypedArray()
                AlertDialog.Builder(this).setTitle("Deposit which Pokémon?").setItems(labels){_,which->
                    val chosen=party[which];val fresh=runCatching{file.readBytes()}.getOrNull()?:return@setItems
                    try{
                        val dayCareDepositIntegrity=verifyGen1SaveIntegrity(fresh);require(dayCareDepositIntegrity.first){dayCareDepositIntegrity.second}
                        require(fresh.size==SIZE_G1&&hasValidGen1MainChecksum(fresh)){"The fresh Gen 1 save is invalid."}
                        require((fresh[0x2CF4].toInt() and 255)==0){"Day Care became occupied before the deposit."}
                        val before=parseGen1Party(fresh).sortedBy{it.slot};require(before.size>1){"Generation 1 must keep at least one Pokémon in the party."}
                        val selected=before.firstOrNull{it.slot==chosen.slot};require(selected!=null&&sameGen1TransferRecord(selected,chosen,true)){"The selected party Pokémon changed before the deposit."}
                        val expectedParty=before.filterNot{it.slot==selected.slot}
                        val payload=buildGen1BankPayload(fresh,selected,"Party • Slot ${selected.slot+1}",true);val o=GEN1_BANK_HEADER_SIZE;val work=fresh.copyOf()
                        val monRaw=payload.copyOfRange(o,o+GEN1_BOX_MON_SIZE);val otRaw=payload.copyOfRange(o+GEN1_BOX_MON_SIZE,o+GEN1_BOX_MON_SIZE+11);val nickRaw=payload.copyOfRange(o+GEN1_BOX_MON_SIZE+11,GEN1_BANK_FILE_SIZE)
                        java.util.Arrays.fill(work,0x2CF5,0x2D2C,0.toByte());nickRaw.copyInto(work,0x2CF5);otRaw.copyInto(work,0x2D00);monRaw.copyInto(work,0x2D0B);work[0x2CF4]=1
                        removeGen1PartySlot(work,selected.slot);updateGen1MainChecksum(work)
                        val stagedParty=parseGen1Party(work).sortedBy{it.slot};require(stagedParty.size==expectedParty.size&&stagedParty.zip(expectedParty).all{(a,b)->sameGen1TransferRecord(a,b,true)}){"A remaining party Pokémon changed during Day Care staging."}
                        require((work[0x2CF4].toInt() and 255)==1&&work.copyOfRange(0x2CF5,0x2D00).contentEquals(nickRaw)&&work.copyOfRange(0x2D00,0x2D0B).contentEquals(otRaw)&&work.copyOfRange(0x2D0B,0x2D2C).contentEquals(monRaw)){"The complete Day Care record did not verify during staging."}
                        val pre=verifyGen1WriteState(work,null);require(pre.first){pre.second};file.writeBytes(work)
                        val verify=file.readBytes();require(verify.contentEquals(work)){"The save changed while the Day Care deposit was being written."};val post=verifyGen1WriteState(verify,null);require(post.first){post.second}
                        val persistedParty=parseGen1Party(verify).sortedBy{it.slot};require(persistedParty.size==expectedParty.size&&persistedParty.zip(expectedParty).all{(a,b)->sameGen1TransferRecord(a,b,true)}){"A remaining party Pokémon changed after the Day Care deposit."}
                        require((verify[0x2CF4].toInt() and 255)==1&&verify.copyOfRange(0x2CF5,0x2D00).contentEquals(nickRaw)&&verify.copyOfRange(0x2D00,0x2D0B).contentEquals(otRaw)&&verify.copyOfRange(0x2D0B,0x2D2C).contentEquals(monRaw)){"The complete Day Care record changed after persistence."}
                        Toast.makeText(this,"${selected.nickname.ifBlank{"Pokémon"}} deposited in Day Care and verified",Toast.LENGTH_LONG).show();showGen1DayCare()
                    }catch(e:Exception){runCatching{file.writeBytes(fresh)};showDialog("Day Care deposit failed",(e.message?:"Unknown error")+"\n\nThe fresh working save was restored and no partial deposit was kept.")}
                }.setNegativeButton("Cancel",null).show()
            }
        }else{
            val nick=readGen1Text(data,0x2CF5,11).ifBlank{"(unnamed)"}
            val ot=readGen1Text(data,0x2D00,11).ifBlank{"(unknown)"}
            val mon=0x2D0B;val species=data[mon].toInt()and 255;val level=data[mon+3].toInt()and 255
            val tid=((data[mon+12].toInt()and 255) shl 8) or (data[mon+13].toInt()and 255)
            val exp=((data[mon+14].toInt()and 255) shl 16) or ((data[mon+15].toInt()and 255) shl 8) or (data[mon+16].toInt()and 255)
            val speciesName=gen1SpeciesNameFromInternal(species)
            root.addView(TextView(this).apply{text="$nick";textSize=22f;typeface=Typeface.DEFAULT_BOLD;setTextColor(TEXT)})
            addMutedLine(root,"$speciesName • Level $level")
            addMutedLine(root,"Original Trainer: $ot")
            addMutedLine(root,"Trainer ID: $tid")
            addMutedLine(root,"Experience: $exp")
            addButton(root,"Deposit Pokémon from Party"){showDialog("Day Care occupied","Gen 1 Day Care holds one Pokémon. Return this Pokémon to your party before depositing another.")}.isEnabled=false
            addMutedLine(root,"Return this Pokémon first to free the single Day Care slot.")
            root.addView(TextView(this).apply{text="Safe management";textSize=18f;typeface=Typeface.DEFAULT_BOLD;setTextColor(TEXT);setPadding(0,dp(16),0,dp(4))})
            root.addView(TextView(this).apply{text="PSE can return this Pokémon directly to the party when a slot is free. The original save is restored automatically if checksum, party count or read-back verification fails.";textSize=13f;setTextColor(MUTED);setPadding(0,0,0,dp(10))})
            addButton(root,"Return Pokémon to Party"){
                val initial=runCatching{file.readBytes()}.getOrNull()?:return@addButton
                if(initial.size!=SIZE_G1||!hasValidGen1MainChecksum(initial)){showDialog("Day Care","The fresh Gen 1 save is invalid. Nothing was changed.");return@addButton}
                if((initial[0x2CF4].toInt()and 255)!=1){showDialog("Day Care","Day Care is no longer occupied. Nothing was changed.");return@addButton}
                if(parseGen1Party(initial).size>=6){showDialog("Day Care","The party is full. Move a Pokémon to a PC Box first. Nothing was changed.");return@addButton}
                val initialNick=initial.copyOfRange(0x2CF5,0x2D00);val initialOt=initial.copyOfRange(0x2D00,0x2D0B);val initialMon=initial.copyOfRange(0x2D0B,0x2D2C)
                val internal=initialMon[0].toInt()and 255;val dex=gen1DexFromInternalIndex(internal)
                if(dex==null){showDialog("Day Care","The deposited Pokémon has an invalid Gen 1 species value. Nothing was changed.");return@addButton}
                loadGen1SpeciesMetaAsync(dex){meta->
                    if(meta==null){showDialog("Day Care","PSE could not load the species data needed to rebuild party stats. Nothing was changed.");return@loadGen1SpeciesMetaAsync}
                    val fresh=runCatching{file.readBytes()}.getOrNull()?:return@loadGen1SpeciesMetaAsync
                    try{
                        val dayCareWithdrawIntegrity=verifyGen1SaveIntegrity(fresh);require(dayCareWithdrawIntegrity.first){dayCareWithdrawIntegrity.second}
                        require(fresh.size==SIZE_G1&&hasValidGen1MainChecksum(fresh)){"The fresh Gen 1 save is invalid."}
                        require((fresh[0x2CF4].toInt()and 255)==1){"Day Care is no longer occupied."}
                        require(fresh.copyOfRange(0x2CF5,0x2D00).contentEquals(initialNick)&&fresh.copyOfRange(0x2D00,0x2D0B).contentEquals(initialOt)&&fresh.copyOfRange(0x2D0B,0x2D2C).contentEquals(initialMon)){"The Day Care Pokémon changed while species data was loading."}
                        val before=parseGen1Party(fresh).sortedBy{it.slot};require(before.size<6){"The party became full before withdrawal."}
                        val dMon=0x2D0B;val raw=fresh.copyOfRange(dMon,dMon+33);val work=fresh.copyOf();val level=work[dMon+3].toInt()and 255
                        val tid=((work[dMon+12].toInt()and 255)shl 8)or(work[dMon+13].toInt()and 255);val exp=((work[dMon+14].toInt()and 255)shl 16)or((work[dMon+15].toInt()and 255)shl 8)or(work[dMon+16].toInt()and 255)
                        val moves=IntArray(4){work[dMon+8+it].toInt()and 255};val pp=IntArray(4){work[dMon+29+it].toInt()and 0x3F};val ppUps=IntArray(4){(work[dMon+29+it].toInt() ushr 6)and 3};val dvs=gen1ReadDvs(work,dMon+27);val stat=IntArray(5){i->((work[dMon+17+i*2].toInt()and 255)shl 8)or(work[dMon+18+i*2].toInt()and 255)}
                        val stats=gen1CalculatedStats(meta,level,dvs,stat);val temp=Gen1Pokemon(slot=before.size,species=internal,nickname=readGen1Text(work,0x2CF5,11),otName=readGen1Text(work,0x2D00,11),level=level,currentHp=stats[0],maxHp=stats[0],moves=moves,movePP=pp,movePpUps=ppUps,experience=exp.toLong(),tid=tid,statExp=stat,dvs=dvs)
                        appendGen1PartyPokemon(work,raw,initialOt,initialNick,meta,temp);work[0x2CF4]=0;java.util.Arrays.fill(work,0x2CF5,0x2D2C,0.toByte());updateGen1MainChecksum(work)
                        val staged=parseGen1Party(work).sortedBy{it.slot};require(staged.size==before.size+1&&before.indices.all{sameGen1TransferRecord(staged[it],before[it],true)}&&sameGen1TransferRecord(staged.last(),temp,true)){"The exact Day Care withdrawal did not verify during staging."}
                        require((work[0x2CF4].toInt()and 255)==0&&work.copyOfRange(0x2CF5,0x2D2C).all{it.toInt()==0}){"The Day Care record did not clear completely."};val statsOk=verifyGen1PartyDerivedStats(work,before.size,meta);require(statsOk.first){statsOk.second}
                        val pre=verifyGen1WriteState(work,null);require(pre.first){pre.second};file.writeBytes(work)
                        val verify=file.readBytes();require(verify.contentEquals(work)){"The save changed while the Day Care withdrawal was being written."};val post=verifyGen1WriteState(verify,null);require(post.first){post.second}
                        val persisted=parseGen1Party(verify).sortedBy{it.slot};require(persisted.size==staged.size&&persisted.indices.all{sameGen1TransferRecord(persisted[it],staged[it],true)}){"The party changed after Day Care withdrawal persistence."};require((verify[0x2CF4].toInt()and 255)==0&&verify.copyOfRange(0x2CF5,0x2D2C).all{it.toInt()==0}){"The cleared Day Care record changed after persistence."}
                        Toast.makeText(this,"Day Care Pokémon returned to Party and verified",Toast.LENGTH_LONG).show();showGen1DayCare()
                    }catch(e:Exception){runCatching{file.writeBytes(fresh)};showDialog("Day Care withdrawal failed",(e.message?:"Unknown error")+"\n\nThe fresh working save was restored and no partial transfer was kept.")}
                }
            }
        }
        addButton(root,"Back to Trainer Data"){showTrainerData()};setContentView(ScrollView(this).apply{addView(root)});phoneBackAction={showTrainerData()}
    }

    private val GEN2_CRYSTAL_GS_BALL_OFFSETS = intArrayOf(0x3E3C, 0x3E44)
    private val GEN2_CRYSTAL_GS_BALL_AVAILABLE = 0x0B

    private fun gen2CrystalGsBallReady(data:ByteArray,profile:Gen2Profile):Boolean =
        profile.key=="C" && GEN2_CRYSTAL_GS_BALL_OFFSETS.all{(data[it].toInt() and 0xFF)==GEN2_CRYSTAL_GS_BALL_AVAILABLE}

    private fun enableGen2CrystalGsBall(file:File,opened:ByteArray,openedProfile:Gen2Profile,openedSource:Uri?,openedLabel:String?){
        fun bound()=importedFile?.absolutePath==file.absolutePath&&currentSourceUri==openedSource&&currentSourceLabel==openedLabel
        if(!bound())return showDialog("Crystal GS Ball","The active save identity changed. Reopen Events. Nothing was changed.")
        val fresh=runCatching{file.readBytes()}.getOrNull()
            ?:return showDialog("Crystal GS Ball","PSE could not re-read the working save. Nothing was changed.")
        var writeStarted=false
        var safetyBackup:File?=null
        try{
            require(bound()&&verifyGen2SaveIntegrity(fresh).first){"The confirmed source identity or complete Gen 2 save integrity changed."}
            require(fresh.contentEquals(opened)){"The working save changed after the Events screen opened."}
            val profile=detectGen2Profile(fresh)?:error("The fresh save no longer passes Gen 2 checksum and structure validation.")
            require(profile.key=="C"&&profile.key==openedProfile.key){"The GS Ball event state is only available for a verified Pokémon Crystal save."}
            if(gen2CrystalGsBallReady(fresh,profile)){showDialog("GS Ball already enabled","No save or backup was changed.");return}
            val checksumBefore=fresh.copyOfRange(profile.checksumOffset,profile.checksumOffset+2)
            val work=fresh.copyOf()
            GEN2_CRYSTAL_GS_BALL_OFFSETS.forEach{work[it]=GEN2_CRYSTAL_GS_BALL_AVAILABLE.toByte()}
            val allowed=GEN2_CRYSTAL_GS_BALL_OFFSETS.toSet()
            require(fresh.indices.all{it in allowed||fresh[it]==work[it]}){"An unrelated save byte changed while staging the GS Ball event state."}
            require(work.copyOfRange(profile.checksumOffset,profile.checksumOffset+2).contentEquals(checksumBefore)){"The primary checksum bytes changed even though the GS Ball event state is outside that checksum region."}
            val stagedProfile=detectGen2Profile(work)?:error("The staged Crystal save failed checksum or structure validation.")
            require(stagedProfile.key=="C"&&gen2CrystalGsBallReady(work,stagedProfile)){"The GS Ball event state did not stage exactly."}
            require(verifyGen2SaveIntegrity(work).first){"The complete staged Crystal save failed integrity validation."}
            require(bound()&&file.readBytes().contentEquals(fresh)){"The confirmed source or working save changed before backup. Nothing was written."}
            val backup=File.createTempFile(backupGameName(file)+"_PreCrystalGsBall_",".backup",backupsDir());safetyBackup=backup
            backup.writeBytes(fresh);require(backup.readBytes().contentEquals(fresh)){"The exact pre-edit recovery backup could not be verified."}
            retainGen2SafetyBackup(backup,fresh)
            require(bound()&&isBackupKept(backup)&&backup.readBytes().contentEquals(fresh)&&file.readBytes().contentEquals(fresh)){"The confirmed source or retained recovery backup changed before writing."}
            writeStarted=true
            file.writeBytes(work)
            val persisted=file.readBytes()
            require(persisted.contentEquals(work)){"The save changed while the GS Ball event state was written."}
            val persistedProfile=detectGen2Profile(persisted)?:error("The persisted Crystal save failed checksum or structure validation.")
            require(persistedProfile.key=="C"&&gen2CrystalGsBallReady(persisted,persistedProfile)){"The GS Ball event state did not persist after reopening."}
            require(bound()&&verifyGen2SaveIntegrity(persisted).first&&file.readBytes().contentEquals(work)){"The persisted source identity or complete Crystal save verification failed."}
        }catch(e:Exception){
            val restored=writeStarted&&runCatching{file.writeBytes(fresh);require(file.readBytes().contentEquals(fresh)&&verifyGen2SaveIntegrity(fresh).first)}.isSuccess
            val recovery=if(!writeStarted)"Nothing was written to the working save." else  if(restored)"The exact fresh working save was restored and verified." else  "Automatic restore could not be verified. Stop editing and restore the retained recovery backup."
            showDialog("GS Ball update failed",(e.message?:"Unknown error")+"\n\n"+recovery+(safetyBackup?.let{"\n\nRecovery backup: "+it.name}?:""));return
        }
        Toast.makeText(this,"Crystal GS Ball event state enabled and verified",Toast.LENGTH_LONG).show()
        showGen2Events()
    }

    private fun gen2CrystalCelebiRecord(data:ByteArray):Triple<ByteArray,ByteArray,ByteArray>{
        val raw=ByteArray(32)
        raw[0]=251.toByte()
        raw[1]=0
        intArrayOf(0xD7,0xDB,0xF6,0xF8).forEachIndexed{i,v->raw[2+i]=v.toByte()}
        writeU16BE(raw,6,readU16BE(data,0x2009))
        writeU24BE(raw,8,gen2ExperienceForLevel("GROWTH_MEDIUM_SLOW",30))
        raw[21]=0x9A.toByte();raw[22]=0xAA.toByte()
        intArrayOf(5,25,5,15).forEachIndexed{i,v->raw[23+i]=v.toByte()}
        raw[27]=70;raw[28]=0
        raw[29]=0x9E.toByte()
        val femaleTrainer=(data[0x3E3D].toInt() and 0xFF)==1
        raw[30]=(0x0E or if(femaleTrainer)0x80 else 0).toByte()
        raw[31]=30
        return Triple(raw,data.copyOfRange(0x200B,0x2016),gen1EncodeName("CELEBI",10))
    }

    private fun isExactGen2CrystalCelebi(p:Gen2Pokemon,data:ByteArray):Boolean{
        val expectedCaught=0x9E00 or 0x0E or if((data[0x3E3D].toInt() and 0xFF)==1)0x80 else 0
        return p.species==251&&p.nickname=="CELEBI"&&p.otName==readGen1Text(data,0x200B,11)&&
            p.tid==readU16BE(data,0x2009)&&p.level==30&&p.heldItem==0&&
            p.experience==gen2ExperienceForLevel("GROWTH_MEDIUM_SLOW",30)&&
            p.moves.contentEquals(intArrayOf(0xD7,0xDB,0xF6,0xF8))&&
            p.movePP.contentEquals(intArrayOf(5,25,5,15))&&p.statExp.all{it==0}&&
            p.happiness==70&&p.pokerus==0&&p.caughtData==expectedCaught&&
            p.dvs.contentEquals(intArrayOf(8,9,10,10,10))&&!p.shiny&&!p.isEgg
    }

    private fun chooseGen2EventBox(data:ByteArray,done:(Int)->Unit){
        val profile=detectGen2Profile(data)?:return showDialog("Gen 2 Events","The loaded save no longer passes Gen 2 checksum and structure validation.")
        val choices=(1..14).mapNotNull{box->
            val count=data[gen2BoxOffset(box)].toInt() and 0xFF
            if(count in 0 until 20)"PC Box $box • ${20-count} empty" to box else null
        }
        if(choices.isEmpty())return showDialog("Gen 2 Events","All 14 initialized Gen 2 PC boxes are full. Nothing was changed.")
        if(profile.key !in setOf("GS","C"))return showDialog("Gen 2 Events","This save profile is not supported.")
        AlertDialog.Builder(this).setTitle("Store Gen 2 event Pokémon where?")
            .setItems(choices.map{it.first}.toTypedArray()){_,which->done(choices[which].second)}
            .setNegativeButton("Cancel",null).show()
    }

    private fun injectGen2CrystalCelebi(file:File,opened:ByteArray,openedProfile:Gen2Profile,box:Int,openedSource:Uri?,openedLabel:String?){
        fun bound()=importedFile?.absolutePath==file.absolutePath&&currentSourceUri==openedSource&&currentSourceLabel==openedLabel
        if(!bound())return showDialog("Crystal Celebi","The active save identity changed. Reopen Events. Nothing was changed.")
        val fresh=runCatching{file.readBytes()}.getOrNull()
            ?:return showDialog("Crystal Celebi","PSE could not re-read the working save. Nothing was changed.")
        var writeStarted=false
        var safetyBackup:File?=null
        try{
            require(bound()&&verifyGen2SaveIntegrity(fresh).first){"The active save changed or failed full Gen 2 integrity validation."}
            require(fresh.contentEquals(opened)){"The working save changed after the Events screen opened."}
            val profile=detectGen2Profile(fresh)?:error("The fresh save no longer passes Gen 2 checksum and structure validation.")
            require(profile.key=="C"&&profile.key==openedProfile.key){"Crystal Celebi injection requires a verified Pokémon Crystal save."}
            require(box in 1..14){"The selected PC box is invalid."}
            val before=gen2LocationPayloads(fresh,"Box $box",profile)
            require(before.size<20){"PC Box $box became full before injection."}
            val work=fresh.copyOf();val(raw,ot,nick)=gen2CrystalCelebiRecord(fresh)
            val slot=appendGen2BoxPokemon(work,box,raw,ot,nick)
            markGen2PokedexOwnedSeen(work,profile,251)
            updateGen2PrimaryChecksum(work,profile)

            val base=gen2BoxOffset(box);val mons=base+22;val ots=mons+20*32;val nicks=ots+20*11
            val(owned,seen)=gen2PokedexBases(profile);val dexByte=(251-1)/8
            val allowed=mutableSetOf(base,base+1+before.size,base+1+before.size+1,owned+dexByte,seen+dexByte,profile.checksumOffset,profile.checksumOffset+1)
            for(i in 0 until 32)allowed.add(mons+slot*32+i)
            for(i in 0 until 11){allowed.add(ots+slot*11+i);allowed.add(nicks+slot*11+i)}
            require(fresh.indices.all{it in allowed||fresh[it]==work[it]}){"An unrelated byte changed while staging Crystal Celebi."}

            val stagedProfile=detectGen2Profile(work)?:error("The staged Crystal save failed checksum or structure validation.")
            val stagedPayloads=gen2LocationPayloads(work,"Box $box",stagedProfile)
            require(stagedPayloads.size==before.size+1&&sameGen2PayloadList(stagedPayloads.take(before.size),before)){"Existing PC box records changed during Celebi staging."}
            val staged=parseGen2Box(work,box).firstOrNull{it.slot==slot}
            require(staged!=null&&isExactGen2CrystalCelebi(staged,work)){"The staged Celebi did not match the deterministic Crystal event template."}
            require(gen2PokedexOwnedSeen(work,stagedProfile,251)){"Celebi was not staged as Seen and Owned."}

            require(verifyGen2SaveIntegrity(work).first){"The staged Crystal save failed full Gen 2 integrity validation."}
            require(bound()&&file.readBytes().contentEquals(fresh)){"The active save changed before backup creation. Nothing was written."}
            val backup=File.createTempFile(backupGameName(file)+"_PreCrystalCelebi_",".backup",backupsDir());safetyBackup=backup
            backup.writeBytes(fresh);require(backup.readBytes().contentEquals(fresh)){"The recovery backup did not verify exactly."}
            retainGen2SafetyBackup(backup,fresh)
            require(bound()&&isBackupKept(backup)&&backup.readBytes().contentEquals(fresh)&&file.readBytes().contentEquals(fresh)){"The active save or retained recovery backup changed before writing."}
            writeStarted=true
            file.writeBytes(work)
            val persisted=file.readBytes()
            require(persisted.contentEquals(work)){"The save changed while Crystal Celebi was written."}
            val persistedProfile=detectGen2Profile(persisted)?:error("The persisted Crystal save failed checksum or structure validation.")
            val persistedPayloads=gen2LocationPayloads(persisted,"Box $box",persistedProfile)
            require(sameGen2PayloadList(persistedPayloads,stagedPayloads)){"The PC box changed after reopening the save."}
            val saved=parseGen2Box(persisted,box).firstOrNull{it.slot==slot}
            require(saved!=null&&isExactGen2CrystalCelebi(saved,persisted)&&gen2PokedexOwnedSeen(persisted,persistedProfile,251)){"Crystal Celebi or its Pokédex registration did not persist exactly."}
            require(bound()&&verifyGen2SaveIntegrity(persisted).first&&file.readBytes().contentEquals(work)){"The persisted save failed full integrity or final source verification."}
        }catch(e:Exception){
            val restored=writeStarted&&runCatching{file.writeBytes(fresh);require(file.readBytes().contentEquals(fresh)&&verifyGen2SaveIntegrity(fresh).first)}.isSuccess
            val recovery=if(!writeStarted)"Nothing was written to the working save." else  if(restored)"The exact fresh working save was restored and verified; no partial Pokémon or Pokédex update was kept." else  "Automatic restore could not be verified. Restore the retained recovery backup before continuing."
            showDialog("Celebi injection failed",(e.message?:"Unknown error")+"\n\n"+recovery+(safetyBackup?.let{"\n\nRecovery backup: "+it.name}?:""));return
        }
        Toast.makeText(this,"Crystal Celebi injected and verified in PC Box $box",Toast.LENGTH_LONG).show()
        showGen2Events()
    }

    private data class Gen2ArchivedEvent(val label:String,val source:String,val marker:Int,val payload:ByteArray){
        val species:Int get()=payload[0].toInt() and 0xFF
        val isEgg:Boolean get()=marker==0xFD
    }
    private val gen2ArchivedEvents:List<Gen2ArchivedEvent> by lazy {
        val rows=JSONArray(assets.open("gen2_archived_events.json").bufferedReader(Charsets.UTF_8).use{it.readText()})
        (0 until rows.length()).map{index->
            val row=rows.getJSONObject(index);val hex=row.getString("payload")
            require(hex.length==108&&hex.all{it in "0123456789abcdef"}){"An archived event record is malformed."}
            val payload=ByteArray(54){hex.substring(it*2,it*2+2).toInt(16).toByte()}
            val event=Gen2ArchivedEvent(row.getString("label"),row.getString("source"),row.getInt("marker"),payload)
            require(event.species in 1..251&&(event.marker==event.species||event.isEgg)){"An archived species or Egg marker is invalid."}
            event
        }
    }

    private fun addGen2EventCard(root:LinearLayout,label:String,eventSpecies:Int,shiny:Boolean,action:()->Unit){
        val card=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL;gravity=Gravity.CENTER_VERTICAL;setPadding(dp(8),dp(8),dp(8),0);background=roundedBg(CARD,Color.rgb(42,83,105),12)}
        val sprite=ImageView(this).apply{scaleType=ImageView.ScaleType.FIT_CENTER;contentDescription=label}
        card.addView(sprite,LinearLayout.LayoutParams(dp(56),dp(56)))
        loadPokemonSprite(sprite,eventSpecies,shiny)
        val details=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL}
        card.addView(details,LinearLayout.LayoutParams(0,-2,1f))
        root.addView(card,LinearLayout.LayoutParams(-1,-2).apply{bottomMargin=dp(10)})
        addButton(details,label){EventScreenBoundary.open(action){reportGen2EventError(it)}}.apply{minHeight=dp(56);layoutParams.height=-2}
    }

    private fun reportGen2EventError(error:Exception){
        android.util.Log.e("PSEEvents","Gen 2 Events operation failed",error)
        val detail=EventScreenBoundary.diagnostic(error)
        getSharedPreferences("pse_diagnostics",MODE_PRIVATE).edit().putString("last_gen2_events_error",detail).apply()
        showDialog("Gen 2 Events operation failed","No event was injected.\n\n"+detail)
    }

    private fun injectGen2ArchivedEvent(file:File,opened:ByteArray,openedProfile:Gen2Profile,box:Int,event:Gen2ArchivedEvent,openedSource:Uri?,openedLabel:String?){
        fun bound()=importedFile?.absolutePath==file.absolutePath&&currentSourceUri==openedSource&&currentSourceLabel==openedLabel
        if(!bound())return showDialog("Gen 2 event","The active save identity changed. Reopen Events. Nothing was changed.")
        val fresh=runCatching{file.readBytes()}.getOrNull()
            ?:return showDialog("Gen 2 event","PSE could not read the working save. Nothing was changed.")
        var writeStarted=false
        var safetyBackup:File?=null
        try{
            require(bound()&&verifyGen2SaveIntegrity(fresh).first){"The active save changed or failed full Gen 2 integrity validation."}
            require(importedFile?.absolutePath==file.absolutePath&&fresh.contentEquals(opened)){"The active save changed after confirmation."}
            val profile=detectGen2Profile(fresh)?:error("The fresh Gen 2 save failed checksum or structure validation.")
            require(profile.key==openedProfile.key&&profile.key in setOf("GS","C")){"The destination game profile changed or is unsupported."}
            require(box in 1..14){"The selected PC box is invalid."}
            val before=gen2LocationPayloads(fresh,"Box $box",profile)
            require(before.size<20){"The destination box is full. Nothing was changed."}
            val payload=event.payload.copyOf()
            require(payload.size==54){"The archived event record is incomplete."}
            val species=payload[0].toInt() and 0xFF
            val isEgg=event.marker==0xFD
            require(species in 1..251&&(event.marker==species||isEgg)){"The archived species or Egg marker is invalid."}
            val work=fresh.copyOf()
            val slot=appendGen2BoxPokemon(work,box,payload.copyOfRange(0,32),payload.copyOfRange(32,43),payload.copyOfRange(43,54))
            val boxBase=gen2BoxOffset(box)
            work[boxBase+1+slot]=event.marker.toByte()
            if(!isEgg)markGen2PokedexOwnedSeen(work,profile,species)
            updateGen2PrimaryChecksum(work,profile)
            val base=gen2BoxOffset(box);val mons=base+22;val ots=mons+20*32;val nicks=ots+20*11
            val(owned,seen)=gen2PokedexBases(profile);val dexByte=(species-1)/8
            val allowed=mutableSetOf(base,base+1+before.size,base+2+before.size,profile.checksumOffset,profile.checksumOffset+1)
            if(!isEgg){allowed.add(owned+dexByte);allowed.add(seen+dexByte)}
            for(i in 0 until 32)allowed.add(mons+slot*32+i)
            for(i in 0 until 11){allowed.add(ots+slot*11+i);allowed.add(nicks+slot*11+i)}
            require(fresh.indices.all{it in allowed||fresh[it]==work[it]}){"The event changed unrelated save bytes."}
            fun verify(bytes:ByteArray){
                require(bound()&&verifyGen2SaveIntegrity(bytes).first){"The event save failed full integrity or source identity verification."}
                val checked=detectGen2Profile(bytes)?:error("Event save failed checksum or structure validation.")
                require(checked.key==profile.key){"The event changed game identity."}
                val after=gen2LocationPayloads(bytes,"Box $box",checked)
                require(after.size==before.size+1&&sameGen2PayloadList(after.take(before.size),before)){"Existing Pokemon changed during event injection."}
                require(bytes.copyOfRange(mons+slot*32,mons+slot*32+32).contentEquals(payload.copyOfRange(0,32))&&
                    bytes.copyOfRange(ots+slot*11,ots+slot*11+11).contentEquals(payload.copyOfRange(32,43))&&
                    bytes.copyOfRange(nicks+slot*11,nicks+slot*11+11).contentEquals(payload.copyOfRange(43,54))){"The archived event data did not verify exactly."}
                require((bytes[base+1+slot].toInt() and 0xFF)==event.marker){"The event Egg marker did not persist."}
                if(!isEgg)require(gen2PokedexOwnedSeen(bytes,checked,species)){"Event Pokédex registration did not verify."}
            }
            verify(work)
            require(importedFile?.absolutePath==file.absolutePath&&file.readBytes().contentEquals(fresh)){"The save changed before writing. Nothing was changed."}
            val backup=File.createTempFile(backupGameName(file)+"_PreGen2ArchivedEvent_",".backup",backupsDir());safetyBackup=backup
            backup.writeBytes(fresh);require(backup.readBytes().contentEquals(fresh)){"The recovery backup did not verify exactly."}
            retainGen2SafetyBackup(backup,fresh)
            require(bound()&&isBackupKept(backup)&&backup.readBytes().contentEquals(fresh)&&file.readBytes().contentEquals(fresh)){"The active save or retained recovery backup changed before writing."}
            writeStarted=true;file.writeBytes(work)
            val persisted=file.readBytes();require(persisted.contentEquals(work)){"The event write did not persist exactly."};verify(persisted)
            require(bound()&&verifyGen2SaveIntegrity(persisted).first&&file.readBytes().contentEquals(work)){"The persisted event failed full integrity or final source verification."}
        }catch(e:Exception){
            val restored=if(writeStarted)runCatching{file.writeBytes(fresh);require(file.readBytes().contentEquals(fresh)&&verifyGen2SaveIntegrity(fresh).first)}.isSuccess else false
            val recovery=if(!writeStarted)"Nothing was written to the working save." else  if(restored)"The exact fresh working save was restored and verified; no partial event or Pokédex update was kept." else  "Automatic restore could not be verified. Restore the retained recovery backup before continuing."
            showDialog("Gen 2 event injection failed",(e.message?:"Unknown error")+"\n\n"+recovery+(safetyBackup?.let{"\n\nRecovery backup: "+it.name}?:""));return
        }
        Toast.makeText(this,"${event.label} injected and verified in PC Box $box",Toast.LENGTH_LONG).show()
        showGen2Events()
    }

    private fun showGen2Events(){
        EventScreenBoundary.open({renderGen2Events()}){error->
            android.util.Log.e("PSEEvents","Opening Gen 2 Events failed",error)
            val detail=EventScreenBoundary.diagnostic(error)
            getSharedPreferences("pse_diagnostics",MODE_PRIVATE).edit()
                .putString("last_gen2_events_error",detail).apply()
            showDialog("Gen 2 Events could not open",
                "No save data was changed. Please send this error detail so the failing Events operation can be corrected.\n\n"+detail)
        }
    }

    private fun renderGen2Events(){
        val eventsSource=currentSourceUri;val eventsLabel=currentSourceLabel
        val file=importedFile?:return
        val data=runCatching{file.readBytes()}.getOrNull()
            ?:return showDialog("Gen 2 Events","PSE could not read the loaded save.")
        val profile=detectGen2Profile(data)
            ?:return showDialog("Gen 2 Events","Gen 2 Events requires a valid Gold, Silver or Crystal save checksum and structure.")
        fun verifiedEventsSource():Boolean {
            if(gen2ListSnapshotMatches(file,data,eventsSource,eventsLabel))return true
            showDialog("Gen 2 Events","The save identity, bytes or integrity changed while Events was open. Reopen Events. Nothing was changed.");return false
        }
        val root=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(dp(18),dp(36),dp(18),dp(24));setBackgroundColor(BG)}
        root.addView(TextView(this).apply{text="Gen 2 Events";textSize=28f;typeface=Typeface.DEFAULT_BOLD;setTextColor(TEXT)})
        root.addView(TextView(this).apply{text="${profile.displayName}\nThis catalog is dispatched through generation-specific Gen 2 save logic. Gen 1 event offsets and checksums are never used.";textSize=14f;setTextColor(MUTED);setPadding(0,dp(4),0,dp(14))})
        if(profile.key=="C"){
            fun gsBallBound()=importedFile?.absolutePath==file.absolutePath&&currentSourceUri==eventsSource&&currentSourceLabel==eventsLabel
            var gsBallConsumed=false
            root.addView(TextView(this).apply{text="Crystal GS Ball event state";textSize=19f;typeface=Typeface.DEFAULT_BOLD;setTextColor(TEXT);setPadding(0,dp(6),0,dp(4))})
            root.addView(TextView(this).apply{text="${if(gen2CrystalGsBallReady(data,profile))"Ready" else "Not enabled"} • sets both documented Crystal GS Ball event flags to 0x0B. This enables the in-game Goldenrod/Kurt/Ilex Forest sequence without guessing any other state.";textSize=14f;setTextColor(MUTED);setPadding(0,0,0,dp(8))})
            if(!gen2CrystalGsBallReady(data,profile))addButton(root,"🔮  Enable Crystal GS Ball event"){
                if(!verifiedEventsSource())return@addButton
                if(!gsBallBound()){showDialog("Crystal GS Ball","The active save identity changed. Reopen Events. Nothing was changed.");return@addButton}
                AlertDialog.Builder(this).setTitle("Enable Crystal GS Ball event?")
                    .setMessage("PSE will set only the two documented Pokémon Crystal GS Ball availability bytes. A verified kept recovery backup is required before writing. PSE verifies the complete save and exact persisted flags; if writing starts and then fails, PSE attempts and verifies a complete restore. An unverified restore requires restoring the retained backup.")
                    .setNegativeButton("Cancel",null).setPositiveButton("Enable Event"){_,_->
                        if(gsBallConsumed){showDialog("Crystal GS Ball","This event edit was already submitted. Reopen Events before trying again.");return@setPositiveButton}
                        gsBallConsumed=true
                        enableGen2CrystalGsBall(file,data,profile,eventsSource,eventsLabel)
                    }.show()
            }
            root.addView(TextView(this).apply{text="Crystal Ilex Forest Celebi";textSize=19f;typeface=Typeface.DEFAULT_BOLD;setTextColor(TEXT);setPadding(0,dp(16),0,dp(4))})
            root.addView(TextView(this).apply{text="Level 30 • Heal Bell / Safeguard / AncientPower / Future Sight • Ilex Forest caught data • player OT and Trainer ID • no item, Mail or Pokérus. Uses fixed legal non-shiny DVs and registers Celebi Seen and Owned.";textSize=14f;setTextColor(MUTED);setPadding(0,0,0,dp(8))})
            fun celebiBound()=importedFile?.absolutePath==file.absolutePath&&currentSourceUri==eventsSource&&currentSourceLabel==eventsLabel
            var celebiConsumed=false
            addGen2EventCard(root,"🎁  Inject Crystal Celebi",251,false){
                if(!verifiedEventsSource())return@addGen2EventCard
                if(!celebiBound()){showDialog("Crystal Celebi","The active save identity changed. Reopen Events. Nothing was changed.");return@addGen2EventCard}
                val fresh=runCatching{file.readBytes()}.getOrNull()
                if(fresh==null){showDialog("Crystal Celebi","PSE could not re-read the working save.");return@addGen2EventCard}
                val freshProfile=detectGen2Profile(fresh)
                if(freshProfile==null||freshProfile.key!="C"){showDialog("Crystal Celebi","The working save is no longer a valid Pokémon Crystal save.");return@addGen2EventCard}
                if(!verifyGen2SaveIntegrity(fresh).first){showDialog("Crystal Celebi","The working save failed full Gen 2 integrity validation. Nothing was changed.");return@addGen2EventCard}
                chooseGen2EventBox(fresh){box->
                    if(!celebiBound()||!runCatching{file.readBytes().contentEquals(fresh)}.getOrDefault(false)){showDialog("Crystal Celebi","The active save changed while choosing a box. Reopen Events. Nothing was changed.");return@chooseGen2EventBox}
                    AlertDialog.Builder(this).setTitle("Inject deterministic Crystal Celebi?")
                        .setMessage("PSE will add the level 30 Ilex Forest Celebi representation to PC Box $box, update Seen/Owned, rebuild the Crystal checksum, and re-read every stored event field. Existing Pokémon and unrelated bytes must remain exact. A verified kept recovery backup is required before writing. If writing starts and then fails, PSE attempts and verifies a complete restore. An unverified restore requires restoring the retained backup.\n\nThis creates a legal destination-save representation; it does not claim the Pokémon came from original distribution hardware.")
                        .setNegativeButton("Cancel",null).setPositiveButton("Inject Event"){_,_->
                            if(celebiConsumed){showDialog("Crystal Celebi","This event injection was already submitted. Reopen Events before trying again.");return@setPositiveButton}
                            celebiConsumed=true
                            injectGen2CrystalCelebi(file,fresh,freshProfile,box,eventsSource,eventsLabel)
                        }.show()
                }
            }
        }else{
            root.addView(TextView(this).apply{text="Gold / Silver event catalog";textSize=19f;typeface=Typeface.DEFAULT_BOLD;setTextColor(TEXT);setPadding(0,dp(6),0,dp(4))})
            root.addView(TextView(this).apply{text="This is the genuine Generation 2 Gold / Silver Events path. Crystal's GS Ball state and Ilex Forest Celebi encounter are not present in these titles, so PSE does not write Crystal-only flags or invent unsupported event data. Verified English distribution samples are listed below.";textSize=14f;setTextColor(MUTED);setPadding(0,0,0,dp(8))})
        }
        root.addView(TextView(this).apply{text="Archived Generation 2 distributions";textSize=19f;typeface=Typeface.DEFAULT_BOLD;setTextColor(TEXT);setPadding(0,dp(16),0,dp(4))})
        addMutedLine(root,"English archive samples for Western Gold/Silver/Crystal. Includes distribution Pokémon, event Eggs and archived hatched examples. These are copies of documented records, not proof of event attendance or a complete worldwide catalogue. Egg injections preserve the Egg marker and do not register the Pokédex until hatching.")
        fun archivedBound()=importedFile?.absolutePath==file.absolutePath&&currentSourceUri==eventsSource&&currentSourceLabel==eventsLabel
        var archivedConsumed=false
        for(event in gen2ArchivedEvents){
            val archivedHatch=event.source.contains("/Hatched/")
            val kind=if(event.isEgg)"Event Egg" else if(archivedHatch)"Archived hatch" else "Distribution Pokémon"
            val shiny=gen2Shiny(gen2Dvs(event.payload,21))
            addGen2EventCard(root,"🎁  ${event.label}\n$kind",event.species,shiny){
                if(!verifiedEventsSource())return@addGen2EventCard
                if(!archivedBound()){showDialog("Gen 2 event","The active save changed. Reopen Events.");return@addGen2EventCard}
                val fresh=runCatching{file.readBytes()}.getOrNull()
                val freshProfile=fresh?.let{detectGen2Profile(it)}
                if(fresh==null||freshProfile==null||freshProfile.key!=profile.key){showDialog("Gen 2 event","The working save changed or is invalid. Reopen Events.");return@addGen2EventCard}
                if(!verifyGen2SaveIntegrity(fresh).first){showDialog("Gen 2 event","The working save failed full Gen 2 integrity validation. Nothing was changed.");return@addGen2EventCard}
                chooseGen2EventBox(fresh){box->
                    if(!archivedBound()||!runCatching{file.readBytes().contentEquals(fresh)}.getOrDefault(false)){showDialog("Gen 2 event","The active save changed while choosing a box. Reopen Events. Nothing was changed.");return@chooseGen2EventBox}
                    EventScreenBoundary.open({
                        AlertDialog.Builder(this).setTitle("Inject archived Gen 2 event?")
                            .setMessage("${event.label}\n\n$kind • PC Box $box\n\nCopies the exact archived identity, moves and DVs. Existing Pokémon and unrelated save data must remain unchanged. This does not enable Crystal-only story flags. A verified kept recovery backup is required before writing. If writing starts and then fails, PSE attempts and verifies a complete restore. An unverified restore requires restoring the retained backup.")
                            .setNegativeButton("Cancel",null).setPositiveButton("Inject Event"){_,_->
                                if(archivedConsumed){showDialog("Gen 2 event","An archived event injection was already submitted. Reopen Events before trying again.");return@setPositiveButton}
                                archivedConsumed=true
                                injectGen2ArchivedEvent(file,fresh,freshProfile,box,event,eventsSource,eventsLabel)
                            }.show()
                    }){reportGen2EventError(it)}
                }
            }
        }
        addButton(root,"Back to Home"){showHome()}
        setContentView(ScrollView(this).apply{addView(root)});phoneBackAction={showHome()}
    }

    private fun chooseGen1EventDestination(data:ByteArray,title:String,done:(Int?)->Unit){
        if(!ensureGen1TrainerToolIntegrity(data,title))return
        val choices=ArrayList<Pair<String,Int?>>()
        if(parseGen1Party(data).size<6) choices.add("Party • next empty slot" to null)
        for((box,empty) in availableGen1BoxTargets(data)) if(empty>0) choices.add("PC Box $box • $empty empty" to box)
        if(choices.isEmpty()){showDialog(title,"There is no safe destination with an empty slot. Free a party slot or space in an initialized PC box first.");return}
        AlertDialog.Builder(this).setTitle("Store event Pokémon where?").setItems(choices.map{it.first}.toTypedArray()){_,which->done(choices[which].second)}.setNegativeButton("Cancel",null).show()
    }

    private fun appendGen1EventToBox(data:ByteArray,box:Int,raw:ByteArray,ot:ByteArray,nick:ByteArray):Int{
        require(gen1BoxIsWritable(data,box)){"Box $box is not initialized or writable."}
        val before=parseGen1Box(data,box).pokemon.size
        require(before<GEN1_BOX_CAPACITY){"Box $box is full."}
        appendGen1BoxPokemon(data,box,raw,ot,nick)
        return before
    }

    private fun showGen1Events(){
        val file=importedFile?:return;val data=runCatching{file.readBytes()}.getOrNull()?:return
        if(data.size!=0x8000){showDialog("Events","Gen 1 Events currently supports Red / Blue / Yellow saves.");return}
