        root.addView(TextView(this).apply{text="North American tour • OT YOSHIRA • Pound";textSize=14f;setTextColor(MUTED);setPadding(0,0,0,dp(8))})
        addButton(root,"YOSHIRA Mew • Lv.5",151){
            val fresh=runCatching{file.readBytes()}.getOrNull()?:return@addButton
            val tid=(1..65535).random()
            chooseGen1EventDestination(fresh,"Event Mew"){destinationBox->
            AlertDialog.Builder(this).setTitle("Inject documented YOSHIRA Mew?").setMessage("PSE will reproduce the documented Gen 1 YOSHIRA Mew distribution parameters in ${if(destinationBox==null) "the next empty party slot" else "PC Box $destinationBox"}.\n\nLevel 5 • Pound • OT YOSHIRA\nFixed DVs: HP 5 / Atk 10 / Def 1 / Speed 12 / Special 5\nTrainer ID: $tid\n\nThe ID is generated in the historical distribution-machine range. PSE will rebuild the checksum, re-read the Pokémon and verify every fixed event field. This reproduces documented event parameters; it does not claim the Pokémon physically came from an original Nintendo distribution machine.").setNegativeButton("Cancel",null).setPositiveButton("Inject Event"){_,_->
                loadGen1SpeciesMetaAsync(151){meta->
                    if(meta==null){showDialog("Event Mew","PSE could not load the Gen 1 Mew species data needed to safely rebuild party stats. Nothing was changed.");return@loadGen1SpeciesMetaAsync}
                    val original=runCatching{file.readBytes()}.getOrNull()?:return@loadGen1SpeciesMetaAsync
                    try{
                        require(original.size==SIZE_G1&&hasValidGen1MainChecksum(original)){"The fresh Gen 1 save is invalid."}
                        val integrity=verifyGen1SaveIntegrity(original);require(integrity.first){integrity.second}
                        val before=parseGen1Party(original);if(destinationBox==null) require(before.size<6){"The party became full before injection."} else require(gen1BoxIsWritable(original,destinationBox)){"The selected PC box is no longer writable."}
                        val work=original.copyOf();val raw=ByteArray(GEN1_BOX_MON_SIZE)
                        raw[0]=meta.internalIndex.toByte();writeU16BE(raw,1,25);raw[3]=5;raw[4]=0;raw[5]=0x18;raw[6]=0x18;raw[7]=45;raw[8]=1
                        writeU16BE(raw,12,tid);raw[14]=0;raw[15]=0;raw[16]=135.toByte();raw[27]=0xA1.toByte();raw[28]=0xC5.toByte();raw[29]=35
                        val ot=gen1EncodeName("YOSHIRA",10);val nick=gen1EncodeName("MEW",10)
                        val event=Gen1Pokemon(before.size,meta.internalIndex,"MEW","YOSHIRA",5,25,25,intArrayOf(1,0,0,0),intArrayOf(35,0,0,0),135,tid,intArrayOf(0,0,0,0,0),intArrayOf(5,10,1,12,5))
                        val slot=if(destinationBox==null) appendGen1PartyPokemon(work,raw,ot,nick,meta,event) else appendGen1EventToBox(work,destinationBox,raw,ot,nick);markGen1PokedexCaught(work,151);updateGen1MainChecksum(work)
                        val pre=verifyGen1WriteState(work,destinationBox);require(pre.first){pre.second};if(destinationBox==null){val pv=verifyGen1PartyDerivedStats(work,slot,meta);require(pv.first){pv.second}}
                        file.writeBytes(work);val verify=file.readBytes();val post=verifyGen1WriteState(verify,destinationBox);require(post.first){post.second};require(verify.contentEquals(work)){"The save changed while the YOSHIRA event was being written."};val q=if(destinationBox==null) parseGen1Party(verify).firstOrNull{it.slot==slot} else parseGen1Box(verify,destinationBox).pokemon.firstOrNull{it.slot==slot};q?:error("Injected Mew could not be re-read.")
                        require(q.species==meta.internalIndex&&q.nickname=="MEW"&&q.otName=="YOSHIRA"&&q.tid==tid&&q.level==5&&q.experience==135L&&q.moves.contentEquals(intArrayOf(1,0,0,0))&&q.movePP.contentEquals(intArrayOf(35,0,0,0))&&q.dvs.contentEquals(intArrayOf(5,10,1,12,5))&&q.statExp.all{it==0}){"Injected Mew did not match the documented event template after re-reading."}
                        Toast.makeText(this,"YOSHIRA Mew injected and verified",Toast.LENGTH_LONG).show();showGen1Events()
                    }catch(e:Exception){runCatching{file.writeBytes(original)};showDialog("Event injection failed",(e.message?:"Unknown error")+"\n\nThe original working save was restored and no partial event was kept.")}
                }
            }.show()
        }
            }
        root.addView(TextView(this).apply{text="More documented Gen 1 distributions";visibility=View.GONE})
        root.addView(TextView(this).apply{text="Pokémon Stadium";textSize=19f;typeface=Typeface.DEFAULT_BOLD;setTextColor(TEXT);setPadding(0,dp(16),0,dp(4))})
        root.addView(TextView(this).apply{text="Stadium rewards • OT STADIUM • TID 02000";textSize=13f;setTextColor(MUTED);setPadding(0,0,0,dp(8))})
        fun stadiumEvent(name:String,dex:Int,level:Int,moves:IntArray,pps:IntArray){
            addButton(root,"$name • Lv. $level",dex){
                val fresh=runCatching{file.readBytes()}.getOrNull()?:return@addButton
                chooseGen1EventDestination(fresh,"Stadium Event"){destinationBox->
                AlertDialog.Builder(this).setTitle("Inject STADIUM $name?").setMessage("PSE will reproduce the documented international Pokémon Stadium reward parameters in ${if(destinationBox==null) "the next empty party slot" else "PC Box $destinationBox"}.\n\n$name • Level $level • OT STADIUM • ID 02000\n\nPSE will rebuild the save checksum and verify the injected Pokémon after writing. This matches documented game-based distribution parameters; it does not claim this Pokémon physically came from a Nintendo 64 transfer.").setNegativeButton("Cancel",null).setPositiveButton("Inject Event"){_,_->
                    loadGen1SpeciesMetaAsync(dex){meta->
                        if(meta==null){showDialog("Stadium Event","PSE could not load the Gen 1 species data needed to safely build this reward. Nothing was changed.");return@loadGen1SpeciesMetaAsync}
                        val original=runCatching{file.readBytes()}.getOrNull()?:return@loadGen1SpeciesMetaAsync
                        try{
                            require(original.size==SIZE_G1&&hasValidGen1MainChecksum(original)){"The fresh Gen 1 save is invalid."}
                        val integrity=verifyGen1SaveIntegrity(original);require(integrity.first){integrity.second}
                            val before=parseGen1Party(original);if(destinationBox==null) require(before.size<6){"The party became full before injection."} else require(gen1BoxIsWritable(original,destinationBox)){"The selected PC box is no longer writable."}
                            val exp=gen1ExperienceForLevel(meta.growth,level);val work=original.copyOf();val raw=ByteArray(GEN1_BOX_MON_SIZE)
                            raw[0]=meta.internalIndex.toByte();raw[3]=level.toByte();raw[5]=meta.type1.toByte();raw[6]=meta.type2.toByte();raw[7]=meta.catchRate.toByte();for(i in 0..3)raw[8+i]=moves.getOrElse(i){0}.toByte();writeU16BE(raw,12,2000);writeU24BE(raw,14,exp)
                            // Stadium reward DVs are not fixed by the documented template, so generate a valid Gen 1 DV spread.
                            val atk=(0..15).random();val def=(0..15).random();val spe=(0..15).random();val spc=(0..15).random();raw[27]=((atk shl 4) or def).toByte();raw[28]=((spe shl 4) or spc).toByte();for(i in 0..3)raw[29+i]=pps.getOrElse(i){0}.coerceIn(0,63).toByte()
                            val dvs=gen1ReadDvs(raw,27);val stats=gen1CalculatedStats(meta,level,dvs,intArrayOf(0,0,0,0,0));writeU16BE(raw,1,stats[0])
                            val event=Gen1Pokemon(before.size,meta.internalIndex,name,"STADIUM",level,stats[0],stats[0],moves.copyOf(),pps.copyOf(),exp,2000,intArrayOf(0,0,0,0,0),dvs)
                            val ot=gen1EncodeName("STADIUM",10);val nick=gen1EncodeName(name,10);val slot=if(destinationBox==null) appendGen1PartyPokemon(work,raw,ot,nick,meta,event) else appendGen1EventToBox(work,destinationBox,raw,ot,nick);markGen1PokedexCaught(work,dex);updateGen1MainChecksum(work)
                            val pre=verifyGen1WriteState(work,destinationBox);require(pre.first){pre.second};if(destinationBox==null){val pv=verifyGen1PartyDerivedStats(work,slot,meta);require(pv.first){pv.second}}
                            file.writeBytes(work);val verify=file.readBytes();val post=verifyGen1WriteState(verify,destinationBox);require(post.first){post.second};require(verify.contentEquals(work)){"The save changed while the Stadium event was being written."};val q=if(destinationBox==null) parseGen1Party(verify).firstOrNull{it.slot==slot} else parseGen1Box(verify,destinationBox).pokemon.firstOrNull{it.slot==slot};q?:error("Injected Stadium Pokémon could not be re-read.")
                            require(q.species==meta.internalIndex&&q.nickname==name&&q.otName=="STADIUM"&&q.tid==2000&&q.level==level&&q.moves.contentEquals(moves)&&q.statExp.all{it==0}){"Injected Stadium Pokémon did not match the documented event template after re-reading."};require(q.experience==exp&&q.movePP.contentEquals(pps)&&q.dvs.contentEquals(dvs)){"Injected Stadium Pokémon did not preserve its complete reward values after re-reading."}
                            Toast.makeText(this,"STADIUM $name injected and verified",Toast.LENGTH_LONG).show();showGen1Events()
                        }catch(e:Exception){runCatching{file.writeBytes(original)};showDialog("Event injection failed",(e.message?:"Unknown error")+"\n\nThe original working save was restored and no partial event was kept.")}
                    }
                }.show()
                }
            }
        }
        root.addView(TextView(this).apply{text="Mew distributions";textSize=18f;setTextColor(TEXT);typeface=Typeface.DEFAULT_BOLD;setPadding(0,dp(18),0,dp(6))})
        root.addView(TextView(this).apply{text="Mew • Level 5 • Pound. Template details are shown before adding.";textSize=13f;setTextColor(MUTED)})
