                            try{
                                require(original.size==SIZE_G1&&hasValidGen1MainChecksum(original)){"The fresh Gen 1 save is invalid."}
                        val integrity=verifyGen1SaveIntegrity(original);require(integrity.first){integrity.second}
                                val before=parseGen1Party(original);if(destinationBox==null) require(before.size<6){"The party became full before injection."} else require(gen1BoxIsWritable(original,destinationBox)){"The selected PC box is no longer writable."}
                                val work=original.copyOf();val raw=ByteArray(GEN1_BOX_MON_SIZE)
                                raw[0]=meta.internalIndex.toByte();raw[5]=meta.type1.toByte();raw[6]=meta.type2.toByte();raw[7]=meta.catchRate.toByte();writeU16BE(raw,12,tid);raw[14]=0;raw[15]=0;raw[16]=135.toByte();raw[8]=1;raw[29]=35;raw[3]=5
                                // Fixed distribution-machine DVs: Atk A, Def 1, Spd C, Spc 5 -> derived HP DV 5.
