                                val event=Gen1Pokemon(before.size,meta.internalIndex,"MEW",otName,5,stats[0],stats[0],intArrayOf(1,0,0,0),intArrayOf(35,0,0,0),135,tid,intArrayOf(0,0,0,0,0),dvs)
                                val ot=gen1EncodeName(otName,10);val nick=gen1EncodeName("MEW",10);val slot=if(destinationBox==null) appendGen1PartyPokemon(work,raw,ot,nick,meta,event) else appendGen1EventToBox(work,destinationBox,raw,ot,nick);markGen1PokedexCaught(work,151);updateGen1MainChecksum(work)
                                val pre=verifyGen1WriteState(work,destinationBox);require(pre.first){pre.second};if(destinationBox==null){val pv=verifyGen1PartyDerivedStats(work,slot,meta);require(pv.first){pv.second}}
                                file.writeBytes(work);val verify=file.readBytes();val post=verifyGen1WriteState(verify,destinationBox);require(post.first){post.second};require(verify.contentEquals(work)){"The save changed while the documented Mew event was being written."};val q=if(destinationBox==null) parseGen1Party(verify).firstOrNull{it.slot==slot} else parseGen1Box(verify,destinationBox).pokemon.firstOrNull{it.slot==slot};require(q!=null && q.species==meta.internalIndex && q.level==5 && q.otName.equals(otName,true) && q.tid==tid){"Injected Mew did not re-read with the documented identity."};require(q.nickname=="MEW"&&q.experience==135L&&q.moves.contentEquals(intArrayOf(1,0,0,0))&&q.movePP.contentEquals(intArrayOf(35,0,0,0))&&q.dvs.contentEquals(intArrayOf(5,10,1,12,5))&&q.statExp.all{it==0}){"Injected Mew did not preserve its complete documented values after re-reading."};val di=150;val mask=1 shl(di%8);require((verify[0x25A3+di/8].toInt() and mask)!=0&&(verify[0x25B6+di/8].toInt() and mask)!=0){"Injected Mew did not register in the Pokédex."}
