    private fun gen1TrainerState(data:ByteArray):ByteArray{
        require(data.size==SIZE_G1){"Gen 1 trainer data requires a 32 KB save."}
        val out=ByteArray(18);var w=0
        for(i in 0 until 8)out[w++]=data[0x2598+i]
        for(i in 0 until 3)out[w++]=data[0x25F3+i]
        out[w++]=data[0x2602]
        out[w++]=data[0x2605];out[w++]=data[0x2606]
        for(i in 0 until 4)out[w++]=data[0x2CED+i]
        return out
    }

    private fun showGen1TrainerEditor(){
        val file=importedFile?:return;val data=runCatching{file.readBytes()}.getOrNull()?:return
        if(data.size!=0x8000){showDialog("Trainer Editor","This trainer editor is for Gen 1 Red/Blue/Yellow saves.");return}
        if(!ensureGen1TrainerToolIntegrity(data,"Trainer Editor"))return
        val root=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(dp(18),dp(36),dp(18),dp(24));setBackgroundColor(BG)}
        root.addView(TextView(this).apply{text="Gen 1 Trainer Editor";textSize=28f;typeface=Typeface.DEFAULT_BOLD;setTextColor(TEXT)})
        root.addView(TextView(this).apply{text="Edit your Red / Blue / Yellow trainer data. Each field below shows what it changes and its valid range.";textSize=14f;setTextColor(MUTED);setPadding(0,dp(4),0,dp(18))})
        fun label(title:String,info:String){root.addView(TextView(this).apply{text=title; textSize=15f; typeface=Typeface.DEFAULT_BOLD; setTextColor(TEXT); setPadding(dp(4),dp(10),dp(4),0)});root.addView(TextView(this).apply{text=info;textSize=12f;setTextColor(MUTED);setPadding(dp(4),0,dp(4),0)})}
        fun numberField(v:Int)=EditText(this).apply{inputType=2;setText(v.toString());setTextColor(TEXT);setHintTextColor(MUTED)}
        label("Trainer Name","Your in-game trainer name • 1–7 characters")
        val name=EditText(this).apply{setText(gen1ReadName(data,0x2598));setTextColor(TEXT);setHintTextColor(MUTED)};root.addView(name)
        label("Trainer ID","The numeric ID attached to your trainer • 0–65535")
        val tid=numberField(((data[0x2605].toInt()and 255)shl 8)or(data[0x2606].toInt()and 255));root.addView(tid)
        label("Money","Current money carried by your trainer • 0–999,999")
        val money=numberField(gen1BcdMoney(data));root.addView(money)
        label("Badges","Number of Gym Badges earned • 0–8")
        val badges=numberField(Integer.bitCount(data[0x2602].toInt()and 255));root.addView(badges)
        root.addView(TextView(this).apply{text="Play Time";textSize=17f;typeface=Typeface.DEFAULT_BOLD;setTextColor(TEXT);setPadding(dp(4),dp(16),dp(4),0)})
        root.addView(TextView(this).apply{text="Set the save's recorded play time. Minutes and seconds must be 0–59.";textSize=12f;setTextColor(MUTED);setPadding(dp(4),0,dp(4),dp(4))})
        label("Hours","0–255 hours");val hours=numberField(data[0x2CED].toInt()and 255);root.addView(hours)
        label("Minutes","0–59 minutes");val minutes=numberField(data[0x2CEF].toInt()and 255);root.addView(minutes)
        label("Seconds","0–59 seconds");val seconds=numberField(data[0x2CF0].toInt()and 255);root.addView(seconds)
        root.addView(TextView(this).apply{text="What happens when I save?";textSize=17f;typeface=Typeface.DEFAULT_BOLD;setTextColor(TEXT);setPadding(dp(4),dp(18),dp(4),dp(4))})
        root.addView(TextView(this).apply{text="PSE updates the selected trainer values, rebuilds the Gen 1 save checksum, writes the save, then reads it back and verifies the result. If verification fails, PSE restores the original working save automatically.";textSize=13f;setTextColor(MUTED);setPadding(dp(4),0,dp(4),dp(14))})
        addButton(root,"Save Trainer Data"){
            val n=name.text.toString().trim();val id=tid.text.toString().toIntOrNull();val cash=money.text.toString().toIntOrNull();val badgeCount=badges.text.toString().toIntOrNull();val h=hours.text.toString().toIntOrNull();val m=minutes.text.toString().toIntOrNull();val sec=seconds.text.toString().toIntOrNull()
            if(n.isEmpty()||n.length>7||id==null||id !in 0..65535||cash==null||cash !in 0..999999||badgeCount==null||badgeCount !in 0..8||h==null||h !in 0..255||m==null||m !in 0..59||sec==null||sec !in 0..59){showDialog("Trainer Editor","Use a 1–7 character name, Trainer ID 0–65535, money 0–999999, badges 0–8, hours 0–255, and minutes/seconds 0–59.");return@addButton}
            val fresh=runCatching{file.readBytes()}.getOrElse{showDialog("Trainer edit failed","The fresh Gen 1 save could not be read. Nothing was changed.");return@addButton}
            try{
                val trainerIntegrity=verifyGen1SaveIntegrity(fresh);require(trainerIntegrity.first){trainerIntegrity.second}
                require(fresh.size==SIZE_G1&&hasValidGen1MainChecksum(fresh)){"The fresh Gen 1 save is invalid."}
                require(gen1TrainerState(fresh).contentEquals(gen1TrainerState(data))){"Trainer data changed after this screen was opened. Reopen the editor and try again."}
                val work=fresh.copyOf();val enc=gen1EncodeName(n);for(i in enc.indices)work[0x2598+i]=enc[i];work[0x2605]=(id shr 8).toByte();work[0x2606]=id.toByte();gen1WriteBcdMoney(work,cash);work[0x2602]=(if(badgeCount==8)255 else (1 shl badgeCount)-1).toByte();work[0x2CED]=h.toByte();work[0x2CEE]=0;work[0x2CEF]=m.toByte();work[0x2CF0]=sec.toByte();updateGen1MainChecksum(work)
                val expected=gen1TrainerState(work)
                require(work.indices.all{it in 0x2598 until 0x25A0||it in 0x25F3 until 0x25F6||it==0x2602||it in 0x2605..0x2606||it in 0x2CED..0x2CF0||it==GEN1_CHECKSUM_OFFSET||work[it]==fresh[it]}){"The trainer edit changed unrelated save data."}
                val pre=verifyGen1WriteState(work,null);require(pre.first){pre.second};file.writeBytes(work)
                val verify=file.readBytes();require(verify.contentEquals(work)){"The save changed while trainer data was being written."};val post=verifyGen1WriteState(verify,null);require(post.first){post.second};require(gen1TrainerState(verify).contentEquals(expected)&&gen1ReadName(verify,0x2598)==n&&((((verify[0x2605].toInt()and 255)shl 8)or(verify[0x2606].toInt()and 255))==id)&&gen1BcdMoney(verify)==cash&&Integer.bitCount(verify[0x2602].toInt()and 255)==badgeCount&&(verify[0x2CED].toInt()and 255)==h&&(verify[0x2CEF].toInt()and 255)==m&&(verify[0x2CF0].toInt()and 255)==sec){"Trainer data did not verify exactly after re-reading."}
                Toast.makeText(this,"Gen 1 trainer data updated and verified",Toast.LENGTH_LONG).show();showGen1TrainerEditor()
            }catch(e:Exception){runCatching{file.writeBytes(fresh)};showDialog("Trainer edit failed",(e.message?:"Unknown error")+"\n\nThe fresh working save was restored.")}
        }
        addButton(root,"Back to Trainer Data"){showTrainerData()};setContentView(ScrollView(this).apply{addView(root)});phoneBackAction={showTrainerData()}
    }

    private fun markGen1PokedexCaught(data:ByteArray,dex:Int){
        require(data.size==0x8000){"Gen 1 Pokédex registration requires a 32 KB save."}
        require(dex in 1..151){"Invalid Gen 1 Pokédex number: $dex"}
        val i=dex-1;val mask=1 shl(i%8)
        val seen=0x25B6+i/8;val caught=0x25A3+i/8
        data[seen]=(data[seen].toInt() or mask).toByte()
        data[caught]=(data[caught].toInt() or mask).toByte()
    }

    private fun gen1PokedexState(data:ByteArray):ByteArray{
        require(data.size==SIZE_G1){"Gen 1 Pokédex data requires a 32 KB save."}
        val out=ByteArray(38)
        data.copyInto(out,0,0x25A3,0x25A3+19)
        data.copyInto(out,19,0x25B6,0x25B6+19)
        return out
    }

    private fun showGen1PokedexEditor(){
        val file=importedFile?:return;val data=runCatching{file.readBytes()}.getOrNull()?:return
        if(data.size!=SIZE_G1||!hasValidGen1MainChecksum(data)){showDialog("Pokédex Editor","This editor requires a valid 32 KB Gen 1 Red/Blue/Yellow save.");return}
        if(!ensureGen1TrainerToolIntegrity(data,"Pokédex Editor"))return
        val root=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(dp(18),dp(36),dp(18),dp(24));setBackgroundColor(BG)}
        root.addView(TextView(this).apply{text="Gen 1 Pokédex Editor";textSize=28f;typeface=Typeface.DEFAULT_BOLD;setTextColor(TEXT)})
        root.addView(TextView(this).apply{text="Edit Seen and Caught Pokédex flags for all 151 Pokémon. Marking a Pokémon as Caught also marks it as Seen.";textSize=14f;setTextColor(MUTED);setPadding(0,dp(4),0,dp(12))})
        val seenBase=0x25B6;val caughtBase=0x25A3
        fun flag(base:Int,n:Int):Boolean{val i=n-1;return ((data[base+i/8].toInt()and 255)and(1 shl(i%8)))!=0}
        val seen=BooleanArray(151){flag(seenBase,it+1)};val caught=BooleanArray(151){flag(caughtBase,it+1)}
        val summary=TextView(this).apply{textSize=14f;setTextColor(TEXT);setPadding(dp(4),dp(4),dp(4),dp(10))};root.addView(summary)
        val list=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL};val seenChecks=ArrayList<CheckBox>();val caughtChecks=ArrayList<CheckBox>()
        fun refreshSummary(){summary.text="Seen: ${seen.count{it}} / 151    •    Caught: ${caught.count{it}} / 151"}
        fun refreshChecks(){for(i in 0 until 151){seenChecks[i].isChecked=seen[i];caughtChecks[i].isChecked=caught[i]};refreshSummary()}
        fun action(text:String,fn:()->Unit){addButton(root,text){fn();refreshChecks()}}
        action("Mark All Seen"){for(i in seen.indices)seen[i]=true}
        action("Mark All Caught"){for(i in caught.indices){caught[i]=true;seen[i]=true}}
        action("Clear All"){for(i in 0 until 151){seen[i]=false;caught[i]=false}}
        for(i in 0 until 151){
            val row=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL;gravity=Gravity.CENTER_VERTICAL;setPadding(0,dp(2),0,dp(2))}
            val dex=i+1
            row.background=roundedBg(CARD,Color.rgb(20,95,135),12)
            row.setPadding(dp(8),dp(5),dp(8),dp(5))
            row.addView(TextView(this).apply{text="#${dex.toString().padStart(3,'0')}";textSize=13f;setTextColor(MUTED);gravity=Gravity.CENTER_VERTICAL},LinearLayout.LayoutParams(dp(50),dp(64)))
            val sprite=ImageView(this).apply{scaleType=ImageView.ScaleType.FIT_CENTER;contentDescription=GEN1_NATIONAL_NAMES.getOrElse(i){"Pokémon #$dex"}}
            row.addView(sprite,LinearLayout.LayoutParams(dp(58),dp(58)));loadPokemonSprite(sprite,dex,false)
            row.addView(TextView(this).apply{text=GEN1_NATIONAL_NAMES.getOrElse(i){"Pokémon #$dex"};textSize=15f;typeface=Typeface.DEFAULT_BOLD;setTextColor(TEXT);gravity=Gravity.CENTER_VERTICAL;maxLines=2},LinearLayout.LayoutParams(0,dp(64),1f))
            val sc=CheckBox(this).apply{text="Seen";textSize=13f;setTextColor(TEXT);isChecked=seen[i]};val cc=CheckBox(this).apply{text="Caught";textSize=13f;setTextColor(TEXT);isChecked=caught[i]}
            seenChecks.add(sc);caughtChecks.add(cc)
            sc.setOnCheckedChangeListener{_,v->seen[i]=v;if(!v&&caught[i]){caught[i]=false;cc.isChecked=false};refreshSummary()}
            cc.setOnCheckedChangeListener{_,v->caught[i]=v;if(v&&!seen[i]){seen[i]=true;sc.isChecked=true};refreshSummary()}
            row.addView(sc,LinearLayout.LayoutParams(dp(82),dp(64)));row.addView(cc,LinearLayout.LayoutParams(dp(92),dp(64)));list.addView(row,LinearLayout.LayoutParams(-1,-2).apply{bottomMargin=dp(6)})
        }
        refreshSummary();root.addView(list)
        root.addView(TextView(this).apply{text="Safe saving";textSize=17f;typeface=Typeface.DEFAULT_BOLD;setTextColor(TEXT);setPadding(dp(4),dp(16),dp(4),dp(4))})
        root.addView(TextView(this).apply{text="PSE rebuilds the Gen 1 checksum, verifies the edited save, writes it, then reads it back. If verification fails, the original save is restored.";textSize=13f;setTextColor(MUTED);setPadding(dp(4),0,dp(4),dp(10))})
        addButton(root,"Save Pokédex"){
            val original=runCatching{file.readBytes()}.getOrElse{showDialog("Pokédex edit failed","The fresh Gen 1 save could not be read. Nothing was changed.");return@addButton}
            try{
                val pokedexIntegrity=verifyGen1SaveIntegrity(original);require(pokedexIntegrity.first){pokedexIntegrity.second}
                require(original.size==SIZE_G1&&hasValidGen1MainChecksum(original)){"The fresh Gen 1 save is invalid."}
                require(gen1PokedexState(original).contentEquals(gen1PokedexState(data))){"Pokédex data changed after this screen was opened. Reopen the editor and try again."}
                require(caught.indices.all{!caught[it]||seen[it]}){"Caught Pokémon must also be marked Seen."}
                val work=original.copyOf()
                for(j in 0 until 19){work[seenBase+j]=0;work[caughtBase+j]=0};for(i in 0 until 151){val mask=1 shl(i%8);if(seen[i])work[seenBase+i/8]=(work[seenBase+i/8].toInt()or mask).toByte();if(caught[i])work[caughtBase+i/8]=(work[caughtBase+i/8].toInt()or mask).toByte()}
                updateGen1MainChecksum(work)
                val expected=gen1PokedexState(work)
                require(work.indices.all{it in caughtBase until caughtBase+19||it in seenBase until seenBase+19||it==GEN1_CHECKSUM_OFFSET||work[it]==original[it]}){"The Pokédex edit changed unrelated save data."}
                val pre=verifyGen1WriteState(work,null);require(pre.first){pre.second};file.writeBytes(work);val verify=file.readBytes();val post=verifyGen1WriteState(verify,null);require(post.first){post.second};for(i in 0 until 151){val mask=1 shl(i%8);require((((verify[seenBase+i/8].toInt()and 255)and mask)!=0)==seen[i]);require((((verify[caughtBase+i/8].toInt()and 255)and mask)!=0)==caught[i])}
                require(verify.contentEquals(work)){"The save changed while Pokédex data was being written."};require(gen1PokedexState(verify).contentEquals(expected)){"Persisted Pokédex data did not match the staged edit."}
                Toast.makeText(this,"Gen 1 Pokédex updated and verified",Toast.LENGTH_LONG).show();showGen1PokedexEditor()
            }catch(e:Exception){runCatching{file.writeBytes(original)};showDialog("Pokédex edit failed",(e.message?:"Unknown error")+"\n\nThe fresh working save was restored.")}
        }
        addButton(root,"Back to Trainer Data"){showTrainerData()};setContentView(ScrollView(this).apply{addView(root)});phoneBackAction={showTrainerData()}
    }

    private fun gen2TrainerState(data:ByteArray):ByteArray{
        require(data.size>=0x2016){"The Gen 2 trainer block is outside the save."}
        return data.copyOfRange(0x2009,0x2016)
    }

    private fun gen2RivalState(data:ByteArray):ByteArray{
        require(data.size>=0x202C){"The Gen 2 rival-name block is outside the save."}
        return data.copyOfRange(0x2021,0x202C)
    }

    private fun gen2RivalName(data:ByteArray):String = readGen1Text(data,0x2021,11)

    private fun gen2TrainerGenderState(data:ByteArray,profile:Gen2Profile):ByteArray{
        if(profile.key!="C")return byteArrayOf()
        require(data.size>0x3E3D){"The Crystal trainer-gender fields are outside the save."}
        val palette=data[0x206A].toInt()and 0xFF;val gender=data[0x3E3D].toInt()and 0xFF
        require(gender in 0..1&&palette==gender){"The Crystal trainer-gender and palette fields are inconsistent."}
        return byteArrayOf(palette.toByte(),gender.toByte())
    }

    private fun showGen2TrainerEditor(){
        val openedUri=currentSourceUri;val openedLabel=currentSourceLabel
        val file=importedFile?:return;val opened=runCatching{file.readBytes()}.getOrNull()?:return
        fun bound()=importedFile?.absolutePath==file.absolutePath&&currentSourceUri==openedUri&&currentSourceLabel==openedLabel
        val openedProfile=detectGen2Profile(opened)?:run{showDialog("Gen 2 Trainer Editor","This editor requires a valid Pokémon Gold, Silver or Crystal save.");return}
        val openedState=gen2TrainerState(opened);val openedRivalState=gen2RivalState(opened);val openedGenderState=runCatching{gen2TrainerGenderState(opened,openedProfile)}.getOrElse{showDialog("Gen 2 Trainer Editor",it.message?:"The verified trainer gender could not be read.");return};val openedTrainer=parseTrainerGen2(opened,openedProfile)?:run{showDialog("Gen 2 Trainer Editor","The verified Gen 2 trainer fields could not be read.");return}
        val root=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(dp(18),dp(36),dp(18),dp(24));setBackgroundColor(BG)}
