        fun label(title:String,detail:String){root.addView(TextView(this).apply{text=title;textSize=15f;typeface=Typeface.DEFAULT_BOLD;setTextColor(TEXT);setPadding(dp(4),dp(10),dp(4),0)});root.addView(TextView(this).apply{text=detail;textSize=12f;setTextColor(MUTED);setPadding(dp(4),0,dp(4),0)})}
        label("Trainer Name","Your in-game trainer name • 1–7 supported Western characters")
        val name=EditText(this).apply{setText(openedTrainer.trainerName);setTextColor(TEXT);setHintTextColor(MUTED)};root.addView(name)
        label("Trainer ID","The numeric ID attached to your trainer • 0–65535")
        val tid=EditText(this).apply{inputType=android.text.InputType.TYPE_CLASS_NUMBER;setText(openedTrainer.tid.toString());setTextColor(TEXT);setHintTextColor(MUTED)};root.addView(tid)
        label("Rival Name","Your rival's in-game name • 1–7 supported Western characters")
        val rival=EditText(this).apply{setText(gen2RivalName(opened));setTextColor(TEXT);setHintTextColor(MUTED)};root.addView(rival)
        label("Trainer Gender",if(openedProfile.key=="C")"Crystal stores the player gender and matching palette together" else "Gold and Silver use the male player character")
        val genderPicker:Spinner?=if(openedProfile.key=="C")Spinner(this).apply{adapter=ArrayAdapter(this@MainActivity,android.R.layout.simple_spinner_dropdown_item,listOf("Male","Female"));setSelection(openedGenderState[1].toInt()and 0xFF);root.addView(this)}else null
        if(genderPicker==null)root.addView(TextView(this).apply{text="Male (fixed for this game)";textSize=15f;setTextColor(TEXT);setPadding(dp(4),dp(8),dp(4),dp(8))})
        root.addView(TextView(this).apply{text="PSE changes only the verified Gen 2 trainer identity, rival name and Crystal gender bytes, rebuilds the primary checksum, rejects stale state without writing, verifies the staged and persisted data, and verifies any attempted restore after a write failure. A retained recovery backup is required before saving.";textSize=13f;setTextColor(MUTED);setPadding(dp(4),dp(18),dp(4),dp(12))})
        var consumed=false
        addButton(root,"Save Trainer Data"){
            if(consumed){showDialog("Gen 2 Trainer Editor","This edit was already submitted. Reopen Trainer Data before saving again.");return@addButton}
            if(importedFile?.absolutePath!=file.absolutePath){showDialog("Gen 2 trainer edit failed","The active save changed. Reopen Trainer Data before editing. Nothing was changed.");return@addButton}
            if(!bound()){showDialog("Gen 2 trainer edit failed","The source identity changed. Reopen Trainer Data before editing. Nothing was changed.");return@addButton}
            val newName=name.text.toString().trim();val newTid=tid.text.toString().toIntOrNull();val newRival=rival.text.toString().trim();val newGender=genderPicker?.selectedItemPosition?:0
            if(newName.isEmpty()||newName.length>7||newRival.isEmpty()||newRival.length>7||newTid==null||newTid !in 0..65535||newGender !in 0..1||newName.any{encodeGen1Char(it)==null}||newRival.any{encodeGen1Char(it)==null}){showDialog("Gen 2 Trainer Editor","Use 1–7 supported Western characters for both trainer and rival names, and a Trainer ID from 0–65535.");return@addButton}
            consumed=true
            val fresh=runCatching{file.readBytes()}.getOrElse{showDialog("Gen 2 trainer edit failed","The fresh Gen 2 save could not be read. Nothing was changed.");return@addButton}
            var safetyBackup:File?=null
            var writeStarted=false
            try{
                require(bound()&&verifyGen2SaveIntegrity(fresh).first){"The confirmed Gen 2 source identity or full save integrity changed."}
                val profile=detectGen2Profile(fresh)?:error("The fresh Gen 2 save failed checksum validation.");require(profile.key==openedProfile.key){"The Gen 2 game profile changed while the editor was open."};require(gen2TrainerState(fresh).contentEquals(openedState)&&gen2RivalState(fresh).contentEquals(openedRivalState)&&gen2TrainerGenderState(fresh,profile).contentEquals(openedGenderState)){"Trainer identity changed after this screen was opened. Reopen the editor and try again."}
                val work=fresh.copyOf();writeU16BE(work,0x2009,newTid);writeGen1Text(work,0x200B,11,newName);writeGen1Text(work,0x2021,11,newRival);if(profile.key=="C"){work[0x206A]=newGender.toByte();work[0x3E3D]=newGender.toByte()};updateGen2PrimaryChecksum(work,profile);val expected=gen2TrainerState(work);val expectedRival=gen2RivalState(work);val expectedGender=gen2TrainerGenderState(work,profile)
                require(work.indices.all{it in 0x2009 until 0x2016||it in 0x2021 until 0x202C||profile.key=="C"&&(it==0x206A||it==0x3E3D)||it in profile.checksumOffset..profile.checksumOffset+1||work[it]==fresh[it]}){"The Gen 2 trainer edit changed unrelated save data."}
                val stagedProfile=detectGen2Profile(work)?:error("The staged Gen 2 save failed checksum verification.");val staged=parseTrainerGen2(work,stagedProfile);require(stagedProfile.key==profile.key&&gen2ChecksumValid(work,stagedProfile)&&gen2TrainerState(work).contentEquals(expected)&&gen2RivalState(work).contentEquals(expectedRival)&&gen2TrainerGenderState(work,stagedProfile).contentEquals(expectedGender)&&staged!=null&&staged.trainerName==newName&&staged.tid==newTid&&gen2RivalName(work)==newRival){"The staged Gen 2 trainer data did not verify exactly."}
                require(verifyGen2SaveIntegrity(work).first){"The complete staged Gen 2 save failed integrity validation."}
                require(importedFile?.absolutePath==file.absolutePath&&file.readBytes().contentEquals(fresh)){"The Gen 2 source changed while the trainer edit was staged. Nothing was written."}
                require(bound()){"The confirmed Gen 2 source identity changed before backup."}
                val backup=File.createTempFile(backupGameName(file)+"_PreGen2Trainer_",".backup",backupsDir());safetyBackup=backup
                backup.writeBytes(fresh);require(backup.readBytes().contentEquals(fresh)){"The exact pre-edit recovery backup could not be verified."}
                retainGen2SafetyBackup(backup,fresh)
                require(bound()&&isBackupKept(backup)&&backup.readBytes().contentEquals(fresh)&&file.readBytes().contentEquals(fresh)){"The confirmed source or retained recovery backup changed before writing."}
                writeStarted=true
                file.writeBytes(work);val persisted=file.readBytes();require(persisted.contentEquals(work)){"The Gen 2 save changed while trainer data was written."};val persistedProfile=detectGen2Profile(persisted)?:error("The persisted Gen 2 save failed checksum verification.");val verified=parseTrainerGen2(persisted,persistedProfile);require(persistedProfile.key==profile.key&&gen2ChecksumValid(persisted,persistedProfile)&&gen2TrainerState(persisted).contentEquals(expected)&&gen2RivalState(persisted).contentEquals(expectedRival)&&gen2TrainerGenderState(persisted,persistedProfile).contentEquals(expectedGender)&&verified!=null&&verified.trainerName==newName&&verified.tid==newTid&&gen2RivalName(persisted)==newRival){"The persisted Gen 2 trainer data did not match the staged edit."}
                require(bound()&&verifyGen2SaveIntegrity(persisted).first&&file.readBytes().contentEquals(work)){"The persisted Gen 2 source identity or complete save verification failed."}
            }catch(e:Exception){
                val restored=writeStarted&&runCatching{file.writeBytes(fresh)}.isSuccess&&runCatching{file.readBytes().contentEquals(fresh)}.getOrDefault(false)
                val recovery=if(!writeStarted)"Nothing was written to the save." else  if(restored)"The complete fresh working save was restored." else  "Automatic restore could not be verified. Stop editing this save and restore a verified backup."
                showDialog("Gen 2 trainer edit failed",(e.message?:"Unknown error")+"\n\n$recovery"+(safetyBackup?.let{"\n\nRecovery backup: "+it.name}?:""));return@addButton
            }
            Toast.makeText(this,"Gen 2 trainer data updated and verified",Toast.LENGTH_LONG).show();showGen2TrainerEditor()
        }
        addButton(root,"Back to Trainer Data"){showTrainerData()};setContentView(ScrollView(this).apply{addView(root)});phoneBackAction={showTrainerData()}
    }

    // Western G/S/C RTCStatusFlags: PKHeX SAV2Offsets 0x0C60. Pinned pret
    // constants/ram_constants.asm RTC_RESET=bit7; intro_menu Continue invokes RestartClock.
    private fun gen2ClockResetRequested(data:ByteArray,profile:Gen2Profile):Boolean {
        require(profile.key in setOf("GS","C")&&verifyGen2SaveIntegrity(data).first&&detectGen2Profile(data)?.key==profile.key){"A verified Gold, Silver or Crystal save is required."}
        require(0x0C60 in data.indices){"The saved RTC status flag is outside the save."}
        return(data[0x0C60].toInt()and 0x80)!=0
    }

    private fun confirmGen2ClockReset() {
        val file=importedFile?:return
        val source=currentSourceUri;val label=currentSourceLabel
        fun bound()=importedFile?.absolutePath==file.absolutePath&&currentSourceUri==source&&currentSourceLabel==label
        val opened=runCatching{file.readBytes()}.getOrElse{showDialog("Gen 2 Clock","The working save could not be read. Nothing was changed.");return}
        val profile=detectGen2Profile(opened)?:run{showDialog("Gen 2 Clock","A verified Gold, Silver or Crystal save is required. Nothing was changed.");return}
        val requested=runCatching{require(bound()&&file.readBytes().contentEquals(opened)&&bound());gen2ClockResetRequested(opened,profile)}
            .getOrElse{showDialog("Gen 2 Clock","The complete save or source identity could not be verified. Nothing was changed.");return}
        if(requested){showDialog("Clock reset already requested","The saved request flag is already set. No save or backup was changed. After Save & Replace, cold-start the game and choose Continue, not an emulator save state.");return}
        AlertDialog.Builder(this).setTitle("Request in-game clock reset?")
            .setMessage("This sets only the saved RTC reset-request flag in PSE's working copy. It does not choose a day/time, edit play time, change daily or quest flags, or rewrite emulator RTC data. A verified kept recovery backup is required. Stop the emulator before Save & Replace, then cold-start the game and choose Continue, not a save state. The game will offer its own day/time correction screen. Changing the clock in-game can affect timed events; review the time carefully and keep your backup.")
            .setNegativeButton("Cancel",null)
            .setPositiveButton("Request reset"){_,_->requestGen2ClockReset(file,opened,source,label,profile.key)}
            .show()
    }

    private fun requestGen2ClockReset(file:File,opened:ByteArray,openedSource:Uri?,openedLabel:String?,profileKey:String) {
        fun bound()=importedFile?.absolutePath==file.absolutePath&&currentSourceUri==openedSource&&currentSourceLabel==openedLabel
        var writeStarted=false
        var safetyBackup:File?=null
        try{
            require(bound()){"The active save identity changed after confirmation."}
            val fresh=file.readBytes()
            require(fresh.contentEquals(opened)){"The complete working save changed after confirmation. Reopen Trainer Data."}
            val profile=detectGen2Profile(fresh)?:error("The fresh Gen 2 save is invalid.")
            require(profile.key==profileKey&&!gen2ClockResetRequested(fresh,profile)){"The profile or clock reset-request state changed."}
            val work=fresh.copyOf()
            work[0x0C60]=((work[0x0C60].toInt()and 0xFF)or 0x80).toByte()
            require(work.indices.all{it==0x0C60||work[it]==fresh[it]}){"Unrelated data changed while staging the clock request."}
            require(gen2ClockResetRequested(work,profile)){"The staged clock reset request did not verify."}
            val backup=File.createTempFile(backupGameName(file)+"_PreClockReset_",".backup",backupsDir());safetyBackup=backup
            backup.writeBytes(fresh);require(backup.readBytes().contentEquals(fresh)){"The recovery backup did not persist exactly."}
            retainGen2SafetyBackup(backup,fresh)
            require(bound()&&file.readBytes().contentEquals(fresh)&&backup.readBytes().contentEquals(fresh)&&isBackupKept(backup)){"The save, source identity or retained backup changed before writing."}
            writeStarted=true
            file.writeBytes(work)
            val persisted=file.readBytes()
            require(bound()&&persisted.contentEquals(work)&&gen2ClockResetRequested(persisted,profile)){"The complete persisted clock reset request did not verify."}
        }catch(e:Exception){
            val restored=writeStarted&&runCatching{file.writeBytes(opened);require(file.readBytes().contentEquals(opened)&&verifyGen2SaveIntegrity(opened).first)}.isSuccess
            val recovery=if(!writeStarted)"Nothing was written to the working save." else  if(restored)"The exact previous working save was restored and verified." else  "Automatic rollback could not be verified. Stop editing and restore the kept recovery backup."
            showDialog("Clock reset request failed",(e.message?:"Could not safely request the clock reset")+"\n\n"+recovery+(safetyBackup?.let{"\n\nRecovery backup: "+it.name}?:""));return
        }
        showDialog("Clock reset requested","The saved request flag was set and verified. No day/time was chosen and no emulator RTC bytes were changed. After Save & Replace, cold-start the game and choose Continue to set the clock in-game.")
    }

    private data class Gen2PlayTimeState(val cap:Int,val hours:Int,val minutes:Int,val seconds:Int,val frames:Int)

    private fun gen2PlayTimeOffsets(profile:Gen2Profile):IntArray =
        if(profile.key=="C")intArrayOf(0x2051,0x2052,0x2054,0x2055,0x2056) else intArrayOf(0x2052,0x2053,0x2055,0x2056,0x2057)

    private fun gen2PlayTimeState(data:ByteArray,profile:Gen2Profile):Gen2PlayTimeState{
        val o=gen2PlayTimeOffsets(profile);require(o[4]<data.size){"The Gen 2 play-time fields are outside the save."}
        val state=Gen2PlayTimeState(data[o[0]].toInt()and 0xFF,readU16BE(data,o[1]),data[o[2]].toInt()and 0xFF,data[o[3]].toInt()and 0xFF,data[o[4]].toInt()and 0xFF)
        require(state.hours in 0..999&&state.minutes in 0..59&&state.seconds in 0..59&&state.frames in 0..59){"The Gen 2 play-time fields are invalid."}
        return state
    }

    private fun showGen2PlayTimeEditor(){
        val openedUri=currentSourceUri;val openedLabel=currentSourceLabel
        val file=importedFile?:return;val opened=runCatching{file.readBytes()}.getOrNull()?:return
        fun bound()=importedFile?.absolutePath==file.absolutePath&&currentSourceUri==openedUri&&currentSourceLabel==openedLabel
        val openedProfile=detectGen2Profile(opened)?:run{showDialog("Gen 2 Play Time","This editor requires a valid Pokémon Gold, Silver or Crystal save.");return}
        val openedState=runCatching{gen2PlayTimeState(opened,openedProfile)}.getOrElse{showDialog("Gen 2 Play Time",it.message?:"The verified play time could not be read.");return}
        val root=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(dp(18),dp(36),dp(18),dp(24));setBackgroundColor(BG)}
        root.addView(TextView(this).apply{text="Gen 2 Play Time";textSize=28f;typeface=Typeface.DEFAULT_BOLD;setTextColor(TEXT)})
        root.addView(TextView(this).apply{text="Edit the verified elapsed play-time fields for Pokémon Gold, Silver and Crystal, capped at 999:59:59. This is not the day/time clock; use Request Gen 2 Clock Reset to ask the game to correct that separately.";textSize=14f;setTextColor(MUTED);setPadding(0,dp(4),0,dp(16))})
        fun field(label:String,value:Int,max:Int):EditText{root.addView(TextView(this).apply{text="$label • 0–$max";textSize=15f;typeface=Typeface.DEFAULT_BOLD;setTextColor(TEXT);setPadding(dp(4),dp(10),dp(4),0)});return EditText(this).apply{inputType=android.text.InputType.TYPE_CLASS_NUMBER;setText(value.toString());setTextColor(TEXT);setHintTextColor(MUTED);root.addView(this)}}
        val hours=field("Hours",openedState.hours,999);val minutes=field("Minutes",openedState.minutes,59);val seconds=field("Seconds",openedState.seconds,59)
        root.addView(TextView(this).apply{text="PSE preserves the sub-second frame counter and unverified play-time flag bits, updates the official cap flag only when elapsed play time reaches 999:59:59, rebuilds the primary checksum, and verifies the complete persisted working save. Day/time and emulator RTC data are not changed by this editor. A retained recovery backup is required before saving.";textSize=13f;setTextColor(MUTED);setPadding(dp(4),dp(18),dp(4),dp(12))})
        var consumed=false
        addButton(root,"Save Play Time"){
            if(consumed){showDialog("Gen 2 Play Time","This edit was already submitted. Reopen Play Time before saving again.");return@addButton}
            if(importedFile?.absolutePath!=file.absolutePath){showDialog("Gen 2 play-time edit failed","The active save changed. Reopen Play Time before editing. Nothing was changed.");return@addButton}
            if(!bound()){showDialog("Gen 2 play-time edit failed","The source identity changed. Reopen Play Time before editing. Nothing was changed.");return@addButton}
            val parsedHours=hours.text.toString().toIntOrNull();val parsedMinutes=minutes.text.toString().toIntOrNull();val parsedSeconds=seconds.text.toString().toIntOrNull()
            if(parsedHours==null||parsedHours !in 0..999||parsedMinutes==null||parsedMinutes !in 0..59||parsedSeconds==null||parsedSeconds !in 0..59){showDialog("Gen 2 Play Time","Use 0–999 hours and 0–59 minutes and seconds.");return@addButton}
            val newHours=parsedHours;val newMinutes=parsedMinutes;val newSeconds=parsedSeconds
            consumed=true
            val fresh=runCatching{file.readBytes()}.getOrElse{showDialog("Gen 2 play-time edit failed","The fresh Gen 2 save could not be read. Nothing was changed.");return@addButton}
            var safetyBackup:File?=null
            var writeStarted=false
            try{
                require(bound()&&verifyGen2SaveIntegrity(fresh).first){"The confirmed Gen 2 source identity or full save integrity changed."}
                val profile=detectGen2Profile(fresh)?:error("The fresh Gen 2 save failed checksum validation.");require(profile.key==openedProfile.key){"The Gen 2 game profile changed while the editor was open."};require(gen2PlayTimeState(fresh,profile)==openedState){"Play time changed after this screen was opened. Reopen the editor and try again."}
                val work=fresh.copyOf();val o=gen2PlayTimeOffsets(profile);val capped=newHours==999&&newMinutes==59&&newSeconds==59
                work[o[0]]=(((work[o[0]].toInt()and 0xFF)and 0xFE)or(if(capped)1 else 0)).toByte();writeU16BE(work,o[1],newHours);work[o[2]]=newMinutes.toByte();work[o[3]]=newSeconds.toByte();updateGen2PrimaryChecksum(work,profile)
                val expected=gen2PlayTimeState(work,profile);require(expected.hours==newHours&&expected.minutes==newMinutes&&expected.seconds==newSeconds&&expected.frames==openedState.frames&&(((expected.cap and 1)!=0)==capped)){"The staged Gen 2 play time did not match the requested value."}
                require(work.indices.all{it==o[0]||it in o[1]..o[1]+1||it==o[2]||it==o[3]||it in profile.checksumOffset..profile.checksumOffset+1||work[it]==fresh[it]}){"The Gen 2 play-time edit changed unrelated save data."}
                val stagedProfile=detectGen2Profile(work)?:error("The staged Gen 2 save failed checksum verification.");require(stagedProfile.key==profile.key&&gen2ChecksumValid(work,stagedProfile)&&gen2PlayTimeState(work,stagedProfile)==expected){"The staged Gen 2 play time did not verify exactly."}
                require(verifyGen2SaveIntegrity(work).first){"The complete staged Gen 2 save failed integrity validation."}
                require(importedFile?.absolutePath==file.absolutePath&&file.readBytes().contentEquals(fresh)){"The Gen 2 source changed while the play-time edit was staged. Nothing was written."}
                require(bound()){"The confirmed Gen 2 source identity changed before backup."}
                val backup=File.createTempFile(backupGameName(file)+"_PreGen2PlayTime_",".backup",backupsDir());safetyBackup=backup
                backup.writeBytes(fresh);require(backup.readBytes().contentEquals(fresh)){"The exact pre-edit recovery backup could not be verified."}
                retainGen2SafetyBackup(backup,fresh)
                require(bound()&&isBackupKept(backup)&&backup.readBytes().contentEquals(fresh)&&file.readBytes().contentEquals(fresh)){"The confirmed source or retained recovery backup changed before writing."}
                writeStarted=true
                file.writeBytes(work);val persisted=file.readBytes();require(persisted.contentEquals(work)){"The Gen 2 save changed while play time was written."};val persistedProfile=detectGen2Profile(persisted)?:error("The persisted Gen 2 save failed checksum verification.");require(persistedProfile.key==profile.key&&gen2ChecksumValid(persisted,persistedProfile)&&gen2PlayTimeState(persisted,persistedProfile)==expected){"The persisted Gen 2 play time did not match the staged edit."}
                require(bound()&&verifyGen2SaveIntegrity(persisted).first&&file.readBytes().contentEquals(work)){"The persisted Gen 2 source identity or complete save verification failed."}
            }catch(e:Exception){
                val restored=writeStarted&&runCatching{file.writeBytes(fresh)}.isSuccess&&runCatching{file.readBytes().contentEquals(fresh)}.getOrDefault(false)
                val recovery=if(!writeStarted)"Nothing was written to the save." else  if(restored)"The complete fresh working save was restored." else  "Automatic restore could not be verified. Stop editing this save and restore a verified backup."
                showDialog("Gen 2 play-time edit failed",(e.message?:"Unknown error")+"\n\n$recovery"+(safetyBackup?.let{"\n\nRecovery backup: "+it.name}?:""));return@addButton
            }
            Toast.makeText(this,"Gen 2 play time updated and verified",Toast.LENGTH_LONG).show();showGen2PlayTimeEditor()
        }
