    private fun gen2BadgeOffset(profile:Gen2Profile):Int = if(profile.key=="C")0x23E5 else 0x23E4

    private fun gen2BadgeState(data:ByteArray,profile:Gen2Profile):ByteArray{
        val offset=gen2BadgeOffset(profile);require(offset+1<data.size){"The Gen 2 badge fields are outside the save."}
        return data.copyOfRange(offset,offset+2)
    }

    private fun showGen2BadgeEditor(){
        val openedUri=currentSourceUri;val openedLabel=currentSourceLabel
