        val openedState=gen2BadgeState(opened,openedProfile);val names=listOf("Zephyr","Hive","Plain","Fog","Mineral","Storm","Glacier","Rising","Boulder","Cascade","Thunder","Rainbow","Soul","Marsh","Volcano","Earth")
        val selected=BooleanArray(16){index->((openedState[index/8].toInt()and 0xFF)and(1 shl(index and 7)))!=0}
        val root=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(dp(18),dp(36),dp(18),dp(24));setBackgroundColor(BG)}
        root.addView(TextView(this).apply{text="Gen 2 Badges";textSize=28f;typeface=Typeface.DEFAULT_BOLD;setTextColor(TEXT)})
        root.addView(TextView(this).apply{text="Edit the eight Johto and eight Kanto badge flags for Pokémon Gold, Silver and Crystal.";textSize=14f;setTextColor(MUTED);setPadding(0,dp(4),0,dp(12))})
        val summary=TextView(this).apply{textSize=14f;setTextColor(TEXT);setPadding(dp(4),dp(4),dp(4),dp(10))};root.addView(summary);val checks=ArrayList<CheckBox>()
        fun refreshSummary(){summary.text="Johto: ${selected.sliceArray(0 until 8).count{it}} / 8    •    Kanto: ${selected.sliceArray(8 until 16).count{it}} / 8"}
        fun refreshChecks(){for(i in selected.indices)checks[i].isChecked=selected[i];refreshSummary()}
        addButton(root,"Mark All Badges"){for(i in selected.indices)selected[i]=true;refreshChecks()};addButton(root,"Clear All Badges"){for(i in selected.indices)selected[i]=false;refreshChecks()}
        for(i in names.indices){val region=if(i<8)"Johto" else "Kanto";val check=CheckBox(this).apply{text="$region • ${names[i]} Badge";textSize=15f;setTextColor(TEXT);isChecked=selected[i];setPadding(dp(8),dp(5),dp(8),dp(5))};check.setOnCheckedChangeListener{_,value->selected[i]=value;refreshSummary()};checks.add(check);root.addView(check)}
        refreshSummary()
        root.addView(TextView(this).apply{text="PSE changes only the two official badge bytes, rebuilds the primary checksum, rejects stale state without writing, verifies the staged and persisted working save, and verifies any attempted restore after a write failure. A retained recovery backup is required before saving.";textSize=13f;setTextColor(MUTED);setPadding(dp(4),dp(18),dp(4),dp(12))})
        var consumed=false
        addButton(root,"Save Badges"){
            if(consumed){showDialog("Gen 2 Badges","This edit was already submitted. Reopen Badges before saving again.");return@addButton}
            if(importedFile?.absolutePath!=file.absolutePath){showDialog("Gen 2 badge edit failed","The active save changed. Reopen Badges before editing. Nothing was changed.");return@addButton}
            if(!bound()){showDialog("Gen 2 badge edit failed","The source identity changed. Reopen Badges before editing. Nothing was changed.");return@addButton}
            consumed=true
            val fresh=runCatching{file.readBytes()}.getOrElse{showDialog("Gen 2 badge edit failed","The fresh Gen 2 save could not be read. Nothing was changed.");return@addButton}
            var safetyBackup:File?=null
            var writeStarted=false
            try{
                require(bound()&&verifyGen2SaveIntegrity(fresh).first){"The confirmed Gen 2 source identity or full save integrity changed."}
                val profile=detectGen2Profile(fresh)?:error("The fresh Gen 2 save failed checksum validation.");require(profile.key==openedProfile.key){"The Gen 2 game profile changed while the editor was open."};require(gen2BadgeState(fresh,profile).contentEquals(openedState)){"Badge progress changed after this screen was opened. Reopen the editor and try again."}
                val work=fresh.copyOf();val offset=gen2BadgeOffset(profile);var johto=0;var kanto=0;for(i in 0 until 8){if(selected[i])johto=johto or(1 shl i);if(selected[i+8])kanto=kanto or(1 shl i)};work[offset]=johto.toByte();work[offset+1]=kanto.toByte();updateGen2PrimaryChecksum(work,profile);val expected=gen2BadgeState(work,profile)
                require(work.indices.all{it in offset..offset+1||it in profile.checksumOffset..profile.checksumOffset+1||work[it]==fresh[it]}){"The Gen 2 badge edit changed unrelated save data."}
                val stagedProfile=detectGen2Profile(work)?:error("The staged Gen 2 save failed checksum verification.");require(stagedProfile.key==profile.key&&gen2ChecksumValid(work,stagedProfile)&&gen2BadgeState(work,stagedProfile).contentEquals(expected)){"The staged Gen 2 badges did not verify exactly."}
                for(i in selected.indices){val byte=expected[i/8].toInt()and 0xFF;require(((byte and(1 shl(i and 7)))!=0)==selected[i]){"A staged Gen 2 badge did not match the requested state."}}
                require(verifyGen2SaveIntegrity(work).first){"The complete staged Gen 2 save failed integrity validation."}
                require(importedFile?.absolutePath==file.absolutePath&&file.readBytes().contentEquals(fresh)){"The Gen 2 source changed while the badge edit was staged. Nothing was written."}
                require(bound()){"The confirmed Gen 2 source identity changed before backup."}
                val backup=File.createTempFile(backupGameName(file)+"_PreGen2Badges_",".backup",backupsDir());safetyBackup=backup
                backup.writeBytes(fresh);require(backup.readBytes().contentEquals(fresh)){"The exact pre-edit recovery backup could not be verified."}
                retainGen2SafetyBackup(backup,fresh)
                require(bound()&&isBackupKept(backup)&&backup.readBytes().contentEquals(fresh)&&file.readBytes().contentEquals(fresh)){"The confirmed source or retained recovery backup changed before writing."}
                writeStarted=true
                file.writeBytes(work);val persisted=file.readBytes();require(persisted.contentEquals(work)){"The Gen 2 save changed while badges were written."};val persistedProfile=detectGen2Profile(persisted)?:error("The persisted Gen 2 save failed checksum verification.");require(persistedProfile.key==profile.key&&gen2ChecksumValid(persisted,persistedProfile)&&gen2BadgeState(persisted,persistedProfile).contentEquals(expected)){"The persisted Gen 2 badges did not match the staged edit."}
                require(bound()&&verifyGen2SaveIntegrity(persisted).first&&file.readBytes().contentEquals(work)){"The persisted Gen 2 source identity or complete save verification failed."}
            }catch(e:Exception){
                val restored=writeStarted&&runCatching{file.writeBytes(fresh)}.isSuccess&&runCatching{file.readBytes().contentEquals(fresh)}.getOrDefault(false)
                val recovery=if(!writeStarted)"Nothing was written to the save." else  if(restored)"The complete fresh working save was restored." else  "Automatic restore could not be verified. Stop editing this save and restore a verified backup."
                showDialog("Gen 2 badge edit failed",(e.message?:"Unknown error")+"\n\n$recovery"+(safetyBackup?.let{"\n\nRecovery backup: "+it.name}?:""));return@addButton
            }
            Toast.makeText(this,"Gen 2 badges updated and verified",Toast.LENGTH_LONG).show();showGen2BadgeEditor()
        }
        addButton(root,"Back to Trainer Data"){showTrainerData()};setContentView(ScrollView(this).apply{addView(root)});phoneBackAction={showTrainerData()}
    }

    private data class Gen2CurrencyState(val money:Long,val coins:Int)

    private fun gen2MoneyOffset(profile:Gen2Profile):Int = if(profile.key=="C")0x23DC else 0x23DB

    private fun gen2CurrencyState(data:ByteArray,profile:Gen2Profile):Gen2CurrencyState{
        val offset=gen2MoneyOffset(profile);require(offset+8<data.size){"The Gen 2 currency fields are outside the save."}
        val state=Gen2CurrencyState(readU24BE(data,offset),readU16BE(data,offset+7));require(state.money in 0L..999999L&&state.coins in 0..9999){"The Gen 2 currency fields are invalid."};return state
    }

