                val profile=detectGen2Profile(fresh)?:error("The fresh Gen 2 save failed checksum validation.");require(profile.key==openedProfile.key){"The Gen 2 game profile changed while the editor was open."};require(gen2CurrencyState(fresh,profile)==openedState){"Currency changed after this screen was opened. Reopen the editor and try again."}
                val work=fresh.copyOf();val offset=gen2MoneyOffset(profile);writeU24BE(work,offset,newMoney);writeU16BE(work,offset+7,newCoins);updateGen2PrimaryChecksum(work,profile);val expected=gen2CurrencyState(work,profile);require(expected.money==newMoney&&expected.coins==newCoins){"The staged Gen 2 currency did not match the requested values."}
                require(work.indices.all{it in offset..offset+2||it in offset+7..offset+8||it in profile.checksumOffset..profile.checksumOffset+1||work[it]==fresh[it]}){"The Gen 2 currency edit changed unrelated save data."}
