            val dex=i+1;val name=GEN2_NATIONAL_NAMES.getOrElse(i){"Pokémon #$dex"};val row=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL;gravity=Gravity.CENTER_VERTICAL;background=roundedBg(CARD,Color.rgb(20,95,135),12);setPadding(dp(8),dp(5),dp(8),dp(5))}
