            val sprite=ImageView(this).apply{scaleType=ImageView.ScaleType.FIT_CENTER;contentDescription=name};row.addView(sprite,LinearLayout.LayoutParams(dp(58),dp(58)));loadGen2Sprite(sprite,dex,false)
            row.addView(TextView(this).apply{text=name;textSize=15f;typeface=Typeface.DEFAULT_BOLD;setTextColor(TEXT);gravity=Gravity.CENTER_VERTICAL;maxLines=2},LinearLayout.LayoutParams(0,dp(64),1f))
            val sc=CheckBox(this).apply{text="Seen";textSize=13f;setTextColor(TEXT);isChecked=seen[i]};val oc=CheckBox(this).apply{text="Owned";textSize=13f;setTextColor(TEXT);isChecked=owned[i]};seenChecks.add(sc);ownedChecks.add(oc)
            sc.setOnCheckedChangeListener{_,v->seen[i]=v;if(!v&&owned[i]){owned[i]=false;oc.isChecked=false};refreshSummary()};oc.setOnCheckedChangeListener{_,v->owned[i]=v;if(v&&!seen[i]){seen[i]=true;sc.isChecked=true};refreshSummary()}
            row.addView(sc,LinearLayout.LayoutParams(dp(82),dp(64)));row.addView(oc,LinearLayout.LayoutParams(dp(92),dp(64)));list.addView(row,LinearLayout.LayoutParams(-1,-2).apply{bottomMargin=dp(6)})
