        root.addView(TextView(this).apply{text="Safe saving";textSize=17f;typeface=Typeface.DEFAULT_BOLD;setTextColor(TEXT);setPadding(dp(4),dp(16),dp(4),dp(4))})
        root.addView(TextView(this).apply{text="PSE changes only the 251 Seen/Owned flags, preserves unused flag bits and all unrelated bytes, rebuilds the Gen 2 checksum, rejects stale state without writing, verifies the persisted working save, and verifies any attempted restore after a write failure. A retained recovery backup is required before saving.";textSize=13f;setTextColor(MUTED);setPadding(dp(4),0,dp(4),dp(10))})
