    private fun showGen3TrainerEditor() {
        val file = importedFile ?: return showHome()
        val openedSourceUri = currentSourceUri
        val openedSourceLabel = currentSourceLabel
        val opened = runCatching { file.readBytes() }.getOrNull() ?: run {
            showDialog("Gen 3 Trainer Editor", "PSE could not read the loaded save.")
            return
        }
        if (generationForSize(opened.size) != 3 || !gen3SaveValid(opened)) {
            showDialog("Gen 3 Trainer Editor", "This screen requires a valid Generation 3 save.")
            return
        }
        val game = detectGen3GameFromData(opened, openedSourceLabel ?: file.name)
        val trainer = parseGen3Trainer(opened, game) ?: run {
            showDialog("Gen 3 Trainer Editor", "PSE could not read the active Gen 3 trainer section.")
            return
        }
        phoneBackAction = { showTrainerData() }
        val scroll = ScrollView(this).apply { setBackgroundColor(BG) }
        val root = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(dp(16), dp(42), dp(16), dp(24))
            setBackgroundColor(BG)
        }
        scroll.addView(root)
        root.addView(TextView(this).apply {
            text = "Edit Gen 3 Trainer"
            textSize = 28f
            typeface = Typeface.DEFAULT_BOLD
            setTextColor(TEXT)
        })
        addMutedLine(root, "$game • active trainer section")
        val nameInput = inputField("Trainer name (1–7 supported Gen 3 characters)", trainer.trainerName).also { root.addView(it.first) }.second
        val tidInput = inputField("Trainer ID (0–65535)", trainer.tid.toString(), true).also { root.addView(it.first) }.second
        val sidInput = inputField("Secret ID (0–65535)", trainer.sid.toString(), true).also { root.addView(it.first) }.second
        val genderSpinner = Spinner(this)
        val genders = listOf("Male", "Female")
        genderSpinner.adapter = ArrayAdapter(this, android.R.layout.simple_spinner_dropdown_item, genders)
        genderSpinner.setSelection(if (trainer.gender == "Female") 1 else 0)
        root.addView(TextView(this).apply {
            text = "Player gender"
            textSize = 14f
            setTextColor(MUTED)
            setPadding(0, dp(8), 0, dp(4))
        })
        root.addView(genderSpinner, LinearLayout.LayoutParams(-1, dp(56)))
        val hoursInput = inputField("Play time hours (0–999)", trainer.playedHours.toString(), true).also { root.addView(it.first) }.second
        val minutesInput = inputField("Play time minutes (0–59)", trainer.playedMinutes.toString(), true).also { root.addView(it.first) }.second
        val secondsInput = inputField("Play time seconds (0–59)", trainer.playedSeconds.toString(), true).also { root.addView(it.first) }.second
        val framesInput = inputField("Play time frames (0–59)", trainer.playedFrames.toString(), true).also { root.addView(it.first) }.second
        val loadedState = Gen3TrainerState(
            name = trainer.trainerName,
            trainerId = trainer.tid,
            secretId = trainer.sid,
            money = trainer.money.toInt(),
            gender = if (trainer.gender == "Female") 1 else 0,
            playedHours = trainer.playedHours,
            playedMinutes = trainer.playedMinutes,
            playedSeconds = trainer.playedSeconds,
            playedFrames = trainer.playedFrames
        )
        var reviewedSummary = emptyList<String>()
        val reviewText = TextView(this).apply {
            text = "Pending trainer changes have not been reviewed."
            textSize = 14f
            setTextColor(MUTED)
            setPadding(dp(4), dp(10), dp(4), dp(6))
        }
        val reviewAcknowledged = CheckBox(this).apply {
            text = "I reviewed these exact pending trainer changes"
            setTextColor(TEXT)
            isChecked = false
        }
        fun invalidateReview() {
            reviewedSummary = emptyList()
            reviewAcknowledged.isChecked = false
            reviewText.text = "Pending trainer changes have not been reviewed."
        }
        fun readEditedState(): Gen3TrainerState? {
            val name = nameInput.text.toString().trim()
            val tid = tidInput.text.toString().toIntOrNull()
            val sid = sidInput.text.toString().toIntOrNull()
            val playedHours = hoursInput.text.toString().toIntOrNull()
            val playedMinutes = minutesInput.text.toString().toIntOrNull()
            val playedSeconds = secondsInput.text.toString().toIntOrNull()
            val playedFrames = framesInput.text.toString().toIntOrNull()
            val supportedName = name.length in 1..7 && name.all { character ->
                character in 'A'..'Z' ||
                    character in 'a'..'z' ||
                    character in '0'..'9' ||
                    character in " !?.,/'-♂♀"
            }
            if (!supportedName) {
                showDialog(
                    "Gen 3 Trainer Editor",
                    "Trainer name must contain 1–7 supported Gen 3 characters: letters, numbers, spaces, or ! ? . , / ' - ♂ ♀."
                )
                return null
            }
            if (tid == null || tid !in 0..65535 || sid == null || sid !in 0..65535) {
                showDialog("Gen 3 Trainer Editor", "Trainer ID and Secret ID must each be between 0 and 65535.")
                return null
            }
            if (playedHours == null || playedHours !in 0..999 ||
                playedMinutes == null || playedMinutes !in 0..59 ||
                playedSeconds == null || playedSeconds !in 0..59 ||
                playedFrames == null || playedFrames !in 0..59) {
                showDialog("Gen 3 Trainer Editor", "Play time must use 0–999 hours and 0–59 minutes, seconds, and frames.")
                return null
            }
            return try {
                val renamed = Gen3TrainerEditing.rename(loadedState, name)
                val withIds = Gen3TrainerEditing.setTrainerIds(renamed, tid, sid)
                val withGender = Gen3TrainerEditing.setGender(withIds, genderSpinner.selectedItemPosition)
                Gen3TrainerEditing.setPlayTime(
                    withGender,
                    playedHours,
                    playedMinutes,
                    playedSeconds,
                    playedFrames
                )
            } catch (e: IllegalArgumentException) {
                showDialog("Gen 3 Trainer Editor", e.message ?: "The trainer values are invalid.")
                null
            }
        }
        addButton(root, "↺  Reset Play Time to Zero") {
            val reset = Gen3TrainerEditing.resetPlayTime(loadedState)
            hoursInput.setText(reset.playedHours.toString())
            minutesInput.setText(reset.playedMinutes.toString())
            secondsInput.setText(reset.playedSeconds.toString())
            framesInput.setText(reset.playedFrames.toString())
            invalidateReview()
            Toast.makeText(this, "Play time set to zero in the form; tap Review, acknowledge, then Save to persist it", Toast.LENGTH_LONG).show()
        }
        addButton(root, "↶  Restore Loaded Values") {
            val restored = Gen3TrainerEditing.restoreLoadedValues(loadedState)
            nameInput.setText(restored.name)
            tidInput.setText(restored.trainerId.toString())
            sidInput.setText(restored.secretId.toString())
            genderSpinner.setSelection(restored.gender)
            hoursInput.setText(restored.playedHours.toString())
            minutesInput.setText(restored.playedMinutes.toString())
            secondsInput.setText(restored.playedSeconds.toString())
            framesInput.setText(restored.playedFrames.toString())
            invalidateReview()
            Toast.makeText(this, "Unsaved trainer edits restored to the loaded save values", Toast.LENGTH_LONG).show()
        }
        addButton(root, "Review Pending Trainer Changes") review@{
            val edited = readEditedState() ?: return@review
            reviewedSummary = Gen3TrainerEditing.changeSummary(loadedState, edited)
            reviewAcknowledged.isChecked = false
            reviewText.text = if (reviewedSummary.isEmpty()) {
                "No trainer values have changed."
            } else {
                "Exact pending changes:\n" + reviewedSummary.joinToString("\n") { "• $it" }
            }
        }
        root.addView(reviewText)
        root.addView(reviewAcknowledged)
        addMutedLine(root, "Reset and Restore change only the form. Review shows the exact pending values and must still match at Save. PSE changes only the trainer-name, ID, player-gender, and complete play-time bytes in the active Gen 3 section, rebuilds its checksum, verifies the saved values, and restores the original bytes if any check fails.")
        addButton(root, "💾  Save Gen 3 Trainer") save@{
            val edited = readEditedState() ?: return@save
            val changeSummary = Gen3TrainerEditing.changeSummary(loadedState, edited)
            if (changeSummary.isEmpty()) {
                showDialog("Gen 3 Trainer Editor", "No trainer values have changed, so nothing was written.")
                return@save
            }
            if (!Gen3TrainerEditing.isReviewedForSave(
                    loadedState,
                    edited,
                    reviewedSummary,
                    reviewAcknowledged.isChecked
                )) {
                showDialog(
                    "Review required",
                    "Tap Review Pending Trainer Changes, inspect the exact values, and acknowledge that review before saving. If the form changed after review, review it again."
                )
                return@save
            }
            AlertDialog.Builder(this)
                .setTitle("Save reviewed Gen 3 trainer changes?")
                .setMessage("Reviewed exact changes:\n${changeSummary.joinToString("\n") { "• $it" }}\n\nA verified recovery backup will be pinned before PSE writes the working copy.")
                .setNegativeButton("Cancel", null)
                .setPositiveButton("Save") { _, _ ->
                    applyGen3TrainerEdit(file, opened, openedSourceUri, openedSourceLabel, edited)
                }
                .show()
        }
        addButton(root, "Cancel") { showTrainerData() }
        setContentView(scroll)
    }

    private fun applyGen3TrainerEdit(
        file: File,
        opened: ByteArray,
        openedSourceUri: Uri?,
        openedSourceLabel: String?,
        edited: Gen3TrainerState
    ) {
        var writeStarted = false
        try {
            require(importedFile?.absolutePath == file.absolutePath &&
                currentSourceUri == openedSourceUri &&
                currentSourceLabel == openedSourceLabel) {
                "The loaded save identity changed while the editor was open."
            }
            val fresh = file.readBytes()
            require(fresh.contentEquals(opened)) {
                "The save changed while the editor was open. Reopen Trainer Data before saving."
            }
            require(generationForSize(fresh.size) == 3 && gen3SaveValid(fresh)) {
                "The fresh save is no longer a valid Generation 3 save."
            }
            val section0 = gen3ActiveSection(fresh, 0)
                ?: error("PSE could not map the active Gen 3 trainer section.")
            val work = fresh.copyOf()
            writeGen3Text(work, section0, 7, edited.name)
            work[section0 + 0x08] = edited.gender.toByte()
            writeU16LE(work, section0 + 0x0A, edited.trainerId)
            writeU16LE(work, section0 + 0x0C, edited.secretId)
            writeU16LE(work, section0 + 0x0E, edited.playedHours)
            work[section0 + 0x10] = edited.playedMinutes.toByte()
            work[section0 + 0x11] = edited.playedSeconds.toByte()
            work[section0 + 0x12] = edited.playedFrames.toByte()
            updateGen3SectionChecksumAt(work, section0, 0)
            require(gen3SaveValid(work)) {
                "The edited save failed Gen 3 section validation."
            }
            val allowed = HashSet<Int>()
            for (i in 0 until 7) allowed.add(section0 + i)
            allowed.add(section0 + 0x08)
            for (i in 0x0A..0x12) allowed.add(section0 + i)
            allowed.add(section0 + 0xFF6)
            allowed.add(section0 + 0xFF7)
            require(work.indices.all { it in allowed || work[it] == fresh[it] }) {
                "The trainer edit changed unrelated save data."
            }
            val backup = File.createTempFile(
                backupGameName(file) + "_PreGen3Trainer_",
                ".backup",
                backupsDir()
            )
            backup.writeBytes(fresh)
            require(backup.readBytes().contentEquals(fresh)) {
                "The recovery backup did not verify."
            }
            retainGen2ToGen3SafetyBackup(backup, fresh)
            require(importedFile?.absolutePath == file.absolutePath &&
                currentSourceUri == openedSourceUri &&
                currentSourceLabel == openedSourceLabel &&
                file.readBytes().contentEquals(fresh)) {
                "The active save changed before writing. Nothing was changed."
            }
            writeStarted = true
            file.writeBytes(work)
            val verify = file.readBytes()
            require(verify.contentEquals(work) && gen3SaveValid(verify)) {
                "The persisted Gen 3 save failed byte or checksum verification."
            }
            val parsed = parseGen3Trainer(
                verify,
                detectGen3GameFromData(verify, openedSourceLabel ?: file.name)
            ) ?: error("The persisted trainer data could not be read.")
            val expectedGender = if (edited.gender == 1) "Female" else "Male"
            require(parsed.trainerName == edited.name &&
                parsed.tid == edited.trainerId &&
                parsed.sid == edited.secretId &&
                parsed.gender == expectedGender &&
                parsed.playedHours == edited.playedHours &&
                parsed.playedMinutes == edited.playedMinutes &&
                parsed.playedSeconds == edited.playedSeconds &&
                parsed.playedFrames == edited.playedFrames) {
                "The Gen 3 trainer values did not persist exactly."
            }
            Toast.makeText(this, "Gen 3 trainer updated and verified", Toast.LENGTH_LONG).show()
            showTrainerData()
        } catch (e: Exception) {
            if (writeStarted) runCatching { file.writeBytes(opened) }
            showDialog(
                "Gen 3 trainer edit failed",
                (e.message ?: "Unknown error") + "\n\n" +
                    if (writeStarted) "The original save was restored where possible." else "Nothing was written."
            )
        }
    }

    private fun showTrainerData() {
        if (openActiveSwitchSection("trainer")) return
        phoneBackAction = { showHome() }
        val file = importedFile
        if (file == null) {
            showDialog("Trainer Data", "No save is loaded yet. Tap Import 3DS Save first.")
            return
        }
        val a = analyzeSave(file)
        if (!a.structurallyValid) {
            showDialog("Trainer Data", "This file has not passed structural validation, so trainer data will not be interpreted.")
            return
        }
        val t = a.trainer
        if (t == null) {
            showDialog("Trainer Data", "Trainer data could not be read from this save.")
            return
        }
        val trainerGen = generationForSize(a.actualSize)
        val displayedGame = sourceGameIdentity(file, currentSourceLabel) ?: t.exactGame

        val scroll = ScrollView(this).apply { setBackgroundColor(BG) }
        val root = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(dp(16), dp(42), dp(16), dp(24))
            setBackgroundColor(BG)
        }
        scroll.addView(root)

        root.addView(TextView(this).apply {
            text = "Trainer Data"
            textSize = 28f
            typeface = Typeface.DEFAULT_BOLD
            setTextColor(TEXT)
        })
        root.addView(TextView(this).apply {
            text = "$displayedGame • Gen $trainerGen"
            textSize = 15f
            setTextColor(MUTED)
            setPadding(0, dp(4), 0, dp(18))
        })

        val gen2PlayTime = if (trainerGen == 2) {
            runCatching {
                val bytes = file.readBytes()
                val profile = detectGen2Profile(bytes) ?: error("Invalid Gen 2 save")
                gen2PlayTimeState(bytes, profile)
            }.getOrNull()
        } else null
        val gen2Currency = if (trainerGen == 2) {
            runCatching {
                val bytes = file.readBytes()
                val profile = detectGen2Profile(bytes) ?: error("Invalid Gen 2 save")
                gen2CurrencyState(bytes, profile)
            }.getOrNull()
        } else null
        addTrainerSummaryCard(root, t, trainerGen, gen2PlayTime, gen2Currency)
        if (trainerGen == 1) {
            addButton(root, "✏  Edit Gen 1 Trainer") { showGen1TrainerEditor() }
            addButton(root, "▣  Edit Gen 1 Pokédex") { showGen1PokedexEditor() }
            addButton(root, "◆  Edit Gen 1 Progress") { showGen1ProgressEditor() }
            addButton(root, "⌂  Gen 1 Day Care") { showGen1DayCare() }

        } else if (trainerGen == 2) {
            val trainerSourceUri=currentSourceUri;val trainerSourceLabel=currentSourceLabel
            val trainerSnapshot=runCatching{file.readBytes()}.getOrNull()
            fun verifiedGen2TrainerSource():Boolean {
                if(trainerSnapshot!=null&&gen2ListSnapshotMatches(file,trainerSnapshot,trainerSourceUri,trainerSourceLabel))return true
                showDialog("Gen 2 Trainer Data","The save identity, bytes or integrity changed while Trainer Data was open. Reopen Trainer Data. Nothing was changed.");return false
            }
            addButton(root, "✏  Edit Gen 2 Trainer") { if(!verifiedGen2TrainerSource())return@addButton; showGen2TrainerEditor() }
            addButton(root, "◷  Edit Gen 2 Play Time") { if(!verifiedGen2TrainerSource())return@addButton; showGen2PlayTimeEditor() }
            addButton(root, "◷  Request Gen 2 Clock Reset") { if(!verifiedGen2TrainerSource())return@addButton; confirmGen2ClockReset() }
            addButton(root, "◆  Edit Gen 2 Badges") { if(!verifiedGen2TrainerSource())return@addButton; showGen2BadgeEditor() }
            addButton(root, "¤  Edit Gen 2 Currency") { if(!verifiedGen2TrainerSource())return@addButton; showGen2CurrencyEditor() }
            addButton(root, "▣  Edit Gen 2 Pokédex") { if(!verifiedGen2TrainerSource())return@addButton; showGen2PokedexEditor() }
            addButton(root, "⌂  View Gen 2 Day Care") { if(!verifiedGen2TrainerSource())return@addButton; showGen2DayCare() }
            root.addView(TextView(this).apply {
                text = "Gen 2 trainer editing covers the verified trainer name, Trainer ID, rival name, Crystal player gender and play-time fields. Gold and Silver correctly keep their male player character fixed. Badge progress is also editable. Trainer currency is editable separately. Other trainer values remain read-only until their exact version-specific layouts are verified."
                textSize = 14f
                setTextColor(MUTED)
                setPadding(dp(4), dp(2), dp(4), dp(12))
            })
        } else if (trainerGen == 3) {
            addButton(root, "✏  Edit Gen 3 Trainer") { showGen3TrainerEditor() }
            addButton(root, "▣  Edit Gen 3 Pokédex") { showPokedexEditor() }
            root.addView(TextView(this).apply {
                text = "Gen 3 trainer editing safely updates the 1–7 character trainer name, Trainer ID, Secret ID, player gender, and complete play time including frames. PSE preserves all unrelated bytes, rebuilds the active section checksum, verifies persistence, and rolls back automatically on failure."
                textSize = 14f
                setTextColor(MUTED)
                setPadding(dp(4), dp(2), dp(4), dp(12))
            })
        } else if (trainerGen == 4) {
            root.addView(TextView(this).apply {
                text = "Gen 4 trainer data is now readable. Trainer editing stays locked until the Gen 4 write/checksum path is enabled."
                textSize = 14f
                setTextColor(MUTED)
                setPadding(dp(4), dp(2), dp(4), dp(12))
            })
        } else {
            addButton(root, "✏️  Edit Trainer") { showTrainerEditor() }
        }
        addButton(root, "←  Back to Home") { showHome() }
        val shell = LinearLayout(this).apply { orientation = LinearLayout.VERTICAL; setBackgroundColor(BG) }
        shell.addView(scroll, LinearLayout.LayoutParams(-1, 0, 1f))
        shell.addView(buildBottomNav("home"), LinearLayout.LayoutParams(-1, -2))
        setContentView(shell)
    }

    private fun addTrainerSummaryCard(root: LinearLayout, t: TrainerData, generation: Int, gen2PlayTime: Gen2PlayTimeState? = null, gen2Currency: Gen2CurrencyState? = null) {
        val card = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(dp(16), dp(14), dp(16), dp(14))
            background = roundedBg(CARD, Color.rgb(20, 95, 135), 14)
        }
        fun line(label: String, value: String) {
            card.addView(TextView(this).apply {
                text = "$label: $value"
                textSize = 16f
                setTextColor(TEXT)
                setPadding(0, dp(3), 0, dp(3))
            })
        }
        line("Trainer", t.trainerName.ifBlank { "(blank)" })
        line("TID", t.tid.toString().padStart(5, '0'))
        if (generation >= 3) line("SID", t.sid.toString().padStart(5, '0'))
        line("Gender", t.gender)
        line("Language", t.language)
        line("Money", String.format(Locale.US, "%,d", t.money))
        if (gen2Currency != null) line("Coins", String.format(Locale.US, "%,d", gen2Currency.coins))
        if (generation == 7) line("Region", "Alola") else line("Badges", t.badges.toString())
        val playTime = gen2PlayTime?.let { "${it.hours}:${it.minutes.toString().padStart(2, '0')}:${it.seconds.toString().padStart(2, '0')}" }
            ?: "${t.playedHours}:${t.playedMinutes.toString().padStart(2, '0')}:${t.playedSeconds.toString().padStart(2, '0')}"
        line("Play time", playTime)
        root.addView(card, LinearLayout.LayoutParams(-1, -2).apply { bottomMargin = dp(12) })
    }

    private fun showTrainerEditor() {
        phoneBackAction = { showTrainerData() }
        val file = importedFile ?: return showHome()
        val analysis = analyzeSave(file)
        val trainer = analysis.trainer
        val trainerGeneration = generationForSize(analysis.actualSize)
        if (trainerGeneration == 1 || trainerGeneration == 4) {
            val message = if (trainerGeneration == 4)
                "Gen 4 trainer editing is not enabled yet. Trainer data is read-only until PSE enables the Gen 4 write path with block CRC rebuild and rollback verification."
            else
                "Gen 1 trainer editing is not enabled yet. This first Gen 1 build is read/scan/import only so we can validate Game Boy & Game Boy Color save detection safely before enabling writes."
            showDialog("Trainer Editor", message)
            return
        }
        if (!analysis.structurallyValid || trainer == null || !trainer.gameMatchesFamily) {
            showDialog("Trainer Editor", "PSE will not edit trainer data unless the loaded save passes structural and game-family validation.")
            return
        }

        val scroll = ScrollView(this).apply { setBackgroundColor(BG) }
        val root = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(dp(16), dp(42), dp(16), dp(24))
            setBackgroundColor(BG)
        }
        scroll.addView(root)

        root.addView(TextView(this).apply {
            text = "Edit Trainer"
            textSize = 28f
            typeface = Typeface.DEFAULT_BOLD
            setTextColor(TEXT)
        })
        root.addView(TextView(this).apply {
            text = "${trainer.exactGame}\nChanges are made only to PSE's working copy. Your emulator save is untouched until Save & Replace Current Save."
            textSize = 14f
            setTextColor(MUTED)
            setPadding(0, dp(4), 0, dp(16))
        })

        fun label(text: String) = TextView(this).apply {
            this.text = text
            textSize = 14f
            setTextColor(MUTED)
            setPadding(0, dp(8), 0, dp(4))
        }
        fun edit(value: String, numeric: Boolean = false) = EditText(this).apply {
            setText(value)
            setTextColor(TEXT)
            setHintTextColor(MUTED)
            setBackgroundColor(CARD)
            setPadding(dp(12), dp(10), dp(12), dp(10))
            if (numeric) inputType = android.text.InputType.TYPE_CLASS_NUMBER
        }

        root.addView(label("Trainer name (max 12 characters)"))
        val nameInput = edit(trainer.trainerName)
        root.addView(nameInput, LinearLayout.LayoutParams(-1, -2))

        root.addView(label("Trainer ID (0–65535)"))
        val tidInput = edit(trainer.tid.toString(), true)
        root.addView(tidInput, LinearLayout.LayoutParams(-1, -2))

        root.addView(label("Secret ID (0–65535)"))
        val sidInput = edit(trainer.sid.toString(), true)
        root.addView(sidInput, LinearLayout.LayoutParams(-1, -2))

        root.addView(label("Gender"))
        val genderSpinner = Spinner(this)
        val genders = listOf("Male", "Female")
        genderSpinner.adapter = ArrayAdapter(this, android.R.layout.simple_spinner_dropdown_item, genders)
        genderSpinner.setSelection(if (trainer.gender == "Female") 1 else 0)
        root.addView(genderSpinner, LinearLayout.LayoutParams(-1, -2))

        root.addView(label("Language"))
        val languages = trainerLanguageChoices()
        val languageSpinner = Spinner(this)
        languageSpinner.adapter = ArrayAdapter(this, android.R.layout.simple_spinner_dropdown_item, languages.map { it.second })
        val currentLanguage = languages.indexOfFirst { it.second == trainer.language }.takeIf { it >= 0 } ?: 1
        languageSpinner.setSelection(currentLanguage)
        root.addView(languageSpinner, LinearLayout.LayoutParams(-1, -2))

        root.addView(label("Money (0–9,999,999)"))
        val moneyInput = edit(trainer.money.toString(), true)
        root.addView(moneyInput, LinearLayout.LayoutParams(-1, -2))

        root.addView(TextView(this).apply {
            text = "TID/SID, name, gender, language and money are written to their game-specific trainer blocks. PSE rebuilds the affected save-block checksums and verifies every edited value before keeping the change."
            textSize = 13f
            setTextColor(MUTED)
            setPadding(0, dp(16), 0, dp(8))
        })

        addButton(root, "💾  Save Trainer Changes") {
            val name = nameInput.text.toString().trim()
            val tid = tidInput.text.toString().toIntOrNull()
            val sid = sidInput.text.toString().toIntOrNull()
            val money = moneyInput.text.toString().toLongOrNull()
            if (name.isEmpty() || name.length > 12) {
                showDialog("Trainer Editor", "Trainer name must be 1–12 characters.")
                return@addButton
            }
            if (tid == null || tid !in 0..65535 || sid == null || sid !in 0..65535) {
                showDialog("Trainer Editor", "TID and SID must each be between 0 and 65535.")
                return@addButton
            }
            if (money == null || money !in 0L..9_999_999L) {
                showDialog("Trainer Editor", "Money must be between 0 and 9,999,999.")
                return@addButton
            }
            val genderRaw = genderSpinner.selectedItemPosition
            val languageRaw = languages[languageSpinner.selectedItemPosition].first
            confirmTrainerEdit(name, tid, sid, genderRaw, languageRaw, money)
        }
        addButton(root, "Cancel") { showTrainerData() }
        setContentView(scroll)
    }

    private fun trainerLanguageChoices(): List<Pair<Int, String>> = listOf(
        1 to "Japanese",
        2 to "English",
        3 to "French",
        4 to "Italian",
        5 to "German",
        7 to "Spanish",
        8 to "Korean",
        9 to "Chinese (Simplified)",
        10 to "Chinese (Traditional)"
    )

    private fun confirmTrainerEdit(name: String, tid: Int, sid: Int, genderRaw: Int, languageRaw: Int, money: Long) {
        AlertDialog.Builder(this)
            .setTitle("Save trainer changes?")
            .setMessage("PSE will update only its working copy. The emulator save will not be changed until you use Save & Replace Current Save.\n\nTrainer: $name\nTID: $tid\nSID: $sid\nGender: ${if (genderRaw == 1) "Female" else "Male"}\nLanguage: ${pokemonLanguageName(languageRaw)}\nMoney: ${String.format(Locale.US, "%,d", money)}")
            .setPositiveButton("Save Changes") { _, _ -> writeTrainerChanges(name, tid, sid, genderRaw, languageRaw, money) }
            .setNegativeButton("Cancel", null)
            .show()
    }

    private fun writeTrainerChanges(name: String, tid: Int, sid: Int, genderRaw: Int, languageRaw: Int, money: Long) {
        val file = importedFile ?: return
        val original = try { file.readBytes() } catch (e: Exception) {
            showDialog("Trainer Editor", "Could not read the working save: ${e.message}")
            return
        }
        val data = original.copyOf()
        try {
            when (data.size) {
                SIZE_G6_XY, SIZE_G6_ORAS -> {
                    writeU16LE(data, STATUS_OFFSET, tid)
                    writeU16LE(data, STATUS_OFFSET + 2, sid)
                    data[STATUS_OFFSET + 5] = genderRaw.toByte()
                    data[STATUS_OFFSET + 0x2D] = languageRaw.toByte()
                    writeGen6String(data, STATUS_OFFSET + 0x48, 0x1A, name)
                    writeU32LE(data, MISC_OFFSET + 0x08, money)
                    updateSaveBlockChecksum(data, 17, STATUS_OFFSET, 0x170)
                    val miscLength = if (data.size == SIZE_G6_XY) 0x140 else 0x130
                    updateSaveBlockChecksum(data, 11, MISC_OFFSET, miscLength)
                }
                SIZE_G7_SM, SIZE_G7_USUM -> {
                    val status = if (data.size == SIZE_G7_SM) STATUS_OFFSET_SM else STATUS_OFFSET_USUM
                    val misc = if (data.size == SIZE_G7_SM) MISC_OFFSET_SM else MISC_OFFSET_USUM
                    writeU16LE(data, status, tid)
                    writeU16LE(data, status + 2, sid)
                    data[status + 5] = genderRaw.toByte()
                    data[status + 0x35] = languageRaw.toByte()
                    writeGen6String(data, status + 0x38, 0x1A, name)
                    writeU32LE(data, misc + 0x04, money)
                    updateSaveBlockChecksum(data, 3, status, 0xC0)
                    updateSaveBlockChecksum(data, 9, misc, if (data.size == SIZE_G7_SM) 0x200 else 0x1FC)
                }
                else -> throw IllegalStateException("Unsupported save size")
            }

            file.writeBytes(data)
            val verified = analyzeSave(file)
            val t = verified.trainer
            val expectedGender = if (genderRaw == 1) "Female" else "Male"
            val expectedLanguage = pokemonLanguageName(languageRaw)
            val ok = verified.structurallyValid && t != null && t.gameMatchesFamily &&
                t.trainerName == name && t.tid == tid && t.sid == sid && t.gender == expectedGender &&
                t.language == expectedLanguage && t.money == money
            if (!ok) {
                file.writeBytes(original)
                showDialog("Trainer edit rolled back", "PSE could not verify every trainer value after writing, so the working save was restored to its previous state.")
                return
            }
            Toast.makeText(this, "Trainer data updated and verified", Toast.LENGTH_LONG).show()
            showTrainerData()
        } catch (e: Exception) {
            runCatching { file.writeBytes(original) }
            showDialog("Trainer edit failed", "No trainer changes were kept. ${e.message ?: "Unknown error"}")
        }
    }

    private fun updateSaveBlockChecksum(data: ByteArray, blockId: Int, offset: Int, length: Int) {
        if (data.size == SIZE_G7_SM || data.size == SIZE_G7_USUM) {
            updateGen7SaveBlockChecksum(data, blockId, offset, length)
            finalizeGen7Save(data)
            return
        }
        if (offset < 0 || length <= 0 || offset + length > data.size) throw IllegalArgumentException("Invalid save block range")
        val crc = crc16Ccitt(data, offset, length)
        val metadata = data.size - 0x200
        val checksumOffset = metadata + 0x14 + (blockId * 8) + 6
        if (checksumOffset < 0 || checksumOffset + 1 >= data.size) throw IllegalArgumentException("Invalid save block checksum location")
        data[checksumOffset] = (crc and 0xFF).toByte()
        data[checksumOffset + 1] = ((crc ushr 8) and 0xFF).toByte()
    }

    private fun analyzeSave(file: File): SaveAnalysis {
        val data = try { file.readBytes() } catch (_: Exception) { ByteArray(0) }
        val size = data.size
        val family: String
        val expected: Int?
        val supported: Boolean

        val gen2ProfileForSize = if (size >= SIZE_G1 && size <= SIZE_G1 + 4096) detectGen2ChecksumProfile(data) else null

        when {
            size == SIZE_G1 -> {
                val g2 = gen2ProfileForSize
                family = g2?.displayName ?: "Pokémon Red / Blue / Yellow"
                expected = SIZE_G1
                supported = true
            }
            gen2ProfileForSize != null -> {
                family = gen2ProfileForSize.displayName
                // Preserve emulator RTC/trailer bytes; the validated SRAM payload is the first 32 KiB.
                expected = size
                supported = true
            }
            size == 0x20000 && gen3SaveValid(data) -> {
                family = detectGen3GameFromData(data, currentSourceLabel ?: file.name)
                expected = 0x20000
                supported = true
            }
            size == SIZE_G4 -> {
                val g5 = detectGen5Profile(data)
                family = if (g5 != null) gen5GameNameFromPath(currentSourceLabel ?: file.name, g5) else detectGen4GameFromPath(currentSourceLabel ?: file.name)
                expected = SIZE_G4
                supported = g5 != null || detectGen4Profile(data) != null
            }
            size == SIZE_G6_XY -> {
                family = "Pokémon X / Pokémon Y"
                expected = SIZE_G6_XY
                supported = true
            }
            size == SIZE_G6_ORAS -> {
                family = "Pokémon Omega Ruby / Alpha Sapphire"
                expected = SIZE_G6_ORAS
                supported = true
            }
            size == SIZE_G7_SM -> {
                family = "Pokémon Sun / Pokémon Moon"
                expected = SIZE_G7_SM
                supported = true
            }
            size == SIZE_G7_USUM -> {
                family = "Pokémon Ultra Sun / Pokémon Ultra Moon"
                expected = SIZE_G7_USUM
                supported = true
            }
            else -> {
                family = "Unknown / unsupported save size"
                expected = null
                supported = false
            }
        }

        val gen2Profile = gen2ProfileForSize
        val gen2Integrity = if (gen2Profile != null) verifyGen2SaveIntegrity(data) else null
        val gen1Integrity = if (size == SIZE_G1 && gen2Profile == null) verifyGen1SaveIntegrity(data) else null
        val footerValid = if (gen2Profile != null) gen2Integrity?.first==true else if (size == SIZE_G1) verifyGen1SaveIntegrity(data).first else if (size == 0x20000) gen3SaveValid(data) else if (size == SIZE_G4) (detectGen4Profile(data) != null || detectGen5Profile(data) != null) else hasBeefFooter(data)
        val trainer = if (supported && footerValid) {
            if (gen2Profile != null) parseTrainerGen2(data, gen2Profile) else if (size == 0x20000) parseGen3Trainer(data, family) else parseTrainer(data, size)
        } else null
        val hash = sha256(data)
        val note = when {
            gen2Profile != null -> if(gen2Integrity?.first==true) "Valid ${gen2Profile.displayName} Generation 2 battery save. ${gen2Integrity.second}${if (size > SIZE_G1) " Emulator RTC/trailer bytes are preserved." else ""}" else "Generation 2 save validation failed: ${gen2Integrity?.second?:"Unknown structural error."}"
            size == SIZE_G1 -> when {
                footerValid && trainer != null -> "Valid Generation 1 battery save. ${gen1Integrity?.second ?: "Save integrity verified."} Trainer data was read successfully."
                gen1Integrity?.first == false -> "Generation 1 save validation failed: ${requireNotNull(gen1Integrity).second}"
                else -> "The Generation 1 save passed integrity validation, but trainer data could not be read."
            }
            size == 0x20000 -> "Valid Generation 3 Game Boy Advance battery save. Ruby, Sapphire, Emerald, FireRed and LeafGreen use the shared Gen 3 engine; available operations are shown after the save is loaded."
            size == SIZE_G4 && detectGen5Profile(data) != null -> "Generation 5 Nintendo DS save detected. PK5 Party + all 24 PC Boxes are enabled in this first Gen 5 implementation."
            size == SIZE_G4 -> "Generation 4 Nintendo DS save detected. Stage 3 enables read-only PK4 Party + all 18 PC Box viewing with active save-block selection, block CRC verification and PK4 integrity checks; write operations remain safety-locked."
            size == SIZE_G7_SM || size == SIZE_G7_USUM -> if (trainer?.gameMatchesFamily == true) "Structurally valid ${trainer.exactGame} save. Gen 7 boxed and party Pokémon management is available." else "Gen 7 save detected, but the stored game ID needs attention."
            !supported -> "This file does not match a currently recognised decrypted Pokémon 3DS save size."
            !footerValid -> "The size matches a supported 3DS Pokémon save, but the standard BEEF footer signature was not found. The file may be encrypted, truncated, or not a normal decrypted 'main' save."
            trainer == null -> "The file passed structural validation, but the trainer block could not be parsed."
            !trainer.gameMatchesFamily -> "The file passed structural validation, but its stored game ID does not match the save-size family."
            else -> "Structurally valid ${trainer.exactGame} save. Trainer data was read successfully."
        }

        return SaveAnalysis(family, supported, expected, size, footerValid, hash, note, trainer, gen2Integrity?.second?:gen1Integrity?.second)
    }

    private fun parseTrainer(data: ByteArray, size: Int): TrainerData? {
        return when (size) {
            SIZE_G1 -> parseTrainerGen1(data)
            SIZE_G4 -> if (detectGen5Profile(data) != null) parseTrainerGen5(data) else parseTrainerGen4(data)
            SIZE_G6_XY, SIZE_G6_ORAS -> parseTrainerGen6(data, size)
            SIZE_G7_SM, SIZE_G7_USUM -> parseTrainerGen7(data, size)
            else -> null
        }
    }


    private fun parseTrainerGen5(data: ByteArray): TrainerData? {
        val profile = detectGen5Profile(data) ?: return null
        val o = 0x19400
        if (o + 0x40 > data.size) return null
        // Gen 5 switched trainer strings to UTF-16LE/Unicode. The offsets are shared by BW
        // and B2W2; only the trainer block length/checksum differs between the families.
        val name = readGen6String(data, o + 0x04, 16).ifBlank { "Trainer" }
        val tid = readU16LE(data, o + 0x14)
        val sid = readU16LE(data, o + 0x16)
        val genderRaw = data[o + 0x21].toInt() and 0xFF
        val languageRaw = data[o + 0x1E].toInt() and 0xFF
        val playedHours = readU16LE(data, o + 0x24).coerceIn(0, 999)
        val playedMinutes = (data[o + 0x26].toInt() and 0xFF).coerceIn(0, 59)
        val playedSeconds = (data[o + 0x27].toInt() and 0xFF).coerceIn(0, 59)
        val exact = gen5GameNameFromPath(currentSourceLabel ?: "", profile)
        return TrainerData(name, tid, sid, 0, exact, true,
            when(genderRaw){0->"Male";1->"Female";else->"Unknown ($genderRaw)"},
            pokemonLanguageName(languageRaw), 0L, 0, playedHours, playedMinutes, playedSeconds)
    }

    private fun parseTrainerGen4(data: ByteArray): TrainerData? {
        val profile = detectGen4Profile(data) ?: return null
        val active = gen4ActiveBlock(data, 0, profile.generalSize)
        val generalStart = active * 0x40000
        if (!gen4BlockChecksumValid(data, generalStart, profile.generalSize, profile)) return null
        val trainerRel = if (profile.family == "Platinum") 0x68 else 0x64
        val o = generalStart + trainerRel
        if (o + 0x26 > data.size) return null

        val trainerName = readGen4String(data, o, 16).ifBlank { "Trainer" }
        val tid = readU16LE(data, o + 0x10)
        val sid = readU16LE(data, o + 0x12)
        val money = readU32LE(data, o + 0x14)
        val genderRaw = data[o + 0x18].toInt() and 0xFF
        val languageRaw = data[o + 0x19].toInt() and 0xFF
        var badges = Integer.bitCount(data[o + 0x1A].toInt() and 0xFF)
        if (profile.family == "HeartGold / SoulSilver")
            badges += Integer.bitCount(data[o + 0x1F].toInt() and 0xFF)
        val hours = readU16LE(data, o + 0x22)
        val minutes = data[o + 0x24].toInt() and 0xFF
        val seconds = data[o + 0x25].toInt() and 0xFF
        val pathTitle = detectGen4GameFromPath(currentSourceLabel ?: "")
        val exactGame = if (pathTitle != "Pokémon Gen 4") pathTitle else "Pokémon ${profile.family}"
        val gameId = data[o + 0x1C].toInt() and 0xFF
        val gender = when (genderRaw) { 0 -> "Male"; 1 -> "Female"; else -> "Unknown ($genderRaw)" }

        return TrainerData(
            trainerName = trainerName,
            tid = tid,
            sid = sid,
            gameId = gameId,
            exactGame = exactGame,
            gameMatchesFamily = true,
            gender = gender,
            language = pokemonLanguageName(languageRaw),
            money = money,
            badges = badges,
            playedHours = hours,
            playedMinutes = minutes,
            playedSeconds = seconds
        )
    }

    private fun hasValidGen1MainChecksum(data: ByteArray): Boolean {
        if (data.size != SIZE_G1 || GEN1_CHECKSUM_OFFSET >= data.size) return false
        var sum = 0
        for (i in GEN1_MAIN_START until GEN1_CHECKSUM_OFFSET) sum = (sum + (data[i].toInt() and 0xFF)) and 0xFF
        val expected = sum.inv() and 0xFF
        return (data[GEN1_CHECKSUM_OFFSET].toInt() and 0xFF) == expected
    }

    private fun readGen1Text(data: ByteArray, offset: Int, length: Int): String {
        val out = StringBuilder()
        val end = minOf(offset + length, data.size)
        for (i in offset until end) {
            val b = data[i].toInt() and 0xFF
            if (b == 0x50) break
            val c = when (b) {
                in 0x80..0x99 -> ('A'.code + (b - 0x80)).toChar()
                in 0xA0..0xB9 -> ('a'.code + (b - 0xA0)).toChar()
                in 0xF6..0xFF -> ('0'.code + (b - 0xF6)).toChar()
                0x7F -> ' '
                0xE0 -> '\''
                0xE3 -> '-'
                0xE6 -> '?'
                0xE7 -> '!'
                0xF2 -> '.'
                else -> '�'
            }
            out.append(c)
        }
        return out.toString().trim().replace("�", "")
    }

    private fun readBcdMoney3(data: ByteArray, offset: Int): Long {
        if (offset + 2 >= data.size) return 0
        var value = 0L
        repeat(3) { idx ->
            val b = data[offset + idx].toInt() and 0xFF
            val hi = (b ushr 4) and 0xF
            val lo = b and 0xF
            if (hi > 9 || lo > 9) return 0
            value = value * 100 + hi * 10 + lo
        }
        return value
    }

    private fun parseTrainerGen1(data: ByteArray): TrainerData? {
        if (data.size != SIZE_G1 || !hasValidGen1MainChecksum(data)) return null
        val name = readGen1Text(data, GEN1_PLAYER_NAME, 11)
        val tid = ((data[GEN1_TID].toInt() and 0xFF) shl 8) or (data[GEN1_TID + 1].toInt() and 0xFF)
        val badges = Integer.bitCount(data[GEN1_BADGES].toInt() and 0xFF)
        val money = readBcdMoney3(data, GEN1_MONEY)
        val hours = data[GEN1_PLAYTIME].toInt() and 0xFF
        val minutes = data[GEN1_PLAYTIME + 2].toInt() and 0xFF
        val seconds = data[GEN1_PLAYTIME + 3].toInt() and 0xFF
        return TrainerData(
            trainerName = name,
            tid = tid,
            sid = 0,
            gameId = 1,
            exactGame = "Pokémon Red / Blue / Yellow",
            gameMatchesFamily = true,
            gender = "Male",
            language = "English / Western",
            money = money,
            badges = badges,
            playedHours = hours,
            playedMinutes = minutes,
            playedSeconds = seconds
        )
    }

    private fun parseTrainerGen6(data: ByteArray, size: Int): TrainerData? {
        if (data.size < STATUS_OFFSET + STATUS_MIN_LENGTH) return null
        val tid = readU16LE(data, STATUS_OFFSET)
        val sid = readU16LE(data, STATUS_OFFSET + 2)
        val gameId = data[STATUS_OFFSET + 4].toInt() and 0xFF
        val genderRaw = data[STATUS_OFFSET + 5].toInt() and 0xFF
        val languageRaw = data[STATUS_OFFSET + 0x2D].toInt() and 0xFF
        val trainerName = readGen6String(data, STATUS_OFFSET + 0x48, 0x1A)

        val exactGame = when (gameId) {
            24 -> "Pokémon X"
            25 -> "Pokémon Y"
            26 -> "Pokémon Alpha Sapphire"
            27 -> "Pokémon Omega Ruby"
            else -> "Unknown Gen 6 title (ID $gameId)"
        }
        val gameMatchesFamily = when (size) {
            SIZE_G6_XY -> gameId == 24 || gameId == 25
            SIZE_G6_ORAS -> gameId == 26 || gameId == 27
            else -> false
        }
        val gender = when (genderRaw) {
            0 -> "Male"
            1 -> "Female"
            else -> "Unknown ($genderRaw)"
        }
        val language = when (languageRaw) {
            1 -> "Japanese"
            2 -> "English"
            3 -> "French"
            4 -> "Italian"
            5 -> "German"
            7 -> "Spanish"
            8 -> "Korean"
            9 -> "Chinese (Simplified)"
            10 -> "Chinese (Traditional)"
            11 -> "Spanish (Latin America)"
            else -> "Unknown ($languageRaw)"
        }

        val money = readU32LE(data, MISC_OFFSET + 0x08)
        val badgeMask = data[MISC_OFFSET + 0x0C].toInt() and 0xFF
        val badges = Integer.bitCount(badgeMask)
        val playedHours = readU16LE(data, PLAYTIME_OFFSET)
        val playedMinutes = data[PLAYTIME_OFFSET + 2].toInt() and 0xFF
        val playedSeconds = data[PLAYTIME_OFFSET + 3].toInt() and 0xFF

        return TrainerData(
            trainerName = trainerName,
            tid = tid,
            sid = sid,
            gameId = gameId,
            exactGame = exactGame,
            gameMatchesFamily = gameMatchesFamily,
            gender = gender,
            language = language,
            money = money,
            badges = badges,
            playedHours = playedHours,
            playedMinutes = playedMinutes,
            playedSeconds = playedSeconds
        )
    }

    private fun parseTrainerGen7(data: ByteArray, size: Int): TrainerData? {
        val status = if (size == SIZE_G7_SM) STATUS_OFFSET_SM else STATUS_OFFSET_USUM
        val misc = if (size == SIZE_G7_SM) MISC_OFFSET_SM else MISC_OFFSET_USUM
        val play = if (size == SIZE_G7_SM) PLAYTIME_OFFSET_SM else PLAYTIME_OFFSET_USUM
        if (data.size < status + 0xC0 || data.size < play + 4) return null

        val tid = readU16LE(data, status)
        val sid = readU16LE(data, status + 2)
        val gameId = data[status + 4].toInt() and 0xFF
        val genderRaw = data[status + 5].toInt() and 0xFF
        val languageRaw = data[status + 0x35].toInt() and 0xFF
        val trainerName = readGen6String(data, status + 0x38, 0x1A)
        val exactGame = when (gameId) {
            30 -> "Pokémon Sun"
            31 -> "Pokémon Moon"
            32 -> "Pokémon Ultra Sun"
            33 -> "Pokémon Ultra Moon"
            else -> "Unknown Gen 7 title (ID $gameId)"
        }
        val gameMatchesFamily = when (size) {
            SIZE_G7_SM -> gameId == 30 || gameId == 31
            SIZE_G7_USUM -> gameId == 32 || gameId == 33
            else -> false
        }
        val gender = when (genderRaw) { 0 -> "Male"; 1 -> "Female"; else -> "Unknown ($genderRaw)" }
        val language = pokemonLanguageName(languageRaw)
        val money = readU32LE(data, misc + 0x04)
        val badgeBits = readU32LE(data, misc + 0x08).toInt()
        val badges = Integer.bitCount((badgeBits shl 13) ushr 17)
        val playedHours = readU16LE(data, play)
        val playedMinutes = data[play + 2].toInt() and 0xFF
        val playedSeconds = data[play + 3].toInt() and 0xFF
        return TrainerData(trainerName, tid, sid, gameId, exactGame, gameMatchesFamily, gender, language,
            money, badges, playedHours, playedMinutes, playedSeconds)
    }

    private fun generationForSize(size: Int): Int = when {
        size >= SIZE_G1 && size <= SIZE_G1 + 4096 -> importedFile?.let { f -> runCatching { detectGen2ChecksumProfile(f.readBytes()) }.getOrNull() }?.let { if (it != null) 2 else if (size == SIZE_G1) 1 else 0 } ?: if (size == SIZE_G1) 1 else 0
        size == 0x20000 && importedFile?.let { runCatching { gen3SaveValid(it.readBytes()) }.getOrDefault(false) } == true -> 3
        size == SIZE_G4 -> importedFile?.let { f -> runCatching { f.readBytes() }.getOrNull() }?.let { bytes -> if (detectGen5Profile(bytes) != null) 5 else 4 } ?: 4
        size == SIZE_G7_SM || size == SIZE_G7_USUM -> 7
        size == SIZE_G6_XY || size == SIZE_G6_ORAS -> 6
        else -> 0
    }

    private fun isCurrentGen7(): Boolean = importedFile?.let { generationForSize(it.length().toInt()) == 7 } == true

    private fun readGen6String(data: ByteArray, offset: Int, byteLength: Int): String {
        val sb = StringBuilder()
        var p = offset
        val end = minOf(offset + byteLength, data.size)
        while (p + 1 < end) {
            val value = readU16LE(data, p)
            if (value == 0 || value == 0xFFFF) break
            if (value in 0xD800..0xDFFF) {
                sb.append('�')
            } else {
                sb.append(value.toChar())
            }
            p += 2
        }
        return sb.toString().trimEnd('\u0000')
    }

    private fun readU16LE(data: ByteArray, offset: Int): Int {
        if (offset < 0 || offset + 1 >= data.size) return 0
        return (data[offset].toInt() and 0xFF) or ((data[offset + 1].toInt() and 0xFF) shl 8)
    }

    private fun readU32LE(data: ByteArray, offset: Int): Long {
        if (offset < 0 || offset + 3 >= data.size) return 0
        return (data[offset].toLong() and 0xFF) or
                ((data[offset + 1].toLong() and 0xFF) shl 8) or
                ((data[offset + 2].toLong() and 0xFF) shl 16) or
                ((data[offset + 3].toLong() and 0xFF) shl 24)
    }

    private fun writeU16LE(data: ByteArray, offset: Int, value: Int) {
        if (offset < 0 || offset + 1 >= data.size) return
        data[offset] = (value and 0xFF).toByte()
        data[offset + 1] = ((value ushr 8) and 0xFF).toByte()
    }

    private fun writeU32LE(data: ByteArray, offset: Int, value: Long) {
        if (offset < 0 || offset + 3 >= data.size) return
        data[offset] = (value and 0xFF).toByte()
        data[offset + 1] = ((value ushr 8) and 0xFF).toByte()
        data[offset + 2] = ((value ushr 16) and 0xFF).toByte()
        data[offset + 3] = ((value ushr 24) and 0xFF).toByte()
    }

    private fun writeGen6String(data: ByteArray, offset: Int, byteLength: Int, value: String) {
        if (offset < 0 || offset + byteLength > data.size) return
        java.util.Arrays.fill(data, offset, offset + byteLength, 0.toByte())
        val maxChars = (byteLength / 2 - 1).coerceAtLeast(0)
        value.take(maxChars).forEachIndexed { i, ch -> writeU16LE(data, offset + i * 2, ch.code) }
    }

    private fun writeGen5String(data: ByteArray, offset: Int, byteLength: Int, value: String, maxChars: Int) {
        if (offset < 0 || offset + byteLength > data.size || byteLength < 2) return
        // Generation 5 strings use 0xFFFF as their terminator. Do not zero-fill the
        // remainder: PK5 keeps "trash bytes" after the terminator, and writing 0x0000
        // there can be rendered by the DS games as unknown glyphs (????). This matches
        // the PK5 convention used by established editors: write the new text, place the
        // 0xFFFF terminator immediately after it, and preserve the remaining trash bytes.
        val limit = minOf(maxChars, byteLength / 2 - 1).coerceAtLeast(0)
        val text = value.take(limit)
        text.forEachIndexed { i, ch -> writeU16LE(data, offset + i * 2, ch.code) }
        writeU16LE(data, offset + text.length * 2, 0xFFFF)
    }

    private fun hasBeefFooter(data: ByteArray): Boolean {
        if (data.size < 0x1F0) return false
        val p = data.size - 0x1F0
        val value = (data[p].toInt() and 0xFF) or
                ((data[p + 1].toInt() and 0xFF) shl 8) or
                ((data[p + 2].toInt() and 0xFF) shl 16) or
                ((data[p + 3].toInt() and 0xFF) shl 24)
        return value == 0x42454546
    }

    private fun sha256(data: ByteArray): String {
        return try {
            MessageDigest.getInstance("SHA-256").digest(data)
                .joinToString("") { "%02x".format(it) }
        } catch (_: Exception) {
            "Unavailable"
        }
    }

    private fun addCardLine(text: String, bold: Boolean = false, color: Int? = null) {
        val tv = TextView(this).apply {
            this.text = text
            textSize = if (bold) 13f else 15f
            setTextColor(color ?: if (bold) Color.rgb(130, 200, 255) else TEXT)
            if (bold) typeface = Typeface.DEFAULT_BOLD
            setPadding(0, 2, 0, 7)
        }
        saveCard.addView(tv)
    }

    private fun showBackups() {
        val backups = backupsDir().listFiles()?.filter { it.isFile }?.sortedByDescending { it.lastModified() } ?: emptyList()
        if (backups.isEmpty()) {
            showDialog("Backups", "No backups yet. A backup is created only when you use Save & Replace Current Save.")
            return
        }
        val labels = backups.map { file ->
            val badge = when {
                backupIsProtected(file) -> "⭐ ORIGINAL • PROTECTED"
                isBackupKept(file) -> "📌 KEPT"
                else -> "↻ ROLLING"
            }
            "$badge\n${file.name}\n${formatBytes(file.length())}"
        }.toTypedArray()
        AlertDialog.Builder(this)
            .setTitle("Backups (${backups.size})")
            .setItems(labels) { _, which -> showBackupActions(backups[which]) }
            .setNeutralButton("📁 Safe Files") { _, _ -> showSafeBackups() }
            .setNegativeButton("Close", null)
            .show()
    }

    private fun showBackupActions(file: File) {
        val opened=runCatching{file.readBytes()}.getOrNull()
        val knownGame=getSharedPreferences("pse_current_source",MODE_PRIVATE).getString("source_game",null)
        val gen2Pins=opened?.let{detectGen2ChecksumProfile(it)!=null}==true||
            knownGame in setOf("Pokémon Gold","Pokémon Silver","Pokémon Crystal","Pokémon Gold / Silver")||
            importedFile?.let{runCatching{detectGen2ChecksumProfile(it.readBytes())!=null}.getOrDefault(false)}==true
        if(gen2Pins&&opened==null){showDialog("Backup actions blocked","PSE could not snapshot the selected Gen 2 backup. No pin or file was changed.");return}
        val openedPath=importedFile?.absolutePath;val openedSource=currentSourceUri;val openedLabel=currentSourceLabel;val openedFolder=safeFolderUri()
        val protected = backupIsProtected(file)
        val kept = isBackupKept(file)
        val actions = mutableListOf<String>()
        actions.add("Restore to current PSE save")
        if (!protected) actions.add(if (kept) "Remove Keep pin" else "Keep this backup")
        if (!protected) actions.add("Delete backup")
        actions.add("Open PSE Safe Backups")
        AlertDialog.Builder(this)
            .setTitle(file.name)
            .setMessage(
                "${if (protected) "⭐ Protected ORIGINAL\n" else if (kept) "📌 Kept backup\n" else "↻ Rolling backup\n"}" +
                "Size: ${formatBytes(file.length())}"+if(gen2Pins)"\n\nKeep actions change only the pin. They do not mirror files or run cleanup; use Delete backup for explicit deletion." else ""
            )
            .setItems(actions.toTypedArray()) { _, which ->
                if(gen2Pins&&actions[which] in setOf("Keep this backup","Remove Keep pin")){
                    setGen2BackupPin(file,requireNotNull(opened),!kept,kept,openedPath,openedSource,openedLabel,openedFolder)
                    return@setItems
                }
                when (actions[which]) {
                    "Restore to current PSE save" -> restoreBackupToWorkingSave(file)
                    "Keep this backup" -> {
                        setBackupKept(file, true)
                        mirrorBackupToSafeFolder(file)
                        Toast.makeText(this, "Backup marked Keep", Toast.LENGTH_SHORT).show()
                        showBackups()
                    }
                    "Remove Keep pin" -> {
                        setBackupKept(file, false)
                        pruneRollingBackups(gameNameFromBackupName(file.name) ?: backupGameName(), 10)
                        Toast.makeText(this, "Keep pin removed", Toast.LENGTH_SHORT).show()
                        showBackups()
                    }
                    "Delete backup" -> confirmDeleteBackup(file)
                    "Open PSE Safe Backups" -> showSafeBackups()
                }
            }
            .setNegativeButton("Back", null)
            .show()
    }

    private fun setGen2BackupPin(file:File,opened:ByteArray,keep:Boolean,expectedKept:Boolean,openedPath:String?,openedSource:Uri?,openedLabel:String?,openedFolder:Uri?) {
        fun bound()=importedFile?.absolutePath==openedPath&&currentSourceUri==openedSource&&currentSourceLabel==openedLabel&&safeFolderUri()==openedFolder
        fun unchanged()=file.isFile&&!backupIsProtected(file)&&file.canonicalFile.parentFile==backupsDir().canonicalFile&&file.canonicalPath!=importedFile?.canonicalPath&&Uri.fromFile(file)!=currentSourceUri&&file.readBytes().contentEquals(opened)
        var commitStarted=false
        try{
            require(bound()&&unchanged()&&keptBackupNames().contains(file.name)==expectedKept){"The selected backup, Keep status or active save changed. Reopen Backups."}
            val names=keptBackupNames().apply{if(keep)add(file.name)else remove(file.name)}
            require(bound()&&unchanged()&&keptBackupNames().contains(file.name)==expectedKept){"The confirmed backup or pin changed before saving metadata."}
            val prefs=getSharedPreferences("pse_backup_state",MODE_PRIVATE)
            commitStarted=true
            require(prefs.edit().putStringSet("kept",names).commit()){"The Keep-pin change could not be saved."}
            require(prefs.getStringSet("kept",emptySet())==names&&bound()&&unchanged()){"The pin or confirmed backup could not be rechecked after saving metadata."}
        }catch(e:Exception){
            // A failed/unverified unpin must conservatively restore retention, not delete a file.
            val retained=commitStarted&&!keep&&runCatching{
                val names=keptBackupNames().apply{add(file.name)}
                val prefs=getSharedPreferences("pse_backup_state",MODE_PRIVATE)
                require(prefs.edit().putStringSet("kept",names).commit())
                require(prefs.getStringSet("kept",emptySet())?.contains(file.name)==true)
            }.isSuccess
            val outcome=if(!commitStarted)"No Keep-pin change was made." else  if(retained)"The selected backup's Keep pin was restored and verified." else "The Keep-pin result could not be verified. Refresh Backups before cleanup or deletion."
            showDialog("Keep-pin change not completed",(e.message?:"Could not verify backup retention")+"\n\n"+outcome+"\n\nNo save or backup file was written, mirrored or deleted.");return
        }
        Toast.makeText(this,if(keep)"Keep pin saved and verified; files unchanged" else "Keep pin removed and verified; no files deleted",Toast.LENGTH_LONG).show()
        showBackups()
    }

    private fun gameNameFromBackupName(name: String): String? {
        val parts = name.split("_")
        return when {
            (name.startsWith("AUTO_") || name.startsWith("EDIT_") || name.startsWith("ORIGINAL_")) && parts.size > 1 -> parts[1]
            else -> null
        }
    }

    private fun restoreBackupToWorkingSave(file: File) {
        val current = importedFile
        if (current == null) {
            showDialog("Restore backup", "No current PSE save is loaded. Import a save first so PSE knows what working copy to restore.")
            return
        }
        val check = analyzeSave(file)
        if (!check.structurallyValid) {
            showDialog("Restore blocked", "This backup did not pass structural validation, so PSE did not restore it.")
            return
        }
        val currentCheck=analyzeSave(current)
        if(!currentCheck.structurallyValid){showDialog("Restore blocked","The current working save did not pass structural validation. Nothing was changed.");return}
        val gen2Identity=verifyGen2BackupRestoreIdentity(file,current,file.name)
        if(!gen2Identity.first){showDialog("Restore blocked",gen2Identity.second);return}
        val openedBackup=runCatching{file.readBytes()}.getOrElse{showDialog("Restore blocked","The selected backup could not be read. Nothing was changed.");return}
        val openedCurrent=runCatching{current.readBytes()}.getOrElse{showDialog("Restore blocked","The current working save could not be read. Nothing was changed.");return}
        val gen2Restore=detectGen2Profile(openedCurrent)!=null
        val openedSourceUri=currentSourceUri;val openedSourceLabel=currentSourceLabel
        AlertDialog.Builder(this)
            .setTitle("Restore this backup?")
            .setMessage("This restores the selected backup into PSE's current working copy. It does not overwrite the emulator until you use Save & Replace Current Save.")
            .setNegativeButton("Cancel", null)
            .setPositiveButton("Restore") { _, _ ->
                if(gen2Restore&&(importedFile?.absolutePath!=current.absolutePath||currentSourceUri!=openedSourceUri||currentSourceLabel!=openedSourceLabel)){showDialog("Restore blocked","The active Gen 2 save or source identity changed. Reopen Backups. Nothing was written.");return@setPositiveButton}
                var writeStarted=false
                val original=runCatching{current.readBytes()}.getOrNull()
                val selected=runCatching{file.readBytes()}.getOrNull()
                if(original==null||selected==null){showDialog("Restore failed","The backup or current working save could not be read. Nothing was changed.");return@setPositiveButton}
                try {
                    require(original.contentEquals(openedCurrent)){"The current working save changed while the restore confirmation was open. Reopen Backups and try again."}
                    require(selected.contentEquals(openedBackup)){"The selected backup changed while the restore confirmation was open. Reopen Backups and try again."}
                    require(analyzeSave(file).structurallyValid){"The selected backup no longer passes structural validation."}
                    val freshIdentity=verifyGen2BackupRestoreIdentity(file,current,file.name);require(freshIdentity.first){freshIdentity.second}
                    if(gen2Restore)require(importedFile?.absolutePath==current.absolutePath&&currentSourceUri==openedSourceUri&&currentSourceLabel==openedSourceLabel&&current.readBytes().contentEquals(original)&&file.readBytes().contentEquals(selected)){"The Gen 2 working save, source identity or backup changed during restore validation. Nothing was written."}
                    writeStarted=true
                    current.writeBytes(selected);val persisted=current.readBytes()
                    require(persisted.contentEquals(selected)){"The restored working save did not persist byte-for-byte."}
                    require(analyzeSave(current).structurallyValid){"The restored working save failed structural validation."}
                    val persistedIdentity=verifyGen2BackupRestoreIdentity(file,current,file.name);require(persistedIdentity.first){"The persisted restore failed its Gen 2 identity check. ${persistedIdentity.second}"}
                    if(gen2Restore)require(importedFile?.absolutePath==current.absolutePath&&currentSourceUri==openedSourceUri&&currentSourceLabel==openedSourceLabel){"The active Gen 2 save or source identity changed while restoration was written."}
                    if(!gen2Restore){refreshSaveCard();Toast.makeText(this, "Backup restored to current PSE save", Toast.LENGTH_LONG).show()}
                } catch (e: Exception) {
                    val rollbackVerified=(!gen2Restore||writeStarted)&&runCatching{current.writeBytes(original);current.readBytes().contentEquals(original)}.getOrDefault(false)
                    showDialog("Restore failed",(e.message ?: "Could not restore backup")+if(gen2Restore&&!writeStarted)"\n\nNothing was written to the working save or backup." else if(rollbackVerified)"\n\nThe exact previous working save was restored and verified." else "\n\nPSE could not verify rollback. Do not use this working copy; re-import the untouched source save.")
                    return@setPositiveButton
                }
                if(gen2Restore){refreshSaveCard();Toast.makeText(this, "Backup restored to current PSE save", Toast.LENGTH_LONG).show()}
            }
            .show()
    }

    private fun confirmDeleteBackup(file: File) {
        if (backupIsProtected(file)) {
            showDialog("Protected ORIGINAL", "PSE will not delete the protected ORIGINAL backup automatically or from this screen.")
            return
        }
        val opened=runCatching{file.readBytes()}.getOrNull()
        val knownGame=getSharedPreferences("pse_current_source",MODE_PRIVATE).getString("source_game",null)
        val gen2Delete=opened?.let{detectGen2ChecksumProfile(it)!=null}==true||
            knownGame in setOf("Pokémon Gold","Pokémon Silver","Pokémon Crystal","Pokémon Gold / Silver")||
            importedFile?.let{runCatching{detectGen2ChecksumProfile(it.readBytes())!=null}.getOrDefault(false)}==true
        if(gen2Delete){
            if(opened==null){showDialog("Delete blocked","PSE could not snapshot the selected Gen 2 backup. Nothing was deleted.");return}
            confirmGen2InternalBackupDelete(file,opened)
            return
        }
        AlertDialog.Builder(this)
            .setTitle("Delete backup?")
            .setMessage("Delete ${file.name} from PSE and its configured Safe Files folder?")
            .setNegativeButton("Cancel", null)
            .setPositiveButton("Delete") { _, _ ->
                deleteBackupEverywhere(file)
                Toast.makeText(this, "Backup deleted", Toast.LENGTH_SHORT).show()
                showBackups()
            }
            .show()
    }

    private fun confirmGen2InternalBackupDelete(file:File,opened:ByteArray) {
        val openedPath=importedFile?.absolutePath;val openedSource=currentSourceUri;val openedLabel=currentSourceLabel
        val openedFolder=safeFolderUri();val openedKept=keptBackupNames().contains(file.name)
        fun bound()=importedFile?.absolutePath==openedPath&&currentSourceUri==openedSource&&currentSourceLabel==openedLabel&&safeFolderUri()==openedFolder&&keptBackupNames().contains(file.name)==openedKept
        fun selected()=file.isFile&&!backupIsProtected(file)&&file.canonicalFile.parentFile==backupsDir().canonicalFile&&file.canonicalPath!=importedFile?.canonicalPath&&Uri.fromFile(file)!=currentSourceUri
        var mirror:DocumentFile?=null
        var root:DocumentFile?=null
        try{
            require(selected()&&file.readBytes().contentEquals(opened)){"The selected backup changed, became protected or aliases the active save."}
            if(openedFolder!=null){
                root=requireNotNull(DocumentFile.fromTreeUri(this,openedFolder)){"Could not inspect the configured Safe Files folder."}
                require(root!!.exists()&&root!!.isDirectory){"The configured Safe Files folder is unavailable."}
                mirror=root!!.findFile(file.name)
                mirror?.let{doc->
                    require(doc.exists()&&doc.isFile&&doc.name==file.name&&doc.uri!=openedSource){"The same-name Safe Files entry is not a separate backup."}
                    val bytes=contentResolver.openInputStream(doc.uri).use{requireNotNull(it).readBytes()}
                    require(bytes.contentEquals(opened)){"The same-name Safe Files copy has different bytes. Neither copy was deleted; manage that copy separately in Safe Files."}
                }
            }
            require(bound()&&selected()&&file.readBytes().contentEquals(opened)){"The backup or active context changed while preparing confirmation."}
        }catch(e:Exception){showDialog("Delete blocked",(e.message?:"Could not inspect this Gen 2 backup")+"\n\nNothing was deleted.");return}
        val context=Gen2BackupDeleteContext(
            file=file,
            opened=opened,
            openedPath=openedPath,
            openedSource=openedSource,
            openedLabel=openedLabel,
            openedFolder=openedFolder,
            openedKept=openedKept,
            openedMirror=mirror,
            openedMirrorUri=mirror?.uri,
            openedRoot=root
        )
        AlertDialog.Builder(this).setTitle("Delete this Gen 2 backup?")
            .setMessage("Delete "+file.name+" from PSE"+if(mirror!=null)" and its verified identical Safe Files copy? Other backups, the emulator and working save will not be changed." else " only? No matching Safe Files copy was found. Other backups, the emulator and working save will not be changed.")
            .setNegativeButton("Cancel",null)
            .setPositiveButton("Delete"){_,_->deleteGen2InternalBackupConfirmed(context)}
            .show()
    }

    private class Gen2BackupDeleteContext(
        val file:File,
        val opened:ByteArray,
        val openedPath:String?,
        val openedSource:Uri?,
        val openedLabel:String?,
        val openedFolder:Uri?,
        val openedKept:Boolean,
        val openedMirror:DocumentFile?,
        val openedMirrorUri:Uri?,
        val openedRoot:DocumentFile?
    )

    private fun deleteGen2InternalBackupConfirmed(context:Gen2BackupDeleteContext) {
        val file=context.file
        val opened=context.opened
        val openedMirror=context.openedMirror
        val openedMirrorUri=context.openedMirrorUri
        val openedRoot=context.openedRoot
        fun bound()=importedFile?.absolutePath==context.openedPath&&currentSourceUri==context.openedSource&&currentSourceLabel==context.openedLabel&&safeFolderUri()==context.openedFolder&&keptBackupNames().contains(file.name)==context.openedKept
        fun selected()=file.isFile&&!backupIsProtected(file)&&file.canonicalFile.parentFile==backupsDir().canonicalFile&&file.canonicalPath!=importedFile?.canonicalPath&&Uri.fromFile(file)!=currentSourceUri
        if(!bound()){showDialog("Delete blocked","The active save, source identity, folder or Keep pin changed. Reopen Backups. Nothing was deleted.");return}
        var mirrorAttempted=false;var mirrorRemoved=false;var internalAttempted=false
        try{
            fun checkSelected(){require(bound()&&selected()&&file.readBytes().contentEquals(opened)){"The confirmed internal backup or active context changed."}}
            checkSelected()
            if(openedRoot!=null){
                require(openedRoot.exists()&&openedRoot.isDirectory){"The confirmed Safe Files folder is unavailable."}
                val fresh=openedRoot.findFile(file.name)
                require(fresh?.uri==openedMirrorUri){"The matching Safe Files entry changed after confirmation."}
                openedMirror?.let{doc->
                    require(doc.uri==openedMirrorUri&&doc.exists()&&doc.isFile&&doc.name==file.name&&doc.uri!=currentSourceUri){"The confirmed Safe Files copy changed or aliases the emulator source."}
                    val bytes=contentResolver.openInputStream(doc.uri).use{requireNotNull(it).readBytes()}
                    require(bytes.contentEquals(opened)){"The matching Safe Files copy changed bytes after confirmation."}
                    checkSelected()
                    val finalBytes=contentResolver.openInputStream(doc.uri).use{requireNotNull(it).readBytes()}
                    require(finalBytes.contentEquals(opened)&&doc.exists()&&doc.isFile&&doc.name==file.name&&doc.uri!=currentSourceUri&&openedRoot.findFile(file.name)?.uri==openedMirrorUri){"The matching Safe Files copy changed during final checks."}
                    checkSelected()
                    mirrorAttempted=true
                    val deleted=doc.delete()
                    require(deleted&&!doc.exists()&&openedRoot.findFile(file.name)==null){"PSE could not verify removal of the matching Safe Files copy."}
                    mirrorRemoved=true
                }
            }
            checkSelected()
            internalAttempted=true
            val deleted=file.delete()
            require(deleted&&!file.exists()){"PSE could not verify removal of the internal backup."}
        }catch(e:Exception){
            val outcome=if(!mirrorAttempted&&!internalAttempted)"Nothing was deleted." else  if(mirrorRemoved&&!internalAttempted)"The identical Safe Files copy was removed and verified; PSE did not delete the internal backup." else "The deletion was not fully verified and may be partial. Refresh Backups and Safe Files before taking further action."
            showDialog("Delete not completed",(e.message?:"Could not verify backup deletion")+"\n\n"+outcome+"\n\nKeep-pin metadata was not changed. PSE did not write to the emulator, working save or other backups.")
            return
        }
        val pinCleaned=runCatching{
            val prefs=getSharedPreferences("pse_backup_state",MODE_PRIVATE)
            val names=keptBackupNames().apply{remove(file.name)}
            require(prefs.edit().putStringSet("kept",names).commit())
            require(prefs.getStringSet("kept",emptySet())==names)
        }.isSuccess
        if(!pinCleaned)showDialog("Deletion verified","The confirmed backup copy/copies were removed and verified. Keep-pin cleanup could not be verified; refresh Backups. No save data was written.")
        else Toast.makeText(this,"Selected Gen 2 backup deletion verified",Toast.LENGTH_SHORT).show()
        showBackups()
    }

    data class PokemonEntry(
        val species: Int,
        val nickname: String,
        val isNicknamed: Boolean,
        val level: Int?,
        val checksumValid: Boolean,
        val heldItem: Int,
        val tid: Int,
        val sid: Int,
        val experience: Long,
        val ability: Int,
        val abilityNumber: Int,
        val pid: Long,
        val nature: Int,
        val gender: Int,
        val form: Int,
        val evs: IntArray,
        val moves: IntArray,
        val movePP: IntArray,
        val ivs: IntArray,
        val isEgg: Boolean,
        val otName: String,
        val friendship: Int,
        val currentHandler: Int,
        val pokerusDays: Int,
        val pokerusStrain: Int,
        val shiny: Boolean,
        val language: Int,
        val markingValue: Int,
        val fatefulEncounter: Boolean,
        val relearnMoves: IntArray,
        val eggLocation: Int,
        val metLocation: Int,
        val ball: Int,
        val metLevel: Int,
        val otGender: Int,
        val originGame: Int,
        val country: Int,
        val region: Int,
        val consoleRegion: Int,
        val eggYear: Int, val eggMonth: Int, val eggDay: Int,
        val metYear: Int, val metMonth: Int, val metDay: Int,
        val hyperTrainFlags: Int
    )

    private data class Gen5Profile(
        val family:String, val sequel:Boolean, val checksumTable:Int, val pokedexOffset:Int,
        val checksumTableLength:Int, val checksumBlockChecksumOffset:Int
    )

    private fun gen5BlockCrcValid(data:ByteArray, offset:Int, length:Int, checksumOffset:Int):Boolean {
        if(offset < 0 || length <= 0 || checksumOffset + 1 >= data.size || offset + length > data.size) return false
        return gen4Crc16Ccitt(data, offset, offset + length) == readU16LE(data, checksumOffset)
    }

    private fun detectGen5Profile(data:ByteArray):Gen5Profile? {
        if(data.size != SIZE_G5) return null
        // Trainer-data block lengths differ between BW and B2W2. Validate more than one block to
        // avoid mistaking a Gen 4 512 KiB save for Gen 5.
        val box = gen5BlockCrcValid(data, 0x00400, 0x0FF0, 0x013F2)
        if(!box) return null
        val bwTrainer = gen5BlockCrcValid(data, 0x19400, 0x0068, 0x1946A)
        val b2Trainer = gen5BlockCrcValid(data, 0x19400, 0x00B0, 0x194B2)
        return when {
            b2Trainer -> Gen5Profile("Black 2 / White 2", true, 0x25F00, 0x21400, 0x0094, 0x25FA2)
            bwTrainer -> Gen5Profile("Black / White", false, 0x23F00, 0x21600, 0x008C, 0x23F9A)
            else -> null
        }
    }

    private fun gen5GameNameFromPath(path:String, p:Gen5Profile):String {
        // A raw Gen 5 .sav distinguishes BW from B2W2 structurally, but not the paired
        // cartridge version. Use the ROM/save source name for the final Black/White side.
        // Common dump names include "Black Version 2", not only "Black 2".
        val q=path.lowercase(Locale.US).replace('_', ' ').replace('-', ' ')
        val white2 = Regex("\\bwhite(?:\\s+version)?\\s*2\\b").containsMatchIn(q) || Regex("\\bw2\\b").containsMatchIn(q)
        val black2 = Regex("\\bblack(?:\\s+version)?\\s*2\\b").containsMatchIn(q) || Regex("\\bb2\\b").containsMatchIn(q)
        return when {
            p.sequel && white2 -> "Pokémon White 2"
            p.sequel && black2 -> "Pokémon Black 2"
            !p.sequel && Regex("\\bwhite(?:\\s+version)?\\b").containsMatchIn(q) -> "Pokémon White"
            !p.sequel && Regex("\\bblack(?:\\s+version)?\\b").containsMatchIn(q) -> "Pokémon Black"
            else -> "Pokémon ${p.family}"
        }
    }

    private fun decryptPk5(raw:ByteArray):ByteArray? {
        if(raw.size != 136 && raw.size != 220) return null
        val d=raw.copyOf()
        val pid=readU32LE(d,0)
        val chk=readU16LE(d,6).toLong()
        gen4Crypt(d,8,136,chk)
        if(d.size>136) gen4Crypt(d,136,d.size,pid)
        gen4Unshuffle(d)
        return d
    }

    private fun parsePk5(raw:ByteArray, party:Boolean):PokemonEntry? {
        val d=decryptPk5(raw) ?: return null
        val species=readU16LE(d,0x08)
        if(species !in 1..649) return null
        var sum=0
        for(o in 0x08 until 0x88 step 2) sum=(sum+readU16LE(d,o)) and 0xFFFF
        val checksumOk=sum==readU16LE(d,0x06)
        val pid=readU32LE(d,0)
        val tid=readU16LE(d,0x0C); val sid=readU16LE(d,0x0E)
        val iv32=readU32LE(d,0x38)
        val g=d[0x40].toInt() and 0xFF
        val poker=d[0x82].toInt() and 0xFF
        val shiny=(tid xor sid xor (pid.toInt() and 0xFFFF) xor ((pid.toInt() ushr 16) and 0xFFFF))<8
        val hidden=(d[0x42].toInt() and 1)!=0
        val abilityNumber=if(hidden)4 else if(((pid ushr 16) and 1L)==0L)1 else 2
        return PokemonEntry(
            species=species,nickname=readGen6String(d,0x48,22),isNicknamed=((iv32 ushr 31) and 1L)==1L,
            level=if(party && d.size>0x8C)(d[0x8C].toInt() and 0xFF).takeIf{it in 1..100}else null,
            checksumValid=checksumOk,heldItem=readU16LE(d,0x0A),tid=tid,sid=sid,experience=readU32LE(d,0x10),
            ability=d[0x15].toInt() and 0xFF,abilityNumber=abilityNumber,pid=pid,nature=d[0x41].toInt() and 0xFF,gender=(g ushr 1) and 3,form=(g ushr 3) and 0x1F,
            evs=IntArray(6){d[0x18+it].toInt() and 0xFF},moves=IntArray(4){readU16LE(d,0x28+it*2)},movePP=IntArray(4){d[0x30+it].toInt() and 0xFF},
            ivs=IntArray(6){i->((iv32 ushr (i*5)) and 31L).toInt()},isEgg=((iv32 ushr 30) and 1L)==1L,
            otName=readGen6String(d,0x68,16),friendship=d[0x14].toInt() and 0xFF,currentHandler=0,pokerusDays=poker and 0xF,pokerusStrain=(poker ushr 4) and 0xF,
            shiny=shiny,language=d[0x17].toInt() and 0xFF,markingValue=d[0x16].toInt() and 0xFF,fatefulEncounter=(g and 1)!=0,relearnMoves=IntArray(4),
            eggLocation=readU16LE(d,0x7E),metLocation=readU16LE(d,0x80),ball=d[0x83].toInt() and 0xFF,
            metLevel=d[0x84].toInt() and 0x7F,otGender=(d[0x84].toInt() ushr 7) and 1,originGame=d[0x5F].toInt() and 0xFF,
            country=0,region=0,consoleRegion=0,eggYear=d[0x78].toInt() and 0xFF,eggMonth=d[0x79].toInt() and 0xFF,eggDay=d[0x7A].toInt() and 0xFF,
            metYear=d[0x7B].toInt() and 0xFF,metMonth=d[0x7C].toInt() and 0xFF,metDay=d[0x7D].toInt() and 0xFF,hyperTrainFlags=0
        )
    }

    private fun gen5Party(data:ByteArray):List<PokemonEntry?> {
        val count=(data.getOrNull(0x18E04)?.toInt() ?: 0) and 0xFF
        return (0 until 6).map { slot ->
            if(slot>=count) null else { val o=0x18E08+slot*220; if(o+220>data.size)null else parsePk5(data.copyOfRange(o,o+220),true) }
        }
    }

    private fun gen5Box(data:ByteArray, box:Int):List<PokemonEntry?> {
        if(box !in 0 until 24) return List(30){null}
        val base=0x00400 + box*0x1000
        return (0 until 30).map { slot -> val o=base+slot*136; if(o+136>data.size)null else parsePk5(data.copyOfRange(o,o+136),false) }
    }

    private fun encryptPk5(decrypted:ByteArray):ByteArray {
        if(decrypted.size != 136 && decrypted.size != 220) throw IllegalArgumentException("Invalid PK5 size")
        val out=decrypted.copyOf(); var sum=0
        for(o in 0x08 until 0x88 step 2) sum=(sum+readU16LE(out,o)) and 0xFFFF
        writeU16LE(out,0x06,sum); val pid=readU32LE(out,0)
        gen4Shuffle(out); gen4Crypt(out,8,136,sum.toLong()); if(out.size>136) gen4Crypt(out,136,out.size,pid)
        return out
    }

    private fun gen5Pk5PpUps(raw:ByteArray):IntArray {
        val d=decryptPk5(raw)?:return IntArray(4){-1}
        return IntArray(4){d[0x34+it].toInt() and 3}
    }

    private fun gen5BoxChecksumValid(save:ByteArray, box:Int, profile:Gen5Profile):Boolean {
        if(box !in 0 until 24) return false
        val base=0x00400 + box*0x1000
        val crc=gen4Crc16Ccitt(save,base,base+0x0FF0)
        val local=readU16LE(save,base+0x0FF2)
        val mirror=readU16LE(save,profile.checksumTable + 2 + box*2)
        return crc==local && crc==mirror
    }

    private fun gen5ChecksumTableValid(save:ByteArray, profile:Gen5Profile):Boolean {
        val start=profile.checksumTable
        val end=start+profile.checksumTableLength
        if(start<0 || end>save.size || profile.checksumBlockChecksumOffset+1>=save.size) return false
        return gen4Crc16Ccitt(save,start,end)==readU16LE(save,profile.checksumBlockChecksumOffset)
    }

    private fun updateGen5BoxChecksum(save:ByteArray, box:Int, profile:Gen5Profile) {
        require(box in 0 until 24)
        val base=0x00400 + box*0x1000
        val crc=gen4Crc16Ccitt(save,base,base+0x0FF0)
        writeU16LE(save,base+0x0FF2,crc)
        val mirror=profile.checksumTable + 2 + box*2
        require(mirror+1 < save.size) { "Invalid Gen 5 checksum mirror" }
        writeU16LE(save,mirror,crc)
        val tableCrc=gen4Crc16Ccitt(save,profile.checksumTable,profile.checksumTable+profile.checksumTableLength)
        writeU16LE(save,profile.checksumBlockChecksumOffset,tableCrc)
    }

    private fun gen5PartyChecksumValid(save:ByteArray, profile:Gen5Profile):Boolean {
        val base=0x18E00
        val crc=gen4Crc16Ccitt(save,base,base+0x0534)
        val local=readU16LE(save,0x19336)
        val mirror=readU16LE(save,profile.checksumTable+0x34)
        return crc==local && crc==mirror
    }

    private fun updateGen5PartyChecksum(save:ByteArray, profile:Gen5Profile) {
        val base=0x18E00
        val crc=gen4Crc16Ccitt(save,base,base+0x0534)
        writeU16LE(save,0x19336,crc)
        writeU16LE(save,profile.checksumTable+0x34,crc)
        val tableCrc=gen4Crc16Ccitt(save,profile.checksumTable,profile.checksumTable+profile.checksumTableLength)
        writeU16LE(save,profile.checksumBlockChecksumOffset,tableCrc)
    }

    private data class Gen5EditValues(
        val nickname:String,val ot:String,val exp:Long,val held:Int,val friendship:Int,val nature:Int,
        val moves:IntArray,val pp:IntArray,val ivs:IntArray,val evs:IntArray,val shiny:Boolean,
        val ability:Int,val abilityNumber:Int,val form:Int,val originGame:Int,val eggLocation:Int,val metLocation:Int,
        val ball:Int,val metLevel:Int,val otGender:Int,val fatefulEncounter:Boolean
    )

    private data class Gen5PartyRebuild(val level:Int,val baseStats:IntArray)

    private var gen5LegalityRecheckAfterEdit=false

    private fun gen5PidForAbilityAndShiny(oldPid:Long, tid:Int, sid:Int, abilityNumber:Int, wantShiny:Boolean):Long {
        var hi=((oldPid ushr 16) and 0xFFFFL).toInt()
        var lo=(oldPid and 0xFFFFL).toInt()
        if(abilityNumber==1 || abilityNumber==2){
            val wantParity=if(abilityNumber==2)1 else 0
            if((hi and 1)!=wantParity)hi=hi xor 1
        }
        val nowShiny=(tid xor sid xor lo xor hi)<8
        if(nowShiny!=wantShiny)lo=if(wantShiny)(tid xor sid xor hi) and 0xFFFF else (lo xor 0x0008) and 0xFFFF
        return ((hi.toLong() shl 16) or lo.toLong()) and 0xFFFFFFFFL
    }

    private fun gen5PartyStatsFromRaw(raw:ByteArray):IntArray? {
        if(raw.size!=220)return null
        val d=decryptPk5(raw)?:return null
        return intArrayOf(
            d[0x8C].toInt() and 0xFF,
            readU16LE(d,0x8E), readU16LE(d,0x90), readU16LE(d,0x92),
            readU16LE(d,0x94), readU16LE(d,0x96), readU16LE(d,0x98), readU16LE(d,0x9A)
        )
    }

    private fun calculateGen5BattleStats(base:IntArray, ivs:IntArray, evs:IntArray, nature:Int, level:Int):IntArray {
        require(base.size==6 && ivs.size==6 && evs.size==6 && nature in 0..24 && level in 1..100)
        val out=IntArray(6)
        out[0]=if(base[0]==1)1 else (((2*base[0]+ivs[0]+evs[0]/4)*level)/100)+level+10
        val up=nature/5; val down=nature%5
        for(i in 1..5){
            var stat=(((2*base[i]+ivs[i]+evs[i]/4)*level)/100)+5
            val n=i-1
            if(up!=down){
                if(n==up)stat=stat*110/100
                else if(n==down)stat=stat*90/100
            }
            out[i]=stat
        }
        return out
    }

    private fun parseGen5BaseStats(json:JSONObject?):IntArray? {
        json?:return null
        fun parseArray(a:org.json.JSONArray?):IntArray? {
            a?:return null
            val m=HashMap<String,Int>()
            for(i in 0 until a.length()){
                val o=a.optJSONObject(i)?:continue
                val name=o.optJSONObject("stat")?.optString("name").orEmpty()
                val value=o.optInt("base_stat",-1)
                if(name.isNotBlank()&&value>0)m[name]=value
            }
            val keys=arrayOf("hp","attack","defense","speed","special-attack","special-defense")
            if(keys.any{m[it]==null})return null
            return IntArray(6){m[keys[it]]!!}
        }
        val past=json.optJSONArray("past_stats")
        if(past!=null){
            for(i in 0 until past.length()){
                val o=past.optJSONObject(i)?:continue
                if(o.optJSONObject("generation")?.optString("name")=="generation-v") parseArray(o.optJSONArray("stats"))?.let{return it}
            }
        }
        return parseArray(json.optJSONArray("stats"))
    }

    private fun resolveGen5BaseStatsAsync(species:Int, done:(IntArray?)->Unit){
        val key="gen5_base_stats_$species"
        metaPrefs.getString(key,null)?.split(',')?.mapNotNull{it.toIntOrNull()}?.takeIf{it.size==6}?.let{cached->done(cached.toIntArray());return}
        imageExecutor.execute{
            val stats=try{parseGen5BaseStats(fetchJson("https://pokeapi.co/api/v2/pokemon/$species"))}catch(_:Exception){null}
            if(stats!=null)metaPrefs.edit().putString(key,stats.joinToString(",")).apply()
            mainHandler.post{if(!isFinishing&&!isDestroyed)done(stats)}
        }
    }

    private fun prepareGen5PartyEdit(location:String,pokemon:PokemonEntry,v:Gen5EditValues){
        if(pokemon.form!=0 || v.form!=0){showDialog("Party form editing locked","Party stat rebuilding currently supports only default form 0. Boxed Pokémon can use form IDs 0–31; non-default Party forms remain protected.");return}
        Toast.makeText(this,"Checking Gen 5 growth and battle stats…",Toast.LENGTH_SHORT).show()
        resolveGen5BaseStatsAsync(pokemon.species) baseStats@{base->
            if(base==null){showDialog("Could not verify Gen 5 stats","PSE could not resolve Generation 5 base stats for this species. No changes were written.");return@baseStats}
            resolveBoxedLevelAsync(pokemon.species,pokemon.experience) currentLevel@{oldLevel->
                if(oldLevel==null || pokemon.level==null || oldLevel!=pokemon.level){showDialog("Could not verify current level","The stored party level does not match the level implied by its EXP, or the growth curve could not be resolved. No changes were written.");return@currentLevel}
                resolveBoxedLevelAsync(pokemon.species,v.exp) targetLevel@{newLevel->
                    if(newLevel==null){showDialog("Could not resolve new level","PSE could not map the requested EXP to a Gen 5 level. No changes were written.");return@targetLevel}
                    val rebuild=Gen5PartyRebuild(newLevel,base)
                    AlertDialog.Builder(this).setTitle("Save Gen 5 Party changes?").setMessage("PSE verified this Pokémon's current Gen 5 growth curve and base stats. It will rebuild Level, Max HP and all cached battle stats from EXP, nature, IVs and EVs, preserve current HP up to the new maximum, then rebuild PK5 + Party/checksum-table checksums and re-read everything. Any failure restores the original working copy.").setNegativeButton("Cancel",null).setPositiveButton("Save"){_,_->applyGen5PokemonEdit(location,pokemon,v,rebuild)}.show()
                }
            }
        }
    }

    private fun mutatePk5(raw:ByteArray, old:PokemonEntry, v:Gen5EditValues, partyRebuild:Gen5PartyRebuild?=null):ByteArray {
        require(raw.size==136 || raw.size==220) { "PK5 must be 136 or 220 bytes" }
        val d=decryptPk5(raw) ?: throw IllegalStateException("Could not decrypt PK5")
        writeU32LE(d,0,gen5PidForAbilityAndShiny(old.pid,old.tid,old.sid,v.abilityNumber,v.shiny))
        writeU16LE(d,0x0A,v.held)
        d[0x15]=v.ability.toByte()
        d[0x42]=((d[0x42].toInt() and 0xFE) or if(v.abilityNumber==4)1 else 0).toByte()
        d[0x40]=((d[0x40].toInt() and 0x06) or (if(v.fatefulEncounter)1 else 0) or ((v.form and 0x1F) shl 3)).toByte()
        d[0x5F]=v.originGame.toByte()
        writeU16LE(d,0x7E,v.eggLocation);writeU16LE(d,0x80,v.metLocation)
        d[0x83]=v.ball.toByte();d[0x84]=((v.metLevel and 0x7F) or ((v.otGender and 1) shl 7)).toByte()
        writeU32LE(d,0x10,v.exp)
        d[0x14]=v.friendship.toByte()
        for(i in 0..5)d[0x18+i]=v.evs[i].toByte()
        for(i in 0..3){writeU16LE(d,0x28+i*2,v.moves[i]);d[0x30+i]=v.pp[i].toByte()}
        var ivw=readU32LE(d,0x38) and 0xC0000000L
        for(i in 0..5)ivw=ivw or ((v.ivs[i].toLong() and 31L) shl (i*5))
        if(v.nickname!=old.nickname || old.isNicknamed) ivw=ivw or 0x80000000L
        writeU32LE(d,0x38,ivw)
        d[0x41]=v.nature.toByte()
        writeGen5String(d,0x48,22,v.nickname,10)
        writeGen5String(d,0x68,16,v.ot,7)
        if(partyRebuild!=null){
            require(d.size==220){"Party stat rebuild requires a 220-byte PK5"}
            val stats=calculateGen5BattleStats(partyRebuild.baseStats,v.ivs,v.evs,v.nature,partyRebuild.level)
            val oldCurrent=readU16LE(d,0x8E)
            d[0x8C]=partyRebuild.level.toByte()
            writeU16LE(d,0x8E,oldCurrent.coerceAtMost(stats[0]))
            writeU16LE(d,0x90,stats[0]);writeU16LE(d,0x92,stats[1]);writeU16LE(d,0x94,stats[2])
            writeU16LE(d,0x96,stats[3]);writeU16LE(d,0x98,stats[4]);writeU16LE(d,0x9A,stats[5])
        }
        return encryptPk5(d)
    }

    private fun showGen5PokemonEditor(location:String,pokemon:PokemonEntry){
        val global=boxedLocationToGlobalIndex(location)
        val partySlot=Regex("Party\\s+Slot\\s+(\\d+)").find(location)?.groupValues?.getOrNull(1)?.toIntOrNull()?.minus(1)?.takeIf{it in 0..5}
        val isParty=partySlot!=null
        if(global==null && partySlot==null)return showDialog("Edit Pokémon","PSE could not resolve this Gen 5 Pokémon location.")
        if(global!=null && global !in 0 until 24*30)return showDialog("Edit Pokémon","That is not a Gen 5 PC slot.")
        phoneBackAction={showPokemonDetails(location,pokemon)}
        val scroll=ScrollView(this).apply{setBackgroundColor(BG)}
        val root=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(dp(16),dp(58),dp(16),dp(28));setBackgroundColor(BG)};scroll.addView(root)
        root.addView(TextView(this).apply{text="Edit ${pokemon.nickname.ifBlank{"Species #${pokemon.species}"}}";textSize=27f;typeface=Typeface.DEFAULT_BOLD;setTextColor(TEXT)})
        addMutedLine(root,"$location • Gen 5 Stage 7 ${if(isParty)"party" else "boxed"} PK5 editor")
        addButton(root,"←  Cancel"){showPokemonDetails(location,pokemon)}
        val nick=inputField("Nickname (max 10)",pokemon.nickname).also{root.addView(it.first)}.second
        val ot=inputField("OT name (max 7)",pokemon.otName).also{root.addView(it.first)}.second
        val exp=inputField("Experience",pokemon.experience.toString(),true).also{root.addView(it.first)}.second
        val held=inputField("Held item ID",pokemon.heldItem.toString(),true).also{root.addView(it.first)}.second
        val friendship=inputField("Friendship (0–255)",pokemon.friendship.toString(),true).also{root.addView(it.first)}.second
        val natureNames=listOf("Hardy","Lonely","Brave","Adamant","Naughty","Bold","Docile","Relaxed","Impish","Lax","Timid","Hasty","Serious","Jolly","Naive","Modest","Mild","Quiet","Bashful","Rash","Calm","Gentle","Sassy","Careful","Quirky")
        val nature=spinnerField("Nature",natureNames,pokemon.nature.coerceIn(0,24)).also{root.addView(it.first)}.second
        val shiny=CheckBox(this).apply{text="Shiny";isChecked=pokemon.shiny;setTextColor(TEXT);textSize=16f};root.addView(shiny)
        val ability=inputField("Ability ID (0–255)",pokemon.ability.toString(),true).also{root.addView(it.first)}.second
        val abilityNumber=spinnerField("Ability slot",listOf("Slot 1","Slot 2","Hidden"),when(pokemon.abilityNumber){2->1;4->2;else->0}).also{root.addView(it.first)}.second
        val form=inputField("Form ID (0–31)",pokemon.form.toString(),true).also{root.addView(it.first)}.second
        addSectionTitle(root,"ORIGIN / ENCOUNTER")
        val originGame=inputField("Origin game ID (0–255)",pokemon.originGame.toString(),true).also{root.addView(it.first)}.second
        val eggLocation=inputField("Egg location ID (0–65535)",pokemon.eggLocation.toString(),true).also{root.addView(it.first)}.second
        val metLocation=inputField("Met location ID (0–65535)",pokemon.metLocation.toString(),true).also{root.addView(it.first)}.second
        val ball=inputField("Ball ID (0–255)",pokemon.ball.toString(),true).also{root.addView(it.first)}.second
        val metLevel=inputField("Met level (0–100)",pokemon.metLevel.toString(),true).also{root.addView(it.first)}.second
        val otGender=spinnerField("OT gender",listOf("Male","Female"),pokemon.otGender.coerceIn(0,1)).also{root.addView(it.first)}.second
        val fateful=CheckBox(this).apply{text="Fateful encounter";isChecked=pokemon.fatefulEncounter;setTextColor(TEXT);textSize=16f};root.addView(fateful)
        addMutedLine(root,"Shiny + ability-slot edits rebuild the PID consistently. Ability ID, form and origin/encounter fields are written explicitly and verified after re-encryption. Non-default Party forms remain protected because their cached battle stats can be form-specific.")
        addSectionTitle(root,"MOVES / PP")
        val moveIds=pokemon.moves.copyOf();val ppF=ArrayList<EditText>()
        for(i in 0..3){
            val selector=selectorButton("Move ${i+1}",if(moveIds[i]==0)"None" else "Move #${moveIds[i]}").also{root.addView(it.first)}.second
            if(moveIds[i]!=0){val oldMove=moveIds[i];resolvePokeApiNameAsync("move",oldMove){n->if(n!=null&&moveIds[i]==oldMove)selector.text="$n (#$oldMove)"}}
            val pp=inputField("Move ${i+1} PP (0–63)",pokemon.movePP[i].toString(),true).also{root.addView(it.first)}.second;ppF.add(pp)
            selector.setOnClickListener{
                openCatalogPicker("move","Choose Gen 5 Move ${i+1}",false){chosen->
                    if(chosen.id !in 0..559)showDialog("Gen 5 move","${chosen.name} (#${chosen.id}) did not exist in Generation 5.")
                    else{moveIds[i]=chosen.id;selector.text=chosen.toString();if(chosen.id==0)pp.setText("0") else resolveMovePpAsync(chosen.id){base->if(base!=null)pp.setText(base.coerceAtMost(63).toString())}}
                }
            }
        }
        val labels=arrayOf("HP","Attack","Defense","Speed","Sp. Atk","Sp. Def")
        addSectionTitle(root,"IVs");val ivF=ArrayList<EditText>();for(i in 0..5)ivF.add(inputField("${labels[i]} IV (0–31)",pokemon.ivs[i].toString(),true).also{root.addView(it.first)}.second)
        addSectionTitle(root,"EVs");val evF=ArrayList<EditText>();for(i in 0..5)evF.add(inputField("${labels[i]} EV (0–255)",pokemon.evs[i].toString(),true).also{root.addView(it.first)}.second)
        if(isParty){
            addMutedLine(root,"Stage 7 Party stat rebuild: EXP determines Level automatically. Nature, IV and EV edits recalculate Max HP, Attack, Defense, Speed, Sp. Atk and Sp. Def. Non-default forms remain locked rather than guessing form-specific base stats.")
        }
        addButton(root,"💾  Save Changes") save@{
            val v=try{Gen5EditValues(nick.text.toString().trim(),ot.text.toString().trim(),exp.text.toString().toLong(),held.text.toString().toInt(),friendship.text.toString().toInt(),nature.selectedItemPosition,moveIds.copyOf(),IntArray(4){ppF[it].text.toString().toInt()},IntArray(6){ivF[it].text.toString().toInt()},IntArray(6){evF[it].text.toString().toInt()},shiny.isChecked,ability.text.toString().toInt(),when(abilityNumber.selectedItemPosition){1->2;2->4;else->1},form.text.toString().toInt(),originGame.text.toString().toInt(),eggLocation.text.toString().toInt(),metLocation.text.toString().toInt(),ball.text.toString().toInt(),metLevel.text.toString().toInt(),otGender.selectedItemPosition,fateful.isChecked)}catch(_:Exception){showDialog("Invalid values","One or more fields are not valid numbers.");return@save}
            val err=when{v.nickname.length>10->"Nickname must be 10 characters or fewer.";v.ot.length>7->"OT name must be 7 characters or fewer.";v.nickname.any{Character.isSurrogate(it)}||v.ot.any{Character.isSurrogate(it)}->"Unsupported text character.";v.exp !in 0..0xFFFFFFFFL->"Experience value is invalid.";v.held !in 0..65535->"Held item ID is invalid.";v.friendship !in 0..255->"Friendship must be 0–255.";v.moves.any{it !in 0..559}->"Gen 5 move IDs must be 0–559.";v.pp.any{it !in 0..63}->"PP must be 0–63.";v.ivs.any{it !in 0..31}->"IVs must be 0–31.";v.evs.any{it !in 0..255}->"EVs must be 0–255.";v.evs.sum()>510->"EV total must be 510 or lower.";v.ability !in 0..255->"Ability ID must be 0–255.";v.abilityNumber !in listOf(1,2,4)->"Ability slot is invalid.";v.form !in 0..31->"Form ID must be 0–31.";v.originGame !in 0..255->"Origin game ID must be 0–255.";v.eggLocation !in 0..65535 || v.metLocation !in 0..65535->"Location IDs must be 0–65535.";v.ball !in 0..255->"Ball ID must be 0–255.";v.metLevel !in 0..100->"Met level must be 0–100.";v.otGender !in 0..1->"OT gender is invalid.";else->null}
            if(err!=null){showDialog("Invalid values",err);return@save}
            if(isParty)prepareGen5PartyEdit(location,pokemon,v) else AlertDialog.Builder(this).setTitle("Save Gen 5 Pokémon changes?").setMessage("PSE will rebuild the encrypted PK5, update the correct Gen 5 save-block CRC and mirrored checksum table, re-read the edited slot, and verify every changed field. If anything fails, the original working copy is restored automatically. Your emulator save is still untouched until Save & Replace Current Save.").setNegativeButton("Cancel",null).setPositiveButton("Save"){_,_->applyGen5PokemonEdit(location,pokemon,v,null)}.show()
        }
        addMutedLine(root,"Stage 7 writes only the selected PK5 in PSE's working copy. Boxed editing remains fully enabled. Default-form Party Pokémon now support shiny, ability, origin/encounter, EXP/level, nature, IV and EV edits; boxed Pokémon also support form IDs with cached-stat rebuilding, checksum/reparse verification and rollback.")
        setContentView(scroll)
    }

    private fun applyGen5PokemonEdit(location:String,old:PokemonEntry,v:Gen5EditValues,partyRebuild:Gen5PartyRebuild?=null){
        val global=boxedLocationToGlobalIndex(location)
        val partySlot=Regex("Party\\s+Slot\\s+(\\d+)").find(location)?.groupValues?.getOrNull(1)?.toIntOrNull()?.minus(1)?.takeIf{it in 0..5}
        if(global==null && partySlot==null)return showDialog("Edit failed","Gen 5 Pokémon location could not be resolved.")
        val file=importedFile?:return
        val original=try{file.readBytes()}catch(e:Exception){showDialog("Edit failed",e.message?:"Could not read save");return}
        val save=original.copyOf()
        try{
            val profile=detectGen5Profile(save) ?: throw IllegalStateException("Could not detect Gen 5 save layout")
            val staged:PokemonEntry
            if(global!=null){
                if(global !in 0 until 24*30)throw IllegalStateException("Invalid Gen 5 PC slot")
                val box=global/30;val slot=global%30
                if(!gen5BoxChecksumValid(save,box,profile))throw IllegalStateException("The source Gen 5 box checksum did not validate")
                if(!gen5ChecksumTableValid(save,profile))throw IllegalStateException("The source Gen 5 checksum table did not validate")
                val off=0x00400+box*0x1000+slot*136
                val current=parsePk5(save.copyOfRange(off,off+136),false) ?: throw IllegalStateException("Pokémon is no longer in that box slot")
                if(current.pid!=old.pid || current.species!=old.species)throw IllegalStateException("The box slot changed since the editor was opened")
                if(!current.checksumValid)throw IllegalStateException("Source PK5 checksum is invalid")
                mutatePk5(save.copyOfRange(off,off+136),current,v).copyInto(save,off)
                updateGen5BoxChecksum(save,box,profile)
                if(!gen5BoxChecksumValid(save,box,profile) || !gen5ChecksumTableValid(save,profile))throw IllegalStateException("Gen 5 save checksum rebuild failed")
                staged=parsePk5(save.copyOfRange(off,off+136),false) ?: throw IllegalStateException("Edited PK5 could not be re-read")
            }else{
                val slot=requireNotNull(partySlot)
                if(!gen5PartyChecksumValid(save,profile))throw IllegalStateException("The source Gen 5 party checksum did not validate")
                if(!gen5ChecksumTableValid(save,profile))throw IllegalStateException("The source Gen 5 checksum table did not validate")
                val count=(save[0x18E04].toInt() and 0xFF).coerceIn(0,6)
                if(slot>=count)throw IllegalStateException("That Gen 5 party slot is empty")
                val off=0x18E08+slot*220
                val current=parsePk5(save.copyOfRange(off,off+220),true) ?: throw IllegalStateException("Pokémon is no longer in that party slot")
                if(current.pid!=old.pid || current.species!=old.species)throw IllegalStateException("The party slot changed since the editor was opened")
                if(!current.checksumValid)throw IllegalStateException("Source party PK5 checksum is invalid")
                val rebuild=partyRebuild ?: throw IllegalStateException("Party stat rebuild context is missing")
                if(current.form!=0)throw IllegalStateException("Non-default Gen 5 forms remain locked for Party stat editing")
                if(current.level==null)throw IllegalStateException("Current Party level could not be read")
                val before=gen5PartyStatsFromRaw(save.copyOfRange(off,off+220)) ?: throw IllegalStateException("Current Party battle stats could not be read")
                val expectedBefore=calculateGen5BattleStats(rebuild.baseStats,current.ivs,current.evs,current.nature,current.level)
                if(before[0]!=current.level || before[2]!=expectedBefore[0] || before[3]!=expectedBefore[1] || before[4]!=expectedBefore[2] || before[5]!=expectedBefore[3] || before[6]!=expectedBefore[4] || before[7]!=expectedBefore[5])throw IllegalStateException("Current cached Party stats do not match the verified Gen 5 calculation; edit refused")
                mutatePk5(save.copyOfRange(off,off+220),current,v,rebuild).copyInto(save,off)
                updateGen5PartyChecksum(save,profile)
                if(!gen5PartyChecksumValid(save,profile) || !gen5ChecksumTableValid(save,profile))throw IllegalStateException("Gen 5 party checksum rebuild failed")
                staged=parsePk5(save.copyOfRange(off,off+220),true) ?: throw IllegalStateException("Edited party PK5 could not be re-read")
                if(staged.level!=rebuild.level)throw IllegalStateException("Rebuilt Party level did not verify")
                val after=gen5PartyStatsFromRaw(save.copyOfRange(off,off+220)) ?: throw IllegalStateException("Rebuilt Party battle stats could not be read")
                val expectedAfter=calculateGen5BattleStats(rebuild.baseStats,v.ivs,v.evs,v.nature,rebuild.level)
                if(after[0]!=rebuild.level || after[2]!=expectedAfter[0] || after[3]!=expectedAfter[1] || after[4]!=expectedAfter[2] || after[5]!=expectedAfter[3] || after[6]!=expectedAfter[4] || after[7]!=expectedAfter[5] || after[1]>after[2])throw IllegalStateException("Rebuilt Party battle stats failed verification")
            }
            if(!staged.checksumValid || staged.species!=old.species || staged.pid!=gen5PidForAbilityAndShiny(old.pid,old.tid,old.sid,v.abilityNumber,v.shiny) || staged.shiny!=v.shiny || staged.ability!=v.ability || staged.abilityNumber!=v.abilityNumber || staged.form!=v.form || staged.originGame!=v.originGame || staged.eggLocation!=v.eggLocation || staged.metLocation!=v.metLocation || staged.ball!=v.ball || staged.metLevel!=v.metLevel || staged.otGender!=v.otGender || staged.fatefulEncounter!=v.fatefulEncounter || staged.nickname!=v.nickname || staged.otName!=v.ot || staged.experience!=v.exp || staged.heldItem!=v.held || staged.friendship!=v.friendship || staged.nature!=v.nature || !staged.moves.contentEquals(v.moves) || !staged.movePP.contentEquals(v.pp) || !staged.ivs.contentEquals(v.ivs) || !staged.evs.contentEquals(v.evs))throw IllegalStateException("Edited PK5 values did not verify")
            file.writeBytes(save)
            val verify=file.readBytes();val vp=detectGen5Profile(verify) ?: throw IllegalStateException("Written Gen 5 save layout could not be re-read")
            val q=if(global!=null){
                val box=global/30;val slot=global%30
                if(!gen5BoxChecksumValid(verify,box,vp) || !gen5ChecksumTableValid(verify,vp))throw IllegalStateException("Written Gen 5 box checksums failed verification")
                gen5Box(verify,box)[slot]
            }else{
                val slot=requireNotNull(partySlot)
                if(!gen5PartyChecksumValid(verify,vp) || !gen5ChecksumTableValid(verify,vp))throw IllegalStateException("Written Gen 5 party checksums failed verification")
                gen5Party(verify)[slot]
            } ?: throw IllegalStateException("Written PK5 could not be re-read")
            if(!q.checksumValid || q.species!=staged.species || q.pid!=staged.pid || q.shiny!=v.shiny || q.ability!=v.ability || q.abilityNumber!=v.abilityNumber || q.form!=v.form || q.originGame!=v.originGame || q.eggLocation!=v.eggLocation || q.metLocation!=v.metLocation || q.ball!=v.ball || q.metLevel!=v.metLevel || q.otGender!=v.otGender || q.fatefulEncounter!=v.fatefulEncounter || q.nickname!=v.nickname || q.otName!=v.ot || q.experience!=v.exp || q.heldItem!=v.held || q.friendship!=v.friendship || q.nature!=v.nature || !q.moves.contentEquals(v.moves) || !q.movePP.contentEquals(v.pp) || !q.ivs.contentEquals(v.ivs) || !q.evs.contentEquals(v.evs))throw IllegalStateException("Written PK5 changed during verification")
            if(partySlot!=null && partyRebuild!=null){
                if(q.level!=partyRebuild.level)throw IllegalStateException("Written Party level changed during verification")
                val off=0x18E08+partySlot*220
                val stats=gen5PartyStatsFromRaw(verify.copyOfRange(off,off+220)) ?: throw IllegalStateException("Written Party stats could not be re-read")
                val expected=calculateGen5BattleStats(partyRebuild.baseStats,v.ivs,v.evs,v.nature,partyRebuild.level)
                if(stats[0]!=partyRebuild.level || stats[2]!=expected[0] || stats[3]!=expected[1] || stats[4]!=expected[2] || stats[5]!=expected[3] || stats[6]!=expected[4] || stats[7]!=expected[5] || stats[1]>stats[2])throw IllegalStateException("Written Party battle stats changed during verification")
            }
            Toast.makeText(this,"Gen 5 Pokémon updated and verified",Toast.LENGTH_LONG).show()
            if(gen5LegalityRecheckAfterEdit){gen5LegalityRecheckAfterEdit=false;checkGen5PokemonLegality(location,q)}else showPokemonDetails(location,q)
        }catch(e:Exception){
            runCatching{file.writeBytes(original)}
            showDialog("Gen 5 edit rolled back","${e.message?:"Unknown error"}. The original working copy was restored.")
        }
    }

    private fun editGen5Nickname(location:String,p:PokemonEntry) {
        val global=boxedLocationToGlobalIndex(location) ?: return showDialog("Gen 5 edit","Party writes remain safety-locked for now.")
        val input=EditText(this).apply{setText(p.nickname);setSingleLine(true)}
        AlertDialog.Builder(this).setTitle("Edit Gen 5 nickname").setMessage("First Gen 5 writer test: change only the boxed Pokémon nickname.")
            .setView(input).setNegativeButton("Cancel",null).setPositiveButton("Save"){_,_->
                val file=importedFile ?: return@setPositiveButton
                val original=file.readBytes(); val save=original.copyOf(); val profile=detectGen5Profile(save) ?: return@setPositiveButton
                try {
                    val box=global/30; val slot=global%30; val off=0x00400+box*0x1000+slot*136
                    val raw=save.copyOfRange(off,off+136); val d=decryptPk5(raw) ?: error("PK5 decrypt failed")
                    writeGen5String(d,0x48,22,input.text.toString().take(10),10); val enc=encryptPk5(d); enc.copyInto(save,off)
                    updateGen5BoxChecksum(save,box,profile); file.writeBytes(save)
                    val verify=file.readBytes(); val vp=detectGen5Profile(verify) ?: error("Gen 5 save checksums did not validate")
                    val q=gen5Box(verify,box)[slot] ?: error("Edited PK5 could not be re-read")
                    if(!q.checksumValid || q.species!=p.species || q.pid!=p.pid || q.nickname!=input.text.toString().take(10)) error("Edited PK5 verification failed")
                    Toast.makeText(this,"Gen 5 nickname updated and verified",Toast.LENGTH_LONG).show(); showPokemonDetails(location,q)
                } catch(e:Exception) { runCatching{file.writeBytes(original)}; showDialog("Gen 5 edit rolled back",e.message ?: "Verification failed") }
            }.show()
    }

    private fun showGen5PokemonViewer(tab:String="party", boxIndex:Int=0) {
        phoneBackAction={ resetPokemonSelection(); showHome() }
        val file=importedFile ?: return showDialog("Gen 5","No Gen 5 save is loaded.")
        val data=runCatching{file.readBytes()}.getOrDefault(ByteArray(0))
        val profile=detectGen5Profile(data) ?: return showDialog("Gen 5","PSE could not validate this Gen 5 save layout.")
        val safeBox=boxIndex.coerceIn(0,23)
        val scroll=ScrollView(this).apply{setBackgroundColor(BG)}
        val root=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(dp(12),dp(54),dp(12),dp(24));setBackgroundColor(BG)}
        scroll.addView(root)
        root.addView(TextView(this).apply{text="My Pokémon";textSize=26f;typeface=Typeface.DEFAULT_BOLD;setTextColor(TEXT)})
        val exactGame = gen5GameNameFromPath(currentSourceLabel ?: file.name, profile).removePrefix("Pokémon ")
        root.addView(TextView(this).apply{text="Nintendo DS • Gen 5 • $exactGame • Stage 7";textSize=14f;setTextColor(MUTED);setPadding(0,dp(4),0,dp(12))})
        val tabs=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL}
        fun tabButton(label:String,active:Boolean,go:()->Unit)=Button(this).apply {
            text=label; setAllCaps(false); isEnabled=true; alpha=if(active)1f else 0.62f
            setOnClickListener { if(!active) go() }
        }
        tabs.addView(tabButton("Party",tab=="party"){showGen5PokemonViewer("party",safeBox)},LinearLayout.LayoutParams(0,dp(52),1f))
        tabs.addView(tabButton("PC Boxes",tab!="party"){showGen5PokemonViewer("boxes",safeBox)},LinearLayout.LayoutParams(0,dp(52),1f))
        root.addView(tabs)

        // Stage 3 verification summary: parse every native PK5 slot up front so a real
        // BW/B2W2 save can immediately prove that party + full PC storage mapping is sound.
        val partyPreview = gen5Party(data)
        var boxedCount = 0
        var badPk5Checksums = 0
        for (b in 0 until 24) {
            gen5Box(data, b).forEach { mon ->
                if (mon != null) {
                    if (mon.checksumValid) boxedCount++ else badPk5Checksums++
                }
            }
        }
        // Only checksum-valid PK5 records count as occupied. A structurally readable record with a
        // bad checksum is surfaced separately instead of inflating the occupied-slot total.
        val partyCount = partyPreview.count { it != null && it.checksumValid }
        val summary = if (badPk5Checksums == 0)
            "Parsed: $partyCount / 6 Party • $boxedCount / 720 PC • PK5 checksums OK"
        else
            "Parsed: $partyCount / 6 Party • $boxedCount / 720 PC • ⚠ $badPk5Checksums PK5 checksum issue(s)"
        addMutedLine(root, summary)
        if(tab=="party") {
            val mons=partyPreview
            mons.forEachIndexed{i,p-> if(p!=null) root.addView(pokemonRow("Party Slot ${i+1}",p)) else root.addView(emptyPokemonRow("Party Slot ${i+1}")) }
            addMutedLine(root,"${mons.count{it!=null && it.checksumValid}} / 6 party slots occupied.")
        } else {
            val nav=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL;gravity=Gravity.CENTER_VERTICAL;setPadding(0,dp(8),0,dp(4))}
            nav.addView(Button(this).apply{text="‹";setOnClickListener{showGen5PokemonViewer("boxes",(safeBox+23)%24)}},LinearLayout.LayoutParams(dp(58),dp(52)))
            nav.addView(TextView(this).apply{text="Box ${safeBox+1} / 24";gravity=Gravity.CENTER;textSize=18f;typeface=Typeface.DEFAULT_BOLD;setTextColor(TEXT)},LinearLayout.LayoutParams(0,dp(52),1f))
            nav.addView(Button(this).apply{text="›";setOnClickListener{showGen5PokemonViewer("boxes",(safeBox+1)%24)}},LinearLayout.LayoutParams(dp(58),dp(52)))
            root.addView(nav)
            val mons=gen5Box(data,safeBox)
            // Match the native Gen 5 PC layout: 6 columns × 5 rows = 30 slots.
            val grid=GridLayout(this).apply{
                columnCount=6
                rowCount=5
                alignmentMode=GridLayout.ALIGN_BOUNDS
                useDefaultMargins=false
                setPadding(0,dp(6),0,dp(8))
            }
            mons.forEachIndexed{i,p->grid.addView(boxGridCell(safeBox,i,p,safeBox*30+i,false,false))}
            root.addView(grid); addMutedLine(root,"${mons.count{it!=null && it.checksumValid}} / 30 occupied slots in Box ${safeBox+1}.")
        }
        addMutedLine(root,"Gen 5 Stage 7: boxed PK5 editing remains enabled. Default-form Party Pokémon now support EXP/level, nature, IVs and EVs with cached battle-stat rebuilding. Current stats are validated before editing; Party-block CRC + checksum-table mirrors are rebuilt and verified.")
        val shell=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setBackgroundColor(BG)}
        shell.addView(scroll,LinearLayout.LayoutParams(-1,0,1f));shell.addView(buildBottomNav("pokemon"),LinearLayout.LayoutParams(-1,-2));setContentView(shell)
    }

    private data class Gen4Profile(
        val family:String, val generalSize:Int, val storageSize:Int, val storageStart:Int,
        val partyOffset:Int, val hgss:Boolean
    )

    private fun gen4FooterLooksValid(data:ByteArray, generalSize:Int):Boolean {
        if(data.size!=SIZE_G4)return false
        for(part in intArrayOf(0,0x40000)){
            if(part+generalSize>data.size)continue
            val size=readU32LE(data,part+generalSize-0x0C)
            val magic=readU32LE(data,part+generalSize-0x08)
            if(size==generalSize.toLong() && (magic==0x20060623L || magic==0x20070903L)) return true
        }
        return false
    }

    private fun detectGen4Profile(data:ByteArray):Gen4Profile? = when {
        gen4FooterLooksValid(data,0xC100) -> Gen4Profile("Diamond / Pearl",0xC100,0x121E0,0xC100,0x98,false)
        gen4FooterLooksValid(data,0xCF2C) -> Gen4Profile("Platinum",0xCF2C,0x121E4,0xCF2C,0xA0,false)
        gen4FooterLooksValid(data,0xF628) -> Gen4Profile("HeartGold / SoulSilver",0xF628,0x12310,0xF700,0x98,true)
        else -> null
    }

    private fun gen4CompareCounters(a:Long,b:Long):Int {
        val max=0xFFFFFFFFL
        if(a==max && b!=max-1)return 1
        if(b==max && a!=max-1)return 0
        return if(a>=b)0 else 1
    }

    private fun gen4ActiveBlock(data:ByteArray,begin:Int,length:Int):Int {
        val f0=begin+length-0x14
        val f1=f0+0x40000
        if(f0<0 || f1+8>data.size)return 0
        val major=gen4CompareCounters(readU32LE(data,f0),readU32LE(data,f1))
        if(readU32LE(data,f0)!=readU32LE(data,f1))return major
        return gen4CompareCounters(readU32LE(data,f0+4),readU32LE(data,f1+4))
    }

    private fun gen4Crypt(buf:ByteArray,start:Int,end:Int,seedIn:Long){
        var seed=seedIn and 0xFFFFFFFFL
        var o=start
        while(o+1<end){
            seed=(0x41C64E6DL*seed+0x6073L) and 0xFFFFFFFFL
            val xor=(seed ushr 16).toInt() and 0xFFFF
            writeU16LE(buf,o,readU16LE(buf,o) xor xor)
            o+=2
        }
    }

    private val gen4BlockPosition = intArrayOf(
        0,1,2,3, 0,1,3,2, 0,2,1,3, 0,3,1,2,
        0,2,3,1, 0,3,2,1, 1,0,2,3, 1,0,3,2,
        2,0,1,3, 3,0,1,2, 2,0,3,1, 3,0,2,1,
        1,2,0,3, 1,3,0,2, 2,1,0,3, 3,1,0,2,
        2,3,0,1, 3,2,0,1, 1,2,3,0, 1,3,2,0,
        2,1,3,0, 3,1,2,0, 2,3,1,0, 3,2,1,0,
        0,1,2,3, 0,1,3,2, 0,2,1,3, 0,3,1,2,
        0,2,3,1, 0,3,2,1, 1,0,2,3, 1,0,3,2
    )

    private fun gen4Unshuffle(buf:ByteArray){
        val pid=readU32LE(buf,0).toInt()
        val sv=(pid ushr 13) and 31
        if(sv==0)return
        val perm=intArrayOf(0,1,2,3)
        val slotOf=intArrayOf(0,1,2,3)
        for(i in 0 until 3){
            val desired=gen4BlockPosition[sv*4+i]
            val j=slotOf[desired]
            if(j==i)continue
            for(k in 0 until 32){
                val a=8+i*32+k; val b=8+j*32+k
                val t=buf[a];buf[a]=buf[b];buf[b]=t
            }
            val blockAtI=perm[i]
            perm[j]=blockAtI
            slotOf[blockAtI]=j
        }
    }

    private fun decryptPk4(raw:ByteArray):ByteArray?{
        if(raw.size!=136 && raw.size!=236)return null
        val d=raw.copyOf()
        val pid=readU32LE(d,0)
        val chk=readU16LE(d,6).toLong()
        gen4Crypt(d,8,136,chk)
        if(d.size>136)gen4Crypt(d,136,d.size,pid)
        gen4Unshuffle(d)
        return d
    }

    private fun gen4Char(v:Int):Char = when(v){
        in 0x121..0x12A -> ('0'.code+v-0x121).toChar()
        in 0x12B..0x144 -> ('A'.code+v-0x12B).toChar()
        in 0x145..0x15E -> ('a'.code+v-0x145).toChar()
        0x1DE -> ' '
        0x1AC -> '!'; 0x1AD -> '?'; 0x1AE -> ','; 0x1AF -> '.'
        0x1B1 -> '/'; 0x1B3 -> '\''; 0x1BA -> '('; 0x1BB -> ')'; 0x1BD -> '♂'; 0x1BE -> '♀'
        0x1BF -> '+'; 0x1C0 -> '-'; 0x1C1 -> '*'; 0x1C3 -> '='; 0x1C4 -> '&'; 0x1C6 -> ':'; 0x1C7 -> ';'; 0x1D0 -> '@'; 0x1D2 -> '%'; 0x1E9 -> '_'
        else -> '?'
    }

    private fun readGen4String(data:ByteArray,off:Int,len:Int):String = buildString{
        var i=0
        while(i+1<len && off+i+1<data.size){
            val v=readU16LE(data,off+i)
            if(v==0 || v==0xFFFF)break
            append(gen4Char(v));i+=2
        }
    }.trim()

    private fun parsePk4(raw:ByteArray,party:Boolean):PokemonEntry?{
        val d=decryptPk4(raw)?:return null
        val species=readU16LE(d,0x08)
        if(species !in 1..493)return null
        var sum=0
        for(o in 0x08 until 0x88 step 2)sum=(sum+readU16LE(d,o)) and 0xFFFF
        val checksumOk=sum==readU16LE(d,0x06)
        val pid=readU32LE(d,0)
        val tid=readU16LE(d,0x0C);val sid=readU16LE(d,0x0E)
        val iv32=readU32LE(d,0x38)
        val g=d[0x40].toInt() and 0xFF
        val gender=if((g and 4)!=0)2 else if((g and 2)!=0)1 else 0
        val poker=d[0x82].toInt() and 0xFF
        val ballHg=d[0x86].toInt() and 0xFF
        val eggPt=readU16LE(d,0x44);val metPt=readU16LE(d,0x46)
        val eggDp=readU16LE(d,0x7E);val metDp=readU16LE(d,0x80)
        val shiny=(tid xor sid xor (pid.toInt() and 0xFFFF) xor ((pid.toInt() ushr 16) and 0xFFFF))<8
        return PokemonEntry(
            species=species,nickname=readGen4String(d,0x48,22),isNicknamed=((iv32 ushr 31) and 1L)==1L,
            level=if(party && d.size>0x8C)(d[0x8C].toInt() and 0xFF).takeIf{it in 1..100}else null,
            checksumValid=checksumOk,heldItem=readU16LE(d,0x0A),tid=tid,sid=sid,experience=readU32LE(d,0x10),
            ability=d[0x15].toInt() and 0xFF,abilityNumber=if((pid and 1L)==0L)1 else 2,pid=pid,nature=(pid%25L).toInt(),gender=gender,form=(g ushr 3) and 0x1F,
            evs=IntArray(6){d[0x18+it].toInt() and 0xFF},moves=IntArray(4){readU16LE(d,0x28+it*2)},movePP=IntArray(4){d[0x30+it].toInt() and 0xFF},
            ivs=IntArray(6){i->((iv32 ushr (i*5)) and 31L).toInt()},isEgg=((iv32 ushr 30) and 1L)==1L,
            otName=readGen4String(d,0x68,16),friendship=d[0x14].toInt() and 0xFF,currentHandler=0,pokerusDays=poker and 0xF,pokerusStrain=(poker ushr 4) and 0xF,
            shiny=shiny,language=d[0x17].toInt() and 0xFF,markingValue=d[0x16].toInt() and 0xFF,fatefulEncounter=(g and 1)!=0,relearnMoves=IntArray(4),
            eggLocation=if(eggPt!=0)eggPt else eggDp,metLocation=if(metPt!=0)metPt else metDp,ball=if(ballHg!=0)ballHg else (d[0x83].toInt() and 0xFF),
            metLevel=d[0x84].toInt() and 0x7F,otGender=(d[0x84].toInt() ushr 7) and 1,originGame=d[0x5F].toInt() and 0xFF,
            country=0,region=0,consoleRegion=0,eggYear=d[0x78].toInt() and 0xFF,eggMonth=d[0x79].toInt() and 0xFF,eggDay=d[0x7A].toInt() and 0xFF,
            metYear=d[0x7B].toInt() and 0xFF,metMonth=d[0x7C].toInt() and 0xFF,metDay=d[0x7D].toInt() and 0xFF,hyperTrainFlags=0
        )
    }

    private fun gen4Crc16Ccitt(data:ByteArray,start:Int,endExclusive:Int):Int {
        var crc=0xFFFF
        val end=endExclusive.coerceAtMost(data.size)
        var i=start.coerceAtLeast(0)
        while(i<end){
            crc = crc xor ((data[i].toInt() and 0xFF) shl 8)
            repeat(8){ crc = if((crc and 0x8000)!=0) ((crc shl 1) xor 0x1021) and 0xFFFF else (crc shl 1) and 0xFFFF }
            i++
        }
        return crc and 0xFFFF
    }

    private fun gen4BlockChecksumValid(data:ByteArray,start:Int,length:Int,p:Gen4Profile):Boolean {
        val footer=if(p.hgss)0x10 else 0x14
        if(start<0 || length<=footer || start+length>data.size)return false
        val stored=readU16LE(data,start+length-2)
        val actual=gen4Crc16Ccitt(data,start,start+length-footer)
        return stored==actual
    }

    private data class Gen4Validation(
        val activeGeneral:Int,val activeStorage:Int,val generalChecksum:Boolean,val storageChecksum:Boolean,
        val occupiedPk4:Int,val goodPk4:Int,val badPk4:Int,val emptyPk4:Int
    )

    private fun gen4Validation(data:ByteArray,p:Gen4Profile):Gen4Validation {
        val ag=gen4ActiveBlock(data,0,p.generalSize)
        val ast=gen4ActiveBlock(data,p.storageStart,p.storageSize)
        val gStart=ag*0x40000
        val sStart=ast*0x40000+p.storageStart
        var occupied=0;var good=0;var bad=0;var empty=0
        for(box in 0 until 18){
            val boxBase=if(p.hgss) sStart+box*0x1000 else sStart+4+box*0xFF0
            for(slot in 0 until 30){
                val o=boxBase+slot*136
                if(o<0 || o+136>data.size)continue
                val raw=data.copyOfRange(o,o+136)
                val mon=parsePk4(raw,false)
                if(mon==null){
                    // Gen 4 unused PC slots are not guaranteed to be physically zero-filled.
                    // If the enclosing storage block CRC passes and no valid PK4 can be
                    // decoded from the slot, treat it as unoccupied rather than corrupt.
                    empty++
                }else{
                    occupied++
                    if(mon.checksumValid) good++ else bad++
                }
            }
        }
        val party=gen4Party(data,p)
        for(mon in party){
            if(mon!=null){ occupied++; if(mon.checksumValid)good++ else bad++ } else empty++
        }
        return Gen4Validation(ag,ast,gen4BlockChecksumValid(data,gStart,p.generalSize,p),gen4BlockChecksumValid(data,sStart,p.storageSize,p),occupied,good,bad,empty)
    }

    private fun gen4BoxName(data:ByteArray,p:Gen4Profile,box:Int):String {
        val active=gen4ActiveBlock(data,p.storageStart,p.storageSize)
        val base=active*0x40000+p.storageStart
        val namesBase=if(p.hgss) base+0x12008 else base+4+(18*0xFF0)
        return readGen4String(data,namesBase+box*40,40)
    }

    private fun gen4Party(data:ByteArray,p:Gen4Profile):List<PokemonEntry?>{
        val active=gen4ActiveBlock(data,0,p.generalSize)
        val base=active*0x40000
        val count=(data.getOrNull(base+p.partyOffset-4)?.toInt() ?: 0) and 0xFF
        return (0 until 6).map{slot->
            if(slot>=count)null else {
                val o=base+p.partyOffset+slot*236
                if(o+236>data.size)null else parsePk4(data.copyOfRange(o,o+236),true)
            }
        }
    }

    private fun gen4Box(data:ByteArray,p:Gen4Profile,box:Int):List<PokemonEntry?>{
        val active=gen4ActiveBlock(data,p.storageStart,p.storageSize)
        val base=active*0x40000+p.storageStart
        val boxBase=if(p.hgss) base+box*0x1000 else base+4+box*0xFF0
        return (0 until 30).map{slot->
            val o=boxBase+slot*136
            if(o+136>data.size)null else parsePk4(data.copyOfRange(o,o+136),false)
        }
    }


    private fun gen4EncodeChar(c:Char):Int? = when(c){
        in '0'..'9' -> 0x121 + (c.code-'0'.code)
        in 'A'..'Z' -> 0x12B + (c.code-'A'.code)
        in 'a'..'z' -> 0x145 + (c.code-'a'.code)
        ' ' -> 0x1DE
        '!' -> 0x1AC; '?' -> 0x1AD; ',' -> 0x1AE; '.' -> 0x1AF
        '/' -> 0x1B1; '\'' -> 0x1B3; '(' -> 0x1BA; ')' -> 0x1BB; '♂' -> 0x1BD; '♀' -> 0x1BE
        '+' -> 0x1BF; '-' -> 0x1C0; '*' -> 0x1C1; '=' -> 0x1C3; '&' -> 0x1C4; ':' -> 0x1C6; ';' -> 0x1C7; '@' -> 0x1D0; '%' -> 0x1D2; '_' -> 0x1E9
        else -> null
    }

    private fun writeGen4String(data:ByteArray,off:Int,byteLen:Int,text:String){
        val maxChars=(byteLen/2)-1
        if(text.length>maxChars) throw IllegalArgumentException("Text is too long for this Gen 4 field")
        for(i in 0 until byteLen step 2) writeU16LE(data,off+i,0xFFFF)
        text.forEachIndexed{i,c->
            val v=gen4EncodeChar(c) ?: throw IllegalArgumentException("Unsupported Gen 4 character: $c")
            writeU16LE(data,off+i*2,v)
        }
        if(text.length*2<byteLen) writeU16LE(data,off+text.length*2,0xFFFF)
    }

    private fun gen4Shuffle(buf:ByteArray){
        val pid=readU32LE(buf,0).toInt()
        val sv=(pid ushr 13) and 31
        if(sv==0)return
        val perm=intArrayOf(0,1,2,3)
        val slotOf=intArrayOf(0,1,2,3)
        val swaps=ArrayList<Pair<Int,Int>>()
        for(i in 0 until 3){
            val desired=gen4BlockPosition[sv*4+i]
            val j=slotOf[desired]
            if(j==i)continue
            swaps.add(Pair(i,j))
            val blockAtI=perm[i]
            perm[j]=blockAtI
            slotOf[blockAtI]=j
        }
        for(n in swaps.size-1 downTo 0){
            val (i,j)=swaps[n]
            for(k in 0 until 32){
                val a=8+i*32+k; val b=8+j*32+k
                val t=buf[a];buf[a]=buf[b];buf[b]=t
            }
        }
    }

    private fun encryptPk4(decrypted:ByteArray):ByteArray{
        if(decrypted.size!=136 && decrypted.size!=236) throw IllegalArgumentException("Invalid PK4 size")
        val out=decrypted.copyOf()
        var sum=0
        for(o in 0x08 until 0x88 step 2) sum=(sum+readU16LE(out,o)) and 0xFFFF
        writeU16LE(out,0x06,sum)
        val pid=readU32LE(out,0)
        gen4Shuffle(out)
        gen4Crypt(out,8,136,sum.toLong())
        if(out.size>136)gen4Crypt(out,136,out.size,pid)
        return out
    }

    private data class Gen4EditValues(
        val nickname:String,val ot:String,val tid:Int,val sid:Int,val exp:Long,val held:Int,val friendship:Int,
        val nature:Int,val shiny:Boolean,val moves:IntArray,val pp:IntArray,val ivs:IntArray,val evs:IntArray
    )

    private fun gen4PidForNatureShiny(old:Long,tid:Int,sid:Int,nature:Int,shiny:Boolean,abilityNumber:Int?=null):Long{
        require(abilityNumber==null||abilityNumber in 1..2){"The requested Generation 4 ability slot is invalid."}
        val oldLo=old.toInt() and 0xFFFF
        val oldParity=abilityNumber?.minus(1)?: (old.toInt() and 1)
        if(shiny){
            for(delta in 0..65535){
                val lo=(oldLo+delta) and 0xFFFF
                if((lo and 1)!=oldParity) continue
                for(sv in 0..7){
                    val hi=(tid xor sid xor lo xor sv) and 0xFFFF
                    val pid=((hi.toLong() shl 16) or lo.toLong()) and 0xFFFFFFFFL
                    if((pid%25L).toInt()==nature)return pid
                }
            }
        }else{
            var pid=old and 0xFFFFFFFFL
            for(i in 0..250000){
                if((pid%25L).toInt()==nature && ((pid.toInt() and 1)==oldParity)){
                    val sv=tid xor sid xor (pid.toInt() and 0xFFFF) xor ((pid.toInt() ushr 16) and 0xFFFF)
                    if(sv>=8)return pid
                }
                pid=(pid+1) and 0xFFFFFFFFL
            }
        }
        throw IllegalStateException("Could not generate a Gen 4 PID for the requested nature/shiny state")
    }

    private fun mutatePk4(raw:ByteArray,v:Gen4EditValues):ByteArray{
        if(raw.size!=136)throw IllegalArgumentException("Boxed PK4 must be 136 bytes")
        val d=decryptPk4(raw) ?: throw IllegalStateException("Could not decrypt PK4")
        val oldPid=readU32LE(d,0)
        val newPid=gen4PidForNatureShiny(oldPid,v.tid,v.sid,v.nature,v.shiny)
        writeU32LE(d,0,newPid)
        writeU16LE(d,0x0A,v.held);writeU16LE(d,0x0C,v.tid);writeU16LE(d,0x0E,v.sid);writeU32LE(d,0x10,v.exp)
        d[0x14]=v.friendship.toByte()
        for(i in 0..5)d[0x18+i]=v.evs[i].toByte()
        for(i in 0..3){writeU16LE(d,0x28+i*2,v.moves[i]);d[0x30+i]=v.pp[i].toByte()}
        var ivw=readU32LE(d,0x38) and 0xC0000000L
        for(i in 0..5)ivw=ivw or ((v.ivs[i].toLong() and 31L) shl (i*5))
        writeU32LE(d,0x38,ivw)
        writeGen4String(d,0x48,22,v.nickname)
        writeGen4String(d,0x68,16,v.ot)
        return encryptPk4(d)
    }

    private fun gen4BoxSlotOffset(data:ByteArray,p:Gen4Profile,global:Int):Int{
        require(global in 0 until 18*30){"Invalid Gen 4 PC slot"}
        val box=global/30;val slot=global%30
        val active=gen4ActiveBlock(data,p.storageStart,p.storageSize)
        val base=active*0x40000+p.storageStart
        val boxBase=if(p.hgss) base+box*0x1000 else base+4+box*0xFF0
        return boxBase+slot*136
    }

    private fun updateGen4BlockChecksum(save:ByteArray,start:Int,length:Int,p:Gen4Profile){
        val footer=if(p.hgss)0x10 else 0x14
        if(start<0 || start+length>save.size)throw IllegalArgumentException("Invalid Gen 4 block")
        val crc=gen4Crc16Ccitt(save,start,start+length-footer)
        writeU16LE(save,start+length-2,crc)
    }

    private fun showGen4PokemonEditor(location:String,pokemon:PokemonEntry){
        val global=boxedLocationToGlobalIndex(location) ?: return showDialog("Edit Pokémon","Gen 4 editing is currently enabled for boxed Pokémon only.")
        if(global !in 0 until 18*30)return showDialog("Edit Pokémon","That is not a Gen 4 PC slot.")
        phoneBackAction={showPokemonDetails(location,pokemon)}
        val scroll=ScrollView(this).apply{setBackgroundColor(BG)}
        val root=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(dp(16),dp(58),dp(16),dp(28));setBackgroundColor(BG)};scroll.addView(root)
        root.addView(TextView(this).apply{text="Edit ${pokemon.nickname.ifBlank{"Species #${pokemon.species}"}}";textSize=27f;typeface=Typeface.DEFAULT_BOLD;setTextColor(TEXT)})
        addMutedLine(root,"$location • Gen 4 boxed PK4 editor")
        addButton(root,"←  Cancel"){showPokemonDetails(location,pokemon)}
        val nick=inputField("Nickname (max 10)",pokemon.nickname).also{root.addView(it.first)}.second
        val ot=inputField("OT name (max 7)",pokemon.otName).also{root.addView(it.first)}.second
        val tid=inputField("TID (0–65535)",pokemon.tid.toString(),true).also{root.addView(it.first)}.second
        val sid=inputField("SID (0–65535)",pokemon.sid.toString(),true).also{root.addView(it.first)}.second
        val exp=inputField("Experience",pokemon.experience.toString(),true).also{root.addView(it.first)}.second
        val held=inputField("Held item ID",pokemon.heldItem.toString(),true).also{root.addView(it.first)}.second
        val friendship=inputField("Friendship (0–255)",pokemon.friendship.toString(),true).also{root.addView(it.first)}.second
        val natureNames=listOf("Hardy","Lonely","Brave","Adamant","Naughty","Bold","Docile","Relaxed","Impish","Lax","Timid","Hasty","Serious","Jolly","Naive","Modest","Mild","Quiet","Bashful","Rash","Calm","Gentle","Sassy","Careful","Quirky")
        val nature=spinnerField("Nature",natureNames,pokemon.nature.coerceIn(0,24)).also{root.addView(it.first)}.second
        val shiny=CheckBox(this).apply{text="Shiny";isChecked=pokemon.shiny;textSize=16f;setTextColor(TEXT)};root.addView(shiny)
        addSectionTitle(root,"MOVES / PP")
        val moveIds=pokemon.moves.copyOf();val ppF=ArrayList<EditText>()
        for(i in 0..3){
            val selector=selectorButton("Move ${i+1}",if(moveIds[i]==0)"None" else "Move #${moveIds[i]}").also{root.addView(it.first)}.second
            if(moveIds[i]!=0){val oldMove=moveIds[i];resolvePokeApiNameAsync("move",oldMove){n->if(n!=null&&moveIds[i]==oldMove)selector.text="$n (#$oldMove)"}}
            val pp=inputField("Move ${i+1} PP (0–63)",pokemon.movePP[i].toString(),true).also{root.addView(it.first)}.second;ppF.add(pp)
            selector.setOnClickListener{
                openCatalogPicker("move","Choose Gen 4 Move ${i+1}",false){chosen->
                    if(chosen.id !in 0..467)showDialog("Gen 4 move","${chosen.name} (#${chosen.id}) did not exist in Generation 4.")
                    else{moveIds[i]=chosen.id;selector.text=chosen.toString();if(chosen.id==0)pp.setText("0") else resolveMovePpAsync(chosen.id){base->if(base!=null)pp.setText(base.coerceAtMost(63).toString())}}
                }
            }
        }
        val labels=arrayOf("HP","Attack","Defense","Speed","Sp. Atk","Sp. Def")
        addSectionTitle(root,"IVs");val ivF=ArrayList<EditText>();for(i in 0..5)ivF.add(inputField("${labels[i]} IV (0–31)",pokemon.ivs[i].toString(),true).also{root.addView(it.first)}.second)
        addSectionTitle(root,"EVs");val evF=ArrayList<EditText>();for(i in 0..5)evF.add(inputField("${labels[i]} EV (0–255)",pokemon.evs[i].toString(),true).also{root.addView(it.first)}.second)
        addButton(root,"💾  Save Changes") save@{
            val v=try{Gen4EditValues(nick.text.toString().trim(),ot.text.toString().trim(),tid.text.toString().toInt(),sid.text.toString().toInt(),exp.text.toString().toLong(),held.text.toString().toInt(),friendship.text.toString().toInt(),nature.selectedItemPosition,shiny.isChecked,moveIds.copyOf(),IntArray(4){ppF[it].text.toString().toInt()},IntArray(6){ivF[it].text.toString().toInt()},IntArray(6){evF[it].text.toString().toInt()})}catch(_:Exception){showDialog("Invalid values","One or more fields are not valid numbers.");return@save}
            val unsupported=(v.nickname+v.ot).firstOrNull{gen4EncodeChar(it)==null}
            val err=when{v.nickname.length>10->"Nickname must be 10 characters or fewer.";v.ot.length>7->"OT name must be 7 characters or fewer.";unsupported!=null->"Character '$unsupported' is not supported by the Gen 4 text writer yet.";v.tid !in 0..65535||v.sid !in 0..65535->"TID/SID must be 0–65535.";v.exp !in 0..0xFFFFFFFFL->"Experience value is invalid.";v.held !in 0..65535->"Held item ID is invalid.";v.friendship !in 0..255->"Friendship must be 0–255.";v.moves.any{it !in 0..467}->"Gen 4 move IDs must be 0–467.";v.pp.any{it !in 0..63}->"PP must be 0–63.";v.ivs.any{it !in 0..31}->"IVs must be 0–31.";v.evs.any{it !in 0..255}->"EVs must be 0–255.";else->null}
            if(err!=null){showDialog("Invalid values",err);return@save}
            AlertDialog.Builder(this).setTitle("Save Gen 4 Pokémon changes?").setMessage("PSE will rebuild the encrypted PK4, update the active Gen 4 storage-block CRC, re-read the edited slot and validate the save. If verification fails, the original working copy is restored automatically.").setNegativeButton("Cancel",null).setPositiveButton("Save"){_,_->applyGen4PokemonEdit(location,pokemon,v)}.show()
        }
        addMutedLine(root,"Changes affect only PSE's working copy until Save & Replace. Boxed Gen 4 edits use PK4 checksum verification, storage-block CRC rebuild and automatic rollback.")
        setContentView(scroll)
    }

    private fun applyGen4PokemonEdit(location:String,old:PokemonEntry,v:Gen4EditValues){
        val global=boxedLocationToGlobalIndex(location) ?: return showDialog("Edit failed","Gen 4 boxed slot could not be resolved.")
        val file=importedFile?:return
        val original=try{file.readBytes()}catch(e:Exception){showDialog("Edit failed",e.message?:"Could not read save");return}
        val save=original.copyOf()
        try{
            val profile=detectGen4Profile(save) ?: throw IllegalStateException("Could not detect Gen 4 save layout")
            if(global !in 0 until 18*30)throw IllegalStateException("Invalid Gen 4 PC slot")
            val validationBefore=gen4Validation(save,profile)
            if(!validationBefore.generalChecksum || !validationBefore.storageChecksum || validationBefore.badPk4!=0)throw IllegalStateException("Gen 4 save did not pass pre-edit validation")
            val off=gen4BoxSlotOffset(save,profile,global)
            val current=parsePk4(save.copyOfRange(off,off+136),false) ?: throw IllegalStateException("Pokémon is no longer in that box slot")
            if(current.pid!=old.pid || current.species!=old.species)throw IllegalStateException("The box slot changed since the editor was opened")
            if(!current.checksumValid)throw IllegalStateException("Source PK4 checksum is invalid")
            val changed=mutatePk4(save.copyOfRange(off,off+136),v)
            changed.copyInto(save,off)
            val activeStorage=gen4ActiveBlock(save,profile.storageStart,profile.storageSize)
            val storageStart=activeStorage*0x40000+profile.storageStart
            updateGen4BlockChecksum(save,storageStart,profile.storageSize,profile)
            val staged=parsePk4(save.copyOfRange(off,off+136),false) ?: throw IllegalStateException("Edited PK4 could not be re-read")
            if(!staged.checksumValid || staged.species!=old.species || staged.nickname!=v.nickname || staged.otName!=v.ot || staged.tid!=v.tid || staged.sid!=v.sid || staged.experience!=v.exp || staged.heldItem!=v.held || staged.friendship!=v.friendship || staged.nature!=v.nature || staged.shiny!=v.shiny || !staged.moves.contentEquals(v.moves) || !staged.movePP.contentEquals(v.pp) || !staged.ivs.contentEquals(v.ivs) || !staged.evs.contentEquals(v.evs))throw IllegalStateException("Edited PK4 did not verify")
            val validationAfter=gen4Validation(save,profile)
            if(!validationAfter.generalChecksum || !validationAfter.storageChecksum || validationAfter.badPk4!=0)throw IllegalStateException("Gen 4 block/checksum verification failed")
            file.writeBytes(save)
            val verify=file.readBytes();val verifyProfile=detectGen4Profile(verify) ?: throw IllegalStateException("Written save layout could not be re-read")
            val finalValidation=gen4Validation(verify,verifyProfile)
            if(!finalValidation.generalChecksum || !finalValidation.storageChecksum || finalValidation.badPk4!=0)throw IllegalStateException("Written Gen 4 save failed verification")
            val finalOff=gen4BoxSlotOffset(verify,verifyProfile,global)
            val q=parsePk4(verify.copyOfRange(finalOff,finalOff+136),false) ?: throw IllegalStateException("Written PK4 could not be re-read")
            if(!q.checksumValid || q.pid!=staged.pid || q.species!=staged.species)throw IllegalStateException("Written PK4 changed during verification")
            Toast.makeText(this,"Gen 4 Pokémon updated and verified",Toast.LENGTH_LONG).show()
            showPokemonDetails(location,q)
        }catch(e:Exception){
            runCatching{file.writeBytes(original)}
            showDialog("Edit failed","${e.message?:"Unknown error"}. The original working copy was restored.")
        }
    }


    private fun gen4EmptyBoxSlots(data:ByteArray,p:Gen4Profile):List<Int>{
        val out=ArrayList<Int>()
        for(global in 0 until 18*30){
            val off=gen4BoxSlotOffset(data,p,global)
            val raw=data.copyOfRange(off,off+136)
            if(raw.all{it==0.toByte()} || parsePk4(raw,false)==null) out.add(global)
        }
        return out
    }

    private fun chooseGen4DuplicateDestination(location:String,pokemon:PokemonEntry){
        val source=boxedLocationToGlobalIndex(location) ?: return showDialog("Duplicate Pokémon","Gen 4 Duplicate is currently enabled for boxed Pokémon only.")
        val file=importedFile?:return
        val data=runCatching{file.readBytes()}.getOrNull() ?: return showDialog("Duplicate Pokémon","Could not read the working copy.")
        val profile=detectGen4Profile(data) ?: return showDialog("Duplicate Pokémon","Could not detect the Gen 4 save layout.")
        val v=gen4Validation(data,profile)
        if(!v.generalChecksum || !v.storageChecksum || v.badPk4!=0) return showDialog("Duplicate Pokémon","This Gen 4 save did not pass validation, so no write was attempted.")
        val targets=gen4EmptyBoxSlots(data,profile)
        if(targets.isEmpty()) return showDialog("Duplicate Pokémon","No empty Gen 4 PC slot was found.")
        AlertDialog.Builder(this).setTitle("Duplicate ${pokemon.nickname.ifBlank{"Species #${pokemon.species}"}}")
            .setItems(arrayOf("First empty slot","Choose box / slot")){_,which->
                if(which==0) duplicateGen4Pokemon(source,targets.first(),pokemon)
                else showGen4DuplicateBoxPicker(source,pokemon,data,profile)
            }.setNegativeButton("Cancel",null).show()
    }

    private fun showGen4DuplicateBoxPicker(source:Int,pokemon:PokemonEntry,data:ByteArray,profile:Gen4Profile){
        val boxes=(0 until 18).filter{box->(0 until 30).any{slot->
            val g=box*30+slot; val off=gen4BoxSlotOffset(data,profile,g); val raw=data.copyOfRange(off,off+136)
            raw.all{it==0.toByte()} || parsePk4(raw,false)==null
        }}
        if(boxes.isEmpty()) return showDialog("Duplicate Pokémon","No empty Gen 4 PC slot was found.")
        AlertDialog.Builder(this).setTitle("Choose destination box").setItems(boxes.map{"Box ${it+1}"}.toTypedArray()){_,bi->
            val box=boxes[bi]
            val empties=(0 until 30).filter{slot->
                val g=box*30+slot; val off=gen4BoxSlotOffset(data,profile,g); val raw=data.copyOfRange(off,off+136)
                raw.all{it==0.toByte()} || parsePk4(raw,false)==null
            }
            AlertDialog.Builder(this).setTitle("Box ${box+1} • choose empty slot").setItems(empties.map{"Slot ${it+1}"}.toTypedArray()){_,si->
                duplicateGen4Pokemon(source,box*30+empties[si],pokemon)
            }.setNegativeButton("Cancel",null).show()
        }.setNegativeButton("Cancel",null).show()
    }

    private fun duplicateGen4Pokemon(source:Int,target:Int,expected:PokemonEntry){
        val file=importedFile?:return
        val original=try{file.readBytes()}catch(e:Exception){showDialog("Duplicate Pokémon",e.message?:"Could not read save");return}
        try{
            require(source in 0 until 540 && target in 0 until 540 && source!=target){"Invalid Gen 4 PC slot"}
            val save=original.copyOf()
            val profile=detectGen4Profile(save) ?: throw IllegalStateException("Could not detect Gen 4 save layout")
            val before=gen4Validation(save,profile)
            if(!before.generalChecksum || !before.storageChecksum || before.badPk4!=0) throw IllegalStateException("Gen 4 save did not pass pre-duplicate validation")
            val srcOff=gen4BoxSlotOffset(save,profile,source); val dstOff=gen4BoxSlotOffset(save,profile,target)
            val srcRaw=save.copyOfRange(srcOff,srcOff+136)
            val src=parsePk4(srcRaw,false) ?: throw IllegalStateException("Source Pokémon is no longer present")
            if(!src.checksumValid || src.pid!=expected.pid || src.species!=expected.species) throw IllegalStateException("Source PK4 changed or failed checksum validation")
            val dstRaw=save.copyOfRange(dstOff,dstOff+136)
            if(!(dstRaw.all{it==0.toByte()} || parsePk4(dstRaw,false)==null)) throw IllegalStateException("Destination slot is no longer empty")
            srcRaw.copyInto(save,dstOff)
            val activeStorage=gen4ActiveBlock(save,profile.storageStart,profile.storageSize)
            updateGen4BlockChecksum(save,activeStorage*0x40000+profile.storageStart,profile.storageSize,profile)
            val stagedRaw=save.copyOfRange(dstOff,dstOff+136); val staged=parsePk4(stagedRaw,false) ?: throw IllegalStateException("Duplicated PK4 could not be re-read")
            if(!staged.checksumValid || !stagedRaw.contentEquals(srcRaw) || staged.pid!=src.pid || staged.species!=src.species) throw IllegalStateException("Duplicated PK4 did not verify")
            val after=gen4Validation(save,profile)
            if(!after.generalChecksum || !after.storageChecksum || after.badPk4!=0) throw IllegalStateException("Gen 4 checksum verification failed")
            file.writeBytes(save)
            val verify=file.readBytes(); val vp=detectGen4Profile(verify) ?: throw IllegalStateException("Written save layout could not be re-read")
            val vv=gen4Validation(verify,vp)
            if(!vv.generalChecksum || !vv.storageChecksum || vv.badPk4!=0) throw IllegalStateException("Written Gen 4 save failed verification")
            val vo=gen4BoxSlotOffset(verify,vp,target); val vr=verify.copyOfRange(vo,vo+136); val mon=parsePk4(vr,false) ?: throw IllegalStateException("Written duplicate could not be re-read")
            if(!vr.contentEquals(srcRaw) || !mon.checksumValid || mon.pid!=src.pid || mon.species!=src.species) throw IllegalStateException("Written duplicate changed during verification")
            Toast.makeText(this,"Gen 4 Pokémon duplicated and verified",Toast.LENGTH_LONG).show()
            showPokemonDetails("Box ${target/30+1} • Slot ${target%30+1}",mon)
        }catch(e:Exception){
            runCatching{file.writeBytes(original)}
            showDialog("Duplicate failed","${e.message?:"Unknown error"}. The original working copy was restored.")
        }
    }

