    private fun deleteGen4Pokemon(global:Int,expected:PokemonEntry){
        val file=importedFile?:return
        val original=try{file.readBytes()}catch(e:Exception){showDialog("Delete Pokémon",e.message?:"Could not read save");return}
        try{
            require(global in 0 until 540){"Invalid Gen 4 PC slot"}
            val save=original.copyOf(); val profile=detectGen4Profile(save) ?: throw IllegalStateException("Could not detect Gen 4 save layout")
            val before=gen4Validation(save,profile)
            if(!before.generalChecksum || !before.storageChecksum || before.badPk4!=0) throw IllegalStateException("Gen 4 save did not pass pre-delete validation")
            val off=gen4BoxSlotOffset(save,profile,global); val raw=save.copyOfRange(off,off+136); val current=parsePk4(raw,false) ?: throw IllegalStateException("Pokémon is no longer present")
            if(!current.checksumValid || current.pid!=expected.pid || current.species!=expected.species) throw IllegalStateException("Source PK4 changed or failed checksum validation")
            ByteArray(136).copyInto(save,off)
            val activeStorage=gen4ActiveBlock(save,profile.storageStart,profile.storageSize)
            updateGen4BlockChecksum(save,activeStorage*0x40000+profile.storageStart,profile.storageSize,profile)
            val staged=save.copyOfRange(off,off+136)
            if(!staged.all{it==0.toByte()} || parsePk4(staged,false)!=null) throw IllegalStateException("Deleted slot was not empty after staging")
            val after=gen4Validation(save,profile)
            if(!after.generalChecksum || !after.storageChecksum || after.badPk4!=0) throw IllegalStateException("Gen 4 checksum verification failed")
            file.writeBytes(save)
            val verify=file.readBytes(); val vp=detectGen4Profile(verify) ?: throw IllegalStateException("Written save layout could not be re-read")
            val vv=gen4Validation(verify,vp)
            if(!vv.generalChecksum || !vv.storageChecksum || vv.badPk4!=0) throw IllegalStateException("Written Gen 4 save failed verification")
            val vo=gen4BoxSlotOffset(verify,vp,global); val vr=verify.copyOfRange(vo,vo+136)
            if(!vr.all{it==0.toByte()} || parsePk4(vr,false)!=null) throw IllegalStateException("Deleted slot was not empty after re-read")
            Toast.makeText(this,"Gen 4 Pokémon deleted and verified",Toast.LENGTH_LONG).show()
            showGen4PokemonViewer("boxes",global/30)
        }catch(e:Exception){
            runCatching{file.writeBytes(original)}
            showDialog("Delete failed","${e.message?:"Unknown error"}. The original working copy was restored.")
        }
    }

