    private fun depositGen4ToBank(global:Int,expected:PokemonEntry){
        val file=importedFile?:return
        val original=try{file.readBytes()}catch(e:Exception){showDialog("PSE Bank",e.message?:"Could not read save");return}
        var bankFile:File?=null;var backup:File?=null
        try{
            require(global in 0 until 540){"Invalid Gen 4 PC slot"}
            val save=original.copyOf(); val profile=detectGen4Profile(save) ?: throw IllegalStateException("Could not detect Gen 4 save layout")
            val before=gen4Validation(save,profile)
            if(!before.generalChecksum || !before.storageChecksum || before.badPk4!=0) throw IllegalStateException("Gen 4 save did not pass pre-deposit validation")
            val off=gen4BoxSlotOffset(save,profile,global); val raw=save.copyOfRange(off,off+136)
            val source=parsePk4(raw,false) ?: throw IllegalStateException("Pokémon is no longer present")
            if(!source.checksumValid || source.pid!=expected.pid || source.species!=expected.species) throw IllegalStateException("Source PK4 changed or failed checksum validation")
            val created=File(bankDir(),"${System.currentTimeMillis()}_${source.species}.pk4"); bankFile=created; created.writeBytes(raw)
            val bankRaw=created.readBytes(); val bankMon=if(bankRaw.size==136)parsePk4(bankRaw,false)else null
            if(!bankRaw.contentEquals(raw) || bankMon==null || !bankMon.checksumValid || bankMon.pid!=source.pid || bankMon.species!=source.species) throw IllegalStateException("Gen 4 Bank entry verification failed")
            ByteArray(136).copyInto(save,off)
            val activeStorage=gen4ActiveBlock(save,profile.storageStart,profile.storageSize)
            updateGen4BlockChecksum(save,activeStorage*0x40000+profile.storageStart,profile.storageSize,profile)
            val after=gen4Validation(save,profile)
            if(!after.generalChecksum || !after.storageChecksum || after.badPk4!=0) throw IllegalStateException("Gen 4 checksum verification failed")
            val recovery=File.createTempFile(backupGameName(file)+"_PreGen4BankDeposit_",".backup",backupsDir());backup=recovery
            recovery.writeBytes(original);require(recovery.readBytes().contentEquals(original)){"The Gen 4 recovery backup did not verify."}
            file.writeBytes(save)
            val verify=file.readBytes(); val vp=detectGen4Profile(verify) ?: throw IllegalStateException("Written save layout could not be re-read")
            val vv=gen4Validation(verify,vp); if(!vv.generalChecksum || !vv.storageChecksum || vv.badPk4!=0) throw IllegalStateException("Written Gen 4 save failed verification")
            val vo=gen4BoxSlotOffset(verify,vp,global); val vr=verify.copyOfRange(vo,vo+136)
            if(!vr.all{it==0.toByte()} || parsePk4(vr,false)!=null) throw IllegalStateException("Source slot was not empty after re-read")
            if(!created.readBytes().contentEquals(raw)) throw IllegalStateException("Bank copy changed during the transaction")
            Toast.makeText(this,"Moved to Gen 4 PSE Bank and verified",Toast.LENGTH_LONG).show(); bankViewGeneration=4
            val count=bankDir().listFiles()?.count{it.isFile&&it.extension.equals("pk4",true)}?:1; bankViewBox=(count-1).coerceAtLeast(0)/30; showBank()
        }catch(e:Exception){runCatching{file.writeBytes(original)};runCatching{bankFile?.delete()};showDialog("Gen 4 Bank move failed","${e.message?:"Unknown error"}. The original working copy was restored and no new Bank entry was kept."+(backup?.let{"\n\nRecovery backup: ${it.name}"}?:""))}
    }

    private fun showGen4BankEntry(bankFile:File,p:PokemonEntry){
        val currentGen=importedFile?.let{generationForSize(it.length().toInt())}?:0
        val b=AlertDialog.Builder(this).setTitle("${p.nickname.ifBlank{"Pokémon #${p.species}"}} • Gen 4 Bank")
            .setMessage(when(currentGen){
                3 -> "Original 136-byte PK4 preserved. Review a PSE conversion back into the loaded Gen 3 save. This is not an official reverse migration."
                4 -> "Original 136-byte PK4 preserved. Withdraw it into an empty Gen 4 PC slot."
                5 -> "Original 136-byte PK4 preserved. Review a PSE conversion into the loaded native Gen 5 save."
                6 -> "Original 136-byte PK4 preserved. Review a direct PSE conversion into a chosen native Gen 6 slot, including the exact PID, ability and format changes."
                7 -> "Original 136-byte PK4 preserved. Review the exact PID, ability, markings and native field changes before writing a verified PK7 with retained recovery."
                else -> "Original 136-byte PK4 preserved. Load Gen 3 for a reviewed reverse PSE conversion, Gen 4 to withdraw it, or Gen 5, Gen 6 or Gen 7 for a reviewed forward conversion."
            })
            .setNegativeButton("Close",null)
            .setNeutralButton("Delete"){_,_->AlertDialog.Builder(this).setTitle("Delete Bank entry?").setMessage("This permanently removes the preserved Gen 4 PK4 copy.").setNegativeButton("Cancel",null).setPositiveButton("Delete"){_,_->if(bankFile.delete()){Toast.makeText(this,"Bank entry deleted",Toast.LENGTH_SHORT).show();showBank()}else showDialog("PSE Bank","The Bank entry could not be deleted.")}.show()}
        if(currentGen==3)b.setPositiveButton("PSE Convert to Gen 3"){_,_->prepareGen4ToGen3Transfer(bankFile,p)}
        if(currentGen==4)b.setPositiveButton("Withdraw to Gen 4"){_,_->chooseGen4BankWithdrawDestination(bankFile,p)}
        if(currentGen==5)b.setPositiveButton("Transfer to Gen 5"){_,_->prepareGen4ToGen5Transfer(bankFile,p)}
        if(currentGen==6)b.setPositiveButton("Transfer to Gen 6"){_,_->prepareGen4ToGen6Transfer(bankFile,p)}
        if(currentGen==7)b.setPositiveButton("Transfer to Gen 7"){_,_->prepareGen4ForwardTransfer(bankFile,p)}
        b.show()
    }

    private fun prepareGen4ToGen6Transfer(bankFile:File,shown:PokemonEntry){
        val file=importedFile?:return showDialog("Gen 4 → Gen 6","Load a valid Generation 6 destination save first.")
        val openedUri=currentSourceUri;val openedLabel=currentSourceLabel
        fun bound()=importedFile?.absolutePath==file.absolutePath&&currentSourceUri==openedUri&&currentSourceLabel==openedLabel
        val root=runCatching{bankDir().canonicalFile}.getOrNull()
            ?:return showDialog("Gen 4 → Gen 6","The PSE Bank path could not be verified.")
        val selected=runCatching{bankFile.canonicalFile}.getOrNull()
            ?:return showDialog("Gen 4 → Gen 6","The selected Bank path could not be verified.")
        if(selected.parentFile!=root||!selected.isFile||!selected.extension.equals("pk4",true))
            return showDialog("Gen 4 → Gen 6","The selected record is outside the Generation 4 PSE Bank.")
        val bank=runCatching{selected.readBytes()}.getOrNull()
            ?:return showDialog("Gen 4 → Gen 6","The selected Bank record could not be read.")
        val source=if(bank.size==136)parsePk4(bank,false)else null
        if(source==null||!source.checksumValid||source.pid!=shown.pid||source.species!=shown.species||
            source.tid!=shown.tid||source.sid!=shown.sid)
            return showDialog("Gen 4 → Gen 6","The selected Bank record changed or failed its PK4 checksum.")
        gen4ToGen5PreflightRejection(source)?.let{
            return showDialog("Gen 4 → Gen 6 blocked","$it\n\nThe Bank record and destination were left unchanged.")
        }
        if(source.moves.indices.any{source.moves[it]==0&&source.movePP[it]!=0})
            return showDialog("Gen 4 → Gen 6 blocked","An empty move slot contains PP data that cannot be preserved.\n\nNothing was changed.")
        val sourceUps=gen4Pk4PpUps(bank)
        if(sourceUps.any{it !in 0..3}||(0..3).any{source.moves[it]==0&&sourceUps[it]!=0})
            return showDialog("Gen 4 → Gen 6 blocked","The PK4 contains PP-Up data that cannot be preserved exactly.\n\nNothing was changed.")
        val destination=runCatching{file.readBytes()}.getOrNull()
            ?:return showDialog("Gen 4 → Gen 6","The destination save could not be read.")
        if((destination.size!=SIZE_G6_XY&&destination.size!=SIZE_G6_ORAS)||!bound()||
            !gen6BoxChecksumValid(destination)||!gen6BlockChecksumValid(destination,20))
            return showDialog("Gen 4 → Gen 6","Load a checksum-clean Pokémon X, Y, Omega Ruby or Alpha Sapphire save first.")
        val trainer=analyzeSave(file).trainer
            ?:return showDialog("Gen 4 → Gen 6","PSE could not read the destination trainer identity.")
        fun snapshotsMatch()=bound()&&runCatching{
            file.readBytes().contentEquals(destination)&&selected.readBytes().contentEquals(bank)
        }.getOrDefault(false)
        val loading=AlertDialog.Builder(this).setTitle("Prepare Gen 4 → Gen 6")
            .setMessage("Resolving the exact Generation 5 ability mapping and preparing a verified native PK6…")
            .setCancelable(false).create();loading.show()
        loadGen3ToGen4MetaAsync(source,5,4){meta,reason->
            if(loading.isShowing)loading.dismiss()
            if(!snapshotsMatch())return@loadGen3ToGen4MetaAsync showDialog(
                "Gen 4 → Gen 6","The destination or Bank record changed during preparation. Nothing was changed.")
            if(meta==null)return@loadGen3ToGen4MetaAsync showDialog(
                "Gen 4 → Gen 6 blocked",(reason?:"Generation 5 ability data could not be verified.")+"\n\nNothing was changed.")
            val pk5=try{buildGen4ToGen5Pk5(bank,source,destination,meta,false)}catch(e:Exception){
                return@loadGen3ToGen4MetaAsync showDialog(
                    "Gen 4 → Gen 6 blocked",(e.message?:"The PK5 conversion bridge could not be prepared.")+"\n\nNothing was changed.")
            }
            val bridge=parsePk5(pk5,false)
                ?:return@loadGen3ToGen4MetaAsync showDialog("Gen 4 → Gen 6","The PK5 conversion bridge could not be reopened.")
            if(!gen5Pk5PpUps(pk5).contentEquals(sourceUps))
                return@loadGen3ToGen4MetaAsync showDialog("Gen 4 → Gen 6 blocked","The PK5 bridge did not preserve every PP-Up value. Nothing was changed.")
            val pk6=try{buildGen5ToGen6Pk6(pk5,bridge,destination,trainer)}catch(e:Exception){
                return@loadGen3ToGen4MetaAsync showDialog(
                    "Gen 4 → Gen 6 blocked",(e.message?:"No safe native PK6 mapping is available.")+"\n\nNothing was changed.")
            }
            val converted=parsePk6(pk6,0,PK6_STORED_SIZE,false,721)
                ?:return@loadGen3ToGen4MetaAsync showDialog("Gen 4 → Gen 6","The prepared PK6 could not be reopened.")
            if(!snapshotsMatch())return@loadGen3ToGen4MetaAsync showDialog(
                "Gen 4 → Gen 6","The destination or Bank record changed after conversion preparation. Nothing was changed.")
            val prepared=Gen5Gen6Prepared(
                sourceGeneration=4,bankFile=selected,bankBytes=bank,source=source,
                destination=destination,trainer=trainer,pk6=pk6,converted=converted,
                destinationFile=file,sourceUri=openedUri,sourceLabel=openedLabel,gen4Meta=meta
            )
            val oldPid="%08X".format(source.pid);val newPid="%08X".format(converted.pid)
            val pidNote=if(source.pid==converted.pid)"PID remains $oldPid." else
                "PID changes $oldPid → $newPid only as required to preserve the verified ability slot, nature, gender and shiny state across the native Gen 5 and Gen 6 formats."
            val oldMet=if(source.metLocation==0)"none" else "#${source.metLocation}"
            val oldEgg=if(source.eggLocation==0)"none" else "#${source.eggLocation}"
            val preview=buildString{
                append("PSE Bank conversion preview\n\n")
                append("Preserved: species/form, TID/SID, nickname and OT, EXP, verified ability, nature, gender, shiny state, moves, current PP, PP Ups, IVs, EVs, friendship, Pokérus, Ball, language, source title, met level/date and fateful marker.\n")
                append("$pidNote\n")
                append("Ability: source ability #${source.ability} in slot ${source.abilityNumber} remains verified ability #${meta.abilityId}.\n")
                append("Required format changes: Gen 4 met location $oldMet becomes native Gen 6 transfer marker 30001; Egg location $oldEgg becomes 0 because the location catalog is not interchangeable. Current handler becomes ${trainer.trainerName}; relearn moves and geographic fields start empty.\n\n")
                append("Held items, Eggs and unsupported source values are blocked instead of discarded. This is a PSE conversion, not an in-game trade or a claim of official transfer provenance. The source save stays unchanged. The exact Gen 4 Bank record remains until a retained recovery backup, chosen PK6 slot, Pokédex update, checksums and reopened destination all verify.")
            }
            AlertDialog.Builder(this).setTitle("${source.nickname.ifBlank{meta.speciesName}} • Gen 4 → Gen 6")
                .setMessage(preview).setNegativeButton("Cancel",null)
                .setPositiveButton("Choose Gen 6 destination"){_,_->
                    if(!snapshotsMatch())showDialog("Gen 4 → Gen 6","The destination or Bank record changed after review. Nothing was changed.")
                    else chooseGen5ToGen6Destination(prepared)
                }.show()
        }
    }

    private data class Gen4ToGen3Plan(val meta:Gen3ToGen4Meta,val originGame:Int,val originLegalised:Boolean=false,val metLocation:Int=0)
    private data class Gen4Gen3Prepared(
        val bankFile:File,val bankBytes:ByteArray,val source:PokemonEntry,val destination:ByteArray,
        val plan:Gen4ToGen3Plan,val pk3:ByteArray,val converted:PokemonEntry,val destinationFile:File,
        val sourceUri:Uri?,val sourceLabel:String?
    )

    private fun gen3TextSupported(text:String):Boolean=text.all{c->
        c in 'A'..'Z'||c in 'a'..'z'||c in '0'..'9'||c in charArrayOf(' ','!','?','.',',','/','-','\'','♂','♀')
    }

    private fun gen4ToGen3PreflightRejection(p:PokemonEntry,allowOriginLegalise:Boolean=false):String?=when{
        !p.checksumValid->"The source PK4 checksum is invalid."
        p.species !in 1..386->"Species #${p.species} did not exist in Generation 3."
        p.species==386->"Deoxys form is title-dependent in Generation 3. PSE will not guess a destination form."
        p.form!=0->"Form ${p.form} has no verified native PK3 representation."
        p.isEgg->"Egg state has no verified reverse PK4 to PK3 mapping."
        p.heldItem!=0->"Held item #${p.heldItem} cannot be mapped safely because Gen 3 and Gen 4 item IDs are not interchangeable."
        p.moves.any{it !in 0..354}->"A move is outside the Generation 3 move catalogue."
        p.language!=2->"Language ID ${p.language} cannot be verified by the current native PK3 text writer."
        p.nickname.length>10||!gen3TextSupported(p.nickname)->"The nickname cannot be represented exactly in native Gen 3 text."
        p.otName.length>7||!gen3TextSupported(p.otName)->"The Original Trainer name cannot be represented exactly in native Gen 3 text."
        p.evs.any{it !in 0..255}||p.evs.sum()>510->"The EV data is not destination-valid for Generation 3."
        p.ivs.any{it !in 0..31}->"The IV data is invalid."
        p.ball !in 1..12->"Ball ID ${p.ball} has no verified direct Gen 4 to Gen 3 mapping."
        !allowOriginLegalise&&p.originGame !in 1..5->"Origin game ID ${p.originGame} is not a Gen 3 title. Choose an explicit Legalise origin to continue; PSE will not assign provenance silently."
        !allowOriginLegalise&&p.metLocation!=55->"Only Gen 3-origin Pal Park records (Gen 4 met location #55) have a documented reverse PSE conversion unless you explicitly Legalise the origin."
        p.eggLocation!=0->"The PK4 contains Egg location data that PK3 cannot preserve safely."
        p.fatefulEncounter->"Fateful-encounter provenance cannot be represented without changing its meaning."
        p.markingValue !in 0..15->"Gen 4 marking value ${p.markingValue} is not representable by the four native Gen 3 markings."
        p.abilityNumber !in 1..2->"The PK4 ability slot is not representable in Generation 3."
        ((p.pid.toInt() and 1)+1)!=p.abilityNumber->"The PK4 ability slot does not match PID parity."
        p.metLevel !in 1..100->"The PK4 met level is not valid for Generation 3."
        else->null
    }

    private fun buildGen4ToGen3Pk3(raw:ByteArray,p:PokemonEntry,destination:ByteArray,plan:Gen4ToGen3Plan):ByteArray{
        require(raw.size==136){"The preserved Gen 4 Bank record has an unexpected size."}
        require(generationForSize(destination.size)==3&&gen3SaveValid(destination)){"A valid Generation 3 destination save is required."}
        gen4ToGen3PreflightRejection(p,plan.originLegalised)?.let{error(it)}
        require(plan.metLocation==0){"The prepared PK3 met-location mapping is invalid."}
        require(plan.originGame in 1..5){"Choose a valid Generation 3 origin title."}
        require(plan.meta.abilityId==p.ability){"The PK4 ability does not match the verified Generation 3 ability for slot ${p.abilityNumber}."}
        require(gen3TransferGender(p,plan.meta.genderRate)==p.gender){"PID-derived gender does not match the PK4 gender field."}
        val ups=gen4Pk4PpUps(raw);require(ups.all{it in 0..3}){"PK4 PP Ups could not be verified."}
        val out=ByteArray(80);writeU32LE(out,0,p.pid);writeU16LE(out,4,p.tid);writeU16LE(out,6,p.sid)
        val defaultName=canonicalGen3SpeciesName(p.species)?:plan.meta.speciesName
        writeGen3Text(out,8,10,p.nickname.ifBlank{defaultName});out[0x12]=p.language.toByte();writeGen3Text(out,0x14,7,p.otName);out[0x1B]=p.markingValue.toByte()
        val blocks=hashMapOf<Char,ByteArray>('G' to ByteArray(12),'A' to ByteArray(12),'E' to ByteArray(12),'M' to ByteArray(12))
        val g=blocks['G']!!;val a=blocks['A']!!;val e=blocks['E']!!;val m=blocks['M']!!
        writeU16LE(g,0,p.species);writeU16LE(g,2,0);writeU32LE(g,4,p.experience)
        var ppBonuses=0;for(i in 0..3){writeU16LE(a,i*2,p.moves[i]);a[8+i]=(if(p.moves[i]==0)0 else p.movePP[i].coerceIn(0,63)).toByte();ppBonuses=ppBonuses or ((if(p.moves[i]==0)0 else ups[i]) shl (i*2))}
        g[8]=ppBonuses.toByte();g[9]=p.friendship.coerceIn(0,255).toByte();for(i in 0..5)e[i]=p.evs[i].toByte()
        m[0]=(((p.pokerusStrain and 0xF) shl 4) or (p.pokerusDays and 0xF)).toByte();m[1]=plan.metLocation.toByte()
        writeU16LE(m,2,(p.metLevel and 0x7F) or ((plan.originGame and 0xF) shl 7) or ((p.ball and 0xF) shl 11) or ((p.otGender and 1) shl 15))
        var ivWord=0L;for(i in 0..5)ivWord=ivWord or ((p.ivs[i].toLong() and 31L) shl(i*5));if(p.abilityNumber==2)ivWord=ivWord or 0x80000000L;writeU32LE(m,4,ivWord)
        val order=gen3Orders[(p.pid%24L).toInt()];val plain=ByteArray(48);for(i in 0..3)(blocks[order[i]]!!).copyInto(plain,i*12)
        var sum=0;for(i in 0 until 48 step 2)sum=(sum+readU16LE(plain,i)) and 0xFFFF;writeU16LE(out,0x1C,sum)
        val key=(p.pid xor (((p.sid.toLong() and 0xFFFFL) shl 16) or (p.tid.toLong() and 0xFFFFL))).toInt();var x=0
        while(x<48){writeU32LE(plain,x,(readU32LE(plain,x).toInt() xor key).toLong() and 0xFFFFFFFFL);x+=4};plain.copyInto(out,0x20)
        val q=parsePk3(out,0,false)?:error("The converted PK3 could not be parsed.")
        require(q.checksumValid&&q.pid==p.pid&&q.species==p.species&&q.tid==p.tid&&q.sid==p.sid&&q.nickname==p.nickname.ifBlank{defaultName}&&q.otName==p.otName&&q.experience==p.experience&&q.nature==p.nature&&q.shiny==p.shiny&&q.heldItem==0&&q.friendship==p.friendship&&q.language==p.language&&q.markingValue==p.markingValue&&q.abilityNumber==p.abilityNumber&&q.originGame==plan.originGame&&q.ball==p.ball&&q.metLevel==p.metLevel&&q.metLocation==0&&q.otGender==p.otGender&&q.moves.contentEquals(p.moves)&&q.movePP.contentEquals(IntArray(4){if(p.moves[it]==0)0 else p.movePP[it].coerceIn(0,63)})&&gen3MovePpUps(out).contentEquals(ups)&&q.evs.contentEquals(p.evs)&&q.ivs.contentEquals(p.ivs)&&q.pokerusDays==(p.pokerusDays and 0xF)&&q.pokerusStrain==(p.pokerusStrain and 0xF)){"The converted PK3 did not preserve every destination-representable field."}
        return out
    }

    private fun sameGen4ToGen3Pk3(a:PokemonEntry,b:PokemonEntry):Boolean=
        a.checksumValid&&b.checksumValid&&a.pid==b.pid&&a.species==b.species&&a.tid==b.tid&&a.sid==b.sid&&a.nickname==b.nickname&&a.otName==b.otName&&a.experience==b.experience&&a.nature==b.nature&&a.shiny==b.shiny&&a.originGame==b.originGame&&a.ball==b.ball&&a.metLevel==b.metLevel&&a.metLocation==b.metLocation&&a.language==b.language&&a.markingValue==b.markingValue&&a.abilityNumber==b.abilityNumber&&a.heldItem==b.heldItem&&a.friendship==b.friendship&&a.pokerusDays==b.pokerusDays&&a.pokerusStrain==b.pokerusStrain&&a.moves.contentEquals(b.moves)&&a.movePP.contentEquals(b.movePP)&&a.evs.contentEquals(b.evs)&&a.ivs.contentEquals(b.ivs)

    private fun prepareGen4ToGen3Transfer(bankFile:File,shown:PokemonEntry,legalisedOriginGame:Int?=null){
        val file=importedFile?:return showDialog("Gen 4 → Gen 3","Load a valid Generation 3 destination save first.");val openedUri=currentSourceUri;val openedLabel=currentSourceLabel
        fun bound()=importedFile?.absolutePath==file.absolutePath&&currentSourceUri==openedUri&&currentSourceLabel==openedLabel
        val destination=runCatching{file.readBytes()}.getOrNull()?:return showDialog("Gen 4 → Gen 3","The destination save could not be read.")
        if(!bound()||generationForSize(destination.size)!=3||!gen3SaveValid(destination))return showDialog("Gen 4 → Gen 3","The loaded destination is not a valid bound Generation 3 save.")
        val root=runCatching{bankDir().canonicalFile}.getOrNull()?:return;val selected=runCatching{bankFile.canonicalFile}.getOrNull()?:return
        if(selected.parentFile!=root||!selected.extension.equals("pk4",true))return showDialog("Gen 4 → Gen 3","The selected record is outside the Generation 4 PSE Bank.")
        val bank=runCatching{selected.readBytes()}.getOrNull()?:return showDialog("Gen 4 → Gen 3","The Bank record could not be read.")
        val source=if(bank.size==136)parsePk4(bank,false)else null
        if(source==null||source.pid!=shown.pid||source.species!=shown.species)return showDialog("Gen 4 → Gen 3","The selected Bank record changed. Nothing was changed.")
        val needsOriginLegalise=source.originGame !in 1..5||source.metLocation!=55
        if(needsOriginLegalise&&legalisedOriginGame==null){
            val games=arrayOf("Pokémon Sapphire","Pokémon Ruby","Pokémon Emerald","Pokémon FireRed","Pokémon LeafGreen")
            val ids=intArrayOf(1,2,3,4,5)
            AlertDialog.Builder(this).setTitle("Legalise Gen 4 → Gen 3 origin")
                .setMessage("This is not a documented Gen 3-origin Pal Park record. Choose a Gen 3 title to write as its origin. This changes provenance and does not verify history. The PK3 met location will be 0 (unspecified). Cancel leaves the Bank record and destination unchanged.")
                .setItems(games){_,which->prepareGen4ToGen3Transfer(bankFile,shown,ids[which])}
                .setNegativeButton("Cancel",null).show()
            return
        }
        val originGame=legalisedOriginGame?:source.originGame
        if(originGame !in 1..5)return showDialog("Gen 4 → Gen 3 blocked","A valid Gen 3 origin title is required. Nothing was changed.")
        gen4ToGen3PreflightRejection(source,legalisedOriginGame!=null)?.let{return showDialog("Gen 4 → Gen 3 blocked","$it\n\nThe Bank record and destination were left unchanged.")}
        fun snapshotsMatch()=bound()&&runCatching{file.readBytes().contentEquals(destination)&&selected.readBytes().contentEquals(bank)}.getOrDefault(false)
        val loading=AlertDialog.Builder(this).setTitle("Prepare Gen 4 → Gen 3").setMessage("Verifying the historical ability slot and native PK3 mapping…").setCancelable(false).create();loading.show()
        loadGen3ToGen4MetaAsync(source,3,4){meta,reason->loading.dismiss();if(!snapshotsMatch())return@loadGen3ToGen4MetaAsync showDialog("Gen 4 → Gen 3","The destination or Bank record changed during preparation.");if(meta==null)return@loadGen3ToGen4MetaAsync showDialog("Gen 4 → Gen 3 blocked",(reason?:"Conversion metadata could not be verified.")+"\n\nNothing was changed.")
            val plan=Gen4ToGen3Plan(meta,originGame,legalisedOriginGame!=null);val pk3=try{buildGen4ToGen3Pk3(bank,source,destination,plan)}catch(e:Exception){return@loadGen3ToGen4MetaAsync showDialog("Gen 4 → Gen 3 blocked",(e.message?:"No safe mapping is available.")+"\n\nNothing was changed.")};val converted=parsePk3(pk3,0,false)?:return@loadGen3ToGen4MetaAsync
            val prepared=Gen4Gen3Prepared(selected,bank,source,destination,plan,pk3,converted,file,openedUri,openedLabel)
            val originName=arrayOf("Sapphire","Ruby","Emerald","FireRed","LeafGreen")[plan.originGame-1]
            val originDisclosure=if(plan.originLegalised) "Legalise applied: the user selected Gen 3 origin $originName; this changes provenance and does not verify history." else "Preserved Gen 3 origin: $originName."
            val preview="PSE conversion, not an official reverse migration.\n\nPreserved: species, PID, OT/TID/SID, nickname, EXP/nature/shiny state, ability slot, IVs, EVs, moves, PP/PP Ups, friendship, Pokérus, Ball, met level and markings.\n\n$originDisclosure\n\nRequired format difference: Gen 4 Pal Park location #55 and its migration date cannot reconstruct the original Gen 3 encounter. PSE writes native PK3 met location 0 (unspecified); PK3 has no date fields. No held item, form, Egg or fateful marker will be discarded because records containing them are blocked.\n\nThe original PK4 Bank record remains exact until the native destination save, Pokédex mirrors and section checksums persist and reopen successfully."
            AlertDialog.Builder(this).setTitle("${source.nickname.ifBlank{meta.speciesName}} • Gen 4 → Gen 3").setMessage(preview).setNegativeButton("Cancel",null).setPositiveButton("Review destination"){_,_->if(snapshotsMatch())chooseGen4ToGen3Destination(prepared)else showDialog("Gen 4 → Gen 3","The destination or Bank record changed after review.")}.show()
        }
    }

    private fun gen4ToGen3StillBound(p:Gen4Gen3Prepared)=importedFile?.absolutePath==p.destinationFile.absolutePath&&currentSourceUri==p.sourceUri&&currentSourceLabel==p.sourceLabel&&runCatching{p.destinationFile.readBytes().contentEquals(p.destination)&&p.bankFile.readBytes().contentEquals(p.bankBytes)}.getOrDefault(false)
    private fun chooseGen4ToGen3Destination(p:Gen4Gen3Prepared){
        if(!gen4ToGen3StillBound(p))return showDialog("Gen 4 → Gen 3","The prepared snapshots changed. Reopen PSE Bank.");val pc=gen3PcBuffer(p.destination)?:return showDialog("Gen 4 → Gen 3","PSE could not reconstruct Gen 3 PC storage.");val empty=(0 until 420).filter{parsePk3(pc,4+it*80,false)==null};if(empty.isEmpty())return showDialog("Gen 4 → Gen 3","No empty Gen 3 PC slot is available.");val first=empty.first()
        AlertDialog.Builder(this).setTitle("Choose native Gen 3 destination").setMessage("The reviewed PSE conversion will be written to one empty native PK3 slot.").setNegativeButton("Cancel",null).setPositiveButton("First Empty (Box ${first/30+1} / Slot ${first%30+1})"){_,_->transferGen4BankToGen3(p,first)}.setNeutralButton("Choose Box / Slot"){_,_->showGen4ToGen3BoxPicker(p,pc)}.show()
    }
    private fun showGen4ToGen3BoxPicker(p:Gen4Gen3Prepared,pc:ByteArray){
        if(!gen4ToGen3StillBound(p))return showDialog("Gen 4 → Gen 3","The prepared snapshots changed. Reopen PSE Bank.");val boxes=(0 until 14).filter{b->(0 until 30).any{s->parsePk3(pc,4+(b*30+s)*80,false)==null}}
        AlertDialog.Builder(this).setTitle("Choose Gen 3 destination box").setItems(boxes.map{"Box ${it+1}"}.toTypedArray()){_,w->val b=boxes[w];val empties=(0 until 30).filter{s->parsePk3(pc,4+(b*30+s)*80,false)==null};AlertDialog.Builder(this).setTitle("Box ${b+1} • choose slot").setItems(empties.map{"Slot ${it+1}"}.toTypedArray()){_,sw->transferGen4BankToGen3(p,b*30+empties[sw])}.setNegativeButton("Cancel",null).show()}.setNegativeButton("Cancel",null).show()
    }

    private fun transferGen4BankToGen3(p:Gen4Gen3Prepared,target:Int){
        if(!gen4ToGen3StillBound(p))return showDialog("Gen 4 → Gen 3","The prepared snapshots changed. Reopen PSE Bank.");val file=p.destinationFile;val fresh=runCatching{file.readBytes()}.getOrNull()?:return;var writeStarted=false;var deleteAttempted=false;var backup:File?=null
        try{
            require(fresh.contentEquals(p.destination)&&generationForSize(fresh.size)==3&&gen3SaveValid(fresh)){"The Gen 3 destination changed or failed validation."};require(target in 0 until 420){"The destination slot is invalid."};val bank=p.bankFile.readBytes();require(bank.contentEquals(p.bankBytes)){"The PK4 Bank record changed."};val source=parsePk4(bank,false)?:error("The PK4 Bank record is invalid.");require(source.pid==p.source.pid&&source.species==p.source.species){"The selected Pokémon changed."}
            val pk3=buildGen4ToGen3Pk3(bank,source,fresh,p.plan);val converted=parsePk3(pk3,0,false)?:error("The refreshed PK3 could not be parsed.");require(pk3.contentEquals(p.pk3)&&sameGen4ToGen3Pk3(converted,p.converted)){"The prepared conversion changed before writing."}
            val save=fresh.copyOf();val pc=gen3PcBuffer(save)?:error("Could not reconstruct Gen 3 PC storage.");val beforePc=pc.copyOf();val off=4+target*80;require(parsePk3(pc,off,false)==null){"The destination slot is no longer empty."};pk3.copyInto(pc,off);val staged=parsePk3(pc,off,false)?:error("The staged PK3 could not be parsed.");require(sameGen4ToGen3Pk3(staged,converted)){"The staged PK3 changed."};require(pc.indices.all{it in off until off+80||pc[it]==beforePc[it]}){"Unrelated Gen 3 PC data changed."}
            writeGen1ToGen3PcAndDexFrozen(save,pc,converted.species);require(gen3SaveValid(save)&&gen2ToGen3DexRegistered(save,converted.species)){"The staged Gen 3 checksums or Pokédex mirrors failed verification."}
            val map=gen3ActiveSectionMap(fresh)?:error("Could not map the original Gen 3 sections.");val allowed=HashSet<Int>();var cursor=0;for(id in 5..13){val base=map[id];val len=gen3SectionLengths[id];val a=maxOf(off,cursor);val z=minOf(off+80,cursor+len);for(i in a until z)allowed.add(base+i-cursor);allowed.add(base+0xFF6);allowed.add(base+0xFF7);cursor+=len};val layout=gen3PokedexLayout(fresh)?:error("Could not map Gen 3 Pokédex mirrors.");val dexByte=(converted.species-1)/8;for(base in layout.mirrors)allowed.add(base+dexByte);for(base in intArrayOf(layout.section0,layout.section1,layout.seenSection)){allowed.add(base+0xFF6);allowed.add(base+0xFF7)};require(save.indices.all{it in allowed||save[it]==fresh[it]}){"The conversion changed data outside the selected PK3, Pokédex mirrors and required section checksums."}
            val recovery=File.createTempFile(backupGameName(file)+"_PreGen4ToGen3_",".backup",backupsDir());backup=recovery;recovery.writeBytes(fresh);require(recovery.readBytes().contentEquals(fresh)){"The recovery backup did not verify."};retainGen2ToGen3SafetyBackup(recovery,fresh);require(isBackupKept(recovery)&&gen4ToGen3StillBound(p)){"The retained backup, destination identity or Bank record changed before writing."}
            writeStarted=true;file.writeBytes(save);val written=file.readBytes();require(written.contentEquals(save)&&gen3SaveValid(written)&&gen2ToGen3DexRegistered(written,converted.species)){"The persisted Gen 3 save failed verification."};require(written.indices.all{it in allowed||written[it]==fresh[it]}){"The reopened save changed outside the reviewed scope."};val vpc=gen3PcBuffer(written)?:error("Could not reopen Gen 3 PC storage.");val actual=vpc.copyOfRange(off,off+80);val q=parsePk3(actual,0,false)?:error("The persisted PK3 could not be parsed.");require(actual.contentEquals(pk3)&&sameGen4ToGen3Pk3(q,staged)){"The exact native PK3 did not persist."}
            require(p.bankFile.readBytes().contentEquals(p.bankBytes)){"The PK4 Bank record changed before cleanup."};deleteAttempted=true;require(p.bankFile.delete()&&!p.bankFile.exists()){"The PK4 Bank record could not be removed after destination verification."}
        }catch(e:Exception){val bankRestored=runCatching{if(deleteAttempted&&!p.bankFile.exists())p.bankFile.writeBytes(p.bankBytes);p.bankFile.readBytes().contentEquals(p.bankBytes)}.getOrDefault(false);val saveRestored=!writeStarted||(bankRestored&&runCatching{file.writeBytes(fresh);file.readBytes().contentEquals(fresh)&&gen3SaveValid(fresh)}.getOrDefault(false));val recovery=if(bankRestored&&saveRestored)"The exact destination and PK4 Bank record were restored or kept and verified." else "Automatic recovery could not be verified. Keep the recovery backup and remaining files for review.";showDialog("Gen 4 → Gen 3 failed",(e.message?:"Unknown error")+"\n\n"+recovery+(backup?.let{"\n\nRecovery backup: ${it.name}"}?:""));return}
        Toast.makeText(this,"PSE converted Gen 4 → Gen 3 to Box ${target/30+1} • Slot ${target%30+1} and verified",Toast.LENGTH_LONG).show();showBank()
    }

    private data class Gen4Gen5Prepared(
        val sourceGeneration:Int,val bankFile:File,val bankBytes:ByteArray,val source:PokemonEntry,
        val destination:ByteArray,val meta:Gen3ToGen4Meta,val pk5:ByteArray,
        val converted:PokemonEntry,val destinationFile:File,
        val sourceUri:Uri?,val sourceLabel:String?,val gen3Plan:Gen3ToGen4Plan?=null
    )

    private fun genToGen5Title(p:Gen4Gen5Prepared)="Gen ${p.sourceGeneration} → Gen 5"

    private fun gen4ToGen5PreflightRejection(p:PokemonEntry):String?=when{
        !p.checksumValid->"The source PK4 checksum is invalid."
        p.species !in 1..493->"Only species that exist in Generation 4 can transfer on this route."
        p.isEgg->"Egg records are not supported by this transfer yet."
        p.heldItem!=0->"Held item #${p.heldItem} has no verified cross-generation item mapping. Remove it in the source game and deposit the Pokémon again."
        p.abilityNumber !in 1..2->"The source ability slot is not representable in Generation 5."
        p.ability !in 1..123->"The source ability ID is outside the Generation 4 ability catalogue."
        p.nature !in 0..24->"The source nature is invalid."
        p.moves.any{it !in 0..559}->"A source move is outside the Generation 5 move catalogue."
        p.movePP.any{it !in 0..63}->"A source move PP value is invalid."
        p.ivs.any{it !in 0..31}->"The source IV data is invalid."
        p.evs.any{it !in 0..255}||p.evs.sum()>510->"The source EV data exceeds Generation 5 limits."
        p.ball !in 1..25->"Ball ID ${p.ball} has no verified Generation 5 mapping."
        p.metLevel !in 1..100->"The source met level is outside Generation 5 limits."
        p.language !in 1..10->"Language ID ${p.language} is outside Generation 5 limits."
        p.nickname.length>10->"The nickname exceeds the supported Generation 5 name length."
        p.otName.length>7->"The Original Trainer name exceeds the supported Generation 5 name length."
        p.originGame !in 1..12->"The origin-game value cannot be represented safely in a Generation 5 record."
        else->null
    }

    private fun buildGen4ToGen5Pk5(
        raw:ByteArray,p:PokemonEntry,destination:ByteArray,meta:Gen3ToGen4Meta,
        validateGen5Destination:Boolean=true
    ):ByteArray{
        require(raw.size==136){"The preserved Gen 4 Bank record has an unexpected size."}
        if(validateGen5Destination)detectGen5Profile(destination)?:error("A valid Generation 5 destination save is required.")
        gen4ToGen5PreflightRejection(p)?.let{error(it)}
        require(meta.abilityId==p.ability){"The source ability does not match the verified Generation 5 ability slot."}
        require(gen3TransferGender(p,meta.genderRate)==p.gender){"The source gender does not match the verified species gender ratio."}
        val ups=gen4Pk4PpUps(raw);require(ups.all{it in 0..3}){"The source PP-Up values could not be read safely."}
        val out=decryptPk4(raw)?:error("The source PK4 could not be decrypted.")
        val targetPid=gen5PidForAbilityAndShiny(p)
        writeU32LE(out,0,targetPid)
        writeU16LE(out,0x08,p.species);writeU16LE(out,0x0A,0)
        writeU16LE(out,0x0C,p.tid);writeU16LE(out,0x0E,p.sid);writeU32LE(out,0x10,p.experience)
        out[0x14]=p.friendship.coerceIn(0,255).toByte();out[0x15]=p.ability.toByte()
        out[0x16]=p.markingValue.coerceIn(0,255).toByte();out[0x17]=p.language.toByte()
        for(i in 0..5)out[0x18+i]=p.evs[i].toByte()
        for(i in 0..3){
            writeU16LE(out,0x28+i*2,p.moves[i])
            out[0x30+i]=(if(p.moves[i]==0)0 else p.movePP[i]).toByte()
            out[0x34+i]=(if(p.moves[i]==0)0 else ups[i]).toByte()
        }
        var ivWord=0L
        for(i in 0..5)ivWord=ivWord or ((p.ivs[i].toLong() and 31L) shl(i*5))
        if(p.isNicknamed)ivWord=ivWord or 0x80000000L
        writeU32LE(out,0x38,ivWord)
        out[0x40]=(((p.gender and 3) shl 1) or ((p.form and 0x1F) shl 3) or (if(p.fatefulEncounter)1 else 0)).toByte()
        out[0x41]=p.nature.toByte()
        out[0x42]=0
        writeGen5String(out,0x48,22,p.nickname,10)
        out[0x5F]=p.originGame.toByte()
        writeGen5String(out,0x68,16,p.otName,7)
        out[0x82]=(((p.pokerusStrain and 0xF) shl 4) or (p.pokerusDays and 0xF)).toByte()
        out[0x83]=p.ball.toByte()
        out[0x84]=((p.metLevel and 0x7F) or ((p.otGender and 1) shl 7)).toByte()
        // Gen 4 map-location IDs do not identify the same places in Gen 5.
        writeU16LE(out,0x80,0)
        val encrypted=encryptPk5(out)
        val q=parsePk5(encrypted,false)?:error("The converted PK5 could not be parsed.")
        require(q.checksumValid&&!q.isEgg&&q.pid==targetPid&&q.species==p.species&&q.tid==p.tid&&q.sid==p.sid&&
            q.nickname==p.nickname&&q.isNicknamed==p.isNicknamed&&q.otName==p.otName&&q.experience==p.experience&&
            q.ability==p.ability&&q.abilityNumber==p.abilityNumber&&q.nature==p.nature&&q.gender==p.gender&&
            q.form==p.form&&q.fatefulEncounter==p.fatefulEncounter&&q.shiny==p.shiny&&q.heldItem==0&&
            q.friendship==p.friendship&&q.markingValue==p.markingValue&&q.language==p.language&&
            q.moves.contentEquals(p.moves)&&q.movePP.contentEquals(p.movePP)&&
            gen4Pk4PpUps(encrypted).contentEquals(ups)&&q.evs.contentEquals(p.evs)&&q.ivs.contentEquals(p.ivs)&&
            q.pokerusDays==p.pokerusDays&&q.pokerusStrain==p.pokerusStrain&&q.eggLocation==p.eggLocation&&
            q.metLocation==0&&q.ball==p.ball&&q.metLevel==p.metLevel&&q.otGender==p.otGender&&
            q.originGame==p.originGame&&q.metYear==p.metYear&&q.metMonth==p.metMonth&&q.metDay==p.metDay){
            "The converted PK5 did not preserve every supported field."
        }
        return encrypted
    }

    private fun sameGen4ToGen5Pk5(a:PokemonEntry,b:PokemonEntry):Boolean=
        a.checksumValid&&b.checksumValid&&!a.isEgg&&!b.isEgg&&a.pid==b.pid&&a.species==b.species&&
            a.tid==b.tid&&a.sid==b.sid&&a.nickname==b.nickname&&a.isNicknamed==b.isNicknamed&&
            a.otName==b.otName&&a.experience==b.experience&&a.ability==b.ability&&
            a.abilityNumber==b.abilityNumber&&a.nature==b.nature&&a.gender==b.gender&&a.form==b.form&&
            a.fatefulEncounter==b.fatefulEncounter&&a.shiny==b.shiny&&a.heldItem==b.heldItem&&
            a.friendship==b.friendship&&a.markingValue==b.markingValue&&a.language==b.language&&
            a.moves.contentEquals(b.moves)&&a.movePP.contentEquals(b.movePP)&&
            a.evs.contentEquals(b.evs)&&a.ivs.contentEquals(b.ivs)&&a.ball==b.ball&&
            a.metLevel==b.metLevel&&a.otGender==b.otGender&&a.originGame==b.originGame&&
            a.metYear==b.metYear&&a.metMonth==b.metMonth&&a.metDay==b.metDay

    private fun prepareGen4ToGen5Transfer(bankFile:File,shown:PokemonEntry){
        val file=importedFile?:return showDialog("Gen 4 → Gen 5","Load a valid Generation 5 destination save first.")
        val openedUri=currentSourceUri;val openedLabel=currentSourceLabel
        fun bound()=importedFile?.absolutePath==file.absolutePath&&currentSourceUri==openedUri&&currentSourceLabel==openedLabel
        val destination=runCatching{file.readBytes()}.getOrNull()?:return showDialog("Gen 4 → Gen 5","The destination save could not be read.")
        val profile=detectGen5Profile(destination)?:return showDialog("Gen 4 → Gen 5","Load a valid Black, White, Black 2 or White 2 save first.")
        if(!bound()||!gen5ChecksumTableValid(destination,profile)||(0 until 24).any{!gen5BoxChecksumValid(destination,it,profile)})
            return showDialog("Gen 4 → Gen 5","The loaded destination is not a valid, checksum-clean Generation 5 save.")
        val root=runCatching{bankDir().canonicalFile}.getOrNull()?:return
        val selected=runCatching{bankFile.canonicalFile}.getOrNull()?:return
        if(selected.parentFile!=root||!selected.extension.equals("pk4",true))
            return showDialog("Gen 4 → Gen 5","The selected record is outside the Generation 4 PSE Bank.")
        val bank=runCatching{selected.readBytes()}.getOrNull()?:return showDialog("Gen 4 → Gen 5","The Bank record could not be read.")
        val source=if(bank.size==136)parsePk4(bank,false)else null
        if(source==null||source.pid!=shown.pid||source.species!=shown.species||!source.checksumValid)
            return showDialog("Gen 4 → Gen 5","The selected Bank record changed or failed its PK4 checksum.")
        gen4ToGen5PreflightRejection(source)?.let{
            return showDialog("Gen 4 → Gen 5 blocked","$it\n\nThe Bank record and destination were left unchanged.")
        }
        val loading=AlertDialog.Builder(this).setTitle("Prepare Gen 4 → Gen 5")
            .setMessage("Preparing the native PK5 conversion and destination preview…").setCancelable(false).create()
        loading.show()
        loadGen3ToGen4MetaAsync(source,5,4){meta,reason->
            loading.dismiss()
            if(!bound()||!runCatching{file.readBytes().contentEquals(destination)&&selected.readBytes().contentEquals(bank)}.getOrDefault(false))
                return@loadGen3ToGen4MetaAsync showDialog("Gen 4 → Gen 5","The destination or Bank record changed during preparation. Nothing was changed.")
            if(meta==null)return@loadGen3ToGen4MetaAsync showDialog("Gen 4 → Gen 5 blocked",
                (reason?:"Generation 5 conversion data could not be verified.")+"\n\nNothing was changed.")
            val pk5=try{buildGen4ToGen5Pk5(bank,source,destination,meta)}catch(e:Exception){
                return@loadGen3ToGen4MetaAsync showDialog("Gen 4 → Gen 5 blocked",(e.message?:"No safe mapping is available.")+"\n\nNothing was changed.")
            }
            val converted=parsePk5(pk5,false)?:return@loadGen3ToGen4MetaAsync showDialog("Gen 4 → Gen 5","The prepared PK5 could not be re-read.")
            val prepared=Gen4Gen5Prepared(
                sourceGeneration=4,bankFile=selected,bankBytes=bank,source=source,
                destination=destination,meta=meta,pk5=pk5,converted=converted,
                destinationFile=file,sourceUri=openedUri,sourceLabel=openedLabel
            )
            val pidNotice=if(converted.pid==source.pid)"PID preserved." else "PID adjustment: ${source.pid.toString(16).uppercase().padStart(8,'0')} → ${converted.pid.toString(16).uppercase().padStart(8,'0')} so the Generation 5 ability slot agrees with its PID; TID/SID, ability, nature and shiny state are preserved. Review before continuing."
            val preview="PSE converts this preserved Gen 4 Bank record into a native Gen 5 PK5. Species, TID/SID, nickname, OT, experience, ability, nature, gender/form, shiny state, moves/PP/PP Ups, IVs, EVs, friendship, Pokérus, ball, met level, origin game and met date are preserved. $pidNotice The Gen 4 met-location number is set to 0 because Gen 4 and Gen 5 location catalogs differ; this is shown as unspecified location, not official migration provenance. Records with held items or unsupported fields remain blocked. The Gen 4 Bank copy stays available until the reviewed Gen 5 save is written."
            AlertDialog.Builder(this).setTitle("${source.nickname.ifBlank{"Pokémon #${source.species}"}} • Gen 4 → Gen 5")
                .setMessage(preview).setNegativeButton("Cancel",null)
                .setPositiveButton("Choose Gen 5 destination"){_,_->chooseGen4ToGen5Destination(prepared)}
                .show()
        }
    }

    private fun gen4ToGen5StillBound(p:Gen4Gen5Prepared):Boolean=
        importedFile?.absolutePath==p.destinationFile.absolutePath&&currentSourceUri==p.sourceUri&&
            currentSourceLabel==p.sourceLabel&&runCatching{
                p.destinationFile.readBytes().contentEquals(p.destination)&&
                    p.bankFile.readBytes().contentEquals(p.bankBytes)
            }.getOrDefault(false)

    private fun chooseGen4ToGen5Destination(p:Gen4Gen5Prepared){
        val title=genToGen5Title(p)
        if(!gen4ToGen5StillBound(p))return showDialog(title,"The destination or Bank record changed. Reopen PSE Bank.")
        val profile=detectGen5Profile(p.destination)?:return
        val empty=(0 until 24*30).filter{index->
            val off=0x00400+(index/30)*0x1000+(index%30)*136
            parsePk5(p.destination.copyOfRange(off,off+136),false)==null
        }
        if(empty.isEmpty())return showDialog(title,"All 720 native Gen 5 PC slots are occupied.")
        val first=empty.first()
        AlertDialog.Builder(this).setTitle("Choose native Gen 5 destination")
            .setMessage("The reviewed PSE conversion will be written to one empty PK5 slot. The destination box checksum and Pokédex will be updated.")
            .setItems(arrayOf("First Empty • Box ${first/30+1} • Slot ${first%30+1}","Choose Box / Slot")){_,which->
                if(!gen4ToGen5StillBound(p))showDialog(title,"The destination or Bank record changed. Reopen PSE Bank.")
                else if(which==0)transferGen4BankToGen5(p,first)else showGen4ToGen5BoxPicker(p)
            }.setNegativeButton("Cancel",null).show()
    }

    private fun showGen4ToGen5BoxPicker(p:Gen4Gen5Prepared){
        val title=genToGen5Title(p)
        if(!gen4ToGen5StillBound(p))return showDialog(title,"The destination or Bank record changed. Reopen PSE Bank.")
        val emptyBoxes=(0 until 24).filter{box->
            (0 until 30).any{slot->
                val off=0x00400+box*0x1000+slot*136
                parsePk5(p.destination.copyOfRange(off,off+136),false)==null
            }
        }
        if(emptyBoxes.isEmpty())return showDialog(title,"All native Gen 5 PC boxes are full.")
        AlertDialog.Builder(this).setTitle("Choose Gen 5 destination box")
            .setItems(emptyBoxes.map{"Box ${it+1}"} .toTypedArray()){_,which->
                val box=emptyBoxes[which]
                val slots=(0 until 30).filter{slot->
                    val off=0x00400+box*0x1000+slot*136
                    parsePk5(p.destination.copyOfRange(off,off+136),false)==null
                }
                AlertDialog.Builder(this).setTitle("Box ${box+1} • choose slot")
                    .setItems(slots.map{"Slot ${it+1}"} .toTypedArray()){_,slotIndex->
                        transferGen4BankToGen5(p,box*30+slots[slotIndex])
                    }.setNegativeButton("Cancel",null).show()
            }.setNegativeButton("Cancel",null).show()
    }

    private fun transferGen4BankToGen5(p:Gen4Gen5Prepared,target:Int){
        val title=genToGen5Title(p)
        if(!gen4ToGen5StillBound(p))return showDialog(title,"The destination or Bank record changed. Reopen PSE Bank.")
        val file=p.destinationFile
        val original=runCatching{file.readBytes()}.getOrNull()?:return showDialog(title,"The destination could not be read.")
        var writeStarted=false;var bankDeleteAttempted=false;var backup:File?=null
        try{
            require(original.contentEquals(p.destination)){"The prepared destination changed."}
            val profile=detectGen5Profile(original)?:error("The Generation 5 destination is no longer valid.")
            require(gen5ChecksumTableValid(original,profile)&&(0 until 24).all{gen5BoxChecksumValid(original,it,profile)}){"The destination box checksums changed."}
            require(target in 0 until 720){"The Gen 5 destination slot is invalid."}
            val bank=p.bankFile.readBytes()
            require(bank.contentEquals(p.bankBytes)){"The Gen ${p.sourceGeneration} Bank record changed."}
            val pk5=when(p.sourceGeneration){
                3->{
                    val source=parsePk3(bank,0,false)?:error("The PK3 Bank record is invalid.")
                    require(source.checksumValid&&source.pid==p.source.pid&&source.species==p.source.species&&
                        source.tid==p.source.tid&&source.sid==p.source.sid){"The source PK3 no longer matches the reviewed Pokémon."}
                    val plan=p.gen3Plan?:error("The reviewed Gen 3 conversion plan is unavailable.")
                    val bridge=buildGen3ToGen4Pk4(bank,source,original,plan,false)
                    val bridgeSource=parsePk4(bridge,false)?:error("The verified PK4 conversion bridge could not be reopened.")
                    buildGen4ToGen5Pk5(bridge,bridgeSource,original,p.meta)
                }
                4->{
                    val source=parsePk4(bank,false)?:error("The PK4 Bank record is invalid.")
                    require(source.checksumValid&&sameGen4ToGen5Pk5(source,p.source)){"The source PK4 no longer matches the reviewed Pokémon."}
                    buildGen4ToGen5Pk5(bank,source,original,p.meta)
                }
                else->error("This Generation ${p.sourceGeneration} to Generation 5 route is not supported.")
            }
            require(pk5.contentEquals(p.pk5)){"The prepared conversion changed before writing."}
            val box=target/30;val slot=target%30;val offset=0x00400+box*0x1000+slot*136
            require(parsePk5(original.copyOfRange(offset,offset+136),false)==null){"The selected Gen 5 slot is no longer empty."}
            val save=original.copyOf();pk5.copyInto(save,offset)
            val staged=parsePk5(save.copyOfRange(offset,offset+136),false)?:error("The staged PK5 could not be parsed.")
            require(sameGen4ToGen5Pk5(staged,p.converted)){"The staged PK5 differs from the reviewed conversion."}
            registerGen1ToGen5Pokedex(save,profile,staged)
            updateGen5BoxChecksum(save,box,profile)
            require(gen5BoxChecksumValid(save,box,profile)&&gen5ChecksumTableValid(save,profile)&&gen1ToGen5DexRegistered(save,profile,staged)){
                "The staged Generation 5 save, Pokédex or checksum table could not be verified."
            }
            val recovery=File.createTempFile(backupGameName(file)+"_PreGen${p.sourceGeneration}ToGen5_",".backup",backupsDir());backup=recovery
            recovery.writeBytes(original);require(recovery.readBytes().contentEquals(original)){"The Generation 5 recovery backup did not verify."}
            writeStarted=true;file.writeBytes(save)
            val written=file.readBytes()
            require(written.contentEquals(save)){"The written Gen 5 save differs from the reviewed destination."}
            val reopenedProfile=detectGen5Profile(written)?:error("The written Generation 5 save could not be reopened.")
            require(gen5BoxChecksumValid(written,box,reopenedProfile)&&gen5ChecksumTableValid(written,reopenedProfile)&&
                gen1ToGen5DexRegistered(written,reopenedProfile,staged)){"The written Gen 5 save failed checksum or Pokédex validation."}
            val actual=written.copyOfRange(offset,offset+136);val reopened=parsePk5(actual,false)
            require(actual.contentEquals(pk5)&&reopened!=null&&sameGen4ToGen5Pk5(reopened,p.converted)){
                "The exact converted PK5 did not persist."
            }
            require(importedFile?.absolutePath==file.absolutePath&&currentSourceUri==p.sourceUri&&currentSourceLabel==p.sourceLabel&&
                p.bankFile.readBytes().contentEquals(p.bankBytes)&&file.readBytes().contentEquals(save)){
                "The source identity, Gen ${p.sourceGeneration} Bank record or verified Gen 5 destination changed before Bank cleanup."
            }
            bankDeleteAttempted=true
            require(p.bankFile.delete()&&!p.bankFile.exists()){"The Gen ${p.sourceGeneration} Bank entry could not be removed after the Gen 5 destination was written."}
            require(file.readBytes().contentEquals(save)){"The verified Gen 5 destination changed after Bank cleanup."}
        }catch(e:Exception){
            val bankRestored=runCatching{
                if(bankDeleteAttempted&&!p.bankFile.exists()){require(p.bankFile.createNewFile()){"The Bank recovery path could not be reserved."};p.bankFile.writeBytes(p.bankBytes)}
                p.bankFile.readBytes().contentEquals(p.bankBytes)
            }.getOrDefault(false)
            val saveRestored=!writeStarted||runCatching{file.writeBytes(original);file.readBytes().contentEquals(original)}.getOrDefault(false)
            val recovery=if(bankRestored&&saveRestored)"The original destination and Gen ${p.sourceGeneration} Bank record were restored or kept." else
                "Automatic recovery could not be fully confirmed. Keep the saved backup and remaining files for review."
            showDialog("$title failed",(e.message?:"Unknown error")+"\n\n"+recovery+(backup?.let{"\n\nRecovery backup: ${it.name}"}?:""))
            return
        }
        Toast.makeText(this,"PSE transferred Gen ${p.sourceGeneration} → Gen 5 to Box ${target/30+1} • Slot ${target%30+1}.",Toast.LENGTH_LONG).show()
        showBank()
    }

    private fun confirmGen5DepositToBank(location:String,pokemon:PokemonEntry){
        val global=boxedLocationToGlobalIndex(location)
            ?:return showDialog("PSE Bank","Gen 5 Bank deposit is enabled for boxed Pokémon only.")
        if(global !in 0 until 24*30)return showDialog("PSE Bank","That is not a native Gen 5 PC slot.")
        AlertDialog.Builder(this).setTitle("Move ${pokemon.nickname.ifBlank{"Species #${pokemon.species}"}} to PSE Bank?")
            .setMessage("PSE will preserve the exact 136-byte PK5 record, verify the Gen 5 Bank copy, retain a recovery backup, then clear $location and rebuild the native box and checksum-table CRCs. If either side fails, the save and Bank entry roll back.")
            .setNegativeButton("Cancel",null).setPositiveButton("Move to Bank"){_,_->depositGen5ToBank(global,pokemon)}.show()
    }

    private fun depositGen5ToBank(global:Int,expected:PokemonEntry){
        val file=importedFile?:return
        val openedUri=currentSourceUri;val openedLabel=currentSourceLabel
        fun bound()=importedFile?.absolutePath==file.absolutePath&&currentSourceUri==openedUri&&currentSourceLabel==openedLabel
        val original=runCatching{file.readBytes()}.getOrNull()?:return showDialog("Gen 5 PSE Bank","The selected save could not be read.")
        var bankFile:File?=null;var backup:File?=null;var writeStarted=false
        try{
            require(bound()&&global in 0 until 720){"The source identity or PC slot changed."}
            val profile=detectGen5Profile(original)?:error("A valid Black, White, Black 2 or White 2 save is required.")
            require(gen5ChecksumTableValid(original,profile)&&(0 until 24).all{gen5BoxChecksumValid(original,it,profile)}){
                "The Gen 5 save did not pass box and checksum-table validation."
            }
            val box=global/30;val slot=global%30;val offset=0x00400+box*0x1000+slot*136
            val raw=original.copyOfRange(offset,offset+136);val source=parsePk5(raw,false)?:error("The boxed PK5 is no longer present.")
            require(source.checksumValid&&source.pid==expected.pid&&source.species==expected.species&&source.tid==expected.tid&&source.sid==expected.sid){
                "The source PK5 changed or failed its checksum."
            }
            val created=File(bankDir(),"${System.currentTimeMillis()}_${source.species}.pk5");bankFile=created;created.writeBytes(raw)
            val bankBytes=created.readBytes();val bankMon=if(bankBytes.size==136)parsePk5(bankBytes,false)else null
            require(bankBytes.contentEquals(raw)&&bankMon!=null&&bankMon.checksumValid&&bankMon.pid==source.pid&&bankMon.species==source.species){
                "The exact Gen 5 Bank record did not verify."
            }
            val recovery=File.createTempFile(backupGameName(file)+"_PreGen5BankDeposit_",".backup",backupsDir());backup=recovery
            recovery.writeBytes(original);require(recovery.readBytes().contentEquals(original)){"The recovery backup did not verify."}
            val work=original.copyOf();ByteArray(136).copyInto(work,offset);updateGen5BoxChecksum(work,box,profile)
            require(parsePk5(work.copyOfRange(offset,offset+136),false)==null&&gen5BoxChecksumValid(work,box,profile)&&gen5ChecksumTableValid(work,profile)){
                "The staged source removal or native Gen 5 checksums did not verify."
            }
            require(bound()&&file.readBytes().contentEquals(original)&&created.readBytes().contentEquals(raw)&&recovery.readBytes().contentEquals(original)){
                "The source, Bank record or recovery backup changed before writing."
            }
            writeStarted=true;file.writeBytes(work)
            val written=file.readBytes();require(written.contentEquals(work)){"The persisted save differs from the reviewed write."}
            val wp=detectGen5Profile(written)?:error("The persisted Gen 5 save could not be reopened.")
            require(gen5BoxChecksumValid(written,box,wp)&&gen5ChecksumTableValid(written,wp)&&parsePk5(written.copyOfRange(offset,offset+136),false)==null){
                "The persisted source removal or native checksums did not verify."
            }
            require(created.readBytes().contentEquals(raw)){"The Bank copy changed after persistence."}
            Toast.makeText(this,"Moved to Gen 5 PSE Bank and verified",Toast.LENGTH_LONG).show();bankViewGeneration=5
            val count=bankDir().listFiles()?.count{it.isFile&&it.extension.equals("pk5",true)}?:1;bankViewBox=(count-1).coerceAtLeast(0)/30;showBank()
        }catch(e:Exception){
            val saveRestored=!writeStarted||runCatching{file.writeBytes(original);file.readBytes().contentEquals(original)}.getOrDefault(false)
            val bankRemoved=runCatching{bankFile?.delete()!=false}.getOrDefault(false)
            val recovery=if(saveRestored&&bankRemoved)"The original working save was restored and no new Bank entry was kept." else "Automatic recovery could not be fully confirmed; keep the retained backup for recovery."
            showDialog("Gen 5 Bank move failed",(e.message?:"Unknown error")+"\n\n"+recovery+(backup?.let{"\n\nRecovery backup: ${it.name}"}?:""))
        }
    }

    private fun showGen5BankEntry(bankFile:File,p:PokemonEntry){
        val currentGen=importedFile?.let{generationForSize(it.length().toInt())}?:0
        val message=when(currentGen){
            4->"Original 136-byte PK5 preserved. Review a backward PSE conversion into the loaded native Gen 4 save. This is not an official transfer or provenance claim."
            5->"Original 136-byte PK5 preserved. Load Gen 4 for the adjacent backward conversion, Gen 6 for the adjacent forward conversion, or Gen 7 for the reviewed later-generation route."
            6->"Original 136-byte PK5 preserved. Review a native Gen 6 conversion, its exact field differences, and an explicit destination slot before writing."
            7->"Original 136-byte PK5 preserved. Review the final PID, markings and native field changes before writing one verified PK7 with retained recovery."
            else->"Original 136-byte PK5 preserved. Load a valid Gen 4, Gen 6 or Gen 7 save to review a PSE Bank conversion."
        }
        val b=AlertDialog.Builder(this).setTitle("${p.nickname.ifBlank{"Pokémon #${p.species}"}} • Gen 5 Bank").setMessage(message)
            .setNegativeButton("Close",null)
            .setNeutralButton("Delete"){_,_->AlertDialog.Builder(this).setTitle("Delete Bank entry?").setMessage("This permanently removes the preserved Gen 5 PK5 copy.").setNegativeButton("Cancel",null).setPositiveButton("Delete"){_,_->if(bankFile.delete()){Toast.makeText(this,"Bank entry deleted",Toast.LENGTH_SHORT).show();showBank()}else showDialog("PSE Bank","The Bank entry could not be deleted.")}.show()}
        if(currentGen==4)b.setPositiveButton("PSE Convert to Gen 4"){_,_->prepareGen5ToGen4Transfer(bankFile,p)}
        if(currentGen==6)b.setPositiveButton("Transfer to Gen 6"){_,_->prepareGen5ToGen6Transfer(bankFile,p)}
        if(currentGen==7)b.setPositiveButton("Transfer to Gen 7"){_,_->prepareGen5ToGen7Transfer(bankFile,p)}
        b.show()
    }

    private fun prepareGen5ToGen7Transfer(bankFile:File,shown:PokemonEntry){
        val file=importedFile?:return showDialog("Gen 5 → Gen 7","Load a valid Sun, Moon, Ultra Sun or Ultra Moon destination first.")
        val openedUri=currentSourceUri;val openedLabel=currentSourceLabel
        fun bound()=importedFile?.absolutePath==file.absolutePath&&currentSourceUri==openedUri&&currentSourceLabel==openedLabel
        val destination=runCatching{file.readBytes()}.getOrNull()
            ?:return showDialog("Gen 5 → Gen 7","The destination save could not be read.")
        val checks=validateGen7CoreChecksums(destination)
        if(!bound()||generationForSize(destination.size)!=7||!checks.first)
            return showDialog("Gen 5 → Gen 7",checks.second)
        val trainer=analyzeSave(file).trainer
            ?:return showDialog("Gen 5 → Gen 7","PSE could not read the destination trainer identity.")
        val root=runCatching{bankDir().canonicalFile}.getOrNull()
            ?:return showDialog("Gen 5 → Gen 7","The PSE Bank path could not be verified.")
        val selected=runCatching{bankFile.canonicalFile}.getOrNull()
            ?:return showDialog("Gen 5 → Gen 7","The selected Bank path could not be verified.")
        if(selected.parentFile!=root||!selected.isFile||!selected.extension.equals("pk5",true))
            return showDialog("Gen 5 → Gen 7","The selected record is outside the Generation 5 PSE Bank.")
        val bank=runCatching{selected.readBytes()}.getOrNull()
            ?:return showDialog("Gen 5 → Gen 7","The selected Bank record could not be read.")
        val source=if(bank.size==136)parsePk5(bank,false)else null
        if(source==null||!source.checksumValid||source.pid!=shown.pid||source.species!=shown.species||
            source.tid!=shown.tid||source.sid!=shown.sid)
            return showDialog("Gen 5 → Gen 7","The selected Bank record changed or failed its PK5 checksum.")
        gen5ToGen6PreflightRejection(source)?.let{
            return showDialog("Gen 5 → Gen 7 blocked","$it\n\nThe Bank record and destination were left unchanged.")
        }
        if(source.moves.indices.any{source.moves[it]==0&&source.movePP[it]!=0})
            return showDialog("Gen 5 → Gen 7 blocked","An empty move slot contains PP data that cannot be preserved.\n\nNothing was changed.")
        val sourceUps=gen5Pk5PpUps(bank)
        if(sourceUps.any{it !in 0..3}||(0..3).any{source.moves[it]==0&&sourceUps[it]!=0})
            return showDialog("Gen 5 → Gen 7 blocked","The PK5 contains PP-Up data that cannot be preserved exactly.\n\nNothing was changed.")
        fun snapshotsMatch()=bound()&&runCatching{
            file.readBytes().contentEquals(destination)&&selected.readBytes().contentEquals(bank)
        }.getOrDefault(false)
        val pk6=try{buildGen5ToGen6Pk6(bank,source,destination,trainer,7)}catch(e:Exception){
            return showDialog("Gen 5 → Gen 7 blocked",(e.message?:"The PK6 conversion bridge could not be prepared.")+"\n\nNothing was changed.")
        }
        val bridge6=parsePk6(pk6,0,PK6_STORED_SIZE,false,721)
            ?:return showDialog("Gen 5 → Gen 7","The PK6 conversion bridge could not be reopened.")
        val pk7=try{buildGen6ToGen7Pk7(pk6,bridge6)}catch(e:Exception){
            return showDialog("Gen 5 → Gen 7 blocked",(e.message?:"No safe native PK7 mapping is available.")+"\n\nNothing was changed.")
        }
        if(!gen6Pk6PpUps(pk7).contentEquals(sourceUps))
            return showDialog("Gen 5 → Gen 7 blocked","The prepared PK7 did not preserve every PP-Up value. Nothing was changed.")
        val converted=parsePk6(pk7,0,PK6_STORED_SIZE,false,807)
            ?:return showDialog("Gen 5 → Gen 7","The prepared PK7 could not be reopened.")
        if(!snapshotsMatch())return showDialog("Gen 5 → Gen 7","The destination or Bank record changed during preparation. Nothing was changed.")
        val markingNote=gen6ToGen7Markings(bridge6.markingValue).second
        val prepared=Gen6Gen7Prepared(
            bankFile=selected,bankBytes=bank,source=source,destination=destination,pk7=pk7,converted=converted,
            destinationFile=file,sourceUri=openedUri,sourceLabel=openedLabel,markingNote=markingNote,
            originGame=converted.originGame,sourceGeneration=5,trainer=trainer
        )
        val oldPid="%08X".format(source.pid);val newPid="%08X".format(converted.pid)
        val pidNote=if(source.pid==converted.pid)"PID remains $oldPid." else
            "PID changes $oldPid → $newPid only to preserve ${if(source.shiny)"shiny" else "non-shiny"} status under the wider Generation 6/7 threshold."
        val oldMet=if(source.metLocation==0)"none" else "#${source.metLocation}"
        val oldEgg=if(source.eggLocation==0)"none" else "#${source.eggLocation}"
        val preview=buildString{
            append("PSE Bank conversion preview; this does not claim an official Pokémon Bank transaction or provenance.\n\n")
            append("Preserved: species/form, TID/SID, nickname and OT, EXP, ability/slot, nature, gender, shiny state, moves, current PP, PP Ups, IVs, EVs, friendship, Pokérus, Ball, language, source title, met level/date and fateful marker.\n")
            append("$pidNote\nMarkings: $markingNote.\n")
            append("Required format changes: Gen 5 met location $oldMet becomes native transfer marker 30001; Egg location $oldEgg becomes 0. Current handler becomes ${trainer.trainerName}; relearn moves, geographic fields, Resort state and Hyper Training start empty.\n\n")
            append("Held items, Eggs, unsupported forms and invalid catalogue values are blocked instead of discarded. The source save stays unchanged. The exact Gen 5 Bank record remains until a retained recovery backup, chosen PK7 slot, Pokédex update, block CRCs, save signature and reopened destination all verify.")
        }
        AlertDialog.Builder(this).setTitle("${source.nickname.ifBlank{"Pokémon #${source.species}"}} • Gen 5 → Gen 7")
            .setMessage(preview).setNegativeButton("Cancel",null)
            .setPositiveButton("Choose Gen 7 destination"){_,_->
                if(!snapshotsMatch())showDialog("Gen 5 → Gen 7","The destination or Bank record changed after review. Nothing was changed.")
                else chooseGen6ToGen7Destination(prepared)
            }.show()
    }

    private data class Gen5Gen6Prepared(
        val sourceGeneration:Int,val bankFile:File,val bankBytes:ByteArray,val source:PokemonEntry,
        val destination:ByteArray,val trainer:TrainerData,val pk6:ByteArray,
        val converted:PokemonEntry,val destinationFile:File,
        val sourceUri:Uri?,val sourceLabel:String?,val gen4Meta:Gen3ToGen4Meta?=null
    )

    private fun genToGen6Title(p:Gen5Gen6Prepared)="Gen ${p.sourceGeneration} → Gen 6"

    private fun gen5ToGen6FormSupported(species:Int,form:Int):Boolean=when(species){
        201->form in 0..27
        386->form in 0..3
        412,413->form in 0..2
        422,423,492,550,641,642,645,647->form in 0..1
        479->form in 0..5
        585,586->form in 0..3
        else->form==0
    }

    private fun gen5ToGen6DateValid(year:Int,month:Int,day:Int):Boolean=
        (year==0&&month==0&&day==0)||(year in 0..99&&month in 1..12&&day in 1..31)

    private fun gen5ToGen6Markings(markings:Int):Int=markings and 0x3F

    private fun gen6Pk6PpUps(raw:ByteArray):IntArray{
        if(raw.size!=PK6_STORED_SIZE)return IntArray(4){-1}
        val d=decryptPk6IfNeeded(raw)
        return IntArray(4){d[0x66+it].toInt() and 3}
    }

    private fun gen6Pk6HandlerName(raw:ByteArray):String=
        if(raw.size==PK6_STORED_SIZE)readGen6String(decryptPk6IfNeeded(raw),0x78,26) else ""

    private fun gen5ToGen6PreflightRejection(p:PokemonEntry):String?=when{
        !p.checksumValid->"The source PK5 checksum is invalid."
        p.species !in 1..649->"Species #${p.species} is outside the Generation 5 catalogue."
        p.isEgg->"Egg records do not have a verified Gen 5 to Gen 6 PSE Bank mapping."
        p.heldItem!=0->"Held item #${p.heldItem} cannot cross this route without loss. Remove it in the Gen 5 source and deposit the Pokémon again."
        !gen5ToGen6FormSupported(p.species,p.form)->"Form ${p.form} for species #${p.species} has no verified persistent Gen 6 mapping."
        p.gender !in 0..2->"Gender value ${p.gender} is not representable in a native PK6."
        p.ability !in 1..164->"Ability #${p.ability} is outside the Generation 5 ability catalogue."
        p.abilityNumber !in intArrayOf(1,2,4)->"Ability slot ${p.abilityNumber} is not a supported normal, secondary, or hidden slot."
        p.nature !in 0..24->"Nature value ${p.nature} is invalid."
        p.moves.any{it !in 0..559}->"A move is outside the Generation 5 move catalogue."
        p.movePP.any{it !in 0..63}->"A move PP value is invalid."
        p.evs.any{it !in 0..255}||p.evs.sum()>510->"The EV data exceeds native Generation 6 limits."
        p.ivs.any{it !in 0..31}->"The IV data is invalid."
        p.friendship !in 0..255->"The friendship value is invalid."
        p.markingValue !in 0..63->"Gen 5 marking value ${p.markingValue} cannot be mapped to the six Gen 6 marking states."
        p.nickname.isBlank()||p.nickname.length>12||p.nickname.any{it=='\uFFFD'||it.code<0x20}->"The nickname cannot be represented exactly by the native Gen 6 text writer."
        p.otName.isBlank()||p.otName.length>12||p.otName.any{it=='\uFFFD'||it.code<0x20}->"The Original Trainer name cannot be represented exactly by the native Gen 6 text writer."
        p.language !in setOf(1,2,3,4,5,7,8)->"Language ID ${p.language} is not a verified Gen 5 language value supported by this Gen 6 writer."
        p.ball !in 1..25->"Ball ID ${p.ball} has no verified Generation 6 mapping on this route."
        p.metLevel !in 1..100->"The met level is outside Generation 6 limits."
        p.originGame !in 1..23->"Origin game ID ${p.originGame} cannot be represented safely in Generation 6."
        !gen5ToGen6DateValid(p.metYear,p.metMonth,p.metDay)->"The met date is not a valid native date."
        !gen5ToGen6DateValid(p.eggYear,p.eggMonth,p.eggDay)->"The Egg date is not a valid native date."
        else->null
    }

    private fun buildGen5ToGen6Pk6(
        raw:ByteArray,p:PokemonEntry,destination:ByteArray,trainer:TrainerData,targetGeneration:Int=6
    ):ByteArray{
        require(raw.size==136){"The preserved Gen 5 Bank record has an unexpected size."}
        require(
            (targetGeneration==6&&(destination.size==SIZE_G6_XY||destination.size==SIZE_G6_ORAS))||
                (targetGeneration==7&&generationForSize(destination.size)==7)
        ){"A valid Generation $targetGeneration destination save is required."}
        require(trainer.gameMatchesFamily&&(targetGeneration!=6||trainer.gameId in 24..27)){
            "PSE could not verify the loaded Generation $targetGeneration title."
        }
        require(trainer.trainerName.isNotBlank()&&trainer.trainerName.length<=12&&trainer.trainerName.none{it=='\uFFFD'||it.code<0x20}){"The destination trainer name cannot be represented exactly as the Gen 6 handling trainer."}
        gen5ToGen6PreflightRejection(p)?.let{error(it)}
        val ups=gen5Pk5PpUps(raw);require(ups.all{it in 0..3}){"The PK5 PP-Up values could not be verified."}
        val out=ByteArray(PK6_STORED_SIZE)
        var ec=(p.pid xor (p.tid.toLong() shl 16) xor p.sid.toLong() xor 0x47354736L) and 0xFFFFFFFFL
        if(ec==0L)ec=1L
        writeU32LE(out,0,ec);writeU16LE(out,0x08,p.species);writeU16LE(out,0x0A,0)
        writeU16LE(out,0x0C,p.tid);writeU16LE(out,0x0E,p.sid);writeU32LE(out,0x10,p.experience)
        out[0x14]=p.ability.toByte();out[0x15]=p.abilityNumber.toByte();out[0x2A]=gen5ToGen6Markings(p.markingValue).toByte()
        val pid=forceGen7ShinyState(p.pid,p.tid,p.sid,p.shiny);writeU32LE(out,0x18,pid);out[0x1C]=p.nature.toByte()
        out[0x1D]=(((p.gender and 3) shl 1) or ((p.form and 0x1F) shl 3) or (if(p.fatefulEncounter)1 else 0)).toByte()
        for(i in 0..5)out[0x1E+i]=p.evs[i].toByte()
        out[0x2B]=(((p.pokerusStrain and 0xF) shl 4) or (p.pokerusDays and 0xF)).toByte()
        writeGen6String(out,0x40,26,p.nickname)
        for(i in 0..3){writeU16LE(out,0x5A+i*2,p.moves[i]);out[0x62+i]=(if(p.moves[i]==0)0 else p.movePP[i]).toByte();out[0x66+i]=(if(p.moves[i]==0)0 else ups[i]).toByte()}
        var ivWord=0L;for(i in 0..5)ivWord=ivWord or ((p.ivs[i].toLong() and 31L) shl(i*5));if(p.isNicknamed)ivWord=ivWord or 0x80000000L;writeU32LE(out,0x74,ivWord)
        writeGen6String(out,0x78,26,trainer.trainerName);out[0x92]=if(trainer.gender.equals("Female",true))1 else 0;out[0x93]=1;out[0xA2]=p.friendship.toByte()
        writeGen6String(out,0xB0,26,p.otName);out[0xCA]=p.friendship.toByte()
        out[0xD1]=p.eggYear.toByte();out[0xD2]=p.eggMonth.toByte();out[0xD3]=p.eggDay.toByte()
        out[0xD4]=p.metYear.toByte();out[0xD5]=p.metMonth.toByte();out[0xD6]=p.metDay.toByte()
        writeU16LE(out,0xD8,0);writeU16LE(out,0xDA,30001);out[0xDC]=p.ball.toByte()
        out[0xDD]=((p.metLevel and 0x7F) or ((p.otGender and 1) shl 7)).toByte();out[0xDF]=p.originGame.toByte();out[0xE3]=p.language.toByte()
        updatePk6Checksum(out);val encrypted=encryptPk6(out);val q=parsePk6(encrypted,0,PK6_STORED_SIZE,false,721)?:error("The converted PK6 could not be parsed.")
        require(q.checksumValid&&!q.isEgg&&q.species==p.species&&q.pid==pid&&q.tid==p.tid&&q.sid==p.sid&&q.nickname==p.nickname&&q.isNicknamed==p.isNicknamed&&q.otName==p.otName&&q.experience==p.experience&&q.ability==p.ability&&q.abilityNumber==p.abilityNumber&&q.nature==p.nature&&q.gender==p.gender&&q.form==p.form&&q.shiny==p.shiny&&q.fatefulEncounter==p.fatefulEncounter&&q.heldItem==0&&q.friendship==p.friendship&&q.currentHandler==1&&gen6Pk6HandlerName(encrypted)==trainer.trainerName&&q.markingValue==gen5ToGen6Markings(p.markingValue)&&q.moves.contentEquals(p.moves)&&q.movePP.contentEquals(p.movePP)&&gen6Pk6PpUps(encrypted).contentEquals(ups)&&q.evs.contentEquals(p.evs)&&q.ivs.contentEquals(p.ivs)&&q.pokerusDays==p.pokerusDays&&q.pokerusStrain==p.pokerusStrain&&q.relearnMoves.all{it==0}&&q.eggLocation==0&&q.metLocation==30001&&q.ball==p.ball&&q.metLevel==p.metLevel&&q.otGender==p.otGender&&q.originGame==p.originGame&&q.language==p.language&&q.eggYear==p.eggYear&&q.eggMonth==p.eggMonth&&q.eggDay==p.eggDay&&q.metYear==p.metYear&&q.metMonth==p.metMonth&&q.metDay==p.metDay){"The converted PK6 did not preserve every reviewed field."}
        return encrypted
    }

    private fun sameGen5ToGen6Pk6(a:PokemonEntry,b:PokemonEntry):Boolean=
        a.checksumValid&&b.checksumValid&&!a.isEgg&&!b.isEgg&&a.species==b.species&&a.pid==b.pid&&a.tid==b.tid&&a.sid==b.sid&&a.nickname==b.nickname&&a.isNicknamed==b.isNicknamed&&a.otName==b.otName&&a.experience==b.experience&&a.ability==b.ability&&a.abilityNumber==b.abilityNumber&&a.nature==b.nature&&a.gender==b.gender&&a.form==b.form&&a.shiny==b.shiny&&a.fatefulEncounter==b.fatefulEncounter&&a.heldItem==b.heldItem&&a.friendship==b.friendship&&a.currentHandler==b.currentHandler&&a.markingValue==b.markingValue&&a.moves.contentEquals(b.moves)&&a.movePP.contentEquals(b.movePP)&&a.evs.contentEquals(b.evs)&&a.ivs.contentEquals(b.ivs)&&a.pokerusDays==b.pokerusDays&&a.pokerusStrain==b.pokerusStrain&&a.relearnMoves.contentEquals(b.relearnMoves)&&a.eggLocation==b.eggLocation&&a.metLocation==b.metLocation&&a.ball==b.ball&&a.metLevel==b.metLevel&&a.otGender==b.otGender&&a.originGame==b.originGame&&a.language==b.language&&a.eggYear==b.eggYear&&a.eggMonth==b.eggMonth&&a.eggDay==b.eggDay&&a.metYear==b.metYear&&a.metMonth==b.metMonth&&a.metDay==b.metDay

    private fun prepareGen5ToGen6Transfer(bankFile:File,shown:PokemonEntry){
        val file=importedFile?:return showDialog("Gen 5 → Gen 6","Load a valid Generation 6 destination save first.")
        val openedUri=currentSourceUri;val openedLabel=currentSourceLabel
        fun bound()=importedFile?.absolutePath==file.absolutePath&&currentSourceUri==openedUri&&currentSourceLabel==openedLabel
        val destination=runCatching{file.readBytes()}.getOrNull()?:return showDialog("Gen 5 → Gen 6","The destination save could not be read.")
        if((destination.size!=SIZE_G6_XY&&destination.size!=SIZE_G6_ORAS)||!bound()||!gen6BoxChecksumValid(destination)||!gen6BlockChecksumValid(destination,20))return showDialog("Gen 5 → Gen 6","Load a checksum-clean Pokémon X, Y, Omega Ruby or Alpha Sapphire save first.")
        val trainer=analyzeSave(file).trainer?:return showDialog("Gen 5 → Gen 6","PSE could not read the destination trainer identity.")
        val root=runCatching{bankDir().canonicalFile}.getOrNull()?:return;val selected=runCatching{bankFile.canonicalFile}.getOrNull()?:return
        if(selected.parentFile!=root||!selected.extension.equals("pk5",true))return showDialog("Gen 5 → Gen 6","The selected record is outside the Generation 5 PSE Bank.")
        val bank=runCatching{selected.readBytes()}.getOrNull()?:return showDialog("Gen 5 → Gen 6","The Bank record could not be read.")
        val source=if(bank.size==136)parsePk5(bank,false)else null
        if(source==null||!source.checksumValid||source.pid!=shown.pid||source.species!=shown.species)return showDialog("Gen 5 → Gen 6","The selected Bank record changed or failed its PK5 checksum.")
        gen5ToGen6PreflightRejection(source)?.let{return showDialog("Gen 5 → Gen 6 blocked","$it\n\nThe Bank record and destination were left unchanged.")}
        val pk6=try{buildGen5ToGen6Pk6(bank,source,destination,trainer)}catch(e:Exception){return showDialog("Gen 5 → Gen 6 blocked",(e.message?:"No safe native mapping is available.")+"\n\nNothing was changed.")}
        if(!bound()||!runCatching{file.readBytes().contentEquals(destination)&&selected.readBytes().contentEquals(bank)}.getOrDefault(false))return showDialog("Gen 5 → Gen 6","The destination or Bank record changed during preparation. Nothing was changed.")
        val converted=parsePk6(pk6,0,PK6_STORED_SIZE,false,721)?:return showDialog("Gen 5 → Gen 6","The prepared PK6 could not be re-read.")
        val prepared=Gen5Gen6Prepared(
            sourceGeneration=5,bankFile=selected,bankBytes=bank,source=source,
            destination=destination,trainer=trainer,pk6=pk6,converted=converted,
            destinationFile=file,sourceUri=openedUri,sourceLabel=openedLabel
        )
        val oldPid="%08X".format(source.pid);val newPid="%08X".format(converted.pid);val pidNote=if(source.pid==converted.pid)"PID remains $oldPid." else "PID changes $oldPid → $newPid only to preserve ${if(source.shiny)"shiny" else "non-shiny"} status under Gen 6's wider shiny threshold."
        val preview="PSE will write a native PK6 while preserving species/form, TID/SID, nickname and OT, experience, ability slot, nature, gender, shiny state, moves/PP/PP Ups, IVs, EVs, friendship, Pokérus, Ball, met level, origin game and dates.\n\nReviewed Gen 6 differences:\n• $pidNote\n• Gen 5 one-bit markings 0x${"%02X".format(source.markingValue)} remain the same six native one-bit PK6 markings.\n• Met location #${source.metLocation} becomes native transfer marker 30001; this is labelled as a PSE conversion and does not claim official transporter provenance.\n• Egg location #${source.eggLocation} becomes 0 because the location catalog is not interchangeable.\n• Current handler becomes ${trainer.trainerName}; the original OT remains ${source.otName}.\n• Relearn moves and geographic fields start empty because PK5 stores neither.\n\nHeld items and unsupported forms are blocked instead of discarded. The PK5 Bank record remains until the selected Gen 6 slot, Pokédex and checksums persist and reopen successfully."
        AlertDialog.Builder(this).setTitle("${source.nickname.ifBlank{"Pokémon #${source.species}"}} • Gen 5 → Gen 6").setMessage(preview).setNegativeButton("Cancel",null).setPositiveButton("Choose Gen 6 destination"){_,_->chooseGen5ToGen6Destination(prepared)}.show()
    }

    private fun gen5ToGen6StillBound(p:Gen5Gen6Prepared):Boolean=
        importedFile?.absolutePath==p.destinationFile.absolutePath&&currentSourceUri==p.sourceUri&&currentSourceLabel==p.sourceLabel&&runCatching{p.destinationFile.readBytes().contentEquals(p.destination)&&p.bankFile.readBytes().contentEquals(p.bankBytes)}.getOrDefault(false)

    private fun chooseGen5ToGen6Destination(p:Gen5Gen6Prepared){
        val title=genToGen6Title(p)
        if(!gen5ToGen6StillBound(p))return showDialog(title,"The destination or Bank record changed. Reopen PSE Bank.")
        val info=boxStorageInfo(p.destination)?:return
        val empty=(0 until info.second).filter{
            parsePk6(p.destination,info.first+it*PK6_STORED_SIZE,PK6_STORED_SIZE,false,info.third)==null
        }
        if(empty.isEmpty())return showDialog(title,"All native Generation 6 PC slots are occupied.")
        val first=empty.first()
        AlertDialog.Builder(this).setTitle("Choose native Gen 6 destination")
            .setMessage("The reviewed PK6 will be written to one empty slot. PSE will update only that slot, the required Pokédex flags, and native block checksums.")
            .setItems(arrayOf("First Empty • Box ${first/30+1} • Slot ${first%30+1}","Choose Box / Slot")){_,which->
                if(!gen5ToGen6StillBound(p))showDialog(title,"The destination or Bank record changed. Reopen PSE Bank.")
                else if(which==0)transferGen5BankToGen6(p,first)else showGen5ToGen6BoxPicker(p)
            }.setNegativeButton("Cancel",null).show()
    }

    private fun showGen5ToGen6BoxPicker(p:Gen5Gen6Prepared){
        val title=genToGen6Title(p)
        if(!gen5ToGen6StillBound(p))return showDialog(title,"The destination or Bank record changed. Reopen PSE Bank.")
        val info=boxStorageInfo(p.destination)?:return
        val boxes=(0 until info.second/30).filter{box->(0 until 30).any{slot->
            parsePk6(p.destination,info.first+(box*30+slot)*PK6_STORED_SIZE,PK6_STORED_SIZE,false,info.third)==null
        }}
        if(boxes.isEmpty())return showDialog(title,"All native Generation 6 PC boxes are full.")
        AlertDialog.Builder(this).setTitle("Choose Gen 6 destination box")
            .setItems(boxes.map{"Box ${it+1}"}.toTypedArray()){_,which->
                val box=boxes[which]
                val slots=(0 until 30).filter{slot->
                    parsePk6(p.destination,info.first+(box*30+slot)*PK6_STORED_SIZE,PK6_STORED_SIZE,false,info.third)==null
                }
                AlertDialog.Builder(this).setTitle("Box ${box+1} • choose slot")
                    .setItems(slots.map{"Slot ${it+1}"}.toTypedArray()){_,slotIndex->
                        transferGen5BankToGen6(p,box*30+slots[slotIndex])
                    }.setNegativeButton("Cancel",null).show()
            }.setNegativeButton("Cancel",null).show()
    }

    private fun retainGenToGen6SafetyBackup(file:File,expected:ByteArray){
        require(file.isFile&&file.readBytes().contentEquals(expected)&&(expected.size==SIZE_G6_XY||expected.size==SIZE_G6_ORAS)&&gen6BoxChecksumValid(expected)&&gen6BlockChecksumValid(expected,20)){"The Gen 6 destination recovery backup did not verify."}
        val names=keptBackupNames().apply{add(file.name)};val prefs=getSharedPreferences("pse_backup_state",MODE_PRIVATE)
        require(prefs.edit().putStringSet("kept",names).commit()){"The recovery backup Keep pin could not be saved. Nothing may be written."}
        require(isBackupKept(file)&&file.readBytes().contentEquals(expected)){"The retained recovery backup or Keep pin could not be rechecked."}
    }

    private fun transferGen5BankToGen6(p:Gen5Gen6Prepared,target:Int){
        val title=genToGen6Title(p)
        if(!gen5ToGen6StillBound(p))return showDialog(title,"The destination or Bank record changed. Reopen PSE Bank.")
        val file=p.destinationFile
        val original=runCatching{file.readBytes()}.getOrNull()?:return showDialog(title,"The destination save could not be read.")
        var writeStarted=false;var deleteAttempted=false;var backup:File?=null
        try{
            require(original.contentEquals(p.destination)&&(original.size==SIZE_G6_XY||original.size==SIZE_G6_ORAS)){"The prepared Gen 6 destination changed."};require(gen6BoxChecksumValid(original)&&gen6BlockChecksumValid(original,20)){"The destination storage or Pokédex checksum changed."}
            val info=boxStorageInfo(original)?:error("PSE could not resolve native Gen 6 PC storage.");require(target in 0 until info.second){"The selected Gen 6 slot is invalid."};val offset=info.first+target*PK6_STORED_SIZE;require(parsePk6(original,offset,PK6_STORED_SIZE,false,info.third)==null){"The selected Gen 6 slot is no longer empty."}
            val bank=p.bankFile.readBytes();require(bank.contentEquals(p.bankBytes)){"The Gen ${p.sourceGeneration} Bank record changed."}
            val sourcePpUps:IntArray
            val pk6=when(p.sourceGeneration){
                3->{
                    val source=parsePk3(bank,0,false)?:error("The PK3 Bank record is invalid.")
                    require(source.checksumValid&&source.pid==p.source.pid&&source.species==p.source.species&&
                        source.tid==p.source.tid&&source.sid==p.source.sid){"The selected PK3 no longer matches the reviewed Pokémon."}
                    sourcePpUps=gen3MovePpUps(bank);p.pk6
                }
                4->{
                    val source=parsePk4(bank,false)?:error("The PK4 Bank record is invalid.")
                    require(source.checksumValid&&sameGen4ToGen5Pk5(source,p.source)){
                        "The selected PK4 no longer matches the reviewed Pokémon."
                    }
                    val meta=p.gen4Meta?:error("The reviewed Generation 5 ability mapping is unavailable.")
                    val bridge=buildGen4ToGen5Pk5(bank,source,original,meta,false)
                    val bridgeSource=parsePk5(bridge,false)
                        ?:error("The verified PK5 conversion bridge could not be reopened.")
                    sourcePpUps=gen4Pk4PpUps(bank)
                    buildGen5ToGen6Pk6(bridge,bridgeSource,original,p.trainer)
                }
                5->{
                    val source=parsePk5(bank,false)?:error("The PK5 Bank record is invalid.")
                    require(source.checksumValid&&source.pid==p.source.pid&&source.species==p.source.species){
                        "The selected PK5 no longer matches the reviewed Pokémon."
                    }
                    sourcePpUps=gen5Pk5PpUps(bank)
                    buildGen5ToGen6Pk6(bank,source,original,p.trainer)
                }
                else->error("This Generation ${p.sourceGeneration} to Generation 6 route is not supported.")
            }
            require(pk6.contentEquals(p.pk6)){"The reviewed PK6 conversion changed before writing."}
            val save=original.copyOf();pk6.copyInto(save,offset)
            val staged=parsePk6(save,offset,PK6_STORED_SIZE,false,info.third)?:error("The staged PK6 could not be parsed.")
            require(sameGen5ToGen6Pk6(staged,p.converted)&&gen6Pk6PpUps(pk6).contentEquals(sourcePpUps)){
                "The staged PK6 differs from the reviewed conversion."
            }
            val allowed=HashSet<Int>();for(i in offset until offset+PK6_STORED_SIZE)allowed.add(i);val bit=staged.species-1;val bd=bit ushr 3;val shift=staged.gender.coerceIn(0,1) or ((if(staged.shiny)1 else 0) shl 1);allowed.add(0x15000+0x08+bd);allowed.add(0x15000+0x08+0x60*(1+shift)+bd);for(i in 5..8)allowed.add(0x15000+0x08+0x60*i+bd);val boxBlock=if(save.size==SIZE_G6_XY)53 else 56;for(i in 0..1){allowed.add(gen6ChecksumOffset(save,boxBlock)+i);allowed.add(gen6ChecksumOffset(save,20)+i)}
            registerGen6Dex(save,staged.species,staged.gender,staged.shiny,staged.language);updateGen6BoxChecksum(save);updateGen6DexChecksum(save);require(save.indices.all{it in allowed||save[it]==original[it]}){"The conversion changed data outside the selected PK6, required Pokédex flags and native checksums."};require(gen6BoxChecksumValid(save)&&gen6BlockChecksumValid(save,20)&&gen6DexCaught(save,staged.species)){"The staged Gen 6 save failed storage, Pokédex or checksum verification."}
            val recovery=File.createTempFile(backupGameName(file)+"_PreGen${p.sourceGeneration}ToGen6_",".backup",backupsDir());backup=recovery
            recovery.writeBytes(original);require(recovery.readBytes().contentEquals(original)){"The Gen 6 recovery backup did not verify."}
            retainGenToGen6SafetyBackup(recovery,original)
            require(gen5ToGen6StillBound(p)&&file.readBytes().contentEquals(original)&&isBackupKept(recovery)){"The source identity, snapshots or retained backup changed before writing."}
            writeStarted=true;file.writeBytes(save)
            val written=file.readBytes()
            require(written.contentEquals(save)&&written.indices.all{it in allowed||written[it]==original[it]}){"The persisted Gen 6 save differs from the reviewed write scope."}
            require(gen6BoxChecksumValid(written)&&gen6BlockChecksumValid(written,20)&&gen6DexCaught(written,staged.species)){"The persisted Gen 6 save failed checksum or Pokédex validation."}
            val actual=written.copyOfRange(offset,offset+PK6_STORED_SIZE);val reopened=parsePk6(actual,0,PK6_STORED_SIZE,false,721)
            require(actual.contentEquals(pk6)&&reopened!=null&&sameGen5ToGen6Pk6(reopened,p.converted)&&
                gen6Pk6PpUps(actual).contentEquals(sourcePpUps)){"The exact converted PK6 did not persist after reopening."}
            require(importedFile?.absolutePath==file.absolutePath&&currentSourceUri==p.sourceUri&&
                currentSourceLabel==p.sourceLabel&&p.bankFile.readBytes().contentEquals(p.bankBytes)&&
                file.readBytes().contentEquals(save)&&isBackupKept(recovery)){
                "The Bank record, destination identity or retained backup changed before cleanup."
            }
            deleteAttempted=true
            require(p.bankFile.delete()&&!p.bankFile.exists()){"The Gen ${p.sourceGeneration} Bank record could not be removed after destination verification."}
            require(file.readBytes().contentEquals(save)){"The verified Gen 6 destination changed after Bank cleanup."}
        }catch(e:Exception){
            val bankRestored=runCatching{if(deleteAttempted&&!p.bankFile.exists())p.bankFile.writeBytes(p.bankBytes);p.bankFile.readBytes().contentEquals(p.bankBytes)}.getOrDefault(false)
            val saveRestored=!writeStarted||(bankRestored&&runCatching{file.writeBytes(original);file.readBytes().contentEquals(original)&&gen6BoxChecksumValid(original)&&gen6BlockChecksumValid(original,20)}.getOrDefault(false))
            val recovery=if(bankRestored&&saveRestored)"The exact Gen 6 destination and Gen ${p.sourceGeneration} Bank record were restored or kept and verified." else "Automatic recovery could not be fully verified. Keep the retained recovery backup and remaining files for review."
            showDialog("$title failed",(e.message?:"Unknown error")+"\n\n"+recovery+(backup?.let{"\n\nRecovery backup: ${it.name}"}?:""));return
        }
        Toast.makeText(this,"PSE transferred Gen ${p.sourceGeneration} → Gen 6 to Box ${target/30+1} • Slot ${target%30+1} and verified",Toast.LENGTH_LONG).show();showBank()
    }

    private fun showGen6BankEntry(bankFile:File,p:PokemonEntry){
        val currentGen=importedFile?.let{generationForSize(it.length().toInt())}?:0
        val message=when(currentGen){
            5->"Original 232-byte PK6 preserved. Review a backward PSE conversion into the loaded native Gen 5 save. This is not an official transfer or provenance claim."
            6->"Original 232-byte PK6 preserved. Withdraw it unchanged to the loaded Gen 6 save, or load Gen 5 to review the adjacent backward PSE conversion."
            7->"Original 232-byte PK6 preserved. Review the existing forward conversion into the loaded Gen 7 save."
            else->"Original 232-byte PK6 preserved. Load a valid Gen 5, Gen 6 or Gen 7 save to review an adjacent PSE Bank route."
        }
        val b=AlertDialog.Builder(this).setTitle("${p.nickname.ifBlank{"Pokémon #${p.species}"}} • Gen 6 Bank").setMessage(message)
            .setNegativeButton("Close",null)
            .setNeutralButton("Delete"){_,_->AlertDialog.Builder(this).setTitle("Delete Bank entry?").setMessage("This permanently removes the preserved Gen 6 PK6 copy.").setNegativeButton("Cancel",null).setPositiveButton("Delete"){_,_->if(bankFile.delete()){Toast.makeText(this,"Bank entry deleted",Toast.LENGTH_SHORT).show();showBank()}else showDialog("PSE Bank","The Bank entry could not be deleted.")}.show()}
        if(currentGen==5)b.setPositiveButton("PSE Convert to Gen 5"){_,_->prepareGen6ToGen5Transfer(bankFile,p,null)}
        if(currentGen==6)b.setPositiveButton("Withdraw to Gen 6"){_,_->chooseWithdrawDestination(bankFile,p)}
        if(currentGen==7)b.setPositiveButton("Transfer to Gen 7"){_,_->prepareGen6ToGen7Transfer(bankFile,p)}
        b.show()
    }

    private fun showGen7BankEntry(bankFile:File,p:PokemonEntry){
        val currentGen=importedFile?.let{generationForSize(it.length().toInt())}?:0
        val message=when(currentGen){
            6->"Original 232-byte PK7 preserved. Review a backward PSE conversion into the loaded native Gen 6 save. This is not an official transfer or provenance claim."
            7->"Original 232-byte PK7 preserved. Withdraw it unchanged to the loaded Gen 7 save, or load Gen 6 to review the adjacent backward PSE conversion."
            else->"Original 232-byte PK7 preserved. Load a valid Gen 6 or Gen 7 save to review this PSE Bank route."
        }
        val b=AlertDialog.Builder(this).setTitle("${p.nickname.ifBlank{"Pokémon #${p.species}"}} • Gen 7 Bank").setMessage(message)
            .setNegativeButton("Close",null)
            .setNeutralButton("Delete"){_,_->AlertDialog.Builder(this).setTitle("Delete Bank entry?").setMessage("This permanently removes the preserved Gen 7 PK7 copy.").setNegativeButton("Cancel",null).setPositiveButton("Delete"){_,_->if(bankFile.delete()){Toast.makeText(this,"Bank entry deleted",Toast.LENGTH_SHORT).show();showBank()}else showDialog("PSE Bank","The Bank entry could not be deleted.")}.show()}
        if(currentGen==6)b.setPositiveButton("PSE Convert to Gen 6"){_,_->prepareGen7ToGen6Transfer(bankFile,p)}
        if(currentGen==7)b.setPositiveButton("Withdraw to Gen 7"){_,_->chooseWithdrawDestination(bankFile,p)}
        b.show()
    }

    private data class Gen6Gen5Plan(val originGame:Int,val originLabel:String,val legalised:Boolean)
    private data class Gen6Gen5Prepared(
        val bankFile:File,val bankBytes:ByteArray,val source:PokemonEntry,val destination:ByteArray,
        val plan:Gen6Gen5Plan,val pk5:ByteArray,val converted:PokemonEntry,val destinationFile:File,
        val sourceUri:Uri?,val sourceLabel:String?,val omittedMetadata:String
    )

    private fun gen6ToGen5Markings(markings:Int):Int=markings and 0x3F

    private fun gen6ToGen5PreflightRejection(p:PokemonEntry):String?=when{
        !p.checksumValid->"The source PK6 checksum is invalid."
        p.species !in 1..649->"Species #${p.species} did not exist in Generation 5."
        p.isEgg->"Egg records do not have a verified Gen 6 to Gen 5 PSE Bank mapping."
        p.heldItem!=0->"Held item #${p.heldItem} cannot be mapped safely because Gen 6 and Gen 5 item IDs are not interchangeable. Remove it in the Gen 6 source and deposit the Pokémon again."
        !gen5ToGen6FormSupported(p.species,p.form)->"Form ${p.form} for species #${p.species} has no verified persistent Generation 5 mapping."
        p.ability !in 1..164->"Ability #${p.ability} did not exist in Generation 5."
        p.abilityNumber !in setOf(1,2,4)->"Ability slot ${p.abilityNumber} cannot be represented by native PK5."
        p.nature !in 0..24->"Nature ${p.nature} is outside Generation 5 limits."
        p.gender !in 0..2->"Gender value ${p.gender} cannot be represented by native PK5."
        p.moves.any{it !in 0..559}->"A move is outside the Generation 5 move catalogue."
        p.movePP.any{it !in 0..63}->"A move PP value is outside the native PK5 range."
        p.evs.any{it !in 0..255}||p.evs.sum()>510->"The EV data is not destination-valid for Generation 5."
        p.ivs.any{it !in 0..31}->"The IV data is invalid."
        p.friendship !in 0..255->"The active friendship value is invalid."
        p.currentHandler !in 0..1->"Current-handler value ${p.currentHandler} is not a verified native Gen 6 state."
        p.relearnMoves.any{it!=0}->"Relearn moves ${p.relearnMoves.filter{it!=0}.joinToString()} cannot be stored in PK5. Clear them in the Gen 6 source before depositing again."
        p.hyperTrainFlags!=0->"Hyper Training flags 0x${"%02X".format(p.hyperTrainFlags)} cannot be stored in Generation 5."
        p.markingValue !in 0..63->"Gen 6 marking value 0x${"%04X".format(p.markingValue)} is outside the six native one-bit markings."
        p.nickname.isBlank()||p.nickname.length>10||p.nickname.any{it=='\uFFFD'||it.code<0x20}->"The nickname cannot be represented exactly by the native Gen 5 text writer."
        p.otName.isBlank()||p.otName.length>7||p.otName.any{it=='\uFFFD'||it.code<0x20}->"The Original Trainer name cannot be represented exactly by the native Gen 5 text writer."
        p.language !in setOf(1,2,3,4,5,7,8)->"Language ID ${p.language} is not a verified Generation 5 language value."
        p.ball !in 1..25->"Ball ID ${p.ball} has no verified Generation 5 mapping on this route."
        p.metLevel !in 1..100->"The met level is outside Generation 5 limits."
        p.originGame !in 1..27->"Origin game ID ${p.originGame} has no documented Generation 5 conversion rule."
        !gen5ToGen6DateValid(p.metYear,p.metMonth,p.metDay)->"The met date is not a valid native date."
        !gen5ToGen6DateValid(p.eggYear,p.eggMonth,p.eggDay)->"The Egg date is not a valid native date."
        else->null
    }

    private fun gen5PidForAbilityAndShiny(p:PokemonEntry):Long{
        var pid=p.pid and 0xFFFFFFFFL
        val requiredParity=when(p.abilityNumber){1->0;2->1;else->-1}
        fun sv(v:Long)=p.tid xor p.sid xor (v.toInt() and 0xFFFF) xor ((v.toInt() ushr 16) and 0xFFFF)
        if(p.shiny){
            val low=(pid and 0xFFFF).toInt()
            val candidates=(0..7).toList()
            val target=candidates.firstOrNull{value->requiredParity<0||((p.tid xor p.sid xor low xor value) and 1)==requiredParity}?:0
            val high=p.tid xor p.sid xor low xor target
            pid=((high.toLong() and 0xFFFFL) shl 16) or (low.toLong() and 0xFFFFL)
        }else if(requiredParity>=0&&(((pid ushr 16).toInt() and 1)!=requiredParity)){
            pid=pid xor 0x00010000L
        }
        require((sv(pid)<8)==p.shiny){"PSE could not preserve the reviewed shiny state under Generation 5's PID threshold."}
        require(requiredParity<0||(((pid ushr 16).toInt() and 1)==requiredParity)){"PSE could not encode the reviewed normal ability slot in the Generation 5 PID."}
        return pid and 0xFFFFFFFFL
    }

    private fun buildGen6ToGen5Pk5(raw:ByteArray,p:PokemonEntry,destination:ByteArray,plan:Gen6Gen5Plan):ByteArray{
        require(raw.size==PK6_STORED_SIZE){"The preserved Gen 6 Bank record has an unexpected size."}
        val profile=detectGen5Profile(destination)?:error("A valid Generation 5 destination save is required.")
        gen6ToGen5PreflightRejection(p)?.let{error(it)}
        require(!plan.legalised||(if(profile.sequel)plan.originGame in 22..23 else plan.originGame in 20..21)){"The chosen title mapping does not match the loaded Generation 5 save family."}
        require(!plan.legalised||p.originGame in 24..27){"Origin Legalise was requested for a record that does not need it."}
        val ups=gen6Pk6PpUps(raw);require(ups.all{it in 0..3}){"The PK6 PP-Up values could not be verified."};require((0..3).all{p.moves[it]!=0||(p.movePP[it]==0&&ups[it]==0)}){"An empty move slot contains PP or PP-Up data that PK5 cannot preserve safely."}
        val out=ByteArray(136);java.util.Arrays.fill(out,0x48,0x48+22,0xFF.toByte());java.util.Arrays.fill(out,0x68,0x68+16,0xFF.toByte())
        val pid=gen5PidForAbilityAndShiny(p);writeU32LE(out,0,pid);writeU16LE(out,0x08,p.species);writeU16LE(out,0x0A,0);writeU16LE(out,0x0C,p.tid);writeU16LE(out,0x0E,p.sid);writeU32LE(out,0x10,p.experience)
        out[0x14]=p.friendship.toByte();out[0x15]=p.ability.toByte();out[0x16]=gen6ToGen5Markings(p.markingValue).toByte();out[0x17]=p.language.toByte()
        for(i in 0..5)out[0x18+i]=p.evs[i].toByte()
        for(i in 0..3){writeU16LE(out,0x28+i*2,p.moves[i]);out[0x30+i]=(if(p.moves[i]==0)0 else p.movePP[i]).toByte();out[0x34+i]=(if(p.moves[i]==0)0 else ups[i]).toByte()}
        var ivWord=0L;for(i in 0..5)ivWord=ivWord or ((p.ivs[i].toLong() and 31L) shl(i*5));if(p.isNicknamed)ivWord=ivWord or 0x80000000L;writeU32LE(out,0x38,ivWord)
        out[0x40]=(((p.gender and 3) shl 1) or ((p.form and 0x1F) shl 3) or (if(p.fatefulEncounter)1 else 0)).toByte();out[0x41]=p.nature.toByte();out[0x42]=(if(p.abilityNumber==4)1 else 0).toByte()
        writeGen5String(out,0x48,22,p.nickname,10);out[0x5F]=plan.originGame.toByte();writeGen5String(out,0x68,16,p.otName,7)
        out[0x78]=p.eggYear.toByte();out[0x79]=p.eggMonth.toByte();out[0x7A]=p.eggDay.toByte();out[0x7B]=p.metYear.toByte();out[0x7C]=p.metMonth.toByte();out[0x7D]=p.metDay.toByte()
        writeU16LE(out,0x7E,0);writeU16LE(out,0x80,0);out[0x82]=(((p.pokerusStrain and 0xF) shl 4) or (p.pokerusDays and 0xF)).toByte();out[0x83]=p.ball.toByte();out[0x84]=((p.metLevel and 0x7F) or ((p.otGender and 1) shl 7)).toByte()
        val encrypted=encryptPk5(out);val q=parsePk5(encrypted,false)?:error("The converted PK5 could not be parsed.")
        require(q.checksumValid&&!q.isEgg&&q.species==p.species&&q.pid==pid&&q.tid==p.tid&&q.sid==p.sid&&q.nickname==p.nickname&&q.isNicknamed==p.isNicknamed&&q.otName==p.otName&&q.experience==p.experience&&q.ability==p.ability&&q.abilityNumber==p.abilityNumber&&q.nature==p.nature&&q.gender==p.gender&&q.form==p.form&&q.shiny==p.shiny&&q.fatefulEncounter==p.fatefulEncounter&&q.heldItem==0&&q.friendship==p.friendship&&q.currentHandler==0&&q.markingValue==gen6ToGen5Markings(p.markingValue)&&q.moves.contentEquals(p.moves)&&q.movePP.contentEquals(p.movePP)&&gen5Pk5PpUps(encrypted).contentEquals(ups)&&q.evs.contentEquals(p.evs)&&q.ivs.contentEquals(p.ivs)&&q.pokerusDays==p.pokerusDays&&q.pokerusStrain==p.pokerusStrain&&q.eggLocation==0&&q.metLocation==0&&q.ball==p.ball&&q.metLevel==p.metLevel&&q.otGender==p.otGender&&q.originGame==plan.originGame&&q.language==p.language&&q.eggYear==p.eggYear&&q.eggMonth==p.eggMonth&&q.eggDay==p.eggDay&&q.metYear==p.metYear&&q.metMonth==p.metMonth&&q.metDay==p.metDay){"The converted PK5 did not preserve every reviewed representable field."}
        return encrypted
    }

    private fun sameGen6ToGen5Pk5(a:PokemonEntry,b:PokemonEntry):Boolean=
        a.checksumValid&&b.checksumValid&&!a.isEgg&&!b.isEgg&&a.species==b.species&&a.pid==b.pid&&a.tid==b.tid&&a.sid==b.sid&&a.nickname==b.nickname&&a.isNicknamed==b.isNicknamed&&a.otName==b.otName&&a.experience==b.experience&&a.ability==b.ability&&a.abilityNumber==b.abilityNumber&&a.nature==b.nature&&a.gender==b.gender&&a.form==b.form&&a.shiny==b.shiny&&a.fatefulEncounter==b.fatefulEncounter&&a.heldItem==b.heldItem&&a.friendship==b.friendship&&a.markingValue==b.markingValue&&a.moves.contentEquals(b.moves)&&a.movePP.contentEquals(b.movePP)&&a.evs.contentEquals(b.evs)&&a.ivs.contentEquals(b.ivs)&&a.pokerusDays==b.pokerusDays&&a.pokerusStrain==b.pokerusStrain&&a.eggLocation==b.eggLocation&&a.metLocation==b.metLocation&&a.ball==b.ball&&a.metLevel==b.metLevel&&a.otGender==b.otGender&&a.originGame==b.originGame&&a.language==b.language&&a.eggYear==b.eggYear&&a.eggMonth==b.eggMonth&&a.eggDay==b.eggDay&&a.metYear==b.metYear&&a.metMonth==b.metMonth&&a.metDay==b.metDay

    private fun gen6ToGen5OmittedMetadata(raw:ByteArray,p:PokemonEntry):String{
        val d=decryptPk6IfNeeded(raw)
        fun hex(start:Int,end:Int)=d.copyOfRange(start,end).joinToString(" "){"%02X".format(it.toInt() and 0xFF)}
        val handler=readGen6String(d,0x78,26).ifBlank{"(empty)"}
        val ec=readU32LE(d,0)
        val handlerFriendship=d[0xA2].toInt() and 0xFF;val otFriendship=d[0xCA].toInt() and 0xFF
        return "encryption constant ${"%08X".format(ec)}; handler '$handler' (current-handler flag ${p.currentHandler}, friendship $handlerFriendship); OT friendship $otFriendship; country/region/console ${p.country}/${p.region}/${p.consoleRegion}; handler/affection/memory bytes ${hex(0x92,0xB0)}; OT memory bytes ${hex(0xCA,0xD1)}"
    }

    private fun prepareGen6ToGen5Transfer(bankFile:File,shown:PokemonEntry,requestedPlan:Gen6Gen5Plan?){
        val file=importedFile?:return showDialog("Gen 6 → Gen 5","Load a valid Generation 5 destination save first.")
        val openedUri=currentSourceUri;val openedLabel=currentSourceLabel
        fun bound()=importedFile?.absolutePath==file.absolutePath&&currentSourceUri==openedUri&&currentSourceLabel==openedLabel
        val destination=runCatching{file.readBytes()}.getOrNull()?:return showDialog("Gen 6 → Gen 5","The destination save could not be read.")
        val profile=detectGen5Profile(destination)?:return showDialog("Gen 6 → Gen 5","Load a valid Black, White, Black 2 or White 2 save first.")
        if(!bound()||!gen5ChecksumTableValid(destination,profile)||(0 until 24).any{!gen5BoxChecksumValid(destination,it,profile)})return showDialog("Gen 6 → Gen 5","The loaded Generation 5 destination did not pass native box and checksum-table validation.")
        val root=runCatching{bankDir().canonicalFile}.getOrNull()?:return;val selected=runCatching{bankFile.canonicalFile}.getOrNull()?:return
        if(selected.parentFile!=root||!selected.extension.equals("pk6",true))return showDialog("Gen 6 → Gen 5","The selected record is outside the Generation 6 PSE Bank.")
        val bank=runCatching{selected.readBytes()}.getOrNull()?:return showDialog("Gen 6 → Gen 5","The Bank record could not be read.")
        val source=if(bank.size==PK6_STORED_SIZE)parsePk6(bank,0,PK6_STORED_SIZE,false,721)else null
        if(source==null||!source.checksumValid||source.pid!=shown.pid||source.species!=shown.species)return showDialog("Gen 6 → Gen 5","The selected Bank record changed or failed its PK6 checksum.")
        gen6ToGen5PreflightRejection(source)?.let{return showDialog("Gen 6 → Gen 5 blocked","$it\n\nThe Bank record and destination were left unchanged.")}
        val plan=if(source.originGame<=23)Gen6Gen5Plan(source.originGame,"preserve origin ID ${source.originGame}",false)else requestedPlan
        if(plan==null){
            val options=if(profile.sequel)arrayOf("Legalise origin as Pokémon Black 2 (22)","Legalise origin as Pokémon White 2 (23)") else arrayOf("Legalise origin as Pokémon Black (20)","Legalise origin as Pokémon White (21)")
            AlertDialog.Builder(this).setTitle("Choose documented Gen 5 origin mapping").setMessage("Origin game ID ${source.originGame} identifies a Gen 6 title and cannot exist in PK5. This explicit PSE Legalise choice records the loaded Gen 5 title family; it is not official provenance. No other field is changed by this choice.").setItems(options){_,which->val id=if(profile.sequel)22+which else 20+which;prepareGen6ToGen5Transfer(bankFile,shown,Gen6Gen5Plan(id,options[which],true))}.setNegativeButton("Cancel",null).show()
            return
        }
        if(plan.legalised&&source.originGame !in 24..27)return showDialog("Gen 6 → Gen 5 blocked","The requested origin conversion does not apply to this record.")
        val pk5=try{buildGen6ToGen5Pk5(bank,source,destination,plan)}catch(e:Exception){return showDialog("Gen 6 → Gen 5 blocked",(e.message?:"No safe native mapping is available.")+"\n\nNothing was changed.")}
        if(!bound()||!runCatching{file.readBytes().contentEquals(destination)&&selected.readBytes().contentEquals(bank)}.getOrDefault(false))return showDialog("Gen 6 → Gen 5","The destination or Bank record changed during preparation. Nothing was changed.")
        val converted=parsePk5(pk5,false)?:return showDialog("Gen 6 → Gen 5","The prepared PK5 could not be re-read.")
        val omitted=gen6ToGen5OmittedMetadata(bank,source);val prepared=Gen6Gen5Prepared(selected,bank,source,destination,plan,pk5,converted,file,openedUri,openedLabel,omitted)
        val pidNote=if(source.pid==converted.pid)"PID remains ${"%08X".format(source.pid)}." else "PID changes ${"%08X".format(source.pid)} → ${"%08X".format(converted.pid)} only to preserve ${if(source.shiny)"shiny" else "non-shiny"} state and the normal ability slot under Gen 5 PID rules."
        val originNote=if(plan.legalised)"Origin ${source.originGame} → ${plan.originGame}: ${plan.originLabel}. This is an explicit PSE Legalise conversion, not official provenance." else "Origin ID ${source.originGame} is preserved."
        val preview="PSE conversion, not an official backward transfer or provenance claim.\n\nPreserved: species/form, TID/SID, nickname and OT, EXP, ability/slot, nature, gender, shiny state, moves/PP/PP Ups, IVs, EVs, active friendship, Pokérus, Ball, met level, dates and fateful marker.\n\nReviewed Gen 5 differences:\n• $pidNote\n• $originNote\n• Gen 6 and Gen 5 use the same six one-bit markings, so 0x${"%02X".format(source.markingValue)} is preserved exactly.\n• Met location #${source.metLocation} and Egg location #${source.eggLocation} become explicit unspecified location 0 because the catalogs are not interchangeable.\n• PK5 has one friendship value, so active friendship ${source.friendship} is retained; separate OT/handler friendship cannot both be represented.\n• PK5 has no current handler, relearn-move, geography, affection or memory fields. Relearn moves and Hyper Training must already be empty. Omitted exact PK6 metadata: $omitted.\n\nHeld items and unsupported species, forms, moves or fields are blocked instead of discarded. The PK6 Bank record remains until the native PK5, Pokédex, box CRCs, checksum table and persisted reopen all verify. Round trips are not promised lossless."
        AlertDialog.Builder(this).setTitle("${source.nickname.ifBlank{"Pokémon #${source.species}"}} • Gen 6 → Gen 5").setMessage(preview).setNegativeButton("Cancel",null).setPositiveButton("Choose Gen 5 destination"){_,_->chooseGen6ToGen5Destination(prepared)}.show()
    }

    private fun gen6ToGen5StillBound(p:Gen6Gen5Prepared):Boolean=
        importedFile?.absolutePath==p.destinationFile.absolutePath&&currentSourceUri==p.sourceUri&&currentSourceLabel==p.sourceLabel&&runCatching{p.destinationFile.readBytes().contentEquals(p.destination)&&p.bankFile.readBytes().contentEquals(p.bankBytes)}.getOrDefault(false)

    private fun chooseGen6ToGen5Destination(p:Gen6Gen5Prepared){
        if(!gen6ToGen5StillBound(p))return showDialog("Gen 6 → Gen 5","The destination or Bank record changed. Reopen PSE Bank.")
        val empty=(0 until 720).filter{val o=0x00400+(it/30)*0x1000+(it%30)*136;parsePk5(p.destination.copyOfRange(o,o+136),false)==null}
        if(empty.isEmpty())return showDialog("Gen 6 → Gen 5","All 720 native Generation 5 PC slots are occupied.")
        val first=empty.first();AlertDialog.Builder(this).setTitle("Choose native Gen 5 destination").setMessage("The reviewed PK5 will be written to one empty slot. PSE will update only that slot, required Pokédex flags, the box CRC and native checksum table.").setItems(arrayOf("First Empty • Box ${first/30+1} • Slot ${first%30+1}","Choose Box / Slot")){_,which->if(!gen6ToGen5StillBound(p))showDialog("Gen 6 → Gen 5","The destination or Bank record changed. Reopen PSE Bank.")else if(which==0)transferGen6BankToGen5(p,first)else showGen6ToGen5BoxPicker(p)}.setNegativeButton("Cancel",null).show()
    }

    private fun showGen6ToGen5BoxPicker(p:Gen6Gen5Prepared){
        if(!gen6ToGen5StillBound(p))return showDialog("Gen 6 → Gen 5","The destination or Bank record changed. Reopen PSE Bank.")
        val boxes=(0 until 24).filter{box->(0 until 30).any{slot->val o=0x00400+box*0x1000+slot*136;parsePk5(p.destination.copyOfRange(o,o+136),false)==null}}
        AlertDialog.Builder(this).setTitle("Choose Gen 5 destination box").setItems(boxes.map{"Box ${it+1}"}.toTypedArray()){_,which->val box=boxes[which];val slots=(0 until 30).filter{slot->val o=0x00400+box*0x1000+slot*136;parsePk5(p.destination.copyOfRange(o,o+136),false)==null};AlertDialog.Builder(this).setTitle("Box ${box+1} • choose slot").setItems(slots.map{"Slot ${it+1}"}.toTypedArray()){_,slotIndex->transferGen6BankToGen5(p,box*30+slots[slotIndex])}.setNegativeButton("Cancel",null).show()}.setNegativeButton("Cancel",null).show()
    }

    private fun retainGen6ToGen5SafetyBackup(file:File,expected:ByteArray){
        val profile=detectGen5Profile(expected)?:error("The Generation 5 destination recovery backup has no valid native layout.");require(file.isFile&&file.readBytes().contentEquals(expected)&&gen5ChecksumTableValid(expected,profile)&&(0 until 24).all{gen5BoxChecksumValid(expected,it,profile)}){"The Generation 5 destination recovery backup did not verify."}
        val names=keptBackupNames().apply{add(file.name)};val prefs=getSharedPreferences("pse_backup_state",MODE_PRIVATE);require(prefs.edit().putStringSet("kept",names).commit()){"The recovery backup Keep pin could not be saved. Nothing may be written."};require(isBackupKept(file)&&file.readBytes().contentEquals(expected)){"The retained recovery backup or Keep pin could not be rechecked."}
    }

    private fun transferGen6BankToGen5(p:Gen6Gen5Prepared,target:Int){
        if(!gen6ToGen5StillBound(p))return showDialog("Gen 6 → Gen 5","The destination or Bank record changed. Reopen PSE Bank.")
        val file=p.destinationFile;val original=runCatching{file.readBytes()}.getOrNull()?:return;var writeStarted=false;var deleteAttempted=false;var backup:File?=null;var bankRecovery:File?=null
        try{
            require(original.contentEquals(p.destination)&&target in 0 until 720){"The prepared Generation 5 destination changed or the selected slot is invalid."};val profile=detectGen5Profile(original)?:error("The destination is no longer a valid Generation 5 save.");require(gen5ChecksumTableValid(original,profile)&&(0 until 24).all{gen5BoxChecksumValid(original,it,profile)}){"The destination box checksums or checksum table changed."}
            val bank=p.bankFile.readBytes();require(bank.contentEquals(p.bankBytes)){"The Gen 6 Bank record changed."};val source=parsePk6(bank,0,PK6_STORED_SIZE,false,721)?:error("The PK6 Bank record is invalid.");require(source.checksumValid&&source.pid==p.source.pid&&source.species==p.source.species&&source.tid==p.source.tid&&source.sid==p.source.sid){"The selected source no longer matches the reviewed Pokémon."}
            val pk5=buildGen6ToGen5Pk5(bank,source,original,p.plan);require(pk5.contentEquals(p.pk5)){"The reviewed PK5 conversion changed before writing."};val box=target/30;val slot=target%30;val offset=0x00400+box*0x1000+slot*136;require(parsePk5(original.copyOfRange(offset,offset+136),false)==null){"The selected Generation 5 slot is no longer empty."}
            val save=original.copyOf();pk5.copyInto(save,offset);val staged=parsePk5(save.copyOfRange(offset,offset+136),false)?:error("The staged PK5 could not be parsed.");require(sameGen6ToGen5Pk5(staged,p.converted)&&gen5Pk5PpUps(pk5).contentEquals(gen6Pk6PpUps(bank))){"The staged PK5 differs from the reviewed conversion."}
            val allowed=HashSet<Int>();for(i in offset until offset+136)allowed.add(i);val bit=staged.species-1;val maskByte=bit/8;val dex=profile.pokedexOffset;allowed.add(dex+0x08+maskByte);for(region in 0..3){allowed.add(dex+0x5C+region*0x54+maskByte);allowed.add(dex+0x1AC+region*0x54+maskByte)};if(staged.species<=493){val langBit=bit*7+1;allowed.add(dex+(if(profile.sequel)0x328 else 0x320)+langBit/8)};val (_,dexLocal,dexMirror)=gen5PokedexBlock(profile);for(i in 0..1){allowed.add(dexLocal+i);allowed.add(dexMirror+i);allowed.add(0x00400+box*0x1000+0x0FF2+i);allowed.add(profile.checksumTable+2+box*2+i);allowed.add(profile.checksumBlockChecksumOffset+i)}
            registerGen1ToGen5Pokedex(save,profile,staged);updateGen5BoxChecksum(save,box,profile);require(save.indices.all{it in allowed||save[it]==original[it]}){"The conversion changed data outside the selected PK5, required Pokédex flags, box CRC and checksum table."};require(gen5BoxChecksumValid(save,box,profile)&&gen5ChecksumTableValid(save,profile)&&gen1ToGen5DexRegistered(save,profile,staged)){"The staged Generation 5 save failed storage, Pokédex or checksum verification."}
            val recovery=File.createTempFile(backupGameName(file)+"_PreGen6ToGen5_",".backup",backupsDir());backup=recovery;recovery.writeBytes(original);require(recovery.readBytes().contentEquals(original)){"The Generation 5 recovery backup did not verify."};retainGen6ToGen5SafetyBackup(recovery,original)
            val bankCopy=File.createTempFile("PSE_G6ToG5_BankRecovery_",".tmp",bankDir());bankRecovery=bankCopy;bankCopy.writeBytes(p.bankBytes);require(bankCopy.readBytes().contentEquals(p.bankBytes)){"The Bank recovery snapshot did not verify."};require(gen6ToGen5StillBound(p)&&file.readBytes().contentEquals(original)&&isBackupKept(recovery)){"The source identity, snapshots or retained backup changed before writing."}
            writeStarted=true;file.writeBytes(save);val written=file.readBytes();require(written.contentEquals(save)&&written.indices.all{it in allowed||written[it]==original[it]}){"The persisted Generation 5 save differs from the reviewed write scope."};val wp=detectGen5Profile(written)?:error("The persisted Generation 5 save could not be reopened.");require(gen5BoxChecksumValid(written,box,wp)&&gen5ChecksumTableValid(written,wp)&&gen1ToGen5DexRegistered(written,wp,staged)){"The persisted Generation 5 save failed checksum or Pokédex validation."};val actual=written.copyOfRange(offset,offset+136);val reopened=parsePk5(actual,false);require(actual.contentEquals(pk5)&&reopened!=null&&sameGen6ToGen5Pk5(reopened,p.converted)&&gen5Pk5PpUps(actual).contentEquals(gen6Pk6PpUps(bank))){"The exact converted PK5 did not persist after reopening."}
            require(p.bankFile.readBytes().contentEquals(p.bankBytes)&&file.readBytes().contentEquals(save)){"The Bank record or destination identity changed before cleanup."};deleteAttempted=true;require(p.bankFile.delete()&&!p.bankFile.exists()){"The Gen 6 Bank record could not be removed after destination verification."};require(file.readBytes().contentEquals(save)){"The destination changed after Bank cleanup."};runCatching{bankCopy.delete()}
        }catch(e:Exception){
            val bankRestored=runCatching{if(deleteAttempted&&!p.bankFile.exists())p.bankFile.writeBytes(p.bankBytes);p.bankFile.readBytes().contentEquals(p.bankBytes)}.getOrDefault(false);val saveRestored=!writeStarted||runCatching{file.writeBytes(original);val restored=file.readBytes();val rp=detectGen5Profile(restored)?:error("The restored Generation 5 layout is invalid.");restored.contentEquals(original)&&gen5ChecksumTableValid(restored,rp)&&(0 until 24).all{gen5BoxChecksumValid(restored,it,rp)}}.getOrDefault(false);val recovery=if(bankRestored&&saveRestored)"The exact Generation 5 destination and Gen 6 Bank record were restored or kept and verified." else "Automatic recovery could not be fully verified. Keep the retained recovery backup and Bank recovery file for review.";showDialog("Gen 6 → Gen 5 failed",(e.message?:"Unknown error")+"\n\n"+recovery+(backup?.let{"\n\nRecovery backup: ${it.name}"}?:"")+(bankRecovery?.takeIf{it.exists()}?.let{"\nBank recovery: ${it.name}"}?:""));return
        }
        Toast.makeText(this,"PSE converted Gen 6 → Gen 5 to Box ${target/30+1} • Slot ${target%30+1} and verified",Toast.LENGTH_LONG).show();showBank()
    }

    private data class Gen6Gen7Prepared(
        val bankFile:File,val bankBytes:ByteArray,val source:PokemonEntry,val destination:ByteArray,
        val pk7:ByteArray,val converted:PokemonEntry,val destinationFile:File,val sourceUri:Uri?,
        val sourceLabel:String?,val markingNote:String,val originGame:Int,var submitted:Boolean=false,
        val sourceGeneration:Int=6,val trainer:TrainerData?=null,val gen4Meta:Gen3ToGen4Meta?=null
    )

    private fun genToGen7Title(p:Gen6Gen7Prepared)="Gen ${p.sourceGeneration} → Gen 7"

    private fun gen6ToGen7Markings(markings:Int):Pair<Int,String>{
        require(markings in 0..0x3F){"Marking value 0x${"%04X".format(markings)} is outside the six native PK6 one-bit markings."}
        var mapped=0;for(i in 0..5)if(((markings ushr i) and 1)!=0)mapped=mapped or (1 shl(i*2))
        return mapped to "native Gen 6 one-bit markings 0x${"%02X".format(markings)} → Gen 7 blue marking states 0x${"%04X".format(mapped)}"
    }

    private fun gen6ToGen7PreflightRejection(p:PokemonEntry,raw:ByteArray,originGame:Int=p.originGame):String?=when{
        !p.checksumValid->"The source PK6 checksum is invalid."
        raw.size!=PK6_STORED_SIZE->"The preserved Gen 6 Bank record has an unexpected size."
        decryptPk6IfNeeded(raw).let{(it[0x16].toInt() and 0xFF)!=0||(it[0x17].toInt() and 0xFF)!=0}->"PK6 Super Training Bag state is nonzero and PK7 has no field that can preserve it. Clear the active Bag and hit count before depositing again."
        p.species !in 1..721->"Species #${p.species} did not exist in Generation 6."
        p.isEgg->"Egg records do not have a verified PSE Bank Gen 6 to Gen 7 conversion."
        p.species==25&&p.form!=0->"Pikachu form ${p.form} is generation-specific and could change meaning in Gen 7; PSE will not relabel it silently."
        p.form !in 0..31->"Form ${p.form} is outside the native stored-Pokémon field."
        p.heldItem !in 0..775->"Held item #${p.heldItem} is outside the verified Generation 6 item catalogue."
        p.ability !in 1..191->"Ability #${p.ability} is outside the Generation 6 catalogue."
        p.abilityNumber !in setOf(1,2,4)->"Ability slot ${p.abilityNumber} is not a verified Generation 6 slot."
        p.nature !in 0..24->"Nature ${p.nature} is outside native limits."
        p.gender !in 0..2->"Gender value ${p.gender} is not destination-valid."
        p.moves.any{it !in 0..621}->"A move is outside the Generation 6 move catalogue."
        p.relearnMoves.any{it !in 0..621}->"A relearn move is outside the Generation 6 move catalogue."
        p.movePP.any{it !in 0..63}->"A move PP value is outside the native range."
        p.evs.any{it !in 0..255}||p.evs.sum()>510->"The EV data is not destination-valid."
        p.ivs.any{it !in 0..31}->"The IV data is invalid."
        p.friendship !in 0..255->"The active friendship value is invalid."
        p.currentHandler !in 0..1->"Current-handler value ${p.currentHandler} is not a verified native state."
        p.hyperTrainFlags!=0->"Reserved PK6 byte 0xDE contains 0x${"%02X".format(p.hyperTrainFlags)}. PSE will not reinterpret it as Gen 7 Hyper Training."
        runCatching{gen6ToGen7Markings(p.markingValue)}.exceptionOrNull()!=null->runCatching{gen6ToGen7Markings(p.markingValue)}.exceptionOrNull()?.message?:"The marking data cannot be converted safely."
        p.nickname.isBlank()||p.nickname.length>12||p.nickname.any{it=='\uFFFD'||it.code<0x20}->"The nickname is not valid native 3DS Pokémon text."
        p.otName.isBlank()||p.otName.length>12||p.otName.any{it=='\uFFFD'||it.code<0x20}->"The Original Trainer name is not valid native 3DS Pokémon text."
        p.language !in setOf(1,2,3,4,5,7,8)->"Language ID ${p.language} is not a verified Generation 6 value."
        p.ball !in 1..25->"Ball ID ${p.ball} is outside the Generation 6 catalogue."
        p.metLevel !in 1..100->"The met level is outside native limits."
        originGame !in 1..27->"Origin game ID $originGame is not representable by a verified Generation 6-origin PK6."
        !gen5ToGen6DateValid(p.metYear,p.metMonth,p.metDay)->"The met date is invalid."
        !gen5ToGen6DateValid(p.eggYear,p.eggMonth,p.eggDay)->"The Egg date is invalid."
        else->null
    }

    private fun sameGen6ToGen7Pk7(a:PokemonEntry,b:PokemonEntry):Boolean=
        a.checksumValid&&b.checksumValid&&!a.isEgg&&!b.isEgg&&a.species==b.species&&a.nickname==b.nickname&&a.isNicknamed==b.isNicknamed&&a.heldItem==b.heldItem&&a.tid==b.tid&&a.sid==b.sid&&a.experience==b.experience&&a.ability==b.ability&&a.abilityNumber==b.abilityNumber&&a.pid==b.pid&&a.nature==b.nature&&a.gender==b.gender&&a.form==b.form&&a.evs.contentEquals(b.evs)&&a.moves.contentEquals(b.moves)&&a.movePP.contentEquals(b.movePP)&&a.ivs.contentEquals(b.ivs)&&a.otName==b.otName&&a.friendship==b.friendship&&a.currentHandler==b.currentHandler&&a.pokerusDays==b.pokerusDays&&a.pokerusStrain==b.pokerusStrain&&a.shiny==b.shiny&&a.language==b.language&&a.fatefulEncounter==b.fatefulEncounter&&a.relearnMoves.contentEquals(b.relearnMoves)&&a.eggLocation==b.eggLocation&&a.metLocation==b.metLocation&&a.ball==b.ball&&a.metLevel==b.metLevel&&a.otGender==b.otGender&&a.originGame==b.originGame&&a.country==b.country&&a.region==b.region&&a.consoleRegion==b.consoleRegion&&a.eggYear==b.eggYear&&a.eggMonth==b.eggMonth&&a.eggDay==b.eggDay&&a.metYear==b.metYear&&a.metMonth==b.metMonth&&a.metDay==b.metDay&&a.hyperTrainFlags==b.hyperTrainFlags

    private fun buildGen6ToGen7Pk7(raw:ByteArray,p:PokemonEntry,originGame:Int=p.originGame):ByteArray{
        require(raw.size==PK6_STORED_SIZE){"The preserved Gen 6 Bank record has an unexpected size."};gen6ToGen7PreflightRejection(p,raw,originGame)?.let{error(it)}
        val ups=gen6Pk6PpUps(raw);require(ups.all{it in 0..3}){"The PK6 PP-Up values could not be verified."};require((0..3).all{p.moves[it]!=0||(p.movePP[it]==0&&ups[it]==0)}){"An empty move slot contains PP or PP-Up data that cannot be reviewed safely."}
        val sourcePlain=decryptPk6IfNeeded(raw);val targetPlain=sourcePlain.copyOf();val markings=gen6ToGen7Markings(p.markingValue).first;writeU16LE(targetPlain,0x16,markings);targetPlain[0x2A]=0;targetPlain[0xDE]=0;targetPlain[0xDF]=originGame.toByte();updatePk6Checksum(targetPlain)
        require(targetPlain.indices.all{it in setOf(0x06,0x07,0x16,0x17,0x2A,0xDE,0xDF)||targetPlain[it]==sourcePlain[it]}){"The PK7 conversion changed an unreviewed stored-Pokémon field."}
        val encrypted=encryptPk6(targetPlain);val q=parsePk6(encrypted,0,PK6_STORED_SIZE,false,807)?:error("The converted PK7 could not be parsed.")
        require(sameGen6ToGen7Pk7(q,p.copy(markingValue=markings,hyperTrainFlags=0,originGame=originGame))&&q.markingValue==markings&&gen6Pk6PpUps(encrypted).contentEquals(ups)){"The converted PK7 did not preserve every reviewed field."}
        return encrypted
    }

    private fun prepareGen6ToGen7Transfer(bankFile:File,shown:PokemonEntry,requestedOriginGame:Int?=null){
        val file=importedFile?:return showDialog("Gen 6 → Gen 7","Load a valid Sun, Moon, Ultra Sun or Ultra Moon destination first.");val openedUri=currentSourceUri;val openedLabel=currentSourceLabel
        fun bound()=importedFile?.absolutePath==file.absolutePath&&currentSourceUri==openedUri&&currentSourceLabel==openedLabel
        val destination=runCatching{file.readBytes()}.getOrNull()?:return showDialog("Gen 6 → Gen 7","The destination save could not be read.");val checks=validateGen7CoreChecksums(destination);if(!bound()||generationForSize(destination.size)!=7||!checks.first)return showDialog("Gen 6 → Gen 7",checks.second)
        val root=runCatching{bankDir().canonicalFile}.getOrNull()?:return;val selected=runCatching{bankFile.canonicalFile}.getOrNull()?:return;if(selected.parentFile!=root||!selected.extension.equals("pk6",true))return showDialog("Gen 6 → Gen 7","The selected record is outside the Generation 6 PSE Bank.")
        val bank=runCatching{selected.readBytes()}.getOrNull()?:return showDialog("Gen 6 → Gen 7","The Bank record could not be read.");val source=if(bank.size==PK6_STORED_SIZE)parsePk6(bank,0,PK6_STORED_SIZE,false,721)else null
        if(source==null||!source.checksumValid||source.pid!=shown.pid||source.species!=shown.species||source.tid!=shown.tid||source.sid!=shown.sid)return showDialog("Gen 6 → Gen 7","The selected Bank record changed or failed its PK6 checksum.");val needsLegalise=source.originGame !in 1..27
        val originGame=requestedOriginGame?:source.originGame
        if(needsLegalise&&requestedOriginGame==null){
            val ids=listOf(24,25,26,27)
            AlertDialog.Builder(this).setTitle("Choose Gen 6 origin mapping")
                .setMessage("Origin game ID ${source.originGame} is outside the verified Gen 6-origin range. Choose a Gen 6 origin ID for PK7. This is an explicit PSE Legalise choice, not verified history; cancelling leaves the Bank record and destination unchanged.")
                .setItems(ids.map{"Origin game ID $it"}.toTypedArray()){_,which->prepareGen6ToGen7Transfer(bankFile,shown,ids[which])}
                .setNegativeButton("Cancel",null).show()
            return
        }
        if(needsLegalise&&originGame !in 24..27)return showDialog("Gen 6 → Gen 7 blocked","Choose a valid Gen 6 origin ID.")
        gen6ToGen7PreflightRejection(source,bank,originGame)?.let{return showDialog("Gen 6 → Gen 7 blocked","$it\n\nThe PK6 Bank record and Gen 7 destination were left unchanged.")}
        val pk7=try{buildGen6ToGen7Pk7(bank,source,originGame)}catch(e:Exception){return showDialog("Gen 6 → Gen 7 blocked",(e.message?:"No safe native PK7 mapping is available.")+"\n\nNothing was changed.")};if(!bound()||!runCatching{file.readBytes().contentEquals(destination)&&selected.readBytes().contentEquals(bank)}.getOrDefault(false))return showDialog("Gen 6 → Gen 7","The destination or Bank record changed during preparation. Nothing was changed.")
        val converted=parsePk6(pk7,0,PK6_STORED_SIZE,false,807)?:return showDialog("Gen 6 → Gen 7","The prepared PK7 could not be re-read.");val markingNote=gen6ToGen7Markings(source.markingValue).second;val prepared=Gen6Gen7Prepared(selected,bank,source,destination,pk7,converted,file,openedUri,openedLabel,markingNote,originGame)
        val originNote=if(needsLegalise)"Origin Legalise: game ID ${source.originGame} → ${originGame}; this is a user-selected provenance change, not verified history." else "Origin game ID ${originGame} is preserved."
        val preview="PSE Bank conversion into native PK7 storage; this does not claim an official Pokémon Bank transaction or provenance.\n\nPreserved exactly: species/form, encryption constant, PID, OT/TID/SID, nickname, held item, EXP, ability/slot, nature, gender, shiny state, moves/PP/PP Ups/relearn moves, IVs, EVs, friendship and handler data, Pokérus, encounter locations, Ball, met level, origin game, language, dates, geography, memories and all other stored metadata.\n\nReviewed format differences:\n• $markingNote.\n• $originNote\n• PK6 Super Training Bag state must be empty because PK7 uses bytes 0x16–0x17 for markings; nonzero Bag state is blocked rather than discarded.\n• Gen 7 Resort state and Hyper Training start empty. Nonzero reserved PK6 byte 0xDE is blocked rather than reinterpreted.\n• Generation-specific Pikachu forms, Eggs, invalid catalogue values and unsupported metadata are blocked with their exact reason.\n\nThe user chooses one empty native Gen 7 slot. PSE then updates that exact PK7, required Pokédex flags, Box/Pokédex block CRCs and the native save signature. A retained verified recovery backup is mandatory. The PK6 Bank record is removed only after persisted reopen verification; either side is restored on failure."
        AlertDialog.Builder(this).setTitle("${source.nickname.ifBlank{"Pokémon #${source.species}"}} • Gen 6 → Gen 7").setMessage(preview).setNegativeButton("Cancel",null).setPositiveButton("Choose Gen 7 destination"){_,_->chooseGen6ToGen7Destination(prepared)}.show()
    }

    private fun gen6ToGen7SnapshotsMatch(p:Gen6Gen7Prepared,requireOpen:Boolean=true):Boolean=
        (!requireOpen||!p.submitted)&&importedFile?.absolutePath==p.destinationFile.absolutePath&&currentSourceUri==p.sourceUri&&currentSourceLabel==p.sourceLabel&&runCatching{p.destinationFile.readBytes().contentEquals(p.destination)&&p.bankFile.readBytes().contentEquals(p.bankBytes)}.getOrDefault(false)

    private fun chooseGen6ToGen7Destination(p:Gen6Gen7Prepared){
        val title=genToGen7Title(p)
        if(!gen6ToGen7SnapshotsMatch(p))return showDialog(title,"The destination or Bank record changed. Reopen PSE Bank.")
        val info=boxStorageInfo(p.destination)?:return
        val empty=(0 until info.second).filter{parsePk6(p.destination,info.first+it*PK6_STORED_SIZE,PK6_STORED_SIZE,false,807)==null}
        if(empty.isEmpty())return showDialog(title,"All native Generation 7 PC slots are occupied.")
        val first=empty.first()
        AlertDialog.Builder(this).setTitle("Choose native Gen 7 destination")
            .setMessage("The reviewed PK7 will be written to one empty slot. PSE will update only that slot, required Pokédex flags, native block CRCs and the save signature.")
            .setItems(arrayOf("First Empty • Box ${first/30+1} • Slot ${first%30+1}","Choose Box / Slot")){_,which->
                if(!gen6ToGen7SnapshotsMatch(p))showDialog(title,"The destination or Bank record changed. Reopen PSE Bank.")
                else if(which==0)transferGen6BankToGen7(p,first)else showGen6ToGen7BoxPicker(p)
            }.setNegativeButton("Cancel",null).show()
    }

    private fun showGen6ToGen7BoxPicker(p:Gen6Gen7Prepared){
        val title=genToGen7Title(p)
        if(!gen6ToGen7SnapshotsMatch(p))return showDialog(title,"The destination or Bank record changed. Reopen PSE Bank.")
        val info=boxStorageInfo(p.destination)?:return
        val boxes=(0 until info.second/30).filter{box->(0 until 30).any{slot->
            parsePk6(p.destination,info.first+(box*30+slot)*PK6_STORED_SIZE,PK6_STORED_SIZE,false,807)==null
        }}
        if(boxes.isEmpty())return showDialog(title,"All native Generation 7 PC boxes are full.")
        AlertDialog.Builder(this).setTitle("Choose Gen 7 destination box").setItems(boxes.map{"Box ${it+1}"}.toTypedArray()){_,which->
            val box=boxes[which];val slots=(0 until 30).filter{slot->
                parsePk6(p.destination,info.first+(box*30+slot)*PK6_STORED_SIZE,PK6_STORED_SIZE,false,807)==null
            }
            AlertDialog.Builder(this).setTitle("Box ${box+1} • choose slot").setItems(slots.map{"Slot ${it+1}"}.toTypedArray()){_,slotIndex->
                transferGen6BankToGen7(p,box*30+slots[slotIndex])
            }.setNegativeButton("Cancel",null).show()
        }.setNegativeButton("Cancel",null).show()
    }

    private fun transferGen6BankToGen7(p:Gen6Gen7Prepared,target:Int){
        val title=genToGen7Title(p)
        if(!gen6ToGen7SnapshotsMatch(p)||p.submitted)return showDialog(title,"The destination or Bank record changed, or this transfer was already submitted. Reopen PSE Bank.")
        val file=p.destinationFile;val fresh=runCatching{file.readBytes()}.getOrNull()?:return showDialog(title,"The destination save could not be read. Nothing was changed.");p.submitted=true;var writeStarted=false;var deleteAttempted=false;var backup:File?=null;var bankRecovery:File?=null
        try{
            require(fresh.contentEquals(p.destination)&&generationForSize(fresh.size)==7){"The prepared Gen 7 destination changed."};val checks=validateGen7CoreChecksums(fresh);require(checks.first){checks.second};val info=boxStorageInfo(fresh)?:error("PSE could not resolve native Gen 7 PC storage.");require(target in 0 until info.second){"The selected Gen 7 slot is invalid."};val off=info.first+target*PK6_STORED_SIZE;require(parsePk6(fresh,off,PK6_STORED_SIZE,false,807)==null){"The selected Gen 7 slot is no longer empty."}
            val bank=p.bankFile.readBytes();require(bank.contentEquals(p.bankBytes)){"The Gen ${p.sourceGeneration} Bank record changed."}
            val sourcePpUps:IntArray
            val pk7=when(p.sourceGeneration){
                4->{
                    val source=parsePk4(bank,false)?:error("The PK4 Bank record is invalid.")
                    require(source.checksumValid&&sameGen4ToGen5Pk5(source,p.source)){"The selected PK4 no longer matches the reviewed Pokémon."}
                    val meta=p.gen4Meta?:error("The reviewed Generation 5 ability mapping is unavailable.")
                    val trainer=p.trainer?:error("The reviewed Generation 7 trainer identity is unavailable.")
                    val pk5=buildGen4ToGen5Pk5(bank,source,fresh,meta,false)
                    val bridge5=parsePk5(pk5,false)?:error("The verified PK5 bridge could not be reopened.")
                    val pk6=buildGen5ToGen6Pk6(pk5,bridge5,fresh,trainer,7)
                    val bridge6=parsePk6(pk6,0,PK6_STORED_SIZE,false,721)?:error("The verified PK6 bridge could not be reopened.")
                    sourcePpUps=gen4Pk4PpUps(bank)
                    buildGen6ToGen7Pk7(pk6,bridge6,p.originGame)
                }
                5->{
                    val source=parsePk5(bank,false)?:error("The PK5 Bank record is invalid.")
                    require(source.checksumValid&&sameGen4ToGen5Pk5(source,p.source)){
                        "The selected PK5 no longer matches the reviewed Pokémon."
                    }
                    val trainer=p.trainer?:error("The reviewed Generation 7 trainer identity is unavailable.")
                    val pk6=buildGen5ToGen6Pk6(bank,source,fresh,trainer,7)
                    val bridge6=parsePk6(pk6,0,PK6_STORED_SIZE,false,721)
                        ?:error("The verified PK6 bridge could not be reopened.")
                    sourcePpUps=gen5Pk5PpUps(bank)
                    buildGen6ToGen7Pk7(pk6,bridge6,p.originGame)
                }
                6->{
                    val source=parsePk6(bank,0,PK6_STORED_SIZE,false,721)?:error("The PK6 Bank record is invalid.")
                    require(source.checksumValid&&source.pid==p.source.pid&&source.species==p.source.species&&source.tid==p.source.tid&&source.sid==p.source.sid){"The selected source no longer matches the reviewed Pokémon."}
                    sourcePpUps=gen6Pk6PpUps(bank)
                    buildGen6ToGen7Pk7(bank,source,p.originGame)
                }
                else->error("This Generation ${p.sourceGeneration} to Generation 7 route is not supported.")
            }
            require(pk7.contentEquals(p.pk7)){"The reviewed PK7 conversion changed before writing."}
            val work=fresh.copyOf();pk7.copyInto(work,off);val staged=parsePk6(work,off,PK6_STORED_SIZE,false,807)?:error("The staged PK7 could not be parsed.")
            require(sameGen6ToGen7Pk7(staged,p.converted)&&staged.markingValue==p.converted.markingValue&&gen6Pk6PpUps(pk7).contentEquals(sourcePpUps)){"The staged PK7 differs from the reviewed conversion."}
            val allowed=HashSet<Int>();for(i in off until off+PK6_STORED_SIZE)allowed.add(i);val bit=staged.species-1;val byte=bit ushr 3;val dexBase=if(work.size==SIZE_G7_SM)0x02A00 else 0x02C00;allowed.add(dexBase+0x88+byte);val shift=staged.gender.coerceIn(0,1) or ((if(staged.shiny)1 else 0) shl 1);for(plane in listOf(shift,4,5,6,7))allowed.add(dexBase+0xF0+plane*0x8C+byte);var lang=staged.language;if(lang in 1..10&&lang!=6){if(lang>=7)lang--;lang--;allowed.add(dexBase+0x550+((bit*9+lang) ushr 3))};for(id in intArrayOf(6,14)){val c=gen7ChecksumOffset(work,id);allowed.add(c);allowed.add(c+1)};val signature=if(work.size==SIZE_G7_USUM)0x6C100 else 0x6BB00;for(i in signature until signature+0x80)allowed.add(i)
            registerGen7Dex(work,staged.species,staged.form,staged.gender,staged.shiny,staged.language);updateGen7SaveBlockChecksum(work,14,info.first,info.second*PK6_STORED_SIZE);val dexInfo=gen7BlockInfo(work,6)?:error("Gen 7 Pokédex block layout is unavailable.");updateGen7SaveBlockChecksum(work,6,dexInfo.first,dexInfo.second);finalizeGen7Save(work);require(work.indices.all{it in allowed||work[it]==fresh[it]}){"The conversion changed data outside the reviewed PK7, Pokédex flags, block CRCs and save signature."};require(gen7DexRegistered(work,staged)){"The staged Gen 7 Pokédex registration failed."};val stagedChecks=validateGen7CoreChecksums(work);require(stagedChecks.first){stagedChecks.second}
            val recovery=File.createTempFile(backupGameName(file)+"_PreGen${p.sourceGeneration}ToGen7_",".backup",backupsDir());backup=recovery;recovery.writeBytes(fresh);require(recovery.readBytes().contentEquals(fresh)){"The exact Gen 7 recovery backup did not verify."};retainGen2ToGen7SafetyBackup(recovery,fresh);val bankCopy=File.createTempFile("PSE_G${p.sourceGeneration}ToG7_BankRecovery_",".tmp",bankDir());bankRecovery=bankCopy;bankCopy.writeBytes(p.bankBytes);require(bankCopy.readBytes().contentEquals(p.bankBytes)){"The Bank recovery snapshot did not verify."};require(gen6ToGen7SnapshotsMatch(p,false)&&isBackupKept(recovery)&&file.readBytes().contentEquals(fresh)){"The source identity, snapshots or retained backup changed before writing."}
            writeStarted=true;file.writeBytes(work);val written=file.readBytes();require(written.contentEquals(work)&&written.indices.all{it in allowed||written[it]==fresh[it]}){"The persisted Gen 7 save differs from the reviewed write scope."};val actual=written.copyOfRange(off,off+PK6_STORED_SIZE);val reopened=parsePk6(actual,0,PK6_STORED_SIZE,false,807)?:error("The persisted PK7 could not be parsed.");require(actual.contentEquals(pk7)&&sameGen6ToGen7Pk7(reopened,p.converted)&&gen6Pk6PpUps(actual).contentEquals(sourcePpUps)&&gen7DexRegistered(written,reopened)){"The exact converted PK7 or Pokédex registration did not persist."};val writtenChecks=validateGen7CoreChecksums(written);require(writtenChecks.first){writtenChecks.second}
            require(p.bankFile.readBytes().contentEquals(p.bankBytes)&&file.readBytes().contentEquals(work)){"The Bank record or destination changed before cleanup."};deleteAttempted=true;require(p.bankFile.delete()&&!p.bankFile.exists()){"The Gen ${p.sourceGeneration} Bank record could not be removed after destination verification."};require(file.readBytes().contentEquals(work)){"The destination changed after Bank cleanup."};runCatching{bankCopy.delete()}
        }catch(e:Exception){
            val bankRestored=runCatching{if(deleteAttempted&&!p.bankFile.exists())p.bankFile.writeBytes(p.bankBytes);p.bankFile.readBytes().contentEquals(p.bankBytes)}.getOrDefault(false);val destinationRestored=!writeStarted||runCatching{file.writeBytes(fresh);val restored=file.readBytes();restored.contentEquals(fresh)&&validateGen7CoreChecksums(restored).first}.getOrDefault(false);val recovery=if(bankRestored&&destinationRestored)"The exact Gen 7 destination and Gen ${p.sourceGeneration} Bank record were restored or kept and verified." else "Automatic recovery could not be fully verified. Keep the retained recovery backup and Bank recovery file for review.";showDialog("$title failed",(e.message?:"Unknown error")+"\n\n"+recovery+(backup?.let{"\n\nRecovery backup: ${it.name}"}?:"")+(bankRecovery?.takeIf{it.exists()}?.let{"\nBank recovery: ${it.name}"}?:""));return
        }
        Toast.makeText(this,"PSE transferred Gen ${p.sourceGeneration} → Gen 7 to Box ${target/30+1} • Slot ${target%30+1} and verified",Toast.LENGTH_LONG).show();showBank()
    }

    private data class Gen7Gen6Prepared(
        val bankFile:File,val bankBytes:ByteArray,val source:PokemonEntry,val destination:ByteArray,
        val pk6:ByteArray,val converted:PokemonEntry,val destinationFile:File,val sourceUri:Uri?,
        val sourceLabel:String?,val markingNote:String,val originGame:Int,var submitted:Boolean=false
    )

    private val gen7OnlyOrReinterpretedForms=setOf(19,20,25,26,27,28,37,38,50,51,52,53,74,75,76,88,89,103,105,658,718)

    private fun gen7ToGen6Markings(markings:Int):Pair<Int,String>{
        require(markings in 0..0x0FFF){"Marking value 0x${"%04X".format(markings)} is outside the six native PK7 two-bit markings."}
        var mapped=0
        for(i in 0..5){
            val state=(markings ushr(i*2)) and 3
            require(state in 0..1){"Marking ${i+1} uses ${if(state==2)"red" else "mixed blue/red"} state $state, which native PK6 cannot represent. Clear it or change it to blue before depositing again."}
            if(state==1)mapped=mapped or (1 shl i)
        }
        return mapped to "Gen 7 blue marking states 0x${"%04X".format(markings)} → native Gen 6 one-bit markings 0x${"%02X".format(mapped)}"
    }

    private fun gen7ToGen6PreflightRejection(p:PokemonEntry,raw:ByteArray,originGame:Int=p.originGame):String?{
        if(!p.checksumValid)return "The source PK7 checksum is invalid."
        if(raw.size!=PK6_STORED_SIZE)return "The preserved Gen 7 Bank record has an unexpected size."
        if(p.species !in 1..721)return "Species #${p.species} did not exist in Generation 6."
        if(p.isEgg)return "Egg records do not have a verified PSE Bank Gen 7 to Gen 6 conversion."
        if(p.form!=0&&p.species in gen7OnlyOrReinterpretedForms)return "Form ${p.form} for species #${p.species} was introduced or reinterpreted in Generation 7 and has no destination-valid native PK6 mapping."
        if(p.form !in 0..31)return "Form ${p.form} is outside the native stored-Pokémon field."
        if(p.heldItem !in 0..775)return "Held item #${p.heldItem} is outside the Generation 6 item catalogue."
        if(p.ability !in 1..191)return "Ability #${p.ability} did not exist in Generation 6."
        if(p.abilityNumber !in setOf(1,2,4))return "Ability slot ${p.abilityNumber} is not a verified Generation 6 slot."
        if(p.nature !in 0..24)return "Nature ${p.nature} is outside native limits."
        if(p.gender !in 0..2)return "Gender value ${p.gender} is not destination-valid."
        if(p.moves.any{it !in 0..621})return "A move is outside the Generation 6 move catalogue."
        if(p.relearnMoves.any{it !in 0..621})return "A relearn move is outside the Generation 6 move catalogue."
        if(p.movePP.any{it !in 0..63})return "A move PP value is outside the native range."
        if(p.evs.any{it !in 0..255}||p.evs.sum()>510)return "The EV data is not destination-valid."
        if(p.ivs.any{it !in 0..31})return "The IV data is invalid."
        if(p.friendship !in 0..255)return "The active friendship value is invalid."
        if(p.currentHandler !in 0..1)return "Current-handler value ${p.currentHandler} is not a verified native state."
        if(p.hyperTrainFlags!=0)return "Hyper Training flags 0x${"%02X".format(p.hyperTrainFlags)} do not exist in Generation 6. Clear them before depositing again."
        runCatching{gen7ToGen6Markings(p.markingValue)}.exceptionOrNull()?.let{return it.message?:"The marking data cannot be converted safely."}
        if(p.nickname.isBlank()||p.nickname.length>12||p.nickname.any{it=='\uFFFD'||it.code<0x20})return "The nickname is not valid native 3DS Pokémon text."
        if(p.otName.isBlank()||p.otName.length>12||p.otName.any{it=='\uFFFD'||it.code<0x20})return "The Original Trainer name is not valid native 3DS Pokémon text."
        if(p.language !in setOf(1,2,3,4,5,7,8))return "Language ID ${p.language} is not a verified Generation 6 value."
        if(p.ball !in 1..25)return "Ball ID ${p.ball} did not exist in Generation 6."
        if(p.metLevel !in 1..100)return "The met level is outside native limits."
        if(originGame !in 1..27)return "Origin game ID $originGame is Generation 7 data with no documented destination-valid Generation 6 provenance mapping."
        if(!gen5ToGen6DateValid(p.metYear,p.metMonth,p.metDay))return "The met date is invalid."
        if(!gen5ToGen6DateValid(p.eggYear,p.eggMonth,p.eggDay))return "The Egg date is invalid."
        val plain=decryptPk6IfNeeded(raw)
        val resort=plain[0x2A].toInt() and 0xFF
        if(resort!=0)return "Poké Pelago Resort event status 0x${"%02X".format(resort)} has no native PK6 field. Clear the Resort state before depositing again."
        val alolaRoyale=plain[0x35].toInt() and 0xC0
        val tree=plain[0x36].toInt() and 0x03
        if(alolaRoyale!=0||tree!=0)return "Generation 7-only Alola, Battle Royale or Battle Tree ribbon flags are set (0x35=${"%02X".format(plain[0x35].toInt() and 0xFF)}, 0x36=${"%02X".format(plain[0x36].toInt() and 0xFF)}). Native PK6 cannot preserve them."
        if((plain[0x36].toInt() and 0xFC)!=0||plain[0x37].toInt()!=0)return "Reserved Generation 7 ribbon data is nonzero and cannot be written safely as native PK6."
        return null
    }

    private fun buildGen7ToGen6Pk6(raw:ByteArray,p:PokemonEntry,originGame:Int=p.originGame):ByteArray{
        require(raw.size==PK6_STORED_SIZE){"The preserved Gen 7 Bank record has an unexpected size."};gen7ToGen6PreflightRejection(p,raw,originGame)?.let{error(it)}
        val ups=gen6Pk6PpUps(raw);require(ups.all{it in 0..3}){"The PK7 PP-Up values could not be verified."};require((0..3).all{p.moves[it]!=0||(p.movePP[it]==0&&ups[it]==0)}){"An empty move slot contains PP or PP-Up data that cannot be reviewed safely."}
        val sourcePlain=decryptPk6IfNeeded(raw);val targetPlain=sourcePlain.copyOf();val markings=gen7ToGen6Markings(p.markingValue).first
        targetPlain[0x16]=0;targetPlain[0x17]=0;targetPlain[0x2A]=markings.toByte();targetPlain[0xDE]=0;targetPlain[0xDF]=originGame.toByte();updatePk6Checksum(targetPlain)
        require(targetPlain.indices.all{it in setOf(0x06,0x07,0x16,0x17,0x2A,0xDE,0xDF)||targetPlain[it]==sourcePlain[it]}){"The PK6 conversion changed an unreviewed stored-Pokémon field."}
        val encrypted=encryptPk6(targetPlain);val q=parsePk6(encrypted,0,PK6_STORED_SIZE,false,721)?:error("The converted PK6 could not be parsed.")
        require(sameGen6ToGen7Pk7(q,p.copy(markingValue=markings,hyperTrainFlags=0,originGame=originGame))&&q.markingValue==markings&&gen6Pk6PpUps(encrypted).contentEquals(ups)){"The converted PK6 did not preserve every reviewed field."}
        return encrypted
    }

    private fun prepareGen7ToGen6Transfer(bankFile:File,shown:PokemonEntry,requestedOriginGame:Int?=null){
        val file=importedFile?:return showDialog("Gen 7 → Gen 6","Load a valid Pokémon X, Y, Omega Ruby or Alpha Sapphire destination first.");val openedUri=currentSourceUri;val openedLabel=currentSourceLabel
        fun bound()=importedFile?.absolutePath==file.absolutePath&&currentSourceUri==openedUri&&currentSourceLabel==openedLabel
        val destination=runCatching{file.readBytes()}.getOrNull()?:return showDialog("Gen 7 → Gen 6","The destination save could not be read.")
        if(!bound()||generationForSize(destination.size)!=6||!gen6BoxChecksumValid(destination)||!gen6BlockChecksumValid(destination,20))return showDialog("Gen 7 → Gen 6","Load a checksum-clean Pokémon X, Y, Omega Ruby or Alpha Sapphire save first.")
        val root=runCatching{bankDir().canonicalFile}.getOrNull()?:return;val selected=runCatching{bankFile.canonicalFile}.getOrNull()?:return
        if(selected.parentFile!=root||!selected.extension.equals("pk7",true))return showDialog("Gen 7 → Gen 6","The selected record is outside the Generation 7 PSE Bank.")
        val bank=runCatching{selected.readBytes()}.getOrNull()?:return showDialog("Gen 7 → Gen 6","The Bank record could not be read.");val source=if(bank.size==PK6_STORED_SIZE)parsePk6(bank,0,PK6_STORED_SIZE,false,807)else null
        if(source==null||!source.checksumValid||source.pid!=shown.pid||source.species!=shown.species||source.tid!=shown.tid||source.sid!=shown.sid)return showDialog("Gen 7 → Gen 6","The selected Bank record changed or failed its PK7 checksum.")
        val needsLegalise=source.originGame !in 1..27
        val originGame=requestedOriginGame?:source.originGame
        if(needsLegalise&&requestedOriginGame==null){
            val ids=listOf(24,25,26,27)
            AlertDialog.Builder(this).setTitle("Choose Gen 6 origin mapping")
                .setMessage("Origin game ID ${source.originGame} has no documented Generation 6 provenance mapping. Choose a Gen 6 origin ID for PK6. This is an explicit PSE Legalise choice, not verified history; cancelling leaves the Bank record and destination unchanged.")
                .setItems(ids.map{"Origin game ID $it"}.toTypedArray()){_,which->prepareGen7ToGen6Transfer(bankFile,shown,ids[which])}
                .setNegativeButton("Cancel",null).show()
            return
        }
        if(needsLegalise&&originGame !in 24..27)return showDialog("Gen 7 → Gen 6 blocked","Choose a valid Gen 6 origin ID.")
        gen7ToGen6PreflightRejection(source,bank,originGame)?.let{return showDialog("Gen 7 → Gen 6 blocked","$it\n\nThe PK7 Bank record and Gen 6 destination were left unchanged.")}
        val pk6=try{buildGen7ToGen6Pk6(bank,source,originGame)}catch(e:Exception){return showDialog("Gen 7 → Gen 6 blocked",(e.message?:"No safe native PK6 mapping is available.")+"\n\nNothing was changed.")}
        if(!bound()||!runCatching{file.readBytes().contentEquals(destination)&&selected.readBytes().contentEquals(bank)}.getOrDefault(false))return showDialog("Gen 7 → Gen 6","The destination or Bank record changed during preparation. Nothing was changed.")
        val converted=parsePk6(pk6,0,PK6_STORED_SIZE,false,721)?:return showDialog("Gen 7 → Gen 6","The prepared PK6 could not be re-read.");val markingNote=gen7ToGen6Markings(source.markingValue).second;val prepared=Gen7Gen6Prepared(selected,bank,source,destination,pk6,converted,file,openedUri,openedLabel,markingNote,originGame)
        val originNote=if(needsLegalise)"Origin Legalise: game ID ${source.originGame} → ${originGame}; this is a user-selected provenance change, not verified history." else "Origin game ID ${originGame} is preserved."
        val preview="Backward PSE conversion into native PK6 storage. This is not an official game transfer, trade or provenance claim, and PSE does not promise a lossless round trip.\n\nPreserved exactly: destination-representable species/form, encryption constant, PID, OT/TID/SID, nickname, held item, EXP, ability/slot, nature, gender, shiny state, moves/PP/PP Ups/relearn moves, IVs, EVs, friendship and handler data, Pokérus, encounter locations, Ball, met level, pre-Gen-7 origin, language, dates, geography, memories and all other shared metadata.\n\nReviewed format differences:\n• $markingNote.\n• $originNote\n• Red or mixed marking states are blocked because PK6 has only one bit per marking.\n• PK6 Super Training Bag state starts empty because PK7 uses bytes 0x16–0x17 for markings.\n• Nonzero Resort state, Hyper Training, Gen 7-only ribbons, species, forms, moves, items, abilities, Balls and origin data are blocked with the exact reason rather than discarded or relabelled.\n\nThe user chooses one empty native Gen 6 slot. PSE updates that exact PK6, required Pokédex flags and native block checksums. A retained verified recovery backup is mandatory. The PK7 Bank record is removed only after persisted reopen verification; either side is restored on failure."
        AlertDialog.Builder(this).setTitle("${source.nickname.ifBlank{"Pokémon #${source.species}"}} • Gen 7 → Gen 6").setMessage(preview).setNegativeButton("Cancel",null).setPositiveButton("Choose Gen 6 destination"){_,_->chooseGen7ToGen6Destination(prepared)}.show()
    }

    private fun gen7ToGen6SnapshotsMatch(p:Gen7Gen6Prepared,requireOpen:Boolean=true):Boolean=
        (!requireOpen||!p.submitted)&&importedFile?.absolutePath==p.destinationFile.absolutePath&&currentSourceUri==p.sourceUri&&currentSourceLabel==p.sourceLabel&&runCatching{p.destinationFile.readBytes().contentEquals(p.destination)&&p.bankFile.readBytes().contentEquals(p.bankBytes)}.getOrDefault(false)

    private fun chooseGen7ToGen6Destination(p:Gen7Gen6Prepared){
        if(!gen7ToGen6SnapshotsMatch(p))return showDialog("Gen 7 → Gen 6","The destination or Bank record changed. Reopen PSE Bank.");val info=boxStorageInfo(p.destination)?:return;val empty=(0 until info.second).filter{parsePk6(p.destination,info.first+it*PK6_STORED_SIZE,PK6_STORED_SIZE,false,721)==null};if(empty.isEmpty())return showDialog("Gen 7 → Gen 6","All native Generation 6 PC slots are occupied.")
        val first=empty.first();AlertDialog.Builder(this).setTitle("Choose native Gen 6 destination").setMessage("The reviewed PK6 will be written to one empty slot. PSE will update only that slot, required Pokédex flags and native block checksums.").setItems(arrayOf("First Empty • Box ${first/30+1} • Slot ${first%30+1}","Choose Box / Slot")){_,which->if(!gen7ToGen6SnapshotsMatch(p))showDialog("Gen 7 → Gen 6","The destination or Bank record changed. Reopen PSE Bank.")else if(which==0)transferGen7BankToGen6(p,first)else showGen7ToGen6BoxPicker(p)}.setNegativeButton("Cancel",null).show()
    }

    private fun showGen7ToGen6BoxPicker(p:Gen7Gen6Prepared){
        if(!gen7ToGen6SnapshotsMatch(p))return showDialog("Gen 7 → Gen 6","The destination or Bank record changed. Reopen PSE Bank.");val info=boxStorageInfo(p.destination)?:return;val boxes=(0 until info.second/30).filter{box->(0 until 30).any{slot->parsePk6(p.destination,info.first+(box*30+slot)*PK6_STORED_SIZE,PK6_STORED_SIZE,false,721)==null}}
        AlertDialog.Builder(this).setTitle("Choose Gen 6 destination box").setItems(boxes.map{"Box ${it+1}"}.toTypedArray()){_,which->val box=boxes[which];val slots=(0 until 30).filter{slot->parsePk6(p.destination,info.first+(box*30+slot)*PK6_STORED_SIZE,PK6_STORED_SIZE,false,721)==null};AlertDialog.Builder(this).setTitle("Box ${box+1} • choose slot").setItems(slots.map{"Slot ${it+1}"}.toTypedArray()){_,slotIndex->transferGen7BankToGen6(p,box*30+slots[slotIndex])}.setNegativeButton("Cancel",null).show()}.setNegativeButton("Cancel",null).show()
    }

    private fun transferGen7BankToGen6(p:Gen7Gen6Prepared,target:Int){
        if(!gen7ToGen6SnapshotsMatch(p)||p.submitted)return showDialog("Gen 7 → Gen 6","The destination or Bank record changed, or this conversion was already submitted. Reopen PSE Bank.")
        val file=p.destinationFile;val fresh=runCatching{file.readBytes()}.getOrNull()?:return showDialog("Gen 7 → Gen 6","The destination save could not be read. Nothing was changed.");p.submitted=true;var writeStarted=false;var deleteAttempted=false;var backup:File?=null;var bankRecovery:File?=null
        try{
            require(fresh.contentEquals(p.destination)&&generationForSize(fresh.size)==6){"The prepared Gen 6 destination changed."};require(gen6BoxChecksumValid(fresh)&&gen6BlockChecksumValid(fresh,20)){"The destination storage or Pokédex checksum changed."};val info=boxStorageInfo(fresh)?:error("PSE could not resolve native Gen 6 PC storage.");require(target in 0 until info.second){"The selected Gen 6 slot is invalid."};val off=info.first+target*PK6_STORED_SIZE;require(parsePk6(fresh,off,PK6_STORED_SIZE,false,721)==null){"The selected Gen 6 slot is no longer empty."}
            val bank=p.bankFile.readBytes();require(bank.contentEquals(p.bankBytes)){"The Gen 7 Bank record changed."};val source=parsePk6(bank,0,PK6_STORED_SIZE,false,807)?:error("The PK7 Bank record is invalid.");require(source.checksumValid&&source.pid==p.source.pid&&source.species==p.source.species&&source.tid==p.source.tid&&source.sid==p.source.sid){"The selected source no longer matches the reviewed Pokémon."};val pk6=buildGen7ToGen6Pk6(bank,source,p.originGame);require(pk6.contentEquals(p.pk6)){"The reviewed PK6 conversion changed before writing."}
            val work=fresh.copyOf();pk6.copyInto(work,off);val staged=parsePk6(work,off,PK6_STORED_SIZE,false,721)?:error("The staged PK6 could not be parsed.");require(sameGen6ToGen7Pk7(staged,p.converted)&&staged.markingValue==p.converted.markingValue&&gen6Pk6PpUps(pk6).contentEquals(gen6Pk6PpUps(bank))){"The staged PK6 differs from the reviewed conversion."}
            val allowed=HashSet<Int>();for(i in off until off+PK6_STORED_SIZE)allowed.add(i);val bit=staged.species-1;val bd=bit ushr 3;val shift=staged.gender.coerceIn(0,1) or ((if(staged.shiny)1 else 0) shl 1);allowed.add(0x15000+0x08+bd);allowed.add(0x15000+0x08+0x60*(1+shift)+bd);for(i in 5..8)allowed.add(0x15000+0x08+0x60*i+bd);val boxBlock=if(work.size==SIZE_G6_XY)53 else 56;for(id in intArrayOf(20,boxBlock)){val c=gen6ChecksumOffset(work,id);allowed.add(c);allowed.add(c+1)}
            registerGen6Dex(work,staged.species,staged.gender,staged.shiny,staged.language);updateGen6BoxChecksum(work);updateGen6DexChecksum(work);require(work.indices.all{it in allowed||work[it]==fresh[it]}){"The conversion changed data outside the reviewed PK6, Pokédex flags and native checksums."};require(gen6BoxChecksumValid(work)&&gen6BlockChecksumValid(work,20)&&gen6DexCaught(work,staged.species)){"The staged Gen 6 save failed storage, Pokédex or checksum verification."}
            val recovery=File.createTempFile(backupGameName(file)+"_PreGen7ToGen6_",".backup",backupsDir());backup=recovery;recovery.writeBytes(fresh);require(recovery.readBytes().contentEquals(fresh)){"The exact Gen 6 recovery backup did not verify."};retainGenToGen6SafetyBackup(recovery,fresh);val bankCopy=File.createTempFile("PSE_G7ToG6_BankRecovery_",".tmp",bankDir());bankRecovery=bankCopy;bankCopy.writeBytes(p.bankBytes);require(bankCopy.readBytes().contentEquals(p.bankBytes)){"The Bank recovery snapshot did not verify."};require(gen7ToGen6SnapshotsMatch(p,false)&&isBackupKept(recovery)&&file.readBytes().contentEquals(fresh)){"The source identity, snapshots or retained backup changed before writing."}
            writeStarted=true;file.writeBytes(work);val written=file.readBytes();require(written.contentEquals(work)&&written.indices.all{it in allowed||written[it]==fresh[it]}){"The persisted Gen 6 save differs from the reviewed write scope."};require(gen6BoxChecksumValid(written)&&gen6BlockChecksumValid(written,20)&&gen6DexCaught(written,staged.species)){"The persisted Gen 6 save failed checksum or Pokédex validation."};val actual=written.copyOfRange(off,off+PK6_STORED_SIZE);val reopened=parsePk6(actual,0,PK6_STORED_SIZE,false,721)?:error("The persisted PK6 could not be parsed.");require(actual.contentEquals(pk6)&&sameGen6ToGen7Pk7(reopened,p.converted)&&reopened.markingValue==p.converted.markingValue&&gen6Pk6PpUps(actual).contentEquals(gen6Pk6PpUps(bank))){"The exact converted PK6 did not persist after reopening."}
            require(p.bankFile.readBytes().contentEquals(p.bankBytes)&&file.readBytes().contentEquals(work)){"The Bank record or destination changed before cleanup."};deleteAttempted=true;require(p.bankFile.delete()&&!p.bankFile.exists()){"The Gen 7 Bank record could not be removed after destination verification."};require(file.readBytes().contentEquals(work)){"The destination changed after Bank cleanup."};runCatching{bankCopy.delete()}
        }catch(e:Exception){
            val bankRestored=runCatching{if(deleteAttempted&&!p.bankFile.exists())p.bankFile.writeBytes(p.bankBytes);p.bankFile.readBytes().contentEquals(p.bankBytes)}.getOrDefault(false);val destinationRestored=!writeStarted||runCatching{file.writeBytes(fresh);val restored=file.readBytes();restored.contentEquals(fresh)&&gen6BoxChecksumValid(restored)&&gen6BlockChecksumValid(restored,20)}.getOrDefault(false);val recovery=if(bankRestored&&destinationRestored)"The exact Gen 6 destination and Gen 7 Bank record were restored or kept and verified." else "Automatic recovery could not be fully verified. Keep the retained recovery backup and Bank recovery file for review.";showDialog("Gen 7 → Gen 6 failed",(e.message?:"Unknown error")+"\n\n"+recovery+(backup?.let{"\n\nRecovery backup: ${it.name}"}?:"")+(bankRecovery?.takeIf{it.exists()}?.let{"\nBank recovery: ${it.name}"}?:""));return
        }
        Toast.makeText(this,"PSE converted Gen 7 → Gen 6 to Box ${target/30+1} • Slot ${target%30+1} and verified",Toast.LENGTH_LONG).show();showBank()
    }

    private data class Gen5Gen4Prepared(
        val bankFile:File,val bankBytes:ByteArray,val source:PokemonEntry,val destination:ByteArray,
        val meta:Gen3ToGen4Meta,val originGame:Int,val originLegalised:Boolean,val pk4:ByteArray,val converted:PokemonEntry,val destinationFile:File,
        val sourceUri:Uri?,val sourceLabel:String?
    )

    private fun gen5ToGen4PreflightRejection(p:PokemonEntry,allowOriginLegalise:Boolean=false):String?=when{
        !p.checksumValid->"The source PK5 checksum is invalid."
        p.species !in 1..493->"Species #${p.species} did not exist in Generation 4."
        p.form!=0->"Form ${p.form} has no verified native Gen 4 mapping on this route."
        p.isEgg->"Egg state has no verified backward PK5 to PK4 mapping."
        p.heldItem!=0->"Held item #${p.heldItem} cannot be mapped safely because Gen 5 and Gen 4 item IDs are not interchangeable."
        p.moves.any{it !in 0..467}->"A move is outside the Generation 4 move catalogue."
        p.ability !in 1..123->"Ability #${p.ability} did not exist in Generation 4."
        p.abilityNumber !in 1..2->"Hidden or unsupported ability slots cannot be represented in Generation 4."
        p.nature !in 0..24->"The explicit Gen 5 nature is invalid for Generation 4."

        p.nickname.length>10||p.nickname.any{gen4EncodeChar(it)==null}->"The nickname cannot be represented exactly by the native Gen 4 text writer."
        p.otName.length>7||p.otName.any{gen4EncodeChar(it)==null}->"The Original Trainer name cannot be represented exactly by the native Gen 4 text writer."
        p.language !in 1..10->"Language ID ${p.language} is outside the supported Gen 4 range."
        p.evs.any{it !in 0..255}||p.evs.sum()>510->"The EV data is not destination-valid for Generation 4."
        p.ivs.any{it !in 0..31}->"The IV data is invalid."
        p.movePP.any{it !in 0..63}->"A move PP value is invalid."
        p.ball !in 1..16->"Ball ID ${p.ball} has no verified title-independent Gen 4 mapping."
        !allowOriginLegalise&&p.originGame !in 1..12->"Origin game ID ${p.originGame} is not representable as verified pre-Gen-5 provenance. Choose an explicit Gen 4-era origin mapping to continue."
        p.metLevel !in 1..100->"The met level is outside Generation 4 limits."
        p.metLocation!=0->"Gen 5 met location #${p.metLocation} has no documented Gen 4 location mapping. Only the explicit unspecified location used by PSE's Gen 4 → Gen 5 route can be reversed safely."
        p.eggLocation!=0->"The PK5 contains Egg location data that cannot be mapped safely to Gen 4."
        else->null
    }

    private fun buildGen5ToGen4Pk4(raw:ByteArray,p:PokemonEntry,destination:ByteArray,meta:Gen3ToGen4Meta,originGame:Int=p.originGame,originLegalised:Boolean=false):ByteArray{
        require(raw.size==136){"The preserved Gen 5 Bank record has an unexpected size."}
        detectGen4Profile(destination)?:error("A valid Generation 4 destination save is required.")
        gen5ToGen4PreflightRejection(p,originLegalised)?.let{error(it)}
        require(meta.abilityId==p.ability){"The PK5 ability does not match the verified Generation 4 ability for slot ${p.abilityNumber}."}
        require(gen3TransferGender(p,meta.genderRate)==p.gender){"PID-derived gender does not match the PK5 gender field."}
        val ups=gen5Pk5PpUps(raw);require(ups.all{it in 0..3}){"The PK5 PP-Up values could not be verified."}
        val out=decryptPk5(raw)?:error("The source PK5 could not be decrypted.")
        val targetPid=gen4PidForNatureShiny(p.pid,p.tid,p.sid,p.nature,p.shiny,p.abilityNumber)
        writeU32LE(out,0,targetPid);writeU16LE(out,0x0A,0);out[0x41]=0;out[0x42]=0;out[0x5F]=originGame.toByte()
        for(i in 0..3)out[0x34+i]=(if(p.moves[i]==0)0 else ups[i]).toByte()
        writeGen4String(out,0x48,22,p.nickname);writeGen4String(out,0x68,16,p.otName)
        writeU16LE(out,0x44,0);writeU16LE(out,0x46,0);writeU16LE(out,0x7E,0);writeU16LE(out,0x80,0)
        out[0x83]=p.ball.toByte();out[0x85]=0;out[0x86]=0;out[0x87]=0
        val encrypted=encryptPk4(out);val q=parsePk4(encrypted,false)?:error("The converted PK4 could not be parsed.")
        require(q.checksumValid&&!q.isEgg&&q.pid==targetPid&&q.species==p.species&&q.tid==p.tid&&q.sid==p.sid&&
            q.nickname==p.nickname&&q.isNicknamed==p.isNicknamed&&q.otName==p.otName&&q.experience==p.experience&&
            q.ability==p.ability&&q.abilityNumber==p.abilityNumber&&q.nature==p.nature&&q.gender==p.gender&&q.form==0&&
            q.fatefulEncounter==p.fatefulEncounter&&q.shiny==p.shiny&&q.heldItem==0&&q.friendship==p.friendship&&
            q.markingValue==p.markingValue&&q.language==p.language&&q.moves.contentEquals(p.moves)&&q.movePP.contentEquals(p.movePP)&&
            gen4Pk4PpUps(encrypted).contentEquals(ups)&&q.evs.contentEquals(p.evs)&&q.ivs.contentEquals(p.ivs)&&
            q.pokerusDays==p.pokerusDays&&q.pokerusStrain==p.pokerusStrain&&q.eggLocation==0&&q.metLocation==0&&
            q.ball==p.ball&&q.metLevel==p.metLevel&&q.otGender==p.otGender&&q.originGame==originGame&&
            q.eggYear==p.eggYear&&q.eggMonth==p.eggMonth&&q.eggDay==p.eggDay&&q.metYear==p.metYear&&q.metMonth==p.metMonth&&q.metDay==p.metDay){
            "The converted PK4 did not preserve every destination-representable field."
        }
        return encrypted
    }

    private fun sameGen5ToGen4Pk4(a:PokemonEntry,b:PokemonEntry):Boolean=
        a.checksumValid&&b.checksumValid&&!a.isEgg&&!b.isEgg&&a.pid==b.pid&&a.species==b.species&&a.tid==b.tid&&a.sid==b.sid&&
            a.nickname==b.nickname&&a.isNicknamed==b.isNicknamed&&a.otName==b.otName&&a.experience==b.experience&&
            a.ability==b.ability&&a.abilityNumber==b.abilityNumber&&a.nature==b.nature&&a.gender==b.gender&&a.form==b.form&&
            a.fatefulEncounter==b.fatefulEncounter&&a.shiny==b.shiny&&a.heldItem==b.heldItem&&a.friendship==b.friendship&&
            a.markingValue==b.markingValue&&a.language==b.language&&a.moves.contentEquals(b.moves)&&a.movePP.contentEquals(b.movePP)&&
            a.evs.contentEquals(b.evs)&&a.ivs.contentEquals(b.ivs)&&a.pokerusDays==b.pokerusDays&&a.pokerusStrain==b.pokerusStrain&&
            a.eggLocation==b.eggLocation&&a.metLocation==b.metLocation&&a.ball==b.ball&&a.metLevel==b.metLevel&&
            a.otGender==b.otGender&&a.originGame==b.originGame&&a.eggYear==b.eggYear&&a.eggMonth==b.eggMonth&&a.eggDay==b.eggDay&&
            a.metYear==b.metYear&&a.metMonth==b.metMonth&&a.metDay==b.metDay

    private fun prepareGen5ToGen4Transfer(bankFile:File,shown:PokemonEntry,requestedOriginGame:Int?=null){
        val file=importedFile?:return showDialog("Gen 5 → Gen 4","Load a valid Generation 4 destination save first.")
        val openedUri=currentSourceUri;val openedLabel=currentSourceLabel
        fun bound()=importedFile?.absolutePath==file.absolutePath&&currentSourceUri==openedUri&&currentSourceLabel==openedLabel
        val destination=runCatching{file.readBytes()}.getOrNull()?:return showDialog("Gen 5 → Gen 4","The destination save could not be read.")
        val profile=detectGen4Profile(destination)?:return showDialog("Gen 5 → Gen 4","Load a valid Diamond, Pearl, Platinum, HeartGold or SoulSilver save first.")
        val validation=gen4Validation(destination,profile)
        if(!bound()||!validation.generalChecksum||!validation.storageChecksum||validation.badPk4!=0)
            return showDialog("Gen 5 → Gen 4","The loaded destination is not a valid, checksum-clean Generation 4 save.")
        val root=runCatching{bankDir().canonicalFile}.getOrNull()?:return;val selected=runCatching{bankFile.canonicalFile}.getOrNull()?:return
        if(selected.parentFile!=root||!selected.extension.equals("pk5",true))return showDialog("Gen 5 → Gen 4","The selected record is outside the Generation 5 PSE Bank.")
        val bank=runCatching{selected.readBytes()}.getOrNull()?:return showDialog("Gen 5 → Gen 4","The Bank record could not be read.")
        val source=if(bank.size==136)parsePk5(bank,false)else null
        if(source==null||!source.checksumValid||source.pid!=shown.pid||source.species!=shown.species)
            return showDialog("Gen 5 → Gen 4","The selected Bank record changed or failed its PK5 checksum.")
        val originLegalised=source.originGame !in 1..12
        val originGame=requestedOriginGame?:source.originGame
        if(originLegalised&&requestedOriginGame==null){
            val ids=(1..12).toList()
            AlertDialog.Builder(this).setTitle("Choose Gen 4-compatible origin")
                .setMessage("Origin game ID ${source.originGame} is outside the verified pre-Gen-5 range. Choose the origin ID to write in PK4. This is an explicit PSE Legalise change, not official provenance; cancelling leaves the Bank record and destination unchanged.")
                .setItems(ids.map{"Origin game ID $it"}.toTypedArray()){_,which->prepareGen5ToGen4Transfer(bankFile,shown,ids[which])}
                .setNegativeButton("Cancel",null).show()
            return
        }
        if(originLegalised&&originGame !in 1..12)return showDialog("Gen 5 → Gen 4 blocked","Choose a valid pre-Gen-5 origin ID.")
        gen5ToGen4PreflightRejection(source,originLegalised)?.let{return showDialog("Gen 5 → Gen 4 blocked","$it\n\nThe Bank record and destination were left unchanged.")}
        fun snapshotsMatch()=bound()&&runCatching{file.readBytes().contentEquals(destination)&&selected.readBytes().contentEquals(bank)}.getOrDefault(false)
        val loading=AlertDialog.Builder(this).setTitle("Prepare Gen 5 → Gen 4").setMessage("Verifying the historical ability, PID-derived fields and native PK4 mapping…").setCancelable(false).create();loading.show()
        loadGen3ToGen4MetaAsync(source,4,5){meta,reason->
            loading.dismiss();if(!snapshotsMatch())return@loadGen3ToGen4MetaAsync showDialog("Gen 5 → Gen 4","The destination or Bank record changed during preparation.")
            if(meta==null)return@loadGen3ToGen4MetaAsync showDialog("Gen 5 → Gen 4 blocked",(reason?:"Generation 4 conversion data could not be verified.")+"\n\nNothing was changed.")
            val pk4=try{buildGen5ToGen4Pk4(bank,source,destination,meta,originGame,originLegalised)}catch(e:Exception){return@loadGen3ToGen4MetaAsync showDialog("Gen 5 → Gen 4 blocked",(e.message?:"No safe mapping is available.")+"\n\nNothing was changed.")}
            val converted=parsePk4(pk4,false)?:return@loadGen3ToGen4MetaAsync showDialog("Gen 5 → Gen 4","The prepared PK4 could not be re-read.")
            val prepared=Gen5Gen4Prepared(selected,bank,source,destination,meta,originGame,originLegalised,pk4,converted,file,openedUri,openedLabel)
            val pidNotice=if(converted.pid==source.pid)"PID preserved." else "PID adjustment: ${source.pid.toString(16).uppercase().padStart(8,'0')} → ${converted.pid.toString(16).uppercase().padStart(8,'0')} so Generation 4 PID-derived nature and ability slot remain valid; nature, ability, shiny state and TID/SID are preserved. Review before continuing."
            val originNotice=if(originLegalised)"Origin Legalise: game ID ${source.originGame} → ${originGame}; this is a user-selected provenance change, not verified history." else "Origin game ID ${source.originGame} is preserved."
            val preview="PSE conversion, not an official backward transfer or provenance claim.\n\nPreserved: species, OT/TID/SID, nickname, EXP, nature, shiny state, verified non-hidden ability, gender, IVs, EVs, moves, PP/PP Ups, friendship, Pokérus, markings, Ball, met level, encounter dates and fateful marker. $originNotice $pidNotice\n\nRequired format difference: native PK4 has no explicit nature or hidden-ability field. Gen 5 location IDs are not remapped; only the explicit unspecified location 0 produced by PSE's forward route is accepted and remains 0. Held items, Eggs, forms, Gen 5 species/moves/abilities/origins and all ambiguous fields are blocked instead of discarded.\n\nThe exact PK5 Bank record remains until the reviewed native PK4, Pokédex mirrors, block CRCs and persisted reopen all verify."
            AlertDialog.Builder(this).setTitle("${source.nickname.ifBlank{"Pokémon #${source.species}"}} • Gen 5 → Gen 4").setMessage(preview)
                .setNegativeButton("Cancel",null).setPositiveButton("Review destination"){_,_->if(snapshotsMatch())chooseGen5ToGen4Destination(prepared)else showDialog("Gen 5 → Gen 4","The destination or Bank record changed after review.")}.show()
        }
    }

    private fun gen5ToGen4StillBound(p:Gen5Gen4Prepared):Boolean=
        importedFile?.absolutePath==p.destinationFile.absolutePath&&currentSourceUri==p.sourceUri&&currentSourceLabel==p.sourceLabel&&
            runCatching{p.destinationFile.readBytes().contentEquals(p.destination)&&p.bankFile.readBytes().contentEquals(p.bankBytes)}.getOrDefault(false)

    private fun chooseGen5ToGen4Destination(p:Gen5Gen4Prepared){
        if(!gen5ToGen4StillBound(p))return showDialog("Gen 5 → Gen 4","The prepared snapshots changed. Reopen PSE Bank.")
        val profile=detectGen4Profile(p.destination)?:return;val empty=gen4EmptyBoxSlots(p.destination,profile)
        if(empty.isEmpty())return showDialog("Gen 5 → Gen 4","No empty native Gen 4 PC slot is available.")
        val first=empty.first();AlertDialog.Builder(this).setTitle("Choose native Gen 4 destination")
            .setMessage("The reviewed PSE conversion will be written to one empty native PK4 slot. PSE will update the Pokédex and both active block CRCs.")
            .setItems(arrayOf("First Empty • Box ${first/30+1} • Slot ${first%30+1}","Choose Box / Slot")){_,which->
                if(!gen5ToGen4StillBound(p))showDialog("Gen 5 → Gen 4","The prepared snapshots changed. Reopen PSE Bank.")
                else if(which==0)transferGen5BankToGen4(p,first)else showGen5ToGen4BoxPicker(p)
            }.setNegativeButton("Cancel",null).show()
    }

    private fun showGen5ToGen4BoxPicker(p:Gen5Gen4Prepared){
        if(!gen5ToGen4StillBound(p))return showDialog("Gen 5 → Gen 4","The prepared snapshots changed. Reopen PSE Bank.")
        val profile=detectGen4Profile(p.destination)?:return
        val boxes=(0 until 18).filter{b->(0 until 30).any{s->val o=gen4BoxSlotOffset(p.destination,profile,b*30+s);parsePk4(p.destination.copyOfRange(o,o+136),false)==null}}
        AlertDialog.Builder(this).setTitle("Choose Gen 4 destination box").setItems(boxes.map{"Box ${it+1}"}.toTypedArray()){_,w->
            val b=boxes[w];val slots=(0 until 30).filter{s->val o=gen4BoxSlotOffset(p.destination,profile,b*30+s);parsePk4(p.destination.copyOfRange(o,o+136),false)==null}
            AlertDialog.Builder(this).setTitle("Box ${b+1} • choose slot").setItems(slots.map{"Slot ${it+1}"}.toTypedArray()){_,sw->transferGen5BankToGen4(p,b*30+slots[sw])}.setNegativeButton("Cancel",null).show()
        }.setNegativeButton("Cancel",null).show()
    }

    private fun transferGen5BankToGen4(p:Gen5Gen4Prepared,target:Int){
        if(!gen5ToGen4StillBound(p))return showDialog("Gen 5 → Gen 4","The prepared snapshots changed. Reopen PSE Bank.")
        val file=p.destinationFile;val fresh=runCatching{file.readBytes()}.getOrNull()?:return
        var writeStarted=false;var bankDeleteAttempted=false;var backup:File?=null;var bankRecovery:File?=null
        try{
            require(fresh.contentEquals(p.destination)&&target in 0 until 540){"The destination changed or the selected slot is invalid."}
            val profile=detectGen4Profile(fresh)?:error("The destination is no longer a valid Gen 4 save.")
            val before=gen4Validation(fresh,profile);require(before.generalChecksum&&before.storageChecksum&&before.badPk4==0){"The fresh Gen 4 destination failed validation."}
            val bank=p.bankFile.readBytes();require(bank.contentEquals(p.bankBytes)){"The selected Gen 5 Bank bytes changed after review."}
            val source=parsePk5(bank,false)?:error("The selected Gen 5 Bank record is invalid.")
            require(source.checksumValid&&source.pid==p.source.pid&&source.species==p.source.species&&source.tid==p.source.tid&&source.sid==p.source.sid){"The selected Gen 5 Pokémon changed after review."}
            val refreshedPk4=buildGen5ToGen4Pk4(bank,source,fresh,p.meta,p.originGame,p.originLegalised);val refreshed=parsePk4(refreshedPk4,false)?:error("The refreshed PK4 could not be parsed.")
            require(refreshedPk4.contentEquals(p.pk4)&&sameGen5ToGen4Pk4(refreshed,p.converted)&&gen4Pk4PpUps(refreshedPk4).contentEquals(gen5Pk5PpUps(bank))){"The prepared conversion changed before staging."}
            val off=gen4BoxSlotOffset(fresh,profile,target);require(parsePk4(fresh.copyOfRange(off,off+136),false)==null){"The destination slot is no longer empty."}
            val work=fresh.copyOf();val allowed=HashSet<Int>();refreshedPk4.copyInto(work,off);for(i in off until off+136)allowed.add(i)
            val staged=parsePk4(work.copyOfRange(off,off+136),false)?:error("The staged PK4 could not be parsed.")
            require(sameGen5ToGen4Pk4(staged,refreshed)&&gen4Pk4PpUps(work.copyOfRange(off,off+136)).contentEquals(gen5Pk5PpUps(bank))){"The staged PK4 differs from the reviewed conversion."}
            val general=gen4ActiveBlock(work,0,profile.generalSize)*0x40000;val dexBase=general+gen4PokedexBase(profile);val bit=staged.species-1
            allowed.add(dexBase+0x04+bit/8);allowed.add(dexBase+0x44+bit/8);allowed.add(general+profile.generalSize-2);allowed.add(general+profile.generalSize-1)
            registerGen1ToGen4Pokedex(work,profile,staged.species)
            val storage=gen4ActiveBlock(work,profile.storageStart,profile.storageSize)*0x40000+profile.storageStart
            allowed.add(storage+profile.storageSize-2);allowed.add(storage+profile.storageSize-1);updateGen4BlockChecksum(work,storage,profile.storageSize,profile)
            require(work.indices.all{it in allowed||work[it]==fresh[it]}){"Unrelated Gen 4 save data changed during staging."}
            val stagedValidation=gen4Validation(work,profile);require(stagedValidation.generalChecksum&&stagedValidation.storageChecksum&&stagedValidation.badPk4==0&&gen1ToGen4DexRegistered(work,profile,staged.species)){"The staged Gen 4 save, PK4 or Pokédex failed verification."}
            require(gen5ToGen4StillBound(p)&&file.readBytes().contentEquals(fresh)){"The destination or Bank record changed during staging."}
            val recovery=File.createTempFile(backupGameName(file)+"_PreGen5ToGen4_",".backup",backupsDir());backup=recovery;recovery.writeBytes(fresh);require(recovery.readBytes().contentEquals(fresh)){"The exact Gen 4 recovery backup did not verify."};retainGen2ToGen4SafetyBackup(recovery,fresh)
            val bankCopy=File.createTempFile("PSE_G5ToG4_BankRecovery_",".tmp",bankDir());bankRecovery=bankCopy;bankCopy.writeBytes(p.bankBytes);require(bankCopy.readBytes().contentEquals(p.bankBytes)){"The Bank recovery snapshot did not verify."}
            require(gen5ToGen4StillBound(p)&&recovery.readBytes().contentEquals(fresh)){"The destination, Bank record or recovery backup changed before writing."}
            writeStarted=true;file.writeBytes(work);val written=file.readBytes()
            require(written.contentEquals(work)&&written.indices.all{it in allowed||written[it]==fresh[it]}){"The persisted destination changed outside the reviewed byte scope."}
            val wp=detectGen4Profile(written)?:error("The persisted Gen 4 layout could not be reopened.");val after=gen4Validation(written,wp)
            require(after.generalChecksum&&after.storageChecksum&&after.badPk4==0&&gen1ToGen4DexRegistered(written,wp,staged.species)){"The persisted Gen 4 save failed checksum or Pokédex verification."}
            val actualOff=gen4BoxSlotOffset(written,wp,target);val actual=written.copyOfRange(actualOff,actualOff+136);val reopened=parsePk4(actual,false)?:error("The persisted PK4 could not be reopened.")
            require(actual.contentEquals(refreshedPk4)&&sameGen5ToGen4Pk4(reopened,staged)&&gen4Pk4PpUps(actual).contentEquals(gen5Pk5PpUps(bank))){"The exact reviewed PK4 did not persist."}
            require(importedFile?.absolutePath==file.absolutePath&&currentSourceUri==p.sourceUri&&currentSourceLabel==p.sourceLabel&&
                p.bankFile.readBytes().contentEquals(p.bankBytes)&&file.readBytes().contentEquals(work)){
                "The source identity, Gen 5 Bank record or verified Gen 4 destination changed before Bank cleanup."
            }
            bankDeleteAttempted=true;require(p.bankFile.delete()&&!p.bankFile.exists()){"The Gen 5 Bank record could not be removed after destination verification."}
            require(file.readBytes().contentEquals(work)){"The destination changed after Bank cleanup."};runCatching{bankCopy.delete()}
        }catch(e:Exception){
            val bankRestored=runCatching{if(bankDeleteAttempted&&!p.bankFile.exists()){require(p.bankFile.createNewFile()){"The Bank recovery path could not be reserved."};p.bankFile.writeBytes(p.bankBytes)};p.bankFile.readBytes().contentEquals(p.bankBytes)}.getOrDefault(false)
            val saveRestored=!writeStarted||runCatching{file.writeBytes(fresh);file.readBytes().contentEquals(fresh)}.getOrDefault(false)
            val recovery=if(bankRestored&&saveRestored)"The original destination and Gen 5 Bank record were restored or kept." else "Automatic recovery could not be fully confirmed. Keep the retained backup and Bank recovery file for review."
            showDialog("Gen 5 → Gen 4 failed",(e.message?:"Unknown error")+"\n\n"+recovery+(backup?.let{"\n\nRecovery backup: ${it.name}"}?:"")+(bankRecovery?.takeIf{it.exists()}?.let{"\nBank recovery: ${it.name}"}?:""));return
        }
        Toast.makeText(this,"PSE converted Gen 5 → Gen 4 to Box ${target/30+1} • Slot ${target%30+1} and verified.",Toast.LENGTH_LONG).show();showBank()
    }

    private fun prepareGen4ForwardTransfer(bankFile:File,shown:PokemonEntry){
        val file=importedFile?:return showDialog("Gen 4 → Gen 7","Load a valid Sun, Moon, Ultra Sun or Ultra Moon destination first.")
        val openedUri=currentSourceUri;val openedLabel=currentSourceLabel
        fun bound()=importedFile?.absolutePath==file.absolutePath&&currentSourceUri==openedUri&&currentSourceLabel==openedLabel
        val destination=runCatching{file.readBytes()}.getOrNull()
            ?:return showDialog("Gen 4 → Gen 7","The destination save could not be read.")
        val checks=validateGen7CoreChecksums(destination)
        if(!bound()||generationForSize(destination.size)!=7||!checks.first)return showDialog("Gen 4 → Gen 7",checks.second)
        val trainer=analyzeSave(file).trainer?:return showDialog("Gen 4 → Gen 7","PSE could not read the destination trainer identity.")
        val root=runCatching{bankDir().canonicalFile}.getOrNull()?:return showDialog("Gen 4 → Gen 7","The PSE Bank path could not be verified.")
        val selected=runCatching{bankFile.canonicalFile}.getOrNull()?:return showDialog("Gen 4 → Gen 7","The selected Bank path could not be verified.")
        if(selected.parentFile!=root||!selected.isFile||!selected.extension.equals("pk4",true))
            return showDialog("Gen 4 → Gen 7","The selected record is outside the Generation 4 PSE Bank.")
        val bank=runCatching{selected.readBytes()}.getOrNull()?:return showDialog("Gen 4 → Gen 7","The selected Bank record could not be read.")
        val source=if(bank.size==136)parsePk4(bank,false)else null
        if(source==null||!source.checksumValid||source.pid!=shown.pid||source.species!=shown.species||source.tid!=shown.tid||source.sid!=shown.sid)
            return showDialog("Gen 4 → Gen 7","The selected Bank record changed or failed its PK4 checksum.")
        gen4ToGen5PreflightRejection(source)?.let{return showDialog("Gen 4 → Gen 7 blocked","$it\n\nThe Bank record and destination were left unchanged.")}
        if(source.moves.indices.any{source.moves[it]==0&&source.movePP[it]!=0})
            return showDialog("Gen 4 → Gen 7 blocked","An empty move slot contains PP data that cannot be preserved.\n\nNothing was changed.")
        val sourceUps=gen4Pk4PpUps(bank)
        if(sourceUps.any{it !in 0..3}||(0..3).any{source.moves[it]==0&&sourceUps[it]!=0})
            return showDialog("Gen 4 → Gen 7 blocked","The PK4 contains PP-Up data that cannot be preserved exactly.\n\nNothing was changed.")
        fun snapshotsMatch()=bound()&&runCatching{file.readBytes().contentEquals(destination)&&selected.readBytes().contentEquals(bank)}.getOrDefault(false)
        val loading=AlertDialog.Builder(this).setTitle("Prepare Gen 4 → Gen 7")
            .setMessage("Resolving the exact ability mapping and preparing a verified native PK7…").setCancelable(false).create();loading.show()
        loadGen3ToGen4MetaAsync(source,5,4){meta,reason->
            if(loading.isShowing)loading.dismiss()
            if(!snapshotsMatch())return@loadGen3ToGen4MetaAsync showDialog("Gen 4 → Gen 7","The destination or Bank record changed during preparation. Nothing was changed.")
            if(meta==null)return@loadGen3ToGen4MetaAsync showDialog("Gen 4 → Gen 7 blocked",(reason?:"Generation 5 ability data could not be verified.")+"\n\nNothing was changed.")
            val pk5=try{buildGen4ToGen5Pk5(bank,source,destination,meta,false)}catch(e:Exception){
                return@loadGen3ToGen4MetaAsync showDialog("Gen 4 → Gen 7 blocked",(e.message?:"The PK5 conversion bridge could not be prepared.")+"\n\nNothing was changed.")
            }
            val bridge5=parsePk5(pk5,false)?:return@loadGen3ToGen4MetaAsync showDialog("Gen 4 → Gen 7","The PK5 conversion bridge could not be reopened.")
            val pk6=try{buildGen5ToGen6Pk6(pk5,bridge5,destination,trainer,7)}catch(e:Exception){
                return@loadGen3ToGen4MetaAsync showDialog("Gen 4 → Gen 7 blocked",(e.message?:"The PK6 conversion bridge could not be prepared.")+"\n\nNothing was changed.")
            }
            val bridge6=parsePk6(pk6,0,PK6_STORED_SIZE,false,721)?:return@loadGen3ToGen4MetaAsync showDialog("Gen 4 → Gen 7","The PK6 conversion bridge could not be reopened.")
            val pk7=try{buildGen6ToGen7Pk7(pk6,bridge6)}catch(e:Exception){
                return@loadGen3ToGen4MetaAsync showDialog("Gen 4 → Gen 7 blocked",(e.message?:"No safe native PK7 mapping is available.")+"\n\nNothing was changed.")
            }
            if(!gen6Pk6PpUps(pk7).contentEquals(sourceUps))
                return@loadGen3ToGen4MetaAsync showDialog("Gen 4 → Gen 7 blocked","The prepared PK7 did not preserve every PP-Up value. Nothing was changed.")
            val converted=parsePk6(pk7,0,PK6_STORED_SIZE,false,807)?:return@loadGen3ToGen4MetaAsync showDialog("Gen 4 → Gen 7","The prepared PK7 could not be reopened.")
            if(!snapshotsMatch())return@loadGen3ToGen4MetaAsync showDialog("Gen 4 → Gen 7","The destination or Bank record changed after conversion preparation. Nothing was changed.")
            val markingNote=gen6ToGen7Markings(bridge6.markingValue).second
            val prepared=Gen6Gen7Prepared(
                bankFile=selected,bankBytes=bank,source=source,destination=destination,pk7=pk7,converted=converted,
                destinationFile=file,sourceUri=openedUri,sourceLabel=openedLabel,markingNote=markingNote,
                originGame=converted.originGame,sourceGeneration=4,trainer=trainer,gen4Meta=meta
            )
            val oldPid="%08X".format(source.pid);val newPid="%08X".format(converted.pid)
            val pidNote=if(source.pid==converted.pid)"PID remains $oldPid." else
                "PID changes $oldPid → $newPid only as required to preserve the verified ability slot, nature, gender and shiny state through the native formats."
            val oldMet=if(source.metLocation==0)"none" else "#${source.metLocation}"
            val oldEgg=if(source.eggLocation==0)"none" else "#${source.eggLocation}"
            val preview=buildString{
                append("PSE Bank conversion preview; this does not claim an official Pokémon Bank transaction or provenance.\n\n")
                append("Preserved: species/form, TID/SID, nickname and OT, EXP, verified ability, nature, gender, shiny state, moves, current PP, PP Ups, IVs, EVs, friendship, Pokérus, Ball, language, source title, met level/date and fateful marker.\n")
                append("$pidNote\nAbility: source ability #${source.ability} in slot ${source.abilityNumber} remains verified ability #${meta.abilityId}.\n")
                append("Markings: $markingNote.\n")
                append("Required format changes: Gen 4 met location $oldMet becomes native transfer marker 30001; Egg location $oldEgg becomes 0. Current handler becomes ${trainer.trainerName}; relearn moves, geographic fields, Resort state and Hyper Training start empty.\n\n")
                append("Held items, Eggs and unsupported values are blocked instead of discarded. The source save stays unchanged. The exact Gen 4 Bank record remains until a retained recovery backup, chosen PK7 slot, Pokédex update, block CRCs, save signature and reopened destination all verify.")
            }
            AlertDialog.Builder(this).setTitle("${source.nickname.ifBlank{meta.speciesName}} • Gen 4 → Gen 7").setMessage(preview)
                .setNegativeButton("Cancel",null).setPositiveButton("Choose Gen 7 destination"){_,_->
                    if(!snapshotsMatch())showDialog("Gen 4 → Gen 7","The destination or Bank record changed after review. Nothing was changed.")
                    else chooseGen6ToGen7Destination(prepared)
                }.show()
        }
    }

    private fun chooseGen4BankWithdrawDestination(bankFile:File,p:PokemonEntry){
        val file=importedFile ?: return showDialog("Withdraw","Import a Gen 4 destination save first.")
        val data=runCatching{file.readBytes()}.getOrDefault(ByteArray(0)); val profile=detectGen4Profile(data) ?: return showDialog("Withdraw blocked","Load a valid Gen 4 save to withdraw an original PK4 Bank record.")
        val v=gen4Validation(data,profile); if(!v.generalChecksum || !v.storageChecksum || v.badPk4!=0)return showDialog("Withdraw blocked","The loaded Gen 4 save did not pass validation.")
        val raw=runCatching{bankFile.readBytes()}.getOrDefault(ByteArray(0)); val source=if(raw.size==136)parsePk4(raw,false)else null
        if(source==null || !source.checksumValid)return showDialog("Withdraw","This Bank entry is not a valid PK4 record.")
        val empties=gen4EmptyBoxSlots(data,profile); if(empties.isEmpty())return showDialog("Withdraw","No empty Gen 4 PC slot is available.")
        val first=empties.first()
        AlertDialog.Builder(this).setTitle("Withdraw ${p.nickname.ifBlank{"Pokémon"}} to…").setItems(arrayOf("First empty slot • Box ${first/30+1} • Slot ${first%30+1}","Choose a box / slot")){_,which->if(which==0)withdrawGen4BankToSlot(bankFile,p,first)else showGen4BankBoxPicker(bankFile,p,data,profile)}.setNegativeButton("Cancel",null).show()
    }

    private fun showGen4BankBoxPicker(bankFile:File,p:PokemonEntry,data:ByteArray,profile:Gen4Profile){
        val boxes=(0 until 18).filter{b->(0 until 30).any{s->val g=b*30+s;val o=gen4BoxSlotOffset(data,profile,g);val r=data.copyOfRange(o,o+136);r.all{it==0.toByte()}||parsePk4(r,false)==null}}
        AlertDialog.Builder(this).setTitle("Choose Gen 4 destination box").setItems(boxes.map{"Box ${it+1}"}.toTypedArray()){_,w->
            val b=boxes[w];val empties=(0 until 30).filter{s->val g=b*30+s;val o=gen4BoxSlotOffset(data,profile,g);val r=data.copyOfRange(o,o+136);r.all{it==0.toByte()}||parsePk4(r,false)==null}
            AlertDialog.Builder(this).setTitle("Box ${b+1} • choose slot").setItems(empties.map{"Slot ${it+1}"}.toTypedArray()){_,sw->withdrawGen4BankToSlot(bankFile,p,b*30+empties[sw])}.setNegativeButton("Cancel",null).show()
        }.setNegativeButton("Cancel",null).show()
    }

    private fun withdrawGen4BankToSlot(bankFile:File,p:PokemonEntry,target:Int){
        val file=importedFile?:return; val original=try{file.readBytes()}catch(e:Exception){showDialog("Withdraw",e.message?:"Could not read save");return}
        try{
            require(target in 0 until 540){"Invalid Gen 4 PC slot"}; val profile=detectGen4Profile(original) ?: throw IllegalStateException("A valid Gen 4 destination save is required")
            val before=gen4Validation(original,profile); if(!before.generalChecksum || !before.storageChecksum || before.badPk4!=0)throw IllegalStateException("Gen 4 destination did not pass validation")
            val raw=bankFile.readBytes(); val source=if(raw.size==136)parsePk4(raw,false)else null; require(source!=null && source.checksumValid){"The Bank PK4 record is invalid"}
            val save=original.copyOf(); val off=gen4BoxSlotOffset(save,profile,target); val old=save.copyOfRange(off,off+136)
            if(!(old.all{it==0.toByte()} || parsePk4(old,false)==null))throw IllegalStateException("Destination slot is no longer empty")
            raw.copyInto(save,off); val staged=parsePk4(save.copyOfRange(off,off+136),false) ?: throw IllegalStateException("PK4 could not be parsed after placement")
            if(!staged.checksumValid || staged.pid!=source.pid || staged.species!=source.species)throw IllegalStateException("Placed PK4 failed verification")
            val activeStorage=gen4ActiveBlock(save,profile.storageStart,profile.storageSize);updateGen4BlockChecksum(save,activeStorage*0x40000+profile.storageStart,profile.storageSize,profile)
            val after=gen4Validation(save,profile);if(!after.generalChecksum || !after.storageChecksum || after.badPk4!=0)throw IllegalStateException("Gen 4 checksum verification failed")
            file.writeBytes(save);val verify=file.readBytes();val vp=detectGen4Profile(verify)?:throw IllegalStateException("Written save layout could not be re-read");val vv=gen4Validation(verify,vp)
            if(!vv.generalChecksum || !vv.storageChecksum || vv.badPk4!=0)throw IllegalStateException("Written Gen 4 save failed verification")
            val vo=gen4BoxSlotOffset(verify,vp,target);val actual=verify.copyOfRange(vo,vo+136);val mon=parsePk4(actual,false)
            if(!actual.contentEquals(raw)||mon==null||!mon.checksumValid||mon.pid!=source.pid||mon.species!=source.species)throw IllegalStateException("Withdrawn PK4 did not verify after re-read")
            if(!bankFile.delete()){file.writeBytes(original);throw IllegalStateException("The destination verified, but the Bank entry could not be removed; the save was restored to avoid duplication")}
            Toast.makeText(this,"Withdrawn to Box ${target/30+1} • Slot ${target%30+1} and verified",Toast.LENGTH_LONG).show();showBank()
        }catch(e:Exception){runCatching{file.writeBytes(original)};showDialog("Gen 4 withdraw failed","${e.message?:"Unknown error"}. The original working copy was restored and the Bank entry was kept.")}
    }

    private fun showGen4PokemonViewer(tab:String="party",boxIndex:Int=0) {
        phoneBackAction={showHome()}
        val file=importedFile?:return showHome()
        val data=runCatching{file.readBytes()}.getOrDefault(ByteArray(0))
        val profile=detectGen4Profile(data) ?: return showDialog("Gen 4", "PSE could not validate this Gen 4 save layout.")
        val safeBox=boxIndex.coerceIn(0,17)
        val scroll=ScrollView(this).apply{setBackgroundColor(BG)}
        val root=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(dp(16),dp(58),dp(16),dp(28));setBackgroundColor(BG)}
        scroll.addView(root)
        root.addView(TextView(this).apply{text="My Pokémon";textSize=28f;typeface=Typeface.DEFAULT_BOLD;setTextColor(TEXT)})
        root.addView(TextView(this).apply{text="Nintendo DS • Gen 4/5 • ${profile.family} • Stage 5 boxed edit / duplicate / delete";textSize=14f;setTextColor(MUTED);setPadding(0,dp(4),0,dp(12))})
        addButton(root,"←  Back to PSE"){showHome()}
        val verification=gen4Validation(data,profile)
        addSectionTitle(root,"SAVE VALIDATION")
        addDetailLine(root,"Active general block","Copy ${verification.activeGeneral+1} • ${if(verification.generalChecksum) "CRC PASS" else "CRC FAIL"}")
        addDetailLine(root,"Active storage block","Copy ${verification.activeStorage+1} • ${if(verification.storageChecksum) "CRC PASS" else "CRC FAIL"}")
        addDetailLine(root,"PK4 integrity","${verification.goodPk4} valid • ${verification.badPk4} checksum warning • ${verification.emptyPk4} empty slots")
        if(verification.generalChecksum && verification.storageChecksum && verification.badPk4==0)
            addMutedLine(root,"✓ Gen 4 active blocks and every detected Pokémon passed validation. Boxed PK4 editing, Duplicate, Delete and Bank are enabled; party writes remain locked.")
        else
            addMutedLine(root,"⚠ PSE found a validation warning. Gen 4 editing is disabled until the save validates cleanly.")
        val tabs=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL}
        fun tabButton(label:String,active:Boolean,go:()->Unit)=Button(this).apply {
            text=label; setAllCaps(false); isEnabled=true; alpha=if(active)1f else 0.62f
            setOnClickListener { if(!active) go() }
        }
        tabs.addView(tabButton("Party",tab=="party"){showGen4PokemonViewer("party",safeBox)},LinearLayout.LayoutParams(0,dp(52),1f))
        tabs.addView(tabButton("PC Boxes",tab!="party"){showGen4PokemonViewer("boxes",safeBox)},LinearLayout.LayoutParams(0,dp(52),1f))
        root.addView(tabs)
        if(tab=="party"){
            addSectionTitle(root,"PARTY")
            val party=gen4Party(data,profile)
            party.forEachIndexed{i,mon->if(mon!=null)root.addView(pokemonRow("Party • Slot ${i+1}",mon)) else root.addView(emptyPokemonRow("Party • Slot ${i+1}"))}
        }else{
            val nav=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL;gravity=Gravity.CENTER_VERTICAL}
            nav.addView(Button(this).apply{text="‹";setOnClickListener{showGen4PokemonViewer("boxes",(safeBox+17)%18)}},LinearLayout.LayoutParams(dp(58),dp(52)))
            val boxName=gen4BoxName(data,profile,safeBox)
            nav.addView(TextView(this).apply{text=if(boxName.isBlank()) "Box ${safeBox+1} of 18" else "Box ${safeBox+1} • $boxName";gravity=Gravity.CENTER;textSize=18f;typeface=Typeface.DEFAULT_BOLD;setTextColor(TEXT)},LinearLayout.LayoutParams(0,dp(52),1f))
            nav.addView(Button(this).apply{text="›";setOnClickListener{showGen4PokemonViewer("boxes",(safeBox+1)%18)}},LinearLayout.LayoutParams(dp(58),dp(52)))
            root.addView(nav)
            val mons=gen4Box(data,profile,safeBox)
            val grid=GridLayout(this).apply{columnCount=6}
            mons.forEachIndexed{slot,mon->grid.addView(boxGridCell(safeBox,slot,mon,safeBox*30+slot,false,false))}
            root.addView(grid)
            addMutedLine(root,"${mons.count{it!=null}} / 30 occupied slots in Box ${safeBox+1}.")
        }
        addMutedLine(root,"Gen 4: boxed editing, Duplicate, Delete, PSE Bank deposit/withdraw, Gen 4 → Gen 5 Bank transfer and Gen 4 → Gen 7 forward transfer are enabled. Party editing remains locked for now.")
        val shell=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setBackgroundColor(BG)}
        shell.addView(scroll,LinearLayout.LayoutParams(-1,0,1f));shell.addView(buildBottomNav("pokemon"),LinearLayout.LayoutParams(-1,-2));setContentView(shell)
    }

    private fun resetPokemonSelection() {
        pokemonMultiSelectMode = false
        selectedPokemonSlots.clear()
    }

    private fun showPokemonViewer(tab: String = "party", boxIndex: Int = 0) {
        if (openActiveSwitchSection("party")) return
        val gen1File = importedFile
        if (gen1File != null) {
            val bytes = runCatching { gen1File.readBytes() }.getOrDefault(ByteArray(0))
            if (detectGen2ChecksumProfile(bytes) != null) {
                val integrity=verifyGen2SaveIntegrity(bytes)
                if(integrity.first)showGen2PokemonViewer(tab)else showDialog("My Pokémon",integrity.second+" Nothing was changed.")
                return
            }
            if (bytes.size == SIZE_G1) {
                showGen1PokemonViewer(tab)
                return
            }
        }
        if (gen1File != null && gen1File.length().toInt() == 0x20000) {
            val bytes = runCatching { gen1File.readBytes() }.getOrDefault(ByteArray(0))
            if (gen3SaveValid(bytes)) { showGen3PokemonViewer(tab, boxIndex); return }
        }
        if (gen1File != null && gen1File.length().toInt() == SIZE_G4) {
            val bytes = runCatching { gen1File.readBytes() }.getOrDefault(ByteArray(0))
            if (detectGen5Profile(bytes) != null) showGen5PokemonViewer(tab, boxIndex) else showGen4PokemonViewer(tab, boxIndex)
            return
        }
        phoneBackAction = { resetPokemonSelection(); showHome() }
        val file = importedFile
        if (file == null) {
            showDialog("My Pokémon", "No save is loaded yet. Tap Import 3DS Save first.")
            return
        }
        val analysis = analyzeSave(file)
        if (!analysis.structurallyValid) {
            showDialog("My Pokémon", "This file has not passed structural validation.")
            return
        }
        val data = try { file.readBytes() } catch (_: Exception) { ByteArray(0) }
        val gen = generationForSize(data.size)
        val boxOffset = when (data.size) {
            SIZE_G6_XY -> BOX_OFFSET_XY
            SIZE_G6_ORAS -> BOX_OFFSET_ORAS
            SIZE_G7_SM -> BOX_OFFSET_SM
            SIZE_G7_USUM -> BOX_OFFSET_USUM
            else -> return
        }
        val partyOffset = when (data.size) {
            SIZE_G6_XY, SIZE_G6_ORAS -> PARTY_OFFSET
            SIZE_G7_SM -> PARTY_OFFSET_SM
            SIZE_G7_USUM -> PARTY_OFFSET_USUM
            else -> return
        }
        val boxCount = if (gen == 7) 32 else 31
        val maxSpecies = if (gen == 7) 807 else 721
        val safeBox = boxIndex.coerceIn(0, boxCount - 1)

        val scroll = ScrollView(this).apply { setBackgroundColor(BG) }
        val root = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(dp(16), dp(58), dp(16), dp(28))
            setBackgroundColor(BG)
        }
        scroll.addView(root)

        root.addView(TextView(this).apply {
            text = "Pokémon Boxes"
            textSize = 28f
            typeface = Typeface.DEFAULT_BOLD
            setTextColor(TEXT)
        })
        root.addView(TextView(this).apply {
            text = "${analysis.trainer?.exactGame ?: analysis.family} • ${if (gen == 7) "Gen 7 viewer • boxed editing enabled" else "Viewer • Bank transfers enabled"}"
            textSize = 14f
            setTextColor(MUTED)
            setPadding(0, 4, 0, 12)
        })
        addButton(root, "←  Back to PSE") { resetPokemonSelection(); showHome() }

        val tabs = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            weightSum = 2f
        }
        val partyButton = Button(this).apply {
            text = "Party"
            setAllCaps(false)
            setTextColor(TEXT)
            setBackgroundColor(if (tab == "party") Color.rgb(25, 115, 205) else Color.rgb(45, 45, 45))
            setOnClickListener { resetPokemonSelection(); showPokemonViewer("party", safeBox) }
        }
        val boxButton = Button(this).apply {
            text = "PC Boxes"
            setAllCaps(false)
            setTextColor(TEXT)
            setBackgroundColor(if (tab == "boxes") Color.rgb(25, 115, 205) else Color.rgb(45, 45, 45))
            setOnClickListener { showPokemonViewer("boxes", safeBox) }
        }
        tabs.addView(partyButton, LinearLayout.LayoutParams(0, dp(52), 1f).apply { rightMargin = dp(4) })
        tabs.addView(boxButton, LinearLayout.LayoutParams(0, dp(52), 1f).apply { leftMargin = dp(4) })
        root.addView(tabs, LinearLayout.LayoutParams(-1, -2).apply { topMargin = dp(8); bottomMargin = dp(10) })

        if (tab == "party") {
            var found = 0
            for (slot in 0 until 6) {
                val offset = partyOffset + slot * PK6_PARTY_SIZE
                val entry = parsePk6(data, offset, PK6_PARTY_SIZE, party = true, maxSpecies = maxSpecies)
                if (entry != null) {
                    found++
                    root.addView(pokemonRow("Slot ${slot + 1}", entry))
                } else {
                    root.addView(emptyPokemonRow("Slot ${slot + 1}"))
                }
            }
            addMutedLine(root, "Party: $found / 6")
        } else {
            val nav = LinearLayout(this).apply {
                orientation = LinearLayout.HORIZONTAL
                gravity = Gravity.CENTER_VERTICAL
            }
            val prev = Button(this).apply {
                text = "‹"
                textSize = 22f
                setTextColor(TEXT)
                isEnabled = safeBox > 0
                setOnClickListener { showPokemonViewer("boxes", safeBox - 1) }
            }
            val label = TextView(this).apply {
                text = "Box ${safeBox + 1} / $boxCount"
                gravity = Gravity.CENTER
                textSize = 17f
                typeface = Typeface.DEFAULT_BOLD
                setTextColor(TEXT)
            }
            val next = Button(this).apply {
                text = "›"
                textSize = 22f
                setTextColor(TEXT)
                isEnabled = safeBox < boxCount - 1
                setOnClickListener { showPokemonViewer("boxes", safeBox + 1) }
            }
            nav.addView(prev, LinearLayout.LayoutParams(dp(58), dp(52)))
            nav.addView(label, LinearLayout.LayoutParams(0, dp(52), 1f))
            nav.addView(next, LinearLayout.LayoutParams(dp(58), dp(52)))
            root.addView(nav, LinearLayout.LayoutParams(-1, -2).apply { bottomMargin = dp(10) })

            if (!pokemonMultiSelectMode) {
                addButton(root, "☑️  Multi-select • Move to PSE Bank") {
                    pokemonMultiSelectMode = true
                    selectedPokemonSlots.clear()
                    showPokemonViewer("boxes", safeBox)
                }
            } else {
                root.addView(TextView(this).apply {
                    text = "${selectedPokemonSlots.size} Pokémon selected"
                    textSize = 16f
                    typeface = Typeface.DEFAULT_BOLD
                    setTextColor(ACCENT)
                    setPadding(0, dp(4), 0, dp(8))
                })
                val selectRow = LinearLayout(this).apply { orientation = LinearLayout.HORIZONTAL; weightSum = 2f }
                val cancelSelect = Button(this).apply {
                    text = "Cancel"
                    setAllCaps(false)
                    setTextColor(TEXT)
                    setOnClickListener { resetPokemonSelection(); showPokemonViewer("boxes", safeBox) }
                }
                val selectAll = Button(this).apply {
                    text = "Select All"
                    setAllCaps(false)
                    setTextColor(TEXT)
                    setOnClickListener {
                        for (slot in 0 until 30) {
                            val global = safeBox * 30 + slot
                            val offset = boxOffset + global * PK6_STORED_SIZE
                            if (parsePk6(data, offset, PK6_STORED_SIZE, false, maxSpecies) != null) selectedPokemonSlots.add(global)
                        }
                        showPokemonViewer("boxes", safeBox)
                    }
                }
                selectRow.addView(cancelSelect, LinearLayout.LayoutParams(0, dp(48), 1f).apply { rightMargin = dp(4) })
                selectRow.addView(selectAll, LinearLayout.LayoutParams(0, dp(48), 1f).apply { leftMargin = dp(4) })
                root.addView(selectRow, LinearLayout.LayoutParams(-1, -2).apply { bottomMargin = dp(8) })
            }

            val grid = GridLayout(this).apply {
                columnCount = 6
                rowCount = 5
                alignmentMode = GridLayout.ALIGN_BOUNDS
                useDefaultMargins = false
            }
            var found = 0
            for (slot in 0 until 30) {
                val index = safeBox * 30 + slot
                val offset = boxOffset + index * PK6_STORED_SIZE
                val entry = parsePk6(data, offset, PK6_STORED_SIZE, party = false, maxSpecies = maxSpecies)
                if (entry != null) found++
                grid.addView(boxGridCell(safeBox, slot, entry, index, pokemonMultiSelectMode, selectedPokemonSlots.contains(index)))
            }
            root.addView(grid, LinearLayout.LayoutParams(-1, -2).apply { bottomMargin = dp(8) })
            addMutedLine(root, "$found / 30 occupied slots in Box ${safeBox + 1}.")

            if (pokemonMultiSelectMode && selectedPokemonSlots.isNotEmpty()) {
                addSectionTitle(root, "BULK ACTIONS")
                val actions = GridLayout(this).apply { columnCount = 2; rowCount = 2 }
                fun actionButton(label: String, enabled: Boolean = true, action: () -> Unit): Button = Button(this).apply {
                    text = label
                    setAllCaps(false)
                    textSize = 14f
                    setTextColor(if (enabled) TEXT else MUTED)
                    isEnabled = enabled
                    setOnClickListener { action() }
                    layoutParams = GridLayout.LayoutParams().apply {
                        width = (resources.displayMetrics.widthPixels - dp(44)) / 2
                        height = dp(58)
                        setMargins(dp(2), dp(2), dp(2), dp(2))
                    }
                }
                actions.addView(actionButton("📦 Move") { chooseBulkMoveDestination(safeBox) })
                actions.addView(actionButton("📑 Duplicate") { chooseBulkDuplicateDestination(safeBox) })
                actions.addView(actionButton("🏦 Move to PSE Bank") { confirmBulkDepositToBank(safeBox) })
                actions.addView(actionButton("🗑️ Delete") { confirmBulkDelete(safeBox) })
                root.addView(actions)
            }
        }

        val shell = LinearLayout(this).apply { orientation = LinearLayout.VERTICAL; setBackgroundColor(BG) }
        shell.addView(scroll, LinearLayout.LayoutParams(-1, 0, 1f))
        shell.addView(buildBottomNav("pokemon"), LinearLayout.LayoutParams(-1, -2))
        setContentView(shell)
    }

    private fun gen3GridCell(
        p: PokemonEntry?,
        box: Int,
        slot: Int,
        selectionMode: Boolean = false,
        selected: Boolean = false,
        onToggle: (() -> Unit)? = null
    ): LinearLayout {
        val w=((resources.displayMetrics.widthPixels-dp(44))/4).coerceAtLeast(dp(70))
        return LinearLayout(this).apply {
            orientation=LinearLayout.VERTICAL; gravity=Gravity.CENTER; setPadding(dp(2),dp(3),dp(2),dp(3))
            val fill = when {
                selected -> Color.rgb(20, 100, 145)
                p == null -> Color.rgb(11,27,38)
                else -> CARD
            }
            val stroke = if (selected) ACCENT else Color.rgb(25,55,72)
            background=roundedBg(fill,stroke,10)
            layoutParams=GridLayout.LayoutParams().apply{width=w;height=dp(112);setMargins(dp(2),dp(2),dp(2),dp(2))}
            if(p!=null){
                isClickable=true
                setOnClickListener {
                    if (selectionMode) onToggle?.invoke()
                    else showPokemonDetails("Box $box • Slot ${slot+1}",p)
                }
                val iv=ImageView(this@MainActivity).apply{scaleType=ImageView.ScaleType.FIT_CENTER;contentDescription=p.nickname}
                addView(iv,LinearLayout.LayoutParams(dp(60),dp(58))); loadPokemonSprite(iv,p.species,p.shiny)
                addView(TextView(this@MainActivity).apply{text=p.nickname.ifBlank{canonicalGen3SpeciesName(p.species)?:"Pokémon #${p.species}"};textSize=10f;maxLines=1;ellipsize=android.text.TextUtils.TruncateAt.END;gravity=Gravity.CENTER;setTextColor(TEXT);typeface=Typeface.DEFAULT_BOLD},LinearLayout.LayoutParams(-1,dp(18)))
                val lv=TextView(this@MainActivity).apply{text=p.level?.let{"Lv.$it${if(p.shiny)" ✦" else ""}"}?:if(p.shiny)"Lv. … ✦" else "Lv. …";textSize=10f;gravity=Gravity.CENTER;setTextColor(MUTED)}
                addView(lv)
                if(p.level==null) resolveBoxedLevelAsync(p.species,p.experience){level->lv.text=level?.let{"Lv.$it${if(p.shiny)" ✦" else ""}"}?:"Lv. ?"}
            } else addView(TextView(this@MainActivity).apply{text="○";textSize=28f;gravity=Gravity.CENTER;setTextColor(Color.rgb(80,80,80))},LinearLayout.LayoutParams(dp(64),dp(78)))
            addView(TextView(this@MainActivity).apply{text=(if(selected)"✓ " else "")+(slot+1);textSize=10f;gravity=Gravity.CENTER;setTextColor(if(selected) TEXT else MUTED)})
        }
    }


    private fun writeGen3Text(buf: ByteArray, off: Int, len: Int, text: String) {
        for (i in 0 until len) buf[off+i] = 0xFF.toByte()
        val t = text.take(len)
        for (i in t.indices) {
            val c=t[i]
            val v=when(c){
                in 'A'..'Z' -> 0xBB + (c-'A')
                in 'a'..'z' -> 0xD5 + (c-'a')
                in '0'..'9' -> 0xA1 + (c-'0')
                ' ' -> 0x00; '!' -> 0xAB; '?' -> 0xAC; '.' -> 0xAD; ',' -> 0xB8; '/' -> 0xBA; '-' -> 0xAE
                '\'' -> 0xB4; '♂' -> 0xB5; '♀' -> 0xB6
                else -> 0xAC
            }
            buf[off+i]=v.toByte()
        }
    }

    private fun gen3PidForNatureShiny(oldPid: Long, tid:Int, sid:Int, nature:Int, shiny:Boolean): Long {
        val old = oldPid and 0xFFFFFFFFL
        if (((old % 25L).toInt()==nature) && (((tid xor sid xor (old.toInt() and 0xFFFF) xor ((old.toInt() ushr 16) and 0xFFFF)) < 8) == shiny)) return old
        val baseLow=(old.toInt() and 0xFFFF)
        if (shiny) {
            for (loDelta in 0..65535) {
                val lo=(baseLow+loDelta) and 0xFFFF
                for (sv in 0..7) {
                    val hi=(tid xor sid xor lo xor sv) and 0xFFFF
                    val pid=((hi.toLong() shl 16) or lo.toLong()) and 0xFFFFFFFFL
                    if ((pid%25L).toInt()==nature) return pid
                }
            }
        } else {
            var pid=old
            for (i in 0..100000) {
                pid=(pid+1) and 0xFFFFFFFFL
                if ((pid%25L).toInt()!=nature) continue
                val sv=tid xor sid xor (pid.toInt() and 0xFFFF) xor ((pid.toInt() ushr 16) and 0xFFFF)
                if (sv>=8) return pid
            }
        }
        return old
    }

    private data class Gen3EditValues(
        val nickname:String,val ot:String,val tid:Int,val sid:Int,val exp:Long,val held:Int,val friendship:Int,
        val nature:Int,val shiny:Boolean,val moves:IntArray,val pp:IntArray,val ivs:IntArray,val evs:IntArray,val abilitySlot:Int
    )

    private data class Gen3PartyRebuild(val level:Int,val baseStats:IntArray)

    private fun gen3PartyStatsFromRaw(raw:ByteArray):IntArray? {
        if(raw.size!=100)return null
        return intArrayOf(
            raw[0x54].toInt() and 0xFF,
            readU16LE(raw,0x56), readU16LE(raw,0x58), readU16LE(raw,0x5A),
            readU16LE(raw,0x5C), readU16LE(raw,0x5E), readU16LE(raw,0x60), readU16LE(raw,0x62)
        )
    }

    private fun calculateGen3BattleStats(base:IntArray, ivs:IntArray, evs:IntArray, nature:Int, level:Int):IntArray {
        require(base.size==6 && ivs.size==6 && evs.size==6 && nature in 0..24 && level in 1..100)
        val out=IntArray(6)
        out[0]=if(base[0]==1)1 else (((2*base[0]+ivs[0]+evs[0]/4)*level)/100)+level+10
        val up=nature/5; val down=nature%5
        for(i in 1..5){
            var stat=(((2*base[i]+ivs[i]+evs[i]/4)*level)/100)+5
            val n=i-1
            if(up!=down){
                if(n==up)stat=stat*110/100
                else if(n==down)stat=stat*90/100
            }
            out[i]=stat
        }
        return out
    }

