    private fun canonicalGen3BaseStats(species:Int):IntArray? =
        gen3BaseStatsRows.getOrNull(species-1)?.copyOf()

    private fun parseGen3BaseStats(json:JSONObject?):IntArray? {
        json?:return null
        fun parseArray(a:JSONArray?):IntArray? {
            a?:return null
            val m=HashMap<String,Int>()
            for(i in 0 until a.length()){
                val o=a.optJSONObject(i)?:continue
                val name=o.optJSONObject("stat")?.optString("name").orEmpty()
                val value=o.optInt("base_stat",-1)
                if(name.isNotBlank()&&value>0)m[name]=value
            }
            val keys=arrayOf("hp","attack","defense","speed","special-attack","special-defense")
            if(keys.any{m[it]==null})return null
            return IntArray(6){m[keys[it]]!!}
        }
        val generationRank=mapOf(
            "generation-iii" to 3,"generation-iv" to 4,"generation-v" to 5,"generation-vi" to 6,
            "generation-vii" to 7,"generation-viii" to 8,"generation-ix" to 9
        )
        val candidates=ArrayList<Pair<Int,IntArray>>()
        val past=json.optJSONArray("past_stats")
        if(past!=null){
            for(i in 0 until past.length()){
                val o=past.optJSONObject(i)?:continue
                val generationName=o.optJSONObject("generation")?.optString("name").orEmpty()
                val rank=generationRank[generationName]?:continue
                if(rank<3)continue
                parseArray(o.optJSONArray("stats"))?.let{candidates.add(rank to it)}
            }
        }
        // PokeAPI only emits a historical row when a species' stats later changed. The oldest
        // post-Gen-2 row therefore represents the Gen 3 values; otherwise current stats apply.
        return candidates.minByOrNull{it.first}?.second ?: parseArray(json.optJSONArray("stats"))
    }

    private fun resolveGen3BaseStatsAsync(species:Int, done:(IntArray?)->Unit){
        canonicalGen3BaseStats(species)?.let{done(it);return}
        val key="gen3_base_stats_$species"
        metaPrefs.getString(key,null)?.split(',')?.mapNotNull{it.toIntOrNull()}?.takeIf{it.size==6}?.let{cached->done(cached.toIntArray());return}
        imageExecutor.execute{
            val stats=try{parseGen3BaseStats(fetchJson("https://pokeapi.co/api/v2/pokemon/$species"))}catch(_:Exception){null}
            if(stats!=null)metaPrefs.edit().putString(key,stats.joinToString(",")).apply()
            mainHandler.post{if(!isFinishing&&!isDestroyed)done(stats)}
        }
    }

    private fun prepareGen3PartyEdit(location:String,pokemon:PokemonEntry,v:Gen3EditValues){
        if(pokemon.species==386){showDialog("Party stat editing locked","Deoxys uses game-specific Generation 3 base stats. PSE will not guess which forme's cached stats should be written, so EXP, nature, IV and EV Party edits remain locked for Deoxys.");return}
        Toast.makeText(this,"Checking Gen 3 growth and battle stats…",Toast.LENGTH_SHORT).show()
        resolveGen3BaseStatsAsync(pokemon.species) baseStats@{base->
            if(base==null){showDialog("Could not verify Gen 3 stats","PSE could not resolve Generation 3 base stats for this species. No changes were written.");return@baseStats}
            resolveBoxedLevelAsync(pokemon.species,pokemon.experience) currentLevel@{oldLevel->
                if(oldLevel==null || pokemon.level==null || oldLevel!=pokemon.level){showDialog("Could not verify current level","The stored Party level does not match the level implied by its EXP, or the growth curve could not be resolved. No changes were written.");return@currentLevel}
                resolveBoxedLevelAsync(pokemon.species,v.exp) targetLevel@{newLevel->
                    if(newLevel==null){showDialog("Could not resolve new level","PSE could not map the requested EXP to a Gen 3 level. No changes were written.");return@targetLevel}
                    val rebuild=Gen3PartyRebuild(newLevel,base)
                    AlertDialog.Builder(this).setTitle("Save Gen 3 Party changes?").setMessage("PSE verified this Pokémon's Gen 3 growth curve and base stats. It will rebuild Level, Max HP and all cached battle stats from EXP, nature, IVs and EVs, preserve current HP up to the new maximum, then rebuild the PK3 and Gen 3 section checksum. Any failure restores the original working copy.").setNegativeButton("Cancel",null).setPositiveButton("Save"){_,_->applyGen3PokemonEdit(location,pokemon,v,rebuild)}.show()
                }
            }
        }
    }

    private fun mutatePk3(raw:ByteArray, party:Boolean, v:Gen3EditValues, partyRebuild:Gen3PartyRebuild?=null):ByteArray {
        val out=raw.copyOf()
        val oldPid=readU32LE(out,0); val newPid=gen3PidForNatureShiny(oldPid,v.tid,v.sid,v.nature,v.shiny)
        val oldOid=readU32LE(out,4)
        val enc=out.copyOfRange(0x20,0x50); val oldKey=(oldPid xor oldOid).toInt(); val dec=enc.copyOf()
        var x=0
        while(x<48){val n=readU32LE(dec,x).toInt() xor oldKey;writeU32LE(dec,x,n.toLong() and 0xFFFFFFFFL);x+=4}
        val oldOrder=gen3Orders[(oldPid%24L).toInt()]; val blocks=HashMap<Char,ByteArray>()
        for(i in 0..3) blocks[oldOrder[i]]=dec.copyOfRange(i*12,i*12+12)
        val g=blocks['G']!!;val a=blocks['A']!!;val e=blocks['E']!!;val m=blocks['M']!!
        writeU16LE(g,2,v.held);writeU32LE(g,4,v.exp);g[9]=v.friendship.toByte()
        for(i in 0..3){writeU16LE(a,i*2,v.moves[i]);a[8+i]=v.pp[i].toByte()}
        for(i in 0..5)e[i]=v.evs[i].toByte()
        var ivw=readU32LE(m,4)
        ivw=ivw and 0xC0000000L
        for(i in 0..5)ivw=ivw or ((v.ivs[i].toLong() and 31L) shl (i*5))
        ivw = if(v.abilitySlot==2) ivw or 0x80000000L else ivw and 0x7FFFFFFFL
        writeU32LE(m,4,ivw)
        writeU32LE(out,0,newPid);writeU16LE(out,4,v.tid);writeU16LE(out,6,v.sid)
        writeGen3Text(out,8,10,v.nickname);writeGen3Text(out,0x14,7,v.ot)
        val newOrder=gen3Orders[(newPid%24L).toInt()]; val plain=ByteArray(48)
        for(i in 0..3)(blocks[newOrder[i]]!!).copyInto(plain,i*12)
        var sum=0;for(i in 0 until 48 step 2)sum=(sum+readU16LE(plain,i)) and 0xFFFF;writeU16LE(out,0x1C,sum)
        val oid=((v.sid.toLong() and 0xFFFFL) shl 16) or (v.tid.toLong() and 0xFFFFL); val key=(newPid xor oid).toInt()
        x=0;while(x<48){val n=readU32LE(plain,x).toInt() xor key;writeU32LE(plain,x,n.toLong() and 0xFFFFFFFFL);x+=4}
        plain.copyInto(out,0x20)
        if(partyRebuild!=null){
            require(party && out.size==100){"Party stat rebuild requires a 100-byte PK3"}
            val stats=calculateGen3BattleStats(partyRebuild.baseStats,v.ivs,v.evs,v.nature,partyRebuild.level)
            val oldCurrent=readU16LE(out,0x56)
            out[0x54]=partyRebuild.level.toByte()
            writeU16LE(out,0x56,oldCurrent.coerceAtMost(stats[0]))
            writeU16LE(out,0x58,stats[0]);writeU16LE(out,0x5A,stats[1]);writeU16LE(out,0x5C,stats[2])
            writeU16LE(out,0x5E,stats[3]);writeU16LE(out,0x60,stats[4]);writeU16LE(out,0x62,stats[5])
        }
        return out
    }

    private fun updateGen3SectionChecksumAt(save: ByteArray, base: Int, id: Int) {
        if (id !in 0..13) throw IllegalArgumentException("Invalid Gen 3 section id $id")
        if (base < 0 || base + 0x1000 > save.size) throw IllegalArgumentException("Invalid Gen 3 section base")
        if (readU16LE(save, base + 0xFF4) != id) throw IllegalStateException("Gen 3 section $id moved unexpectedly")
        writeU16LE(save, base + 0xFF6, gen3SectionChecksum(save, base, gen3SectionLengths[id]))
    }

    private fun updateGen3SectionChecksum(save:ByteArray,id:Int){
        val b=gen3ActiveSection(save,id) ?: throw IllegalStateException("Missing Gen 3 section $id")
        updateGen3SectionChecksumAt(save,b,id)
    }

    private fun writeGen3PcBuffer(save:ByteArray,pc:ByteArray){
        // Resolve the complete active section table while the save is still valid. Once the
        // first changed PC section is copied its old checksum is temporarily stale, so trying
        // to rediscover later sections via gen3ValidSlot() would incorrectly make them vanish.
        val sectionMap = gen3ActiveSectionMap(save) ?: throw IllegalStateException("Could not map active Gen 3 save sections")
        var src=0
        for(id in 5..13){
            val b=sectionMap[id]
            if(b<0) throw IllegalStateException("Missing Gen 3 PC section $id")
            val len=gen3SectionLengths[id]
            pc.copyInto(save,b,src,src+len)
            src+=len
            updateGen3SectionChecksumAt(save,b,id)
        }
    }

    private data class Gen3ContestSnapshot(
        val raw: ByteArray, val offset: Int, val pc: ByteArray?, val member: PokemonEntry
    )

    private fun gen3ContestSnapshot(
        file: File, opened: ByteArray, sourceUri: Uri?, sourceLabel: String?,
        location: String, expected: PokemonEntry
    ): Gen3ContestSnapshot {
        require(importedFile?.absolutePath == file.absolutePath &&
            currentSourceUri == sourceUri && currentSourceLabel == sourceLabel &&
            file.readBytes().contentEquals(opened) && gen3SaveValid(opened)) {
            "The save or its identity changed. Reopen this Pokémon before editing Pokémon metadata."
        }
        val global = boxedLocationToGlobalIndex(location)
        val pc: ByteArray?
        val offset: Int
        val buffer: ByteArray
        val party: Boolean
        if (global != null) {
            require(global in 0 until 420) { "The selected Gen 3 PC slot is invalid." }
            val storage = gen3PcBuffer(opened) ?: error("The Gen 3 PC could not be opened.")
            pc = storage
            offset = 4 + global * 80
            buffer = storage
            party = false
        } else {
            val slot = partyLocationToSlot(location) ?: error("The Pokémon location is invalid.")
            val game = detectGen3GameFromData(opened, sourceLabel ?: file.name)
            val start = gen3PartyOffset(opened, game) ?: error("The Gen 3 party could not be located.")
            require(start >= 4 && start + 600 <= opened.size) { "The party storage is incomplete." }
            val count = readU32LE(opened, start - 4).toInt()
            require(count in 1..6 && slot in 0 until count) { "The selected party slot is no longer active." }
            offset = start + slot * 100
            pc = null
            buffer = opened
            party = true
        }
        val current = parsePk3(buffer, offset, party) ?: error("The selected Pokémon could not be read.")
        require(current.checksumValid && expected.checksumValid && current.pid == expected.pid &&
            current.species == expected.species && current.tid == expected.tid && current.sid == expected.sid &&
            current.nickname == expected.nickname && current.otName == expected.otName &&
            current.experience == expected.experience && current.level == expected.level &&
            current.heldItem == expected.heldItem && current.isEgg == expected.isEgg &&
            current.friendship == expected.friendship && current.language == expected.language &&
            current.markingValue == expected.markingValue && current.moves.contentEquals(expected.moves) &&
            current.movePP.contentEquals(expected.movePP) && current.ivs.contentEquals(expected.ivs) &&
            current.evs.contentEquals(expected.evs)) { "The displayed Pokémon changed. Reopen its details." }
        val raw = buffer.copyOfRange(offset, offset + (if (party) 100 else 80))
        Gen3ContestEditing.read(raw)
        return Gen3ContestSnapshot(raw, offset, pc, current)
    }

    private fun showGen3ContestEditor(
        file: File, opened: ByteArray, sourceUri: Uri?, sourceLabel: String?,
        location: String, expected: PokemonEntry
    ) {
        try {
            val snapshot = gen3ContestSnapshot(file, opened, sourceUri, sourceLabel, location, expected)
            val before = Gen3ContestEditing.read(snapshot.raw)
            val names = listOf("Cool", "Beauty", "Cute", "Smart", "Tough", "Sheen")
            val oldValues = listOf(before.cool, before.beauty, before.cute, before.smart, before.tough, before.sheen)
            val form = LinearLayout(this).apply {
                orientation = LinearLayout.VERTICAL
                setPadding(dp(20), dp(8), dp(20), dp(8))
            }
            addMutedLine(form, "$location • Stored Gen 3 condition values (0–255). " +
                "This edits this Pokémon's condition only; ribbons and contest progress stay unchanged.")
            val fields = names.mapIndexed { index, name ->
                inputField(name, oldValues[index].toString(), true).also { form.addView(it.first) }.second
            }
            var consumed = false
            AlertDialog.Builder(this)
                .setTitle("Contest condition & sheen")
                .setView(ScrollView(this).apply { addView(form) })
                .setNegativeButton("Cancel") { _, _ -> consumed = true }
                .setOnCancelListener { consumed = true }
                .setPositiveButton("Review") { _, _ ->
                    if (!consumed) {
                        consumed = true
                        try {
                            val fresh = gen3ContestSnapshot(file, opened, sourceUri, sourceLabel, location, expected)
                            val numbers = fields.map { field ->
                                field.text.toString().toIntOrNull()?.also { value ->
                                    require(value in 0..255) { "Every condition value must be between 0 and 255." }
                                } ?: error("Enter a whole number from 0 to 255 for each value.")
                            }
                            val values = Gen3ContestState(numbers[0], numbers[1], numbers[2],
                                numbers[3], numbers[4], numbers[5])
                            val edited = Gen3ContestEditing.replace(fresh.raw, values)
                            if (edited.contentEquals(fresh.raw)) {
                                showDialog("Condition unchanged", "No condition values were changed.")
                            } else {
                                val changes = names.indices.filter { oldValues[it] != numbers[it] }
                                    .joinToString("\n") { "${names[it]}: ${oldValues[it]} → ${numbers[it]}" }
                                var applied = false
                                AlertDialog.Builder(this)
                                    .setTitle("Save Gen 3 condition changes?")
                                    .setMessage("$location\n\n$changes\n\nPSE will retain a verified recovery backup, " +
                                        "repair Pokémon and save checksums, reopen and verify the exact record. " +
                                        "Other Pokémon fields, party stats, ribbons and unrelated slots stay unchanged.")
                                    .setNegativeButton("Cancel") { _, _ -> applied = true }
                                    .setOnCancelListener { applied = true }
                                    .setPositiveButton("Save condition") { _, _ ->
                                        if (!applied) {
                                            applied = true
                                            applyGen3ContestEdit(file, opened, sourceUri, sourceLabel,
                                                location, expected, values)
                                        }
                                    }.show()
                            }
                        } catch (error: Exception) {
                            showDialog("Condition edit stopped", error.message ?: "The condition could not be reviewed.")
                        }
                    }
                }.show()
        } catch (error: Exception) {
            showDialog("Condition edit stopped", error.message ?: "This Pokémon's condition could not be opened.")
        }
    }

    private fun applyGen3ContestEdit(
        file: File, opened: ByteArray, sourceUri: Uri?, sourceLabel: String?,
        location: String, expected: PokemonEntry, values: Gen3ContestState
    ) {
        var writeStarted = false
        try {
            val snapshot = gen3ContestSnapshot(file, opened, sourceUri, sourceLabel, location, expected)
            val edited = Gen3ContestEditing.replace(snapshot.raw, values)
            if (edited.contentEquals(snapshot.raw)) return
            val changed = edited.indices.filter { edited[it] != snapshot.raw[it] }.toSet()
            val sectionMap = gen3ActiveSectionMap(opened) ?: error("The active save sections could not be mapped.")
            val work = opened.copyOf()
            val allowed = HashSet<Int>()
            val sourcePc = snapshot.pc
            if (sourcePc != null) {
                val editedPc = sourcePc.copyOf()
                edited.copyInto(editedPc, snapshot.offset)
                writeGen3PcBuffer(work, editedPc)
                require(gen3PcBuffer(work)?.contentEquals(editedPc) == true) { "The staged PC did not verify." }
                val pcOffsets = changed.map { snapshot.offset + it }.toSet()
                var pcBase = 0
                for (sectionId in 5..13) {
                    val sectionBase = sectionMap[sectionId]
                    require(sectionBase >= 0) { "Missing Gen 3 PC section $sectionId." }
                    val length = gen3SectionLengths[sectionId]
                    for (local in 0 until length) {
                        if (pcBase + local in pcOffsets) allowed.add(sectionBase + local)
                    }
                    allowed.add(sectionBase + 0xFF6)
                    allowed.add(sectionBase + 0xFF7)
                    pcBase += length
                }
            } else {
                val section1 = sectionMap[1]
                require(section1 >= 0 && snapshot.offset >= section1 &&
                    snapshot.offset + 100 <= section1 + gen3SectionLengths[1]) {
                    "The selected party record is outside its validated section."
                }
                edited.copyInto(work, snapshot.offset)
                updateGen3SectionChecksumAt(work, section1, 1)
                changed.forEach { allowed.add(snapshot.offset + it) }
                allowed.add(section1 + 0xFF6)
                allowed.add(section1 + 0xFF7)
            }
            require(gen3SaveValid(work) && work.indices.all { it in allowed || work[it] == opened[it] }) {
                "The staged condition edit failed checksum or unrelated-byte verification."
            }
            val backup = File.createTempFile(backupGameName(file) + "_PreGen3Condition_", ".backup", backupsDir())
            backup.writeBytes(opened)
            require(backup.readBytes().contentEquals(opened)) { "The recovery backup did not verify." }
            retainGen2ToGen3SafetyBackup(backup, opened)
            gen3ContestSnapshot(file, opened, sourceUri, sourceLabel, location, expected)
            writeStarted = true
            file.writeBytes(work)
            val persisted = file.readBytes()
            require(persisted.contentEquals(work) && gen3SaveValid(persisted)) {
                "The persisted condition edit failed byte or checksum verification."
            }
            val reopened = gen3ContestSnapshot(file, persisted, sourceUri, sourceLabel, location, expected)
            require(reopened.raw.contentEquals(edited) && Gen3ContestEditing.read(reopened.raw) == values) {
                "The condition values did not reopen exactly."
            }
            Toast.makeText(this, "Gen 3 condition saved and verified; recovery backup retained", Toast.LENGTH_LONG).show()
            showPokemonDetails(location, reopened.member)
        } catch (error: Exception) {
            val restored = if (writeStarted) runCatching {
                file.writeBytes(opened)
                val restoredBytes = file.readBytes()
                restoredBytes.contentEquals(opened) && gen3SaveValid(restoredBytes)
            }.getOrDefault(false) else false
            val recovery = when {
                !writeStarted -> "Nothing was written."
                restored -> "The original save was restored and verified."
                else -> "Automatic restore could not be verified. Restore the retained backup before editing again."
            }
            showDialog("Gen 3 condition edit failed", (error.message ?: "Unknown error") + "\n\n" + recovery)
        }
    }

