    private fun gen3PpUpBasePp(member: PokemonEntry): Map<Int, Int> =
        member.moves.distinct().filter { it != 0 }.associateWith { move ->
            canonicalGen3MovePp(move) ?: error("Verified Gen 3 PP data is unavailable for move #$move.")
        }

    private fun showGen3PpUpEditor(
        file: File, opened: ByteArray, sourceUri: Uri?, sourceLabel: String?,
        location: String, expected: PokemonEntry
    ) {
        try {
            val snapshot = gen3ContestSnapshot(file, opened, sourceUri, sourceLabel, location, expected)
            val basePp = gen3PpUpBasePp(snapshot.member)
            val before = Gen3PpUpEditing.read(snapshot.raw, basePp)
            val form = LinearLayout(this).apply {
                orientation = LinearLayout.VERTICAL
                setPadding(dp(20), dp(8), dp(20), dp(8))
            }
            addMutedLine(form, "$location • Edit each move's PP Up count. Current PP stays unchanged. " +
                "A reduction is blocked if current PP would exceed the new maximum.")
            val names = snapshot.member.moves.map { canonicalGen3MoveName(it) ?: error("Unknown Gen 3 move.") }
            val fields = (0 until 4).map { slot ->
                val move = snapshot.member.moves[slot]
                val options = if (move == 0 || (basePp[move] ?: 0) <= 4) listOf(0) else (0..3).toList()
                addMutedLine(form, "${slot + 1}. ${names[slot]} • Current PP: ${snapshot.member.movePP[slot]}")
                spinnerField("PP Ups", options.map { ups ->
                    "$ups • maximum PP ${Gen3PpUpEditing.maximumPp(move, ups, basePp)}"
                }, before[slot]).also { form.addView(it.first) }.second.also { it.isEnabled = options.size > 1 }
            }
            var consumed = false
            AlertDialog.Builder(this)
                .setTitle("Move PP Ups")
                .setView(ScrollView(this).apply { addView(form) })
                .setNegativeButton("Cancel") { _, _ -> consumed = true }
                .setOnCancelListener { consumed = true }
                .setPositiveButton("Review") { _, _ ->
                    if (!consumed) {
                        consumed = true
                        try {
                            val fresh = gen3ContestSnapshot(file, opened, sourceUri, sourceLabel, location, expected)
                            val values = fields.map { it.selectedItemPosition }
                            val edited = Gen3PpUpEditing.replace(fresh.raw, values, basePp)
                            if (edited.contentEquals(fresh.raw)) {
                                showDialog("PP Ups unchanged", "No PP Up counts were changed.")
                            } else {
                                val changes = (0 until 4).filter { before[it] != values[it] }.joinToString("\n") { slot ->
                                    val move = snapshot.member.moves[slot]
                                    val oldMax = Gen3PpUpEditing.maximumPp(move, before[slot], basePp)
                                    val newMax = Gen3PpUpEditing.maximumPp(move, values[slot], basePp)
                                    "${slot + 1}. ${names[slot]}: ${before[slot]} → ${values[slot]} PP Ups; maximum PP $oldMax → $newMax"
                                }
                                var applied = false
                                AlertDialog.Builder(this)
                                    .setTitle("Save Gen 3 PP Up changes?")
                                    .setMessage("$location\n\n$changes\n\nPSE will retain a verified recovery backup, " +
                                        "repair Pokémon and save checksums, reopen and verify the exact record. " +
                                        "Moves, current PP, other Pokémon fields, party stats and unrelated slots stay unchanged.")
                                    .setNegativeButton("Cancel") { _, _ -> applied = true }
                                    .setOnCancelListener { applied = true }
                                    .setPositiveButton("Save PP Ups") { _, _ ->
                                        if (!applied) {
                                            applied = true
                                            applyGen3PpUpEdit(file, opened, sourceUri, sourceLabel,
                                                location, expected, values)
                                        }
                                    }.show()
                            }
                        } catch (error: Exception) {
                            showDialog("PP Up edit stopped", error.message ?: "The PP Up counts could not be reviewed.")
                        }
                    }
                }.show()
        } catch (error: Exception) {
            showDialog("PP Up edit stopped", error.message ?: "This Pokémon's PP Ups could not be opened.")
        }
    }

