    private fun showGen3ForgetMoveEditor(
        file: File, opened: ByteArray, sourceUri: Uri?, sourceLabel: String?,
        location: String, expected: PokemonEntry
    ) {
        try {
            val snapshot = gen3ContestSnapshot(file, opened, sourceUri, sourceLabel, location, expected)
            val basePp = gen3PpUpBasePp(snapshot.member)
            val before = Gen3MoveOrderEditing.read(snapshot.raw, basePp)
            val count = before.takeWhile { it.moveId != 0 }.size
            if (count < 2) {
                showDialog("Last move protected", "A Pokémon must keep at least one move. There are no extra moves to forget.")
                return
            }
            val form = LinearLayout(this).apply {
                orientation = LinearLayout.VERTICAL
                setPadding(dp(20), dp(8), dp(20), dp(8))
            }
            addMutedLine(form, "$location • Choose one move to forget. " +
                "Remaining moves shift up with their current PP and PP Ups. The last move is protected.")
            val names = before.map { canonicalGen3MoveName(it.moveId) ?: error("Unknown Gen 3 move.") }
            val options = (0 until count).map { slot ->
                "Slot ${slot + 1}: ${names[slot]} • PP ${before[slot].pp} • PP Ups ${before[slot].ppUps}"
            }
            val choice = spinnerField("Move to forget", options, 0).also { form.addView(it.first) }.second
            var consumed = false
            AlertDialog.Builder(this)
                .setTitle("Forget a move")
                .setView(ScrollView(this).apply { addView(form) })
                .setNegativeButton("Cancel") { _, _ -> consumed = true }
                .setOnCancelListener { consumed = true }
                .setPositiveButton("Review") { _, _ ->
                    if (!consumed) {
                        consumed = true
                        try {
                            val fresh = gen3ContestSnapshot(file, opened, sourceUri, sourceLabel, location, expected)
                            val selectedSlot = choice.selectedItemPosition
                            val edited = Gen3MoveForgetting.forget(fresh.raw, selectedSlot, basePp)
                            if (edited.contentEquals(fresh.raw)) {
                                showDialog("Moves unchanged", "No move was forgotten.")
                            } else {
                                val after = Gen3MoveOrderEditing.read(edited, basePp)
                                val changes = (0 until 4).joinToString("\n") { slot ->
                                    val name = canonicalGen3MoveName(after[slot].moveId) ?: error("Unknown Gen 3 move.")
                                    "Slot ${slot + 1}: ${names[slot]} → $name " +
                                        "(PP ${after[slot].pp}, PP Ups ${after[slot].ppUps})"
                                }
                                var applied = false
                                AlertDialog.Builder(this)
                                    .setTitle("Forget ${names[selectedSlot]}?")
                                    .setMessage("$location\n\n$changes\n\nPSE will retain a verified recovery backup, " +
                                        "repair Pokémon and save checksums, reopen and verify the exact record. " +
                                        "Remaining moves retain their PP and PP Ups; the final empty slot is cleared. Other fields, party stats and unrelated slots stay unchanged.")
                                    .setNegativeButton("Cancel") { _, _ -> applied = true }
                                    .setOnCancelListener { applied = true }
                                    .setPositiveButton("Forget move") { _, _ ->
                                        if (!applied) {
                                            applied = true
                                            applyGen3ForgetMove(file, opened, sourceUri, sourceLabel,
                                                location, expected, selectedSlot)
                                        }
                                    }.show()
                            }
                        } catch (error: Exception) {
                            showDialog("Move forgetting stopped", error.message ?: "The move-forgetting edit could not be reviewed.")
                        }
                    }
                }.show()
        } catch (error: Exception) {
            showDialog("Move forgetting stopped", error.message ?: "This Pokémon's moves could not be opened.")
        }
    }

    private fun applyGen3ForgetMove(
        file: File, opened: ByteArray, sourceUri: Uri?, sourceLabel: String?,
        location: String, expected: PokemonEntry, selectedSlot: Int
    ) {
        var writeStarted = false
        try {
            val snapshot = gen3ContestSnapshot(file, opened, sourceUri, sourceLabel, location, expected)
            val basePp = gen3PpUpBasePp(snapshot.member)
            val before = Gen3MoveOrderEditing.read(snapshot.raw, basePp)
            val edited = Gen3MoveForgetting.forget(snapshot.raw, selectedSlot, basePp)
            if (edited.contentEquals(snapshot.raw)) return
            val changed = edited.indices.filter { edited[it] != snapshot.raw[it] }.toSet()
            val sectionMap = gen3ActiveSectionMap(opened) ?: error("The active save sections could not be mapped.")
            val work = opened.copyOf()
            val allowed = HashSet<Int>()
            val sourcePc = snapshot.pc
            if (sourcePc != null) {
                val editedPc = sourcePc.copyOf()
                edited.copyInto(editedPc, snapshot.offset)
                writeGen3PcBuffer(work, editedPc)
                require(gen3PcBuffer(work)?.contentEquals(editedPc) == true) { "The staged PC did not verify." }
                val pcOffsets = changed.map { snapshot.offset + it }.toSet()
                var pcBase = 0
                for (sectionId in 5..13) {
                    val sectionBase = sectionMap[sectionId]
                    require(sectionBase >= 0) { "Missing Gen 3 PC section $sectionId." }
                    val length = gen3SectionLengths[sectionId]
                    for (local in 0 until length) {
                        if (pcBase + local in pcOffsets) allowed.add(sectionBase + local)
                    }
                    allowed.add(sectionBase + 0xFF6)
                    allowed.add(sectionBase + 0xFF7)
                    pcBase += length
                }
            } else {
                val section1 = sectionMap[1]
                require(section1 >= 0 && snapshot.offset >= section1 &&
                    snapshot.offset + 100 <= section1 + gen3SectionLengths[1]) {
                    "The selected party record is outside its validated section."
                }
                edited.copyInto(work, snapshot.offset)
                updateGen3SectionChecksumAt(work, section1, 1)
                changed.forEach { allowed.add(snapshot.offset + it) }
                allowed.add(section1 + 0xFF6)
                allowed.add(section1 + 0xFF7)
            }
            require(gen3SaveValid(work) && work.indices.all { it in allowed || work[it] == opened[it] }) {
                "The staged move-forgetting edit failed checksum or unrelated-byte verification."
            }
            val backup = File.createTempFile(backupGameName(file) + "_PreGen3ForgetMove_", ".backup", backupsDir())
            backup.writeBytes(opened)
            require(backup.readBytes().contentEquals(opened)) { "The recovery backup did not verify." }
            retainGen2ToGen3SafetyBackup(backup, opened)
            gen3ContestSnapshot(file, opened, sourceUri, sourceLabel, location, expected)
            writeStarted = true
            file.writeBytes(work)
            val persisted = file.readBytes()
            require(persisted.contentEquals(work) && gen3SaveValid(persisted)) {
                "The persisted move-forgetting edit failed byte or checksum verification."
            }
            val remaining = before.filterIndexed { index, move -> index != selectedSlot && move.moveId != 0 }
            val expectedSlots = remaining + List(4 - remaining.size) { Gen3MoveSlot(0, 0, 0) }
            val expectedAfter = snapshot.member.copy(
                moves = IntArray(4) { expectedSlots[it].moveId },
                movePP = IntArray(4) { expectedSlots[it].pp })
            val reopened = gen3ContestSnapshot(file, persisted, sourceUri, sourceLabel, location, expectedAfter)
            require(reopened.raw.contentEquals(edited) && Gen3MoveOrderEditing.read(reopened.raw, basePp) == expectedSlots) {
                "The remaining move slots did not reopen exactly."
            }
            Toast.makeText(this, "Move forgotten and verified; recovery backup retained", Toast.LENGTH_LONG).show()
            showPokemonDetails(location, reopened.member)
        } catch (error: Exception) {
            val restored = if (writeStarted) runCatching {
                file.writeBytes(opened)
                val restoredBytes = file.readBytes()
                restoredBytes.contentEquals(opened) && gen3SaveValid(restoredBytes)
            }.getOrDefault(false) else false
            val recovery = when {
                !writeStarted -> "Nothing was written."
                restored -> "The original save was restored and verified."
                else -> "Automatic restore could not be verified. Restore the retained backup before editing again."
            }
            showDialog("Gen 3 move-forgetting edit failed", (error.message ?: "Unknown error") + "\n\n" + recovery)
        }
    }

