    private fun showGen3PartyStatusEditor(
        file: File, opened: ByteArray, sourceUri: Uri?, sourceLabel: String?,
        location: String, expected: PokemonEntry
    ) {
        try {
            val snapshot = gen3ContestSnapshot(file, opened, sourceUri, sourceLabel, location, expected)
            require(snapshot.pc == null) { "Status conditions are stored only on party Pokémon." }
            val before = Gen3PartyStatusEditing.read(snapshot.raw)
            val form = LinearLayout(this).apply {
                orientation = LinearLayout.VERTICAL
                setPadding(dp(20), dp(8), dp(20), dp(8))
            }
            addMutedLine(form, "$location • Edit the party status condition without changing HP, PP or stats. " +
                "Sleep turns apply only to Sleep; the bad-poison counter applies only to Bad poison. " +
                "Fainted Pokémon can be cured but cannot receive a new condition.")
            val condition = spinnerField("Status condition", Gen3PartyStatusEditing.conditionNames, before.condition.ordinal)
                .also { form.addView(it.first) }.second
            val sleep = inputField("Sleep turns remaining (1–7, Sleep only)",
                (if (before.sleepTurns > 0) before.sleepTurns else 1).toString(), true)
                .also { form.addView(it.first) }.second
            val toxic = inputField("Bad-poison counter (0–15, Bad poison only)", before.toxicCounter.toString(), true)
                .also { form.addView(it.first) }.second
            fun summary(value: Gen3PartyStatus): String = when (value.condition) {
                Gen3StatusCondition.SLEEP -> "Sleep (${value.sleepTurns} turns remaining)"
                Gen3StatusCondition.BAD_POISON -> "Bad poison (counter ${value.toxicCounter})"
                else -> Gen3PartyStatusEditing.conditionNames[value.condition.ordinal]
            }
            var consumed = false
            AlertDialog.Builder(this)
                .setTitle("Party status condition")
                .setView(ScrollView(this).apply { addView(form) })
                .setNegativeButton("Cancel") { _, _ -> consumed = true }
                .setOnCancelListener { consumed = true }
                .setPositiveButton("Review") { _, _ ->
                    if (!consumed) {
                        consumed = true
                        try {
                            val fresh = gen3ContestSnapshot(file, opened, sourceUri, sourceLabel, location, expected)
                            val chosen = Gen3StatusCondition.values()[condition.selectedItemPosition]
                            val values = Gen3PartyStatus(chosen,
                                if (chosen == Gen3StatusCondition.SLEEP) sleep.text.toString().toIntOrNull()
                                    ?: error("Enter a whole number for sleep turns.") else 0,
                                if (chosen == Gen3StatusCondition.BAD_POISON) toxic.text.toString().toIntOrNull()
                                    ?: error("Enter a whole number for the bad-poison counter.") else 0).requireValid()
                            val edited = Gen3PartyStatusEditing.replace(fresh.raw, values)
                            if (edited.contentEquals(fresh.raw)) {
                                showDialog("Status unchanged", "The party status was not changed.")
                            } else {
                                var applied = false
                                AlertDialog.Builder(this)
                                    .setTitle("Save party status?")
                                    .setMessage("$location\n\n${summary(before)} → ${summary(values)}\n\n" +
                                        "PSE will retain a verified recovery backup, update the save checksum and reopen the saved record. " +
                                        "HP, stats, PP, Pokémon data and other party slots stay unchanged.")
                                    .setNegativeButton("Cancel") { _, _ -> applied = true }
                                    .setOnCancelListener { applied = true }
                                    .setPositiveButton("Save status") { _, _ ->
                                        if (!applied) {
                                            applied = true
                                            applyGen3PartyStatusEdit(file, opened, sourceUri, sourceLabel,
                                                location, expected, values)
                                        }
                                    }.show()
                            }
                        } catch (error: Exception) {
                            showDialog("Party status edit stopped", error.message ?: "The status change could not be reviewed.")
                        }
                    }
                }.show()
        } catch (error: Exception) {
            showDialog("Party status unavailable", error.message ?: "This Pokémon's party status could not be opened.")
        }
    }

    private fun applyGen3PartyStatusEdit(
        file: File, opened: ByteArray, sourceUri: Uri?, sourceLabel: String?,
        location: String, expected: PokemonEntry, values: Gen3PartyStatus
    ) {
        var writeStarted = false
        try {
            val snapshot = gen3ContestSnapshot(file, opened, sourceUri, sourceLabel, location, expected)
            require(snapshot.pc == null) { "Status conditions are stored only on party Pokémon." }
            val edited = Gen3PartyStatusEditing.replace(snapshot.raw, values)
            if (edited.contentEquals(snapshot.raw)) return
            val sectionMap = gen3ActiveSectionMap(opened) ?: error("The active save sections could not be mapped.")
            val section1 = sectionMap[1]
            require(section1 >= 0 && snapshot.raw.size == 100 && snapshot.offset >= section1 &&
                snapshot.offset + 100 <= section1 + gen3SectionLengths[1]) {
                "The selected party record is outside its validated section."
            }
            val work = opened.copyOf()
            edited.copyInto(work, snapshot.offset)
            updateGen3SectionChecksumAt(work, section1, 1)
            val allowed = (0x50..0x53).map { snapshot.offset + it }.toSet() +
                setOf(section1 + 0xFF6, section1 + 0xFF7)
            require(gen3SaveValid(work) && work.indices.all { it in allowed || work[it] == opened[it] }) {
                "The staged party status edit failed checksum or unrelated-byte verification."
            }
            val backup = File.createTempFile(backupGameName(file) + "_PreGen3PartyStatus_", ".backup", backupsDir())
            backup.writeBytes(opened)
            require(backup.readBytes().contentEquals(opened)) { "The recovery backup did not verify." }
            retainGen2ToGen3SafetyBackup(backup, opened)
            gen3ContestSnapshot(file, opened, sourceUri, sourceLabel, location, expected)
            writeStarted = true
            file.writeBytes(work)
            val persisted = file.readBytes()
            require(persisted.contentEquals(work) && gen3SaveValid(persisted)) {
                "The persisted party status edit failed byte or checksum verification."
            }
            val reopened = gen3ContestSnapshot(file, persisted, sourceUri, sourceLabel, location, expected)
            require(reopened.raw.contentEquals(edited) && Gen3PartyStatusEditing.read(reopened.raw) == values) {
                "The party status did not reopen exactly."
            }
            Toast.makeText(this, "Party status saved and verified; recovery backup retained", Toast.LENGTH_LONG).show()
            showPokemonDetails(location, reopened.member)
        } catch (error: Exception) {
            val restored = if (writeStarted) runCatching {
                file.writeBytes(opened)
                val restoredBytes = file.readBytes()
                restoredBytes.contentEquals(opened) && gen3SaveValid(restoredBytes)
            }.getOrDefault(false) else false
            val recovery = when {
                !writeStarted -> "Nothing was written."
                restored -> "The original save was restored and verified."
                else -> "Automatic restore could not be verified. Restore the retained backup before editing again."
            }
            showDialog("Gen 3 party status edit failed", (error.message ?: "Unknown error") + "\n\n" + recovery)
        }
    }

    private fun gen3PartyPpCatalog(): Map<Int, Int> = (1..354).associateWith { move ->
        canonicalGen3MovePp(move) ?: error("Verified Gen 3 PP is unavailable for move #$move.")
    }

    private fun showGen3SelectedPartyPpRecovery(
        file: File, opened: ByteArray, sourceUri: Uri?, sourceLabel: String?,
        selectedSlots: List<Int>? = null
    ) {
        try {
            val snapshot = gen3PartyMarkingSnapshot(file, opened, sourceUri, sourceLabel)
            val candidates = snapshot.members.indices.filter { !snapshot.members[it].isEgg }
            require(candidates.isNotEmpty()) { "There are no non-Egg party Pokémon to restore." }
            if (selectedSlots == null) {
                val selected = linkedSetOf<Int>()
                val labels = candidates.map { slot ->
                    val member = snapshot.members[slot]
                    "Slot ${slot + 1} • ${member.nickname.ifBlank { "Species #${member.species}" }}"
                }
                var consumed = false
                AlertDialog.Builder(this)
                    .setTitle("Select party Pokémon for PP recovery")
                    .setMultiChoiceItems(labels.toTypedArray(), BooleanArray(candidates.size)) { _, index, checked ->
                        val slot = candidates.getOrNull(index) ?: return@setMultiChoiceItems
                        if (checked) selected.add(slot) else selected.remove(slot)
                    }
                    .setNegativeButton("Cancel") { _, _ -> consumed = true }
                    .setOnCancelListener { consumed = true }
                    .setPositiveButton("Review PP recovery") { _, _ ->
                        if (!consumed) {
                            consumed = true
                            showGen3SelectedPartyPpRecovery(file, opened, sourceUri, sourceLabel, selected.toList().sorted())
                        }
                    }.show()
                return
            }
            val slots = selectedSlots.toList()
            require(slots.all { it in candidates }) { "Only active non-Egg party Pokémon can have PP restored." }
            val catalog = gen3PartyPpCatalog()
            val result = Gen3PartyPpRestoration.restore(snapshot.records, snapshot.count, slots, catalog)
            if (result.changedSlots.isEmpty()) {
                showDialog("PP already full", "The selected party Pokémon already have full PP. Nothing was written.")
                return
            }
            val changes = result.changedSlots.joinToString("\n\n") { slot ->
                val member = snapshot.members[slot]
                val before = Gen3MoveOrderEditing.read(snapshot.records.copyOfRange(slot * 100, (slot + 1) * 100), catalog)
                val after = Gen3MoveOrderEditing.read(result.partyRecords.copyOfRange(slot * 100, (slot + 1) * 100), catalog)
                val moves = before.indices.filter { before[it].moveId != 0 && before[it].pp != after[it].pp }
                    .joinToString("\n") { index ->
                        val name = canonicalGen3MoveName(before[index].moveId) ?: error("Unknown Gen 3 move.")
                        "$name: ${before[index].pp} → ${after[index].pp} PP"
                    }
                "Slot ${slot + 1} • ${member.nickname.ifBlank { "Species #${member.species}" }}\n$moves"
            }
            var consumed = false
            AlertDialog.Builder(this)
                .setTitle("Restore PP for ${result.changedSlots.size} party Pokémon?")
                .setMessage(changes + "\n\nRestore moves to their maximum PP with the existing PP Ups. " +
                    "HP, status, stats, moves and PP Ups stay unchanged. Eggs, unselected Pokémon and inactive slots stay unchanged. " +
                    "PSE will retain one verified recovery backup, save the complete batch and reopen it for verification.")
                .setNegativeButton("Cancel") { _, _ -> consumed = true }
                .setOnCancelListener { consumed = true }
                .setPositiveButton("Restore selected PP") { _, _ ->
                    if (!consumed) {
                        consumed = true
                        applyGen3SelectedPartyPpRecovery(file, opened, sourceUri, sourceLabel, slots)
                    }
                }.show()
        } catch (error: Exception) {
            showDialog("Party PP recovery stopped", error.message ?: "The party PP recovery could not be reviewed.")
        }
    }

    private fun applyGen3SelectedPartyPpRecovery(
        file: File, opened: ByteArray, sourceUri: Uri?, sourceLabel: String?, slots: List<Int>
    ) {
        var writeStarted = false
        try {
            val snapshot = gen3PartyMarkingSnapshot(file, opened, sourceUri, sourceLabel)
            require(slots.all { it in snapshot.members.indices && !snapshot.members[it].isEgg }) {
                "A selected party slot is no longer eligible for PP recovery."
            }
            val catalog = gen3PartyPpCatalog()
            val result = Gen3PartyPpRestoration.restore(snapshot.records, snapshot.count, slots, catalog)
            if (result.changedSlots.isEmpty()) return
            val sectionMap = gen3ActiveSectionMap(opened) ?: error("The active save sections could not be mapped.")
            val section1 = sectionMap[1]
            require(section1 >= 0 && snapshot.offset >= section1 &&
                snapshot.offset + 600 <= section1 + gen3SectionLengths[1]) {
                "The party is outside its validated save section."
            }
            val work = opened.copyOf()
            result.partyRecords.copyInto(work, snapshot.offset)
            updateGen3SectionChecksumAt(work, section1, 1)
            val allowed = result.changedSlots.flatMap { slot ->
                (0 until 80).map { snapshot.offset + slot * 100 + it }
            }.toSet() + setOf(section1 + 0xFF6, section1 + 0xFF7)
            require(gen3SaveValid(work) && work.indices.all { it in allowed || work[it] == opened[it] }) {
                "The staged party PP recovery failed checksum or unrelated-byte verification."
            }
            val backup = File.createTempFile(backupGameName(file) + "_PreGen3PartyPp_", ".backup", backupsDir())
            backup.writeBytes(opened)
            require(backup.readBytes().contentEquals(opened)) { "The recovery backup did not verify." }
            retainGen2ToGen3SafetyBackup(backup, opened)
            gen3PartyMarkingSnapshot(file, opened, sourceUri, sourceLabel)
            writeStarted = true
            file.writeBytes(work)
            val persisted = file.readBytes()
            require(persisted.contentEquals(work) && gen3SaveValid(persisted)) {
                "The persisted party PP recovery failed byte or checksum verification."
            }
            val reopened = gen3PartyMarkingSnapshot(file, persisted, sourceUri, sourceLabel)
            require(reopened.offset == snapshot.offset && reopened.count == snapshot.count &&
                reopened.records.contentEquals(result.partyRecords)) { "The recovered party did not reopen exactly." }
            slots.forEach { slot ->
                val raw = reopened.records.copyOfRange(slot * 100, (slot + 1) * 100)
                require(Gen3PpRestoration.restore(raw, catalog).contentEquals(raw)) {
                    "Party slot ${slot + 1} did not reopen with full PP."
                }
            }
            Toast.makeText(this, "${result.changedSlots.size} party Pokémon's PP restored and verified; backup retained",
                Toast.LENGTH_LONG).show()
            showGen3PokemonViewer("party")
        } catch (error: Exception) {
            val restored = if (writeStarted) runCatching {
                file.writeBytes(opened)
                val restoredBytes = file.readBytes()
                restoredBytes.contentEquals(opened) && gen3SaveValid(restoredBytes)
            }.getOrDefault(false) else false
            val recovery = when {
                !writeStarted -> "Nothing was written."
                restored -> "The original save was restored and verified."
                else -> "Automatic restore could not be verified. Restore the retained backup before editing again."
            }
            showDialog("Gen 3 party PP recovery failed", (error.message ?: "Unknown error") + "\n\n" + recovery)
        }
    }

    private fun showGen3SelectedBoxPpRecovery(
        file: File, opened: ByteArray, sourceUri: Uri?, sourceLabel: String?,
        boxIndex: Int, boxName: String, selectedSlots: List<Int>
    ) {
        try {
            val pc = requireGen3MarkingPcSnapshot(file, opened, sourceUri, sourceLabel, boxIndex, boxName)
            val snapshot = Gen3BoxEditing.snapshotSelectedBoxRecords(pc, boxIndex, selectedSlots)
            val members = snapshot.records.mapIndexed { index, raw ->
                val member = parsePk3(raw, 0, false)
                require(member != null && member.checksumValid) {
                    "Selected slot ${snapshot.slots[index] + 1} failed PK3 validation."
                }
                require(!member.isEgg) { "Deselect Eggs before restoring PP. No Pokémon in this batch was changed." }
                member
            }
            val catalog = gen3PartyPpCatalog()
            val result = Gen3BoxPpRestoration.restore(pc, boxIndex, snapshot.slots, catalog)
            if (result.changedSlots.isEmpty()) {
                showDialog("PP already full", "The selected PC Pokémon already have full PP. Nothing was written.")
                return
            }
            val start = Gen3BoxEditing.boxStorageRange(boxIndex).first
            val changes = result.changedSlots.joinToString("\n\n") { slot ->
                val index = snapshot.slots.indexOf(slot)
                val member = members[index]
                val before = Gen3MoveOrderEditing.read(snapshot.records[index], catalog)
                val after = Gen3MoveOrderEditing.read(result.pc.copyOfRange(start + slot * 80, start + (slot + 1) * 80), catalog)
                val moves = before.indices.filter { before[it].moveId != 0 && before[it].pp != after[it].pp }
                    .joinToString("\n") { move ->
                        val name = canonicalGen3MoveName(before[move].moveId) ?: error("Unknown Gen 3 move.")
                        "$name: ${before[move].pp} → ${after[move].pp} PP"
                    }
                "Slot ${slot + 1} • ${member.nickname.ifBlank { "Species #${member.species}" }}\n$moves"
            }
            var consumed = false
            AlertDialog.Builder(this)
                .setTitle("Restore PP for ${result.changedSlots.size} PC Pokémon?")
                .setMessage("Box ${boxIndex + 1} • $boxName\n\n" + changes +
                    "\n\nRestore move PP to the maximum with the existing PP Ups. Moves, PP Ups and other Pokémon data stay unchanged. " +
                    "Unselected slots, other boxes, box names and wallpapers stay unchanged. " +
                    "PSE will retain one verified recovery backup, save the complete batch and reopen it for verification.")
                .setNegativeButton("Cancel") { _, _ -> consumed = true }
                .setOnCancelListener { consumed = true }
                .setPositiveButton("Restore selected PP") { _, _ ->
                    if (!consumed) {
                        consumed = true
                        applyGen3SelectedBoxPpRecovery(file, opened, sourceUri, sourceLabel,
                            boxIndex, boxName, snapshot.slots)
                    }
                }.show()
        } catch (error: Exception) {
            showDialog("PC PP recovery stopped", error.message ?: "The selected PC Pokémon could not be reviewed.")
        }
    }

    private fun applyGen3SelectedBoxPpRecovery(
        file: File, opened: ByteArray, sourceUri: Uri?, sourceLabel: String?,
        boxIndex: Int, boxName: String, selectedSlots: List<Int>
    ) {
        var writeStarted = false
        try {
            val pc = requireGen3MarkingPcSnapshot(file, opened, sourceUri, sourceLabel, boxIndex, boxName)
            val snapshot = Gen3BoxEditing.snapshotSelectedBoxRecords(pc, boxIndex, selectedSlots)
            snapshot.records.forEachIndexed { index, raw ->
                val member = parsePk3(raw, 0, false)
                require(member != null && member.checksumValid && !member.isEgg) {
                    "Selected slot ${snapshot.slots[index] + 1} is no longer eligible for PP recovery."
                }
            }
            val catalog = gen3PartyPpCatalog()
            val result = Gen3BoxPpRestoration.restore(pc, boxIndex, snapshot.slots, catalog)
            if (result.changedSlots.isEmpty()) return
            val start = Gen3BoxEditing.boxStorageRange(boxIndex).first
            val pcOffsets = result.changedSlots.flatMap { slot -> (0 until 80).map { start + slot * 80 + it } }.toSet()
            require(result.pc.indices.all { it in pcOffsets || result.pc[it] == pc[it] }) {
                "The staged PP recovery changed unrelated PC bytes."
            }
            val sectionMap = gen3ActiveSectionMap(opened) ?: error("The active PC sections could not be mapped.")
            val work = opened.copyOf()
            writeGen3PcBuffer(work, result.pc)
            require(gen3SaveValid(work) && gen3PcBuffer(work)?.contentEquals(result.pc) == true) {
                "The staged PP recovery failed save checksum or PC verification."
            }
            val allowed = HashSet<Int>()
            var pcBase = 0
            for (sectionId in 5..13) {
                val sectionBase = sectionMap[sectionId]
                require(sectionBase >= 0) { "Missing Gen 3 PC section $sectionId." }
                val length = gen3SectionLengths[sectionId]
                for (local in 0 until length) {
                    if (pcBase + local in pcOffsets) allowed.add(sectionBase + local)
                }
                allowed.add(sectionBase + 0xFF6)
                allowed.add(sectionBase + 0xFF7)
                pcBase += length
            }
            require(work.indices.all { it in allowed || work[it] == opened[it] }) {
                "The PP recovery changed unrelated save data."
            }
            val backup = File.createTempFile(backupGameName(file) + "_PreGen3BoxPp_", ".backup", backupsDir())
            backup.writeBytes(opened)
            require(backup.readBytes().contentEquals(opened)) { "The recovery backup did not verify." }
            retainGen2ToGen3SafetyBackup(backup, opened)
            requireGen3MarkingPcSnapshot(file, opened, sourceUri, sourceLabel, boxIndex, boxName)
            writeStarted = true
            file.writeBytes(work)
            val persisted = file.readBytes()
            val reopenedPc = requireGen3MarkingPcSnapshot(file, persisted, sourceUri, sourceLabel, boxIndex, boxName)
            require(persisted.contentEquals(work) && gen3SaveValid(persisted) && reopenedPc.contentEquals(result.pc)) {
                "The persisted PP recovery failed byte, checksum or PC reopen verification."
            }
            snapshot.slots.forEach { slot ->
                val raw = reopenedPc.copyOfRange(start + slot * 80, start + (slot + 1) * 80)
                require(Gen3PpRestoration.restore(raw, catalog).contentEquals(raw)) {
                    "PC slot ${slot + 1} did not reopen with full PP."
                }
            }
            resetGen3BoxSelection()
            Toast.makeText(this, "${result.changedSlots.size} PC Pokémon's PP restored and verified; backup retained",
                Toast.LENGTH_LONG).show()
            showGen3PokemonViewer("boxes", boxIndex)
        } catch (error: Exception) {
            val restored = if (writeStarted) runCatching {
                file.writeBytes(opened)
                val restoredBytes = file.readBytes()
                restoredBytes.contentEquals(opened) && gen3SaveValid(restoredBytes)
            }.getOrDefault(false) else false
            val recovery = when {
                !writeStarted -> "Nothing was written."
                restored -> "The original save was restored and verified."
                else -> "Automatic restore could not be verified. Restore the retained backup before editing again."
            }
            showDialog("Gen 3 PC PP recovery failed", (error.message ?: "Unknown error") + "\n\n" + recovery)
        }
    }

    private fun showGen3PartyHpEditor(
        file: File, opened: ByteArray, sourceUri: Uri?, sourceLabel: String?,
        location: String, expected: PokemonEntry
    ) {
        try {
            val selected = gen3ContestSnapshot(file, opened, sourceUri, sourceLabel, location, expected)
            require(selected.pc == null) { "Current HP is stored only on party Pokémon." }
            val slot = partyLocationToSlot(location) ?: error("The selected party slot is invalid.")
            val snapshot = gen3PartyMarkingSnapshot(file, opened, sourceUri, sourceLabel)
            require(slot in 0 until snapshot.count && selected.offset == snapshot.offset + slot * 100) {
                "The selected party location changed."
            }
            val before = Gen3PartyHpEditing.read(selected.raw)
            val form = LinearLayout(this).apply {
                orientation = LinearLayout.VERTICAL
                setPadding(dp(20), dp(8), dp(20), dp(8))
            }
            addMutedLine(form, "$location • Current HP: ${before.current}/${before.maximum}. " +
                "Change current HP without changing maximum HP, stats, status or PP. " +
                "At least one usable non-Egg party Pokémon must keep HP remaining.")
            val field = inputField("Current HP (0–${before.maximum})", before.current.toString(), true)
                .also { form.addView(it.first) }.second
            var consumed = false
            AlertDialog.Builder(this)
                .setTitle("Current party HP")
                .setView(ScrollView(this).apply { addView(form) })
                .setNegativeButton("Cancel") { _, _ -> consumed = true }
                .setOnCancelListener { consumed = true }
                .setPositiveButton("Review") { _, _ ->
                    if (!consumed) {
                        consumed = true
                        try {
                            gen3ContestSnapshot(file, opened, sourceUri, sourceLabel, location, expected)
                            val fresh = gen3PartyMarkingSnapshot(file, opened, sourceUri, sourceLabel)
                            val hp = field.text.toString().toIntOrNull() ?: error("Enter a whole number for current HP.")
                            val edited = Gen3PartyHpEditing.replace(fresh.records, fresh.count, slot, hp)
                            if (edited.contentEquals(fresh.records)) {
                                showDialog("HP unchanged", "Current HP was not changed. Nothing was written.")
                            } else {
                                var applied = false
                                AlertDialog.Builder(this)
                                    .setTitle("Save current HP?")
                                    .setMessage("$location\n\nHP: ${before.current} → $hp / ${before.maximum}\n\n" +
                                        "PSE will retain a verified recovery backup, update the save checksum and reopen the saved party. " +
                                        "Maximum HP, stats, status, PP, Pokémon data and other party slots stay unchanged.")
                                    .setNegativeButton("Cancel") { _, _ -> applied = true }
                                    .setOnCancelListener { applied = true }
                                    .setPositiveButton("Save current HP") { _, _ ->
                                        if (!applied) {
                                            applied = true
                                            applyGen3PartyHpEdit(file, opened, sourceUri, sourceLabel,
                                                location, expected, hp)
                                        }
                                    }.show()
                            }
                        } catch (error: Exception) {
                            showDialog("Current HP edit stopped", error.message ?: "The HP change could not be reviewed.")
                        }
                    }
                }.show()
        } catch (error: Exception) {
            showDialog("Current HP unavailable", error.message ?: "This Pokémon's party HP could not be opened.")
        }
    }

    private fun applyGen3PartyHpEdit(
        file: File, opened: ByteArray, sourceUri: Uri?, sourceLabel: String?,
        location: String, expected: PokemonEntry, hp: Int
    ) {
        var writeStarted = false
        try {
            val selected = gen3ContestSnapshot(file, opened, sourceUri, sourceLabel, location, expected)
            require(selected.pc == null) { "Current HP is stored only on party Pokémon." }
            val slot = partyLocationToSlot(location) ?: error("The selected party slot is invalid.")
            val snapshot = gen3PartyMarkingSnapshot(file, opened, sourceUri, sourceLabel)
            require(slot in 0 until snapshot.count && selected.offset == snapshot.offset + slot * 100) {
                "The selected party location changed."
            }
            val edited = Gen3PartyHpEditing.replace(snapshot.records, snapshot.count, slot, hp)
            if (edited.contentEquals(snapshot.records)) return
            val sectionMap = gen3ActiveSectionMap(opened) ?: error("The active save sections could not be mapped.")
            val section1 = sectionMap[1]
            require(section1 >= 0 && snapshot.offset >= section1 &&
                snapshot.offset + 600 <= section1 + gen3SectionLengths[1]) {
                "The party is outside its validated save section."
            }
            val work = opened.copyOf()
            edited.copyInto(work, snapshot.offset)
            updateGen3SectionChecksumAt(work, section1, 1)
            val hpOffset = snapshot.offset + slot * 100 + 0x56
            val allowed = setOf(hpOffset, hpOffset + 1, section1 + 0xFF6, section1 + 0xFF7)
            require(gen3SaveValid(work) && work.indices.all { it in allowed || work[it] == opened[it] }) {
                "The staged current HP edit failed checksum or unrelated-byte verification."
            }
            val backup = File.createTempFile(backupGameName(file) + "_PreGen3PartyHp_", ".backup", backupsDir())
            backup.writeBytes(opened)
            require(backup.readBytes().contentEquals(opened)) { "The recovery backup did not verify." }
            retainGen2ToGen3SafetyBackup(backup, opened)
            gen3ContestSnapshot(file, opened, sourceUri, sourceLabel, location, expected)
            writeStarted = true
            file.writeBytes(work)
            val persisted = file.readBytes()
            require(persisted.contentEquals(work) && gen3SaveValid(persisted)) {
                "The persisted current HP edit failed byte or checksum verification."
            }
            val party = gen3PartyMarkingSnapshot(file, persisted, sourceUri, sourceLabel)
            require(party.offset == snapshot.offset && party.count == snapshot.count && party.records.contentEquals(edited)) {
                "The edited party did not reopen exactly."
            }
            val reopened = gen3ContestSnapshot(file, persisted, sourceUri, sourceLabel, location, expected)
            val expectedRaw = edited.copyOfRange(slot * 100, (slot + 1) * 100)
            require(reopened.raw.contentEquals(expectedRaw) && Gen3PartyHpEditing.read(reopened.raw).current == hp) {
                "The selected Pokémon did not reopen with the requested HP."
            }
            Toast.makeText(this, "Current HP saved and verified; recovery backup retained", Toast.LENGTH_LONG).show()
            showPokemonDetails(location, reopened.member)
        } catch (error: Exception) {
            val restored = if (writeStarted) runCatching {
                file.writeBytes(opened)
                val restoredBytes = file.readBytes()
                restoredBytes.contentEquals(opened) && gen3SaveValid(restoredBytes)
            }.getOrDefault(false) else false
            val recovery = when {
                !writeStarted -> "Nothing was written."
                restored -> "The original save was restored and verified."
                else -> "Automatic restore could not be verified. Restore the retained backup before editing again."
            }
            showDialog("Gen 3 current HP edit failed", (error.message ?: "Unknown error") + "\n\n" + recovery)
        }
    }

    private fun showGen3GameDetailsMenu() {
        val file = importedFile ?: return
        val sourceUri = currentSourceUri
        val sourceLabel = currentSourceLabel
        try {
            val opened = file.readBytes()
            fun requireSameSource() {
                require(importedFile?.absolutePath == file.absolutePath && currentSourceUri == sourceUri &&
                    currentSourceLabel == sourceLabel && file.readBytes().contentEquals(opened) && gen3SaveValid(opened)) {
                    "The save or its identity changed. Reopen Game Details."
                }
            }
            requireSameSource()
            val game = detectGen3GameFromPath(sourceLabel ?: file.name)
            val actions = Gen3GameDetailsCatalog.actionsForTitle(game)
            require(actions.isNotEmpty()) {
                "The source name must identify Ruby, Sapphire, Emerald, FireRed or LeafGreen before opening Game Details."
            }
            phoneBackAction = { showHome() }
            val root = LinearLayout(this).apply {
                orientation = LinearLayout.VERTICAL
                setPadding(dp(18), dp(52), dp(18), dp(28))
                setBackgroundColor(BG)
            }
            addSectionTitle(root, "GAME DETAILS")
            addMutedLine(root, game)
            addButton(root, "←  Home") { showHome() }
            addMutedLine(root, "Choose a title-specific tool. Each editor keeps its own review, backup and save-verification steps.")
            for (action in actions) {
                addButton(root, action.label) {
                    try {
                        requireSameSource()
                        require(action in Gen3GameDetailsCatalog.actionsForTitle(game)) { "This tool is unavailable for the loaded title." }
                        when (action) {
                            Gen3GameDetailsAction.POKEBLOCKS -> showGen3PokeblockCase()
                            Gen3GameDetailsAction.COINS -> showGen3CoinEditor()
                            Gen3GameDetailsAction.BATTLE_POINTS -> showGen3BattlePointEditor()
                            Gen3GameDetailsAction.BERRY_POWDER -> showGen3BerryPowderEditor()
                            Gen3GameDetailsAction.SOOT_ASH -> showGen3SootAshEditor()
                            Gen3GameDetailsAction.OPTIONS -> showGen3GameOptionsEditor()
                            Gen3GameDetailsAction.SELECT_SHORTCUT -> showGen3RegisteredItemEditor()
                            Gen3GameDetailsAction.SAVED_LOCATION -> showGen3SavedLocation()
                            Gen3GameDetailsAction.RECORDED_ACTIVITY -> showGen3RecordedActivity()
                            Gen3GameDetailsAction.HALL_OF_FAME -> showGen3HallOfFame()
                        }
                    } catch (error: Exception) {
                        showDialog("Game Details stopped", error.message ?: "Reopen the loaded save.")
                    }
                }
            }
            setContentView(ScrollView(this).apply { setBackgroundColor(BG); addView(root) })
        } catch (error: Exception) {
            showDialog("Game Details unavailable", error.message ?: "The tools could not be opened safely.")
        }
    }

    private data class Gen3ActivitySnapshot(
        val game: String, val profile: Gen3ActivityProfile, val trainer: ByteArray, val stats: ByteArray
    )

    private fun gen3ActivitySnapshot(action: Gen3GameDetailsAction): Gen3ActivitySnapshot {
        require(action == Gen3GameDetailsAction.RECORDED_ACTIVITY || action == Gen3GameDetailsAction.HALL_OF_FAME)
        val file = importedFile ?: error("Reopen a supported Gen 3 save.")
        val sourceUri = currentSourceUri
        val sourceLabel = currentSourceLabel
        val opened = file.readBytes()
        require(importedFile?.absolutePath == file.absolutePath && currentSourceUri == sourceUri &&
            currentSourceLabel == sourceLabel && file.readBytes().contentEquals(opened) && gen3SaveValid(opened)) {
            "The save or its identity changed. Reopen Game Details."
        }
        val game = detectGen3GameFromPath(sourceLabel ?: file.name)
        require(action in Gen3GameDetailsCatalog.actionsForTitle(game)) {
            "This view requires an identified supported Gen 3 title."
        }
        val profile = when (game) {
            "Pokémon Ruby", "Pokémon Sapphire" -> Gen3ActivityProfile.RUBY_SAPPHIRE
            "Pokémon Emerald" -> Gen3ActivityProfile.EMERALD
            "Pokémon FireRed", "Pokémon LeafGreen" -> Gen3ActivityProfile.FIRERED_LEAFGREEN
            else -> error("The game-stat format could not be identified.")
        }
        val sections = gen3ActiveSectionMap(opened) ?: error("The active save sections could not be mapped.")
        val trainerBase = sections[0]
        val statsBase = sections[Gen3RecordedActivityReadOnly.SECTION_ID]
        require(trainerBase >= 0 && trainerBase + gen3SectionLengths[0] <= opened.size &&
            statsBase >= 0 && statsBase + gen3SectionLengths[2] <= opened.size) {
            "The trainer or game-stat section is incomplete."
        }
        return Gen3ActivitySnapshot(game, profile,
            opened.copyOfRange(trainerBase, trainerBase + gen3SectionLengths[0]),
            opened.copyOfRange(statsBase, statsBase + gen3SectionLengths[2]))
    }

