    private fun showGen3SavedLocation() {
        val file = importedFile ?: return
        val sourceUri = currentSourceUri
        val sourceLabel = currentSourceLabel
        try {
            val opened = file.readBytes()
            require(importedFile?.absolutePath == file.absolutePath && currentSourceUri == sourceUri &&
                currentSourceLabel == sourceLabel && file.readBytes().contentEquals(opened) && gen3SaveValid(opened)) {
                "The save or its identity changed. Reopen Saved Location."
            }
            val game = detectGen3GameFromPath(sourceLabel ?: file.name)
            require(Gen3GameDetailsAction.SAVED_LOCATION in Gen3GameDetailsCatalog.actionsForTitle(game)) {
                "Saved Location requires an identified supported Gen 3 title."
            }
            val sections = gen3ActiveSectionMap(opened) ?: error("The active save sections could not be mapped.")
            val id = Gen3SavedLocationReadOnly.SECTION_ID
            val base = sections[id]
            require(base >= 0 && base + gen3SectionLengths[id] <= opened.size) { "The saved-location section is incomplete." }
            val location = Gen3SavedLocationReadOnly.read(opened.copyOfRange(base, base + gen3SectionLengths[id]))
            val rubySapphire = game == "Pokémon Ruby" || game == "Pokémon Sapphire"
            val warp0CLabel = if (rubySapphire) "Saved warp 1 record" else "Continue-game warp record"
            val warp24Label = if (rubySapphire) "Saved warp 4 record" else "Escape warp record"
            fun describe(warp: Gen3SavedWarp): String =
                "Map: " + (Gen3SavedMapNames.displayNameForTitle(game, warp.mapGroup, warp.mapNumber) ?: "Unknown / unmapped") +
                "\nMap group: " + warp.mapGroup + "\nMap number: " + warp.mapNumber +
                "\nWarp ID: " + warp.warpId + "\nWarp X/Y: " + warp.x + " / " + warp.y
            phoneBackAction = { showGen3GameDetailsMenu() }
            val root = LinearLayout(this).apply {
                orientation = LinearLayout.VERTICAL
                setPadding(dp(18), dp(52), dp(18), dp(28))
                setBackgroundColor(BG)
            }
            addSectionTitle(root, "Saved Location • Read-only")
            addMutedLine(root, game)
            addButton(root, "←  Game Details") { showGen3GameDetailsMenu() }
            addMutedLine(root, "Saved snapshot. Scroll to inspect each record. Reopen this view to refresh from the working copy.")
            addSectionTitle(root, "Saved player position")
            addMutedLine(root, "Saved player X/Y: " + location.playerX + " / " + location.playerY +
                "\nMap layout ID: " + location.mapLayoutId)
            addSectionTitle(root, "Saved location record:")
            addMutedLine(root, describe(location.location))
            addSectionTitle(root, "Last-heal record:")
            addMutedLine(root, describe(location.lastHeal))
            addSectionTitle(root, "Saved dynamic warp record:")
            addMutedLine(root, describe(location.dynamicWarp))
            addSectionTitle(root, warp0CLabel + ":")
            addMutedLine(root, describe(location.warpAt0C))
            addSectionTitle(root, warp24Label + ":")
            addMutedLine(root, describe(location.warpAt24))
            addSectionTitle(root, "Saved field settings (raw)")
            addMutedLine(root, "Music ID: " + location.fieldState.musicId +
                "\nWeather ID: " + location.fieldState.weather +
                "\nWeather-cycle stage: " + location.fieldState.weatherCycleStage +
                "\nFlash level: " + location.fieldState.flashLevel)
            addMutedLine(root, "Names identify the saved map records for this title; they do not prove a valid destination or current position. Raw values, including signed sentinels, are preserved. This view does not move the player or change the save.")
            addButton(root, "←  Game Details") { showGen3GameDetailsMenu() }
            setContentView(ScrollView(this).apply { setBackgroundColor(BG); addView(root) })
        } catch (error: Exception) {
            showDialog("Saved Location unavailable", error.message ?: "The saved location could not be read safely.")
        }
    }

    private data class Gen3RegisteredItemSnapshot(
        val game: String, val profile: Gen3RegisteredItemProfile, val sectionBase: Int,
        val section: ByteArray, val itemId: Int
    )

    private fun gen3RegisteredItemSnapshot(
        file: File, opened: ByteArray, sourceUri: Uri?, sourceLabel: String?
    ): Gen3RegisteredItemSnapshot {
        require(importedFile?.absolutePath == file.absolutePath && currentSourceUri == sourceUri &&
            currentSourceLabel == sourceLabel && file.readBytes().contentEquals(opened) && gen3SaveValid(opened)) {
            "The save or its identity changed. Reopen Registered SELECT Shortcut."
        }
        val game = detectGen3GameFromPath(sourceLabel ?: file.name)
        val profile = when (game) {
            "Pokémon Ruby", "Pokémon Sapphire", "Pokémon Emerald" -> Gen3RegisteredItemProfile.HOENN
            "Pokémon FireRed", "Pokémon LeafGreen" -> Gen3RegisteredItemProfile.FIRERED_LEAFGREEN
            else -> error("The source name must identify Ruby, Sapphire, Emerald, FireRed or LeafGreen before managing its shortcut.")
        }
        val sections = gen3ActiveSectionMap(opened) ?: error("The active save sections could not be mapped.")
        val id = Gen3RegisteredItemEditing.SECTION_ID
        val base = sections[id]
        require(base >= 0 && base + gen3SectionLengths[id] <= opened.size) { "The registered-item section is incomplete." }
        val section = opened.copyOfRange(base, base + gen3SectionLengths[id])
        return Gen3RegisteredItemSnapshot(game, profile, base, section, Gen3RegisteredItemEditing.read(section, profile))
    }

    private fun showGen3RegisteredItemEditor() {
        val file = importedFile ?: return
        val sourceUri = currentSourceUri
        val sourceLabel = currentSourceLabel
        try {
            val opened = file.readBytes()
            val snapshot = gen3RegisteredItemSnapshot(file, opened, sourceUri, sourceLabel)
            phoneBackAction = { showHome() }
            val root = LinearLayout(this).apply {
                orientation = LinearLayout.VERTICAL
                setPadding(dp(18), dp(52), dp(18), dp(28))
                setBackgroundColor(BG)
            }
            addSectionTitle(root, "REGISTERED SELECT SHORTCUT")
            addMutedLine(root, snapshot.game)
            addButton(root, "←  Home") { showHome() }
            if (snapshot.itemId == 0) {
                addMutedLine(root, "No item is registered to SELECT.")
            } else {
                addMutedLine(root, Gen3RegisteredItemEditing.itemLabel(snapshot.itemId, snapshot.profile))
                addMutedLine(root, "Saved native item ID: #" + snapshot.itemId + " (0x" +
                    snapshot.itemId.toString(16).uppercase(Locale.US).padStart(4, '0') + ")")
                addMutedLine(root, "Clear the SELECT shortcut without removing any items from your Bag or PC. Register a different item through the game's Bag.")
                var consumed = false
                var reviewOpen = false
                addButton(root, "Review Clear Shortcut") {
                    if (!consumed && !reviewOpen) {
                        try {
                            gen3RegisteredItemSnapshot(file, opened, sourceUri, sourceLabel)
                            reviewOpen = true
                            var applied = false
                            AlertDialog.Builder(this)
                                .setTitle("Clear registered SELECT shortcut?")
                                .setMessage(snapshot.game + "\n\n" +
                                    Gen3RegisteredItemEditing.itemLabel(snapshot.itemId, snapshot.profile) +
                                    " → No registered item\n\nBag and PC items remain unchanged. PSE will retain a verified recovery backup and reopen the working copy to verify the cleared shortcut.")
                                .setNegativeButton("Cancel") { _, _ -> applied = true }
                                .setOnCancelListener { applied = true }
                                .setOnDismissListener { reviewOpen = false }
                                .setPositiveButton("Clear Shortcut") { _, _ ->
                                    if (!applied && !consumed) {
                                        applied = true
                                        consumed = true
                                        applyGen3RegisteredItemClear(file, opened, sourceUri, sourceLabel)
                                    }
                                }.show()
                        } catch (error: Exception) {
                            showDialog("Shortcut clear stopped", error.message ?: "Reopen Registered SELECT Shortcut.")
                        }
                    }
                }
            }
            addMutedLine(root, "Changes affect PSE's working copy. Use Save & Replace to update the original save.")
            setContentView(ScrollView(this).apply { setBackgroundColor(BG); addView(root) })
        } catch (error: Exception) {
            showDialog("Registered SELECT Shortcut unavailable", error.message ?: "The shortcut could not be opened safely.")
        }
    }

    private fun applyGen3RegisteredItemClear(
        file: File, opened: ByteArray, sourceUri: Uri?, sourceLabel: String?
    ) {
        var writeStarted = false
        try {
            val snapshot = gen3RegisteredItemSnapshot(file, opened, sourceUri, sourceLabel)
            val edited = Gen3RegisteredItemEditing.clear(snapshot.section, snapshot.profile)
            if (edited.contentEquals(snapshot.section)) return
            val work = opened.copyOf()
            edited.copyInto(work, snapshot.sectionBase)
            updateGen3SectionChecksumAt(work, snapshot.sectionBase, Gen3RegisteredItemEditing.SECTION_ID)
            val offset = snapshot.sectionBase + snapshot.profile.sectionOffset
            val allowed = setOf(offset, offset + 1, snapshot.sectionBase + 0xFF6, snapshot.sectionBase + 0xFF7)
            require(gen3SaveValid(work) && work.indices.all { it in allowed || work[it] == opened[it] }) {
                "The staged shortcut clear failed checksum or unrelated-byte verification."
            }
            val backup = File.createTempFile(backupGameName(file) + "_PreGen3RegisteredItem_", ".backup", backupsDir())
            backup.writeBytes(opened)
            require(backup.readBytes().contentEquals(opened)) { "The recovery backup did not verify." }
            retainGen2ToGen3SafetyBackup(backup, opened)
            gen3RegisteredItemSnapshot(file, opened, sourceUri, sourceLabel)
            writeStarted = true
            file.writeBytes(work)
            val persisted = file.readBytes()
            require(persisted.contentEquals(work) && gen3SaveValid(persisted)) { "The persisted shortcut did not verify." }
            val reopened = gen3RegisteredItemSnapshot(file, persisted, sourceUri, sourceLabel)
            require(reopened.profile == snapshot.profile && reopened.sectionBase == snapshot.sectionBase &&
                reopened.section.contentEquals(edited) && reopened.itemId == 0) {
                "The cleared shortcut did not reopen exactly."
            }
            Toast.makeText(this, "Shortcut cleared and verified; recovery backup retained", Toast.LENGTH_LONG).show()
            showGen3RegisteredItemEditor()
        } catch (error: Exception) {
            val restored = if (writeStarted) runCatching {
                file.writeBytes(opened)
                val bytes = file.readBytes()
                bytes.contentEquals(opened) && gen3SaveValid(bytes)
            }.getOrDefault(false) else false
            val recovery = when {
                !writeStarted -> "Nothing was written."
                restored -> "The original save was restored and verified."
                else -> "Automatic restore could not be verified. Restore the retained backup before editing again."
            }
            showDialog("Shortcut clear failed", (error.message ?: "Unknown error") + "\n\n" + recovery)
        }
    }

