    private fun gen3GameOptionsSummary(options: Gen3GameOptions, profile: Gen3GameOptionsProfile): String =
        "Text speed: " + listOf("Slow", "Mid", "Fast")[options.textSpeed] +
        "\nBattle scene: " + listOf("On", "Off")[options.battleSceneOff] +
        "\nBattle style: " + listOf("Shift", "Set")[options.battleStyle] +
        "\nSound: " + listOf("Mono", "Stereo")[options.sound] +
        "\nButton mode: " + listOf(profile.firstButtonLabel, "L/R", "L = A")[options.buttonMode] +
        "\nFrame: " + (options.frame + 1)

    private fun showGen3GameOptionsEditor() {
        val file = importedFile ?: return
        val sourceUri = currentSourceUri
        val sourceLabel = currentSourceLabel
        try {
            val opened = file.readBytes()
            val snapshot = gen3GameOptionsSnapshot(file, opened, sourceUri, sourceLabel)
            phoneBackAction = { showHome() }
            val root = LinearLayout(this).apply {
                orientation = LinearLayout.VERTICAL
                setPadding(dp(18), dp(52), dp(18), dp(28))
                setBackgroundColor(BG)
            }
            addSectionTitle(root, "GAME OPTIONS")
            addMutedLine(root, snapshot.game)
            addButton(root, "←  Home") { showHome() }
            fun choice(label: String, labels: List<String>, selected: Int): Spinner {
                addMutedLine(root, label)
                val spinner = Spinner(this)
                spinner.adapter = ArrayAdapter<String>(this, android.R.layout.simple_spinner_item, labels).apply {
                    setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item)
                }
                spinner.setSelection(selected)
                root.addView(spinner)
                return spinner
            }
            val options = snapshot.options
            val textSpeed = choice("Text speed", listOf("Slow", "Mid", "Fast"), options.textSpeed)
            val scene = choice("Battle scene", listOf("On", "Off"), options.battleSceneOff)
            val style = choice("Battle style", listOf("Shift", "Set"), options.battleStyle)
            val sound = choice("Sound", listOf("Mono", "Stereo"), options.sound)
            val buttons = choice("Button mode", listOf(snapshot.profile.firstButtonLabel, "L/R", "L = A"), options.buttonMode)
            val frame = choice("Text frame", (1..snapshot.profile.frameCount).map { "Frame " + it }, options.frame)
            addMutedLine(root, "Only these six saved options change. Map zoom, reserved bits and other save data are preserved.")
            addMutedLine(root, "Changes affect PSE's working copy. Use Save & Replace to update the original save.")
            var consumed = false
            var reviewOpen = false
            fun currentSelections(): Gen3GameOptions =
                Gen3GameOptions(buttons.selectedItemPosition, textSpeed.selectedItemPosition,
                    frame.selectedItemPosition, sound.selectedItemPosition, style.selectedItemPosition,
                    scene.selectedItemPosition)
            fun selectOptions(target: Gen3GameOptions) {
                buttons.setSelection(target.buttonMode)
                textSpeed.setSelection(target.textSpeed)
                frame.setSelection(target.frame)
                sound.setSelection(target.sound)
                style.setSelection(target.battleStyle)
                scene.setSelection(target.battleSceneOff)
            }
            addMutedLine(root, "Defaults affect the displayed settings only. Hoenn keeps the selected button mode; FireRed/LeafGreen use Help. Map zoom stays unchanged. Review and Save Options are still required.")
            addButton(root, "Use option defaults") {
                if (!consumed && !reviewOpen) {
                    try {
                        gen3GameOptionsSnapshot(file, opened, sourceUri, sourceLabel)
                        selectOptions(Gen3GameOptionsEditing.defaultSelections(currentSelections(), snapshot.profile))
                    } catch (error: Exception) {
                        showDialog("Options selection stopped", error.message ?: "Reopen Game Options.")
                    }
                }
            }
            addButton(root, "Restore loaded selections") {
                if (!consumed && !reviewOpen) {
                    try {
                        gen3GameOptionsSnapshot(file, opened, sourceUri, sourceLabel)
                        selectOptions(snapshot.options)
                    } catch (error: Exception) {
                        showDialog("Options selection stopped", error.message ?: "Reopen Game Options.")
                    }
                }
            }
            addButton(root, "Review Options") {
                if (!consumed && !reviewOpen) {
                    try {
                        val target = currentSelections()
                        val fresh = gen3GameOptionsSnapshot(file, opened, sourceUri, sourceLabel)
                        val edited = Gen3GameOptionsEditing.replace(fresh.section, fresh.profile, target)
                        if (edited.contentEquals(fresh.section)) {
                            showDialog("Options unchanged", "The selected options are already saved. Nothing was written.")
                        } else {
                            reviewOpen = true
                            var applied = false
                            AlertDialog.Builder(this)
                                .setTitle("Save Game Options?")
                                .setMessage(snapshot.game + "\n\nCurrent:\n" +
                                    gen3GameOptionsSummary(snapshot.options, snapshot.profile) +
                                    "\n\nSelected:\n" + gen3GameOptionsSummary(target, snapshot.profile) +
                                    "\n\nPSE will retain a verified recovery backup, save the options and reopen them for verification.")
                                .setNegativeButton("Cancel") { _, _ -> applied = true }
                                .setOnCancelListener { applied = true }
                                .setOnDismissListener { reviewOpen = false }
                                .setPositiveButton("Save Options") { _, _ ->
                                    if (!applied && !consumed) {
                                        applied = true
                                        consumed = true
                                        applyGen3GameOptionsEdit(file, opened, sourceUri, sourceLabel, target)
                                    }
                                }.show()
                        }
                    } catch (error: Exception) {
                        showDialog("Options edit stopped", error.message ?: "The options could not be reviewed.")
                    }
                }
            }
            setContentView(ScrollView(this).apply { setBackgroundColor(BG); addView(root) })
        } catch (error: Exception) {
            showDialog("Game Options unavailable", error.message ?: "The options could not be opened safely.")
        }
    }

    private fun applyGen3GameOptionsEdit(
        file: File, opened: ByteArray, sourceUri: Uri?, sourceLabel: String?, target: Gen3GameOptions
    ) {
        var writeStarted = false
        try {
            val snapshot = gen3GameOptionsSnapshot(file, opened, sourceUri, sourceLabel)
            val edited = Gen3GameOptionsEditing.replace(snapshot.section, snapshot.profile, target)
            if (edited.contentEquals(snapshot.section)) return
            val work = opened.copyOf()
            edited.copyInto(work, snapshot.sectionBase)
            updateGen3SectionChecksumAt(work, snapshot.sectionBase, Gen3GameOptionsEditing.SECTION_ID)
            val allowed = setOf(snapshot.sectionBase + 0x13, snapshot.sectionBase + 0x14,
                snapshot.sectionBase + 0x15, snapshot.sectionBase + 0xFF6, snapshot.sectionBase + 0xFF7)
            require(gen3SaveValid(work) && work.indices.all { it in allowed || work[it] == opened[it] }) {
                "The staged options edit failed checksum or unrelated-byte verification."
            }
            val backup = File.createTempFile(backupGameName(file) + "_PreGen3GameOptions_", ".backup", backupsDir())
            backup.writeBytes(opened)
            require(backup.readBytes().contentEquals(opened)) { "The recovery backup did not verify." }
            retainGen2ToGen3SafetyBackup(backup, opened)
            gen3GameOptionsSnapshot(file, opened, sourceUri, sourceLabel)
            writeStarted = true
            file.writeBytes(work)
            val persisted = file.readBytes()
            require(persisted.contentEquals(work) && gen3SaveValid(persisted)) { "The persisted options did not verify." }
            val reopened = gen3GameOptionsSnapshot(file, persisted, sourceUri, sourceLabel)
            require(reopened.profile == snapshot.profile && reopened.sectionBase == snapshot.sectionBase &&
                reopened.section.contentEquals(edited) && reopened.options == target) {
                "The edited options did not reopen exactly."
            }
            Toast.makeText(this, "Options saved and verified; recovery backup retained", Toast.LENGTH_LONG).show()
            showGen3GameOptionsEditor()
        } catch (error: Exception) {
            val restored = if (writeStarted) runCatching {
                file.writeBytes(opened)
                val bytes = file.readBytes()
                bytes.contentEquals(opened) && gen3SaveValid(bytes)
            }.getOrDefault(false) else false
            val recovery = when {
                !writeStarted -> "Nothing was written."
                restored -> "The original save was restored and verified."
                else -> "Automatic restore could not be verified. Restore the retained backup before editing again."
            }
            showDialog("Game Options edit failed", (error.message ?: "Unknown error") + "\n\n" + recovery)
        }
    }

