    private fun applyGen3SootAshEdit(
        file: File, opened: ByteArray, sourceUri: Uri?, sourceLabel: String?, ash: Int
    ) {
        var writeStarted = false
        try {
            val snapshot = gen3SootAshSnapshot(file, opened, sourceUri, sourceLabel)
            val edited = Gen3SootAshEditing.replace(snapshot.section, snapshot.profile, ash)
            if (edited.contentEquals(snapshot.section)) return
            val work = opened.copyOf()
            edited.copyInto(work, snapshot.sectionBase)
            updateGen3SectionChecksumAt(work, snapshot.sectionBase, Gen3SootAshEditing.SECTION_ID)
            val start = snapshot.sectionBase + snapshot.profile.sectionOffset
            val allowed = setOf(start, start + 1, snapshot.sectionBase + 0xFF6, snapshot.sectionBase + 0xFF7)
            require(gen3SaveValid(work) && work.indices.all { it in allowed || work[it] == opened[it] }) {
                "The staged ash edit failed checksum or unrelated-byte verification."
            }
            val backup = File.createTempFile(backupGameName(file) + "_PreGen3SootAsh_", ".backup", backupsDir())
            backup.writeBytes(opened)
            require(backup.readBytes().contentEquals(opened)) { "The recovery backup did not verify." }
            retainGen2ToGen3SafetyBackup(backup, opened)
            gen3SootAshSnapshot(file, opened, sourceUri, sourceLabel)
            writeStarted = true
            file.writeBytes(work)
            val persisted = file.readBytes()
            require(persisted.contentEquals(work) && gen3SaveValid(persisted)) { "The persisted ash count did not verify." }
            val reopened = gen3SootAshSnapshot(file, persisted, sourceUri, sourceLabel)
            require(reopened.profile == snapshot.profile && reopened.sectionBase == snapshot.sectionBase &&
                reopened.section.contentEquals(edited) && reopened.ash == ash) {
                "The edited ash count did not reopen exactly."
            }
            Toast.makeText(this, "Ash saved and verified; recovery backup retained", Toast.LENGTH_LONG).show()
            showGen3SootAshEditor()
        } catch (error: Exception) {
            val restored = if (writeStarted) runCatching {
                file.writeBytes(opened)
                val bytes = file.readBytes()
                bytes.contentEquals(opened) && gen3SaveValid(bytes)
            }.getOrDefault(false) else false
            val recovery = when {
                !writeStarted -> "Nothing was written."
                restored -> "The original save was restored and verified."
                else -> "Automatic restore could not be verified. Restore the retained backup before editing again."
            }
            showDialog("Ash edit failed", (error.message ?: "Unknown error") + "\n\n" + recovery)
        }
    }

