            setContentView(ScrollView(this).apply { setBackgroundColor(BG); addView(root) })
        } catch (error: Exception) {
            showDialog("Pokéblock case unavailable", error.message ?: "The case could not be opened safely.")
        }
    }

    private fun showGen3PokeblockOrganisation(
        file: File, opened: ByteArray, sourceUri: Uri?, sourceLabel: String?
    ) {
        try {
            gen3PokeblockSnapshot(file, opened, sourceUri, sourceLabel)
            val modes = Gen3PokeblockOrganisation.values()
            val labels = arrayOf("Close empty gaps (keep block order)", "Level: highest first", "Group by colour")
            var chosen = false
            AlertDialog.Builder(this)
                .setTitle("Organise Pokéblock case")
                .setNegativeButton("Cancel") { _, _ -> chosen = true }
                .setOnCancelListener { chosen = true }
                .setItems(labels) { _, which ->
                    if (!chosen) {
                        chosen = true
                        try {
                            val snapshot = gen3PokeblockSnapshot(file, opened, sourceUri, sourceLabel)
                            val mode = modes[which]
                            val order = Gen3PokeblockEditing.organisationOrder(snapshot.section, snapshot.layout, mode)
                            val edited = Gen3PokeblockEditing.reorder(snapshot.section, snapshot.layout, order)
                            if (edited.contentEquals(snapshot.section)) {
                                showDialog("Case already organised", "This order is already in place. Nothing was written.")
                            } else {
                                val entries = Gen3PokeblockEditing.read(edited, snapshot.layout)
                                val changed = entries.indices.filter { entries[it] != snapshot.entries[it] }
                                fun describe(entry: Gen3PokeblockEntry): String = if (entry.color == 0) "Empty" else
                                    "${Gen3PokeblockEditing.colorNames[entry.color]} • flavours ${entry.spicy}/${entry.dry}/${entry.sweet}/${entry.bitter}/${entry.sour} • feel ${entry.feel}"
                                val changes = changed.joinToString("\n\n") { slot ->
                                    "Slot ${slot + 1}\n${describe(snapshot.entries[slot])}\n→ ${describe(entries[slot])} (from slot ${order[slot] + 1})"
                                }
                                val review = TextView(this).apply {
                                    text = "${snapshot.game}\n${labels[which]}\n${changed.size} slots change; all ${entries.count { it.color != 0 }} blocks are retained.\n\n" +
                                        "Flavour order: spicy / dry / sweet / bitter / sour. Equal sort values keep their original order.\n\n$changes\n\n" +
                                        "PSE will retain a verified recovery backup and reopen the case after saving."
                                    setPadding(dp(20), dp(8), dp(20), dp(8))
                                }
                                var applied = false
                                AlertDialog.Builder(this)
                                    .setTitle("Review case organisation")
                                    .setView(ScrollView(this).apply { addView(review) })
                                    .setNegativeButton("Cancel") { _, _ -> applied = true }
                                    .setOnCancelListener { applied = true }
                                    .setPositiveButton("Save order") { _, _ ->
                                        if (!applied) {
                                            applied = true
                                            applyGen3PokeblockOrganisation(file, opened, sourceUri, sourceLabel, mode, edited)
                                        }
                                    }.show()
                            }
                        } catch (error: Exception) {
                            showDialog("Case organisation stopped", error.message ?: "The order could not be reviewed.")
                        }
                    }
                }.show()
        } catch (error: Exception) {
            showDialog("Case organisation unavailable", error.message ?: "The case could not be opened safely.")
        }
    }

    private fun applyGen3PokeblockOrganisation(
        file: File, opened: ByteArray, sourceUri: Uri?, sourceLabel: String?,
        mode: Gen3PokeblockOrganisation, reviewed: ByteArray
    ) {
        var writeStarted = false
        try {
            val snapshot = gen3PokeblockSnapshot(file, opened, sourceUri, sourceLabel)
            val order = Gen3PokeblockEditing.organisationOrder(snapshot.section, snapshot.layout, mode)
            val edited = Gen3PokeblockEditing.reorder(snapshot.section, snapshot.layout, order)
            require(edited.contentEquals(reviewed)) { "The reviewed order changed. Reopen the case." }
            if (edited.contentEquals(snapshot.section)) return
            val entries = Gen3PokeblockEditing.read(edited, snapshot.layout)
            val changed = entries.indices.filter { entries[it] != snapshot.entries[it] }
            val allowed = mutableSetOf(snapshot.sectionBase + 0xFF6, snapshot.sectionBase + 0xFF7)
            changed.forEach { slot ->
                val start = snapshot.sectionBase + snapshot.layout.caseOffset + slot * 8
                allowed.addAll(start..start + 6)
            }
            val work = opened.copyOf()
            edited.copyInto(work, snapshot.sectionBase)
            updateGen3SectionChecksumAt(work, snapshot.sectionBase, 1)
            require(gen3SaveValid(work) && work.indices.all { it in allowed || work[it] == opened[it] }) {
                "The staged case failed checksum or unrelated-byte verification."
            }
            val backup = File.createTempFile(backupGameName(file) + "_PreGen3PokeblockOrder_", ".backup", backupsDir())
            backup.writeBytes(opened)
            require(backup.readBytes().contentEquals(opened)) { "The recovery backup did not verify." }
            retainGen2ToGen3SafetyBackup(backup, opened)
            gen3PokeblockSnapshot(file, opened, sourceUri, sourceLabel)
            writeStarted = true
            file.writeBytes(work)
            val persisted = file.readBytes()
            require(persisted.contentEquals(work) && gen3SaveValid(persisted)) { "The persisted case did not verify." }
            val reopened = gen3PokeblockSnapshot(file, persisted, sourceUri, sourceLabel)
            require(reopened.layout == snapshot.layout && reopened.sectionBase == snapshot.sectionBase &&
                reopened.section.contentEquals(edited) && reopened.entries == entries) {
                "The organised case did not reopen exactly."
            }
            Toast.makeText(this, "Case organised and verified; recovery backup retained", Toast.LENGTH_LONG).show()
            showGen3PokeblockCase()
        } catch (error: Exception) {
            val restored = if (writeStarted) runCatching {
                file.writeBytes(opened)
                val bytes = file.readBytes()
                bytes.contentEquals(opened) && gen3SaveValid(bytes)
            }.getOrDefault(false) else false
            val recovery = when {
                !writeStarted -> "Nothing was written."
                restored -> "The original save was restored and verified."
                else -> "Automatic restore could not be verified. Restore the retained backup before editing again."
            }
            showDialog("Case organisation failed", (error.message ?: "Unknown error") + "\n\n" + recovery)
        }
    }

    private fun showGen3PokeblockEditor(
        file: File, opened: ByteArray, sourceUri: Uri?, sourceLabel: String?, slot: Int
    ) {
        try {
            val snapshot = gen3PokeblockSnapshot(file, opened, sourceUri, sourceLabel)
            val before = snapshot.entries.getOrNull(slot) ?: error("The selected Pokéblock slot is invalid.")
            val form = LinearLayout(this).apply {
                orientation = LinearLayout.VERTICAL
                setPadding(dp(20), dp(8), dp(20), dp(8))
            }
            addMutedLine(form, "${snapshot.game} • Slot ${slot + 1}. Choose values from 0 to 255. " +
                "The game applies at most 99 feel when feeding. Choosing Empty clears all flavour and feel values.")
            val color = spinnerField("Colour", Gen3PokeblockEditing.colorNames, before.color)
                .also { form.addView(it.first) }.second
            val names = listOf("Spicy", "Dry", "Sweet", "Bitter", "Sour", "Feel / sheen")
            val fields = names.mapIndexed { index, name ->
                inputField("$name (0–255)", before.values()[index + 1].toString(), true)
                    .also { form.addView(it.first) }.second
            }
            var consumed = false
            AlertDialog.Builder(this)
                .setTitle("Pokéblock slot ${slot + 1}")
                .setView(ScrollView(this).apply { addView(form) })
                .setNegativeButton("Cancel") { _, _ -> consumed = true }
                .setOnCancelListener { consumed = true }
                .setPositiveButton("Review") { _, _ ->
                    if (!consumed) {
                        consumed = true
                        try {
                            val fresh = gen3PokeblockSnapshot(file, opened, sourceUri, sourceLabel)
                            val values = if (color.selectedItemPosition == 0) Gen3PokeblockEntry() else {
                                val numbers = fields.map { it.text.toString().toIntOrNull() ?: error("Enter whole numbers for flavours and feel.") }
                                Gen3PokeblockEntry(color.selectedItemPosition, numbers[0], numbers[1], numbers[2],
                                    numbers[3], numbers[4], numbers[5]).requireValid()
                            }
                            val edited = Gen3PokeblockEditing.replace(fresh.section, fresh.layout, slot, values)
                            if (edited.contentEquals(fresh.section)) {
                                showDialog("Pokéblock unchanged", "No values were changed. Nothing was written.")
                            } else {
                                val changes = "Colour: ${Gen3PokeblockEditing.colorNames[before.color]} → ${Gen3PokeblockEditing.colorNames[values.color]}\n" +
                                    names.indices.joinToString("\n") { "${names[it]}: ${before.values()[it + 1]} → ${values.values()[it + 1]}" }
                                var applied = false
                                AlertDialog.Builder(this)
                                    .setTitle("Save Pokéblock slot ${slot + 1}?")
                                    .setMessage("${snapshot.game}\n\n$changes\n\nPSE will retain a verified recovery backup, update the save checksum and reopen the case. Other slots and unrelated save data stay unchanged.")
                                    .setNegativeButton("Cancel") { _, _ -> applied = true }
                                    .setOnCancelListener { applied = true }
                                    .setPositiveButton("Save Pokéblock") { _, _ ->
                                        if (!applied) {
                                            applied = true
                                            applyGen3PokeblockEdit(file, opened, sourceUri, sourceLabel, slot, values)
                                        }
                                    }.show()
                            }
                        } catch (error: Exception) {
                            showDialog("Pokéblock edit stopped", error.message ?: "The edit could not be reviewed.")
                        }
                    }
                }.show()
        } catch (error: Exception) {
            showDialog("Pokéblock edit stopped", error.message ?: "The selected slot could not be opened.")
        }
    }

    private fun applyGen3PokeblockEdit(
        file: File, opened: ByteArray, sourceUri: Uri?, sourceLabel: String?, slot: Int, values: Gen3PokeblockEntry
    ) {
        var writeStarted = false
        try {
            val snapshot = gen3PokeblockSnapshot(file, opened, sourceUri, sourceLabel)
            val edited = Gen3PokeblockEditing.replace(snapshot.section, snapshot.layout, slot, values)
            if (edited.contentEquals(snapshot.section)) return
            val work = opened.copyOf()
            edited.copyInto(work, snapshot.sectionBase)
            updateGen3SectionChecksumAt(work, snapshot.sectionBase, 1)
            val start = snapshot.sectionBase + snapshot.layout.caseOffset + slot * 8
            val allowed = (start..start + 6).toSet() + setOf(snapshot.sectionBase + 0xFF6, snapshot.sectionBase + 0xFF7)
            require(gen3SaveValid(work) && work.indices.all { it in allowed || work[it] == opened[it] }) {
                "The staged Pokéblock edit failed checksum or unrelated-byte verification."
            }
            val backup = File.createTempFile(backupGameName(file) + "_PreGen3Pokeblock_", ".backup", backupsDir())
            backup.writeBytes(opened)
            require(backup.readBytes().contentEquals(opened)) { "The recovery backup did not verify." }
            retainGen2ToGen3SafetyBackup(backup, opened)
            gen3PokeblockSnapshot(file, opened, sourceUri, sourceLabel)
            writeStarted = true
            file.writeBytes(work)
            val persisted = file.readBytes()
            require(persisted.contentEquals(work) && gen3SaveValid(persisted)) { "The persisted save did not verify." }
            val reopened = gen3PokeblockSnapshot(file, persisted, sourceUri, sourceLabel)
            require(reopened.layout == snapshot.layout && reopened.sectionBase == snapshot.sectionBase &&
                reopened.section.contentEquals(edited) && reopened.entries[slot] == values) {
                "The edited Pokéblock case did not reopen exactly."
            }
            Toast.makeText(this, "Pokéblock saved and verified; recovery backup retained", Toast.LENGTH_LONG).show()
            showGen3PokeblockCase()
        } catch (error: Exception) {
            val restored = if (writeStarted) runCatching {
                file.writeBytes(opened)
                val bytes = file.readBytes()
                bytes.contentEquals(opened) && gen3SaveValid(bytes)
            }.getOrDefault(false) else false
            val recovery = when {
                !writeStarted -> "Nothing was written."
                restored -> "The original save was restored and verified."
                else -> "Automatic restore could not be verified. Restore the retained backup before editing again."
            }
            showDialog("Pokéblock edit failed", (error.message ?: "Unknown error") + "\n\n" + recovery)
        }
    }

