            if(moveIds[i]!=0){val oldMove=moveIds[i];resolvePokeApiNameAsync("move",oldMove){n->if(n!=null&&moveIds[i]==oldMove)selector.text="$n (#$oldMove)"}}
            val pp=inputField("Move ${i+1} PP (0–63)",p.movePP[i].toString(),true).also{root.addView(it.first)}.second;ppF.add(pp)
            selector.setOnClickListener{
                openCatalogPicker("move","Choose Gen 3 Move ${i+1}",false){chosen->
