        addSectionTitle(root,"EVs");val evF=ArrayList<EditText>();for(i in 0..5)evF.add(inputField("${labels[i]} EV (0–255)",p.evs[i].toString(),true).also{root.addView(it.first)}.second)
        if(isParty)addMutedLine(root,"Party stat rebuild: EXP determines Level automatically. Nature, IV and EV edits recalculate Max HP, Attack, Defense, Speed, Sp. Atk and Sp. Def. PSE verifies the current cached stats first and rolls back if any rebuilt value fails verification.")
        addButton(root,"💾  Save Changes") save@{
            val v=try{Gen3EditValues(nick.text.toString().trim(),ot.text.toString().trim(),tid.text.toString().toInt(),sid.text.toString().toInt(),exp.text.toString().toLong(),heldItemId,friendship.text.toString().toInt(),nature.selectedItemPosition,shiny.isChecked,moveIds.copyOf(),IntArray(4){ppF[it].text.toString().toInt()},IntArray(6){ivF[it].text.toString().toInt()},IntArray(6){evF[it].text.toString().toInt()},abilitySlotValues[abilitySlot.selectedItemPosition])}catch(_:Exception){showDialog("Invalid values","One or more fields are not valid numbers.");return@save}
            val err=when{v.nickname.length>10->"Nickname must be 10 characters or fewer.";v.ot.length>7->"OT name must be 7 characters or fewer.";v.tid !in 0..65535||v.sid !in 0..65535->"TID/SID must be 0–65535.";v.exp !in 0..0xFFFFFF->"Gen 3 EXP must fit in 24 bits.";v.held !in 0..65535->"Held item ID is invalid.";v.friendship !in 0..255->"Friendship must be 0–255.";v.moves.any{it !in 0..354}->"Gen 3 move IDs must be 0–354.";v.pp.any{it !in 0..63}->"PP must be 0–63.";v.ivs.any{it !in 0..31}->"IVs must be 0–31.";v.evs.any{it !in 0..255}->"EVs must be 0–255.";else->null}
            if(err!=null){showDialog("Invalid values",err);return@save}
            val needsPartyRebuild=isParty && (v.exp!=p.experience||v.nature!=p.nature||!v.ivs.contentEquals(p.ivs)||!v.evs.contentEquals(p.evs))
            if(needsPartyRebuild) prepareGen3PartyEdit(location,p,v)
            else AlertDialog.Builder(this).setTitle("Save Gen 3 Pokémon changes?").setMessage("PSE will rebuild the encrypted PK3 record and all affected Gen 3 section checksums, re-read the Pokémon and roll back automatically if verification fails.").setNegativeButton("Cancel",null).setPositiveButton("Save"){_,_->applyGen3PokemonEdit(location,p,v,null)}.show()
        }
        addMutedLine(root,"Changes affect only PSE's working copy until Save & Replace. PSE verifies the PK3 checksum and the Gen 3 save-section checksums before keeping an edit.")
        setContentView(scroll)
    }

    private fun applyGen3PokemonEdit(location:String,old:PokemonEntry,v:Gen3EditValues,partyRebuild:Gen3PartyRebuild?=null){
        val file=importedFile?:return;val original=try{file.readBytes()}catch(e:Exception){showDialog("Edit failed",e.message?:"Could not read save");return};val save=original.copyOf();val game=detectGen3GameFromData(save,currentSourceLabel?:file.name)
        try{
            val partySlot=partyLocationToSlot(location);val global=boxedLocationToGlobalIndex(location)
            var newP:PokemonEntry?=null
            var partyExpectedStats:IntArray?=null
            if(global!=null){
                val pc=gen3PcBuffer(save)?:throw IllegalStateException("Could not reconstruct PC storage");val off=4+global*80;val cur=parsePk3(pc,off,false)?:throw IllegalStateException("Pokémon is no longer in that box slot");if(cur.pid!=old.pid||cur.species!=old.species)throw IllegalStateException("The box slot changed since the editor was opened");val raw=pc.copyOfRange(off,off+80);mutatePk3(raw,false,v).copyInto(pc,off);writeGen3PcBuffer(save,pc);newP=parsePk3(pc,off,false)
            }else if(partySlot!=null){
                val sectionMap=gen3ActiveSectionMap(save)?:throw IllegalStateException("Could not map active Gen 3 save sections");val section1=sectionMap[1];if(section1<0)throw IllegalStateException("Missing Gen 3 party section");val po=section1+if(game.contains("FireRed")||game.contains("LeafGreen"))0x38 else 0x238;val off=po+partySlot*100;val cur=parsePk3(save,off,true)?:throw IllegalStateException("Party slot changed");if(cur.pid!=old.pid||cur.species!=old.species)throw IllegalStateException("The party slot changed since the editor was opened");val raw=save.copyOfRange(off,off+100)
                if(partyRebuild!=null){
                    if(cur.level==null)throw IllegalStateException("Current Party level could not be read")
                    val before=gen3PartyStatsFromRaw(raw)?:throw IllegalStateException("Current Party battle stats could not be read")
                    val expectedBefore=calculateGen3BattleStats(partyRebuild.baseStats,cur.ivs,cur.evs,cur.nature,cur.level)
                    if(before[0]!=cur.level || before[2]!=expectedBefore[0] || before[3]!=expectedBefore[1] || before[4]!=expectedBefore[2] || before[5]!=expectedBefore[3] || before[6]!=expectedBefore[4] || before[7]!=expectedBefore[5] || before[1]>before[2])throw IllegalStateException("Current cached Party stats do not match the verified Gen 3 calculation; edit refused")
                    partyExpectedStats=calculateGen3BattleStats(partyRebuild.baseStats,v.ivs,v.evs,v.nature,partyRebuild.level)
                }
                val rebuilt=mutatePk3(raw,true,v,partyRebuild);rebuilt.copyInto(save,off);updateGen3SectionChecksumAt(save,section1,1);newP=parsePk3(save,off,true)
                if(partyRebuild!=null){
                    if(newP?.level!=partyRebuild.level)throw IllegalStateException("Rebuilt Party level did not verify")
                    val after=gen3PartyStatsFromRaw(rebuilt)?:throw IllegalStateException("Rebuilt Party battle stats could not be read")
                    val expected=requireNotNull(partyExpectedStats)
                    if(after[0]!=partyRebuild.level || after[2]!=expected[0] || after[3]!=expected[1] || after[4]!=expected[2] || after[5]!=expected[3] || after[6]!=expected[4] || after[7]!=expected[5] || after[1]>after[2])throw IllegalStateException("Rebuilt Party battle stats failed verification")
                }
            }else throw IllegalStateException("Unknown Pokémon location")
            if(newP==null||!newP!!.checksumValid||newP!!.species!=old.species||newP!!.nickname!=v.nickname||newP!!.tid!=v.tid||newP!!.sid!=v.sid||newP!!.experience!=v.exp||newP!!.heldItem!=v.held||newP!!.friendship!=v.friendship||newP!!.nature!=v.nature||newP!!.shiny!=v.shiny||!newP!!.moves.contentEquals(v.moves)||!newP!!.movePP.contentEquals(v.pp)||!newP!!.ivs.contentEquals(v.ivs)||!newP!!.evs.contentEquals(v.evs))throw IllegalStateException("Edited PK3 did not verify")
            if(!gen3SaveValid(save))throw IllegalStateException("Gen 3 section checksum verification failed")
            file.writeBytes(save);val verify=file.readBytes();if(!gen3SaveValid(verify))throw IllegalStateException("Written save failed verification")
            val verifiedP=if(global!=null){val pc=gen3PcBuffer(verify)?:throw IllegalStateException("Could not re-read PC storage");parsePk3(pc,4+global*80,false)}else{val map=gen3ActiveSectionMap(verify)?:throw IllegalStateException("Could not re-map Gen 3 sections");val section1=map[1];val po=section1+if(game.contains("FireRed")||game.contains("LeafGreen"))0x38 else 0x238;val off=po+requireNotNull(partySlot)*100;val q=parsePk3(verify,off,true);if(partyRebuild!=null){val stats=gen3PartyStatsFromRaw(verify.copyOfRange(off,off+100))?:throw IllegalStateException("Written Party stats could not be re-read");val expected=requireNotNull(partyExpectedStats);if(stats[0]!=partyRebuild.level||stats[2]!=expected[0]||stats[3]!=expected[1]||stats[4]!=expected[2]||stats[5]!=expected[3]||stats[6]!=expected[4]||stats[7]!=expected[5]||stats[1]>stats[2])throw IllegalStateException("Written Party battle stats failed verification")};q}
            if(verifiedP==null||!verifiedP.checksumValid||verifiedP.species!=old.species||verifiedP.experience!=v.exp||verifiedP.nature!=v.nature||!verifiedP.ivs.contentEquals(v.ivs)||!verifiedP.evs.contentEquals(v.evs))throw IllegalStateException("Written PK3 failed final verification")
            Toast.makeText(this,"Gen 3 Pokémon updated and verified",Toast.LENGTH_LONG).show();showPokemonDetails(location,verifiedP)
        }catch(e:Exception){runCatching{file.writeBytes(original)};showDialog("Edit failed","${e.message?:"Unknown error"}. The original working copy was restored.")}
    }







    private fun gen3PartyBatchMoveMembers(
        data: ByteArray,
        offset: Int,
        count: Int
    ): List<PokemonEntry> {
        require(count in 1..6 && offset >= 4 && offset <= data.size - 600) {
            "The Gen 3 party count or storage is invalid."
        }
        return (0 until count).map { slot ->
            val pokemon = parsePk3(data, offset + slot * 100, true)
                ?: error("Party slot ${slot + 1} could not be read.")
            require(pokemon.checksumValid) {
                "Party slot ${slot + 1} failed its PK3 checksum."
            }
            pokemon
        }
    }

    private fun showGen3PartyBatchMoveSelection(
        file: File,
        opened: ByteArray,
        sourceUri: Uri?,
        sourceLabel: String?,
        copyOnly: Boolean = false
    ) {
        try {
            require(importedFile?.absolutePath == file.absolutePath &&
                currentSourceUri == sourceUri && currentSourceLabel == sourceLabel &&
                file.readBytes().contentEquals(opened) && gen3SaveValid(opened)) {
                "The save or its identity changed. Reopen the party before selecting."
            }
            val game = detectGen3GameFromData(opened, sourceLabel ?: file.name)
            val offset = gen3PartyOffset(opened, game)
                ?: error("The Gen 3 party block could not be located.")
            val count = readU32LE(opened, offset - 4).toInt()
            val members = gen3PartyBatchMoveMembers(opened, offset, count)
            require(copyOnly || count >= 2) {
                "At least two party Pokémon are needed to move one into PC storage."
            }
            val action = if (copyOnly) "Duplicate" else "Move"
            val selected = linkedSetOf<Int>()
            AlertDialog.Builder(this)
                .setTitle("${action} selected party Pokémon")
                .setMultiChoiceItems(
                    members.mapIndexed { slot, pokemon ->
                        val name = pokemon.nickname.ifBlank {
                            canonicalGen3SpeciesName(pokemon.species) ?: "Species #${pokemon.species}"
                        }
                        "Slot ${slot + 1} • ${name}" + if (pokemon.isEgg) " • Egg" else ""
                    }.toTypedArray(),
                    BooleanArray(count)
                ) { _, slot, checked ->
                    if (checked) selected.add(slot) else selected.remove(slot)
                }
                .setNegativeButton("Cancel", null)
                .setPositiveButton("Choose box") { _, _ ->
                    chooseGen3PartyBatchMoveBox(
                        file, opened, sourceUri, sourceLabel, selected.toList().sorted(), copyOnly
                    )
                }
                .show()
        } catch (error: Exception) {
            showDialog("Party move stopped", error.message ?: "The party could not be selected.")
        }
    }

    private fun chooseGen3PartyBatchMoveBox(
        file: File,
        opened: ByteArray,
        sourceUri: Uri?,
        sourceLabel: String?,
        slots: List<Int>,
        copyOnly: Boolean = false
    ) {
        try {
            require(importedFile?.absolutePath == file.absolutePath &&
                currentSourceUri == sourceUri && currentSourceLabel == sourceLabel &&
                file.readBytes().contentEquals(opened) && gen3SaveValid(opened)) {
                "The save or its identity changed while selecting. Reopen the party."
            }
            val game = detectGen3GameFromData(opened, sourceLabel ?: file.name)
            val offset = gen3PartyOffset(opened, game)
                ?: error("The Gen 3 party block could not be located.")
            val count = readU32LE(opened, offset - 4).toInt()
            val members = gen3PartyBatchMoveMembers(opened, offset, count)
            require(slots.isNotEmpty() && slots.size == slots.toSet().size &&
                (copyOnly || slots.size < count) && slots.all { it in 0 until count }) {
                "Select unique active party Pokémon. A move must leave one party Pokémon."
            }
            require(copyOnly || (0 until count).any { it !in slots && !members[it].isEgg }) {
                "Keep at least one non-Egg Pokémon in the party."
            }
            val pc = gen3PcBuffer(opened) ?: error("The Gen 3 PC storage could not be opened.")
            val names = gen3PcBoxNames(pc)
            val boxes = (0 until Gen3SaveState.BOX_COUNT).filter {
                Gen3BoxEditing.emptyBoxSlots(pc, it).size >= slots.size
            }
            require(boxes.isNotEmpty()) {
                "No Gen 3 PC box has room for all ${slots.size} selected Pokémon."
            }
            val action = if (copyOnly) "Duplicate" else "Move"
            AlertDialog.Builder(this)
                .setTitle("${action} ${slots.size} Pokémon to which box?")
                .setItems(boxes.map { box ->
                    "${names[box]} • Box ${box + 1} • " +
                        "${Gen3BoxEditing.emptyBoxSlots(pc, box).size} empty"
                }.toTypedArray()) { _, which ->
                    reviewGen3PartyBatchMove(
                        file, opened, sourceUri, sourceLabel, slots, boxes[which], copyOnly
                    )
                }
                .setNegativeButton("Cancel", null)
                .show()
        } catch (error: Exception) {
            showDialog("Party move stopped", error.message ?: "No destination could be selected.")
        }
    }

    private fun reviewGen3PartyBatchMove(
        file: File,
        opened: ByteArray,
        sourceUri: Uri?,
        sourceLabel: String?,
        slots: List<Int>,
        targetBox: Int,
        copyOnly: Boolean = false
    ) {
        try {
            require(importedFile?.absolutePath == file.absolutePath &&
                currentSourceUri == sourceUri && currentSourceLabel == sourceLabel &&
                file.readBytes().contentEquals(opened) && gen3SaveValid(opened)) {
                "The save or its identity changed before review. Reopen the party."
            }
            val game = detectGen3GameFromData(opened, sourceLabel ?: file.name)
            val offset = gen3PartyOffset(opened, game)
                ?: error("The Gen 3 party block could not be located.")
            val count = readU32LE(opened, offset - 4).toInt()
            val members = gen3PartyBatchMoveMembers(opened, offset, count)
            val pc = gen3PcBuffer(opened) ?: error("The Gen 3 PC storage could not be opened.")
            val party = opened.copyOfRange(offset, offset + 600)
            val result = if (copyOnly) {
                Gen3PartyEditing.duplicatePartyPokemonBatchToPc(party, count, slots, pc, targetBox)
            } else {
                Gen3PartyEditing.movePartyPokemonBatchToPc(party, count, slots, pc, targetBox)
            }
            require(copyOnly || (0 until count).any { it !in result.sourceSlots && !members[it].isEgg }) {
                "Keep at least one non-Egg Pokémon in the party."
            }
            val boxName = gen3PcBoxNames(pc)[targetBox]
            val lines = result.sourceSlots.mapIndexed { index, slot ->
                val pokemon = members[slot]
                val name = pokemon.nickname.ifBlank {
                    canonicalGen3SpeciesName(pokemon.species) ?: "Species #${pokemon.species}"
                }
                "Party ${slot + 1} • ${name} → Box ${targetBox + 1} Slot ${result.targetSlots[index] + 1}"
            }.joinToString("\n")
            val action = if (copyOnly) "Duplicate" else "Move"
            val sourceBehavior = if (copyOnly) {
                "All ${count} party Pokémon and their full records will stay unchanged. "
            } else {
                "${result.partyCount} Pokémon will remain, with their full records compacted in order. "
            }
            AlertDialog.Builder(this)
                .setTitle("${action} ${slots.size} Pokémon to ${boxName}?")
                .setMessage(
                    lines + "\n\n" + sourceBehavior +
                        "PSE will preserve each exact PK3, create a verified backup, rebuild " +
                        "checksums, and reopen both party and PC. The whole batch rolls " +
                        "back on any mismatch."
                )
                .setNegativeButton("Cancel", null)
                .setPositiveButton("${action} batch") { _, _ ->
                    moveGen3PartyBatchToPc(
                        file, opened, sourceUri, sourceLabel, slots, targetBox,
                        result.targetSlots, copyOnly
                    )
                }
                .show()
        } catch (error: Exception) {
            showDialog("Party move stopped", error.message ?: "The batch could not be reviewed.")
        }
    }

    private fun moveGen3PartyBatchToPc(
        file: File,
        reviewed: ByteArray,
        sourceUri: Uri?,
        sourceLabel: String?,
        slots: List<Int>,
        targetBox: Int,
        reviewedTargets: List<Int>,
        copyOnly: Boolean = false
    ) {
        var writeStarted = false
        try {
            require(importedFile?.absolutePath == file.absolutePath &&
                currentSourceUri == sourceUri && currentSourceLabel == sourceLabel) {
                "The loaded save identity changed after review."
            }
            val fresh = file.readBytes()
            require(fresh.contentEquals(reviewed) && gen3SaveValid(fresh)) {
                "The save changed or failed validation after review."
            }
            val game = detectGen3GameFromData(fresh, sourceLabel ?: file.name)
            val offset = gen3PartyOffset(fresh, game)
                ?: error("The Gen 3 party block could not be located.")
            val count = readU32LE(fresh, offset - 4).toInt()
            val members = gen3PartyBatchMoveMembers(fresh, offset, count)
            val party = fresh.copyOfRange(offset, offset + 600)
            val pc = gen3PcBuffer(fresh) ?: error("The Gen 3 PC storage could not be opened.")
            val result = if (copyOnly) {
                Gen3PartyEditing.duplicatePartyPokemonBatchToPc(party, count, slots, pc, targetBox)
            } else {
                Gen3PartyEditing.movePartyPokemonBatchToPc(party, count, slots, pc, targetBox)
            }
            val expectedCount = if (copyOnly) count else count - slots.size
            require(result.targetSlots == reviewedTargets && result.partyCount == expectedCount &&
                (!copyOnly || result.partyRecords.contentEquals(party))) {
                "The destination or party count changed after review."
            }
            val remaining = (0 until count).filter { copyOnly || it !in result.sourceSlots }
            require(copyOnly || remaining.any { !members[it].isEgg }) {
                "Keep at least one non-Egg Pokémon in the party."
            }
            remaining.forEachIndexed { target, source ->
                require(result.partyRecords.copyOfRange(target * 100, (target + 1) * 100)
                    .contentEquals(party.copyOfRange(source * 100, (source + 1) * 100))) {
                    "The staged move changed a remaining party record."
                }
            }
            require(result.partyRecords.copyOfRange(result.partyCount * 100, count * 100)
                .all { it == 0.toByte() } &&
                result.partyRecords.copyOfRange(count * 100, 600)
                    .contentEquals(party.copyOfRange(count * 100, 600))) {
                "The staged move did not preserve inactive party storage or clear vacated records."
            }
            val range = Gen3BoxEditing.boxStorageRange(targetBox)
            val targetRanges = result.targetSlots.map { slot ->
                range.first + slot * 80 until range.first + (slot + 1) * 80
            }
            result.sourceSlots.forEachIndexed { index, source ->
                val targetOffset = targetRanges[index].first
                val raw = party.copyOfRange(source * 100, source * 100 + 80)
                val copied = result.pc.copyOfRange(targetOffset, targetOffset + 80)
                val pokemon = parsePk3(copied, 0, false)
                require(copied.contentEquals(raw) && pokemon != null &&
                    pokemon.checksumValid && pokemon.pid == members[source].pid &&
                    pokemon.species == members[source].species &&
                    pokemon.isEgg == members[source].isEgg) {
                    "A staged PC destination did not preserve its exact PK3 or Egg state."
                }
            }
            require(pc.indices.all { index ->
                targetRanges.any { index in it } || result.pc[index] == pc[index]
            }) {
                "The staged move changed unrelated PC data."
            }

            val sectionMap = gen3ActiveSectionMap(fresh)
                ?: error("The active save sections could not be mapped.")
            val section1 = sectionMap[1]
            require(section1 >= 0) { "The active party section is missing." }
            val work = fresh.copyOf()
            if (!copyOnly) {
                result.partyRecords.copyInto(work, offset)
                writeU32LE(work, offset - 4, result.partyCount.toLong())
                updateGen3SectionChecksumAt(work, section1, 1)
            }
            writeGen3PcBuffer(work, result.pc)
            val allowed = HashSet<Int>()
            if (!copyOnly) {
                for (index in offset - 4 until offset + count * 100) allowed.add(index)
                allowed.add(section1 + 0xFF6)
                allowed.add(section1 + 0xFF7)
            }
            var pcBase = 0
            for (id in 5..13) {
                val base = sectionMap[id]
                require(base >= 0) { "Missing Gen 3 PC section ${id}." }
                val length = gen3SectionLengths[id]
                for (local in 0 until length) {
                    if (targetRanges.any { pcBase + local in it }) allowed.add(base + local)
                }
                allowed.add(base + 0xFF6)
                allowed.add(base + 0xFF7)
                pcBase += length
            }
            require(gen3SaveValid(work) &&
                gen3ActiveSectionMap(work)?.contentEquals(sectionMap) == true &&
                gen3PcBuffer(work)?.contentEquals(result.pc) == true &&
                work.indices.all { it in allowed || work[it] == fresh[it] }) {
                "The staged move failed checksum, active-section, or unrelated-byte verification."
            }
            val backupSuffix = if (copyOnly) "_PreGen3PartyBatchCopy_" else "_PreGen3PartyBatchToPc_"
            val backup = File.createTempFile(
                backupGameName(file) + backupSuffix, ".backup", backupsDir()
            )
            backup.writeBytes(fresh)
            require(backup.readBytes().contentEquals(fresh)) { "The recovery backup did not verify." }
            retainGen2ToGen3SafetyBackup(backup, fresh)
            require(importedFile?.absolutePath == file.absolutePath &&
                currentSourceUri == sourceUri && currentSourceLabel == sourceLabel &&
                file.readBytes().contentEquals(fresh)) {
                "The active save changed before writing. Nothing was changed."
            }

            writeStarted = true
            file.writeBytes(work)
            val persisted = file.readBytes()
            require(persisted.contentEquals(work) && gen3SaveValid(persisted)) {
                "The persisted move failed byte or checksum verification."
            }
            val reopenedOffset = gen3PartyOffset(persisted, game)
                ?: error("The moved party could not be reopened.")
            require(readU32LE(persisted, reopenedOffset - 4).toInt() == result.partyCount &&
                persisted.copyOfRange(reopenedOffset, reopenedOffset + 600)
                    .contentEquals(result.partyRecords)) {
                "The compacted party did not persist exactly."
            }
            for (slot in 0 until result.partyCount) {
                val pokemon = parsePk3(persisted, reopenedOffset + slot * 100, true)
                require(pokemon != null && pokemon.checksumValid) {
                    "A remaining party Pokémon failed validation after reopen."
                }
            }
            val persistedPc = gen3PcBuffer(persisted)
                ?: error("The moved PC storage could not be reopened.")
            require(persistedPc.contentEquals(result.pc)) {
                "The destination PC did not persist exactly."
            }
            result.sourceSlots.forEachIndexed { index, source ->
                val target = targetRanges[index].first
                val pokemon = parsePk3(persistedPc, target, false)
                require(persistedPc.copyOfRange(target, target + 80)
                    .contentEquals(party.copyOfRange(source * 100, source * 100 + 80)) &&
                    pokemon != null && pokemon.checksumValid &&
                    pokemon.pid == members[source].pid &&
                    pokemon.species == members[source].species &&
                    pokemon.isEgg == members[source].isEgg) {
                    "A moved PK3 failed final verification after reopen."
                }
            }
            resetGen3BoxSelection()
            val completedAction = if (copyOnly) "Duplicated" else "Moved"
            Toast.makeText(
                this, "${completedAction} ${slots.size} party Pokémon to PC and verified", Toast.LENGTH_LONG
            ).show()
            showGen3PokemonViewer("boxes", targetBox)
        } catch (error: Exception) {
            val restored = if (writeStarted) {
                runCatching {
                    file.writeBytes(reviewed)
                    file.readBytes().contentEquals(reviewed)
                }.getOrDefault(false)
            } else false
            val recovery = when {
                !writeStarted -> "Nothing was written."
                restored -> "The reviewed save was restored and verified."
                else -> "Automatic rollback could not be verified. Restore the retained recovery backup before editing again."
            }
            showDialog(
                if (copyOnly) "Gen 3 party batch duplication failed" else "Gen 3 party batch move failed",
                (error.message ?: "Unknown error") + "\n\n" + recovery
            )
        }
    }

    private fun gen3PartyRecoveryCandidates(
        data: ByteArray,
        partyOffset: Int,
        partyCount: Int
    ): List<Int> {
        require(partyCount in 1..6 && partyOffset >= 4 &&
            partyOffset <= data.size - 600) {
            "The Gen 3 party storage or count is invalid."
        }
        return (0 until partyCount).filter { slot ->
            val pokemon = parsePk3(data, partyOffset + slot * 100, true)
                ?: error("Party slot ${slot + 1} could not be read.")
            require(pokemon.checksumValid) {
                "Party slot ${slot + 1} failed PK3 checksum validation."
            }
            // Eggs retain their original party-only fields and encrypted record.
            !pokemon.isEgg
        }
    }

    private fun showGen3PartySortDialog(
        file: File, opened: ByteArray, sourceUri: Uri?, sourceLabel: String?
    ) {
        fun bound(): Boolean = importedFile?.absolutePath == file.absolutePath &&
            currentSourceUri == sourceUri && currentSourceLabel == sourceLabel
        try {
            require(bound() && file.readBytes().contentEquals(opened) && gen3SaveValid(opened)) {
                "The save or its identity changed. Reopen the party."
            }
            val game = detectGen3GameFromData(opened, sourceLabel ?: file.name)
            val offset = gen3PartyOffset(opened, game) ?: error("The party could not be located.")
            val count = readU32LE(opened, offset - 4).toInt()
            val members = gen3PartyBatchMoveMembers(opened, offset, count)
            require(count >= 2) { "At least two party Pokémon are needed to sort." }
            val entries = members.mapIndexed { slot, p ->
                val level = if (p.isEgg) 0 else requireNotNull(p.level) {
                    "Party slot ${slot + 1} has no readable level. Sorting was stopped."
                }
                Gen3PartySortEntry(slot, p.species, level, p.nickname.ifBlank {
                    canonicalGen3SpeciesName(p.species) ?: "Species #${p.species}"
                }, p.isEgg)
            }
            val options = listOf(
                Triple("National Dex: lowest first", Gen3PartySortField.SPECIES, false),
                Triple("National Dex: highest first", Gen3PartySortField.SPECIES, true),
                Triple("Level: lowest first", Gen3PartySortField.LEVEL, false),
                Triple("Level: highest first", Gen3PartySortField.LEVEL, true),
                Triple("Name: A → Z", Gen3PartySortField.NAME, false),
                Triple("Name: Z → A", Gen3PartySortField.NAME, true)
            )
            var chosen = false
            AlertDialog.Builder(this)
                .setTitle("Sort Gen 3 party")
                .setItems(options.map { it.first }.toTypedArray()) { _, index ->
                    if (chosen || index !in options.indices) return@setItems
                    chosen = true
                    try {
                        require(bound() && file.readBytes().contentEquals(opened)) {
                            "The save changed while choosing a sort. Reopen the party."
                        }
                        val option = options[index]
                        val order = Gen3PartyEditing.sortedPartySlots(entries, option.second, option.third)
                        val records = opened.copyOfRange(offset, offset + 600)
                        val reordered = Gen3PartyEditing.reorderPartyPokemon(records, count, order)
                        if (reordered.contentEquals(records)) {
                            showDialog("Party already sorted", "The party already matches this order.")
                        } else {
                            val preview = order.mapIndexed { target, source ->
                                val entry = entries[source]
                                "Slot ${target + 1}: ${entry.name} • " +
                                    if (entry.isEgg) "Egg" else "Lv ${entry.level} • #${entry.species}"
                            }.joinToString("\n")
                            var consumed = false
                            AlertDialog.Builder(this)
                                .setTitle("Apply party sort?")
                                .setMessage(option.first + "\n\n" + preview +
                                    "\n\nTies keep their original order. Eggs remain last in their original order. " +
                                    "Each full Pokémon record is preserved, including HP, status, moves and PP. " +
                                    "PSE will retain a recovery backup, save and verify the order, " +
                                    "and restore the working save if verification fails.")
                                .setNegativeButton("Cancel") { _, _ -> consumed = true }
                                .setOnCancelListener { consumed = true }
                                .setPositiveButton("Sort party") { _, _ ->
                                    if (!consumed) {
                                        consumed = true
                                        applyGen3PartyOrder(file, opened, sourceUri, sourceLabel, order)
                                    }
                                }.show()
                        }
                    } catch (error: Exception) {
                        showDialog("Party sorting stopped", error.message ?: "The sort could not be reviewed.")
                    }
                }
                .setNegativeButton("Cancel") { _, _ -> chosen = true }
                .setOnCancelListener { chosen = true }
                .show()
        } catch (error: Exception) {
            showDialog("Party sorting stopped", error.message ?: "The party could not be opened.")
        }
    }

    private fun showGen3PartyOrderDialog(
        file: File, opened: ByteArray, sourceUri: Uri?, sourceLabel: String?
    ) {
        fun bound(): Boolean = importedFile?.absolutePath == file.absolutePath &&
            currentSourceUri == sourceUri && currentSourceLabel == sourceLabel
        try {
            require(bound() && file.readBytes().contentEquals(opened) && gen3SaveValid(opened)) {
                "The save or its identity changed. Reopen the party."
            }
            val game = detectGen3GameFromData(opened, sourceLabel ?: file.name)
            val offset = gen3PartyOffset(opened, game) ?: error("The party could not be located.")
            val count = readU32LE(opened, offset - 4).toInt()
            val members = gen3PartyBatchMoveMembers(opened, offset, count)
            require(count >= 2) { "At least two party Pokémon are needed to change the order." }
            val order = ArrayList<Int>()
            fun label(slot: Int): String {
                val p = members[slot]
                val name = p.nickname.ifBlank {
                    canonicalGen3SpeciesName(p.species) ?: "Species #${p.species}"
                }
                return "${name} • original slot ${slot + 1}" + if (p.isEgg) " • Egg" else ""
            }
            fun chooseNext() {
                try {
                    require(bound() && file.readBytes().contentEquals(opened)) {
                        "The save changed during selection. Reopen the party."
                    }
                    val remaining = (0 until count).filter { it !in order }
                    if (remaining.size == 1) {
                        order.add(remaining.single())
                        chooseNext()
                        return
                    }
                    if (remaining.isEmpty()) {
                        val chosen = order.toList()
                        val records = opened.copyOfRange(offset, offset + 600)
                        val staged = Gen3PartyEditing.reorderPartyPokemon(records, count, chosen)
                        if (staged.contentEquals(records)) {
                            showDialog("Party order unchanged", "The chosen order matches the current party.")
                            return
                        }
                        val preview = chosen.mapIndexed { target, source ->
                            "Slot ${target + 1}: ${label(source)}"
                        }.joinToString("\n")
                        var consumed = false
                        AlertDialog.Builder(this)
                            .setTitle("Apply new party order?")
                            .setMessage(preview + "\n\nEach Pokémon keeps its HP, status, moves, PP and Egg data. " +
                                "PSE will retain a recovery backup, save and verify the new order, " +
                                "and restore the working save if verification fails.")
                            .setNegativeButton("Cancel") { _, _ -> consumed = true }
                            .setOnCancelListener { consumed = true }
                            .setPositiveButton("Apply order") { _, _ ->
                                if (!consumed) {
                                    consumed = true
                                    applyGen3PartyOrder(file, opened, sourceUri, sourceLabel, chosen)
                                }
                            }.show()
                        return
                    }
                    var consumed = false
                    AlertDialog.Builder(this)
                        .setTitle("Choose Pokémon for slot ${order.size + 1}")
                        .setItems(remaining.map { label(it) }.toTypedArray()) { _, index ->
                            if (!consumed && index in remaining.indices) {
                                consumed = true
                                order.add(remaining[index])
                                chooseNext()
                            }
                        }
                        .setNegativeButton("Cancel") { _, _ -> consumed = true }
                        .setOnCancelListener { consumed = true }
                        .show()
                } catch (error: Exception) {
                    showDialog("Party reordering stopped", error.message ?: "The party could not be reviewed.")
                }
            }
            chooseNext()
        } catch (error: Exception) {
            showDialog("Party reordering stopped", error.message ?: "The party could not be selected.")
        }
    }

    private fun applyGen3PartyOrder(
        file: File, reviewed: ByteArray, sourceUri: Uri?, sourceLabel: String?, order: List<Int>
    ) {
        fun bound(): Boolean = importedFile?.absolutePath == file.absolutePath &&
            currentSourceUri == sourceUri && currentSourceLabel == sourceLabel
        var writeStarted = false
        var backup: File? = null
        try {
            require(bound()) { "The save identity changed after review." }
            val fresh = file.readBytes()
            require(fresh.contentEquals(reviewed) && gen3SaveValid(fresh)) {
                "The save changed or failed validation after review."
            }
            val game = detectGen3GameFromData(fresh, sourceLabel ?: file.name)
            val offset = gen3PartyOffset(fresh, game) ?: error("The party could not be located.")
            val count = readU32LE(fresh, offset - 4).toInt()
            val members = gen3PartyBatchMoveMembers(fresh, offset, count)
            val records = fresh.copyOfRange(offset, offset + 600)
            val reordered = Gen3PartyEditing.reorderPartyPokemon(records, count, order)
            require(!reordered.contentEquals(records)) { "The party order is already unchanged." }
            order.forEachIndexed { target, source ->
                require(reordered.copyOfRange(target * 100, (target + 1) * 100)
                    .contentEquals(records.copyOfRange(source * 100, (source + 1) * 100))) {
                    "A staged party member did not retain its complete record."
                }
            }
            require(reordered.copyOfRange(count * 100, reordered.size)
                .contentEquals(records.copyOfRange(count * 100, records.size))) {
                "The inactive party storage changed."
            }
            val map = gen3ActiveSectionMap(fresh) ?: error("The active save sections could not be mapped.")
            val section1 = map[1]
            require(section1 >= 0) { "The active party section is missing." }
            val work = fresh.copyOf()
            reordered.copyInto(work, offset)
            updateGen3SectionChecksumAt(work, section1, 1)
            val partyRange = offset until offset + count * 100
            require(gen3SaveValid(work) &&
                gen3ActiveSectionMap(work)?.contentEquals(map) == true &&
                readU32LE(work, offset - 4).toInt() == count &&
                work.indices.all { index ->
                    index in partyRange || index == section1 + 0xFF6 ||
                        index == section1 + 0xFF7 || work[index] == fresh[index]
                }) { "The staged party order failed integrity or unrelated-byte verification." }
            backup = File.createTempFile(backupGameName(file) + "_PreGen3PartyOrder_", ".backup", backupsDir())
            backup!!.writeBytes(fresh)
            require(backup!!.readBytes().contentEquals(fresh)) { "The recovery backup did not verify." }
            retainGen2ToGen3SafetyBackup(backup!!, fresh)
            require(bound() && file.readBytes().contentEquals(fresh)) {
                "The save changed before writing. Nothing was changed."
            }
            writeStarted = true
            file.writeBytes(work)
            val persisted = file.readBytes()
            require(persisted.contentEquals(work) && gen3SaveValid(persisted)) {
                "The persisted party order failed byte or checksum verification."
            }
            val reopened = gen3PartyOffset(persisted, game) ?: error("The party could not be reopened.")
            require(readU32LE(persisted, reopened - 4).toInt() == count &&
                persisted.copyOfRange(reopened, reopened + 600).contentEquals(reordered)) {
                "The party order or count did not persist exactly."
            }
            val verified = gen3PartyBatchMoveMembers(persisted, reopened, count)
            require(order.indices.all { target ->
                val expected = members[order[target]]
                val actual = verified[target]
                actual.pid == expected.pid && actual.species == expected.species &&
                    actual.isEgg == expected.isEgg
            }) { "The reordered party identities or Egg states did not reopen correctly." }
            Toast.makeText(this, "Party order saved and verified", Toast.LENGTH_LONG).show()
            showGen3PokemonViewer("party")
        } catch (error: Exception) {
            val restored = if (writeStarted) runCatching {
                file.writeBytes(reviewed)
                file.readBytes().contentEquals(reviewed)
            }.getOrDefault(false) else true
            val recovery = when {
                !writeStarted -> "Nothing was written."
                restored -> "The reviewed save was restored and verified."
                else -> "Automatic rollback could not be verified. Restore the retained recovery backup before editing again."
            }
            showDialog("Gen 3 party reordering failed",
                (error.message ?: "Unknown error") + "\n\n" + recovery +
                    (backup?.let { "\nRecovery backup: ${it.name}" } ?: ""))
        }
    }

    private data class Gen3PartyMarkingSnapshot(
        val offset: Int, val count: Int, val records: ByteArray, val members: List<PokemonEntry>
    )

    private fun gen3PartyMarkingSnapshot(
        file: File, opened: ByteArray, sourceUri: Uri?, sourceLabel: String?
    ): Gen3PartyMarkingSnapshot {
        require(importedFile?.absolutePath == file.absolutePath &&
            currentSourceUri == sourceUri && currentSourceLabel == sourceLabel &&
            file.readBytes().contentEquals(opened) && gen3SaveValid(opened)) {
            "The save or its identity changed. Reopen the party before editing."
        }
        val game = detectGen3GameFromData(opened, sourceLabel ?: file.name)
        val offset = gen3PartyOffset(opened, game) ?: error("The Gen 3 party could not be located.")
        require(offset >= 4 && offset + 600 <= opened.size) { "The party storage is incomplete." }
        val count = readU32LE(opened, offset - 4).toInt()
        require(count in 1..6) { "The party count is invalid." }
        val records = opened.copyOfRange(offset, offset + 600)
        val members = (0 until count).map { slot ->
            val pokemon = parsePk3(records, slot * 100, true)
            require(pokemon != null && pokemon.checksumValid &&
                (records[slot * 100 + 0x13].toInt() and 3) == 2) {
                "Party slot ${slot + 1} failed PK3 validation."
            }
            pokemon
        }
        return Gen3PartyMarkingSnapshot(offset, count, records, members)
    }

    private fun showGen3PartyMarkings(
        file: File, opened: ByteArray, sourceUri: Uri?, sourceLabel: String?,
        selectedSlots: List<Int>? = null
    ) {
        try {
            val snapshot = gen3PartyMarkingSnapshot(file, opened, sourceUri, sourceLabel)
            val names = listOf("Circle", "Square", "Triangle", "Heart")
            fun label(slot: Int): String {
                val p = snapshot.members[slot]
                val markings = names.indices.filter { (p.markingValue and (1 shl it)) != 0 }
                    .map { names[it] }.joinToString(", ").ifBlank { "None" }
                return "Slot ${slot + 1} • ${p.nickname.ifBlank { "Species #${p.species}" }}" +
                    (if (p.isEgg) " • Egg" else "") + " • $markings"
            }
            if (selectedSlots == null) {
                val selected = linkedSetOf<Int>()
                var consumed = false
                AlertDialog.Builder(this)
                    .setTitle("Select party Pokémon for markings")
                    .setMultiChoiceItems((0 until snapshot.count).map { label(it) }.toTypedArray(),
                        BooleanArray(snapshot.count)) { _, index, checked ->
                        if (index in 0 until snapshot.count) {
                            if (checked) selected.add(index) else selected.remove(index)
                        }
                    }
                    .setNegativeButton("Cancel") { _, _ -> consumed = true }
                    .setOnCancelListener { consumed = true }
                    .setPositiveButton("Edit markings") { _, _ ->
                        if (!consumed) {
                            consumed = true
                            showGen3PartyMarkings(file, opened, sourceUri, sourceLabel, selected.toList().sorted())
                        }
                    }.show()
                return
            }
            val slots = selectedSlots.toList().sorted()
            // Validate selection and every selected PK3 before displaying editing controls.
            Gen3PartyEditing.setSelectedPartyMarkings(snapshot.records, snapshot.count, slots, 0)
            val masks = slots.map { snapshot.members[it].markingValue and 15 }
            val common = masks.reduce { first, next -> first and next }
            val checks = names.mapIndexed { index, name ->
                CheckBox(this).apply {
                    text = name
                    setTextColor(TEXT)
                    isChecked = (common and (1 shl index)) != 0
                }
            }
            val form = LinearLayout(this).apply {
                orientation = LinearLayout.VERTICAL
                setPadding(dp(20), dp(8), dp(20), dp(8))
            }
            addMutedLine(form, "Checked markings replace all four markings on each selected party Pokémon. " +
                "Uncheck all four to clear markings. HP, status, battle stats and Egg state stay unchanged.")
            if (masks.distinct().size > 1) {
                addMutedLine(form, "This selection has mixed markings; only shared markings start checked.")
            }
            checks.forEach { form.addView(it) }
            slots.forEach { addMutedLine(form, label(it)) }
            var consumed = false
            AlertDialog.Builder(this)
                .setTitle("Edit party markings (${slots.size} selected)")
                .setView(ScrollView(this).apply { addView(form) })
                .setNegativeButton("Cancel") { _, _ -> consumed = true }
                .setOnCancelListener { consumed = true }
                .setPositiveButton("Review") { _, _ ->
                    if (!consumed) {
                        consumed = true
                        try {
                            val fresh = gen3PartyMarkingSnapshot(file, opened, sourceUri, sourceLabel)
                            val mask = checks.indices.filter { checks[it].isChecked }
                                .fold(0) { value, index -> value or (1 shl index) }
                            Gen3PartyEditing.setSelectedPartyMarkings(fresh.records, fresh.count, slots, mask)
                            val marked = names.indices.filter { (mask and (1 shl it)) != 0 }
                                .map { names[it] }.joinToString(", ").ifBlank { "None (clear all four)" }
                            var applied = false
                            AlertDialog.Builder(this)
                                .setTitle("Apply party markings?")
                                .setMessage("Slots: ${slots.joinToString(", ") { (it + 1).toString() }}\n\n" +
                                    "Replace markings with: $marked\n\n" +
                                    "PSE will verify a recovery backup, update only selected marking bits, " +
                                    "repair the party section checksum, reopen and verify the result. " +
                                    "Unselected Pokémon, Egg state, HP, status and battle stats stay unchanged.")
                                .setNegativeButton("Cancel") { _, _ -> applied = true }
                                .setOnCancelListener { applied = true }
                                .setPositiveButton("Apply markings") { _, _ ->
                                    if (!applied) {
                                        applied = true
                                        applyGen3PartyMarkings(file, opened, sourceUri, sourceLabel, slots, mask)
                                    }
                                }.show()
                        } catch (error: Exception) {
                            showDialog("Party marking edit stopped", error.message ?: "The selection could not be reviewed.")
                        }
                    }
                }.show()
        } catch (error: Exception) {
            showDialog("Party marking edit stopped", error.message ?: "The party could not be selected.")
        }
    }

    private fun applyGen3PartyMarkings(
        file: File, opened: ByteArray, sourceUri: Uri?, sourceLabel: String?,
        slots: List<Int>, mask: Int
    ) {
        var writeStarted = false
        try {
            val snapshot = gen3PartyMarkingSnapshot(file, opened, sourceUri, sourceLabel)
            val edited = Gen3PartyEditing.setSelectedPartyMarkings(snapshot.records, snapshot.count, slots, mask)
            val markingOffsets = slots.map { it * 100 + 0x1B }.toSet()
            require(edited.indices.all { it in markingOffsets || edited[it] == snapshot.records[it] }) {
                "The staged marking edit changed unrelated party data."
            }
            slots.forEach { slot ->
                val before = snapshot.members[slot]
                val after = parsePk3(edited, slot * 100, true)
                require(after != null && after.checksumValid && before.isEgg == after.isEgg &&
                    after.markingValue == ((before.markingValue and 0xF0) or mask)) {
                    "Party slot ${slot + 1} failed marking verification."
                }
            }
            if (edited.contentEquals(snapshot.records)) {
                Toast.makeText(this, "Selected party Pokémon already have these markings", Toast.LENGTH_LONG).show()
                return
            }
            val sectionMap = gen3ActiveSectionMap(opened) ?: error("The active save sections could not be mapped.")
            val section1 = sectionMap[1]
            require(section1 >= 0 && snapshot.offset >= section1 &&
                snapshot.offset + 600 <= section1 + gen3SectionLengths[1]) {
                "The party is outside its validated save section."
            }
            val work = opened.copyOf()
            edited.copyInto(work, snapshot.offset)
            updateGen3SectionChecksumAt(work, section1, 1)
            val allowed = markingOffsets.map { snapshot.offset + it }.toSet() +
                setOf(section1 + 0xFF6, section1 + 0xFF7)
            require(gen3SaveValid(work) && work.indices.all { it in allowed || work[it] == opened[it] }) {
                "The staged save failed checksum or unrelated-byte verification."
            }
            val backup = File.createTempFile(backupGameName(file) + "_PreGen3PartyMarkings_", ".backup", backupsDir())
            backup.writeBytes(opened)
            require(backup.readBytes().contentEquals(opened)) { "The recovery backup did not verify." }
            retainGen2ToGen3SafetyBackup(backup, opened)
            gen3PartyMarkingSnapshot(file, opened, sourceUri, sourceLabel)
            writeStarted = true
            file.writeBytes(work)
            val persisted = file.readBytes()
            require(persisted.contentEquals(work) && gen3SaveValid(persisted)) {
                "The persisted party markings failed byte or checksum verification."
            }
            val reopened = gen3PartyMarkingSnapshot(file, persisted, sourceUri, sourceLabel)
            require(reopened.offset == snapshot.offset && reopened.count == snapshot.count &&
                reopened.records.contentEquals(edited)) { "The marked party did not reopen exactly." }
            Toast.makeText(this, "${slots.size} party Pokémon's markings saved and verified; backup retained",
                Toast.LENGTH_LONG).show()
            showGen3PokemonViewer("party")
        } catch (error: Exception) {
            val restored = if (writeStarted) runCatching {
                file.writeBytes(opened)
                val restoredBytes = file.readBytes()
                restoredBytes.contentEquals(opened) && gen3SaveValid(restoredBytes)
            }.getOrDefault(false) else false
            val recovery = when {
                !writeStarted -> "Nothing was written."
                restored -> "The original save was restored and verified."
                else -> "Automatic restore could not be verified. Restore the retained backup before editing again."
            }
            showDialog("Gen 3 party marking edit failed", (error.message ?: "Unknown error") + "\n\n" + recovery)
        }
    }

    private fun showGen3SelectedPartyRecovery(
        file: File, opened: ByteArray, sourceUri: Uri?, sourceLabel: String?
    ) {
        try {
            require(importedFile?.absolutePath == file.absolutePath &&
                currentSourceUri == sourceUri && currentSourceLabel == sourceLabel &&
                file.readBytes().contentEquals(opened) && gen3SaveValid(opened)) {
                "The save or its identity changed. Reopen the party."
            }
            val game = detectGen3GameFromData(opened, sourceLabel ?: file.name)
            val offset = gen3PartyOffset(opened, game) ?: error("The party could not be located.")
            val count = readU32LE(opened, offset - 4).toInt()
            val candidates = gen3PartyRecoveryCandidates(opened, offset, count)
            require(candidates.isNotEmpty()) { "There are no non-Egg party Pokémon to restore." }
            val selected = linkedSetOf<Int>()
            val labels = candidates.map { slot ->
                val p = parsePk3(opened, offset + slot * 100, true)
                    ?: error("A party record could not be read.")
                val name = p.nickname.ifBlank {
                    canonicalGen3SpeciesName(p.species) ?: "Species #${p.species}"
                }
                val hp = readU16LE(opened, offset + slot * 100 + 0x56)
                val maximum = readU16LE(opened, offset + slot * 100 + 0x58)
                val status = (offset + slot * 100 + 0x50 until offset + slot * 100 + 0x54)
                    .any { opened[it] != 0.toByte() }
                "Slot ${slot + 1} • ${name} • HP ${hp}/${maximum}" +
                    if (status) " • status condition" else ""
            }
            var consumed = false
            AlertDialog.Builder(this)
                .setTitle("Select party Pokémon to restore")
                .setMultiChoiceItems(labels.toTypedArray(), BooleanArray(candidates.size)) { _, index, checked ->
                    val slot = candidates.getOrNull(index) ?: return@setMultiChoiceItems
                    if (checked) selected.add(slot) else selected.remove(slot)
                }
                .setNegativeButton("Cancel") { _, _ -> consumed = true }
                .setOnCancelListener { consumed = true }
                .setPositiveButton("Review recovery") { _, _ ->
                    if (!consumed) {
                        consumed = true
                        showGen3PartyBatchRecoveryDialog(
                            file, opened, sourceUri, sourceLabel, selected.toList().sorted()
                        )
                    }
                }.show()
        } catch (error: Exception) {
            showDialog("Party recovery selection stopped",
                error.message ?: "The party could not be selected. Nothing was changed.")
        }
    }

    private fun showGen3PartyBatchRecoveryDialog(
        file: File,
        opened: ByteArray,
        openedSourceUri: Uri?,
        openedSourceLabel: String?,
        selectedSlots: List<Int>? = null
    ) {
        try {
            require(importedFile?.absolutePath == file.absolutePath &&
                currentSourceUri == openedSourceUri &&
                currentSourceLabel == openedSourceLabel) {
                "The loaded save identity changed. Reopen the party."
            }
            val fresh = file.readBytes()
            require(fresh.contentEquals(opened) && gen3SaveValid(fresh)) {
                "The save changed or failed validation. Reopen the party."
            }
            val game = detectGen3GameFromData(fresh, openedSourceLabel ?: file.name)
            val partyOffset = gen3PartyOffset(fresh, game)
                ?: error("The Gen 3 party block could not be located.")
            val partyCount = readU32LE(fresh, partyOffset - 4).toInt()
            val candidates = gen3PartyRecoveryCandidates(fresh, partyOffset, partyCount)
            if (candidates.isEmpty()) {
                showDialog("Party recovery", "There are no non-Egg party Pokémon to restore.")
                return
            }
            val slots = selectedSlots?.sorted() ?: candidates
            val records = fresh.copyOfRange(partyOffset, partyOffset + 600)
            val result = Gen3PartyEditing.restoreEligiblePartyHpAndStatus(
                records, partyCount, candidates, slots
            )
            if (result.changedSlots.isEmpty()) {
                showDialog(
                    "Party already restored",
                    "The selected party Pokémon have full HP and no status condition."
                )
                return
            }
            val changes = result.changedSlots.joinToString("\n") { slot ->
                val pokemon = parsePk3(fresh, partyOffset + slot * 100, true)
                    ?: error("A reviewed party Pokémon could not be read.")
                val name = pokemon.nickname.ifBlank {
                    canonicalGen3SpeciesName(pokemon.species) ?: "Species #${pokemon.species}"
                }
                val before = readU16LE(records, slot * 100 + 0x56)
                val maximum = readU16LE(records, slot * 100 + 0x58)
                val statusSet = (slot * 100 + 0x50 until slot * 100 + 0x54)
                    .any { records[it] != 0.toByte() }
                "Slot ${slot + 1} • ${name}: HP ${before} → ${maximum}" +
                    if (statusSet) " • clear status" else ""
            }
            var consumed = false
            AlertDialog.Builder(this)
                .setTitle("Restore ${result.changedSlots.size} party Pokémon?")
                .setMessage(
                    changes + "\n\nUnselected Pokémon, Eggs and already healthy Pokémon stay unchanged. " +
                        "This restores current HP and status only; moves and PP stay as loaded. " +
                        "PSE will create a verified recovery backup, save the whole batch, " +
                        "rebuild the party checksum, reopen every party record, and " +
                        "restore the backup if verification fails."
                )
                .setNegativeButton("Cancel") { _, _ -> consumed = true }
                .setOnCancelListener { consumed = true }
                .setPositiveButton("Restore party") { _, _ ->
                    if (!consumed) {
                        consumed = true
                        restoreGen3WholePartyHpAndStatus(
                            file, fresh, openedSourceUri, openedSourceLabel, slots
                        )
                    }
                }
                .show()
        } catch (error: Exception) {
            showDialog(
                "Party recovery stopped",
                error.message ?: "The Gen 3 party could not be reviewed."
            )
        }
    }

    private fun restoreGen3WholePartyHpAndStatus(
        file: File,
        reviewed: ByteArray,
        reviewedSourceUri: Uri?,
        reviewedSourceLabel: String?,
        reviewedSlots: List<Int>
    ) {
        var writeStarted = false
        try {
            require(importedFile?.absolutePath == file.absolutePath &&
                currentSourceUri == reviewedSourceUri &&
                currentSourceLabel == reviewedSourceLabel) {
                "The loaded save identity changed after review."
            }
            val fresh = file.readBytes()
            require(fresh.contentEquals(reviewed) && gen3SaveValid(fresh)) {
                "The save changed or failed validation after review."
            }
            val game = detectGen3GameFromData(fresh, reviewedSourceLabel ?: file.name)
            val partyOffset = gen3PartyOffset(fresh, game)
                ?: error("The Gen 3 party block could not be located.")
            val partyCount = readU32LE(fresh, partyOffset - 4).toInt()
            val candidates = gen3PartyRecoveryCandidates(fresh, partyOffset, partyCount)
            val slots = reviewedSlots.toList()
            val records = fresh.copyOfRange(partyOffset, partyOffset + 600)
            val result = Gen3PartyEditing.restoreEligiblePartyHpAndStatus(
                records, partyCount, candidates, slots
            )
            require(result.changedSlots.isNotEmpty()) {
                "The party already has full HP and no status conditions."
            }
            require(records.indices.all { index ->
                val slot = index / 100
                val local = index % 100
                (slot in result.changedSlots &&
                    (local in 0x50 until 0x54 || local in 0x56 until 0x58)) ||
                    records[index] == result.partyRecords[index]
            }) {
                "The staged recovery changed data outside current HP and status."
            }
            val sectionMap = gen3ActiveSectionMap(fresh)
                ?: error("The active Gen 3 save sections could not be mapped.")
            val section1 = sectionMap[1]
            require(section1 >= 0) { "The active party section is missing." }
            val work = fresh.copyOf()
            result.partyRecords.copyInto(work, partyOffset)
            updateGen3SectionChecksumAt(work, section1, 1)
            val allowed = HashSet<Int>()
            result.changedSlots.forEach { slot ->
                val offset = partyOffset + slot * 100
                for (index in offset + 0x50 until offset + 0x54) allowed.add(index)
                for (index in offset + 0x56 until offset + 0x58) allowed.add(index)
            }
            allowed.add(section1 + 0xFF6)
            allowed.add(section1 + 0xFF7)
            require(gen3SaveValid(work) &&
                readU32LE(work, partyOffset - 4).toInt() == partyCount &&
                work.indices.all { it in allowed || work[it] == fresh[it] }) {
                "The staged party recovery failed checksum or unrelated-byte verification."
            }
            val backup = File.createTempFile(
                backupGameName(file) + "_PreGen3WholePartyRecovery_",
                ".backup",
                backupsDir()
            )
            backup.writeBytes(fresh)
            require(backup.readBytes().contentEquals(fresh)) {
                "The recovery backup did not verify."
            }
            retainGen2ToGen3SafetyBackup(backup, fresh)
            require(importedFile?.absolutePath == file.absolutePath &&
                currentSourceUri == reviewedSourceUri &&
                currentSourceLabel == reviewedSourceLabel &&
                file.readBytes().contentEquals(fresh)) {
                "The active save changed before writing. Nothing was changed."
            }

            writeStarted = true
            file.writeBytes(work)
            val persisted = file.readBytes()
            require(persisted.contentEquals(work) && gen3SaveValid(persisted)) {
                "The persisted party recovery failed byte or checksum verification."
            }
            val reopenedOffset = gen3PartyOffset(persisted, game)
                ?: error("The persisted party could not be reopened.")
            require(readU32LE(persisted, reopenedOffset - 4).toInt() == partyCount &&
                persisted.copyOfRange(reopenedOffset, reopenedOffset + 600)
                    .contentEquals(result.partyRecords) &&
                gen3PartyRecoveryCandidates(persisted, reopenedOffset, partyCount) == candidates) {
                "The recovered party, Egg state, or party count did not persist exactly."
            }
            result.changedSlots.forEach { slot ->
                val offset = reopenedOffset + slot * 100
                require(readU16LE(persisted, offset + 0x56) ==
                    readU16LE(persisted, offset + 0x58) &&
                    (offset + 0x50 until offset + 0x54)
                        .all { persisted[it] == 0.toByte() }) {
                    "Party slot ${slot + 1} did not reopen with full HP and clear status."
                }
            }
            Toast.makeText(
                this,
                "Restored ${result.changedSlots.size} party Pokémon and verified",
                Toast.LENGTH_LONG
            ).show()
            showGen3PokemonViewer("party")
        } catch (error: Exception) {
            val restored = if (writeStarted) {
                runCatching {
                    file.writeBytes(reviewed)
                    file.readBytes().contentEquals(reviewed)
                }.getOrDefault(false)
            } else {
                false
            }
            val recovery = when {
                !writeStarted -> "Nothing was written."
                restored -> "The reviewed save was restored and verified."
                else -> "Automatic restore could not be verified. Restore the retained recovery backup before editing again."
            }
            showDialog(
                "Gen 3 whole-party recovery failed",
                (error.message ?: "Unknown error") + "\n\n" + recovery
            )
        }
    }

    private fun confirmGen3PartyRecovery(
        location: String,
        p: PokemonEntry
    ) {
        val file = importedFile ?: return
        val sourceSlot = partyLocationToSlot(location) ?: run {
            showDialog(
                "Restore HP & Status",
                "This action is available for Gen 3 party Pokémon only."
            )
            return
        }
        val reviewedSourceUri = currentSourceUri
        val reviewedSourceLabel = currentSourceLabel
        val reviewed = runCatching { file.readBytes() }.getOrNull() ?: run {
            showDialog("Restore HP & Status", "Could not read the working copy.")
            return
        }
        if (!gen3SaveValid(reviewed)) {
            showDialog(
                "Restore HP & Status",
                "The Gen 3 save failed section/checksum validation."
            )
            return
        }
        val game = detectGen3GameFromData(reviewed, reviewedSourceLabel ?: file.name)
        val partyOffset = gen3PartyOffset(reviewed, game) ?: run {
            showDialog(
                "Restore HP & Status",
                "The Gen 3 party block could not be located."
            )
            return
        }
        val partyCount = readU32LE(reviewed, partyOffset - 4).toInt()
        val recordOffset = partyOffset + sourceSlot * 100
        val source = parsePk3(reviewed, recordOffset, true)
        if (partyCount !in 1..6 || sourceSlot !in 0 until partyCount ||
            source == null || source.pid != p.pid || source.species != p.species ||
            !source.checksumValid) {
            showDialog(
                "Restore blocked",
                "The party changed or the selected Pokémon failed its PK3 checksum."
            )
            return
        }
        val raw = reviewed.copyOfRange(recordOffset, recordOffset + 100)
        val recovery = runCatching {
            Gen3PartyEditing.restorePartyHpAndStatus(raw)
        }.getOrElse {
            showDialog("Restore blocked", it.message ?: "The party HP fields are invalid.")
            return
        }
        if (recovery.previousHp == recovery.maxHp && !recovery.statusWasSet) {
            showDialog(
                "Already restored",
                "This Pokémon already has full HP and no status condition."
            )
            return
        }
        val name = source.nickname.ifBlank {
            canonicalGen3SpeciesName(source.species) ?: "Species #" + source.species
        }
        AlertDialog.Builder(this)
            .setTitle("Restore " + name + "?")
            .setMessage(
                "Restore current HP from " + recovery.previousHp + " to " +
                    recovery.maxHp + " and clear its party status condition?\n\n" +
                    "PSE will not change the encrypted 80-byte PK3 data or cached battle " +
                    "stats. It will create a verified recovery backup, update the party " +
                    "section checksum, reopen the record, and roll back on any mismatch."
            )
            .setNegativeButton("Cancel", null)
            .setPositiveButton("Restore") { _, _ ->
                restoreGen3PartyPokemon(
                    file,
                    reviewed,
                    reviewedSourceUri,
                    reviewedSourceLabel,
                    sourceSlot,
                    p
                )
            }
            .show()
    }

    private fun restoreGen3PartyPokemon(
        file: File,
        reviewed: ByteArray,
        reviewedSourceUri: Uri?,
        reviewedSourceLabel: String?,
        sourceSlot: Int,
        p: PokemonEntry
    ) {
        var writeStarted = false
        try {
            require(importedFile?.absolutePath == file.absolutePath &&
                currentSourceUri == reviewedSourceUri &&
                currentSourceLabel == reviewedSourceLabel) {
                "The loaded save identity changed after review."
            }
            val fresh = file.readBytes()
            require(fresh.contentEquals(reviewed)) {
                "The save changed after review. Reopen the Pokémon and try again."
            }
            require(gen3SaveValid(fresh)) {
                "The fresh save is no longer a valid Generation 3 save."
            }
            val game = detectGen3GameFromData(fresh, reviewedSourceLabel ?: file.name)
            val partyOffset = gen3PartyOffset(fresh, game)
                ?: error("The Gen 3 party block could not be located.")
            val partyCount = readU32LE(fresh, partyOffset - 4).toInt()
            require(partyCount in 1..6 && sourceSlot in 0 until partyCount) {
                "The selected party slot is no longer active."
            }
            val recordOffset = partyOffset + sourceSlot * 100
            val source = parsePk3(fresh, recordOffset, true)
                ?: error("The source party Pokémon is no longer present.")
            require(source.pid == p.pid && source.species == p.species &&
                source.checksumValid) {
                "The source party Pokémon changed or failed its PK3 checksum."
            }
            val originalRecord = fresh.copyOfRange(recordOffset, recordOffset + 100)
            val recovery = Gen3PartyEditing.restorePartyHpAndStatus(originalRecord)
            require(recovery.previousHp < recovery.maxHp || recovery.statusWasSet) {
                "This Pokémon already has full HP and no status condition."
            }
            require(recovery.partyRecord.copyOfRange(0, 80)
                    .contentEquals(originalRecord.copyOfRange(0, 80)) &&
                recovery.partyRecord.copyOfRange(0x58, 100)
                    .contentEquals(originalRecord.copyOfRange(0x58, 100)) &&
                recovery.partyRecord.indices.all {
                    it in 0x50 until 0x54 || it in 0x56 until 0x58 ||
                        recovery.partyRecord[it] == originalRecord[it]
                }) {
                "The staged recovery changed data outside status and current HP."
            }

            val sectionMap = gen3ActiveSectionMap(fresh)
                ?: error("PSE could not map the active Gen 3 save sections.")
            val section1 = sectionMap[1]
            require(section1 >= 0) { "The active party section is missing." }
            val work = fresh.copyOf()
            recovery.partyRecord.copyInto(work, recordOffset)
            updateGen3SectionChecksumAt(work, section1, 1)
            require(readU32LE(work, partyOffset - 4).toInt() == partyCount) {
                "The staged recovery changed the party count."
            }
            require(gen3SaveValid(work)) {
                "The staged save failed Gen 3 section-checksum verification."
            }
            val allowed = HashSet<Int>()
            for (index in recordOffset + 0x50 until recordOffset + 0x54) {
                allowed.add(index)
            }
            for (index in recordOffset + 0x56 until recordOffset + 0x58) {
                allowed.add(index)
            }
            allowed.add(section1 + 0xFF6)
            allowed.add(section1 + 0xFF7)
            require(work.indices.all { it in allowed || work[it] == fresh[it] }) {
                "The recovery changed data outside status, current HP, and checksum."
            }

            val backup = File.createTempFile(
                backupGameName(file) + "_PreGen3PartyRecovery_",
                ".backup",
                backupsDir()
            )
            backup.writeBytes(fresh)
            require(backup.readBytes().contentEquals(fresh)) {
                "The recovery backup did not verify."
            }
            retainGen2ToGen3SafetyBackup(backup, fresh)
            require(importedFile?.absolutePath == file.absolutePath &&
                currentSourceUri == reviewedSourceUri &&
                currentSourceLabel == reviewedSourceLabel &&
                file.readBytes().contentEquals(fresh)) {
                "The active save changed before writing. Nothing was changed."
            }

            writeStarted = true
            file.writeBytes(work)
            val persisted = file.readBytes()
            require(persisted.contentEquals(work) && gen3SaveValid(persisted)) {
                "The persisted Gen 3 save failed byte or checksum verification."
            }
            val reopenedOffset = gen3PartyOffset(persisted, game)
                ?: error("The persisted party block could not be reopened.")
            val reopenedRecordOffset = reopenedOffset + sourceSlot * 100
            val reopened = parsePk3(persisted, reopenedRecordOffset, true)
                ?: error("The restored party Pokémon was missing after reopen.")
            val reopenedRaw = persisted.copyOfRange(
                reopenedRecordOffset,
                reopenedRecordOffset + 100
            )
            val reopenedHp = readU16LE(reopenedRaw, 0x56)
            val reopenedMaxHp = readU16LE(reopenedRaw, 0x58)
            require(reopened.checksumValid && reopened.pid == source.pid &&
                reopened.species == source.species &&
                reopenedRaw.copyOfRange(0x50, 0x54).all { it == 0.toByte() } &&
                reopenedHp == recovery.maxHp &&
                reopenedMaxHp == recovery.maxHp &&
                reopenedRaw.copyOfRange(0, 80)
                    .contentEquals(originalRecord.copyOfRange(0, 80))) {
                "The restored party record failed final verification."
            }
            Toast.makeText(
                this,
                "Restored HP and status and verified",
                Toast.LENGTH_LONG
            ).show()
            showGen3PokemonViewer("party")
        } catch (error: Exception) {
            val restored = if (writeStarted) {
                runCatching {
                    file.writeBytes(reviewed)
                    file.readBytes().contentEquals(reviewed)
                }.getOrDefault(false)
            } else {
                false
            }
            val recovery = when {
                !writeStarted -> "Nothing was written."
                restored -> "The reviewed save was restored and verified."
                else -> "Automatic restore could not be verified. Restore the retained backup before editing this save again."
            }
            showDialog(
                "Gen 3 party recovery failed",
                (error.message ?: "Unknown error") + "\n\n" + recovery
            )
        }
    }

    private fun confirmGen3PcToParty(
        location: String,
        p: PokemonEntry
    ) {
        val file = importedFile ?: return
        val sourceGlobal = boxedLocationToGlobalIndex(location) ?: run {
            showDialog("Move to Party", "This action is available for Gen 3 PC Pokémon only.")
            return
        }
        val reviewedSourceUri = currentSourceUri
        val reviewedSourceLabel = currentSourceLabel
        val reviewed = runCatching { file.readBytes() }.getOrNull() ?: run {
            showDialog("Move to Party", "Could not read the working copy.")
            return
        }
        if (!gen3SaveValid(reviewed)) {
            showDialog("Move to Party", "The Gen 3 save failed section/checksum validation.")
            return
        }
        if (p.species == 386) {
            showDialog(
                "Move to Party blocked",
                "Deoxys has game-specific Generation 3 base stats. PSE will not guess " +
                    "which forme's cached party stats to build."
            )
            return
        }
        val pc = gen3PcBuffer(reviewed) ?: run {
            showDialog("Move to Party", "The Gen 3 PC storage could not be opened.")
            return
        }
        val sourceOffset = 4 + sourceGlobal * 80
        val source = parsePk3(pc, sourceOffset, false)
        val game = detectGen3GameFromData(reviewed, reviewedSourceLabel ?: file.name)
        val partyOffset = gen3PartyOffset(reviewed, game) ?: run {
            showDialog("Move to Party", "The Gen 3 party block could not be located.")
            return
        }
        val partyCount = readU32LE(reviewed, partyOffset - 4).toInt()
        if (partyCount !in 1..5 || source == null ||
            source.pid != p.pid || source.species != p.species ||
            !source.checksumValid) {
            showDialog(
                "Move to Party blocked",
                if (partyCount >= 6) {
                    "The Gen 3 party is full."
                } else {
                    "The PC slot changed or the selected Pokémon failed its PK3 checksum."
                }
            )
            return
        }
        val targetOffset = partyOffset + partyCount * 100
        if (!reviewed.copyOfRange(targetOffset, targetOffset + 100)
                .all { it == 0.toByte() }) {
            showDialog(
                "Move to Party blocked",
                "The next inactive party record is not exactly empty. Nothing was changed."
            )
            return
        }
        val growthRate = canonicalGen3GrowthRate(source.species)
        val level = growthRate?.let {
            canonicalLevelForGrowthRate(it, source.experience)
        }
        val baseStats = canonicalGen3BaseStats(source.species)
        if (level == null || baseStats == null) {
            showDialog(
                "Move to Party blocked",
                "PSE could not verify this Pokémon's Gen 3 growth curve and base stats."
            )
            return
        }
        val battleStats = calculateGen3BattleStats(
            baseStats,
            source.ivs,
            source.evs,
            source.nature,
            level
        )
        val name = source.nickname.ifBlank {
            canonicalGen3SpeciesName(source.species) ?: "Species #" + source.species
        }
        AlertDialog.Builder(this)
            .setTitle("Move " + name + " to Party?")
            .setMessage(
                "Move this exact PK3 from " + location + " into Party Slot " +
                    (partyCount + 1) + "?\n\nPSE will preserve its complete 80-byte " +
                    "stored record, rebuild only the required party level/HP/battle-stat " +
                    "fields from embedded Gen 3 data, clear the PC source, create a verified " +
                    "backup, update all affected checksums, reopen both locations, and roll " +
                    "back on any mismatch."
            )
            .setNegativeButton("Cancel", null)
            .setPositiveButton("Move") { _, _ ->
                moveGen3PcPokemonToParty(
                    file,
                    reviewed,
                    reviewedSourceUri,
                    reviewedSourceLabel,
                    sourceGlobal,
                    p,
                    level,
                    battleStats
                )
            }
            .show()
    }

    private fun moveGen3PcPokemonToParty(
        file: File,
        reviewed: ByteArray,
        reviewedSourceUri: Uri?,
        reviewedSourceLabel: String?,
        sourceGlobal: Int,
        p: PokemonEntry,
        reviewedLevel: Int,
        reviewedStats: IntArray
    ) {
        var writeStarted = false
        try {
            require(importedFile?.absolutePath == file.absolutePath &&
                currentSourceUri == reviewedSourceUri &&
                currentSourceLabel == reviewedSourceLabel) {
                "The loaded save identity changed after review."
            }
            val fresh = file.readBytes()
            require(fresh.contentEquals(reviewed)) {
                "The save changed after review. Reopen the Pokémon and try again."
            }
            require(gen3SaveValid(fresh)) {
                "The fresh save is no longer a valid Generation 3 save."
            }
            require(p.species != 386) {
                "Deoxys party-stat rebuilding remains safety-locked."
            }
            val freshPc = gen3PcBuffer(fresh)
                ?: error("The fresh Gen 3 PC storage could not be opened.")
            val sourceOffset = 4 + sourceGlobal * 80
            val source = parsePk3(freshPc, sourceOffset, false)
                ?: error("The source PC Pokémon is no longer present.")
            require(source.pid == p.pid && source.species == p.species &&
                source.checksumValid) {
                "The source PC Pokémon changed or failed its PK3 checksum."
            }
            val game = detectGen3GameFromData(fresh, reviewedSourceLabel ?: file.name)
            val partyOffset = gen3PartyOffset(fresh, game)
                ?: error("The Gen 3 party block could not be located.")
            val partyCount = readU32LE(fresh, partyOffset - 4).toInt()
            require(partyCount in 1..5) {
                "The Gen 3 party is full or has an invalid count."
            }
            val targetSlot = partyCount
            require(fresh.copyOfRange(
                partyOffset + targetSlot * 100,
                partyOffset + (targetSlot + 1) * 100
            ).all { it == 0.toByte() }) {
                "The next inactive party record is not exactly empty."
            }

            val growthRate = canonicalGen3GrowthRate(source.species)
                ?: error("The Gen 3 growth curve could not be resolved.")
            val level = canonicalLevelForGrowthRate(growthRate, source.experience)
                ?: error("The Gen 3 level could not be resolved from experience.")
            val baseStats = canonicalGen3BaseStats(source.species)
                ?: error("The Gen 3 base stats could not be resolved.")
            val battleStats = calculateGen3BattleStats(
                baseStats,
                source.ivs,
                source.evs,
                source.nature,
                level
            )
            require(level == reviewedLevel &&
                battleStats.contentEquals(reviewedStats)) {
                "The verified party reconstruction inputs changed."
            }

            val partyRecords = fresh.copyOfRange(partyOffset, partyOffset + 600)
            val storedRecord = freshPc.copyOfRange(sourceOffset, sourceOffset + 80)
            val result = Gen3PartyEditing.movePcPokemonToParty(
                partyRecords,
                partyCount,
                freshPc,
                sourceGlobal,
                level,
                battleStats
            )
            require(result.partyCount == partyCount + 1 &&
                result.insertedSlot == targetSlot &&
                result.partyRecords.copyOfRange(
                    targetSlot * 100,
                    targetSlot * 100 + 80
                ).contentEquals(storedRecord) &&
                result.pc.copyOfRange(sourceOffset, sourceOffset + 80)
                    .all { it == 0.toByte() }) {
                "The staged PC-to-party move did not preserve and relocate the exact PK3."
            }
            require(result.partyRecords.indices.all {
                it in targetSlot * 100 until (targetSlot + 1) * 100 ||
                    result.partyRecords[it] == partyRecords[it]
            }) {
                "The staged move changed another party record."
            }
            require(result.pc.indices.all {
                it in sourceOffset until sourceOffset + 80 ||
                    result.pc[it] == freshPc[it]
            }) {
                "The staged move changed another PC byte."
            }
            val staged = parsePk3(result.partyRecords, targetSlot * 100, true)
                ?: error("The staged party Pokémon could not be reopened.")
            val stagedRaw = result.partyRecords.copyOfRange(
                targetSlot * 100,
                (targetSlot + 1) * 100
            )
            val stagedStats = gen3PartyStatsFromRaw(stagedRaw)
                ?: error("The staged party battle stats could not be read.")
            require(staged.checksumValid && staged.pid == source.pid &&
                staged.species == source.species && staged.level == level &&
                stagedStats[0] == level && stagedStats[1] == battleStats[0] &&
                stagedStats[2] == battleStats[0] &&
                (0 until 5).all { stagedStats[it + 3] == battleStats[it + 1] }) {
                "The staged party record failed identity or battle-stat verification."
            }

            val sectionMap = gen3ActiveSectionMap(fresh)
                ?: error("PSE could not map the active Gen 3 save sections.")
            val section1 = sectionMap[1]
            require(section1 >= 0) { "The active party section is missing." }
            val work = fresh.copyOf()
            writeGen3PcBuffer(work, result.pc)
            result.partyRecords.copyInto(work, partyOffset)
            writeU32LE(work, partyOffset - 4, result.partyCount.toLong())
            updateGen3SectionChecksumAt(work, section1, 1)
            require(gen3SaveValid(work)) {
                "The staged save failed complete Gen 3 checksum verification."
            }

            val allowed = HashSet<Int>()
            for (index in partyOffset - 4 until partyOffset) allowed.add(index)
            for (index in partyOffset + targetSlot * 100 until
                partyOffset + (targetSlot + 1) * 100) {
                allowed.add(index)
            }
            allowed.add(section1 + 0xFF6)
            allowed.add(section1 + 0xFF7)
            var logicalBase = 0
            val sourceEnd = sourceOffset + 80
            for (id in 5..13) {
                val sectionBase = sectionMap[id]
                require(sectionBase >= 0) { "An active PC section is missing." }
                val sectionLength = gen3SectionLengths[id]
                val overlapStart = maxOf(sourceOffset, logicalBase)
                val overlapEnd = minOf(sourceEnd, logicalBase + sectionLength)
                for (logical in overlapStart until overlapEnd) {
                    allowed.add(sectionBase + logical - logicalBase)
                }
                allowed.add(sectionBase + 0xFF6)
                allowed.add(sectionBase + 0xFF7)
                logicalBase += sectionLength
            }
            require(work.indices.all { it in allowed || work[it] == fresh[it] }) {
                "The move changed data outside the source PC slot, new party record, " +
                    "party count, and affected checksums."
            }

            val backup = File.createTempFile(
                backupGameName(file) + "_PreGen3PcToParty_",
                ".backup",
                backupsDir()
            )
            backup.writeBytes(fresh)
            require(backup.readBytes().contentEquals(fresh)) {
                "The recovery backup did not verify."
            }
            retainGen2ToGen3SafetyBackup(backup, fresh)
            require(importedFile?.absolutePath == file.absolutePath &&
                currentSourceUri == reviewedSourceUri &&
                currentSourceLabel == reviewedSourceLabel &&
                file.readBytes().contentEquals(fresh)) {
                "The active save changed before writing. Nothing was changed."
            }

            writeStarted = true
            file.writeBytes(work)
            val persisted = file.readBytes()
            require(persisted.contentEquals(work) && gen3SaveValid(persisted)) {
                "The persisted Gen 3 save failed byte or checksum verification."
            }
            val reopenedPc = gen3PcBuffer(persisted)
                ?: error("The persisted Gen 3 PC storage could not be reopened.")
            val reopenedPartyOffset = gen3PartyOffset(persisted, game)
                ?: error("The persisted party block could not be reopened.")
            require(reopenedPc.copyOfRange(sourceOffset, sourceOffset + 80)
                    .all { it == 0.toByte() } &&
                readU32LE(persisted, reopenedPartyOffset - 4).toInt() ==
                    result.partyCount &&
                persisted.copyOfRange(
                    reopenedPartyOffset + targetSlot * 100,
                    reopenedPartyOffset + targetSlot * 100 + 80
                ).contentEquals(storedRecord)) {
                "The exact PC-to-party move did not persist."
            }
            val reopened = parsePk3(
                persisted,
                reopenedPartyOffset + targetSlot * 100,
                true
            ) ?: error("The moved party Pokémon was missing after reopen.")
            val reopenedRaw = persisted.copyOfRange(
                reopenedPartyOffset + targetSlot * 100,
                reopenedPartyOffset + (targetSlot + 1) * 100
            )
            val reopenedStats = gen3PartyStatsFromRaw(reopenedRaw)
                ?: error("The persisted party stats could not be read.")
            require(reopened.checksumValid && reopened.pid == source.pid &&
                reopened.species == source.species && reopened.level == level &&
                reopenedStats.contentEquals(stagedStats)) {
                "The moved party Pokémon failed final verification."
            }
            Toast.makeText(
                this,
                "Moved into Party Slot " + (targetSlot + 1) + " and verified",
                Toast.LENGTH_LONG
            ).show()
            showGen3PokemonViewer("party")
        } catch (error: Exception) {
            val restored = if (writeStarted) {
                runCatching {
                    file.writeBytes(reviewed)
                    file.readBytes().contentEquals(reviewed)
                }.getOrDefault(false)
            } else {
                false
            }
            val recovery = when {
                !writeStarted -> "Nothing was written."
                restored -> "The reviewed save was restored and verified."
                else -> "Automatic restore could not be verified. Restore the retained backup before editing this save again."
            }
            showDialog(
                "Gen 3 PC-to-party move failed",
                (error.message ?: "Unknown error") + "\n\n" + recovery
            )
        }
    }

    private fun chooseGen3PartySwapDestination(
        location: String,
        p: PokemonEntry
    ) {
        val file = importedFile ?: return
        val sourceSlot = partyLocationToSlot(location) ?: run {
            showDialog("Swap Party Positions", "This action is available for Gen 3 party Pokémon only.")
            return
        }
        val reviewedSourceUri = currentSourceUri
        val reviewedSourceLabel = currentSourceLabel
        val reviewed = runCatching { file.readBytes() }.getOrNull() ?: run {
            showDialog("Swap Party Positions", "Could not read the working copy.")
            return
        }
        if (!gen3SaveValid(reviewed)) {
            showDialog(
                "Swap Party Positions",
                "The Gen 3 save failed section/checksum validation."
            )
            return
        }
        val game = detectGen3GameFromData(reviewed, reviewedSourceLabel ?: file.name)
        val partyOffset = gen3PartyOffset(reviewed, game) ?: run {
            showDialog("Swap Party Positions", "The Gen 3 party block could not be located.")
            return
        }
        val partyCount = readU32LE(reviewed, partyOffset - 4).toInt()
        val source = parsePk3(reviewed, partyOffset + sourceSlot * 100, true)
        if (partyCount !in 2..6 || sourceSlot !in 0 until partyCount ||
            source == null || source.pid != p.pid || source.species != p.species ||
            !source.checksumValid) {
            showDialog(
                "Swap blocked",
                if (partyCount <= 1) {
                    "At least two active party Pokémon are required."
                } else {
                    "The party changed or the selected Pokémon failed its PK3 checksum."
                }
            )
            return
        }
        val targets = (0 until partyCount)
            .filter { it != sourceSlot }
            .mapNotNull { slot ->
                val target = parsePk3(reviewed, partyOffset + slot * 100, true)
                    ?: return@mapNotNull null
                if (!target.checksumValid) return@mapNotNull null
                slot to target
            }
        if (targets.size != partyCount - 1) {
            showDialog(
                "Swap blocked",
                "One or more active party records failed PK3 validation. Nothing was changed."
            )
            return
        }
        val labels = targets.map { (slot, target) ->
            val name = target.nickname.ifBlank {
                canonicalGen3SpeciesName(target.species) ?: "Species #" + target.species
            }
            "Party Slot " + (slot + 1) + " • " + name
        }.toTypedArray()
        AlertDialog.Builder(this)
            .setTitle(
                "Swap " + p.nickname.ifBlank { "Party Slot " + (sourceSlot + 1) } + " with"
            )
            .setItems(labels) { _, which ->
                val targetSlot = targets[which].first
                val target = targets[which].second
                val sourceName = p.nickname.ifBlank {
                    canonicalGen3SpeciesName(p.species) ?: "Species #" + p.species
                }
                val targetName = target.nickname.ifBlank {
                    canonicalGen3SpeciesName(target.species) ?: "Species #" + target.species
                }
                AlertDialog.Builder(this)
                    .setTitle("Swap Party Positions?")
                    .setMessage(
                        "Swap " + sourceName + " in Party Slot " + (sourceSlot + 1) +
                            " with " + targetName + " in Party Slot " + (targetSlot + 1) +
                            "?\n\nPSE will exchange the two complete 100-byte records, keep " +
                            "the party count unchanged, create a verified recovery backup, " +
                            "update the section checksum, reopen both slots, and roll back on " +
                            "any mismatch."
                    )
                    .setNegativeButton("Cancel", null)
                    .setPositiveButton("Swap") { _, _ ->
                        swapGen3PartyPokemon(
                            file,
                            reviewed,
                            reviewedSourceUri,
                            reviewedSourceLabel,
                            sourceSlot,
                            targetSlot,
                            p
                        )
                    }
                    .show()
            }
            .setNegativeButton("Cancel", null)
            .show()
    }

    private fun swapGen3PartyPokemon(
        file: File,
        reviewed: ByteArray,
        reviewedSourceUri: Uri?,
        reviewedSourceLabel: String?,
        sourceSlot: Int,
        targetSlot: Int,
        p: PokemonEntry
    ) {
        var writeStarted = false
        try {
            require(importedFile?.absolutePath == file.absolutePath &&
                currentSourceUri == reviewedSourceUri &&
                currentSourceLabel == reviewedSourceLabel) {
                "The loaded save identity changed after review."
            }
            val fresh = file.readBytes()
            require(fresh.contentEquals(reviewed)) {
                "The save changed after review. Reopen the Pokémon and try again."
            }
            require(gen3SaveValid(fresh)) {
                "The fresh save is no longer a valid Generation 3 save."
            }
            val game = detectGen3GameFromData(fresh, reviewedSourceLabel ?: file.name)
            val partyOffset = gen3PartyOffset(fresh, game)
                ?: error("The Gen 3 party block could not be located.")
            val partyCount = readU32LE(fresh, partyOffset - 4).toInt()
            require(partyCount in 2..6 &&
                sourceSlot in 0 until partyCount &&
                targetSlot in 0 until partyCount &&
                sourceSlot != targetSlot) {
                "The selected party positions are no longer active and distinct."
            }
            val source = parsePk3(fresh, partyOffset + sourceSlot * 100, true)
                ?: error("The source party Pokémon is no longer present.")
            val target = parsePk3(fresh, partyOffset + targetSlot * 100, true)
                ?: error("The target party Pokémon is no longer present.")
            require(source.pid == p.pid && source.species == p.species &&
                source.checksumValid && target.checksumValid) {
                "A selected party Pokémon changed or failed its PK3 checksum."
            }

            val partyRecords = fresh.copyOfRange(partyOffset, partyOffset + 600)
            val sourceRecord = partyRecords.copyOfRange(
                sourceSlot * 100,
                sourceSlot * 100 + 100
            )
            val targetRecord = partyRecords.copyOfRange(
                targetSlot * 100,
                targetSlot * 100 + 100
            )
            val result = Gen3PartyEditing.swapPartyPokemon(
                partyRecords,
                partyCount,
                sourceSlot,
                targetSlot
            )
            require(result.sourceSlot == sourceSlot &&
                result.targetSlot == targetSlot &&
                result.partyRecords.copyOfRange(
                    sourceSlot * 100,
                    sourceSlot * 100 + 100
                ).contentEquals(targetRecord) &&
                result.partyRecords.copyOfRange(
                    targetSlot * 100,
                    targetSlot * 100 + 100
                ).contentEquals(sourceRecord)) {
                "The staged swap did not preserve both exact party records."
            }
            require(result.partyRecords.indices.all {
                it in sourceSlot * 100 until (sourceSlot + 1) * 100 ||
                    it in targetSlot * 100 until (targetSlot + 1) * 100 ||
                    result.partyRecords[it] == partyRecords[it]
            }) {
                "The staged swap changed another party record."
            }
            val sourceAfter = parsePk3(result.partyRecords, targetSlot * 100, true)
                ?: error("The staged source Pokémon could not be reopened.")
            val targetAfter = parsePk3(result.partyRecords, sourceSlot * 100, true)
                ?: error("The staged target Pokémon could not be reopened.")
            require(sourceAfter.checksumValid && targetAfter.checksumValid &&
                sourceAfter.pid == source.pid && sourceAfter.species == source.species &&
                targetAfter.pid == target.pid && targetAfter.species == target.species) {
                "The staged records failed PK3 identity verification."
            }

            val sectionMap = gen3ActiveSectionMap(fresh)
                ?: error("PSE could not map the active Gen 3 save sections.")
            val section1 = sectionMap[1]
            require(section1 >= 0) { "The active party section is missing." }
            val work = fresh.copyOf()
            result.partyRecords.copyInto(work, partyOffset)
            updateGen3SectionChecksumAt(work, section1, 1)
            require(readU32LE(work, partyOffset - 4).toInt() == partyCount) {
                "The staged swap changed the party count."
            }
            require(gen3SaveValid(work)) {
                "The staged save failed Gen 3 section-checksum verification."
            }
            val allowed = HashSet<Int>()
            for (index in partyOffset + sourceSlot * 100 until
                partyOffset + (sourceSlot + 1) * 100) {
                allowed.add(index)
            }
            for (index in partyOffset + targetSlot * 100 until
                partyOffset + (targetSlot + 1) * 100) {
                allowed.add(index)
            }
            allowed.add(section1 + 0xFF6)
            allowed.add(section1 + 0xFF7)
            require(work.indices.all { it in allowed || work[it] == fresh[it] }) {
                "The swap changed data outside the two party records and checksum."
            }

            val backup = File.createTempFile(
                backupGameName(file) + "_PreGen3PartySwap_",
                ".backup",
                backupsDir()
            )
            backup.writeBytes(fresh)
            require(backup.readBytes().contentEquals(fresh)) {
                "The recovery backup did not verify."
            }
            retainGen2ToGen3SafetyBackup(backup, fresh)
            require(importedFile?.absolutePath == file.absolutePath &&
                currentSourceUri == reviewedSourceUri &&
                currentSourceLabel == reviewedSourceLabel &&
                file.readBytes().contentEquals(fresh)) {
                "The active save changed before writing. Nothing was changed."
            }

            writeStarted = true
            file.writeBytes(work)
            val persisted = file.readBytes()
            require(persisted.contentEquals(work) && gen3SaveValid(persisted)) {
                "The persisted Gen 3 save failed byte or checksum verification."
            }
            val reopenedOffset = gen3PartyOffset(persisted, game)
                ?: error("The persisted party block could not be reopened.")
            require(readU32LE(persisted, reopenedOffset - 4).toInt() == partyCount &&
                persisted.copyOfRange(
                    reopenedOffset + sourceSlot * 100,
                    reopenedOffset + (sourceSlot + 1) * 100
                ).contentEquals(targetRecord) &&
                persisted.copyOfRange(
                    reopenedOffset + targetSlot * 100,
                    reopenedOffset + (targetSlot + 1) * 100
                ).contentEquals(sourceRecord)) {
                "The exact swapped party records did not persist."
            }
            val reopenedSource = parsePk3(
                persisted,
                reopenedOffset + targetSlot * 100,
                true
            ) ?: error("The source Pokémon was missing after reopen.")
            val reopenedTarget = parsePk3(
                persisted,
                reopenedOffset + sourceSlot * 100,
                true
            ) ?: error("The target Pokémon was missing after reopen.")
            require(reopenedSource.checksumValid && reopenedTarget.checksumValid &&
                reopenedSource.pid == source.pid &&
                reopenedSource.species == source.species &&
                reopenedTarget.pid == target.pid &&
                reopenedTarget.species == target.species) {
                "A swapped party record failed verification after reopen."
            }
            Toast.makeText(
                this,
                "Swapped Party Slots " + (sourceSlot + 1) + " and " +
                    (targetSlot + 1) + " and verified",
                Toast.LENGTH_LONG
            ).show()
            showGen3PokemonViewer("party")
        } catch (error: Exception) {
            val restored = if (writeStarted) {
                runCatching {
                    file.writeBytes(reviewed)
                    file.readBytes().contentEquals(reviewed)
                }.getOrDefault(false)
            } else {
                false
            }
            val recovery = when {
                !writeStarted -> "Nothing was written."
                restored -> "The reviewed save was restored and verified."
                else -> "Automatic restore could not be verified. Restore the retained backup before editing this save again."
            }
            showDialog(
                "Gen 3 party position swap failed",
                (error.message ?: "Unknown error") + "\n\n" + recovery
            )
        }
    }

    private fun confirmGen3PartyDuplicate(
        location: String,
        p: PokemonEntry
    ) {
        val file = importedFile ?: return
        val sourceSlot = partyLocationToSlot(location) ?: run {
            showDialog("Duplicate Party Pokémon", "This action is available for Gen 3 party Pokémon only.")
            return
        }
        val reviewedSourceUri = currentSourceUri
        val reviewedSourceLabel = currentSourceLabel
        val reviewed = runCatching { file.readBytes() }.getOrNull() ?: run {
            showDialog("Duplicate Party Pokémon", "Could not read the working copy.")
            return
        }
        if (!gen3SaveValid(reviewed)) {
            showDialog(
                "Duplicate Party Pokémon",
                "The Gen 3 save failed section/checksum validation."
            )
            return
        }
        val game = detectGen3GameFromData(reviewed, reviewedSourceLabel ?: file.name)
        val partyOffset = gen3PartyOffset(reviewed, game) ?: run {
            showDialog("Duplicate Party Pokémon", "The Gen 3 party block could not be located.")
            return
        }
        val partyCount = readU32LE(reviewed, partyOffset - 4).toInt()
        val source = parsePk3(reviewed, partyOffset + sourceSlot * 100, true)
        if (partyCount !in 1..5 || sourceSlot !in 0 until partyCount ||
            source == null || source.pid != p.pid || source.species != p.species ||
            !source.checksumValid) {
            showDialog(
                "Duplicate blocked",
                if (partyCount >= 6) {
                    "The Gen 3 party is full."
                } else {
                    "The party changed or the selected Pokémon failed its PK3 checksum."
                }
            )
            return
        }
        val targetOffset = partyOffset + partyCount * 100
        if (!reviewed.copyOfRange(targetOffset, targetOffset + 100)
                .all { it == 0.toByte() }) {
            showDialog(
                "Duplicate blocked",
                "The next inactive party record is not exactly empty. Nothing was changed."
            )
            return
        }
        val name = p.nickname.ifBlank {
            canonicalGen3SpeciesName(p.species) ?: "Species #${p.species}"
        }
        AlertDialog.Builder(this)
            .setTitle("Duplicate $name in Party?")
            .setMessage(
                "PSE will copy the complete 100-byte Party Slot ${sourceSlot + 1} record into " +
                    "Party Slot ${partyCount + 1}, create a verified recovery backup, update " +
                    "party count/checksum, reopen both records, and roll back on any mismatch."
            )
            .setNegativeButton("Cancel", null)
            .setPositiveButton("Duplicate") { _, _ ->
                duplicateGen3PartyPokemon(
                    file,
                    reviewed,
                    reviewedSourceUri,
                    reviewedSourceLabel,
                    sourceSlot,
                    p
                )
            }
            .show()
    }

    private fun duplicateGen3PartyPokemon(
        file: File,
        reviewed: ByteArray,
        reviewedSourceUri: Uri?,
        reviewedSourceLabel: String?,
        sourceSlot: Int,
        p: PokemonEntry
    ) {
        var writeStarted = false
        try {
            require(importedFile?.absolutePath == file.absolutePath &&
                currentSourceUri == reviewedSourceUri &&
                currentSourceLabel == reviewedSourceLabel) {
                "The loaded save identity changed after review."
            }
            val fresh = file.readBytes()
            require(fresh.contentEquals(reviewed)) {
                "The save changed after review. Reopen the Pokémon and try again."
            }
            require(gen3SaveValid(fresh)) {
                "The fresh save is no longer a valid Generation 3 save."
            }
            val game = detectGen3GameFromData(fresh, reviewedSourceLabel ?: file.name)
            val partyOffset = gen3PartyOffset(fresh, game)
                ?: error("The Gen 3 party block could not be located.")
            val partyCount = readU32LE(fresh, partyOffset - 4).toInt()
            require(partyCount in 1..5 && sourceSlot in 0 until partyCount) {
                "The party is full or the selected slot is no longer active."
            }
            val source = parsePk3(fresh, partyOffset + sourceSlot * 100, true)
                ?: error("The source party Pokémon is no longer present.")
            require(source.pid == p.pid && source.species == p.species &&
                source.checksumValid) {
                "The source party Pokémon changed or failed its PK3 checksum."
            }
            val partyRecords = fresh.copyOfRange(partyOffset, partyOffset + 600)
            val result = Gen3PartyEditing.duplicatePartyPokemon(
                partyRecords,
                partyCount,
                sourceSlot
            )
            val targetSlot = result.duplicatedSlot
            val sourceRecord = partyRecords.copyOfRange(
                sourceSlot * 100,
                sourceSlot * 100 + 100
            )
            require(result.partyCount == partyCount + 1 &&
                targetSlot == partyCount &&
                result.partyRecords.copyOfRange(
                    targetSlot * 100,
                    targetSlot * 100 + 100
                ).contentEquals(sourceRecord)) {
                "The staged party duplicate did not preserve the exact source record."
            }
            require(result.partyRecords.indices.all {
                it in targetSlot * 100 until (targetSlot + 1) * 100 ||
                    result.partyRecords[it] == partyRecords[it]
            }) {
                "The staged duplicate changed another party record."
            }
            val duplicated = parsePk3(result.partyRecords, targetSlot * 100, true)
                ?: error("The staged duplicate could not be parsed.")
            require(duplicated.checksumValid && duplicated.pid == source.pid &&
                duplicated.species == source.species &&
                duplicated.nickname == source.nickname &&
                duplicated.tid == source.tid && duplicated.sid == source.sid &&
                duplicated.experience == source.experience &&
                duplicated.level == source.level &&
                duplicated.moves.contentEquals(source.moves) &&
                duplicated.ivs.contentEquals(source.ivs) &&
                duplicated.evs.contentEquals(source.evs)) {
                "The staged duplicate failed PK3 or party-field verification."
            }

            val sectionMap = gen3ActiveSectionMap(fresh)
                ?: error("PSE could not map the active Gen 3 save sections.")
            val section1 = sectionMap[1]
            require(section1 >= 0) { "The active party section is missing." }
            val work = fresh.copyOf()
            result.partyRecords.copyInto(work, partyOffset)
            writeU32LE(work, partyOffset - 4, result.partyCount.toLong())
            updateGen3SectionChecksumAt(work, section1, 1)
            require(gen3SaveValid(work)) {
                "The staged save failed Gen 3 section-checksum verification."
            }
            val targetRange = partyOffset + targetSlot * 100 until
                partyOffset + (targetSlot + 1) * 100
            val allowed = HashSet<Int>()
            for (index in partyOffset - 4 until partyOffset) allowed.add(index)
            for (index in targetRange) allowed.add(index)
            allowed.add(section1 + 0xFF6)
            allowed.add(section1 + 0xFF7)
            require(work.indices.all { it in allowed || work[it] == fresh[it] }) {
                "The duplicate changed data outside party count, the new record, and checksum."
            }

            val backup = File.createTempFile(
                backupGameName(file) + "_PreGen3PartyDuplicate_",
                ".backup",
                backupsDir()
            )
            backup.writeBytes(fresh)
            require(backup.readBytes().contentEquals(fresh)) {
                "The recovery backup did not verify."
            }
            retainGen2ToGen3SafetyBackup(backup, fresh)
            require(importedFile?.absolutePath == file.absolutePath &&
                currentSourceUri == reviewedSourceUri &&
                currentSourceLabel == reviewedSourceLabel &&
                file.readBytes().contentEquals(fresh)) {
                "The active save changed before writing. Nothing was changed."
            }

            writeStarted = true
            file.writeBytes(work)
            val persisted = file.readBytes()
            require(persisted.contentEquals(work) && gen3SaveValid(persisted)) {
                "The persisted Gen 3 save failed byte or checksum verification."
            }
            val reopenedOffset = gen3PartyOffset(persisted, game)
                ?: error("The persisted party block could not be reopened.")
            require(readU32LE(persisted, reopenedOffset - 4).toInt() ==
                result.partyCount &&
                persisted.copyOfRange(
                    reopenedOffset + targetSlot * 100,
                    reopenedOffset + (targetSlot + 1) * 100
                ).contentEquals(sourceRecord)) {
                "The exact duplicated party record did not persist."
            }
            val reopened = parsePk3(persisted, reopenedOffset + targetSlot * 100, true)
                ?: error("The duplicated party member was missing after reopen.")
            require(reopened.checksumValid && reopened.pid == source.pid &&
                reopened.species == source.species && reopened.level == source.level) {
                "The duplicated party member failed verification after reopen."
            }
            Toast.makeText(
                this,
                "Duplicated into Party Slot ${targetSlot + 1} and verified",
                Toast.LENGTH_LONG
            ).show()
            showGen3PokemonViewer("party")
        } catch (error: Exception) {
            val restored = if (writeStarted) {
                runCatching {
                    file.writeBytes(reviewed)
                    file.readBytes().contentEquals(reviewed)
                }.getOrDefault(false)
            } else {
                false
            }
            val recovery = when {
                !writeStarted -> "Nothing was written."
                restored -> "The reviewed save was restored and verified."
                else -> "Automatic restore could not be verified. Restore the retained backup before editing this save again."
            }
            showDialog(
                "Gen 3 party duplication failed",
                (error.message ?: "Unknown error") + "\n\n" + recovery
            )
        }
    }


    private enum class Gen3PartyBatchAction {
        DELETE,
        MOVE_TO_BANK,
        COPY_TO_BANK
    }

    private fun gen3PartyBatchBankCount(): Int {
        val files = bankDir().listFiles()
            ?: error("The PSE Bank inventory could not be read.")
        return files.count { it.isFile && it.extension.equals("pk3", true) }
    }

    private fun showGen3PartyBatchDeleteSelection(
        file: File,
        opened: ByteArray,
        sourceUri: Uri?,
        sourceLabel: String?,
        action: Gen3PartyBatchAction = Gen3PartyBatchAction.DELETE
    ) {
        val toBank = action != Gen3PartyBatchAction.DELETE
        val keepParty = action == Gen3PartyBatchAction.COPY_TO_BANK
        try {
            require(importedFile?.absolutePath == file.absolutePath &&
                currentSourceUri == sourceUri && currentSourceLabel == sourceLabel &&
                file.readBytes().contentEquals(opened) && gen3SaveValid(opened)) {
                "The save or its identity changed. Reopen the party before selecting."
            }
            val game = detectGen3GameFromData(opened, sourceLabel ?: file.name)
            val offset = gen3PartyOffset(opened, game)
                ?: error("The Gen 3 party block could not be located.")
            val count = readU32LE(opened, offset - 4).toInt()
            val members = gen3PartyBatchMoveMembers(opened, offset, count)
            require(keepParty || count >= 2) { "PSE will not remove the final party Pokémon." }
            val selected = linkedSetOf<Int>()
            AlertDialog.Builder(this)
                .setTitle(
                    if (keepParty) "Select party Pokémon to copy to PSE Bank"
                    else if (toBank) "Select party Pokémon for PSE Bank"
                    else "Select party Pokémon to delete"
                )
                .setMultiChoiceItems(
                    members.mapIndexed { slot, pokemon ->
                        val name = pokemon.nickname.ifBlank {
                            canonicalGen3SpeciesName(pokemon.species) ?: "Species #${pokemon.species}"
                        }
                        "Slot ${slot + 1} • ${name}" + if (pokemon.isEgg) " • Egg" else ""
                    }.toTypedArray(),
                    BooleanArray(count)
                ) { _, slot, checked ->
                    if (checked) selected.add(slot) else selected.remove(slot)
                }
                .setNegativeButton("Cancel", null)
                .setPositiveButton(
                    if (keepParty) "Review Bank copy" else if (toBank) "Review Bank move" else "Review deletion"
                ) { _, _ ->
                    reviewGen3PartyBatchDelete(
                        file, opened, sourceUri, sourceLabel, selected.toList().sorted(), action
                    )
                }
                .show()
        } catch (error: Exception) {
            showDialog(if (keepParty) "Party Bank copy stopped" else if (toBank) "Party Bank move stopped" else "Party deletion stopped", error.message ?: "The party could not be selected.")
        }
    }

    private fun reviewGen3PartyBatchDelete(
        file: File,
        opened: ByteArray,
        sourceUri: Uri?,
        sourceLabel: String?,
        slots: List<Int>,
        action: Gen3PartyBatchAction = Gen3PartyBatchAction.DELETE
    ) {
        val toBank = action != Gen3PartyBatchAction.DELETE
        val keepParty = action == Gen3PartyBatchAction.COPY_TO_BANK
        try {
            require(importedFile?.absolutePath == file.absolutePath &&
                currentSourceUri == sourceUri && currentSourceLabel == sourceLabel &&
                file.readBytes().contentEquals(opened) && gen3SaveValid(opened)) {
                "The save or its identity changed while selecting. Reopen the party."
            }
            val game = detectGen3GameFromData(opened, sourceLabel ?: file.name)
            val offset = gen3PartyOffset(opened, game)
                ?: error("The Gen 3 party block could not be located.")
            val count = readU32LE(opened, offset - 4).toInt()
            val members = gen3PartyBatchMoveMembers(opened, offset, count)
            val party = opened.copyOfRange(offset, offset + 600)
            val result = if (keepParty) {
                Gen3PartyEditing.copySelectedPartyRecords(party, count, slots)
                Gen3PartyRemovalResult(party.copyOf(), count)
            } else {
                Gen3PartyEditing.removePartyPokemonBatch(party, count, slots)
            }
            val remaining = (0 until count).filter { keepParty || it !in slots }
            require(keepParty || remaining.any { !members[it].isEgg }) {
                "Keep at least one non-Egg Pokémon in the party."
            }
            val names = slots.joinToString("\n") { slot ->
                val pokemon = members[slot]
                val name = pokemon.nickname.ifBlank {
                    canonicalGen3SpeciesName(pokemon.species) ?: "Species #${pokemon.species}"
                }
                "Slot ${slot + 1} • ${name}" + if (pokemon.isEgg) " • Egg" else ""
            }
            if (toBank) {
                require(gen3PartyBatchBankCount() <= GEN1_BANK_CAPACITY - slots.size) {
                    "The Gen 3 PSE Bank does not have room for the whole selection."
                }
            }
            val actionLabel = when (action) {
                Gen3PartyBatchAction.COPY_TO_BANK -> "Copy to PSE Bank"
                Gen3PartyBatchAction.MOVE_TO_BANK -> "Move to PSE Bank"
                Gen3PartyBatchAction.DELETE -> "Delete"
            }
            val destination = if (keepParty) {
                "PSE will copy each exact PK3 into a verified Gen 3 Bank entry. " +
                    "The source save, party count, and full party records will stay unchanged. "
            } else if (toBank) {
                "PSE will move each exact PK3 into a verified Gen 3 Bank entry. "
            } else {
                "This removes the selected Pokémon from the working save. They will not be moved to PSE Bank. "
            }
            AlertDialog.Builder(this)
                .setTitle("${actionLabel}: ${slots.size} party Pokémon?")
                .setMessage(
                    names + "\n\n" + destination +
                        if (keepParty) {
                            "PSE will verify staged and finalized Bank files and recheck the " +
                                "unchanged source. If any check fails, only new Bank files will be removed."
                        } else {
                            "${result.partyCount} Pokémon will remain, with every full party " +
                                "record preserved in order. PSE will retain a verified recovery " +
                                "backup, rebuild the party checksum, reopen the save, and roll " +
                                "back the whole batch if verification fails."
                        }
                )
                .setNegativeButton("Cancel", null)
                .setPositiveButton("${actionLabel} (${slots.size})") { _, _ ->
                    deleteGen3PartyBatch(file, opened, sourceUri, sourceLabel, slots, action)
                }
                .show()
        } catch (error: Exception) {
            showDialog(if (keepParty) "Party Bank copy stopped" else if (toBank) "Party Bank move stopped" else "Party deletion stopped", error.message ?: "The deletion could not be reviewed.")
        }
    }

    private fun deleteGen3PartyBatch(
        file: File,
        reviewed: ByteArray,
        sourceUri: Uri?,
        sourceLabel: String?,
        slots: List<Int>,
        action: Gen3PartyBatchAction = Gen3PartyBatchAction.DELETE
    ) {
        val toBank = action != Gen3PartyBatchAction.DELETE
        val keepParty = action == Gen3PartyBatchAction.COPY_TO_BANK
        val temporaryBankFiles = ArrayList<File>()
        val finalBankFiles = ArrayList<File>()
        var writeStarted = false
        try {
            require(importedFile?.absolutePath == file.absolutePath &&
                currentSourceUri == sourceUri && currentSourceLabel == sourceLabel) {
                "The loaded save identity changed after review."
            }
            val fresh = file.readBytes()
            require(fresh.contentEquals(reviewed) && gen3SaveValid(fresh)) {
                "The save changed or failed validation after review."
            }
            val game = detectGen3GameFromData(fresh, sourceLabel ?: file.name)
            val offset = gen3PartyOffset(fresh, game)
                ?: error("The Gen 3 party block could not be located.")
            val count = readU32LE(fresh, offset - 4).toInt()
            val members = gen3PartyBatchMoveMembers(fresh, offset, count)
            val party = fresh.copyOfRange(offset, offset + 600)
            val orderedSlots = slots.sorted()
            val bankRecords = if (toBank) {
                Gen3PartyEditing.copySelectedPartyRecords(party, count, orderedSlots)
            } else emptyList()
            val result = if (keepParty) {
                Gen3PartyRemovalResult(party.copyOf(), count)
            } else {
                Gen3PartyEditing.removePartyPokemonBatch(party, count, slots)
            }
            val remaining = (0 until count).filter { keepParty || it !in slots }
            require(result.partyCount == remaining.size &&
                (keepParty || remaining.any { !members[it].isEgg })) {
                "The remaining party must contain at least one valid non-Egg Pokémon."
            }
            remaining.forEachIndexed { target, source ->
                require(result.partyRecords.copyOfRange(target * 100, (target + 1) * 100)
                    .contentEquals(party.copyOfRange(source * 100, (source + 1) * 100))) {
                    "The staged deletion changed a remaining party record."
                }
            }
            require(result.partyRecords.copyOfRange(result.partyCount * 100, count * 100)
                .all { it == 0.toByte() } &&
                result.partyRecords.copyOfRange(count * 100, 600)
                    .contentEquals(party.copyOfRange(count * 100, 600))) {
                "The staged deletion did not clear vacated records or preserve inactive storage."
            }
            val sectionMap = gen3ActiveSectionMap(fresh)
                ?: error("The active Gen 3 save sections could not be mapped.")
            val section1 = sectionMap[1]
            require(section1 >= 0) { "The active party section is missing." }
            val work = fresh.copyOf()
            if (!keepParty) {
                result.partyRecords.copyInto(work, offset)
                writeU32LE(work, offset - 4, result.partyCount.toLong())
                updateGen3SectionChecksumAt(work, section1, 1)
            }
            val firstSelected = slots.minOrNull()
                ?: error("At least one party slot must be selected.")
            val allowed = HashSet<Int>()
            if (!keepParty) {
                for (index in offset - 4 until offset) allowed.add(index)
                for (index in offset + firstSelected * 100 until offset + count * 100) {
                    allowed.add(index)
                }
                allowed.add(section1 + 0xFF6)
                allowed.add(section1 + 0xFF7)
            }
            require(gen3SaveValid(work) &&
                gen3ActiveSectionMap(work)?.contentEquals(sectionMap) == true &&
                readU32LE(work, offset - 4).toInt() == result.partyCount &&
                work.indices.all { it in allowed || work[it] == fresh[it] }) {
                "The staged deletion failed checksum, active-section, or unrelated-byte verification."
            }

            val backupSuffix = when (action) {
                Gen3PartyBatchAction.COPY_TO_BANK -> "_PreGen3PartyBankCopy_"
                Gen3PartyBatchAction.MOVE_TO_BANK -> "_PreGen3PartyBankBatch_"
                Gen3PartyBatchAction.DELETE -> "_PreGen3PartyBatchDelete_"
            }
            val backup = File.createTempFile(
                backupGameName(file) + backupSuffix, ".backup", backupsDir()
            )
            backup.writeBytes(fresh)
            require(backup.readBytes().contentEquals(fresh)) { "The recovery backup did not verify." }
            retainGen2ToGen3SafetyBackup(backup, fresh)
            require(importedFile?.absolutePath == file.absolutePath &&
                currentSourceUri == sourceUri && currentSourceLabel == sourceLabel &&
                file.readBytes().contentEquals(fresh)) {
                "The active save changed before writing. Nothing was changed."
            }
            val stamp = System.currentTimeMillis()
            if (toBank) {
                require(gen3PartyBatchBankCount() <= GEN1_BANK_CAPACITY - bankRecords.size) {
                    "The Gen 3 PSE Bank filled before staging."
                }
                bankRecords.forEachIndexed { index, raw ->
                    val staged = File.createTempFile(
                        "PSE_G3_PARTY_${stamp}_${index}_", ".tmp", bankDir()
                    )
                    temporaryBankFiles.add(staged)
                    staged.writeBytes(raw)
                    val verifyRaw = staged.readBytes()
                    val pokemon = if (verifyRaw.size == 80) parsePk3(verifyRaw, 0, false) else null
                    val source = members[orderedSlots[index]]
                    require(verifyRaw.contentEquals(raw) && pokemon != null &&
                        pokemon.checksumValid && pokemon.pid == source.pid &&
                        pokemon.species == source.species && pokemon.isEgg == source.isEgg) {
                        "A staged party-to-Bank PK3 failed exact-byte or identity verification."
                    }
                }
                require(gen3PartyBatchBankCount() <= GEN1_BANK_CAPACITY - bankRecords.size &&
                    importedFile?.absolutePath == file.absolutePath &&
                    currentSourceUri == sourceUri && currentSourceLabel == sourceLabel &&
                    file.readBytes().contentEquals(fresh)) {
                    "The Bank inventory or source save changed before writing."
                }
            }
            if (!keepParty) {
                writeStarted = true
                file.writeBytes(work)
            }
            val persisted = file.readBytes()
            require(persisted.contentEquals(work) && gen3SaveValid(persisted)) {
                "The persisted party deletion failed byte or checksum verification."
            }
            val reopenedOffset = gen3PartyOffset(persisted, game)
                ?: error("The remaining party could not be reopened.")
            require(readU32LE(persisted, reopenedOffset - 4).toInt() == result.partyCount &&
                persisted.copyOfRange(reopenedOffset, reopenedOffset + 600)
                    .contentEquals(result.partyRecords)) {
                "The remaining party did not persist exactly."
            }
            remaining.forEachIndexed { slot, source ->
                val pokemon = parsePk3(persisted, reopenedOffset + slot * 100, true)
                require(pokemon != null && pokemon.checksumValid &&
                    pokemon.pid == members[source].pid &&
                    pokemon.species == members[source].species &&
                    pokemon.isEgg == members[source].isEgg) {
                    "A remaining party Pokémon failed identity or checksum verification after reopen."
                }
            }
            if (toBank) {
                require(gen3PartyBatchBankCount() <= GEN1_BANK_CAPACITY - bankRecords.size) {
                    "The Gen 3 PSE Bank filled before finalization."
                }
                temporaryBankFiles.forEachIndexed { index, staged ->
                    val source = members[orderedSlots[index]]
                    val unique = staged.nameWithoutExtension.substringAfterLast('_')
                    val target = File(
                        bankDir(), "${stamp}_party_${index}_${source.species}_${unique}.pk3"
                    )
                    // Reserve ownership before tracking a target so cleanup never deletes
                    // a pre-existing Bank entry if a filename collision occurs.
                    require(target.createNewFile()) { "A new Bank filename could not be reserved." }
                    finalBankFiles.add(target)
                    require(staged.renameTo(target)) { "A staged Bank entry could not be finalized." }
                    val verifyRaw = target.readBytes()
                    val pokemon = if (verifyRaw.size == 80) parsePk3(verifyRaw, 0, false) else null
                    require(verifyRaw.contentEquals(bankRecords[index]) && pokemon != null &&
                        pokemon.checksumValid && pokemon.pid == source.pid &&
                        pokemon.species == source.species && pokemon.isEgg == source.isEgg) {
                        "A finalized party-to-Bank entry failed exact-byte or identity verification."
                    }
                }
                require(finalBankFiles.size == bankRecords.size &&
                    finalBankFiles.indices.all { index ->
                        finalBankFiles[index].readBytes().contentEquals(bankRecords[index])
                    } && gen3PartyBatchBankCount() <= GEN1_BANK_CAPACITY &&
                    file.readBytes().contentEquals(work)) {
                    "The finalized Bank batch or source party did not verify exactly."
                }
            }
            resetGen3BoxSelection()
            Toast.makeText(
                this,
                if (keepParty) "Copied ${slots.size} party Pokémon to PSE Bank; source unchanged"
                else if (toBank) "Moved ${slots.size} party Pokémon to PSE Bank and verified"
                else "Deleted ${slots.size} party Pokémon and verified",
                Toast.LENGTH_LONG
            ).show()
            if (toBank) {
                bankMultiSelectMode = false
                selectedBankFiles.clear()
                bankViewGeneration = 3
                bankViewBox = (gen3PartyBatchBankCount() - 1).coerceAtLeast(0) / 30
                showBank()
            } else {
                showGen3PokemonViewer("party")
            }
        } catch (error: Exception) {
            val restored = if (writeStarted) {
                runCatching {
                    file.writeBytes(reviewed)
                    file.readBytes().contentEquals(reviewed)
                }.getOrDefault(false)
            } else false
            var bankClean = true
            if (toBank && (!writeStarted || restored)) {
                (temporaryBankFiles + finalBankFiles).distinctBy { it.absolutePath }
                    .forEach { candidate ->
                        if (candidate.exists() && !runCatching {
                                candidate.delete() && !candidate.exists()
                            }.getOrDefault(false)) {
                            bankClean = false
                        }
                    }
            } else if (toBank) {
                // Retain staged/finalized records when source restoration is uncertain.
                bankClean = false
            }
            val recovery = when {
                !writeStarted && bankClean -> "No save changes or new Bank entries were kept."
                !writeStarted -> "The save was not written, but some staged Bank files need manual review."
                restored && bankClean -> "The reviewed save was restored and verified; no new Bank entries were kept."
                restored -> "The reviewed save was restored, but some new Bank files could not be removed. Review PSE Bank before editing again."
                toBank -> "Source rollback could not be verified. Staged and finalized Bank files were retained for recovery. Restore the retained save backup and review PSE Bank before editing again."
                else -> "Automatic rollback could not be verified. Restore the retained recovery backup before editing again."
            }
            showDialog(
                if (keepParty) "Gen 3 party batch Bank copy failed"
                else if (toBank) "Gen 3 party batch Bank move failed"
                else "Gen 3 party batch deletion failed",
                (error.message ?: "Unknown error") + "\n\n" + recovery
            )
        }
    }

    private fun confirmGen3PartyDelete(
        location: String,
        p: PokemonEntry
    ) {
        val file = importedFile ?: return
        val sourceSlot = partyLocationToSlot(location) ?: run {
            showDialog("Remove from Party", "This action is available for Gen 3 party Pokémon only.")
            return
        }
        val reviewedSourceUri = currentSourceUri
        val reviewedSourceLabel = currentSourceLabel
        val reviewed = runCatching { file.readBytes() }.getOrNull() ?: run {
            showDialog("Remove from Party", "Could not read the working copy.")
            return
        }
        if (!gen3SaveValid(reviewed)) {
            showDialog("Remove from Party", "The Gen 3 save failed section/checksum validation.")
            return
        }
        val game = detectGen3GameFromData(reviewed, reviewedSourceLabel ?: file.name)
        val partyOffset = gen3PartyOffset(reviewed, game) ?: run {
            showDialog("Remove from Party", "The Gen 3 party block could not be located.")
            return
        }
        val partyCount = readU32LE(reviewed, partyOffset - 4).toInt()
        val source = parsePk3(reviewed, partyOffset + sourceSlot * 100, true)
        if (partyCount !in 2..6 || sourceSlot !in 0 until partyCount ||
            source == null || source.pid != p.pid || source.species != p.species ||
            !source.checksumValid) {
            showDialog(
                "Remove blocked",
                if (partyCount <= 1) {
                    "PSE will not remove the final Gen 3 party Pokémon."
                } else {
                    "The party changed or the selected Pokémon failed its PK3 checksum."
                }
            )
            return
        }
        val remaining = (0 until partyCount).filter { it != sourceSlot }.map { slot ->
            parsePk3(reviewed, partyOffset + slot * 100, true)
        }
        if (remaining.any { it == null || !it.checksumValid } ||
            remaining.filterNotNull().none { !it.isEgg }) {
            showDialog(
                "Remove blocked",
                "The remaining party must contain at least one checksum-valid non-Egg Pokémon."
            )
            return
        }
        val name = p.nickname.ifBlank {
            canonicalGen3SpeciesName(p.species) ?: "Species #${p.species}"
        }
        AlertDialog.Builder(this)
            .setTitle("Remove $name from Party?")
            .setMessage(
                "This clears Party Slot ${sourceSlot + 1} from PSE's working copy and compacts " +
                    "all later 100-byte party records. PSE will create a verified recovery " +
                    "backup, update party count/checksum, reopen every remaining member, and " +
                    "roll back on any mismatch."
            )
            .setNegativeButton("Cancel", null)
            .setPositiveButton("Remove from Party") { _, _ ->
                deleteGen3PartyPokemon(
                    file,
                    reviewed,
                    reviewedSourceUri,
                    reviewedSourceLabel,
                    sourceSlot,
                    p
                )
            }
            .show()
    }

    private fun deleteGen3PartyPokemon(
        file: File,
        reviewed: ByteArray,
        reviewedSourceUri: Uri?,
        reviewedSourceLabel: String?,
        sourceSlot: Int,
        p: PokemonEntry
    ) {
        var writeStarted = false
        try {
            require(importedFile?.absolutePath == file.absolutePath &&
                currentSourceUri == reviewedSourceUri &&
                currentSourceLabel == reviewedSourceLabel) {
                "The loaded save identity changed after review."
            }
            val fresh = file.readBytes()
            require(fresh.contentEquals(reviewed)) {
                "The save changed after review. Reopen the Pokémon and try again."
            }
            require(gen3SaveValid(fresh)) {
                "The fresh save is no longer a valid Generation 3 save."
            }
            val game = detectGen3GameFromData(fresh, reviewedSourceLabel ?: file.name)
            val partyOffset = gen3PartyOffset(fresh, game)
                ?: error("The Gen 3 party block could not be located.")
            val partyCount = readU32LE(fresh, partyOffset - 4).toInt()
            require(partyCount in 2..6 && sourceSlot in 0 until partyCount) {
                "PSE will not remove the final party member or an inactive slot."
            }
            val source = parsePk3(fresh, partyOffset + sourceSlot * 100, true)
                ?: error("The source party Pokémon is no longer present.")
            require(source.pid == p.pid && source.species == p.species &&
                source.checksumValid) {
                "The source party Pokémon changed or failed its PK3 checksum."
            }
            val partyRecords = fresh.copyOfRange(partyOffset, partyOffset + 600)
            val result = Gen3PartyEditing.removePartyPokemon(
                partyRecords,
                partyCount,
                sourceSlot
            )
            require(result.partyCount == partyCount - 1) {
                "The staged party count is incorrect."
            }
            for (slot in 0 until result.partyCount) {
                val sourceRecordSlot = if (slot < sourceSlot) slot else slot + 1
                require(result.partyRecords.copyOfRange(slot * 100, slot * 100 + 100)
                    .contentEquals(
                        partyRecords.copyOfRange(
                            sourceRecordSlot * 100,
                            sourceRecordSlot * 100 + 100
                        )
                    )) {
                    "The staged compaction changed another party record."
                }
            }
            require(result.partyRecords.copyOfRange(
                result.partyCount * 100,
                partyCount * 100
            ).all { it == 0.toByte() }) {
                "The vacated party record was not cleared."
            }
            require(result.partyRecords.indices.all {
                it < partyCount * 100 || result.partyRecords[it] == partyRecords[it]
            }) {
                "The staged removal changed inactive party storage."
            }
            val remaining = (0 until result.partyCount).map { slot ->
                parsePk3(result.partyRecords, slot * 100, true)
                    ?: error("A remaining party record could not be parsed.")
            }
            require(remaining.all { it.checksumValid } && remaining.any { !it.isEgg }) {
                "The remaining party is invalid or contains only Eggs."
            }

            val sectionMap = gen3ActiveSectionMap(fresh)
                ?: error("PSE could not map the active Gen 3 save sections.")
            val section1 = sectionMap[1]
            require(section1 >= 0) { "The active party section is missing." }
            val work = fresh.copyOf()
            result.partyRecords.copyInto(work, partyOffset)
            writeU32LE(work, partyOffset - 4, result.partyCount.toLong())
            updateGen3SectionChecksumAt(work, section1, 1)
            require(gen3SaveValid(work)) {
                "The staged save failed Gen 3 section-checksum verification."
            }
            val allowed = HashSet<Int>()
            for (index in partyOffset - 4 until partyOffset) allowed.add(index)
            for (index in partyOffset + sourceSlot * 100 until
                partyOffset + partyCount * 100) allowed.add(index)
            allowed.add(section1 + 0xFF6)
            allowed.add(section1 + 0xFF7)
            require(work.indices.all { it in allowed || work[it] == fresh[it] }) {
                "The removal changed data outside the party count, compacted records, and checksum."
            }

            val backup = File.createTempFile(
                backupGameName(file) + "_PreGen3PartyDelete_",
                ".backup",
                backupsDir()
            )
            backup.writeBytes(fresh)
            require(backup.readBytes().contentEquals(fresh)) {
                "The recovery backup did not verify."
            }
            retainGen2ToGen3SafetyBackup(backup, fresh)
            require(importedFile?.absolutePath == file.absolutePath &&
                currentSourceUri == reviewedSourceUri &&
                currentSourceLabel == reviewedSourceLabel &&
                file.readBytes().contentEquals(fresh)) {
                "The active save changed before writing. Nothing was changed."
            }

            writeStarted = true
            file.writeBytes(work)
            val persisted = file.readBytes()
            require(persisted.contentEquals(work) && gen3SaveValid(persisted)) {
                "The persisted Gen 3 save failed byte or checksum verification."
            }
            val reopenedOffset = gen3PartyOffset(persisted, game)
                ?: error("The persisted party block could not be reopened.")
            require(readU32LE(persisted, reopenedOffset - 4).toInt() ==
                result.partyCount &&
                persisted.copyOfRange(reopenedOffset, reopenedOffset + 600)
                    .contentEquals(result.partyRecords)) {
                "The compacted party did not persist exactly."
            }
            val reopened = (0 until result.partyCount).map { slot ->
                parsePk3(persisted, reopenedOffset + slot * 100, true)
                    ?: error("A remaining party member was missing after reopen.")
            }
            require(reopened.all { it.checksumValid } && reopened.any { !it.isEgg }) {
                "The reopened party is invalid or contains only Eggs."
            }
            Toast.makeText(
                this,
                "Removed from Party and verified; recovery backup retained",
                Toast.LENGTH_LONG
            ).show()
            showGen3PokemonViewer("party")
        } catch (error: Exception) {
            val restored = if (writeStarted) {
                runCatching {
                    file.writeBytes(reviewed)
                    file.readBytes().contentEquals(reviewed)
                }.getOrDefault(false)
            } else {
                false
            }
            val recovery = when {
                !writeStarted -> "Nothing was written."
                restored -> "The reviewed save was restored and verified."
                else -> "Automatic restore could not be verified. Restore the retained backup before editing this save again."
            }
            showDialog(
                "Gen 3 party removal failed",
                (error.message ?: "Unknown error") + "\n\n" + recovery
            )
        }
    }

    private fun chooseGen3PartyMoveDestination(
        location: String,
        p: PokemonEntry
    ) {
        val file = importedFile ?: return
        val sourceSlot = partyLocationToSlot(location) ?: run {
            showDialog("Move to PC", "This action is available for Gen 3 party Pokémon only.")
            return
        }
        val reviewed = runCatching { file.readBytes() }.getOrNull() ?: run {
            showDialog("Move to PC", "Could not read the working copy.")
            return
        }
        if (!gen3SaveValid(reviewed)) {
            showDialog("Move to PC", "The Gen 3 save failed section/checksum validation.")
            return
        }
        val game = detectGen3GameFromData(reviewed, currentSourceLabel ?: file.name)
        val partyOffset = gen3PartyOffset(reviewed, game) ?: run {
            showDialog("Move to PC", "The Gen 3 party block could not be located.")
            return
        }
        val partyCount = readU32LE(reviewed, partyOffset - 4).toInt()
        val source = parsePk3(reviewed, partyOffset + sourceSlot * 100, true)
        if (partyCount !in 1..6 || sourceSlot !in 0 until partyCount ||
            source == null || source.pid != p.pid || source.species != p.species ||
            !source.checksumValid) {
            showDialog(
                "Move stopped",
                "The party changed or the selected Pokémon failed its PK3 checksum."
            )
            return
        }
        val pc = gen3PcBuffer(reviewed) ?: run {
            showDialog("Move to PC", "Could not reconstruct Gen 3 PC storage.")
            return
        }
        val emptyTargets = (0 until Gen3SaveState.BOX_COUNT *
            Gen3SaveState.BOX_CAPACITY).filter { global ->
            val offset = 4 + global * 80
            pc.copyOfRange(offset, offset + 80).all { it == 0.toByte() }
        }
        if (emptyTargets.isEmpty()) {
            showDialog("Move to PC", "No empty Gen 3 PC slot is available.")
            return
        }
        val boxNames = gen3PcBoxNames(pc)
        val first = emptyTargets.first()
        AlertDialog.Builder(this)
            .setTitle("Move ${p.nickname.ifBlank { "Pokémon" }} to PC…")
            .setItems(
                arrayOf(
                    "First empty • ${boxNames[first / 30]} • Slot ${first % 30 + 1}",
                    "Choose a box and slot"
                )
            ) { _, which ->
                if (which == 0) {
                    confirmGen3PartyMove(sourceSlot, p, first)
                } else {
                    showGen3PartyMoveBoxPicker(sourceSlot, p, pc, boxNames)
                }
            }
            .setNegativeButton("Cancel", null)
            .show()
    }

    private fun showGen3PartyMoveBoxPicker(
        sourceSlot: Int,
        p: PokemonEntry,
        pc: ByteArray,
        boxNames: List<String>
    ) {
        val boxes = (0 until Gen3SaveState.BOX_COUNT).filter { box ->
            Gen3BoxEditing.emptyBoxSlots(pc, box).isNotEmpty()
        }
        AlertDialog.Builder(this)
            .setTitle("Choose destination box")
            .setItems(
                boxes.map { box -> "${boxNames[box]} • Box ${box + 1}" }.toTypedArray()
            ) { _, which ->
                val box = boxes[which]
                val emptySlots = Gen3BoxEditing.emptyBoxSlots(pc, box)
                AlertDialog.Builder(this)
                    .setTitle("${boxNames[box]} • choose slot")
                    .setItems(
                        emptySlots.map { slot -> "Slot ${slot + 1}" }.toTypedArray()
                    ) { _, slotChoice ->
                        confirmGen3PartyMove(
                            sourceSlot,
                            p,
                            box * Gen3SaveState.BOX_CAPACITY + emptySlots[slotChoice]
                        )
                    }
                    .setNegativeButton("Cancel", null)
                    .show()
            }
            .setNegativeButton("Cancel", null)
            .show()
    }

    private fun confirmGen3PartyMove(
        sourceSlot: Int,
        p: PokemonEntry,
        targetGlobal: Int
    ) {
        val file = importedFile ?: return
        val reviewedSourceUri = currentSourceUri
        val reviewedSourceLabel = currentSourceLabel
        val reviewed = runCatching { file.readBytes() }.getOrNull() ?: run {
            showDialog("Move to PC", "Could not read the working copy.")
            return
        }
        if (!gen3SaveValid(reviewed)) {
            showDialog("Move to PC", "The Gen 3 save failed section/checksum validation.")
            return
        }
        val game = detectGen3GameFromData(reviewed, reviewedSourceLabel ?: file.name)
        val partyOffset = gen3PartyOffset(reviewed, game) ?: run {
            showDialog("Move to PC", "The Gen 3 party block could not be located.")
            return
        }
        val partyCount = readU32LE(reviewed, partyOffset - 4).toInt()
        val source = parsePk3(reviewed, partyOffset + sourceSlot * 100, true)
        val pc = gen3PcBuffer(reviewed)
        if (partyCount !in 1..6 || sourceSlot !in 0 until partyCount ||
            source == null || source.pid != p.pid || source.species != p.species ||
            !source.checksumValid || pc == null) {
            showDialog("Move stopped", "The reviewed party or PC storage is no longer valid.")
            return
        }
        val targetOffset = 4 + targetGlobal * 80
        if (targetGlobal !in 0 until Gen3SaveState.BOX_COUNT *
            Gen3SaveState.BOX_CAPACITY ||
            !pc.copyOfRange(targetOffset, targetOffset + 80)
                .all { it == 0.toByte() }) {
            showDialog("Move stopped", "The destination PC slot is no longer empty.")
            return
        }
        val boxNames = gen3PcBoxNames(pc)
        val name = p.nickname.ifBlank {
            canonicalGen3SpeciesName(p.species) ?: "Species #${p.species}"
        }
        AlertDialog.Builder(this)
            .setTitle("Move $name to PC?")
            .setMessage(
                "Party Slot ${sourceSlot + 1} → ${boxNames[targetGlobal / 30]} • " +
                    "Slot ${targetGlobal % 30 + 1}\n\n" +
                    "PSE will create a verified recovery backup, move the exact PK3 record, " +
                    "compact the party, update its count, repair all affected checksums, " +
                    "reopen both regions, and roll back on any mismatch."
            )
            .setNegativeButton("Cancel", null)
            .setPositiveButton("Move to PC") { _, _ ->
                moveGen3PartyPokemonToPc(
                    file,
                    reviewed,
                    reviewedSourceUri,
                    reviewedSourceLabel,
                    sourceSlot,
                    targetGlobal,
                    p
                )
            }
            .show()
    }

    private fun moveGen3PartyPokemonToPc(
        file: File,
        reviewed: ByteArray,
        reviewedSourceUri: Uri?,
        reviewedSourceLabel: String?,
        sourceSlot: Int,
        targetGlobal: Int,
        p: PokemonEntry
    ) {
        var writeStarted = false
        try {
            require(importedFile?.absolutePath == file.absolutePath &&
                currentSourceUri == reviewedSourceUri &&
                currentSourceLabel == reviewedSourceLabel) {
                "The loaded save identity changed after review."
            }
            val fresh = file.readBytes()
            require(fresh.contentEquals(reviewed)) {
                "The save changed after review. Reopen the Pokémon and try again."
            }
            require(gen3SaveValid(fresh)) {
                "The fresh save is no longer a valid Generation 3 save."
            }
            val game = detectGen3GameFromData(fresh, reviewedSourceLabel ?: file.name)
            val partyOffset = gen3PartyOffset(fresh, game)
                ?: error("The Gen 3 party block could not be located.")
            val partyCount = readU32LE(fresh, partyOffset - 4).toInt()
            require(partyCount in 1..6 && sourceSlot in 0 until partyCount) {
                "The selected party slot is no longer active."
            }
            val source = parsePk3(fresh, partyOffset + sourceSlot * 100, true)
                ?: error("The source party Pokémon is no longer present.")
            require(source.pid == p.pid && source.species == p.species &&
                source.checksumValid) {
                "The source party Pokémon changed or failed its PK3 checksum."
            }
            val freshPc = gen3PcBuffer(fresh)
                ?: error("PSE could not reconstruct the fresh Gen 3 PC storage.")
            val targetOffset = 4 + targetGlobal * 80
            require(targetGlobal in 0 until Gen3SaveState.BOX_COUNT *
                Gen3SaveState.BOX_CAPACITY &&
                freshPc.copyOfRange(targetOffset, targetOffset + 80)
                    .all { it == 0.toByte() }) {
                "The destination PC slot is no longer empty."
            }
            val partyRecords = fresh.copyOfRange(partyOffset, partyOffset + 600)
            val sourceStored = partyRecords.copyOfRange(
                sourceSlot * 100,
                sourceSlot * 100 + 80
            )
            val result = Gen3PartyEditing.movePartyPokemonToPc(
                partyRecords,
                partyCount,
                sourceSlot,
                freshPc,
                targetGlobal
            )
            require(result.partyCount == partyCount - 1 &&
                result.pc.copyOfRange(targetOffset, targetOffset + 80)
                    .contentEquals(sourceStored)) {
                "The staged party-to-PC move did not preserve the exact PK3 record."
            }
            for (slot in 0 until result.partyCount) {
                val sourceRecordSlot = if (slot < sourceSlot) slot else slot + 1
                require(result.partyRecords.copyOfRange(slot * 100, slot * 100 + 100)
                    .contentEquals(
                        partyRecords.copyOfRange(
                            sourceRecordSlot * 100,
                            sourceRecordSlot * 100 + 100
                        )
                    )) {
                    "The staged party compaction changed another party record."
                }
            }
            require(result.partyRecords.copyOfRange(
                result.partyCount * 100,
                partyCount * 100
            ).all { it == 0.toByte() }) {
                "The vacated party record was not cleared."
            }
            require(result.partyRecords.indices.all {
                it < partyCount * 100 || result.partyRecords[it] == partyRecords[it]
            }) {
                "The staged party move changed inactive party storage."
            }
            require(result.pc.indices.all {
                it in targetOffset until targetOffset + 80 ||
                    result.pc[it] == freshPc[it]
            }) {
                "The staged party move changed unrelated PC data."
            }
            val stored = parsePk3(result.pc, targetOffset, false)
                ?: error("The staged PC destination could not be parsed.")
            require(stored.checksumValid && stored.pid == source.pid &&
                stored.species == source.species && stored.nickname == source.nickname &&
                stored.tid == source.tid && stored.sid == source.sid &&
                stored.experience == source.experience &&
                stored.moves.contentEquals(source.moves) &&
                stored.ivs.contentEquals(source.ivs) &&
                stored.evs.contentEquals(source.evs)) {
                "The staged PC destination did not preserve the source PK3."
            }

            val sectionMap = gen3ActiveSectionMap(fresh)
                ?: error("PSE could not map the active Gen 3 save sections.")
            val section1 = sectionMap[1]
            require(section1 >= 0) { "The active party section is missing." }
            val work = fresh.copyOf()
            result.partyRecords.copyInto(work, partyOffset)
            writeU32LE(work, partyOffset - 4, result.partyCount.toLong())
            updateGen3SectionChecksumAt(work, section1, 1)
            writeGen3PcBuffer(work, result.pc)
            require(gen3SaveValid(work) &&
                gen3PcBuffer(work)?.contentEquals(result.pc) == true) {
                "The staged save failed checksum or PC byte verification."
            }
            val allowed = HashSet<Int>()
            for (index in partyOffset - 4 until partyOffset) allowed.add(index)
            for (index in partyOffset + sourceSlot * 100 until
                partyOffset + partyCount * 100) allowed.add(index)
            allowed.add(section1 + 0xFF6)
            allowed.add(section1 + 0xFF7)
            var pcBase = 0
            val targetRange = targetOffset until targetOffset + 80
            for (sectionId in 5..13) {
                val sectionBase = sectionMap[sectionId]
                require(sectionBase >= 0) { "Missing Gen 3 PC section $sectionId." }
                val sectionLength = gen3SectionLengths[sectionId]
                for (localOffset in 0 until sectionLength) {
                    if (pcBase + localOffset in targetRange) {
                        allowed.add(sectionBase + localOffset)
                    }
                }
                allowed.add(sectionBase + 0xFF6)
                allowed.add(sectionBase + 0xFF7)
                pcBase += sectionLength
            }
            require(work.indices.all { it in allowed || work[it] == fresh[it] }) {
                "The move changed data outside the party, destination slot, and checksums."
            }

            val backup = File.createTempFile(
                backupGameName(file) + "_PreGen3PartyToPc_",
                ".backup",
                backupsDir()
            )
            backup.writeBytes(fresh)
            require(backup.readBytes().contentEquals(fresh)) {
                "The recovery backup did not verify."
            }
            retainGen2ToGen3SafetyBackup(backup, fresh)
            require(importedFile?.absolutePath == file.absolutePath &&
                currentSourceUri == reviewedSourceUri &&
                currentSourceLabel == reviewedSourceLabel &&
                file.readBytes().contentEquals(fresh)) {
                "The active save changed before writing. Nothing was changed."
            }

            writeStarted = true
            file.writeBytes(work)
            val persisted = file.readBytes()
            require(persisted.contentEquals(work) && gen3SaveValid(persisted)) {
                "The persisted Gen 3 save failed byte or checksum verification."
            }
            val reopenedPartyOffset = gen3PartyOffset(persisted, game)
                ?: error("The persisted party block could not be reopened.")
            require(readU32LE(persisted, reopenedPartyOffset - 4).toInt() ==
                result.partyCount &&
                persisted.copyOfRange(reopenedPartyOffset, reopenedPartyOffset + 600)
                    .contentEquals(result.partyRecords)) {
                "The compacted party did not persist exactly."
            }
            val persistedPc = gen3PcBuffer(persisted)
                ?: error("The persisted PC storage could not be reopened.")
            require(persistedPc.copyOfRange(targetOffset, targetOffset + 80)
                .contentEquals(sourceStored)) {
                "The moved PK3 did not persist exactly."
            }
            val reopened = parsePk3(persistedPc, targetOffset, false)
                ?: error("The moved Pokémon was missing after reopen.")
            require(reopened.checksumValid && reopened.pid == source.pid &&
                reopened.species == source.species && reopened.nickname == source.nickname) {
                "The moved Pokémon failed verification after reopen."
            }
            Toast.makeText(
                this,
                "Moved to Box ${targetGlobal / 30 + 1} • Slot ${targetGlobal % 30 + 1} and verified",
                Toast.LENGTH_LONG
            ).show()
            showGen3PokemonViewer("boxes", targetGlobal / 30)
        } catch (error: Exception) {
            val restored = if (writeStarted) {
                runCatching {
                    file.writeBytes(reviewed)
                    file.readBytes().contentEquals(reviewed)
                }.getOrDefault(false)
            } else {
                false
            }
            val recovery = when {
                !writeStarted -> "Nothing was written."
                restored -> "The reviewed save was restored and verified."
                else -> "Automatic restore could not be verified. Restore the retained backup before editing this save again."
            }
            showDialog(
                "Gen 3 party-to-PC move failed",
                (error.message ?: "Unknown error") + "\n\n" + recovery
            )
        }
    }

    private fun chooseGen3SwapSlot(location: String, p: PokemonEntry) {
        val file = importedFile ?: return
        val sourceGlobal = boxedLocationToGlobalIndex(location) ?: run {
            showDialog("Swap Pokémon", "Gen 3 PC swapping is available for boxed Pokémon only.")
            return
        }
        val reviewed = runCatching { file.readBytes() }.getOrNull() ?: run {
            showDialog("Swap Pokémon", "Could not read the working copy.")
            return
        }
        if (!gen3SaveValid(reviewed)) {
            showDialog("Swap Pokémon", "The Gen 3 save failed section/checksum validation.")
            return
        }
        val pc = gen3PcBuffer(reviewed) ?: run {
            showDialog("Swap Pokémon", "Could not reconstruct Gen 3 PC storage.")
            return
        }
        val source = parsePk3(pc, 4 + sourceGlobal * 80, false)
        if (source == null || source.pid != p.pid || source.species != p.species ||
            !source.checksumValid) {
            showDialog(
                "Swap stopped",
                "The source Pokémon changed or failed its PK3 checksum. Reopen it and try again."
            )
            return
        }
        val boxIndex = sourceGlobal / Gen3SaveState.BOX_CAPACITY
        val targets = (0 until Gen3SaveState.BOX_CAPACITY).mapNotNull { slot ->
            val global = boxIndex * Gen3SaveState.BOX_CAPACITY + slot
            if (global == sourceGlobal) return@mapNotNull null
            val target = parsePk3(pc, 4 + global * 80, false)
            if (target == null || !target.checksumValid) null else Triple(slot, global, target)
        }
        if (targets.isEmpty()) {
            showDialog("Swap Pokémon", "This box has no other checksum-valid Pokémon.")
            return
        }
        val boxName = gen3PcBoxNames(pc)[boxIndex]
        val labels = targets.map { (slot, _, target) ->
            val name = target.nickname.ifBlank {
                canonicalGen3SpeciesName(target.species) ?: "Species #${target.species}"
            }
            "Slot ${slot + 1} • $name"
        }.toTypedArray()
        AlertDialog.Builder(this)
            .setTitle("$boxName • swap with")
            .setItems(labels) { _, which ->
                confirmGen3Swap(sourceGlobal, p, targets[which].second)
            }
            .setNegativeButton("Cancel", null)
            .show()
    }

    private fun confirmGen3Swap(
        sourceGlobal: Int,
        p: PokemonEntry,
        targetGlobal: Int
    ) {
        val file = importedFile ?: return
        val reviewedSourceUri = currentSourceUri
        val reviewedSourceLabel = currentSourceLabel
        val reviewed = runCatching { file.readBytes() }.getOrNull() ?: run {
            showDialog("Swap Pokémon", "Could not read the working copy.")
            return
        }
        if (!gen3SaveValid(reviewed)) {
            showDialog("Swap Pokémon", "The Gen 3 save failed section/checksum validation.")
            return
        }
        val pc = gen3PcBuffer(reviewed) ?: run {
            showDialog("Swap Pokémon", "Could not reconstruct Gen 3 PC storage.")
            return
        }
        val source = parsePk3(pc, 4 + sourceGlobal * 80, false)
        val target = parsePk3(pc, 4 + targetGlobal * 80, false)
        if (source == null || source.pid != p.pid || source.species != p.species ||
            !source.checksumValid) {
            showDialog("Swap stopped", "The source Pokémon changed or failed its PK3 checksum.")
            return
        }
        if (target == null || !target.checksumValid) {
            showDialog("Swap stopped", "The target Pokémon is missing or failed its PK3 checksum.")
            return
        }
        if (sourceGlobal / Gen3SaveState.BOX_CAPACITY !=
            targetGlobal / Gen3SaveState.BOX_CAPACITY) {
            showDialog("Swap stopped", "The target must be in the same PC box.")
            return
        }
        val boxName = gen3PcBoxNames(pc)[sourceGlobal / Gen3SaveState.BOX_CAPACITY]
        val sourceName = p.nickname.ifBlank {
            canonicalGen3SpeciesName(p.species) ?: "Species #${p.species}"
        }
        val targetName = target.nickname.ifBlank {
            canonicalGen3SpeciesName(target.species) ?: "Species #${target.species}"
        }
        AlertDialog.Builder(this)
            .setTitle("Swap $sourceName and $targetName?")
            .setMessage(
                "$boxName • Slots ${sourceGlobal % 30 + 1} and ${targetGlobal % 30 + 1}\n\n" +
                    "PSE will create a verified recovery backup, exchange the two exact PK3 " +
                    "records, repair PC checksums, reopen both slots, and roll back on any mismatch."
            )
            .setNegativeButton("Cancel", null)
            .setPositiveButton("Swap Pokémon") { _, _ ->
                swapGen3PokemonWithinBox(
                    file,
                    reviewed,
                    reviewedSourceUri,
                    reviewedSourceLabel,
                    sourceGlobal,
                    targetGlobal,
                    p
                )
            }
            .show()
    }

    private fun swapGen3PokemonWithinBox(
        file: File,
        reviewed: ByteArray,
        reviewedSourceUri: Uri?,
        reviewedSourceLabel: String?,
        sourceGlobal: Int,
        targetGlobal: Int,
        p: PokemonEntry
    ) {
        var writeStarted = false
        try {
            val slotCount = Gen3SaveState.BOX_COUNT * Gen3SaveState.BOX_CAPACITY
            require(sourceGlobal in 0 until slotCount &&
                targetGlobal in 0 until slotCount &&
                sourceGlobal != targetGlobal &&
                sourceGlobal / Gen3SaveState.BOX_CAPACITY ==
                    targetGlobal / Gen3SaveState.BOX_CAPACITY) {
                "The swap requires two different slots in the same PC box."
            }
            require(importedFile?.absolutePath == file.absolutePath &&
                currentSourceUri == reviewedSourceUri &&
                currentSourceLabel == reviewedSourceLabel) {
                "The loaded save identity changed after review."
            }
            val fresh = file.readBytes()
            require(fresh.contentEquals(reviewed)) {
                "The save changed after review. Reopen the Pokémon and try again."
            }
            require(gen3SaveValid(fresh)) {
                "The fresh save is no longer a valid Generation 3 save."
            }
            val freshPc = gen3PcBuffer(fresh)
                ?: error("PSE could not reconstruct the fresh Gen 3 PC storage.")
            val sourceOffset = 4 + sourceGlobal * 80
            val targetOffset = 4 + targetGlobal * 80
            val sourceRange = sourceOffset until sourceOffset + 80
            val targetRange = targetOffset until targetOffset + 80
            val source = parsePk3(freshPc, sourceOffset, false)
                ?: error("The source Pokémon is no longer present.")
            val target = parsePk3(freshPc, targetOffset, false)
                ?: error("The target Pokémon is no longer present.")
            require(source.pid == p.pid && source.species == p.species &&
                source.checksumValid && target.checksumValid) {
                "A selected Pokémon changed or failed its PK3 checksum."
            }
            val sourceRaw = freshPc.copyOfRange(sourceOffset, sourceOffset + 80)
            val targetRaw = freshPc.copyOfRange(targetOffset, targetOffset + 80)
            val editedPc = Gen3BoxEditing.swapPokemonStorage(
                freshPc,
                sourceGlobal,
                targetGlobal
            )
            require(editedPc.copyOfRange(sourceOffset, sourceOffset + 80)
                .contentEquals(targetRaw) &&
                editedPc.copyOfRange(targetOffset, targetOffset + 80)
                    .contentEquals(sourceRaw)) {
                "The staged PC swap did not preserve both exact PK3 records."
            }
            require(editedPc.indices.all {
                it in sourceRange || it in targetRange || editedPc[it] == freshPc[it]
            }) {
                "The staged swap changed unrelated PC data."
            }
            val stagedSource = parsePk3(editedPc, targetOffset, false)
                ?: error("The staged source PK3 could not be parsed.")
            val stagedTarget = parsePk3(editedPc, sourceOffset, false)
                ?: error("The staged target PK3 could not be parsed.")
            require(stagedSource.checksumValid && stagedTarget.checksumValid &&
                stagedSource.pid == source.pid && stagedSource.species == source.species &&
                stagedTarget.pid == target.pid && stagedTarget.species == target.species) {
                "A staged PK3 failed identity or checksum verification."
            }

            val sectionMap = gen3ActiveSectionMap(fresh)
                ?: error("PSE could not map the active Gen 3 PC sections.")
            val work = fresh.copyOf()
            writeGen3PcBuffer(work, editedPc)
            require(gen3SaveValid(work) &&
                gen3PcBuffer(work)?.contentEquals(editedPc) == true) {
                "The staged save failed checksum or PC byte verification."
            }
            val allowed = HashSet<Int>()
            var pcBase = 0
            for (sectionId in 5..13) {
                val sectionBase = sectionMap[sectionId]
                require(sectionBase >= 0) { "Missing Gen 3 PC section $sectionId." }
                val sectionLength = gen3SectionLengths[sectionId]
                for (localOffset in 0 until sectionLength) {
                    val pcOffset = pcBase + localOffset
                    if (pcOffset in sourceRange || pcOffset in targetRange) {
                        allowed.add(sectionBase + localOffset)
                    }
                }
                allowed.add(sectionBase + 0xFF6)
                allowed.add(sectionBase + 0xFF7)
                pcBase += sectionLength
            }
            require(work.indices.all { it in allowed || work[it] == fresh[it] }) {
                "The swap changed data outside the two selected slots and PC checksums."
            }

            val backup = File.createTempFile(
                backupGameName(file) + "_PreGen3PcSwap_",
                ".backup",
                backupsDir()
            )
            backup.writeBytes(fresh)
            require(backup.readBytes().contentEquals(fresh)) {
                "The recovery backup did not verify."
            }
            retainGen2ToGen3SafetyBackup(backup, fresh)
            require(importedFile?.absolutePath == file.absolutePath &&
                currentSourceUri == reviewedSourceUri &&
                currentSourceLabel == reviewedSourceLabel &&
                file.readBytes().contentEquals(fresh)) {
                "The active save changed before writing. Nothing was changed."
            }

            writeStarted = true
            file.writeBytes(work)
            val persisted = file.readBytes()
            require(persisted.contentEquals(work) && gen3SaveValid(persisted)) {
                "The persisted Gen 3 save failed byte or checksum verification."
            }
            val persistedPc = gen3PcBuffer(persisted)
                ?: error("The persisted Gen 3 PC storage could not be reopened.")
            require(persistedPc.copyOfRange(sourceOffset, sourceOffset + 80)
                .contentEquals(targetRaw) &&
                persistedPc.copyOfRange(targetOffset, targetOffset + 80)
                    .contentEquals(sourceRaw)) {
                "The swapped PK3 records did not persist exactly."
            }
            val reopenedSource = parsePk3(persistedPc, targetOffset, false)
                ?: error("The source Pokémon was missing after reopen.")
            val reopenedTarget = parsePk3(persistedPc, sourceOffset, false)
                ?: error("The target Pokémon was missing after reopen.")
            require(reopenedSource.checksumValid && reopenedTarget.checksumValid &&
                reopenedSource.pid == source.pid && reopenedSource.species == source.species &&
                reopenedTarget.pid == target.pid && reopenedTarget.species == target.species) {
                "A swapped Pokémon failed verification after reopen."
            }
            Toast.makeText(
                this,
                "Swapped slots ${sourceGlobal % 30 + 1} and ${targetGlobal % 30 + 1} and verified",
                Toast.LENGTH_LONG
            ).show()
            showGen3PokemonViewer("boxes", sourceGlobal / 30)
        } catch (error: Exception) {
            val restored = if (writeStarted) {
                runCatching {
                    file.writeBytes(reviewed)
                    file.readBytes().contentEquals(reviewed)
                }.getOrDefault(false)
            } else {
                false
            }
            val recovery = when {
                !writeStarted -> "Nothing was written."
                restored -> "The reviewed save was restored and verified."
                else -> "Automatic restore could not be verified. Restore the retained backup before editing this save again."
            }
            showDialog(
                "Gen 3 PC swap failed",
                (error.message ?: "Unknown error") + "\n\n" + recovery
            )
        }
    }

    private fun chooseGen3ReorderSlot(location: String, p: PokemonEntry) {
        val file = importedFile ?: return
        val sourceGlobal = boxedLocationToGlobalIndex(location) ?: run {
            showDialog("Reorder Pokémon", "Gen 3 PC reordering is available for boxed Pokémon only.")
            return
        }
        val data = runCatching { file.readBytes() }.getOrNull() ?: run {
            showDialog("Reorder Pokémon", "Could not read the working copy.")
            return
        }
        if (!gen3SaveValid(data)) {
            showDialog("Reorder Pokémon", "The Gen 3 save failed section/checksum validation.")
            return
        }
        val pc = gen3PcBuffer(data) ?: run {
            showDialog("Reorder Pokémon", "Could not reconstruct Gen 3 PC storage.")
            return
        }
        val source = parsePk3(pc, 4 + sourceGlobal * 80, false)
        if (source == null || source.pid != p.pid || source.species != p.species ||
            !source.checksumValid) {
            showDialog(
                "Reorder stopped",
                "The source Pokémon changed or failed its PK3 checksum. Reopen it and try again."
            )
            return
        }
        val boxIndex = sourceGlobal / Gen3SaveState.BOX_CAPACITY
        val emptySlots = Gen3BoxEditing.emptyBoxSlots(pc, boxIndex)
        if (emptySlots.isEmpty()) {
            showDialog("Reorder Pokémon", "This box has no empty slot.")
            return
        }
        val boxName = gen3PcBoxNames(pc)[boxIndex]
        AlertDialog.Builder(this)
            .setTitle("$boxName • move to slot")
            .setItems(emptySlots.map { slot -> "Slot ${slot + 1}" }.toTypedArray()) {
                    _, which ->
                confirmGen3Move(
                    sourceGlobal,
                    p,
                    boxIndex * Gen3SaveState.BOX_CAPACITY + emptySlots[which]
                )
            }
            .setNegativeButton("Cancel", null)
            .show()
    }

    private fun chooseGen3MoveDestination(location: String, p: PokemonEntry) {
        val file = importedFile ?: return
        val sourceGlobal = boxedLocationToGlobalIndex(location) ?: run {
            showDialog("Move Pokémon", "Gen 3 PC movement is available for boxed Pokémon only.")
            return
        }
        val data = runCatching { file.readBytes() }.getOrNull() ?: run {
            showDialog("Move Pokémon", "Could not read the working copy.")
            return
        }
        if (!gen3SaveValid(data)) {
            showDialog("Move Pokémon", "The Gen 3 save failed section/checksum validation.")
            return
        }
        val pc = gen3PcBuffer(data) ?: run {
            showDialog("Move Pokémon", "Could not reconstruct Gen 3 PC storage.")
            return
        }
        val source = parsePk3(pc, 4 + sourceGlobal * 80, false)
        if (source == null || source.pid != p.pid || source.species != p.species ||
            !source.checksumValid) {
            showDialog(
                "Move stopped",
                "The source Pokémon changed or failed its PK3 checksum. Reopen it and try again."
            )
            return
        }
        val sourceBox = sourceGlobal / Gen3SaveState.BOX_CAPACITY
        val targets = (0 until Gen3SaveState.BOX_COUNT * Gen3SaveState.BOX_CAPACITY)
            .filter { global ->
                global / Gen3SaveState.BOX_CAPACITY != sourceBox &&
                    parsePk3(pc, 4 + global * 80, false) == null
            }
        if (targets.isEmpty()) {
            showDialog("Move Pokémon", "No empty slot exists in another Gen 3 PC box.")
            return
        }
        val boxNames = gen3PcBoxNames(pc)
        val first = targets.first()
        val labels = arrayOf(
            "First empty • ${boxNames[first / 30]} • Slot ${first % 30 + 1}",
            "Choose another box and slot"
        )
        AlertDialog.Builder(this)
            .setTitle("Move ${p.nickname.ifBlank { "Pokémon" }} to…")
            .setItems(labels) { _, which ->
                if (which == 0) {
                    confirmGen3Move(sourceGlobal, p, first)
                } else {
                    showGen3MoveBoxPicker(sourceGlobal, p, pc, boxNames)
                }
            }
            .setNegativeButton("Cancel", null)
            .show()
    }

    private fun showGen3MoveBoxPicker(
        sourceGlobal: Int,
        p: PokemonEntry,
        pc: ByteArray,
        boxNames: List<String>
    ) {
        val sourceBox = sourceGlobal / Gen3SaveState.BOX_CAPACITY
        val boxes = (0 until Gen3SaveState.BOX_COUNT).filter { box ->
            box != sourceBox && (0 until Gen3SaveState.BOX_CAPACITY).any { slot ->
                parsePk3(pc, 4 + (box * Gen3SaveState.BOX_CAPACITY + slot) * 80, false) == null
            }
        }
        if (boxes.isEmpty()) {
            showDialog("Move Pokémon", "No empty slot exists in another Gen 3 PC box.")
            return
        }
        AlertDialog.Builder(this)
            .setTitle("Choose destination box")
            .setItems(boxes.map { box -> "${boxNames[box]} • Box ${box + 1}" }.toTypedArray()) {
                    _, which ->
                showGen3MoveSlotPicker(sourceGlobal, p, boxes[which], pc, boxNames)
            }
            .setNegativeButton("Cancel", null)
            .show()
    }

    private fun showGen3MoveSlotPicker(
        sourceGlobal: Int,
        p: PokemonEntry,
        boxIndex: Int,
        pc: ByteArray,
        boxNames: List<String>
    ) {
        val emptySlots = (0 until Gen3SaveState.BOX_CAPACITY).filter { slot ->
            parsePk3(
                pc,
                4 + (boxIndex * Gen3SaveState.BOX_CAPACITY + slot) * 80,
                false
            ) == null
        }
        if (emptySlots.isEmpty()) {
            showDialog("Move Pokémon", "${boxNames[boxIndex]} no longer has an empty slot.")
            return
        }
        AlertDialog.Builder(this)
            .setTitle("${boxNames[boxIndex]} • move to slot")
            .setItems(emptySlots.map { slot -> "Slot ${slot + 1}" }.toTypedArray()) { _, which ->
                confirmGen3Move(
                    sourceGlobal,
                    p,
                    boxIndex * Gen3SaveState.BOX_CAPACITY + emptySlots[which]
                )
            }
            .setNegativeButton("Cancel", null)
            .show()
    }

    private fun confirmGen3Move(
        sourceGlobal: Int,
        p: PokemonEntry,
        targetGlobal: Int
    ) {
        val file = importedFile ?: return
        val reviewedSourceUri = currentSourceUri
        val reviewedSourceLabel = currentSourceLabel
        val reviewed = runCatching { file.readBytes() }.getOrNull() ?: run {
            showDialog("Move Pokémon", "Could not read the working copy.")
            return
        }
        if (!gen3SaveValid(reviewed)) {
            showDialog("Move Pokémon", "The Gen 3 save failed section/checksum validation.")
            return
        }
        val pc = gen3PcBuffer(reviewed) ?: run {
            showDialog("Move Pokémon", "Could not reconstruct Gen 3 PC storage.")
            return
        }
        val source = parsePk3(pc, 4 + sourceGlobal * 80, false)
        val target = parsePk3(pc, 4 + targetGlobal * 80, false)
        if (source == null || source.pid != p.pid || source.species != p.species ||
            !source.checksumValid) {
            showDialog("Move stopped", "The source Pokémon changed or failed its PK3 checksum.")
            return
        }
        if (target != null) {
            showDialog("Move stopped", "The destination slot is no longer empty.")
            return
        }
        val boxNames = gen3PcBoxNames(pc)
        val name = p.nickname.ifBlank {
            canonicalGen3SpeciesName(p.species) ?: "Species #${p.species}"
        }
        AlertDialog.Builder(this)
            .setTitle("Move $name?")
            .setMessage(
                "From ${boxNames[sourceGlobal / 30]} • Slot ${sourceGlobal % 30 + 1}\n" +
