    private fun gen3BoxSortEntries(
        occupied: List<Pair<Int, PokemonEntry>>
    ): List<Gen3BoxSortEntry> = occupied.map { (slot, p) ->
        require(p.checksumValid) { "An occupied box slot failed PK3 validation." }
        val level = if (p.isEgg) 0 else {
            val growth = canonicalGen3GrowthRate(p.species)
                ?: error("A box Pokémon's growth curve is unavailable.")
            canonicalLevelForGrowthRate(growth, p.experience)
                ?: error("A box Pokémon's level could not be resolved.")
        }
        Gen3BoxSortEntry(slot, p.species, level, p.nickname.ifBlank {
            canonicalGen3SpeciesName(p.species) ?: "Species #${p.species}"
        }, p.isEgg)
    }

    private fun showGen3BoxSortDialog(
        file: File, opened: ByteArray, openedSourceUri: Uri?, openedSourceLabel: String?,
        boxIndex: Int, boxName: String
    ) {
        fun bound(): Boolean = importedFile?.absolutePath == file.absolutePath &&
            currentSourceUri == openedSourceUri && currentSourceLabel == openedSourceLabel
        try {
            require(bound() && file.readBytes().contentEquals(opened) && gen3SaveValid(opened)) {
                "The save or its identity changed. Reopen PC Boxes."
            }
            val pc = gen3PcBuffer(opened) ?: error("PC storage could not be reconstructed.")
            require(gen3PcBoxNames(pc)[boxIndex] == boxName) { "The selected box changed." }
            val range = Gen3BoxEditing.boxStorageRange(boxIndex)
            val occupied = ArrayList<Pair<Int, PokemonEntry>>()
            for (slot in 0 until Gen3SaveState.BOX_CAPACITY) {
                val offset = range.first + slot * 80
                if (pc.copyOfRange(offset, offset + 80).all { it == 0.toByte() }) continue
                val p = parsePk3(pc, offset, false) ?: error("An occupied box slot could not be read.")
                require(p.checksumValid) { "An occupied box slot failed PK3 validation." }
                occupied.add(slot to p)
            }
            require(occupied.isNotEmpty()) { "$boxName has no Pokémon to organise." }
            val entries = gen3BoxSortEntries(occupied)
            val options = listOf(
                Triple("Pack gaps: keep current order", Gen3BoxSortField.PACK, false),
                Triple("National Dex: lowest first", Gen3BoxSortField.SPECIES, false),
                Triple("National Dex: highest first", Gen3BoxSortField.SPECIES, true),
                Triple("Level: lowest first", Gen3BoxSortField.LEVEL, false),
                Triple("Level: highest first", Gen3BoxSortField.LEVEL, true),
                Triple("Name: A → Z", Gen3BoxSortField.NAME, false),
                Triple("Name: Z → A", Gen3BoxSortField.NAME, true)
            )
            var chosen = false
            AlertDialog.Builder(this)
                .setTitle("Organise $boxName")
                .setItems(options.map { it.first }.toTypedArray()) { _, index ->
                    if (chosen || index !in options.indices) return@setItems
                    chosen = true
                    try {
                        require(bound() && file.readBytes().contentEquals(opened)) {
                            "The save changed while choosing a sort. Reopen PC Boxes."
                        }
                        val option = options[index]
                        val packing = option.second == Gen3BoxSortField.PACK
                        val order = Gen3BoxEditing.sortedOccupiedSlots(entries, option.second, option.third)
                        if (order == (0 until occupied.size).toList()) {
                            showDialog("Box already organised", "$boxName is already packed in this order.")
                        } else {
                            val bySlot = entries.associateBy { it.sourceSlot }
                            val preview = order.mapIndexed { target, source ->
                                val entry = requireNotNull(bySlot[source])
                                "Slot ${target + 1}: ${entry.name} • " +
                                    if (entry.isEgg) "Egg" else "Lv ${entry.level} • #${entry.species}"
                            }.joinToString("\n")
                            var consumed = false
                            AlertDialog.Builder(this)
                                .setTitle(if (packing) "Pack box gaps?" else "Apply box sort?")
                                .setMessage(option.first + "\n\n" + preview +
                                    (if (packing) "\n\nEvery Pokémon, including Eggs, keeps its current relative order. "
                                        else "\n\nTies keep their original order. Eggs remain last in original order. ") +
                                    "PSE will pack the exact Pokémon records, retain a recovery backup, " +
                                    "verify the saved order and restore the working save if verification fails.")
                                .setNegativeButton("Cancel") { _, _ -> consumed = true }
                                .setOnCancelListener { consumed = true }
                                .setPositiveButton(if (packing) "Pack gaps" else "Sort box") { _, _ ->
                                    if (!consumed) {
                                        consumed = true
                                        applyGen3BoxSort(file, opened, openedSourceUri, openedSourceLabel,
                                            boxIndex, boxName, order, option.second, option.third)
                                    }
                                }.show()
                        }
                    } catch (error: Exception) {
                        showDialog("Box sorting stopped", error.message ?: "The sort could not be reviewed.")
                    }
                }
                .setNegativeButton("Cancel") { _, _ -> chosen = true }
                .setOnCancelListener { chosen = true }
                .show()
        } catch (error: Exception) {
            showDialog("Box sorting stopped", error.message ?: "The box could not be opened.")
        }
    }

    private fun applyGen3BoxSort(
        file: File,
        opened: ByteArray,
        openedSourceUri: Uri?,
        openedSourceLabel: String?,
        boxIndex: Int,
        boxName: String,
        orderedSlots: List<Int>,
        field: Gen3BoxSortField,
        descending: Boolean
    ) {
        var writeStarted = false
        try {
            require(importedFile?.absolutePath == file.absolutePath &&
                currentSourceUri == openedSourceUri &&
                currentSourceLabel == openedSourceLabel) {
                "The loaded save identity changed while the box screen was open."
            }
            val fresh = file.readBytes()
            require(fresh.contentEquals(opened)) {
                "The save changed while the box screen was open. Reopen PC Boxes before sorting."
            }
            require(gen3SaveValid(fresh)) {
                "The fresh save is no longer a valid Generation 3 save."
            }
            val freshPc = gen3PcBuffer(fresh)
                ?: error("PSE could not reconstruct the fresh Gen 3 PC storage.")
            require(gen3PcBoxNames(freshPc)[boxIndex] == boxName) {
                "The selected PC box changed after this screen was opened."
            }
            val range = Gen3BoxEditing.boxStorageRange(boxIndex)
            val occupied = ArrayList<Pair<Int, PokemonEntry>>()
            for (slot in 0 until Gen3SaveState.BOX_CAPACITY) {
                val offset = range.first + slot * 80
                val raw = freshPc.copyOfRange(offset, offset + 80)
                if (raw.all { it == 0.toByte() }) continue
                val pokemon = parsePk3(freshPc, offset, false)
                    ?: error("An occupied source slot could not be parsed.")
                require(pokemon.checksumValid) {
                    "An occupied source slot failed its PK3 checksum."
                }
                occupied.add(slot to pokemon)
            }
            val freshOrder = Gen3BoxEditing.sortedOccupiedSlots(
                gen3BoxSortEntries(occupied), field, descending)
            require(freshOrder == orderedSlots && orderedSlots.isNotEmpty()) {
                "The reviewed box sort order changed before writing."
            }
            val sourceRecords = orderedSlots.map { slot ->
                val offset = range.first + slot * 80
                freshPc.copyOfRange(offset, offset + 80)
            }
            val editedPc = Gen3BoxEditing.reorderBoxStorage(
                freshPc,
                boxIndex,
                orderedSlots
            )
            sourceRecords.forEachIndexed { destinationSlot, record ->
                val offset = range.first + destinationSlot * 80
                require(editedPc.copyOfRange(offset, offset + 80)
                    .contentEquals(record)) {
                    "A staged PK3 record was not preserved exactly."
                }
            }
            require(
                editedPc.copyOfRange(
                    range.first + sourceRecords.size * 80,
                    range.last + 1
                ).all { it == 0.toByte() }
            ) {
                "The staged box contains non-empty data after the packed records."
            }
            require(editedPc.indices.all {
                it in range || editedPc[it] == freshPc[it]
            }) {
                "The staged sort changed unrelated PC data."
            }
            val stagedMembers = sourceRecords.indices.map { slot ->
                val pokemon = parsePk3(editedPc, range.first + slot * 80, false)
                    ?: error("A staged PK3 record could not be parsed.")
                require(pokemon.checksumValid) {
                    "A staged PK3 record failed checksum verification."
                }
                slot to pokemon
            }
            require(Gen3BoxEditing.sortedOccupiedSlots(gen3BoxSortEntries(stagedMembers), field, descending) ==
                sourceRecords.indices.toList()) {
                "The staged box is not in the reviewed sort order."
            }

            val sectionMap = gen3ActiveSectionMap(fresh)
                ?: error("PSE could not map the active Gen 3 PC sections.")
            val work = fresh.copyOf()
            writeGen3PcBuffer(work, editedPc)
            require(gen3SaveValid(work) &&
                gen3ActiveSectionMap(work)?.contentEquals(sectionMap) == true &&
                gen3PcBuffer(work)?.contentEquals(editedPc) == true) {
                "The staged Gen 3 save failed checksum or PC byte verification."
            }
            val allowed = HashSet<Int>()
            var pcBase = 0
            for (sectionId in 5..13) {
                val sectionBase = sectionMap[sectionId]
                require(sectionBase >= 0) { "Missing Gen 3 PC section $sectionId." }
                val sectionLength = gen3SectionLengths[sectionId]
                for (localOffset in 0 until sectionLength) {
                    if (pcBase + localOffset in range) {
                        allowed.add(sectionBase + localOffset)
                    }
                }
                allowed.add(sectionBase + 0xFF6)
                allowed.add(sectionBase + 0xFF7)
                pcBase += sectionLength
            }
            require(work.indices.all { it in allowed || work[it] == fresh[it] }) {
                "The sort changed data outside the selected box and PC checksums."
            }

            val backup = File.createTempFile(
                backupGameName(file) + "_PreGen3BoxSort_",
                ".backup",
                backupsDir()
            )
            backup.writeBytes(fresh)
            require(backup.readBytes().contentEquals(fresh)) {
                "The recovery backup did not verify."
            }
            retainGen2ToGen3SafetyBackup(backup, fresh)
            require(importedFile?.absolutePath == file.absolutePath &&
                currentSourceUri == openedSourceUri &&
                currentSourceLabel == openedSourceLabel &&
                file.readBytes().contentEquals(fresh)) {
                "The active save changed before writing. Nothing was changed."
            }

            writeStarted = true
            file.writeBytes(work)
            val persisted = file.readBytes()
            require(persisted.contentEquals(work) && gen3SaveValid(persisted)) {
                "The persisted Gen 3 save failed byte or checksum verification."
            }
            val persistedPc = gen3PcBuffer(persisted)
                ?: error("The persisted Gen 3 PC storage could not be reopened.")
            require(persistedPc.contentEquals(editedPc) &&
                gen3PcBoxNames(persistedPc)[boxIndex] == boxName) {
                "The sorted Gen 3 box did not persist exactly."
            }
            val reopenedMembers = sourceRecords.indices.map { slot ->
                val pokemon = parsePk3(persistedPc, range.first + slot * 80, false)
                    ?: error("A sorted Pokémon was missing after reopen.")
                require(pokemon.checksumValid) {
                    "A sorted Pokémon failed checksum verification after reopen."
                }
                slot to pokemon
            }
            require(Gen3BoxEditing.sortedOccupiedSlots(gen3BoxSortEntries(reopenedMembers), field, descending) ==
                sourceRecords.indices.toList()) {
                "The reopened box is not in the reviewed sort order."
            }
            Toast.makeText(
                this,
                "$boxName organised and verified",
                Toast.LENGTH_LONG
            ).show()
            showGen3PokemonViewer("boxes", boxIndex)
        } catch (error: Exception) {
            val restored = if (writeStarted) {
                runCatching {
                    file.writeBytes(opened)
                    file.readBytes().contentEquals(opened)
                }.getOrDefault(false)
            } else {
                false
            }
            val recovery = when {
                !writeStarted -> "Nothing was written."
                restored -> "The original save was restored and verified."
                else -> "Automatic restore could not be verified. Restore the retained backup before editing this save again."
            }
            showDialog(
                "Gen 3 box sort failed",
                (error.message ?: "Unknown error") + "\n\n" + recovery
            )
        }
    }

    private fun showGen3BoxSwapDialog(
        file: File,
        opened: ByteArray,
        openedSourceUri: Uri?,
        openedSourceLabel: String?,
        firstBoxIndex: Int,
        loadedBoxNames: List<String>
    ) {
        val pc = gen3PcBuffer(opened)
        if (pc == null) {
            showDialog("Swap Gen 3 boxes", "PC storage could not be reconstructed.")
            return
        }
        val occupiedCounts = List(Gen3SaveState.BOX_COUNT) { boxIndex ->
            (0 until Gen3SaveState.BOX_CAPACITY).count { slot ->
                val global = boxIndex * Gen3SaveState.BOX_CAPACITY + slot
                parsePk3(pc, 4 + global * 80, false) != null
            }
        }
        val target = EditText(this).apply {
            hint = "Target box number (1–14)"
            setSingleLine(true)
            setTextColor(TEXT)
            setHintTextColor(MUTED)
        }
        AlertDialog.Builder(this)
            .setTitle("Swap ${loadedBoxNames[firstBoxIndex]} contents")
            .setMessage(
                "Choose another box. Only the 30 Pokémon slots are exchanged; both box names stay unchanged."
            )
            .setView(target)
            .setNegativeButton("Cancel", null)
            .setPositiveButton("Review") { _, _ ->
                val secondBoxIndex = target.text.toString().trim().toIntOrNull()?.minus(1)
                if (secondBoxIndex == null ||
                    secondBoxIndex !in 0 until Gen3SaveState.BOX_COUNT ||
                    secondBoxIndex == firstBoxIndex) {
                    showDialog(
                        "Invalid target box",
                        "Enter a different box number from 1 to 14. Nothing was written."
                    )
                    return@setPositiveButton
                }
                AlertDialog.Builder(this)
                    .setTitle("Swap these box contents?")
                    .setMessage(
                        "${loadedBoxNames[firstBoxIndex]}: ${occupiedCounts[firstBoxIndex]} Pokémon\n" +
                            "${loadedBoxNames[secondBoxIndex]}: ${occupiedCounts[secondBoxIndex]} Pokémon\n\n" +
                            "Names remain in place. PSE will create a verified recovery backup, " +
                            "swap only these two box regions, repair PC checksums, reopen, and verify."
                    )
                    .setNegativeButton("Cancel", null)
                    .setPositiveButton("Swap boxes") { _, _ ->
                        applyGen3BoxSwap(
                            file,
                            opened,
                            openedSourceUri,
                            openedSourceLabel,
                            firstBoxIndex,
                            secondBoxIndex,
                            loadedBoxNames,
                            occupiedCounts
                        )
                    }
                    .show()
            }
            .show()
    }

    private fun applyGen3BoxSwap(
        file: File,
        opened: ByteArray,
        openedSourceUri: Uri?,
        openedSourceLabel: String?,
        firstBoxIndex: Int,
        secondBoxIndex: Int,
        loadedBoxNames: List<String>,
        loadedOccupiedCounts: List<Int>
    ) {
        var writeStarted = false
        try {
            require(firstBoxIndex != secondBoxIndex) {
                "The source and target boxes must be different."
            }
            require(importedFile?.absolutePath == file.absolutePath &&
                currentSourceUri == openedSourceUri &&
                currentSourceLabel == openedSourceLabel) {
                "The loaded save identity changed while the box screen was open."
            }
            val fresh = file.readBytes()
            require(fresh.contentEquals(opened)) {
                "The save changed while the box screen was open. Reopen PC Boxes before swapping."
            }
            require(gen3SaveValid(fresh)) {
                "The fresh save is no longer a valid Generation 3 save."
            }
            val freshPc = gen3PcBuffer(fresh)
                ?: error("PSE could not reconstruct the fresh Gen 3 PC storage.")
            require(gen3PcBoxNames(freshPc) == loadedBoxNames) {
                "The PC box names changed after this screen was opened."
            }
            val freshOccupiedCounts = List(Gen3SaveState.BOX_COUNT) { boxIndex ->
                (0 until Gen3SaveState.BOX_CAPACITY).count { slot ->
                    val global = boxIndex * Gen3SaveState.BOX_CAPACITY + slot
                    parsePk3(freshPc, 4 + global * 80, false) != null
                }
            }
            require(freshOccupiedCounts == loadedOccupiedCounts) {
                "The PC box contents changed after this screen was opened."
            }

            val firstRange = Gen3BoxEditing.boxStorageRange(firstBoxIndex)
            val secondRange = Gen3BoxEditing.boxStorageRange(secondBoxIndex)
            val editedPc = Gen3BoxEditing.swapBoxStorage(
                freshPc,
                firstBoxIndex,
                secondBoxIndex
            )
            require(
                editedPc.copyOfRange(firstRange.first, firstRange.last + 1)
                    .contentEquals(freshPc.copyOfRange(secondRange.first, secondRange.last + 1)) &&
                    editedPc.copyOfRange(secondRange.first, secondRange.last + 1)
                        .contentEquals(freshPc.copyOfRange(firstRange.first, firstRange.last + 1))
            ) {
                "The staged box contents did not exchange exactly."
            }
            require(editedPc.indices.all {
                it in firstRange || it in secondRange || editedPc[it] == freshPc[it]
            }) {
                "The staged box swap changed unrelated PC data."
            }

            val sectionMap = gen3ActiveSectionMap(fresh)
                ?: error("PSE could not map the active Gen 3 PC sections.")
            val work = fresh.copyOf()
            writeGen3PcBuffer(work, editedPc)
            require(gen3SaveValid(work) &&
                gen3PcBuffer(work)?.contentEquals(editedPc) == true) {
                "The staged Gen 3 PC storage failed checksum or byte verification."
            }
            val allowed = HashSet<Int>()
            var pcBase = 0
            for (sectionId in 5..13) {
                val sectionBase = sectionMap[sectionId]
                require(sectionBase >= 0) { "Missing Gen 3 PC section $sectionId." }
                val sectionLength = gen3SectionLengths[sectionId]
                for (localOffset in 0 until sectionLength) {
                    val pcOffset = pcBase + localOffset
                    if (pcOffset in firstRange || pcOffset in secondRange) {
                        allowed.add(sectionBase + localOffset)
                    }
                }
                allowed.add(sectionBase + 0xFF6)
                allowed.add(sectionBase + 0xFF7)
                pcBase += sectionLength
            }
            require(work.indices.all { it in allowed || work[it] == fresh[it] }) {
                "The box swap changed data outside the two selected boxes and PC checksums."
            }

            val backup = File.createTempFile(
                backupGameName(file) + "_PreGen3BoxSwap_",
                ".backup",
                backupsDir()
            )
            backup.writeBytes(fresh)
            require(backup.readBytes().contentEquals(fresh)) {
                "The recovery backup did not verify."
            }
            retainGen2ToGen3SafetyBackup(backup, fresh)
            require(importedFile?.absolutePath == file.absolutePath &&
                currentSourceUri == openedSourceUri &&
                currentSourceLabel == openedSourceLabel &&
                file.readBytes().contentEquals(fresh)) {
                "The active save changed before writing. Nothing was changed."
            }

            writeStarted = true
            file.writeBytes(work)
            val persisted = file.readBytes()
            require(persisted.contentEquals(work) && gen3SaveValid(persisted)) {
                "The persisted Gen 3 save failed byte or checksum verification."
            }
            val persistedPc = gen3PcBuffer(persisted)
                ?: error("The persisted Gen 3 PC storage could not be reopened.")
            require(persistedPc.contentEquals(editedPc) &&
                gen3PcBoxNames(persistedPc) == loadedBoxNames) {
                "The swapped Gen 3 boxes did not persist exactly."
            }
            val persistedCounts = List(Gen3SaveState.BOX_COUNT) { boxIndex ->
                (0 until Gen3SaveState.BOX_CAPACITY).count { slot ->
                    val global = boxIndex * Gen3SaveState.BOX_CAPACITY + slot
                    parsePk3(persistedPc, 4 + global * 80, false) != null
                }
            }
            require(
                persistedCounts[firstBoxIndex] == loadedOccupiedCounts[secondBoxIndex] &&
                    persistedCounts[secondBoxIndex] == loadedOccupiedCounts[firstBoxIndex]
            ) {
                "The reopened box occupancy did not match the reviewed swap."
            }
            Toast.makeText(
                this,
                "Box contents swapped and verified; recovery backup retained",
                Toast.LENGTH_LONG
            ).show()
            showGen3PokemonViewer("boxes", firstBoxIndex)
        } catch (error: Exception) {
            val restored = if (writeStarted) {
                runCatching {
                    file.writeBytes(opened)
                    file.readBytes().contentEquals(opened)
                }.getOrDefault(false)
            } else {
                false
            }
            val recovery = when {
                !writeStarted -> "Nothing was written."
                restored -> "The original save was restored and verified."
                else -> "Automatic restore could not be verified. Restore the retained backup before editing this save again."
            }
            showDialog(
                "Gen 3 box swap failed",
                (error.message ?: "Unknown error") + "\n\n" + recovery
            )
        }
    }

    private fun showGen3SelectedPartyMoveDialog(
        file: File,
        opened: ByteArray,
        openedSourceUri: Uri?,
        openedSourceLabel: String?,
        boxIndex: Int,
        boxName: String,
        selectedSlots: List<Int>,
        copyOnly: Boolean = false
    ) {
        val action = if (copyOnly) "Copy" else "Move"
        try {
            require(selectedSlots.isNotEmpty() &&
                selectedSlots.size == selectedSlots.toSet().size) {
                "Select one or more unique Gen 3 PC slots."
            }
            require(importedFile?.absolutePath == file.absolutePath &&
                currentSourceUri == openedSourceUri &&
                currentSourceLabel == openedSourceLabel) {
                "The loaded save identity changed while multi-select was open."
            }
            require(file.readBytes().contentEquals(opened) && gen3SaveValid(opened)) {
                "The opened save is no longer a valid Generation 3 save."
            }
            val pc = gen3PcBuffer(opened)
                ?: error("PSE could not reconstruct the opened Gen 3 PC storage.")
            require(gen3PcBoxNames(pc)[boxIndex] == boxName) {
                "The selected PC box changed after this screen was opened."
            }
            val records = Gen3BoxEditing.copySelectedBoxRecords(
                pc,
                boxIndex,
                selectedSlots
            )
            val game = detectGen3GameFromData(
                opened,
                openedSourceLabel ?: file.name
            )
            val partyOffset = gen3PartyOffset(opened, game)
                ?: error("The Gen 3 party block could not be located.")
            val partyCount = readU32LE(opened, partyOffset - 4).toInt()
            require(partyCount in 1..5 &&
                selectedSlots.size <= 6 - partyCount) {
                "The Gen 3 party does not have room for this complete batch."
            }
            for (slot in partyCount until partyCount + selectedSlots.size) {
                require(opened.copyOfRange(
                    partyOffset + slot * 100,
                    partyOffset + (slot + 1) * 100
                ).all { it == 0.toByte() }) {
                    "An inactive destination party record is not exactly empty."
                }
            }
            val names = records.mapIndexed { index, raw ->
                val pokemon = parsePk3(raw, 0, false)
                    ?: error("Selected slot ${selectedSlots.sorted()[index] + 1} is empty.")
                require(pokemon.checksumValid && pokemon.species != 386) {
                    if (pokemon.species == 386) {
                        "Deoxys party-stat rebuilding remains safety-locked."
                    } else {
                        "A selected PK3 failed checksum validation."
                    }
                }
                val growth = canonicalGen3GrowthRate(pokemon.species)
                    ?: error("A selected Pokémon's growth curve is unavailable.")
                val level = canonicalLevelForGrowthRate(
                    growth,
                    pokemon.experience
                ) ?: error("A selected Pokémon's level could not be resolved.")
                val base = canonicalGen3BaseStats(pokemon.species)
                    ?: error("A selected Pokémon's base stats are unavailable.")
                calculateGen3BattleStats(
                    base,
                    pokemon.ivs,
                    pokemon.evs,
                    pokemon.nature,
                    level
                )
                pokemon.nickname.ifBlank {
                    canonicalGen3SpeciesName(pokemon.species)
                        ?: "Species #${pokemon.species}"
                }
            }
            val sourceLabels = selectedSlots.sorted()
                .joinToString(", ") { (it + 1).toString() }
            val partyLabels = (partyCount until partyCount + selectedSlots.size)
                .joinToString(", ") { (it + 1).toString() }
            var consumed = false
            AlertDialog.Builder(this)
                .setTitle("${action} ${selectedSlots.size} Pokémon to Party?")
                .setMessage(
                    "From Box ${boxIndex + 1} • $boxName slots: $sourceLabels\n" +
                        "To Party slots: $partyLabels\n" +
                        names.joinToString(", ", prefix = "Pokémon: ") +
                        "\n\nPSE will preserve each exact PK3, rebuild verified " +
                        "party-only stats, create a recovery backup, " +
                        (if (copyOnly) "keep every PC original unchanged, " else "clear only the source slots, ") +
                        "update checksums, reopen the save, and roll back " +
                        "the entire batch on any mismatch."
                )
                .setNegativeButton("Cancel") { _, _ -> consumed = true }
                .setOnCancelListener { consumed = true }
                .setPositiveButton("${action} batch") { _, _ ->
                    if (!consumed) {
                        consumed = true
                        moveSelectedGen3PcPokemonToParty(
                            file,
                            opened,
                            openedSourceUri,
                            openedSourceLabel,
                            boxIndex,
                            boxName,
                            selectedSlots.sorted(),
                            copyOnly
                        )
                    }
                }
                .show()
        } catch (error: Exception) {
            showDialog(
                "${action} selected to Party stopped",
                error.message ?: "The selected Gen 3 batch could not be reviewed."
            )
        }
    }

    private fun moveSelectedGen3PcPokemonToParty(
        file: File,
        opened: ByteArray,
        openedSourceUri: Uri?,
        openedSourceLabel: String?,
        boxIndex: Int,
        boxName: String,
        selectedSlots: List<Int>,
        copyOnly: Boolean
    ) {
        var writeStarted = false
        try {
            require(selectedSlots.isNotEmpty() &&
                selectedSlots.size == selectedSlots.toSet().size &&
                selectedSlots.all { it in 0 until Gen3SaveState.BOX_CAPACITY }) {
                "The selected Gen 3 PC slots are invalid."
            }
            require(importedFile?.absolutePath == file.absolutePath &&
                currentSourceUri == openedSourceUri &&
                currentSourceLabel == openedSourceLabel) {
                "The loaded save identity changed after review."
            }
            val fresh = file.readBytes()
            require(fresh.contentEquals(opened) && gen3SaveValid(fresh)) {
                "The save changed or failed validation after review."
            }
            val freshPc = gen3PcBuffer(fresh)
                ?: error("The fresh Gen 3 PC storage could not be opened.")
            require(gen3PcBoxNames(freshPc)[boxIndex] == boxName) {
                "The source PC box changed after review."
            }
            val sortedSlots = selectedSlots.sorted()
            val records = Gen3BoxEditing.copySelectedBoxRecords(
                freshPc,
                boxIndex,
                sortedSlots
            )
            val sources = records.mapIndexed { index, raw ->
                val pokemon = parsePk3(raw, 0, false)
                    ?: error("A selected source PC Pokémon is missing.")
                require(pokemon.checksumValid && pokemon.species != 386) {
                    if (pokemon.species == 386) {
                        "Deoxys party-stat rebuilding remains safety-locked."
                    } else {
                        "A selected source PK3 failed checksum validation."
                    }
                }
                pokemon
            }
            val sourceGlobals = sortedSlots.map {
                boxIndex * Gen3SaveState.BOX_CAPACITY + it
            }
            val builds = sources.mapIndexed { index, pokemon ->
                val growthRate = canonicalGen3GrowthRate(pokemon.species)
                    ?: error("A selected Gen 3 growth curve could not be resolved.")
                val level = canonicalLevelForGrowthRate(
                    growthRate,
                    pokemon.experience
                ) ?: error("A selected Gen 3 level could not be resolved.")
                val baseStats = canonicalGen3BaseStats(pokemon.species)
                    ?: error("A selected Gen 3 base-stat set could not be resolved.")
                val stats = calculateGen3BattleStats(
                    baseStats,
                    pokemon.ivs,
                    pokemon.evs,
                    pokemon.nature,
                    level
                )
                Gen3PcPartyBuild(sourceGlobals[index], level, stats)
            }

            val game = detectGen3GameFromData(
                fresh,
                openedSourceLabel ?: file.name
            )
            val partyOffset = gen3PartyOffset(fresh, game)
                ?: error("The Gen 3 party block could not be located.")
            val partyCount = readU32LE(fresh, partyOffset - 4).toInt()
            gen3PartyBatchMoveMembers(fresh, partyOffset, partyCount)
            require(partyCount in 1..5 &&
                builds.size <= 6 - partyCount) {
                "The Gen 3 party no longer has room for the complete batch."
            }
            val partyRecords = fresh.copyOfRange(
                partyOffset,
                partyOffset + 600
            )
            val result = if (copyOnly) {
                Gen3PartyEditing.copyPcPokemonBatchToParty(partyRecords, partyCount, freshPc, builds)
            } else {
                Gen3PartyEditing.movePcPokemonBatchToParty(partyRecords, partyCount, freshPc, builds)
            }
            val expectedPartySlots =
                (partyCount until partyCount + builds.size).toList()
            require(result.partyCount == partyCount + builds.size &&
                result.sourceGlobalIndices == sourceGlobals &&
                result.insertedSlots == expectedPartySlots) {
                "The staged PC-to-party batch mapping is invalid."
            }
            val sourceRanges = sourceGlobals.map { global ->
                val start = 4 + global * 80
                start until (start + 80)
            }
            val partyRanges = expectedPartySlots.map { slot ->
                val start = slot * 100
                start until (start + 100)
            }
            require(if (copyOnly) result.pc.contentEquals(freshPc) else sourceRanges.all { range ->
                range.all { result.pc[it] == 0.toByte() }
            }) {
                "A staged source PC slot did not match the reviewed copy/move action."
            }
            require(result.pc.indices.all { index ->
                sourceRanges.any { index in it } || result.pc[index] == freshPc[index]
            }) {
                "The staged batch changed unrelated PC data."
            }
            require(result.partyRecords.indices.all { index ->
                partyRanges.any { index in it } ||
                    result.partyRecords[index] == partyRecords[index]
            }) {
                "The staged batch changed an unrelated party record."
            }
            expectedPartySlots.forEachIndexed { index, slot ->
                val offset = slot * 100
                require(result.partyRecords.copyOfRange(offset, offset + 80)
                    .contentEquals(records[index])) {
                    "A staged party slot did not preserve its exact PK3."
                }
                val staged = parsePk3(result.partyRecords, offset, true)
                    ?: error("A staged party Pokémon could not be reopened.")
                val stagedStats = gen3PartyStatsFromRaw(
                    result.partyRecords.copyOfRange(offset, offset + 100)
                ) ?: error("A staged party stat block could not be read.")
                val build = builds[index]
                require(staged.checksumValid &&
                    staged.pid == sources[index].pid &&
                    staged.species == sources[index].species &&
                    staged.level == build.level &&
                    stagedStats[0] == build.level &&
                    stagedStats[1] == build.battleStats[0] &&
                    stagedStats[2] == build.battleStats[0] &&
                    (0 until 5).all {
                        stagedStats[it + 3] == build.battleStats[it + 1]
                    }) {
                    "A staged party record failed identity or stat verification."
                }
            }

            val sectionMap = gen3ActiveSectionMap(fresh)
                ?: error("PSE could not map the active Gen 3 save sections.")
            val section1 = sectionMap[1]
            require(section1 >= 0) { "The active party section is missing." }
            val work = fresh.copyOf()
            if (!copyOnly) writeGen3PcBuffer(work, result.pc)
            result.partyRecords.copyInto(work, partyOffset)
            writeU32LE(work, partyOffset - 4, result.partyCount.toLong())
            updateGen3SectionChecksumAt(work, section1, 1)
            require(gen3SaveValid(work) &&
                gen3ActiveSectionMap(work)?.contentEquals(sectionMap) == true) {
                "The staged save failed complete Gen 3 checksum verification."
            }

            val allowed = HashSet<Int>()
            for (index in partyOffset - 4 until partyOffset) {
                allowed.add(index)
            }
            partyRanges.forEach { range ->
                for (index in range) allowed.add(partyOffset + index)
            }
            allowed.add(section1 + 0xFF6)
            allowed.add(section1 + 0xFF7)
            if (!copyOnly) {
                var logicalBase = 0
                for (id in 5..13) {
                    val sectionBase = sectionMap[id]
                    require(sectionBase >= 0) { "An active PC section is missing." }
                    val sectionLength = gen3SectionLengths[id]
                    for (localOffset in 0 until sectionLength) {
                        val logical = logicalBase + localOffset
                        if (sourceRanges.any { logical in it }) {
                            allowed.add(sectionBase + localOffset)
                        }
                    }
                    allowed.add(sectionBase + 0xFF6)
                    allowed.add(sectionBase + 0xFF7)
                    logicalBase += sectionLength
                }
            }
            require(work.indices.all { it in allowed || work[it] == fresh[it] }) {
                "The batch changed data outside source PC slots, new party records, " +
                    "party count, and affected checksums."
            }

            val backup = File.createTempFile(
                backupGameName(file) + (if (copyOnly) "_PreGen3PcCopyToParty_" else "_PreGen3PcBatchToParty_"),
                ".backup",
                backupsDir()
            )
            backup.writeBytes(fresh)
            require(backup.readBytes().contentEquals(fresh)) {
                "The recovery backup did not verify."
            }
            retainGen2ToGen3SafetyBackup(backup, fresh)
            require(importedFile?.absolutePath == file.absolutePath &&
                currentSourceUri == openedSourceUri &&
                currentSourceLabel == openedSourceLabel &&
                file.readBytes().contentEquals(fresh)) {
                "The active save changed before writing. Nothing was changed."
            }

            writeStarted = true
            file.writeBytes(work)
            val persisted = file.readBytes()
            require(persisted.contentEquals(work) && gen3SaveValid(persisted)) {
                "The persisted Gen 3 save failed byte or checksum verification."
            }
            val reopenedPc = gen3PcBuffer(persisted)
                ?: error("The persisted Gen 3 PC storage could not be reopened.")
            val reopenedPartyOffset = gen3PartyOffset(persisted, game)
                ?: error("The persisted party block could not be reopened.")
            require(readU32LE(
                persisted,
                reopenedPartyOffset - 4
            ).toInt() == result.partyCount &&
                reopenedPc.contentEquals(result.pc) &&
                persisted.copyOfRange(reopenedPartyOffset, reopenedPartyOffset + 600)
                    .contentEquals(result.partyRecords)) {
                "The exact source PC state, party records or count did not persist."
            }
            expectedPartySlots.forEachIndexed { index, slot ->
                val offset = reopenedPartyOffset + slot * 100
                val raw = persisted.copyOfRange(offset, offset + 100)
                val reopened = parsePk3(raw, 0, true)
                    ?: error("A moved party Pokémon was missing after reopen.")
                val stats = gen3PartyStatsFromRaw(raw)
                    ?: error("A persisted party stat block could not be read.")
                val build = builds[index]
                require(raw.copyOfRange(0, 80).contentEquals(records[index]) &&
                    reopened.checksumValid &&
                    reopened.pid == sources[index].pid &&
                    reopened.species == sources[index].species &&
                    reopened.level == build.level &&
                    stats[0] == build.level &&
                    stats[1] == build.battleStats[0] &&
                    stats[2] == build.battleStats[0] &&
                    (0 until 5).all {
                        stats[it + 3] == build.battleStats[it + 1]
                    }) {
                    "A moved party Pokémon failed final verification."
                }
            }

            resetGen3BoxSelection()
            Toast.makeText(
                this,
                if (copyOnly) "Copied ${records.size} Pokémon to Party; PC originals unchanged"
                else "${records.size} Gen 3 Pokémon moved to Party and verified",
                Toast.LENGTH_LONG
            ).show()
            showGen3PokemonViewer("party")
        } catch (error: Exception) {
            val restored = if (writeStarted) {
                runCatching {
                    file.writeBytes(opened)
                    file.readBytes().contentEquals(opened)
                }.getOrDefault(false)
            } else {
                true
            }
            val recovery = if (restored) {
                "The original save was preserved or restored."
            } else {
                "Automatic rollback could not be verified. Use the retained recovery backup."
            }
            showDialog(
                if (copyOnly) "Gen 3 PC-to-party copy failed" else "Gen 3 PC batch-to-party move failed",
                (error.message ?: "Unknown error") + "\n\n" + recovery
            )
        }
    }

    private fun showGen3SelectedDuplicateBoxPicker(
        file: File,
        opened: ByteArray,
        openedSourceUri: Uri?,
        openedSourceLabel: String?,
        sourceBoxIndex: Int,
        sourceBoxName: String,
        selectedSlots: List<Int>
    ) {
        if (selectedSlots.isEmpty()) return
        try {
            require(importedFile?.absolutePath == file.absolutePath &&
                currentSourceUri == openedSourceUri &&
                currentSourceLabel == openedSourceLabel) {
                "The loaded save identity changed while multi-select was open."
            }
            require(gen3SaveValid(opened)) {
                "The opened save is no longer a valid Generation 3 save."
            }
            val pc = gen3PcBuffer(opened)
                ?: error("PSE could not reconstruct the opened Gen 3 PC storage.")
            require(gen3PcBoxNames(pc)[sourceBoxIndex] == sourceBoxName) {
                "The selected PC box changed after this screen was opened."
            }
            Gen3BoxEditing.copySelectedBoxRecords(
                pc,
                sourceBoxIndex,
                selectedSlots
            )
            val boxNames = gen3PcBoxNames(pc)
            val targets = (0 until Gen3SaveState.BOX_COUNT).filter { box ->
                box != sourceBoxIndex &&
                    Gen3BoxEditing.emptyBoxSlots(pc, box).size >= selectedSlots.size
            }
            if (targets.isEmpty()) {
                showDialog(
                    "Duplicate selected",
