                .setTitle("Duplicate ${selectedSlots.size} Pokémon to which box?")
                .setItems(targets.map { box ->
                    val empty = Gen3BoxEditing.emptyBoxSlots(pc, box).size
                    "${boxNames[box]} • Box ${box + 1} • $empty empty"
                }.toTypedArray()) { _, which ->
                    val targetBox = targets[which]
                    val targetSlots = Gen3BoxEditing.emptyBoxSlots(pc, targetBox)
                        .take(selectedSlots.size)
                    val sourceLabels = selectedSlots.sorted()
                        .joinToString(", ") { (it + 1).toString() }
                    val targetLabels = targetSlots
                        .joinToString(", ") { (it + 1).toString() }
                    AlertDialog.Builder(this)
                        .setTitle("Duplicate batch to ${boxNames[targetBox]}?")
                        .setMessage(
                            "Keep Box ${sourceBoxIndex + 1} • $sourceBoxName slots: " +
                                "$sourceLabels\nCopy to Box ${targetBox + 1} • " +
                                "${boxNames[targetBox]} slots: $targetLabels\n\n" +
                                "PSE will preserve every source PK3, create a verified " +
                                "recovery backup, write only the listed empty slots, repair " +
                                "PC checksums, reopen the save, and roll back on any mismatch."
                        )
                        .setNegativeButton("Cancel", null)
                        .setPositiveButton("Duplicate batch") { _, _ ->
                            duplicateSelectedGen3ToBox(
                                file,
                                opened,
                                openedSourceUri,
                                openedSourceLabel,
                                sourceBoxIndex,
                                sourceBoxName,
                                selectedSlots,
                                targetBox,
                                boxNames[targetBox]
                            )
