    private fun moveSelectedGen3ToBox(
        file: File,
        opened: ByteArray,
        openedSourceUri: Uri?,
        openedSourceLabel: String?,
        sourceBoxIndex: Int,
        sourceBoxName: String,
        selectedSlots: List<Int>,
        targetBoxIndex: Int,
        targetBoxName: String
    ) {
        var writeStarted = false
        try {
            require(selectedSlots.isNotEmpty() &&
                selectedSlots.size == selectedSlots.toSet().size &&
                selectedSlots.all { it in 0 until Gen3SaveState.BOX_CAPACITY }) {
                "The selected Gen 3 PC slots are invalid."
            }
            require(sourceBoxIndex != targetBoxIndex &&
                sourceBoxIndex in 0 until Gen3SaveState.BOX_COUNT &&
                targetBoxIndex in 0 until Gen3SaveState.BOX_COUNT) {
                "The selected source or destination box is invalid."
            }
            require(importedFile?.absolutePath == file.absolutePath &&
                currentSourceUri == openedSourceUri &&
                currentSourceLabel == openedSourceLabel) {
                "The loaded save identity changed while the move was open."
            }
            val fresh = file.readBytes()
            require(fresh.contentEquals(opened)) {
                "The save changed while the move was open. Reopen PC Boxes and try again."
            }
            require(gen3SaveValid(fresh)) {
                "The fresh save is no longer a valid Generation 3 save."
            }
            val freshPc = gen3PcBuffer(fresh)
                ?: error("PSE could not reconstruct the fresh Gen 3 PC storage.")
            val boxNames = gen3PcBoxNames(freshPc)
            require(boxNames[sourceBoxIndex] == sourceBoxName &&
                boxNames[targetBoxIndex] == targetBoxName) {
                "A source or destination PC box changed after review."
            }
            val sortedSlots = selectedSlots.sorted()
            val records = Gen3BoxEditing.copySelectedBoxRecords(
                freshPc,
                sourceBoxIndex,
                sortedSlots
            )
            records.forEachIndexed { index, raw ->
                val pokemon = parsePk3(raw, 0, false)
                require(pokemon != null && pokemon.checksumValid) {
                    "Selected slot ${sortedSlots[index] + 1} failed PK3 validation."
                }
            }
            val moved = Gen3BoxEditing.moveSelectedBoxRecords(
                freshPc,
                sourceBoxIndex,
                sortedSlots,
                targetBoxIndex
            )
            require(moved.sourceSlots == sortedSlots &&
                moved.targetSlots.size == records.size &&
                moved.targetSlots == moved.targetSlots.sorted() &&
                moved.targetSlots.size == moved.targetSlots.toSet().size) {
                "The staged destination mapping is invalid."
            }
            val sourceBoxRange = Gen3BoxEditing.boxStorageRange(sourceBoxIndex)
            val targetBoxRange = Gen3BoxEditing.boxStorageRange(targetBoxIndex)
            val sourceRanges = moved.sourceSlots.map { slot ->
                val start = sourceBoxRange.first + slot * 80
                start until (start + 80)
            }
            val targetRanges = moved.targetSlots.map { slot ->
                val start = targetBoxRange.first + slot * 80
                start until (start + 80)
            }
            require(sourceRanges.all { range ->
                range.all { moved.pc[it] == 0.toByte() }
            }) {
                "A staged source slot was not cleared."
            }
            require(targetRanges.indices.all { index ->
                moved.pc.copyOfRange(
                    targetRanges[index].first,
                    targetRanges[index].last + 1
                ).contentEquals(records[index])
            }) {
                "A staged destination slot did not match its source PK3."
            }
            val changedRanges = sourceRanges + targetRanges
            require(moved.pc.indices.all { index ->
                changedRanges.any { index in it } || moved.pc[index] == freshPc[index]
            }) {
                "The staged batch move changed unrelated PC data."
            }

            val sectionMap = gen3ActiveSectionMap(fresh)
                ?: error("PSE could not map the active Gen 3 PC sections.")
            val work = fresh.copyOf()
            writeGen3PcBuffer(work, moved.pc)
            require(gen3SaveValid(work) &&
                gen3PcBuffer(work)?.contentEquals(moved.pc) == true) {
                "The staged Gen 3 PC storage failed checksum or byte verification."
            }
            val allowed = HashSet<Int>()
            var pcBase = 0
            for (sectionId in 5..13) {
                val sectionBase = sectionMap[sectionId]
                require(sectionBase >= 0) {
                    "Missing Gen 3 PC section $sectionId."
                }
                val sectionLength = gen3SectionLengths[sectionId]
                for (localOffset in 0 until sectionLength) {
                    val pcOffset = pcBase + localOffset
                    if (changedRanges.any { pcOffset in it }) {
                        allowed.add(sectionBase + localOffset)
                    }
                }
                allowed.add(sectionBase + 0xFF6)
                allowed.add(sectionBase + 0xFF7)
                pcBase += sectionLength
            }
            require(work.indices.all { it in allowed || work[it] == fresh[it] }) {
                "The batch move changed data outside selected slots and PC checksums."
            }

            val backup = File.createTempFile(
                backupGameName(file) + "_PreGen3PcBatchMove_",
                ".backup",
                backupsDir()
            )
            backup.writeBytes(fresh)
            require(backup.readBytes().contentEquals(fresh)) {
                "The recovery backup did not verify."
            }
            retainGen2ToGen3SafetyBackup(backup, fresh)
            require(importedFile?.absolutePath == file.absolutePath &&
                currentSourceUri == openedSourceUri &&
                currentSourceLabel == openedSourceLabel &&
                file.readBytes().contentEquals(fresh)) {
                "The active save changed before writing. Nothing was changed."
            }

            writeStarted = true
            file.writeBytes(work)
            val persisted = file.readBytes()
            require(persisted.contentEquals(work) && gen3SaveValid(persisted)) {
                "The persisted Gen 3 save failed byte or checksum verification."
            }
            val persistedPc = gen3PcBuffer(persisted)
                ?: error("The persisted Gen 3 PC storage could not be reopened.")
            require(persistedPc.contentEquals(moved.pc) &&
                gen3PcBoxNames(persistedPc)[sourceBoxIndex] == sourceBoxName &&
                gen3PcBoxNames(persistedPc)[targetBoxIndex] == targetBoxName &&
                sourceRanges.all { range ->
                    range.all { persistedPc[it] == 0.toByte() }
                } &&
                targetRanges.indices.all { index ->
                    persistedPc.copyOfRange(
                        targetRanges[index].first,
                        targetRanges[index].last + 1
                    ).contentEquals(records[index])
                }) {
                "The exact source-to-destination mapping did not persist."
            }

            resetGen3BoxSelection()
            Toast.makeText(
                this,
                "${records.size} Gen 3 Pokémon moved to $targetBoxName and verified",
                Toast.LENGTH_LONG
            ).show()
            showGen3PokemonViewer("boxes", targetBoxIndex)
        } catch (error: Exception) {
            val restored = if (writeStarted) {
                runCatching {
                    file.writeBytes(opened)
                    file.readBytes().contentEquals(opened)
                }.getOrDefault(false)
            } else {
                true
            }
            val recovery = if (restored) {
                "The original save was preserved or restored."
            } else {
                "Automatic rollback could not be verified. Use the retained recovery backup."
            }
            showDialog(
                "Gen 3 batch PC move failed",
                (error.message ?: "Unknown error") + "\n\n" + recovery
            )
        }
    }


    private fun showGen3SelectedBankCopyDialog(
        file: File,
        opened: ByteArray,
        openedSourceUri: Uri?,
        openedSourceLabel: String?,
        boxIndex: Int,
        boxName: String,
        selectedSlots: List<Int>
    ) {
        try {
            require(selectedSlots.isNotEmpty() &&
                selectedSlots.size == selectedSlots.toSet().size &&
                selectedSlots.all { it in 0 until Gen3SaveState.BOX_CAPACITY }) {
                "The selected Gen 3 PC slots are invalid."
            }
            require(importedFile?.absolutePath == file.absolutePath &&
                currentSourceUri == openedSourceUri &&
                currentSourceLabel == openedSourceLabel) {
                "The loaded save identity changed while multi-select was open."
            }
            val fresh = file.readBytes()
            require(fresh.contentEquals(opened) && gen3SaveValid(fresh)) {
                "The save changed or failed validation while multi-select was open."
            }
            val pc = gen3PcBuffer(fresh)
                ?: error("PSE could not reconstruct the fresh Gen 3 PC storage.")
            require(gen3PcBoxNames(pc)[boxIndex] == boxName) {
                "The selected PC box changed after this screen was opened."
            }
            val snapshot = Gen3BoxEditing.snapshotSelectedBoxRecords(
                pc,
                boxIndex,
                selectedSlots
            )
            val pokemon = snapshot.records.mapIndexed { index, raw ->
                parsePk3(raw, 0, false).also { parsed ->
                    require(parsed != null && parsed.checksumValid) {
                        "Selected slot ${snapshot.slots[index] + 1} failed PK3 validation."
                    }
                }!!
            }
            val slotLabels = snapshot.slots.joinToString(", ") {
                (it + 1).toString()
            }
            val names = pokemon.joinToString(", ") {
                if (it.nickname.isNotBlank()) it.nickname else "Species #${it.species}"
            }
            AlertDialog.Builder(this)
                .setTitle("Copy ${snapshot.records.size} Pokémon to PSE Bank?")
                .setMessage(
                    "Box ${boxIndex + 1} • ${boxName}\nSlots: ${slotLabels}\n" +
                        "Pokémon: ${names}\n\nPSE will copy each exact PK3 through " +
                        "temporary files, verify every checksum and identity, then finalize " +
                        "the complete Bank batch. The source save and PC slots stay unchanged. " +
                        "If any file or source check fails, every new Bank file is removed."
                )
                .setNegativeButton("Cancel", null)
                .setPositiveButton("Copy batch") { _, _ ->
                    copySelectedGen3ToBank(
                        file,
                        opened,
                        openedSourceUri,
                        openedSourceLabel,
                        boxIndex,
                        boxName,
                        snapshot.slots
                    )
                }
                .show()
        } catch (error: Exception) {
            showDialog(
                "Copy selected to PSE Bank stopped",
                error.message ?: "The selected Gen 3 batch could not be reviewed."
            )
        }
    }

    private fun copySelectedGen3ToBank(
        file: File,
        opened: ByteArray,
        openedSourceUri: Uri?,
        openedSourceLabel: String?,
        boxIndex: Int,
        boxName: String,
        selectedSlots: List<Int>
    ) {
        val temporaryBankFiles = ArrayList<File>()
        val finalBankFiles = ArrayList<File>()
        try {
            require(selectedSlots.isNotEmpty() &&
                selectedSlots.size == selectedSlots.toSet().size &&
                selectedSlots.all { it in 0 until Gen3SaveState.BOX_CAPACITY }) {
                "The selected Gen 3 PC slots are invalid."
            }
            require(importedFile?.absolutePath == file.absolutePath &&
                currentSourceUri == openedSourceUri &&
                currentSourceLabel == openedSourceLabel) {
                "The loaded save identity changed after review."
            }
            val fresh = file.readBytes()
            require(fresh.contentEquals(opened) && gen3SaveValid(fresh)) {
                "The save changed or failed validation after review."
            }
            val freshPc = gen3PcBuffer(fresh)
                ?: error("PSE could not reconstruct the fresh Gen 3 PC storage.")
            require(gen3PcBoxNames(freshPc)[boxIndex] == boxName) {
                "The selected PC box changed after review."
            }
            val snapshot = Gen3BoxEditing.snapshotSelectedBoxRecords(
                freshPc,
                boxIndex,
                selectedSlots
            )
            val parsed = snapshot.records.mapIndexed { index, raw ->
                val pokemon = parsePk3(raw, 0, false)
                require(pokemon != null && pokemon.checksumValid) {
                    "Selected slot ${snapshot.slots[index] + 1} failed PK3 validation."
                }
                pokemon
            }
            require(file.readBytes().contentEquals(fresh)) {
                "The source save changed before Bank staging. Nothing was copied."
            }

            val stamp = System.currentTimeMillis()
            snapshot.records.forEachIndexed { index, raw ->
                val staged = File.createTempFile(
                    "PSE_G3_COPY_${stamp}_${index}_",
                    ".tmp",
                    bankDir()
                )
                temporaryBankFiles.add(staged)
                staged.writeBytes(raw)
                val verifyRaw = staged.readBytes()
                val verifyPokemon = if (verifyRaw.size == 80) {
                    parsePk3(verifyRaw, 0, false)
                } else {
                    null
                }
                require(verifyRaw.contentEquals(raw) &&
                    verifyPokemon != null &&
                    verifyPokemon.checksumValid &&
                    verifyPokemon.pid == parsed[index].pid &&
                    verifyPokemon.species == parsed[index].species) {
                    "A staged Gen 3 Bank copy failed verification."
                }
            }
            require(file.readBytes().contentEquals(fresh) &&
                importedFile?.absolutePath == file.absolutePath &&
                currentSourceUri == openedSourceUri &&
                currentSourceLabel == openedSourceLabel) {
                "The source save or its identity changed before finalization."
            }

            fun nextBankCopyTarget(index: Int, species: Int): File {
                var suffix = 0
                while (true) {
                    val extra = if (suffix == 0) "" else "_${suffix}"
                    val candidate = File(
                        bankDir(),
                        "${stamp}_copy_${index}_${species}${extra}.pk3"
                    )
                    if (!candidate.exists()) return candidate
                    suffix++
                }
            }
            temporaryBankFiles.forEachIndexed { index, staged ->
                val target = nextBankCopyTarget(index, parsed[index].species)
                finalBankFiles.add(target)
                require(staged.renameTo(target)) {
                    "A staged Gen 3 Bank copy could not be finalized."
                }
                val verifyRaw = target.readBytes()
                val verifyPokemon = if (verifyRaw.size == 80) {
                    parsePk3(verifyRaw, 0, false)
                } else {
                    null
                }
                require(verifyRaw.contentEquals(snapshot.records[index]) &&
                    verifyPokemon != null &&
                    verifyPokemon.checksumValid &&
                    verifyPokemon.pid == parsed[index].pid &&
                    verifyPokemon.species == parsed[index].species) {
                    "A finalized Gen 3 Bank copy failed verification."
                }
            }
            require(finalBankFiles.size == snapshot.records.size &&
                finalBankFiles.indices.all { index ->
                    finalBankFiles[index].readBytes()
                        .contentEquals(snapshot.records[index])
                } &&
                file.readBytes().contentEquals(fresh) &&
                gen3PcBuffer(file.readBytes())?.contentEquals(freshPc) == true) {
                "The final Bank batch or unchanged source did not verify exactly."
            }

            resetGen3BoxSelection()
            Toast.makeText(
                this,
                "${snapshot.records.size} Gen 3 Pokémon copied to PSE Bank; source unchanged",
                Toast.LENGTH_LONG
            ).show()
            bankViewGeneration = 3
            val bankCount = bankDir().listFiles()?.count {
                it.isFile && it.extension.equals("pk3", true)
            } ?: snapshot.records.size
            bankViewBox = ((bankCount - 1).coerceAtLeast(0)) / 30
            showBank()
        } catch (error: Exception) {
            var bankClean = true
            (temporaryBankFiles + finalBankFiles).distinctBy { it.absolutePath }
                .forEach { candidate ->
                    if (candidate.exists() && !runCatching {
                            candidate.delete() && !candidate.exists()
                        }.getOrDefault(false)) {
                        bankClean = false
                    }
                }
            val sourcePreserved = runCatching {
                file.readBytes().contentEquals(opened)
            }.getOrDefault(false)
            val recovery = when {
                sourcePreserved && bankClean ->
                    "The source save stayed unchanged, and no new Bank entry was kept."
                sourcePreserved ->
                    "The source save stayed unchanged, but one or more staged Bank files could not be removed automatically."
                bankClean ->
                    "New Bank files were removed, but the source save changed outside this operation. Reopen it before editing."
                else ->
                    "The source save changed outside this operation and Bank cleanup was incomplete. Review both before editing again."
            }
            showDialog(
                "Gen 3 batch Bank copy failed",
                (error.message ?: "Unknown error") + "\n\n" + recovery
            )
        }
    }

    private fun showGen3SelectedBankDialog(
        file: File,
        opened: ByteArray,
        openedSourceUri: Uri?,
        openedSourceLabel: String?,
        boxIndex: Int,
        boxName: String,
