    private fun depositSelectedGen3ToBank(
        file: File,
        opened: ByteArray,
        openedSourceUri: Uri?,
        openedSourceLabel: String?,
        boxIndex: Int,
        boxName: String,
        selectedSlots: List<Int>
    ) {
        val temporaryBankFiles = ArrayList<File>()
        val finalBankFiles = ArrayList<File>()
        var writeStarted = false
        try {
            require(selectedSlots.isNotEmpty() &&
                selectedSlots.size == selectedSlots.toSet().size &&
                selectedSlots.all { it in 0 until Gen3SaveState.BOX_CAPACITY }) {
                "The selected Gen 3 PC slots are invalid."
            }
            require(importedFile?.absolutePath == file.absolutePath &&
                currentSourceUri == openedSourceUri &&
                currentSourceLabel == openedSourceLabel) {
                "The loaded save identity changed while multi-select was open."
            }
            val fresh = file.readBytes()
            require(fresh.contentEquals(opened)) {
                "The save changed while multi-select was open. Reopen PC Boxes before moving."
            }
            require(gen3SaveValid(fresh)) {
                "The fresh save is no longer a valid Generation 3 save."
            }
            val freshPc = gen3PcBuffer(fresh)
                ?: error("PSE could not reconstruct the fresh Gen 3 PC storage.")
            require(gen3PcBoxNames(freshPc)[boxIndex] == boxName) {
                "The selected PC box changed after this screen was opened."
            }
            val sortedSlots = selectedSlots.sorted()
            val records = Gen3BoxEditing.copySelectedBoxRecords(
                freshPc,
                boxIndex,
                sortedSlots
            )
            val parsed = records.mapIndexed { index, raw ->
                val pokemon = parsePk3(raw, 0, false)
                require(pokemon != null && pokemon.checksumValid) {
                    "Selected slot ${sortedSlots[index] + 1} failed PK3 validation."
                }
                pokemon
            }
            val boxRange = Gen3BoxEditing.boxStorageRange(boxIndex)
            val selectedRanges = sortedSlots.map { slot ->
                val start = boxRange.first + slot * 80
                start until (start + 80)
            }
            val editedPc = Gen3BoxEditing.clearSelectedBoxSlots(
                freshPc,
                boxIndex,
                sortedSlots
            )
            require(selectedRanges.all { range ->
                range.all { editedPc[it] == 0.toByte() }
            }) {
                "A staged source slot was not cleared."
            }
            require(editedPc.indices.all { index ->
                selectedRanges.any { index in it } || editedPc[index] == freshPc[index]
            }) {
                "The staged Bank move changed unrelated PC data."
            }

            val sectionMap = gen3ActiveSectionMap(fresh)
                ?: error("PSE could not map the active Gen 3 PC sections.")
            val work = fresh.copyOf()
            writeGen3PcBuffer(work, editedPc)
            require(gen3SaveValid(work) &&
                gen3PcBuffer(work)?.contentEquals(editedPc) == true) {
                "The staged Gen 3 PC storage failed checksum or byte verification."
            }
            val allowed = HashSet<Int>()
            var pcBase = 0
            for (sectionId in 5..13) {
                val sectionBase = sectionMap[sectionId]
                require(sectionBase >= 0) { "Missing Gen 3 PC section $sectionId." }
                val sectionLength = gen3SectionLengths[sectionId]
                for (localOffset in 0 until sectionLength) {
                    val pcOffset = pcBase + localOffset
                    if (selectedRanges.any { pcOffset in it }) {
                        allowed.add(sectionBase + localOffset)
                    }
                }
                allowed.add(sectionBase + 0xFF6)
                allowed.add(sectionBase + 0xFF7)
                pcBase += sectionLength
            }
            require(work.indices.all { it in allowed || work[it] == fresh[it] }) {
                "The Bank move changed data outside selected slots and PC checksums."
            }

            val backup = File.createTempFile(
                backupGameName(file) + "_PreGen3BankBatch_",
                ".backup",
                backupsDir()
            )
            backup.writeBytes(fresh)
            require(backup.readBytes().contentEquals(fresh)) {
                "The recovery backup did not verify."
            }
            retainGen2ToGen3SafetyBackup(backup, fresh)
            require(importedFile?.absolutePath == file.absolutePath &&
                currentSourceUri == openedSourceUri &&
                currentSourceLabel == openedSourceLabel &&
                file.readBytes().contentEquals(fresh)) {
                "The active save changed before Bank staging. Nothing was changed."
            }

            val stamp = System.currentTimeMillis()
            records.forEachIndexed { index, raw ->
                val staged = File.createTempFile(
                    "PSE_G3_${stamp}_${index}_",
                    ".tmp",
                    bankDir()
                )
                temporaryBankFiles.add(staged)
                staged.writeBytes(raw)
                val verifyRaw = staged.readBytes()
                val verifyPokemon = if (verifyRaw.size == 80) {
                    parsePk3(verifyRaw, 0, false)
                } else {
                    null
                }
                require(verifyRaw.contentEquals(raw) &&
                    verifyPokemon != null &&
                    verifyPokemon.checksumValid &&
                    verifyPokemon.pid == parsed[index].pid &&
                    verifyPokemon.species == parsed[index].species) {
                    "A staged Gen 3 Bank entry failed verification."
                }
            }
            require(file.readBytes().contentEquals(fresh) &&
                importedFile?.absolutePath == file.absolutePath &&
                currentSourceUri == openedSourceUri &&
                currentSourceLabel == openedSourceLabel) {
                "The active save changed before writing. Nothing was changed."
            }

            writeStarted = true
            file.writeBytes(work)
            val persisted = file.readBytes()
            require(persisted.contentEquals(work) && gen3SaveValid(persisted)) {
                "The persisted Gen 3 save failed byte or checksum verification."
            }
            val persistedPc = gen3PcBuffer(persisted)
                ?: error("The persisted Gen 3 PC storage could not be reopened.")
            require(persistedPc.contentEquals(editedPc) &&
                gen3PcBoxNames(persistedPc)[boxIndex] == boxName &&
                selectedRanges.all { range ->
                    range.all { persistedPc[it] == 0.toByte() }
                }) {
                "The selected source slots did not persist as empty."
            }

            fun nextBankTarget(index: Int, species: Int): File {
                var suffix = 0
                while (true) {
                    val extra = if (suffix == 0) "" else "_$suffix"
                    val candidate = File(
                        bankDir(),
                        "${stamp}_${index}_${species}$extra.pk3"
                    )
                    if (!candidate.exists()) return candidate
                    suffix++
                }
            }
            temporaryBankFiles.forEachIndexed { index, staged ->
                val target = nextBankTarget(index, parsed[index].species)
                finalBankFiles.add(target)
                require(staged.renameTo(target)) {
                    "A staged Gen 3 Bank entry could not be finalized."
                }
                val verifyRaw = target.readBytes()
                val verifyPokemon = if (verifyRaw.size == 80) {
                    parsePk3(verifyRaw, 0, false)
                } else {
                    null
                }
                require(verifyRaw.contentEquals(records[index]) &&
                    verifyPokemon != null &&
                    verifyPokemon.checksumValid &&
                    verifyPokemon.pid == parsed[index].pid &&
                    verifyPokemon.species == parsed[index].species) {
                    "A finalized Gen 3 Bank entry failed verification."
                }
            }
            require(finalBankFiles.size == records.size &&
                finalBankFiles.indices.all { index ->
                    finalBankFiles[index].readBytes().contentEquals(records[index])
                }) {
                "The finalized Gen 3 Bank batch did not verify exactly."
            }

            resetGen3BoxSelection()
            Toast.makeText(
                this,
                "${records.size} Gen 3 Pokémon moved to PSE Bank and verified",
                Toast.LENGTH_LONG
            ).show()
            bankViewGeneration = 3
            val bankCount = bankDir().listFiles()?.count {
                it.isFile && it.extension.equals("pk3", true)
            } ?: records.size
            bankViewBox = ((bankCount - 1).coerceAtLeast(0)) / 30
            showBank()
        } catch (error: Exception) {
            val saveRestored = if (writeStarted) {
                runCatching {
                    file.writeBytes(opened)
                    file.readBytes().contentEquals(opened)
                }.getOrDefault(false)
            } else {
                true
            }
            var bankClean = true
            (temporaryBankFiles + finalBankFiles).distinctBy { it.absolutePath }
                .forEach { candidate ->
                    if (candidate.exists() && !runCatching {
                            candidate.delete() && !candidate.exists()
                        }.getOrDefault(false)) {
                        bankClean = false
                    }
                }
            val recovery = when {
                saveRestored && bankClean ->
                    "The original save was preserved or restored, and no new Bank entry was kept."
                saveRestored ->
                    "The original save was restored, but one or more staged Bank files could not be removed automatically."
                bankClean ->
                    "New Bank files were removed, but the original save could not be restored automatically. Use the retained recovery backup."
                else ->
                    "Automatic rollback was incomplete. Use the retained recovery backup and review PSE Bank before editing again."
            }
            showDialog(
                "Gen 3 batch Bank move failed",
                (error.message ?: "Unknown error") + "\n\n" + recovery
            )
        }
    }

    private fun requireGen3MarkingPcSnapshot(
        file: File, opened: ByteArray, sourceUri: Uri?, sourceLabel: String?,
        boxIndex: Int, boxName: String
    ): ByteArray {
        Gen3BoxEditing.boxStorageRange(boxIndex)
        require(importedFile?.absolutePath == file.absolutePath &&
            currentSourceUri == sourceUri && currentSourceLabel == sourceLabel &&
            file.readBytes().contentEquals(opened) && gen3SaveValid(opened)) {
            "The save or its identity changed. Reopen PC Boxes before editing."
        }
        val pc = gen3PcBuffer(opened) ?: error("The Gen 3 PC could not be opened.")
        require(gen3PcBoxNames(pc)[boxIndex] == boxName) { "The selected PC box changed." }
        return pc
    }

    private fun showGen3SelectedMarkingsDialog(
        file: File, opened: ByteArray, sourceUri: Uri?, sourceLabel: String?,
        boxIndex: Int, boxName: String, selectedSlots: List<Int>
    ) {
        try {
            val pc = requireGen3MarkingPcSnapshot(file, opened, sourceUri, sourceLabel, boxIndex, boxName)
            val snapshot = Gen3BoxEditing.snapshotSelectedBoxRecords(pc, boxIndex, selectedSlots)
            val names = listOf("Circle", "Square", "Triangle", "Heart")
            val masks = snapshot.records.map { it[0x1B].toInt() and 15 }
            val common = masks.reduce { first, next -> first and next }
            val checks = names.mapIndexed { index, name ->
                CheckBox(this).apply {
                    text = name
                    setTextColor(TEXT)
                    isChecked = (common and (1 shl index)) != 0
                }
            }
            val form = LinearLayout(this).apply {
                orientation = LinearLayout.VERTICAL
                setPadding(dp(20), dp(8), dp(20), dp(8))
            }
            addMutedLine(form, "Checked markings will replace all four markings on every selected Pokémon. " +
                "Uncheck all four to clear markings. Other Pokémon data stays unchanged.")
            if (masks.distinct().size > 1) {
                addMutedLine(form, "This selection has mixed markings; only shared markings start checked.")
            }
            checks.forEach { form.addView(it) }
            snapshot.records.forEachIndexed { index, raw ->
                val pokemon = parsePk3(raw, 0, false)
                require(pokemon != null && pokemon.checksumValid && (raw[0x13].toInt() and 1) == 0) {
                    "Selected slot ${snapshot.slots[index] + 1} failed PK3 validation."
                }
                val marked = names.indices.filter { (masks[index] and (1 shl it)) != 0 }
                    .map { names[it] }.joinToString(", ").ifBlank { "None" }
                addMutedLine(form, "Slot ${snapshot.slots[index] + 1} • " +
                    "${pokemon.nickname.ifBlank { "Species #${pokemon.species}" }} • $marked")
            }
            var consumed = false
            AlertDialog.Builder(this)
                .setTitle("Edit ${snapshot.slots.size} Pokémon's markings")
                .setView(ScrollView(this).apply { addView(form) })
                .setNegativeButton("Cancel") { _, _ -> consumed = true }
                .setOnCancelListener { consumed = true }
                .setPositiveButton("Review") { _, _ ->
                    if (!consumed) {
                        consumed = true
                        try {
                            val freshPc = requireGen3MarkingPcSnapshot(
                                file, opened, sourceUri, sourceLabel, boxIndex, boxName)
                            val mask = checks.indices.filter { checks[it].isChecked }
                                .fold(0) { value, index -> value or (1 shl index) }
                            Gen3BoxEditing.setSelectedBoxMarkings(freshPc, boxIndex, snapshot.slots, mask)
                            val marked = names.indices.filter { (mask and (1 shl it)) != 0 }
                                .map { names[it] }.joinToString(", ").ifBlank { "None (clear all four)" }
                            var applied = false
                            AlertDialog.Builder(this)
                                .setTitle("Apply markings to ${snapshot.slots.size} Pokémon?")
                                .setMessage("Box ${boxIndex + 1} • $boxName\n" +
                                    "Slots: ${snapshot.slots.joinToString(", ") { (it + 1).toString() }}\n\n" +
                                    "Replace markings with: $marked\n\n" +
                                    "PSE will verify a recovery backup, update only the marking bits, " +
                                    "repair save checksums, reopen and verify the result. " +
                                    "Egg state, encrypted Pokémon data and unselected slots stay unchanged.")
                                .setNegativeButton("Cancel") { _, _ -> applied = true }
                                .setOnCancelListener { applied = true }
                                .setPositiveButton("Apply markings") { _, _ ->
                                    if (!applied) {
                                        applied = true
                                        applyGen3SelectedMarkings(file, opened, sourceUri, sourceLabel,
                                            boxIndex, boxName, snapshot.slots, mask)
                                    }
                                }.show()
                        } catch (error: Exception) {
                            showDialog("Marking edit stopped", error.message ?: "The selection could not be reviewed.")
                        }
                    }
                }.show()
        } catch (error: Exception) {
            showDialog("Marking edit stopped", error.message ?: "The selected Pokémon could not be opened.")
        }
    }

    private fun applyGen3SelectedMarkings(
        file: File, opened: ByteArray, sourceUri: Uri?, sourceLabel: String?,
        boxIndex: Int, boxName: String, selectedSlots: List<Int>, mask: Int
    ) {
        var writeStarted = false
        try {
            val freshPc = requireGen3MarkingPcSnapshot(
                file, opened, sourceUri, sourceLabel, boxIndex, boxName)
            val snapshot = Gen3BoxEditing.snapshotSelectedBoxRecords(freshPc, boxIndex, selectedSlots)
            val editedPc = Gen3BoxEditing.setSelectedBoxMarkings(freshPc, boxIndex, snapshot.slots, mask)
            val boxStart = Gen3BoxEditing.boxStorageRange(boxIndex).first
            val markingOffsets = snapshot.slots.map { boxStart + it * 80 + 0x1B }.toSet()
            require(editedPc.indices.all { it in markingOffsets || editedPc[it] == freshPc[it] }) {
                "The staged marking edit changed unrelated PC bytes."
            }
            snapshot.slots.forEach { slot ->
                val offset = boxStart + slot * 80
                val before = parsePk3(freshPc, offset, false)
                val after = parsePk3(editedPc, offset, false)
                val expected = (freshPc[offset + 0x1B].toInt() and 0xF0) or mask
                require(before != null && before.checksumValid && after != null && after.checksumValid &&
                    after.markingValue == expected && before.isEgg == after.isEgg) {
                    "Selected slot ${slot + 1} failed marking or checksum verification."
                }
            }
            if (editedPc.contentEquals(freshPc)) {
                Toast.makeText(this, "Selected Pokémon already have these markings", Toast.LENGTH_LONG).show()
                return
            }
            val sectionMap = gen3ActiveSectionMap(opened)
                ?: error("The active Gen 3 PC sections could not be mapped.")
            val work = opened.copyOf()
            writeGen3PcBuffer(work, editedPc)
            require(gen3SaveValid(work) && gen3PcBuffer(work)?.contentEquals(editedPc) == true) {
                "The staged save failed checksum or PC byte verification."
            }
            val allowed = HashSet<Int>()
            var pcBase = 0
            for (sectionId in 5..13) {
                val sectionBase = sectionMap[sectionId]
                require(sectionBase >= 0) { "Missing Gen 3 PC section $sectionId." }
                val sectionLength = gen3SectionLengths[sectionId]
                for (local in 0 until sectionLength) {
                    if (pcBase + local in markingOffsets) allowed.add(sectionBase + local)
                }
                allowed.add(sectionBase + 0xFF6)
                allowed.add(sectionBase + 0xFF7)
                pcBase += sectionLength
            }
            require(work.indices.all { it in allowed || work[it] == opened[it] }) {
                "The marking edit changed unrelated save data."
            }
            val backup = File.createTempFile(backupGameName(file) + "_PreGen3Markings_", ".backup", backupsDir())
            backup.writeBytes(opened)
            require(backup.readBytes().contentEquals(opened)) { "The recovery backup did not verify." }
            retainGen2ToGen3SafetyBackup(backup, opened)
            requireGen3MarkingPcSnapshot(file, opened, sourceUri, sourceLabel, boxIndex, boxName)
            writeStarted = true
            file.writeBytes(work)
            val persisted = file.readBytes()
            require(persisted.contentEquals(work) && gen3SaveValid(persisted) &&
                gen3PcBuffer(persisted)?.contentEquals(editedPc) == true) {
                "The persisted markings failed byte, checksum or reopen verification."
            }
            resetGen3BoxSelection()
            Toast.makeText(this, "${snapshot.slots.size} Pokémon's markings saved and verified; backup retained",
                Toast.LENGTH_LONG).show()
            showGen3PokemonViewer("boxes", boxIndex)
        } catch (error: Exception) {
            val restored = if (writeStarted) runCatching {
                file.writeBytes(opened)
                file.readBytes().contentEquals(opened) && gen3SaveValid(file.readBytes())
            }.getOrDefault(false) else false
            val recovery = when {
                !writeStarted -> "Nothing was written."
                restored -> "The original save was restored and verified."
                else -> "Automatic restore could not be verified. Restore the retained backup before editing again."
            }
            showDialog("Gen 3 marking edit failed", (error.message ?: "Unknown error") + "\n\n" + recovery)
        }
    }

