    private fun applyGen3SelectedDelete(
        file: File,
        opened: ByteArray,
        openedSourceUri: Uri?,
        openedSourceLabel: String?,
        boxIndex: Int,
        boxName: String,
        selectedSlots: List<Int>
    ) {
        var writeStarted = false
        try {
            require(selectedSlots.isNotEmpty() &&
                selectedSlots.size == selectedSlots.toSet().size &&
                selectedSlots.all { it in 0 until Gen3SaveState.BOX_CAPACITY }) {
                "The selected Gen 3 PC slots are invalid."
            }
            require(importedFile?.absolutePath == file.absolutePath &&
                currentSourceUri == openedSourceUri &&
                currentSourceLabel == openedSourceLabel) {
                "The loaded save identity changed while multi-select was open."
            }
            val fresh = file.readBytes()
            require(fresh.contentEquals(opened)) {
                "The save changed while multi-select was open. Reopen PC Boxes before deleting."
            }
            require(gen3SaveValid(fresh)) {
                "The fresh save is no longer a valid Generation 3 save."
            }
            val freshPc = gen3PcBuffer(fresh)
                ?: error("PSE could not reconstruct the fresh Gen 3 PC storage.")
            require(gen3PcBoxNames(freshPc)[boxIndex] == boxName) {
                "The selected PC box changed after this screen was opened."
            }
            val boxRange = Gen3BoxEditing.boxStorageRange(boxIndex)
            val selectedRanges = selectedSlots.map { slot ->
                val start = boxRange.first + slot * 80
                start until (start + 80)
            }
            selectedRanges.forEachIndexed { index, range ->
                val raw = freshPc.copyOfRange(range.first, range.last + 1)
                require(raw.any { it != 0.toByte() }) {
                    "Selected slot ${selectedSlots[index] + 1} is now empty."
                }
                val pokemon = parsePk3(freshPc, range.first, false)
                require(pokemon != null && pokemon.checksumValid) {
                    "Selected slot ${selectedSlots[index] + 1} failed PK3 validation."
                }
            }

            val editedPc = Gen3BoxEditing.clearSelectedBoxSlots(
                freshPc,
                boxIndex,
                selectedSlots
            )
            require(selectedRanges.all { range ->
                range.all { editedPc[it] == 0.toByte() }
            }) {
                "A staged selected slot was not cleared."
            }
            require(editedPc.indices.all { index ->
                selectedRanges.any { index in it } || editedPc[index] == freshPc[index]
            }) {
                "The staged multi-delete changed unrelated PC data."
            }

            val sectionMap = gen3ActiveSectionMap(fresh)
                ?: error("PSE could not map the active Gen 3 PC sections.")
            val work = fresh.copyOf()
            writeGen3PcBuffer(work, editedPc)
            require(gen3SaveValid(work) &&
                gen3PcBuffer(work)?.contentEquals(editedPc) == true) {
                "The staged Gen 3 PC storage failed checksum or byte verification."
            }
            val allowed = HashSet<Int>()
            var pcBase = 0
            for (sectionId in 5..13) {
                val sectionBase = sectionMap[sectionId]
                require(sectionBase >= 0) { "Missing Gen 3 PC section $sectionId." }
                val sectionLength = gen3SectionLengths[sectionId]
                for (localOffset in 0 until sectionLength) {
                    val pcOffset = pcBase + localOffset
                    if (selectedRanges.any { pcOffset in it }) {
                        allowed.add(sectionBase + localOffset)
                    }
                }
                allowed.add(sectionBase + 0xFF6)
                allowed.add(sectionBase + 0xFF7)
                pcBase += sectionLength
            }
            require(work.indices.all { it in allowed || work[it] == fresh[it] }) {
                "The multi-delete changed data outside selected slots and PC checksums."
            }

            val backup = File.createTempFile(
                backupGameName(file) + "_PreGen3MultiDelete_",
                ".backup",
                backupsDir()
            )
            backup.writeBytes(fresh)
            require(backup.readBytes().contentEquals(fresh)) {
                "The recovery backup did not verify."
            }
            retainGen2ToGen3SafetyBackup(backup, fresh)
            require(importedFile?.absolutePath == file.absolutePath &&
                currentSourceUri == openedSourceUri &&
                currentSourceLabel == openedSourceLabel &&
                file.readBytes().contentEquals(fresh)) {
                "The active save changed before writing. Nothing was changed."
            }

            writeStarted = true
            file.writeBytes(work)
            val persisted = file.readBytes()
            require(persisted.contentEquals(work) && gen3SaveValid(persisted)) {
                "The persisted Gen 3 save failed byte or checksum verification."
            }
            val persistedPc = gen3PcBuffer(persisted)
                ?: error("The persisted Gen 3 PC storage could not be reopened.")
            require(persistedPc.contentEquals(editedPc) &&
                gen3PcBoxNames(persistedPc)[boxIndex] == boxName &&
                selectedRanges.all { range ->
                    range.all { persistedPc[it] == 0.toByte() }
                } &&
                persistedPc.indices.all { index ->
                    selectedRanges.any { index in it } ||
                        persistedPc[index] == freshPc[index]
                }) {
                "The selected Gen 3 slots did not persist exactly."
            }
            resetGen3BoxSelection()
            Toast.makeText(
                this,
                "${selectedSlots.size} selected Pokémon deleted and verified; recovery backup retained",
                Toast.LENGTH_LONG
            ).show()
            showGen3PokemonViewer("boxes", boxIndex)
        } catch (error: Exception) {
            val restored = if (writeStarted) {
                runCatching {
                    file.writeBytes(opened)
                    file.readBytes().contentEquals(opened)
                }.getOrDefault(false)
            } else {
                false
            }
            val recovery = when {
                !writeStarted -> "Nothing was written."
                restored -> "The original save was restored and verified."
                else -> "Automatic restore could not be verified. Restore the retained backup before editing this save again."
            }
            showDialog(
                "Gen 3 selected delete failed",
                (error.message ?: "Unknown error") + "\n\n" + recovery
            )
        }
    }

    private fun showGen3ClearBoxDialog(
        file: File,
        opened: ByteArray,
        openedSourceUri: Uri?,
        openedSourceLabel: String?,
        boxIndex: Int,
        boxName: String,
        occupiedCount: Int
    ) {
        val confirmation = EditText(this).apply {
            hint = "Type CLEAR"
            setSingleLine(true)
            setTextColor(TEXT)
            setHintTextColor(MUTED)
        }
        AlertDialog.Builder(this)
            .setTitle("Clear $boxName?")
            .setMessage(
                "This will remove $occupiedCount Pokémon from Box ${boxIndex + 1}. " +
                    "The box name will stay unchanged. A verified recovery backup is created first.\n\n" +
                    "Type CLEAR to review and confirm this destructive change."
            )
            .setView(confirmation)
            .setNegativeButton("Cancel", null)
            .setPositiveButton("Clear box") { _, _ ->
                if (confirmation.text.toString().trim() != "CLEAR") {
                    showDialog(
                        "Clear cancelled",
                        "The confirmation text did not exactly match CLEAR. Nothing was written."
                    )
                    return@setPositiveButton
                }
                applyGen3BoxClear(
                    file,
                    opened,
                    openedSourceUri,
                    openedSourceLabel,
                    boxIndex,
                    boxName,
                    occupiedCount
                )
            }
            .show()
    }

    private fun applyGen3BoxClear(
        file: File,
        opened: ByteArray,
        openedSourceUri: Uri?,
        openedSourceLabel: String?,
        boxIndex: Int,
        boxName: String,
        loadedOccupiedCount: Int
    ) {
        var writeStarted = false
        try {
            require(importedFile?.absolutePath == file.absolutePath &&
                currentSourceUri == openedSourceUri &&
                currentSourceLabel == openedSourceLabel) {
                "The loaded save identity changed while the box screen was open."
            }
            val fresh = file.readBytes()
            require(fresh.contentEquals(opened)) {
                "The save changed while the box screen was open. Reopen PC Boxes before clearing."
            }
            require(gen3SaveValid(fresh)) {
                "The fresh save is no longer a valid Generation 3 save."
            }
            val freshPc = gen3PcBuffer(fresh)
                ?: error("PSE could not reconstruct the fresh Gen 3 PC storage.")
            val freshNames = gen3PcBoxNames(freshPc)
            require(freshNames[boxIndex] == boxName) {
                "The selected PC box changed after this screen was opened."
            }
            val freshOccupiedCount = (0 until Gen3SaveState.BOX_CAPACITY).count { slot ->
                val global = boxIndex * Gen3SaveState.BOX_CAPACITY + slot
                parsePk3(freshPc, 4 + global * 80, false) != null
            }
            require(freshOccupiedCount == loadedOccupiedCount && freshOccupiedCount > 0) {
                "The selected box contents changed or the box is already empty."
            }

            val boxRange = Gen3BoxEditing.boxStorageRange(boxIndex)
            val editedPc = Gen3BoxEditing.clearBoxStorage(freshPc, boxIndex)
            require(boxRange.all { editedPc[it] == 0.toByte() }) {
                "The staged box clear left Pokémon data in the selected box."
            }
            require(editedPc.indices.all { it in boxRange || editedPc[it] == freshPc[it] }) {
                "The staged box clear changed unrelated PC data."
            }

            val sectionMap = gen3ActiveSectionMap(fresh)
                ?: error("PSE could not map the active Gen 3 PC sections.")
            val work = fresh.copyOf()
            writeGen3PcBuffer(work, editedPc)
            require(gen3SaveValid(work) &&
                gen3PcBuffer(work)?.contentEquals(editedPc) == true) {
                "The staged Gen 3 PC storage failed checksum or byte verification."
            }
            val allowed = HashSet<Int>()
            var pcBase = 0
            for (sectionId in 5..13) {
                val sectionBase = sectionMap[sectionId]
                require(sectionBase >= 0) { "Missing Gen 3 PC section $sectionId." }
                val sectionLength = gen3SectionLengths[sectionId]
                for (localOffset in 0 until sectionLength) {
                    if (pcBase + localOffset in boxRange) {
                        allowed.add(sectionBase + localOffset)
                    }
                }
                allowed.add(sectionBase + 0xFF6)
                allowed.add(sectionBase + 0xFF7)
                pcBase += sectionLength
            }
            require(work.indices.all { it in allowed || work[it] == fresh[it] }) {
                "The box clear changed data outside the selected box and PC checksums."
            }

            val backup = File.createTempFile(
                backupGameName(file) + "_PreGen3BoxClear_",
                ".backup",
                backupsDir()
            )
            backup.writeBytes(fresh)
            require(backup.readBytes().contentEquals(fresh)) {
                "The recovery backup did not verify."
            }
            retainGen2ToGen3SafetyBackup(backup, fresh)
            require(importedFile?.absolutePath == file.absolutePath &&
                currentSourceUri == openedSourceUri &&
                currentSourceLabel == openedSourceLabel &&
                file.readBytes().contentEquals(fresh)) {
                "The active save changed before writing. Nothing was changed."
            }

            writeStarted = true
            file.writeBytes(work)
            val persisted = file.readBytes()
            require(persisted.contentEquals(work) && gen3SaveValid(persisted)) {
                "The persisted Gen 3 save failed byte or checksum verification."
            }
            val persistedPc = gen3PcBuffer(persisted)
                ?: error("The persisted Gen 3 PC storage could not be reopened.")
            require(persistedPc.contentEquals(editedPc) &&
                gen3PcBoxNames(persistedPc)[boxIndex] == boxName &&
                boxRange.all { persistedPc[it] == 0.toByte() }) {
                "The cleared Gen 3 box did not persist exactly."
            }
            Toast.makeText(
                this,
                "$boxName cleared and verified; recovery backup retained",
                Toast.LENGTH_LONG
            ).show()
            showGen3PokemonViewer("boxes", boxIndex)
        } catch (error: Exception) {
            val restored = if (writeStarted) {
                runCatching {
                    file.writeBytes(opened)
                    file.readBytes().contentEquals(opened)
                }.getOrDefault(false)
            } else {
                false
            }
            val recovery = when {
                !writeStarted -> "Nothing was written."
                restored -> "The original save was restored and verified."
                else -> "Automatic restore could not be verified. Restore the retained backup before editing this save again."
            }
            showDialog(
                "Gen 3 box clear failed",
                (error.message ?: "Unknown error") + "\n\n" + recovery
            )
        }
    }

    private fun gen3PcBoxNames(pc: ByteArray): List<String> {
        require(pc.size >= 0x83C2) { "Gen 3 PC storage is too short for box names." }
        return List(Gen3SaveState.BOX_COUNT) { index ->
            readGen3Text(pc, 0x8344 + index * 9, 9)
                .ifBlank { "Box ${index + 1}" }
        }
    }

    private fun showGen3BoxRenameDialog(
        file: File,
        opened: ByteArray,
        openedSourceUri: Uri?,
        openedSourceLabel: String?,
        boxIndex: Int,
        boxNames: List<String>
    ) {
        val input = EditText(this).apply {
            setText(boxNames[boxIndex])
            hint = "Box name (1–8 characters)"
            setSingleLine(true)
            setTextColor(TEXT)
            setHintTextColor(MUTED)
            setSelectAllOnFocus(true)
        }
        AlertDialog.Builder(this)
            .setTitle("Rename Box ${boxIndex + 1}")
            .setMessage("Use 1–8 supported Gen 3 characters. Pokémon in the box are not changed.")
            .setView(input)
            .setNegativeButton("Cancel", null)
            .setPositiveButton("Review") { _, _ ->
                val renamed = runCatching {
                    Gen3BoxEditing.renameBoxNames(
                        boxNames,
                        boxIndex,
                        input.text.toString()
                    )
                }.getOrElse { error ->
                    showDialog(
                        "Invalid Gen 3 box name",
                        error.message ?: "The requested box name is invalid."
                    )
                    return@setPositiveButton
                }
                if (renamed[boxIndex] == boxNames[boxIndex]) {
                    showDialog("Rename Gen 3 box", "The box name is unchanged, so nothing was written.")
                    return@setPositiveButton
                }
                AlertDialog.Builder(this)
                    .setTitle("Save reviewed box name?")
                    .setMessage(
                        "Box ${boxIndex + 1}: ${boxNames[boxIndex]} → ${renamed[boxIndex]}\n\n" +
                            "PSE will back up the save, update only this PC box name and PC section checksums, then reopen and verify it."
                    )
                    .setNegativeButton("Cancel", null)
                    .setPositiveButton("Save") { _, _ ->
                        applyGen3BoxRename(
                            file,
                            opened,
                            openedSourceUri,
                            openedSourceLabel,
                            boxIndex,
                            boxNames,
                            renamed
                        )
                    }
                    .show()
            }
            .show()
    }

    private fun applyGen3BoxRename(
        file: File,
        opened: ByteArray,
        openedSourceUri: Uri?,
        openedSourceLabel: String?,
        boxIndex: Int,
        loadedBoxNames: List<String>,
        renamedBoxNames: List<String>
    ) {
        var writeStarted = false
        try {
            require(importedFile?.absolutePath == file.absolutePath &&
                currentSourceUri == openedSourceUri &&
                currentSourceLabel == openedSourceLabel) {
                "The loaded save identity changed while the box screen was open."
            }
            val fresh = file.readBytes()
            require(fresh.contentEquals(opened)) {
                "The save changed while the box screen was open. Reopen PC Boxes before renaming."
            }
            require(gen3SaveValid(fresh)) {
                "The fresh save is no longer a valid Generation 3 save."
            }
            val freshPc = gen3PcBuffer(fresh)
                ?: error("PSE could not reconstruct the fresh Gen 3 PC storage.")
            require(gen3PcBoxNames(freshPc) == loadedBoxNames) {
                "The PC box names changed after this screen was opened."
            }
            val expectedName = renamedBoxNames[boxIndex]
            val nameOffset = 0x8344 + boxIndex * 9
            val nameRange = nameOffset until (nameOffset + 9)
            val editedPc = freshPc.copyOf()
            writeGen3Text(editedPc, nameOffset, 9, expectedName)
            require(readGen3Text(editedPc, nameOffset, 9) == expectedName) {
                "The staged Gen 3 box name did not encode exactly."
            }
            require(editedPc.indices.all { it in nameRange || editedPc[it] == freshPc[it] }) {
                "The staged box rename changed unrelated PC data."
            }

            val sectionMap = gen3ActiveSectionMap(fresh)
                ?: error("PSE could not map the active Gen 3 PC sections.")
            val work = fresh.copyOf()
            writeGen3PcBuffer(work, editedPc)
            require(gen3SaveValid(work) &&
                gen3PcBuffer(work)?.contentEquals(editedPc) == true) {
                "The staged Gen 3 PC storage failed checksum or byte verification."
            }
            val allowed = HashSet<Int>()
            var pcBase = 0
            for (sectionId in 5..13) {
                val sectionBase = sectionMap[sectionId]
                require(sectionBase >= 0) { "Missing Gen 3 PC section $sectionId." }
                val sectionLength = gen3SectionLengths[sectionId]
                for (localOffset in 0 until sectionLength) {
                    if (pcBase + localOffset in nameRange) {
                        allowed.add(sectionBase + localOffset)
                    }
                }
                allowed.add(sectionBase + 0xFF6)
                allowed.add(sectionBase + 0xFF7)
                pcBase += sectionLength
            }
            require(work.indices.all { it in allowed || work[it] == fresh[it] }) {
                "The box rename changed data outside the selected name and PC checksums."
            }

            val backup = File.createTempFile(
                backupGameName(file) + "_PreGen3BoxName_",
                ".backup",
                backupsDir()
            )
            backup.writeBytes(fresh)
            require(backup.readBytes().contentEquals(fresh)) {
                "The recovery backup did not verify."
            }
            retainGen2ToGen3SafetyBackup(backup, fresh)
            require(importedFile?.absolutePath == file.absolutePath &&
                currentSourceUri == openedSourceUri &&
                currentSourceLabel == openedSourceLabel &&
                file.readBytes().contentEquals(fresh)) {
                "The active save changed before writing. Nothing was changed."
            }

            writeStarted = true
            file.writeBytes(work)
            val persisted = file.readBytes()
            require(persisted.contentEquals(work) && gen3SaveValid(persisted)) {
                "The persisted Gen 3 save failed byte or checksum verification."
            }
            val persistedPc = gen3PcBuffer(persisted)
                ?: error("The persisted Gen 3 PC storage could not be reopened.")
            require(persistedPc.contentEquals(editedPc) &&
                gen3PcBoxNames(persistedPc) == renamedBoxNames) {
                "The renamed Gen 3 box did not persist exactly."
            }
            Toast.makeText(this, "Gen 3 box renamed and verified", Toast.LENGTH_LONG).show()
            showGen3PokemonViewer("boxes", boxIndex)
        } catch (error: Exception) {
            val restored = if (writeStarted) {
                runCatching {
                    file.writeBytes(opened)
                    file.readBytes().contentEquals(opened)
                }.getOrDefault(false)
            } else {
                false
            }
            val recovery = when {
                !writeStarted -> "Nothing was written."
                restored -> "The original save was restored and verified."
                else -> "Automatic restore could not be verified. Restore the retained backup before editing this save again."
            }
            showDialog(
                "Gen 3 box rename failed",
                (error.message ?: "Unknown error") + "\n\n" + recovery
            )
        }
    }

