    private fun pokemonRow(location: String, p: PokemonEntry): LinearLayout {
        return LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.CENTER_VERTICAL
            setPadding(dp(10), dp(8), dp(12), dp(8))
            setBackgroundColor(CARD)
            isClickable = true
            isFocusable = true
            setOnClickListener { showPokemonDetails(location, p) }

            val sprite = ImageView(this@MainActivity).apply {
                scaleType = ImageView.ScaleType.CENTER_INSIDE
                contentDescription = p.nickname
                setPadding(dp(2), dp(2), dp(6), dp(2))
            }
            addView(sprite, LinearLayout.LayoutParams(dp(72), dp(72)))
            loadPokemonSprite(sprite, p.species, p.shiny)

            val textColumn = LinearLayout(this@MainActivity).apply {
                orientation = LinearLayout.VERTICAL
            }
            textColumn.addView(TextView(this@MainActivity).apply {
                text = location
                textSize = 12f
                typeface = Typeface.DEFAULT_BOLD
                setTextColor(Color.rgb(130, 200, 255))
            })
            textColumn.addView(TextView(this@MainActivity).apply {
                val name = p.nickname.ifBlank { "Species #${p.species}" }
                val levelText = p.level?.let { " • Lv $it" } ?: ""
                text = "$name • #${p.species}$levelText" + if (!p.checksumValid) " • checksum warning" else ""
                textSize = 16f
                typeface = Typeface.DEFAULT_BOLD
                setTextColor(TEXT)
                setPadding(0, 3, 0, 0)
            })
            textColumn.addView(TextView(this@MainActivity).apply {
                text = if (p.shiny) "✨ Shiny • Tap for details" else "Tap for details"
                textSize = 11f
                setTextColor(MUTED)
                setPadding(0, 4, 0, 0)
            })
            addView(textColumn, LinearLayout.LayoutParams(0, -2, 1f))

            addView(TextView(this@MainActivity).apply {
                text = "›"
                textSize = 28f
                setTextColor(MUTED)
                gravity = Gravity.CENTER
            }, LinearLayout.LayoutParams(dp(30), -1))
        }.also { view ->
            view.layoutParams = LinearLayout.LayoutParams(-1, -2).apply { bottomMargin = dp(7) }
        }
    }

    private fun emptyPokemonRow(location: String): LinearLayout {
        return LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.CENTER_VERTICAL
            setPadding(dp(16), dp(12), dp(16), dp(12))
            setBackgroundColor(Color.rgb(27, 27, 27))
            addView(TextView(this@MainActivity).apply {
                text = "○"
                textSize = 28f
                setTextColor(Color.rgb(100, 100, 100))
                gravity = Gravity.CENTER
            }, LinearLayout.LayoutParams(dp(56), dp(56)))
            val col = LinearLayout(this@MainActivity).apply { orientation = LinearLayout.VERTICAL }
            col.addView(TextView(this@MainActivity).apply {
                text = location
                textSize = 12f
                setTextColor(Color.rgb(120, 120, 120))
                typeface = Typeface.DEFAULT_BOLD
            })
            col.addView(TextView(this@MainActivity).apply {
                text = "Empty"
                textSize = 15f
                setTextColor(Color.rgb(120, 120, 120))
            })
            addView(col, LinearLayout.LayoutParams(0, -2, 1f))
        }.also { view ->
            view.layoutParams = LinearLayout.LayoutParams(-1, -2).apply { bottomMargin = dp(7) }
        }
    }


    private fun boxGridCell(boxIndex: Int, slot: Int, p: PokemonEntry?, global: Int, multiSelect: Boolean, selected: Boolean): LinearLayout {
        val cellWidth = ((resources.displayMetrics.widthPixels - dp(44)) / 6).coerceAtLeast(dp(50))
        return LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            gravity = Gravity.CENTER
            setPadding(dp(2), dp(3), dp(2), dp(3))
            background = roundedBg(if (selected) Color.rgb(12, 116, 171) else if (p == null) Color.rgb(11, 27, 38) else CARD, if (selected) Color.rgb(70, 190, 255) else Color.rgb(25, 55, 72), 10)
            layoutParams = GridLayout.LayoutParams().apply {
                width = cellWidth
                height = dp(112)
                setMargins(dp(1), dp(1), dp(1), dp(1))
            }

            if (p != null) {
                isClickable = true
                isFocusable = true
                setOnClickListener {
                    if (multiSelect) {
                        if (selectedPokemonSlots.contains(global)) selectedPokemonSlots.remove(global) else selectedPokemonSlots.add(global)
                        showPokemonViewer("boxes", boxIndex)
                    } else {
                        showPokemonDetails("Box ${boxIndex + 1} • Slot ${slot + 1}", p)
                    }
                }
                if (multiSelect) {
                    addView(TextView(this@MainActivity).apply {
                        text = if (selected) "☑" else "☐"
                        textSize = 13f
                        gravity = Gravity.CENTER
                        setTextColor(if (selected) Color.WHITE else MUTED)
                    }, LinearLayout.LayoutParams(-1, dp(18)))
                }
                val sprite = ImageView(this@MainActivity).apply {
                    scaleType = ImageView.ScaleType.FIT_CENTER
                    contentDescription = p.nickname
                }
                addView(sprite, LinearLayout.LayoutParams(dp(52), if (multiSelect) dp(30) else dp(46)))
                loadPokemonSprite(sprite, p.species, p.shiny)

                addView(TextView(this@MainActivity).apply {
                    text = p.nickname.ifBlank { "Pokémon #${p.species}" }
                    textSize = 9f
                    maxLines = 1
                    ellipsize = android.text.TextUtils.TruncateAt.END
                    gravity = Gravity.CENTER
                    setTextColor(TEXT)
                    typeface = Typeface.DEFAULT_BOLD
                }, LinearLayout.LayoutParams(-1, dp(17)))

                val levelText = TextView(this@MainActivity).apply {
                    text = "Lv …"
                    textSize = 9f
                    gravity = Gravity.CENTER
                    setTextColor(MUTED)
                }
                addView(levelText, LinearLayout.LayoutParams(-1, if (multiSelect) dp(14) else dp(18)))
                resolveBoxedLevelAsync(p.species, p.experience) { level ->
                    levelText.text = level?.let { "Lv $it" } ?: "Lv ?"
                }
            } else {
                addView(TextView(this@MainActivity).apply {
                    text = "○"
                    textSize = 24f
                    gravity = Gravity.CENTER
                    setTextColor(Color.rgb(80, 80, 80))
                }, LinearLayout.LayoutParams(dp(52), dp(66)))
            }

            addView(TextView(this@MainActivity).apply {
                text = (slot + 1).toString()
                textSize = 10f
                gravity = Gravity.CENTER
                setTextColor(if (p == null) Color.rgb(100, 100, 100) else MUTED)
            })
        }
    }

    private fun showPokemonDetails(location: String, p: PokemonEntry) {
        val detailGen = importedFile?.let { generationForSize(it.length().toInt()) } ?: 0
        val speciesLabel = if(detailGen==3) canonicalGen3SpeciesName(p.species)?: "Species #${p.species}" else "Species #${p.species}"
        val displaySpeciesName = p.nickname.ifBlank { speciesLabel }
        val phoneBackGlobal = boxedLocationToGlobalIndex(location)
        val phoneBackBox = phoneBackGlobal?.div(30) ?: 0
        phoneBackAction = { showPokemonViewer(if (phoneBackGlobal != null) "boxes" else "party", phoneBackBox) }
        val scroll = ScrollView(this).apply { setBackgroundColor(BG) }
        val root = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(dp(16), dp(58), dp(16), dp(28))
            setBackgroundColor(BG)
        }
        scroll.addView(root)

        root.addView(TextView(this).apply {
            text = displaySpeciesName
            textSize = 28f
            typeface = Typeface.DEFAULT_BOLD
            setTextColor(TEXT)
        })
        root.addView(TextView(this).apply {
            text = "$location • $speciesLabel"
            textSize = 14f
            setTextColor(MUTED)
            setPadding(0, 4, 0, 16)
        })
        val detailGlobal = boxedLocationToGlobalIndex(location)
        val detailBox = detailGlobal?.div(30) ?: 0
        addButton(root, "←  Back to My Pokémon") { showPokemonViewer(if (detailGlobal != null) "boxes" else "party", detailBox) }
        if (detailGen == 5) {
            addButton(root, "✓  Deep Legality Check") { checkGen5PokemonLegality(location, p) }
            addButton(root, "✏️  Edit Pokémon") { showGen5PokemonEditor(location,p) }
            if (detailGlobal != null && detailGlobal < 24*30) addButton(root, "🏦  Move to PSE Bank") { confirmGen5DepositToBank(location,p) }
            addMutedLine(root, "Gen 5 boxed PK5 editing and PSE Bank deposit are enabled. Bank deposits preserve the exact PK5 before clearing the source slot, rebuild native box/checksum-table CRCs, retain a verified recovery backup and roll both sides back on failure. Default-form Party Pokémon support the editor; party Bank deposits remain locked.")
        } else if (detailGen == 4) {
            fun gen4LockedAction(name:String){ showDialog(name, "This Gen 4 action is still safety-locked. Boxed editing, Duplicate, Delete, PSE Bank and Deep Legality are enabled; party writes remain locked for now.") }
            addButton(root, "✓  Deep Legality Check") { checkGen4PokemonLegality(location, p) }
            if (detailGlobal != null && detailGlobal < 18*30) addButton(root, "✏️  Edit Pokémon") { showGen4PokemonEditor(location, p) } else addButton(root, "✏️  Edit Pokémon") { gen4LockedAction("Edit Pokémon") }
            if (detailGlobal != null && detailGlobal < 18*30) addButton(root, "📑  Duplicate Pokémon") { chooseGen4DuplicateDestination(location, p) } else addButton(root, "📑  Duplicate Pokémon") { gen4LockedAction("Duplicate Pokémon") }
            if (detailGlobal != null && detailGlobal < 18*30) addButton(root, "🏦  Move to PSE Bank") { confirmGen4DepositToBank(location, p) } else addButton(root, "🏦  Move to PSE Bank") { gen4LockedAction("PSE Bank") }
            if (detailGlobal != null && detailGlobal < 18*30) addButton(root, "🗑️  Delete Pokémon") { confirmGen4Delete(location, p) } else addButton(root, "🗑️  Delete Pokémon") { gen4LockedAction("Delete Pokémon") }
            addMutedLine(root, "Gen 4 Stage 7: boxed PK4 editing (including named move selection), Duplicate, Delete, PSE Bank deposit/withdraw, Gen 4 → Gen 7 transfer and Deep Legality Check are enabled. Party writes remain locked for now.")
        } else if (detailGen == 3) {
            fun gen3LockedAction(name: String) {
                showDialog(name, "This Gen 3 action is still safety-locked for party Pokémon. Party duplication, party-position swapping, HP/status recovery, PC-to-party movement, Party-to-PC movement, verified Party removal, boxed editing, Duplicate, Delete, PSE Bank and Deep Legality are enabled.")
            }
            addButton(root, "✓  Deep Legality Check") { checkGen3PokemonLegality(location, p) }
            addButton(root, "✏️  Edit Pokémon") { showGen3PokemonEditor(location, p) }
            val contestFile = importedFile
            val contestSourceUri = currentSourceUri
            val contestSourceLabel = currentSourceLabel
            val contestOpened = contestFile?.let { runCatching { it.readBytes() }.getOrNull() }
            addButton(root, "🏅  Contest condition & sheen") {
                if (contestFile != null && contestOpened != null) {
                    showGen3ContestEditor(contestFile, contestOpened, contestSourceUri,
                        contestSourceLabel, location, p)
                } else {
                    showDialog("Condition edit stopped", "The selected save could not be read. Reopen this Pokémon.")
                }
            }
            addButton(root, "🏅  Contest ribbons") {
                if (contestFile != null && contestOpened != null) {
                    showGen3ContestRibbonEditor(contestFile, contestOpened, contestSourceUri,
                        contestSourceLabel, location, p)
                } else {
                    showDialog("Ribbon edit stopped", "The selected save could not be read. Reopen this Pokémon.")
                }
            }
            addButton(root, "🏅  Achievement ribbons") {
                if (contestFile != null && contestOpened != null) {
                    showGen3AchievementRibbonEditor(contestFile, contestOpened, contestSourceUri,
                        contestSourceLabel, location, p)
                } else {
                    showDialog("Ribbon edit stopped", "The selected save could not be read. Reopen this Pokémon.")
                }
            }
            addButton(root, "🦠  Pokérus strain & days") {
                if (contestFile != null && contestOpened != null) {
                    showGen3PokerusEditor(contestFile, contestOpened, contestSourceUri,
                        contestSourceLabel, location, p)
                } else {
                    showDialog("Pokérus edit stopped", "The selected save could not be read. Reopen this Pokémon.")
                }
            }
            addButton(root, "📍  Capture metadata") {
                if (contestFile != null && contestOpened != null) {
                    showGen3CaptureEditor(contestFile, contestOpened, contestSourceUri,
                        contestSourceLabel, location, p)
                } else {
                    showDialog("Capture edit stopped", "The selected save could not be read. Reopen this Pokémon.")
                }
            }
            addButton(root, "📍  Met location") {
                if (contestFile != null && contestOpened != null) {
                    showGen3MetLocationEditor(contestFile, contestOpened, contestSourceUri,
                        contestSourceLabel, location, p)
                } else {
                    showDialog("Met location unavailable", "The selected save could not be read. Reopen this Pokémon.")
                }
            }
            addButton(root, "🔋  Move PP Ups") {
                if (contestFile != null && contestOpened != null) {
                    showGen3PpUpEditor(contestFile, contestOpened, contestSourceUri,
                        contestSourceLabel, location, p)
                } else {
                    showDialog("PP Up edit stopped", "The selected save could not be read. Reopen this Pokémon.")
                }
            }
            addButton(root, "↕  Reorder moves") {
                if (contestFile != null && contestOpened != null) {
                    showGen3MoveOrderEditor(contestFile, contestOpened, contestSourceUri,
                        contestSourceLabel, location, p)
                } else {
                    showDialog("Move reorder stopped", "The selected save could not be read. Reopen this Pokémon.")
                }
            }
            addButton(root, "−  Forget a move") {
                if (contestFile != null && contestOpened != null) {
                    showGen3ForgetMoveEditor(contestFile, contestOpened, contestSourceUri,
                        contestSourceLabel, location, p)
                } else {
                    showDialog("Move forgetting stopped", "The selected save could not be read. Reopen this Pokémon.")
                }
            }
            addButton(root, "🔋  Restore move PP") {
                if (contestFile != null && contestOpened != null) {
                    showGen3RestorePpReview(contestFile, contestOpened, contestSourceUri,
                        contestSourceLabel, location, p)
                } else {
                    showDialog("PP restoration stopped", "The selected save could not be read. Reopen this Pokémon.")
                }
            }
            if (detailGlobal != null) {
                addButton(root, "👥  Move to Party") { confirmGen3PcToParty(location, p) }
                addButton(root, "📑  Duplicate Pokémon") { chooseGen3DuplicateDestination(location, p) }
                addButton(root, "↪  Move to another PC box") {
                    chooseGen3MoveDestination(location, p)
                }
                addButton(root, "↕  Reorder within this PC box") {
                    chooseGen3ReorderSlot(location, p)
                }
                addButton(root, "⇄  Swap within this PC box") {
                    chooseGen3SwapSlot(location, p)
                }
            } else {
                addButton(root, "📑  Duplicate Party Pokémon") {
                    confirmGen3PartyDuplicate(location, p)
                }
                addButton(root, "⇄  Swap Party Positions") {
                    chooseGen3PartySwapDestination(location, p)
                }
                addButton(root, "💚  Current HP") {
                    if (contestFile != null && contestOpened != null) {
                        showGen3PartyHpEditor(contestFile, contestOpened, contestSourceUri,
                            contestSourceLabel, location, p)
                    } else {
                        showDialog("Current HP unavailable", "The selected save could not be read. Reopen this Pokémon.")
                    }
                }
                addButton(root, "🩺  Status condition") {
                    if (contestFile != null && contestOpened != null) {
                        showGen3PartyStatusEditor(contestFile, contestOpened, contestSourceUri,
                            contestSourceLabel, location, p)
                    } else {
                        showDialog("Party status unavailable", "The selected save could not be read. Reopen this Pokémon.")
                    }
                }
                addButton(root, "💚  Restore HP & Status") {
                    confirmGen3PartyRecovery(location, p)
                }
                addButton(root, "📦  Move Party Pokémon to PC") {
                    chooseGen3PartyMoveDestination(location, p)
                }
            }
            addButton(root, "🏦  Move to PSE Bank") { confirmGen3DepositToBank(location, p) }
            if (detailGlobal != null) {
                addButton(root, "🗑️  Delete Pokémon") { confirmGen3Delete(location, p) }
                addMutedLine(root, "Delete clears only this Gen 3 PC slot in PSE's working copy. PSE rebuilds the affected PC sections and verifies the complete active save before keeping the change.")
            } else {
                addButton(root, "🗑️  Remove from Party") {
                    confirmGen3PartyDelete(location, p)
                }
            }
            addMutedLine(root, "Gen 3 boxed Pokémon editing now includes named move selection, Duplicate, movement between boxes, same-box reordering and occupied-slot swapping, Delete, exact Party duplication, party-position swapping, HP/status recovery, PC-to-party movement, party-to-PC movement and guarded Party removal, PSE Bank deposit/withdraw and Deep Legality Check with exact PK3 preservation, full section-checksum verification and automatic rollback.")
        } else if (location.startsWith("Box ") && detailGen != 3) {
            addButton(root, "✓  Deep Legality Check") { checkPokemonLegality(location, p) }
            if (detailGlobal != null && detailGen in setOf(6,7)) addButton(root, "⬆️  Evolve Pokémon") {
                if (detailGen == 7) prepareGen7Evolution(location, detailGlobal, p) else prepareGen6Evolution(location, detailGlobal, p)
            }
            addButton(root, "✏️  Edit Pokémon") { showPokemonEditor(location, p) }
            addButton(root, "📑  Duplicate Pokémon") { chooseDuplicateDestination(location, p) }
            addButton(root, "🏦  Move to PSE Bank") { confirmDepositToBank(location, p) }
            if (detailGlobal != null) {
                addButton(root, "🗑️  Delete Pokémon") { confirmDeletePokemon(location, detailGlobal, p) }
                addMutedLine(root, "Delete clears this PC slot only in PSE's working copy. The emulator save is unchanged until Save & Replace Current Save.")
            }
        } else if (detailGen != 3) {
            val partySlot = partyLocationToSlot(location)
            if (partySlot != null) {
                addButton(root, "✓  Deep Legality Check") { checkPokemonLegality(location, p) }
                addButton(root, "✏️  Edit Party Pokémon") { showPartyPokemonEditor(location, partySlot, p) }
                addButton(root, "📦  Move to PC") { confirmMovePartyPokemonToPc(location, partySlot, p) }
                addButton(root, "🗑️  Remove from Party") { confirmDeletePartyPokemon(location, partySlot, p) }
                addMutedLine(root, "Party operations change only PSE's working copy. PSE compacts the party, updates the party count, rebuilds the party save-block checksum and verifies the result before keeping it.")
            }
        }

        val spriteCard = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            gravity = Gravity.CENTER
            setPadding(dp(12), dp(12), dp(12), dp(12))
            background = roundedBg(CARD, Color.rgb(20, 95, 135), 16)
        }
        val largeSprite = ImageView(this).apply {
            scaleType = ImageView.ScaleType.FIT_CENTER
            adjustViewBounds = true
            contentDescription = p.nickname
        }
        spriteCard.addView(largeSprite, LinearLayout.LayoutParams(-1, dp(250)))
        if (detailGen == 3) loadGen3Artwork(largeSprite, p.species, p.shiny) else loadPokemonSprite(largeSprite, p.species, p.shiny)
        spriteCard.addView(TextView(this).apply {
            text = if (p.shiny) "✨ Shiny $displaySpeciesName" else displaySpeciesName
            textSize = 20f
            typeface = Typeface.DEFAULT_BOLD
            gravity = Gravity.CENTER
            setTextColor(TEXT)
        })
        root.addView(spriteCard, LinearLayout.LayoutParams(-1, -2).apply { topMargin = dp(8); bottomMargin = dp(8) })

        addDetailSection(root, "IDENTITY")
        addDetailLine(root, "Pokémon format", when(detailGen){3->"PK3 (Generation 3)";4->"PK4 (Generation 4)";5->"PK5 (Generation 5)";7->"PK7 (Generation 7)";else->"PK6 (Generation 6)"})
        addDetailLine(root, "Species", if(detailGen==3) "$speciesLabel (#${p.species})" else "#${p.species}")
        addDetailLine(root, "Nickname", p.nickname.ifBlank { "(blank)" })
        val nicknamedLine = addDetailLineView(root, "Nicknamed", if (detailGen == 3) gen3NicknamedStatus(p) else if (p.isNicknamed) "Yes" else "No")
        if (p.level != null) {
            addDetailLine(root, "Level", p.level.toString())
        } else {
            val levelLine = addDetailLineView(root, "Level", "Calculating…")
            resolveBoxedLevelAsync(p.species, p.experience) { level ->
                levelLine.text = "Level: ${level?.toString() ?: "Unknown"}"
            }
        }
        val genderLine = addDetailLineView(root, "Gender", if (detailGen == 3) canonicalGen3GenderRate(p.species)?.let { pokemonGenderName(gen3TransferGender(p,it)) } ?: "Unknown" else pokemonGenderName(p.gender))
        addDetailLine(root, "Nature", natureName(p.nature) + " (#${p.nature})")
        addDetailLine(root, "Form", p.form.toString())
        addDetailLine(root, "Shiny", if (p.shiny) "Yes ✨" else "No")
        addDetailLine(root, "Egg", if (p.isEgg) "Yes" else "No")
        addDetailLine(root, when(detailGen){3->"PK3 checksum";4->"PK4 checksum";5->"PK5 checksum";7->"PK7 checksum";else->"PK6 checksum"}, if (p.checksumValid) "PASS" else "WARNING")

        addDetailSection(root, "TRAINER / GROWTH")
        addDetailLine(root, "Original Trainer", p.otName.ifBlank { "(blank)" })
        addDetailLine(root, "TID", p.tid.toString().padStart(5, '0'))
        addDetailLine(root, "SID", p.sid.toString().padStart(5, '0'))
        addDetailLine(root, "Experience", String.format(Locale.US, "%,d", p.experience))
        addDetailLine(root, "PID", String.format(Locale.US, "%08X", p.pid))
        addDetailLine(root, "Friendship", p.friendship.toString())
        addDetailLine(root, "Language", pokemonLanguageName(p.language))

        if (detailGen == 3) {
            addDetailSection(root, "GEN 3 ORIGIN / ENCOUNTER")
            addDetailLine(root, "Origin game", gen3OriginGameName(p.originGame))
            addDetailLine(root, "Met level", if (p.metLevel > 0) p.metLevel.toString() else "Unknown")
            addDetailLine(root, "Met location", if (p.metLocation == 0) "None / unknown" else "Location #${p.metLocation}")
            addDetailLine(root, "Poké Ball", gen3BallName(p.ball))
            addDetailLine(root, "OT gender", if (p.otGender == 0) "Male" else "Female")
        }

        if (detailGen == 5) {
            addDetailSection(root, "GEN 5 ORIGIN / ENCOUNTER")
            addDetailLine(root, "Origin game", gen5OriginGameName(p.originGame))
            addDetailLine(root, "Met level", if (p.metLevel > 0) p.metLevel.toString() else "Unknown / transferred")
            addDetailLine(root, "Met location", if (p.metLocation == 0) "None / unknown" else "Location #${p.metLocation}")
            addDetailLine(root, "Met date", formatPokemonDate(p.metYear, p.metMonth, p.metDay))
            addDetailLine(root, "Poké Ball", gen5BallName(p.ball))
            addDetailLine(root, "OT gender", if (p.otGender == 0) "Male" else "Female")
            addDetailLine(root, "Fateful encounter", if (p.fatefulEncounter) "Yes" else "No")
            addDetailLine(root, "Egg location", if (p.eggLocation == 0) "None" else "Location #${p.eggLocation}")
            addDetailLine(root, "Egg received date", formatPokemonDate(p.eggYear, p.eggMonth, p.eggDay))
        }

        addDetailSection(root, "ABILITY / ITEM")
        if(detailGen==3) addDetailLine(root,"Ability",canonicalGen3AbilityLabel(p.species,p.abilityNumber)?:"Unknown Gen 3 ability (slot ${p.abilityNumber})") else addResolvedApiLine(root, "Ability", "ability", p.ability, "Ability #${p.ability}")
        addDetailLine(root, "Ability slot", abilitySlotName(p.abilityNumber))
        if (p.heldItem == 0) addDetailLine(root, "Held item", "None")
        else addResolvedApiLine(root, "Held item", "item", p.heldItem, "Item #${p.heldItem}")

        addDetailSection(root, "MOVES")
        for (i in 0..3) {
            val move = p.moves[i]
            if (move == 0) addDetailLine(root, "Move ${i + 1}", "—")
            else addResolvedApiLine(root, "Move ${i + 1}", "move", move, "Move #$move", " • PP ${p.movePP[i]}")
        }

        addDetailSection(root, "IVs / EVs")
        addStatLine(root, "HP", p.ivs[0], p.evs[0])
        addStatLine(root, "Attack", p.ivs[1], p.evs[1])
        addStatLine(root, "Defense", p.ivs[2], p.evs[2])
        addStatLine(root, "Sp. Atk", p.ivs[4], p.evs[4])
        addStatLine(root, "Sp. Def", p.ivs[5], p.evs[5])
        addStatLine(root, "Speed", p.ivs[3], p.evs[3])
        addDetailLine(root, "EV total", p.evs.sum().toString())

        addDetailSection(root, "POKÉRUS")
        val pokerus = when {
            p.pokerusStrain == 0 -> "None"
            p.pokerusDays > 0 -> "Active • strain ${p.pokerusStrain} • ${p.pokerusDays} day(s)"
            else -> "Cured • strain ${p.pokerusStrain}"
        }
        addDetailLine(root, "Status", pokerus)

        addDetailSection(root, "MARKINGS")
        val markingNames = if (detailGen == 3) arrayOf("Circle", "Square", "Triangle", "Heart")
            else arrayOf("Circle", "Triangle", "Square", "Heart", "Star", "Diamond")
        val activeMarkings = markingNames.indices.filter { i ->
            if (isCurrentGen7()) ((p.markingValue ushr (i * 2)) and 3) != 0 else ((p.markingValue ushr i) and 1) != 0
        }.map { markingNames[it] }
        addDetailLine(root, "Marked", if (activeMarkings.isEmpty()) "None" else activeMarkings.joinToString(", "))

        addMutedLine(root, when (detailGen) {
            3 -> "\nPSE Gen 3 • PK3 parsing/editing and PC movement use PK3 checksum verification, exact-slot byte checks, full active section-checksum verification and rollback. Emulator saves are still only changed through Save & Replace Current Save."
            5 -> "\nPSE Gen 5 Stage 7 • Boxed editing remains enabled; default-form Party PK5 EXP/level, nature, IV and EV edits now rebuild cached battle stats with checksum/reparse verification and rollback. Emulator saves are still only changed through Save & Replace Current Save."
            else -> "\nPSE Gen 6/7 editor • boxed and party management use post-write verification. Emulator saves are still only changed through Save & Replace Current Save."
        })
        val shell = LinearLayout(this).apply { orientation = LinearLayout.VERTICAL; setBackgroundColor(BG) }
        shell.addView(scroll, LinearLayout.LayoutParams(-1, 0, 1f))
        shell.addView(buildBottomNav("pokemon"), LinearLayout.LayoutParams(-1, -2))
        setContentView(shell)
    }

    private fun addDetailSection(root: LinearLayout, title: String) {
        addSectionTitle(root, title)
    }

    private fun addDetailLine(root: LinearLayout, label: String, value: String) {
        addDetailLineView(root, label, value)
    }

    private fun addDetailLineView(root: LinearLayout, label: String, value: String): TextView {
        val view = TextView(this).apply {
            text = "$label: $value"
            textSize = 15f
            setTextColor(TEXT)
            setPadding(dp(8), dp(4), dp(8), dp(4))
        }
        root.addView(view)
        return view
    }

    private fun addStatLine(root: LinearLayout, stat: String, iv: Int, ev: Int) {
        addDetailLine(root, stat, "IV $iv   •   EV $ev")
    }

    private fun addResolvedApiLine(root: LinearLayout, label: String, kind: String, id: Int, fallback: String, suffix: String = "") {
        val line = addDetailLineView(root, label, "$fallback$suffix")
        resolvePokeApiNameAsync(kind, id) { name ->
            if (name != null) line.text = "$label: $name (#$id)$suffix"
        }
    }

