    private fun resolvePokeApiNameAsync(kind: String, id: Int, done: (String?) -> Unit) {
        if (kind == "move" && isCurrentGen3Save()) {
            done(canonicalGen3MoveName(id))
            return
        }
        if (kind == "item" && isCurrentGen3Save()) {
            done(canonicalGen3ItemName(id) ?: "Unknown Gen 3 item")
            return
        }
        // Gen 6 save files store held items by the games' internal item index.
        // PokeAPI resource IDs are not guaranteed to be a perfect 1:1 match for
        // every high OR/AS-only index, so prefer our verified local Gen 6 fixes.
        val local = generationMetadataName(kind, id)
        if (local != null) {
            done(local)
            return
        }

        val key = "name_${kind}_$id"
        val cached = metaPrefs.getString(key, null)
        if (!cached.isNullOrBlank()) {
            done(cached)
            return
        }
        imageExecutor.execute {
            val name = try {
                val json = fetchJson("https://pokeapi.co/api/v2/$kind/$id")
                json?.optString("name")?.takeIf { it.isNotBlank() }?.let { prettyApiName(it) }
            } catch (_: Exception) { null }
            if (!name.isNullOrBlank()) metaPrefs.edit().putString(key, name).apply()
            mainHandler.post { if (!isFinishing && !isDestroyed) done(name) }
        }
    }

    private fun generationMetadataName(kind: String, id: Int): String? {
        if (kind != "item") return null
        // Item indexes are generation-specific. Only apply our local correction tables to
        // the generations they were built for. Gen 5 falls through to the generic resolver.
        return when (importedFile?.let { generationForSize(it.length().toInt()) }) {
            7 -> GEN7_USUM_ITEM_NAMES[id]
            6 -> GEN6_ORAS_ITEM_NAMES[id]
            else -> null
        }
    }

