    // Canonical Generation III growth groups in National Pokédex order (1..386).
    // IDs match the existing growth-rate cache: 1 Slow, 2 Medium Fast, 3 Fast,
    // 4 Medium Slow, 5 Erratic, 6 Fluctuating.
    private val gen3GrowthRateCodes=""

    private fun canonicalGen3GrowthRate(species:Int):Int? =
        gen3GrowthRateCodes.getOrNull(species-1)?.digitToIntOrNull()?.takeIf { it in 1..6 }

    private fun canonicalExperienceForGrowthRate(rateId:Int,level:Int):Long? {
        if(rateId !in 1..6 || level !in 1..100)return null
        if(level==1)return 1L
        val n=level.toLong()
        val square=n*n
        val cube=square*n
        return when(rateId){
            1->5L*cube/4L
            2->cube
            3->4L*cube/5L
            4->6L*cube/5L-15L*square+100L*n-140L
            5->when{
                level<=50->(100L-n)*cube/50L
                level<=68->(150L-n)*cube/100L
                level<=98->((1911L-10L*n)/3L)*cube/500L
                else->(160L-n)*cube/100L
            }
            6->when{
                level<=15->((n+1L)/3L+24L)*cube/50L
                level<=36->(n+14L)*cube/50L
                else->(n/2L+32L)*cube/50L
            }
            else->return null
        }
    }

    private fun canonicalLevelForGrowthRate(rateId:Int,experience:Long):Int? {
        if(experience<0L)return null
        var resolved:Int?=null
        for(level in 1..100){
            val threshold=canonicalExperienceForGrowthRate(rateId,level)?:return null
            if(experience<threshold)break
            resolved=level
        }
        return resolved
    }

    private fun resolveBoxedLevelAsync(species: Int, experience: Long, done: (Int?) -> Unit) {
        canonicalGen3GrowthRate(species)?.let { done(canonicalLevelForGrowthRate(it,experience)); return }
        val speciesKey = "growth_species_$species"
        val cachedRate = metaPrefs.getInt(speciesKey, -1)
        if (cachedRate > 0) {
            resolveGrowthLevelAsync(cachedRate, experience, done)
            return
        }
        imageExecutor.execute {
            val rateId = try {
                val json = fetchJson("https://pokeapi.co/api/v2/pokemon-species/$species")
                val url = json?.optJSONObject("growth_rate")?.optString("url").orEmpty()
                Regex("/growth-rate/(\\d+)/?").find(url)?.groupValues?.getOrNull(1)?.toIntOrNull()
            } catch (_: Exception) { null }
            if (rateId != null) metaPrefs.edit().putInt(speciesKey, rateId).apply()
            mainHandler.post {
                if (rateId != null && !isFinishing && !isDestroyed) resolveGrowthLevelAsync(rateId, experience, done)
                else if (!isFinishing && !isDestroyed) done(null)
            }
        }
    }

    private fun resolveGrowthLevelAsync(rateId: Int, experience: Long, done: (Int?) -> Unit) {
        val key = "growth_levels_$rateId"
        val cached = metaPrefs.getString(key, null)
        if (!cached.isNullOrBlank()) {
            done(levelFromThresholds(cached, experience))
            return
        }
        imageExecutor.execute {
            val encoded = try {
                val json = fetchJson("https://pokeapi.co/api/v2/growth-rate/$rateId")
                val levels = json?.optJSONArray("levels")
                if (levels == null) null else {
                    val pairs = ArrayList<Pair<Int, Long>>()
                    for (i in 0 until levels.length()) {
                        val obj = levels.optJSONObject(i) ?: continue
                        pairs.add(obj.optInt("level") to obj.optLong("experience"))
                    }
                    pairs.sortedBy { it.first }.joinToString(",") { "${it.first}:${it.second}" }
                }
            } catch (_: Exception) { null }
            if (!encoded.isNullOrBlank()) metaPrefs.edit().putString(key, encoded).apply()
            val level = encoded?.let { levelFromThresholds(it, experience) }
            mainHandler.post { if (!isFinishing && !isDestroyed) done(level) }
        }
    }

    private fun levelFromThresholds(encoded: String, experience: Long): Int? {
        var best: Int? = null
        encoded.split(',').forEach { token ->
            val parts = token.split(':')
            if (parts.size == 2) {
                val level = parts[0].toIntOrNull()
                val exp = parts[1].toLongOrNull()
                if (level != null && exp != null && experience >= exp) best = level
            }
        }
        return best?.coerceIn(1, 100)
    }

    private fun resolveExperienceForLevelAsync(species: Int, level: Int, done: (Long?) -> Unit) {
        canonicalGen3GrowthRate(species)?.let { done(canonicalExperienceForGrowthRate(it,level)); return }
        val speciesKey = "growth_species_$species"
        fun resolveWithRate(rateId: Int) {
            val key = "growth_levels_$rateId"
            val cached = metaPrefs.getString(key, null)
            if (!cached.isNullOrBlank()) {
                val target = cached.split(',').mapNotNull { token ->
                    val parts = token.split(':')
                    if (parts.size == 2 && parts[0].toIntOrNull() == level) parts[1].toLongOrNull() else null
                }.firstOrNull()
                done(target)
                return
            }
            imageExecutor.execute {
                val encoded = try {
                    val json = fetchJson("https://pokeapi.co/api/v2/growth-rate/$rateId")
                    val levels = json?.optJSONArray("levels")
                    if (levels == null) null else buildString {
                        for (i in 0 until levels.length()) {
                            val o = levels.getJSONObject(i)
                            if (i > 0) append(',')
                            append(o.getInt("level")).append(':').append(o.getLong("experience"))
                        }
                    }
                } catch (_: Exception) { null }
                if (!encoded.isNullOrBlank()) metaPrefs.edit().putString(key, encoded).apply()
                val target = encoded?.split(',')?.mapNotNull { token ->
                    val parts = token.split(':')
                    if (parts.size == 2 && parts[0].toIntOrNull() == level) parts[1].toLongOrNull() else null
                }?.firstOrNull()
                mainHandler.post { if (!isFinishing && !isDestroyed) done(target) }
            }
        }
        val cachedRate = metaPrefs.getInt(speciesKey, -1)
        if (cachedRate > 0) { resolveWithRate(cachedRate); return }
        imageExecutor.execute {
            val rateId = try {
                val json = fetchJson("https://pokeapi.co/api/v2/pokemon-species/$species")
                val url = json?.optJSONObject("growth_rate")?.optString("url").orEmpty()
                Regex("/growth-rate/(\\d+)/?").find(url)?.groupValues?.getOrNull(1)?.toIntOrNull()
            } catch (_: Exception) { null }
            if (rateId != null) metaPrefs.edit().putInt(speciesKey, rateId).apply()
            mainHandler.post { if (rateId != null && !isFinishing && !isDestroyed) resolveWithRate(rateId) else done(null) }
        }
    }

    private fun fetchJson(urlText: String): JSONObject? {
        val connection = URL(urlText).openConnection() as HttpsURLConnection
        return try {
            connection.connectTimeout = 7000
            connection.readTimeout = 7000
            connection.instanceFollowRedirects = true
            connection.setRequestProperty("Accept", "application/json")
            connection.connect()
            if (connection.responseCode !in 200..299) null
            else JSONObject(connection.inputStream.bufferedReader().use { it.readText() })
        } finally {
            connection.disconnect()
        }
    }

    private fun prettyApiName(slug: String): String = slug.split('-').joinToString(" ") { part ->
        part.replaceFirstChar { c -> if (c.isLowerCase()) c.uppercaseChar().toString() else c.toString() }
