    data class Gen1ToGen7TransferMeta(
        val baseFriendship: Int,
        val genderRate: Int,
        val abilityId: Int,
        val abilityNumber: Int,
        val moveBasePp: Map<Int, Int>
    )

    private fun loadGen1ToGen7TransferMetaAsync(
        dex: Int,
        moves: IntArray,
        done: (Gen1ToGen7TransferMeta?) -> Unit
    ) {
        imageExecutor.execute {
            val result = try {
                val speciesJson = fetchJsonObject("https://pokeapi.co/api/v2/pokemon-species/$dex")
                    ?: throw IllegalStateException("Species data unavailable")
                val pokemonJson = fetchJsonObject("https://pokeapi.co/api/v2/pokemon/$dex")
                    ?: throw IllegalStateException("Pokémon data unavailable")

                val baseFriendship = speciesJson.optInt("base_happiness", 70).coerceIn(0, 255)
                val genderRate = speciesJson.optInt("gender_rate", -1)

                var firstAbility = 0
                var hiddenAbility = 0
                val abilities = pokemonJson.optJSONArray("abilities")
                if (abilities != null) {
                    for (i in 0 until abilities.length()) {
                        val item = abilities.optJSONObject(i) ?: continue
                        val abilityObj = item.optJSONObject("ability") ?: continue
                        val id = parseIdFromPokeApiUrl(abilityObj.optString("url")) ?: continue
                        if (item.optBoolean("is_hidden", false)) hiddenAbility = id
                        else if (firstAbility == 0) firstAbility = id
                    }
                }
                val abilityId = if (hiddenAbility != 0) hiddenAbility else firstAbility
                if (abilityId == 0) throw IllegalStateException("Ability data unavailable")
                val abilityNumber = if (hiddenAbility != 0) 4 else 1

                val ppMap = HashMap<Int, Int>()
                for (moveId in moves.filter { it in 1..251 }.distinct()) {
                    val moveJson = fetchJsonObject("https://pokeapi.co/api/v2/move/$moveId")
                    val pp = moveJson?.optInt("pp", 0) ?: 0
                    if (pp > 0) ppMap[moveId] = pp.coerceIn(1, 64)
                }

                Gen1ToGen7TransferMeta(
                    baseFriendship = baseFriendship,
                    genderRate = genderRate,
                    abilityId = abilityId,
                    abilityNumber = abilityNumber,
                    moveBasePp = ppMap
                )
            } catch (_: Exception) {
                null
            }

            mainHandler.post {
                if (!isFinishing && !isDestroyed) done(result)
            }
        }
    }

    private fun gen1TransferGender(p: Gen1Pokemon, genderRate: Int): Int {
        if (genderRate < 0) return 2 // genderless
        if (genderRate <= 0) return 0 // male only
        if (genderRate >= 8) return 1 // female only
        val threshold = (genderRate * 2).coerceIn(0, 16)
        return if (p.dvs.getOrElse(1) { 0 } < threshold) 1 else 0
    }

    private fun randomU32(rng: java.security.SecureRandom): Long {
        val b = ByteArray(4)
        rng.nextBytes(b)
        return ((b[0].toLong() and 0xFF) or
            ((b[1].toLong() and 0xFF) shl 8) or
            ((b[2].toLong() and 0xFF) shl 16) or
            ((b[3].toLong() and 0xFF) shl 24)) and 0xFFFFFFFFL
    }

    private fun shuffledTransferIvs(flawless: Int, rng: java.security.SecureRandom): IntArray {
        val ivs = IntArray(6) { rng.nextInt(32) }
        for (i in 0 until flawless.coerceIn(0, 6)) ivs[i] = 31
        for (i in ivs.lastIndex downTo 1) {
            val j = rng.nextInt(i + 1)
            val t = ivs[i]
            ivs[i] = ivs[j]
            ivs[j] = t
        }
        return ivs
    }

    private fun forceTransferShinyState(pidInput: Long, tid: Int, shinyWanted: Boolean): Long {
        var pid = pidInput and 0xFFFFFFFFL
        val low = (pid and 0xFFFF).toInt()
        var high = ((pid ushr 16) and 0xFFFF).toInt()
        val shinyNow = (tid xor low xor high) < 16
        if (shinyWanted && !shinyNow) {
            high = (tid xor low) and 0xFFFF
            pid = (low.toLong() and 0xFFFFL) or ((high.toLong() and 0xFFFFL) shl 16)
        } else if (!shinyWanted && shinyNow) {
            pid = pid xor 0x10000000L
        }
        return pid and 0xFFFFFFFFL
    }

    private fun currentGen7LanguageId(data: ByteArray): Int {
        val status = when (data.size) {
            SIZE_G7_SM -> STATUS_OFFSET_SM
            SIZE_G7_USUM -> STATUS_OFFSET_USUM
            else -> return 2
        }
        return (data.getOrNull(status + 0x35)?.toInt() ?: 2) and 0xFF
    }

    private fun buildGen1ToGen7Pk7(
        sourceBankBytes: ByteArray,
        p: Gen1Pokemon,
        destinationSave: ByteArray,
        trainer: TrainerData,
        speciesMeta: Gen1SpeciesMeta,
        transferMeta: Gen1ToGen7TransferMeta
    ): ByteArray {
        val dex = gen1DexFromInternalIndex(p.species)
            ?: throw IllegalArgumentException("The Gen 1 species could not be mapped to the National Pokédex.")
        require(destinationSave.size == SIZE_G7_SM || destinationSave.size == SIZE_G7_USUM) {
            "A Generation 7 destination save is required."
        }

        val source = sourceBankBytes
        require(source.size == GEN1_BANK_FILE_SIZE) { "The preserved Gen 1 Bank record has an unexpected size." }

        val rng = java.security.SecureRandom()
        val pk = ByteArray(PK6_STORED_SIZE)
        val ec = randomU32(rng)
        writeU32LE(pk, 0x00, ec)
        writeU16LE(pk, 0x04, 0) // sanity
        writeU16LE(pk, 0x08, dex)
        writeU16LE(pk, 0x0A, 0) // held item removed during VC transfer
        writeU16LE(pk, 0x0C, p.tid)
        writeU16LE(pk, 0x0E, 0) // Gen 1 has no SID

        // Official VC transfer derives nature from the source EXP, then resets EXP
        // to the minimum required for the transfer level.
        val nature = (p.experience % 25L).toInt().coerceIn(0, 24)
        val transferExp = gen1ExperienceForLevel(speciesMeta.growth, p.level)
        writeU32LE(pk, 0x10, transferExp)
        pk[0x14] = transferMeta.abilityId.toByte()
        pk[0x15] = transferMeta.abilityNumber.toByte()
        writeU16LE(pk, 0x16, 0)

        var pid = randomU32(rng)
        pid = forceTransferShinyState(pid, p.tid, gen1WouldBeShinyInGen2(p.dvs))
        writeU32LE(pk, 0x18, pid)
        pk[0x1C] = nature.toByte()

        val gender = gen1TransferGender(p, transferMeta.genderRate)
        val fateful = dex == 151
        pk[0x1D] = (((gender and 0x03) shl 1) or (if (fateful) 1 else 0)).toByte()

        // EVs, contest stats and Pokérus reset.
        for (i in 0 until 6) pk[0x1E + i] = 0
        pk[0x2B] = 0

        val defaultName = GEN1_NATIONAL_NAMES.getOrElse(dex - 1) { "Pokemon" }
        val customNickname = p.nickname.isNotBlank() && !p.nickname.equals(defaultName, ignoreCase = true)
        writeGen6String(pk, 0x40, 26, if (customNickname) p.nickname else defaultName)

        // Moves are preserved; Transporter heals PP. Preserve Gen 1 PP Up count.
        val rawMonOffset = GEN1_BANK_HEADER_SIZE
        for (i in 0..3) {
            val move = p.moves[i]
            writeU16LE(pk, 0x5A + i * 2, move)
            val basePp = transferMeta.moveBasePp[move] ?: p.movePP[i].coerceIn(0, 64)
            pk[0x62 + i] = if (move == 0) 0 else basePp.toByte()
            val ppUps = if (move == 0) 0 else ((source[rawMonOffset + 29 + i].toInt() ushr 6) and 0x03)
            pk[0x66 + i] = ppUps.toByte()
        }

        // VC transfer gives 3 flawless IVs (5 for Mew), remaining IVs random.
        val ivs = shuffledTransferIvs(if (dex == 151) 5 else 3, rng)
        var iv32 = 0L
        for (i in 0..5) iv32 = iv32 or ((ivs[i].toLong() and 31L) shl (i * 5))
        if (customNickname) iv32 = iv32 or 0x80000000L
        writeU32LE(pk, 0x74, iv32)

        // Destination trainer becomes the handling trainer, mirroring Bank reception.
        writeGen6String(pk, 0x78, 26, trainer.trainerName)
        pk[0x92] = if (trainer.gender.equals("Female", true)) 1 else 0
        pk[0x93] = 1
        pk[0xA2] = transferMeta.baseFriendship.toByte()

        // Preserve original Gen 1 OT and reset original friendship to species base.
        writeGen6String(pk, 0xB0, 26, p.otName)
        pk[0xCA] = transferMeta.baseFriendship.toByte()

        val cal = java.util.Calendar.getInstance()
        pk[0xD4] = (cal.get(java.util.Calendar.YEAR) - 2000).coerceIn(0, 255).toByte()
        pk[0xD5] = (cal.get(java.util.Calendar.MONTH) + 1).toByte()
        pk[0xD6] = cal.get(java.util.Calendar.DAY_OF_MONTH).toByte()
        writeU16LE(pk, 0xD8, 0)
        writeU16LE(pk, 0xDA, 30013) // Kanto region: official Gen 1 -> Gen 7 transfer location
        pk[0xDC] = 4 // Poké Ball
        pk[0xDD] = (p.level.coerceIn(1, 100) and 0x7F).toByte()
        pk[0xDE] = 0 // no Hyper Training on transfer
        pk[0xDF] = 35 // Red VC fallback; Gen 1 PKM data does not store the exact source version
        pk[0xE0] = 0
        pk[0xE1] = 0
        pk[0xE2] = 0
        pk[0xE3] = currentGen7LanguageId(destinationSave).coerceIn(1, 10).toByte()

        updatePk6Checksum(pk)
        val encrypted = encryptPk6(pk)
        val verified = parsePk6(encrypted, 0, PK6_STORED_SIZE, false, 807)
            ?: throw IllegalArgumentException("The converted PK7 could not be parsed.")
        require(verified.checksumValid && verified.species == dex && verified.tid == p.tid) {
            "The converted PK7 failed verification."
        }
        return encrypted
    }



    private data class Gen1ToGen4Meta(val baseFriendship:Int,val abilityId:Int)
    private fun loadGen1ToGen4MetaAsync(dex:Int,done:(Gen1ToGen4Meta?)->Unit){
        imageExecutor.execute{
            val result=try{
                val species=fetchJsonObject("https://pokeapi.co/api/v2/pokemon-species/$dex")?:error("Species data unavailable")
                val pokemon=fetchJsonObject("https://pokeapi.co/api/v2/pokemon/$dex")?:error("Pokémon data unavailable")
                val abilities=pokemon.optJSONArray("abilities");var ability=0
                if(abilities!=null)for(i in 0 until abilities.length()){
                    val item=abilities.optJSONObject(i)?:continue
                    if(item.optBoolean("is_hidden",false))continue
                    ability=parseIdFromPokeApiUrl(item.optJSONObject("ability")?.optString("url").orEmpty())?:0
                    if(ability!=0)break
                }
                require(ability in 1..123){"A Generation 4 ability could not be resolved."}
                Gen1ToGen4Meta(species.optInt("base_happiness",70).coerceIn(0,255),ability)
            }catch(_:Exception){null}
            mainHandler.post{if(!isFinishing&&!isDestroyed)done(result)}
        }
    }
    private fun buildGen1ToGen4Pk4(bankBytes:ByteArray,p:Gen1Pokemon,destination:ByteArray,meta:Gen1ToGen4Meta):ByteArray{
        require(bankBytes.size==GEN1_BANK_FILE_SIZE){"The preserved Gen 1 Bank record has an unexpected size."}
        val profile=detectGen4Profile(destination)?:error("A valid Generation 4 destination save is required.")
        val dex=gen1DexFromInternalIndex(p.species)?:error("The Gen 1 species could not be mapped to the National Pokédex.")
        val out=ByteArray(136);val sid=0;val nature=(p.experience%25L).toInt()
        val shiny=p.dvs[2]==10&&p.dvs[3]==10&&p.dvs[4]==10&&p.dvs[1] in setOf(2,3,6,7,10,11,14,15)
        val seed=((p.tid.toLong() shl 16) or (p.experience and 0xFFFFL)) and 0xFFFFFFFFL
        val pid=gen4PidForNatureShiny(seed,p.tid,sid,nature,shiny)
        writeU32LE(out,0,pid);writeU16LE(out,0x08,dex);writeU16LE(out,0x0A,0);writeU16LE(out,0x0C,p.tid);writeU16LE(out,0x0E,sid);writeU32LE(out,0x10,p.experience)
        out[0x14]=meta.baseFriendship.toByte();out[0x15]=meta.abilityId.toByte();out[0x17]=2
        val ev=intArrayOf((p.statExp[0]/257).coerceIn(0,255),(p.statExp[1]/257).coerceIn(0,255),(p.statExp[2]/257).coerceIn(0,255),(p.statExp[3]/257).coerceIn(0,255),(p.statExp[4]/257).coerceIn(0,255),(p.statExp[4]/257).coerceIn(0,255));var total=ev.sum();while(total>510){val i=ev.indices.maxByOrNull{ev[it]}?:0;if(ev[i]==0)break;ev[i]--;total--};for(i in 0..5)out[0x18+i]=ev[i].toByte()
        for(i in 0..3){writeU16LE(out,0x28+i*2,p.moves[i].coerceIn(0,467));out[0x30+i]=bankBytes[GEN1_BANK_HEADER_SIZE+29+i]}
        val iv=intArrayOf(p.dvs[0],p.dvs[1],p.dvs[2],p.dvs[3],p.dvs[4],p.dvs[4]).map{(it*2).coerceIn(0,31)};var ivw=0L;for(i in 0..5)ivw=ivw or ((iv[i].toLong() and 31L) shl(i*5));writeU32LE(out,0x38,ivw)
        writeGen4String(out,0x48,22,p.nickname.ifBlank{GEN1_NATIONAL_NAMES.getOrElse(dex-1){"Pokemon"}});out[0x5F]=when(profile.family){"Platinum"->12;"HeartGold / SoulSilver"->7;else->10}.toByte();writeGen4String(out,0x68,16,p.otName);out[0x83]=4;out[0x84]=p.level.coerceIn(1,100).toByte()
        val encrypted=encryptPk4(out);val q=parsePk4(encrypted,false)?:error("The converted PK4 could not be parsed.")
        require(q.checksumValid&&q.species==dex&&q.tid==p.tid&&q.sid==0&&q.nickname==p.nickname.ifBlank{GEN1_NATIONAL_NAMES.getOrElse(dex-1){"Pokemon"}}&&q.otName==p.otName&&q.experience==p.experience&&q.nature==nature&&q.shiny==shiny&&q.ability==meta.abilityId&&q.ball==4){"The converted PK4 failed identity or legality-field verification."}
        return encrypted
    }
    private fun gen4PokedexBase(p:Gen4Profile):Int=when(p.family){"Diamond / Pearl"->0x12DC;"Platinum"->0x1328;"HeartGold / SoulSilver"->0x15FC;else->error("Unsupported Gen 4 Pokédex layout")}
    private fun registerGen1ToGen4Pokedex(save:ByteArray,p:Gen4Profile,dex:Int){
        require(dex in 1..493);val active=gen4ActiveBlock(save,0,p.generalSize);val base=active*0x40000+gen4PokedexBase(p);val bit=dex-1;val mask=1 shl(bit and 7);val byte=bit/8
        for(o in intArrayOf(base+0x04+byte,base+0x44+byte)){require(o in save.indices){"Gen 4 Pokédex offset is out of range."};save[o]=(save[o].toInt() or mask).toByte()}
        updateGen4BlockChecksum(save,active*0x40000,p.generalSize,p)
    }
    private fun gen1ToGen4DexRegistered(save:ByteArray,p:Gen4Profile,dex:Int):Boolean{val active=gen4ActiveBlock(save,0,p.generalSize);val base=active*0x40000+gen4PokedexBase(p);val bit=dex-1;val mask=1 shl(bit and 7);val byte=bit/8;return intArrayOf(base+0x04+byte,base+0x44+byte).all{it in save.indices&&(save[it].toInt() and mask)!=0}}
    private fun chooseGen1BankToGen4Destination(bankFile:File,p:Gen1Pokemon){
        val file=importedFile?:return;val data=runCatching{file.readBytes()}.getOrNull()?:return;val profile=detectGen4Profile(data)?:return showDialog("Gen 1 → Gen 4","Load a valid Diamond, Pearl, Platinum, HeartGold or SoulSilver save first.")
        val v=gen4Validation(data,profile);if(!v.generalChecksum||!v.storageChecksum||v.badPk4!=0)return showDialog("Gen 1 → Gen 4","The Gen 4 destination did not pass whole-save validation.")
        val raw=runCatching{bankFile.readBytes()}.getOrNull()?:return showDialog("Gen 1 → Gen 4","The selected Bank record could not be read.");val source=parseGen1BankPayload(raw)?:return showDialog("Gen 1 → Gen 4","The selected Bank record is invalid.")
        if(!sameGen1TransferRecord(source,p))return showDialog("Gen 1 → Gen 4","The selected Bank record changed. Nothing was changed.")
        val dex=gen1DexFromInternalIndex(source.species)?:return showDialog("Gen 1 → Gen 4","The species could not be mapped.")
        loadGen1ToGen4MetaAsync(dex){meta->
            if(meta==null)return@loadGen1ToGen4MetaAsync showDialog("Gen 1 → Gen 4","PSE could not resolve a Generation 4 legal ability. The Bank record was kept.")
            val pk4=try{buildGen1ToGen4Pk4(raw,source,data,meta)}catch(e:Exception){return@loadGen1ToGen4MetaAsync showDialog("Gen 1 → Gen 4",e.message?:"Conversion failed")};val converted=parsePk4(pk4,false)?:return@loadGen1ToGen4MetaAsync
            val empties=gen4EmptyBoxSlots(data,profile);if(empties.isEmpty())return@loadGen1ToGen4MetaAsync showDialog("Gen 1 → Gen 4","No empty Gen 4 PC slot is available.");val first=empties.first()
            AlertDialog.Builder(this).setTitle("Convert ${source.nickname.ifBlank{gen1SpeciesNameFromInternal(source.species)}} to Gen 4").setMessage("This is a PSE native PK4 conversion; Nintendo provided no direct Gen 1 → Gen 4 route. The Gen 1 Bank copy is removed only after the destination, Pokédex and checksums verify.").setPositiveButton("First Empty (Box ${first/30+1} / Slot ${first%30+1})"){_,_->transferGen1BankToGen4(bankFile,source,raw,pk4,converted,first)}.setNegativeButton("Cancel",null).show()
        }
    }
    private fun transferGen1BankToGen4(bankFile:File,expected:Gen1Pokemon,openedBank:ByteArray,preparedPk4:ByteArray,prepared:PokemonEntry,target:Int){
        val file=importedFile?:return;val original=runCatching{file.readBytes()}.getOrNull()?:return
        try{
            require(target in 0 until 540){"Invalid Gen 4 PC slot."};val p=detectGen4Profile(original)?:error("The destination is no longer a valid Gen 4 save.");val before=gen4Validation(original,p);require(before.generalChecksum&&before.storageChecksum&&before.badPk4==0){"The fresh Gen 4 destination failed validation."}
            val bank=bankFile.readBytes();val source=parseGen1BankPayload(bank)?:error("The selected Gen 1 Bank record is invalid.");require(bank.contentEquals(openedBank)&&sameGen1TransferRecord(source,expected)){"The selected Bank record changed before transfer. Nothing was changed."}
            val off=gen4BoxSlotOffset(original,p,target);val old=original.copyOfRange(off,off+136);require(old.all{it==0.toByte()}||parsePk4(old,false)==null){"The destination slot is no longer empty."}
            val freshPk4=buildGen1ToGen4Pk4(bank,source,original,Gen1ToGen4Meta(prepared.friendship,prepared.ability));require(freshPk4.contentEquals(preparedPk4)){"The prepared conversion changed before confirmation."}
            val save=original.copyOf();freshPk4.copyInto(save,off);val staged=parsePk4(save.copyOfRange(off,off+136),false)?:error("The staged PK4 could not be parsed.");require(staged.checksumValid&&staged.pid==prepared.pid&&staged.species==prepared.species&&staged.tid==source.tid){"The staged PK4 did not preserve the prepared identity."}
            registerGen1ToGen4Pokedex(save,p,staged.species);val storage=gen4ActiveBlock(save,p.storageStart,p.storageSize);updateGen4BlockChecksum(save,storage*0x40000+p.storageStart,p.storageSize,p);val stagedValidation=gen4Validation(save,p);require(stagedValidation.generalChecksum&&stagedValidation.storageChecksum&&stagedValidation.badPk4==0&&gen1ToGen4DexRegistered(save,p,staged.species)){"The staged Gen 4 save or Pokédex failed verification."}
            file.writeBytes(save);val written=file.readBytes();require(written.contentEquals(save)){"The destination changed while it was being written."};val wp=detectGen4Profile(written)?:error("The persisted Gen 4 layout could not be re-read.");val after=gen4Validation(written,wp);require(after.generalChecksum&&after.storageChecksum&&after.badPk4==0&&gen1ToGen4DexRegistered(written,wp,staged.species)){"The persisted Gen 4 save failed verification."};val actual=written.copyOfRange(gen4BoxSlotOffset(written,wp,target),gen4BoxSlotOffset(written,wp,target)+136);require(actual.contentEquals(freshPk4)){"The exact converted PK4 bytes did not persist."}
            val currentBank=bankFile.readBytes();require(currentBank.contentEquals(bank)&&parseGen1BankPayload(currentBank)?.let{sameGen1TransferRecord(it,source)}==true){"The Bank record changed before cleanup; the destination was restored."};if(!bankFile.delete()){file.writeBytes(original);error("The destination verified, but the Bank record could not be removed; the save was restored to avoid duplication.")}
            Toast.makeText(this,"Transferred Gen 1 → Gen 4 to Box ${target/30+1} • Slot ${target%30+1} and verified",Toast.LENGTH_LONG).show();showBank()
        }catch(e:Exception){runCatching{file.writeBytes(original)};showDialog("Gen 1 → Gen 4 failed","${e.message?:"Unknown error"}\n\nThe exact destination snapshot was restored and the Bank record was kept.")}
    }

    private data class Gen1Gen4BatchPrepared(val bankFile:File,val bankBytes:ByteArray,val source:Gen1Pokemon,val meta:Gen1ToGen4Meta,val pk4:ByteArray,val converted:PokemonEntry)
    private fun prepareSelectedGen1BankToGen4(chosen:List<File>){
        val file=importedFile?:return
        if(chosen.isEmpty())return showDialog("Gen 1 → Gen 4 multi-transfer","Select one or more Gen 1 Bank Pokémon first.")
        if(chosen.map{it.absolutePath}.distinct().size!=chosen.size)return showDialog("Gen 1 → Gen 4 multi-transfer","The selection contains the same Bank entry more than once. Nothing was changed.")
        val destination=runCatching{file.readBytes()}.getOrNull()?:return showDialog("Gen 1 → Gen 4 multi-transfer","The destination save could not be read.")
        val profile=detectGen4Profile(destination)?:return showDialog("Gen 1 → Gen 4 multi-transfer","Load a valid Generation 4 save first.")
        val validation=gen4Validation(destination,profile);if(!validation.generalChecksum||!validation.storageChecksum||validation.badPk4!=0)return showDialog("Gen 1 → Gen 4 multi-transfer","The Gen 4 destination did not pass whole-save validation.")
        if((0 until 18).none{box->(0 until 30).count{slot->val o=gen4BoxSlotOffset(destination,profile,box*30+slot);val raw=destination.copyOfRange(o,o+136);raw.all{it==0.toByte()}||parsePk4(raw,false)==null}>=chosen.size})return showDialog("Gen 1 → Gen 4 multi-transfer","No single Gen 4 PC box has room for all ${chosen.size} selected Pokémon. Nothing was changed.")
        val selected=try{chosen.map{bankFile->val bytes=bankFile.readBytes();val source=parseGen1BankPayload(bytes)?:error("A selected Gen 1 Bank record is invalid.");Triple(bankFile,bytes,source)}}catch(e:Exception){return showDialog("Gen 1 → Gen 4 multi-transfer",e.message?:"A selected Bank record could not be read.")}
        val prepared=ArrayList<Gen1Gen4BatchPrepared>()
        fun stop(message:String){showDialog("Gen 1 → Gen 4 multi-transfer",message)}
        fun next(index:Int){
            if(index>=selected.size){chooseSelectedGen1BankToGen4Destination(prepared,destination);return}
            val(bankFile,bankBytes,source)=selected[index];val dex=gen1DexFromInternalIndex(source.species)?:return stop("A selected species could not be mapped. Nothing was changed.")
            loadGen1ToGen4MetaAsync(dex){meta->
                if(meta==null)return@loadGen1ToGen4MetaAsync stop("PSE could not resolve Generation 4 conversion data. Every Bank record was kept.")
                val pk4=try{buildGen1ToGen4Pk4(bankBytes,source,destination,meta)}catch(e:Exception){return@loadGen1ToGen4MetaAsync stop(e.message?:"A selected Pokémon could not be converted.")}
                val converted=parsePk4(pk4,false)?:return@loadGen1ToGen4MetaAsync stop("A prepared PK4 could not be verified.")
                prepared.add(Gen1Gen4BatchPrepared(bankFile,bankBytes,source,meta,pk4,converted));next(index+1)
            }
        }
        next(0)
    }
    private fun chooseSelectedGen1BankToGen4Destination(prepared:List<Gen1Gen4BatchPrepared>,preparedDestination:ByteArray){
        val file=importedFile?:return;val data=runCatching{file.readBytes()}.getOrNull()?:return
        if(!data.contentEquals(preparedDestination))return showDialog("Gen 1 → Gen 4 multi-transfer","The Gen 4 destination changed while conversions were prepared. Nothing was written.")
        val profile=detectGen4Profile(data)?:return;val targets=(0 until 18).mapNotNull{box->val empty=(0 until 30).count{slot->val o=gen4BoxSlotOffset(data,profile,box*30+slot);val raw=data.copyOfRange(o,o+136);raw.all{it==0.toByte()}||parsePk4(raw,false)==null};if(empty>=prepared.size)box to empty else null}
        if(targets.isEmpty())return showDialog("Gen 1 → Gen 4 multi-transfer","No single Gen 4 PC box has room for the complete prepared batch.")
        var selected=0;AlertDialog.Builder(this).setTitle("Convert ${prepared.size} Gen 1 Pokémon → Gen 4").setMessage("Every PK4 conversion will be staged, registered, checksummed, persisted and re-read before any Gen 1 Bank entry is removed.").setSingleChoiceItems(targets.map{"Box ${it.first+1} • ${it.second} empty slots"}.toTypedArray(),selected){_,which->selected=which}.setNegativeButton("Cancel",null).setPositiveButton("Convert"){_,_->transferSelectedGen1BankToGen4(prepared,preparedDestination,targets[selected].first)}.show()
    }
    private fun transferSelectedGen1BankToGen4(prepared:List<Gen1Gen4BatchPrepared>,preparedDestination:ByteArray,box:Int){
        val file=importedFile?:return;val fresh=runCatching{file.readBytes()}.getOrNull()?:return;val removed=ArrayList<Pair<File,ByteArray>>()
        try{
            require(prepared.isNotEmpty()){"No Gen 1 Bank entries were prepared."};require(prepared.map{it.bankFile.absolutePath}.distinct().size==prepared.size){"The prepared selection contains a duplicate."};require(fresh.contentEquals(preparedDestination)){"The Gen 4 destination changed after preparation."}
            val profile=detectGen4Profile(fresh)?:error("The destination is no longer a valid Gen 4 save.");require(box in 0..17){"Invalid Gen 4 destination box."};val before=gen4Validation(fresh,profile);require(before.generalChecksum&&before.storageChecksum&&before.badPk4==0){"The fresh Gen 4 destination failed validation."}
            fun samePk4(a:PokemonEntry,b:PokemonEntry)=a.checksumValid&&b.checksumValid&&a.pid==b.pid&&a.species==b.species&&a.tid==b.tid&&a.sid==b.sid&&a.nickname==b.nickname&&a.otName==b.otName&&a.experience==b.experience&&a.ability==b.ability&&a.nature==b.nature&&a.shiny==b.shiny&&a.originGame==b.originGame&&a.ball==b.ball&&a.metLevel==b.metLevel&&a.language==b.language&&a.moves.contentEquals(b.moves)&&a.movePP.contentEquals(b.movePP)&&a.evs.contentEquals(b.evs)&&a.ivs.contentEquals(b.ivs)
            val refreshed=prepared.map{item->val current=item.bankFile.readBytes();require(current.contentEquals(item.bankBytes)){"A selected Bank record changed after preparation."};val source=parseGen1BankPayload(current)?:error("A selected Bank record is invalid.");require(sameGen1TransferRecord(source,item.source)){"A selected Bank record no longer matches its prepared source."};val pk4=buildGen1ToGen4Pk4(current,source,fresh,item.meta);val q=parsePk4(pk4,false)?:error("A refreshed PK4 could not be parsed.");require(pk4.contentEquals(item.pk4)&&samePk4(q,item.converted)){"A prepared conversion changed before confirmation."};Gen1Gen4BatchPrepared(item.bankFile,current,source,item.meta,pk4,q)}
            val empty=(0 until 30).filter{slot->val o=gen4BoxSlotOffset(fresh,profile,box*30+slot);val raw=fresh.copyOfRange(o,o+136);raw.all{it==0.toByte()}||parsePk4(raw,false)==null};require(empty.size>=refreshed.size){"Gen 4 Box ${box+1} no longer has room for the complete batch."}
            val work=fresh.copyOf();val allowed=HashSet<Int>();val expected=ArrayList<Triple<Int,ByteArray,PokemonEntry>>()
            for(i in refreshed.indices){val item=refreshed[i];val target=box*30+empty[i];val off=gen4BoxSlotOffset(work,profile,target);require(parsePk4(work.copyOfRange(off,off+136),false)==null){"A destination slot is no longer empty."};item.pk4.copyInto(work,off);for(x in off until off+136)allowed.add(x);val staged=parsePk4(work.copyOfRange(off,off+136),false)?:error("A staged PK4 could not be parsed.");require(samePk4(staged,item.converted)){"A staged PK4 did not preserve every supported converted field."};expected.add(Triple(target,item.pk4,staged))}
            val general=gen4ActiveBlock(work,0,profile.generalSize)*0x40000;val storage=gen4ActiveBlock(work,profile.storageStart,profile.storageSize)*0x40000+profile.storageStart
            for((_,_,mon) in expected){val base=general+gen4PokedexBase(profile);val bit=mon.species-1;allowed.add(base+0x04+bit/8);allowed.add(base+0x44+bit/8);registerGen1ToGen4Pokedex(work,profile,mon.species)}
            allowed.add(general+profile.generalSize-2);allowed.add(general+profile.generalSize-1);allowed.add(storage+profile.storageSize-2);allowed.add(storage+profile.storageSize-1);updateGen4BlockChecksum(work,storage,profile.storageSize,profile)
            require(work.indices.all{it in allowed||work[it]==fresh[it]}){"Unrelated Gen 4 save data changed during staging."};val stagedValidation=gen4Validation(work,profile);require(stagedValidation.generalChecksum&&stagedValidation.storageChecksum&&stagedValidation.badPk4==0){"The staged Gen 4 save failed validation."};require(expected.all{gen1ToGen4DexRegistered(work,profile,it.third.species)}){"A staged Gen 4 Pokédex registration failed."}
            file.writeBytes(work);val written=file.readBytes();require(written.contentEquals(work)){"The destination changed while the batch was written."};val wp=detectGen4Profile(written)?:error("The persisted Gen 4 layout could not be re-read.");val after=gen4Validation(written,wp);require(after.generalChecksum&&after.storageChecksum&&after.badPk4==0){"The persisted Gen 4 save failed validation."};require(written.indices.all{it in allowed||written[it]==fresh[it]}){"Unrelated Gen 4 save data changed after persistence."}
            for((target,bytes,staged) in expected){val off=gen4BoxSlotOffset(written,wp,target);val actual=written.copyOfRange(off,off+136);val q=parsePk4(actual,false)?:error("A persisted PK4 could not be parsed.");require(actual.contentEquals(bytes)&&samePk4(q,staged)&&gen1ToGen4DexRegistered(written,wp,q.species)){"A persisted PK4 or Pokédex registration did not verify."}}
            for(item in refreshed){val current=item.bankFile.readBytes();require(current.contentEquals(item.bankBytes)&&parseGen1BankPayload(current)?.let{sameGen1TransferRecord(it,item.source)}==true){"A Bank record changed before cleanup; the destination was restored."};removed.add(item.bankFile to item.bankBytes);require(item.bankFile.delete()){"A Bank record could not be removed after destination verification."}}
        }catch(e:Exception){for((bank,bytes) in removed)runCatching{bank.writeBytes(bytes)};runCatching{file.writeBytes(fresh)};showDialog("Gen 1 → Gen 4 multi-transfer failed","${e.message?:"Unknown error"}\n\nThe exact destination snapshot and every selected Bank record were restored.");return}
        selectedBankFiles.clear();bankMultiSelectMode=false;Toast.makeText(this,"Transferred ${prepared.size} Gen 1 Pokémon → Gen 4 and verified",Toast.LENGTH_LONG).show();showBank()
    }

    private data class Gen1ToGen5Meta(val baseFriendship:Int,val genderRate:Int,val abilityId:Int)
    private fun loadGen1ToGen5MetaAsync(dex:Int,done:(Gen1ToGen5Meta?)->Unit){
        imageExecutor.execute{
            val result=try{
                val species=fetchJsonObject("https://pokeapi.co/api/v2/pokemon-species/$dex")?:error("Species data unavailable")
                val pokemon=fetchJsonObject("https://pokeapi.co/api/v2/pokemon/$dex")?:error("Pokémon data unavailable")
                val abilities=pokemon.optJSONArray("abilities");var ability=0
                if(abilities!=null)for(i in 0 until abilities.length()){
                    val item=abilities.optJSONObject(i)?:continue;if(item.optBoolean("is_hidden",false))continue
                    ability=parseIdFromPokeApiUrl(item.optJSONObject("ability")?.optString("url").orEmpty())?:0;if(ability!=0)break
                }
                require(ability in 1..164){"A Generation 5 ability could not be resolved."}
                Gen1ToGen5Meta(species.optInt("base_happiness",70).coerceIn(0,255),species.optInt("gender_rate",-1),ability)
            }catch(_:Exception){null}
            mainHandler.post{if(!isFinishing&&!isDestroyed)done(result)}
        }
    }
    private fun gen1ToGen5Gender(p:Gen1Pokemon,rate:Int):Int{if(rate<0)return 2;if(rate<=0)return 0;if(rate>=8)return 1;return if((p.dvs[0]*16)<rate*32)1 else 0}
    private fun buildGen1ToGen5Pk5(bankBytes:ByteArray,p:Gen1Pokemon,destination:ByteArray,meta:Gen1ToGen5Meta):ByteArray{
        require(bankBytes.size==GEN1_BANK_FILE_SIZE){"The preserved Gen 1 Bank record has an unexpected size."};val profile=detectGen5Profile(destination)?:error("A valid Generation 5 destination save is required.");val dex=gen1DexFromInternalIndex(p.species)?:error("The species could not be mapped.")
        val shiny=p.dvs[2]==10&&p.dvs[3]==10&&p.dvs[4]==10&&p.dvs[1] in setOf(2,3,6,7,10,11,14,15);val seed=((p.tid.toLong() shl 16) or (p.experience and 0xFFFFL)) and 0xFFFFFFFFL;val pid=gen5PidForAbilityAndShiny(seed,p.tid,0,1,shiny);val gender=gen1ToGen5Gender(p,meta.genderRate);val nature=(p.experience%25L).toInt()
        val out=ByteArray(136);writeU32LE(out,0,pid);writeU16LE(out,0x08,dex);writeU16LE(out,0x0C,p.tid);writeU16LE(out,0x0E,0);writeU32LE(out,0x10,p.experience);out[0x14]=meta.baseFriendship.toByte();out[0x15]=meta.abilityId.toByte();out[0x17]=2
        val ev=intArrayOf((p.statExp[0]/257).coerceIn(0,255),(p.statExp[1]/257).coerceIn(0,255),(p.statExp[2]/257).coerceIn(0,255),(p.statExp[3]/257).coerceIn(0,255),(p.statExp[4]/257).coerceIn(0,255),(p.statExp[4]/257).coerceIn(0,255));var total=ev.sum();while(total>510){val i=ev.indices.maxByOrNull{ev[it]}?:0;if(ev[i]==0)break;ev[i]--;total--};for(i in 0..5)out[0x18+i]=ev[i].toByte();for(i in 0..3){writeU16LE(out,0x28+i*2,p.moves[i].coerceIn(0,467));out[0x30+i]=bankBytes[GEN1_BANK_HEADER_SIZE+29+i]}
        val iv=intArrayOf(p.dvs[0],p.dvs[1],p.dvs[2],p.dvs[3],p.dvs[4],p.dvs[4]).map{(it*2).coerceIn(0,31)};var ivw=0L;for(i in 0..5)ivw=ivw or ((iv[i].toLong() and 31L) shl(i*5));writeU32LE(out,0x38,ivw);out[0x40]=((gender and 3) shl 1).toByte();out[0x41]=nature.toByte();out[0x42]=0
        writeGen5String(out,0x48,22,p.nickname.ifBlank{GEN1_NATIONAL_NAMES.getOrElse(dex-1){"Pokemon"}},10);out[0x5F]=(if(profile.sequel)22 else 20).toByte();writeGen5String(out,0x68,16,p.otName,7);out[0x83]=4;out[0x84]=p.level.coerceIn(1,100).toByte()
        val encrypted=encryptPk5(out);val q=parsePk5(encrypted,false)?:error("The converted PK5 could not be parsed.");require(q.checksumValid&&q.species==dex&&q.tid==p.tid&&q.sid==0&&q.nickname==p.nickname.ifBlank{GEN1_NATIONAL_NAMES.getOrElse(dex-1){"Pokemon"}}&&q.otName==p.otName&&q.experience==p.experience&&q.ability==meta.abilityId&&q.abilityNumber==1&&q.gender==gender&&q.nature==nature&&q.shiny==shiny&&q.ball==4){"The converted PK5 failed identity or legality-field verification."};return encrypted
    }
    private fun gen5PokedexBlock(profile:Gen5Profile):Triple<Int,Int,Int>{val len=if(profile.sequel)0x04DC else 0x04D4;val local=profile.pokedexOffset+len+2;val mirror=if(profile.sequel)0x25F6C else 0x23F6E;return Triple(len,local,mirror)}
    private fun registerGen1ToGen5Pokedex(save:ByteArray,p:Gen5Profile,mon:PokemonEntry){
        val dex=mon.species;require(dex in 1..649);val bit=dex-1;val mask=1 shl(bit and 7);val byte=bit/8;val region=(if(mon.shiny)2 else 0) or (mon.gender and 1);val base=p.pokedexOffset
        val caught=base+0x08+byte;val seen=base+0x5C+region*0x54+byte;val displayedRegions=(0..3).map{base+0x1AC+it*0x54+byte};for(o in listOf(caught,seen)){require(o in save.indices);save[o]=(save[o].toInt() or mask).toByte()};if(displayedRegions.none{(save[it].toInt() and mask)!=0}){val o=base+0x1AC+region*0x54+byte;save[o]=(save[o].toInt() or mask).toByte()}
        if(dex<=493){val langBase=base+(if(p.sequel)0x328 else 0x320);val langBit=bit*7+1;val o=langBase+langBit/8;save[o]=(save[o].toInt() or (1 shl(langBit and 7))).toByte()}
        val(len,local,mirror)=gen5PokedexBlock(p);val crc=gen4Crc16Ccitt(save,base,base+len);writeU16LE(save,local,crc);writeU16LE(save,mirror,crc);val tableCrc=gen4Crc16Ccitt(save,p.checksumTable,p.checksumTable+p.checksumTableLength);writeU16LE(save,p.checksumBlockChecksumOffset,tableCrc)
    }
    private fun gen1ToGen5DexRegistered(save:ByteArray,p:Gen5Profile,mon:PokemonEntry):Boolean{val bit=mon.species-1;val mask=1 shl(bit and 7);val byte=bit/8;val region=(if(mon.shiny)2 else 0) or (mon.gender and 1);val base=p.pokedexOffset;return (save[base+0x08+byte].toInt() and mask)!=0&&(save[base+0x5C+region*0x54+byte].toInt() and mask)!=0&&(0..3).any{(save[base+0x1AC+it*0x54+byte].toInt() and mask)!=0}}
    private fun chooseGen1BankToGen5Destination(bankFile:File,p:Gen1Pokemon){
        val file=importedFile?:return;val data=runCatching{file.readBytes()}.getOrNull()?:return;val profile=detectGen5Profile(data)?:return showDialog("Gen 1 → Gen 5","Load a valid Black, White, Black 2 or White 2 save first.");if(!gen5ChecksumTableValid(data,profile)||(0 until 24).any{!gen5BoxChecksumValid(data,it,profile)})return showDialog("Gen 1 → Gen 5","The Gen 5 destination did not pass storage/checksum-table validation.")
        val opened=runCatching{bankFile.readBytes()}.getOrNull()?:return;val source=parseGen1BankPayload(opened)?:return showDialog("Gen 1 → Gen 5","The selected Bank record is invalid.");if(!sameGen1TransferRecord(source,p))return showDialog("Gen 1 → Gen 5","The selected Bank record changed. Nothing was changed.");val dex=gen1DexFromInternalIndex(source.species)?:return
        loadGen1ToGen5MetaAsync(dex){meta->if(meta==null)return@loadGen1ToGen5MetaAsync showDialog("Gen 1 → Gen 5","PSE could not resolve Generation 5 conversion data. The Bank record was kept.");val pk5=try{buildGen1ToGen5Pk5(opened,source,data,meta)}catch(e:Exception){return@loadGen1ToGen5MetaAsync showDialog("Gen 1 → Gen 5",e.message?:"Conversion failed")};val converted=parsePk5(pk5,false)?:return@loadGen1ToGen5MetaAsync;val targets=(0 until 24*30).filter{val o=0x00400+(it/30)*0x1000+(it%30)*136;parsePk5(data.copyOfRange(o,o+136),false)==null};if(targets.isEmpty())return@loadGen1ToGen5MetaAsync showDialog("Gen 1 → Gen 5","No empty Gen 5 PC slot is available.");val first=targets.first();AlertDialog.Builder(this).setTitle("Convert ${source.nickname.ifBlank{gen1SpeciesNameFromInternal(source.species)}} to Gen 5").setMessage("This is a PSE native PK5 conversion; Nintendo provided no direct Gen 1 → Gen 5 route. Destination storage, Pokédex and checksums must all verify before the Bank copy is removed.").setPositiveButton("First Empty (Box ${first/30+1} / Slot ${first%30+1})"){_,_->transferGen1BankToGen5(bankFile,source,opened,meta,pk5,converted,first)}.setNegativeButton("Cancel",null).show()}
    }
    private fun transferGen1BankToGen5(bankFile:File,expected:Gen1Pokemon,openedBank:ByteArray,meta:Gen1ToGen5Meta,preparedPk5:ByteArray,prepared:PokemonEntry,target:Int){
        val file=importedFile?:return;val original=runCatching{file.readBytes()}.getOrNull()?:return
        try{require(target in 0 until 720){"Invalid Gen 5 PC slot."};val p=detectGen5Profile(original)?:error("The destination is no longer a valid Gen 5 save.");require(gen5ChecksumTableValid(original,p)&&(0 until 24).all{gen5BoxChecksumValid(original,it,p)}){"The fresh Gen 5 destination failed storage validation."};val bank=bankFile.readBytes();val source=parseGen1BankPayload(bank)?:error("The selected Bank record is invalid.");require(bank.contentEquals(openedBank)&&sameGen1TransferRecord(source,expected)){"The Bank record changed before transfer."};val box=target/30;val off=0x00400+box*0x1000+(target%30)*136;require(parsePk5(original.copyOfRange(off,off+136),false)==null){"The destination slot is no longer empty."};val freshPk5=buildGen1ToGen5Pk5(bank,source,original,meta);require(freshPk5.contentEquals(preparedPk5)){"The prepared conversion changed before confirmation."}
            val save=original.copyOf();freshPk5.copyInto(save,off);val staged=parsePk5(save.copyOfRange(off,off+136),false)?:error("The staged PK5 could not be parsed.");require(staged.checksumValid&&staged.pid==prepared.pid&&staged.species==prepared.species&&staged.tid==source.tid){"The staged PK5 did not preserve the prepared identity."};registerGen1ToGen5Pokedex(save,p,staged);updateGen5BoxChecksum(save,box,p);require(gen5BoxChecksumValid(save,box,p)&&gen5ChecksumTableValid(save,p)&&gen1ToGen5DexRegistered(save,p,staged)){"The staged Gen 5 save failed checksum or Pokédex verification."}
            file.writeBytes(save);val written=file.readBytes();require(written.contentEquals(save)){"The destination changed while it was written."};val wp=detectGen5Profile(written)?:error("The persisted Gen 5 layout could not be re-read.");require(gen5BoxChecksumValid(written,box,wp)&&gen5ChecksumTableValid(written,wp)&&gen1ToGen5DexRegistered(written,wp,staged)){"The persisted Gen 5 save failed verification."};val actual=written.copyOfRange(off,off+136);val q=parsePk5(actual,false);require(actual.contentEquals(freshPk5)&&q!=null&&q.checksumValid&&q.pid==staged.pid&&q.species==staged.species){"The exact converted PK5 did not persist."};val currentBank=bankFile.readBytes();require(currentBank.contentEquals(bank)&&parseGen1BankPayload(currentBank)?.let{sameGen1TransferRecord(it,source)}==true){"The Bank record changed before cleanup; the destination was restored."};if(!bankFile.delete()){file.writeBytes(original);error("The destination verified, but the Bank record could not be removed; the save was restored to avoid duplication.")};Toast.makeText(this,"Transferred Gen 1 → Gen 5 to Box ${box+1} • Slot ${target%30+1} and verified",Toast.LENGTH_LONG).show();showBank()
        }catch(e:Exception){runCatching{file.writeBytes(original)};showDialog("Gen 1 → Gen 5 failed","${e.message?:"Unknown error"}\n\nThe exact destination snapshot was restored and the Bank record was kept.")}
    }

    private data class Gen1Gen5BatchPrepared(val bankFile:File,val bankBytes:ByteArray,val source:Gen1Pokemon,val meta:Gen1ToGen5Meta,val pk5:ByteArray,val converted:PokemonEntry)
    private fun prepareSelectedGen1BankToGen5(chosen:List<File>){
        val file=importedFile?:return;if(chosen.isEmpty())return showDialog("Gen 1 → Gen 5 multi-transfer","Select one or more Gen 1 Bank Pokémon first.");if(chosen.map{it.absolutePath}.distinct().size!=chosen.size)return showDialog("Gen 1 → Gen 5 multi-transfer","The selection contains the same Bank entry more than once. Nothing was changed.")
        val destination=runCatching{file.readBytes()}.getOrNull()?:return;val profile=detectGen5Profile(destination)?:return showDialog("Gen 1 → Gen 5 multi-transfer","Load a valid Generation 5 save first.");if(!gen5ChecksumTableValid(destination,profile)||(0 until 24).any{!gen5BoxChecksumValid(destination,it,profile)})return showDialog("Gen 1 → Gen 5 multi-transfer","The destination failed storage/checksum-table validation.")
        val hasCapacity=(0 until 24).any{box->(0 until 30).count{slot->val o=0x00400+box*0x1000+slot*136;parsePk5(destination.copyOfRange(o,o+136),false)==null}>=chosen.size};if(!hasCapacity)return showDialog("Gen 1 → Gen 5 multi-transfer","No single Gen 5 PC box has room for all ${chosen.size} selected Pokémon. Nothing was changed.")
        val selected=try{chosen.map{bank->val bytes=bank.readBytes();val source=parseGen1BankPayload(bytes)?:error("A selected Gen 1 Bank record is invalid.");Triple(bank,bytes,source)}}catch(e:Exception){return showDialog("Gen 1 → Gen 5 multi-transfer",e.message?:"A selected Bank record could not be read.")};val prepared=ArrayList<Gen1Gen5BatchPrepared>()
        fun stop(message:String){showDialog("Gen 1 → Gen 5 multi-transfer",message)};fun next(index:Int){if(index>=selected.size){chooseSelectedGen1BankToGen5Destination(prepared,destination);return};val(bank,bytes,source)=selected[index];val dex=gen1DexFromInternalIndex(source.species)?:return stop("A selected species could not be mapped.");loadGen1ToGen5MetaAsync(dex){meta->if(meta==null)return@loadGen1ToGen5MetaAsync stop("PSE could not resolve Generation 5 conversion data. Every Bank record was kept.");val pk5=try{buildGen1ToGen5Pk5(bytes,source,destination,meta)}catch(e:Exception){return@loadGen1ToGen5MetaAsync stop(e.message?:"A selected Pokémon could not be converted.")};val converted=parsePk5(pk5,false)?:return@loadGen1ToGen5MetaAsync stop("A prepared PK5 could not be verified.");prepared.add(Gen1Gen5BatchPrepared(bank,bytes,source,meta,pk5,converted));next(index+1)}};next(0)
    }
    private fun chooseSelectedGen1BankToGen5Destination(prepared:List<Gen1Gen5BatchPrepared>,preparedDestination:ByteArray){
        val file=importedFile?:return;val data=runCatching{file.readBytes()}.getOrNull()?:return;if(!data.contentEquals(preparedDestination))return showDialog("Gen 1 → Gen 5 multi-transfer","The destination changed while conversions were prepared. Nothing was written.");val targets=(0 until 24).mapNotNull{box->val empty=(0 until 30).count{slot->val o=0x00400+box*0x1000+slot*136;parsePk5(data.copyOfRange(o,o+136),false)==null};if(empty>=prepared.size)box to empty else null};if(targets.isEmpty())return showDialog("Gen 1 → Gen 5 multi-transfer","No single Gen 5 PC box has room for the complete batch.");var selected=0;AlertDialog.Builder(this).setTitle("Convert ${prepared.size} Gen 1 Pokémon → Gen 5").setMessage("Every PK5 conversion will be staged, registered, checksummed, persisted and re-read before any Gen 1 Bank entry is removed.").setSingleChoiceItems(targets.map{"Box ${it.first+1} • ${it.second} empty slots"}.toTypedArray(),selected){_,which->selected=which}.setNegativeButton("Cancel",null).setPositiveButton("Convert"){_,_->transferSelectedGen1BankToGen5(prepared,preparedDestination,targets[selected].first)}.show()
    }
    private fun transferSelectedGen1BankToGen5(prepared:List<Gen1Gen5BatchPrepared>,preparedDestination:ByteArray,box:Int){
        val file=importedFile?:return;val fresh=runCatching{file.readBytes()}.getOrNull()?:return;val removed=ArrayList<Pair<File,ByteArray>>()
        try{require(prepared.isNotEmpty()){"No Gen 1 Bank entries were prepared."};require(prepared.map{it.bankFile.absolutePath}.distinct().size==prepared.size){"The prepared selection contains a duplicate."};require(fresh.contentEquals(preparedDestination)){"The Gen 5 destination changed after preparation."};val profile=detectGen5Profile(fresh)?:error("The destination is no longer a valid Gen 5 save.");require(box in 0..23){"Invalid Gen 5 destination box."};require(gen5ChecksumTableValid(fresh,profile)&&(0 until 24).all{gen5BoxChecksumValid(fresh,it,profile)}){"The fresh Gen 5 destination failed storage validation."}
            fun samePk5(a:PokemonEntry,b:PokemonEntry)=a.checksumValid&&b.checksumValid&&a.pid==b.pid&&a.species==b.species&&a.tid==b.tid&&a.sid==b.sid&&a.nickname==b.nickname&&a.otName==b.otName&&a.experience==b.experience&&a.ability==b.ability&&a.abilityNumber==b.abilityNumber&&a.nature==b.nature&&a.gender==b.gender&&a.shiny==b.shiny&&a.originGame==b.originGame&&a.ball==b.ball&&a.metLevel==b.metLevel&&a.language==b.language&&a.moves.contentEquals(b.moves)&&a.movePP.contentEquals(b.movePP)&&a.evs.contentEquals(b.evs)&&a.ivs.contentEquals(b.ivs)
            val refreshed=prepared.map{item->val bytes=item.bankFile.readBytes();require(bytes.contentEquals(item.bankBytes)){"A selected Bank record changed after preparation."};val source=parseGen1BankPayload(bytes)?:error("A selected Bank record is invalid.");require(sameGen1TransferRecord(source,item.source)){"A selected Bank record no longer matches its prepared source."};val pk5=buildGen1ToGen5Pk5(bytes,source,fresh,item.meta);val q=parsePk5(pk5,false)?:error("A refreshed PK5 could not be parsed.");require(pk5.contentEquals(item.pk5)&&samePk5(q,item.converted)){"A prepared conversion changed before confirmation."};Gen1Gen5BatchPrepared(item.bankFile,bytes,source,item.meta,pk5,q)}
            val empty=(0 until 30).filter{slot->val o=0x00400+box*0x1000+slot*136;parsePk5(fresh.copyOfRange(o,o+136),false)==null};require(empty.size>=refreshed.size){"Gen 5 Box ${box+1} no longer has room for the complete batch."};val work=fresh.copyOf();val allowed=HashSet<Int>();val expected=ArrayList<Triple<Int,ByteArray,PokemonEntry>>()
            for(i in refreshed.indices){val item=refreshed[i];val slot=empty[i];val target=box*30+slot;val off=0x00400+box*0x1000+slot*136;require(parsePk5(work.copyOfRange(off,off+136),false)==null){"A destination slot is no longer empty."};item.pk5.copyInto(work,off);for(x in off until off+136)allowed.add(x);val staged=parsePk5(work.copyOfRange(off,off+136),false)?:error("A staged PK5 could not be parsed.");require(samePk5(staged,item.converted)){"A staged PK5 did not preserve every supported converted field."};expected.add(Triple(target,item.pk5,staged))}
            val(len,dexLocal,dexMirror)=gen5PokedexBlock(profile);allowed.add(dexLocal);allowed.add(dexLocal+1);allowed.add(dexMirror);allowed.add(dexMirror+1);for((_,_,mon) in expected){val bit=mon.species-1;val byte=bit/8;val region=(if(mon.shiny)2 else 0) or (mon.gender and 1);allowed.add(profile.pokedexOffset+0x08+byte);allowed.add(profile.pokedexOffset+0x5C+region*0x54+byte);for(r in 0..3)allowed.add(profile.pokedexOffset+0x1AC+r*0x54+byte);if(mon.species<=493){val lb=profile.pokedexOffset+(if(profile.sequel)0x328 else 0x320);allowed.add(lb+(bit*7+1)/8)};registerGen1ToGen5Pokedex(work,profile,mon)}
            val boxBase=0x00400+box*0x1000;allowed.add(boxBase+0x0FF2);allowed.add(boxBase+0x0FF3);val boxMirror=profile.checksumTable+2+box*2;allowed.add(boxMirror);allowed.add(boxMirror+1);allowed.add(profile.checksumBlockChecksumOffset);allowed.add(profile.checksumBlockChecksumOffset+1);updateGen5BoxChecksum(work,box,profile)
            require(work.indices.all{it in allowed||work[it]==fresh[it]}){"Unrelated Gen 5 save data changed during staging."};require(gen5BoxChecksumValid(work,box,profile)&&gen5ChecksumTableValid(work,profile)&&expected.all{gen1ToGen5DexRegistered(work,profile,it.third)}){"The staged Gen 5 checksums or Pokédex failed verification."}
            file.writeBytes(work);val written=file.readBytes();require(written.contentEquals(work)){"The destination changed while the batch was written."};val wp=detectGen5Profile(written)?:error("The persisted Gen 5 layout could not be re-read.");require(gen5BoxChecksumValid(written,box,wp)&&gen5ChecksumTableValid(written,wp)){"The persisted Gen 5 save failed checksum validation."};require(written.indices.all{it in allowed||written[it]==fresh[it]}){"Unrelated Gen 5 data changed after persistence."};for((target,bytes,staged) in expected){val off=0x00400+(target/30)*0x1000+(target%30)*136;val actual=written.copyOfRange(off,off+136);val q=parsePk5(actual,false)?:error("A persisted PK5 could not be parsed.");require(actual.contentEquals(bytes)&&samePk5(q,staged)&&gen1ToGen5DexRegistered(written,wp,q)){"A persisted PK5 or Pokédex registration did not verify."}}
            for(item in refreshed){val current=item.bankFile.readBytes();require(current.contentEquals(item.bankBytes)&&parseGen1BankPayload(current)?.let{sameGen1TransferRecord(it,item.source)}==true){"A Bank record changed before cleanup; the destination was restored."};removed.add(item.bankFile to item.bankBytes);require(item.bankFile.delete()){"A Bank record could not be removed after destination verification."}}
        }catch(e:Exception){for((bank,bytes) in removed)runCatching{bank.writeBytes(bytes)};runCatching{file.writeBytes(fresh)};showDialog("Gen 1 → Gen 5 multi-transfer failed","${e.message?:"Unknown error"}\n\nThe exact destination snapshot and every selected Bank record were restored.");return};selectedBankFiles.clear();bankMultiSelectMode=false;Toast.makeText(this,"Transferred ${prepared.size} Gen 1 Pokémon → Gen 5 and verified",Toast.LENGTH_LONG).show();showBank()
    }

    private fun buildGen1ToGen6Pk6(bankBytes:ByteArray,p:Gen1Pokemon,destination:ByteArray,trainer:TrainerData,meta:Gen1ToGen5Meta):ByteArray{
        require(bankBytes.size==GEN1_BANK_FILE_SIZE){"The preserved Gen 1 Bank record has an unexpected size."};require(destination.size==SIZE_G6_XY||destination.size==SIZE_G6_ORAS){"A valid Generation 6 destination save is required."};require(trainer.gameId in 24..27){"PSE could not identify the loaded Generation 6 title."};val dex=gen1DexFromInternalIndex(p.species)?:error("The Gen 1 species could not be mapped to the National Pokédex.")
        val out=ByteArray(PK6_STORED_SIZE);var ec=((p.tid.toLong() shl 16) xor p.experience xor dex.toLong() xor 0x47503136L) and 0xFFFFFFFFL;if(ec==0L)ec=1L;writeU32LE(out,0,ec);writeU16LE(out,0x08,dex);writeU16LE(out,0x0C,p.tid);writeU16LE(out,0x0E,0);writeU32LE(out,0x10,p.experience);out[0x14]=meta.abilityId.toByte();out[0x15]=1
        val shiny=gen1WouldBeShinyInGen2(p.dvs);val pid=forceTransferShinyState((ec xor 0xA5A55A5AL) and 0xFFFFFFFFL,p.tid,shiny);writeU32LE(out,0x18,pid);out[0x1C]=(p.experience%25L).toInt().toByte();val gender=gen1ToGen5Gender(p,meta.genderRate);out[0x1D]=((gender and 3) shl 1).toByte()
        val ev=intArrayOf((p.statExp[0]/257).coerceIn(0,252),(p.statExp[1]/257).coerceIn(0,252),(p.statExp[2]/257).coerceIn(0,252),(p.statExp[3]/257).coerceIn(0,252),(p.statExp[4]/257).coerceIn(0,252),(p.statExp[4]/257).coerceIn(0,252));var total=ev.sum();while(total>510){val i=ev.indices.maxByOrNull{ev[it]}?:0;if(ev[i]==0)break;ev[i]--;total--};for(i in 0..5)out[0x1E+i]=ev[i].toByte()
        val defaultName=GEN1_NATIONAL_NAMES.getOrElse(dex-1){"Pokemon"};val custom=p.nickname.isNotBlank()&&!p.nickname.equals(defaultName,true);writeGen6String(out,0x40,26,if(custom)p.nickname else defaultName);val raw=GEN1_BANK_HEADER_SIZE
        for(i in 0..3){val move=p.moves[i].coerceIn(0,165);writeU16LE(out,0x5A+i*2,move);val packed=bankBytes[raw+29+i].toInt() and 0xFF;out[0x62+i]=(if(move==0)0 else packed and 0x3F).toByte();out[0x66+i]=(if(move==0)0 else packed ushr 6).toByte()}
        val iv=intArrayOf(p.dvs[0],p.dvs[1],p.dvs[2],p.dvs[3],p.dvs[4],p.dvs[4]).map{(it*2).coerceIn(0,31)};var ivw=0L;for(i in 0..5)ivw=ivw or ((iv[i].toLong() and 31L) shl(i*5));if(custom)ivw=ivw or 0x80000000L;writeU32LE(out,0x74,ivw)
        writeGen6String(out,0x78,26,trainer.trainerName);out[0x92]=if(trainer.gender.equals("Female",true))1 else 0;out[0x93]=1;out[0xA2]=meta.baseFriendship.toByte();writeGen6String(out,0xB0,26,p.otName);out[0xCA]=meta.baseFriendship.toByte()
        val cal=java.util.Calendar.getInstance();out[0xD4]=(cal.get(java.util.Calendar.YEAR)-2000).coerceIn(0,255).toByte();out[0xD5]=(cal.get(java.util.Calendar.MONTH)+1).toByte();out[0xD6]=cal.get(java.util.Calendar.DAY_OF_MONTH).toByte();writeU16LE(out,0xD8,0);writeU16LE(out,0xDA,30013);out[0xDC]=4;out[0xDD]=p.level.coerceIn(1,100).toByte();out[0xDF]=35;val language=currentGen6LanguageId(destination);out[0xE3]=(if(language in setOf(1,2,3,4,5,7,8))language else 2).toByte()
        updatePk6Checksum(out);val encrypted=encryptPk6(out);val q=parsePk6(encrypted,0,PK6_STORED_SIZE,false,721)?:error("The converted PK6 could not be parsed.");require(q.checksumValid&&q.species==dex&&q.tid==p.tid&&q.sid==0&&q.nickname==(if(custom)p.nickname else defaultName)&&q.otName==p.otName&&q.experience==p.experience&&q.ability==meta.abilityId&&q.abilityNumber==1&&q.gender==gender&&q.nature==(p.experience%25L).toInt()&&q.shiny==shiny&&q.ball==4&&q.originGame==35&&q.metLocation==30013){"The converted PK6 failed identity or legality-field verification."};return encrypted
    }
    private fun chooseGen1BankToGen6Destination(bankFile:File,p:Gen1Pokemon){
        val file=importedFile?:return;val data=runCatching{file.readBytes()}.getOrNull()?:return;if(generationForSize(data.size)!=6)return showDialog("Gen 1 → Gen 6","Load a valid Pokémon X, Y, Omega Ruby or Alpha Sapphire save first.");if(!gen6BoxChecksumValid(data)||!gen6BlockChecksumValid(data,20))return showDialog("Gen 1 → Gen 6","The Gen 6 destination did not pass PC-storage and Pokédex checksum validation.")
        val raw=runCatching{bankFile.readBytes()}.getOrNull()?:return showDialog("Gen 1 → Gen 6","The selected Bank record could not be read.");val source=parseGen1BankPayload(raw)?:return showDialog("Gen 1 → Gen 6","The selected Bank record is invalid.");if(!sameGen1TransferRecord(source,p))return showDialog("Gen 1 → Gen 6","The selected Bank record changed. Nothing was changed.");val dex=gen1DexFromInternalIndex(source.species)?:return;val trainer=analyzeSave(file).trainer?:return showDialog("Gen 1 → Gen 6","PSE could not read the destination trainer.")
        loadGen1ToGen5MetaAsync(dex){meta->if(meta==null)return@loadGen1ToGen5MetaAsync showDialog("Gen 1 → Gen 6","PSE could not resolve Generation 6 conversion data. The Bank record was kept.");val pk6=try{buildGen1ToGen6Pk6(raw,source,data,trainer,meta)}catch(e:Exception){return@loadGen1ToGen5MetaAsync showDialog("Gen 1 → Gen 6",e.message?:"Conversion failed")};val converted=parsePk6(pk6,0,PK6_STORED_SIZE,false,721)?:return@loadGen1ToGen5MetaAsync;val info=boxStorageInfo(data)?:return@loadGen1ToGen5MetaAsync;val first=findFirstEmptyBoxSlot(data,info.first,info.second,info.third)?:return@loadGen1ToGen5MetaAsync showDialog("Gen 1 → Gen 6","No empty Gen 6 PC slot is available.")
            AlertDialog.Builder(this).setTitle("Convert ${source.nickname.ifBlank{gen1SpeciesNameFromInternal(source.species)}} to Gen 6").setMessage("This is a PSE native PK6 direct re-home; Nintendo provided no direct Gen 1 → Gen 6 route. The preserved Gen 1 OT, TID, nickname, EXP, moves, PP Up data and compatible identity metadata are retained. Destination storage, Pokédex and checksums must verify before the Bank copy is removed.").setPositiveButton("First Empty (Box ${first/30+1} / Slot ${first%30+1})"){_,_->transferGen1BankToGen6(bankFile,source,raw,data,pk6,converted,first)}.setNegativeButton("Cancel",null).show()}
    }
    private fun transferGen1BankToGen6(bankFile:File,expected:Gen1Pokemon,openedBank:ByteArray,preparedDestination:ByteArray,preparedPk6:ByteArray,prepared:PokemonEntry,target:Int){
        val file=importedFile?:return;val original=runCatching{file.readBytes()}.getOrNull()?:return
        try{require(original.contentEquals(preparedDestination)){"The Gen 6 destination changed while the conversion was being prepared."};require(generationForSize(original.size)==6){"The destination is no longer a Gen 6 save."};require(gen6BoxChecksumValid(original)&&gen6BlockChecksumValid(original,20)){"The fresh Gen 6 destination failed storage or Pokédex validation."};val info=boxStorageInfo(original)?:error("PSE could not resolve Gen 6 PC storage.");require(target in 0 until info.second){"Invalid Gen 6 PC slot."};val off=info.first+target*PK6_STORED_SIZE;require(parsePk6(original,off,PK6_STORED_SIZE,false,info.third)==null){"The destination slot is no longer empty."}
            val bank=bankFile.readBytes();val source=parseGen1BankPayload(bank)?:error("The selected Bank record is invalid.");require(bank.contentEquals(openedBank)&&sameGen1TransferRecord(source,expected)){"The Bank record changed before transfer."};val checked=parsePk6(preparedPk6,0,PK6_STORED_SIZE,false,721)?:error("The prepared PK6 is invalid.");require(checked.checksumValid&&checked.pid==prepared.pid&&checked.species==prepared.species&&checked.tid==source.tid&&checked.otName==source.otName){"The prepared PK6 identity changed before confirmation."}
            val save=original.copyOf();preparedPk6.copyInto(save,off);val staged=parsePk6(save,off,PK6_STORED_SIZE,false,721)?:error("The staged PK6 could not be parsed.");require(staged.checksumValid&&staged.pid==prepared.pid&&staged.species==prepared.species&&staged.tid==source.tid&&staged.nickname==prepared.nickname&&staged.otName==prepared.otName){"The staged PK6 did not preserve the prepared identity."};registerGen6Dex(save,staged.species,staged.gender,staged.shiny,staged.language);updateGen6BoxChecksum(save);updateGen6DexChecksum(save);require(gen6BoxChecksumValid(save)&&gen6BlockChecksumValid(save,20)&&gen6DexCaught(save,staged.species)){"The staged Gen 6 save failed checksum or Pokédex verification."}
            file.writeBytes(save);val written=file.readBytes();require(written.contentEquals(save)){"The destination changed while it was written."};val actual=written.copyOfRange(off,off+PK6_STORED_SIZE);val q=parsePk6(actual,0,PK6_STORED_SIZE,false,721);require(actual.contentEquals(preparedPk6)&&q!=null&&q.checksumValid&&q.pid==staged.pid&&q.species==staged.species&&q.tid==source.tid&&q.nickname==staged.nickname&&q.otName==staged.otName){"The exact converted PK6 did not persist."};require(gen6BoxChecksumValid(written)&&gen6BlockChecksumValid(written,20)&&gen6DexCaught(written,staged.species)){"The persisted Gen 6 save failed checksum or Pokédex verification."}
            val currentBank=bankFile.readBytes();require(currentBank.contentEquals(bank)&&parseGen1BankPayload(currentBank)?.let{sameGen1TransferRecord(it,source)}==true){"The Bank record changed before cleanup; the destination was restored."};if(!bankFile.delete()){file.writeBytes(original);error("The destination verified, but the Bank record could not be removed; the save was restored to avoid duplication.")};Toast.makeText(this,"Transferred Gen 1 → Gen 6 to Box ${target/30+1} • Slot ${target%30+1} and verified",Toast.LENGTH_LONG).show();showBank()
        }catch(e:Exception){runCatching{file.writeBytes(original)};showDialog("Gen 1 → Gen 6 failed","${e.message?:"Unknown error"}\n\nThe exact destination snapshot was restored and the Bank record was kept.")}
    }

    private data class Gen1Gen6BatchPrepared(val bankFile:File,val bankBytes:ByteArray,val source:Gen1Pokemon,val meta:Gen1ToGen5Meta,val pk6:ByteArray,val converted:PokemonEntry)
    private fun prepareSelectedGen1BankToGen6(chosen:List<File>){
        val file=importedFile?:return;if(chosen.isEmpty())return showDialog("Gen 1 → Gen 6 multi-transfer","Select one or more Gen 1 Bank Pokémon first.");if(chosen.map{it.absolutePath}.distinct().size!=chosen.size)return showDialog("Gen 1 → Gen 6 multi-transfer","The selection contains the same Bank entry more than once. Nothing was changed.")
        val destination=runCatching{file.readBytes()}.getOrNull()?:return;if(generationForSize(destination.size)!=6)return showDialog("Gen 1 → Gen 6 multi-transfer","Load a valid Generation 6 save first.");require(destination.size==SIZE_G6_XY||destination.size==SIZE_G6_ORAS);if(!gen6BoxChecksumValid(destination)||!gen6BlockChecksumValid(destination,20))return showDialog("Gen 1 → Gen 6 multi-transfer","The destination failed PC-storage or Pokédex checksum validation.");val info=boxStorageInfo(destination)?:return;val trainer=analyzeSave(file).trainer?:return showDialog("Gen 1 → Gen 6 multi-transfer","PSE could not read the destination trainer.")
        val hasCapacity=(0 until info.second/30).any{box->(0 until 30).count{slot->parsePk6(destination,info.first+(box*30+slot)*PK6_STORED_SIZE,PK6_STORED_SIZE,false,info.third)==null}>=chosen.size};if(!hasCapacity)return showDialog("Gen 1 → Gen 6 multi-transfer","No single Gen 6 PC box has room for all ${chosen.size} selected Pokémon. Nothing was changed.")
        val selected=try{chosen.map{bank->val bytes=bank.readBytes();val source=parseGen1BankPayload(bytes)?:error("A selected Gen 1 Bank record is invalid.");Triple(bank,bytes,source)}}catch(e:Exception){return showDialog("Gen 1 → Gen 6 multi-transfer",e.message?:"A selected Bank record could not be read.")};val prepared=ArrayList<Gen1Gen6BatchPrepared>()
        fun stop(message:String){showDialog("Gen 1 → Gen 6 multi-transfer",message)};fun next(index:Int){if(index>=selected.size){chooseSelectedGen1BankToGen6Destination(prepared,destination);return};val(bank,bytes,source)=selected[index];val dex=gen1DexFromInternalIndex(source.species)?:return stop("A selected species could not be mapped.");loadGen1ToGen5MetaAsync(dex){meta->if(meta==null)return@loadGen1ToGen5MetaAsync stop("PSE could not resolve Generation 6 conversion data. Every Bank record was kept.");val pk6=try{buildGen1ToGen6Pk6(bytes,source,destination,trainer,meta)}catch(e:Exception){return@loadGen1ToGen5MetaAsync stop(e.message?:"A selected Pokémon could not be converted.")};val converted=parsePk6(pk6,0,PK6_STORED_SIZE,false,721)?:return@loadGen1ToGen5MetaAsync stop("A prepared PK6 could not be verified.");prepared.add(Gen1Gen6BatchPrepared(bank,bytes,source,meta,pk6,converted));next(index+1)}};next(0)
    }
    private fun chooseSelectedGen1BankToGen6Destination(prepared:List<Gen1Gen6BatchPrepared>,preparedDestination:ByteArray){
        val file=importedFile?:return;val data=runCatching{file.readBytes()}.getOrNull()?:return;if(!data.contentEquals(preparedDestination))return showDialog("Gen 1 → Gen 6 multi-transfer","The destination changed while conversions were prepared. Nothing was written.");val info=boxStorageInfo(data)?:return;val targets=(0 until info.second/30).mapNotNull{box->val empty=(0 until 30).count{slot->parsePk6(data,info.first+(box*30+slot)*PK6_STORED_SIZE,PK6_STORED_SIZE,false,info.third)==null};if(empty>=prepared.size)box to empty else null};if(targets.isEmpty())return showDialog("Gen 1 → Gen 6 multi-transfer","No single Gen 6 PC box has room for the complete batch.");var selected=0
        AlertDialog.Builder(this).setTitle("Convert ${prepared.size} Gen 1 Pokémon → Gen 6").setMessage("Every native PK6 direct re-home will be staged, registered, checksummed, persisted and re-read before any Gen 1 Bank entry is removed.").setSingleChoiceItems(targets.map{"Box ${it.first+1} • ${it.second} empty slots"}.toTypedArray(),selected){_,which->selected=which}.setNegativeButton("Cancel",null).setPositiveButton("Convert"){_,_->transferSelectedGen1BankToGen6(prepared,preparedDestination,targets[selected].first)}.show()
    }
    private fun transferSelectedGen1BankToGen6(prepared:List<Gen1Gen6BatchPrepared>,preparedDestination:ByteArray,box:Int){
        val file=importedFile?:return;val fresh=runCatching{file.readBytes()}.getOrNull()?:return;val removed=ArrayList<Pair<File,ByteArray>>()
        try{require(prepared.isNotEmpty()){"No Gen 1 Bank entries were prepared."};require(prepared.map{it.bankFile.absolutePath}.distinct().size==prepared.size){"The prepared selection contains a duplicate."};require(fresh.contentEquals(preparedDestination)){"The Gen 6 destination changed after preparation."};require(generationForSize(fresh.size)==6){"The destination is no longer a Gen 6 save."};require(gen6BoxChecksumValid(fresh)&&gen6BlockChecksumValid(fresh,20)){"The fresh Gen 6 destination failed storage or Pokédex validation."};val info=boxStorageInfo(fresh)?:error("PSE could not resolve Gen 6 PC storage.");require(box in 0 until info.second/30){"Invalid Gen 6 destination box."};val trainer=analyzeSave(file).trainer?:error("PSE could not re-read the destination trainer.")
            fun samePk6(a:PokemonEntry,b:PokemonEntry)=a.checksumValid&&b.checksumValid&&a.pid==b.pid&&a.species==b.species&&a.tid==b.tid&&a.sid==b.sid&&a.nickname==b.nickname&&a.isNicknamed==b.isNicknamed&&a.otName==b.otName&&a.experience==b.experience&&a.ability==b.ability&&a.abilityNumber==b.abilityNumber&&a.nature==b.nature&&a.gender==b.gender&&a.shiny==b.shiny&&a.originGame==b.originGame&&a.metLocation==b.metLocation&&a.ball==b.ball&&a.metLevel==b.metLevel&&a.language==b.language&&a.moves.contentEquals(b.moves)&&a.movePP.contentEquals(b.movePP)&&a.evs.contentEquals(b.evs)&&a.ivs.contentEquals(b.ivs)
            val refreshed=prepared.map{item->val bytes=item.bankFile.readBytes();require(bytes.contentEquals(item.bankBytes)){"A selected Bank record changed after preparation."};val source=parseGen1BankPayload(bytes)?:error("A selected Gen 1 Bank record is invalid.");require(sameGen1TransferRecord(source,item.source)){"A selected Bank record no longer matches its prepared source."};val pk6=buildGen1ToGen6Pk6(bytes,source,fresh,trainer,item.meta);val q=parsePk6(pk6,0,PK6_STORED_SIZE,false,721)?:error("A refreshed PK6 could not be parsed.");require(pk6.contentEquals(item.pk6)&&samePk6(q,item.converted)){"A prepared conversion changed before confirmation."};Gen1Gen6BatchPrepared(item.bankFile,bytes,source,item.meta,pk6,q)}
            val empty=(0 until 30).filter{slot->parsePk6(fresh,info.first+(box*30+slot)*PK6_STORED_SIZE,PK6_STORED_SIZE,false,info.third)==null};require(empty.size>=refreshed.size){"Gen 6 Box ${box+1} no longer has room for the complete batch."};val work=fresh.copyOf();val allowed=HashSet<Int>();val expected=ArrayList<Triple<Int,ByteArray,PokemonEntry>>()
            for(i in refreshed.indices){val item=refreshed[i];val target=box*30+empty[i];val off=info.first+target*PK6_STORED_SIZE;require(parsePk6(work,off,PK6_STORED_SIZE,false,info.third)==null){"A destination slot is no longer empty."};item.pk6.copyInto(work,off);for(x in off until off+PK6_STORED_SIZE)allowed.add(x);val staged=parsePk6(work,off,PK6_STORED_SIZE,false,721)?:error("A staged PK6 could not be parsed.");require(samePk6(staged,item.converted)){"A staged PK6 did not preserve every supported converted field."};expected.add(Triple(target,item.pk6,staged))}
            for((_,_,mon) in expected){val bit=mon.species-1;val bd=bit ushr 3;val shift=(mon.gender.coerceIn(0,1)) or ((if(mon.shiny)1 else 0) shl 1);allowed.add(0x15000+0x08+bd);allowed.add(0x15000+0x08+0x60*(1+shift)+bd);for(r in 5..8)allowed.add(0x15000+0x08+0x60*r+bd);registerGen6Dex(work,mon.species,mon.gender,mon.shiny,mon.language)};val boxBlock=if(work.size==SIZE_G6_XY)53 else 56;for(id in intArrayOf(20,boxBlock)){val o=gen6ChecksumOffset(work,id);allowed.add(o);allowed.add(o+1)};updateGen6BoxChecksum(work);updateGen6DexChecksum(work)
            require(work.indices.all{it in allowed||work[it]==fresh[it]}){"Unrelated Gen 6 save data changed during staging."};require(gen6BoxChecksumValid(work)&&gen6BlockChecksumValid(work,20)&&expected.all{gen6DexCaught(work,it.third.species)}){"The staged Gen 6 checksums or Pokédex failed verification."}
            file.writeBytes(work);val written=file.readBytes();require(written.contentEquals(work)){"The destination changed while the batch was written."};require(gen6BoxChecksumValid(written)&&gen6BlockChecksumValid(written,20)){"The persisted Gen 6 save failed checksum validation."};require(written.indices.all{it in allowed||written[it]==fresh[it]}){"Unrelated Gen 6 data changed after persistence."};for((target,bytes,staged) in expected){val off=info.first+target*PK6_STORED_SIZE;val actual=written.copyOfRange(off,off+PK6_STORED_SIZE);val q=parsePk6(actual,0,PK6_STORED_SIZE,false,721)?:error("A persisted PK6 could not be parsed.");require(actual.contentEquals(bytes)&&samePk6(q,staged)&&gen6DexCaught(written,q.species)){"A persisted PK6 or Pokédex registration did not verify."}}
            for(item in refreshed){val current=item.bankFile.readBytes();require(current.contentEquals(item.bankBytes)&&parseGen1BankPayload(current)?.let{sameGen1TransferRecord(it,item.source)}==true){"A Bank record changed before cleanup; the destination was restored."};removed.add(item.bankFile to item.bankBytes);require(item.bankFile.delete()){"A Bank record could not be removed after destination verification."}}
        }catch(e:Exception){for((bank,bytes) in removed)runCatching{bank.writeBytes(bytes)};runCatching{file.writeBytes(fresh)};showDialog("Gen 1 → Gen 6 multi-transfer failed","${e.message?:"Unknown error"}\n\nThe exact destination snapshot and every selected Bank record were restored.");return};selectedBankFiles.clear();bankMultiSelectMode=false;Toast.makeText(this,"Transferred ${prepared.size} Gen 1 Pokémon → Gen 6 and verified",Toast.LENGTH_LONG).show();showBank()
    }

    // PSE conversion only: Nintendo never provided a direct Generation I/II -> III migration path.
    private fun gen1ToGen3OriginGame(data:ByteArray):Int {val game=detectGen3GameFromData(data,currentSourceLabel?:importedFile?.name.orEmpty());return when{game.contains("Sapphire")->1;game.contains("Ruby")->2;game.contains("Emerald")->3;game.contains("FireRed")->4;game.contains("LeafGreen")->5;else->3}}
    private fun buildGen1ToGen3Pk3(bankBytes:ByteArray,p:Gen1Pokemon,destinationSave:ByteArray):ByteArray {
        require(bankBytes.size==GEN1_BANK_FILE_SIZE);val dex=gen1DexFromInternalIndex(p.species)?:error("Species mapping failed");val out=ByteArray(80);val sid=0;val sourceShiny=p.dvs[2]==10&&p.dvs[3]==10&&p.dvs[4]==10&&p.dvs[1] in setOf(2,3,6,7,10,11,14,15);val nature=(p.experience%25L).toInt();val pid=gen3PidForNatureShiny(((p.tid.toLong() shl 16) or (p.experience and 0xFFFFL)) and 0xFFFFFFFFL,p.tid,sid,nature,sourceShiny)
        writeU32LE(out,0,pid);writeU16LE(out,4,p.tid);writeU16LE(out,6,sid);writeGen3Text(out,8,10,p.nickname.ifBlank{GEN1_NATIONAL_NAMES.getOrElse(dex-1){"Pokemon"}});out[0x12]=2;writeGen3Text(out,0x14,7,p.otName)
