        for(i in 0..3){writeU16LE(a,i*2,p.moves[i].coerceIn(0,354));a[8+i]=bankBytes[GEN1_BANK_HEADER_SIZE+29+i]}
        val ev=intArrayOf((p.statExp[0]/257).coerceIn(0,255),(p.statExp[1]/257).coerceIn(0,255),(p.statExp[2]/257).coerceIn(0,255),(p.statExp[3]/257).coerceIn(0,255),(p.statExp[4]/257).coerceIn(0,255),(p.statExp[4]/257).coerceIn(0,255));var total=ev.sum();while(total>510){val i=ev.indices.maxByOrNull{ev[it]}?:0;if(ev[i]==0)break;ev[i]--;total--};for(i in 0..5)e[i]=ev[i].toByte()
        val dv=p.dvs;val iv=intArrayOf(dv[0],dv[1],dv[2],dv[3],dv[4],dv[4]).map{(it*2).coerceIn(0,31)};var ivw=0L;for(i in 0..5)ivw=ivw or ((iv[i].toLong() and 31L) shl (i*5));writeU32LE(m,4,ivw)
        val originGame=gen1ToGen3OriginGame(destinationSave);m[0]=0;m[1]=0;writeU16LE(m,2,(p.level.coerceIn(1,100) and 0x7F) or ((originGame and 0xF) shl 7) or (4 shl 11))
        val order=gen3Orders[(pid%24L).toInt()];val plain=ByteArray(48);for(i in 0..3)(blocks[order[i]]!!).copyInto(plain,i*12);var sum=0;for(i in 0 until 48 step 2)sum=(sum+readU16LE(plain,i)) and 0xFFFF;writeU16LE(out,0x1C,sum);val key=(pid xor (p.tid.toLong() and 0xFFFFL)).toInt();var x=0;while(x<48){writeU32LE(plain,x,(readU32LE(plain,x).toInt() xor key).toLong() and 0xFFFFFFFFL);x+=4};plain.copyInto(out,0x20)
        val q=parsePk3(out,0,false)?:error("Converted PK3 parse failed");require(q.checksumValid&&q.species==dex&&q.tid==p.tid&&q.shiny==sourceShiny&&q.originGame==originGame&&q.ball==4);return out
    }
    private fun registerGen1ToGen3Pokedex(save:ByteArray,dex:Int){val s0=gen3ActiveSection(save,0)?:error("Missing section 0");val s1=gen3ActiveSection(save,1)?:error("Missing section 1");val bit=dex-1;val mask=1 shl(bit and 7);val byte=bit/8;val game=detectGen3GameFromData(save,currentSourceLabel?:importedFile?.name.orEmpty());val seen2=if(game.contains("FireRed")||game.contains("LeafGreen"))s1+0x938 else s1+0x988;for(o in intArrayOf(s0+0x28+byte,s0+0x5C+byte,seen2+byte))save[o]=(save[o].toInt() or mask).toByte();updateGen3SectionChecksum(save,0);updateGen3SectionChecksum(save,1)}
    private fun chooseGen1BankToGen3Destination(bankFile:File,p:Gen1Pokemon){val file=importedFile?:return;val data=file.readBytes();if(generationForSize(data.size)!=3||!gen3SaveValid(data))return showDialog("Gen 1 → Gen 3","Load a valid Generation 3 save first.");val raw=bankFile.readBytes();val pk3=try{buildGen1ToGen3Pk3(raw,p,data)}catch(e:Exception){return showDialog("Gen 1 → Gen 3",e.message?:"Conversion failed")};val converted=parsePk3(pk3,0,false)?:return;val pc=gen3PcBuffer(data)?:return;val empties=(0 until 420).filter{parsePk3(pc,4+it*80,false)==null};if(empties.isEmpty())return showDialog("Gen 1 → Gen 3","No empty PC slot.");val first=empties.first();AlertDialog.Builder(this).setTitle("Convert ${p.nickname.ifBlank{gen1SpeciesNameFromInternal(p.species)}} to Gen 3").setMessage("There was no official Gen 1/2 → Gen 3 transfer route. This is a PSE conversion into a native PK3, not an official migration.").setPositiveButton("First Empty (Box ${first/30+1} / Slot ${first%30+1})"){_,_->transferGen1BankToGen3(bankFile,p,pk3,converted,first)}.setNeutralButton("Choose Box / Slot"){_,_->showGen1ToGen3BoxPicker(bankFile,p,pk3,converted,pc)}.setNegativeButton("Cancel",null).show()}
    private fun showGen1ToGen3BoxPicker(bankFile:File,p:Gen1Pokemon,pk3:ByteArray,converted:PokemonEntry,pc:ByteArray){val boxes=(0 until 14).filter{b->(0 until 30).any{s->parsePk3(pc,4+(b*30+s)*80,false)==null}};AlertDialog.Builder(this).setTitle("Choose Gen 3 destination box").setItems(boxes.map{"Box ${it+1}"}.toTypedArray()){_,w->val b=boxes[w];val empties=(0 until 30).filter{s->parsePk3(pc,4+(b*30+s)*80,false)==null};AlertDialog.Builder(this).setTitle("Box ${b+1} • choose slot").setItems(empties.map{"Slot ${it+1}"}.toTypedArray()){_,sw->transferGen1BankToGen3(bankFile,p,pk3,converted,b*30+empties[sw])}.setNegativeButton("Cancel",null).show()}.setNegativeButton("Cancel",null).show()}
    private fun writeGen1ToGen3PcAndDexFrozen(save:ByteArray,pc:ByteArray,dex:Int){
        // Freeze one coherent Gen 3 save-slot map for the whole transaction. Re-selecting
        // sections between PC and Pokédex writes can mix the two redundant save slots.
        val map=gen3ActiveSectionMap(save)?:error("Could not map active Gen 3 save sections")
        require(pc.size==33744){"Unexpected Gen 3 PC storage size ${pc.size}"}
        var cursor=0
        for(id in 5..13){
            val base=map[id]
            if(base<0)error("Missing active Gen 3 PC section $id")
            val len=if(id==13)2000 else 3968
            require(cursor+len<=pc.size && base+len<=save.size){"Gen 3 PC section $id is out of range"}
            pc.copyInto(save,base,cursor,cursor+len)
            updateGen3SectionChecksumAt(save,base,id)
            cursor+=len
        }
        require(cursor==pc.size){"Gen 3 PC storage write was incomplete"}
        val s0=map[0];val s1=map[1]
        if(s0<0||s1<0)error("Missing active Gen 3 Pokédex sections")
        val bit=dex-1;val mask=1 shl(bit and 7);val byte=bit/8
        val game=detectGen3GameFromData(save,currentSourceLabel?:importedFile?.name.orEmpty())
        val frlg=game.contains("FireRed")||game.contains("LeafGreen")
        val emerald=game.contains("Emerald")
        // Gen 3 stores Seen three times: once in Small (section 0), then twice in
        // Large (sections 1-4). Offsets below are the canonical RS/E/FRLG layouts.
        val seen2Rel=when{frlg->0x5F8;emerald->0x988;else->0x938}
        val seen3LargeRel=when{frlg->0x3A18;emerald->0x3B24;else->0x3A8C}
        val seen3Chunk=seen3LargeRel/3968
        val seen3Rel=seen3LargeRel%3968
        val seen3SectionId=1+seen3Chunk
        val sSeen3=map[seen3SectionId]
        if(sSeen3<0)error("Missing active Gen 3 Pokédex mirror section $seen3SectionId")
        for(o in intArrayOf(s0+0x28+byte,s0+0x5C+byte,s1+seen2Rel+byte,sSeen3+seen3Rel+byte)){
            require(o in save.indices){"Gen 3 Pokédex offset is out of range"}
            save[o]=(save[o].toInt() or mask).toByte()
        }
        updateGen3SectionChecksumAt(save,s0,0)
        updateGen3SectionChecksumAt(save,s1,1)
        if(sSeen3!=s1)updateGen3SectionChecksumAt(save,sSeen3,seen3SectionId)
    }

    private fun transferGen1BankToGen3(bankFile:File,p:Gen1Pokemon,pk3:ByteArray,converted:PokemonEntry,target:Int){
        val file=importedFile?:return
        val fresh=runCatching{file.readBytes()}.getOrElse{showDialog("Gen 1 → Gen 3 failed","The fresh destination save could not be read. Nothing was changed.");return}
        try{
            require(generationForSize(fresh.size)==3&&gen3SaveValid(fresh)){"The loaded destination is no longer a valid Gen 3 save."}
            require(target in 0 until 420){"The selected Gen 3 destination slot is invalid."}
            val bankBytes=runCatching{bankFile.readBytes()}.getOrElse{error("The selected Gen 1 Bank record could not be read.")}
            val source=parseGen1BankPayload(bankBytes)?:error("The selected Gen 1 Bank record failed validation.")
            require(sameGen1TransferRecord(source,p)){"The selected Gen 1 Bank record changed before conversion. Nothing was changed."}
            fun samePk3(a:PokemonEntry,b:PokemonEntry)=a.checksumValid&&b.checksumValid&&a.pid==b.pid&&a.species==b.species&&a.tid==b.tid&&a.sid==b.sid&&a.nickname==b.nickname&&a.otName==b.otName&&a.experience==b.experience&&a.nature==b.nature&&a.shiny==b.shiny&&a.originGame==b.originGame&&a.ball==b.ball&&a.metLevel==b.metLevel&&a.language==b.language&&a.heldItem==b.heldItem&&a.friendship==b.friendship&&a.isEgg==b.isEgg&&a.moves.contentEquals(b.moves)&&a.movePP.contentEquals(b.movePP)&&a.evs.contentEquals(b.evs)&&a.ivs.contentEquals(b.ivs)
            val freshPk3=buildGen1ToGen3Pk3(bankBytes,source,fresh)
            val freshConverted=parsePk3(freshPk3,0,false)?:error("The refreshed Gen 1 Pokémon could not be converted to PK3.")
            require(freshPk3.contentEquals(pk3)&&samePk3(freshConverted,converted)){"The prepared Gen 3 conversion changed before confirmation. Nothing was changed."}
            val save=fresh.copyOf();val pc=gen3PcBuffer(save)?:error("Could not reconstruct Gen 3 PC storage")
            val beforePc=pc.copyOf();val off=4+target*80
            require(off>=4&&off+freshPk3.size<=pc.size){"The selected Gen 3 destination slot is out of range."}
            require(parsePk3(pc,off,false)==null){"The destination slot is no longer empty."}
            freshPk3.copyInto(pc,off)
            val staged=parsePk3(pc,off,false)?:error("Converted PK3 could not be parsed after placement")
            require(samePk3(staged,freshConverted)){"The staged PK3 did not preserve every supported converted field."}
            require(pc.indices.all{it in off until off+freshPk3.size||pc[it]==beforePc[it]}){"Unrelated Gen 3 PC data changed during staging."}
            fun dexRegistered(data:ByteArray,dex:Int):Boolean{
                val map=gen3ActiveSectionMap(data)?:return false;val s0=map[0];val s1=map[1]
                if(s0<0||s1<0)return false
                val bit=dex-1;val mask=1 shl(bit and 7);val byte=bit/8
                val game=detectGen3GameFromData(data,currentSourceLabel?:importedFile?.name.orEmpty())
                val frlg=game.contains("FireRed")||game.contains("LeafGreen");val emerald=game.contains("Emerald")
                val seen2Rel=when{frlg->0x5F8;emerald->0x988;else->0x938}
                val seen3LargeRel=when{frlg->0x3A18;emerald->0x3B24;else->0x3A8C};val seen3SectionId=1+seen3LargeRel/3968;val seen3Rel=seen3LargeRel%3968;val sSeen3=map[seen3SectionId]
                if(sSeen3<0)return false
                val offsets=intArrayOf(s0+0x28+byte,s0+0x5C+byte,s1+seen2Rel+byte,sSeen3+seen3Rel+byte)
                return offsets.all{it in data.indices&&(data[it].toInt() and mask)!=0}
            }
            writeGen1ToGen3PcAndDexFrozen(save,pc,freshConverted.species)
            require(gen3SaveValid(save)){"Gen 3 checksum verification failed"}
            require(dexRegistered(save,freshConverted.species)){"The staged Gen 3 Pokédex mirrors did not verify."}
            file.writeBytes(save)
            val verify=file.readBytes();require(verify.contentEquals(save)){"The Gen 3 destination changed while the conversion was being written."};require(gen3SaveValid(verify)){"The written Gen 3 save failed checksum verification."}
            require(dexRegistered(verify,freshConverted.species)){"The persisted Gen 3 Pokédex mirrors did not verify."}
            val vpc=gen3PcBuffer(verify)?:error("Could not re-read Gen 3 PC storage")
            require(freshPk3.indices.all{vpc[off+it]==freshPk3[it]}){"The converted PK3 bytes did not persist in the selected destination slot."}
            val q=parsePk3(vpc,off,false);require(q!=null&&samePk3(q,freshConverted)){"The persisted PK3 did not preserve every supported converted field."}
            require(vpc.indices.all{it in off until off+freshPk3.size||vpc[it]==beforePc[it]}){"Unrelated Gen 3 PC data changed after persistence."}
            val currentBank=runCatching{bankFile.readBytes()}.getOrElse{error("The selected Gen 1 Bank record could not be re-read before cleanup.")}
            require(currentBank.contentEquals(bankBytes) && parseGen1BankPayload(currentBank)?.let{sameGen1TransferRecord(it,source)}==true){"The selected Gen 1 Bank record changed before cleanup. The Gen 3 destination was restored."}
            if(!bankFile.delete()){file.writeBytes(fresh);error("Bank entry removal failed; the fresh destination save was restored.")}
        }catch(e:Exception){
            runCatching{file.writeBytes(fresh)}
            showDialog("Gen 1 → Gen 3 failed","${e.message?:"Unknown error"}. The fresh Gen 3 working save was restored and the Gen 1 Bank entry was kept.")
            return
        }
        Toast.makeText(this,"${p.nickname.ifBlank{gen1SpeciesNameFromInternal(p.species)}} converted Gen 1 → Gen 3 to Box ${target/30+1} • Slot ${target%30+1} and verified",Toast.LENGTH_LONG).show()
        showGen3PokemonViewer("boxes",target/30)
    }

    private fun buildLegalizedGen1BankPayload(
        originalBankBytes: ByteArray,
        plan: Gen1LegalFixPlan
    ): Pair<ByteArray, Gen1Pokemon> {
        require(originalBankBytes.size == GEN1_BANK_FILE_SIZE) {
            "The preserved Gen 1 Bank record has an unexpected size."
        }

        val fixed = originalBankBytes.copyOf()
        val o = GEN1_BANK_HEADER_SIZE

        writeU24BE(fixed, o + 14, plan.experience)

        for (i in 0..3) {
            fixed[o + 8 + i] = plan.moves[i].toByte()
            val currentPp = plan.pp[i].coerceIn(0, 63)
            fixed[o + 29 + i] = ((plan.ppUps[i].coerceIn(0, 3) shl 6) or currentPp).toByte()
        }

        val reparsed = parseGen1BankPayload(fixed)
            ?: throw IllegalArgumentException("The legalised Gen 1 Bank record could not be parsed.")

        require(reparsed.moves.contentEquals(plan.moves)) {
            "Move verification failed after legalising the Bank record."
        }
        require(reparsed.movePP.contentEquals(plan.pp)) {
            "PP verification failed after legalising the Bank record."
        }
        require(reparsed.movePpUps.contentEquals(plan.ppUps)) {
            "PP Up verification failed after legalising the Bank record."
        }
        require(reparsed.experience == plan.experience) {
            "EXP verification failed after legalising the Bank record."
        }

        return Pair(fixed, reparsed)
    }

    private fun showGen1MakeLegalAndTransfer(
        bankFile: File,
        p: Gen1Pokemon,
        originalBankBytes: ByteArray,
        saveData: ByteArray,
        trainer: TrainerData,
        moveSources: Map<Int, Gen1MoveSource>,
        speciesMeta: Gen1SpeciesMeta,
        transferMeta: Gen1ToGen7TransferMeta,
        illegalMoves: List<Int>
    ) {
        loadGen1MoveNamesAsync(illegalMoves) { moveNames ->
            val plan = buildGen1LegalFixPlan(p, moveSources, moveNames, speciesMeta)

            val illegalNames = illegalMoves.map { moveId ->
                val name = moveNames[moveId] ?: moveSources[moveId]?.name ?: "Move #$moveId"
                "$name (#$moveId)"
            }

            val message = buildString {
                append("This Gen 1 Bank Pokémon has moves that are not legal in Red/Blue/Yellow:\n\n")
                illegalNames.forEach { append("• ").append(it).append("\n") }

                if (plan.changes.isNotEmpty()) {
                    append("\nPSE can make the preserved record legal for this transfer:\n\n")
                    plan.changes.forEach { append("• ").append(it).append("\n") }
                }

                append("\nPSE will not invent replacement moves.")
                append("\n\nThe Bank file will remain unchanged while the transfer is prepared. ")
                append("It will only be removed after the converted Gen 7 Pokémon has been written and verified successfully.")
            }

            AlertDialog.Builder(this)
                .setTitle("Transfer blocked")
                .setMessage(message)
                .setNegativeButton("Cancel", null)
                .setPositiveButton("Make Legal & Transfer") { _, _ ->
                    val legalised = try {
                        buildLegalizedGen1BankPayload(originalBankBytes, plan)
                    } catch (e: Exception) {
                        showDialog(
                            "Make Legal & Transfer",
                            e.message ?: "PSE could not safely legalise the preserved Gen 1 record."
                        )
                        return@setPositiveButton
                    }

                    val legalBankBytes = legalised.first
                    val legalPokemon = legalised.second

                    // Re-run the same R/B/Y move legality rule against the
                    // in-memory legalised copy before any PK7 is produced.
                    val remainingIllegal = legalPokemon.moves.filter { moveId ->
                        if (moveId == 0) false
                        else {
                            val source = moveSources[moveId]
                            source == null ||
                                !(source.nonLevelSource ||
                                    (source.minimumLevel != null && source.minimumLevel <= legalPokemon.level))
                        }
                    }

                    if (remainingIllegal.isNotEmpty()) {
                        showDialog(
                            "Make Legal & Transfer",
                            "PSE could not resolve every illegal move, so the transfer was stopped. The Bank entry was not changed."
                        )
                        return@setPositiveButton
                    }

                    val convertedBytes = try {
                        buildGen1ToGen7Pk7(
                            legalBankBytes,
                            legalPokemon,
                            saveData,
                            trainer,
                            speciesMeta,
                            transferMeta
                        )
                    } catch (e: Exception) {
                        showDialog(
                            "Conversion failed",
                            e.message ?: "PSE could not create the Gen 7 conversion."
                        )
                        return@setPositiveButton
                    }

                    val parsed = parsePk6(
                        convertedBytes,
                        0,
                        PK6_STORED_SIZE,
                        false,
                        807
                    ) ?: run {
                        showDialog(
                            "Conversion failed",
                            "The legalised Gen 7 conversion could not be verified."
                        )
                        return@setPositiveButton
                    }

                    chooseGen1ToGen7Destination(
                        bankFile,
                        originalBankBytes,
                        legalBankBytes,
                        legalPokemon,
                        convertedBytes,
                        parsed
                    )
                }
                .show()
        }
    }

    private fun gen2BoxRawCore(data:ByteArray,box:Int,slot:Int):ByteArray {
        require(box in 1..14&&slot in 0 until 20){"Invalid Gen 2 box record location."}
        val base=gen2BoxOffset(box);val count=data[base].toInt() and 0xFF
        require(count in 0..20&&slot<count){"The Gen 2 box record is no longer present."}
        val start=base+22+slot*32
        require(start>=0&&start+32<=data.size){"The Gen 2 box record is outside the save."}
        return data.copyOfRange(start,start+32)
    }

    private fun buildGen1BankToGen2Record(bankBytes:ByteArray,p:Gen1Pokemon):Triple<ByteArray,ByteArray,ByteArray> {
        require(bankBytes.size==GEN1_BANK_FILE_SIZE){"The preserved Gen 1 Bank record has an unexpected size."}
        val dex=gen1DexFromInternalIndex(p.species)?:error("The Gen 1 species could not be mapped to the Gen 2 Pokédex.")
        require(dex in 1..151){"Only Generation 1 species can use this conversion."}
        val o=GEN1_BANK_HEADER_SIZE
        val mon=ByteArray(32)
        mon[0]=dex.toByte()
        // Time Capsule compatibility: the Gen 1 catch-rate byte becomes the Gen 2 held-item byte.
        mon[1]=bankBytes[o+7]
        for(i in 0..3)mon[2+i]=p.moves[i].toByte()
        writeU16BE(mon,6,p.tid)
        mon[8]=((p.experience ushr 16) and 0xFF).toByte();mon[9]=((p.experience ushr 8) and 0xFF).toByte();mon[10]=(p.experience and 0xFF).toByte()
        for(i in 0..4)writeU16BE(mon,11+i*2,p.statExp.getOrElse(i){0})
        mon[21]=bankBytes[o+27];mon[22]=bankBytes[o+28]
        for(i in 0..3)mon[23+i]=bankBytes[o+29+i]
        mon[27]=70 // traded Pokémon friendship baseline in Generation II
        mon[28]=0  // no Pokérus state exists in Generation I
        mon[29]=0;mon[30]=0 // no Generation II caught-data exists in Generation I
        mon[31]=p.level.coerceIn(1,100).toByte()
        val ot=bankBytes.copyOfRange(o+GEN1_BOX_MON_SIZE,o+GEN1_BOX_MON_SIZE+11)
        val nick=bankBytes.copyOfRange(o+GEN1_BOX_MON_SIZE+11,GEN1_BANK_FILE_SIZE)
        return Triple(mon,ot,nick)
    }

    private fun chooseGen1BankToGen2Destination(bankFile:File,p:Gen1Pokemon){
        val openedSource=currentSourceUri;val openedLabel=currentSourceLabel
        val file=importedFile?:return
        val data=runCatching{file.readBytes()}.getOrNull()?:return
        val profile=detectGen2Profile(data)?:run{showDialog("Transfer to Gen 2","Load a valid Gold, Silver or Crystal save first.");return}
        val targets=availableGen2BoxTargets(data)
        if(targets.isEmpty()){showDialog("Transfer to Gen 2","All 14 Gen 2 PC boxes are full or unavailable.");return}
        val labels=targets.map{gen2BoxDestinationLabel(it.first,it.second,file,profile,currentSourceUri,data)}.toTypedArray()
        var consumed=false
        AlertDialog.Builder(this)
            .setTitle("Transfer ${p.nickname.ifBlank{gen1SpeciesNameFromInternal(p.species)}} to ${profile.displayName}")
            .setMessage("PSE will convert the preserved RBY record to the compatible Generation II box structure, preserve OT/TID, nickname, EXP, Stat Exp, DVs, moves and PP Ups, apply the Time Capsule held-item interpretation, then re-read and verify the destination before removing the Gen 1 Bank copy.\n\nContinue to choose the destination PC Box.")
            .setPositiveButton("Choose Gen 2 Box") { _, _ ->
                AlertDialog.Builder(this)
                    .setTitle("Choose Gen 2 PC Box")
                    .setItems(labels){_,which->
                        if(consumed||which !in targets.indices){showDialog("Transfer to Gen 2","This destination choice was already handled or is invalid. Reopen the Bank entry. Nothing was changed.");return@setItems}
                        consumed=true
                        transferGen1BankToGen2(bankFile,p,targets[which].first,file,data,openedSource,openedLabel,profile.key)
                    }
                    .setNegativeButton("Cancel",null)
                    .show()
            }
            .setNegativeButton("Cancel",null)
            .show()
    }

    private fun transferGen1BankToGen2(bankFile:File,p:Gen1Pokemon,targetBox:Int,openedFile:File,openedDestination:ByteArray,openedSource:Uri?,openedLabel:String?,profileKey:String){
        val file=openedFile
        fun bound()=importedFile?.absolutePath==file.absolutePath&&currentSourceUri==openedSource&&currentSourceLabel==openedLabel
        val fresh=runCatching{file.readBytes()}.getOrElse{showDialog("Gen 1 → Gen 2 transfer failed","The fresh destination save could not be read. Nothing was changed.");return}
        var committedSlot=-1
        var writeStarted=false;var bankDeleteAttempted=false
        var recoveryBankBytes:ByteArray?=null
        var safetyBackup:File?=null
        try{
            require(bound()&&fresh.contentEquals(openedDestination)&&verifyGen2SaveIntegrity(fresh).first){"The selected destination save or source identity changed. Reopen the Bank entry."}
            val profile=detectGen2Profile(fresh)?:error("The loaded destination is no longer a valid Gen 2 save.")
            require(profile.key==profileKey){"The selected Gen 2 destination profile changed."}
            require(targetBox in 1..14){"Invalid Gen 2 destination box."}
            val base=gen2BoxOffset(targetBox);val beforeCount=fresh[base].toInt() and 0xFF
            require(beforeCount in 0..19){"Box $targetBox is full or structurally invalid."}
            val before=parseGen2Box(fresh,targetBox).sortedBy{it.slot}
            require(before.size==beforeCount){"Box $targetBox contains an invalid Pokémon record."}
            val bankBytes=runCatching{bankFile.readBytes()}.getOrElse{error("The selected Gen 1 Bank record could not be read.")}
            val source=parseGen1BankPayload(bankBytes)?:error("The selected Gen 1 Bank record failed validation.")
            require(sameGen1TransferRecord(source,p)){"The selected Gen 1 Bank record changed before transfer. Nothing was changed."}
            recoveryBankBytes=bankBytes.copyOf()
            val (mon,ot,nick)=buildGen1BankToGen2Record(bankBytes,source)
            val work=fresh.copyOf()
            val slot=appendGen2BoxPokemon(work,targetBox,mon,ot,nick)
            val dex=gen1DexFromInternalIndex(source.species)?:error("Species mapping failed during Pokédex registration.")
            val dexIndex=dex-1;val dexMask:Int=1 shl(dexIndex and 7);val dexByte=dexIndex/8
            val ownedBase=if(profile.key=="C")0x2A27 else 0x2A4C
            val seenBase=if(profile.key=="C")0x2A47 else 0x2A6C
            work[ownedBase+dexByte]=(work[ownedBase+dexByte].toInt() or dexMask).toByte()
            work[seenBase+dexByte]=(work[seenBase+dexByte].toInt() or dexMask).toByte()
            updateGen2PrimaryChecksum(work,profile)
            require(gen2ChecksumValid(work,profile)){"The Gen 2 primary checksum could not be rebuilt after Pokédex registration."}
            fun matches(q:Gen2Pokemon)=q.species==dex&&q.tid==source.tid&&q.nickname==source.nickname&&q.otName==source.otName&&q.level==source.level&&q.heldItem==(bankBytes[GEN1_BANK_HEADER_SIZE+7].toInt() and 0xFF)&&q.experience==source.experience&&q.moves.contentEquals(source.moves)&&q.movePP.contentEquals(source.movePP)&&q.statExp.contentEquals(source.statExp)&&q.dvs.contentEquals(source.dvs)&&q.happiness==70&&q.pokerus==0&&q.caughtData==0
            fun sameGen2(a:Gen2Pokemon,b:Gen2Pokemon)=a.species==b.species&&a.tid==b.tid&&a.nickname==b.nickname&&a.otName==b.otName&&a.level==b.level&&a.heldItem==b.heldItem&&a.experience==b.experience&&a.moves.contentEquals(b.moves)&&a.movePP.contentEquals(b.movePP)&&a.statExp.contentEquals(b.statExp)&&a.dvs.contentEquals(b.dvs)&&a.happiness==b.happiness&&a.pokerus==b.pokerus&&a.caughtData==b.caughtData
            val staged=parseGen2Box(work,targetBox).sortedBy{it.slot};require(staged.size==before.size+1){"The staged Gen 2 box count did not increase by one."}
            require(staged.take(before.size).zip(before).all{(a,b)->sameGen2(a,b)}){"An existing Gen 2 box record changed during staging."}
            val stagedCopy=staged.firstOrNull{it.slot==slot};require(stagedCopy!=null&&matches(stagedCopy)){"The staged Gen 2 Pokémon did not preserve every supported field."}
            require(gen2BoxRawCore(work,targetBox,slot).contentEquals(mon)){"The staged Gen 2 record did not preserve the exact converted bytes, including PP Ups."}
            require((work[ownedBase+dexByte].toInt() and dexMask)!=0&&(work[seenBase+dexByte].toInt() and dexMask)!=0){"The staged Gen 2 Pokédex flags did not verify."}
            require(verifyGen2SaveIntegrity(work).first){"The complete staged Gen 2 destination failed integrity verification."}
            val backup=File.createTempFile(backupGameName(file)+"_PreGen1BankTransfer_",".backup",backupsDir());safetyBackup=backup
            backup.writeBytes(fresh);require(backup.readBytes().contentEquals(fresh)){"The recovery backup did not persist exactly."}
            retainGen2SafetyBackup(backup,fresh)
            require(bound()&&file.readBytes().contentEquals(fresh)&&bankFile.readBytes().contentEquals(bankBytes)&&backup.readBytes().contentEquals(fresh)&&isBackupKept(backup)){"The destination, Bank record, source identity or retained backup changed before writing."}
            writeStarted=true
            file.writeBytes(work)
            val written=file.readBytes();require(written.contentEquals(work)){"The Gen 2 destination changed while the transfer was being written."};val writtenProfile=detectGen2Profile(written)?:error("The written Gen 2 save failed checksum verification.")
            require(bound()&&writtenProfile.key==profileKey&&verifyGen2SaveIntegrity(written).first){"The complete persisted destination or source identity did not verify."}
            val after=parseGen2Box(written,targetBox).sortedBy{it.slot};require(after.size==before.size+1){"The persisted Gen 2 box count did not increase by one."}
            require(after.take(before.size).zip(before).all{(a,b)->sameGen2(a,b)}){"An existing Gen 2 box record changed after persistence."}
            val q=after.firstOrNull{it.slot==slot};require(q!=null&&matches(q)){"The converted Gen 2 Pokémon did not preserve every supported field after re-reading."}
            require(gen2BoxRawCore(written,targetBox,slot).contentEquals(mon)){"The persisted Gen 2 record changed from the exact staged bytes, including PP Ups."}
            val verifyOwned=if(writtenProfile.key=="C")0x2A27 else 0x2A4C
            val verifySeen=if(writtenProfile.key=="C")0x2A47 else 0x2A6C
            require((written[verifyOwned+dexByte].toInt() and dexMask)!=0&&(written[verifySeen+dexByte].toInt() and dexMask)!=0){"The transferred Pokémon did not register as Seen and Owned in the Gen 2 Pokédex."}
            require(gen2ChecksumValid(written,writtenProfile)){"The Gen 2 save checksum did not remain valid."}
            val committedBank=bankFile.readBytes();require(committedBank.contentEquals(bankBytes) && parseGen1BankPayload(committedBank)?.let{sameGen1TransferRecord(it,source)}==true){"The selected Gen 1 Bank record changed before cleanup; Bank removal was stopped."}
            require(bound()&&file.readBytes().contentEquals(written)){"The destination changed before Bank cleanup."}
            bankDeleteAttempted=true
            require(bankFile.delete()){"The verified destination was written, but Bank cleanup failed."}
            require(!bankFile.exists()){"The Bank deletion could not be verified."}
            committedSlot=slot
        }catch(e:Exception){
            val bankRestored=!writeStarted||runCatching{
                val expected=recoveryBankBytes?:error("The original Bank payload is unavailable.")
                if(bankDeleteAttempted){
                    if(bankFile.exists())require(bankFile.readBytes().contentEquals(expected)){"An existing Bank recovery path changed; it was not overwritten."}
                    else{require(bankFile.createNewFile()){"A Bank recovery path could not be reserved."};bankFile.writeBytes(expected)}
                }
                require(bankFile.readBytes().contentEquals(expected)){"The original Bank payload could not be kept or restored exactly."}
            }.isSuccess
            val restored=writeStarted&&bankRestored&&runCatching{file.writeBytes(fresh)}.isSuccess&&runCatching{file.readBytes().contentEquals(fresh)&&verifyGen2SaveIntegrity(fresh).first}.getOrDefault(false)
            val recovery=if(!writeStarted)"Nothing was written to the destination save or removed from Bank." else  if(restored)"The exact previous destination and original Bank record were kept or restored and verified." else  "Automatic recovery could not be verified. Stop editing; keep the working save and remaining Bank records, and restore the kept recovery backup only after reviewing Bank recovery."
            showDialog("Gen 1 → Gen 2 transfer failed",(e.message?:"Unknown error")+"\n\n"+recovery+(safetyBackup?.let{"\n\nRecovery backup: "+it.name}?:""))
            return
        }
        Toast.makeText(this,"Transferred to Gen 2 Box $targetBox • Slot ${committedSlot+1} and verified",Toast.LENGTH_LONG).show()
        showGen2PokemonViewer("boxes",targetBox)
    }

    private fun prepareGen1ForwardTransfer(bankFile: File, p: Gen1Pokemon) {
        val originalBankBytes = runCatching { bankFile.readBytes() }.getOrNull() ?: run {
            showDialog("Transfer Forward", "PSE could not read the preserved Gen 1 Bank entry.")
            return
        }
        val destination = importedFile ?: run {
            showDialog("Transfer Forward", "Load a Pokémon Sun, Moon, Ultra Sun or Ultra Moon save first.")
            return
        }
        val saveData = runCatching { destination.readBytes() }.getOrNull() ?: return
        if (generationForSize(saveData.size) != 7) {
            val gen = generationForSize(saveData.size)
            val reason = if (gen == 6)
                "There is no official Gen 1 → Gen 6 transfer path. Virtual Console Gen 1 Pokémon transfer through Poké Transporter/Bank into Generation 7."
            else
                "Load a Generation 7 save to use the Gen 1 forward-transfer conversion."
            showDialog("Transfer Forward", reason)
            return
        }

        val dex = gen1DexFromInternalIndex(p.species) ?: return
        val trainer = analyzeSave(destination).trainer ?: run {
            showDialog("Transfer Forward", "PSE could not read the destination Gen 7 trainer data.")
            return
        }

        val loading = AlertDialog.Builder(this)
            .setTitle("Prepare Gen 1 → Gen 7")
            .setMessage("Checking the preserved Gen 1 record and preparing a Bank-style PK7 conversion…")
            .setCancelable(false)
            .create()
        loading.show()

        loadGen1MoveSourcesAsync(dex) { moveSources ->
            loadGen1SpeciesMetaAsync(dex) { speciesMeta ->
                loadGen1ToGen7TransferMetaAsync(dex, p.moves) { transferMeta ->
                    if (loading.isShowing) loading.dismiss()

                    if (moveSources == null || speciesMeta == null || transferMeta == null) {
                        showDialog(
                            "Transfer Forward",
                            "PSE could not load all conversion data. Check your connection and try again; the Gen 1 Bank record was not changed."
                        )
                        return@loadGen1ToGen7TransferMetaAsync
                    }

                    val illegalMoves = p.moves.filter { moveId ->
                        if (moveId == 0) false
                        else {
                            val source = moveSources[moveId]
                            source == null || !(source.nonLevelSource || (source.minimumLevel != null && source.minimumLevel <= p.level))
                        }
                    }
                    if (illegalMoves.isNotEmpty()) {
                        showGen1MakeLegalAndTransfer(
                            bankFile = bankFile,
                            p = p,
                            originalBankBytes = originalBankBytes,
                            saveData = saveData,
                            trainer = trainer,
                            moveSources = moveSources,
                            speciesMeta = speciesMeta,
                            transferMeta = transferMeta,
                            illegalMoves = illegalMoves
                        )
                        return@loadGen1ToGen7TransferMetaAsync
                    }

                    val converted = try {
                        buildGen1ToGen7Pk7(originalBankBytes, p, saveData, trainer, speciesMeta, transferMeta)
                    } catch (e: Exception) {
                        showDialog("Conversion failed", e.message ?: "PSE could not create the PK7 conversion.")
                        return@loadGen1ToGen7TransferMetaAsync
                    }

                    val parsed = parsePk6(converted, 0, PK6_STORED_SIZE, false, 807)
                        ?: return@loadGen1ToGen7TransferMetaAsync
                    chooseGen1ToGen7Destination(bankFile, originalBankBytes, originalBankBytes, p, converted, parsed)
                }
            }
        }
    }

    private fun chooseGen1ToGen7Destination(
        bankFile: File,
        originalBankBytes: ByteArray,
        preparedBankBytes: ByteArray,
        source: Gen1Pokemon,
        convertedPk7: ByteArray,
        converted: PokemonEntry
    ) {
        val file = importedFile ?: return
        val data = runCatching { file.readBytes() }.getOrNull() ?: return
        if (generationForSize(data.size) != 7) {
            showDialog("Transfer Forward", "The loaded destination is no longer a Generation 7 save.")
            return
        }

        val (boxOffset, slotCount, maxSpecies) = boxStorageInfo(data) ?: return
        val firstEmpty = findFirstEmptyBoxSlot(data, boxOffset, slotCount, maxSpecies)
        if (firstEmpty == null) {
            showDialog("Transfer Forward", "No empty Gen 7 PC box slot was found.")
            return
        }

        val firstBox = firstEmpty / 30 + 1
        val firstSlot = firstEmpty % 30 + 1

        AlertDialog.Builder(this)
            .setTitle("Transfer ${source.nickname.ifBlank { gen1SpeciesNameFromInternal(source.species) }} to Gen 7…")
            .setMessage(
                "PSE has created and verified a PK7 conversion using the Virtual Console → Bank transfer rules.\n\n" +
                "Choose where to place the Pokémon.\n\n" +
                "The original Gen 1 Bank record will not be removed until the Gen 7 save write verifies successfully."
            )
            .setPositiveButton("First Empty ($firstBox/$firstSlot)") { _, _ ->
                transferGen1BankToGen7(
                    bankFile,
                    originalBankBytes,
                    preparedBankBytes,
                    source,
                    convertedPk7,
                    converted,
                    firstEmpty
                )
            }
            .setNeutralButton("Choose Box / Slot") { _, _ ->
                showGen1ToGen7BoxPicker(
                    bankFile,
                    originalBankBytes,
                    preparedBankBytes,
                    source,
                    convertedPk7,
                    converted
                )
            }
            .setNegativeButton("Cancel", null)
            .show()
    }

    private fun showGen1ToGen7BoxPicker(
        bankFile: File,
        originalBankBytes: ByteArray,
        preparedBankBytes: ByteArray,
        source: Gen1Pokemon,
        convertedPk7: ByteArray,
        converted: PokemonEntry
    ) {
        val file = importedFile ?: return
        val data = runCatching { file.readBytes() }.getOrNull() ?: return

        if (generationForSize(data.size) != 7) {
            showDialog("Transfer Forward", "The loaded destination is no longer a Generation 7 save.")
            return
        }

        val (boxOffset, slotCount, maxSpecies) = boxStorageInfo(data) ?: return
        val boxCount = slotCount / 30
        val labels = ArrayList<String>()

        for (box in 0 until boxCount) {
            val empty = countEmptySlotsInBox(data, boxOffset, box, maxSpecies)
            labels.add(
                "Box ${box + 1} • $empty empty slot${if (empty == 1) "" else "s"}"
            )
        }

        AlertDialog.Builder(this)
            .setTitle("Choose Gen 7 Box")
            .setItems(labels.toTypedArray()) { _, boxIndex ->
                val empty = countEmptySlotsInBox(data, boxOffset, boxIndex, maxSpecies)
                if (empty <= 0) {
                    showDialog(
                        "Box ${boxIndex + 1}",
                        "This box is full. Choose another box."
                    )
                } else {
                    showGen1ToGen7SlotGrid(
                        bankFile,
                        originalBankBytes,
                        preparedBankBytes,
                        source,
                        convertedPk7,
                        converted,
                        boxIndex
                    )
                }
            }
            .setNegativeButton("Back") { _, _ ->
                chooseGen1ToGen7Destination(
                    bankFile,
                    originalBankBytes,
                    preparedBankBytes,
                    source,
                    convertedPk7,
                    converted
                )
            }
            .show()
    }

    private fun showGen1ToGen7SlotGrid(
        bankFile: File,
        originalBankBytes: ByteArray,
        preparedBankBytes: ByteArray,
        source: Gen1Pokemon,
        convertedPk7: ByteArray,
        converted: PokemonEntry,
        boxIndex: Int
    ) {
        val file = importedFile ?: return
        val data = runCatching { file.readBytes() }.getOrNull() ?: return
        val (boxOffset, slotCount, maxSpecies) = boxStorageInfo(data) ?: return
        if (generationForSize(data.size) != 7 || boxIndex !in 0 until (slotCount / 30)) return

        val wrapper = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(dp(12), dp(8), dp(12), dp(8))
        }
        addMutedLine(wrapper, "Tap an empty Gen 7 slot. Occupied slots are disabled.")
        val grid = GridLayout(this).apply {
            columnCount = 6
            rowCount = 5
            alignmentMode = GridLayout.ALIGN_BOUNDS
            useDefaultMargins = false
        }
        val cellWidth = ((resources.displayMetrics.widthPixels - dp(90)) / 6).coerceAtLeast(dp(42))
        for (slot in 0 until 30) {
            val global = boxIndex * 30 + slot
            val occupied = parsePk6(
                data, boxOffset + global * PK6_STORED_SIZE,
                PK6_STORED_SIZE, false, maxSpecies
            ) != null
            val cell = TextView(this).apply {
                text = if (occupied) "●\n${slot + 1}" else "○\n${slot + 1}"
                gravity = Gravity.CENTER
                textSize = 13f
                setTextColor(if (occupied) Color.rgb(105,105,105) else TEXT)
                setBackgroundColor(if (occupied) Color.rgb(35,35,35) else Color.rgb(55,55,55))
                isEnabled = !occupied
                if (!occupied) setOnClickListener {
                    transferGen1BankToGen7(bankFile, originalBankBytes, preparedBankBytes, source, convertedPk7, converted, global)
                }
            }
            grid.addView(cell, GridLayout.LayoutParams().apply {
                width = cellWidth
                height = dp(58)
                setMargins(dp(2),dp(2),dp(2),dp(2))
            })
        }
        wrapper.addView(grid)
        AlertDialog.Builder(this)
            .setTitle("Box ${boxIndex + 1} • choose Gen 7 slot")
            .setView(wrapper)
            .setNegativeButton("Back") { _, _ ->
                chooseGen1ToGen7Destination(bankFile, originalBankBytes, preparedBankBytes, source, convertedPk7, converted)
            }
            .setNeutralButton("Cancel", null)
            .show()
    }

    private fun transferGen1BankToGen7(
        bankFile: File,
        originalBankBytes: ByteArray,
        preparedBankBytes: ByteArray,
        source: Gen1Pokemon,
        convertedPk7: ByteArray,
        converted: PokemonEntry,
        target: Int
    ) {
        val file = importedFile ?: return
        val fresh = runCatching { file.readBytes() }.getOrElse {
            showDialog("Transfer Forward", "The fresh Gen 7 destination save could not be read. Nothing was changed.")
            return
        }
        try {
            require(generationForSize(fresh.size) == 7) { "The loaded destination is no longer a Gen 7 save." }
            val info = boxStorageInfo(fresh) ?: error("PSE could not resolve the Gen 7 PC storage.")
            val (boxOffset, slotCount, maxSpecies) = info
            require(target in 0 until slotCount) { "The selected Gen 7 destination slot is invalid." }
            val storageLength = slotCount * PK6_STORED_SIZE
            require(boxOffset >= 0 && boxOffset + storageLength <= fresh.size) { "The Gen 7 PC storage is outside the save." }
            val (freshChecksumsOk, freshChecksumMessage) = validateGen7CoreChecksums(fresh)
            require(freshChecksumsOk) { freshChecksumMessage }

            require(originalBankBytes.size == GEN1_BANK_FILE_SIZE && preparedBankBytes.size == GEN1_BANK_FILE_SIZE) {
                "The captured Gen 1 Bank payload has an unexpected size."
            }
            val currentBank = runCatching { bankFile.readBytes() }.getOrElse {
                error("The selected Gen 1 Bank record could not be read.")
            }
            require(currentBank.contentEquals(originalBankBytes)) {
                "The selected Gen 1 Bank record changed before transfer. Nothing was changed."
            }
            val originalSource = parseGen1BankPayload(currentBank)
                ?: error("The selected Gen 1 Bank record failed validation.")
            val preparedSource = parseGen1BankPayload(preparedBankBytes)
                ?: error("The prepared Gen 1 transfer record failed validation.")
            require(sameGen1TransferRecord(preparedSource, source)) {
                "The prepared Gen 1 transfer record no longer matches the confirmed conversion."
            }
            val payload = GEN1_BANK_HEADER_SIZE
            fun legalisedField(index: Int) =
                index in payload + 8..payload + 11 ||
                    index in payload + 14..payload + 16 ||
                    index in payload + 29..payload + 32
            require(originalBankBytes.indices.all { index ->
                originalBankBytes[index] == preparedBankBytes[index] || legalisedField(index)
            }) { "The prepared Gen 1 record changed a field outside the approved legalisation set." }
            for (i in 0..3) {
                require(
                    (originalBankBytes[payload + 29 + i].toInt() and 0xC0) ==
                        (preparedBankBytes[payload + 29 + i].toInt() and 0xC0)
                ) { "Move legalisation changed a preserved PP Up value." }
            }

            fun samePk7(a: PokemonEntry, b: PokemonEntry) =
                a.species == b.species && a.nickname == b.nickname && a.isNicknamed == b.isNicknamed &&
                    a.level == b.level && a.checksumValid && b.checksumValid && a.heldItem == b.heldItem &&
                    a.tid == b.tid && a.sid == b.sid && a.experience == b.experience &&
                    a.ability == b.ability && a.abilityNumber == b.abilityNumber && a.pid == b.pid &&
                    a.nature == b.nature && a.gender == b.gender && a.form == b.form &&
                    a.evs.contentEquals(b.evs) && a.moves.contentEquals(b.moves) &&
                    a.movePP.contentEquals(b.movePP) && a.ivs.contentEquals(b.ivs) &&
                    a.isEgg == b.isEgg && a.otName == b.otName && a.friendship == b.friendship &&
                    a.currentHandler == b.currentHandler && a.pokerusDays == b.pokerusDays &&
                    a.pokerusStrain == b.pokerusStrain && a.shiny == b.shiny &&
                    a.language == b.language && a.markingValue == b.markingValue &&
                    a.fatefulEncounter == b.fatefulEncounter && a.relearnMoves.contentEquals(b.relearnMoves) &&
                    a.eggLocation == b.eggLocation && a.metLocation == b.metLocation &&
                    a.ball == b.ball && a.metLevel == b.metLevel && a.otGender == b.otGender &&
                    a.originGame == b.originGame && a.country == b.country && a.region == b.region &&
                    a.consoleRegion == b.consoleRegion && a.eggYear == b.eggYear &&
                    a.eggMonth == b.eggMonth && a.eggDay == b.eggDay && a.metYear == b.metYear &&
                    a.metMonth == b.metMonth && a.metDay == b.metDay &&
                    a.hyperTrainFlags == b.hyperTrainFlags
            require(convertedPk7.size == PK6_STORED_SIZE) { "The prepared PK7 has an unexpected size." }
            val prepared = parsePk6(convertedPk7, 0, PK6_STORED_SIZE, false, 807)
                ?: error("The prepared PK7 could not be parsed.")
            require(samePk7(prepared, converted) && prepared.tid == preparedSource.tid) {
                "The prepared PK7 no longer matches the confirmed conversion. Nothing was changed."
            }

            val offset = boxOffset + target * PK6_STORED_SIZE
            require(offset >= boxOffset && offset + PK6_STORED_SIZE <= boxOffset + storageLength) {
                "The selected Gen 7 destination slot is outside PC storage."
            }
            require(parsePk6(fresh, offset, PK6_STORED_SIZE, false, maxSpecies) == null) {
                "That Gen 7 slot is no longer empty."
            }
            val beforeStorage = fresh.copyOfRange(boxOffset, boxOffset + storageLength)
            val selectedStart = target * PK6_STORED_SIZE
            val selectedEnd = selectedStart + PK6_STORED_SIZE
            fun pcStorageIsolated(data: ByteArray): Boolean {
                if (data.size != fresh.size) return false
                val after = data.copyOfRange(boxOffset, boxOffset + storageLength)
                return after.indices.all { it in selectedStart until selectedEnd || after[it] == beforeStorage[it] }
            }

            val work = fresh.copyOf()
            convertedPk7.copyInto(work, offset)
            val stagedBytes = work.copyOfRange(offset, offset + PK6_STORED_SIZE)
            val staged = parsePk6(stagedBytes, 0, PK6_STORED_SIZE, false, 807)
                ?: error("The staged PK7 could not be parsed.")
            require(stagedBytes.contentEquals(convertedPk7) && samePk7(staged, prepared)) {
                "The staged PK7 did not preserve every supported converted field."
            }
            require(pcStorageIsolated(work)) { "Unrelated Gen 7 PC data changed during staging." }
            registerGen7Dex(work, staged.species, staged.form, staged.gender, staged.shiny, staged.language)
            updateGen7SaveBlockChecksum(work, 14, boxOffset, storageLength)
            val dexInfo = gen7BlockInfo(work, 6) ?: error("Gen 7 Pokédex block layout is unavailable.")
            updateGen7SaveBlockChecksum(work, 6, dexInfo.first, dexInfo.second)
            finalizeGen7Save(work)
            require(gen7DexRegistered(work, staged)) {
                "The staged Gen 7 Pokédex registration did not verify."
            }
            val (stagedChecksumsOk, stagedChecksumMessage) = validateGen7CoreChecksums(work)
            require(stagedChecksumsOk) { stagedChecksumMessage }
            require(pcStorageIsolated(work)) { "Unrelated Gen 7 PC data changed while rebuilding integrity data." }

            file.writeBytes(work)
            val written = file.readBytes()
            require(written.contentEquals(work)) { "The Gen 7 destination changed while the transfer was being written." }
            require(boxStorageInfo(written) == info) { "The persisted Gen 7 PC layout changed unexpectedly." }
            val actual = written.copyOfRange(offset, offset + PK6_STORED_SIZE)
            val persisted = parsePk6(actual, 0, PK6_STORED_SIZE, false, 807)
                ?: error("The persisted PK7 could not be parsed.")
            require(actual.contentEquals(convertedPk7) && samePk7(persisted, prepared)) {
                "The persisted PK7 did not preserve every supported converted field."
            }
            require(gen7DexRegistered(written, persisted)) {
                "The persisted Gen 7 Pokédex registration did not verify."
            }
            val (writtenChecksumsOk, writtenChecksumMessage) = validateGen7CoreChecksums(written)
            require(writtenChecksumsOk) { writtenChecksumMessage }
            require(pcStorageIsolated(written)) { "Unrelated Gen 7 PC data changed after persistence." }

            val cleanupBank = runCatching { bankFile.readBytes() }.getOrElse {
                error("The selected Gen 1 Bank record could not be re-read before cleanup.")
            }
            require(cleanupBank.contentEquals(originalBankBytes) && parseGen1BankPayload(cleanupBank)?.let { sameGen1TransferRecord(it, originalSource) } == true) {
                "The selected Gen 1 Bank record changed before cleanup."
            }
            if (!bankFile.delete()) {
                file.writeBytes(fresh)
                error("The Gen 7 write verified, but the Bank entry could not be removed; the fresh destination save was restored.")
            }
        } catch (e: Exception) {
            runCatching { file.writeBytes(fresh) }
            showDialog(
                "Transfer Forward failed",
                "${e.message ?: "Unknown error"}\n\nThe fresh Gen 7 working save was restored and the Gen 1 Bank entry was kept."
            )
            return
        }

        val box = target / 30 + 1
        val slot = target % 30 + 1
        Toast.makeText(
            this,
            "${source.nickname.ifBlank { gen1SpeciesNameFromInternal(source.species) }} transferred Gen 1 → Gen 7 to Box $box • Slot $slot and verified",
            Toast.LENGTH_LONG
        ).show()
        showPokemonViewer("boxes", box - 1)
    }


    private fun prettyMoveName(raw: String): String =
        raw.split("-").joinToString(" ") { part ->
            part.replaceFirstChar { ch -> if (ch.isLowerCase()) ch.titlecase(Locale.US) else ch.toString() }
        }

    private fun parseIdFromPokeApiUrl(url: String): Int? =
        url.trimEnd('/').substringAfterLast('/').toIntOrNull()

    private fun decodeGen1MoveSources(encoded: String): Map<Int, Gen1MoveSource>? = try {
        val root = JSONObject(encoded)
        val array = root.getJSONArray("moves")
        val out = HashMap<Int, Gen1MoveSource>()
        for (i in 0 until array.length()) {
            val j = array.getJSONObject(i)
            val level = if (j.isNull("minLevel")) null else j.getInt("minLevel")
            val source = Gen1MoveSource(
                j.getInt("id"),
                j.getString("name"),
                j.getBoolean("nonLevel"),
                level
            )
            out[source.moveId] = source
        }
        out
    } catch (_: Exception) { null }

    private fun encodeGen1MoveSources(sources: Map<Int, Gen1MoveSource>): String =
        JSONObject().apply {
            put("moves", JSONArray().apply {
                sources.values.sortedBy { it.moveId }.forEach { source ->
                    put(JSONObject().apply {
                        put("id", source.moveId)
                        put("name", source.name)
                        put("nonLevel", source.nonLevelSource)
                        if (source.minimumLevel == null) put("minLevel", JSONObject.NULL)
                        else put("minLevel", source.minimumLevel)
                    })
                }
            })
        }.toString()

    private fun fetchJsonObject(urlText: String): JSONObject? {
        val connection = URL(urlText).openConnection() as HttpsURLConnection
        return try {
            connection.connectTimeout = 8000
            connection.readTimeout = 8000
            connection.instanceFollowRedirects = true
            connection.connect()
            if (connection.responseCode !in 200..299) null
            else JSONObject(connection.inputStream.bufferedReader().use { it.readText() })
        } finally {
            connection.disconnect()
        }
    }

    private fun mergeGen1MoveSourcesFromPokemon(
        pokemonJson: JSONObject,
        out: MutableMap<Int, Gen1MoveSource>
    ) {
        val moves = pokemonJson.optJSONArray("moves") ?: return
        val allowedVersionGroups = setOf("red-blue", "yellow")

        for (i in 0 until moves.length()) {
            val moveEntry = moves.optJSONObject(i) ?: continue
            val moveObj = moveEntry.optJSONObject("move") ?: continue
            val moveId = parseIdFromPokeApiUrl(moveObj.optString("url")) ?: continue
            if (moveId !in 1..165) continue

            val rawName = moveObj.optString("name", "move-$moveId")
            var hasNonLevelSource = false
            var minimumLevel: Int? = null

            val details = moveEntry.optJSONArray("version_group_details") ?: continue
            for (d in 0 until details.length()) {
                val detail = details.optJSONObject(d) ?: continue
                val versionGroup = detail.optJSONObject("version_group")?.optString("name") ?: continue
                if (versionGroup !in allowedVersionGroups) continue

                val method = detail.optJSONObject("move_learn_method")?.optString("name") ?: continue
                val learnedAt = detail.optInt("level_learned_at", 0)

                if (method == "level-up") {
                    val normalizedLevel = if (learnedAt <= 0) 1 else learnedAt
                    minimumLevel = if (minimumLevel == null) normalizedLevel else minOf(minimumLevel, normalizedLevel)
                } else {
                    // TM/HM and any legitimate special Gen 1 acquisition method.
                    hasNonLevelSource = true
                }
            }

            if (!hasNonLevelSource && minimumLevel == null) continue

            val existing = out[moveId]
            out[moveId] = Gen1MoveSource(
                moveId = moveId,
                name = existing?.name ?: prettyMoveName(rawName),
                nonLevelSource = (existing?.nonLevelSource == true) || hasNonLevelSource,
                minimumLevel = when {
                    existing?.minimumLevel == null -> minimumLevel
                    minimumLevel == null -> existing.minimumLevel
                    else -> minOf(existing.minimumLevel, minimumLevel)
                }
            )
        }
    }

    private fun loadGen1MoveSourcesAsync(dex: Int, done: (Map<Int, Gen1MoveSource>?) -> Unit) {
        val cacheKey = "gen1_rby_move_sources_$dex"
        metaPrefs.getString(cacheKey, null)?.let { cached ->
            decodeGen1MoveSources(cached)?.let {
                done(it)
                return
            }
        }

        imageExecutor.execute {
            val result = try {
                val merged = HashMap<Int, Gen1MoveSource>()
                var speciesRef: String? = dex.toString()
                val visited = HashSet<String>()

                // Current species + every pre-evolution. This lets evolved Pokémon
                // legally retain moves learned before evolving.
                while (!speciesRef.isNullOrBlank() && visited.add(speciesRef)) {
                    val speciesJson = fetchJsonObject("https://pokeapi.co/api/v2/pokemon-species/$speciesRef")
                        ?: break
                    val speciesName = speciesJson.optString("name", speciesRef)
                    fetchJsonObject("https://pokeapi.co/api/v2/pokemon/$speciesName")
                        ?.let { mergeGen1MoveSourcesFromPokemon(it, merged) }

                    val pre = speciesJson.optJSONObject("evolves_from_species")
                    speciesRef = if (pre == null) null else pre.optString("name").takeIf { it.isNotBlank() }
                }

                merged.takeIf { it.isNotEmpty() }
            } catch (_: Exception) {
                null
            }

            if (result != null) {
                metaPrefs.edit().putString(cacheKey, encodeGen1MoveSources(result)).apply()
            }
            mainHandler.post {
                if (!isFinishing && !isDestroyed) done(result)
            }
        }
    }

    private fun gen1MoveDisplayName(moveId: Int, sources: Map<Int, Gen1MoveSource>?): String =
        sources?.get(moveId)?.name ?: "Move #$moveId"


    private fun loadGen1MoveNamesAsync(moveIds: Collection<Int>, done: (Map<Int, String>) -> Unit) {
        val ids = moveIds.filter { it in 1..165 }.distinct()
        if (ids.isEmpty()) {
            done(emptyMap())
            return
        }

        imageExecutor.execute {
            val names = linkedMapOf<Int, String>()
            for (moveId in ids) {
                val key = "gen1_move_name_$moveId"
                val cached = metaPrefs.getString(key, null)
                if (!cached.isNullOrBlank()) {
                    names[moveId] = cached
                    continue
                }

                try {
                    val json = fetchJsonObject("https://pokeapi.co/api/v2/move/$moveId")
                    val raw = json?.optString("name").orEmpty()
                    if (raw.isNotBlank()) {
                        val pretty = prettyMoveName(raw)
                        names[moveId] = pretty
                        metaPrefs.edit().putString(key, pretty).apply()
                    }
                } catch (_: Exception) { }
            }

            mainHandler.post {
                if (!isFinishing && !isDestroyed) done(names)
            }
        }
    }

    data class Gen1LegalFixPlan(
        val moves: IntArray,
        val pp: IntArray,
        val ppUps: IntArray,
        val experience: Long,
        val changes: List<String>
    )

    private fun buildGen1LegalFixPlan(
        p: Gen1Pokemon,
        moveSources: Map<Int, Gen1MoveSource>,
        moveNames: Map<Int, String>,
        meta: Gen1SpeciesMeta?
    ): Gen1LegalFixPlan {
        val fixedMoves = p.moves.copyOf()
        val fixedPp = p.movePP.copyOf()
        val fixedPpUps = p.movePpUps.copyOf()
        val changes = mutableListOf<String>()
        val seen = mutableSetOf<Int>()

        for (i in fixedMoves.indices) {
            val moveId = fixedMoves[i]

            if (moveId == 0) {
                if (fixedPp[i] != 0 || fixedPpUps[i] != 0) {
                    fixedPp[i] = 0
                    fixedPpUps[i] = 0
                    changes += "Cleared PP from empty move slot ${i + 1}."
                }
                continue
            }

            val source = moveSources[moveId]
            val name = moveNames[moveId] ?: source?.name ?: "Move #$moveId"
            val duplicate = !seen.add(moveId)
            val eventLegal = gen1DocumentedEventMoveAllowed(p, gen1DexFromInternalIndex(p.species) ?: 0, moveId)
            val levelLegal = eventLegal || source != null &&
                (source.nonLevelSource || (source.minimumLevel != null && source.minimumLevel <= p.level))

            if (moveId !in 1..165 || (source == null && !eventLegal) || !levelLegal || duplicate) {
                fixedMoves[i] = 0
                fixedPp[i] = 0
                fixedPpUps[i] = 0
                changes += when {
                    duplicate -> "Removed duplicate $name from move slot ${i + 1}."
                    source == null -> "Removed $name from move slot ${i + 1}; ${gen1SpeciesNameFromInternal(p.species)} cannot learn it in Red/Blue/Yellow."
                    !levelLegal -> "Removed $name from move slot ${i + 1}; its earliest legal level is Lv.${source.minimumLevel}, above this Pokémon's Lv.${p.level}."
                    else -> "Removed invalid Gen 1 move #$moveId from slot ${i + 1}."
                }
            }
        }

        val kept = fixedMoves.indices.filter { fixedMoves[it] != 0 }
        val compactedMoves = IntArray(4)
        val compactedPp = IntArray(4)
        val compactedPpUps = IntArray(4)
        for ((target, source) in kept.withIndex()) {
            compactedMoves[target] = fixedMoves[source]
            compactedPp[target] = fixedPp[source]
            compactedPpUps[target] = fixedPpUps[source]
        }
        if (!compactedMoves.contentEquals(fixedMoves)) {
            changes += "Compacted the remaining moves into consecutive slots without changing their order or PP Ups."
        }

        var fixedExperience = p.experience
        if (meta != null && gen1LevelForExperience(meta.growth, p.experience) != p.level) {
            fixedExperience = gen1ExperienceForLevel(meta.growth, p.level)
            changes += "Adjusted EXP to $fixedExperience, the minimum legal EXP for Lv.${p.level} ${meta.name}."
        }

        return Gen1LegalFixPlan(compactedMoves, compactedPp, compactedPpUps, fixedExperience, changes)
    }

    private fun showGen1LegalisationReview(
        p: Gen1Pokemon,
        location: String,
        party: Boolean,
        moveSources: Map<Int, Gen1MoveSource>,
        moveNames: Map<Int, String>,
        meta: Gen1SpeciesMeta?,
        plan: Gen1LegalFixPlan
    ) {
        val body = buildString {
            append("PSE can safely fix the detected Gen 1 issues in its working copy:\n\n")
            plan.changes.forEach { append("• ").append(it).append("\n") }
            append("\nPSE will not invent replacement moves. Illegal or duplicate moves are removed, just like the safe-fix approach used by the Gen 6/7 legaliser.")
            append("\n\nAfter applying the fixes, PSE will rebuild the affected checksum(s), re-read the Pokémon, verify the write, and automatically run Deep Legality again.")
        }

        AlertDialog.Builder(this)
            .setTitle("Make Pokémon Legal")
            .setMessage(body)
            .setNegativeButton("Cancel", null)
            .setPositiveButton("Apply Safe Fixes") { _, _ ->
                val speciesMeta = meta
                if (speciesMeta == null) {
                    showDialog("Make Legal", "PSE could not load the Gen 1 species data needed to safely recalculate this Pokémon.")
                    return@setPositiveButton
                }

                applyGen1PokemonEditFull(
                    p = p,
                    location = location,
                    party = party,
                    meta = speciesMeta,
                    speciesInternal = p.species,
                    nickname = p.nickname,
                    otName = p.otName,
                    tid = p.tid,
                    level = p.level,
                    experience = plan.experience,
                    moves = plan.moves,
                    pp = plan.pp,
                    ppUps = plan.ppUps,
                    dvs = p.dvs,
                    statExp = p.statExp,
                    afterSave = { verified ->
                        showGen1LegalityCheck(verified, location, party)
                    }
                )
            }
            .show()
    }

    private val gen1InternalToDex = intArrayOf(0, 112, 115, 32, 35, 21, 100, 34, 80, 2, 103, 108, 102, 88, 94, 29, 31, 104, 111, 131, 59, 151, 130, 90, 72, 92, 123, 120, 9, 127, 114, 0, 0, 58, 95, 22, 16, 79, 64, 75, 113, 67, 122, 106, 107, 24, 47, 54, 96, 76, 0, 126, 0, 125, 82, 109, 0, 56, 86, 50, 128, 0, 0, 0, 83, 48, 149, 0, 0, 0, 84, 60, 124, 146, 144, 145, 132, 52, 98, 0, 0, 0, 37, 38, 25, 26, 0, 0, 147, 148, 140, 141, 116, 117, 0, 0, 27, 28, 138, 139, 39, 40, 133, 136, 135, 134, 66, 41, 23, 46, 61, 62, 13, 14, 15, 0, 85, 57, 51, 49, 87, 0, 0, 10, 11, 12, 68, 0, 55, 97, 42, 150, 143, 129, 0, 0, 89, 0, 99, 91, 0, 101, 36, 110, 53, 105, 0, 93, 63, 65, 17, 18, 121, 1, 3, 73, 0, 118, 119, 0, 0, 0, 0, 77, 78, 19, 20, 33, 30, 74, 137, 142, 0, 81, 0, 0, 4, 7, 5, 8, 6, 0, 0, 0, 0, 43, 44, 45, 69, 70, 71)
    private val gen1DexToInternal: IntArray by lazy {
        IntArray(152).also { out ->
            for (i in 1 until gen1InternalToDex.size) {
                val dex = gen1InternalToDex[i]
                if (dex in 1..151) out[dex] = i
            }
        }
    }
    private val gen1MetaMemory = HashMap<Int, Gen1SpeciesMeta>()

    private fun gen1DexFromInternalIndex(index: Int): Int? =
        gen1InternalToDex.getOrNull(index)?.takeIf { it in 1..151 }

    private fun gen1InternalIndexForDex(dex: Int): Int? =
        gen1DexToInternal.getOrNull(dex)?.takeIf { it in 1..190 }

    private fun gen1SpeciesNameFromInternal(index: Int): String {
        val dex = gen1DexFromInternalIndex(index) ?: return "Species #$index"
        return GEN1_NATIONAL_NAMES.getOrElse(dex - 1) { "Species #$index" }
    }

    private fun gen1PretSlug(dex: Int): String {
        val name = GEN1_NATIONAL_NAMES.getOrElse(dex - 1) { return dex.toString() }
        return when (dex) {
            29 -> "nidoran_f"
            32 -> "nidoran_m"
            83 -> "farfetchd"
            122 -> "mr_mime"
            else -> name.lowercase(Locale.US)
                .replace("♀", "_f").replace("♂", "_m")
                .replace(".", "").replace("'", "").replace("’", "")
                .replace("-", "_").replace(" ", "_")
        }
    }

    private fun gen1TypeId(name: String): Int = when (name.trim()) {
        "NORMAL" -> 0x00; "FIGHTING" -> 0x01; "FLYING" -> 0x02; "POISON" -> 0x03
        "GROUND" -> 0x04; "ROCK" -> 0x05; "BUG" -> 0x07; "GHOST" -> 0x08
        "FIRE" -> 0x14; "WATER" -> 0x15; "GRASS" -> 0x16; "ELECTRIC" -> 0x17
        "PSYCHIC_TYPE", "PSYCHIC" -> 0x18; "ICE" -> 0x19; "DRAGON" -> 0x1A
        else -> 0x00
    }

    private fun fetchGen1Text(urlText: String): String? {
        val connection = URL(urlText).openConnection() as HttpsURLConnection
        return try {
            connection.connectTimeout = 7000
            connection.readTimeout = 7000
            connection.instanceFollowRedirects = true
            connection.connect()
            if (connection.responseCode !in 200..299) null else connection.inputStream.bufferedReader().use { it.readText() }
        } finally { connection.disconnect() }
    }

    private fun parseGen1SpeciesMetaText(dex: Int, raw: String): Gen1SpeciesMeta? {
        val internal = gen1InternalIndexForDex(dex) ?: return null
        val stats = Regex("""db\s+(\d+)\s*,\s*(\d+)\s*,\s*(\d+)\s*,\s*(\d+)\s*,\s*(\d+)""").find(raw) ?: return null
        val types = Regex("""db\s+([A-Z_]+)\s*,\s*([A-Z_]+)\s*;\s*type""").find(raw) ?: return null
        val catchRate = Regex("""db\s+(\d+)\s*;\s*catch rate""").find(raw) ?: return null
        val growth = Regex("""db\s+(GROWTH_[A-Z_]+)\s*;\s*growth rate""").find(raw) ?: return null
        return Gen1SpeciesMeta(
            dex, internal, GEN1_NATIONAL_NAMES[dex - 1],
            IntArray(5) { i -> stats.groupValues[i + 1].toInt() },
            gen1TypeId(types.groupValues[1]), gen1TypeId(types.groupValues[2]),
            catchRate.groupValues[1].toInt().coerceIn(0, 255), growth.groupValues[1]
        )
    }

    private fun encodeGen1SpeciesMeta(meta: Gen1SpeciesMeta): String = JSONObject().apply {
        put("dex", meta.dex); put("internal", meta.internalIndex); put("name", meta.name)
        put("stats", JSONArray().apply { meta.baseStats.forEach { put(it) } })
        put("type1", meta.type1); put("type2", meta.type2); put("catch", meta.catchRate); put("growth", meta.growth)
    }.toString()

    private fun decodeGen1SpeciesMeta(encoded: String): Gen1SpeciesMeta? = try {
        val j = JSONObject(encoded); val a = j.getJSONArray("stats")
        Gen1SpeciesMeta(j.getInt("dex"), j.getInt("internal"), j.getString("name"), IntArray(5) { a.getInt(it) },
            j.getInt("type1"), j.getInt("type2"), j.getInt("catch"), j.getString("growth"))
    } catch (_: Exception) { null }

    private fun loadGen1SpeciesMetaAsync(dex: Int, done: (Gen1SpeciesMeta?) -> Unit) {
        gen1MetaMemory[dex]?.let { done(it); return }
        val key = "gen1_species_meta_$dex"
        metaPrefs.getString(key, null)?.let { decodeGen1SpeciesMeta(it) }?.let { meta ->
            gen1MetaMemory[dex] = meta; done(meta); return
        }
        imageExecutor.execute {
            val meta = try {
                val raw = fetchGen1Text("https://raw.githubusercontent.com/pret/pokered/master/data/pokemon/base_stats/${gen1PretSlug(dex)}.asm")
                raw?.let { parseGen1SpeciesMetaText(dex, it) }
            } catch (_: Exception) { null }
            if (meta != null) { gen1MetaMemory[dex] = meta; metaPrefs.edit().putString(key, encodeGen1SpeciesMeta(meta)).apply() }
            mainHandler.post { if (!isFinishing && !isDestroyed) done(meta) }
        }
    }

    private fun gen1ExperienceForLevel(growth: String, level: Int): Long {
        val n = level.coerceIn(1,100).toLong(); val cube = n*n*n
        return when (growth) {
            "GROWTH_FAST" -> 4L*cube/5L
            "GROWTH_MEDIUM_SLOW" -> (6L*cube/5L - 15L*n*n + 100L*n - 140L).coerceAtLeast(0L)
            "GROWTH_SLOW" -> 5L*cube/4L
            else -> cube
        }
    }

    private fun gen1LevelForExperience(growth: String, experience: Long): Int {
        var result = 1
        for (level in 1..100) { if (experience >= gen1ExperienceForLevel(growth, level)) result = level else break }
        return result
    }

    private fun gen1StatExpTerm(value: Int): Int = Math.sqrt(value.coerceIn(0,65535).toDouble()).toInt()/4

    private fun gen1CalculatedStats(meta: Gen1SpeciesMeta, level: Int, dvs: IntArray, statExp: IntArray): IntArray {
        val out = IntArray(5)
        for (i in 0..4) {
            val core = (((meta.baseStats[i] + dvs[i]) * 2 + gen1StatExpTerm(statExp[i])) * level) / 100
            out[i] = if (i == 0) core + level + 10 else core + 5
        }
        return out
    }

    private fun writeU24BE(data: ByteArray, offset: Int, value: Long) {
        require(offset >= 0 && offset <= data.size - 3) { "24-bit write is outside the save" }
        val v = value.coerceIn(0,0xFFFFFF)
        data[offset] = ((v ushr 16) and 0xFF).toByte(); data[offset+1] = ((v ushr 8) and 0xFF).toByte(); data[offset+2] = (v and 0xFF).toByte()
    }

    private fun gen1BoxDataOffset(data: ByteArray, boxNumber: Int): Int =
        if (boxNumber !in 1..12) -1 else if (boxNumber == gen1CurrentBoxNumber(data)) GEN1_CURRENT_BOX_DATA else gen1StoredBoxOffset(boxNumber)

    private fun gen1BoxIsWritable(data: ByteArray, boxNumber: Int): Boolean {
        if(gen1BoxStructureError(data,boxNumber)!=null)return false
        if (boxNumber == gen1CurrentBoxNumber(data)) return hasValidGen1MainChecksum(data)
        if (!gen1StoredBoxesInitialised(data)) return false
        return parseGen1Box(data, boxNumber).checksumValid == true
    }

    private fun gen1AllBoxesChecksum(data: ByteArray, bankStart: Int, checksumOffset: Int): Int {
        var sum=0; for (i in bankStart until checksumOffset) sum=(sum+(data[i].toInt() and 0xFF)) and 0xFF
        return sum xor 0xFF
    }

    private fun updateGen1StoredBankChecksums(data: ByteArray, boxNumber: Int) {
        val bankStart: Int; val allOffset: Int; val individualStart: Int; val firstBox: Int
        if (boxNumber in 1..6) { bankStart=GEN1_BOX_BANK2_START; allOffset=GEN1_BANK2_ALL_CHECKSUM; individualStart=GEN1_BANK2_INDIVIDUAL_CHECKSUMS; firstBox=1 }
        else { bankStart=GEN1_BOX_BANK3_START; allOffset=GEN1_BANK3_ALL_CHECKSUM; individualStart=GEN1_BANK3_INDIVIDUAL_CHECKSUMS; firstBox=7 }
        data[allOffset] = gen1AllBoxesChecksum(data, bankStart, allOffset).toByte()
        for (i in 0 until 6) data[individualStart+i] = gen1BoxChecksum(data, gen1StoredBoxOffset(firstBox+i)).toByte()
    }

    private fun gen1StoredBankChecksumsValid(data:ByteArray,boxNumber:Int):Boolean {
        if(!gen1StoredBoxesInitialised(data)) return true
        val bankStart:Int;val allOffset:Int;val individualStart:Int;val firstBox:Int
        if(boxNumber in 1..6){bankStart=GEN1_BOX_BANK2_START;allOffset=GEN1_BANK2_ALL_CHECKSUM;individualStart=GEN1_BANK2_INDIVIDUAL_CHECKSUMS;firstBox=1}
        else if(boxNumber in 7..12){bankStart=GEN1_BOX_BANK3_START;allOffset=GEN1_BANK3_ALL_CHECKSUM;individualStart=GEN1_BANK3_INDIVIDUAL_CHECKSUMS;firstBox=7}
        else return false
        if((data[allOffset].toInt() and 0xFF)!=gen1AllBoxesChecksum(data,bankStart,allOffset))return false
        for(i in 0 until 6)if((data[individualStart+i].toInt() and 0xFF)!=gen1BoxChecksum(data,gen1StoredBoxOffset(firstBox+i)))return false
        return true
    }

    private fun syncGen1CurrentBoxToStored(data:ByteArray,boxNumber:Int) {
        if(boxNumber!=gen1CurrentBoxNumber(data) || !gen1StoredBoxesInitialised(data))return
        val stored=gen1StoredBoxOffset(boxNumber)
        require(stored>=0 && stored+GEN1_BOX_SIZE<=data.size){"The active Gen 1 stored-box mirror is outside the save."}
        data.copyOfRange(GEN1_CURRENT_BOX_DATA,GEN1_CURRENT_BOX_DATA+GEN1_BOX_SIZE).copyInto(data,stored)
        updateGen1StoredBankChecksums(data,boxNumber)
    }

    private fun updateGen1ChecksumsAfterBoxChange(data: ByteArray, boxNumber: Int) {
        if (boxNumber == gen1CurrentBoxNumber(data)) {
            updateGen1MainChecksum(data)
            syncGen1CurrentBoxToStored(data,boxNumber)
        } else updateGen1StoredBankChecksums(data, boxNumber)
    }

    private fun verifyGen1WriteState(data:ByteArray,affectedBox:Int?=null):Pair<Boolean,String> {
        if(data.size!=SIZE_G1||detectGen2ChecksumProfile(data)!=null)return false to "The written file is not a Generation 1 save."
        if(!hasValidGen1MainChecksum(data))return false to "The Gen 1 main checksum did not verify."
        gen1PartyStructureError(data)?.let{return false to it}
        val wholeIntegrity=verifyGen1SaveIntegrity(data)
        if(!wholeIntegrity.first)return false to wholeIntegrity.second
        if(affectedBox!=null){
            gen1BoxStructureError(data,affectedBox)?.let{return false to it}
            if(affectedBox !in 1..12)return false to "The affected Gen 1 box number is invalid."
            val parsed=parseGen1Box(data,affectedBox)
            if(parsed.checksumValid!=true)return false to "Box $affectedBox did not pass checksum verification."
            if(affectedBox==gen1CurrentBoxNumber(data) && gen1StoredBoxesInitialised(data)){
                val stored=gen1StoredBoxOffset(affectedBox)
                val currentBytes=data.copyOfRange(GEN1_CURRENT_BOX_DATA,GEN1_CURRENT_BOX_DATA+GEN1_BOX_SIZE)
                val storedBytes=data.copyOfRange(stored,stored+GEN1_BOX_SIZE)
                if(!currentBytes.contentEquals(storedBytes))return false to "The active Gen 1 box cache and stored-box mirror are not synchronized."
            }
            if(gen1StoredBoxesInitialised(data) && !gen1StoredBankChecksumsValid(data,affectedBox))return false to "The Gen 1 stored-box bank checksums did not verify."
        }
        return true to "Gen 1 write verified."
    }

    private fun verifyGen1PartyDerivedStats(data:ByteArray,slot:Int,meta:Gen1SpeciesMeta):Pair<Boolean,String> {
        if(slot !in 0..5)return false to "The Gen 1 party slot is invalid."
        if(!hasValidGen1MainChecksum(data))return false to "The Gen 1 main checksum did not verify."
        val p=parseGen1Party(data).firstOrNull{it.slot==slot}?:return false to "The edited party Pokémon could not be re-read."
        val expected=gen1CalculatedStats(meta,p.level,p.dvs,p.statExp)
        if(p.maxHp!=expected[0])return false to "Party Max HP was not rebuilt correctly."
        val mon=GEN1_PARTY_MONS+slot*GEN1_PARTY_MON_SIZE
        if(mon<0 || mon+43>=data.size)return false to "The Gen 1 party stat record is outside the save."
        val actual=intArrayOf(readU16BE(data,mon+36),readU16BE(data,mon+38),readU16BE(data,mon+40),readU16BE(data,mon+42))
        for(i in 0..3)if(actual[i]!=expected[i+1])return false to "Party ${listOf("Attack","Defense","Speed","Special")[i]} was not rebuilt correctly."
        if(p.currentHp !in 0..p.maxHp)return false to "Party current HP is outside the rebuilt HP range."
        return true to "Gen 1 party derived stats verified."
    }

    private fun readU16BE(data: ByteArray, offset: Int): Int {
        if (offset + 1 >= data.size) return 0
        return ((data[offset].toInt() and 0xFF) shl 8) or (data[offset + 1].toInt() and 0xFF)
    }

    private fun readU24BE(data: ByteArray, offset: Int): Long {
        if (offset + 2 >= data.size) return 0
        return ((data[offset].toLong() and 0xFF) shl 16) or
            ((data[offset + 1].toLong() and 0xFF) shl 8) or
            (data[offset + 2].toLong() and 0xFF)
    }

    private fun gen1ReadDvs(data: ByteArray, offset: Int): IntArray {
        if (offset + 1 >= data.size) return intArrayOf(0, 0, 0, 0, 0)
        val a = data[offset].toInt() and 0xFF
        val b = data[offset + 1].toInt() and 0xFF
        val attack = (a ushr 4) and 0xF
        val defense = a and 0xF
        val speed = (b ushr 4) and 0xF
        val special = b and 0xF
        val hp = ((attack and 1) shl 3) or ((defense and 1) shl 2) or ((speed and 1) shl 1) or (special and 1)
        return intArrayOf(hp, attack, defense, speed, special)
    }

    private fun gen1WouldBeShinyInGen2(dvs: IntArray): Boolean {
        if (dvs.size < 5) return false
        val attack = dvs[1]
        return dvs[2] == 10 && dvs[3] == 10 && dvs[4] == 10 && attack in setOf(2, 3, 6, 7, 10, 11, 14, 15)
    }

    private fun writeU16BE(data: ByteArray, offset: Int, value: Int) {
        require(offset >= 0 && offset <= data.size - 2) { "16-bit write is outside the save" }
        val v = value.coerceIn(0, 0xFFFF)
        data[offset] = ((v ushr 8) and 0xFF).toByte()
        data[offset + 1] = (v and 0xFF).toByte()
    }

    private fun encodeGen1Char(c: Char): Int? = when (c) {
        in 'A'..'Z' -> 0x80 + (c.code - 'A'.code)
        in 'a'..'z' -> 0xA0 + (c.code - 'a'.code)
        in '0'..'9' -> 0xF6 + (c.code - '0'.code)
        ' ' -> 0x7F
        '\'' -> 0xE0
        '-' -> 0xE3
        '?' -> 0xE6
        '!' -> 0xE7
        '.' -> 0xF2
        else -> null
    }

    private fun writeGen1Text(data: ByteArray, offset: Int, length: Int, value: String) {
        require(length >= 0 && offset >= 0 && offset <= data.size - length) { "Gen 1 text write is outside the save" }
        val text = value.trim().take((length - 1).coerceAtLeast(0))
        val encoded = text.map { c ->
            encodeGen1Char(c) ?: throw IllegalArgumentException("Unsupported Gen 1 character: $c")
        }
        for (i in 0 until length) data[offset + i] = 0x50.toByte()
        for ((i, encodedChar) in encoded.withIndex()) {
            data[offset + i] = encodedChar.toByte()
        }
    }

    data class Gen2Profile(val key: String, val displayName: String, val partyOffset: Int, val checksumStart: Int, val checksumEnd: Int, val checksumOffset: Int)
    data class Gen2Pokemon(val slot:Int,val species:Int,val nickname:String,val otName:String,val level:Int,val heldItem:Int,val tid:Int,val experience:Long,val moves:IntArray,val movePP:IntArray,val statExp:IntArray,val happiness:Int,val pokerus:Int,val caughtData:Int,val dvs:IntArray,val shiny:Boolean,val isEgg:Boolean)
    data class Gen2DayCareState(val firstFlags:Int,val secondFlags:Int,val stepsUntilEgg:Int,val dittoParentState:Int,val firstParent:Gen2Pokemon?,val secondParent:Gen2Pokemon?,val egg:Gen2Pokemon?)
    data class Gen2SpeciesMeta(val species:Int,val name:String,val baseStats:IntArray,val growth:String)
    private val gen2MetaMemory = HashMap<Int, Gen2SpeciesMeta>()
    private val GEN2_NATIONAL_NAMES = GEN1_NATIONAL_NAMES + "Chikorita,Bayleef,Meganium,Cyndaquil,Quilava,Typhlosion,Totodile,Croconaw,Feraligatr,Sentret,Furret,Hoothoot,Noctowl,Ledyba,Ledian,Spinarak,Ariados,Crobat,Chinchou,Lanturn,Pichu,Cleffa,Igglybuff,Togepi,Togetic,Natu,Xatu,Mareep,Flaaffy,Ampharos,Bellossom,Marill,Azumarill,Sudowoodo,Politoed,Hoppip,Skiploom,Jumpluff,Aipom,Sunkern,Sunflora,Yanma,Wooper,Quagsire,Espeon,Umbreon,Murkrow,Slowking,Misdreavus,Unown,Wobbuffet,Girafarig,Pineco,Forretress,Dunsparce,Gligar,Steelix,Snubbull,Granbull,Qwilfish,Scizor,Shuckle,Heracross,Sneasel,Teddiursa,Ursaring,Slugma,Magcargo,Swinub,Piloswine,Corsola,Remoraid,Octillery,Delibird,Mantine,Skarmory,Houndour,Houndoom,Kingdra,Phanpy,Donphan,Porygon2,Stantler,Smeargle,Tyrogue,Hitmontop,Smoochum,Elekid,Magby,Miltank,Blissey,Raikou,Entei,Suicune,Larvitar,Pupitar,Tyranitar,Lugia,Ho-Oh,Celebi".split(",")

    private val gen2GsProfile = Gen2Profile("GS", "Pokémon Gold / Silver", 0x288A, 0x2009, 0x2D68, 0x2D69)
    private val gen2CrystalProfile = Gen2Profile("C", "Pokémon Crystal", 0x2865, 0x2009, 0x2B82, 0x2D0D)

    private fun gen2DayCareBase(profile:Gen2Profile):Int = if(profile.key=="C")0x2A83 else 0x2AA8

    private fun parseGen2DayCareRecord(data:ByteArray,rawOffset:Int,slot:Int,isEgg:Boolean):Gen2Pokemon{
        require(rawOffset>=0&&rawOffset+53<data.size){"A Gen 2 Day Care record is outside the save."}
        val body=rawOffset+22;val species=data[body].toInt()and 0xFF
        require(species in 1..251){"Day Care ${if(isEgg)"Egg" else "slot ${slot+1}"} has invalid species #$species."}
        val dvs=gen2Dvs(data,body+21)
        return Gen2Pokemon(slot,species,readGen1Text(data,rawOffset,11),readGen1Text(data,rawOffset+11,11),data[body+31].toInt()and 0xFF,data[body+1].toInt()and 0xFF,readU16BE(data,body+6),readU24BE(data,body+8),IntArray(4){data[body+2+it].toInt()and 0xFF},IntArray(4){data[body+23+it].toInt()and 63},IntArray(5){readU16BE(data,body+11+it*2)},data[body+27].toInt()and 0xFF,data[body+28].toInt()and 0xFF,readU16BE(data,body+29),dvs,gen2Shiny(dvs),isEgg)
    }

    private fun gen2DayCareState(data:ByteArray,profile:Gen2Profile):Gen2DayCareState{
        val base=gen2DayCareBase(profile);require(base+165<data.size){"The Gen 2 Day Care block is outside the save."}
        val firstFlags=data[base].toInt()and 0xFF;val secondFlags=data[base+55].toInt()and 0xFF
        val first=if((firstFlags and 1)!=0)parseGen2DayCareRecord(data,base+1,0,false)else null
        val second=if((secondFlags and 1)!=0)parseGen2DayCareRecord(data,base+58,1,false)else null
        val egg=if((firstFlags and 0x40)!=0)parseGen2DayCareRecord(data,base+112,2,true)else null
        return Gen2DayCareState(firstFlags,secondFlags,data[base+56].toInt()and 0xFF,data[base+57].toInt()and 0xFF,first,second,egg)
    }

    private fun gen2Checksum(data:ByteArray,p:Gen2Profile):Int { var sum=0; for(i in p.checksumStart..p.checksumEnd) sum=(sum+(data[i].toInt() and 0xFF)) and 0xFFFF; return sum }
    private fun gen2ChecksumValid(data:ByteArray,p:Gen2Profile):Boolean = data.size>=SIZE_G1 && p.checksumOffset+1<data.size && readU16LE(data,p.checksumOffset)==gen2Checksum(data,p)
    private fun detectGen2ChecksumProfile(data:ByteArray):Gen2Profile? = when { gen2ChecksumValid(data,gen2CrystalProfile)->gen2CrystalProfile; gen2ChecksumValid(data,gen2GsProfile)->gen2GsProfile; else->null }
    private fun gen2StructureError(data:ByteArray,p:Gen2Profile):String?{
        if(!gen2ChecksumValid(data,p))return "The Gen 2 primary checksum is invalid."
        fun locationError(label:String,base:Int,capacity:Int,recordSize:Int,recordStart:Int):String?{
            if(base<0||recordStart<0||base+1+capacity>=data.size||recordStart+capacity*recordSize+capacity*22>data.size)return "$label is outside the supported Gen 2 SRAM range."
            val count=data[base].toInt() and 0xFF;if(count !in 0..capacity)return "$label count $count exceeds its capacity of $capacity."
            if((data[base+1+count].toInt() and 0xFF)!=0xFF)return "$label species list has no terminator after slot $count."
            for(slot in 0 until count){val listed=data[base+1+slot].toInt() and 0xFF;val species=data[recordStart+slot*recordSize].toInt() and 0xFF;if(species !in 1..251)return "$label slot ${slot+1} has invalid species #$species.";if(listed!=species&&listed!=0xFD)return "$label slot ${slot+1} has inconsistent species or Egg metadata."}
            return null
        }
        locationError("Party",p.partyOffset,6,48,p.partyOffset+8)?.let{return it}
        for(box in 1..14){val base=gen2BoxOffset(box);locationError("Box $box",base,20,32,base+22)?.let{return it}}
        runCatching{gen2DayCareState(data,p)}.exceptionOrNull()?.let{return it.message?:"The Gen 2 Day Care block is invalid."}
        return null
    }
    private fun verifyGen2SaveIntegrity(data:ByteArray):Pair<Boolean,String>{val p=detectGen2ChecksumProfile(data)?:return false to "The save does not match a supported Gold, Silver or Crystal checksum profile.";val error=gen2StructureError(data,p);return if(error==null)true to "Gen 2 party, all 14 PC boxes, species metadata and primary checksum verified." else false to error}
    private fun detectGen2Profile(data:ByteArray):Gen2Profile? = detectGen2ChecksumProfile(data)?.takeIf{gen2StructureError(data,it)==null}
    private fun parseTrainerGen2(data:ByteArray,p:Gen2Profile):TrainerData? {
        if(gen2StructureError(data,p)!=null)return null
        return runCatching{
            val name=readGen1Text(data,0x200B,11);val tid=readU16BE(data,0x2009)
            val gender=if(p.key=="C"){if((gen2TrainerGenderState(data,p)[1].toInt()and 0xFF)==1)"Female" else "Male"}else "Male"
            val currency=gen2CurrencyState(data,p);val badgeState=gen2BadgeState(data,p);var badges=0;badgeState.forEach{badges+=Integer.bitCount(it.toInt()and 0xFF)}
            val play=gen2PlayTimeState(data,p)
            TrainerData(name,tid,0,2,p.displayName,true,gender,"English / Western",currency.money,badges,play.hours,play.minutes,play.seconds)
        }.getOrNull()
    }
    private fun gen2Dvs(data:ByteArray,o:Int):IntArray { val a=data[o].toInt() and 255; val b=data[o+1].toInt() and 255; val atk=a ushr 4; val def=a and 15; val spd=b ushr 4; val spc=b and 15; val hp=((atk and 1) shl 3) or ((def and 1) shl 2) or ((spd and 1) shl 1) or (spc and 1); return intArrayOf(hp,atk,def,spd,spc) }
    private fun gen2Shiny(d:IntArray)=d[2]==10&&d[3]==10&&d[4]==10&&d[1] in setOf(2,3,6,7,10,11,14,15)
    // Gen 2 box_struct (32 bytes): species@0, item@1, moves@2..5, OT ID@6..7, EXP@8..10,
    // Stat Exp@11..20, DVs@21..22, PP@23..26, happiness@27, Pokérus@28, caught data@29..30, level@31.
    // party_struct is the same 32-byte core followed by 16 bytes of battle/status stats (48 total).
    private fun parseGen2Party(data:ByteArray,p:Gen2Profile):List<Gen2Pokemon>{ if(!gen2ChecksumValid(data,p))return emptyList(); val base=p.partyOffset; val count=(data[base].toInt() and 255).coerceIn(0,6); val mons=base+8; val ots=mons+6*48; val nicks=ots+6*11; return (0 until count).mapNotNull{slot-> val o=mons+slot*48; val sp=data[o].toInt() and 255; val listed=data[base+1+slot].toInt() and 255; if(sp !in 1..251 || (listed!=sp && listed!=0xFD))return@mapNotNull null; val dv=gen2Dvs(data,o+21); Gen2Pokemon(slot,sp,readGen1Text(data,nicks+slot*11,11),readGen1Text(data,ots+slot*11,11),data[o+31].toInt() and 255,data[o+1].toInt() and 255,readU16BE(data,o+6),readU24BE(data,o+8),IntArray(4){data[o+2+it].toInt() and 255},IntArray(4){data[o+23+it].toInt() and 63},IntArray(5){readU16BE(data,o+11+it*2)},data[o+27].toInt() and 255,data[o+28].toInt() and 255,readU16BE(data,o+29),dv,gen2Shiny(dv),listed==0xFD) } }
    private fun gen2PartyCurrentHp(data:ByteArray,p:Gen2Profile,slot:Int):Int{require(slot in 0..5){"The Gen 2 party slot is invalid."};val record=p.partyOffset+8+slot*48;require(record+36<=data.size){"The Gen 2 party record is outside the save."};return readU16LE(data,record+34)}
    private fun gen2BoxOffset(box:Int)=if(box in 1..7)0x4000+(box-1)*0x450 else 0x6000+(box-8)*0x450
    private fun parseGen2Box(data:ByteArray,box:Int):List<Gen2Pokemon>{ val p=detectGen2Profile(data)?:return emptyList(); val base=gen2BoxOffset(box); val count=(data[base].toInt() and 255).coerceIn(0,20); val mons=base+22; val ots=mons+20*32; val nicks=ots+20*11; return (0 until count).mapNotNull{slot->val o=mons+slot*32;val sp=data[o].toInt() and 255;val listed=data[base+1+slot].toInt() and 255;if(sp !in 1..251||(listed!=sp&&listed!=0xFD))return@mapNotNull null;val dv=gen2Dvs(data,o+21);Gen2Pokemon(slot,sp,readGen1Text(data,nicks+slot*11,11),readGen1Text(data,ots+slot*11,11),data[o+31].toInt() and 255,data[o+1].toInt() and 255,readU16BE(data,o+6),readU24BE(data,o+8),IntArray(4){data[o+2+it].toInt() and 255},IntArray(4){data[o+23+it].toInt() and 63},IntArray(5){readU16BE(data,o+11+it*2)},data[o+27].toInt() and 255,data[o+28].toInt() and 255,readU16BE(data,o+29),dv,gen2Shiny(dv),listed==0xFD)} }
    private fun gen2PretSlug(species:Int):String {
        val raw = if (species in 1..GEN1_NATIONAL_NAMES.size) GEN1_NATIONAL_NAMES[species-1] else when(species) {
            152->"chikorita";153->"bayleef";154->"meganium";155->"cyndaquil";156->"quilava";157->"typhlosion";158->"totodile";159->"croconaw";160->"feraligatr"
            else->return species.toString()
        }
        return when(species){29->"nidoran_f";32->"nidoran_m";83->"farfetch_d";122->"mr__mime";201->"unown";250->"ho_oh";else->raw.lowercase(Locale.US).replace("♀","_f").replace("♂","_m").replace(".","").replace("'","").replace("’","").replace("-","_").replace(" ","_")}
    }

    private fun parseGen2SpeciesMetaText(species:Int, raw:String):Gen2SpeciesMeta? {
        val stats = Regex("""db\s+(\d+)\s*,\s*(\d+)\s*,\s*(\d+)\s*,\s*(\d+)\s*,\s*(\d+)\s*,\s*(\d+)""").find(raw) ?: return null
        val growth = Regex("""GROWTH_[A-Z_]+""").find(raw)?.value ?: return null
        val name = Regex("""db\\s+[A-Z0-9_]+\\s*;\\s*([0-9]{3})""").find(raw)?.let { "Species #$species" } ?: "Species #$species"
        return Gen2SpeciesMeta(species,name,IntArray(6){i->stats.groupValues[i+1].toInt()},growth)
    }

    private fun encodeGen2SpeciesMeta(meta:Gen2SpeciesMeta):String = JSONObject().apply {
        put("species",meta.species); put("name",meta.name); put("growth",meta.growth)
        put("stats",JSONArray().apply{meta.baseStats.forEach{put(it)}})
    }.toString()

    private fun decodeGen2SpeciesMeta(raw:String):Gen2SpeciesMeta? = try {
        val j=JSONObject(raw); val a=j.getJSONArray("stats")
        Gen2SpeciesMeta(j.getInt("species"),j.optString("name","Species #${j.getInt("species")}"),IntArray(6){a.getInt(it)},j.getString("growth"))
    } catch(_:Exception){null}

    private fun loadGen2SpeciesMetaAsync(species:Int, done:(Gen2SpeciesMeta?)->Unit) {
        gen2MetaMemory[species]?.let{done(it);return}
        val key="gen2_species_meta_$species"
        metaPrefs.getString(key,null)?.let{decodeGen2SpeciesMeta(it)}?.let{m->gen2MetaMemory[species]=m;done(m);return}
        imageExecutor.execute {
            var meta:Gen2SpeciesMeta?=null
            var slug=gen2PretSlug(species)
            if (slug == species.toString()) {
                try {
                    val manifest=fetchGen1Text("https://raw.githubusercontent.com/pret/pokecrystal/master/data/pokemon/base_stats.asm")
                    val includes=manifest?.lineSequence()?.mapNotNull { line -> Regex("INCLUDE \"data/pokemon/base_stats/([^\"]+)\\.asm\"").find(line)?.groupValues?.getOrNull(1) }?.toList().orEmpty()
                    if(species in 1..includes.size) slug=includes[species-1]
                } catch(_:Exception){}
            }
            val urls=listOf(
                "https://raw.githubusercontent.com/pret/pokecrystal/master/data/pokemon/base_stats/$slug.asm",
                "https://raw.githubusercontent.com/pret/pokegold/master/data/pokemon/base_stats/$slug.asm"
            )
            for(u in urls) try { val raw=fetchGen1Text(u); if(raw!=null){meta=parseGen2SpeciesMetaText(species,raw); if(meta!=null) break} } catch(_:Exception){}
            if(meta!=null){gen2MetaMemory[species]=meta!!;metaPrefs.edit().putString(key,encodeGen2SpeciesMeta(meta!!)).apply()}
            val out=meta;mainHandler.post{if(!isFinishing&&!isDestroyed)done(out)}
        }
    }

