    private val gen2GrowthCodes="XXXXXXXXXMMMMMMXXXMMMMMMMMMMXXXXXXFFMMFFMMXXXMMMMMMMMMMMMSSXXXXXXXXXXXXSSXXXMMMMMMMMMMMMMSSXXXMMMMMMMSSMMMMMMMSSFMMMMMMSSMMMMMSSSSSMMMMMMMMMMSSSSSSSSSXXXXXXXXXXMMMMFFFFMSSMFFFFMMXXXXFFMXXXXFXXMMMMMXMFMMMMMMXMFFMMXSXMMMMSSFMMFSSSSMMMMSFMMMMMSFSSSSSSSSX"
    private fun canonicalGen2Growth(species:Int):String?=when(gen2GrowthCodes.getOrNull(species-1)){
        'F'->"GROWTH_FAST";'M'->"GROWTH_MEDIUM_FAST";'X'->"GROWTH_MEDIUM_SLOW";'S'->"GROWTH_SLOW";else->null
    }

    private data class Gen2ExperienceProgress(val growthLabel:String,val nextLevelExperience:Long,val remaining:Long)

    private fun gen2GrowthLabel(growth:String):String = when(growth){
        "GROWTH_FAST"->"Fast"
        "GROWTH_MEDIUM_FAST"->"Medium Fast"
        "GROWTH_MEDIUM_SLOW"->"Medium Slow"
        "GROWTH_SLOW"->"Slow"
        else->"Unknown"
    }

    private fun gen2ExperienceProgress(species:Int,level:Int,experience:Long):Gen2ExperienceProgress? {
        if(level !in 1..99||experience !in 0L..0xFFFFFFL)return null
        val growth=canonicalGen2Growth(species)?:inferGen2Growth(level,experience)?:return null
        val next=gen2ExperienceForLevel(growth,level+1)
        if(next !in 0L..0xFFFFFFL||experience>=next)return null
        return Gen2ExperienceProgress(gen2GrowthLabel(growth),next,next-experience)
    }

    // Offline Gen 2 consistency helpers. Advanced editing must never depend on network access.
    private fun builtinGen2SpeciesMeta(species:Int):Gen2SpeciesMeta? = when(species) {
        // Guaranteed local seed for the current write-validation path; other species are safely
        // resolved from their own save data below and cached for the rest of the session.
        6 -> Gen2SpeciesMeta(6, "Charizard", intArrayOf(78,84,78,100,109,85), "GROWTH_MEDIUM_SLOW")
        160 -> Gen2SpeciesMeta(160, "Feraligatr", intArrayOf(85,105,100,78,79,83), "GROWTH_MEDIUM_SLOW")
        else -> null
    }

    private fun inferGen2Growth(level:Int, exp:Long):String? {
        if(level !in 1..100) return null
        val groups=listOf("GROWTH_FAST","GROWTH_MEDIUM_FAST","GROWTH_MEDIUM_SLOW","GROWTH_SLOW")
        val matches=groups.filter { g ->
            val min=gen2ExperienceForLevel(g,level)
            val max=if(level<100) gen2ExperienceForLevel(g,level+1)-1 else 0xFFFFFFL
            exp in min..max
        }
        return matches.singleOrNull()
    }

    private fun inferGen2PartyBaseStats(data:ByteArray, location:String, mon:Gen2Pokemon):IntArray? {
        if(!location.startsWith("Party")) return null
        val (record,_,_)=runCatching{gen2RecordOffsets(data,location,mon.slot)}.getOrNull()?:return null
        val stored=intArrayOf(
            readU16BE(data,record+36), readU16BE(data,record+38), readU16BE(data,record+40),
            readU16BE(data,record+42), readU16BE(data,record+44), readU16BE(data,record+46)
        )
        val result=IntArray(6)
        val dvMap=intArrayOf(0,1,2,3,4,4); val seMap=intArrayOf(0,1,2,3,4,4)
        for(i in 0..5){
            val candidates=(1..255).filter { base ->
                val core=(((base+mon.dvs[dvMap[i]])*2+gen2StatExpTerm(mon.statExp[seMap[i]]))*mon.level)/100
                val calc=if(i==0) core+mon.level+10 else core+5
                calc==stored[i]
            }
            if(candidates.size!=1) return null
            result[i]=candidates[0]
        }
        return result
    }

    private fun resolveGen2MetaOffline(mon:Gen2Pokemon, location:String):Gen2SpeciesMeta? {
        canonicalGen2PartyTransferMeta(mon.species)?.let { gen2MetaMemory[mon.species]=it; return it }
        builtinGen2SpeciesMeta(mon.species)?.let { gen2MetaMemory[mon.species]=it; return it }
        gen2MetaMemory[mon.species]?.let{return it}
        val key="gen2_species_meta_${mon.species}"
        metaPrefs.getString(key,null)?.let{decodeGen2SpeciesMeta(it)}?.let{m->gen2MetaMemory[mon.species]=m;return m}
        val data=runCatching{importedFile?.readBytes()}.getOrNull() ?: return null
        val growth=inferGen2Growth(mon.level,mon.experience) ?: return null
        val stats=inferGen2PartyBaseStats(data,location,mon) ?: IntArray(6)
        val meta=Gen2SpeciesMeta(mon.species,"Species #${mon.species}",stats,growth)
        gen2MetaMemory[mon.species]=meta
        metaPrefs.edit().putString(key,encodeGen2SpeciesMeta(meta)).apply()
        return meta
    }
    private fun gen2StatExpTerm(value:Int):Int = Math.ceil(Math.sqrt(value.coerceIn(0,65535).toDouble())).toInt()/4
    private fun gen2CalculatedStats(meta:Gen2SpeciesMeta, level:Int, dvs:IntArray, statExp:IntArray):IntArray {
        val out=IntArray(6)
        // HP, Atk, Def, Spd use their matching DV/Stat Exp. SpA and SpD share Gen 2 Special DV/Stat Exp.
        val dvMap=intArrayOf(0,1,2,3,4,4); val seMap=intArrayOf(0,1,2,3,4,4)
        for(i in 0..5){
            val core=(((meta.baseStats[i]+dvs[dvMap[i]])*2+gen2StatExpTerm(statExp[seMap[i]]))*level)/100
            out[i]=if(i==0) core+level+10 else core+5
        }
        return out
    }

    private fun writeGen2Dvs(data:ByteArray, offset:Int, atk:Int, def:Int, spd:Int, spc:Int) {
        data[offset]=(((atk and 15) shl 4) or (def and 15)).toByte()
        data[offset+1]=(((spd and 15) shl 4) or (spc and 15)).toByte()
    }

    private fun loadGen2Sprite(view: ImageView, species: Int, shiny: Boolean = false) {
        view.setImageDrawable(null)
        if (species !in 1..251) return
        val cacheDir = File(filesDir, "sprite_cache").apply { mkdirs() }
        val suffix = if (shiny) "_shiny" else ""
        val cacheFile = File(cacheDir, "g2_${species}$suffix.png")
        if (cacheFile.exists() && cacheFile.length() > 0) {
            BitmapFactory.decodeFile(cacheFile.absolutePath)?.let { it.density = android.graphics.Bitmap.DENSITY_NONE; view.setImageBitmap(it); return }
        }
        imageExecutor.execute {
            val urls = if (shiny) listOf(
                "https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/versions/generation-ii/crystal/shiny/$species.png",
                "https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/shiny/$species.png"
            ) else listOf(
                "https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/versions/generation-ii/crystal/$species.png",
                "https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/versions/generation-ii/gold/$species.png",
                "https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/$species.png"
            )
            var bitmap: android.graphics.Bitmap? = null
            for (u in urls) try {
                val c = URL(u).openConnection() as HttpsURLConnection; c.connectTimeout=7000; c.readTimeout=7000; c.connect()
                if (c.responseCode in 200..299) { val b=c.inputStream.use{it.readBytes()}; if(b.isNotEmpty()){ try{cacheFile.writeBytes(b)}catch(_:Exception){}; bitmap=BitmapFactory.decodeByteArray(b,0,b.size) } }
                c.disconnect(); if(bitmap!=null) break
            } catch(_:Exception){}
            bitmap?.let { it.density=android.graphics.Bitmap.DENSITY_NONE; val ready=it; mainHandler.post{ if(!isFinishing&&!isDestroyed)view.setImageBitmap(ready) } }
        }
    }

    private fun loadGen2Artwork(view: ImageView, species: Int) {
        view.setImageDrawable(null); if(species !in 1..251)return
        val cacheDir=File(filesDir,"artwork_cache").apply{mkdirs()}; val cacheFile=File(cacheDir,"official_$species.png")
        if(cacheFile.exists()&&cacheFile.length()>0){BitmapFactory.decodeFile(cacheFile.absolutePath)?.let{it.density=android.graphics.Bitmap.DENSITY_NONE;view.setImageBitmap(it);return}}
        imageExecutor.execute { var bitmap:android.graphics.Bitmap?=null; for(u in listOf("https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/$species.png","https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/$species.png")) try{val c=URL(u).openConnection() as HttpsURLConnection;c.connectTimeout=7000;c.readTimeout=7000;c.connect();if(c.responseCode in 200..299){val b=c.inputStream.use{it.readBytes()};if(b.isNotEmpty()){try{cacheFile.writeBytes(b)}catch(_:Exception){};bitmap=BitmapFactory.decodeByteArray(b,0,b.size)}};c.disconnect();if(bitmap!=null)break}catch(_:Exception){}; bitmap?.let{it.density=android.graphics.Bitmap.DENSITY_NONE;val ready=it;mainHandler.post{if(!isFinishing&&!isDestroyed)view.setImageBitmap(ready)}} }
    }


