    private val gen2HiddenPowerTypes=arrayOf("Fighting","Flying","Poison","Ground","Rock","Bug","Ghost","Steel","Fire","Water","Grass","Electric","Psychic","Ice","Dragon","Dark")

    private fun gen2HiddenPower(dvs:IntArray):Pair<String,Int>? {
        if(dvs.size<5||dvs.any{it !in 0..15})return null
        val attack=dvs[1];val defense=dvs[2];val speed=dvs[3];val special=dvs[4]
        val type=gen2HiddenPowerTypes[((attack and 3) shl 2) or (defense and 3)]
        val highBits=(attack and 8) or ((defense and 8) shr 1) or ((speed and 8) shr 2) or ((special and 8) shr 3)
        val power=((highBits*5+(special and 3))/2)+31
        return type to power
    }

    private fun gen2ReturnPower(happiness:Int):Int? {
        if(happiness !in 0..255)return null
        return (happiness*10)/25
    }

    private fun gen2FrustrationPower(happiness:Int):Int? {
        if(happiness !in 0..255)return null
        return ((255-happiness)*10)/25
    }

    private fun gen2UnownForm(species:Int,dvs:IntArray):String? {
        if(species!=201||dvs.size<5||dvs.any{it !in 0..15})return null
        val attack=dvs[1];val defense=dvs[2];val speed=dvs[3];val special=dvs[4]
        val formBits=((attack and 6) shl 5) or ((defense and 6) shl 3) or ((speed and 6) shl 1) or ((special and 6) shr 1)
        return ('A'.code+(formBits/10)).toChar().toString()
    }

    private fun gen2MoveMaxPp(moveId:Int,ppUps:Int):Int? =
        if(ppUps !in 0..3)null else gen2MoveBasePp(moveId)?.let{base->minOf(63,base+(base*ppUps/5))}

    private fun validGen2MovePpLimits(moves:IntArray,pp:IntArray,ppUps:IntArray):Boolean {
        if(moves.size!=4||pp.size!=4||ppUps.size!=4)return false
        return moves.indices.all{i->moves[i]==0||(gen2MoveMaxPp(moves[i],ppUps[i])?.let{pp[i] in 0..it}?:false)}
    }

    private fun validGen2MoveTupleLayout(moves:IntArray,pp:IntArray,ppUps:IntArray):Boolean {
        if(moves.size!=4||pp.size!=4||ppUps.size!=4)return false
        var foundEmpty=false;val seen=mutableSetOf<Int>()
        for(i in 0..3){
            val move=moves[i]
            if(move==0){foundEmpty=true;if(pp[i]!=0||ppUps[i]!=0)return false}
            else if(move !in 1..251||foundEmpty||!seen.add(move))return false
            if(pp[i] !in 0..63||ppUps[i] !in 0..3)return false
        }
        return true
    }

    private fun gen2LegalityProbe(mon:Gen2Pokemon):PokemonEntry = PokemonEntry(
        species=mon.species,nickname=mon.nickname,isNicknamed=true,level=mon.level,checksumValid=true,
        heldItem=mon.heldItem,tid=mon.tid,sid=0,experience=mon.experience,ability=0,abilityNumber=1,pid=0,
        nature=0,gender=0,form=0,evs=IntArray(6),moves=mon.moves.copyOf(),movePP=mon.movePP.copyOf(),ivs=IntArray(6),
        isEgg=mon.isEgg,otName=mon.otName,friendship=mon.happiness,currentHandler=0,pokerusDays=mon.pokerus and 0x0F,
        pokerusStrain=(mon.pokerus ushr 4) and 0x0F,shiny=mon.shiny,language=2,markingValue=0,fatefulEncounter=false,
        relearnMoves=IntArray(4),eggLocation=0,metLocation=0,ball=0,metLevel=mon.level,otGender=0,originGame=0,
        country=0,region=0,consoleRegion=0,eggYear=0,eggMonth=0,eggDay=0,metYear=0,metMonth=0,metDay=0,hyperTrainFlags=0
    )

    private fun buildGen2LegalFixPlan(mon:Gen2Pokemon,deep:DeepLegalityData,sourcePpUps:IntArray):Gen2LegalFixPlan {
        require(sourcePpUps.size==4&&sourcePpUps.all{it in 0..3}){"Gen 2 PP Up state is invalid."}
        val moves=IntArray(4);val pp=IntArray(4);val ppUps=IntArray(4);val changes=mutableListOf<String>();val seen=mutableSetOf<Int>();var target=0
        for(i in 0..3){
            val move=mon.moves[i];val currentPp=mon.movePP[i];val currentPpUps=sourcePpUps[i]
            val unlearnable=move!=0&&mon.species!=235&&deep.onlineOk&&deep.learnableMoves.isNotEmpty()&&move !in deep.learnableMoves
            val invalid=move !in 0..251
            val duplicate=move!=0&&!seen.add(move)
            if(invalid||unlearnable||duplicate){
                val name=deep.moveNames[move]?:"Move #$move"
                changes+=when{invalid->"Move ${i+1} ($name) cleared because it is outside the Gen 2 move range.";unlearnable->"Move ${i+1} ($name) cleared because PSE could not validate it for this species in Gen 2.";else->"Duplicate move ${i+1} ($name) cleared."}
                continue
            }
            if(move==0){
                if(currentPp!=0||currentPpUps!=0)changes+="Move ${i+1} PP and PP Ups cleared because the slot is empty."
                continue
            }
            var fixedPp=currentPp
            (gen2MoveMaxPp(move,currentPpUps)?:deep.moveBasePp[move]?.let{base->minOf(63,base+(base*currentPpUps/5))})?.let{maxPp->if(fixedPp>maxPp){fixedPp=maxPp;changes+="Move ${i+1} PP reduced to its Gen 2 maximum of $maxPp for $currentPpUps PP Up(s)."}}
            if(target!=i)changes+="Move ${i+1} compacted into slot ${target+1} with its PP and PP Up count."
            moves[target]=move;pp[target]=fixedPp;ppUps[target]=currentPpUps;target++
        }
        return Gen2LegalFixPlan(moves,pp,ppUps,changes.distinct())
    }

    private fun checkGen2EggIntegrity(mon:Gen2Pokemon,location:String) {
        require(mon.isEgg){"The Gen 2 Egg integrity check only accepts records with the Egg marker."}
        val file=importedFile?:return
        val openedPath=runCatching{file.canonicalPath}.getOrNull()?:return showDialog("Gen 2 Egg Integrity Check","The selected save source could not be verified. Nothing was changed.")
        val data=runCatching{file.readBytes()}.getOrNull()?:return showDialog("Gen 2 Egg Integrity Check","The Gen 2 save could not be read. Nothing was changed.")
        if(runCatching{importedFile?.canonicalPath}.getOrNull()!=openedPath)return showDialog("Gen 2 Egg Integrity Check","The selected save source changed before the check started. Reopen the Egg and try again. Nothing was changed.")
        val profile=detectGen2Profile(data)?:return showDialog("Gen 2 Egg Integrity Check","The Gen 2 save profile or primary checksum is invalid. Nothing was changed.")
        if(!gen2ChecksumValid(data,profile))return showDialog("Gen 2 Egg Integrity Check","The primary Gen 2 save checksum is invalid. Nothing was changed.")
        val party=location.startsWith("Party");val box=if(party)null else Regex("Box (\\d+)").find(location)?.groupValues?.getOrNull(1)?.toIntOrNull()
        if(!party&&(box==null||box !in 1..14))return showDialog("Gen 2 Egg Integrity Check","The selected Egg location is invalid. Nothing was changed.")
        val current=if(party)parseGen2Party(data,profile).firstOrNull{it.slot==mon.slot}else parseGen2Box(data,box!!).firstOrNull{it.slot==mon.slot}
        if(current==null||!current.isEgg||!sameGen2BankRecord(current,mon))return showDialog("Gen 2 Egg Integrity Check","The selected Egg changed before the check started. Reopen it and try again. Nothing was changed.")
        val ppUps=runCatching{gen2PpUps(data,location,current.slot)}.getOrNull()?:return showDialog("Gen 2 Egg Integrity Check","The Egg move PP Up state could not be verified. Nothing was changed.")
        val offsets=runCatching{gen2RecordOffsets(data,location,current.slot)}.getOrNull()?:return showDialog("Gen 2 Egg Integrity Check","The Egg record offsets could not be verified. Nothing was changed.")
        val listedOffset=runCatching{gen2ListedSpeciesOffset(data,location,current.slot)}.getOrNull()?:return showDialog("Gen 2 Egg Integrity Check","The Egg list marker could not be verified. Nothing was changed.")
        val problems=mutableListOf<String>()
        if((data.getOrNull(listedOffset)?.toInt()?.and(0xFF))!=0xFD)problems+="The selected slot does not contain the Gen 2 Egg marker."
        if((data.getOrNull(offsets.first)?.toInt()?.and(0xFF))!=current.species)problems+="The Egg marker and underlying species record disagree."
        if(current.species !in 1..251)problems+="The underlying species is outside the Generation 2 Pokédex."
        if(!validGen2MoveTupleLayout(current.moves,current.movePP,ppUps))problems+="The Egg move, PP or PP Up tuple layout is malformed."
        else if(!validGen2MovePpLimits(current.moves,current.movePP,ppUps))problems+="One or more Egg moves exceed their Generation 2 PP limit."
        val speciesName=GEN2_NATIONAL_NAMES.getOrElse(current.species-1){"Species #${current.species}"}
        val report=buildString{
            append(if(problems.isEmpty())"✅ PASSED EGG INTEGRITY CHECK" else "❌ INVALID EGG RECORD")
            append("\n\nEgg • ").append(location).append("\nUnderlying species #").append(current.species).append(" ").append(speciesName).append("\nRemaining hatch cycles: ").append(current.happiness).append("\n")
            if(problems.isEmpty())append("\nThe save checksum, Egg marker, underlying species, move tuple layout and PP limits are internally consistent.\n")
            else{append("\nProblems\n");problems.forEach{append("• ").append(it).append("\n")}}
            append("\nThis read-only check does not infer breeding parentage or event provenance. Nothing was changed.")
        }
        showDialog("Gen 2 Egg Integrity Check",report)
    }

    private fun checkGen2PokemonLegality(mon:Gen2Pokemon, location:String) {
        if(mon.isEgg){checkGen2EggIntegrity(mon,location);return}
        val openedUri=currentSourceUri;val openedLabel=currentSourceLabel
        val file=importedFile?:return
        val openedFilePath=runCatching{file.canonicalPath}.getOrNull()?:run{showDialog("Gen 2 Deep Legality Check","The selected save source could not be verified. Nothing was changed.");return}
        val bytes=runCatching{file.readBytes()}.getOrNull()?:return
        val profile=detectGen2Profile(bytes)
        if(profile!=null){
            val party=location.startsWith("Party");val box=if(party)null else Regex("Box (\\d+)").find(location)?.groupValues?.getOrNull(1)?.toIntOrNull()
            val openedLive=if(party)parseGen2Party(bytes,profile).firstOrNull{it.slot==mon.slot}else box?.let{parseGen2Box(bytes,it).firstOrNull{q->q.slot==mon.slot}}
            if(openedLive==null||!sameGen2BankRecord(openedLive,mon)){showDialog("Gen 2 Deep Legality Check","The selected Pokémon or Egg state changed before the check started. Reopen it and try again. Nothing was changed.");return}
        }
        val ppUps=runCatching{gen2PpUps(bytes,location,mon.slot)}.getOrElse{showDialog("Gen 2 Deep Legality Check","The selected record and its PP Up state could not be verified. Nothing was changed.");return}
        val progress=AlertDialog.Builder(this).setTitle("Gen 2 Deep Legality Check").setMessage("Checking Gen 2 structure, species data and move legality…").setCancelable(false).create();progress.show()
        fun bound()=runCatching{importedFile?.canonicalPath==openedFilePath&&file.canonicalPath==openedFilePath&&currentSourceUri==openedUri&&currentSourceLabel==openedLabel&&file.readBytes().contentEquals(bytes)}.getOrDefault(false)
        var reportDelivered=false
        loadDeepLegalityDataForGenerationAsync(gen2LegalityProbe(mon),2){deep->
            if(reportDelivered){return@loadDeepLegalityDataForGenerationAsync};reportDelivered=true
            progress.dismiss()
            val currentPath=runCatching{importedFile?.canonicalPath}.getOrNull();val currentBytes=runCatching{file.readBytes()}.getOrNull()
            if(currentPath!=openedFilePath||currentBytes==null||!currentBytes.contentEquals(bytes)){showDialog("Gen 2 Deep Legality Check","The selected save source changed while legality data was loading. Reopen the Pokémon and try again. Nothing was changed.");return@loadDeepLegalityDataForGenerationAsync}
            if(currentSourceUri!=openedUri||currentSourceLabel!=openedLabel){showDialog("Gen 2 Deep Legality Check","The source identity changed while legality data was loading. Reopen the Pokémon. Nothing was changed.");return@loadDeepLegalityDataForGenerationAsync}
            if(!bound()){showDialog("Gen 2 Deep Legality Check","The original save identity or bytes changed. Reopen the Pokémon. Nothing was changed.");return@loadDeepLegalityDataForGenerationAsync}
            val findings=mutableListOf<LegalityFinding>()
            fun error(t:String)=findings.add(LegalityFinding(2,t))
            fun warn(t:String)=findings.add(LegalityFinding(1,t))
            if(profile==null || !gen2ChecksumValid(bytes,profile))error("Primary Gen 2 save checksum is invalid.")
            if(mon.species !in 1..251)error("Species #${mon.species} is outside the Generation 2 Pokédex.")
            if(mon.level !in 1..100)error("Level ${mon.level} is outside 1–100.")
            if(mon.experience !in 0..0xFFFFFF)error("Experience is outside the Gen 2 stored range.")
            if(mon.heldItem !in 0..255)error("Held item ID is outside the Gen 2 range.")
            if(mon.heldItem!=0&&mon.heldItem !in gen2HeldItemIds)warn("Held item #${mon.heldItem} is not in the verified Generation 2 holdable-item catalogue. PSE will preserve the byte unless you explicitly replace it.")
            if(mon.happiness !in 0..255)error("Happiness is outside 0–255.")
            if(mon.dvs.any{it !in 0..15})error("One or more DVs are outside 0–15.")
            if(mon.statExp.any{it !in 0..65535})error("One or more Stat Exp values are outside 0–65535.")
            if(gen2Shiny(mon.dvs)!=mon.shiny)error("Shiny state does not match the Gen 2 DV pattern.")
            if(mon.nickname.length>10)error("Nickname exceeds the Gen 2 10-character limit.")
            if(mon.otName.length>10)error("Original Trainer name exceeds the Gen 2 10-character limit.")
            val seen=mutableSetOf<Int>()
            mon.moves.forEachIndexed{i,move->
                if(move !in 0..251)error("Move ${i+1} (#$move) did not exist in Generation 2.")
                if(move!=0 && !seen.add(move))error("Move ${i+1} duplicates another active move.")
                if(move==0&&mon.movePP[i]!=0)error("Move ${i+1} is empty but still stores ${mon.movePP[i]} PP.")
                if(move==0&&ppUps[i]!=0)error("Move ${i+1} is empty but still stores ${ppUps[i]} PP Up(s).")
                if(move==0&&mon.moves.drop(i+1).any{it!=0})error("Move ${i+1} is empty before a later active move; active move tuples must be compacted in order.")
                if(move!=0&&mon.species!=235&&deep.onlineOk&&deep.learnableMoves.isNotEmpty()&&move !in deep.learnableMoves){val n=deep.moveNames[move]?:"Move #$move";error("$n (#$move) could not be validated as learnable by this species or its Gen 2 data.")}
                if(move!=0){val maxPp=gen2MoveMaxPp(move,ppUps[i])?:deep.moveBasePp[move]?.let{base->minOf(63,base+(base*ppUps[i]/5))};if(maxPp!=null&&mon.movePP[i]>maxPp)error("Move ${i+1} PP is ${mon.movePP[i]}, above its Gen 2 maximum of $maxPp for ${ppUps[i]} PP Up(s).")}
            }
            if(deep.growthLevel!=null && deep.growthLevel!=mon.level)error("Stored level ${mon.level} does not match the level implied by ${mon.experience} EXP (${deep.growthLevel}).")
            if(!deep.onlineOk)warn("Species/move database could not be reached. Structural checks passed, but move learnability and growth-curve checks are incomplete.")
            else if(deep.partial)warn("Some online Gen 2 reference data was incomplete; PSE did not guess at missing details.")
            val errors=findings.filter{it.severity==2};val warnings=findings.filter{it.severity==1};val plan=buildGen2LegalFixPlan(mon,deep,ppUps)
            val status=when{errors.isNotEmpty()->"❌ INVALID";warnings.isNotEmpty()->"⚠️ PASSED WITH WARNINGS";else->"✅ PASSED DEEP CHECKS"}
            val message=buildString{
                append(status).append("\n\n").append(mon.nickname.ifBlank{"Pokémon #${mon.species}"}).append(" • ").append(location).append("\nSpecies #").append(mon.species).append(" • Lv. ").append(mon.level).append(" • TID ").append(mon.tid).append("\n")
                if(errors.isNotEmpty()){append("\nProblems\n");errors.forEach{append("• ").append(it.text).append("\n")}}
                if(warnings.isNotEmpty()){append("\nWarnings\n");warnings.forEach{append("• ").append(it.text).append("\n")}}
                if(errors.isEmpty()&&warnings.isEmpty())append("\nNo problems were found by PSE's Gen 2 structural and species checks.\n")
                append("\nChecked in this build\n• primary save checksum and Gen 2 field ranges\n• species / level / EXP consistency\n• DVs, shiny derivation and Stat Exp ranges\n• move IDs, duplicate moves and Gen 2 learnability\n• move PP upper limits using each slot's exact PP Up count\n• held item, happiness, nickname and OT structure\n• Pokérus/caught-data storage sanity\n")
                append("\nNot fully certifiable without exact Gen 2 encounter/event databases\n• exact encounter slot/location and catch-level match\n• event distribution identity and redemption provenance\n• trade/event-only edge cases\n")
                if(errors.isNotEmpty()&&plan.changes.isEmpty())append("\nPSE found no safe automatic repair for the remaining problem(s); it will not invent encounter or identity data.")
            }
            var fixConsumed=false;var reportConsumed=false
            val b=AlertDialog.Builder(this).setTitle("Gen 2 Deep Legality Report").setMessage(message).setNegativeButton("OK"){_,_->reportConsumed=true;fixConsumed=true}.setOnCancelListener{reportConsumed=true;fixConsumed=true}
            if(errors.isNotEmpty()&&plan.changes.isNotEmpty())b.setPositiveButton("Fix illegal Pokémon"){_,_->
                if(reportConsumed){return@setPositiveButton};reportConsumed=true
                if(!bound()){fixConsumed=true;showDialog("Gen 2 edit blocked","The reported source identity or bytes changed. Reopen the Pokémon. Nothing was changed.");return@setPositiveButton}
                val fixMessage=buildString{append("PSE can safely apply these Gen 2 fixes:\n\n");plan.changes.forEach{append("• ").append(it).append("\n")};append("\nThe save will be re-read and Deep Legality will run again. If verification fails, PSE restores the original working copy.")}
                AlertDialog.Builder(this).setTitle("Fix illegal Pokémon").setMessage(fixMessage).setNegativeButton("Cancel"){_,_->fixConsumed=true}.setOnCancelListener{fixConsumed=true}.setPositiveButton("Apply safe fixes"){_,_->
                    if(fixConsumed){showDialog("Gen 2 edit blocked","This legality repair confirmation was already handled. Reopen the Pokémon. Nothing was changed.");return@setPositiveButton}
                    fixConsumed=true
                    if(!bound()){showDialog("Gen 2 edit blocked","The confirmed source identity or bytes changed. Reopen the Pokémon. Nothing was changed.");return@setPositiveButton}
                    applyGen2AdvancedEdit(mon,location,bytes,openedFilePath,null,mon.nickname,mon.otName,mon.tid,mon.heldItem,mon.happiness,mon.level,mon.experience,plan.moves,plan.pp,intArrayOf(mon.dvs[1],mon.dvs[2],mon.dvs[3],mon.dvs[4]),mon.statExp.copyOf(),false,ppUps=plan.ppUps,onVerified={fixed->checkGen2PokemonLegality(fixed,location)},openedUri=openedUri,openedLabel=openedLabel)
                }.show()
            }
            b.show()
        }
    }

    private data class Gen2Evolution(val sourceSpecies:Int,val targetSpecies:Int,val requiredItem:Int?,val itemName:String?,val minimumLevel:Int?,val minimumHappiness:Int?=null,val bagItem:Int?=null,val bagItemName:String?=null,val statRelation:Int?=null)


    private fun canonicalGen2EvolutionMeta(species:Int):Gen2SpeciesMeta? {
        val meta=canonicalGen2SpeciesMetadata(species)?:return null
        return Gen2SpeciesMeta(species,GEN2_NATIONAL_NAMES.getOrElse(species-1){"Species #$species"},intArrayOf(meta.hp,meta.attack,meta.defense,meta.speed,meta.specialAttack,meta.specialDefense),"")
    }

    private fun validGen2EvolutionMeta(meta:Gen2SpeciesMeta?):Boolean=meta!=null&&meta.species in 1..251&&meta.baseStats.size==6&&meta.baseStats.all{it in 1..255}

    private fun loadGen2EvolutionMetaAsync(species:Int,done:(Gen2SpeciesMeta?)->Unit){
        canonicalGen2EvolutionMeta(species)?.let{done(it);return}
        loadGen2SpeciesMetaAsync(species){meta->done(meta?.takeIf{validGen2EvolutionMeta(it)})}
    }

