    private fun gen2EvolutionOptions(species:Int):List<Gen2Evolution> = when(species){
        44->listOf(Gen2Evolution(44,45,null,null,null,null,34,"Leaf Stone"),Gen2Evolution(44,182,null,null,null,null,169,"Sun Stone"))
        61->listOf(Gen2Evolution(61,62,null,null,null,null,24,"Water Stone"),gen2Evolution(61)!!)
        133->listOf(Gen2Evolution(133,134,null,null,null,null,24,"Water Stone"),Gen2Evolution(133,135,null,null,null,null,23,"Thunderstone"),Gen2Evolution(133,136,null,null,null,null,22,"Fire Stone"))
        236->listOf(Gen2Evolution(236,107,null,null,20,null,null,null,-1),Gen2Evolution(236,106,null,null,20,null,null,null,1),Gen2Evolution(236,237,null,null,20,null,null,null,0))
        else->listOfNotNull(gen2Evolution(species))
    }

    private fun gen2StatRelationLabel(relation:Int):String=when{relation<0->"Attack lower than Defense";relation>0->"Attack higher than Defense";else->"Attack equal to Defense"}

    private fun prepareGen2Evolution(mon:Gen2Pokemon,location:String){
        val openedFile=importedFile?:return showDialog("Evolve Pokémon","Load a Gen 2 save before evolving. Nothing was changed.")
        val openedUri=currentSourceUri;val openedLabel=currentSourceLabel
        fun bound()=importedFile?.absolutePath==openedFile.absolutePath&&currentSourceUri==openedUri&&currentSourceLabel==openedLabel
        val preparedSource=runCatching{openedFile.readBytes()}.getOrNull()?:return showDialog("Evolve Pokémon","The working save could not be read. Nothing was changed.")
        if(!bound()||!verifyGen2SaveIntegrity(preparedSource).first)return showDialog("Evolve Pokémon","The active Gen 2 save identity or integrity is invalid. Nothing was changed.")
        var evolutionSelectionConsumed=false
        if(mon.isEgg)return showDialog("Evolve Pokémon","Gen 2 Eggs cannot evolve.")
        val options=gen2EvolutionOptions(mon.species);if(options.isEmpty())return showDialog("Evolve Pokémon","This Pokémon has no verified supported evolution in Generation 2.")
        if(options.any{it.statRelation!=null}){
            val minimum=options.mapNotNull{it.minimumLevel}.maxOrNull()?:0;if(mon.level<minimum)return showDialog("Requirements not met","${GEN2_NATIONAL_NAMES.getOrElse(mon.species-1){"This Pokémon"}} must be at least Lv.$minimum before this stat-based evolution can be completed. Nothing was changed.")
            loadGen2EvolutionMetaAsync(mon.species){meta->if(evolutionSelectionConsumed||!bound()||!runCatching{openedFile.readBytes().contentEquals(preparedSource)}.getOrDefault(false)){showDialog("Evolve Pokémon","The active save identity or bytes changed. Reopen evolution. Nothing was changed.");return@loadGen2EvolutionMetaAsync};if(importedFile?.absolutePath!=openedFile.absolutePath){showDialog("Evolve Pokémon","The active save changed while source metadata was loading. Nothing was changed.");return@loadGen2EvolutionMetaAsync};val sourceMeta=meta?:run{showDialog("Evolve Pokémon","PSE could not load verified Gen 2 base-stat data for the source species. Nothing was changed.");return@loadGen2EvolutionMetaAsync};if(!validGen2EvolutionMeta(sourceMeta)||sourceMeta.species!=mon.species){showDialog("Evolve Pokémon","PSE could not load verified Gen 2 base-stat data for the source species. Nothing was changed.");return@loadGen2EvolutionMetaAsync};val stats=gen2CalculatedStats(sourceMeta,mon.level,mon.dvs,mon.statExp);val relation=stats[1].compareTo(stats[2]);val option=options.singleOrNull{it.statRelation==relation}?:run{showDialog("Evolve Pokémon","No verified Gen 2 evolution matches the current Attack and Defense. Nothing was changed.");return@loadGen2EvolutionMetaAsync};evolutionSelectionConsumed=true;prepareGen2EvolutionOption(mon,location,openedFile,option,sourceMeta,openedUri,openedLabel,preparedSource)}
            return
        }
        if(options.size==1){evolutionSelectionConsumed=true;prepareGen2EvolutionOption(mon,location,openedFile,options.single(),null,openedUri,openedLabel,preparedSource);return}
        val labels=options.map{option->val target=GEN2_NATIONAL_NAMES.getOrElse(option.targetSpecies-1){"Species #${option.targetSpecies}"};val method=when{option.bagItem!=null->"${option.bagItemName} from Item Pocket";option.requiredItem!=null->"trade holding ${option.itemName}";option.minimumHappiness!=null->"${option.minimumHappiness} happiness";option.minimumLevel!=null->"level ${option.minimumLevel}";else->"trade"};"$target • $method"}.toTypedArray()
        AlertDialog.Builder(this).setTitle("Choose evolution target").setItems(labels){_,which->if(evolutionSelectionConsumed||!bound()||!runCatching{openedFile.readBytes().contentEquals(preparedSource)}.getOrDefault(false)){showDialog("Evolve Pokémon","The active save identity or bytes changed. Reopen evolution. Nothing was changed.");return@setItems};evolutionSelectionConsumed=true;prepareGen2EvolutionOption(mon,location,openedFile,options[which],null,openedUri,openedLabel,preparedSource)}.setNegativeButton("Cancel",null).show()
    }

    private fun prepareGen2EvolutionOption(mon:Gen2Pokemon,location:String,openedFile:File,option:Gen2Evolution,sourceMeta:Gen2SpeciesMeta?=null,openedUri:Uri?,openedLabel:String?,preparedSource:ByteArray){
        fun bound()=importedFile?.absolutePath==openedFile.absolutePath&&currentSourceUri==openedUri&&currentSourceLabel==openedLabel
        if(!bound()){showDialog("Evolve Pokémon","The active save identity or bytes changed. Reopen evolution. Nothing was changed.");return}
        if(importedFile?.absolutePath!=openedFile.absolutePath){showDialog("Evolve Pokémon","The active save changed. Reopen evolution before continuing. Nothing was changed.");return}
        if(mon.isEgg||option.sourceSpecies!=mon.species)return showDialog("Evolve Pokémon","The selected Gen 2 evolution is invalid. Nothing was changed.")
        if(option.requiredItem!=null&&mon.heldItem!=option.requiredItem)return showDialog("Requirements not met","${GEN2_NATIONAL_NAMES.getOrElse(mon.species-1){"This Pokémon"}} must hold ${option.itemName} (item #${option.requiredItem}) before this trade evolution can be completed. Nothing was changed.")
        if(option.minimumLevel!=null&&mon.level<option.minimumLevel)return showDialog("Requirements not met","${GEN2_NATIONAL_NAMES.getOrElse(mon.species-1){"This Pokémon"}} must be at least Lv.${option.minimumLevel} before this level evolution can be completed. Nothing was changed.")
        if(option.minimumHappiness!=null&&mon.happiness<option.minimumHappiness)return showDialog("Requirements not met","${GEN2_NATIONAL_NAMES.getOrElse(mon.species-1){"This Pokémon"}} must have at least ${option.minimumHappiness} happiness before this friendship evolution can be completed. Nothing was changed.")
        val opened=runCatching{openedFile.readBytes()}.getOrNull()?:return showDialog("Evolve Pokémon","The working Gen 2 save could not be read. Nothing was changed.")
        if(!bound()||!opened.contentEquals(preparedSource)||!verifyGen2SaveIntegrity(opened).first){showDialog("Evolve Pokémon","The active save identity or bytes changed. Reopen evolution. Nothing was changed.");return}
        val profile=detectGen2Profile(opened)?:return showDialog("Evolve Pokémon","The Gen 2 save failed checksum or structural validation. Nothing was changed.")
        if(option.bagItem!=null){val items=parseGen2ItemPocket(opened,profile)?:return showDialog("Evolve Pokémon","The Gen 2 Item Pocket is invalid. Nothing was changed.");if(items.none{it.first==option.bagItem&&it.second>0})return showDialog("Requirements not met","The Item Pocket must contain ${option.bagItemName} (item #${option.bagItem}) before this stone evolution can be completed. Nothing was changed.")}
        val current=if(location.startsWith("Party"))parseGen2Party(opened,profile).firstOrNull{it.slot==mon.slot}else{val box=Regex("Box (\\d+)").find(location)?.groupValues?.getOrNull(1)?.toIntOrNull();box?.let{parseGen2Box(opened,it).firstOrNull{q->q.slot==mon.slot}}}
        if(current==null||!sameGen2BankRecord(current,mon))return showDialog("Evolve Pokémon","The selected Gen 2 Pokémon changed before evolution was prepared. Reopen it and try again.")
        var evolutionDialogOffered=false;var evolutionConfirmationConsumed=false
        loadGen2EvolutionMetaAsync(option.targetSpecies){meta->
            if(evolutionDialogOffered||!bound()||!runCatching{openedFile.readBytes().contentEquals(opened)}.getOrDefault(false)){showDialog("Evolve Pokémon","The active save identity or bytes changed. Reopen evolution. Nothing was changed.");return@loadGen2EvolutionMetaAsync}
            if(importedFile?.absolutePath!=openedFile.absolutePath){showDialog("Evolve Pokémon","The active save changed while target metadata was loading. Nothing was changed.");return@loadGen2EvolutionMetaAsync}
            val targetMeta=meta?:run{showDialog("Evolve Pokémon","PSE could not load verified Gen 2 base-stat data for the evolved species. Nothing was changed.");return@loadGen2EvolutionMetaAsync}
            if(!validGen2EvolutionMeta(targetMeta)||targetMeta.species!=option.targetSpecies){showDialog("Evolve Pokémon","PSE could not load verified Gen 2 base-stat data for the evolved species. Nothing was changed.");return@loadGen2EvolutionMetaAsync}
            val sourceName=GEN2_NATIONAL_NAMES.getOrElse(mon.species-1){"Species #${mon.species}"};val targetName=GEN2_NATIONAL_NAMES.getOrElse(option.targetSpecies-1){"Species #${option.targetSpecies}"}
            val method=when{option.statRelation!=null->"level up at or above Lv.${option.minimumLevel} with ${gen2StatRelationLabel(option.statRelation)}";option.minimumLevel!=null->"level up at or above Lv.${option.minimumLevel}";option.minimumHappiness!=null->"level up with at least ${option.minimumHappiness} happiness";option.bagItem!=null->"use ${option.bagItemName} (item #${option.bagItem}) from the Item Pocket";option.requiredItem==null->"trade without a required held item";else->"trade while holding ${option.itemName} (item #${option.requiredItem})"};val itemEffect=when{option.bagItem!=null->"consume one ${option.bagItemName} from the Item Pocket and preserve its held item";option.requiredItem==null->"preserve its held item";else->"consume the required held item"}
            evolutionDialogOffered=true
            AlertDialog.Builder(this).setTitle("Evolve $sourceName into $targetName?").setMessage("Verified Generation 2 method: $method.\n\nPSE will $itemEffect, preserve identity, moves, PP Ups, DVs, Stat Exp, happiness, Pokérus and caught data, rebuild party stats when applicable, register $targetName in the Pokédex, verify exact persistence, and require a verified kept recovery backup before writing. If a write fails, PSE attempts and verifies a complete restore. An unverified restore requires restoring the retained backup.").setNegativeButton("Cancel",null).setPositiveButton("Evolve"){_,_->if(evolutionConfirmationConsumed){showDialog("Evolve Pokémon","This evolution was already submitted. Reopen evolution before trying again.");return@setPositiveButton};evolutionConfirmationConsumed=true;applyGen2Evolution(mon,location,opened,option,targetMeta,openedFile,sourceMeta,openedUri,openedLabel)}.show()
        }
    }

    private fun applyGen2Evolution(mon:Gen2Pokemon,location:String,openedSource:ByteArray,option:Gen2Evolution,targetMeta:Gen2SpeciesMeta,openedFile:File,sourceMeta:Gen2SpeciesMeta?=null,openedUri:Uri?,openedLabel:String?){
        fun bound()=importedFile?.absolutePath==openedFile.absolutePath&&currentSourceUri==openedUri&&currentSourceLabel==openedLabel
        if(!bound()){showDialog("Evolve Pokémon","The active save identity or bytes changed. Reopen evolution. Nothing was changed.");return}
        if(importedFile?.absolutePath!=openedFile.absolutePath){showDialog("Evolve Pokémon","The active save changed. Reopen evolution before continuing. Nothing was changed.");return}
        val file=openedFile;val fresh=runCatching{file.readBytes()}.getOrNull()?:return
        var writeStarted=false
        var safetyBackup:File?=null;var evolved:Gen2Pokemon?=null;var evolvedName=""
        try{
            require(bound()&&verifyGen2SaveIntegrity(fresh).first){"The fresh Gen 2 save identity or integrity is invalid."}
            require(!mon.isEgg&&option.sourceSpecies==mon.species&&gen2EvolutionOptions(mon.species).contains(option)&&(option.statRelation==null||(sourceMeta!=null&&validGen2EvolutionMeta(sourceMeta)&&sourceMeta.species==mon.species))&&(option.minimumLevel==null||mon.level>=option.minimumLevel)&&(option.minimumHappiness==null||mon.happiness>=option.minimumHappiness)&&validGen2EvolutionMeta(targetMeta)&&targetMeta.species==option.targetSpecies){"The prepared Gen 2 evolution is invalid."};require(fresh.contentEquals(openedSource)){"The Gen 2 save changed while evolution was prepared."}
            val profile=detectGen2Profile(fresh)?:error("The fresh Gen 2 save failed checksum or structural validation.");require(gen2ChecksumValid(fresh,profile)){"The fresh Gen 2 checksum is invalid."};val party=location.startsWith("Party");val box=if(party)null else Regex("Box (\\d+)").find(location)?.groupValues?.getOrNull(1)?.toIntOrNull();require(party||(box!=null&&box in 1..14)){"The Gen 2 location is invalid."}
            val before=gen2LocationPayloads(fresh,location,profile);require(mon.slot in before.indices){"The selected Gen 2 slot no longer exists."};val current=if(party)parseGen2Party(fresh,profile).firstOrNull{it.slot==mon.slot}else parseGen2Box(fresh,box!!).firstOrNull{it.slot==mon.slot};require(current!=null&&sameGen2BankRecord(current,mon)){"The selected Gen 2 Pokémon changed before evolution."};require(option.minimumLevel==null||current.level>=option.minimumLevel){"The required evolution level is no longer met."};require(option.minimumHappiness==null||current.happiness>=option.minimumHappiness){"The required evolution happiness is no longer met."};if(option.statRelation!=null){val liveStats=gen2CalculatedStats(requireNotNull(sourceMeta),current.level,current.dvs,current.statExp);require(liveStats[1].compareTo(liveStats[2])==option.statRelation){"The required Attack and Defense relationship is no longer met."}};if(option.requiredItem!=null)require(current.heldItem==option.requiredItem){"The required ${option.itemName} is no longer held."};val expectedHeldItem=if(option.requiredItem==null)mon.heldItem else 0;val expectedItems=if(option.bagItem==null)null else{val items=parseGen2ItemPocket(fresh,profile)?.toMutableList()?:error("The fresh Gen 2 Item Pocket is invalid.");val itemIndex=items.indexOfFirst{it.first==option.bagItem&&it.second>0};require(itemIndex>=0){"The required ${option.bagItemName} is no longer in the Item Pocket."};val item=items[itemIndex];if(item.second==1)items.removeAt(itemIndex)else items[itemIndex]=item.first to (item.second-1);items}
            val(record,_,nickOffset)=gen2RecordOffsets(fresh,location,mon.slot);val listedOffset=gen2ListedSpeciesOffset(fresh,location,mon.slot);val oldDefault=GEN2_NATIONAL_NAMES.getOrElse(mon.species-1){""};val targetName=GEN2_NATIONAL_NAMES.getOrElse(option.targetSpecies-1){"Species #${option.targetSpecies}"};val expectedNickname=if(mon.nickname.equals(oldDefault,true))targetName else mon.nickname;val work=fresh.copyOf();if(expectedItems!=null)writeGen2ItemPocket(work,profile,expectedItems)
            work[record]=option.targetSpecies.toByte();work[listedOffset]=option.targetSpecies.toByte();work[record+1]=expectedHeldItem.toByte();writeGen1Text(work,nickOffset,11,expectedNickname)
            if(party){val stats=gen2CalculatedStats(targetMeta,mon.level,mon.dvs,mon.statExp);val oldCur=readU16BE(fresh,record+34);val oldMax=readU16BE(fresh,record+36);val damage=(oldMax-oldCur).coerceAtLeast(0);val newCur=if(oldCur==0)0 else(stats[0]-damage).coerceIn(1,stats[0]);writeU16BE(work,record+34,newCur);for(i in 0..5)writeU16BE(work,record+36+i*2,stats[i])}
            markGen2PokedexOwnedSeen(work,profile,option.targetSpecies);updateGen2PrimaryChecksum(work,profile)
            val(ownedBase,seenBase)=gen2PokedexBases(profile);val dexByte=(option.targetSpecies-1)/8;val allowed=HashSet<Int>();allowed.add(record);allowed.add(record+1);allowed.add(listedOffset);for(i in nickOffset..nickOffset+10)allowed.add(i);if(party)for(i in record+34..record+47)allowed.add(i);allowed.add(ownedBase+dexByte);allowed.add(seenBase+dexByte);if(expectedItems!=null){val itemBase=gen2ItemPocketBase(profile);for(i in itemBase until itemBase+42)allowed.add(i)};for(i in profile.checksumOffset..profile.checksumOffset+1)allowed.add(i);require(work.indices.all{i->i in allowed||work[i]==fresh[i]}){"The Gen 2 evolution changed unrelated save data."}
            fun matches(data:ByteArray,q:Gen2Pokemon):Boolean{if(q.species!=option.targetSpecies||q.nickname!=expectedNickname||q.otName!=mon.otName||q.tid!=mon.tid||q.heldItem!=expectedHeldItem||q.happiness!=mon.happiness||q.level!=mon.level||q.experience!=mon.experience||!q.moves.contentEquals(mon.moves)||!q.movePP.contentEquals(mon.movePP)||!q.statExp.contentEquals(mon.statExp)||!q.dvs.contentEquals(mon.dvs)||q.shiny!=mon.shiny||q.pokerus!=mon.pokerus||q.caughtData!=mon.caughtData||q.isEgg)return false;if(!party)return true;val(vr,_,_)=gen2RecordOffsets(data,location,q.slot);val stats=gen2CalculatedStats(targetMeta,q.level,q.dvs,q.statExp);return readU16BE(data,vr+36)==stats[0]&&(1..5).all{readU16BE(data,vr+36+it*2)==stats[it]}&&readU16BE(data,vr+34) in 0..stats[0]}
            val stagedProfile=detectGen2Profile(work)?:error("The staged Gen 2 save failed checksum or structural validation.");require(stagedProfile.key==profile.key&&gen2ChecksumValid(work,stagedProfile)){"The staged Gen 2 profile or checksum changed."};val stagedPayloads=gen2LocationPayloads(work,location,stagedProfile);require(stagedPayloads.size==before.size&&stagedPayloads.indices.all{it==mon.slot||stagedPayloads[it].contentEquals(before[it])}){"Another Gen 2 record changed during evolution."};val staged=if(party)parseGen2Party(work,stagedProfile).firstOrNull{it.slot==mon.slot}else parseGen2Box(work,box!!).firstOrNull{it.slot==mon.slot};require(staged!=null&&matches(work,staged)&&gen2PokedexOwnedSeen(work,stagedProfile,option.targetSpecies)&&(expectedItems==null||parseGen2ItemPocket(work,stagedProfile)==expectedItems)){"The staged evolution, party stats, Pokédex registration or Item Pocket did not verify."}
            require(bound()&&verifyGen2SaveIntegrity(work).first){"The staged Gen 2 evolution identity or full integrity is invalid."}
            require(importedFile?.absolutePath==openedFile.absolutePath&&file.readBytes().contentEquals(fresh)){"The Gen 2 source changed while evolution was staged. Nothing was written."}
            val backup=File.createTempFile(backupGameName(file)+"_PreGen2Evolution_",".backup",backupsDir());safetyBackup=backup
            backup.writeBytes(fresh);require(backup.readBytes().contentEquals(fresh)){"The complete evolution recovery backup did not verify."};retainGen2SafetyBackup(backup,fresh)
            require(bound()&&isBackupKept(backup)&&backup.readBytes().contentEquals(fresh)&&file.readBytes().contentEquals(fresh)){"The source or kept recovery backup changed before evolution. Nothing was written."}
            writeStarted=true
            file.writeBytes(work);val persisted=file.readBytes();require(persisted.contentEquals(work)){"The Gen 2 save changed while evolution was written."};val persistedProfile=detectGen2Profile(persisted)?:error("The persisted Gen 2 save failed checksum or structural validation.");require(persistedProfile.key==profile.key&&gen2ChecksumValid(persisted,persistedProfile)){"The persisted Gen 2 profile or checksum changed."};require(sameGen2PayloadList(gen2LocationPayloads(persisted,location,persistedProfile),stagedPayloads)){"The persisted Gen 2 location did not match the staged evolution."};val verified=if(party)parseGen2Party(persisted,persistedProfile).firstOrNull{it.slot==mon.slot}else parseGen2Box(persisted,box!!).firstOrNull{it.slot==mon.slot};require(verified!=null&&matches(persisted,verified)&&gen2PokedexOwnedSeen(persisted,persistedProfile,option.targetSpecies)&&(expectedItems==null||parseGen2ItemPocket(persisted,persistedProfile)==expectedItems)){"The persisted evolution, party stats, Pokédex registration or Item Pocket did not verify."}
            require(bound()&&verifyGen2SaveIntegrity(persisted).first&&file.readBytes().contentEquals(work)){"The persisted Gen 2 evolution identity or full integrity did not verify."}
            evolved=verified;evolvedName=targetName
        }catch(e:Exception){
            val restored=writeStarted&&runCatching{file.writeBytes(fresh)}.isSuccess&&runCatching{file.readBytes().contentEquals(fresh)&&verifyGen2SaveIntegrity(fresh).first}.getOrDefault(false)
            val recovery=if(!writeStarted)"Nothing was written to the save." else  if(restored)"The complete fresh working save was restored." else  "Automatic restore could not be verified. Stop editing this save and restore a verified backup."
            showDialog("Gen 2 evolution failed","${e.message?:"Unknown error"}\n\n$recovery"+(safetyBackup?.let{"\n\nRecovery backup: "+it.name}?:""));return
        }
        val result=evolved?:return
        Toast.makeText(this,"Evolved to $evolvedName and verified",Toast.LENGTH_LONG).show();showGen2Details(result,location)
    }

    private fun liveGen2PpUps(mon:Gen2Pokemon,location:String):IntArray? {
        val data=runCatching{importedFile?.readBytes()}.getOrNull()?:return null
        val profile=detectGen2Profile(data)?:return null
        if(!gen2ChecksumValid(data,profile))return null
        val current=if(location.startsWith("Party"))parseGen2Party(data,profile).firstOrNull{it.slot==mon.slot}else{val box=location.substringAfter("Box ","").substringBefore(" ").toIntOrNull()?:return null;if(box !in 1..14)return null;parseGen2Box(data,box).firstOrNull{it.slot==mon.slot}}
        if(current==null||!sameGen2BankRecord(current,mon))return null
        return runCatching{gen2PpUps(data,location,mon.slot)}.getOrNull()
    }

    private data class Gen2PokerusDetails(val status:String,val strain:Int,val daysRemaining:Int)

    private fun decodeGen2Pokerus(raw:Int):Gen2PokerusDetails? {
        if(raw !in 0..0xFF)return null
        val strain=(raw ushr 4) and 0x0F
        val daysRemaining=raw and 0x0F
        val status=when{raw==0->"Never infected";daysRemaining>0->"Active";else->"Cured / immune"}
        return Gen2PokerusDetails(status,strain,daysRemaining)
    }

    private data class Gen2CaughtDetails(val level:String,val time:String,val location:String,val otGender:String)

    private fun decodeGen2CaughtData(raw:Int):Gen2CaughtDetails? {
        if(raw !in 1..0xFFFF)return null
        val caughtLevel=(raw ushr 8) and 0x3F
        val caughtTime=(raw ushr 14) and 0x03
        val caughtLocation=raw and 0x7F
        val level=when(caughtLevel){0->"Unknown";1->"Egg marker (displayed as Lv. 5)";else->"Lv. $caughtLevel"}
        val time=when(caughtTime){1->"Morning";2->"Day";3->"Night";else->"Unknown"}
        val location=when(caughtLocation){0->"Unknown";0x7E->"Gift (ID 126)";0x7F->"Event (ID 127)";else->gen2LandmarkName(caughtLocation)?.let{"$it (ID $caughtLocation)"}?:"Landmark ID $caughtLocation"}
        val otGender=when{caughtLocation==0||caughtLocation==0x7F->"Unknown";(raw and 0x80)!=0->"Female";else->"Male"}
        return Gen2CaughtDetails(level,time,location,otGender)
    }

    private val gen2LandmarkNames="NEW BARK TOWN|ROUTE 29|CHERRYGROVE CITY|ROUTE 30|ROUTE 31|VIOLET CITY|SPROUT TOWER|ROUTE 32|RUINS OF ALPH|UNION CAVE|ROUTE 33|AZALEA TOWN|SLOWPOKE WELL|ILEX FOREST|ROUTE 34|GOLDENROD CITY|RADIO TOWER|ROUTE 35|NATIONAL PARK|ROUTE 36|ROUTE 37|ECRUTEAK CITY|TIN TOWER|BURNED TOWER|ROUTE 38|ROUTE 39|OLIVINE CITY|LIGHTHOUSE|BATTLE TOWER|ROUTE 40|WHIRL ISLANDS|ROUTE 41|CIANWOOD CITY|ROUTE 42|MT.MORTAR|MAHOGANY TOWN|ROUTE 43|LAKE OF RAGE|ROUTE 44|ICE PATH|BLACKTHORN CITY|DRAGON'S DEN|ROUTE 45|DARK CAVE|ROUTE 46|SILVER CAVE|PALLET TOWN|ROUTE 1|VIRIDIAN CITY|ROUTE 2|PEWTER CITY|ROUTE 3|MT.MOON|ROUTE 4|CERULEAN CITY|ROUTE 24|ROUTE 25|ROUTE 5|UNDERGROUND|ROUTE 6|VERMILION CITY|DIGLETT'S CAVE|ROUTE 7|ROUTE 8|ROUTE 9|ROCK TUNNEL|ROUTE 10|POWER PLANT|LAVENDER TOWN|LAV RADIO TOWER|CELADON CITY|SAFFRON CITY|ROUTE 11|ROUTE 12|ROUTE 13|ROUTE 14|ROUTE 15|ROUTE 16|ROUTE 17|ROUTE 18|FUCHSIA CITY|ROUTE 19|ROUTE 20|SEAFOAM ISLANDS|CINNABAR ISLAND|ROUTE 21|ROUTE 22|VICTORY ROAD|ROUTE 23|INDIGO PLATEAU|ROUTE 26|ROUTE 27|TOHJO FALLS|ROUTE 28|FAST SHIP".split("|")
    private fun gen2LandmarkName(landmarkId:Int):String? = gen2LandmarkNames.getOrNull(landmarkId-1)
    private fun canonicalGen2CaughtLocationChoices():List<NamedChoice> = mutableListOf(NamedChoice(0,"Unknown / not specified")).apply {
        gen2LandmarkNames.forEachIndexed { index,name -> add(NamedChoice(index+1,name)) }
        add(NamedChoice(0x7E,"Gift"));add(NamedChoice(0x7F,"Event"))
    }

