        addDetailSection(root,"IDENTITY");addDetailLine(root,"Location",location);addDetailLine(root,"Generation","Gen 2 • Gold / Silver / Crystal");addDetailLine(root,"Egg",if(mon.isEgg)"Yes • preserved Gen 2 egg marker" else "No");addDetailLine(root,"National Pokédex","#${mon.species.toString().padStart(3,'0')} $speciesName");addDetailLine(root,"Type",gen2SpeciesTypeName(mon.species)?:"Unknown / invalid species");val speciesMetadata=canonicalGen2SpeciesMetadata(mon.species);addDetailLine(root,"Base stats HP/Atk/Def/Spd/SpA/SpD",speciesMetadata?.let{"${it.hp}/${it.attack}/${it.defense}/${it.speed}/${it.specialAttack}/${it.specialDefense}"}?:"Unknown / invalid species");addDetailLine(root,"Catch rate",speciesMetadata?.catchRate?.toString()?:"Unknown");addDetailLine(root,"Base EXP yield",speciesMetadata?.baseExperience?.toString()?:"Unknown");addDetailLine(root,"Hatch cycles",speciesMetadata?.hatchCycles?.toString()?:"Unknown");val breedingMetadata=canonicalGen2BreedingMetadata(mon.species);addDetailLine(root,"Gender ratio",breedingMetadata?.let{gen2GenderRatioLabel(it.genderRatioCode)}?:"Unknown / invalid species");addDetailLine(root,"Egg Groups",breedingMetadata?.let{gen2EggGroupsLabel(it)}?:"Unknown / invalid species");addDetailLine(root,"Level",mon.level.toString());addDetailLine(root,"Experience",mon.experience.toString());val canonicalGrowth=canonicalGen2Growth(mon.species);val expProgress=gen2ExperienceProgress(mon.species,mon.level,mon.experience);when{mon.level>=100->{addDetailLine(root,"Growth group",canonicalGrowth?.let{gen2GrowthLabel(it)}?:"Unknown / invalid species");addDetailLine(root,"EXP to next level","Level cap")};expProgress==null->{addDetailLine(root,"Growth group","Unknown / ambiguous from save data");addDetailLine(root,"EXP to next level","Unavailable without a verified growth group")};else->{addDetailLine(root,"Growth group",expProgress.growthLabel);addDetailLine(root,"Next level at EXP",expProgress.nextLevelExperience.toString());addDetailLine(root,"EXP to next level",expProgress.remaining.toString())}};val heldItemName=if(mon.heldItem==0)"None" else gen2HeldItemName(mon.heldItem)?:"Unknown / unverified";addDetailLine(root,"Held item",heldItemName);addDetailLine(root,"Held item ID",mon.heldItem.toString());addDetailLine(root,if(mon.isEgg)"Remaining hatch cycles" else "Happiness",mon.happiness.toString());        val canonicalGender=gen2CanonicalGender(mon);val gender=when{mon.species in GEN2_GENDERLESS_SPECIES->"Genderless";canonicalGender==1->"Male";canonicalGender==0->"Female";else->"Unknown"}
        addDetailLine(root,"Shiny",if(mon.shiny)"Yes ✨" else "No");addDetailLine(root,"Gender",gender)

        addDetailSection(root,"TRAINER");addDetailLine(root,"Original Trainer",mon.otName.ifBlank{"—"});addDetailLine(root,"Trainer ID",mon.tid.toString())
        addDetailSection(root,"MOVES");for(i in 0..3)if(mon.moves[i]!=0){val ppUps=livePpUps?.getOrNull(i);val maxPp=ppUps?.let{gen2MoveMaxPp(mon.moves[i],it)};val moveName=gen2MoveName(mon.moves[i]);val metadata=gen2MoveMetadataSummary(mon.moves[i]);val details=when{ppUps!=null&&maxPp!=null->"$moveName (#${mon.moves[i]}) • PP ${mon.movePP[i]}/$maxPp • PP Ups $ppUps";ppUps!=null->"$moveName (#${mon.moves[i]}) • PP ${mon.movePP[i]} • PP Ups $ppUps";else->"$moveName (#${mon.moves[i]}) • PP ${mon.movePP[i]}"};addDetailLine(root,"Move ${i+1}",if(metadata!=null)"$details • $metadata" else details)}
        addDetailSection(root,"GEN 2 DATA");addDetailLine(root,"DVs HP/Atk/Def/Spd/Spc",mon.dvs.joinToString("/"));val unownForm=gen2UnownForm(mon.species,mon.dvs);if(unownForm!=null)addDetailLine(root,"Unown form",unownForm);val hiddenPower=gen2HiddenPower(mon.dvs);if(hiddenPower!=null){addDetailLine(root,"Hidden Power type",hiddenPower.first);addDetailLine(root,"Hidden Power power",hiddenPower.second.toString())};if(!mon.isEgg){val returnPower=gen2ReturnPower(mon.happiness);val frustrationPower=gen2FrustrationPower(mon.happiness);if(returnPower!=null&&frustrationPower!=null){addDetailLine(root,"Return power",returnPower.toString());addDetailLine(root,"Frustration power",frustrationPower.toString())}};addDetailLine(root,"Stat Exp HP/Atk/Def/Spd/Spc",mon.statExp.joinToString("/"));val pokerus=decodeGen2Pokerus(mon.pokerus);addDetailLine(root,"Pokérus raw","0x${mon.pokerus.toString(16).uppercase().padStart(2,'0')}");if(pokerus!=null){addDetailLine(root,"Pokérus status",pokerus.status);addDetailLine(root,"Pokérus strain",pokerus.strain.toString());addDetailLine(root,"Pokérus days remaining",pokerus.daysRemaining.toString())};addDetailLine(root,"Caught data","0x${mon.caughtData.toString(16).uppercase().padStart(4,'0')}");val caught=decodeGen2CaughtData(mon.caughtData);if(caught==null)addDetailLine(root,"Caught details","Not recorded")else{addDetailLine(root,"Caught level",caught.level);addDetailLine(root,"Time of day",caught.time);addDetailLine(root,"Caught location",caught.location);addDetailLine(root,"Original Trainer gender",caught.otGender)}
        setContentView(scroll)
    }

    private fun gen2ListName(mon:Gen2Pokemon):String = if(mon.isEgg)"Egg" else mon.nickname.ifBlank{"Pokémon #${mon.species}"}
    private fun gen2ListStatus(mon:Gen2Pokemon):String = if(mon.isEgg)"Hatch ${mon.happiness}" else "Lv.${mon.level}${if(mon.shiny)" ✦" else ""}"

    private fun gen2ListSnapshotMatches(file:File,opened:ByteArray,source:Uri?,label:String?):Boolean {
        fun bound()=importedFile?.absolutePath==file.absolutePath&&currentSourceUri==source&&currentSourceLabel==label
        if(!bound())return false
        return runCatching {
            val fresh=file.readBytes()
            fresh.contentEquals(opened)&&verifyGen2SaveIntegrity(fresh).first&&bound()
        }.getOrDefault(false)
    }

    private fun gen2GridCell(m:Gen2Pokemon?, box:Int, slot:Int,openedFile:File,openedUri:Uri?,openedLabel:String?,openedSnapshot:ByteArray):LinearLayout {
        val w=((resources.displayMetrics.widthPixels-dp(44))/4).coerceAtLeast(dp(70))
        return LinearLayout(this).apply{
            orientation=LinearLayout.VERTICAL;gravity=Gravity.CENTER;setPadding(dp(2),dp(3),dp(2),dp(3))
            val selected=m!=null&&gen2BoxMultiSelectMode&&selectedGen2BoxSlots.contains(m.slot)
            background=roundedBg(if(m==null)Color.rgb(11,27,38)else if(selected)Color.rgb(25,105,145)else CARD,Color.rgb(25,55,72),10)
            layoutParams=GridLayout.LayoutParams().apply{width=w;height=dp(112);setMargins(dp(2),dp(2),dp(2),dp(2))}
            if(m!=null){isClickable=true;setOnClickListener{if(importedFile?.absolutePath!=openedFile.absolutePath||currentSourceUri!=openedUri||currentSourceLabel!=openedLabel){showDialog("My Gen 2 Pokémon","The working save changed while this box list was open. Reopen the list in the current save. Nothing was changed.");return@setOnClickListener};if(!gen2ListSnapshotMatches(openedFile,openedSnapshot,openedUri,openedLabel)){showDialog("My Gen 2 Pokémon","The save bytes or integrity changed while this list was open. Reopen My Pokémon. Nothing was changed.");return@setOnClickListener};if(gen2BoxMultiSelectMode){if(!selectedGen2BoxSlots.add(m.slot))selectedGen2BoxSlots.remove(m.slot);showGen2PokemonViewer("boxes",box)}else showGen2Details(m,"Box $box • Slot ${slot+1}")};val iv=ImageView(this@MainActivity).apply{scaleType=ImageView.ScaleType.FIT_CENTER;contentDescription=gen2ListName(m)};addView(iv,LinearLayout.LayoutParams(dp(60),dp(58)));loadGen2Sprite(iv,m.species,m.shiny);addView(TextView(this@MainActivity).apply{text=gen2ListName(m);textSize=10f;maxLines=1;ellipsize=android.text.TextUtils.TruncateAt.END;gravity=Gravity.CENTER;setTextColor(TEXT);typeface=Typeface.DEFAULT_BOLD},LinearLayout.LayoutParams(-1,dp(18)));addView(TextView(this@MainActivity).apply{text=gen2ListStatus(m);textSize=10f;gravity=Gravity.CENTER;setTextColor(MUTED)})}
            else addView(TextView(this@MainActivity).apply{text="○";textSize=28f;gravity=Gravity.CENTER;setTextColor(Color.rgb(80,80,80))},LinearLayout.LayoutParams(dp(64),dp(78)))
            addView(TextView(this@MainActivity).apply{text=(slot+1).toString();textSize=10f;gravity=Gravity.CENTER;setTextColor(MUTED)})
        }
    }

    private fun gen2PartyCard(m:Gen2Pokemon,slot:Int,openedFile:File,openedUri:Uri?,openedLabel:String?,openedSnapshot:ByteArray)=LinearLayout(this).apply{
        orientation=LinearLayout.HORIZONTAL;gravity=Gravity.CENTER_VERTICAL;setPadding(dp(10),dp(8),dp(12),dp(8))
        val selected=gen2PartyMultiSelectMode&&selectedGen2PartySlots.contains(m.slot)
        background=roundedBg(if(selected)Color.rgb(25,105,145)else CARD,Color.rgb(22,137,190),10);isClickable=true
        setOnClickListener{if(importedFile?.absolutePath!=openedFile.absolutePath||currentSourceUri!=openedUri||currentSourceLabel!=openedLabel){showDialog("My Gen 2 Pokémon","The working save changed while this party list was open. Reopen the list in the current save. Nothing was changed.");return@setOnClickListener};if(!gen2ListSnapshotMatches(openedFile,openedSnapshot,openedUri,openedLabel)){showDialog("My Gen 2 Pokémon","The save bytes or integrity changed while this list was open. Reopen My Pokémon. Nothing was changed.");return@setOnClickListener};if(gen2PartyMultiSelectMode){if(!selectedGen2PartySlots.add(m.slot))selectedGen2PartySlots.remove(m.slot);showGen2PokemonViewer("party")}else showGen2Details(m,"Party • Slot ${slot+1}")}
        val iv=ImageView(this@MainActivity).apply{scaleType=ImageView.ScaleType.FIT_CENTER;contentDescription=gen2ListName(m)};addView(iv,LinearLayout.LayoutParams(dp(72),dp(72)));loadGen2Sprite(iv,m.species,m.shiny)
        val col=LinearLayout(this@MainActivity).apply{orientation=LinearLayout.VERTICAL};col.addView(TextView(this@MainActivity).apply{text="${gen2ListName(m)} • ${gen2ListStatus(m)}";textSize=18f;typeface=Typeface.DEFAULT_BOLD;setTextColor(TEXT)});col.addView(TextView(this@MainActivity).apply{text=if(m.isEgg)"Underlying species #${m.species} • OT ${m.otName.ifBlank{"—"}} • TID ${m.tid}" else "Species #${m.species} • OT ${m.otName.ifBlank{"—"}} • TID ${m.tid}";textSize=13f;setTextColor(MUTED)});addView(col,LinearLayout.LayoutParams(0,-2,1f));addView(TextView(this@MainActivity).apply{text=if(selected)"✓" else "›";textSize=28f;setTextColor(if(selected)Color.WHITE else MUTED)},LinearLayout.LayoutParams(dp(28),-1))
    }

