            val grid=GridLayout(this).apply{columnCount=4;alignmentMode=GridLayout.ALIGN_BOUNDS;useDefaultMargins=false};for(slot in 0 until 20)grid.addView(gen2GridCell(mons.getOrNull(slot),b,slot,f,boxNameSource,boxNameLabel,d));root.addView(grid)
        }
        addMutedLine(root,"Gen 2 Stage 2: advanced editing plus Duplicate/Delete enabled with dependent-data recalculation, checksum/reparse verification and automatic rollback.");scroll.addView(root);val shell=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setBackgroundColor(BG)};shell.addView(scroll,LinearLayout.LayoutParams(-1,0,1f));shell.addView(buildBottomNav("pokemon"),LinearLayout.LayoutParams(-1,-2));setContentView(shell)
    }

    private fun addGen2SelectionControls(root:LinearLayout,controls:LinearLayout) {
        val grid=GridLayout(this).apply{columnCount=2;orientation=GridLayout.HORIZONTAL;alignmentMode=GridLayout.ALIGN_BOUNDS;useDefaultMargins=false}
        val count=controls.childCount
        repeat(count){
            val control=controls.getChildAt(0)
            controls.removeViewAt(0)
            control.minimumHeight=dp(56)
            if(control is Button){control.setSingleLine(false);control.maxLines=Int.MAX_VALUE;control.ellipsize=null}
            val span=if(count==1)2 else 1
            grid.addView(control,GridLayout.LayoutParams().apply{
                rowSpec=GridLayout.spec(GridLayout.UNDEFINED)
                columnSpec=GridLayout.spec(GridLayout.UNDEFINED,span,1f)
                width=0;height=-2;setMargins(dp(3),dp(3),dp(3),dp(3))
            })
        }
        root.addView(grid,LinearLayout.LayoutParams(-1,-2).apply{bottomMargin=dp(6)})
    }

    private fun chooseGen2ReorderSource(file:File,opened:ByteArray,openedSource:Uri?,openedLabel:String?,box:Int?) {
        fun bound()=importedFile?.absolutePath==file.absolutePath&&currentSourceUri==openedSource&&currentSourceLabel==openedLabel
        val location=if(box==null)"Party" else "Box $box"
        val profile=detectGen2Profile(opened)
        val choices=runCatching{
            require(profile!=null&&bound()&&verifyGen2SaveIntegrity(opened).first)
            require(box==null||box in 1..14)
            require(file.readBytes().contentEquals(opened))
            val records=if(box==null)parseGen2Party(opened,profile!!)else parseGen2Box(opened,box)
            require(records.size>1)
            records
        }.getOrElse{showDialog("Reorder Gen 2 Pokémon","The location, verified save or source identity changed, or there are fewer than two records. Reopen My Pokémon. Nothing was changed.");return}
        val labels=choices.map{"Slot ${it.slot+1} • ${gen2ListName(it)} • ${gen2ListStatus(it)}"}.toTypedArray()
        var consumed=false
        AlertDialog.Builder(this).setTitle(if(box==null)"Choose Party Pokémon to reorder" else "Choose Box $box Pokémon to reorder")
            .setItems(labels){_,which->
                if(consumed){showDialog("Reorder Gen 2 Pokémon","This source choice was already handled. Reopen Reorder.");return@setItems}
                consumed=true
                val valid=runCatching{
                    require(which in choices.indices&&bound())
                    val fresh=file.readBytes()
                    require(fresh.contentEquals(opened)&&verifyGen2SaveIntegrity(fresh).first&&detectGen2Profile(fresh)?.key==profile?.key&&bound())
                }.isSuccess
                if(!valid){showDialog("Reorder Gen 2 Pokémon","The source choice, save or source identity changed. Reopen My Pokémon. Nothing was changed.");return@setItems}
                chooseGen2ReorderDestination(choices[which],location)
            }.setNegativeButton("Cancel",null).show()
    }

    private fun chooseGen2BoxForViewing(file:File,opened:ByteArray,openedSource:Uri?,openedLabel:String?) {
        fun bound()=importedFile?.absolutePath==file.absolutePath&&currentSourceUri==openedSource&&currentSourceLabel==openedLabel
        val profile=detectGen2Profile(opened)
        if(profile==null||!bound()||!runCatching{file.readBytes().contentEquals(opened)}.getOrDefault(false)){
            showDialog("Gen 2 PC Boxes","The verified save or source identity changed. Reopen My Pokémon. Nothing was changed.");return
        }
        val boxes=(1..14).toList()
        val labels=boxes.map{box->gen2BoxLabel(box,gen2BoxNameKey(box,file,profile,openedSource))+" • "+gen2NativeBoxNameLabel(opened,profile,box)+" • "+parseGen2Box(opened,box).size+"/20 Pokémon"}.toTypedArray()
        var consumed=false
        AlertDialog.Builder(this).setTitle("All 14 Gen 2 PC Boxes")
            .setItems(labels){_,which->
                if(consumed){showDialog("Gen 2 PC Boxes","This box choice was already handled. Reopen PC Boxes.");return@setItems}
                consumed=true
                val valid=runCatching{
                    require(which in boxes.indices&&bound())
                    val fresh=file.readBytes()
                    require(fresh.contentEquals(opened)&&verifyGen2SaveIntegrity(fresh).first&&detectGen2Profile(fresh)?.key==profile.key&&bound())
                }.isSuccess
                if(!valid){showDialog("Gen 2 PC Boxes","The box choice, save or source identity changed. Reopen My Pokémon. Nothing was changed.");return@setItems}
                gen2BoxMultiSelectMode=false;selectedGen2BoxSlots.clear();gen2PartyMultiSelectMode=false;selectedGen2PartySlots.clear()
                showGen2PokemonViewer("boxes",boxes[which])
            }.setNegativeButton("Cancel",null).show()
    }

    private fun gen2BoxNameKey(box:Int,file:File,profile:Gen2Profile,source:Uri?):String {
        require(box in 1..14){"Gen 2 PC box number must be between 1 and 14."}
        require(profile.key in setOf("GS","C")){"Unsupported Gen 2 box-label profile."}
        val scope=source?.toString()?:file.absolutePath
        return "gen2_"+profile.key+"_"+sha256(scope.toByteArray(Charsets.UTF_8))+"_box_"+box
    }

    private fun normaliseGen2BoxCustomName(raw:String):String=raw.trim().take(24)

    private fun gen2BoxLabel(box:Int,key:String):String {
        val name=normaliseGen2BoxCustomName(getSharedPreferences("pse_box_names",MODE_PRIVATE).getString(key,"").orEmpty())
        return if(name.isBlank())"Box $box" else "Box $box • $name"
    }

    private fun gen2BoxDestinationLabel(box:Int,empty:Int,file:File,profile:Gen2Profile,source:Uri?,opened:ByteArray):String {
        require(box in 1..14&&empty in 0..20){"Invalid Gen 2 destination box or reported free-slot count."}
        val label=gen2BoxLabel(box,gen2BoxNameKey(box,file,profile,source))
        return "$label • ${gen2NativeBoxNameLabel(opened,profile,box)} • $empty empty slot"+if(empty==1)"" else "s"
    }

    private fun editGen2BoxName(box:Int,file:File,opened:ByteArray,openedSource:Uri?,openedLabel:String?) {
        fun bound()=importedFile?.absolutePath==file.absolutePath&&currentSourceUri==openedSource&&currentSourceLabel==openedLabel
        if(!bound()){showDialog("Name Gen 2 Box","The active save or source identity changed. Reopen PC Boxes. No label or save was changed.");return}
        val profile=detectGen2Profile(opened)?:run{showDialog("Name Gen 2 Box","This label requires a verified Gen 2 save. Nothing was changed.");return}
        val key=gen2BoxNameKey(box,file,profile,openedSource)
        val prefs=getSharedPreferences("pse_box_names",MODE_PRIVATE)
        val previous=prefs.getString(key,null)
        val input=EditText(this).apply{setText(normaliseGen2BoxCustomName(previous.orEmpty()));hint="e.g. Team, Training, Trades";setSingleLine(true)}
        var consumed=false
        fun persist(raw:String) {
            if(consumed){showDialog("Name Gen 2 Box","This label action was already handled. Reopen PC Boxes.");return}
            consumed=true
            var commitStarted=false
            try{
                require(bound()){"The active save or source identity changed while this dialog was open."}
                val fresh=file.readBytes()
                require(fresh.contentEquals(opened)&&verifyGen2SaveIntegrity(fresh).first&&detectGen2Profile(fresh)?.key==profile.key){"The confirmed Gen 2 save changed or failed integrity verification."}
                require(prefs.getString(key,null)==previous){"The saved box label changed while this dialog was open."}
                val name=normaliseGen2BoxCustomName(raw)
                val edit=prefs.edit()
                if(name.isBlank())edit.remove(key)else edit.putString(key,name)
                require(bound()&&file.readBytes().contentEquals(opened)&&prefs.getString(key,null)==previous){"The save or label changed before the label could be saved."}
                commitStarted=true
                require(edit.commit()){"The box label could not be saved."}
                require(prefs.getString(key,null)==name.takeUnless{it.isBlank()}&&bound()&&file.readBytes().contentEquals(opened)){"The saved box label or active save could not be rechecked."}
            }catch(e:Exception){
                showDialog("Box label not completed",(e.message?:"Could not verify this label")+"\n\n"+if(commitStarted)"The label result is unverified. Reopen PC Boxes to check it. No game-save or backup bytes were written." else "No label was saved. No game-save or backup bytes were written.");return
            }
            Toast.makeText(this,"Gen 2 PSE box label saved and verified",Toast.LENGTH_SHORT).show()
            showGen2PokemonViewer("boxes",box)
        }
        AlertDialog.Builder(this).setTitle("Name Gen 2 Box $box")
            .setMessage("PSE-only label for this save, up to 24 characters. This does not rename the box in the game or change exported save bytes.")
            .setView(input).setPositiveButton("Save"){_,_->persist(input.text.toString())}
            .setNeutralButton("Clear name"){_,_->persist("")}
            .setNegativeButton("Cancel",null).show()
    }

    // Western native box-name tables: pinned PKHeX SAV2Offsets GS2727/C2703;
    // pret BOX_NAME_LENGTH=9, terminator50; verified Western box-keyboard glyphs, no control codes.
    private fun gen2NativeBoxNameOffset(data:ByteArray,profile:Gen2Profile,box:Int):Int {
        require(profile.key in setOf("GS","C")&&verifyGen2SaveIntegrity(data).first&&detectGen2Profile(data)?.key==profile.key){"A verified Gold, Silver or Crystal save is required."}
        require(box in 1..14){"The Gen 2 box number is invalid."}
        val base=when(profile.key){"GS"->0x2727;"C"->0x2703;else->error("Unsupported native box-name profile.")}
        val offset=base+(box-1)*9
        require(offset>=0&&offset+9<=data.size){"The in-game box name is outside the save."}
        return offset
    }

    private val gen2NativeBoxGlyphs=listOf("<PK>" to 0xE1,"<MN>" to 0xE2,"'d" to 0xD0,"'l" to 0xD1,"'m" to 0xD2,"'r" to 0xD3,"'s" to 0xD4,"'t" to 0xD5,"'v" to 0xD6,"×" to 0xF1,"(" to 0x9A,")" to 0x9B,":" to 0x9C,";" to 0x9D,"[" to 0x9E,"]" to 0x9F,"-" to 0xE3,"?" to 0xE6,"!" to 0xE7,"♂" to 0xEF,"♀" to 0xF5,"/" to 0xF3,"." to 0xE8,"," to 0xF4,"&" to 0xE9,"é" to 0xEA,"'" to 0xE0)

    private fun gen2NativeBoxName(data:ByteArray,profile:Gen2Profile,box:Int):String {
        val offset=gen2NativeBoxNameOffset(data,profile,box)
        val bytes=data.copyOfRange(offset,offset+9)
        val end=bytes.indexOf(0x50.toByte())
        require(end in 0..8){"The in-game box name has no verified terminator."}
        return buildString{for(i in 0 until end){val c=bytes[i].toInt()and 0xFF;append(when(c){in 0x80..0x99->('A'.code+c-0x80).toChar().toString();in 0xA0..0xB9->('a'.code+c-0xA0).toChar().toString();in 0xF6..0xFF->('0'.code+c-0xF6).toChar().toString();0x7F->" ";else->gen2NativeBoxGlyphs.firstOrNull{it.second==c}?.first?:error("This name contains unsupported game control codes. Nothing was changed.")})}}
    }

    // Display-only: decode the exact chooser snapshot; never re-read a live file or guess a name.
    private fun gen2NativeBoxNameLabel(data:ByteArray,profile:Gen2Profile,box:Int):String {
        val name=runCatching{gen2NativeBoxName(data,profile,box)}.getOrNull()
        return "In-game: "+(name?.ifEmpty{"(empty)"}?:"unavailable (unsupported/invalid)")
    }

    private fun encodeGen2NativeBoxName(name:String):ByteArray {
        val encoded=ArrayList<Byte>();var at=0
        while(at<name.length){
            val glyph=gen2NativeBoxGlyphs.firstOrNull{name.startsWith(it.first,at)}
            val value=if(glyph!=null){at+=glyph.first.length;glyph.second}else{val c=name[at++];when(c){in 'A'..'Z'->0x80+c.code-'A'.code;in 'a'..'z'->0xA0+c.code-'a'.code;in '0'..'9'->0xF6+c.code-'0'.code;' '->0x7F;else->error("Use verified Western box-keyboard characters only. Names are not truncated or substituted.")}}
            encoded.add(value.toByte())
            require(encoded.size<=8){"The in-game box name exceeds eight game characters."}
        }
        require(encoded.isNotEmpty()&&encoded.any{it!=0x7F.toByte()}){"Use 1–8 game characters, not a blank name."}
        val out=ByteArray(9){0x50.toByte()}
        for(i in encoded.indices)out[i]=encoded[i]
        return out
    }

    private fun editGen2NativeBoxName(box:Int,file:File,opened:ByteArray,openedSource:Uri?,openedLabel:String?) {
        fun bound()=importedFile?.absolutePath==file.absolutePath&&currentSourceUri==openedSource&&currentSourceLabel==openedLabel
        val profile=detectGen2Profile(opened)?:run{showDialog("In-game Box name","A verified Gen 2 save is required. Nothing was changed.");return}
        val previous=runCatching{require(bound()&&file.readBytes().contentEquals(opened)&&bound());gen2NativeBoxName(opened,profile,box)}
            .getOrElse{showDialog("In-game Box name",it.message?:"The saved name could not be verified. Nothing was changed.");return}
        val input=EditText(this).apply{setText(previous);setSingleLine(true);hint="Up to 8 game characters"}
        AlertDialog.Builder(this).setTitle("Rename in-game Box $box")
            .setMessage("This changes the name stored in the Gold / Silver / Crystal working save, not your PSE-only label. Use up to eight game characters, including the Western box-keyboard symbols. Enter <PK>, <MN> or 'd/'l/'m/'r/'s/'t/'v for the game's single-byte glyphs; each counts as one character. Unsupported control codes remain locked. Only this box's nine-byte name and the checksum may change. A verified kept recovery backup is required. Use Save & Replace later to apply it to the game.")
            .setView(input).setNegativeButton("Cancel",null)
            .setPositiveButton("Save in-game name"){_,_->saveGen2NativeBoxName(box,file,opened,openedSource,openedLabel,profile.key,input.text.toString())}
            .show()
    }

    private fun saveGen2NativeBoxName(box:Int,file:File,opened:ByteArray,openedSource:Uri?,openedLabel:String?,profileKey:String,name:String) {
        fun bound()=importedFile?.absolutePath==file.absolutePath&&currentSourceUri==openedSource&&currentSourceLabel==openedLabel
        var writeStarted=false
        var safetyBackup:File?=null
        try{
            require(bound()){"The active save identity changed after confirmation."}
            val encoded=encodeGen2NativeBoxName(name)
            val fresh=file.readBytes()
            require(fresh.contentEquals(opened)){"The complete working save changed. Reopen PC Boxes."}
            val profile=detectGen2Profile(fresh)?:error("The fresh Gen 2 save is invalid.")
            require(profile.key==profileKey){"The Gen 2 game profile changed."}
            val previous=gen2NativeBoxName(fresh,profile,box)
            if(previous==name){showDialog("In-game Box name unchanged","The name is already stored. No save, label or backup was changed.");return}
            val offset=gen2NativeBoxNameOffset(fresh,profile,box)
            val work=fresh.copyOf();encoded.copyInto(work,offset)
            updateGen2PrimaryChecksum(work,profile)
            require(work.indices.all{it in offset until offset+9||it in profile.checksumOffset..profile.checksumOffset+1||work[it]==fresh[it]}){"Unrelated save data changed while staging the name."}
            require(gen2NativeBoxName(work,profile,box)==name&&work.copyOfRange(offset,offset+9).contentEquals(encoded)){"The staged in-game name did not verify."}
            val backup=File.createTempFile(backupGameName(file)+"_PreBoxRename_",".backup",backupsDir());safetyBackup=backup
            backup.writeBytes(fresh);require(backup.readBytes().contentEquals(fresh)){"The recovery backup did not persist exactly."}
            retainGen2SafetyBackup(backup,fresh)
            require(bound()&&file.readBytes().contentEquals(fresh)&&backup.readBytes().contentEquals(fresh)&&isBackupKept(backup)){"The save, source identity or retained backup changed before writing."}
            writeStarted=true
            file.writeBytes(work)
            val persisted=file.readBytes()
            require(bound()&&persisted.contentEquals(work)&&gen2NativeBoxName(persisted,profile,box)==name&&persisted.copyOfRange(offset,offset+9).contentEquals(encoded)){"The complete persisted in-game name did not verify."}
        }catch(e:Exception){
            val restored=writeStarted&&runCatching{file.writeBytes(opened);require(file.readBytes().contentEquals(opened)&&verifyGen2SaveIntegrity(opened).first)}.isSuccess
            val recovery=if(!writeStarted)"Nothing was written to the working save." else  if(restored)"The exact previous working save was restored and verified." else  "Automatic rollback could not be verified. Stop editing and restore the kept recovery backup."
            showDialog("In-game Box rename failed",(e.message?:"Could not safely rename the box")+"\n\n"+recovery+(safetyBackup?.let{"\n\nRecovery backup: "+it.name}?:""));return
        }
        Toast.makeText(this,"In-game Gen 2 Box name saved and verified",Toast.LENGTH_LONG).show()
        showGen2PokemonViewer("boxes",box)
    }

    private fun updateGen2PrimaryChecksum(data: ByteArray, p: Gen2Profile) {
        require(data.size >= SIZE_G1) { "Not a supported Gen 2 SRAM image" }
        val sum = gen2Checksum(data, p)
        data[p.checksumOffset] = (sum and 0xFF).toByte()
        data[p.checksumOffset + 1] = ((sum ushr 8) and 0xFF).toByte()
        require(gen2ChecksumValid(data, p)) { "Gen 2 checksum rebuild failed" }
    }

    private fun gen2RecordOffsets(data: ByteArray, location: String, slot: Int): Triple<Int, Int, Int> {
        val party = location.startsWith("Party")
        if (party) {
            val p = detectGen2Profile(data) ?: error("Gen 2 profile is no longer valid")
            val mons = p.partyOffset + 8
            val ots = mons + 6 * 48
            val nicks = ots + 6 * 11
            require(slot in 0 until 6)
            return Triple(mons + slot * 48, ots + slot * 11, nicks + slot * 11)
        }
        val box = Regex("Box (\\d+)").find(location)?.groupValues?.getOrNull(1)?.toIntOrNull()
            ?: error("Could not determine the Gen 2 box number")
        require(box in 1..14 && slot in 0 until 20)
        val base = gen2BoxOffset(box)
        val mons = base + 22
        val ots = mons + 20 * 32
        val nicks = ots + 20 * 11
        return Triple(mons + slot * 32, ots + slot * 11, nicks + slot * 11)
    }

    private fun gen2ListedSpeciesOffset(data:ByteArray,location:String,slot:Int):Int {
        if(location.startsWith("Party")){val p=detectGen2Profile(data)?:error("Gen 2 profile is no longer valid");require(slot in 0 until 6);return p.partyOffset+1+slot}
        val box=Regex("Box (\\d+)").find(location)?.groupValues?.getOrNull(1)?.toIntOrNull()?:error("Could not determine the Gen 2 box number")
        require(box in 1..14&&slot in 0 until 20);return gen2BoxOffset(box)+1+slot
    }

    private fun sameGen2SelectionState(data:ByteArray,location:String,mon:Gen2Pokemon):Boolean {
        val record=runCatching{gen2RecordOffsets(data,location,mon.slot).first}.getOrNull()?:return false
        val listedOffset=runCatching{gen2ListedSpeciesOffset(data,location,mon.slot)}.getOrNull()?:return false
        val expectedListed=if(mon.isEgg)0xFD else mon.species
        return (data.getOrNull(record)?.toInt()?.and(0xFF)==mon.species)&&(data.getOrNull(listedOffset)?.toInt()?.and(0xFF)==expectedListed)
    }

    private fun showGen2EggEditor(mon:Gen2Pokemon,location:String){
        require(mon.isEgg){"The Gen 2 Egg editor only accepts records with the Egg marker."}
        val openedUri=currentSourceUri;val openedLabel=currentSourceLabel
        val openedFile=importedFile?:return
        val openedFilePath=runCatching{openedFile.canonicalPath}.getOrNull()?:return showDialog("Edit Gen 2 Egg","The selected save source could not be verified. Nothing was changed.")
        val openedSource=runCatching{openedFile.readBytes()}.getOrNull()?:return showDialog("Edit Gen 2 Egg","The Gen 2 save could not be read. Nothing was changed.")
        val openedProfile=detectGen2Profile(openedSource)?:return showDialog("Edit Gen 2 Egg","The Gen 2 save failed checksum validation. Nothing was changed.")
        val party=location.startsWith("Party")
        val box=if(party)null else Regex("Box (\\d+)").find(location)?.groupValues?.getOrNull(1)?.toIntOrNull()
        val openedLive=if(party)parseGen2Party(openedSource,openedProfile).firstOrNull{it.slot==mon.slot}else box?.let{parseGen2Box(openedSource,it).firstOrNull{q->q.slot==mon.slot}}
        if(openedLive==null||!openedLive.isEgg||!sameGen2BankRecord(openedLive,mon)){showDialog("Edit Gen 2 Egg","The selected Egg changed before the editor opened. Reopen it and try again.");return}
        val hatchCycles=EditText(this).apply{inputType=android.text.InputType.TYPE_CLASS_NUMBER;setText(mon.happiness.toString());setSelectAllOnFocus(true)}
        var consumed=false
        AlertDialog.Builder(this).setTitle("Edit Gen 2 Egg hatch cycles")
            .setMessage("The Gen 2 happiness byte stores remaining hatch cycles for an Egg. PSE will change only that byte and the save checksum, preserve the Egg marker and underlying Pokémon exactly, then reopen and verify the save.")
            .setView(hatchCycles).setNegativeButton("Cancel",null)
            .setPositiveButton("Save"){_,_->
                if(consumed){showDialog("Gen 2 Egg edit blocked","This Egg edit confirmation was already handled. Reopen the Egg. Nothing was changed.");return@setPositiveButton}
                consumed=true
                val requested=hatchCycles.text.toString().trim().toIntOrNull()
                if(requested==null||requested !in 0..255)showDialog("Edit Gen 2 Egg","Enter a remaining hatch-cycle value from 0 to 255. Nothing was changed.")
                else applyGen2EggHatchCycles(mon,location,openedSource,openedFilePath,requested,openedUri,openedLabel)
            }.show()
    }

    private fun applyGen2EggHatchCycles(mon:Gen2Pokemon,location:String,openedSource:ByteArray,openedFilePath:String,hatchCycles:Int,openedUri:Uri?,openedLabel:String?){
        fun bound()=runCatching{importedFile?.canonicalPath}.getOrNull()==openedFilePath&&currentSourceUri==openedUri&&currentSourceLabel==openedLabel
        val file=importedFile?:return
        if(runCatching{file.canonicalPath}.getOrNull()!=openedFilePath){showDialog("Gen 2 Egg edit failed","The selected save source changed before the edit was applied. Nothing was changed.");return}
        if(!bound()){showDialog("Gen 2 Egg edit blocked","The confirmed source identity changed. Reopen the Egg. Nothing was changed.");return}
        val fresh=runCatching{file.readBytes()}.getOrNull()?:return
        var writeStarted=false
        var safetyBackup:File?=null
        var verifiedEgg:Gen2Pokemon?=null
        try{
            require(bound()&&verifyGen2SaveIntegrity(fresh).first){"The complete confirmed Gen 2 Egg source or identity failed validation."}
            require(hatchCycles in 0..255){"Remaining hatch cycles must be from 0 to 255."}
            require(fresh.contentEquals(openedSource)){"The Gen 2 save changed while the Egg editor was open."}
            val profile=detectGen2Profile(fresh)?:error("The fresh Gen 2 save failed checksum validation.")
            require(gen2ChecksumValid(fresh,profile)){"The fresh Gen 2 checksum is invalid."}
            require(profile.key==detectGen2Profile(openedSource)?.key){"The confirmed Gen 2 Egg source profile changed."}
            val party=location.startsWith("Party")
            val box=if(party)null else Regex("Box (\\d+)").find(location)?.groupValues?.getOrNull(1)?.toIntOrNull()
            require(party||(box!=null&&box in 1..14)){"The Gen 2 Egg location is invalid."}
            val before=gen2LocationPayloads(fresh,location,profile)
            require(mon.slot in before.indices){"The selected Gen 2 Egg slot no longer exists."}
            val current=if(party)parseGen2Party(fresh,profile).firstOrNull{it.slot==mon.slot}else parseGen2Box(fresh,box!!).firstOrNull{it.slot==mon.slot}
            require(current!=null&&current.isEgg&&sameGen2BankRecord(current,mon)){"The selected Egg changed before the edit was applied."}
            require(bound()&&file.readBytes().contentEquals(fresh)){"The confirmed source changed before checking the Egg hatch-cycle edit."}
            if(current.happiness==hatchCycles){Toast.makeText(this,"Gen 2 Egg hatch cycles are already $hatchCycles",Toast.LENGTH_LONG).show();showGen2Details(current,location);return}
            val(record,_,_)=gen2RecordOffsets(fresh,location,mon.slot)
            val listedOffset=gen2ListedSpeciesOffset(fresh,location,mon.slot)
            require((fresh[listedOffset].toInt() and 0xFF)==0xFD){"The selected slot no longer has the Gen 2 Egg marker."}
            val expected=before.map{it.copyOf()}
            require(expected[mon.slot].size>28&&(expected[mon.slot][0].toInt() and 0xFF)==0xFD){"The selected Egg payload could not be verified."}
            expected[mon.slot][28]=hatchCycles.toByte()
            val work=fresh.copyOf();work[record+27]=hatchCycles.toByte();updateGen2PrimaryChecksum(work,profile)
            require(work.indices.all{i->i==record+27||i in profile.checksumOffset..profile.checksumOffset+1||work[i]==fresh[i]}){"The Gen 2 Egg edit changed unrelated save data."}
            val stagedProfile=detectGen2Profile(work)?:error("The staged Gen 2 Egg save failed checksum validation.")
            require(stagedProfile.key==profile.key&&gen2ChecksumValid(work,stagedProfile)){"The staged Gen 2 Egg profile or checksum changed."}
            val stagedPayloads=gen2LocationPayloads(work,location,stagedProfile)
            require(sameGen2PayloadList(stagedPayloads,expected)){"The staged Gen 2 Egg payload changed outside the hatch-cycle byte."}
            val staged=if(party)parseGen2Party(work,stagedProfile).firstOrNull{it.slot==mon.slot}else parseGen2Box(work,box!!).firstOrNull{it.slot==mon.slot}
            require(staged!=null&&staged.isEgg&&staged.species==mon.species&&staged.happiness==hatchCycles){"The staged Gen 2 Egg did not preserve its marker, species and hatch cycles."}
            require(verifyGen2SaveIntegrity(work).first){"The complete staged Gen 2 Egg edit failed integrity verification."}
            require(runCatching{importedFile?.canonicalPath}.getOrNull()==openedFilePath&&runCatching{file.canonicalPath}.getOrNull()==openedFilePath&&file.readBytes().contentEquals(fresh)){"The Gen 2 source changed while the Egg edit was staged. Nothing was written."}
            require(bound()){"The confirmed source identity changed before the Egg edit backup."}
            val backup=File.createTempFile(backupGameName(file)+"_PreGen2EggEdit_",".backup",backupsDir());safetyBackup=backup
            backup.writeBytes(fresh);require(backup.readBytes().contentEquals(fresh)){"The Gen 2 Egg recovery backup did not persist exactly."}
            retainGen2SafetyBackup(backup,fresh)
            require(bound()&&isBackupKept(backup)&&backup.readBytes().contentEquals(fresh)&&file.readBytes().contentEquals(fresh)){"The source identity, bytes or kept backup changed before the Egg edit."}
            writeStarted=true
            file.writeBytes(work)
            val persisted=file.readBytes()
            require(persisted.contentEquals(work)){"The Gen 2 Egg save changed while it was written."}
            val persistedProfile=detectGen2Profile(persisted)?:error("The persisted Gen 2 Egg save failed checksum validation.")
            require(persistedProfile.key==profile.key&&gen2ChecksumValid(persisted,persistedProfile)){"The persisted Gen 2 Egg profile or checksum changed."}
            val persistedPayloads=gen2LocationPayloads(persisted,location,persistedProfile)
            require(sameGen2PayloadList(persistedPayloads,expected)){"The persisted Gen 2 Egg payload did not match the exact staged edit."}
            val verified=if(party)parseGen2Party(persisted,persistedProfile).firstOrNull{it.slot==mon.slot}else parseGen2Box(persisted,box!!).firstOrNull{it.slot==mon.slot}
            require(verified!=null&&verified.isEgg&&verified.species==mon.species&&verified.happiness==hatchCycles){"The reopened Gen 2 Egg did not preserve its marker, species and hatch cycles."}
            require(bound()&&verifyGen2SaveIntegrity(persisted).first&&file.readBytes().contentEquals(work)){"The persisted Gen 2 Egg edit or confirmed identity did not verify."}
            verifiedEgg=verified
        }catch(e:Exception){
            val restored=writeStarted&&runCatching{file.writeBytes(fresh)}.isSuccess&&runCatching{file.readBytes().contentEquals(fresh)}.getOrDefault(false)
            val recovery=if(!writeStarted)"Nothing was written to the save." else  if(restored)"The complete fresh working save was restored." else  "Automatic restore could not be verified. Stop editing this save and restore a verified backup."
            showDialog("Gen 2 Egg edit failed","${e.message?:"Unknown error"}\n\n$recovery"+(safetyBackup?.let{"\n\nRecovery backup: "+it.name}?:""));return
        }
        val verified=requireNotNull(verifiedEgg)
        Toast.makeText(this,"Gen 2 Egg hatch cycles updated and verified",Toast.LENGTH_LONG).show();showGen2Details(verified,location)
    }

    private fun showGen2Editor(mon: Gen2Pokemon, location: String) {
        if(mon.isEgg){showGen2EggEditor(mon,location);return}
        val openedUri=currentSourceUri;val openedLabel=currentSourceLabel
        val openedFile=importedFile?:return
        val openedFilePath=runCatching{openedFile.canonicalPath}.getOrNull()?:run{showDialog("Edit Gen 2 Pokémon","The selected save source could not be verified. Nothing was changed.");return}
        val openedSource=runCatching{openedFile.readBytes()}.getOrNull()?:return
        val openedProfile=detectGen2Profile(openedSource)?:run{showDialog("Edit Gen 2 Pokémon","The Gen 2 save failed checksum validation. Nothing was changed.");return}
        val openedBox=Regex("Box (\\d+)").find(location)?.groupValues?.getOrNull(1)?.toIntOrNull()
        val openedLive=if(location.startsWith("Party"))parseGen2Party(openedSource,openedProfile).firstOrNull{it.slot==mon.slot}else openedBox?.let{parseGen2Box(openedSource,it).firstOrNull{q->q.slot==mon.slot}}
        if(openedLive==null||!sameGen2BankRecord(openedLive,mon)){showDialog("Edit Gen 2 Pokémon","The selected Pokémon or Egg state changed before the editor opened. Reopen it and try again.");return}
        val openedRecord=runCatching{gen2RecordOffsets(openedSource,location,mon.slot).first}.getOrElse{showDialog("Edit Gen 2 Pokémon","The selected record offsets could not be verified. Nothing was changed.");return}
        val openedPpUps=IntArray(4){(openedSource[openedRecord+23+it].toInt() ushr 6) and 3}
        val party = location.startsWith("Party")
        phoneBackAction = { showGen2Details(mon, location) }
        val scroll = ScrollView(this).apply { setBackgroundColor(BG) }
        val root = LinearLayout(this).apply { orientation = LinearLayout.VERTICAL; setPadding(dp(16), dp(58), dp(16), dp(100)); setBackgroundColor(BG) }
        scroll.addView(root)
        root.addView(TextView(this).apply { text = "Edit ${mon.nickname.ifBlank { "Pokémon #${mon.species}" }}"; textSize = 27f; typeface = Typeface.DEFAULT_BOLD; setTextColor(TEXT) })
        addMutedLine(root, "$location • Gen 2 consistency editor")
        addButton(root, "←  Cancel") { showGen2Details(mon, location) }

        addSectionTitle(root, "IDENTITY")
        val nickname = inputField("Nickname (max 10 characters)", mon.nickname).also { root.addView(it.first) }.second
        val ot = inputField("Original Trainer name (max 10 characters)", mon.otName).also { root.addView(it.first) }.second
        val tid = inputField("Trainer ID (0–65535)", mon.tid.toString(), true).also { root.addView(it.first) }.second
        val currentHeldItem=if(mon.heldItem==0)"None" else gen2HeldItemName(mon.heldItem)?.let{"$it (#${mon.heldItem})"}?:"Unknown / unverified (#${mon.heldItem})"
        var heldItemId=mon.heldItem
        val itemSelector=selectorButton("Held item",currentHeldItem).also { root.addView(it.first) }.second
        itemSelector.setOnClickListener {
            showSearchableChoiceDialog("Choose Gen 2 held item",canonicalGen2HeldItemChoices()) { chosen ->
                heldItemId=chosen.id
                itemSelector.text=chosen.toString()
            }
        }
        addMutedLine(root, "The verified Generation 2 holdable-item catalogue is bundled locally. An existing unknown byte is preserved unless you choose a replacement.")
        val happiness = inputField("Happiness (0–255)", mon.happiness.toString(), true).also { root.addView(it.first) }.second

        addSectionTitle(root, "LEVEL / EXPERIENCE")
        val level = inputField("Level (1–100)", mon.level.toString(), true).also { root.addView(it.first) }.second
        val experience = inputField("Experience (0–16,777,215)", mon.experience.toString(), true).also { root.addView(it.first) }.second
        addMutedLine(root, "If Level is changed, PSE sets EXP to the minimum for that level. Otherwise an EXP change automatically resolves the level from the species growth curve.")

        addSectionTitle(root, "MOVES / PP")
        addMutedLine(root, "The complete Generation 2 move list and base PP values are bundled locally; move editing does not require internet access.")
        val moveIds = mon.moves.copyOf()
        val ppFields = ArrayList<EditText>()
        val ppUpFields = ArrayList<EditText>()
        for (i in 0..3) {
            val selector = selectorButton("Move ${i + 1}", if (mon.moves[i] == 0) "None" else "${gen2MoveName(mon.moves[i])} (#${mon.moves[i]})").also { root.addView(it.first) }.second
            val pp = inputField("Move ${i + 1} PP (0–63)", mon.movePP[i].toString(), true).also { root.addView(it.first) }.second
            ppFields.add(pp)
            val ppUps = inputField("Move ${i + 1} PP Ups (0–3)", openedPpUps[i].toString(), true).also { root.addView(it.first) }.second
            ppUpFields.add(ppUps)
            selector.setOnClickListener {
                showSearchableChoiceDialog("Choose Gen 2 Move ${i + 1}", canonicalGen2MoveChoices()) { chosen ->
                    when{
                        chosen.id==0->{moveIds[i]=0;selector.text="None";pp.setText("0");ppUps.setText("0")}
                        chosen.id !in 1..251->showDialog("Gen 2 move", "${chosen.name} (#${chosen.id}) did not exist in Generation 2.")
                        else->{moveIds[i]=chosen.id;selector.text=chosen.toString();gen2MoveBasePp(chosen.id)?.let{base->pp.setText(base.coerceAtMost(63).toString())}}
                    }
                }
            }
        }

        addSectionTitle(root, "DVs")
        val atkDv=inputField("Attack DV (0–15)",mon.dvs[1].toString(),true).also{root.addView(it.first)}.second
        val defDv=inputField("Defense DV (0–15)",mon.dvs[2].toString(),true).also{root.addView(it.first)}.second
        val spdDv=inputField("Speed DV (0–15)",mon.dvs[3].toString(),true).also{root.addView(it.first)}.second
        val spcDv=inputField("Special DV (0–15)",mon.dvs[4].toString(),true).also{root.addView(it.first)}.second
        addMutedLine(root,"HP DV is derived automatically from the low bits of Attack/Defense/Speed/Special. Gen 2 shininess is DV-derived, so PSE changes the DVs when you change Shiny.")
        var desiredShiny = mon.shiny
        val shinyButton = selectorButton("Shiny", if(desiredShiny) "Yes ✨" else "No").also{root.addView(it.first)}.second
        shinyButton.setOnClickListener {
            val choices=arrayOf("Yes ✨ — make shiny","No — make non-shiny")
            AlertDialog.Builder(this).setTitle("Shiny state").setItems(choices){_,which->
                desiredShiny = which==0
                shinyButton.text = if(desiredShiny) "Yes ✨" else "No"
            }.setNegativeButton("Cancel",null).show()
        }
        addMutedLine(root,"Make Shiny uses a legal Gen 2 shiny DV pattern. Make Non-Shiny preserves your entered DVs unless they form a shiny pattern, in which case PSE changes the minimum necessary DV.")

        addSectionTitle(root, "STAT EXP")
        val seNames=arrayOf("HP","Attack","Defense","Speed","Special")
        val seFields=ArrayList<EditText>()
        for(i in 0..4) seFields.add(inputField("${seNames[i]} Stat Exp (0–65535)",mon.statExp[i].toString(),true).also{root.addView(it.first)}.second)
        addSectionTitle(root, "GEN 2 STATE")
        val openedPokerus=decodeGen2Pokerus(mon.pokerus)?:Gen2PokerusDetails("Never infected",0,0)
        val pokerusStatusNames=listOf("None","Active","Cured / immune")
        val initialPokerusStatus=when{openedPokerus.strain==0&&openedPokerus.daysRemaining==0->0;openedPokerus.daysRemaining>0->1;else->2}
        val pokerusStatus=spinnerField("Pokérus status",pokerusStatusNames,initialPokerusStatus).also{root.addView(it.first)}.second
        val pokerusStrain=inputField("Pokérus strain (1–15 when infected)",openedPokerus.strain.toString(),true).also{root.addView(it.first)}.second
        val pokerusDays=inputField("Pokérus days (1–15 active; 0 cured)",openedPokerus.daysRemaining.toString(),true).also{root.addView(it.first)}.second
        val openedCaught=decodeGen2CaughtData(mon.caughtData)
        val caughtRecord=spinnerField("Caught/met record",listOf("Not recorded","Recorded"),if(mon.caughtData==0)0 else 1).also{root.addView(it.first)}.second
        val caughtLevel=inputField("Caught level (0 unknown; 1 is the Gen 2 Egg/Lv. 5 marker; 2–63 exact)",((mon.caughtData ushr 8) and 0x3F).toString(),true).also{root.addView(it.first)}.second
        val caughtTime=spinnerField("Caught time",listOf("Unknown","Morning","Day","Night"),(mon.caughtData ushr 14) and 0x03).also{root.addView(it.first)}.second
        var caughtLocationId=mon.caughtData and 0x7F
        val caughtLocation=selectorButton("Caught location",openedCaught?.location?:"Unknown / not specified").also{root.addView(it.first)}.second
        caughtLocation.setOnClickListener {
            showSearchableChoiceDialog("Choose Gen 2 caught location",canonicalGen2CaughtLocationChoices()) { chosen -> caughtLocationId=chosen.id;caughtLocation.text=chosen.toString() }
        }
        val caughtOtGender=spinnerField("Original Trainer gender flag",listOf("Male","Female"),if((mon.caughtData and 0x80)!=0)1 else 0).also{root.addView(it.first)}.second
        addMutedLine(root,"PSE packs Pokérus strain and remaining days into the exact Gen 2 byte. Caught/met fields use the exact 16-bit value. Choosing Not recorded stores zero. PSE never invents an encounter level, time, location, or OT gender.")
        addMutedLine(root, if(party) "Party battle stats and current HP are recalculated automatically after DV, Stat Exp, Level or EXP changes." else "Boxed Pokémon have no cached battle-stat block; PSE still validates growth, DVs and Stat Exp before accepting the edit.")

        addButton(root, "💾  Save Changes") saveGen2@ {
            val nn=nickname.text.toString().trim(); val no=ot.text.toString().trim()
            val nt=tid.text.toString().toIntOrNull(); val ni=heldItemId; val nh=happiness.text.toString().toIntOrNull()
            val nl=level.text.toString().toIntOrNull(); val ne=experience.text.toString().toLongOrNull()
            val pp=IntArray(4){ppFields[it].text.toString().toIntOrNull()?:-1}
            val nppUps=IntArray(4){ppUpFields[it].text.toString().toIntOrNull()?:-1}
            val pokerusMode=pokerusStatus.selectedItemPosition
            val enteredPokerusStrain=pokerusStrain.text.toString().toIntOrNull()
            val enteredPokerusDays=pokerusDays.text.toString().toIntOrNull()
            val npokerus=when{
                pokerusMode==0->0
                enteredPokerusStrain==null||enteredPokerusStrain !in 1..15->null
                pokerusMode==1&&(enteredPokerusDays==null||enteredPokerusDays !in 1..15)->null
                pokerusMode==1->(enteredPokerusStrain shl 4) or requireNotNull(enteredPokerusDays)
                else->enteredPokerusStrain shl 4
            }
            val caughtMode=caughtRecord.selectedItemPosition
            val enteredCaughtLevel=caughtLevel.text.toString().toIntOrNull()
            val ncaughtData=when{
                caughtMode==0->0
                enteredCaughtLevel==null||enteredCaughtLevel !in 0..63||caughtLocationId !in 0..127->null
                else->(caughtTime.selectedItemPosition shl 14) or (enteredCaughtLevel shl 8) or (caughtOtGender.selectedItemPosition shl 7) or caughtLocationId
            }
            val ndv=intArrayOf(atkDv.text.toString().toIntOrNull()?:-1,defDv.text.toString().toIntOrNull()?:-1,spdDv.text.toString().toIntOrNull()?:-1,spcDv.text.toString().toIntOrNull()?:-1)
            val finalDv = if(ndv.all{it in 0..15}) {
                if(desiredShiny) {
                    val shinyAtk = intArrayOf(2,3,6,7,10,11,14,15).minByOrNull { kotlin.math.abs(it-ndv[0]) } ?: 10
                    intArrayOf(shinyAtk,10,10,10)
                } else if(gen2Shiny(intArrayOf(0,ndv[0],ndv[1],ndv[2],ndv[3]))) {
                    intArrayOf(ndv[0], if(ndv[1]==10) 9 else ndv[1], ndv[2], ndv[3])
                } else ndv.copyOf()
            } else ndv.copyOf()
            val nse=IntArray(5){seFields[it].text.toString().toIntOrNull()?:-1}
            when {
                nn.length>10||no.length>10 -> showDialog("Invalid values","Nickname and OT must be 10 characters or fewer.")
                nn.any{encodeGen1Char(it)==null}||no.any{encodeGen1Char(it)==null}->showDialog("Invalid values","Nickname/OT contains characters this English Gen 2 save cannot store.")
                nt==null||nt !in 0..65535->showDialog("Invalid values","Trainer ID must be 0–65535.")
                ni !in 0..255->showDialog("Invalid values","Held item ID must be 0–255.")
                ni!=mon.heldItem&&ni!=0&&ni !in gen2HeldItemIds->showDialog("Invalid values","That ID is not in the verified Gen 2 held-item catalogue. Existing unknown values can be preserved, but new values must be an ordinary item, Ball or TM01–TM50.")
                nh==null||nh !in 0..255->showDialog("Invalid values","Happiness must be 0–255.")
                nl==null||nl !in 1..100->showDialog("Invalid values","Level must be 1–100.")
                ne==null||ne !in 0..0xFFFFFF->showDialog("Invalid values","Experience must be 0–16,777,215.")
                moveIds.any{it !in 0..251}||pp.any{it !in 0..63}->showDialog("Invalid values","Move or PP value is outside Gen 2 limits.")
                nppUps.any{it !in 0..3}->showDialog("Invalid values","Every PP Up count must be 0–3.")
                !validGen2MovePpLimits(moveIds,pp,nppUps)->showDialog("Invalid PP","A move's PP is above its exact Gen 2 maximum for the selected PP Up count.")
                !validGen2MoveTupleLayout(moveIds,pp,nppUps)->showDialog("Invalid move slots","Active Gen 2 moves must be unique and consecutive. Empty slots must store zero PP and zero PP Ups.")
                npokerus==null->showDialog("Invalid values","Active Pokérus needs a strain and remaining-days value from 1–15. Cured Pokérus needs a strain from 1–15 and stores zero days.")
                ncaughtData==null->showDialog("Invalid values","A recorded caught/met entry needs a level from 0–63 and a valid Generation 2 location.")
                ndv.any{it !in 0..15}->showDialog("Invalid values","Every DV must be 0–15.")
                nse.any{it !in 0..65535}->showDialog("Invalid values","Every Stat Exp value must be 0–65535.")
                else -> {
                    val requestedLevel=nl; val requestedExp=ne
                    val levelChanged=requestedLevel!=mon.level
                    val expChanged=requestedExp!=mon.experience
                    val dvChanged=!finalDv.contentEquals(intArrayOf(mon.dvs[1],mon.dvs[2],mon.dvs[3],mon.dvs[4]))
                    val statExpChanged=!nse.contentEquals(mon.statExp)
                    val needsGrowthData=levelChanged || expChanged
                    val needsPartyBaseStats=party && (levelChanged || expChanged || dvChanged || statExpChanged)
                    val meta=if(needsGrowthData || needsPartyBaseStats) resolveGen2MetaOffline(mon,location) else null
                    if((needsGrowthData || needsPartyBaseStats) && meta==null){showDialog("Could not verify species data","PSE could not safely resolve this Pokémon's Gen 2 growth/base-stat data needed for the requested recalculation. No changes were written.");return@saveGen2}
                    val finalExp=if(levelChanged) gen2ExperienceForLevel(requireNotNull(meta).growth,requestedLevel) else requestedExp
                    val finalLevel=if(expChanged && !levelChanged) gen2LevelForExperience(requireNotNull(meta).growth,finalExp) else requestedLevel
                    val statRecalcNeeded=party && (finalLevel!=mon.level || finalExp!=mon.experience || dvChanged || statExpChanged)
                    if(statRecalcNeeded && (meta==null || meta.baseStats.all{it==0})){showDialog("Could not verify base stats","PSE could not uniquely derive the original Gen 2 base stats needed to rebuild this party Pokémon's battle stats. No changes were written.");return@saveGen2}
                    var editConsumed=false
                    AlertDialog.Builder(this).setTitle("Save Gen 2 changes?")
                        .setMessage("PSE will synchronize Level/EXP, derive HP DV and shiny state, encode all four PP Up counts, preserve exact Pokérus and caught/met values, recalculate party battle stats when needed, rebuild the save checksum, re-read the Pokémon, and roll back automatically if any verification fails. Gen 2 calculation data is resolved locally from the APK/save; internet access is not required.")
                        .setPositiveButton("Save"){_,_->
                            if(editConsumed){showDialog("Gen 2 edit blocked","This edit confirmation was already handled. Reopen the Pokémon. Nothing was changed.");return@setPositiveButton}
                            editConsumed=true
                            applyGen2AdvancedEdit(mon,location,openedSource,openedFilePath,meta,nn,no,nt,ni,nh,finalLevel,finalExp,moveIds.copyOf(),pp,finalDv,nse,statRecalcNeeded,pokerus=npokerus,caughtData=ncaughtData,ppUps=nppUps,openedUri=openedUri,openedLabel=openedLabel)
                        }
                        .setNegativeButton("Cancel",null).show()
                }
            }
        }
        addMutedLine(root,"PSE-wide consistency rule: dependent Pokémon data is recalculated or the edit is refused. Gen 1 already follows this rule; Gen 6/7 boxed records derive level from EXP, while unsafe party stat edits remain locked until their cached battle stats are rebuilt safely.")
        setContentView(scroll)
    }

    private fun applyGen2AdvancedEdit(mon:Gen2Pokemon,location:String,openedSource:ByteArray,openedFilePath:String,meta:Gen2SpeciesMeta?,nickname:String,otName:String,tid:Int,heldItem:Int,happiness:Int,level:Int,experience:Long,moves:IntArray,pp:IntArray,dvCore:IntArray,statExp:IntArray,recalcPartyStats:Boolean,pokerus:Int=mon.pokerus,caughtData:Int=mon.caughtData,ppUps:IntArray?=null,onVerified:((Gen2Pokemon)->Unit)?=null,openedUri:Uri?,openedLabel:String?){
        fun bound()=runCatching{importedFile?.canonicalPath}.getOrNull()==openedFilePath&&currentSourceUri==openedUri&&currentSourceLabel==openedLabel
        val file=importedFile?:return
        if(runCatching{file.canonicalPath}.getOrNull()!=openedFilePath){showDialog("Gen 2 edit failed","The selected save source changed before the edit was applied. Nothing was changed.");return}
        if(!bound()){showDialog("Gen 2 edit blocked","The confirmed source identity changed. Reopen the Pokémon. Nothing was changed.");return}
        val fresh=runCatching{file.readBytes()}.getOrNull()?:return
        var writeStarted=false
        var safetyBackup:File?=null
        var verifiedEdit:Gen2Pokemon?=null
        try{
            require(bound()&&verifyGen2SaveIntegrity(fresh).first){"The complete confirmed Gen 2 source or identity failed validation."}
            require(fresh.contentEquals(openedSource)){"The Gen 2 save changed while the editor or legality check was open."}
            val profile=detectGen2Profile(fresh)?:error("The fresh Gen 2 save did not pass its primary checksum.");require(gen2ChecksumValid(fresh,profile)){"The fresh Gen 2 checksum is invalid."}
            require(profile.key==detectGen2Profile(openedSource)?.key){"The confirmed Gen 2 edit profile changed."}
            val party=location.startsWith("Party");val box=if(party)null else Regex("Box (\\d+)").find(location)?.groupValues?.getOrNull(1)?.toIntOrNull();require(party||(box!=null&&box in 1..14)){"The Gen 2 box location is invalid."}
            val before=gen2LocationPayloads(fresh,location,profile);require(mon.slot in before.indices){"The selected Gen 2 slot no longer exists."};val current=if(party)parseGen2Party(fresh,profile).firstOrNull{it.slot==mon.slot}else parseGen2Box(fresh,box!!).firstOrNull{it.slot==mon.slot};require(current!=null&&sameGen2BankRecord(current,mon)){"The selected Gen 2 record changed before the edit was applied."}
            val(record,otOffset,nickOffset)=gen2RecordOffsets(fresh,location,mon.slot);val requestedPpUps=ppUps?:IntArray(4){(fresh[record+23+it].toInt() ushr 6) and 3};require(pokerus in 0..255&&caughtData in 0..65535&&requestedPpUps.size==4&&requestedPpUps.all{it in 0..3}){"The requested Gen 2 state fields are outside their exact stored ranges."};require(validGen2MoveTupleLayout(moves,pp,requestedPpUps)){"The requested Gen 2 move slots are duplicated, non-consecutive, or retain PP data while empty."};require(validGen2MovePpLimits(moves,pp,requestedPpUps)){"The requested Gen 2 move PP exceeds its exact maximum for the stored PP Up count."};val work=fresh.copyOf()
            writeGen1Text(work,nickOffset,11,nickname);writeGen1Text(work,otOffset,11,otName);work[record+1]=heldItem.toByte();writeU16BE(work,record+6,tid);writeU24BE(work,record+8,experience)
            for(i in 0..4)writeU16BE(work,record+11+i*2,statExp[i]);writeGen2Dvs(work,record+21,dvCore[0],dvCore[1],dvCore[2],dvCore[3]);for(i in 0..3){work[record+2+i]=moves[i].toByte();work[record+23+i]=((requestedPpUps[i] shl 6)or pp[i]).toByte()};work[record+27]=happiness.toByte();work[record+28]=pokerus.toByte();writeU16BE(work,record+29,caughtData);work[record+31]=level.toByte()
            val dvs=gen2Dvs(work,record+21)
            if(party&&recalcPartyStats){val stats=gen2CalculatedStats(requireNotNull(meta),level,dvs,statExp);val oldCur=readU16BE(work,record+34);val oldMax=readU16BE(work,record+36);val damage=(oldMax-oldCur).coerceAtLeast(0);val newCur=if(oldCur==0)0 else(stats[0]-damage).coerceIn(1,stats[0]);writeU16BE(work,record+34,newCur);writeU16BE(work,record+36,stats[0]);writeU16BE(work,record+38,stats[1]);writeU16BE(work,record+40,stats[2]);writeU16BE(work,record+42,stats[3]);writeU16BE(work,record+44,stats[4]);writeU16BE(work,record+46,stats[5])}
            updateGen2PrimaryChecksum(work,profile)
