    }


    private fun editSelectedGen2Levels(chosen:List<Gen2Pokemon>,location:String){
        val openedUri=currentSourceUri;val openedLabel=currentSourceLabel
        val file=importedFile?:return
        if(chosen.isEmpty()){showDialog("Set selected Gen 2 level","Select one or more Gen 2 Pokémon first.");return}
        if(chosen.map{it.slot}.distinct().size!=chosen.size){showDialog("Set selected Gen 2 level","The selection contains the same slot more than once. Nothing was changed.");return}
        val opened=runCatching{file.readBytes()}.getOrNull()?:return showDialog("Set selected Gen 2 level","The Gen 2 save could not be read. Nothing was changed.")
        val profile=detectGen2Profile(opened)?:return showDialog("Set selected Gen 2 level","The Gen 2 save failed checksum validation. Nothing was changed.")
        val party=location.startsWith("Party");val box=if(party)null else Regex("Box (\\d+)").find(location)?.groupValues?.getOrNull(1)?.toIntOrNull();if(!party&&(box==null||box !in 1..14))return showDialog("Set selected Gen 2 level","The Gen 2 box number is invalid. Nothing was changed.")
        val before=runCatching{gen2LocationPayloads(opened,location,profile)}.getOrElse{return showDialog("Set selected Gen 2 level",(it.message?:"The Gen 2 source location is invalid.")+" Nothing was changed.")};val source=if(party)parseGen2Party(opened,profile)else parseGen2Box(opened,box!!)
        val bound=try{chosen.sortedBy{it.slot}.map{selected->val live=source.firstOrNull{it.slot==selected.slot}?:error("A selected Gen 2 slot no longer exists.");require(sameGen2BankRecord(live,selected)){"A selected Gen 2 Pokémon or Egg state changed."};require(before[live.slot].isNotEmpty()){"A selected exact Gen 2 record is unavailable."};require(!live.isEgg){"Gen 2 Eggs cannot be level-edited before they hatch."};live}}catch(e:Exception){showDialog("Set selected Gen 2 level",(e.message?:"The selected Gen 2 records could not be validated.")+" Nothing was changed.");return}
        val input=EditText(this).apply{inputType=android.text.InputType.TYPE_CLASS_NUMBER;hint="1–100";setSingleLine(true)}
        var consumed=false
        AlertDialog.Builder(this).setTitle("Set ${bound.size} Gen 2 Pokémon to level…").setView(input).setNegativeButton("Cancel",null).setPositiveButton("Apply"){_,_->
            if(consumed){showDialog("Set selected Gen 2 level","This level confirmation was already handled. Reopen the selection. Nothing was changed.");return@setPositiveButton}
            consumed=true
            val level=input.text.toString().toIntOrNull();if(level==null||level !in 1..100){showDialog("Set selected Gen 2 level","Enter a level from 1 to 100. Nothing was changed.");return@setPositiveButton};applySelectedGen2Level(bound,location,opened,before,level,file,openedUri,openedLabel)}.show()
    }

    private fun applySelectedGen2Level(chosen:List<Gen2Pokemon>,location:String,openedSource:ByteArray,openedPayloads:List<ByteArray>,level:Int,openedFile:File,openedUri:Uri?,openedLabel:String?){
        fun bound()=importedFile?.absolutePath==openedFile.absolutePath&&currentSourceUri==openedUri&&currentSourceLabel==openedLabel
