                require(level in 1..100&&chosen.isNotEmpty()&&chosen.map{it.slot}.distinct().size==chosen.size){"The prepared Gen 2 batch level edit is invalid."};require(fresh.contentEquals(openedSource)){"The Gen 2 save changed while the level prompt or species data was open."}
                val profile=detectGen2Profile(fresh)?:error("The fresh Gen 2 save failed checksum validation.");require(gen2ChecksumValid(fresh,profile)){"The fresh Gen 2 checksum is invalid."};val party=location.startsWith("Party");val box=if(party)null else Regex("Box (\\d+)").find(location)?.groupValues?.getOrNull(1)?.toIntOrNull();require(party||(box!=null&&box in 1..14)){"The Gen 2 box number is invalid."}
                require(profile.key==detectGen2Profile(openedSource)?.key){"The confirmed Gen 2 batch level source profile changed."}
                val before=gen2LocationPayloads(fresh,location,profile);require(sameGen2PayloadList(before,openedPayloads)){"The Gen 2 source location changed after confirmation."};val current=if(party)parseGen2Party(fresh,profile)else parseGen2Box(fresh,box!!)
                val ordered=chosen.sortedBy{it.slot}.map{selected->val live=current.firstOrNull{it.slot==selected.slot};require(live!=null&&sameGen2BankRecord(live,selected)){"A selected Gen 2 Pokémon or Egg state changed after confirmation."};require(!live.isEgg){"Gen 2 Eggs cannot be level-edited before they hatch."};require(metaMap[live.species]?.let{validGen2PartyTransferMeta(it)}==true){"Verified Gen 2 growth or base-stat data is unavailable for species #${live.species}."};live}
