                    if(party){val stats=gen2CalculatedStats(meta,level,mon.dvs,mon.statExp);val oldCur=readU16BE(fresh,record+34);val oldMax=readU16BE(fresh,record+36);val damage=(oldMax-oldCur).coerceAtLeast(0);val newCur=if(oldCur==0)0 else(stats[0]-damage).coerceIn(1,stats[0]);writeU16BE(work,record+34,newCur);writeU16BE(work,record+36,stats[0]);for(i in 1..5)writeU16BE(work,record+36+i*2,stats[i]);for(i in record+34..record+47)allowed.add(i)}
                }
                updateGen2PrimaryChecksum(work,profile);for(i in profile.checksumOffset..profile.checksumOffset+1)allowed.add(i);require(work.indices.all{i->i in allowed||work[i]==fresh[i]}){"The Gen 2 batch level edit changed unrelated save bytes."}
                fun matches(data:ByteArray,q:Gen2Pokemon,old:Gen2Pokemon):Boolean{val meta=requireNotNull(metaMap[old.species]);val expectedExp=gen2ExperienceForLevel(meta.growth,level);if(q.species!=old.species||q.nickname!=old.nickname||q.otName!=old.otName||q.tid!=old.tid||q.heldItem!=old.heldItem||q.happiness!=old.happiness||q.level!=level||q.experience!=expectedExp||!q.moves.contentEquals(old.moves)||!q.movePP.contentEquals(old.movePP)||!q.statExp.contentEquals(old.statExp)||!q.dvs.contentEquals(old.dvs)||q.shiny!=old.shiny||q.pokerus!=old.pokerus||q.caughtData!=old.caughtData||q.isEgg!=old.isEgg)return false;if(!party)return true;val(record,_,_)=gen2RecordOffsets(data,location,q.slot);val stats=gen2CalculatedStats(meta,level,old.dvs,old.statExp);return readU16BE(data,record+36)==stats[0]&&(1..5).all{readU16BE(data,record+36+it*2)==stats[it]}&&readU16BE(data,record+34) in 0..stats[0]}
                val stagedProfile=detectGen2Profile(work)?:error("The staged Gen 2 save failed checksum verification.");require(stagedProfile.key==profile.key&&gen2ChecksumValid(work,stagedProfile)){"The staged Gen 2 profile or checksum changed."};val stagedPayloads=gen2LocationPayloads(work,location,stagedProfile);require(stagedPayloads.size==before.size&&stagedPayloads.indices.all{it in selectedSlots||stagedPayloads[it].contentEquals(before[it])}){"An unselected Gen 2 record changed during level staging."};val staged=if(party)parseGen2Party(work,stagedProfile)else parseGen2Box(work,box!!);require(ordered.all{old->staged.firstOrNull{it.slot==old.slot}?.let{matches(work,it,old)}==true}){"A staged Gen 2 level, EXP, party stat, or preserved field did not verify."}
