    private fun chooseSelectedGen2BoxMove(chosen:List<Gen2Pokemon>,sourceBox:Int){
        val openedFile=importedFile?:return
        val openedUri=currentSourceUri;val openedLabel=currentSourceLabel
        if(chosen.isEmpty()){showDialog("Move selected Gen 2 Pokémon","Select one or more Gen 2 boxed Pokémon first.");return}
        val openedSnapshot=runCatching{openedFile.readBytes()}.getOrNull()
        if(openedSnapshot==null||!gen2ListSnapshotMatches(openedFile,openedSnapshot,openedUri,openedLabel)){showDialog("Move selected Gen 2 Pokémon","The save bytes or integrity changed before the move menu opened. Reopen the selection. Nothing was changed.");return}
        var menuConsumed=false
        AlertDialog.Builder(this).setTitle("Move ${chosen.size} selected Pokémon").setItems(arrayOf("Move to Party","Move to another PC box")){_,which->
            if(menuConsumed){return@setItems};menuConsumed=true
            if(which !in 0..1){showDialog("Move selected Gen 2 Pokémon","The move choice is invalid. Nothing was changed.");return@setItems}
            if(currentSourceUri!=openedUri||currentSourceLabel!=openedLabel){showDialog("Move selected Gen 2 Pokémon","The original source identity changed while the move menu was open. Reopen the selection. Nothing was changed.");return@setItems}
            if(!gen2ListSnapshotMatches(openedFile,openedSnapshot,openedUri,openedLabel)){showDialog("Move selected Gen 2 Pokémon","The save bytes or integrity changed while the move menu was open. Reopen the selection. Nothing was changed.");return@setItems}
            if(importedFile?.absolutePath!=openedFile.absolutePath){showDialog("Move selected Gen 2 Pokémon","The working save changed while the move menu was open. Reopen the selection in the current save. Nothing was changed.")}else{if(which==0)confirmSelectedGen2BoxToParty(chosen,sourceBox)else confirmSelectedGen2CrossBoxMove(chosen,sourceBox)}}.setNegativeButton("Cancel"){_,_->menuConsumed=true}.setOnCancelListener{menuConsumed=true}.show()
    }

    private fun validGen2PartyTransferMeta(meta:Gen2SpeciesMeta?):Boolean=meta!=null&&meta.species in 1..251&&meta.baseStats.size==6&&meta.baseStats.all{it in 1..255}&&meta.growth in setOf("GROWTH_FAST","GROWTH_MEDIUM_FAST","GROWTH_MEDIUM_SLOW","GROWTH_SLOW")

    private fun canonicalGen2PartyTransferMeta(species:Int):Gen2SpeciesMeta? {
        val stats=canonicalGen2SpeciesMetadata(species)?:return null
        val growth=canonicalGen2Growth(species)?:return null
        return Gen2SpeciesMeta(species,GEN2_NATIONAL_NAMES.getOrElse(species-1){"Species #$species"},intArrayOf(stats.hp,stats.attack,stats.defense,stats.speed,stats.specialAttack,stats.specialDefense),growth).takeIf{validGen2PartyTransferMeta(it)}
    }

    private fun loadGen2PartyTransferMeta(chosen:List<Gen2Pokemon>,done:(Map<Int,Gen2SpeciesMeta>?)->Unit){
        val species=chosen.map{it.species}.distinct();val out=linkedMapOf<Int,Gen2SpeciesMeta>()
        fun next(index:Int){if(index>=species.size){done(out);return};val id=species[index];canonicalGen2PartyTransferMeta(id)?.let{out[id]=it;next(index+1);return};val key="gen2_species_meta_$id";gen2MetaMemory[id]?.let{if(!validGen2PartyTransferMeta(it))gen2MetaMemory.remove(id)};metaPrefs.getString(key,null)?.let{decodeGen2SpeciesMeta(it)}?.let{if(!validGen2PartyTransferMeta(it))metaPrefs.edit().remove(key).apply()}
            loadGen2SpeciesMetaAsync(id){meta->if(!validGen2PartyTransferMeta(meta)||meta?.species!=id){done(null)}else{out[id]=requireNotNull(meta);next(index+1)}}
        };next(0)
    }

    private fun appendGen2PartyPayload(data:ByteArray,payload:ByteArray,meta:Gen2SpeciesMeta):Int{
        require(payload.size==55&&validGen2PartyTransferMeta(meta)){"The Gen 2 party payload or species metadata is invalid."};val profile=detectGen2Profile(data)?:error("The Gen 2 save failed checksum validation.");val base=profile.partyOffset;val count=data[base].toInt() and 0xFF;require(count in 0..5){"The Gen 2 party is full."};val listed=payload[0].toInt() and 0xFF;val species=payload[1].toInt() and 0xFF;require(species==meta.species&&species in 1..251&&(listed==species||listed==0xFD)){"The Gen 2 party payload has inconsistent species or Egg metadata."}
        val mons=base+8;val ots=mons+6*48;val nicks=ots+6*11;val record=mons+count*48;data[base]=(count+1).toByte();data[base+1+count]=payload[0];data[base+1+count+1]=0xFF.toByte();payload.copyInto(data,record,1,33);data[record+32]=0;data[record+33]=0;val level=payload[32].toInt() and 0xFF;val dvs=gen2Dvs(payload,22);val statExp=IntArray(5){readU16BE(payload,12+it*2)};val stats=gen2CalculatedStats(meta,level,dvs,statExp);writeU16BE(data,record+34,stats[0]);for(i in 0..5)writeU16BE(data,record+36+i*2,stats[i]);payload.copyInto(data,ots+count*11,33,44);payload.copyInto(data,nicks+count*11,44,55);updateGen2PrimaryChecksum(data,profile);return count
    }

    private fun verifyGen2PartyTransferStats(data:ByteArray,mon:Gen2Pokemon,meta:Gen2SpeciesMeta):Boolean{
        val record=runCatching{gen2RecordOffsets(data,"Party",mon.slot).first}.getOrNull()?:return false;val expected=gen2CalculatedStats(meta,mon.level,mon.dvs,mon.statExp);return (data[record+32].toInt() and 0xFF)==0&&(data[record+33].toInt() and 0xFF)==0&&readU16BE(data,record+34)==expected[0]&&(0..5).all{readU16BE(data,record+36+it*2)==expected[it]}
    }

    private fun confirmSelectedGen2BoxToParty(chosen:List<Gen2Pokemon>,sourceBox:Int){
        val openedUri=currentSourceUri;val openedLabel=currentSourceLabel
        val file=importedFile?:return
        if(chosen.isEmpty()){showDialog("Move selected Gen 2 Pokémon to Party","Select one or more Gen 2 boxed Pokémon first.");return}
        if(sourceBox !in 1..14||chosen.map{it.slot}.distinct().size!=chosen.size){showDialog("Move selected Gen 2 Pokémon to Party","The source box or selection is invalid. Nothing was changed.");return}
        val opened=runCatching{file.readBytes()}.getOrNull()?:return showDialog("Move selected Gen 2 Pokémon to Party","The Gen 2 source could not be read.");val profile=detectGen2Profile(opened)?:return showDialog("Move selected Gen 2 Pokémon to Party","The Gen 2 source failed checksum validation. Nothing was changed.")
