        val party=location.startsWith("Party");val box=if(party)null else Regex("Box (\\d+)").find(location)?.groupValues?.getOrNull(1)?.toIntOrNull();if(!party&&(box==null||box !in 1..14))return showDialog("Reorder Gen 2 Pokémon","The Gen 2 box number is invalid. Nothing was changed.");val current=if(party)parseGen2Party(opened,profile)else parseGen2Box(opened,box!!);val source=current.firstOrNull{it.slot==selected.slot&&sameGen2BankRecord(it,selected)}?:return showDialog("Reorder Gen 2 Pokémon","The selected Gen 2 Pokémon or Egg state changed. Reopen it and try again.");val choices=current.filter{it.slot!=source.slot};if(choices.isEmpty())return showDialog("Reorder Gen 2 Pokémon","There is no other Gen 2 Pokémon in $location to swap with.")
        var consumed=false
