    private fun reorderGen2Pokemon(source:Gen2Pokemon,destination:Gen2Pokemon,location:String,openedSource:ByteArray,openedPayloads:List<ByteArray>,openedFile:File,openedUri:Uri?,openedLabel:String?){
        fun bound()=importedFile?.absolutePath==openedFile.absolutePath&&currentSourceUri==openedUri&&currentSourceLabel==openedLabel
        if(importedFile?.absolutePath!=openedFile.absolutePath){showDialog("Reorder Gen 2 Pokémon","The active save changed after the swap list opened. Reopen the selection before reordering. Nothing was changed.");return}
        if(!bound()){showDialog("Reorder Gen 2 Pokémon","The source identity changed after confirmation. Reopen the selection. Nothing was changed.");return}
        val file=openedFile;val fresh=runCatching{file.readBytes()}.getOrNull()?:return
        var safetyBackup:File?=null
        var writeStarted=false
        try{
            require(bound()&&verifyGen2SaveIntegrity(fresh).first){"The confirmed Gen 2 source identity or full save integrity changed."}
            require(source.slot!=destination.slot){"Choose two different Gen 2 slots."};require(fresh.contentEquals(openedSource)){"The Gen 2 save changed after the reorder list opened."};val profile=detectGen2Profile(fresh)?:error("The fresh Gen 2 save failed checksum validation.");require(gen2ChecksumValid(fresh,profile)){"The fresh Gen 2 checksum is invalid."};val before=gen2LocationPayloads(fresh,location,profile);require(sameGen2PayloadList(before,openedPayloads)){"The Gen 2 location order or contents changed after confirmation."}
            require(profile.key==detectGen2Profile(openedSource)?.key){"The Gen 2 source profile changed."}
            val party=location.startsWith("Party");val box=if(party)null else Regex("Box (\\d+)").find(location)?.groupValues?.getOrNull(1)?.toIntOrNull();require(party||(box!=null&&box in 1..14)){"The Gen 2 box number is invalid."};val current=if(party)parseGen2Party(fresh,profile)else parseGen2Box(fresh,box!!);val freshSource=current.firstOrNull{it.slot==source.slot};val freshDestination=current.firstOrNull{it.slot==destination.slot};require(freshSource!=null&&freshDestination!=null&&sameGen2BankRecord(freshSource,source)&&sameGen2BankRecord(freshDestination,destination)){"A selected Gen 2 Pokémon or Egg state changed before reordering."}
            val expected=before.map{it.copyOf()}.toMutableList();val temp=expected[source.slot];expected[source.slot]=expected[destination.slot];expected[destination.slot]=temp;val work=fresh.copyOf();swapGen2LocationRecords(work,location,source.slot,destination.slot);val stagedProfile=detectGen2Profile(work)?:error("The staged Gen 2 save failed checksum verification.");require(gen2ChecksumValid(work,stagedProfile)){"The staged Gen 2 checksum is invalid."};require(sameGen2PayloadList(gen2LocationPayloads(work,location,stagedProfile),expected)){"The staged Gen 2 raw record order or fields changed."}
            val staged=if(party)parseGen2Party(work,stagedProfile)else parseGen2Box(work,box!!);require(sameGen2BankRecord(staged[source.slot],destination)&&sameGen2BankRecord(staged[destination.slot],source)){"The staged Gen 2 Pokémon or Egg states did not swap exactly."};
            require(verifyGen2SaveIntegrity(work).first&&stagedProfile.key==profile.key){"The complete staged Gen 2 save failed integrity/profile validation."}
            require(importedFile?.absolutePath==openedFile.absolutePath&&file.readBytes().contentEquals(fresh)){"The Gen 2 source changed while the reorder was staged. Nothing was written."}
            require(bound()){"The confirmed Gen 2 source identity changed before backup."}
            val backup=File.createTempFile(backupGameName(file)+"_PreGen2Reorder_",".backup",backupsDir());safetyBackup=backup
            backup.writeBytes(fresh);require(backup.readBytes().contentEquals(fresh)){"The exact pre-reorder recovery backup could not be verified."}
            retainGen2SafetyBackup(backup,fresh)
            require(bound()&&isBackupKept(backup)&&backup.readBytes().contentEquals(fresh)&&file.readBytes().contentEquals(fresh)){"The confirmed source or retained recovery backup changed before writing."}
            writeStarted=true
            file.writeBytes(work);val written=file.readBytes();require(written.contentEquals(work)){"The Gen 2 save changed while the reorder was written."};val writtenProfile=detectGen2Profile(written)?:error("The persisted Gen 2 save failed checksum verification.");require(gen2ChecksumValid(written,writtenProfile)){"The persisted Gen 2 checksum is invalid."};require(sameGen2PayloadList(gen2LocationPayloads(written,location,writtenProfile),expected)){"The persisted Gen 2 raw record order or fields changed."}
            require(bound()&&writtenProfile.key==profile.key&&verifyGen2SaveIntegrity(written).first&&file.readBytes().contentEquals(work)){"The persisted Gen 2 source identity or complete save verification failed."}
        }catch(e:Exception){
            val restored=writeStarted&&runCatching{file.writeBytes(fresh)}.isSuccess&&runCatching{file.readBytes().contentEquals(fresh)}.getOrDefault(false)
            val recovery=if(!writeStarted)"Nothing was written to the save." else  if(restored)"The exact Gen 2 save was restored." else  "Automatic restore could not be verified. Stop editing this save and restore a verified backup."
            showDialog("Reorder Gen 2 Pokémon failed","${e.message?:"Unknown error"}\n\n$recovery"+(safetyBackup?.let{"\n\nRecovery backup: "+it.name}?:""));return
        }
        Toast.makeText(this,"Gen 2 Pokémon reordered and verified",Toast.LENGTH_LONG).show();if(location.startsWith("Party"))showGen2PokemonViewer("party")else showGen2PokemonViewer("boxes",Regex("Box (\\d+)").find(location)?.groupValues?.getOrNull(1)?.toIntOrNull()?:1)
    }

    private fun gen2DuplicateBoxPayload(source:ByteArray,party:Boolean):ByteArray{
        val recordSize=if(party)48 else 32;require(source.size==1+recordSize+22){"The exact Gen 2 source payload has an invalid size."};val species=source[1].toInt() and 0xFF;val listed=source[0].toInt() and 0xFF;require(species in 1..251&&(listed==species||listed==0xFD)){"The Gen 2 source payload has inconsistent species or Egg metadata."}
        return ByteArray(55).also{out->out[0]=source[0];source.copyInto(out,1,1,33);source.copyInto(out,33,1+recordSize,1+recordSize+11);source.copyInto(out,44,1+recordSize+11,1+recordSize+22)}
    }

    private fun appendGen2DuplicateBoxPayload(data:ByteArray,box:Int,payload:ByteArray):Int{
        require(box in 1..14&&payload.size==55){"The Gen 2 duplication destination is invalid."};val profile=detectGen2Profile(data)?:error("The Gen 2 save failed checksum validation.");val base=gen2BoxOffset(box);val count=data[base].toInt() and 0xFF;require(count in 0..19){"Box $box is full."};val species=payload[1].toInt() and 0xFF;val listed=payload[0].toInt() and 0xFF;require(species in 1..251&&(listed==species||listed==0xFD)){"The duplicate has inconsistent species or Egg metadata."}
        val mons=base+22;val ots=mons+20*32;val nicks=ots+20*11;data[base]=(count+1).toByte();data[base+1+count]=payload[0];data[base+1+count+1]=0xFF.toByte();payload.copyInto(data,mons+count*32,1,33);payload.copyInto(data,ots+count*11,33,44);payload.copyInto(data,nicks+count*11,44,55);require(gen2ChecksumValid(data,profile)){"Box duplication unexpectedly changed the primary checksum."};return count
    }

