            val work=fresh.copyOf();for(selected in ordered.sortedByDescending{it.slot})removeGen2ForBank(work,selected,location);val stagedProfile=detectGen2Profile(work)?:error("The staged Gen 2 source failed checksum verification.");require(gen2ChecksumValid(work,stagedProfile)){"The staged Gen 2 checksum is invalid."};require(sameGen2PayloadList(gen2LocationPayloads(work,location,stagedProfile),expected)){"A surviving Gen 2 record changed during delete staging."}
