            writeStarted=true
            file.writeBytes(work);val written=file.readBytes();require(written.contentEquals(work)){"The Gen 2 source changed while the delete batch was written."};val writtenProfile=detectGen2Profile(written)?:error("The persisted Gen 2 source failed checksum verification.");require(gen2ChecksumValid(written,writtenProfile)){"The persisted Gen 2 checksum is invalid."};require(sameGen2PayloadList(gen2LocationPayloads(written,location,writtenProfile),expected)){"A surviving Gen 2 record changed after persistence."}
            require(bound()&&writtenProfile.key==profile.key&&verifyGen2SaveIntegrity(written).first&&file.readBytes().contentEquals(work)){"The persisted Gen 2 deletion or confirmed identity did not verify."}
        }catch(e:Exception){
