        val location="Party";val before=runCatching{gen2LocationPayloads(opened,location,profile)}.getOrElse{return showDialog("Move selected to PSE Bank",(it.message?:"The Gen 2 party is invalid.")+" Nothing was changed.")};val source=parseGen2Party(opened,profile)
