        var consumed=false
        AlertDialog.Builder(this).setTitle("Move ${ordered.size} Gen 2 party Pokémon to PSE Bank?")
            .setMessage("PSE will preserve each exact Gen 2 party record in selection order, keep at least one party member, verify every Bank copy, and complete the source update atomically.")
            .setNegativeButton("Cancel",null).setPositiveButton("Move"){_,_->
                if(consumed){showDialog("Move selected to PSE Bank","This batch confirmation was already handled. Reopen the selection. Nothing was changed.");return@setPositiveButton}
                consumed=true
                depositSelectedGen2PartyToBank(ordered,opened,payloads,bankBefore,file,openedUri,openedLabel)
            }.show()
    }

    private fun depositSelectedGen2PartyToBank(chosen:List<Gen2Pokemon>,openedSource:ByteArray,expectedPayloads:List<ByteArray>,openedBankSnapshot:List<String>,openedFile:File,openedUri:Uri?,openedLabel:String?){
        fun bound()=importedFile?.absolutePath==openedFile.absolutePath&&currentSourceUri==openedUri&&currentSourceLabel==openedLabel
        if(importedFile?.absolutePath!=openedFile.absolutePath){showDialog("Move selected to PSE Bank","The working save changed while confirmation was open. Reopen the selection in the current save. Nothing was changed.");return}
        val file=openedFile;val fresh=runCatching{file.readBytes()}.getOrNull()?:return;val created=ArrayList<File>();var sourceWriteStarted=false
        var safetyBackup:File?=null
        try{
            require(bound()&&verifyGen2SaveIntegrity(fresh).first){"The captured Gen 2 batch source identity or full integrity changed."}
            require(chosen.isNotEmpty()&&chosen.size==expectedPayloads.size){"The prepared Gen 2 party selection is invalid."};require(chosen.map{it.slot}.distinct().size==chosen.size){"The prepared party selection contains a duplicate slot."};require(fresh.contentEquals(openedSource)){"The Gen 2 source changed after confirmation."}
            val profile=detectGen2Profile(fresh)?:error("The fresh Gen 2 source failed checksum validation.");require(gen2ChecksumValid(fresh,profile)){"The fresh Gen 2 checksum is invalid."};val location="Party";val before=gen2LocationPayloads(fresh,location,profile);val current=parseGen2Party(fresh,profile);require(current.size>chosen.size){"At least one Pokémon must remain in the Gen 2 party."}
            require(profile.key==detectGen2Profile(openedSource)?.key){"The confirmed Gen 2 batch source profile changed."}
            val ordered=chosen.sortedBy{it.slot}.mapIndexed{index,selected->val live=current.firstOrNull{it.slot==selected.slot};require(live!=null&&sameGen2BankRecord(live,selected)){"A selected Gen 2 Pokémon or Egg state changed after confirmation."};require(!live.isEgg){"Gen 2 Eggs cannot be flattened into the current PSE2 Bank format."};val payload=buildGen2BankPayload(fresh,live,location);require(payload.contentEquals(expectedPayloads[index])){"An exact selected Gen 2 party record changed after confirmation."};live}
            require(gen2BankSnapshot()==openedBankSnapshot){"The Gen 2 Bank changed after confirmation."};val bankCount=gen2BankEntryCountForDeposit();require(bankCount<=GEN1_BANK_CAPACITY-ordered.size){"The Gen 2 PSE Bank no longer has room for the complete selection."}
            require(bound()&&file.readBytes().contentEquals(fresh)){"The confirmed source changed before batch Bank reservation."}
            val backup=File.createTempFile(backupGameName(file)+"_PreGen2PartyBankDeposit_",".backup",backupsDir());safetyBackup=backup
            backup.writeBytes(fresh);require(backup.readBytes().contentEquals(fresh)){"The batch deposit recovery backup did not persist exactly."}
            retainGen2SafetyBackup(backup,fresh)
            require(bound()&&backup.readBytes().contentEquals(fresh)&&isBackupKept(backup)){"The source identity or kept backup changed before batch Bank reservation."}
            for(i in ordered.indices){val selected=ordered[i];val payload=expectedPayloads[i];val bankFile=File(bankDir(),"${System.currentTimeMillis()}_${System.nanoTime()}_${selected.species}.pse2");require(bankFile.createNewFile()){"PSE could not reserve a unique Gen 2 Bank record."};created.add(bankFile);bankFile.writeBytes(payload);val stored=bankFile.readBytes();require(stored.contentEquals(payload)&&parseGen2BankPayload(stored)?.let{sameGen2BankRecord(it,selected)}==true){"A staged Gen 2 Bank record did not preserve every supported field."}}
            require(gen2BankSnapshot()==(openedBankSnapshot+created.map{it.canonicalPath}).sorted()){"The Gen 2 Bank inventory changed during party staging."}
            val removedSlots=ordered.map{it.slot}.toSet();val expected=before.filterIndexed{index,_->!removedSlots.contains(index)};val work=fresh.copyOf();for(selected in ordered.sortedByDescending{it.slot})removeGen2ForBank(work,selected,location);val stagedProfile=detectGen2Profile(work)?:error("The staged Gen 2 source failed checksum verification.");require(gen2ChecksumValid(work,stagedProfile)){"The staged Gen 2 checksum is invalid."};require(sameGen2PayloadList(gen2LocationPayloads(work,location,stagedProfile),expected)){"A surviving Gen 2 party record changed during batch staging."}
            require(verifyGen2SaveIntegrity(work).first&&stagedProfile.key==profile.key){"The complete staged Gen 2 batch source failed integrity or profile validation."}
            require(gen2BankSnapshot()==(openedBankSnapshot+created.map{it.canonicalPath}).sorted()&&created.indices.all{created[it].readBytes().contentEquals(expectedPayloads[it])}){"The staged Gen 2 Bank records or inventory changed before source writing."}
            require(importedFile?.absolutePath==file.absolutePath&&file.readBytes().contentEquals(fresh)){"The active Gen 2 save changed during party Bank staging. Nothing was written to the save."}
            require(bound()&&backup.readBytes().contentEquals(fresh)&&isBackupKept(backup)){"The source identity or kept backup changed before depositing the batch."}
            sourceWriteStarted=true
            file.writeBytes(work);val written=file.readBytes();require(written.contentEquals(work)){"The Gen 2 source changed while the party batch was written."};val writtenProfile=detectGen2Profile(written)?:error("The persisted Gen 2 source failed checksum verification.");require(gen2ChecksumValid(written,writtenProfile)){"The persisted Gen 2 checksum is invalid."};require(sameGen2PayloadList(gen2LocationPayloads(written,location,writtenProfile),expected)){"A surviving Gen 2 party record changed after persistence."}
            require(bound()&&writtenProfile.key==profile.key&&verifyGen2SaveIntegrity(written).first){"The persisted Gen 2 batch source or identity did not verify."}
            for(i in created.indices){val committed=created[i].readBytes();require(committed.contentEquals(expectedPayloads[i])&&parseGen2BankPayload(committed)?.let{sameGen2BankRecord(it,ordered[i])}==true){"A committed Gen 2 Bank record changed after source persistence."}}
            require(bound()&&file.readBytes().contentEquals(work)){"The verified Gen 2 source changed before batch deposit completion."}
        }catch(e:Exception){
            val sourceRestored=!sourceWriteStarted||(runCatching{file.writeBytes(fresh)}.isSuccess&&runCatching{file.readBytes().contentEquals(fresh)}.getOrDefault(false))
            val bankCleared=if(!sourceRestored)false else{
                var cleared=true
                for((index,bankFile)in created.withIndex()){
                    val removed=runCatching{
                        if(bankFile.exists()){require(bankFile.readBytes().contentEquals(expectedPayloads[index])){"A reserved Bank record changed; it was not removed."};require(bankFile.delete()){"A reserved Bank record could not be removed."}}
                        require(!bankFile.exists()){"A reserved Bank record still exists."}
                    }.isSuccess
                    if(!removed)cleared=false
                }
                cleared
            }
            val recovery=if(!sourceWriteStarted&&bankCleared)"Nothing was written to the save and no staged Bank record was kept." else  if(sourceRestored&&bankCleared)"The exact fresh Gen 2 source was restored and every staged Bank file was removed." else  "Automatic recovery could not be verified. Stop editing this save and keep any remaining Bank records until a verified backup and Bank contents have been reviewed."
            showDialog("Move selected to PSE Bank failed",(e.message?:"Unknown error")+"\n\n$recovery"+(safetyBackup?.let{"\n\nRecovery backup: "+it.name}?:""));return
        }
        gen2PartyMultiSelectMode=false;selectedGen2PartySlots.clear();Toast.makeText(this,"${chosen.size} Gen 2 party Pokémon moved to PSE Bank and verified",Toast.LENGTH_LONG).show();showBank()
    }

    private fun confirmSelectedGen2BoxToBank(box:Int,chosen:List<Gen2Pokemon>){
        val openedUri=currentSourceUri;val openedLabel=currentSourceLabel
        val file=importedFile?:return
        if(chosen.isEmpty()){showDialog("Move selected to PSE Bank","Select one or more Gen 2 Pokémon first.");return}
        if(chosen.map{it.slot}.distinct().size!=chosen.size){showDialog("Move selected to PSE Bank","The selection contains the same Gen 2 box slot more than once. Nothing was changed.");return}
        val opened=runCatching{file.readBytes()}.getOrNull()?:return showDialog("Move selected to PSE Bank","The Gen 2 source could not be read.")
        val profile=detectGen2Profile(opened)?:return showDialog("Move selected to PSE Bank","The Gen 2 source failed checksum validation. Nothing was changed.")
        val location="Box $box";val before=runCatching{gen2LocationPayloads(opened,location,profile)}.getOrElse{return showDialog("Move selected to PSE Bank",(it.message?:"The Gen 2 box is invalid.")+" Nothing was changed.")};val source=parseGen2Box(opened,box)
        val ordered=try{chosen.sortedBy{it.slot}.map{selected->
            val live=source.firstOrNull{it.slot==selected.slot}?:error("A selected Gen 2 box slot no longer exists.")
            require(sameGen2BankRecord(live,selected)){"A selected Gen 2 Pokémon or Egg state changed."}
            require(!live.isEgg){"Gen 2 Eggs cannot be flattened into the current PSE2 Bank format."}
            live
        }}catch(e:Exception){showDialog("Move selected to PSE Bank",(e.message?:"The selected Gen 2 records could not be validated.")+" Nothing was changed.");return}
        val bankCount=runCatching{gen2BankEntryCountForDeposit()}.getOrElse{showDialog("Move selected to PSE Bank",it.message?:"The Gen 2 Bank inventory is invalid.");return};val bankBefore=gen2BankSnapshot();if(bankCount>GEN1_BANK_CAPACITY-ordered.size){showDialog("Move selected to PSE Bank","The Gen 2 PSE Bank has room for ${GEN1_BANK_CAPACITY-bankCount} more Pokémon, but ${ordered.size} were selected. Nothing was changed.");return}
        val payloads=try{ordered.map{buildGen2BankPayload(opened,it,location)}}catch(e:Exception){showDialog("Move selected to PSE Bank",(e.message?:"The exact Bank payloads could not be prepared.")+" Nothing was changed.");return}
        var consumed=false
        AlertDialog.Builder(this).setTitle("Move ${ordered.size} Gen 2 Pokémon to PSE Bank?")
            .setMessage("PSE will preserve each exact Gen 2 record in selection order, verify every Bank copy, then remove the selected box slots in one transaction. Source changes are rejected. A kept recovery backup is required; incomplete recovery is reported without discarding unverified Bank copies.")
            .setNegativeButton("Cancel",null).setPositiveButton("Move"){_,_->
                if(consumed){showDialog("Move selected to PSE Bank","This batch confirmation was already handled. Reopen the selection. Nothing was changed.");return@setPositiveButton}
                consumed=true
                depositSelectedGen2BoxToBank(box,ordered,opened,payloads,bankBefore,file,openedUri,openedLabel)
            }.show()
    }

