    private fun buildGen2BankPayload(data:ByteArray, mon:Gen2Pokemon, location:String):ByteArray {
        require(!mon.isEgg){"The current PSE2 Bank format cannot preserve Gen 2 egg state."}
        require(sameGen2SelectionState(data,location,mon)){"The selected Pokémon or Egg state changed before Bank serialization."}
        val (record, ot, nick) = gen2RecordOffsets(data, location, mon.slot)
        val out = ByteArray(GEN2_BANK_FILE_SIZE)
        out[0]='P'.code.toByte(); out[1]='S'.code.toByte(); out[2]='E'.code.toByte(); out[3]='2'.code.toByte()
        out[4]=1
        val profile=detectGen2Profile(data)
        out[5]=when(profile?.key){"C"->2; else->1}.toByte()
        out[6]=if(location.startsWith("Party"))1 else 0
        // v0.43.38+: preserve the exact Gen 2 source title when the filename lets PSE
        // distinguish Gold from Silver. Byte 7 was unused in the original PSE2 header,
        // so older Bank entries remain fully compatible (0 = unknown/legacy).
        val sourceGame=profile?.let{detectGen2GameFromPath(currentSourceLabel ?: importedFile?.name ?: "",it)} ?: ""
        out[7]=when {
            sourceGame.contains("Crystal",true) -> 41
            sourceGame.contains("Silver",true) && !sourceGame.contains("Gold",true) -> 40
            sourceGame.contains("Gold",true) && !sourceGame.contains("Silver",true) -> 39
            else -> 0
        }.toByte()
        data.copyOfRange(record,record+32).copyInto(out,GEN2_BANK_HEADER_SIZE)
        data.copyOfRange(ot,ot+11).copyInto(out,GEN2_BANK_HEADER_SIZE+32)
        data.copyOfRange(nick,nick+11).copyInto(out,GEN2_BANK_HEADER_SIZE+43)
        return out
    }

    private fun parseGen2BankPayload(raw:ByteArray):Gen2Pokemon? {
        if(raw.size!=GEN2_BANK_FILE_SIZE || raw[0]!='P'.code.toByte() || raw[1]!='S'.code.toByte() || raw[2]!='E'.code.toByte() || raw[3]!='2'.code.toByte()) return null
        if((raw[4].toInt() and 0xFF)!=1)return null
        val sourceProfile=raw[5].toInt() and 0xFF
        if(sourceProfile !in 1..2)return null
        if((raw[6].toInt() and 0xFF) !in 0..1)return null
        val sourceGame=raw[7].toInt() and 0xFF
        if(sourceGame !in setOf(0,39,40,41))return null
        if(sourceGame in 39..40 && sourceProfile!=1)return null
        if(sourceGame==41 && sourceProfile!=2)return null
        val o=GEN2_BANK_HEADER_SIZE
        val sp=raw[o].toInt() and 0xFF
        if(sp !in 1..251) return null
        val level=raw[o+31].toInt() and 0xFF
        if(level !in 1..100) return null
        val moves=IntArray(4){raw[o+2+it].toInt() and 0xFF}
        if(moves.any{it !in 0..251}) return null
        val movePp=IntArray(4){raw[o+23+it].toInt() and 0x3F}
        if(moves.indices.any{moves[it]==0 && (raw[o+23+it].toInt() and 0xFF)!=0}) return null
        val dv=gen2Dvs(raw,o+21)
        return Gen2Pokemon(
            0, sp,
            readGen1Text(raw,o+43,11), readGen1Text(raw,o+32,11),
            level, raw[o+1].toInt() and 0xFF,
            readU16BE(raw,o+6), readU24BE(raw,o+8),
            moves,
            movePp,
            IntArray(5){readU16BE(raw,o+11+it*2)},
            raw[o+27].toInt() and 0xFF, raw[o+28].toInt() and 0xFF,
            readU16BE(raw,o+29), dv, gen2Shiny(dv), false
        )
    }

    private fun removeGen2ForBank(data:ByteArray, mon:Gen2Pokemon, location:String) {
        val profile=detectGen2Profile(data) ?: error("The working Gen 2 save did not pass its primary checksum.")
        if(location.startsWith("Party")) {
            val base=profile.partyOffset; val count=data[base].toInt() and 0xFF
            require(count in 2..6 && mon.slot in 0 until count){"Cannot bank the final party Pokémon or the party changed."}
            val mons=base+8; val ots=mons+6*48; val nicks=ots+6*11
            require(sameGen2SelectionState(data,location,mon)){"The selected Pokémon or Egg state changed before banking."}
            for(i in mon.slot until count-1){
                data[base+1+i]=data[base+1+i+1]
                System.arraycopy(data,mons+(i+1)*48,data,mons+i*48,48)
                System.arraycopy(data,ots+(i+1)*11,data,ots+i*11,11)
                System.arraycopy(data,nicks+(i+1)*11,data,nicks+i*11,11)
            }
            val n=count-1
            data[base]=n.toByte(); data[base+1+n]=0xFF.toByte()
            java.util.Arrays.fill(data,mons+n*48,mons+(n+1)*48,0.toByte())
            java.util.Arrays.fill(data,ots+n*11,ots+(n+1)*11,0x50.toByte())
            java.util.Arrays.fill(data,nicks+n*11,nicks+(n+1)*11,0x50.toByte())
            updateGen2PrimaryChecksum(data,profile)
        } else {
            val box=Regex("Box (\\d+)").find(location)?.groupValues?.getOrNull(1)?.toIntOrNull() ?: error("Box number was unavailable.")
            val base=gen2BoxOffset(box); val count=data[base].toInt() and 0xFF
            require(count in 1..20 && mon.slot in 0 until count){"Box structure changed before banking."}
            val mons=base+22; val ots=mons+20*32; val nicks=ots+20*11
            require(sameGen2SelectionState(data,location,mon)){"The selected Pokémon or Egg state changed before banking."}
            for(i in mon.slot until count-1){
                data[base+1+i]=data[base+1+i+1]
                System.arraycopy(data,mons+(i+1)*32,data,mons+i*32,32)
                System.arraycopy(data,ots+(i+1)*11,data,ots+i*11,11)
                System.arraycopy(data,nicks+(i+1)*11,data,nicks+i*11,11)
            }
            val n=count-1
            data[base]=n.toByte(); data[base+1+n]=0xFF.toByte()
            java.util.Arrays.fill(data,mons+n*32,mons+(n+1)*32,0.toByte())
            java.util.Arrays.fill(data,ots+n*11,ots+(n+1)*11,0x50.toByte())
            java.util.Arrays.fill(data,nicks+n*11,nicks+(n+1)*11,0x50.toByte())
            require(gen2ChecksumValid(data,profile)){"Box banking unexpectedly changed the primary checksum."}
        }
    }

    private fun appendGen2BoxPokemon(data:ByteArray, box:Int, monRaw:ByteArray, otRaw:ByteArray, nickRaw:ByteArray):Int {
        require(box in 1..14 && monRaw.size==32 && otRaw.size==11 && nickRaw.size==11)
        val base=gen2BoxOffset(box); val count=data[base].toInt() and 0xFF
        require(count in 0..19){"Box $box is full."}
        val mons=base+22; val ots=mons+20*32; val nicks=ots+20*11
        data[base]=(count+1).toByte(); data[base+1+count]=monRaw[0]; data[base+1+count+1]=0xFF.toByte()
        monRaw.copyInto(data,mons+count*32); otRaw.copyInto(data,ots+count*11); nickRaw.copyInto(data,nicks+count*11)
        return count
    }

    private fun gen2LocationPayloads(data:ByteArray,location:String,profile:Gen2Profile):List<ByteArray>{
        val party=location.startsWith("Party");val base:Int;val capacity:Int;val recordSize:Int;val mons:Int;val ots:Int;val nicks:Int
        if(party){base=profile.partyOffset;capacity=6;recordSize=48;mons=base+8;ots=mons+capacity*recordSize;nicks=ots+capacity*11}
        else{val box=Regex("Box (\\d+)").find(location)?.groupValues?.getOrNull(1)?.toIntOrNull()?:error("Box number was unavailable.");require(box in 1..14){"Invalid Gen 2 box."};base=gen2BoxOffset(box);capacity=20;recordSize=32;mons=base+22;ots=mons+capacity*recordSize;nicks=ots+capacity*11}
        val count=data.getOrNull(base)?.toInt()?.and(0xFF)?:error("The Gen 2 location is outside the save.");require(count in 0..capacity){"The Gen 2 location count is invalid."};require((data.getOrNull(base+1+count)?.toInt()?.and(0xFF))==0xFF){"The Gen 2 location species list has no terminator."}
        val parsed=if(party)parseGen2Party(data,profile)else parseGen2Box(data,Regex("Box (\\d+)").find(location)!!.groupValues[1].toInt());require(parsed.size==count){"The Gen 2 location contains an invalid record."}
        return List(count){slot->
            val listed=data[base+1+slot].toInt() and 0xFF;val species=data[mons+slot*recordSize].toInt() and 0xFF;require(species in 1..251&&(listed==species||listed==0xFD)){"Gen 2 slot ${slot+1} has inconsistent species or Egg metadata."}
            ByteArray(1+recordSize+22).also{out->out[0]=data[base+1+slot];data.copyOfRange(mons+slot*recordSize,mons+(slot+1)*recordSize).copyInto(out,1);data.copyOfRange(ots+slot*11,ots+(slot+1)*11).copyInto(out,1+recordSize);data.copyOfRange(nicks+slot*11,nicks+(slot+1)*11).copyInto(out,1+recordSize+11)}
        }
    }

    private fun sameGen2PayloadList(a:List<ByteArray>,b:List<ByteArray>):Boolean=a.size==b.size&&a.indices.all{a[it].contentEquals(b[it])}
    private data class Gen2BankInventory(
        val validEntries:List<Pair<File,Gen2Pokemon>>,
        val invalidFiles:List<File>
    )

    private fun gen2BankInventory():Gen2BankInventory{
        val valid=ArrayList<Pair<File,Gen2Pokemon>>()
        val invalid=ArrayList<File>()
        val files=bankDir().listFiles()?.filter{it.isFile&&it.extension.equals("pse2",true)}?.sortedBy{it.name}?:emptyList()
        for(file in files){
            val parsed=runCatching{parseGen2BankPayload(file.readBytes())}.getOrNull()
            if(parsed==null)invalid.add(file)else valid.add(file to parsed)
        }
        return Gen2BankInventory(valid,invalid)
    }

    private fun gen2BankEntryCountForDeposit():Int{
        val inventory=gen2BankInventory()
        require(inventory.invalidFiles.isEmpty()){"PSE Bank contains an unreadable or invalid Gen 2 record. It was preserved unchanged; quarantine it before depositing another Pokémon."}
        return inventory.validEntries.size
    }

    private fun gen2BankQuarantineDir():File=File(filesDir,"pse_bank_quarantine").apply{mkdirs()}

    private fun gen2BankQuarantineTarget(source:File):File{
        val dir=gen2BankQuarantineDir();val stem=source.nameWithoutExtension.ifBlank{"gen2_record"};var target=File(dir,source.name);var suffix=1
        while(target.exists()){target=File(dir,"${stem}_$suffix.pse2");suffix++}
        return target
    }

    private fun confirmGen2BankQuarantine(files:List<File>){
        val opened=runCatching{
            require(bankViewGeneration==2&&files.isNotEmpty()){"Reopen the Gen 2 Bank before quarantining records."}
            val snapshot=files.sortedBy{it.name}.map{source->
                require(gen2BankRecoveryPathMatches(source,bankDir())&&source.isFile){"An invalid record changed location. Reopen PSE Bank."}
                val bytes=source.readBytes();require(parseGen2BankPayload(bytes)==null){"A record became valid. Reopen PSE Bank."}
                source to bytes
            }
            require(snapshot.map{it.first.canonicalPath}.distinct().size==snapshot.size){"Duplicate invalid record selection."}
            require(gen2BankInventory().invalidFiles.sortedBy{it.name}.map{it.canonicalPath}==snapshot.map{it.first.canonicalPath}){"The invalid Gen 2 Bank inventory changed. Reopen PSE Bank."}
            snapshot
        }.getOrElse{showDialog("Gen 2 Bank quarantine",it.message?:"The invalid records could not be opened safely.");return}
        var consumed=false
        AlertDialog.Builder(this).setTitle("Quarantine invalid records?").setMessage("PSE will exclusively reserve and verify exact copies of these ${opened.size} malformed records in quarantine before removing any active Bank originals. If the batch changes, it will stop. Recovery never overwrites existing records; partial or unverified copies are retained for review.").setNegativeButton("Cancel"){_,_->consumed=true}.setOnCancelListener{consumed=true}.setPositiveButton("Quarantine"){_,_->
            if(consumed){return@setPositiveButton};consumed=true
            quarantineInvalidGen2BankRecords(opened)
        }.show()
    }

    private fun quarantineInvalidGen2BankRecords(opened:List<Pair<File,ByteArray>>){
        val copies=ArrayList<Triple<File,File,ByteArray>>();val deleteAttempted=HashSet<String>()
        val failure=runCatching{
            require(bankViewGeneration==2&&opened.isNotEmpty()){"Reopen the Gen 2 Bank before quarantining records."}
            require(opened.map{it.first.canonicalPath}.distinct().size==opened.size){"Duplicate invalid record selection."}
            val fresh=gen2BankInventory().invalidFiles.sortedBy{it.name}
            require(fresh.map{it.canonicalPath}==opened.map{it.first.canonicalPath}){"The invalid Gen 2 Bank inventory changed. Reopen PSE Bank and try again."}
            for((source,bytes) in opened){
                require(gen2BankRecoveryPathMatches(source,bankDir())&&source.isFile&&source.readBytes().contentEquals(bytes)&&parseGen2BankPayload(bytes)==null){"An invalid record changed after confirmation. No changed record will be quarantined."}
            }
            // Verify the entire batch of exclusive copies before removing any originals.
            for((source,bytes) in opened){
                require(gen2BankRecoveryPathMatches(source,bankDir())&&source.isFile&&source.readBytes().contentEquals(bytes)){"${source.name} changed before quarantine."}
                val target=gen2BankQuarantineTarget(source)
                require(gen2BankRecoveryPathMatches(target,gen2BankQuarantineDir())){"The quarantine destination changed location."}
                require(target.createNewFile()){"The quarantine destination already exists. Reopen PSE Bank."}
                copies.add(Triple(source,target,bytes));target.writeBytes(bytes)
                require(gen2BankRecoveryPathMatches(target,gen2BankQuarantineDir())&&target.isFile&&target.readBytes().contentEquals(bytes)){"${source.name} did not verify byte-for-byte in quarantine."}
            }
            for((source,target,bytes) in copies){
                require(gen2BankRecoveryPathMatches(source,bankDir())&&source.isFile&&source.readBytes().contentEquals(bytes)){"${source.name} changed before original cleanup."}
                require(gen2BankRecoveryPathMatches(target,gen2BankQuarantineDir())&&target.isFile&&target.readBytes().contentEquals(bytes)){"The quarantine copy changed before original cleanup."}
                deleteAttempted.add(source.name)
                require(source.delete()){"PSE could not remove the verified Bank original."}
                require(!source.exists()){"The Bank original still exists after cleanup."}
            }
            for((source,target,bytes) in copies){
                require(gen2BankRecoveryPathMatches(source,bankDir())&&!source.exists()){"A Bank original reappeared during quarantine."}
                require(gen2BankRecoveryPathMatches(target,gen2BankQuarantineDir())&&target.isFile&&target.readBytes().contentEquals(bytes)){"A quarantine copy failed final verification."}
            }
            require(gen2BankInventory().invalidFiles.isEmpty()){"Another invalid Gen 2 Bank record appeared during quarantine."}
        }.exceptionOrNull()
        if(failure!=null){
            // Restore and verify ALL originals before considering removal of any owned copy.
            var sourcesVerified=opened.isNotEmpty()
            for((source,bytes) in opened){
                val verified=runCatching{
                    require(gen2BankRecoveryPathMatches(source,bankDir()))
                    if(source.name in deleteAttempted&&!source.exists()){
                        require(source.createNewFile());source.writeBytes(bytes)
                    }
                    require(source.isFile&&source.readBytes().contentEquals(bytes))
                }.isSuccess
                if(!verified)sourcesVerified=false
            }
            var copiesRemoved=copies.isEmpty()
            if(sourcesVerified){
                copiesRemoved=true
                for((source,target,bytes) in copies.asReversed()){
                    val removed=runCatching{
                        require(gen2BankRecoveryPathMatches(source,bankDir())&&source.isFile&&source.readBytes().contentEquals(bytes))
                        require(gen2BankRecoveryPathMatches(target,gen2BankQuarantineDir()))
                        if(target.exists()){
                            require(target.isFile&&target.readBytes().contentEquals(bytes))
                            require(target.delete())
                        }
                        require(!target.exists())
                    }.isSuccess
                    if(!removed)copiesRemoved=false
                }
            }
            val suffix=if(sourcesVerified&&copiesRemoved)" All original records and removal of owned quarantine copies were verified byte-for-byte." else " Recovery could not be fully verified. Existing or changed records were not overwritten; partial or unverified quarantine copies were retained for review, and invalid Bank records may still block deposits."
            showDialog("Gen 2 Bank quarantine",(failure.message?:"The invalid records could not be quarantined.")+suffix);return
        }
        selectedBankFiles.clear();Toast.makeText(this,"Quarantined ${copies.size} invalid Gen 2 Bank record${if(copies.size==1)"" else "s"}",Toast.LENGTH_LONG).show();showBank()
    }

    private fun gen2BankQuarantinedFiles():List<File> = gen2BankQuarantineDir().listFiles()?.filter{it.isFile&&it.extension.equals("pse2",true)}?.sortedBy{it.name}?:emptyList()

    private fun gen2BankRestoreTarget(source:File):File{
        val dir=bankDir();val stem=source.nameWithoutExtension.ifBlank{"gen2_record"};var target=File(dir,source.name);var suffix=1
        while(target.exists()){target=File(dir,"${stem}_restored_$suffix.pse2");suffix++}
        return target
    }

    private fun gen2BankRecoveryPathMatches(file:File,root:File):Boolean=runCatching{
        file.extension.equals("pse2",true)&&file.parentFile?.canonicalFile==root.canonicalFile&&file.canonicalFile==File(root.canonicalFile,file.name)
    }.getOrDefault(false)

    private fun restoreGen2BankQuarantineRecord(source:File,openedRaw:ByteArray){
        var target:File?=null;var targetReserved=false;var sourceDeleteAttempted=false
        val failure=runCatching{
            require(gen2BankRecoveryPathMatches(source,gen2BankQuarantineDir())){"The selected record is outside PSE\'s Gen 2 quarantine or is an alias."}
            require(source.isFile){"The selected quarantined record no longer exists."};val current=source.readBytes();require(current.contentEquals(openedRaw)){"The quarantined record changed. Reopen the recovery list and try again."}
            val destination=gen2BankRestoreTarget(source)
            require(gen2BankRecoveryPathMatches(destination,bankDir())){"The restore destination is outside the active Gen 2 Bank or is an alias."}
            target=destination
            require(destination.createNewFile()){"The restore destination was claimed by another record. No existing Bank record was overwritten."};targetReserved=true
            destination.writeBytes(current)
            require(destination.isFile&&destination.readBytes().contentEquals(current)){"The restored Bank copy did not verify byte-for-byte."}
            require(gen2BankRecoveryPathMatches(source,gen2BankQuarantineDir())&&source.isFile&&source.readBytes().contentEquals(openedRaw)){"The quarantined record changed before cleanup."}
            sourceDeleteAttempted=true
            require(source.delete()){"The verified Bank copy was written, but the original quarantine record could not be removed."}
            require(!source.exists()){"The original quarantine path still exists after removal."}
            require(gen2BankRecoveryPathMatches(destination,bankDir())&&destination.isFile&&destination.readBytes().contentEquals(openedRaw)){"The restored Bank copy changed after cleanup."}
        }.exceptionOrNull()
        if(failure!=null){
            val sourceVerified=runCatching{
                require(gen2BankRecoveryPathMatches(source,gen2BankQuarantineDir())){"The original quarantine path is no longer safe for recovery."}
                if(sourceDeleteAttempted&&!source.exists()){
                    require(source.createNewFile()){"The original quarantine path could not be reserved for recovery."}
                    source.writeBytes(openedRaw)
                }
                require(source.isFile&&source.readBytes().contentEquals(openedRaw)){"The original quarantine record could not be verified; no existing source was overwritten."}
            }.isSuccess
            val targetRemoved=if(!targetReserved)true else if(!sourceVerified)false else runCatching{
                val owned=target?:error("The reserved restore path is unavailable.")
                require(gen2BankRecoveryPathMatches(owned,bankDir())){"The reserved Bank path is no longer safe for cleanup."}
                if(owned.exists()){
                    require(owned.isFile&&owned.readBytes().contentEquals(openedRaw)){"An existing restore path changed; it was not removed."}
                    require(owned.delete()){"The verified restore copy could not be cleaned up."}
                }
                require(!owned.exists()){"The reserved restore path still exists."}
            }.isSuccess
            val suffix=if(sourceVerified&&targetRemoved)" The original quarantined record was kept or restored byte-for-byte and rollback was verified." else  " Recovery could not be fully verified. Stop and review the remaining quarantine and Bank copies; partial Bank copies may block deposits. No existing source or changed Bank record was overwritten or removed."
            showDialog("Gen 2 Bank recovery",(failure.message?:"The quarantined record could not be restored.")+suffix);return
        }
        selectedBankFiles.clear();Toast.makeText(this,"Restored ${target?.name?:source.name} to the active Gen 2 Bank and verified",Toast.LENGTH_LONG).show();showBank()
    }

    private fun showGen2BankQuarantineRecovery(){
        val files=gen2BankQuarantinedFiles();if(files.isEmpty()){showDialog("Gen 2 Bank recovery","There are no quarantined Gen 2 Bank records.");return}
        var choiceConsumed=false
        AlertDialog.Builder(this).setTitle("Quarantined Gen 2 records (${files.size})").setItems(files.map{it.name}.toTypedArray()){_,which->
            if(choiceConsumed){showDialog("Gen 2 Bank recovery","This recovery selection was already used. Reopen the recovery list.");return@setItems};choiceConsumed=true
            val source=files[which];val opened=runCatching{source.readBytes()}.getOrElse{showDialog("Gen 2 Bank recovery","${source.name} could not be read. It was left unchanged.");return@setItems}
            var restoreConsumed=false
            AlertDialog.Builder(this).setTitle("Restore ${source.name}?").setMessage("PSE will exclusively reserve a new active Gen 2 Bank path and verify this exact file before removing its quarantine original. Existing Bank records are never overwritten. If it is still malformed, it will be reported again and safe deposits will remain blocked until it is quarantined again.").setNegativeButton("Cancel"){_,_->restoreConsumed=true}.setOnCancelListener{restoreConsumed=true}.setPositiveButton("Restore"){_,_->
                if(restoreConsumed){showDialog("Gen 2 Bank recovery","This restore confirmation was already used. Reopen the recovery list.");return@setPositiveButton};restoreConsumed=true
                restoreGen2BankQuarantineRecord(source,opened)
            }.show()
        }.setNegativeButton("Close"){_,_->choiceConsumed=true}.setOnCancelListener{choiceConsumed=true}.show()
    }

    private fun gen2BankSnapshot():List<String> = (bankDir().listFiles()?.filter{it.isFile&&it.extension.equals("pse2",true)}?.map{it.canonicalPath}?.sorted()?:emptyList())
    private fun gen2PokedexBases(profile:Gen2Profile):Pair<Int,Int> = if(profile.key=="C")0x2A27 to 0x2A47 else 0x2A4C to 0x2A6C
    private fun markGen2PokedexOwnedSeen(data:ByteArray,profile:Gen2Profile,species:Int){require(species in 1..251);val(owned,seen)=gen2PokedexBases(profile);val bit=species-1;val mask=1 shl(bit and 7);data[owned+bit/8]=(data[owned+bit/8].toInt() or mask).toByte();data[seen+bit/8]=(data[seen+bit/8].toInt() or mask).toByte()}
    private fun gen2PokedexOwnedSeen(data:ByteArray,profile:Gen2Profile,species:Int):Boolean{if(species !in 1..251)return false;val(owned,seen)=gen2PokedexBases(profile);val bit=species-1;val mask=1 shl(bit and 7);return (data[owned+bit/8].toInt() and mask)!=0&&(data[seen+bit/8].toInt() and mask)!=0}

    private fun confirmGen2DepositToBank(mon:Gen2Pokemon, location:String) {
        if(mon.isEgg){showDialog("Move Gen 2 Egg to PSE Bank","The current PSE2 Bank record cannot preserve Gen 2 egg state. Transfer was rejected and both the save and Bank were left unchanged.");return}
        val openedSource=currentSourceUri;val openedLabel=currentSourceLabel
        val file=importedFile?:return;val opened=runCatching{file.readBytes()}.getOrNull()?:return;val profile=detectGen2Profile(opened)?:return showDialog("Move to PSE Bank","The Gen 2 save is invalid. Nothing was changed.")
        val records=runCatching{gen2LocationPayloads(opened,location,profile)}.getOrElse{return showDialog("Move to PSE Bank",(it.message?:"The Gen 2 source is invalid.")+" Nothing was changed.")};if(mon.slot !in records.indices)return showDialog("Move to PSE Bank","The selected Gen 2 slot no longer exists.")
        val selected=if(location.startsWith("Party"))parseGen2Party(opened,profile).firstOrNull{it.slot==mon.slot}else{val box=Regex("Box (\\d+)").find(location)?.groupValues?.getOrNull(1)?.toIntOrNull()?:return;parseGen2Box(opened,box).firstOrNull{it.slot==mon.slot}}
        if(selected==null||!sameGen2BankRecord(selected,mon))return showDialog("Move to PSE Bank","The selected Gen 2 Pokémon or Egg state changed. Reopen it and try again.")
        val payload=runCatching{buildGen2BankPayload(opened,selected,location)}.getOrElse{return showDialog("Move to PSE Bank",it.message?:"The exact Gen 2 Bank payload could not be prepared.")}
        var consumed=false
        AlertDialog.Builder(this).setTitle("Move to PSE Bank?")
            .setMessage("PSE will preserve the exact Gen 2 Pokémon record, verify the Bank copy, then remove this Pokémon from $location in the working save. If any byte changes after this confirmation or any step fails, both sides remain unchanged.")
            .setNegativeButton("Cancel",null)
            .setPositiveButton("Move"){_,_->
                if(consumed){showDialog("Move to PSE Bank","This confirmation was already handled. Reopen the selection. Nothing was changed.");return@setPositiveButton}
                consumed=true
                depositGen2ToBank(selected,location,opened,payload,file,openedSource,openedLabel)
            }.show()
    }

    private fun depositGen2ToBank(mon:Gen2Pokemon,location:String,openedDestination:ByteArray,expectedPayload:ByteArray,openedFile:File,openedSource:Uri?,openedLabel:String?) {
        fun bound()=importedFile?.absolutePath==openedFile.absolutePath&&currentSourceUri==openedSource&&currentSourceLabel==openedLabel
        if(mon.isEgg){showDialog("Move Gen 2 Egg to PSE Bank","The current PSE2 Bank record cannot preserve Gen 2 egg state. Nothing was changed.");return}
        if(importedFile?.absolutePath!=openedFile.absolutePath){showDialog("Move to PSE Bank","The active save changed after confirmation. Reopen the selection before banking. Nothing was changed.");return}
        val file=openedFile;val fresh=runCatching{file.readBytes()}.getOrNull()?:return;var bankFile:File?=null;var bankReserved=false;var sourceWriteStarted=false
        var safetyBackup:File?=null
        try{
            require(bound()&&verifyGen2SaveIntegrity(fresh).first){"The captured Gen 2 source identity or full integrity changed."}
            require(fresh.contentEquals(openedDestination)){"The Gen 2 save changed after confirmation."}
            val profile=detectGen2Profile(fresh)?:error("The fresh Gen 2 save did not pass its primary checksum.");require(gen2ChecksumValid(fresh,profile)){"The fresh Gen 2 checksum is invalid."}
            require(profile.key==detectGen2Profile(openedDestination)?.key){"The confirmed Gen 2 source profile changed."}
            val before=gen2LocationPayloads(fresh,location,profile);require(mon.slot in before.indices){"The selected Gen 2 slot no longer exists."};val selected=if(location.startsWith("Party"))parseGen2Party(fresh,profile).firstOrNull{it.slot==mon.slot}else{val box=Regex("Box (\\d+)").find(location)?.groupValues?.getOrNull(1)?.toIntOrNull()?:error("Box number was unavailable.");parseGen2Box(fresh,box).firstOrNull{it.slot==mon.slot}}
            require(selected!=null&&sameGen2BankRecord(selected,mon)){"The selected Gen 2 Pokémon or Egg state changed before banking."};require(!selected.isEgg){"Gen 2 Eggs cannot be flattened into the current PSE2 Bank format."};if(location.startsWith("Party"))require(before.size>1){"Cannot bank the final party Pokémon."}
            val bankCount=gen2BankEntryCountForDeposit();val bankBefore=gen2BankSnapshot();require(bankCount<GEN1_BANK_CAPACITY){"The Gen 2 PSE Bank already contains $bankCount Pokémon; its ten boxes hold ${GEN1_BANK_CAPACITY}."};val payload=buildGen2BankPayload(fresh,selected,location);require(payload.contentEquals(expectedPayload)){"The exact Gen 2 source record changed after confirmation."}
            require(bound()&&file.readBytes().contentEquals(fresh)){"The confirmed source changed before Bank reservation."}
            val backup=File.createTempFile(backupGameName(file)+"_PreGen2BankDeposit_",".backup",backupsDir());safetyBackup=backup
            backup.writeBytes(fresh);require(backup.readBytes().contentEquals(fresh)){"The deposit recovery backup did not persist exactly."}
            retainGen2SafetyBackup(backup,fresh)
            require(bound()&&backup.readBytes().contentEquals(fresh)&&isBackupKept(backup)){"The source identity or retained recovery backup changed before Bank reservation."}
            require(gen2BankSnapshot()==bankBefore){"The Gen 2 Bank changed while the deposit was prepared."};bankFile=File(bankDir(),"${System.currentTimeMillis()}_${System.nanoTime()}_${selected.species}.pse2");require(bankFile!!.createNewFile()){"PSE could not reserve a unique Gen 2 Bank record."};bankReserved=true;bankFile!!.writeBytes(payload)
            val storedBytes=bankFile!!.readBytes();val stored=parseGen2BankPayload(storedBytes)?:error("The Gen 2 Bank record could not be verified.");require(storedBytes.contentEquals(payload)&&sameGen2BankRecord(stored,selected)){"The preserved Gen 2 Bank record changed during staging."};require(gen2BankSnapshot()==(bankBefore+bankFile!!.canonicalPath).sorted()){"The Gen 2 Bank inventory changed during staging."}
            val work=fresh.copyOf();removeGen2ForBank(work,selected,location);val expected=before.filterIndexed{index,_->index!=selected.slot};val stagedProfile=detectGen2Profile(work)?:error("The staged Gen 2 save failed checksum verification.");require(gen2ChecksumValid(work,stagedProfile)){"The staged Gen 2 checksum is invalid."};require(sameGen2PayloadList(gen2LocationPayloads(work,location,stagedProfile),expected)){"A remaining Gen 2 Pokémon changed during Bank staging."}
            require(verifyGen2SaveIntegrity(work).first&&stagedProfile.key==profile.key){"The complete staged Gen 2 source failed integrity or profile validation."}
            require(gen2BankSnapshot()==(bankBefore+bankFile!!.canonicalPath).sorted()&&bankFile!!.readBytes().contentEquals(payload)){"The staged Gen 2 Bank record or inventory changed before source writing."}
            require(importedFile?.absolutePath==file.absolutePath&&file.readBytes().contentEquals(fresh)){"The active Gen 2 save changed during Bank staging. Nothing was written to the save."}
            require(bound()&&backup.readBytes().contentEquals(fresh)&&isBackupKept(backup)){"The source identity or retained backup changed before depositing."}
            sourceWriteStarted=true
            file.writeBytes(work);val written=file.readBytes();require(written.contentEquals(work)){"The Gen 2 save changed while the Bank deposit was written."};val writtenProfile=detectGen2Profile(written)?:error("The persisted Gen 2 save failed checksum verification.");require(gen2ChecksumValid(written,writtenProfile)){"The persisted Gen 2 checksum is invalid."};require(sameGen2PayloadList(gen2LocationPayloads(written,location,writtenProfile),expected)){"A remaining Gen 2 Pokémon changed after persistence."}
            require(bound()&&writtenProfile.key==profile.key&&verifyGen2SaveIntegrity(written).first){"The persisted Gen 2 source or identity did not verify."}
            val committed=bankFile!!.readBytes();require(committed.contentEquals(payload)&&parseGen2BankPayload(committed)?.let{sameGen2BankRecord(it,selected)}==true){"The committed Gen 2 Bank record did not remain exact."}
            require(bound()&&file.readBytes().contentEquals(work)){"The verified Gen 2 source changed before deposit completion."}
        }catch(e:Exception){
            val sourceRestored=!sourceWriteStarted||(runCatching{file.writeBytes(fresh)}.isSuccess&&runCatching{file.readBytes().contentEquals(fresh)}.getOrDefault(false))
            val stagedBank=bankFile
            val bankCleared=if(!bankReserved)true else if(!sourceRestored||stagedBank==null)false else runCatching{
                if(stagedBank.exists()){require(stagedBank.readBytes().contentEquals(expectedPayload)){"The reserved Bank record changed; it was not removed."};require(stagedBank.delete()){"The reserved Bank record could not be removed."}}
                require(!stagedBank.exists()){"The reserved Bank record still exists."}
            }.isSuccess
            val recovery=if(!sourceWriteStarted&&bankCleared)"Nothing was written to the save and no staged Bank record was kept." else  if(sourceRestored&&bankCleared)"The exact fresh Gen 2 save was restored and no staged Bank record was kept." else  "Automatic recovery could not be verified. Stop editing this save and keep any remaining Bank record until a verified backup and Bank contents have been reviewed."
            showDialog("PSE Bank move failed",(e.message?:"Unknown error")+"\n\n$recovery"+(safetyBackup?.let{"\n\nRecovery backup: "+it.name}?:""));return
        }
        Toast.makeText(this,"Moved to PSE Bank and verified",Toast.LENGTH_LONG).show();showBank()
    }

    private fun gen2BankGridCell(slot:Int, pair:Pair<File,Gen2Pokemon>?):LinearLayout {
        val w=((resources.displayMetrics.widthPixels-dp(44))/6).coerceAtLeast(dp(50))
        return LinearLayout(this).apply {
            orientation=LinearLayout.VERTICAL; gravity=Gravity.CENTER; setPadding(dp(2),dp(4),dp(2),dp(4)); setBackgroundColor(if(pair==null)Color.rgb(27,27,27) else if(bankMultiSelectMode && selectedBankFiles.contains(pair.first.absolutePath))Color.rgb(25,105,145) else CARD)
            layoutParams=GridLayout.LayoutParams().apply{width=w;height=dp(82);setMargins(dp(1),dp(1),dp(1),dp(1))}
            if(pair!=null){isClickable=true;setOnClickListener{if(bankMultiSelectMode){if(!selectedBankFiles.add(pair.first.absolutePath))selectedBankFiles.remove(pair.first.absolutePath);showBank()}else showGen2BankEntry(pair.first,pair.second)};val iv=ImageView(this@MainActivity).apply{scaleType=ImageView.ScaleType.FIT_CENTER};addView(iv,LinearLayout.LayoutParams(dp(52),dp(52)));loadGen2Sprite(iv,pair.second.species,pair.second.shiny)}
            else addView(TextView(this@MainActivity).apply{text="○";textSize=24f;gravity=Gravity.CENTER;setTextColor(Color.rgb(80,80,80))},LinearLayout.LayoutParams(dp(52),dp(52)))
            addView(TextView(this@MainActivity).apply{text=(slot+1).toString();textSize=10f;gravity=Gravity.CENTER;setTextColor(MUTED)})
        }
    }

    private fun showGen2BankEntry(bankFile:File, mon:Gen2Pokemon) {
        val bankEntryUri=currentSourceUri;val bankEntryLabel=currentSourceLabel
        val bankEntryBytes=runCatching{bankFile.readBytes()}.getOrNull();var bankDeleteOffered=false
        val openedFile=importedFile;val loadedGen2=runCatching{openedFile?.readBytes()?.let{detectGen2Profile(it)}}.getOrNull()
        val message=buildString {
            append("Lv.${mon.level} • OT ${mon.otName.ifBlank{"—"}} • TID ${mon.tid}")
            append(if(mon.shiny)" • Shiny ✨" else "")
            append("\n\nOriginal Gen 2 boxed record, OT and nickname are preserved exactly.")
            if(loadedGen2!=null) append("\n\nA Gen 2 save is loaded. You can withdraw this Pokémon into any PC box with space.")
            else append("\n\nLoad a Gold, Silver or Crystal save to withdraw this Pokémon.")
        }
        val b=AlertDialog.Builder(this).setTitle("${mon.nickname.ifBlank{"Pokémon #${mon.species}"}} • Gen 2 Bank").setMessage(message).setNegativeButton("Close",null)
            .setNeutralButton("Delete"){_,_->
                if(bankDeleteOffered){showDialog("PSE Bank","This Bank deletion was already opened. Reopen PSE Bank.");return@setNeutralButton};bankDeleteOffered=true
                confirmGen2BankDelete(bankFile,mon,bankEntryBytes)
            }
        if(loadedGen2!=null&&openedFile!=null) b.setPositiveButton("Withdraw to Save"){_,_->
            if(importedFile?.absolutePath!=openedFile.absolutePath||currentSourceUri!=bankEntryUri||currentSourceLabel!=bankEntryLabel){showDialog("Gen 2 Bank withdrawal","The destination identity changed since this Bank entry opened. Reopen PSE Bank. Nothing was changed.");return@setPositiveButton}
            withdrawGen2BankToBox(bankFile,mon,openedFile)
        }
        val loadedGen = runCatching { importedFile?.readBytes()?.let { generationForSize(it.size) } }.getOrNull()
        if (loadedGen == 1 && loadedGen2 == null && openedFile != null) b.setPositiveButton("Transfer to Gen 1") { _, _ ->
            if(importedFile?.absolutePath!=openedFile.absolutePath||currentSourceUri!=bankEntryUri||currentSourceLabel!=bankEntryLabel){showDialog("Gen 2 → Gen 1","The destination identity changed since this Bank entry opened. Reopen PSE Bank. Nothing was changed.");return@setPositiveButton}
            prepareGen2ToGen1Transfer(bankFile, mon, openedFile)
        }
        if (loadedGen == 3 && openedFile != null) b.setPositiveButton("Transfer to Gen 3") { _, _ ->
            if(importedFile?.absolutePath!=openedFile.absolutePath||currentSourceUri!=bankEntryUri||currentSourceLabel!=bankEntryLabel){showDialog("Gen 2 → Gen 3","The destination identity changed since this Bank entry opened. Reopen PSE Bank. Nothing was changed.");return@setPositiveButton}
            prepareGen2ToGen3Transfer(bankFile, mon, openedFile)
        }
        if (loadedGen == 4 && openedFile != null) b.setPositiveButton("Transfer to Gen 4") { _, _ ->
            if(importedFile?.absolutePath!=openedFile.absolutePath||currentSourceUri!=bankEntryUri||currentSourceLabel!=bankEntryLabel){showDialog("Gen 2 → Gen 4","The destination identity changed since this Bank entry opened. Reopen PSE Bank. Nothing was changed.");return@setPositiveButton}
            prepareGen2ToGen4Transfer(bankFile, mon, openedFile)
        }
        if (loadedGen == 5 && openedFile != null) b.setPositiveButton("Transfer to Gen 5") { _, _ ->
            if(importedFile?.absolutePath!=openedFile.absolutePath||currentSourceUri!=bankEntryUri||currentSourceLabel!=bankEntryLabel){showDialog("Gen 2 → Gen 5","The destination identity changed since this Bank entry opened. Reopen PSE Bank. Nothing was changed.");return@setPositiveButton}
            prepareGen2ToGen5Transfer(bankFile, mon, openedFile)
        }
        if (loadedGen == 6 && openedFile != null) b.setPositiveButton("Transfer to Gen 6") { _, _ ->
            if(importedFile?.absolutePath!=openedFile.absolutePath||currentSourceUri!=bankEntryUri||currentSourceLabel!=bankEntryLabel){showDialog("Gen 2 → Gen 6","The destination identity changed since this Bank entry opened. Reopen PSE Bank. Nothing was changed.");return@setPositiveButton}
            prepareGen2ToGen6Transfer(bankFile, mon, openedFile)
        }
        if (loadedGen == 7 && openedFile != null) b.setPositiveButton("Transfer to Gen 7") { _, _ ->
            if(importedFile?.absolutePath!=openedFile.absolutePath||currentSourceUri!=bankEntryUri||currentSourceLabel!=bankEntryLabel){showDialog("Gen 2 → Gen 7","The destination identity changed since this Bank entry opened. Reopen PSE Bank. Nothing was changed.");return@setPositiveButton}
            prepareGen2ForwardTransfer(bankFile, mon, openedFile)
        }
        b.show()
    }

    private fun gen2BankDeleteMatches(file:File,expected:Gen2Pokemon,bytes:ByteArray):Boolean=runCatching{
        file.isFile&&file.extension.equals("pse2",true)&&file.parentFile?.canonicalFile==bankDir().canonicalFile&&file.canonicalFile==File(bankDir().canonicalFile,file.name)&&file.readBytes().contentEquals(bytes)&&parseGen2BankPayload(bytes)?.let{sameGen2BankRecord(it,expected)}==true
    }.getOrDefault(false)

    private fun confirmGen2BankDelete(bankFile:File,expected:Gen2Pokemon,openedBytes:ByteArray?){
        val snapshot=openedBytes?.copyOf()?:return showDialog("Delete Bank entry","The original Gen 2 Bank record could not be read. Reopen PSE Bank. Nothing was removed.")
        if(!gen2BankDeleteMatches(bankFile,expected,snapshot))return showDialog("Delete Bank entry","The selected Gen 2 Bank record changed or is invalid. Reopen PSE Bank. Nothing was removed.")
        var consumed=false
        AlertDialog.Builder(this).setTitle("Delete Bank entry?").setMessage("This permanently removes this exact preserved Gen 2 Bank copy. The loaded save and other Bank entries will not be changed. Cancel keeps the record unchanged.")
            .setNegativeButton("Cancel"){_,_->consumed=true}.setOnCancelListener{consumed=true}
            .setPositiveButton("Delete"){_,_->
                if(consumed){showDialog("Delete Bank entry","This deletion confirmation was already used. Reopen PSE Bank.");return@setPositiveButton};consumed=true
                deleteGen2BankEntry(bankFile,expected,snapshot)
            }.show()
    }

    private fun deleteGen2BankEntry(file:File,expected:Gen2Pokemon,snapshot:ByteArray){
        if(!gen2BankDeleteMatches(file,expected,snapshot))return showDialog("Delete Bank entry","The confirmed Gen 2 Bank record changed or is invalid. Nothing was removed.")
        var deleteAttempted=false
        try{
            require(gen2BankDeleteMatches(file,expected,snapshot)){"The selected Gen 2 Bank record changed before removal."}
            deleteAttempted=true
            require(file.delete()){"The Gen 2 Bank record could not be removed."}
            require(!file.exists()){"The removed Gen 2 Bank path still exists."}
        }catch(e:Exception){
            val restored=if(!deleteAttempted)false else runCatching{
                if(!file.exists()){
                    require(file.createNewFile()){"The original Bank path could not be reserved for recovery."}
                    file.writeBytes(snapshot)
                }
                require(gen2BankDeleteMatches(file,expected,snapshot)){"The original Bank record could not be verified; no existing record was overwritten."}
            }.isSuccess
            val recovery=if(!deleteAttempted)"No Bank record was removed by PSE." else  if(restored)"The original Gen 2 Bank record was kept or restored and verified." else  "Recovery could not be verified. Stop editing and review the remaining Bank entry; no existing Bank record was overwritten."
            showDialog("Delete Bank entry failed",(e.message?:"Unknown error")+"\n\n"+recovery);return
        }
        selectedBankFiles.remove(file.absolutePath)
        Toast.makeText(this,"Gen 2 Bank entry deleted and removal verified",Toast.LENGTH_SHORT).show();showBank()
    }


    private fun sameGen2BankRecord(a:Gen2Pokemon,b:Gen2Pokemon):Boolean =
        a.species==b.species&&a.nickname==b.nickname&&a.otName==b.otName&&a.level==b.level&&a.heldItem==b.heldItem&&a.tid==b.tid&&a.experience==b.experience&&a.moves.contentEquals(b.moves)&&a.movePP.contentEquals(b.movePP)&&a.statExp.contentEquals(b.statExp)&&a.happiness==b.happiness&&a.pokerus==b.pokerus&&a.caughtData==b.caughtData&&a.dvs.contentEquals(b.dvs)&&a.shiny==b.shiny&&a.isEgg==b.isEgg

    private data class Gen2ToGen1LegalisePlan(val originalHappiness:Int,val originalPokerus:Int,val originalCaughtData:Int)

    private fun gen2ToGen1LegalisePlan(p:Gen2Pokemon):Gen2ToGen1LegalisePlan? =
        if(!p.isEgg&&p.species in 1..151&&p.moves.all{it in 0..165}&&
            p.heldItem !in GEN2_MAIL_ITEM_IDS&&(p.happiness!=70||p.pokerus!=0||p.caughtData!=0))
            Gen2ToGen1LegalisePlan(p.happiness,p.pokerus,p.caughtData) else null

    private fun gen2ToGen1LegaliseChanges(plan:Gen2ToGen1LegalisePlan):String =
        listOfNotNull(
            if(plan.originalHappiness!=70)"Gen 2 happiness ${plan.originalHappiness}" else null,
            if(plan.originalPokerus!=0)"Gen 2 Pokérus 0x${plan.originalPokerus.toString(16).uppercase().padStart(2,'0')}" else null,
            if(plan.originalCaughtData!=0)"Gen 2 caught/met data 0x${plan.originalCaughtData.toString(16).uppercase().padStart(4,'0')}" else null
        ).joinToString(" and ")

    private fun gen2ToGen1Rejection(p:Gen2Pokemon,legalise:Gen2ToGen1LegalisePlan?=null):String? = when {
        p.isEgg -> "Gen 2 Eggs cannot exist in a Gen 1 save."
        p.species !in 1..151 -> "Species #${p.species} did not exist in Generation 1."
        p.moves.any{it !in 0..165} -> "This Pokémon knows a move that did not exist in Generation 1."
        p.heldItem in GEN2_MAIL_ITEM_IDS -> "Its held Mail and message state cannot be represented in Generation 1."
        p.happiness!=70&&legalise?.originalHappiness!=p.happiness -> "Its Gen 2 happiness is ${p.happiness}; only the preserved Time Capsule baseline of 70 can round-trip without conversion."
        p.pokerus!=0&&legalise?.originalPokerus!=p.pokerus -> "Its Pokérus state cannot be represented in Generation 1."
        p.caughtData!=0&&legalise?.originalCaughtData!=p.caughtData -> "Its Gen 2 caught/met data cannot be represented in Generation 1."
        else -> null
    }

    private fun buildGen2ToGen1Record(bankBytes:ByteArray,p:Gen2Pokemon,meta:Gen1SpeciesMeta,legalise:Gen2ToGen1LegalisePlan?=null):Triple<ByteArray,ByteArray,ByteArray> {
        require(bankBytes.size==GEN2_BANK_FILE_SIZE){"The preserved Gen 2 Bank record has an unexpected size."}
        require(legalise==null||legalise==gen2ToGen1LegalisePlan(p)){"The prepared Gen 1 Legalise plan no longer matches the selected Pokémon."}
        gen2ToGen1Rejection(p,legalise)?.let{error(it)}
        require(meta.dex==p.species&&meta.internalIndex==gen1InternalIndexForDex(p.species)){"The Gen 1 species mapping did not verify."}
        val source=GEN2_BANK_HEADER_SIZE;val mon=ByteArray(GEN1_BOX_MON_SIZE)
        mon[0]=meta.internalIndex.toByte();val stats=gen1CalculatedStats(meta,p.level,p.dvs,p.statExp);writeU16BE(mon,1,stats[0]);mon[3]=p.level.toByte();mon[4]=0;mon[5]=meta.type1.toByte();mon[6]=meta.type2.toByte()
        // Time Capsule-compatible reverse mapping: Gen 2's held-item byte occupies
        // Gen 1's catch-rate byte. The exact byte therefore survives a round trip.
        mon[7]=bankBytes[source+1]
        for(i in 0..3)mon[8+i]=p.moves[i].toByte();writeU16BE(mon,12,p.tid);writeU24BE(mon,14,p.experience)
        for(i in 0..4)writeU16BE(mon,17+i*2,p.statExp[i]);mon[27]=bankBytes[source+21];mon[28]=bankBytes[source+22]
        for(i in 0..3)mon[29+i]=bankBytes[source+23+i]
        val ot=bankBytes.copyOfRange(source+32,source+43);val nick=bankBytes.copyOfRange(source+43,source+54)
        return Triple(mon,ot,nick)
    }

    private fun retainGen2ToGen1SafetyBackup(file:File,expected:ByteArray) {
        require(file.isFile&&file.readBytes().contentEquals(expected)&&verifyGen1SaveIntegrity(expected).first){"The Gen 1 destination recovery backup did not verify."}
        val names=keptBackupNames().apply{add(file.name)}
        val prefs=getSharedPreferences("pse_backup_state",MODE_PRIVATE)
        require(prefs.edit().putStringSet("kept",names).commit()){"The destination recovery backup Keep pin could not be saved. Nothing may be written."}
        require(prefs.getStringSet("kept",emptySet())?.contains(file.name)==true&&file.readBytes().contentEquals(expected)){"The destination recovery backup or Keep pin could not be rechecked."}
    }

    private fun prepareGen2ToGen1Transfer(bankFile:File,shown:Gen2Pokemon,openedFile:File,legalise:Gen2ToGen1LegalisePlan?=null){
        val openedUri=currentSourceUri;val openedLabel=currentSourceLabel
        fun bound()=importedFile?.absolutePath==openedFile.absolutePath&&currentSourceUri==openedUri&&currentSourceLabel==openedLabel
        if(!bound()){showDialog("Gen 2 → Gen 1","The destination identity or prepared source changed. Reopen PSE Bank. Nothing was changed.");return}
        var legaliseConsumed=false
        if(importedFile?.absolutePath!=openedFile.absolutePath)return showDialog("Gen 2 → Gen 1","The active save changed after the Bank entry opened. Reopen PSE Bank. Nothing was changed.")
        val file=openedFile;val destination=runCatching{file.readBytes()}.getOrNull()?:return showDialog("Gen 2 → Gen 1","PSE could not read the destination save.")
        val integrity=verifyGen1SaveIntegrity(destination);if(!integrity.first)return showDialog("Gen 2 → Gen 1",integrity.second)
        val bank=runCatching{bankFile.readBytes()}.getOrNull()?:return showDialog("Gen 2 → Gen 1","PSE could not read the selected Gen 2 Bank record.")
        val source=parseGen2BankPayload(bank)?:return showDialog("Gen 2 → Gen 1","The selected Gen 2 Bank record is invalid.")
        if(!sameGen2BankRecord(source,shown))return showDialog("Gen 2 → Gen 1","The selected Gen 2 Bank record changed. Nothing was changed.")
        gen2ToGen1Rejection(source,legalise)?.let{reason->
            val plan=if(legalise==null)gen2ToGen1LegalisePlan(source) else null
            if(plan!=null){
                AlertDialog.Builder(this).setTitle("Cannot transfer unchanged")
                    .setMessage("$reason\n\nMake legal for Gen 1 will omit only ${gen2ToGen1LegaliseChanges(plan)}, because Generation 1 has no fields that can store those values. Species, OT/TID, nickname, level, EXP, Stat Exp, DVs, moves, PP/PP Ups and the Time Capsule held-item/catch-rate byte remain unchanged.\n\nCancel leaves the Bank record and destination save byte-exact. The Bank record is not removed unless the destination write verifies successfully.")
                    .setNegativeButton("Cancel",null)
                    .setPositiveButton("Make legal for Gen 1"){_,_->
                        if(legaliseConsumed){showDialog("Gen 2 → Gen 1","This Legalise confirmation was already submitted. Reopen PSE Bank.");return@setPositiveButton};legaliseConsumed=true
                        if(!bound()||!runCatching{file.readBytes().contentEquals(destination)&&bankFile.readBytes().contentEquals(bank)}.getOrDefault(false)){showDialog("Gen 2 → Gen 1","The destination identity or prepared source changed. Reopen PSE Bank. Nothing was changed.");return@setPositiveButton}
                        prepareGen2ToGen1Transfer(bankFile,shown,file,plan)
                    }.show()
                return
            }
            return showDialog("Cannot transfer to Gen 1","$reason\n\nNo safe deterministic Gen 1 legalisation is available. The Bank record and destination save were left unchanged.")
        }
        if(legalise!=null&&legalise!=gen2ToGen1LegalisePlan(source))return showDialog("Legalise blocked","The prepared Gen 1 Legalise plan no longer matches this Bank record. Nothing was changed.")
        val targets=availableGen1BoxTargets(destination);if(targets.isEmpty())return showDialog("Gen 2 → Gen 1","No writable Gen 1 PC box has an empty slot. Nothing was changed.")
        var destinationPickerOffered=false;var transferConfirmationConsumed=false;var transferConsumed=false
        loadGen1SpeciesMetaAsync(source.species){meta->
            if(destinationPickerOffered||!bound()){showDialog("Gen 2 → Gen 1","The destination identity or prepared source changed. Reopen PSE Bank. Nothing was changed.");return@loadGen1SpeciesMetaAsync}
            if(meta==null){showDialog("Gen 2 → Gen 1","PSE could not resolve the Gen 1 species data needed for an exact conversion. Nothing was changed.");return@loadGen1SpeciesMetaAsync}
            if(importedFile?.absolutePath!=file.absolutePath){showDialog("Gen 2 → Gen 1","The active save changed while conversion data was prepared. Reopen PSE Bank. Nothing was changed.");return@loadGen1SpeciesMetaAsync}
            val currentBank=runCatching{bankFile.readBytes()}.getOrNull();val currentDestination=runCatching{file.readBytes()}.getOrNull()
            if(currentBank==null||currentDestination==null||!currentBank.contentEquals(bank)||!currentDestination.contentEquals(destination)){showDialog("Gen 2 → Gen 1","The source or destination changed while conversion data was prepared. Nothing was changed.");return@loadGen1SpeciesMetaAsync}
            val labels=targets.map{"Box ${it.first} • ${it.second} empty slot${if(it.second==1)"" else "s"}"}.toTypedArray()
            destinationPickerOffered=true
            AlertDialog.Builder(this).setTitle("Transfer ${source.nickname.ifBlank{"Pokémon #${source.species}"}} to Gen 1")
                .setMessage((if(legalise!=null)"Legalise is confirmed: ${gen2ToGen1LegaliseChanges(legalise)} will be omitted because Gen 1 cannot store it. " else "")+"PSE verified that this Gen 2 Pokémon has a Generation 1 species and moves that can be represented safely. OT/TID, nickname, level, EXP, Stat Exp, DVs, moves and PP Ups will be preserved. The held-item byte is intentionally restored to the Gen 1 catch-rate byte, matching the Time Capsule record layout.\n\nA verified kept recovery backup of the Gen 1 destination is required before writing. If a write fails, PSE attempts and verifies recovery; unverified recovery requires reviewing the retained backup and Bank record. The Gen 2 Bank entry is removed only after the Gen 1 save, PC box, Pokédex and checksums persist and re-read successfully.")
                .setNegativeButton("Cancel",null)
                .setPositiveButton(if(legalise!=null)"Legalise & transfer" else "Transfer"){_,_->
                    if(transferConfirmationConsumed){showDialog("Gen 2 → Gen 1","This transfer confirmation was already submitted. Reopen PSE Bank.");return@setPositiveButton};transferConfirmationConsumed=true
                    if(!bound()||!runCatching{file.readBytes().contentEquals(destination)&&bankFile.readBytes().contentEquals(bank)}.getOrDefault(false)){showDialog("Gen 2 → Gen 1","The destination identity or prepared source changed. Reopen PSE Bank. Nothing was changed.");return@setPositiveButton}
                    AlertDialog.Builder(this).setTitle("Choose Gen 1 destination box")
                        .setItems(labels){_,which->
                            if(transferConsumed){showDialog("Gen 2 → Gen 1","This transfer was already submitted. Reopen PSE Bank.");return@setItems};transferConsumed=true
                            if(!bound()){showDialog("Gen 2 → Gen 1","The destination identity or prepared source changed. Reopen PSE Bank. Nothing was changed.");return@setItems}
                            transferGen2BankToGen1(bankFile,source,bank,destination,meta,targets[which].first,file,legalise,openedUri,openedLabel)
                        }.setNegativeButton("Cancel",null).show()
                }.show()
        }
    }

    private fun transferGen2BankToGen1(bankFile:File,expected:Gen2Pokemon,expectedBank:ByteArray,preparedDestination:ByteArray,meta:Gen1SpeciesMeta,targetBox:Int,openedFile:File,legalise:Gen2ToGen1LegalisePlan?=null,openedUri:Uri?,openedLabel:String?){
        fun bound()=importedFile?.absolutePath==openedFile.absolutePath&&currentSourceUri==openedUri&&currentSourceLabel==openedLabel
        if(!bound()){showDialog("Gen 2 → Gen 1","The destination identity or prepared source changed. Reopen PSE Bank. Nothing was changed.");return}
        if(importedFile?.absolutePath!=openedFile.absolutePath){showDialog("Gen 2 → Gen 1","The active save changed after destination preparation. Reopen PSE Bank. Nothing was changed.");return}
        val file=openedFile;val fresh=runCatching{file.readBytes()}.getOrNull()?:return;var writeStarted=false;var bankDeleteAttempted=false
        var safetyBackup:File?=null
        try{
            require(bound()){"The destination identity changed before transfer validation."}
            require(fresh.contentEquals(preparedDestination)){"The Gen 1 destination changed after preparation."};val integrity=verifyGen1SaveIntegrity(fresh);require(integrity.first){integrity.second};require(targetBox in 1..12&&gen1BoxIsWritable(fresh,targetBox)){"The selected Gen 1 box is no longer writable."}
            val bank=bankFile.readBytes();require(bank.contentEquals(expectedBank)){"The selected Gen 2 Bank record changed after preparation."};val source=parseGen2BankPayload(bank)?:error("The selected Gen 2 Bank record is invalid.");require(sameGen2BankRecord(source,expected)){"The selected Gen 2 Pokémon changed after preparation."};require(legalise==null||legalise==gen2ToGen1LegalisePlan(source)){"The prepared Gen 1 Legalise plan no longer matches the selected Pokémon."};gen2ToGen1Rejection(source,legalise)?.let{error(it)}
            val base=gen1BoxDataOffset(fresh,targetBox);val count=fresh[base].toInt() and 0xFF;require(count in 0 until GEN1_BOX_CAPACITY){"Gen 1 Box $targetBox is full or structurally invalid."};val before=parseGen1Box(fresh,targetBox).pokemon.sortedBy{it.slot};require(before.size==count){"Gen 1 Box $targetBox contains an invalid record."}
            val(mon,ot,nick)=buildGen2ToGen1Record(bank,source,meta,legalise);val work=fresh.copyOf();val slot=appendGen1BoxPokemon(work,targetBox,mon,ot,nick);markGen1PokedexCaught(work,source.species);updateGen1MainChecksum(work)
            val pre=verifyGen1WriteState(work,targetBox);require(pre.first){pre.second};val staged=parseGen1Box(work,targetBox).pokemon.sortedBy{it.slot};require(staged.size==before.size+1){"The staged Gen 1 box count did not increase by one."};require(staged.take(before.size).zip(before).all{(a,b)->sameGen1TransferRecord(a,b)}){"An existing Gen 1 Pokémon changed during staging."}
            fun matches(q:Gen1Pokemon)=q.species==meta.internalIndex&&q.nickname==source.nickname&&q.otName==source.otName&&q.level==source.level&&q.currentHp==gen1CalculatedStats(meta,source.level,source.dvs,source.statExp)[0]&&q.tid==source.tid&&q.experience==source.experience&&q.moves.contentEquals(source.moves)&&q.movePP.contentEquals(source.movePP)&&q.movePpUps.contentEquals(IntArray(4){i->(bank[GEN2_BANK_HEADER_SIZE+23+i].toInt() ushr 6) and 3})&&q.statExp.contentEquals(source.statExp)&&q.dvs.contentEquals(source.dvs)
            val stagedCopy=staged.firstOrNull{it.slot==slot};require(stagedCopy!=null&&matches(stagedCopy)){"The staged Gen 1 conversion did not preserve every supported field."};val stagedBase=gen1BoxDataOffset(work,targetBox)+GEN1_BOX_MONS+slot*GEN1_BOX_MON_SIZE;require(work.copyOfRange(stagedBase,stagedBase+GEN1_BOX_MON_SIZE).contentEquals(mon)){"The exact converted Gen 1 record did not stage."}
            val dexIndex=source.species-1;val dexMask=1 shl(dexIndex and 7);require((work[0x25A3+dexIndex/8].toInt() and dexMask)!=0&&(work[0x25B6+dexIndex/8].toInt() and dexMask)!=0){"The Gen 1 Pokédex flags did not stage."}
            require(bankFile.readBytes().contentEquals(expectedBank)){"The selected Gen 2 Bank record changed during staging."}
            require(importedFile?.absolutePath==file.absolutePath&&file.readBytes().contentEquals(fresh)){"The active Gen 1 destination changed during staging. Nothing was written."}
            require(bound()&&verifyGen1SaveIntegrity(work).first){"The staged Gen 1 destination identity or full integrity is invalid."}
            val backup=File.createTempFile(backupGameName(file)+"_PreGen2ToGen1Transfer_",".backup",backupsDir());safetyBackup=backup
            backup.writeBytes(fresh);require(backup.readBytes().contentEquals(fresh)){"The exact Gen 1 recovery backup did not verify."};retainGen2ToGen1SafetyBackup(backup,fresh)
            require(bound()&&isBackupKept(backup)&&backup.readBytes().contentEquals(fresh)&&file.readBytes().contentEquals(fresh)&&bankFile.readBytes().contentEquals(expectedBank)){"The destination, Bank record or retained backup changed before writing. Nothing was written."}
            writeStarted=true
            file.writeBytes(work);val written=file.readBytes();require(written.contentEquals(work)){"The Gen 1 destination changed while it was written."};val post=verifyGen1WriteState(written,targetBox);require(post.first){post.second};val after=parseGen1Box(written,targetBox).pokemon.sortedBy{it.slot};require(after.size==before.size+1&&after.take(before.size).zip(before).all{(a,b)->sameGen1TransferRecord(a,b)}){"The persisted Gen 1 box changed unexpectedly."};val q=after.firstOrNull{it.slot==slot};require(q!=null&&matches(q)){"The persisted Gen 1 conversion did not preserve every supported field."};val actualBase=gen1BoxDataOffset(written,targetBox)+GEN1_BOX_MONS+slot*GEN1_BOX_MON_SIZE;require(written.copyOfRange(actualBase,actualBase+GEN1_BOX_MON_SIZE).contentEquals(mon)){"The exact Gen 1 record did not persist."};require((written[0x25A3+dexIndex/8].toInt() and dexMask)!=0&&(written[0x25B6+dexIndex/8].toInt() and dexMask)!=0){"The species was not registered Seen and Caught in Gen 1."}
            require(importedFile?.absolutePath==file.absolutePath&&file.readBytes().contentEquals(work)){"The verified Gen 1 destination changed before Bank cleanup."}
            require(bound()&&verifyGen1SaveIntegrity(written).first){"The destination identity or full integrity changed before Bank cleanup."}
            val cleanup=bankFile.readBytes();require(cleanup.contentEquals(expectedBank)&&parseGen2BankPayload(cleanup)?.let{sameGen2BankRecord(it,source)}==true){"The Gen 2 Bank record changed before cleanup."};bankDeleteAttempted=true;require(bankFile.delete()){"The Gen 2 Bank entry could not be removed after destination verification."};require(!bankFile.exists()){"The removed Gen 2 Bank entry still exists."}
            require(bound()){"The destination identity changed after Bank cleanup."}
            require(importedFile?.absolutePath==file.absolutePath&&file.readBytes().contentEquals(work)){"The verified Gen 1 destination changed after Bank cleanup."}
        }catch(e:Exception){
            val bankRestored=if(!writeStarted)true else runCatching{
                if(bankDeleteAttempted&&!bankFile.exists()){
                    require(bankFile.createNewFile()){"The Bank recovery path could not be reserved."}
                    bankFile.writeBytes(expectedBank)
                }
                require(bankFile.readBytes().contentEquals(expectedBank)){"The original Gen 2 Bank record could not be verified; no existing record was overwritten."}
            }.isSuccess
            val destinationRestored=!writeStarted||(bankRestored&&runCatching{file.writeBytes(fresh)}.isSuccess&&runCatching{file.readBytes().contentEquals(fresh)}.getOrDefault(false)&&runCatching{file.readBytes().contentEquals(fresh)&&verifyGen1SaveIntegrity(fresh).first}.getOrDefault(false))
            val recovery=if(!writeStarted)"Nothing was written to the save and no Bank record was removed." else  if(bankRestored&&destinationRestored)"The exact Gen 1 destination and Gen 2 Bank record were restored or kept and verified." else  "Automatic recovery could not be verified. Stop editing and keep the working save and remaining Bank record until a verified backup and Bank contents have been reviewed."
            showDialog("Gen 2 → Gen 1 transfer failed",(e.message?:"Unknown error")+"\n\n$recovery"+(safetyBackup?.let{"\n\nRecovery backup: "+it.name}?:""));return
        }
        Toast.makeText(this,"Transferred Gen 2 → Gen 1 to Box $targetBox and verified",Toast.LENGTH_LONG).show();showBank()
    }

    private data class Gen2Gen1BatchPrepared(val bankFile:File,val bankBytes:ByteArray,val source:Gen2Pokemon,val meta:Gen1SpeciesMeta,val legalise:Gen2ToGen1LegalisePlan?,val mon:ByteArray,val ot:ByteArray,val nick:ByteArray)

    private fun gen2ToGen1ConvertedMatches(q:Gen1Pokemon,item:Gen2Gen1BatchPrepared):Boolean {
        val p=item.source;val stats=gen1CalculatedStats(item.meta,p.level,p.dvs,p.statExp)
        return q.species==item.meta.internalIndex&&q.nickname==p.nickname&&q.otName==p.otName&&q.level==p.level&&q.currentHp==stats[0]&&q.tid==p.tid&&q.experience==p.experience&&q.moves.contentEquals(p.moves)&&q.movePP.contentEquals(p.movePP)&&q.movePpUps.contentEquals(IntArray(4){i->(item.bankBytes[GEN2_BANK_HEADER_SIZE+23+i].toInt() ushr 6) and 3})&&q.statExp.contentEquals(p.statExp)&&q.dvs.contentEquals(p.dvs)
    }

    private data class Gen2Gen1BatchBinding(val uri:Uri?,val label:String?,val destination:ByteArray,val bankImages:List<Pair<String,ByteArray>>)

    private fun prepareSelectedGen2BankToGen1(chosen:List<File>,legalisePlans:Map<String,Gen2ToGen1LegalisePlan>?=null,openedFile:File?=importedFile,binding:Gen2Gen1BatchBinding?=null){
        val file=openedFile?:return
        val openedUri=if(binding==null)currentSourceUri else binding.uri;val openedLabel=if(binding==null)currentSourceLabel else binding.label
        fun bound()=importedFile?.absolutePath==file.absolutePath&&currentSourceUri==openedUri&&currentSourceLabel==openedLabel
        if(!bound())return showDialog("Gen 2 → Gen 1 multi-transfer","The destination identity changed. Reopen PSE Bank. Nothing was changed.")
        var legaliseConsumed=false
        if(importedFile?.absolutePath!=file.absolutePath)return showDialog("Gen 2 → Gen 1 multi-transfer","The active save changed after preparation. Reopen the Bank selection. Nothing was changed.")
        if(chosen.isEmpty())return showDialog("Gen 2 → Gen 1 multi-transfer","Select one or more Gen 2 Bank Pokémon first.")
        if(chosen.map{it.absolutePath}.distinct().size!=chosen.size)return showDialog("Gen 2 → Gen 1 multi-transfer","The selection contains the same Bank entry more than once. Nothing was changed.")
        val destination=runCatching{file.readBytes()}.getOrNull()?:return showDialog("Gen 2 → Gen 1 multi-transfer","The Gen 1 destination could not be read.")
        val integrity=verifyGen1SaveIntegrity(destination);if(!integrity.first)return showDialog("Gen 2 → Gen 1 multi-transfer",integrity.second)
        val targets=availableGen1BoxTargets(destination).filter{it.second>=chosen.size};if(targets.isEmpty())return showDialog("Gen 2 → Gen 1 multi-transfer","No single writable Gen 1 PC box has room for all ${chosen.size} selected Pokémon. Nothing was changed.")
        val selected=try{chosen.map{bankFile->val bytes=bankFile.readBytes();val source=parseGen2BankPayload(bytes)?:error("A selected Gen 2 Bank record is invalid.");Triple(bankFile,bytes,source)}}catch(e:Exception){return showDialog("Gen 2 → Gen 1 multi-transfer",(e.message?:"A selected Bank record could not be read.")+" Nothing was changed.")}
        if(binding!=null&&(!destination.contentEquals(binding.destination)||binding.bankImages.size!=selected.size||!binding.bankImages.zip(selected).all{(image,item)->image.first==item.first.absolutePath&&image.second.contentEquals(item.second)}))return showDialog("Gen 2 → Gen 1 multi-transfer","The original destination or ordered Bank selection changed after Legalise confirmation. Nothing was changed.")
        fun snapshotsMatch()=bound()&&runCatching{file.readBytes().contentEquals(destination)&&selected.all{it.first.readBytes().contentEquals(it.second)}}.getOrDefault(false)
        val requiredLegalise=linkedMapOf<String,Gen2ToGen1LegalisePlan>()
        for((bankFile,_,source) in selected){gen2ToGen1Rejection(source)?.let{reason->val plan=gen2ToGen1LegalisePlan(source)?:return showDialog("Gen 2 → Gen 1 multi-transfer","${source.nickname.ifBlank{"Pokémon #${source.species}"}} cannot transfer: $reason\n\nNo safe deterministic Gen 1 legalisation is available. Every selected Bank record and the destination were left unchanged.");requiredLegalise[bankFile.absolutePath]=plan}}
        if(legalisePlans==null&&requiredLegalise.isNotEmpty()){
            val summary=selected.mapNotNull{(bankFile,_,source)->requiredLegalise[bankFile.absolutePath]?.let{"${source.nickname.ifBlank{"Pokémon #${source.species}"}}: ${gen2ToGen1LegaliseChanges(it)}"}}.joinToString("\n")
            AlertDialog.Builder(this).setTitle("Cannot transfer selection unchanged")
                .setMessage("Make legal for Gen 1 will omit only these destination-incompatible values:\n\n$summary\n\nEvery other Gen 1-representable field remains unchanged. Cancel leaves the destination and every selected Bank record byte-exact. Bank records are removed only after the complete destination write verifies successfully.")
                .setNegativeButton("Cancel",null)
                .setPositiveButton("Make legal for Gen 1"){_,_->
                    if(legaliseConsumed){showDialog("Gen 2 → Gen 1 multi-transfer","This Legalise confirmation was already submitted. Reopen PSE Bank.");return@setPositiveButton};legaliseConsumed=true
                    if(!snapshotsMatch()){showDialog("Gen 2 → Gen 1 multi-transfer","The destination identity, bytes or ordered Bank selection changed. Nothing was changed.");return@setPositiveButton}
                    prepareSelectedGen2BankToGen1(chosen,requiredLegalise,file,Gen2Gen1BatchBinding(openedUri,openedLabel,destination,selected.map{it.first.absolutePath to it.second}))
                }.show();return
        }
        if(legalisePlans!=null&&legalisePlans!=requiredLegalise)return showDialog("Legalise blocked","The prepared Gen 1 Legalise plan no longer matches this selection. Every selected Bank record and the destination were left unchanged.")
        val prepared=ArrayList<Gen2Gen1BatchPrepared>()
        fun stop(message:String){showDialog("Gen 2 → Gen 1 multi-transfer",message+" Every selected Bank record and the destination were left unchanged.")}
        var expectedIndex=0;var pickerOffered=false;var transferConsumed=false
        fun next(index:Int){
            if(importedFile?.absolutePath!=file.absolutePath)return stop("The active save changed while conversion data was prepared.")
            if(index!=expectedIndex||pickerOffered||!snapshotsMatch())return stop("The destination identity, snapshots or preparation order changed.")
            if(index>=selected.size){
                val currentDestination=runCatching{file.readBytes()}.getOrNull();if(currentDestination==null||!currentDestination.contentEquals(destination))return stop("The Gen 1 destination changed while conversion data was prepared.")
                for((bankFile,bankBytes,source) in selected){val current=runCatching{bankFile.readBytes()}.getOrNull();if(current==null||!current.contentEquals(bankBytes)||parseGen2BankPayload(current)?.let{sameGen2BankRecord(it,source)}!=true)return stop("A selected Gen 2 Bank record changed while conversion data was prepared.")}
                pickerOffered=true
                AlertDialog.Builder(this).setTitle("Transfer ${prepared.size} Gen 2 Pokémon to Gen 1")
                    .setMessage((if(requiredLegalise.isNotEmpty())"Legalise is confirmed for ${requiredLegalise.size} selected Pokémon. Only the listed Gen 2-only values will be omitted. " else "")+"Every selected Pokémon was verified as representable in Generation 1. PSE will preserve all destination-supported identity, battle and PP data, register each Pokédex entry, and remove Bank records only after the complete destination persists exactly. A verified kept recovery backup is required before writing. Failed recovery must be reviewed with the retained backup and remaining Bank records.")
                    .setItems(targets.map{"Box ${it.first} • ${it.second} empty slots"}.toTypedArray()){_,which->
                        if(transferConsumed){showDialog("Gen 2 → Gen 1 multi-transfer","This batch transfer was already submitted. Reopen PSE Bank.");return@setItems};transferConsumed=true
                        if(!snapshotsMatch()){stop("The destination identity or prepared snapshots changed before selection.");return@setItems}
                        transferSelectedGen2BankToGen1(prepared,destination,targets[which].first,file,openedUri,openedLabel)
                    }.setNegativeButton("Cancel",null).show();return
            }
            val(bankFile,bankBytes,source)=selected[index]
            var metadataConsumed=false
            loadGen1SpeciesMetaAsync(source.species){meta->
                if(importedFile?.absolutePath!=file.absolutePath)return@loadGen1SpeciesMetaAsync stop("The active save changed while conversion data was prepared.")
                if(metadataConsumed||index!=expectedIndex||pickerOffered||!snapshotsMatch())return@loadGen1SpeciesMetaAsync stop("The destination identity, snapshots or metadata callback order changed.")
                metadataConsumed=true
                if(meta==null)return@loadGen1SpeciesMetaAsync stop("PSE could not resolve Gen 1 species data for ${source.nickname.ifBlank{"Pokémon #${source.species}"}}.")
                val plan=requiredLegalise[bankFile.absolutePath]
                val record=try{buildGen2ToGen1Record(bankBytes,source,meta,plan)}catch(e:Exception){return@loadGen1SpeciesMetaAsync stop(e.message?:"A selected Pokémon could not be converted.")}
                prepared.add(Gen2Gen1BatchPrepared(bankFile,bankBytes,source,meta,plan,record.first,record.second,record.third));expectedIndex=index+1;next(index+1)
            }
        }
        next(0)
    }

    private fun transferSelectedGen2BankToGen1(prepared:List<Gen2Gen1BatchPrepared>,preparedDestination:ByteArray,targetBox:Int,openedFile:File,openedUri:Uri?,openedLabel:String?){
        fun bound()=importedFile?.absolutePath==openedFile.absolutePath&&currentSourceUri==openedUri&&currentSourceLabel==openedLabel
        if(!bound()){showDialog("Gen 2 → Gen 1 multi-transfer","The destination identity changed. Reopen PSE Bank. Nothing was changed.");return}
        if(importedFile?.absolutePath!=openedFile.absolutePath){showDialog("Gen 2 → Gen 1 multi-transfer","The active save changed after destination preparation. Reopen the Bank selection. Nothing was changed.");return}
        val file=openedFile;val fresh=runCatching{file.readBytes()}.getOrNull()?:return;val removed=ArrayList<Pair<File,ByteArray>>();var writeStarted=false
        var safetyBackup:File?=null
        try{
            require(bound()){"The destination identity changed before batch validation."}
            require(prepared.isNotEmpty()){"The prepared selection is empty."};require(prepared.map{it.bankFile.absolutePath}.distinct().size==prepared.size){"The prepared selection contains a duplicate Bank entry."};require(fresh.contentEquals(preparedDestination)){"The Gen 1 destination changed after preparation."}
            val integrity=verifyGen1SaveIntegrity(fresh);require(integrity.first){integrity.second};require(targetBox in 1..12&&gen1BoxIsWritable(fresh,targetBox)){"The selected Gen 1 box is no longer writable."}
            val base=gen1BoxDataOffset(fresh,targetBox);val count=fresh[base].toInt() and 0xFF;require(count in 0..GEN1_BOX_CAPACITY&&count+prepared.size<=GEN1_BOX_CAPACITY){"Gen 1 Box $targetBox no longer has room for the complete selection."};val before=parseGen1Box(fresh,targetBox).pokemon.sortedBy{it.slot};require(before.size==count){"Gen 1 Box $targetBox contains an invalid record."}
            val refreshed=prepared.map{item->val bank=item.bankFile.readBytes();require(bank.contentEquals(item.bankBytes)){"A selected Gen 2 Bank record changed after preparation."};val source=parseGen2BankPayload(bank)?:error("A selected Gen 2 Bank record is invalid.");require(sameGen2BankRecord(source,item.source)){"A selected Gen 2 Pokémon changed after preparation."};require(item.legalise==null||item.legalise==gen2ToGen1LegalisePlan(source)){"A prepared Gen 1 Legalise plan no longer matches a selected Pokémon."};gen2ToGen1Rejection(source,item.legalise)?.let{error(it)};val rebuilt=buildGen2ToGen1Record(bank,source,item.meta,item.legalise);require(rebuilt.first.contentEquals(item.mon)&&rebuilt.second.contentEquals(item.ot)&&rebuilt.third.contentEquals(item.nick)){"A prepared Gen 1 conversion changed before staging."};item}
            val work=fresh.copyOf();val slots=ArrayList<Int>()
            for(item in refreshed){slots.add(appendGen1BoxPokemon(work,targetBox,item.mon,item.ot,item.nick));markGen1PokedexCaught(work,item.source.species)}
            updateGen1MainChecksum(work);val pre=verifyGen1WriteState(work,targetBox);require(pre.first){pre.second};val staged=parseGen1Box(work,targetBox).pokemon.sortedBy{it.slot};require(staged.size==before.size+refreshed.size){"The complete Gen 2 selection did not stage."};require(staged.take(before.size).zip(before).all{(a,b)->sameGen1TransferRecord(a,b)}){"An existing Gen 1 Pokémon changed during batch staging."}
            for(i in refreshed.indices){val item=refreshed[i];val slot=slots[i];val q=staged.firstOrNull{it.slot==slot};require(q!=null&&gen2ToGen1ConvertedMatches(q,item)){"A staged Gen 1 conversion did not preserve every supported field."};val off=gen1BoxDataOffset(work,targetBox)+GEN1_BOX_MONS+slot*GEN1_BOX_MON_SIZE;require(work.copyOfRange(off,off+GEN1_BOX_MON_SIZE).contentEquals(item.mon)){"An exact converted Gen 1 record did not stage."};val bit=item.source.species-1;val mask=1 shl(bit and 7);require((work[0x25A3+bit/8].toInt() and mask)!=0&&(work[0x25B6+bit/8].toInt() and mask)!=0){"A Gen 1 Pokédex registration did not stage."}}
            require(refreshed.all{it.bankFile.readBytes().contentEquals(it.bankBytes)}){"A selected Gen 2 Bank record changed during staging."}
            require(importedFile?.absolutePath==file.absolutePath&&file.readBytes().contentEquals(fresh)){"The active Gen 1 destination changed during staging. Nothing was written."}
            require(bound()&&verifyGen1SaveIntegrity(work).first){"The staged Gen 1 destination identity or full integrity is invalid."}
            val backup=File.createTempFile(backupGameName(file)+"_PreGen2ToGen1Batch_",".backup",backupsDir());safetyBackup=backup
            backup.writeBytes(fresh);require(backup.readBytes().contentEquals(fresh)){"The exact Gen 1 batch recovery backup did not verify."};retainGen2ToGen1SafetyBackup(backup,fresh)
            require(bound()&&isBackupKept(backup)&&backup.readBytes().contentEquals(fresh)&&file.readBytes().contentEquals(fresh)&&refreshed.all{it.bankFile.readBytes().contentEquals(it.bankBytes)}){"The destination, Bank selection or retained backup changed before writing. Nothing was written."}
            writeStarted=true
            file.writeBytes(work);val written=file.readBytes();require(written.contentEquals(work)){"The Gen 1 destination changed while the batch was written."};val post=verifyGen1WriteState(written,targetBox);require(post.first){post.second};val after=parseGen1Box(written,targetBox).pokemon.sortedBy{it.slot};require(after.size==staged.size&&after.take(before.size).zip(before).all{(a,b)->sameGen1TransferRecord(a,b)}){"The persisted Gen 1 box changed unexpectedly."}
            for(i in refreshed.indices){val item=refreshed[i];val slot=slots[i];val q=after.firstOrNull{it.slot==slot};require(q!=null&&gen2ToGen1ConvertedMatches(q,item)){"A persisted Gen 1 conversion did not preserve every supported field."};val off=gen1BoxDataOffset(written,targetBox)+GEN1_BOX_MONS+slot*GEN1_BOX_MON_SIZE;require(written.copyOfRange(off,off+GEN1_BOX_MON_SIZE).contentEquals(item.mon)){"An exact Gen 1 record did not persist."};val bit=item.source.species-1;val mask=1 shl(bit and 7);require((written[0x25A3+bit/8].toInt() and mask)!=0&&(written[0x25B6+bit/8].toInt() and mask)!=0){"A species was not registered Seen and Caught in Gen 1."}}
            require(bound()&&verifyGen1SaveIntegrity(written).first){"The persisted Gen 1 destination identity or full integrity did not verify."}
            for(item in refreshed){require(bound()){"The destination identity changed before a batch Bank cleanup."};require(importedFile?.absolutePath==file.absolutePath&&file.readBytes().contentEquals(work)){"The verified Gen 1 destination changed before Bank cleanup."};val cleanup=item.bankFile.readBytes();require(cleanup.contentEquals(item.bankBytes)&&parseGen2BankPayload(cleanup)?.let{sameGen2BankRecord(it,item.source)}==true){"A selected Gen 2 Bank record changed before cleanup."};removed.add(item.bankFile to item.bankBytes);require(item.bankFile.delete()){"A selected Gen 2 Bank record could not be removed after destination verification."};require(!item.bankFile.exists()){"A removed Gen 2 Bank record still exists."}}
            require(bound()){"The destination identity changed after batch Bank cleanup."}
            require(importedFile?.absolutePath==file.absolutePath&&file.readBytes().contentEquals(work)){"The verified Gen 1 destination changed after Bank cleanup."}
        }catch(e:Exception){
            val bankRestored=if(!writeStarted)true else{
                var restored=true
                for((bank,bytes)in removed){
                    val recovered=runCatching{
                        if(bank.exists())require(bank.readBytes().contentEquals(bytes)){"A Bank recovery path changed; it was not overwritten."}
                        else{require(bank.createNewFile()){"A Bank recovery path could not be reserved."};bank.writeBytes(bytes);require(bank.readBytes().contentEquals(bytes)){"A restored Bank record did not verify."}}
                    }.isSuccess
                    if(!recovered)restored=false
                }
                restored&&prepared.all{runCatching{it.bankFile.readBytes().contentEquals(it.bankBytes)}.getOrDefault(false)}
            }
            val destinationRestored=!writeStarted||(bankRestored&&runCatching{file.writeBytes(fresh)}.isSuccess&&runCatching{file.readBytes().contentEquals(fresh)}.getOrDefault(false)&&runCatching{file.readBytes().contentEquals(fresh)&&verifyGen1SaveIntegrity(fresh).first}.getOrDefault(false))
            val recovery=if(!writeStarted)"Nothing was written to the save and no Bank record was removed." else  if(bankRestored&&destinationRestored)"The exact Gen 1 destination and every selected Gen 2 Bank record were restored or kept and verified." else  "Automatic recovery could not be verified. Stop editing and keep the working save and remaining Bank records until a verified backup and Bank contents have been reviewed."
            showDialog("Gen 2 → Gen 1 multi-transfer failed",(e.message?:"Unknown error")+"\n\n$recovery"+(safetyBackup?.let{"\n\nRecovery backup: "+it.name}?:""));return
        }
        selectedBankFiles.clear();bankMultiSelectMode=false;Toast.makeText(this,"Transferred ${prepared.size} Gen 2 Pokémon → Gen 1 Box $targetBox and verified",Toast.LENGTH_LONG).show();showBank()
    }

    private data class Gen2ToGen3LegalisePlan(
        val species:Int,val heldItem:Int,val caughtData:Int,val nature:Int,val gender:Int,val shiny:Boolean,
        val dvs:List<Int>,val statExp:List<Int>,val happiness:Int,val pokerus:Int
    )

    private fun gen2ToGen3LegalisePlan(p:Gen2Pokemon,meta:Gen1ToGen7TransferMeta):Gen2ToGen3LegalisePlan? {
        if(p.isEgg||p.species !in 1..251||p.moves.any{it !in 0..251}||p.heldItem in GEN2_MAIL_ITEM_IDS)return null
        return Gen2ToGen3LegalisePlan(p.species,p.heldItem,p.caughtData,(p.experience%25L).toInt(),gen2TransferGender(p,meta.genderRate),p.shiny,p.dvs.toList(),p.statExp.toList(),p.happiness,p.pokerus)
    }

    private fun gen2ToGen3LegaliseChanges(plan:Gen2ToGen3LegalisePlan):String = buildString {
        append("• convert the five Gen 2 Stat Exp values into six Gen 3 EVs, capped to the legal 510 total\n")
        append("• expand the Gen 2 DVs into deterministic Gen 3 IVs while preserving gender and shiny state\n")
        append("• derive nature deterministically from EXP (nature index ${plan.nature}) and use the first Gen 3 ability slot\n")
        append("• record this as a PSE conversion caught at the current level in the loaded Gen 3 title")
        if(plan.heldItem!=0)append("\n• remove held item #${plan.heldItem}, because Gen 2 and Gen 3 item IDs are not interchangeable")
        if(plan.caughtData!=0)append("\n• omit Gen 2 caught/met value 0x${plan.caughtData.toString(16).uppercase().padStart(4,'0')}, whose layout has no exact Gen 3 equivalent")
    }

    private fun gen2ToGen3Rejection(p:Gen2Pokemon,plan:Gen2ToGen3LegalisePlan?=null,meta:Gen1ToGen7TransferMeta?=null):String? = when {
        p.isEgg -> "Gen 2 Egg state cannot yet be converted into a verified native Gen 3 Egg."
        p.species !in 1..251 -> "Species #${p.species} is not a valid Generation 2 species."
        p.moves.any{it !in 0..251} -> "This Pokémon contains a move outside the Generation 2 move catalogue."
        p.heldItem in GEN2_MAIL_ITEM_IDS -> "Held Mail and its message state cannot be represented safely by this Gen 3 conversion."
        meta==null -> "Verified species, gender and move metadata is required before this conversion can be prepared."
        plan==null -> "Generation 2 DVs, Stat Exp, nature/ability absence and caught-origin data cannot transfer unchanged into a native PK3."
        plan!=gen2ToGen3LegalisePlan(p,meta) -> "The prepared Gen 3 Legalise plan no longer matches this Pokémon."
        else -> null
    }

    private fun gen3PidGender(pid:Long,genderRate:Int):Int {
        if(genderRate<0)return 2
        if(genderRate<=0)return 0
        if(genderRate>=8)return 1
        return if((pid.toInt() and 0xFF)<(genderRate*32).coerceIn(1,255))1 else 0
    }

    private fun gen2ToGen3Pid(seed:Long,p:Gen2Pokemon,meta:Gen1ToGen7TransferMeta,plan:Gen2ToGen3LegalisePlan):Long {
        var candidate=seed and 0xFFFFFFFFL
        repeat(2_000_000){
            candidate=(candidate+1L) and 0xFFFFFFFFL
            if((candidate%25L).toInt()!=plan.nature)return@repeat
            val low=candidate.toInt() and 0xFFFF;val high=(candidate.toInt() ushr 16) and 0xFFFF
            val shiny=(p.tid xor low xor high)<8
            if(shiny==plan.shiny&&gen3PidGender(candidate,meta.genderRate)==plan.gender)return candidate
        }
        error("PSE could not derive a deterministic PK3 personality that preserves nature, gender and shiny state.")
    }

    private fun gen2ToGen3Evs(p:Gen2Pokemon):IntArray = gen2ToGen5Evs(p.statExp)
    private fun buildGen2ToGen3Pk3(bankBytes:ByteArray,p:Gen2Pokemon,destinationSave:ByteArray,meta:Gen1ToGen7TransferMeta,plan:Gen2ToGen3LegalisePlan):ByteArray {
        require(bankBytes.size==GEN2_BANK_FILE_SIZE){"The preserved Gen 2 Bank record has an unexpected size."}
        require(generationForSize(destinationSave.size)==3&&gen3SaveValid(destinationSave)){"A valid Generation 3 destination save is required."}
        gen2ToGen3Rejection(p,plan,meta)?.let{error(it)}
        val out=ByteArray(80);val seed=((p.tid.toLong() shl 16) xor p.experience xor (p.species.toLong() shl 8) xor p.caughtData.toLong()) and 0xFFFFFFFFL
        val pid=gen2ToGen3Pid(seed,p,meta,plan);writeU32LE(out,0,pid);writeU16LE(out,4,p.tid);writeU16LE(out,6,0)
        val defaultName=GEN2_NATIONAL_NAMES.getOrElse(p.species-1){"Pokemon"};writeGen3Text(out,8,10,p.nickname.ifBlank{defaultName});out[0x12]=2;writeGen3Text(out,0x14,7,p.otName)
        val blocks=hashMapOf<Char,ByteArray>('G' to ByteArray(12),'A' to ByteArray(12),'E' to ByteArray(12),'M' to ByteArray(12));val g=blocks['G']!!;val a=blocks['A']!!;val e=blocks['E']!!;val m=blocks['M']!!
        writeU16LE(g,0,p.species);writeU16LE(g,2,0);writeU32LE(g,4,p.experience);var ppBonuses=0
        val o=GEN2_BANK_HEADER_SIZE;for(i in 0..3){val move=p.moves[i];writeU16LE(a,i*2,move);a[8+i]=if(move==0)0 else p.movePP[i].coerceIn(0,63).toByte();val ups=if(move==0)0 else ((bankBytes[o+23+i].toInt() ushr 6) and 3);ppBonuses=ppBonuses or (ups shl (i*2))};g[8]=ppBonuses.toByte();g[9]=p.happiness.toByte()
        val ev=gen2ToGen3Evs(p);for(i in 0..5)e[i]=ev[i].toByte();m[0]=p.pokerus.toByte();m[1]=0
        val originGame=gen1ToGen3OriginGame(destinationSave);writeU16LE(m,2,(p.level.coerceIn(1,100) and 0x7F) or ((originGame and 0xF) shl 7) or (4 shl 11))
        val iv=gen2ToGen6Ivs(p);var ivw=0L;for(i in 0..5)ivw=ivw or ((iv[i].toLong() and 31L) shl (i*5));writeU32LE(m,4,ivw)
        val order=gen3Orders[(pid%24L).toInt()];val plain=ByteArray(48);for(i in 0..3)(blocks[order[i]]!!).copyInto(plain,i*12);var sum=0;for(i in 0 until 48 step 2)sum=(sum+readU16LE(plain,i)) and 0xFFFF;writeU16LE(out,0x1C,sum);val key=(pid xor (p.tid.toLong() and 0xFFFFL)).toInt();var x=0;while(x<48){writeU32LE(plain,x,(readU32LE(plain,x).toInt() xor key).toLong() and 0xFFFFFFFFL);x+=4};plain.copyInto(out,0x20)
        val q=parsePk3(out,0,false)?:error("The converted PK3 could not be parsed.");require(q.checksumValid&&q.species==p.species&&q.tid==p.tid&&q.nickname==p.nickname.ifBlank{defaultName}&&q.otName==p.otName&&q.experience==p.experience&&q.nature==plan.nature&&q.shiny==p.shiny&&q.heldItem==0&&q.friendship==p.happiness&&q.pokerusDays==(p.pokerus and 0xF)&&q.pokerusStrain==((p.pokerus ushr 4) and 0xF)&&q.moves.contentEquals(p.moves)&&q.movePP.contentEquals(p.movePP)&&q.evs.contentEquals(ev)&&q.ivs.contentEquals(iv)&&gen3PidGender(pid,meta.genderRate)==plan.gender){"The converted PK3 did not preserve every destination-representable field."}
        return out
    }

    private fun sameGen2ToGen3Pk3(a:PokemonEntry,b:PokemonEntry):Boolean = a.checksumValid&&b.checksumValid&&a.pid==b.pid&&a.species==b.species&&a.tid==b.tid&&a.sid==b.sid&&a.nickname==b.nickname&&a.otName==b.otName&&a.experience==b.experience&&a.nature==b.nature&&a.shiny==b.shiny&&a.originGame==b.originGame&&a.ball==b.ball&&a.metLevel==b.metLevel&&a.language==b.language&&a.heldItem==b.heldItem&&a.friendship==b.friendship&&a.pokerusDays==b.pokerusDays&&a.pokerusStrain==b.pokerusStrain&&a.isEgg==b.isEgg&&a.moves.contentEquals(b.moves)&&a.movePP.contentEquals(b.movePP)&&a.evs.contentEquals(b.evs)&&a.ivs.contentEquals(b.ivs)

    private data class Gen3PokedexLayout(
        val mirrors: IntArray,
        val section0: Int,
        val section1: Int,
        val seenSection: Int,
        val seenSectionId: Int
    )

    private fun gen3PokedexLayout(data: ByteArray): Gen3PokedexLayout? {
        val map = gen3ActiveSectionMap(data) ?: return null
        val s0 = map[0]
        val s1 = map[1]
        if (s0 < 0 || s1 < 0) return null
        val game = detectGen3GameFromData(data, currentSourceLabel ?: importedFile?.name.orEmpty())
        val frlg = game.contains("FireRed") || game.contains("LeafGreen")
        val emerald = game.contains("Emerald")
        val seen2Rel = when {
            frlg -> 0x5F8
            emerald -> 0x988
            else -> 0x938
        }
        val seen3LargeRel = when {
            frlg -> 0x3A18
            emerald -> 0x3B24
            else -> 0x3A8C
        }
        val seenSectionId = 1 + seen3LargeRel / 3968
        val seen3Rel = seen3LargeRel % 3968
        val seenSection = map.getOrNull(seenSectionId) ?: return null
        if (seenSection < 0) return null
        val mirrors = intArrayOf(s0 + 0x28, s0 + 0x5C, s1 + seen2Rel, seenSection + seen3Rel)
        return if (mirrors.all { it >= 0 && it + 49 <= data.size }) {
            Gen3PokedexLayout(mirrors, s0, s1, seenSection, seenSectionId)
        } else null
    }

    private fun gen3PokedexState(data: ByteArray): ByteArray {
        val layout = gen3PokedexLayout(data) ?: error("Could not map the active Gen 3 Pokédex mirrors.")
        val out = ByteArray(layout.mirrors.size * 49)
        layout.mirrors.forEachIndexed { index, base ->
            data.copyInto(out, index * 49, base, base + 49)
        }
        return out
    }

    private fun gen3PokedexMirrorsAgree(data: ByteArray): Boolean {
        val state = gen3PokedexState(data)
        for (i in 0 until 49) {
            val first = state[i]
            if ((1 until 4).any { state[it * 49 + i] != first }) return false
        }
        return true
    }

    private fun showPokedexEditor() {
        if (openActiveSwitchSection("pokedex")) return
        val file = importedFile ?: run {
            showDialog("Gen 3 Pokédex", "Load a valid Generation 3 save before opening the Pokédex.")
            return
        }
        val data = runCatching { file.readBytes() }.getOrNull() ?: run {
            showDialog("Gen 3 Pokédex", "PSE could not read the loaded save.")
            return
        }
        if (data.size != 0x20000 || !gen3SaveValid(data)) {
