        }
        fun updateFilter() {
            val query = search.text.toString().trim().lowercase(Locale.US)
            val selectedGeneration = Gen3PokedexGenerationFilter.values()[
                generationFilter.selectedItemPosition
            ]
            val onlyRegistered = registeredOnly.isChecked
            val onlyUnregistered = unregisteredOnly.isChecked
            val onlyPending = pendingOnly.isChecked
            val onlyPendingRegistrations = pendingRegistrationsOnly.isChecked
            val onlyPendingClears = pendingClearsOnly.isChecked
            rowEntries.forEach { (row, index) ->
                val dex = index + 1
                val name = Gen3PokedexEditing.speciesName(dex, gen3SpeciesNames)
                val matchesQuery = query.isBlank() ||
                    dex.toString() == query ||
                    name.lowercase(Locale.US).contains(query)
                val matchesSpeciesGeneration = Gen3PokedexEditing.matchesGeneration(
                    dex,
                    selectedGeneration
                )
                val matchesRegistration = (!onlyRegistered || registered[index]) &&
                    (!onlyUnregistered || !registered[index])
                val changeDirection = Gen3PokedexEditing.changeDirection(
                    loadedRegistration,
                    registered,
                    index
                )
                val matchesPending = when {
                    onlyPendingRegistrations ->
                        changeDirection == Gen3PokedexChangeDirection.REGISTER
                    onlyPendingClears ->
                        changeDirection == Gen3PokedexChangeDirection.CLEAR
                    else -> !onlyPending || changeDirection != null
                }
                row.visibility = if (
                    matchesQuery &&
                    matchesSpeciesGeneration &&
                    matchesRegistration &&
                    matchesPending
                ) View.VISIBLE else View.GONE
            }
            val orderedDexNumbers = Gen3PokedexEditing.orderedDexNumbers(
                gen3SpeciesNames,
                Gen3PokedexSortOrder.values()[sortOrder.selectedItemPosition]
            )
            list.removeAllViews()
