            restored.copyInto(registered)
        }
        action("Restore Loaded Registration") {
            val restored = Gen3PokedexEditing.restoreLoaded(loadedRegistration)
            restored.copyInto(registered)
        }
        addButton(root, "Undo Last Registration Action") undo@{
            val snapshots = lastRegistrationAction ?: run {
                showDialog("Undo Gen 3 Pokédex action", "There is no bulk registration action to undo.")
                return@undo
            }
            val restored = Gen3PokedexEditing.undoActionIfCurrent(
                registered,
                snapshots.first,
                snapshots.second
            )
            if (restored == null) {
