            row.addView(sprite, LinearLayout.LayoutParams(dp(58), dp(58)))
            loadPokemonSprite(sprite, dex, false)
            row.addView(TextView(this).apply {
                text = speciesName
                textSize = 14f
                typeface = Typeface.DEFAULT_BOLD
                setTextColor(TEXT)
                gravity = Gravity.CENTER_VERTICAL
                maxLines = 2
            }, LinearLayout.LayoutParams(0, dp(58), 1f))
            val check = CheckBox(this).apply {
                textSize = 11f
                isChecked = registered[i]
            }
            refreshRegistrationLabel(check, i)
            checks.add(check)
            check.setOnCheckedChangeListener { _, value ->
                registered[i] = value
                refreshRegistrationLabel(check, i)
                refreshSummary()
                updateFilter()
            }
            row.addView(check, LinearLayout.LayoutParams(dp(132), dp(58)))
            rowEntries.add(row to i)
            list.addView(row, LinearLayout.LayoutParams(-1, -2).apply { bottomMargin = dp(6) })
        }
        search.addTextChangedListener(object : android.text.TextWatcher {
            override fun beforeTextChanged(s: CharSequence?, start: Int, count: Int, after: Int) = Unit
            override fun onTextChanged(s: CharSequence?, start: Int, before: Int, count: Int) = updateFilter()
            override fun afterTextChanged(s: android.text.Editable?) = Unit
        })
        generationFilter.onItemSelectedListener = object : AdapterView.OnItemSelectedListener {
            override fun onItemSelected(
                parent: AdapterView<*>?,
                view: View?,
                position: Int,
                id: Long
            ) = updateFilter()

            override fun onNothingSelected(parent: AdapterView<*>?) = Unit
        }
        sortOrder.onItemSelectedListener = object : AdapterView.OnItemSelectedListener {
            override fun onItemSelected(
                parent: AdapterView<*>?,
                view: View?,
                position: Int,
                id: Long
            ) = updateFilter()

            override fun onNothingSelected(parent: AdapterView<*>?) = Unit
        }
        registeredOnly.setOnCheckedChangeListener { _, checked ->
            if (checked) unregisteredOnly.isChecked = false
            updateFilter()
        }
        unregisteredOnly.setOnCheckedChangeListener { _, checked ->
            if (checked) registeredOnly.isChecked = false
            updateFilter()
        }
        pendingOnly.setOnCheckedChangeListener { _, checked ->
            if (checked) {
                pendingRegistrationsOnly.isChecked = false
                pendingClearsOnly.isChecked = false
            }
            updateFilter()
        }
        pendingRegistrationsOnly.setOnCheckedChangeListener { _, checked ->
            if (checked) {
                pendingOnly.isChecked = false
                pendingClearsOnly.isChecked = false
            }
            updateFilter()
        }
        pendingClearsOnly.setOnCheckedChangeListener { _, checked ->
            if (checked) {
                pendingOnly.isChecked = false
                pendingRegistrationsOnly.isChecked = false
            }
            updateFilter()
        }
        addButton(root, "Reset Pokédex Filters") {
            search.setText("")
            generationFilter.setSelection(0)
            sortOrder.setSelection(0)
            registeredOnly.isChecked = false
            unregisteredOnly.isChecked = false
            pendingOnly.isChecked = false
            pendingRegistrationsOnly.isChecked = false
            pendingClearsOnly.isChecked = false
            updateFilter()
        }
        refreshSummary()
        updateFilter()
        root.addView(list)
        root.addView(reviewAcknowledged)
        root.addView(TextView(this).apply {
            text = "Safe saving"
            textSize = 17f
            typeface = Typeface.DEFAULT_BOLD
            setTextColor(TEXT)
            setPadding(dp(4), dp(16), dp(4), dp(4))
        })
        root.addView(TextView(this).apply {
            text = "PSE creates and pins a recovery backup, changes only the four Pokédex mirrors plus their section checksums, then reopens the save and verifies the result. A failed write restores the original bytes."
            textSize = 13f
            setTextColor(MUTED)
            setPadding(dp(4), 0, dp(4), dp(10))
        })
        addButton(root, "Save Pokédex") {
            val pending = Gen3PokedexEditing.summarizeChanges(loadedRegistration, registered)
            if (pending.total == 0) {
                showDialog("Gen 3 Pokédex", "No registration flags have changed, so nothing was written.")
                return@addButton
            }
            if (!Gen3PokedexEditing.readyToSave(loadedRegistration, registered, reviewAcknowledged.isChecked)) {
                showDialog("Review required", "Open Review Pending Pokédex Changes and choose Reviewed before saving. Any later edit requires a fresh review.")
                return@addButton
            }
            val original = runCatching { file.readBytes() }.getOrElse {
                showDialog("Gen 3 Pokédex edit failed", "The fresh save could not be read. Nothing was changed.")
                return@addButton
            }
            var writeStarted = false
            try {
                require(generationForSize(original.size) == 3 && gen3SaveValid(original)) {
                    "The fresh save is no longer a valid Generation 3 save."
                }
                require(gen3PokedexState(original).contentEquals(originalState)) {
                    "The save changed while this screen was open. Reopen the Pokédex editor before saving."
                }
                require(gen3PokedexMirrorsAgree(original)) {
                    "The four Pokédex mirrors changed or became inconsistent. Nothing was written."
                }
                val freshLayout = gen3PokedexLayout(original) ?: error("The active Pokédex sections could not be mapped.")
                val work = original.copyOf()
                for (base in freshLayout.mirrors) {
                    for (i in 0 until 49) work[base + i] = 0
                }
                for (i in registered.indices) {
                    if (!registered[i]) continue
                    val mask = 1 shl (i and 7)
                    val byte = i / 8
                    for (base in freshLayout.mirrors) {
                        work[base + byte] = (work[base + byte].toInt() or mask).toByte()
                    }
                }
                updateGen3SectionChecksumAt(work, freshLayout.section0, 0)
                updateGen3SectionChecksumAt(work, freshLayout.section1, 1)
                if (freshLayout.seenSection != freshLayout.section1) {
                    updateGen3SectionChecksumAt(work, freshLayout.seenSection, freshLayout.seenSectionId)
                }
                require(gen3SaveValid(work)) { "The edited Generation 3 save failed checksum validation." }
                val allowed = HashSet<Int>()
                freshLayout.mirrors.forEach { base -> for (i in 0 until 49) allowed.add(base + i) }
                for (base in intArrayOf(freshLayout.section0, freshLayout.section1, freshLayout.seenSection)) {
                    allowed.add(base + 0xFF6)
                    allowed.add(base + 0xFF7)
                }
                require(work.indices.all { it in allowed || work[it] == original[it] }) {
                    "The Pokédex edit changed unrelated save data."
                }
                val backup = File.createTempFile(backupGameName(file) + "_PreGen3Pokedex_", ".backup", backupsDir())
                backup.writeBytes(original)
                require(backup.readBytes().contentEquals(original)) { "The recovery backup did not verify." }
                retainGen2ToGen3SafetyBackup(backup, original)
                require(importedFile?.absolutePath == file.absolutePath && file.readBytes().contentEquals(original)) {
                    "The active save changed before writing. Nothing was changed."
                }
                writeStarted = true
                file.writeBytes(work)
                val verify = file.readBytes()
                require(verify.contentEquals(work)) { "The save changed while it was being written." }
                require(gen3SaveValid(verify)) { "The persisted save failed checksum validation." }
                require(gen3PokedexState(verify).contentEquals(gen3PokedexState(work))) {
                    "The Pokédex flags did not persist exactly."
                }
                require(gen3PokedexMirrorsAgree(verify)) { "The persisted Pokédex mirrors do not agree." }
                Toast.makeText(this, "Gen 3 Pokédex updated and verified", Toast.LENGTH_LONG).show()
                showPokedexEditor()
            } catch (e: Exception) {
                if (writeStarted) runCatching { file.writeBytes(original) }
                showDialog(
                    "Gen 3 Pokédex edit failed",
                    (e.message ?: "Unknown error") + "\n\n" +
                        if (writeStarted) "The original save was restored where possible." else "Nothing was written."
                )
            }
        }
        addButton(root, "Back to PSE") { showHome() }
        setContentView(ScrollView(this).apply { addView(root) })
    }

    private fun gen2ToGen3DexRegistered(data:ByteArray,dex:Int):Boolean {
        val map=gen3ActiveSectionMap(data)?:return false;val s0=map[0];val s1=map[1];if(s0<0||s1<0||dex !in 1..386)return false
        val bit=dex-1;val mask=1 shl(bit and 7);val byte=bit/8;val game=detectGen3GameFromData(data,currentSourceLabel?:importedFile?.name.orEmpty());val frlg=game.contains("FireRed")||game.contains("LeafGreen");val emerald=game.contains("Emerald")
        val seen2Rel=when{frlg->0x5F8;emerald->0x988;else->0x938};val seen3LargeRel=when{frlg->0x3A18;emerald->0x3B24;else->0x3A8C};val seen3SectionId=1+seen3LargeRel/3968;val seen3Rel=seen3LargeRel%3968;val sSeen3=map[seen3SectionId];if(sSeen3<0)return false
        return intArrayOf(s0+0x28+byte,s0+0x5C+byte,s1+seen2Rel+byte,sSeen3+seen3Rel+byte).all{it in data.indices&&(data[it].toInt() and mask)!=0}
    }

    private data class Gen2Gen3SingleBinding(val uri:Uri?,val label:String?,val destination:ByteArray,val bank:ByteArray)

    private fun retainGen2ToGen3SafetyBackup(file:File,expected:ByteArray) {
        require(file.isFile&&file.readBytes().contentEquals(expected)&&generationForSize(expected.size)==3&&gen3SaveValid(expected)){"The Gen 3 destination recovery backup did not verify."}
        val names=keptBackupNames().apply{add(file.name)}
        val prefs=getSharedPreferences("pse_backup_state",MODE_PRIVATE)
        require(prefs.edit().putStringSet("kept",names).commit()){"The destination recovery backup Keep pin could not be saved. Nothing may be written."}
        require(prefs.getStringSet("kept",emptySet())?.contains(file.name)==true&&file.readBytes().contentEquals(expected)){"The destination recovery backup or Keep pin could not be rechecked."}
    }

    private fun prepareGen2ToGen3Transfer(bankFile:File,shown:Gen2Pokemon,openedFile:File,confirmed:Gen2ToGen3LegalisePlan?=null,binding:Gen2Gen3SingleBinding?=null){
        val openedUri=if(binding==null)currentSourceUri else binding.uri;val openedLabel=if(binding==null)currentSourceLabel else binding.label
        fun bound()=importedFile?.absolutePath==openedFile.absolutePath&&currentSourceUri==openedUri&&currentSourceLabel==openedLabel
        if(!bound()){showDialog("Gen 2 → Gen 3","The destination identity or original snapshots changed. Reopen PSE Bank. Nothing was changed.");return}
        var metadataConsumed=false;var legaliseConsumed=false
        if(importedFile?.absolutePath!=openedFile.absolutePath)return showDialog("Gen 2 → Gen 3","The active save changed after the Bank entry opened. Reopen PSE Bank. Nothing was changed.")
        val file=openedFile;val destination=runCatching{file.readBytes()}.getOrNull()?:return showDialog("Gen 2 → Gen 3","PSE could not read the destination save.")
        if(generationForSize(destination.size)!=3||!gen3SaveValid(destination))return showDialog("Gen 2 → Gen 3","Load a valid Generation 3 save first.")
        val bank=runCatching{bankFile.readBytes()}.getOrNull()?:return showDialog("Gen 2 → Gen 3","PSE could not read the selected Gen 2 Bank record.");val source=parseGen2BankPayload(bank)?:return showDialog("Gen 2 → Gen 3","The selected Gen 2 Bank record is invalid.")
        if(binding!=null&&(!destination.contentEquals(binding.destination)||!bank.contentEquals(binding.bank))){showDialog("Gen 2 → Gen 3","The destination identity or original snapshots changed. Reopen PSE Bank. Nothing was changed.");return}
        fun snapshotsMatch()=bound()&&runCatching{file.readBytes().contentEquals(destination)&&bankFile.readBytes().contentEquals(bank)}.getOrDefault(false)
        if(!sameGen2BankRecord(source,shown))return showDialog("Gen 2 → Gen 3","The selected Gen 2 Bank record changed. Nothing was changed.")
        if(source.isEgg||source.heldItem in GEN2_MAIL_ITEM_IDS)return showDialog("Cannot transfer to Gen 3",gen2ToGen3Rejection(source)!!+"\n\nNo safe deterministic Gen 3 representation is available. Both sides were left unchanged.")
        val loading=AlertDialog.Builder(this).setTitle("Prepare Gen 2 → Gen 3").setMessage("Loading verified species, gender and move metadata…").setCancelable(false).create();loading.show()
        loadGen1ToGen7TransferMetaAsync(source.species,source.moves){meta->
            if(metadataConsumed||!snapshotsMatch()){if(loading.isShowing)loading.dismiss();showDialog("Gen 2 → Gen 3","The destination identity or original snapshots changed. Reopen PSE Bank. Nothing was changed.");return@loadGen1ToGen7TransferMetaAsync};metadataConsumed=true
            if(loading.isShowing)loading.dismiss();if(meta==null){showDialog("Gen 2 → Gen 3","PSE could not load the verified conversion metadata. Both sides were left unchanged.");return@loadGen1ToGen7TransferMetaAsync}
            if(importedFile?.absolutePath!=file.absolutePath){showDialog("Gen 2 → Gen 3","The active save changed while conversion metadata was prepared. Reopen PSE Bank. Nothing was changed.");return@loadGen1ToGen7TransferMetaAsync}
            val plan=gen2ToGen3LegalisePlan(source,meta)?:run{showDialog("Cannot transfer to Gen 3",gen2ToGen3Rejection(source,null,meta)?:"No safe deterministic Gen 3 representation is available.");return@loadGen1ToGen7TransferMetaAsync}
            if(confirmed==null){AlertDialog.Builder(this).setTitle("Cannot transfer unchanged").setMessage("${gen2ToGen3Rejection(source,null,meta)}\n\nMake legal for Gen 3 will:\n${gen2ToGen3LegaliseChanges(plan)}\n\nSpecies, nickname, OT/TID, EXP, level, moves, current PP, PP Ups, happiness and Pokérus are preserved. Cancel leaves the Gen 2 Bank record and Gen 3 destination byte-exact; the Bank record is not removed until the destination write verifies.").setNegativeButton("Cancel",null).setPositiveButton("Make legal for Gen 3"){_,_->if(legaliseConsumed){showDialog("Gen 2 → Gen 3","This Legalise confirmation was already submitted. Reopen PSE Bank.");return@setPositiveButton};legaliseConsumed=true;if(!snapshotsMatch()){showDialog("Gen 2 → Gen 3","The destination identity or original snapshots changed. Reopen PSE Bank. Nothing was changed.");return@setPositiveButton};prepareGen2ToGen3Transfer(bankFile,shown,file,plan,Gen2Gen3SingleBinding(openedUri,openedLabel,destination,bank))}.show();return@loadGen1ToGen7TransferMetaAsync}
            if(confirmed!=plan){showDialog("Legalise blocked","The prepared Gen 3 Legalise plan no longer matches this Bank record. Nothing was changed.");return@loadGen1ToGen7TransferMetaAsync}
            val currentBank=runCatching{bankFile.readBytes()}.getOrNull();val currentDestination=runCatching{file.readBytes()}.getOrNull();if(currentBank==null||!currentBank.contentEquals(bank)||currentDestination==null||!currentDestination.contentEquals(destination)||parseGen2BankPayload(currentBank)?.let{sameGen2BankRecord(it,source)}!=true){showDialog("Gen 2 → Gen 3","The source or destination changed while conversion data was prepared. Nothing was changed.");return@loadGen1ToGen7TransferMetaAsync}
            val pk3=try{buildGen2ToGen3Pk3(bank,source,destination,meta,plan)}catch(e:Exception){showDialog("Gen 2 → Gen 3",e.message?:"PSE could not create a verified PK3 conversion.");return@loadGen1ToGen7TransferMetaAsync};val converted=parsePk3(pk3,0,false)?:return@loadGen1ToGen7TransferMetaAsync;chooseGen2ToGen3Destination(bankFile,source,bank,destination,meta,plan,pk3,converted,file,openedUri,openedLabel)
        }
    }

    private fun chooseGen2ToGen3Destination(bankFile:File,source:Gen2Pokemon,bankBytes:ByteArray,destination:ByteArray,meta:Gen1ToGen7TransferMeta,plan:Gen2ToGen3LegalisePlan,pk3:ByteArray,converted:PokemonEntry,openedFile:File,openedUri:Uri?,openedLabel:String?){
        fun bound()=importedFile?.absolutePath==openedFile.absolutePath&&currentSourceUri==openedUri&&currentSourceLabel==openedLabel
        fun snapshotsMatch()=bound()&&runCatching{openedFile.readBytes().contentEquals(destination)&&bankFile.readBytes().contentEquals(bankBytes)}.getOrDefault(false)
        if(!snapshotsMatch()){showDialog("Gen 2 → Gen 3","The destination identity or original snapshots changed. Reopen PSE Bank. Nothing was changed.");return}
        var choiceConsumed=false
        if(importedFile?.absolutePath!=openedFile.absolutePath)return showDialog("Gen 2 → Gen 3","The active save changed before destination selection. Reopen PSE Bank. Nothing was changed.")
        val pc=gen3PcBuffer(destination)?:return showDialog("Gen 2 → Gen 3","PSE could not read Gen 3 PC storage.");val empties=(0 until 420).filter{parsePk3(pc,4+it*80,false)==null};if(empties.isEmpty())return showDialog("Gen 2 → Gen 3","No empty Gen 3 PC slot is available. Nothing was changed.");val first=empties.first()
        AlertDialog.Builder(this).setTitle("Make legal for Gen 3").setMessage("The destination-specific changes shown earlier will be applied to this conversion. A verified kept Gen 3 recovery backup is required before writing; unverified recovery requires reviewing the retained backup and Bank record. The original Gen 2 Bank record remains exact until the native PK3, Gen 3 Pokédex mirrors and all affected section checksums persist and re-open successfully.").setPositiveButton("First Empty (Box ${first/30+1} / Slot ${first%30+1})"){_,_->if(choiceConsumed){showDialog("Gen 2 → Gen 3","This destination choice was already submitted. Reopen PSE Bank.");return@setPositiveButton};choiceConsumed=true;if(!snapshotsMatch()){showDialog("Gen 2 → Gen 3","The destination identity or original snapshots changed. Reopen PSE Bank. Nothing was changed.");return@setPositiveButton};transferGen2BankToGen3(bankFile,source,bankBytes,destination,meta,plan,pk3,converted,first,openedFile,openedUri,openedLabel)}.setNeutralButton("Choose Box / Slot"){_,_->if(choiceConsumed){showDialog("Gen 2 → Gen 3","This destination choice was already submitted. Reopen PSE Bank.");return@setNeutralButton};choiceConsumed=true;if(!snapshotsMatch()){showDialog("Gen 2 → Gen 3","The destination identity or original snapshots changed. Reopen PSE Bank. Nothing was changed.");return@setNeutralButton};showGen2ToGen3BoxPicker(bankFile,source,bankBytes,destination,meta,plan,pk3,converted,pc,openedFile,openedUri,openedLabel)}.setNegativeButton("Cancel",null).show()
    }

    private fun showGen2ToGen3BoxPicker(bankFile:File,source:Gen2Pokemon,bankBytes:ByteArray,destination:ByteArray,meta:Gen1ToGen7TransferMeta,plan:Gen2ToGen3LegalisePlan,pk3:ByteArray,converted:PokemonEntry,pc:ByteArray,openedFile:File,openedUri:Uri?,openedLabel:String?){
        fun bound()=importedFile?.absolutePath==openedFile.absolutePath&&currentSourceUri==openedUri&&currentSourceLabel==openedLabel
        fun snapshotsMatch()=bound()&&runCatching{openedFile.readBytes().contentEquals(destination)&&bankFile.readBytes().contentEquals(bankBytes)}.getOrDefault(false)
        if(!snapshotsMatch()){showDialog("Gen 2 → Gen 3","The destination identity or original snapshots changed. Reopen PSE Bank. Nothing was changed.");return}
        var boxConsumed=false;var transferConsumed=false
        if(importedFile?.absolutePath!=openedFile.absolutePath)return showDialog("Gen 2 → Gen 3","The active save changed before box selection. Reopen PSE Bank. Nothing was changed.")
        val boxes=(0 until 14).filter{b->(0 until 30).any{s->parsePk3(pc,4+(b*30+s)*80,false)==null}};AlertDialog.Builder(this).setTitle("Choose Gen 3 destination box").setItems(boxes.map{"Box ${it+1}"}.toTypedArray()){_,w->if(boxConsumed){showDialog("Gen 2 → Gen 3","This box choice was already submitted. Reopen PSE Bank.");return@setItems};boxConsumed=true;if(!snapshotsMatch()){showDialog("Gen 2 → Gen 3","The destination identity or original snapshots changed. Reopen PSE Bank. Nothing was changed.");return@setItems};val b=boxes[w];val empties=(0 until 30).filter{s->parsePk3(pc,4+(b*30+s)*80,false)==null};AlertDialog.Builder(this).setTitle("Box ${b+1} • choose slot").setItems(empties.map{"Slot ${it+1}"}.toTypedArray()){_,sw->if(transferConsumed){showDialog("Gen 2 → Gen 3","This transfer was already submitted. Reopen PSE Bank.");return@setItems};transferConsumed=true;if(!snapshotsMatch()){showDialog("Gen 2 → Gen 3","The destination identity or original snapshots changed. Reopen PSE Bank. Nothing was changed.");return@setItems};transferGen2BankToGen3(bankFile,source,bankBytes,destination,meta,plan,pk3,converted,b*30+empties[sw],openedFile,openedUri,openedLabel)}.setNegativeButton("Cancel",null).show()}.setNegativeButton("Cancel",null).show()
    }

    private fun transferGen2BankToGen3(bankFile:File,expected:Gen2Pokemon,expectedBank:ByteArray,preparedDestination:ByteArray,meta:Gen1ToGen7TransferMeta,plan:Gen2ToGen3LegalisePlan,preparedPk3:ByteArray,prepared:PokemonEntry,target:Int,openedFile:File,openedUri:Uri?,openedLabel:String?){
        fun bound()=importedFile?.absolutePath==openedFile.absolutePath&&currentSourceUri==openedUri&&currentSourceLabel==openedLabel
        if(!bound()){showDialog("Gen 2 → Gen 3","The destination identity or original snapshots changed. Reopen PSE Bank. Nothing was changed.");return}
        if(importedFile?.absolutePath!=openedFile.absolutePath){showDialog("Gen 2 → Gen 3","The active save changed after destination selection. Reopen PSE Bank. Nothing was changed.");return}
        val file=openedFile;val fresh=runCatching{file.readBytes()}.getOrNull()?:return;var writeStarted=false;var bankDeleteAttempted=false
        var safetyBackup:File?=null
        try{
            require(bound()){"The Gen 3 destination identity changed before transfer validation."}
            require(fresh.contentEquals(preparedDestination)&&generationForSize(fresh.size)==3&&gen3SaveValid(fresh)){"The Gen 3 destination changed or is no longer valid."};require(target in 0 until 420){"The selected Gen 3 destination slot is invalid."}
            val bank=bankFile.readBytes();require(bank.contentEquals(expectedBank)){"The selected Gen 2 Bank bytes changed after confirmation."};val source=parseGen2BankPayload(bank)?:error("The selected Gen 2 Bank record is invalid.");require(sameGen2BankRecord(source,expected)){"The selected Gen 2 Pokémon changed after confirmation."};require(plan==gen2ToGen3LegalisePlan(source,meta)){"The prepared Gen 3 Legalise plan no longer matches the selected Pokémon."};gen2ToGen3Rejection(source,plan,meta)?.let{error(it)}
            val pk3=buildGen2ToGen3Pk3(bank,source,fresh,meta,plan);val converted=parsePk3(pk3,0,false)?:error("The refreshed PK3 could not be parsed.");require(pk3.contentEquals(preparedPk3)&&sameGen2ToGen3Pk3(converted,prepared)){"The prepared PK3 conversion changed before the write."}
            val save=fresh.copyOf();val pc=gen3PcBuffer(save)?:error("Could not reconstruct Gen 3 PC storage.");val beforePc=pc.copyOf();val off=4+target*80;require(parsePk3(pc,off,false)==null){"The destination slot is no longer empty."};pk3.copyInto(pc,off);val staged=parsePk3(pc,off,false)?:error("The staged PK3 could not be parsed.");require(sameGen2ToGen3Pk3(staged,converted)){"The staged PK3 changed."};require(pc.indices.all{it in off until off+pk3.size||pc[it]==beforePc[it]}){"Unrelated Gen 3 PC data changed during staging."}
            writeGen1ToGen3PcAndDexFrozen(save,pc,converted.species);require(gen3SaveValid(save)&&gen2ToGen3DexRegistered(save,converted.species)){"The staged Gen 3 checksums or Pokédex mirrors failed verification."};
            require(bankFile.readBytes().contentEquals(expectedBank)){"The selected Gen 2 Bank record changed during staging."}
            require(importedFile?.absolutePath==file.absolutePath&&file.readBytes().contentEquals(fresh)){"The active Gen 3 destination changed during staging. Nothing was written."}
            require(bound()&&gen3SaveValid(save)){"The staged Gen 3 destination identity or integrity is invalid."}
            val backup=File.createTempFile(backupGameName(file)+"_PreGen2ToGen3Transfer_",".backup",backupsDir());safetyBackup=backup
            backup.writeBytes(fresh);require(backup.readBytes().contentEquals(fresh)){"The exact Gen 3 recovery backup did not verify."};retainGen2ToGen3SafetyBackup(backup,fresh)
            require(bound()&&isBackupKept(backup)&&backup.readBytes().contentEquals(fresh)&&file.readBytes().contentEquals(fresh)&&bankFile.readBytes().contentEquals(expectedBank)){"The Gen 3 destination, Bank record or retained backup changed before writing. Nothing was written."}
            writeStarted=true
            file.writeBytes(save);val written=file.readBytes();require(written.contentEquals(save)&&gen3SaveValid(written)&&gen2ToGen3DexRegistered(written,converted.species)){"The persisted Gen 3 save, checksums or Pokédex mirrors failed verification."};val vpc=gen3PcBuffer(written)?:error("Could not re-open Gen 3 PC storage.");val actual=vpc.copyOfRange(off,off+80);val q=parsePk3(actual,0,false)?:error("The persisted PK3 could not be parsed.");require(actual.contentEquals(pk3)&&sameGen2ToGen3Pk3(q,staged)){"The exact converted PK3 did not persist."};require(vpc.indices.all{it in off until off+80||vpc[it]==beforePc[it]}){"Unrelated Gen 3 PC data changed after persistence."}
            require(importedFile?.absolutePath==file.absolutePath&&file.readBytes().contentEquals(save)){"The verified Gen 3 destination changed before Bank cleanup."}
            require(bound()&&gen3SaveValid(written)){"The Gen 3 destination identity or integrity changed before Bank cleanup."}
            val cleanup=bankFile.readBytes();require(cleanup.contentEquals(expectedBank)&&parseGen2BankPayload(cleanup)?.let{sameGen2BankRecord(it,source)}==true){"The Gen 2 Bank record changed before cleanup."};bankDeleteAttempted=true;require(bankFile.delete()){"The Gen 2 Bank entry could not be removed after destination verification."};require(!bankFile.exists()){"The removed Gen 2 Bank entry still exists."}
            require(bound()){"The Gen 3 destination identity changed after Bank cleanup."}
            require(importedFile?.absolutePath==file.absolutePath&&file.readBytes().contentEquals(save)){"The verified Gen 3 destination changed after Bank cleanup."}
        }catch(e:Exception){
            val bankRestored=if(!writeStarted)true else runCatching{
                if(bankDeleteAttempted&&!bankFile.exists()){
                    require(bankFile.createNewFile()){"The Bank recovery path could not be reserved."}
                    bankFile.writeBytes(expectedBank)
                }
                require(bankFile.readBytes().contentEquals(expectedBank)){"The original Gen 2 Bank record could not be verified; no existing record was overwritten."}
            }.isSuccess
            val destinationRestored=!writeStarted||(bankRestored&&runCatching{file.writeBytes(fresh)}.isSuccess&&runCatching{file.readBytes().contentEquals(fresh)}.getOrDefault(false)&&runCatching{file.readBytes().contentEquals(fresh)&&gen3SaveValid(fresh)}.getOrDefault(false))
            val recovery=if(!writeStarted)"Nothing was written to the save and no Bank record was removed." else  if(bankRestored&&destinationRestored)"The exact Gen 3 destination and Gen 2 Bank record were restored or kept and verified." else  "Automatic recovery could not be verified. Stop editing and keep the working save and remaining Bank record until a verified backup and Bank contents have been reviewed."
            showDialog("Gen 2 → Gen 3 failed",(e.message?:"Unknown error")+"\n\n$recovery"+(safetyBackup?.let{"\n\nRecovery backup: "+it.name}?:""));return
        }
        Toast.makeText(this,"Transferred Gen 2 → Gen 3 to Box ${target/30+1} • Slot ${target%30+1} and verified",Toast.LENGTH_LONG).show();showBank()
    }

    private data class Gen2Gen3BatchPrepared(
        val bankFile:File,val bankBytes:ByteArray,val source:Gen2Pokemon,val meta:Gen1ToGen7TransferMeta,
        val plan:Gen2ToGen3LegalisePlan,val pk3:ByteArray,val converted:PokemonEntry
    )

    private fun gen2ToGen3BatchLegaliseSummary(p:Gen2Pokemon,plan:Gen2ToGen3LegalisePlan):String {
        val specific=ArrayList<String>()
        if(plan.heldItem!=0)specific.add("remove held item #${plan.heldItem}")
        if(plan.caughtData!=0)specific.add("omit caught/met 0x${plan.caughtData.toString(16).uppercase().padStart(4,'0')}")
        if(specific.isEmpty())specific.add("no held-item or caught/met omission")
        return "${p.nickname.ifBlank{"Pokémon #${p.species}"}}: nature ${plan.nature}, ${specific.joinToString(", ")}"
    }

    private data class Gen2Gen3BatchBinding(val uri:Uri?,val label:String?,val destination:ByteArray,val bankImages:List<Pair<String,ByteArray>>)

    private fun prepareSelectedGen2BankToGen3(chosen:List<File>,confirmedPlans:Map<String,Gen2ToGen3LegalisePlan>?=null,openedFile:File?=importedFile,binding:Gen2Gen3BatchBinding?=null){
        val file=openedFile?:return
        val openedUri=if(binding==null)currentSourceUri else binding.uri;val openedLabel=if(binding==null)currentSourceLabel else binding.label
        fun bound()=importedFile?.absolutePath==file.absolutePath&&currentSourceUri==openedUri&&currentSourceLabel==openedLabel
        if(!bound())return showDialog("Gen 2 → Gen 3 multi-transfer","The destination identity changed. Reopen PSE Bank. Nothing was changed.")
        var legaliseConsumed=false
        if(importedFile?.absolutePath!=file.absolutePath)return showDialog("Gen 2 → Gen 3 multi-transfer","The active save changed after preparation. Reopen the Bank selection. Nothing was changed.")
        if(chosen.isEmpty())return showDialog("Gen 2 → Gen 3 multi-transfer","Select one or more Gen 2 Bank Pokémon first.")
        if(chosen.map{it.absolutePath}.distinct().size!=chosen.size)return showDialog("Gen 2 → Gen 3 multi-transfer","The selection contains the same Bank entry more than once. Nothing was changed.")
        val destination=runCatching{file.readBytes()}.getOrNull()?:return showDialog("Gen 2 → Gen 3 multi-transfer","The Gen 3 destination could not be read.")
        if(generationForSize(destination.size)!=3||!gen3SaveValid(destination))return showDialog("Gen 2 → Gen 3 multi-transfer","Load a valid Generation 3 save first.")
        val selected=try{chosen.map{bankFile->
            require(bankFile.isFile&&bankFile.extension.equals("pse2",true)){"A selected Gen 2 Bank record no longer exists."}
            val bytes=bankFile.readBytes();val source=parseGen2BankPayload(bytes)?:error("A selected Gen 2 Bank record is invalid.")
            val hardReason=when{source.isEgg||source.species !in 1..251||source.moves.any{it !in 0..251}||source.heldItem in GEN2_MAIL_ITEM_IDS->gen2ToGen3Rejection(source);else->null}
            require(hardReason==null){"${source.nickname.ifBlank{"Pokémon #${source.species}"}} cannot transfer: $hardReason"}
            Triple(bankFile,bytes,source)
        }}catch(e:Exception){return showDialog("Cannot transfer selection to Gen 3","${e.message?:"A selected Bank record could not be read."}\n\nNo safe deterministic Gen 3 legalisation is available. Every selected Bank record and the destination were left unchanged.")}
        if(binding!=null&&(!destination.contentEquals(binding.destination)||binding.bankImages.size!=selected.size||!binding.bankImages.zip(selected).all{(image,item)->image.first==item.first.absolutePath&&image.second.contentEquals(item.second)}))return showDialog("Gen 2 → Gen 3 multi-transfer","The original destination or ordered Bank selection changed after Legalise confirmation. Nothing was changed.")
        fun snapshotsMatch()=bound()&&runCatching{file.readBytes().contentEquals(destination)&&selected.all{it.first.readBytes().contentEquals(it.second)}}.getOrDefault(false)
        val pc=gen3PcBuffer(destination)?:return showDialog("Gen 2 → Gen 3 multi-transfer","PSE could not reconstruct Gen 3 PC storage. Nothing was changed.")
        val targets=(0 until 14).mapNotNull{box->val empty=(0 until 30).filter{slot->parsePk3(pc,4+(box*30+slot)*80,false)==null};if(empty.size>=selected.size)box to empty else null}
        if(targets.isEmpty())return showDialog("Gen 2 → Gen 3 multi-transfer","No single Gen 3 PC box has room for all ${selected.size} selected Pokémon. Nothing was changed.")
        val prepared=ArrayList<Gen2Gen3BatchPrepared>();val requiredPlans=linkedMapOf<String,Gen2ToGen3LegalisePlan>()
        fun stop(message:String){showDialog("Gen 2 → Gen 3 multi-transfer",message+" Every selected Bank record and the destination were left unchanged.")}
        var expectedIndex=0;var pickerOffered=false;var transferConsumed=false
        fun next(index:Int){
            if(importedFile?.absolutePath!=file.absolutePath)return stop("The active save changed while conversion data was prepared.")
            if(index!=expectedIndex||pickerOffered||!snapshotsMatch())return stop("The destination identity, snapshots or preparation order changed.")
            if(index>=selected.size){
                val currentDestination=runCatching{file.readBytes()}.getOrNull();if(currentDestination==null||!currentDestination.contentEquals(destination))return stop("The Gen 3 destination changed while conversion data was prepared.")
                for((bankFile,bankBytes,source) in selected){val current=runCatching{bankFile.readBytes()}.getOrNull();if(current==null||!current.contentEquals(bankBytes)||parseGen2BankPayload(current)?.let{sameGen2BankRecord(it,source)}!=true)return stop("A selected Gen 2 Bank record changed while conversion data was prepared.")}
                pickerOffered=true
                if(confirmedPlans==null){
                    val summary=prepared.joinToString("\n"){gen2ToGen3BatchLegaliseSummary(it.source,it.plan)}
                    AlertDialog.Builder(this).setTitle("Cannot transfer selection unchanged")
                        .setMessage("Every selected Gen 2 Pokémon needs a deterministic native PK3 conversion. Make legal for Gen 3 will convert Stat Exp to legal EVs, expand DVs into deterministic IVs while preserving gender and shiny state, derive nature from EXP, use the first Gen 3 ability slot, and record the loaded Gen 3 title as the destination origin.\n\nPer-record material changes:\n$summary\n\nSpecies, nickname, OT/TID, EXP, level, moves, current PP, PP Ups, happiness and Pokérus remain preserved. Cancel leaves the destination and every selected Bank record byte-exact. Bank records are removed only after the complete destination write verifies successfully.")
                        .setNegativeButton("Cancel",null)
                        .setPositiveButton("Make legal for Gen 3"){_,_->
                            if(legaliseConsumed){showDialog("Gen 2 → Gen 3 multi-transfer","This Legalise confirmation was already submitted. Reopen PSE Bank.");return@setPositiveButton};legaliseConsumed=true
                            if(!snapshotsMatch()){stop("The destination identity or original snapshots changed after Legalise confirmation.");return@setPositiveButton}
                            prepareSelectedGen2BankToGen3(chosen,requiredPlans,file,Gen2Gen3BatchBinding(openedUri,openedLabel,destination,selected.map{it.first.absolutePath to it.second}))
                        }.show();return
                }
                if(confirmedPlans!=requiredPlans)return stop("The prepared Gen 3 Legalise plan no longer matches this selection.")
                AlertDialog.Builder(this).setTitle("Make ${prepared.size} Pokémon legal for Gen 3")
                    .setMessage("Legalise is confirmed for the complete selection. PSE will place every converted native PK3 in selection order, register all Pokédex mirrors, verify the exact reopened destination, then remove the original Gen 2 Bank records last. Stale state is rejected. A verified kept Gen 3 recovery backup is required before writing. Recovery is reported only after verification; review the retained backup, working save and remaining Bank records if recovery cannot be verified.")
                    .setItems(targets.map{(box,empty)->"Box ${box+1} • ${empty.size} empty slots"}.toTypedArray()){_,which->
                        if(transferConsumed){showDialog("Gen 2 → Gen 3 multi-transfer","This batch transfer was already submitted. Reopen PSE Bank.");return@setItems};transferConsumed=true
                        if(!snapshotsMatch()){stop("The destination identity or prepared snapshots changed before selection.");return@setItems}
                        transferSelectedGen2BankToGen3(prepared,destination,targets[which].first,file,openedUri,openedLabel)
                    }
                    .setNegativeButton("Cancel",null).show();return
            }
            val(bankFile,bankBytes,source)=selected[index]
            var metadataConsumed=false
            loadGen1ToGen7TransferMetaAsync(source.species,source.moves){meta->
                if(importedFile?.absolutePath!=file.absolutePath)return@loadGen1ToGen7TransferMetaAsync stop("The active save changed while conversion data was prepared.")
                if(metadataConsumed||index!=expectedIndex||pickerOffered||!snapshotsMatch())return@loadGen1ToGen7TransferMetaAsync stop("The destination identity, snapshots or metadata callback order changed.")
                metadataConsumed=true
                if(meta==null)return@loadGen1ToGen7TransferMetaAsync stop("PSE could not load verified conversion metadata for ${source.nickname.ifBlank{"Pokémon #${source.species}"}}.")
                val plan=gen2ToGen3LegalisePlan(source,meta)?:return@loadGen1ToGen7TransferMetaAsync stop(gen2ToGen3Rejection(source,null,meta)?:"No safe deterministic Gen 3 representation is available.")
                requiredPlans[bankFile.absolutePath]=plan
                if(confirmedPlans!=null&&confirmedPlans[bankFile.absolutePath]!=plan)return@loadGen1ToGen7TransferMetaAsync stop("The prepared Gen 3 Legalise plan changed for ${source.nickname.ifBlank{"Pokémon #${source.species}"}}.")
                val pk3=try{buildGen2ToGen3Pk3(bankBytes,source,destination,meta,plan)}catch(e:Exception){return@loadGen1ToGen7TransferMetaAsync stop(e.message?:"A selected Pokémon could not be converted.")}
                val converted=parsePk3(pk3,0,false)?:return@loadGen1ToGen7TransferMetaAsync stop("A prepared PK3 conversion could not be parsed.")
                prepared.add(Gen2Gen3BatchPrepared(bankFile,bankBytes,source,meta,plan,pk3,converted));expectedIndex=index+1;next(index+1)
            }
        }
        next(0)
    }

    private fun transferSelectedGen2BankToGen3(prepared:List<Gen2Gen3BatchPrepared>,preparedDestination:ByteArray,targetBox:Int,openedFile:File,openedUri:Uri?,openedLabel:String?){
        fun bound()=importedFile?.absolutePath==openedFile.absolutePath&&currentSourceUri==openedUri&&currentSourceLabel==openedLabel
        if(!bound()){showDialog("Gen 2 → Gen 3 multi-transfer","The destination identity changed. Reopen PSE Bank. Nothing was changed.");return}
        if(importedFile?.absolutePath!=openedFile.absolutePath){showDialog("Gen 2 → Gen 3 multi-transfer","The active save changed after destination selection. Reopen the Bank selection. Nothing was changed.");return}
        val file=openedFile;val fresh=runCatching{file.readBytes()}.getOrNull()?:return;val removed=ArrayList<Pair<File,ByteArray>>();var writeStarted=false
        var safetyBackup:File?=null
        try{
            require(bound()){"The destination identity changed before batch validation."}
            require(prepared.isNotEmpty()){"The prepared selection is empty."};require(prepared.map{it.bankFile.absolutePath}.distinct().size==prepared.size){"The prepared selection contains a duplicate Bank entry."};require(fresh.contentEquals(preparedDestination)&&generationForSize(fresh.size)==3&&gen3SaveValid(fresh)){"The Gen 3 destination changed or is no longer valid."};require(targetBox in 0..13){"The selected Gen 3 destination box is invalid."}
            val refreshed=prepared.map{item->val bank=item.bankFile.readBytes();require(bank.contentEquals(item.bankBytes)){"A selected Gen 2 Bank record changed after preparation."};val source=parseGen2BankPayload(bank)?:error("A selected Gen 2 Bank record is invalid.");require(sameGen2BankRecord(source,item.source)){"A selected Gen 2 Pokémon changed after preparation."};require(item.plan==gen2ToGen3LegalisePlan(source,item.meta)){"A prepared Gen 3 Legalise plan no longer matches a selected Pokémon."};gen2ToGen3Rejection(source,item.plan,item.meta)?.let{error(it)};val pk3=buildGen2ToGen3Pk3(bank,source,fresh,item.meta,item.plan);val converted=parsePk3(pk3,0,false)?:error("A refreshed PK3 could not be parsed.");require(pk3.contentEquals(item.pk3)&&sameGen2ToGen3Pk3(converted,item.converted)){"A prepared PK3 conversion changed before staging."};item}
            val save=fresh.copyOf();val pc=gen3PcBuffer(save)?:error("Could not reconstruct Gen 3 PC storage.");val beforePc=pc.copyOf();val empty=(0 until 30).filter{slot->parsePk3(pc,4+(targetBox*30+slot)*80,false)==null};require(empty.size>=refreshed.size){"Gen 3 Box ${targetBox+1} no longer has room for the complete selection."}
            val expected=ArrayList<Triple<Int,ByteArray,PokemonEntry>>()
            for(i in refreshed.indices){val item=refreshed[i];val target=targetBox*30+empty[i];val off=4+target*80;require(parsePk3(pc,off,false)==null){"A destination slot is no longer empty."};item.pk3.copyInto(pc,off);val staged=parsePk3(pc,off,false)?:error("A staged PK3 could not be parsed.");require(sameGen2ToGen3Pk3(staged,item.converted)){"A staged PK3 changed."};expected.add(Triple(target,item.pk3,staged))}
            val changed=expected.flatMap{(target,bytes,_)->val off=4+target*80;(off until off+bytes.size).toList()}.toHashSet();require(pc.indices.all{it in changed||pc[it]==beforePc[it]}){"Unrelated Gen 3 PC data changed during batch staging."}
            val dexes=expected.map{it.third.species};writeSelectedGen1ToGen3PcAndDexFrozen(save,pc,dexes);require(gen3SaveValid(save)&&dexes.distinct().all{gen2ToGen3DexRegistered(save,it)}){"The staged Gen 3 checksums or Pokédex mirrors failed verification."}
            require(refreshed.all{it.bankFile.readBytes().contentEquals(it.bankBytes)}){"A selected Gen 2 Bank record changed during staging."}
            require(importedFile?.absolutePath==file.absolutePath&&file.readBytes().contentEquals(fresh)){"The active Gen 3 destination changed during staging. Nothing was written."}
            require(bound()&&gen3SaveValid(save)){"The staged Gen 3 destination identity or integrity is invalid."}
            val backup=File.createTempFile(backupGameName(file)+"_PreGen2ToGen3Batch_",".backup",backupsDir());safetyBackup=backup
            backup.writeBytes(fresh);require(backup.readBytes().contentEquals(fresh)){"The exact Gen 3 batch recovery backup did not verify."};retainGen2ToGen3SafetyBackup(backup,fresh)
            require(bound()&&isBackupKept(backup)&&backup.readBytes().contentEquals(fresh)&&file.readBytes().contentEquals(fresh)&&refreshed.all{it.bankFile.readBytes().contentEquals(it.bankBytes)}){"The Gen 3 destination, selected Bank records or retained backup changed before writing. Nothing was written."}
            writeStarted=true
            file.writeBytes(save);val written=file.readBytes();require(written.contentEquals(save)&&gen3SaveValid(written)&&dexes.distinct().all{gen2ToGen3DexRegistered(written,it)}){"The persisted Gen 3 save, checksums or Pokédex mirrors failed verification."};val vpc=gen3PcBuffer(written)?:error("Could not re-open Gen 3 PC storage.")
            for((target,pk3,staged) in expected){val off=4+target*80;val actual=vpc.copyOfRange(off,off+80);val q=parsePk3(actual,0,false)?:error("A persisted PK3 could not be parsed.");require(actual.contentEquals(pk3)&&sameGen2ToGen3Pk3(q,staged)){"An exact converted PK3 did not persist."}};require(vpc.indices.all{it in changed||vpc[it]==beforePc[it]}){"Unrelated Gen 3 PC data changed after batch persistence."}
            require(bound()&&gen3SaveValid(written)){"The Gen 3 destination identity or integrity changed before batch Bank cleanup."}
            for(item in refreshed){require(bound()){"The destination identity changed before a batch Bank cleanup."};require(importedFile?.absolutePath==file.absolutePath&&file.readBytes().contentEquals(save)){"The verified Gen 3 destination changed before Bank cleanup."};val cleanup=item.bankFile.readBytes();require(cleanup.contentEquals(item.bankBytes)&&parseGen2BankPayload(cleanup)?.let{sameGen2BankRecord(it,item.source)}==true){"A selected Gen 2 Bank record changed before cleanup."};removed.add(item.bankFile to item.bankBytes);require(item.bankFile.delete()){"A selected Gen 2 Bank record could not be removed after destination verification."};require(!item.bankFile.exists()){"A removed Gen 2 Bank record still exists."}}
            require(bound()){"The destination identity changed after batch Bank cleanup."}
            require(importedFile?.absolutePath==file.absolutePath&&file.readBytes().contentEquals(save)){"The verified Gen 3 destination changed after Bank cleanup."}
        }catch(e:Exception){
            val bankRestored=if(!writeStarted)true else{
                var restored=true
                for((bank,bytes)in removed){
                    val recovered=runCatching{
                        if(bank.exists())require(bank.readBytes().contentEquals(bytes)){"A Bank recovery path changed; it was not overwritten."}
                        else{require(bank.createNewFile()){"A Bank recovery path could not be reserved."};bank.writeBytes(bytes);require(bank.readBytes().contentEquals(bytes)){"A restored Bank record did not verify."}}
                    }.isSuccess
                    if(!recovered)restored=false
                }
                restored&&prepared.all{runCatching{it.bankFile.readBytes().contentEquals(it.bankBytes)}.getOrDefault(false)}
            }
            val destinationRestored=!writeStarted||(bankRestored&&runCatching{file.writeBytes(fresh)}.isSuccess&&runCatching{file.readBytes().contentEquals(fresh)}.getOrDefault(false)&&runCatching{file.readBytes().contentEquals(fresh)&&gen3SaveValid(fresh)}.getOrDefault(false))
            val recovery=if(!writeStarted)"Nothing was written to the save and no Bank record was removed." else  if(bankRestored&&destinationRestored)"The exact Gen 3 destination and every selected Gen 2 Bank record were restored or kept and verified." else  "Automatic recovery could not be verified. Stop editing and keep the working save and remaining Bank records until a verified backup and Bank contents have been reviewed."
            showDialog("Gen 2 → Gen 3 multi-transfer failed",(e.message?:"Unknown error")+"\n\n$recovery"+(safetyBackup?.let{"\n\nRecovery backup: "+it.name}?:""));return
        }
        selectedBankFiles.clear();bankMultiSelectMode=false;Toast.makeText(this,"Transferred ${prepared.size} Gen 2 Pokémon → Gen 3 Box ${targetBox+1} and verified",Toast.LENGTH_LONG).show();showBank()
    }

    private fun gen2BankOriginGameId(bankBytes:ByteArray):Int {
        val stored=bankBytes.getOrNull(7)?.toInt()?.and(0xFF) ?: 0
        if(stored in 39..41) return stored
        // Legacy PSE2 records only stored GS-vs-Crystal. Crystal is exact; a legacy
        // Gold/Silver record cannot be distinguished, so retain the historical Gold fallback.
        return if((bankBytes.getOrNull(5)?.toInt()?.and(0xFF) ?: 1)==2) 41 else 39
    }

    private fun pseGen2SourceName(gameId:Int):String = when(gameId){
        39 -> "Gold"
        40 -> "Silver"
        41 -> "Crystal"
        else -> "Generation 2"
    }

    private fun gen2TransferGender(p:Gen2Pokemon, genderRate:Int):Int {
        if(genderRate < 0) return 2
        if(genderRate <= 0) return 0
        if(genderRate >= 8) return 1
        val threshold=(genderRate*2).coerceIn(0,16)
        return if(p.dvs.getOrElse(1){0} < threshold) 1 else 0
    }

    private fun currentGen6LanguageId(data:ByteArray):Int {
        if(data.size!=SIZE_G6_XY && data.size!=SIZE_G6_ORAS)return 2
        return (data.getOrNull(STATUS_OFFSET+0x2D)?.toInt() ?: 2) and 0xFF
    }

    private fun gen2ToGen6Ivs(p:Gen2Pokemon):IntArray {
        // Gen2Pokemon stores DVs as HP/Attack/Defense/Speed/Special. Preserve that
        // ordering while expanding each 0..15 DV deterministically into 0..31.
        val hp=p.dvs.getOrElse(0){0}.coerceIn(0,15)
        val atk=p.dvs.getOrElse(1){0}.coerceIn(0,15)
        val def=p.dvs.getOrElse(2){0}.coerceIn(0,15)
        val spe=p.dvs.getOrElse(3){0}.coerceIn(0,15)
        val spc=p.dvs.getOrElse(4){0}.coerceIn(0,15)
        fun iv(dv:Int)=((dv shl 1) or 1).coerceIn(0,31)
        return intArrayOf(iv(hp),iv(atk),iv(def),iv(spe),iv(spc),iv(spc))
    }

    private data class Gen2ToGen4LegalisePlan(
        val species:Int,val heldItem:Int,val caughtData:Int,val nature:Int,val gender:Int,val shiny:Boolean,
        val dvs:List<Int>,val statExp:List<Int>,val happiness:Int,val pokerus:Int,val genderRate:Int,val abilityId:Int
    )

    private fun gen2ToGen4LegalisePlan(p:Gen2Pokemon,meta:Gen1ToGen5Meta):Gen2ToGen4LegalisePlan? {
        if(p.isEgg||p.species !in 1..251||p.moves.any{it !in 0..251}||p.heldItem in GEN2_MAIL_ITEM_IDS||meta.abilityId !in 1..123)return null
        return Gen2ToGen4LegalisePlan(p.species,p.heldItem,p.caughtData,(p.experience%25L).toInt(),gen2TransferGender(p,meta.genderRate),p.shiny,p.dvs.toList(),p.statExp.toList(),p.happiness,p.pokerus,meta.genderRate,meta.abilityId)
    }

    private fun gen2ToGen4LegaliseChanges(plan:Gen2ToGen4LegalisePlan):String = buildString {
        append("• convert Gen 2 Stat Exp into six legal Gen 4 EVs, capped to 510 total\n")
        append("• expand Gen 2 DVs into deterministic Gen 4 IVs while preserving gender and shiny state\n")
        append("• derive nature deterministically from EXP and select the verified Generation 4 ability\n")
        append("• use a Poké Ball and the loaded Gen 4 title as an explicit PSE native conversion marker")
        if(plan.heldItem!=0)append("\n• remove held item #${plan.heldItem}, because Gen 2 and Gen 4 item IDs are not interchangeable")
        if(plan.caughtData!=0)append("\n• omit Gen 2 caught/met value 0x${plan.caughtData.toString(16).uppercase().padStart(4,'0')}, whose packed layout has no exact PK4 representation")
    }

    private fun gen2ToGen4Rejection(p:Gen2Pokemon,plan:Gen2ToGen4LegalisePlan?=null,meta:Gen1ToGen5Meta?=null):String? = when {
        p.isEgg -> "Gen 2 Egg state cannot yet be converted into a verified native Gen 4 Egg."
        p.species !in 1..251 -> "Species #${p.species} is not a valid Generation 2 species."
        p.moves.any{it !in 0..251} -> "This Pokémon contains a move outside the Generation 2 move catalogue."
        p.heldItem in GEN2_MAIL_ITEM_IDS -> "Held Mail and its message state cannot be represented safely by this Gen 4 conversion."
        meta==null -> "Verified species, ability and gender metadata are required before this conversion can be prepared."
        meta.abilityId !in 1..123 -> "A verified Generation 4 ability could not be selected for this species."
        plan==null -> "Generation 2 DVs, Stat Exp, item IDs and caught-origin data cannot transfer unchanged into a native PK4."
        plan!=gen2ToGen4LegalisePlan(p,meta) -> "The prepared Gen 4 Legalise plan no longer matches this Pokémon."
        else -> null
    }

    private fun gen2ToGen4Pid(p:Gen2Pokemon,plan:Gen2ToGen4LegalisePlan):Long {
        val sid=0;val desiredParity=0 // The selected verified ability is slot 1.
        fun genderForLow(low:Int):Int {
            if(plan.genderRate<0)return 2
            if(plan.genderRate<=0)return 0
            if(plan.genderRate>=8)return 1
            val threshold=(plan.genderRate*32).coerceIn(0,256)
            return if((low and 0xFF)<threshold)1 else 0
        }
        fun genderMatches(low:Int):Boolean = when(plan.gender){2->true;1->genderForLow(low)==1;else->genderForLow(low)==0}
        val seed=((p.tid.toLong() shl 16) xor p.experience xor (p.species.toLong() shl 8) xor p.caughtData.toLong() xor 0x47503234L) and 0xFFFFFFFFL
        if(plan.shiny){
            val start=seed.toInt() and 0xFFFF
            for(delta in 0..65535){val lo=(start+delta) and 0xFFFF;if((lo and 1)!=desiredParity||!genderMatches(lo))continue;for(sv in 0..7){val hi=(p.tid xor sid xor lo xor sv) and 0xFFFF;val pid=((hi.toLong() shl 16) or lo.toLong()) and 0xFFFFFFFFL;if((pid%25L).toInt()==plan.nature)return pid}}
        }else{
            var pid=seed
            repeat(2_000_000){val lo=pid.toInt() and 0xFFFF;val sv=p.tid xor sid xor lo xor ((pid.toInt() ushr 16) and 0xFFFF);if((pid.toInt() and 1)==desiredParity&&genderMatches(lo)&&(pid%25L).toInt()==plan.nature&&sv>=8)return pid;pid=(pid+1) and 0xFFFFFFFFL}
        }
        error("PSE could not create a deterministic Gen 4 PID preserving nature, gender and shiny state.")
    }

    private fun sameGen2ToGen4Pk4(a:PokemonEntry,b:PokemonEntry):Boolean =
        a.checksumValid&&b.checksumValid&&a.pid==b.pid&&a.species==b.species&&a.tid==b.tid&&a.sid==b.sid&&a.nickname==b.nickname&&a.otName==b.otName&&a.experience==b.experience&&a.ability==b.ability&&a.abilityNumber==b.abilityNumber&&a.nature==b.nature&&a.gender==b.gender&&a.shiny==b.shiny&&a.originGame==b.originGame&&a.ball==b.ball&&a.metLevel==b.metLevel&&a.language==b.language&&a.heldItem==b.heldItem&&a.friendship==b.friendship&&a.pokerusDays==b.pokerusDays&&a.pokerusStrain==b.pokerusStrain&&!a.isEgg&&!b.isEgg&&a.moves.contentEquals(b.moves)&&a.movePP.contentEquals(b.movePP)&&a.evs.contentEquals(b.evs)&&a.ivs.contentEquals(b.ivs)

    private fun buildGen2ToGen4Pk4(bankBytes:ByteArray,p:Gen2Pokemon,destination:ByteArray,meta:Gen1ToGen5Meta,plan:Gen2ToGen4LegalisePlan):ByteArray {
        require(bankBytes.size==GEN2_BANK_FILE_SIZE){"The preserved Gen 2 Bank record has an unexpected size."};val profile=detectGen4Profile(destination)?:error("A valid Generation 4 destination save is required.");gen2ToGen4Rejection(p,plan,meta)?.let{error(it)}
        val out=ByteArray(136);val pid=gen2ToGen4Pid(p,plan);writeU32LE(out,0,pid);writeU16LE(out,0x08,p.species);writeU16LE(out,0x0A,0);writeU16LE(out,0x0C,p.tid);writeU16LE(out,0x0E,0);writeU32LE(out,0x10,p.experience);out[0x14]=p.happiness.toByte();out[0x15]=meta.abilityId.toByte();out[0x17]=2
        val ev=gen2ToGen3Evs(p);for(i in 0..5)out[0x18+i]=ev[i].toByte()
        val o=GEN2_BANK_HEADER_SIZE;for(i in 0..3){writeU16LE(out,0x28+i*2,p.moves[i]);out[0x30+i]=bankBytes[o+23+i]};val ivs=gen2ToGen6Ivs(p);var ivw=0L;for(i in 0..5)ivw=ivw or ((ivs[i].toLong() and 31L) shl(i*5));val speciesName=builtinGen2SpeciesMeta(p.species)?.name?:GEN2_NATIONAL_NAMES.getOrElse(p.species-1){"Pokemon"};val custom=p.nickname.isNotBlank()&&!p.nickname.equals(speciesName,true);if(custom)ivw=ivw or 0x80000000L;writeU32LE(out,0x38,ivw)
        out[0x40]=when(plan.gender){2->4;1->2;else->0}.toByte();writeGen4String(out,0x48,22,if(custom)p.nickname else speciesName);out[0x5F]=when(profile.family){"Platinum"->12;"HeartGold / SoulSilver"->7;else->10}.toByte();writeGen4String(out,0x68,16,p.otName);out[0x82]=p.pokerus.toByte();out[0x83]=4;out[0x84]=p.level.coerceIn(1,100).toByte()
        val encrypted=encryptPk4(out);val q=parsePk4(encrypted,false)?:error("The converted PK4 could not be parsed.");require(q.checksumValid&&q.species==p.species&&q.tid==p.tid&&q.sid==0&&q.nickname==(if(custom)p.nickname else speciesName)&&q.otName==p.otName&&q.experience==p.experience&&q.ability==meta.abilityId&&q.abilityNumber==1&&q.nature==plan.nature&&q.gender==plan.gender&&q.shiny==p.shiny&&q.heldItem==0&&q.friendship==p.happiness&&q.pokerusDays==(p.pokerus and 0xF)&&q.pokerusStrain==((p.pokerus ushr 4) and 0xF)&&q.moves.contentEquals(p.moves)&&q.movePP.contentEquals(p.movePP)&&q.evs.contentEquals(ev)&&q.ivs.contentEquals(ivs)){"The converted PK4 did not preserve every destination-representable field."};return encrypted
    }

    private data class Gen2Gen4SingleBinding(val uri:Uri?,val label:String?,val destination:ByteArray,val bank:ByteArray)

    private fun validGen2ToGen4Destination(data:ByteArray):Boolean=runCatching{
        val profile=detectGen4Profile(data)?:return@runCatching false
        val validation=gen4Validation(data,profile)
        validation.generalChecksum&&validation.storageChecksum&&validation.badPk4==0
    }.getOrDefault(false)

    private fun retainGen2ToGen4SafetyBackup(file:File,expected:ByteArray) {
        require(file.isFile&&file.readBytes().contentEquals(expected)&&validGen2ToGen4Destination(expected)){"The Gen 4 destination recovery backup did not verify."}
        val names=keptBackupNames().apply{add(file.name)}
        val prefs=getSharedPreferences("pse_backup_state",MODE_PRIVATE)
        require(prefs.edit().putStringSet("kept",names).commit()){"The destination recovery backup Keep pin could not be saved. Nothing may be written."}
        require(prefs.getStringSet("kept",emptySet())?.contains(file.name)==true&&file.readBytes().contentEquals(expected)){"The destination recovery backup or Keep pin could not be rechecked."}
    }

    private fun prepareGen2ToGen4Transfer(bankFile:File,shown:Gen2Pokemon,openedFile:File,confirmed:Gen2ToGen4LegalisePlan?=null,binding:Gen2Gen4SingleBinding?=null){
        val openedUri=if(binding==null)currentSourceUri else binding.uri;val openedLabel=if(binding==null)currentSourceLabel else binding.label
        fun bound()=importedFile?.absolutePath==openedFile.absolutePath&&currentSourceUri==openedUri&&currentSourceLabel==openedLabel
        if(!bound()){showDialog("Gen 2 → Gen 4","The destination identity changed. Reopen PSE Bank. Nothing was changed.");return}
        var metadataConsumed=false;var legaliseConsumed=false;var transferConsumed=false
        if(importedFile?.absolutePath!=openedFile.absolutePath)return showDialog("Gen 2 → Gen 4","The active save changed after the Bank entry opened. Reopen PSE Bank. Nothing was changed.")
        val file=openedFile;val bank=runCatching{bankFile.readBytes()}.getOrNull()?:return showDialog("Gen 2 → Gen 4","PSE could not read the preserved Gen 2 Bank entry.");val source=parseGen2BankPayload(bank)?:return showDialog("Gen 2 → Gen 4","The selected Gen 2 Bank record is invalid.");if(!sameGen2BankRecord(source,shown))return showDialog("Gen 2 → Gen 4","The selected Gen 2 Bank record changed. Nothing was changed.")
        val destination=runCatching{file.readBytes()}.getOrNull()?:return showDialog("Gen 2 → Gen 4","PSE could not read the destination save.");val profile=detectGen4Profile(destination)?:return showDialog("Gen 2 → Gen 4","Load a valid Generation 4 save first.");val validation=gen4Validation(destination,profile);if(!validation.generalChecksum||!validation.storageChecksum||validation.badPk4!=0)return showDialog("Gen 2 → Gen 4","The Gen 4 destination did not pass whole-save validation.");if(source.isEgg||source.heldItem in GEN2_MAIL_ITEM_IDS)return showDialog("Cannot transfer to Gen 4",gen2ToGen4Rejection(source)!!+"\n\nNo safe deterministic Gen 4 representation is available. Both sides were left unchanged.")
        if(binding!=null&&(!destination.contentEquals(binding.destination)||!bank.contentEquals(binding.bank))){showDialog("Gen 2 → Gen 4","The original destination or Bank snapshot changed after Legalise confirmation. Nothing was changed.");return}
        fun snapshotsMatch()=bound()&&runCatching{file.readBytes().contentEquals(destination)&&bankFile.readBytes().contentEquals(bank)}.getOrDefault(false)
        val loading=AlertDialog.Builder(this).setTitle("Prepare Gen 2 → Gen 4").setMessage("Loading verified species, ability and gender metadata…").setCancelable(false).create();loading.show();loadGen1ToGen5MetaAsync(source.species){meta->
            if(metadataConsumed||!snapshotsMatch()){if(loading.isShowing)loading.dismiss();showDialog("Gen 2 → Gen 4","The destination identity or original snapshots changed. Reopen PSE Bank. Nothing was changed.");return@loadGen1ToGen5MetaAsync};metadataConsumed=true
            if(loading.isShowing)loading.dismiss();if(meta==null){showDialog("Gen 2 → Gen 4","PSE could not load the verified conversion metadata. Both sides were left unchanged.");return@loadGen1ToGen5MetaAsync};
            if(importedFile?.absolutePath!=file.absolutePath){showDialog("Gen 2 → Gen 4","The active save changed while conversion metadata was prepared. Reopen PSE Bank. Nothing was changed.");return@loadGen1ToGen5MetaAsync}
            val plan=gen2ToGen4LegalisePlan(source,meta)?:run{showDialog("Cannot transfer to Gen 4",gen2ToGen4Rejection(source,null,meta)?:"No safe deterministic Gen 4 representation is available.");return@loadGen1ToGen5MetaAsync}
            if(confirmed==null){AlertDialog.Builder(this).setTitle("Cannot transfer unchanged").setMessage("${gen2ToGen4Rejection(source,null,meta)}\n\nMake legal for Gen 4 will:\n${gen2ToGen4LegaliseChanges(plan)}\n\nSpecies, nickname, OT/TID, EXP, level, moves, current PP, PP Ups, happiness and Pokérus are preserved. Cancel leaves the Gen 2 Bank record and Gen 4 destination byte-exact; the Bank record is not removed until the destination write verifies.").setNegativeButton("Cancel",null).setPositiveButton("Make legal for Gen 4"){_,_->if(legaliseConsumed){showDialog("Gen 2 → Gen 4","This Legalise confirmation was already submitted. Reopen PSE Bank.");return@setPositiveButton};legaliseConsumed=true;if(!snapshotsMatch()){showDialog("Gen 2 → Gen 4","The destination identity or original snapshots changed. Nothing was changed.");return@setPositiveButton};prepareGen2ToGen4Transfer(bankFile,shown,file,plan,Gen2Gen4SingleBinding(openedUri,openedLabel,destination,bank))}.show();return@loadGen1ToGen5MetaAsync}
            if(confirmed!=plan){showDialog("Legalise blocked","The prepared Gen 4 Legalise plan no longer matches this Bank record. Nothing was changed.");return@loadGen1ToGen5MetaAsync};val currentBank=runCatching{bankFile.readBytes()}.getOrNull();val currentDestination=runCatching{file.readBytes()}.getOrNull();if(currentBank==null||!currentBank.contentEquals(bank)||parseGen2BankPayload(currentBank)?.let{sameGen2BankRecord(it,source)}!=true||currentDestination==null||!currentDestination.contentEquals(destination)){showDialog("Gen 2 → Gen 4","The source or destination changed while conversion data was prepared. Nothing was changed.");return@loadGen1ToGen5MetaAsync}
            val pk4=try{buildGen2ToGen4Pk4(bank,source,destination,meta,plan)}catch(e:Exception){showDialog("Gen 2 → Gen 4",e.message?:"PSE could not create the verified PK4 conversion.");return@loadGen1ToGen5MetaAsync};val converted=parsePk4(pk4,false)?:return@loadGen1ToGen5MetaAsync;val empties=gen4EmptyBoxSlots(destination,profile);if(empties.isEmpty())return@loadGen1ToGen5MetaAsync showDialog("Gen 2 → Gen 4","No empty Gen 4 PC slot is available. Nothing was changed.");val first=empties.first()
            AlertDialog.Builder(this).setTitle("Place legal Gen 4 conversion").setMessage("Legalise is confirmed. PSE will write the deterministic native PK4 to Box ${first/30+1}, Slot ${first%30+1}, register the Pokédex entry, rebuild Gen 4 checksums, and re-open the exact result before removing the original Gen 2 Bank record. A verified kept Gen 4 recovery backup is required before writing; if recovery cannot be verified, review the retained backup, working save and Bank record.").setNegativeButton("Cancel",null).setPositiveButton("First Empty (${first/30+1}/${first%30+1})"){_,_->if(transferConsumed){showDialog("Gen 2 → Gen 4","This transfer was already submitted. Reopen PSE Bank.");return@setPositiveButton};transferConsumed=true;if(!snapshotsMatch()){showDialog("Gen 2 → Gen 4","The destination identity or prepared snapshots changed. Nothing was changed.");return@setPositiveButton};transferGen2BankToGen4(bankFile,source,bank,destination,meta,plan,pk4,converted,first,file,openedUri,openedLabel)}.show()
        }
    }

    private fun transferGen2BankToGen4(bankFile:File,expected:Gen2Pokemon,expectedBank:ByteArray,preparedDestination:ByteArray,meta:Gen1ToGen5Meta,plan:Gen2ToGen4LegalisePlan,preparedPk4:ByteArray,prepared:PokemonEntry,target:Int,openedFile:File,openedUri:Uri?,openedLabel:String?){
        fun bound()=importedFile?.absolutePath==openedFile.absolutePath&&currentSourceUri==openedUri&&currentSourceLabel==openedLabel
        if(!bound()){showDialog("Gen 2 → Gen 4","The destination identity changed. Reopen PSE Bank. Nothing was changed.");return}
        if(importedFile?.absolutePath!=openedFile.absolutePath){showDialog("Gen 2 → Gen 4","The active save changed after destination selection. Reopen PSE Bank. Nothing was changed.");return}
        val file=openedFile;val fresh=runCatching{file.readBytes()}.getOrNull()?:return;var writeStarted=false;var bankDeleteAttempted=false
        var safetyBackup:File?=null
        try{require(bound()){"The Gen 4 destination identity changed before validation."};require(fresh.contentEquals(preparedDestination)){"The Gen 4 destination changed while the conversion was prepared."};require(target in 0 until 540){"Invalid Gen 4 PC slot."};val profile=detectGen4Profile(fresh)?:error("The destination is no longer a valid Gen 4 save.");val before=gen4Validation(fresh,profile);require(before.generalChecksum&&before.storageChecksum&&before.badPk4==0){"The fresh Gen 4 destination failed validation."};val off=gen4BoxSlotOffset(fresh,profile,target);require(parsePk4(fresh.copyOfRange(off,off+136),false)==null){"The destination slot is no longer empty."}
            val bank=bankFile.readBytes();require(bank.contentEquals(expectedBank)){"The selected Gen 2 Bank bytes changed after confirmation."};val source=parseGen2BankPayload(bank)?:error("The selected Gen 2 Bank record is invalid.");require(sameGen2BankRecord(source,expected)){"The selected Gen 2 Pokémon changed after confirmation."};require(plan==gen2ToGen4LegalisePlan(source,meta)){"The prepared Gen 4 Legalise plan no longer matches the selected Pokémon."};gen2ToGen4Rejection(source,plan,meta)?.let{error(it)};val pk4=buildGen2ToGen4Pk4(bank,source,fresh,meta,plan);val converted=parsePk4(pk4,false)?:error("The refreshed PK4 could not be parsed.");require(pk4.contentEquals(preparedPk4)&&sameGen2ToGen4Pk4(converted,prepared)){"The prepared PK4 conversion changed before staging."}
            val work=fresh.copyOf();pk4.copyInto(work,off);val staged=parsePk4(work.copyOfRange(off,off+136),false)?:error("The staged PK4 could not be parsed.");require(sameGen2ToGen4Pk4(staged,converted)){"The staged PK4 did not preserve every converted field."};registerGen1ToGen4Pokedex(work,profile,staged.species);val storage=gen4ActiveBlock(work,profile.storageStart,profile.storageSize);updateGen4BlockChecksum(work,storage*0x40000+profile.storageStart,profile.storageSize,profile);val stagedValidation=gen4Validation(work,profile);require(stagedValidation.generalChecksum&&stagedValidation.storageChecksum&&stagedValidation.badPk4==0&&gen1ToGen4DexRegistered(work,profile,staged.species)){"The staged Gen 4 save, PK4 or Pokédex failed verification."}
            require(bankFile.readBytes().contentEquals(expectedBank)){"The selected Gen 2 Bank record changed during staging."}
            require(importedFile?.absolutePath==file.absolutePath&&file.readBytes().contentEquals(fresh)){"The active Gen 4 destination changed during staging. Nothing was written."}
            require(bound()&&validGen2ToGen4Destination(work)){"The staged Gen 4 destination identity or integrity is invalid."}
            val backup=File.createTempFile(backupGameName(file)+"_PreGen2ToGen4Transfer_",".backup",backupsDir());safetyBackup=backup
            backup.writeBytes(fresh);require(backup.readBytes().contentEquals(fresh)){"The exact Gen 4 recovery backup did not verify."};retainGen2ToGen4SafetyBackup(backup,fresh)
            require(bound()&&isBackupKept(backup)&&backup.readBytes().contentEquals(fresh)&&file.readBytes().contentEquals(fresh)&&bankFile.readBytes().contentEquals(expectedBank)){"The Gen 4 destination, Bank record or retained backup changed before writing. Nothing was written."}
            writeStarted=true
            file.writeBytes(work);val written=file.readBytes();require(written.contentEquals(work)){"The destination changed while it was written."};val wp=detectGen4Profile(written)?:error("The persisted Gen 4 layout could not be re-read.");val after=gen4Validation(written,wp);require(after.generalChecksum&&after.storageChecksum&&after.badPk4==0&&gen1ToGen4DexRegistered(written,wp,staged.species)){"The persisted Gen 4 save failed verification."};val actual=written.copyOfRange(gen4BoxSlotOffset(written,wp,target),gen4BoxSlotOffset(written,wp,target)+136);val q=parsePk4(actual,false)?:error("The persisted PK4 could not be parsed.");require(actual.contentEquals(pk4)&&sameGen2ToGen4Pk4(q,staged)){"The exact converted PK4 did not persist."};
            require(importedFile?.absolutePath==file.absolutePath&&file.readBytes().contentEquals(work)){"The verified Gen 4 destination changed before Bank cleanup."}
            require(bound()&&validGen2ToGen4Destination(written)){"The Gen 4 destination identity or integrity changed before Bank cleanup."}
            val cleanup=bankFile.readBytes();require(cleanup.contentEquals(expectedBank)&&parseGen2BankPayload(cleanup)?.let{sameGen2BankRecord(it,source)}==true){"The Gen 2 Bank record changed before cleanup."};bankDeleteAttempted=true;require(bankFile.delete()){"The Gen 2 Bank entry could not be removed after destination verification."};require(!bankFile.exists()){"The removed Gen 2 Bank entry still exists."}
            require(bound()){"The Gen 4 destination identity changed after Bank cleanup."}
            require(importedFile?.absolutePath==file.absolutePath&&file.readBytes().contentEquals(work)){"The verified Gen 4 destination changed after Bank cleanup."}
        }catch(e:Exception){
            val bankRestored=if(!writeStarted)true else runCatching{
                if(bankDeleteAttempted&&!bankFile.exists()){
                    require(bankFile.createNewFile()){"The Bank recovery path could not be reserved."}
                    bankFile.writeBytes(expectedBank)
                }
                require(bankFile.readBytes().contentEquals(expectedBank)){"The original Gen 2 Bank record could not be verified; no existing record was overwritten."}
            }.isSuccess
            val destinationRestored=!writeStarted||(bankRestored&&runCatching{file.writeBytes(fresh)}.isSuccess&&runCatching{file.readBytes().contentEquals(fresh)}.getOrDefault(false)&&runCatching{file.readBytes().contentEquals(fresh)&&validGen2ToGen4Destination(fresh)}.getOrDefault(false))
            val recovery=if(!writeStarted)"Nothing was written to the save and no Bank record was removed." else  if(bankRestored&&destinationRestored)"The exact Gen 4 destination and Gen 2 Bank record were restored or kept and verified." else  "Automatic recovery could not be verified. Stop editing and keep the working save and remaining Bank record until a verified backup and Bank contents have been reviewed."
            showDialog("Gen 2 → Gen 4 failed",(e.message?:"Unknown error")+"\n\n$recovery"+(safetyBackup?.let{"\n\nRecovery backup: "+it.name}?:""));return
        }
        Toast.makeText(this,"Transferred Gen 2 → Gen 4 to Box ${target/30+1} • Slot ${target%30+1} and verified",Toast.LENGTH_LONG).show();showBank()
    }

    private data class Gen2Gen4BatchPrepared(
        val bankFile:File,val bankBytes:ByteArray,val source:Gen2Pokemon,val meta:Gen1ToGen5Meta,
        val plan:Gen2ToGen4LegalisePlan,val pk4:ByteArray,val converted:PokemonEntry
    )

    private fun gen2ToGen4BatchLegaliseSummary(p:Gen2Pokemon,plan:Gen2ToGen4LegalisePlan):String {
        val specific=ArrayList<String>()
        if(plan.heldItem!=0)specific.add("remove held item #${plan.heldItem}")
        if(plan.caughtData!=0)specific.add("omit caught/met 0x${plan.caughtData.toString(16).uppercase().padStart(4,'0')}")
        if(specific.isEmpty())specific.add("no held-item or caught/met omission")
        return "${p.nickname.ifBlank{"Pokémon #${p.species}"}}: nature ${plan.nature}, ${specific.joinToString(", ")}"
    }

    private data class Gen2Gen4BatchBinding(val uri:Uri?,val label:String?,val destination:ByteArray,val bankImages:List<Pair<String,ByteArray>>)

    private fun prepareSelectedGen2BankToGen4(chosen:List<File>,confirmedPlans:Map<String,Gen2ToGen4LegalisePlan>?=null,openedFile:File?=importedFile,binding:Gen2Gen4BatchBinding?=null){
        val file=openedFile?:return
        val openedUri=if(binding==null)currentSourceUri else binding.uri;val openedLabel=if(binding==null)currentSourceLabel else binding.label
        fun bound()=importedFile?.absolutePath==file.absolutePath&&currentSourceUri==openedUri&&currentSourceLabel==openedLabel
        if(!bound())return showDialog("Gen 2 → Gen 4 multi-transfer","The destination identity changed. Reopen PSE Bank. Nothing was changed.")
        var legaliseConsumed=false
        if(importedFile?.absolutePath!=file.absolutePath)return showDialog("Gen 2 → Gen 4 multi-transfer","The active save changed after preparation. Reopen the Bank selection. Nothing was changed.")
        if(chosen.isEmpty())return showDialog("Gen 2 → Gen 4 multi-transfer","Select one or more Gen 2 Bank Pokémon first.")
        if(chosen.map{it.absolutePath}.distinct().size!=chosen.size)return showDialog("Gen 2 → Gen 4 multi-transfer","The selection contains the same Bank entry more than once. Nothing was changed.")
        val destination=runCatching{file.readBytes()}.getOrNull()?:return showDialog("Gen 2 → Gen 4 multi-transfer","The Gen 4 destination could not be read.")
        val profile=detectGen4Profile(destination)?:return showDialog("Gen 2 → Gen 4 multi-transfer","Load a valid Generation 4 save first.")
        val validation=gen4Validation(destination,profile);if(!validation.generalChecksum||!validation.storageChecksum||validation.badPk4!=0)return showDialog("Gen 2 → Gen 4 multi-transfer","The Gen 4 destination did not pass whole-save validation.")
        val selected=try{chosen.map{bankFile->
            require(bankFile.isFile&&bankFile.extension.equals("pse2",true)){"A selected Gen 2 Bank record no longer exists."}
            val bytes=bankFile.readBytes();val source=parseGen2BankPayload(bytes)?:error("A selected Gen 2 Bank record is invalid.")
            val hardReason=when{source.isEgg||source.species !in 1..251||source.moves.any{it !in 0..251}||source.heldItem in GEN2_MAIL_ITEM_IDS->gen2ToGen4Rejection(source);else->null}
            require(hardReason==null){"${source.nickname.ifBlank{"Pokémon #${source.species}"}} cannot transfer: $hardReason"};Triple(bankFile,bytes,source)
        }}catch(e:Exception){return showDialog("Cannot transfer selection to Gen 4","${e.message?:"A selected Bank record could not be read."}\n\nNo safe deterministic Gen 4 legalisation is available. Every selected Bank record and the destination were left unchanged.")}
        if(binding!=null&&(!destination.contentEquals(binding.destination)||binding.bankImages.size!=selected.size||!binding.bankImages.zip(selected).all{(image,item)->image.first==item.first.absolutePath&&image.second.contentEquals(item.second)}))return showDialog("Gen 2 → Gen 4 multi-transfer","The original destination or ordered Bank selection changed after Legalise confirmation. Nothing was changed.")
        fun snapshotsMatch()=bound()&&runCatching{file.readBytes().contentEquals(destination)&&selected.all{it.first.readBytes().contentEquals(it.second)}}.getOrDefault(false)
        val targets=(0 until 18).mapNotNull{box->val empty=(0 until 30).filter{slot->val off=gen4BoxSlotOffset(destination,profile,box*30+slot);parsePk4(destination.copyOfRange(off,off+136),false)==null};if(empty.size>=selected.size)box to empty else null}
        if(targets.isEmpty())return showDialog("Gen 2 → Gen 4 multi-transfer","No single Gen 4 PC box has room for all ${selected.size} selected Pokémon. Nothing was changed.")
        val prepared=ArrayList<Gen2Gen4BatchPrepared>();val requiredPlans=linkedMapOf<String,Gen2ToGen4LegalisePlan>()
        fun stop(message:String){showDialog("Gen 2 → Gen 4 multi-transfer",message+" Every selected Bank record and the destination were left unchanged.")}
        var expectedIndex=0;var pickerOffered=false;var transferConsumed=false
        fun next(index:Int){
            if(importedFile?.absolutePath!=file.absolutePath)return stop("The active save changed while conversion data was prepared.")
            if(index!=expectedIndex||pickerOffered||!snapshotsMatch())return stop("The destination identity, snapshots or preparation order changed.")
            if(index>=selected.size){
                val currentDestination=runCatching{file.readBytes()}.getOrNull();if(currentDestination==null||!currentDestination.contentEquals(destination))return stop("The Gen 4 destination changed while conversion data was prepared.")
                for((bankFile,bankBytes,source) in selected){val current=runCatching{bankFile.readBytes()}.getOrNull();if(current==null||!current.contentEquals(bankBytes)||parseGen2BankPayload(current)?.let{sameGen2BankRecord(it,source)}!=true)return stop("A selected Gen 2 Bank record changed while conversion data was prepared.")}
                pickerOffered=true
                if(confirmedPlans==null){
                    val summary=prepared.joinToString("\n"){gen2ToGen4BatchLegaliseSummary(it.source,it.plan)}
                    AlertDialog.Builder(this).setTitle("Cannot transfer selection unchanged")
                        .setMessage("Every selected Gen 2 Pokémon needs a deterministic native PK4 conversion. Make legal for Gen 4 will convert Stat Exp to legal EVs, expand DVs into deterministic IVs while preserving gender and shiny state, derive nature from EXP, select a verified Gen 4 ability, and mark the loaded Gen 4 title as destination origin.\n\nPer-record material changes:\n$summary\n\nSpecies, nickname, OT/TID, EXP, level, moves, current PP, PP Ups, happiness and Pokérus remain preserved. Cancel leaves the destination and every selected Bank record byte-exact. Bank records are removed only after the complete destination write verifies successfully.")
                        .setNegativeButton("Cancel",null).setPositiveButton("Make legal for Gen 4"){_,_->
                            if(legaliseConsumed){showDialog("Gen 2 → Gen 4 multi-transfer","This Legalise confirmation was already submitted. Reopen PSE Bank.");return@setPositiveButton};legaliseConsumed=true
                            if(!snapshotsMatch()){stop("The destination identity or original snapshots changed after Legalise confirmation.");return@setPositiveButton}
                            prepareSelectedGen2BankToGen4(chosen,requiredPlans,file,Gen2Gen4BatchBinding(openedUri,openedLabel,destination,selected.map{it.first.absolutePath to it.second}))
                        }.show();return
                }
                if(confirmedPlans!=requiredPlans)return stop("The prepared Gen 4 Legalise plan no longer matches this selection.")
                AlertDialog.Builder(this).setTitle("Make ${prepared.size} Pokémon legal for Gen 4")
                    .setMessage("Legalise is confirmed for the complete selection. PSE will place every converted native PK4 in selection order, register all Pokédex entries, verify the exact reopened destination, then remove the original Gen 2 Bank records last. Stale state is rejected. A verified kept Gen 4 recovery backup is required before writing. Recovery is reported only after verification; review the retained backup, working save and remaining Bank records if recovery cannot be verified.")
                    .setItems(targets.map{(box,empty)->"Box ${box+1} • ${empty.size} empty slots"}.toTypedArray()){_,which->
                        if(transferConsumed){showDialog("Gen 2 → Gen 4 multi-transfer","This batch transfer was already submitted. Reopen PSE Bank.");return@setItems};transferConsumed=true
                        if(!snapshotsMatch()){stop("The destination identity or prepared snapshots changed before selection.");return@setItems}
                        transferSelectedGen2BankToGen4(prepared,destination,targets[which].first,file,openedUri,openedLabel)
                    }
                    .setNegativeButton("Cancel",null).show();return
            }
            val(bankFile,bankBytes,source)=selected[index]
            var metadataConsumed=false
            loadGen1ToGen5MetaAsync(source.species){meta->
                if(importedFile?.absolutePath!=file.absolutePath)return@loadGen1ToGen5MetaAsync stop("The active save changed while conversion data was prepared.")
                if(metadataConsumed||index!=expectedIndex||pickerOffered||!snapshotsMatch())return@loadGen1ToGen5MetaAsync stop("The destination identity, snapshots or metadata callback order changed.")
                metadataConsumed=true
                if(meta==null)return@loadGen1ToGen5MetaAsync stop("PSE could not load verified conversion metadata for ${source.nickname.ifBlank{"Pokémon #${source.species}"}}.")
                val plan=gen2ToGen4LegalisePlan(source,meta)?:return@loadGen1ToGen5MetaAsync stop(gen2ToGen4Rejection(source,null,meta)?:"No safe deterministic Gen 4 representation is available.")
                requiredPlans[bankFile.absolutePath]=plan
                if(confirmedPlans!=null&&confirmedPlans[bankFile.absolutePath]!=plan)return@loadGen1ToGen5MetaAsync stop("The prepared Gen 4 Legalise plan changed for ${source.nickname.ifBlank{"Pokémon #${source.species}"}}.")
                val pk4=try{buildGen2ToGen4Pk4(bankBytes,source,destination,meta,plan)}catch(e:Exception){return@loadGen1ToGen5MetaAsync stop(e.message?:"A selected Pokémon could not be converted.")}
                val converted=parsePk4(pk4,false)?:return@loadGen1ToGen5MetaAsync stop("A prepared PK4 conversion could not be parsed.")
                prepared.add(Gen2Gen4BatchPrepared(bankFile,bankBytes,source,meta,plan,pk4,converted));expectedIndex=index+1;next(index+1)
            }
        }
        next(0)
    }

    private fun transferSelectedGen2BankToGen4(prepared:List<Gen2Gen4BatchPrepared>,preparedDestination:ByteArray,targetBox:Int,openedFile:File,openedUri:Uri?,openedLabel:String?){
        fun bound()=importedFile?.absolutePath==openedFile.absolutePath&&currentSourceUri==openedUri&&currentSourceLabel==openedLabel
        if(!bound()){showDialog("Gen 2 → Gen 4 multi-transfer","The destination identity changed. Reopen PSE Bank. Nothing was changed.");return}
        if(importedFile?.absolutePath!=openedFile.absolutePath){showDialog("Gen 2 → Gen 4 multi-transfer","The active save changed after destination selection. Reopen the Bank selection. Nothing was changed.");return}
        val file=openedFile;val fresh=runCatching{file.readBytes()}.getOrNull()?:return;val removed=ArrayList<Pair<File,ByteArray>>();var writeStarted=false
        var safetyBackup:File?=null
        try{
            require(bound()){"The destination identity changed before batch validation."}
            require(prepared.isNotEmpty()){"The prepared selection is empty."};require(prepared.map{it.bankFile.absolutePath}.distinct().size==prepared.size){"The prepared selection contains a duplicate Bank entry."};require(fresh.contentEquals(preparedDestination)){"The Gen 4 destination changed after preparation."};require(targetBox in 0..17){"The selected Gen 4 destination box is invalid."}
            val profile=detectGen4Profile(fresh)?:error("The destination is no longer a valid Gen 4 save.");val before=gen4Validation(fresh,profile);require(before.generalChecksum&&before.storageChecksum&&before.badPk4==0){"The fresh Gen 4 destination failed validation."}
            val refreshed=prepared.map{item->val bank=item.bankFile.readBytes();require(bank.contentEquals(item.bankBytes)){"A selected Gen 2 Bank record changed after preparation."};val source=parseGen2BankPayload(bank)?:error("A selected Gen 2 Bank record is invalid.");require(sameGen2BankRecord(source,item.source)){"A selected Gen 2 Pokémon changed after preparation."};require(item.plan==gen2ToGen4LegalisePlan(source,item.meta)){"A prepared Gen 4 Legalise plan no longer matches a selected Pokémon."};gen2ToGen4Rejection(source,item.plan,item.meta)?.let{error(it)};val pk4=buildGen2ToGen4Pk4(bank,source,fresh,item.meta,item.plan);val converted=parsePk4(pk4,false)?:error("A refreshed PK4 could not be parsed.");require(pk4.contentEquals(item.pk4)&&sameGen2ToGen4Pk4(converted,item.converted)){"A prepared PK4 conversion changed before staging."};item}
            val empty=(0 until 30).filter{slot->val off=gen4BoxSlotOffset(fresh,profile,targetBox*30+slot);parsePk4(fresh.copyOfRange(off,off+136),false)==null};require(empty.size>=refreshed.size){"Gen 4 Box ${targetBox+1} no longer has room for the complete selection."}
            val work=fresh.copyOf();val allowed=HashSet<Int>();val expected=ArrayList<Triple<Int,ByteArray,PokemonEntry>>()
            for(i in refreshed.indices){val item=refreshed[i];val target=targetBox*30+empty[i];val off=gen4BoxSlotOffset(work,profile,target);require(parsePk4(work.copyOfRange(off,off+136),false)==null){"A destination slot is no longer empty."};item.pk4.copyInto(work,off);for(x in off until off+136)allowed.add(x);val staged=parsePk4(work.copyOfRange(off,off+136),false)?:error("A staged PK4 could not be parsed.");require(sameGen2ToGen4Pk4(staged,item.converted)){"A staged PK4 did not preserve every converted field."};expected.add(Triple(target,item.pk4,staged))}
            val general=gen4ActiveBlock(work,0,profile.generalSize)*0x40000;val storage=gen4ActiveBlock(work,profile.storageStart,profile.storageSize)*0x40000+profile.storageStart
            for((_,_,mon) in expected){val base=general+gen4PokedexBase(profile);val bit=mon.species-1;allowed.add(base+0x04+bit/8);allowed.add(base+0x44+bit/8);registerGen1ToGen4Pokedex(work,profile,mon.species)}
            allowed.add(general+profile.generalSize-2);allowed.add(general+profile.generalSize-1);allowed.add(storage+profile.storageSize-2);allowed.add(storage+profile.storageSize-1);updateGen4BlockChecksum(work,storage,profile.storageSize,profile)
            require(work.indices.all{it in allowed||work[it]==fresh[it]}){"Unrelated Gen 4 save data changed during batch staging."};val stagedValidation=gen4Validation(work,profile);require(stagedValidation.generalChecksum&&stagedValidation.storageChecksum&&stagedValidation.badPk4==0){"The staged Gen 4 save failed validation."};require(expected.all{gen1ToGen4DexRegistered(work,profile,it.third.species)}){"A staged Gen 4 Pokédex registration failed."}
            require(refreshed.all{it.bankFile.readBytes().contentEquals(it.bankBytes)}){"A selected Gen 2 Bank record changed during staging."}
            require(importedFile?.absolutePath==file.absolutePath&&file.readBytes().contentEquals(fresh)){"The active Gen 4 destination changed during staging. Nothing was written."}
            require(bound()&&validGen2ToGen4Destination(work)){"The staged Gen 4 destination identity or integrity is invalid."}
            val backup=File.createTempFile(backupGameName(file)+"_PreGen2ToGen4Batch_",".backup",backupsDir());safetyBackup=backup
            backup.writeBytes(fresh);require(backup.readBytes().contentEquals(fresh)){"The exact Gen 4 batch recovery backup did not verify."};retainGen2ToGen4SafetyBackup(backup,fresh)
            require(bound()&&isBackupKept(backup)&&backup.readBytes().contentEquals(fresh)&&file.readBytes().contentEquals(fresh)&&refreshed.all{it.bankFile.readBytes().contentEquals(it.bankBytes)}){"The Gen 4 destination, selected Bank records or retained backup changed before writing. Nothing was written."}
            writeStarted=true
            file.writeBytes(work);val written=file.readBytes();require(written.contentEquals(work)){"The destination changed while the batch was written."};val wp=detectGen4Profile(written)?:error("The persisted Gen 4 layout could not be re-read.");val after=gen4Validation(written,wp);require(after.generalChecksum&&after.storageChecksum&&after.badPk4==0){"The persisted Gen 4 save failed validation."};require(written.indices.all{it in allowed||written[it]==fresh[it]}){"Unrelated Gen 4 save data changed after persistence."}
            for((target,pk4,staged) in expected){val off=gen4BoxSlotOffset(written,wp,target);val actual=written.copyOfRange(off,off+136);val q=parsePk4(actual,false)?:error("A persisted PK4 could not be parsed.");require(actual.contentEquals(pk4)&&sameGen2ToGen4Pk4(q,staged)&&gen1ToGen4DexRegistered(written,wp,q.species)){"A persisted PK4 or Pokédex registration did not verify."}}
            require(bound()&&validGen2ToGen4Destination(written)){"The Gen 4 destination identity or integrity changed before batch Bank cleanup."}
            for(item in refreshed){require(bound()){"The destination identity changed before a batch Bank cleanup."};require(importedFile?.absolutePath==file.absolutePath&&file.readBytes().contentEquals(work)){"The verified Gen 4 destination changed before Bank cleanup."};val cleanup=item.bankFile.readBytes();require(cleanup.contentEquals(item.bankBytes)&&parseGen2BankPayload(cleanup)?.let{sameGen2BankRecord(it,item.source)}==true){"A selected Gen 2 Bank record changed before cleanup."};removed.add(item.bankFile to item.bankBytes);require(item.bankFile.delete()){"A selected Gen 2 Bank record could not be removed after destination verification."};require(!item.bankFile.exists()){"A removed Gen 2 Bank record still exists."}}
            require(bound()){"The destination identity changed after batch Bank cleanup."}
            require(importedFile?.absolutePath==file.absolutePath&&file.readBytes().contentEquals(work)){"The verified Gen 4 destination changed after Bank cleanup."}
        }catch(e:Exception){
            val bankRestored=if(!writeStarted)true else{
                var restored=true
                for((bank,bytes)in removed){
                    val recovered=runCatching{
                        if(bank.exists())require(bank.readBytes().contentEquals(bytes)){"A Bank recovery path changed; it was not overwritten."}
                        else{require(bank.createNewFile()){"A Bank recovery path could not be reserved."};bank.writeBytes(bytes);require(bank.readBytes().contentEquals(bytes)){"A restored Bank record did not verify."}}
                    }.isSuccess
                    if(!recovered)restored=false
                }
                restored&&prepared.all{runCatching{it.bankFile.readBytes().contentEquals(it.bankBytes)}.getOrDefault(false)}
            }
            val destinationRestored=!writeStarted||(bankRestored&&runCatching{file.writeBytes(fresh)}.isSuccess&&runCatching{file.readBytes().contentEquals(fresh)}.getOrDefault(false)&&runCatching{file.readBytes().contentEquals(fresh)&&validGen2ToGen4Destination(fresh)}.getOrDefault(false))
            val recovery=if(!writeStarted)"Nothing was written to the save and no Bank record was removed." else  if(bankRestored&&destinationRestored)"The exact Gen 4 destination and every selected Gen 2 Bank record were restored or kept and verified." else  "Automatic recovery could not be verified. Stop editing and keep the working save and remaining Bank records until a verified backup and Bank contents have been reviewed."
            showDialog("Gen 2 → Gen 4 multi-transfer failed",(e.message?:"Unknown error")+"\n\n$recovery"+(safetyBackup?.let{"\n\nRecovery backup: "+it.name}?:""));return
        }
        selectedBankFiles.clear();bankMultiSelectMode=false;Toast.makeText(this,"Transferred ${prepared.size} Gen 2 Pokémon → Gen 4 Box ${targetBox+1} and verified",Toast.LENGTH_LONG).show();showBank()
    }

private data class Gen2ToGen5LegalisePlan(
        val species:Int,val heldItem:Int,val caughtData:Int,val nature:Int,val gender:Int,val shiny:Boolean,
        val dvs:List<Int>,val statExp:List<Int>,val happiness:Int,val pokerus:Int,val genderRate:Int,val abilityId:Int
    )

    private fun gen2ToGen5LegalisePlan(p:Gen2Pokemon,meta:Gen1ToGen5Meta):Gen2ToGen5LegalisePlan? {
        if(p.isEgg||p.species !in 1..251||p.moves.any{it !in 0..251}||p.heldItem in GEN2_MAIL_ITEM_IDS||meta.abilityId !in 1..164)return null
        return Gen2ToGen5LegalisePlan(p.species,p.heldItem,p.caughtData,(p.experience%25L).toInt(),gen2TransferGender(p,meta.genderRate),p.shiny,p.dvs.toList(),p.statExp.toList(),p.happiness,p.pokerus,meta.genderRate,meta.abilityId)
    }

    private fun gen2ToGen5LegaliseChanges(plan:Gen2ToGen5LegalisePlan):String = buildString {
        append("• convert Gen 2 Stat Exp into six Gen 5 EVs, capped to 510 total\n")
        append("• expand Gen 2 DVs deterministically while preserving gender and shiny state\n")
        append("• derive a deterministic nature, select the verified Gen 5 ability, and mark the converted PK5 with the loaded title\n")
        append("• preserve Gen 2 happiness and Pokérus; omit packed caught location/time and preserve recorded OT gender")
        if(plan.heldItem!=0)append("\n• remove held item #"+plan.heldItem+", because Gen 2 item IDs are not interchangeable with Gen 5")
    }

    private fun gen2ToGen5Rejection(p:Gen2Pokemon,plan:Gen2ToGen5LegalisePlan?=null,meta:Gen1ToGen5Meta?=null):String? = when {
        p.isEgg -> "Gen 2 Egg state cannot yet be converted into a verified native Gen 5 Egg."
        p.species !in 1..251 -> "Species #"+p.species+" is not a valid Generation 2 species."
        p.moves.any{it !in 0..251} -> "This Pokémon contains a move outside the Generation 2 move catalogue."
        p.heldItem in GEN2_MAIL_ITEM_IDS -> "Held Mail and its message state cannot be represented safely by this Gen 5 conversion."
        meta==null -> "Verified species, ability and gender metadata are required before this conversion can be prepared."
        meta.abilityId !in 1..164 -> "A verified Generation 5 ability could not be selected for this species."
        plan==null -> "Generation 2 DVs, Stat Exp, held-item IDs and caught-origin data cannot transfer unchanged into a native PK5."
        plan!=gen2ToGen5LegalisePlan(p,meta) -> "The prepared Gen 5 Legalise plan no longer matches this Pokémon."
        else -> null
    }

    private fun gen2ToGen5Evs(statExp:IntArray):IntArray {
        require(statExp.size==5){"Five Gen 2 stat-experience values are required."}
        val special=(statExp[4]/257).coerceIn(0,255)
        // Gen 2 Special is one stat-experience pool; split its mapped budget across both Gen 5 stats.
        val ev=intArrayOf((statExp[0]/257).coerceIn(0,255),(statExp[1]/257).coerceIn(0,255),(statExp[2]/257).coerceIn(0,255),(statExp[3]/257).coerceIn(0,255),(special+1)/2,special/2)
        var total=ev.sum()
        while(total>510){val i=ev.indices.maxByOrNull{ev[it]}?:0;if(ev[i]==0)break;ev[i]--;total--}
        return ev
    }

    private fun buildGen2ToGen5Pk5(bankBytes:ByteArray,p:Gen2Pokemon,destination:ByteArray,meta:Gen1ToGen5Meta,plan:Gen2ToGen5LegalisePlan):ByteArray {
        require(bankBytes.size==GEN2_BANK_FILE_SIZE){"The preserved Gen 2 Bank record has an unexpected size."}
        val profile=detectGen5Profile(destination)?:error("A valid Generation 5 destination save is required.")
        gen2ToGen5Rejection(p,plan,meta)?.let{error(it)}
        val pidSeed=((p.tid.toLong() shl 16) xor p.experience xor (p.species.toLong() shl 8) xor p.caughtData.toLong() xor 0x47503235L) and 0xFFFFFFFFL
        val pid=gen5PidForAbilityAndShiny(pidSeed,p.tid,0,1,plan.shiny)
        val out=ByteArray(136)
        writeU32LE(out,0,pid);writeU16LE(out,0x08,p.species);writeU16LE(out,0x0C,p.tid);writeU16LE(out,0x0E,0);writeU32LE(out,0x10,p.experience)
        out[0x14]=plan.happiness.toByte();out[0x15]=meta.abilityId.toByte();out[0x17]=2
        val ev=gen2ToGen5Evs(p.statExp);for(i in 0..5)out[0x18+i]=ev[i].toByte()
        val bankOffset=GEN2_BANK_HEADER_SIZE
        for(i in 0..3){writeU16LE(out,0x28+i*2,p.moves[i]);out[0x30+i]=bankBytes[bankOffset+23+i]}
        val ivs=gen2ToGen6Ivs(p);var ivWord=0L;for(i in 0..5)ivWord=ivWord or ((ivs[i].toLong() and 31L) shl(i*5));writeU32LE(out,0x38,ivWord)
        out[0x40]=((plan.gender and 3) shl 1).toByte();out[0x41]=plan.nature.toByte()
        val speciesName=builtinGen2SpeciesMeta(p.species)?.name?:GEN2_NATIONAL_NAMES.getOrElse(p.species-1){"Pokemon"}
        val nickname=if(p.nickname.isBlank())speciesName else p.nickname
        writeGen5String(out,0x48,22,nickname,10);out[0x5F]=(if(profile.sequel)22 else 20).toByte();writeGen5String(out,0x68,16,p.otName,7)
        val caughtDetails=decodeGen2CaughtData(plan.caughtData);val otGender=if(caughtDetails?.otGender=="Female")1 else 0
        out[0x82]=plan.pokerus.toByte();out[0x83]=4;out[0x84]=((p.level.coerceIn(1,100) and 0x7F) or (otGender shl 7)).toByte()
        val encrypted=encryptPk5(out);val q=parsePk5(encrypted,false)?:error("The converted PK5 could not be parsed.")
        require(q.checksumValid&&!q.isEgg&&q.species==p.species&&q.tid==p.tid&&q.sid==0&&q.nickname==nickname&&q.otName==p.otName&&q.experience==p.experience&&q.heldItem==0&&q.ability==meta.abilityId&&q.abilityNumber==1&&q.gender==plan.gender&&q.nature==plan.nature&&q.shiny==plan.shiny&&q.friendship==plan.happiness&&q.pokerusDays+((q.pokerusStrain shl 4))==plan.pokerus&&q.ball==4&&q.metLevel==p.level&&q.otGender==otGender&&q.originGame==(if(profile.sequel)22 else 20)&&q.moves.contentEquals(p.moves)&&q.movePP.contentEquals(p.movePP)&&q.ivs.contentEquals(ivs)&&q.evs.contentEquals(ev)){"The converted PK5 failed identity or preserved-state verification."}
        return encrypted
    }

    private fun sameGen2ToGen5Pk5(a:PokemonEntry,b:PokemonEntry):Boolean =
        a.checksumValid&&b.checksumValid&&!a.isEgg&&!b.isEgg&&a.pid==b.pid&&a.species==b.species&&a.tid==b.tid&&a.sid==b.sid&&a.nickname==b.nickname&&a.otName==b.otName&&a.experience==b.experience&&a.heldItem==b.heldItem&&a.ability==b.ability&&a.abilityNumber==b.abilityNumber&&a.gender==b.gender&&a.nature==b.nature&&a.shiny==b.shiny&&a.friendship==b.friendship&&a.pokerusDays==b.pokerusDays&&a.pokerusStrain==b.pokerusStrain&&a.ball==b.ball&&a.metLevel==b.metLevel&&a.otGender==b.otGender&&a.originGame==b.originGame&&a.moves.contentEquals(b.moves)&&a.movePP.contentEquals(b.movePP)&&a.ivs.contentEquals(b.ivs)&&a.evs.contentEquals(b.evs)

    private data class Gen2Gen5SingleBinding(val uri:Uri?,val label:String?,val destination:ByteArray,val bank:ByteArray)

    private fun validGen2ToGen5Destination(data:ByteArray):Boolean=runCatching{
        val profile=detectGen5Profile(data)?:return@runCatching false
        generationForSize(data.size)==5&&gen5ChecksumTableValid(data,profile)&&(0 until 24).all{gen5BoxChecksumValid(data,it,profile)}
    }.getOrDefault(false)

    private fun retainGen2ToGen5SafetyBackup(file:File,expected:ByteArray) {
        require(file.isFile&&file.readBytes().contentEquals(expected)&&validGen2ToGen5Destination(expected)){"The Gen 5 destination recovery backup did not verify."}
        val names=keptBackupNames().apply{add(file.name)}
        val prefs=getSharedPreferences("pse_backup_state",MODE_PRIVATE)
        require(prefs.edit().putStringSet("kept",names).commit()){"The destination recovery backup Keep pin could not be saved. Nothing may be written."}
        require(prefs.getStringSet("kept",emptySet())?.contains(file.name)==true&&file.readBytes().contentEquals(expected)){"The destination recovery backup or Keep pin could not be rechecked."}
    }

    private fun prepareGen2ToGen5Transfer(bankFile:File,shown:Gen2Pokemon,openedFile:File,confirmed:Gen2ToGen5LegalisePlan?=null,binding:Gen2Gen5SingleBinding?=null){
        val openedUri=if(binding==null)currentSourceUri else binding.uri;val openedLabel=if(binding==null)currentSourceLabel else binding.label
        fun bound()=importedFile?.absolutePath==openedFile.absolutePath&&currentSourceUri==openedUri&&currentSourceLabel==openedLabel
        if(!bound()){showDialog("Gen 2 → Gen 5","The destination identity changed. Reopen PSE Bank. Nothing was changed.");return}
        var metadataConsumed=false;var legaliseConsumed=false;var transferConsumed=false
        if(importedFile?.absolutePath!=openedFile.absolutePath)return showDialog("Gen 2 → Gen 5","The active save changed. Reopen PSE Bank. Nothing was changed.")
        val file=openedFile;
        val bank=runCatching{bankFile.readBytes()}.getOrNull()?:return showDialog("Gen 2 → Gen 5","PSE could not read the preserved Gen 2 Bank entry.")
        val source=parseGen2BankPayload(bank)?:return showDialog("Gen 2 → Gen 5","The selected Gen 2 Bank record is invalid.")
        if(!sameGen2BankRecord(source,shown))return showDialog("Gen 2 → Gen 5","The selected Gen 2 Bank record changed. Nothing was changed.")
        val destination=runCatching{file.readBytes()}.getOrNull()?:return showDialog("Gen 2 → Gen 5","PSE could not read the destination save.")
        val profile=detectGen5Profile(destination)?:return showDialog("Gen 2 → Gen 5","Load a valid Generation 5 save first.")
        if(!gen5ChecksumTableValid(destination,profile)||(0 until 24).any{!gen5BoxChecksumValid(destination,it,profile)})return showDialog("Gen 2 → Gen 5","The Gen 5 destination did not pass storage and checksum-table validation.")
        if(source.isEgg||source.heldItem in GEN2_MAIL_ITEM_IDS)return showDialog("Cannot transfer to Gen 5",gen2ToGen5Rejection(source)!!+"\n\nNo safe deterministic Gen 5 representation is available. Both sides were left unchanged.")
        if(binding!=null&&(!destination.contentEquals(binding.destination)||!bank.contentEquals(binding.bank))){showDialog("Gen 2 → Gen 5","The original destination or Bank snapshot changed after Legalise confirmation. Nothing was changed.");return}
        fun snapshotsMatch()=bound()&&runCatching{file.readBytes().contentEquals(destination)&&bankFile.readBytes().contentEquals(bank)}.getOrDefault(false)
        val loading=AlertDialog.Builder(this).setTitle("Prepare Gen 2 → Gen 5").setMessage("Loading verified species, ability and gender metadata…").setCancelable(false).create();loading.show()
        loadGen1ToGen5MetaAsync(source.species){meta->
            if(metadataConsumed||!snapshotsMatch()){if(loading.isShowing)loading.dismiss();showDialog("Gen 2 → Gen 5","The destination identity or original snapshots changed. Reopen PSE Bank. Nothing was changed.");return@loadGen1ToGen5MetaAsync};metadataConsumed=true
            if(loading.isShowing)loading.dismiss()
            if(importedFile?.absolutePath!=file.absolutePath)return@loadGen1ToGen5MetaAsync showDialog("Gen 2 → Gen 5","The active save changed while conversion data was prepared. Reopen PSE Bank. Nothing was changed.")
            if(meta==null)return@loadGen1ToGen5MetaAsync showDialog("Gen 2 → Gen 5","PSE could not load verified conversion metadata. Both sides were left unchanged.")
            val plan=gen2ToGen5LegalisePlan(source,meta)?:run{showDialog("Cannot transfer to Gen 5",gen2ToGen5Rejection(source,null,meta)?:"No safe deterministic Gen 5 representation is available.");return@loadGen1ToGen5MetaAsync}
            if(confirmed==null){AlertDialog.Builder(this).setTitle("Cannot transfer unchanged").setMessage((gen2ToGen5Rejection(source,null,meta)?:"This record requires explicit conversion.")+"\n\nMake legal for Gen 5 will:\n"+gen2ToGen5LegaliseChanges(plan)+"\n\nSpecies, nickname, OT/TID, EXP, level, moves, current PP, happiness and Pokérus are preserved. Cancel leaves the Gen 2 Bank record and Gen 5 destination byte-exact; the Bank record is not removed until the destination write verifies.").setNegativeButton("Cancel",null).setPositiveButton("Make legal for Gen 5"){_,_->if(legaliseConsumed){showDialog("Gen 2 → Gen 5","This Legalise confirmation was already submitted. Reopen PSE Bank.");return@setPositiveButton};legaliseConsumed=true;if(!snapshotsMatch()){showDialog("Gen 2 → Gen 5","The destination identity or original snapshots changed. Nothing was changed.");return@setPositiveButton};prepareGen2ToGen5Transfer(bankFile,shown,file,plan,Gen2Gen5SingleBinding(openedUri,openedLabel,destination,bank))}.show();return@loadGen1ToGen5MetaAsync}
            if(confirmed!=plan)return@loadGen1ToGen5MetaAsync showDialog("Legalise blocked","The prepared Gen 5 Legalise plan no longer matches this Bank record. Nothing was changed.")
            val currentBank=runCatching{bankFile.readBytes()}.getOrNull();val currentDestination=runCatching{file.readBytes()}.getOrNull()
            if(currentBank==null||!currentBank.contentEquals(bank)||parseGen2BankPayload(currentBank)?.let{sameGen2BankRecord(it,source)}!=true||currentDestination==null||!currentDestination.contentEquals(destination))return@loadGen1ToGen5MetaAsync showDialog("Gen 2 → Gen 5","The source or destination changed while conversion data was prepared. Nothing was changed.")
            val pk5=try{buildGen2ToGen5Pk5(bank,source,destination,meta,plan)}catch(e:Exception){return@loadGen1ToGen5MetaAsync showDialog("Gen 2 → Gen 5",e.message?:"Conversion failed")}
            val converted=parsePk5(pk5,false)?:return@loadGen1ToGen5MetaAsync showDialog("Gen 2 → Gen 5","The prepared PK5 could not be reopened and validated.")
            val targets=(0 until 24*30).filter{slot->val off=0x00400+(slot/30)*0x1000+(slot%30)*136;val raw=destination.copyOfRange(off,off+136);parsePk5(raw,false)==null&&raw.all{it==0.toByte()}}
            if(targets.isEmpty())return@loadGen1ToGen5MetaAsync showDialog("Gen 2 → Gen 5","No empty Gen 5 PC slot is available. Nothing was changed.")
            val target=targets.first()
            AlertDialog.Builder(this).setTitle("Convert "+(source.nickname.ifBlank{GEN2_NATIONAL_NAMES.getOrElse(source.species-1){"Pokémon"}})+" to Gen 5").setMessage("PSE will place a verified PK5 in Box "+(target/30+1)+", Slot "+(target%30+1)+", update the Gen 5 Pokédex and box checksums, verify the reopened save, then remove the Bank record last. A verified kept Gen 5 recovery backup is required before writing; if recovery cannot be verified, review the retained backup, working save and Bank record.").setPositiveButton("Transfer"){_,_->if(transferConsumed){showDialog("Gen 2 → Gen 5","This transfer was already submitted. Reopen PSE Bank.");return@setPositiveButton};transferConsumed=true;if(!snapshotsMatch()){showDialog("Gen 2 → Gen 5","The destination identity or prepared snapshots changed. Nothing was changed.");return@setPositiveButton};transferGen2BankToGen5(bankFile,source,bank,destination,meta,plan,pk5,converted,target,file,openedUri,openedLabel)}.setNegativeButton("Cancel",null).show()
        }
    }

    private fun transferGen2BankToGen5(bankFile:File,expected:Gen2Pokemon,expectedBank:ByteArray,preparedDestination:ByteArray,meta:Gen1ToGen5Meta,plan:Gen2ToGen5LegalisePlan,preparedPk5:ByteArray,prepared:PokemonEntry,target:Int,openedFile:File,openedUri:Uri?,openedLabel:String?){
        fun bound()=importedFile?.absolutePath==openedFile.absolutePath&&currentSourceUri==openedUri&&currentSourceLabel==openedLabel
        if(!bound()){showDialog("Gen 2 → Gen 5","The destination identity changed. Reopen PSE Bank. Nothing was changed.");return}
        if(importedFile?.absolutePath!=openedFile.absolutePath){showDialog("Gen 2 → Gen 5","The active save changed after destination selection. Reopen PSE Bank. Nothing was changed.");return}
        val file=openedFile;val original=runCatching{file.readBytes()}.getOrNull()?:return;var writeStarted=false;var bankDeleteAttempted=false
        var safetyBackup:File?=null
        try{
            require(bound()){"The Gen 5 destination identity changed before validation."}
            require(original.contentEquals(preparedDestination)){"The Gen 5 destination changed while the conversion was prepared."}
            val profile=detectGen5Profile(original)?:error("The destination is no longer a valid Gen 5 save.")
            require(generationForSize(original.size)==5&&gen5ChecksumTableValid(original,profile)&&(0 until 24).all{gen5BoxChecksumValid(original,it,profile)}){"The fresh Gen 5 destination failed storage validation."}
            require(target in 0 until 720){"Invalid Gen 5 PC slot."}
            val offset=0x00400+(target/30)*0x1000+(target%30)*136
            val emptySlot=original.copyOfRange(offset,offset+136);require(parsePk5(emptySlot,false)==null&&emptySlot.all{it==0.toByte()}){"The destination slot is no longer structurally empty."}
            val bank=bankFile.readBytes();require(bank.contentEquals(expectedBank)){"The selected Gen 2 Bank bytes changed after confirmation."}
            val source=parseGen2BankPayload(bank)?:error("The selected Gen 2 Bank record is invalid.");require(sameGen2BankRecord(source,expected)){"The selected Gen 2 Pokémon changed after confirmation."}
            require(plan==gen2ToGen5LegalisePlan(source,meta)){"The prepared Gen 5 Legalise plan no longer matches the selected Pokémon."}
            gen2ToGen5Rejection(source,plan,meta)?.let{error(it)}
            val pk5=buildGen2ToGen5Pk5(bank,source,original,meta,plan);val refreshed=parsePk5(pk5,false)?:error("The refreshed PK5 could not be parsed.")
            require(pk5.contentEquals(preparedPk5)&&sameGen2ToGen5Pk5(refreshed,prepared)){"The prepared PK5 conversion changed before staging."}
            val box=target/30;val work=original.copyOf();pk5.copyInto(work,offset)
            val staged=parsePk5(work.copyOfRange(offset,offset+136),false)?:error("The staged PK5 could not be parsed.")
            require(sameGen2ToGen5Pk5(staged,refreshed)){"The staged PK5 did not preserve every converted field."}
            registerGen1ToGen5Pokedex(work,profile,staged);updateGen5BoxChecksum(work,box,profile)
            require(gen5BoxChecksumValid(work,box,profile)&&gen5ChecksumTableValid(work,profile)&&gen1ToGen5DexRegistered(work,profile,staged)){"The staged Gen 5 save, PK5 or Pokédex failed verification."}
            require(bankFile.readBytes().contentEquals(expectedBank)){"The selected Gen 2 Bank record changed during staging."}
            require(importedFile?.absolutePath==file.absolutePath&&file.readBytes().contentEquals(original)){"The active Gen 5 destination changed during staging. Nothing was written."}
            require(bound()&&validGen2ToGen5Destination(work)){"The staged Gen 5 destination identity or integrity is invalid."}
            val backup=File.createTempFile(backupGameName(file)+"_PreGen2ToGen5Transfer_",".backup",backupsDir());safetyBackup=backup
            backup.writeBytes(original);require(backup.readBytes().contentEquals(original)){"The exact Gen 5 recovery backup did not verify."};retainGen2ToGen5SafetyBackup(backup,original)
            require(bound()&&isBackupKept(backup)&&backup.readBytes().contentEquals(original)&&file.readBytes().contentEquals(original)&&bankFile.readBytes().contentEquals(expectedBank)){"The Gen 5 destination, Bank record or retained backup changed before writing. Nothing was written."}
            writeStarted=true
            file.writeBytes(work);val written=file.readBytes();require(written.contentEquals(work)){"The Gen 5 destination changed while it was written."}
            val persistedProfile=detectGen5Profile(written)?:error("The persisted Gen 5 layout could not be re-read.")
            require(gen5BoxChecksumValid(written,box,persistedProfile)&&gen5ChecksumTableValid(written,persistedProfile)&&gen1ToGen5DexRegistered(written,persistedProfile,staged)){"The persisted Gen 5 save failed verification."}
            val actual=written.copyOfRange(offset,offset+136);val verified=parsePk5(actual,false)
            require(actual.contentEquals(pk5)&&verified!=null&&sameGen2ToGen5Pk5(verified,staged)){"The exact converted PK5 did not persist."}
            require(importedFile?.absolutePath==file.absolutePath&&file.readBytes().contentEquals(work)){"The verified Gen 5 destination changed before Bank cleanup."}
            require(bound()&&validGen2ToGen5Destination(written)){"The Gen 5 destination identity or integrity changed before Bank cleanup."}
            val cleanup=bankFile.readBytes();require(cleanup.contentEquals(expectedBank)&&parseGen2BankPayload(cleanup)?.let{sameGen2BankRecord(it,source)}==true){"The Gen 2 Bank record changed before cleanup."}
            bankDeleteAttempted=true;require(bankFile.delete()){"The Gen 2 Bank entry could not be removed after destination verification."};require(!bankFile.exists()){"The removed Gen 2 Bank entry still exists."}
            require(bound()){"The Gen 5 destination identity changed after Bank cleanup."}
            require(importedFile?.absolutePath==file.absolutePath&&file.readBytes().contentEquals(work)){"The verified Gen 5 destination changed after Bank cleanup."}
        }catch(e:Exception){
            val bankRestored=if(!writeStarted)true else runCatching{
                if(bankDeleteAttempted&&!bankFile.exists()){
                    require(bankFile.createNewFile()){"The Bank recovery path could not be reserved."}
                    bankFile.writeBytes(expectedBank)
                }
                require(bankFile.readBytes().contentEquals(expectedBank)){"The original Gen 2 Bank record could not be verified; no existing record was overwritten."}
            }.isSuccess
            val destinationRestored=!writeStarted||(bankRestored&&runCatching{file.writeBytes(original)}.isSuccess&&runCatching{file.readBytes().contentEquals(original)}.getOrDefault(false)&&runCatching{file.readBytes().contentEquals(original)&&validGen2ToGen5Destination(original)}.getOrDefault(false))
            val recovery=if(!writeStarted)"Nothing was written to the save and no Bank record was removed." else  if(bankRestored&&destinationRestored)"The exact Gen 5 destination and Gen 2 Bank record were restored or kept and verified." else  "Automatic recovery could not be verified. Stop editing and keep the working save and remaining Bank record until a verified backup and Bank contents have been reviewed."
            showDialog("Gen 2 → Gen 5 failed",(e.message?:"Unknown error")+"\n\n$recovery"+(safetyBackup?.let{"\n\nRecovery backup: "+it.name}?:""));return
        }
        Toast.makeText(this,"Transferred Gen 2 → Gen 5 to Box "+(target/30+1)+" • Slot "+(target%30+1)+" and verified",Toast.LENGTH_LONG).show();showBank()
    }

        private data class Gen2Gen5BatchPrepared(
        val bankFile:File,val bankBytes:ByteArray,val source:Gen2Pokemon,val meta:Gen1ToGen5Meta,
        val plan:Gen2ToGen5LegalisePlan,val pk5:ByteArray,val converted:PokemonEntry
    )

    private fun gen2ToGen5BatchLegaliseSummary(p:Gen2Pokemon,plan:Gen2ToGen5LegalisePlan):String {
        val changes=gen2ToGen5LegaliseChanges(plan).replace("\n"," • ")
        return "${p.nickname.ifBlank{"Pokémon #${p.species}"}}: $changes"
    }

    private fun gen2ToGen5BoxSlotOffset(globalSlot:Int):Int {
        require(globalSlot in 0 until 720){"Invalid Gen 5 PC slot."}
        return 0x00400+(globalSlot/30)*0x1000+(globalSlot%30)*136
    }

    private data class Gen2Gen5BatchBinding(val uri:Uri?,val label:String?,val destination:ByteArray,val bankImages:List<Pair<String,ByteArray>>)

    private fun prepareSelectedGen2BankToGen5(chosen:List<File>,confirmedPlans:Map<String,Gen2ToGen5LegalisePlan>?=null,openedFile:File?=importedFile,binding:Gen2Gen5BatchBinding?=null){
        val file=openedFile?:return
        val openedUri=if(binding==null)currentSourceUri else binding.uri;val openedLabel=if(binding==null)currentSourceLabel else binding.label
        fun bound()=importedFile?.absolutePath==file.absolutePath&&currentSourceUri==openedUri&&currentSourceLabel==openedLabel
        if(!bound())return showDialog("Gen 2 → Gen 5 multi-transfer","The destination identity changed. Reopen PSE Bank. Nothing was changed.")
        var legaliseConsumed=false
        if(importedFile?.absolutePath!=file.absolutePath)return showDialog("Gen 2 → Gen 5 multi-transfer","The active save changed after preparation. Reopen the Bank selection. Nothing was changed.")
        if(chosen.isEmpty())return showDialog("Gen 2 → Gen 5 multi-transfer","Select one or more Gen 2 Bank Pokémon first.")
        if(chosen.map{it.absolutePath}.distinct().size!=chosen.size)return showDialog("Gen 2 → Gen 5 multi-transfer","The selection contains the same Bank entry more than once. Nothing was changed.")
        val destination=runCatching{file.readBytes()}.getOrNull()?:return showDialog("Gen 2 → Gen 5 multi-transfer","The Gen 5 destination could not be read.")
        val profile=detectGen5Profile(destination)?:return showDialog("Gen 2 → Gen 5 multi-transfer","Load a valid Generation 5 save first.")
        if(generationForSize(destination.size)!=5||!gen5ChecksumTableValid(destination,profile)||(0 until 24).any{!gen5BoxChecksumValid(destination,it,profile)})return showDialog("Gen 2 → Gen 5 multi-transfer","The Gen 5 destination did not pass whole-save storage and checksum validation.")
        val selected=try{chosen.map{bankFile->
            require(bankFile.isFile&&bankFile.extension.equals("pse2",true)){"A selected Gen 2 Bank record no longer exists."}
            val bytes=bankFile.readBytes();val source=parseGen2BankPayload(bytes)?:error("A selected Gen 2 Bank record is invalid.")
            val hardReason=when{source.isEgg||source.species !in 1..251||source.moves.any{it !in 0..251}||source.heldItem in GEN2_MAIL_ITEM_IDS->gen2ToGen5Rejection(source);else->null}
            require(hardReason==null){"${source.nickname.ifBlank{"Pokémon #${source.species}"}} cannot transfer: $hardReason"};Triple(bankFile,bytes,source)
        }}catch(e:Exception){return showDialog("Cannot transfer selection to Gen 5","${e.message?:"A selected Bank record could not be read."}\n\nNo safe deterministic Gen 5 legalisation is available. Every selected Bank record and the destination were left unchanged.")}
        if(binding!=null&&(!destination.contentEquals(binding.destination)||binding.bankImages.size!=selected.size||!binding.bankImages.zip(selected).all{(image,item)->image.first==item.first.absolutePath&&image.second.contentEquals(item.second)}))return showDialog("Gen 2 → Gen 5 multi-transfer","The original destination or ordered Bank selection changed after Legalise confirmation. Nothing was changed.")
        fun snapshotsMatch()=bound()&&runCatching{file.readBytes().contentEquals(destination)&&selected.all{it.first.readBytes().contentEquals(it.second)}}.getOrDefault(false)
        val targets=(0 until 24).mapNotNull{box->val empty=(0 until 30).filter{slot->val off=gen2ToGen5BoxSlotOffset(box*30+slot);val raw=destination.copyOfRange(off,off+136);parsePk5(raw,false)==null&&raw.all{it==0.toByte()}};if(empty.size>=selected.size)box to empty else null}
        if(targets.isEmpty())return showDialog("Gen 2 → Gen 5 multi-transfer","No single Gen 5 PC box has room for all ${selected.size} selected Pokémon. Nothing was changed.")
        val prepared=ArrayList<Gen2Gen5BatchPrepared>();val requiredPlans=linkedMapOf<String,Gen2ToGen5LegalisePlan>()
        fun stop(message:String){showDialog("Gen 2 → Gen 5 multi-transfer",message+" Every selected Bank record and the destination were left unchanged.")}
        var expectedIndex=0;var pickerOffered=false;var transferConsumed=false
        fun next(index:Int){
            if(importedFile?.absolutePath!=file.absolutePath)return stop("The active save changed while conversion data was prepared.")
            if(index!=expectedIndex||pickerOffered||!snapshotsMatch())return stop("The destination identity, snapshots or preparation order changed.")
            if(index>=selected.size){
                val currentDestination=runCatching{file.readBytes()}.getOrNull();if(currentDestination==null||!currentDestination.contentEquals(destination))return stop("The Gen 5 destination changed while conversion data was prepared.")
                for((bankFile,bankBytes,source) in selected){val current=runCatching{bankFile.readBytes()}.getOrNull();if(current==null||!current.contentEquals(bankBytes)||parseGen2BankPayload(current)?.let{sameGen2BankRecord(it,source)}!=true)return stop("A selected Gen 2 Bank record changed while conversion data was prepared.")}
                pickerOffered=true
                if(confirmedPlans==null){
                    val summary=prepared.joinToString("\n"){gen2ToGen5BatchLegaliseSummary(it.source,it.plan)}
                    AlertDialog.Builder(this).setTitle("Cannot transfer selection unchanged")
                        .setMessage("Every selected Gen 2 Pokémon needs a deterministic native PK5 conversion. Make legal for Gen 5 will convert Stat Exp to legal EVs, expand DVs into deterministic IVs while preserving gender and shiny state, derive nature, select a verified ability, apply the loaded Gen 5 title as origin, and preserve OT gender.\n\nPer-record material changes:\n$summary\n\nSpecies, nickname, OT/TID, EXP, level, moves, current PP, happiness and Pokérus remain preserved. Cancel leaves the destination and every selected Bank record byte-exact. Bank records are removed only after the complete destination write verifies successfully.")
                        .setNegativeButton("Cancel",null).setPositiveButton("Make legal for Gen 5"){_,_->
                            if(legaliseConsumed){showDialog("Gen 2 → Gen 5 multi-transfer","This Legalise confirmation was already submitted. Reopen PSE Bank.");return@setPositiveButton};legaliseConsumed=true
                            if(!snapshotsMatch()){stop("The destination identity or original snapshots changed after Legalise confirmation.");return@setPositiveButton}
                            prepareSelectedGen2BankToGen5(chosen,requiredPlans,file,Gen2Gen5BatchBinding(openedUri,openedLabel,destination,selected.map{it.first.absolutePath to it.second}))
                        }.show();return
                }
                if(confirmedPlans!=requiredPlans)return stop("The prepared Gen 5 Legalise plan no longer matches this selection.")
                AlertDialog.Builder(this).setTitle("Make ${prepared.size} Pokémon legal for Gen 5")
                    .setMessage("Legalise is confirmed for the complete selection. PSE will place every converted PK5 in selection order, register each Pokédex entry, update box and checksum-table checksums, verify the exact reopened destination, then remove the original Gen 2 Bank records last. Stale state is rejected. A verified kept Gen 5 recovery backup is required before writing. Recovery is reported only after verification; review the retained backup, working save and remaining Bank records if recovery cannot be verified.")
                    .setItems(targets.map{(box,empty)->"Box ${box+1} • ${empty.size} empty slots"}.toTypedArray()){_,which->
                        if(transferConsumed){showDialog("Gen 2 → Gen 5 multi-transfer","This batch transfer was already submitted. Reopen PSE Bank.");return@setItems};transferConsumed=true
                        if(!snapshotsMatch()){stop("The destination identity or prepared snapshots changed before selection.");return@setItems}
                        transferSelectedGen2BankToGen5(prepared,destination,targets[which].first,file,openedUri,openedLabel)
                    }
                    .setNegativeButton("Cancel",null).show();return
            }
            val(bankFile,bankBytes,source)=selected[index]
            var metadataConsumed=false
            loadGen1ToGen5MetaAsync(source.species){meta->
                if(importedFile?.absolutePath!=file.absolutePath)return@loadGen1ToGen5MetaAsync stop("The active save changed while conversion data was prepared.")
                if(metadataConsumed||index!=expectedIndex||pickerOffered||!snapshotsMatch())return@loadGen1ToGen5MetaAsync stop("The destination identity, snapshots or metadata callback order changed.")
                metadataConsumed=true
                if(meta==null)return@loadGen1ToGen5MetaAsync stop("PSE could not load verified conversion metadata for ${source.nickname.ifBlank{"Pokémon #${source.species}"}}.")
                val plan=gen2ToGen5LegalisePlan(source,meta)?:return@loadGen1ToGen5MetaAsync stop(gen2ToGen5Rejection(source,null,meta)?:"No safe deterministic Gen 5 representation is available.")
                requiredPlans[bankFile.absolutePath]=plan
                if(confirmedPlans!=null&&confirmedPlans[bankFile.absolutePath]!=plan)return@loadGen1ToGen5MetaAsync stop("The prepared Gen 5 Legalise plan changed for ${source.nickname.ifBlank{"Pokémon #${source.species}"}}.")
                val pk5=try{buildGen2ToGen5Pk5(bankBytes,source,destination,meta,plan)}catch(e:Exception){return@loadGen1ToGen5MetaAsync stop(e.message?:"A selected Pokémon could not be converted.")}
                val converted=parsePk5(pk5,false)?:return@loadGen1ToGen5MetaAsync stop("A prepared PK5 conversion could not be parsed.")
                prepared.add(Gen2Gen5BatchPrepared(bankFile,bankBytes,source,meta,plan,pk5,converted));expectedIndex=index+1;next(index+1)
            }
        }
        next(0)
    }

    private fun transferSelectedGen2BankToGen5(prepared:List<Gen2Gen5BatchPrepared>,preparedDestination:ByteArray,targetBox:Int,openedFile:File,openedUri:Uri?,openedLabel:String?){
        fun bound()=importedFile?.absolutePath==openedFile.absolutePath&&currentSourceUri==openedUri&&currentSourceLabel==openedLabel
        if(!bound()){showDialog("Gen 2 → Gen 5 multi-transfer","The destination identity changed. Reopen PSE Bank. Nothing was changed.");return}
        if(importedFile?.absolutePath!=openedFile.absolutePath){showDialog("Gen 2 → Gen 5 multi-transfer","The active save changed after destination selection. Reopen the Bank selection. Nothing was changed.");return}
        val file=openedFile;val fresh=runCatching{file.readBytes()}.getOrNull()?:return;val removed=ArrayList<Pair<File,ByteArray>>();var writeStarted=false
        var safetyBackup:File?=null
        try{
            require(bound()){"The destination identity changed before batch validation."}
            require(prepared.isNotEmpty()){"The prepared selection is empty."};require(prepared.map{it.bankFile.absolutePath}.distinct().size==prepared.size){"The prepared selection contains a duplicate Bank entry."};require(fresh.contentEquals(preparedDestination)){"The Gen 5 destination changed after preparation."}
            require(targetBox in 0 until 24){"The selected Gen 5 destination box is invalid."}
            val profile=detectGen5Profile(fresh)?:error("The destination is no longer a valid Gen 5 save.")
            require(generationForSize(fresh.size)==5&&gen5ChecksumTableValid(fresh,profile)&&(0 until 24).all{gen5BoxChecksumValid(fresh,it,profile)}){"The fresh Gen 5 destination failed storage validation."}
            val refreshed=prepared.map{item->
                val bank=item.bankFile.readBytes();require(bank.contentEquals(item.bankBytes)){"A selected Gen 2 Bank record changed after preparation."}
                val source=parseGen2BankPayload(bank)?:error("A selected Gen 2 Bank record is invalid.");require(sameGen2BankRecord(source,item.source)){"A selected Gen 2 Pokémon changed after preparation."}
                require(item.plan==gen2ToGen5LegalisePlan(source,item.meta)){"A prepared Gen 5 Legalise plan no longer matches a selected Pokémon."}
                gen2ToGen5Rejection(source,item.plan,item.meta)?.let{error(it)}
                val pk5=buildGen2ToGen5Pk5(bank,source,fresh,item.meta,item.plan);val converted=parsePk5(pk5,false)?:error("A refreshed PK5 could not be parsed.")
                require(pk5.contentEquals(item.pk5)&&sameGen2ToGen5Pk5(converted,item.converted)){"A prepared PK5 conversion changed before staging."}
                Gen2Gen5BatchPrepared(item.bankFile,bank,source,item.meta,item.plan,pk5,converted)
            }
            val empty=(0 until 30).filter{slot->val off=gen2ToGen5BoxSlotOffset(targetBox*30+slot);val raw=fresh.copyOfRange(off,off+136);parsePk5(raw,false)==null&&raw.all{it==0.toByte()}}
            require(empty.size>=refreshed.size){"Gen 5 Box ${targetBox+1} no longer has room for the complete selection."}
            val work=fresh.copyOf();val allowed=HashSet<Int>();val expected=ArrayList<Triple<Int,ByteArray,PokemonEntry>>()
            for(i in refreshed.indices){
                val item=refreshed[i];val target=targetBox*30+empty[i];val off=gen2ToGen5BoxSlotOffset(target)
                val raw=work.copyOfRange(off,off+136);require(parsePk5(raw,false)==null&&raw.all{it==0.toByte()}){"A Gen 5 destination slot is no longer structurally empty."}
                item.pk5.copyInto(work,off);for(x in off until off+136)allowed.add(x)
                val staged=parsePk5(work.copyOfRange(off,off+136),false)?:error("A staged PK5 could not be parsed.")
                require(sameGen2ToGen5Pk5(staged,item.converted)){"A staged PK5 did not preserve every converted field."}
                expected.add(Triple(target,item.pk5,staged))
            }
            val dexBase=profile.pokedexOffset
            for((_,_,mon) in expected){
                val bit=mon.species-1;val byte=bit/8;val region=(if(mon.shiny)2 else 0) or (mon.gender and 1)
                allowed.add(dexBase+0x08+byte);allowed.add(dexBase+0x5C+region*0x54+byte)
                for(r in 0..3)allowed.add(dexBase+0x1AC+r*0x54+byte)
                if(mon.species<=493){val langBase=dexBase+(if(profile.sequel)0x328 else 0x320);val langBit=bit*7+1;allowed.add(langBase+langBit/8)}
                registerGen1ToGen5Pokedex(work,profile,mon)
            }
            val(_,dexLocal,dexMirror)=gen5PokedexBlock(profile);for(o in intArrayOf(dexLocal,dexMirror,profile.checksumBlockChecksumOffset))for(n in 0..1)allowed.add(o+n)
            val boxBase=0x00400+targetBox*0x1000;val boxMirror=profile.checksumTable+2+targetBox*2
            for(n in 0..1){allowed.add(boxBase+0x0FF2+n);allowed.add(boxMirror+n)}
            updateGen5BoxChecksum(work,targetBox,profile)
            require(work.indices.all{it in allowed||work[it]==fresh[it]}){"Unrelated Gen 5 save data changed during batch staging."}
            require(gen5ChecksumTableValid(work,profile)&&(0 until 24).all{gen5BoxChecksumValid(work,it,profile)}&&expected.all{gen1ToGen5DexRegistered(work,profile,it.third)}){"The staged Gen 5 boxes, checksum table or Pokédex failed verification."}
            require(refreshed.all{it.bankFile.readBytes().contentEquals(it.bankBytes)}){"A selected Gen 2 Bank record changed during staging."}
            require(importedFile?.absolutePath==file.absolutePath&&file.readBytes().contentEquals(fresh)){"The active Gen 5 destination changed during staging. Nothing was written."}
            require(bound()&&validGen2ToGen5Destination(work)){"The staged Gen 5 destination identity or integrity is invalid."}
            val backup=File.createTempFile(backupGameName(file)+"_PreGen2ToGen5Batch_",".backup",backupsDir());safetyBackup=backup
            backup.writeBytes(fresh);require(backup.readBytes().contentEquals(fresh)){"The exact Gen 5 batch recovery backup did not verify."};retainGen2ToGen5SafetyBackup(backup,fresh)
            require(bound()&&isBackupKept(backup)&&backup.readBytes().contentEquals(fresh)&&file.readBytes().contentEquals(fresh)&&refreshed.all{it.bankFile.readBytes().contentEquals(it.bankBytes)}){"The Gen 5 destination, selected Bank records or retained backup changed before writing. Nothing was written."}
            writeStarted=true
            file.writeBytes(work);val written=file.readBytes();require(written.contentEquals(work)){"The destination changed while the batch was written."}
            val persistedProfile=detectGen5Profile(written)?:error("The persisted Gen 5 layout could not be re-read.")
            require(gen5ChecksumTableValid(written,persistedProfile)&&(0 until 24).all{gen5BoxChecksumValid(written,it,persistedProfile)}){"The persisted Gen 5 save failed validation."}
            require(written.indices.all{it in allowed||written[it]==fresh[it]}){"Unrelated Gen 5 save data changed after persistence."}
            for((target,pk5,staged) in expected){
                val off=gen2ToGen5BoxSlotOffset(target);val actual=written.copyOfRange(off,off+136);val q=parsePk5(actual,false)?:error("A persisted PK5 could not be parsed.")
                require(actual.contentEquals(pk5)&&sameGen2ToGen5Pk5(q,staged)&&gen1ToGen5DexRegistered(written,persistedProfile,q)){"A persisted PK5 or Pokédex registration did not verify."}
            }
            require(bound()&&validGen2ToGen5Destination(written)){"The Gen 5 destination identity or integrity changed before batch Bank cleanup."}
            for(item in refreshed){require(bound()){"The destination identity changed before a batch Bank cleanup."}
                require(importedFile?.absolutePath==file.absolutePath&&file.readBytes().contentEquals(work)){"The verified Gen 5 destination changed before Bank cleanup."}
                val cleanup=item.bankFile.readBytes();require(cleanup.contentEquals(item.bankBytes)&&parseGen2BankPayload(cleanup)?.let{sameGen2BankRecord(it,item.source)}==true){"A selected Gen 2 Bank record changed before cleanup."}
                removed.add(item.bankFile to item.bankBytes);require(item.bankFile.delete()){"A selected Gen 2 Bank record could not be removed after destination verification."};require(!item.bankFile.exists()){"A removed Gen 2 Bank record still exists."}
            }
            require(bound()){"The destination identity changed after batch Bank cleanup."}
            require(importedFile?.absolutePath==file.absolutePath&&file.readBytes().contentEquals(work)){"The verified Gen 5 destination changed after Bank cleanup."}
        }catch(e:Exception){
            val bankRestored=if(!writeStarted)true else{
                var restored=true
                for((bank,bytes) in removed){
                    val recovered=runCatching{
                        if(bank.exists())require(bank.readBytes().contentEquals(bytes)){"An existing Bank recovery path changed; it was not overwritten."}
                        else{require(bank.createNewFile()){"A Bank recovery path could not be reserved."};bank.writeBytes(bytes);require(bank.readBytes().contentEquals(bytes)){"A recovered Bank record did not verify."}}
                    }.isSuccess
                    restored=recovered&&restored
                }
                restored&&prepared.all{runCatching{it.bankFile.readBytes().contentEquals(it.bankBytes)}.getOrDefault(false)}
            }
            val destinationRestored=!writeStarted||(bankRestored&&runCatching{file.writeBytes(fresh)}.isSuccess&&runCatching{file.readBytes().contentEquals(fresh)}.getOrDefault(false)&&runCatching{file.readBytes().contentEquals(fresh)&&validGen2ToGen5Destination(fresh)}.getOrDefault(false))
            val recovery=if(!writeStarted)"Nothing was written to the save and no Bank record was removed." else  if(bankRestored&&destinationRestored)"The exact Gen 5 destination and every selected Gen 2 Bank record were restored or kept and verified." else  "Automatic recovery could not be verified. Stop editing and keep the working save and remaining Bank records until a verified backup and Bank contents have been reviewed."
            showDialog("Gen 2 → Gen 5 multi-transfer failed",(e.message?:"Unknown error")+"\n\n$recovery"+(safetyBackup?.let{"\n\nRecovery backup: "+it.name}?:""));return
        }
        selectedBankFiles.clear();bankMultiSelectMode=false
        Toast.makeText(this,"Transferred ${prepared.size} Gen 2 Pokémon → Gen 5 Box ${targetBox+1} and verified",Toast.LENGTH_LONG).show();showBank()
    }
    private data class Gen2ToGen6LegalisePlan(
        val species:Int,val heldItem:Int,val caughtData:Int,val nature:Int,val gender:Int,val shiny:Boolean,
        val dvs:List<Int>,val statExp:List<Int>,val happiness:Int,val pokerus:Int,val originGame:Int
    )

    private fun gen2ToGen6LegalisePlan(p:Gen2Pokemon,meta:Gen1ToGen7TransferMeta,bankBytes:ByteArray):Gen2ToGen6LegalisePlan? {
        if(bankBytes.size!=GEN2_BANK_FILE_SIZE||p.isEgg||p.species !in 1..251||p.moves.any{it !in 0..251}||p.heldItem in GEN2_MAIL_ITEM_IDS)return null
        return Gen2ToGen6LegalisePlan(p.species,p.heldItem,p.caughtData,(p.experience%25L).toInt(),gen2TransferGender(p,meta.genderRate),p.shiny,p.dvs.toList(),p.statExp.toList(),p.happiness,p.pokerus,gen2BankOriginGameId(bankBytes))
    }

    private fun gen2ToGen6LegaliseChanges(plan:Gen2ToGen6LegalisePlan):String = buildString {
        append("• convert Gen 2 Stat Exp into six legal Gen 6 EVs, capped to 510 total\n")
        append("• expand Gen 2 DVs into deterministic Gen 6 IVs while preserving gender and shiny state\n")
        append("• derive nature deterministically from EXP and select the verified species ability\n")
        append("• use the PSE Johto transfer marker instead of inventing a Gen 6 capture")
        if(plan.heldItem!=0)append("\n• remove held item #${plan.heldItem}, because Gen 2 and Gen 6 item IDs are not interchangeable")
        if(plan.caughtData!=0)append("\n• omit Gen 2 caught/met value 0x${plan.caughtData.toString(16).uppercase().padStart(4,'0')}, whose layout has no exact Gen 6 equivalent")
    }

    private fun gen2ToGen6Rejection(p:Gen2Pokemon,plan:Gen2ToGen6LegalisePlan?=null,meta:Gen1ToGen7TransferMeta?=null,bankBytes:ByteArray?=null):String? = when {
        p.isEgg -> "Gen 2 Egg state cannot yet be converted into a verified native Gen 6 Egg."
        p.species !in 1..251 -> "Species #${p.species} is not a valid Generation 2 species."
        p.moves.any{it !in 0..251} -> "This Pokémon contains a move outside the Generation 2 move catalogue."
        p.heldItem in GEN2_MAIL_ITEM_IDS -> "Held Mail and its message state cannot be represented safely by this Gen 6 conversion."
        meta==null||bankBytes==null -> "Verified species, ability, gender and source metadata are required before this conversion can be prepared."
        plan==null -> "Generation 2 DVs, Stat Exp, nature/ability absence, item IDs and caught-origin data cannot transfer unchanged into a native PK6."
        plan!=gen2ToGen6LegalisePlan(p,meta,bankBytes) -> "The prepared Gen 6 Legalise plan no longer matches this Pokémon."
        else -> null
    }

    private fun sameGen2ToGen6Pk6(a:PokemonEntry,b:PokemonEntry):Boolean = a.checksumValid&&b.checksumValid&&a.pid==b.pid&&a.species==b.species&&a.tid==b.tid&&a.sid==b.sid&&a.nickname==b.nickname&&a.otName==b.otName&&a.experience==b.experience&&a.ability==b.ability&&a.abilityNumber==b.abilityNumber&&a.nature==b.nature&&a.gender==b.gender&&a.shiny==b.shiny&&a.originGame==b.originGame&&a.metLocation==b.metLocation&&a.ball==b.ball&&a.metLevel==b.metLevel&&a.language==b.language&&a.heldItem==b.heldItem&&a.friendship==b.friendship&&a.currentHandler==b.currentHandler&&a.pokerusDays==b.pokerusDays&&a.pokerusStrain==b.pokerusStrain&&a.isEgg==b.isEgg&&a.moves.contentEquals(b.moves)&&a.movePP.contentEquals(b.movePP)&&a.evs.contentEquals(b.evs)&&a.ivs.contentEquals(b.ivs)

    private fun buildGen2ToGen6Pk6(bankBytes:ByteArray,p:Gen2Pokemon,destinationSave:ByteArray,trainer:TrainerData,meta:Gen1ToGen7TransferMeta,plan:Gen2ToGen6LegalisePlan):ByteArray {
        require(!p.isEgg){"Gen 2 Eggs cannot be converted to Gen 6 until egg-specific conversion is implemented."};require(bankBytes.size==GEN2_BANK_FILE_SIZE){"The preserved Gen 2 Bank record has an unexpected size."};require(destinationSave.size==SIZE_G6_XY||destinationSave.size==SIZE_G6_ORAS){"A Generation 6 destination save is required."};require(trainer.gameId in 24..27){"PSE could not identify the loaded Generation 6 title."};gen2ToGen6Rejection(p,plan,meta,bankBytes)?.let{error(it)}
        val pk=ByteArray(PK6_STORED_SIZE);var ec=((p.tid.toLong() shl 16) xor p.experience xor (p.species.toLong() shl 8) xor p.caughtData.toLong() xor 0x47503236L) and 0xFFFFFFFFL;if(ec==0L)ec=1L
        writeU32LE(pk,0x00,ec);writeU16LE(pk,0x04,0);writeU16LE(pk,0x08,p.species);writeU16LE(pk,0x0A,0);writeU16LE(pk,0x0C,p.tid);writeU16LE(pk,0x0E,0);writeU32LE(pk,0x10,p.experience);pk[0x14]=meta.abilityId.toByte();pk[0x15]=meta.abilityNumber.toByte();writeU16LE(pk,0x16,0)
        val pid=forceTransferShinyState((ec xor 0xA5A55A5AL) and 0xFFFFFFFFL,p.tid,p.shiny);writeU32LE(pk,0x18,pid);pk[0x1C]=plan.nature.toByte();pk[0x1D]=((plan.gender and 3) shl 1).toByte();val evs=gen2ToGen3Evs(p);for(i in 0..5)pk[0x1E+i]=evs[i].toByte();pk[0x2B]=p.pokerus.toByte()
        val speciesName=GEN2_NATIONAL_NAMES.getOrElse(p.species-1){error("The Gen 2 species name is unavailable.")};val custom=p.nickname.isNotBlank()&&!p.nickname.equals(speciesName,true);val expectedName=if(custom)p.nickname else speciesName;writeGen6String(pk,0x40,26,expectedName);val o=GEN2_BANK_HEADER_SIZE
        for(i in 0..3){val move=p.moves[i];writeU16LE(pk,0x5A+i*2,move);pk[0x62+i]=if(move==0)0 else p.movePP[i].coerceIn(0,63).toByte();pk[0x66+i]=if(move==0)0 else ((bankBytes[o+23+i].toInt() ushr 6) and 3).toByte()}
        val ivs=gen2ToGen6Ivs(p);var iv32=0L;for(i in 0..5)iv32=iv32 or ((ivs[i].toLong() and 31L) shl (i*5));if(custom)iv32=iv32 or 0x80000000L;writeU32LE(pk,0x74,iv32)
        writeGen6String(pk,0x78,26,trainer.trainerName);pk[0x92]=if(trainer.gender.equals("Female",true))1 else 0;pk[0x93]=1;pk[0xA2]=p.happiness.toByte();writeGen6String(pk,0xB0,26,p.otName);pk[0xCA]=p.happiness.toByte();writeU16LE(pk,0xD8,0);writeU16LE(pk,0xDA,30017);pk[0xDC]=4;pk[0xDD]=(p.level.coerceIn(1,100) and 0x7F).toByte();pk[0xDF]=plan.originGame.toByte();pk[0xE3]=currentGen6LanguageId(destinationSave).coerceIn(1,10).toByte()
        updatePk6Checksum(pk);val enc=encryptPk6(pk);val q=parsePk6(enc,0,PK6_STORED_SIZE,false,721)?:error("The converted PK6 could not be parsed.")
        require(q.checksumValid&&q.species==p.species&&q.tid==p.tid&&q.nickname==expectedName&&q.otName==p.otName&&q.experience==p.experience&&q.ability==meta.abilityId&&q.abilityNumber==meta.abilityNumber&&q.nature==plan.nature&&q.gender==plan.gender&&q.shiny==p.shiny&&q.originGame==plan.originGame&&q.metLocation==30017&&q.ball==4&&q.metLevel==p.level.coerceIn(1,100)&&q.heldItem==0&&q.friendship==p.happiness&&q.pokerusDays==(p.pokerus and 0xF)&&q.pokerusStrain==((p.pokerus ushr 4) and 0xF)&&q.moves.contentEquals(p.moves)&&q.movePP.contentEquals(p.movePP)&&q.evs.contentEquals(evs)&&q.ivs.contentEquals(ivs)){"The converted PK6 did not preserve every destination-representable field."};return enc
    }

    private data class Gen2Gen6SingleBinding(val uri:Uri?,val label:String?,val destination:ByteArray,val bank:ByteArray){var submitted=false}

    private fun validGen2ToGen6Destination(data:ByteArray):Boolean=runCatching{
        generationForSize(data.size)==6&&gen6BoxChecksumValid(data)&&gen6BlockChecksumValid(data,20)
    }.getOrDefault(false)

    private fun retainGen2ToGen6SafetyBackup(file:File,expected:ByteArray) {
        require(file.isFile&&file.readBytes().contentEquals(expected)&&validGen2ToGen6Destination(expected)){"The Gen 6 destination recovery backup did not verify."}
        val names=keptBackupNames().apply{add(file.name)}
        val prefs=getSharedPreferences("pse_backup_state",MODE_PRIVATE)
        require(prefs.edit().putStringSet("kept",names).commit()){"The destination recovery backup Keep pin could not be saved. Nothing may be written."}
        require(prefs.getStringSet("kept",emptySet())?.contains(file.name)==true&&file.readBytes().contentEquals(expected)){"The destination recovery backup or Keep pin could not be rechecked."}
    }

    private fun prepareGen2ToGen6Transfer(bankFile:File,shown:Gen2Pokemon,openedFile:File,confirmed:Gen2ToGen6LegalisePlan?=null,binding:Gen2Gen6SingleBinding?=null){
        val openedUri=if(binding==null)currentSourceUri else binding.uri;val openedLabel=if(binding==null)currentSourceLabel else binding.label
        fun bound()=importedFile?.absolutePath==openedFile.absolutePath&&currentSourceUri==openedUri&&currentSourceLabel==openedLabel
        if(!bound()){showDialog("Gen 2 → Gen 6","The destination identity changed. Reopen PSE Bank. Nothing was changed.");return}
        var metadataConsumed=false;var legaliseConsumed=false
        if(importedFile?.absolutePath!=openedFile.absolutePath)return showDialog("Gen 2 → Gen 6","The active save changed. Reopen PSE Bank. Nothing was changed.")
        val file=openedFile;val bank=runCatching{bankFile.readBytes()}.getOrNull()?:return showDialog("Gen 2 → Gen 6","PSE could not read the preserved Gen 2 Bank entry.");val source=parseGen2BankPayload(bank)?:return showDialog("Gen 2 → Gen 6","The selected Gen 2 Bank record is invalid.");if(!sameGen2BankRecord(source,shown))return showDialog("Gen 2 → Gen 6","The selected Gen 2 Bank record changed. Nothing was changed.")
        val destination=runCatching{file.readBytes()}.getOrNull()?:return showDialog("Gen 2 → Gen 6","PSE could not read the destination save.");if(generationForSize(destination.size)!=6||!gen6BoxChecksumValid(destination)||!gen6BlockChecksumValid(destination,20))return showDialog("Gen 2 → Gen 6","Load a valid Generation 6 save whose PC storage and Pokédex checksums pass.");if(source.isEgg||source.heldItem in GEN2_MAIL_ITEM_IDS)return showDialog("Cannot transfer to Gen 6",gen2ToGen6Rejection(source)!!+"\n\nNo safe deterministic Gen 6 representation is available. Both sides were left unchanged.")
        if(binding!=null&&(!destination.contentEquals(binding.destination)||!bank.contentEquals(binding.bank)||binding.submitted)){showDialog("Gen 2 → Gen 6","The original destination or Bank snapshot changed, or this transfer was already submitted. Nothing was changed.");return}
        val captured=binding?:Gen2Gen6SingleBinding(openedUri,openedLabel,destination,bank)
        fun snapshotsMatch()=!captured.submitted&&bound()&&runCatching{file.readBytes().contentEquals(destination)&&bankFile.readBytes().contentEquals(bank)}.getOrDefault(false)
        val trainer=analyzeSave(file).trainer?:return showDialog("Gen 2 → Gen 6","PSE could not read the destination trainer data.");val loading=AlertDialog.Builder(this).setTitle("Prepare Gen 2 → Gen 6").setMessage("Loading verified species, ability, gender and move metadata…").setCancelable(false).create();loading.show()
        loadGen1ToGen7TransferMetaAsync(source.species,source.moves){meta->
            if(metadataConsumed||!snapshotsMatch()){if(loading.isShowing)loading.dismiss();showDialog("Gen 2 → Gen 6","The destination identity or original snapshots changed. Reopen PSE Bank. Nothing was changed.");return@loadGen1ToGen7TransferMetaAsync};metadataConsumed=true
            if(loading.isShowing)loading.dismiss();if(importedFile?.absolutePath!=file.absolutePath)return@loadGen1ToGen7TransferMetaAsync showDialog("Gen 2 → Gen 6","The active save changed while conversion data was prepared. Reopen PSE Bank. Nothing was changed.");if(meta==null){showDialog("Gen 2 → Gen 6","PSE could not load the verified conversion metadata. Both sides were left unchanged.");return@loadGen1ToGen7TransferMetaAsync};val plan=gen2ToGen6LegalisePlan(source,meta,bank)?:run{showDialog("Cannot transfer to Gen 6",gen2ToGen6Rejection(source,null,meta,bank)?:"No safe deterministic Gen 6 representation is available.");return@loadGen1ToGen7TransferMetaAsync}
            if(confirmed==null){AlertDialog.Builder(this).setTitle("Cannot transfer unchanged").setMessage("${gen2ToGen6Rejection(source,null,meta,bank)}\n\nMake legal for Gen 6 will:\n${gen2ToGen6LegaliseChanges(plan)}\n\nSpecies, nickname, OT/TID, EXP, level, moves, current PP, PP Ups, happiness and Pokérus are preserved. Cancel leaves the Gen 2 Bank record and Gen 6 destination byte-exact; the Bank record is not removed until the destination write verifies.").setNegativeButton("Cancel",null).setPositiveButton("Make legal for Gen 6"){_,_->if(legaliseConsumed||!snapshotsMatch()){showDialog("Gen 2 → Gen 6","This confirmation was already submitted or the original destination and Bank snapshots changed. Nothing was changed.");return@setPositiveButton};legaliseConsumed=true;prepareGen2ToGen6Transfer(bankFile,shown,file,plan,captured)}.show();return@loadGen1ToGen7TransferMetaAsync}
            if(confirmed!=plan){showDialog("Legalise blocked","The prepared Gen 6 Legalise plan no longer matches this Bank record. Nothing was changed.");return@loadGen1ToGen7TransferMetaAsync};val currentBank=runCatching{bankFile.readBytes()}.getOrNull();val currentDestination=runCatching{file.readBytes()}.getOrNull();if(currentBank==null||!currentBank.contentEquals(bank)||parseGen2BankPayload(currentBank)?.let{sameGen2BankRecord(it,source)}!=true||currentDestination==null||!currentDestination.contentEquals(destination)){showDialog("Gen 2 → Gen 6","The source or destination changed while conversion data was prepared. Nothing was changed.");return@loadGen1ToGen7TransferMetaAsync}
            val pk6=try{buildGen2ToGen6Pk6(bank,source,destination,trainer,meta,plan)}catch(e:Exception){showDialog("Gen 2 → Gen 6",e.message?:"PSE could not create the verified PK6 conversion.");return@loadGen1ToGen7TransferMetaAsync};val converted=parsePk6(pk6,0,PK6_STORED_SIZE,false,721)?:return@loadGen1ToGen7TransferMetaAsync;chooseGen2ToGen6Destination(bankFile,source,bank,destination,trainer,meta,plan,pk6,converted,file,captured)
        }
    }

    private fun chooseGen2ToGen6Destination(bankFile:File,source:Gen2Pokemon,bankBytes:ByteArray,preparedDestination:ByteArray,trainer:TrainerData,meta:Gen1ToGen7TransferMeta,plan:Gen2ToGen6LegalisePlan,pk6:ByteArray,converted:PokemonEntry,openedFile:File,binding:Gen2Gen6SingleBinding){
        fun bound()=importedFile?.absolutePath==openedFile.absolutePath&&currentSourceUri==binding.uri&&currentSourceLabel==binding.label
        fun snapshotsMatch()=!binding.submitted&&bound()&&preparedDestination.contentEquals(binding.destination)&&bankBytes.contentEquals(binding.bank)&&runCatching{openedFile.readBytes().contentEquals(binding.destination)&&bankFile.readBytes().contentEquals(binding.bank)}.getOrDefault(false)
        if(!snapshotsMatch()){showDialog("Gen 2 → Gen 6","The destination identity or original snapshots changed, or this selection was already submitted. Reopen PSE Bank. Nothing was changed.");return}
        if(importedFile?.absolutePath!=openedFile.absolutePath)return showDialog("Gen 2 → Gen 6","The active save changed after destination selection. Reopen PSE Bank. Nothing was changed.")
        var choiceConsumed=false
        val file=openedFile;val data=runCatching{file.readBytes()}.getOrNull()?:return;if(!data.contentEquals(preparedDestination)||generationForSize(data.size)!=6||!gen6BoxChecksumValid(data)||!gen6BlockChecksumValid(data,20))return showDialog("Gen 2 → Gen 6","The destination changed or failed validation. Nothing was changed.");val info=boxStorageInfo(data)?:return;val first=findFirstEmptyBoxSlot(data,info.first,info.second,info.third)?:return showDialog("Gen 2 → Gen 6","No empty Gen 6 PC box slot was found.");val box=first/30+1;val slot=first%30+1
        AlertDialog.Builder(this).setTitle("Place legal Gen 6 conversion").setMessage("The confirmed destination-specific changes will be applied. A verified kept Gen 6 recovery backup is required before writing; review the retained backup, working save and Bank record if recovery cannot be verified. The original Gen 2 Bank record remains exact until the PK6, Pokédex and Gen 6 checksums persist and re-open successfully.").setPositiveButton("First Empty ($box/$slot)"){_,_->if(choiceConsumed||!snapshotsMatch()){showDialog("Gen 2 → Gen 6","The destination identity or original snapshots changed, or this selection was already submitted. Reopen PSE Bank. Nothing was changed.");return@setPositiveButton};choiceConsumed=true;transferGen2BankToGen6(bankFile,source,bankBytes,preparedDestination,trainer,meta,plan,pk6,converted,first,file,binding)}.setNeutralButton("Choose Box / Slot"){_,_->if(choiceConsumed||!snapshotsMatch()){showDialog("Gen 2 → Gen 6","The destination identity or original snapshots changed, or this selection was already submitted. Reopen PSE Bank. Nothing was changed.");return@setNeutralButton};choiceConsumed=true;showGen2ToGen6BoxPicker(bankFile,source,bankBytes,preparedDestination,trainer,meta,plan,pk6,converted,file,binding)}.setNegativeButton("Cancel",null).show()
    }

    private fun showGen2ToGen6BoxPicker(bankFile:File,source:Gen2Pokemon,bankBytes:ByteArray,preparedDestination:ByteArray,trainer:TrainerData,meta:Gen1ToGen7TransferMeta,plan:Gen2ToGen6LegalisePlan,pk6:ByteArray,converted:PokemonEntry,openedFile:File,binding:Gen2Gen6SingleBinding){
        fun bound()=importedFile?.absolutePath==openedFile.absolutePath&&currentSourceUri==binding.uri&&currentSourceLabel==binding.label
        fun snapshotsMatch()=!binding.submitted&&bound()&&preparedDestination.contentEquals(binding.destination)&&bankBytes.contentEquals(binding.bank)&&runCatching{openedFile.readBytes().contentEquals(binding.destination)&&bankFile.readBytes().contentEquals(binding.bank)}.getOrDefault(false)
        if(!snapshotsMatch()){showDialog("Gen 2 → Gen 6","The destination identity or original snapshots changed, or this selection was already submitted. Reopen PSE Bank. Nothing was changed.");return}
        if(importedFile?.absolutePath!=openedFile.absolutePath)return showDialog("Gen 2 → Gen 6","The active save changed after destination selection. Reopen PSE Bank. Nothing was changed.")
        var boxConsumed=false
        val file=openedFile;val data=runCatching{file.readBytes()}.getOrNull()?:return;if(!data.contentEquals(preparedDestination))return showDialog("Gen 2 → Gen 6","The destination changed. Nothing was written.");val(boxOffset,slotCount,maxSpecies)=boxStorageInfo(data)?:return;val labels=ArrayList<String>();for(box in 0 until slotCount/30){val empty=countEmptySlotsInBox(data,boxOffset,box,maxSpecies);labels.add("Box ${box+1} • $empty empty slot${if(empty==1)"" else "s"}")}
        AlertDialog.Builder(this).setTitle("Choose Gen 6 Box").setItems(labels.toTypedArray()){_,boxIndex->if(boxConsumed||!snapshotsMatch()){showDialog("Gen 2 → Gen 6","The destination identity or original snapshots changed, or this selection was already submitted. Reopen PSE Bank. Nothing was changed.");return@setItems};if(countEmptySlotsInBox(data,boxOffset,boxIndex,maxSpecies)<=0)showDialog("Box ${boxIndex+1}","This box is full. Choose another box.")else{boxConsumed=true;showGen2ToGen6SlotGrid(bankFile,source,bankBytes,preparedDestination,trainer,meta,plan,pk6,converted,boxIndex,file,binding)}}.setNegativeButton("Back"){_,_->if(boxConsumed||!snapshotsMatch()){showDialog("Gen 2 → Gen 6","The destination identity or original snapshots changed, or this selection was already submitted. Reopen PSE Bank. Nothing was changed.");return@setNegativeButton};boxConsumed=true;chooseGen2ToGen6Destination(bankFile,source,bankBytes,preparedDestination,trainer,meta,plan,pk6,converted,file,binding)}.show()
    }

    private fun showGen2ToGen6SlotGrid(bankFile:File,source:Gen2Pokemon,bankBytes:ByteArray,preparedDestination:ByteArray,trainer:TrainerData,meta:Gen1ToGen7TransferMeta,plan:Gen2ToGen6LegalisePlan,pk6:ByteArray,converted:PokemonEntry,boxIndex:Int,openedFile:File,binding:Gen2Gen6SingleBinding){
        fun bound()=importedFile?.absolutePath==openedFile.absolutePath&&currentSourceUri==binding.uri&&currentSourceLabel==binding.label
        fun snapshotsMatch()=!binding.submitted&&bound()&&preparedDestination.contentEquals(binding.destination)&&bankBytes.contentEquals(binding.bank)&&runCatching{openedFile.readBytes().contentEquals(binding.destination)&&bankFile.readBytes().contentEquals(binding.bank)}.getOrDefault(false)
        if(!snapshotsMatch()){showDialog("Gen 2 → Gen 6","The destination identity or original snapshots changed, or this selection was already submitted. Reopen PSE Bank. Nothing was changed.");return}
        if(importedFile?.absolutePath!=openedFile.absolutePath)return showDialog("Gen 2 → Gen 6","The active save changed after destination selection. Reopen PSE Bank. Nothing was changed.")
        var gridConsumed=false
        val file=openedFile;val data=runCatching{file.readBytes()}.getOrNull()?:return;if(!data.contentEquals(preparedDestination))return showDialog("Gen 2 → Gen 6","The destination changed. Nothing was written.");val(boxOffset,slotCount,maxSpecies)=boxStorageInfo(data)?:return;if(boxIndex !in 0 until slotCount/30)return;val wrapper=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(dp(12),dp(8),dp(12),dp(8))};addMutedLine(wrapper,"Tap an empty Gen 6 slot. Occupied slots are disabled.");val grid=GridLayout(this).apply{columnCount=6;rowCount=5;alignmentMode=GridLayout.ALIGN_BOUNDS;useDefaultMargins=false};val cellWidth=((resources.displayMetrics.widthPixels-dp(90))/6).coerceAtLeast(dp(42))
        for(slot in 0 until 30){val global=boxIndex*30+slot;val occupied=parsePk6(data,boxOffset+global*PK6_STORED_SIZE,PK6_STORED_SIZE,false,maxSpecies)!=null;val cell=TextView(this).apply{text=if(occupied)"●\n${slot+1}" else "○\n${slot+1}";gravity=Gravity.CENTER;textSize=13f;setTextColor(if(occupied)Color.rgb(105,105,105)else TEXT);setBackgroundColor(if(occupied)Color.rgb(35,35,35)else Color.rgb(55,55,55));isEnabled=!occupied;if(!occupied)setOnClickListener{if(gridConsumed||!snapshotsMatch()){showDialog("Gen 2 → Gen 6","The destination identity or original snapshots changed, or this selection was already submitted. Reopen PSE Bank. Nothing was changed.");return@setOnClickListener};gridConsumed=true;transferGen2BankToGen6(bankFile,source,bankBytes,preparedDestination,trainer,meta,plan,pk6,converted,global,file,binding)}};grid.addView(cell,GridLayout.LayoutParams().apply{width=cellWidth;height=dp(58);setMargins(dp(2),dp(2),dp(2),dp(2))})}
        wrapper.addView(grid);AlertDialog.Builder(this).setTitle("Box ${boxIndex+1} • choose Gen 6 slot").setView(wrapper).setNegativeButton("Back"){_,_->if(gridConsumed||!snapshotsMatch()){showDialog("Gen 2 → Gen 6","The destination identity or original snapshots changed, or this selection was already submitted. Reopen PSE Bank. Nothing was changed.");return@setNegativeButton};gridConsumed=true;showGen2ToGen6BoxPicker(bankFile,source,bankBytes,preparedDestination,trainer,meta,plan,pk6,converted,file,binding)}.setNeutralButton("Cancel",null).show()
    }

    private fun transferGen2BankToGen6(bankFile:File,expected:Gen2Pokemon,expectedBank:ByteArray,preparedDestination:ByteArray,trainer:TrainerData,meta:Gen1ToGen7TransferMeta,plan:Gen2ToGen6LegalisePlan,preparedPk6:ByteArray,prepared:PokemonEntry,target:Int,openedFile:File,binding:Gen2Gen6SingleBinding){
        fun bound()=importedFile?.absolutePath==openedFile.absolutePath&&currentSourceUri==binding.uri&&currentSourceLabel==binding.label
        if(binding.submitted||!bound()){showDialog("Gen 2 → Gen 6","The destination identity or original snapshots changed, or this selection was already submitted. Reopen PSE Bank. Nothing was changed.");return};binding.submitted=true
        if(importedFile?.absolutePath!=openedFile.absolutePath)return showDialog("Gen 2 → Gen 6","The active save changed after destination selection. Reopen PSE Bank. Nothing was changed.")
        val file=openedFile;val fresh=runCatching{file.readBytes()}.getOrNull()?:return;var writeStarted=false;var bankDeleteAttempted=false
        var safetyBackup:File?=null
        try{require(bound()&&fresh.contentEquals(binding.destination)&&expectedBank.contentEquals(binding.bank)){"The original Gen 6 destination identity or Bank binding changed."};require(fresh.contentEquals(preparedDestination)){"The Gen 6 destination changed while the conversion was prepared."};require(generationForSize(fresh.size)==6&&gen6BoxChecksumValid(fresh)&&gen6BlockChecksumValid(fresh,20)){"The fresh Gen 6 destination failed storage or Pokédex validation."};val info=boxStorageInfo(fresh)?:error("PSE could not resolve Gen 6 PC storage.");require(target in 0 until info.second){"Invalid Gen 6 PC slot."};val off=info.first+target*PK6_STORED_SIZE;require(parsePk6(fresh,off,PK6_STORED_SIZE,false,info.third)==null){"The destination slot is no longer empty."}
            val bank=bankFile.readBytes();require(bank.contentEquals(expectedBank)){"The selected Gen 2 Bank bytes changed after confirmation."};val source=parseGen2BankPayload(bank)?:error("The selected Gen 2 Bank record is invalid.");require(sameGen2BankRecord(source,expected)){"The selected Gen 2 Pokémon changed after confirmation."};require(plan==gen2ToGen6LegalisePlan(source,meta,bank)){"The prepared Gen 6 Legalise plan no longer matches the selected Pokémon."};gen2ToGen6Rejection(source,plan,meta,bank)?.let{error(it)};val pk6=buildGen2ToGen6Pk6(bank,source,fresh,trainer,meta,plan);val converted=parsePk6(pk6,0,PK6_STORED_SIZE,false,721)?:error("The refreshed PK6 could not be parsed.");require(pk6.contentEquals(preparedPk6)&&sameGen2ToGen6Pk6(converted,prepared)){"The prepared PK6 conversion changed before staging."}
            val save=fresh.copyOf();pk6.copyInto(save,off);val staged=parsePk6(save,off,PK6_STORED_SIZE,false,721)?:error("The staged PK6 could not be parsed.");require(sameGen2ToGen6Pk6(staged,converted)){"The staged PK6 did not preserve every converted field."};registerGen6Dex(save,staged.species,staged.gender,staged.shiny,staged.language);updateGen6BoxChecksum(save);updateGen6DexChecksum(save);require(gen6BoxChecksumValid(save)&&gen6BlockChecksumValid(save,20)&&gen6DexCaught(save,staged.species)){"The staged Gen 6 checksums or Pokédex registration failed verification."}
            require(bankFile.readBytes().contentEquals(expectedBank)){"The selected Gen 2 Bank record changed during staging."}
            require(importedFile?.absolutePath==file.absolutePath&&file.readBytes().contentEquals(fresh)){"The active Gen 6 destination changed during staging. Nothing was written."}
            require(bound()&&validGen2ToGen6Destination(save)){"The staged Gen 6 destination identity or PC/Pokédex integrity is invalid."}
            val backup=File.createTempFile(backupGameName(file)+"_PreGen2ToGen6Transfer_",".backup",backupsDir());safetyBackup=backup
            backup.writeBytes(fresh);require(backup.readBytes().contentEquals(fresh)){"The exact Gen 6 recovery backup did not verify."};retainGen2ToGen6SafetyBackup(backup,fresh)
            require(bound()&&isBackupKept(backup)&&backup.readBytes().contentEquals(fresh)&&file.readBytes().contentEquals(fresh)&&bankFile.readBytes().contentEquals(expectedBank)){"The Gen 6 destination, Bank record or retained backup changed before writing. Nothing was written."}
            writeStarted=true
            file.writeBytes(save);val written=file.readBytes();require(written.contentEquals(save)){"The destination changed while it was written."};val actual=written.copyOfRange(off,off+PK6_STORED_SIZE);val q=parsePk6(actual,0,PK6_STORED_SIZE,false,721)?:error("The persisted PK6 could not be parsed.");require(actual.contentEquals(pk6)&&sameGen2ToGen6Pk6(q,staged)){"The exact converted PK6 did not persist."};require(gen6BoxChecksumValid(written)&&gen6BlockChecksumValid(written,20)&&gen6DexCaught(written,q.species)){"The persisted Gen 6 checksums or Pokédex registration failed verification."}
            require(importedFile?.absolutePath==file.absolutePath&&file.readBytes().contentEquals(save)){"The verified Gen 6 destination changed before Bank cleanup."}
            require(bound()&&validGen2ToGen6Destination(written)){"The Gen 6 destination identity or PC/Pokédex integrity changed before Bank cleanup."}
            val cleanup=bankFile.readBytes();require(cleanup.contentEquals(expectedBank)&&parseGen2BankPayload(cleanup)?.let{sameGen2BankRecord(it,source)}==true){"The Gen 2 Bank record changed before cleanup."};bankDeleteAttempted=true;require(bankFile.delete()){"The Gen 2 Bank entry could not be removed after destination verification."};require(!bankFile.exists()){"The removed Gen 2 Bank entry still exists."}
            require(bound()){"The Gen 6 destination identity changed after Bank cleanup."}
            require(importedFile?.absolutePath==file.absolutePath&&file.readBytes().contentEquals(save)){"The verified Gen 6 destination changed after Bank cleanup."}
        }catch(e:Exception){
            val bankRestored=if(!writeStarted)true else runCatching{
                if(bankDeleteAttempted&&!bankFile.exists()){
                    require(bankFile.createNewFile()){"The Bank recovery path could not be reserved."}
                    bankFile.writeBytes(expectedBank)
                }
                require(bankFile.readBytes().contentEquals(expectedBank)){"The original Gen 2 Bank record could not be verified; no existing record was overwritten."}
            }.isSuccess
            val destinationRestored=!writeStarted||(bankRestored&&runCatching{file.writeBytes(fresh)}.isSuccess&&runCatching{file.readBytes().contentEquals(fresh)}.getOrDefault(false)&&runCatching{file.readBytes().contentEquals(fresh)&&validGen2ToGen6Destination(fresh)}.getOrDefault(false))
            val recovery=if(!writeStarted)"Nothing was written to the save and no Bank record was removed." else  if(bankRestored&&destinationRestored)"The exact Gen 6 destination and Gen 2 Bank record were restored or kept and verified." else  "Automatic recovery could not be verified. Stop editing and keep the working save and remaining Bank record until a verified backup and Bank contents have been reviewed."
            showDialog("Gen 2 → Gen 6 failed",(e.message?:"Unknown error")+"\n\n$recovery"+(safetyBackup?.let{"\n\nRecovery backup: "+it.name}?:""));return
        }
        Toast.makeText(this,"Transferred Gen 2 → Gen 6 to Box ${target/30+1} • Slot ${target%30+1} and verified",Toast.LENGTH_LONG).show();showBank()
    }

    private data class Gen2Gen6BatchPrepared(
        val bankFile:File,val bankBytes:ByteArray,val source:Gen2Pokemon,val meta:Gen1ToGen7TransferMeta,
        val plan:Gen2ToGen6LegalisePlan,val pk6:ByteArray,val converted:PokemonEntry
    )

    private fun gen2ToGen6BatchLegaliseSummary(p:Gen2Pokemon,plan:Gen2ToGen6LegalisePlan):String {
        val specific=ArrayList<String>()
        if(plan.heldItem!=0)specific.add("remove held item #${plan.heldItem}")
        if(plan.caughtData!=0)specific.add("omit caught/met 0x${plan.caughtData.toString(16).uppercase().padStart(4,'0')}")
        if(specific.isEmpty())specific.add("no held-item or caught/met omission")
        return "${p.nickname.ifBlank{"Pokémon #${p.species}"}}: nature ${plan.nature}, ${specific.joinToString(", ")}"
    }

    private data class Gen2Gen6BatchBinding(val uri:Uri?,val label:String?,val destination:ByteArray,val bankImages:List<Pair<String,ByteArray>>)

    private fun prepareSelectedGen2BankToGen6(chosen:List<File>,confirmedPlans:Map<String,Gen2ToGen6LegalisePlan>?=null,openedFile:File?=importedFile,binding:Gen2Gen6BatchBinding?=null){
        val file=openedFile?:return
        val openedUri=if(binding==null)currentSourceUri else binding.uri;val openedLabel=if(binding==null)currentSourceLabel else binding.label
        fun bound()=importedFile?.absolutePath==file.absolutePath&&currentSourceUri==openedUri&&currentSourceLabel==openedLabel
        if(!bound())return showDialog("Gen 2 → Gen 6 multi-transfer","The destination identity changed. Reopen PSE Bank. Nothing was changed.")
        var legaliseConsumed=false
        if(importedFile?.absolutePath!=file.absolutePath)return showDialog("Gen 2 → Gen 6 multi-transfer","The active save changed after preparation. Reopen the Bank selection. Nothing was changed.")
        if(chosen.isEmpty())return showDialog("Gen 2 → Gen 6 multi-transfer","Select one or more Gen 2 Bank Pokémon first.")
        if(chosen.map{it.absolutePath}.distinct().size!=chosen.size)return showDialog("Gen 2 → Gen 6 multi-transfer","The selection contains the same Bank entry more than once. Nothing was changed.")
        val destination=runCatching{file.readBytes()}.getOrNull()?:return showDialog("Gen 2 → Gen 6 multi-transfer","The Gen 6 destination could not be read.")
        if(generationForSize(destination.size)!=6||!gen6BoxChecksumValid(destination)||!gen6BlockChecksumValid(destination,20))return showDialog("Gen 2 → Gen 6 multi-transfer","Load a valid Generation 6 save whose PC storage and Pokédex checksums pass.")
        val info=boxStorageInfo(destination)?:return showDialog("Gen 2 → Gen 6 multi-transfer","PSE could not resolve Gen 6 PC storage.")
        val trainer=analyzeSave(file).trainer?:return showDialog("Gen 2 → Gen 6 multi-transfer","PSE could not read the destination trainer.")
        val selected=try{chosen.map{bankFile->
            require(bankFile.isFile&&bankFile.extension.equals("pse2",true)){"A selected Gen 2 Bank record no longer exists."}
            val bytes=bankFile.readBytes();val source=parseGen2BankPayload(bytes)?:error("A selected Gen 2 Bank record is invalid.")
            val hardReason=gen2ToGen6Rejection(source)
            require(!source.isEgg&&source.heldItem !in GEN2_MAIL_ITEM_IDS){"${source.nickname.ifBlank{"Pokémon #${source.species}"}} cannot transfer: $hardReason"}
            require(source.species in 1..251&&source.moves.none{it !in 0..251}){"${source.nickname.ifBlank{"Pokémon #${source.species}"}} cannot transfer: $hardReason"}
            Triple(bankFile,bytes,source)
        }}catch(e:Exception){return showDialog("Cannot transfer selection to Gen 6","${e.message?:"A selected Bank record could not be read."}\n\nNo safe deterministic Gen 6 legalisation is available. Every selected Bank record and the destination were left unchanged.")}
        if(binding!=null&&(!destination.contentEquals(binding.destination)||binding.bankImages.size!=selected.size||!binding.bankImages.zip(selected).all{(image,item)->image.first==item.first.absolutePath&&image.second.contentEquals(item.second)}))return showDialog("Gen 2 → Gen 6 multi-transfer","The original destination or ordered Bank selection changed after Legalise confirmation. Nothing was changed.")
        fun snapshotsMatch()=bound()&&runCatching{file.readBytes().contentEquals(destination)&&selected.all{it.first.readBytes().contentEquals(it.second)}}.getOrDefault(false)
        val hasCapacity=(0 until info.second/30).any{box->(0 until 30).count{slot->parsePk6(destination,info.first+(box*30+slot)*PK6_STORED_SIZE,PK6_STORED_SIZE,false,info.third)==null}>=selected.size}
        if(!hasCapacity)return showDialog("Gen 2 → Gen 6 multi-transfer","No single Gen 6 PC box has room for all ${selected.size} selected Pokémon. Nothing was changed.")
        val prepared=ArrayList<Gen2Gen6BatchPrepared>();val requiredPlans=linkedMapOf<String,Gen2ToGen6LegalisePlan>()
        fun stop(message:String){showDialog("Gen 2 → Gen 6 multi-transfer",message+" Every selected Bank record and the destination were left unchanged.")}
        var expectedIndex=0;var pickerOffered=false;var transferConsumed=false
        fun next(index:Int){
            if(importedFile?.absolutePath!=file.absolutePath)return stop("The active save changed while conversion data was prepared.")
            if(index!=expectedIndex||pickerOffered||!snapshotsMatch())return stop("The destination identity, snapshots or preparation order changed.")
            if(index>=selected.size){
                val currentDestination=runCatching{file.readBytes()}.getOrNull();if(currentDestination==null||!currentDestination.contentEquals(destination))return stop("The Gen 6 destination changed while conversion data was prepared.")
                for((bankFile,bankBytes,source) in selected){val current=runCatching{bankFile.readBytes()}.getOrNull();if(current==null||!current.contentEquals(bankBytes)||parseGen2BankPayload(current)?.let{sameGen2BankRecord(it,source)}!=true)return stop("A selected Gen 2 Bank record changed while conversion data was prepared.")}
                pickerOffered=true
                if(confirmedPlans==null){
                    val summary=prepared.joinToString("\n"){gen2ToGen6BatchLegaliseSummary(it.source,it.plan)}
                    AlertDialog.Builder(this).setTitle("Cannot transfer selection unchanged")
                        .setMessage("Every selected Gen 2 Pokémon needs a deterministic native PK6 conversion. Make legal for Gen 6 will convert Stat Exp to legal EVs, expand DVs into deterministic IVs while preserving gender and shiny state, derive nature from EXP, select the verified ability, and use the PSE Johto transfer marker.\n\nPer-record material changes:\n$summary\n\nSpecies, nickname, OT/TID, EXP, level, moves, current PP, PP Ups, happiness and Pokérus remain preserved. Cancel leaves the destination and every selected Bank record byte-exact. Bank records are removed only after the complete destination write verifies successfully.")
                        .setNegativeButton("Cancel",null)
                        .setPositiveButton("Make legal for Gen 6"){_,_->
                            if(legaliseConsumed){showDialog("Gen 2 → Gen 6 multi-transfer","This Legalise confirmation was already submitted. Reopen PSE Bank.");return@setPositiveButton};legaliseConsumed=true
                            if(!snapshotsMatch()){stop("The destination identity or original snapshots changed after Legalise confirmation.");return@setPositiveButton}
                            prepareSelectedGen2BankToGen6(chosen,requiredPlans,file,Gen2Gen6BatchBinding(openedUri,openedLabel,destination,selected.map{it.first.absolutePath to it.second}))
                        }.show();return
                }
                if(confirmedPlans!=requiredPlans)return stop("The prepared Gen 6 Legalise plan no longer matches this selection.")
                val targets=(0 until info.second/30).mapNotNull{box->val empty=(0 until 30).count{slot->parsePk6(destination,info.first+(box*30+slot)*PK6_STORED_SIZE,PK6_STORED_SIZE,false,info.third)==null};if(empty>=prepared.size)box to empty else null}
                if(targets.isEmpty())return stop("No single Gen 6 PC box has room for the complete selection.")
                AlertDialog.Builder(this).setTitle("Make ${prepared.size} Pokémon legal for Gen 6")
                    .setMessage("Legalise is confirmed for the complete selection. PSE will place every converted native PK6 in selection order, register every Pokédex entry, verify the exact reopened destination, then remove the original Gen 2 Bank records last. Stale state is rejected. A verified kept Gen 6 recovery backup is required before writing. Recovery is reported only after verification; review the retained backup, working save and remaining Bank records if recovery cannot be verified.")
                    .setItems(targets.map{(box,empty)->"Box ${box+1} • $empty empty slots"}.toTypedArray()){_,which->
                        if(transferConsumed){showDialog("Gen 2 → Gen 6 multi-transfer","This batch transfer was already submitted. Reopen PSE Bank.");return@setItems};transferConsumed=true
                        if(!snapshotsMatch()){stop("The destination identity or prepared snapshots changed before selection.");return@setItems}
                        transferSelectedGen2BankToGen6(prepared,destination,targets[which].first,file,openedUri,openedLabel)
                    }
                    .setNegativeButton("Cancel",null).show();return
            }
            val(bankFile,bankBytes,source)=selected[index]
            var metadataConsumed=false
            loadGen1ToGen7TransferMetaAsync(source.species,source.moves){meta->
                if(importedFile?.absolutePath!=file.absolutePath)return@loadGen1ToGen7TransferMetaAsync stop("The active save changed while conversion data was prepared.")
                if(metadataConsumed||index!=expectedIndex||pickerOffered||!snapshotsMatch())return@loadGen1ToGen7TransferMetaAsync stop("The destination identity, snapshots or metadata callback order changed.")
                metadataConsumed=true
                if(meta==null)return@loadGen1ToGen7TransferMetaAsync stop("PSE could not load verified conversion metadata for ${source.nickname.ifBlank{"Pokémon #${source.species}"}}.")
                val plan=gen2ToGen6LegalisePlan(source,meta,bankBytes)?:return@loadGen1ToGen7TransferMetaAsync stop(gen2ToGen6Rejection(source,null,meta,bankBytes)?:"No safe deterministic Gen 6 representation is available.")
                requiredPlans[bankFile.absolutePath]=plan
                if(confirmedPlans!=null&&confirmedPlans[bankFile.absolutePath]!=plan)return@loadGen1ToGen7TransferMetaAsync stop("The prepared Gen 6 Legalise plan changed for ${source.nickname.ifBlank{"Pokémon #${source.species}"}}.")
                val pk6=try{buildGen2ToGen6Pk6(bankBytes,source,destination,trainer,meta,plan)}catch(e:Exception){return@loadGen1ToGen7TransferMetaAsync stop(e.message?:"A selected Pokémon could not be converted.")}
                val converted=parsePk6(pk6,0,PK6_STORED_SIZE,false,721)?:return@loadGen1ToGen7TransferMetaAsync stop("A prepared PK6 conversion could not be parsed.")
                prepared.add(Gen2Gen6BatchPrepared(bankFile,bankBytes,source,meta,plan,pk6,converted));expectedIndex=index+1;next(index+1)
            }
        }
        next(0)
    }

    private fun transferSelectedGen2BankToGen6(prepared:List<Gen2Gen6BatchPrepared>,preparedDestination:ByteArray,targetBox:Int,openedFile:File,openedUri:Uri?,openedLabel:String?){
        fun bound()=importedFile?.absolutePath==openedFile.absolutePath&&currentSourceUri==openedUri&&currentSourceLabel==openedLabel
        if(!bound()){showDialog("Gen 2 → Gen 6 multi-transfer","The destination identity changed. Reopen PSE Bank. Nothing was changed.");return}
        if(importedFile?.absolutePath!=openedFile.absolutePath){showDialog("Gen 2 → Gen 6 multi-transfer","The active save changed after destination selection. Reopen the Bank selection. Nothing was changed.");return}
        val file=openedFile;val fresh=runCatching{file.readBytes()}.getOrNull()?:return;val removed=ArrayList<Pair<File,ByteArray>>();var writeStarted=false
        var safetyBackup:File?=null
        try{
            require(bound()){"The destination identity changed before batch validation."}
            require(prepared.isNotEmpty()){"The prepared selection is empty."};require(prepared.map{it.bankFile.absolutePath}.distinct().size==prepared.size){"The prepared selection contains a duplicate Bank entry."};require(fresh.contentEquals(preparedDestination)&&generationForSize(fresh.size)==6&&gen6BoxChecksumValid(fresh)&&gen6BlockChecksumValid(fresh,20)){"The Gen 6 destination changed or is no longer valid."}
            val info=boxStorageInfo(fresh)?:error("PSE could not resolve Gen 6 PC storage.");require(targetBox in 0 until info.second/30){"The selected Gen 6 destination box is invalid."};val trainer=analyzeSave(file).trainer?:error("PSE could not re-read the destination trainer.")
            val refreshed=prepared.map{item->val bank=item.bankFile.readBytes();require(bank.contentEquals(item.bankBytes)){"A selected Gen 2 Bank record changed after preparation."};val source=parseGen2BankPayload(bank)?:error("A selected Gen 2 Bank record is invalid.");require(sameGen2BankRecord(source,item.source)){"A selected Gen 2 Pokémon changed after preparation."};require(item.plan==gen2ToGen6LegalisePlan(source,item.meta,bank)){"A prepared Gen 6 Legalise plan no longer matches a selected Pokémon."};gen2ToGen6Rejection(source,item.plan,item.meta,bank)?.let{error(it)};val pk6=buildGen2ToGen6Pk6(bank,source,fresh,trainer,item.meta,item.plan);val converted=parsePk6(pk6,0,PK6_STORED_SIZE,false,721)?:error("A refreshed PK6 could not be parsed.");require(pk6.contentEquals(item.pk6)&&sameGen2ToGen6Pk6(converted,item.converted)){"A prepared PK6 conversion changed before staging."};Gen2Gen6BatchPrepared(item.bankFile,bank,source,item.meta,item.plan,pk6,converted)}
            val empty=(0 until 30).filter{slot->parsePk6(fresh,info.first+(targetBox*30+slot)*PK6_STORED_SIZE,PK6_STORED_SIZE,false,info.third)==null};require(empty.size>=refreshed.size){"Gen 6 Box ${targetBox+1} no longer has room for the complete selection."}
            val work=fresh.copyOf();val allowed=HashSet<Int>();val expected=ArrayList<Triple<Int,ByteArray,PokemonEntry>>()
            for(i in refreshed.indices){val item=refreshed[i];val target=targetBox*30+empty[i];val off=info.first+target*PK6_STORED_SIZE;require(parsePk6(work,off,PK6_STORED_SIZE,false,info.third)==null){"A destination slot is no longer empty."};item.pk6.copyInto(work,off);for(x in off until off+PK6_STORED_SIZE)allowed.add(x);val staged=parsePk6(work,off,PK6_STORED_SIZE,false,721)?:error("A staged PK6 could not be parsed.");require(sameGen2ToGen6Pk6(staged,item.converted)){"A staged PK6 did not preserve every converted field."};expected.add(Triple(target,item.pk6,staged))}
            for((_,_,mon) in expected){val bit=mon.species-1;val bd=bit ushr 3;val shift=(mon.gender.coerceIn(0,1)) or ((if(mon.shiny)1 else 0) shl 1);allowed.add(0x15000+0x08+bd);allowed.add(0x15000+0x08+0x60*(1+shift)+bd);for(r in 5..8)allowed.add(0x15000+0x08+0x60*r+bd);registerGen6Dex(work,mon.species,mon.gender,mon.shiny,mon.language)}
            val boxBlock=if(work.size==SIZE_G6_XY)53 else 56;for(id in intArrayOf(20,boxBlock)){val o=gen6ChecksumOffset(work,id);allowed.add(o);allowed.add(o+1)};updateGen6BoxChecksum(work);updateGen6DexChecksum(work)
            require(work.indices.all{it in allowed||work[it]==fresh[it]}){"Unrelated Gen 6 save data changed during batch staging."};require(gen6BoxChecksumValid(work)&&gen6BlockChecksumValid(work,20)&&expected.all{gen6DexCaught(work,it.third.species)}){"The staged Gen 6 checksums or Pokédex failed verification."}
            require(refreshed.all{it.bankFile.readBytes().contentEquals(it.bankBytes)}){"A selected Gen 2 Bank record changed during staging."}
            require(importedFile?.absolutePath==file.absolutePath&&file.readBytes().contentEquals(fresh)){"The active Gen 6 destination changed during staging. Nothing was written."}
            require(bound()&&validGen2ToGen6Destination(work)){"The staged Gen 6 destination identity or PC/Pokédex integrity is invalid."}
            val backup=File.createTempFile(backupGameName(file)+"_PreGen2ToGen6Batch_",".backup",backupsDir());safetyBackup=backup
            backup.writeBytes(fresh);require(backup.readBytes().contentEquals(fresh)){"The exact Gen 6 batch recovery backup did not verify."};retainGen2ToGen6SafetyBackup(backup,fresh)
            require(bound()&&isBackupKept(backup)&&backup.readBytes().contentEquals(fresh)&&file.readBytes().contentEquals(fresh)&&refreshed.all{it.bankFile.readBytes().contentEquals(it.bankBytes)}){"The Gen 6 destination, selected Bank records or retained backup changed before writing. Nothing was written."}
            writeStarted=true
            file.writeBytes(work);val written=file.readBytes();require(written.contentEquals(work)){"The destination changed while the batch was written."};require(gen6BoxChecksumValid(written)&&gen6BlockChecksumValid(written,20)){"The persisted Gen 6 save failed checksum validation."};require(written.indices.all{it in allowed||written[it]==fresh[it]}){"Unrelated Gen 6 data changed after persistence."}
            for((target,bytes,staged) in expected){val off=info.first+target*PK6_STORED_SIZE;val actual=written.copyOfRange(off,off+PK6_STORED_SIZE);val q=parsePk6(actual,0,PK6_STORED_SIZE,false,721)?:error("A persisted PK6 could not be parsed.");require(actual.contentEquals(bytes)&&sameGen2ToGen6Pk6(q,staged)&&gen6DexCaught(written,q.species)){"A persisted PK6 or Pokédex registration did not verify."}}
            require(bound()&&validGen2ToGen6Destination(written)){"The Gen 6 destination identity or PC/Pokédex integrity changed before batch Bank cleanup."}
            for(item in refreshed){require(bound()){"The destination identity changed before a batch Bank cleanup."}
                require(importedFile?.absolutePath==file.absolutePath&&file.readBytes().contentEquals(work)){"The verified Gen 6 destination changed before Bank cleanup."}
                val cleanup=item.bankFile.readBytes();require(cleanup.contentEquals(item.bankBytes)&&parseGen2BankPayload(cleanup)?.let{sameGen2BankRecord(it,item.source)}==true){"A selected Gen 2 Bank record changed before cleanup."}
                removed.add(item.bankFile to item.bankBytes);require(item.bankFile.delete()){"A selected Gen 2 Bank record could not be removed after destination verification."};require(!item.bankFile.exists()){"A removed Gen 2 Bank record still exists."}
            }
            require(bound()){"The destination identity changed after batch Bank cleanup."}
            require(importedFile?.absolutePath==file.absolutePath&&file.readBytes().contentEquals(work)){"The verified Gen 6 destination changed after Bank cleanup."}
        }catch(e:Exception){
            val bankRestored=if(!writeStarted)true else{
                var restored=true
                for((bank,bytes) in removed){
                    val recovered=runCatching{
                        if(bank.exists())require(bank.readBytes().contentEquals(bytes)){"An existing Bank recovery path changed; it was not overwritten."}
                        else{require(bank.createNewFile()){"A Bank recovery path could not be reserved."};bank.writeBytes(bytes);require(bank.readBytes().contentEquals(bytes)){"A recovered Bank record did not verify."}}
                    }.isSuccess
                    restored=recovered&&restored
                }
                restored&&prepared.all{runCatching{it.bankFile.readBytes().contentEquals(it.bankBytes)}.getOrDefault(false)}
            }
            val destinationRestored=!writeStarted||(bankRestored&&runCatching{file.writeBytes(fresh)}.isSuccess&&runCatching{file.readBytes().contentEquals(fresh)}.getOrDefault(false)&&runCatching{file.readBytes().contentEquals(fresh)&&validGen2ToGen6Destination(fresh)}.getOrDefault(false))
            val recovery=if(!writeStarted)"Nothing was written to the save and no Bank record was removed." else  if(bankRestored&&destinationRestored)"The exact Gen 6 destination and every selected Gen 2 Bank record were restored or kept and verified." else  "Automatic recovery could not be verified. Stop editing and keep the working save and remaining Bank records until a verified backup and Bank contents have been reviewed."
            showDialog("Gen 2 → Gen 6 multi-transfer failed",(e.message?:"Unknown error")+"\n\n$recovery"+(safetyBackup?.let{"\n\nRecovery backup: "+it.name}?:""));return
        }
        selectedBankFiles.clear();bankMultiSelectMode=false;Toast.makeText(this,"Transferred ${prepared.size} Gen 2 Pokémon → Gen 6 Box ${targetBox+1} and verified",Toast.LENGTH_LONG).show();showBank()
    }

    private data class Gen2ToGen7LegalisePlan(
        val species:Int,val heldItem:Int,val caughtData:Int,val nature:Int,val gender:Int,val shiny:Boolean,
        val dvs:List<Int>,val statExp:List<Int>,val happiness:Int,val pokerus:Int,val originGame:Int,val ivs:List<Int>
    )

    private fun gen2ToGen7DeterministicIvs(p:Gen2Pokemon):IntArray {
        val ivs=gen2ToGen6Ivs(p);val order=intArrayOf(0,1,2,3,4,5);var state=((p.tid.toLong() shl 16) xor p.experience xor (p.species.toLong() shl 8) xor p.caughtData.toLong() xor 0x47503237L) and 0xFFFFFFFFL
        for(i in order.lastIndex downTo 1){state=(state*1664525L+1013904223L) and 0xFFFFFFFFL;val j=(state%(i+1)).toInt();val t=order[i];order[i]=order[j];order[j]=t}
        for(i in 0 until if(p.species==251)5 else 3)ivs[order[i]]=31
        return ivs
    }

    private fun gen2ToGen7LegalisePlan(p:Gen2Pokemon,meta:Gen1ToGen7TransferMeta,bankBytes:ByteArray):Gen2ToGen7LegalisePlan? {
        if(bankBytes.size!=GEN2_BANK_FILE_SIZE||p.isEgg||p.species !in 1..251||p.moves.any{it !in 0..251}||p.heldItem in GEN2_MAIL_ITEM_IDS)return null
        return Gen2ToGen7LegalisePlan(p.species,p.heldItem,p.caughtData,(p.experience%25L).toInt(),gen2TransferGender(p,meta.genderRate),p.shiny,p.dvs.toList(),p.statExp.toList(),p.happiness,p.pokerus,gen2BankOriginGameId(bankBytes),gen2ToGen7DeterministicIvs(p).toList())
    }

    private fun gen2ToGen7LegaliseChanges(plan:Gen2ToGen7LegalisePlan):String = buildString {
        append("• convert Gen 2 Stat Exp into six legal Gen 7 EVs, capped to 510 total\n")
        append("• expand Gen 2 DVs into deterministic Gen 7 IVs, including the required ${if(plan.species==251)5 else 3} perfect transfer IVs, while preserving gender and shiny state\n")
        append("• derive nature deterministically from EXP and select the verified species ability\n")
        append("• use the PSE Johto transfer marker instead of inventing a Gen 7 capture")
        if(plan.heldItem!=0)append("\n• remove held item #${plan.heldItem}, because Gen 2 and Gen 7 item IDs are not interchangeable")
        if(plan.caughtData!=0)append("\n• omit Gen 2 caught/met value 0x${plan.caughtData.toString(16).uppercase().padStart(4,'0')}, whose layout has no exact Gen 7 equivalent")
    }

    private fun gen2ToGen7Rejection(p:Gen2Pokemon,plan:Gen2ToGen7LegalisePlan?=null,meta:Gen1ToGen7TransferMeta?=null,bankBytes:ByteArray?=null):String? = when {
        p.isEgg -> "Gen 2 Egg state cannot yet be converted into a verified native Gen 7 Egg."
        p.species !in 1..251 -> "Species #${p.species} is not a valid Generation 2 species."
        p.moves.any{it !in 0..251} -> "This Pokémon contains a move outside the Generation 2 move catalogue."
        p.heldItem in GEN2_MAIL_ITEM_IDS -> "Held Mail and its message state cannot be represented safely by this Gen 7 conversion."
        meta==null||bankBytes==null -> "Verified species, ability, gender and source metadata are required before this conversion can be prepared."
        plan==null -> "Generation 2 DVs, Stat Exp, nature/ability absence, item IDs and caught-origin data cannot transfer unchanged into a native PK7."
        plan!=gen2ToGen7LegalisePlan(p,meta,bankBytes) -> "The prepared Gen 7 Legalise plan no longer matches this Pokémon."
        else -> null
    }

    private fun sameGen2ToGen7Pk7(a:PokemonEntry,b:PokemonEntry):Boolean = a.checksumValid&&b.checksumValid&&a.pid==b.pid&&a.species==b.species&&a.tid==b.tid&&a.sid==b.sid&&a.nickname==b.nickname&&a.otName==b.otName&&a.experience==b.experience&&a.ability==b.ability&&a.abilityNumber==b.abilityNumber&&a.nature==b.nature&&a.gender==b.gender&&a.shiny==b.shiny&&a.originGame==b.originGame&&a.metLocation==b.metLocation&&a.ball==b.ball&&a.metLevel==b.metLevel&&a.language==b.language&&a.heldItem==b.heldItem&&a.friendship==b.friendship&&a.currentHandler==b.currentHandler&&a.pokerusDays==b.pokerusDays&&a.pokerusStrain==b.pokerusStrain&&a.isEgg==b.isEgg&&a.fatefulEncounter==b.fatefulEncounter&&a.moves.contentEquals(b.moves)&&a.movePP.contentEquals(b.movePP)&&a.evs.contentEquals(b.evs)&&a.ivs.contentEquals(b.ivs)

    private fun buildGen2ToGen7Pk7(bankBytes:ByteArray,p:Gen2Pokemon,destinationSave:ByteArray,trainer:TrainerData,meta:Gen1ToGen7TransferMeta,plan:Gen2ToGen7LegalisePlan):ByteArray {
        require(!p.isEgg){"Gen 2 Eggs cannot be converted to Gen 7 until egg-specific conversion is implemented."};require(bankBytes.size==GEN2_BANK_FILE_SIZE){"The preserved Gen 2 Bank record has an unexpected size."};require(destinationSave.size==SIZE_G7_SM||destinationSave.size==SIZE_G7_USUM){"A Generation 7 destination save is required."};gen2ToGen7Rejection(p,plan,meta,bankBytes)?.let{error(it)}
        val pk=ByteArray(PK6_STORED_SIZE);var ec=((p.tid.toLong() shl 16) xor p.experience xor (p.species.toLong() shl 8) xor p.caughtData.toLong() xor 0x47503237L) and 0xFFFFFFFFL;if(ec==0L)ec=1L
        writeU32LE(pk,0x00,ec);writeU16LE(pk,0x04,0);writeU16LE(pk,0x08,p.species);writeU16LE(pk,0x0A,0);writeU16LE(pk,0x0C,p.tid);writeU16LE(pk,0x0E,0);writeU32LE(pk,0x10,p.experience);pk[0x14]=meta.abilityId.toByte();pk[0x15]=meta.abilityNumber.toByte();writeU16LE(pk,0x16,0)
        val pid=forceTransferShinyState((ec xor 0xA5A55A5AL) and 0xFFFFFFFFL,p.tid,p.shiny);writeU32LE(pk,0x18,pid);pk[0x1C]=plan.nature.toByte();val fateful=p.species==251;pk[0x1D]=(((plan.gender and 3) shl 1) or (if(fateful)1 else 0)).toByte();val evs=gen2ToGen3Evs(p);for(i in 0..5)pk[0x1E+i]=evs[i].toByte();pk[0x2B]=p.pokerus.toByte()
        val speciesName=GEN2_NATIONAL_NAMES.getOrElse(p.species-1){error("The Gen 2 species name is unavailable.")};val custom=p.nickname.isNotBlank()&&!p.nickname.equals(speciesName,true);val expectedName=if(custom)p.nickname else speciesName;writeGen6String(pk,0x40,26,expectedName);val o=GEN2_BANK_HEADER_SIZE
        for(i in 0..3){val move=p.moves[i];writeU16LE(pk,0x5A+i*2,move);pk[0x62+i]=if(move==0)0 else p.movePP[i].coerceIn(0,63).toByte();pk[0x66+i]=if(move==0)0 else ((bankBytes[o+23+i].toInt() ushr 6) and 3).toByte()}
        val ivs=plan.ivs.toIntArray();var iv32=0L;for(i in 0..5)iv32=iv32 or ((ivs[i].toLong() and 31L) shl(i*5));if(custom)iv32=iv32 or 0x80000000L;writeU32LE(pk,0x74,iv32)
        writeGen6String(pk,0x78,26,trainer.trainerName);pk[0x92]=if(trainer.gender.equals("Female",true))1 else 0;pk[0x93]=1;pk[0xA2]=p.happiness.toByte();writeGen6String(pk,0xB0,26,p.otName);pk[0xCA]=p.happiness.toByte();writeU16LE(pk,0xD8,0);writeU16LE(pk,0xDA,30017);pk[0xDC]=4;pk[0xDD]=(p.level.coerceIn(1,100) and 0x7F).toByte();pk[0xDF]=plan.originGame.toByte();pk[0xE3]=currentGen7LanguageId(destinationSave).coerceIn(1,10).toByte()
        updatePk6Checksum(pk);val enc=encryptPk6(pk);val q=parsePk6(enc,0,PK6_STORED_SIZE,false,807)?:error("The converted PK7 could not be parsed.")
        require(q.checksumValid&&q.species==p.species&&q.tid==p.tid&&q.nickname==expectedName&&q.otName==p.otName&&q.experience==p.experience&&q.ability==meta.abilityId&&q.abilityNumber==meta.abilityNumber&&q.nature==plan.nature&&q.gender==plan.gender&&q.shiny==p.shiny&&q.originGame==plan.originGame&&q.metLocation==30017&&q.ball==4&&q.metLevel==p.level.coerceIn(1,100)&&q.heldItem==0&&q.friendship==p.happiness&&q.pokerusDays==(p.pokerus and 0xF)&&q.pokerusStrain==((p.pokerus ushr 4) and 0xF)&&q.fatefulEncounter==fateful&&q.moves.contentEquals(p.moves)&&q.movePP.contentEquals(p.movePP)&&q.evs.contentEquals(evs)&&q.ivs.contentEquals(ivs)){"The converted PK7 did not preserve every destination-representable field."};return enc
    }

    private data class Gen2Gen7SingleBinding(val uri:Uri?,val label:String?,val destination:ByteArray,val bank:ByteArray){var submitted=false}

    private fun validGen2ToGen7Destination(data:ByteArray):Boolean=runCatching{
        generationForSize(data.size)==7&&validateGen7CoreChecksums(data).first
    }.getOrDefault(false)

    private fun retainGen2ToGen7SafetyBackup(file:File,expected:ByteArray){
        require(file.isFile&&file.readBytes().contentEquals(expected)&&validGen2ToGen7Destination(expected)){"The Gen 7 recovery backup is not an exact valid destination snapshot."}
        val names=keptBackupNames().apply{add(file.name)}
        val prefs=getSharedPreferences("pse_backup_state",MODE_PRIVATE)
        require(prefs.edit().putStringSet("kept",names).commit()){"The Gen 7 recovery backup could not be durably kept."}
        require(prefs.getStringSet("kept",emptySet())?.contains(file.name)==true&&file.readBytes().contentEquals(expected)){"The retained Gen 7 recovery backup did not verify."}
    }

    private fun prepareGen2ForwardTransfer(bankFile:File,shown:Gen2Pokemon,openedFile:File,confirmed:Gen2ToGen7LegalisePlan?=null,binding:Gen2Gen7SingleBinding?=null){
        val openedUri=if(binding==null)currentSourceUri else binding.uri;val openedLabel=if(binding==null)currentSourceLabel else binding.label
        fun bound()=importedFile?.absolutePath==openedFile.absolutePath&&currentSourceUri==openedUri&&currentSourceLabel==openedLabel
        if(!bound())return showDialog("Gen 2 → Gen 7","The destination identity changed. Reopen PSE Bank. Nothing was changed.")
        var metadataConsumed=false;var legaliseConsumed=false
        if(importedFile?.absolutePath!=openedFile.absolutePath)return showDialog("Gen 2 → Gen 7","The active save changed. Reopen PSE Bank. Nothing was changed.")
        val file=openedFile;val bank=runCatching{bankFile.readBytes()}.getOrNull()?:return showDialog("Gen 2 → Gen 7","PSE could not read the preserved Gen 2 Bank entry.");val source=parseGen2BankPayload(bank)?:return showDialog("Gen 2 → Gen 7","The selected Gen 2 Bank record is invalid.");if(!sameGen2BankRecord(source,shown))return showDialog("Gen 2 → Gen 7","The selected Gen 2 Bank record changed. Nothing was changed.")
        val destination=runCatching{file.readBytes()}.getOrNull()?:return showDialog("Gen 2 → Gen 7","PSE could not read the destination save.");val checksumState=validateGen7CoreChecksums(destination);if(generationForSize(destination.size)!=7||!checksumState.first)return showDialog("Gen 2 → Gen 7",checksumState.second);if(source.isEgg||source.heldItem in GEN2_MAIL_ITEM_IDS)return showDialog("Cannot transfer to Gen 7",gen2ToGen7Rejection(source)!!+"\n\nNo safe deterministic Gen 7 representation is available. Both sides were left unchanged.")
        if(binding!=null&&(!destination.contentEquals(binding.destination)||!bank.contentEquals(binding.bank)||binding.submitted))return showDialog("Gen 2 → Gen 7","The original destination or Bank snapshot changed. Reopen PSE Bank. Nothing was changed.")
        val captured=binding?:Gen2Gen7SingleBinding(openedUri,openedLabel,destination,bank)
        fun snapshotsMatch()=!captured.submitted&&bound()&&runCatching{file.readBytes().contentEquals(destination)&&bankFile.readBytes().contentEquals(bank)}.getOrDefault(false)
        val trainer=parseTrainerGen7(destination,destination.size)?:return showDialog("Gen 2 → Gen 7","PSE could not read the destination trainer data.");val loading=AlertDialog.Builder(this).setTitle("Prepare Gen 2 → Gen 7").setMessage("Loading verified species, ability, gender and move metadata…").setCancelable(false).create();loading.show()
        loadGen1ToGen7TransferMetaAsync(source.species,source.moves){meta->
            if(metadataConsumed||!snapshotsMatch()){if(loading.isShowing)loading.dismiss();showDialog("Gen 2 → Gen 7","The destination identity or original snapshots changed, or this metadata callback was already used. Reopen PSE Bank. Nothing was changed.");return@loadGen1ToGen7TransferMetaAsync};metadataConsumed=true
            if(loading.isShowing)loading.dismiss();if(importedFile?.absolutePath!=file.absolutePath)return@loadGen1ToGen7TransferMetaAsync showDialog("Gen 2 → Gen 7","The active save changed while conversion data was prepared. Reopen PSE Bank. Nothing was changed.");if(meta==null){showDialog("Gen 2 → Gen 7","PSE could not load the verified conversion metadata. Both sides were left unchanged.");return@loadGen1ToGen7TransferMetaAsync};val plan=gen2ToGen7LegalisePlan(source,meta,bank)?:run{showDialog("Cannot transfer to Gen 7",gen2ToGen7Rejection(source,null,meta,bank)?:"No safe deterministic Gen 7 representation is available.");return@loadGen1ToGen7TransferMetaAsync}
            if(confirmed==null){AlertDialog.Builder(this).setTitle("Cannot transfer unchanged").setMessage("${gen2ToGen7Rejection(source,null,meta,bank)}\n\nMake legal for Gen 7 will:\n${gen2ToGen7LegaliseChanges(plan)}\n\nSpecies, nickname, OT/TID, EXP, level, moves, current PP, PP Ups, happiness and Pokérus are preserved. Cancel leaves the Gen 2 Bank record and Gen 7 destination byte-exact; the Bank record is not removed until the destination write verifies.").setNegativeButton("Cancel",null).setPositiveButton("Make legal for Gen 7"){_,_->
                if(legaliseConsumed||!snapshotsMatch()){showDialog("Gen 2 → Gen 7","The destination identity or original snapshots changed, or this Legalise confirmation was already used. Reopen PSE Bank. Nothing was changed.");return@setPositiveButton};legaliseConsumed=true
                prepareGen2ForwardTransfer(bankFile,shown,file,plan,captured)
            }.show();return@loadGen1ToGen7TransferMetaAsync}
            if(confirmed!=plan){showDialog("Legalise blocked","The prepared Gen 7 Legalise plan no longer matches this Bank record. Nothing was changed.");return@loadGen1ToGen7TransferMetaAsync};val currentBank=runCatching{bankFile.readBytes()}.getOrNull();val currentDestination=runCatching{file.readBytes()}.getOrNull();if(currentBank==null||!currentBank.contentEquals(bank)||parseGen2BankPayload(currentBank)?.let{sameGen2BankRecord(it,source)}!=true||currentDestination==null||!currentDestination.contentEquals(destination)){showDialog("Gen 2 → Gen 7","The source or destination changed while conversion data was prepared. Nothing was changed.");return@loadGen1ToGen7TransferMetaAsync}
            val pk7=try{buildGen2ToGen7Pk7(bank,source,destination,trainer,meta,plan)}catch(e:Exception){showDialog("Gen 2 → Gen 7",e.message?:"PSE could not create the verified PK7 conversion.");return@loadGen1ToGen7TransferMetaAsync};val converted=parsePk6(pk7,0,PK6_STORED_SIZE,false,807)?:return@loadGen1ToGen7TransferMetaAsync;chooseGen2ToGen7Destination(bankFile,source,bank,destination,trainer,meta,plan,pk7,converted,file,captured)
        }
    }

    private fun chooseGen2ToGen7Destination(bankFile:File,source:Gen2Pokemon,bankBytes:ByteArray,preparedDestination:ByteArray,trainer:TrainerData,meta:Gen1ToGen7TransferMeta,plan:Gen2ToGen7LegalisePlan,pk7:ByteArray,converted:PokemonEntry,openedFile:File,binding:Gen2Gen7SingleBinding){
        fun bound()=importedFile?.absolutePath==openedFile.absolutePath&&currentSourceUri==binding.uri&&currentSourceLabel==binding.label
        fun snapshotsMatch()=!binding.submitted&&bound()&&preparedDestination.contentEquals(binding.destination)&&bankBytes.contentEquals(binding.bank)&&runCatching{openedFile.readBytes().contentEquals(binding.destination)&&bankFile.readBytes().contentEquals(binding.bank)}.getOrDefault(false)
        if(!snapshotsMatch())return showDialog("Gen 2 → Gen 7","The destination identity or original snapshots changed, or this transfer was already submitted. Reopen PSE Bank. Nothing was changed.")
        var choiceConsumed=false
        if(importedFile?.absolutePath!=openedFile.absolutePath)return showDialog("Gen 2 → Gen 7","The active save changed after destination selection. Reopen PSE Bank. Nothing was changed.")
