        wrapper.addView(grid);AlertDialog.Builder(this).setTitle("Box ${boxIndex+1} • choose Gen 7 slot").setView(wrapper).setNegativeButton("Back"){_,_->if(gridConsumed||!snapshotsMatch()){showDialog("Gen 2 → Gen 7","The original destination or Bank snapshots changed, or this slot choice was already used. Reopen PSE Bank.");return@setNegativeButton};gridConsumed=true;showGen2ToGen7BoxPicker(bankFile,source,bankBytes,preparedDestination,trainer,meta,plan,pk7,converted,file,binding)}.setNeutralButton("Cancel",null).show()
    }

    private fun transferGen2BankToGen7(bankFile:File,expected:Gen2Pokemon,expectedBank:ByteArray,preparedDestination:ByteArray,trainer:TrainerData,meta:Gen1ToGen7TransferMeta,plan:Gen2ToGen7LegalisePlan,preparedPk7:ByteArray,prepared:PokemonEntry,target:Int,openedFile:File,binding:Gen2Gen7SingleBinding){
        fun bound()=importedFile?.absolutePath==openedFile.absolutePath&&currentSourceUri==binding.uri&&currentSourceLabel==binding.label
        if(binding.submitted||!bound()){showDialog("Gen 2 → Gen 7","The destination identity or original snapshots changed, or this selection was already submitted. Reopen PSE Bank. Nothing was changed.");return};binding.submitted=true
        if(importedFile?.absolutePath!=openedFile.absolutePath)return showDialog("Gen 2 → Gen 7","The active save changed after destination selection. Reopen PSE Bank. Nothing was changed.")
        val file=openedFile;val fresh=runCatching{file.readBytes()}.getOrNull()?:return;var writeStarted=false;var bankDeleteAttempted=false
        var safetyBackup:File?=null
        try{
            require(bound()&&fresh.contentEquals(binding.destination)&&expectedBank.contentEquals(binding.bank)){"The original Gen 7 destination identity or Bank binding changed."}
            require(fresh.contentEquals(preparedDestination)&&generationForSize(fresh.size)==7){"The Gen 7 destination changed while the conversion was prepared."};val checksumState=validateGen7CoreChecksums(fresh);require(checksumState.first){checksumState.second};val info=boxStorageInfo(fresh)?:error("PSE could not resolve Gen 7 PC storage.");require(target in 0 until info.second){"Invalid Gen 7 PC slot."};val off=info.first+target*PK6_STORED_SIZE;require(parsePk6(fresh,off,PK6_STORED_SIZE,false,info.third)==null){"The destination slot is no longer empty."}
            val bank=bankFile.readBytes();require(bank.contentEquals(expectedBank)){"The selected Gen 2 Bank bytes changed after confirmation."};val source=parseGen2BankPayload(bank)?:error("The selected Gen 2 Bank record is invalid.");require(sameGen2BankRecord(source,expected)){"The selected Gen 2 Pokémon changed after confirmation."};require(plan==gen2ToGen7LegalisePlan(source,meta,bank)){"The prepared Gen 7 Legalise plan no longer matches the selected Pokémon."};gen2ToGen7Rejection(source,plan,meta,bank)?.let{error(it)};val pk7=buildGen2ToGen7Pk7(bank,source,fresh,trainer,meta,plan);val converted=parsePk6(pk7,0,PK6_STORED_SIZE,false,807)?:error("The refreshed PK7 could not be parsed.");require(pk7.contentEquals(preparedPk7)&&sameGen2ToGen7Pk7(converted,prepared)){"The prepared PK7 conversion changed before staging."}
            val storageLength=info.second*PK6_STORED_SIZE;val beforeStorage=fresh.copyOfRange(info.first,info.first+storageLength);val relative=target*PK6_STORED_SIZE;val work=fresh.copyOf();pk7.copyInto(work,off);val staged=parsePk6(work,off,PK6_STORED_SIZE,false,807)?:error("The staged PK7 could not be parsed.");require(sameGen2ToGen7Pk7(staged,converted)){"The staged PK7 did not preserve every converted field."};fun pcIsolated(data:ByteArray):Boolean{val after=data.copyOfRange(info.first,info.first+storageLength);return after.indices.all{it in relative until relative+PK6_STORED_SIZE||after[it]==beforeStorage[it]}}
            require(pcIsolated(work)){"Unrelated Gen 7 PC data changed during staging."};registerGen7Dex(work,staged.species,staged.form,staged.gender,staged.shiny,staged.language);updateGen7SaveBlockChecksum(work,14,info.first,storageLength);val dexInfo=gen7BlockInfo(work,6)?:error("Gen 7 Pokédex block layout is unavailable.");updateGen7SaveBlockChecksum(work,6,dexInfo.first,dexInfo.second);finalizeGen7Save(work);require(gen7DexRegistered(work,staged)){"The staged Gen 7 Pokédex registration failed verification."};val stagedChecks=validateGen7CoreChecksums(work);require(stagedChecks.first){stagedChecks.second};require(pcIsolated(work)){"Unrelated Gen 7 PC data changed while rebuilding integrity data."}
            require(bankFile.readBytes().contentEquals(expectedBank)){"The selected Gen 2 Bank record changed during staging."}
            require(importedFile?.absolutePath==file.absolutePath&&file.readBytes().contentEquals(fresh)){"The active Gen 7 destination changed during staging. Nothing was written."}
            require(bound()&&validGen2ToGen7Destination(work)){"The staged Gen 7 destination identity or core save-block integrity is invalid."}
            val backup=File.createTempFile(backupGameName(file)+"_PreGen2ToGen7Transfer_",".backup",backupsDir());safetyBackup=backup
            backup.writeBytes(fresh);require(backup.readBytes().contentEquals(fresh)){"The exact Gen 7 recovery backup did not verify."};retainGen2ToGen7SafetyBackup(backup,fresh)
            require(bound()&&isBackupKept(backup)&&backup.readBytes().contentEquals(fresh)&&file.readBytes().contentEquals(fresh)&&bankFile.readBytes().contentEquals(expectedBank)){"The Gen 7 destination, Bank record or retained backup changed before writing. Nothing was written."}
            writeStarted=true
            file.writeBytes(work);val written=file.readBytes();require(written.contentEquals(work)&&boxStorageInfo(written)==info){"The destination changed while it was written."};val actual=written.copyOfRange(off,off+PK6_STORED_SIZE);val q=parsePk6(actual,0,PK6_STORED_SIZE,false,807)?:error("The persisted PK7 could not be parsed.");require(actual.contentEquals(pk7)&&sameGen2ToGen7Pk7(q,staged)&&gen7DexRegistered(written,q)){"The exact converted PK7 or Pokédex registration did not persist."};val writtenChecks=validateGen7CoreChecksums(written);require(writtenChecks.first){writtenChecks.second};require(pcIsolated(written)){"Unrelated Gen 7 PC data changed after persistence."}
            require(importedFile?.absolutePath==file.absolutePath&&file.readBytes().contentEquals(work)){"The verified Gen 7 destination changed before Bank cleanup."}
            require(bound()&&validGen2ToGen7Destination(written)){"The Gen 7 destination identity or core save-block integrity changed before Bank cleanup."}
            val cleanup=bankFile.readBytes();require(cleanup.contentEquals(expectedBank)&&parseGen2BankPayload(cleanup)?.let{sameGen2BankRecord(it,source)}==true){"The Gen 2 Bank record changed before cleanup."};bankDeleteAttempted=true;require(bankFile.delete()){"The Gen 2 Bank entry could not be removed after destination verification."};require(!bankFile.exists()){"The removed Gen 2 Bank entry still exists."}
            require(bound()){"The Gen 7 destination identity changed after Bank cleanup."}
            require(importedFile?.absolutePath==file.absolutePath&&file.readBytes().contentEquals(work)){"The verified Gen 7 destination changed after Bank cleanup."}
        }catch(e:Exception){
            val bankRestored=if(!writeStarted)true else runCatching{
                if(bankDeleteAttempted&&!bankFile.exists()){
                    require(bankFile.createNewFile()){"The Bank recovery path could not be reserved."}
                    bankFile.writeBytes(expectedBank)
                }
                require(bankFile.readBytes().contentEquals(expectedBank)){"The original Gen 2 Bank record could not be verified; no existing record was overwritten."}
            }.isSuccess
            val destinationRestored=!writeStarted||(bankRestored&&runCatching{file.writeBytes(fresh)}.isSuccess&&runCatching{file.readBytes().contentEquals(fresh)}.getOrDefault(false)&&runCatching{file.readBytes().contentEquals(fresh)&&validGen2ToGen7Destination(fresh)}.getOrDefault(false))
            val recovery=if(!writeStarted)"Nothing was written to the save and no Bank record was removed." else  if(bankRestored&&destinationRestored)"The exact Gen 7 destination and Gen 2 Bank record were restored or kept and verified." else  "Automatic recovery could not be verified. Stop editing and keep the working save and remaining Bank record until a verified backup and Bank contents have been reviewed."
            showDialog("Gen 2 → Gen 7 failed",(e.message?:"Unknown error")+"\n\n$recovery"+(safetyBackup?.let{"\n\nRecovery backup: "+it.name}?:""));return
        }
        Toast.makeText(this,"Transferred Gen 2 → Gen 7 to Box ${target/30+1} • Slot ${target%30+1} and verified",Toast.LENGTH_LONG).show();showBank()
    }

    private data class Gen2Gen7BatchPrepared(
        val bankFile:File,val bankBytes:ByteArray,val source:Gen2Pokemon,val meta:Gen1ToGen7TransferMeta,
        val plan:Gen2ToGen7LegalisePlan,val pk7:ByteArray,val converted:PokemonEntry
    )

    private fun gen2ToGen7BatchLegaliseSummary(p:Gen2Pokemon,plan:Gen2ToGen7LegalisePlan):String {
        val specific=ArrayList<String>()
        if(plan.heldItem!=0)specific.add("remove held item #${plan.heldItem}")
        if(plan.caughtData!=0)specific.add("omit caught/met 0x${plan.caughtData.toString(16).uppercase().padStart(4,'0')}")
        if(specific.isEmpty())specific.add("no held-item or caught/met omission")
        return "${p.nickname.ifBlank{"Pokémon #${p.species}"}}: nature ${plan.nature}, ${plan.ivs.count{it==31}} perfect IVs, ${specific.joinToString(", ")}"
    }

    private data class Gen2Gen7BatchBinding(val uri:Uri?,val label:String?,val destination:ByteArray,val bankImages:List<Pair<String,ByteArray>>)

    private fun prepareSelectedGen2BankToGen7(chosen:List<File>,confirmedPlans:Map<String,Gen2ToGen7LegalisePlan>?=null,openedFile:File?=importedFile,binding:Gen2Gen7BatchBinding?=null){
        val file=openedFile?:return
        val openedUri=if(binding==null)currentSourceUri else binding.uri;val openedLabel=if(binding==null)currentSourceLabel else binding.label
        fun bound()=importedFile?.absolutePath==file.absolutePath&&currentSourceUri==openedUri&&currentSourceLabel==openedLabel
        if(!bound())return showDialog("Gen 2 → Gen 7 multi-transfer","The destination identity changed. Reopen PSE Bank. Nothing was changed.")
        var legaliseConsumed=false
        if(importedFile?.absolutePath!=file.absolutePath)return showDialog("Gen 2 → Gen 7 multi-transfer","The active save changed after preparation. Reopen the Bank selection. Nothing was changed.")
        if(chosen.isEmpty())return showDialog("Gen 2 → Gen 7 multi-transfer","Select one or more Gen 2 Bank Pokémon first.")
        if(chosen.map{it.absolutePath}.distinct().size!=chosen.size)return showDialog("Gen 2 → Gen 7 multi-transfer","The selection contains the same Bank entry more than once. Nothing was changed.")
        val destination=runCatching{file.readBytes()}.getOrNull()?:return showDialog("Gen 2 → Gen 7 multi-transfer","The Gen 7 destination could not be read.")
        val checks=validateGen7CoreChecksums(destination);if(generationForSize(destination.size)!=7||!checks.first)return showDialog("Gen 2 → Gen 7 multi-transfer",checks.second)
        val info=boxStorageInfo(destination)?:return showDialog("Gen 2 → Gen 7 multi-transfer","PSE could not resolve Gen 7 PC storage.")
        val trainer=parseTrainerGen7(destination,destination.size)?:return showDialog("Gen 2 → Gen 7 multi-transfer","PSE could not read the destination trainer.")
        val selected=try{chosen.map{bankFile->
            require(bankFile.isFile&&bankFile.extension.equals("pse2",true)){"A selected Gen 2 Bank record no longer exists."}
            val bytes=bankFile.readBytes();val source=parseGen2BankPayload(bytes)?:error("A selected Gen 2 Bank record is invalid.")
            val hardReason=gen2ToGen7Rejection(source)
            require(!source.isEgg&&source.heldItem !in GEN2_MAIL_ITEM_IDS){"${source.nickname.ifBlank{"Pokémon #${source.species}"}} cannot transfer: $hardReason"}
            require(source.species in 1..251&&source.moves.none{it !in 0..251}){"${source.nickname.ifBlank{"Pokémon #${source.species}"}} cannot transfer: $hardReason"}
            Triple(bankFile,bytes,source)
        }}catch(e:Exception){return showDialog("Cannot transfer selection to Gen 7","${e.message?:"A selected Bank record could not be read."}\n\nNo safe deterministic Gen 7 legalisation is available. Every selected Bank record and the destination were left unchanged.")}
        if(binding!=null&&(!destination.contentEquals(binding.destination)||binding.bankImages.size!=selected.size||!binding.bankImages.zip(selected).all{(image,item)->image.first==item.first.absolutePath&&image.second.contentEquals(item.second)}))return showDialog("Gen 2 → Gen 7 multi-transfer","The original destination or ordered Bank selection changed after Legalise confirmation. Nothing was changed.")
        fun snapshotsMatch()=bound()&&runCatching{file.readBytes().contentEquals(destination)&&selected.all{it.first.readBytes().contentEquals(it.second)}}.getOrDefault(false)
        val hasCapacity=(0 until info.second/30).any{box->(0 until 30).count{slot->parsePk6(destination,info.first+(box*30+slot)*PK6_STORED_SIZE,PK6_STORED_SIZE,false,info.third)==null}>=selected.size}
        if(!hasCapacity)return showDialog("Gen 2 → Gen 7 multi-transfer","No single Gen 7 PC box has room for all ${selected.size} selected Pokémon. Nothing was changed.")
        val prepared=ArrayList<Gen2Gen7BatchPrepared>();val requiredPlans=linkedMapOf<String,Gen2ToGen7LegalisePlan>()
        fun stop(message:String){showDialog("Gen 2 → Gen 7 multi-transfer",message+" Every selected Bank record and the destination were left unchanged.")}
        var expectedIndex=0;var pickerOffered=false;var transferConsumed=false
        fun next(index:Int){
            if(importedFile?.absolutePath!=file.absolutePath)return stop("The active save changed while conversion data was prepared.")
            if(index!=expectedIndex||pickerOffered||!snapshotsMatch())return stop("The destination identity, snapshots or preparation order changed.")
            if(index>=selected.size){
                val currentDestination=runCatching{file.readBytes()}.getOrNull();if(currentDestination==null||!currentDestination.contentEquals(destination))return stop("The Gen 7 destination changed while conversion data was prepared.")
                for((bankFile,bankBytes,source) in selected){val current=runCatching{bankFile.readBytes()}.getOrNull();if(current==null||!current.contentEquals(bankBytes)||parseGen2BankPayload(current)?.let{sameGen2BankRecord(it,source)}!=true)return stop("A selected Gen 2 Bank record changed while conversion data was prepared.")}
                pickerOffered=true
                if(confirmedPlans==null){
                    val summary=prepared.joinToString("\n"){gen2ToGen7BatchLegaliseSummary(it.source,it.plan)}
                    AlertDialog.Builder(this).setTitle("Cannot transfer selection unchanged")
                        .setMessage("Every selected Gen 2 Pokémon needs a deterministic native PK7 conversion. Make legal for Gen 7 will convert Stat Exp to legal EVs, expand DVs into deterministic transfer IVs while preserving gender and shiny state, derive nature from EXP, select the verified ability, and use the PSE Johto transfer marker.\n\nPer-record material changes:\n$summary\n\nSpecies, nickname, OT/TID, EXP, level, moves, current PP, PP Ups, happiness and Pokérus remain preserved. Cancel leaves the destination and every selected Bank record byte-exact. Bank records are removed only after the complete destination write verifies successfully.")
                        .setNegativeButton("Cancel",null)
                        .setPositiveButton("Make legal for Gen 7"){_,_->
                            if(legaliseConsumed){showDialog("Gen 2 → Gen 7 multi-transfer","This Legalise confirmation was already submitted. Reopen PSE Bank.");return@setPositiveButton};legaliseConsumed=true
                            if(!snapshotsMatch()){stop("The destination identity or original snapshots changed after Legalise confirmation.");return@setPositiveButton}
                            prepareSelectedGen2BankToGen7(chosen,requiredPlans,file,Gen2Gen7BatchBinding(openedUri,openedLabel,destination,selected.map{it.first.absolutePath to it.second}))
                        }.show();return
                }
                if(confirmedPlans!=requiredPlans)return stop("The prepared Gen 7 Legalise plan no longer matches this selection.")
                val targets=(0 until info.second/30).mapNotNull{box->val empty=(0 until 30).count{slot->parsePk6(destination,info.first+(box*30+slot)*PK6_STORED_SIZE,PK6_STORED_SIZE,false,info.third)==null};if(empty>=prepared.size)box to empty else null}
                if(targets.isEmpty())return stop("No single Gen 7 PC box has room for the complete selection.")
                AlertDialog.Builder(this).setTitle("Make ${prepared.size} Pokémon legal for Gen 7")
                    .setMessage("Legalise is confirmed for the complete selection. PSE will place every converted native PK7 in selection order, register every Pokédex entry, verify the exact reopened destination, then remove the original Gen 2 Bank records last. Stale state is rejected. A verified kept Gen 7 recovery backup is required before writing. Recovery is reported only after verification; review the retained backup, working save and remaining Bank records if recovery cannot be verified.")
                    .setItems(targets.map{(box,empty)->"Box ${box+1} • $empty empty slots"}.toTypedArray()){_,which->
                        if(transferConsumed){showDialog("Gen 2 → Gen 7 multi-transfer","This batch transfer was already submitted. Reopen PSE Bank.");return@setItems};transferConsumed=true
                        if(!snapshotsMatch()){stop("The destination identity or prepared snapshots changed before selection.");return@setItems}
                        transferSelectedGen2BankToGen7(prepared,destination,targets[which].first,file,openedUri,openedLabel)
                    }
                    .setNegativeButton("Cancel",null).show();return
            }
            val(bankFile,bankBytes,source)=selected[index]
            var metadataConsumed=false
            loadGen1ToGen7TransferMetaAsync(source.species,source.moves){meta->
                if(importedFile?.absolutePath!=file.absolutePath)return@loadGen1ToGen7TransferMetaAsync stop("The active save changed while conversion data was prepared.")
                if(metadataConsumed||index!=expectedIndex||pickerOffered||!snapshotsMatch())return@loadGen1ToGen7TransferMetaAsync stop("The destination identity, snapshots or metadata callback order changed.")
                metadataConsumed=true
                if(meta==null)return@loadGen1ToGen7TransferMetaAsync stop("PSE could not load verified conversion metadata for ${source.nickname.ifBlank{"Pokémon #${source.species}"}}.")
                val plan=gen2ToGen7LegalisePlan(source,meta,bankBytes)?:return@loadGen1ToGen7TransferMetaAsync stop(gen2ToGen7Rejection(source,null,meta,bankBytes)?:"No safe deterministic Gen 7 representation is available.")
                requiredPlans[bankFile.absolutePath]=plan
                if(confirmedPlans!=null&&confirmedPlans[bankFile.absolutePath]!=plan)return@loadGen1ToGen7TransferMetaAsync stop("The prepared Gen 7 Legalise plan changed for ${source.nickname.ifBlank{"Pokémon #${source.species}"}}.")
                val pk7=try{buildGen2ToGen7Pk7(bankBytes,source,destination,trainer,meta,plan)}catch(e:Exception){return@loadGen1ToGen7TransferMetaAsync stop(e.message?:"A selected Pokémon could not be converted.")}
                val converted=parsePk6(pk7,0,PK6_STORED_SIZE,false,807)?:return@loadGen1ToGen7TransferMetaAsync stop("A prepared PK7 conversion could not be parsed.")
                prepared.add(Gen2Gen7BatchPrepared(bankFile,bankBytes,source,meta,plan,pk7,converted));expectedIndex=index+1;next(index+1)
            }
        }
        next(0)
    }

    private fun transferSelectedGen2BankToGen7(prepared:List<Gen2Gen7BatchPrepared>,preparedDestination:ByteArray,targetBox:Int,openedFile:File,openedUri:Uri?,openedLabel:String?){
        fun bound()=importedFile?.absolutePath==openedFile.absolutePath&&currentSourceUri==openedUri&&currentSourceLabel==openedLabel
        if(!bound()){showDialog("Gen 2 → Gen 7 multi-transfer","The destination identity changed. Reopen PSE Bank. Nothing was changed.");return}
        if(importedFile?.absolutePath!=openedFile.absolutePath){showDialog("Gen 2 → Gen 7 multi-transfer","The active save changed after destination selection. Reopen the Bank selection. Nothing was changed.");return}
        val file=openedFile;val fresh=runCatching{file.readBytes()}.getOrNull()?:return;val removed=ArrayList<Pair<File,ByteArray>>();var writeStarted=false
        var safetyBackup:File?=null
        try{
            require(bound()){"The destination identity changed before batch validation."}
            require(prepared.isNotEmpty()){"The prepared selection is empty."};require(prepared.map{it.bankFile.absolutePath}.distinct().size==prepared.size){"The prepared selection contains a duplicate Bank entry."};require(fresh.contentEquals(preparedDestination)&&generationForSize(fresh.size)==7){"The Gen 7 destination changed or is no longer valid."};val checks=validateGen7CoreChecksums(fresh);require(checks.first){checks.second}
            val info=boxStorageInfo(fresh)?:error("PSE could not resolve Gen 7 PC storage.");require(targetBox in 0 until info.second/30){"The selected Gen 7 destination box is invalid."};val trainer=parseTrainerGen7(fresh,fresh.size)?:error("PSE could not re-read the destination trainer.")
            val refreshed=prepared.map{item->val bank=item.bankFile.readBytes();require(bank.contentEquals(item.bankBytes)){"A selected Gen 2 Bank record changed after preparation."};val source=parseGen2BankPayload(bank)?:error("A selected Gen 2 Bank record is invalid.");require(sameGen2BankRecord(source,item.source)){"A selected Gen 2 Pokémon changed after preparation."};require(item.plan==gen2ToGen7LegalisePlan(source,item.meta,bank)){"A prepared Gen 7 Legalise plan no longer matches a selected Pokémon."};gen2ToGen7Rejection(source,item.plan,item.meta,bank)?.let{error(it)};val pk7=buildGen2ToGen7Pk7(bank,source,fresh,trainer,item.meta,item.plan);val converted=parsePk6(pk7,0,PK6_STORED_SIZE,false,807)?:error("A refreshed PK7 could not be parsed.");require(pk7.contentEquals(item.pk7)&&sameGen2ToGen7Pk7(converted,item.converted)){"A prepared PK7 conversion changed before staging."};Gen2Gen7BatchPrepared(item.bankFile,bank,source,item.meta,item.plan,pk7,converted)}
            val empty=(0 until 30).filter{slot->parsePk6(fresh,info.first+(targetBox*30+slot)*PK6_STORED_SIZE,PK6_STORED_SIZE,false,info.third)==null};require(empty.size>=refreshed.size){"Gen 7 Box ${targetBox+1} no longer has room for the complete selection."}
            val storageLength=info.second*PK6_STORED_SIZE;val beforeStorage=fresh.copyOfRange(info.first,info.first+storageLength);val work=fresh.copyOf();val allowed=HashSet<Int>();val expected=ArrayList<Triple<Int,ByteArray,PokemonEntry>>()
            for(i in refreshed.indices){val item=refreshed[i];val target=targetBox*30+empty[i];val off=info.first+target*PK6_STORED_SIZE;require(parsePk6(work,off,PK6_STORED_SIZE,false,info.third)==null){"A destination slot is no longer empty."};item.pk7.copyInto(work,off);for(x in target*PK6_STORED_SIZE until (target+1)*PK6_STORED_SIZE)allowed.add(x);val staged=parsePk6(work,off,PK6_STORED_SIZE,false,807)?:error("A staged PK7 could not be parsed.");require(sameGen2ToGen7Pk7(staged,item.converted)){"A staged PK7 did not preserve every converted field."};expected.add(Triple(target,item.pk7,staged))}
            fun pcIsolated(data:ByteArray):Boolean{val after=data.copyOfRange(info.first,info.first+storageLength);return after.indices.all{it in allowed||after[it]==beforeStorage[it]}}
            require(pcIsolated(work)){"Unrelated Gen 7 PC data changed during batch staging."};for((_,_,mon) in expected)registerGen7Dex(work,mon.species,mon.form,mon.gender,mon.shiny,mon.language);updateGen7SaveBlockChecksum(work,14,info.first,storageLength);val dexInfo=gen7BlockInfo(work,6)?:error("Gen 7 Pokédex block layout is unavailable.");updateGen7SaveBlockChecksum(work,6,dexInfo.first,dexInfo.second);finalizeGen7Save(work)
            require(expected.all{gen7DexRegistered(work,it.third)}){"A staged Gen 7 Pokédex registration failed verification."};val stagedChecks=validateGen7CoreChecksums(work);require(stagedChecks.first){stagedChecks.second};require(pcIsolated(work)){"Unrelated Gen 7 PC data changed while rebuilding integrity data."}
            require(refreshed.all{it.bankFile.readBytes().contentEquals(it.bankBytes)}){"A selected Gen 2 Bank record changed during staging."}
            require(importedFile?.absolutePath==file.absolutePath&&file.readBytes().contentEquals(fresh)){"The active Gen 7 destination changed during staging. Nothing was written."}
            require(bound()&&validGen2ToGen7Destination(work)){"The staged Gen 7 destination identity or core save-block integrity is invalid."}
            val backup=File.createTempFile(backupGameName(file)+"_PreGen2ToGen7Batch_",".backup",backupsDir());safetyBackup=backup
            backup.writeBytes(fresh);require(backup.readBytes().contentEquals(fresh)){"The exact Gen 7 batch recovery backup did not verify."};retainGen2ToGen7SafetyBackup(backup,fresh)
            require(bound()&&isBackupKept(backup)&&backup.readBytes().contentEquals(fresh)&&file.readBytes().contentEquals(fresh)&&refreshed.all{it.bankFile.readBytes().contentEquals(it.bankBytes)}){"The Gen 7 destination, selected Bank records or retained backup changed before writing. Nothing was written."}
            writeStarted=true
            file.writeBytes(work);val written=file.readBytes();require(written.contentEquals(work)&&boxStorageInfo(written)==info){"The destination changed while the batch was written."};val writtenChecks=validateGen7CoreChecksums(written);require(writtenChecks.first){writtenChecks.second};require(pcIsolated(written)){"Unrelated Gen 7 PC data changed after persistence."}
            for((target,bytes,staged) in expected){val off=info.first+target*PK6_STORED_SIZE;val actual=written.copyOfRange(off,off+PK6_STORED_SIZE);val q=parsePk6(actual,0,PK6_STORED_SIZE,false,807)?:error("A persisted PK7 could not be parsed.");require(actual.contentEquals(bytes)&&sameGen2ToGen7Pk7(q,staged)&&gen7DexRegistered(written,q)){"A persisted PK7 or Pokédex registration did not verify."}}
            require(bound()&&validGen2ToGen7Destination(written)){"The Gen 7 destination identity or core save-block integrity changed before batch Bank cleanup."}
            for(item in refreshed){require(bound()){"The destination identity changed before a batch Bank cleanup."}
                require(importedFile?.absolutePath==file.absolutePath&&file.readBytes().contentEquals(work)){"The verified Gen 7 destination changed before Bank cleanup."}
                val cleanup=item.bankFile.readBytes();require(cleanup.contentEquals(item.bankBytes)&&parseGen2BankPayload(cleanup)?.let{sameGen2BankRecord(it,item.source)}==true){"A selected Gen 2 Bank record changed before cleanup."}
                removed.add(item.bankFile to item.bankBytes);require(item.bankFile.delete()){"A selected Gen 2 Bank record could not be removed after destination verification."};require(!item.bankFile.exists()){"A removed Gen 2 Bank record still exists."}
            }
            require(bound()){"The destination identity changed after batch Bank cleanup."}
            require(importedFile?.absolutePath==file.absolutePath&&file.readBytes().contentEquals(work)){"The verified Gen 7 destination changed after Bank cleanup."}
        }catch(e:Exception){
            val bankRestored=if(!writeStarted)true else{
                var restored=true
                for((bank,bytes) in removed){
                    val recovered=runCatching{
                        if(bank.exists())require(bank.readBytes().contentEquals(bytes)){"An existing Bank recovery path changed; it was not overwritten."}
                        else{require(bank.createNewFile()){"A Bank recovery path could not be reserved."};bank.writeBytes(bytes);require(bank.readBytes().contentEquals(bytes)){"A recovered Bank record did not verify."}}
                    }.isSuccess
                    restored=recovered&&restored
                }
                restored&&prepared.all{runCatching{it.bankFile.readBytes().contentEquals(it.bankBytes)}.getOrDefault(false)}
            }
            val destinationRestored=!writeStarted||(bankRestored&&runCatching{file.writeBytes(fresh)}.isSuccess&&runCatching{file.readBytes().contentEquals(fresh)}.getOrDefault(false)&&runCatching{file.readBytes().contentEquals(fresh)&&validGen2ToGen7Destination(fresh)}.getOrDefault(false))
            val recovery=if(!writeStarted)"Nothing was written to the save and no Bank record was removed." else  if(bankRestored&&destinationRestored)"The exact Gen 7 destination and every selected Gen 2 Bank record were restored or kept and verified." else  "Automatic recovery could not be verified. Stop editing and keep the working save and remaining Bank records until a verified backup and Bank contents have been reviewed."
            showDialog("Gen 2 → Gen 7 multi-transfer failed",(e.message?:"Unknown error")+"\n\n$recovery"+(safetyBackup?.let{"\n\nRecovery backup: "+it.name}?:""));return
        }
        selectedBankFiles.clear();bankMultiSelectMode=false;Toast.makeText(this,"Transferred ${prepared.size} Gen 2 Pokémon → Gen 7 Box ${targetBox+1} and verified",Toast.LENGTH_LONG).show();showBank()
    }

    private fun withdrawGen2BankToBox(bankFile:File, mon:Gen2Pokemon, openedFile:File) {
        val openedSource=currentSourceUri;val openedLabel=currentSourceLabel
        fun bound()=importedFile?.absolutePath==openedFile.absolutePath&&currentSourceUri==openedSource&&currentSourceLabel==openedLabel
        if(importedFile?.absolutePath!=openedFile.absolutePath){showDialog("Withdraw","The active save changed after the Bank entry opened. Reopen PSE Bank. Nothing was changed.");return}
        val file=openedFile;val openedDestination=runCatching{file.readBytes()}.getOrNull()?:return;val openedProfile=detectGen2Profile(openedDestination)?:run{showDialog("Withdraw","Load a valid Gold, Silver or Crystal save first.");return}
        if(!gen2ChecksumValid(openedDestination,openedProfile)){showDialog("Withdraw","The Gen 2 destination checksum is invalid. Nothing was changed.");return}
        val openedBank=runCatching{bankFile.readBytes()}.getOrNull()?:run{showDialog("Withdraw","The selected Gen 2 Bank record could not be read.");return};val opened=parseGen2BankPayload(openedBank)
        if(opened==null||!sameGen2BankRecord(opened,mon)){showDialog("Withdraw","The selected Gen 2 Bank record changed. Reopen PSE Bank and try again.");return}
        val targets=availableGen2BoxTargets(openedDestination);if(targets.isEmpty()){showDialog("Withdraw","No Gen 2 PC box has room.");return}
        var consumed=false
        AlertDialog.Builder(this).setTitle("Withdraw to…").setItems(targets.map{(b,e)->gen2BoxDestinationLabel(b,e,file,openedProfile,currentSourceUri,openedDestination)}.toTypedArray()){_,which->
            if(consumed||which !in targets.indices){consumed=true;showDialog("Withdraw","This destination choice was already handled or is invalid. Reopen PSE Bank. Nothing was changed.");return@setItems}
            consumed=true
            if(!bound()){showDialog("Withdraw","The source identity changed after the box list opened. Reopen PSE Bank. Nothing was changed.");return@setItems}
            if(importedFile?.absolutePath!=file.absolutePath){showDialog("Withdraw","The active save changed after the box list opened. Reopen PSE Bank. Nothing was changed.");return@setItems}
            val box=targets[which].first;var writeStarted=false;var bankDeleteAttempted=false;val fresh=runCatching{file.readBytes()}.getOrNull()?:return@setItems
            var safetyBackup:File?=null
            try{
                require(bound()&&verifyGen2SaveIntegrity(fresh).first&&detectGen2Profile(fresh)?.key==openedProfile.key){"The captured Gen 2 destination identity, integrity or profile changed."}
                require(fresh.contentEquals(openedDestination)){"The Gen 2 destination changed after the box list opened."};val profile=detectGen2Profile(fresh)?:error("The fresh Gen 2 destination is invalid.");require(gen2ChecksumValid(fresh,profile)){"The fresh Gen 2 checksum is invalid."}
                val currentBank=bankFile.readBytes();require(currentBank.contentEquals(openedBank)){"The selected Gen 2 Bank bytes changed before withdrawal."};val source=parseGen2BankPayload(currentBank)?:error("The selected Gen 2 Bank record is invalid.");require(sameGen2BankRecord(source,opened)){"The selected Gen 2 Pokémon changed before withdrawal."}
                require(box in 1..14){"The selected Gen 2 destination box is invalid."};val location="Box $box";val before=gen2LocationPayloads(fresh,location,profile);require(before.size<20){"Box $box is now full."};val work=fresh.copyOf();val o=GEN2_BANK_HEADER_SIZE;val monRaw=currentBank.copyOfRange(o,o+32);val otRaw=currentBank.copyOfRange(o+32,o+43);val nickRaw=currentBank.copyOfRange(o+43,o+54);val slot=appendGen2BoxPokemon(work,box,monRaw,otRaw,nickRaw)
                markGen2PokedexOwnedSeen(work,profile,source.species);updateGen2PrimaryChecksum(work,profile);val stagedProfile=detectGen2Profile(work)?:error("The staged Gen 2 save failed checksum verification.");require(gen2ChecksumValid(work,stagedProfile)){"The staged Gen 2 checksum is invalid."};val stagedPayloads=gen2LocationPayloads(work,location,stagedProfile);require(stagedPayloads.size==before.size+1&&sameGen2PayloadList(stagedPayloads.take(before.size),before)){"Existing Gen 2 box records changed during withdrawal staging."};val staged=parseGen2Box(work,box).firstOrNull{it.slot==slot};require(staged!=null&&sameGen2BankRecord(staged,source)){"The staged Gen 2 Bank record did not preserve every supported field."};require(gen2BoxRawCore(work,box,slot).contentEquals(monRaw)&&gen2PokedexOwnedSeen(work,stagedProfile,source.species)){"The exact record or Gen 2 Pokédex registration did not stage."}
                require(verifyGen2SaveIntegrity(work).first&&stagedProfile.key==openedProfile.key){"The complete staged Gen 2 withdrawal failed integrity or profile validation."}
                val backup=File.createTempFile(backupGameName(file)+"_PreGen2BankWithdraw_",".backup",backupsDir());safetyBackup=backup
                backup.writeBytes(fresh);require(backup.readBytes().contentEquals(fresh)){"The withdrawal recovery backup did not persist exactly."}
                retainGen2SafetyBackup(backup,fresh)
                require(bankFile.readBytes().contentEquals(openedBank)){"The selected Gen 2 Bank record changed during staging."}
                require(importedFile?.absolutePath==file.absolutePath&&file.readBytes().contentEquals(fresh)){"The active Gen 2 destination changed during staging. Nothing was written."}
                require(bound()&&backup.readBytes().contentEquals(fresh)&&isBackupKept(backup)){"The source identity or retained recovery backup changed before withdrawal."}
                writeStarted=true
                file.writeBytes(work);val written=file.readBytes();require(written.contentEquals(work)){"The Gen 2 destination changed while withdrawal was written."};val writtenProfile=detectGen2Profile(written)?:error("The persisted Gen 2 save failed checksum verification.");require(gen2ChecksumValid(written,writtenProfile)){"The persisted Gen 2 checksum is invalid."};val afterPayloads=gen2LocationPayloads(written,location,writtenProfile);require(afterPayloads.size==stagedPayloads.size&&sameGen2PayloadList(afterPayloads,stagedPayloads)){"The persisted Gen 2 box records changed after staging."};val q=parseGen2Box(written,box).firstOrNull{it.slot==slot};require(q!=null&&sameGen2BankRecord(q,source)&&gen2BoxRawCore(written,box,slot).contentEquals(monRaw)){"The exact withdrawn Gen 2 Pokémon did not persist."};require(gen2PokedexOwnedSeen(written,writtenProfile,source.species)){"The withdrawn species was not registered Seen and Owned in Gen 2."}
                require(bound()&&writtenProfile.key==openedProfile.key&&verifyGen2SaveIntegrity(written).first){"The complete persisted Gen 2 withdrawal or source identity did not verify."}
                require(importedFile?.absolutePath==file.absolutePath&&file.readBytes().contentEquals(work)){"The verified Gen 2 destination changed before Bank cleanup."}
                require(bound()){"The source identity changed before Bank cleanup."}
                val cleanup=bankFile.readBytes();require(cleanup.contentEquals(openedBank)&&parseGen2BankPayload(cleanup)?.let{sameGen2BankRecord(it,source)}==true){"The selected Gen 2 Bank record changed before cleanup."};bankDeleteAttempted=true;require(bankFile.delete()){"The Bank entry could not be removed after destination verification."};require(!bankFile.exists()){"The removed Bank entry still exists."}
                require(importedFile?.absolutePath==file.absolutePath&&file.readBytes().contentEquals(work)){"The verified Gen 2 destination changed after Bank cleanup."}
                require(bound()){"The source identity changed after Bank cleanup."}
            }catch(e:Exception){
                val bankRestored=if(!writeStarted)true else runCatching{
                    if(bankDeleteAttempted&&!bankFile.exists()){
                        require(bankFile.createNewFile()){"The Bank recovery path could not be reserved."}
                        bankFile.writeBytes(openedBank)
                    }
                    require(bankFile.readBytes().contentEquals(openedBank)){"The original Bank record could not be verified; no existing record was overwritten."}
                }.isSuccess
                val destinationRestored=!writeStarted||(bankRestored&&runCatching{file.writeBytes(fresh)}.isSuccess&&runCatching{file.readBytes().contentEquals(fresh)}.getOrDefault(false))
                val recovery=if(!writeStarted)"Nothing was written to the save and no Bank record was removed." else  if(bankRestored&&destinationRestored)"The exact Gen 2 destination and Bank record were restored or kept and verified." else  "Automatic recovery could not be verified. Stop editing and keep the working save and remaining Bank record until a verified backup and Bank contents have been reviewed."
                showDialog("Withdraw failed",(e.message?:"Unknown error")+"\n\n$recovery"+(safetyBackup?.let{"\n\nRecovery backup: "+it.name}?:""));return@setItems
            }
            Toast.makeText(this,"Withdrawn to Box $box and verified",Toast.LENGTH_LONG).show();showBank()
        }.setNegativeButton("Cancel"){_,_->consumed=true}.setOnCancelListener{consumed=true}.show()
    }

    private fun updateGen1MainChecksum(data: ByteArray) {
        require(data.size == SIZE_G1) { "Not a 32 KB Gen 1 save" }
        var sum = 0
        for (i in GEN1_MAIN_START until GEN1_CHECKSUM_OFFSET) sum = (sum + (data[i].toInt() and 0xFF)) and 0xFF
        data[GEN1_CHECKSUM_OFFSET] = (sum.inv() and 0xFF).toByte()
    }

    private fun gen1PartyStructureError(data:ByteArray):String? {
        if(data.size!=SIZE_G1)return "The Gen 1 party is outside a 32 KB save."
        val count=data[GEN1_PARTY_COUNT].toInt() and 0xFF
        if(count !in 0..6)return "The Gen 1 party count is invalid."
        if((data[GEN1_PARTY_SPECIES+count].toInt() and 0xFF)!=0xFF)return "The Gen 1 party species list has no terminator."
        for(slot in 0 until count){
            val listed=data[GEN1_PARTY_SPECIES+slot].toInt() and 0xFF
            val stored=data[GEN1_PARTY_MONS+slot*GEN1_PARTY_MON_SIZE].toInt() and 0xFF
            if(listed==0||listed==0xFF||stored==0||stored==0xFF||listed!=stored)return "Gen 1 party slot ${slot+1} has inconsistent species metadata."
        }
        return null
    }

    private fun parseGen1Party(data: ByteArray): List<Gen1Pokemon> {
        if (data.size != SIZE_G1 || !hasValidGen1MainChecksum(data) || gen1PartyStructureError(data)!=null) return emptyList()
        val count = data[GEN1_PARTY_COUNT].toInt() and 0xFF
        val result = mutableListOf<Gen1Pokemon>()
        for (slot in 0 until count) {
            val speciesList = data[GEN1_PARTY_SPECIES + slot].toInt() and 0xFF
            val o = GEN1_PARTY_MONS + slot * GEN1_PARTY_MON_SIZE
            if (o + GEN1_PARTY_MON_SIZE > data.size) break
            val species = data[o].toInt() and 0xFF
            if (species == 0 || species == 0xFF || speciesList == 0xFF) continue
            result += Gen1Pokemon(
                slot = slot,
                species = species,
                nickname = readGen1Text(data, GEN1_PARTY_NICKS + slot * 11, 11),
                otName = readGen1Text(data, GEN1_PARTY_OT_NAMES + slot * 11, 11),
                level = data[o + 33].toInt() and 0xFF,
                currentHp = readU16BE(data, o + 1),
                maxHp = readU16BE(data, o + 34),
                moves = IntArray(4) { i -> data[o + 8 + i].toInt() and 0xFF },
                movePP = IntArray(4) { i -> data[o + 29 + i].toInt() and 0x3F },
                movePpUps = IntArray(4) { i -> (data[o + 29 + i].toInt() ushr 6) and 3 },
                experience = readU24BE(data, o + 14),
                tid = readU16BE(data, o + 12),
                statExp = IntArray(5) { i -> readU16BE(data, o + 17 + i * 2) },
                dvs = gen1ReadDvs(data, o + 27)
            )
        }
        return result
    }

    private fun gen1CurrentBoxStatusError(data:ByteArray):String? {
        if(data.size!=SIZE_G1)return "The Gen 1 current-box status is outside a 32 KB save."
        val rawIndex=data[GEN1_CURRENT_BOX_NUMBER].toInt() and 0x7F
        if(rawIndex !in 0..11)return "The Gen 1 current-box index is invalid."
        return null
    }

    private fun gen1CurrentBoxNumber(data: ByteArray): Int {
        if (data.size <= GEN1_CURRENT_BOX_NUMBER) return 1
        return ((data[GEN1_CURRENT_BOX_NUMBER].toInt() and 0x7F) + 1).coerceIn(1, 12)
    }

    private fun gen1StoredBoxesInitialised(data: ByteArray): Boolean {
        if (data.size <= GEN1_CURRENT_BOX_NUMBER) return false
        return (data[GEN1_CURRENT_BOX_NUMBER].toInt() and 0x80) != 0
    }

    private fun gen1StoredBoxOffset(boxNumber: Int): Int = when (boxNumber) {
        in 1..6 -> GEN1_BOX_BANK2_START + (boxNumber - 1) * GEN1_BOX_SIZE
        in 7..12 -> GEN1_BOX_BANK3_START + (boxNumber - 7) * GEN1_BOX_SIZE
        else -> -1
    }

    private fun gen1StoredBoxChecksumOffset(boxNumber: Int): Int = when (boxNumber) {
        in 1..6 -> GEN1_BANK2_INDIVIDUAL_CHECKSUMS + (boxNumber - 1)
        in 7..12 -> GEN1_BANK3_INDIVIDUAL_CHECKSUMS + (boxNumber - 7)
        else -> -1
    }

    private fun gen1BoxChecksum(data: ByteArray, offset: Int): Int {
        if (offset < 0 || offset + GEN1_BOX_SIZE > data.size) return -1
        var sum = 0
        for (i in offset until offset + GEN1_BOX_SIZE) sum = (sum + (data[i].toInt() and 0xFF)) and 0xFF
        return sum xor 0xFF
    }

    private fun gen1BoxStructureError(data:ByteArray,boxNumber:Int):String? {
        if(data.size!=SIZE_G1||boxNumber !in 1..12)return "The Gen 1 box location is invalid."
        val isCurrent=boxNumber==gen1CurrentBoxNumber(data)
        if(!isCurrent&&!gen1StoredBoxesInitialised(data))return null
        val offset=if(isCurrent)GEN1_CURRENT_BOX_DATA else gen1StoredBoxOffset(boxNumber)
        if(offset<0||offset+GEN1_BOX_SIZE>data.size)return "Box $boxNumber is outside the Gen 1 save."
        val count=data[offset].toInt() and 0xFF
        if(count !in 0..GEN1_BOX_CAPACITY)return "Box $boxNumber has an invalid Pokémon count."
        if((data[offset+GEN1_BOX_SPECIES_LIST+count].toInt() and 0xFF)!=0xFF)return "Box $boxNumber has no species-list terminator."
        for(slot in 0 until count){
            val listed=data[offset+GEN1_BOX_SPECIES_LIST+slot].toInt() and 0xFF
            val stored=data[offset+GEN1_BOX_MONS+slot*GEN1_BOX_MON_SIZE].toInt() and 0xFF
            if(listed==0||listed==0xFF||stored==0||stored==0xFF||listed!=stored)return "Box $boxNumber slot ${slot+1} has inconsistent species metadata."
        }
        return null
    }

    private fun parseGen1Box(data: ByteArray, boxNumber: Int): Gen1BoxResult {
        val currentBox = gen1CurrentBoxNumber(data)
        val isCurrent = boxNumber == currentBox
        val offset = if (isCurrent) GEN1_CURRENT_BOX_DATA else gen1StoredBoxOffset(boxNumber)
        if (offset < 0 || offset + GEN1_BOX_SIZE > data.size) return Gen1BoxResult(boxNumber, isCurrent, false, emptyList())

        val checksumValid: Boolean? = if (isCurrent) {
            // The current box copy lives inside the main checksum-protected save block.
            hasValidGen1MainChecksum(data)
        } else if (!gen1StoredBoxesInitialised(data)) {
            null
        } else {
            val checksumOffset = gen1StoredBoxChecksumOffset(boxNumber)
            checksumOffset in data.indices && gen1BoxChecksum(data, offset) == (data[checksumOffset].toInt() and 0xFF)
        }

        // Before the player changes boxes for the first time, the game's stored box banks are not initialised.
        if (!isCurrent && !gen1StoredBoxesInitialised(data)) return Gen1BoxResult(boxNumber, false, null, emptyList())
        if(gen1BoxStructureError(data,boxNumber)!=null)return Gen1BoxResult(boxNumber,isCurrent,false,emptyList())

        val count = data[offset].toInt() and 0xFF
        val mons = mutableListOf<Gen1Pokemon>()
        for (slot in 0 until count) {
            val listedSpecies = data[offset + GEN1_BOX_SPECIES_LIST + slot].toInt() and 0xFF
            val monOffset = offset + GEN1_BOX_MONS + slot * GEN1_BOX_MON_SIZE
            if (monOffset + GEN1_BOX_MON_SIZE > data.size) break
            val species = data[monOffset].toInt() and 0xFF
            if (listedSpecies == 0xFF || species == 0 || species == 0xFF) continue
            mons += Gen1Pokemon(
                slot = slot,
                species = species,
                nickname = readGen1Text(data, offset + GEN1_BOX_NICKS + slot * 11, 11),
                otName = readGen1Text(data, offset + GEN1_BOX_OT_NAMES + slot * 11, 11),
                level = data[monOffset + 3].toInt() and 0xFF,
                currentHp = readU16BE(data, monOffset + 1),
                maxHp = 0,
                moves = IntArray(4) { i -> data[monOffset + 8 + i].toInt() and 0xFF },
                movePP = IntArray(4) { i -> data[monOffset + 29 + i].toInt() and 0x3F },
                movePpUps = IntArray(4) { i -> (data[monOffset + 29 + i].toInt() ushr 6) and 3 },
                experience = readU24BE(data, monOffset + 14),
                tid = readU16BE(data, monOffset + 12),
                statExp = IntArray(5) { i -> readU16BE(data, monOffset + 17 + i * 2) },
                dvs = gen1ReadDvs(data, monOffset + 27)
            )
        }
        return Gen1BoxResult(boxNumber, isCurrent, checksumValid, mons)
    }

    private fun gen1PokemonCard(p: Gen1Pokemon, showPartyHp: Boolean): LinearLayout {
        return LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(dp(16), dp(14), dp(16), dp(14))
            background = roundedBg(Color.rgb(12, 42, 57), Color.rgb(22, 137, 190), 1)
            addView(TextView(this@MainActivity).apply {
                text = "${p.nickname.ifBlank { "Pokémon" }}  •  Lv.${p.level}"
                textSize = 19f
                typeface = Typeface.DEFAULT_BOLD
                setTextColor(TEXT)
            })
            addView(TextView(this@MainActivity).apply {
                val hp = if (showPartyHp && p.maxHp > 0) "  •  HP ${p.currentHp}/${p.maxHp}" else ""
                text = "Gen 1 species ID ${p.species}$hp\n" +
                    "OT ${p.otName.ifBlank { "—" }}  •  TID ${p.tid}\n" +
                    "Moves: ${p.moves.filter { it != 0 }.joinToString(", ") { "#$it" }}"
                textSize = 14f
                setTextColor(MUTED)
                setPadding(0, dp(5), 0, 0)
            })
        }
    }


    private fun gen1NationalDexFromDefaultName(name: String): Int? {
        val normal = name.uppercase()
            .replace("♀", "F")
            .replace("♂", "M")
            .replace(".", "")
            .replace("'", "")
            .replace("’", "")
            .replace("-", "")
            .replace(" ", "")
        val names = GEN1_NATIONAL_NAMES
        for (i in names.indices) {
            val candidate = names[i].uppercase()
                .replace("♀", "F")
                .replace("♂", "M")
                .replace(".", "")
                .replace("'", "")
                .replace("’", "")
                .replace("-", "")
                .replace(" ", "")
            if (candidate == normal) return i + 1
        }
        return null
    }

    private fun loadGen1Sprite(view: ImageView, pokemon: Gen1Pokemon) {
        view.setImageDrawable(null)
        val dex = gen1DexFromInternalIndex(pokemon.species) ?: gen1NationalDexFromDefaultName(pokemon.nickname) ?: return
        val cacheDir = File(filesDir, "sprite_cache").apply { mkdirs() }
        val cacheFile = File(cacheDir, "g1_rb_${dex}.png")
        if (cacheFile.exists() && cacheFile.length() > 0) {
            val bitmap = BitmapFactory.decodeFile(cacheFile.absolutePath)
            if (bitmap != null) {
                bitmap.density = android.graphics.Bitmap.DENSITY_NONE
                view.setImageBitmap(bitmap)
                return
            }
        }
        imageExecutor.execute {
            val urls = listOf(
                "https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/versions/generation-i/red-blue/$dex.png",
                "https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/$dex.png"
            )
            var bitmap: android.graphics.Bitmap? = null
            for (urlText in urls) {
                try {
                    val connection = URL(urlText).openConnection() as HttpsURLConnection
                    connection.connectTimeout = 7000
                    connection.readTimeout = 7000
                    connection.instanceFollowRedirects = true
                    connection.connect()
                    if (connection.responseCode in 200..299) {
                        val bytes = connection.inputStream.use { it.readBytes() }
                        if (bytes.isNotEmpty()) {
                            try { cacheFile.writeBytes(bytes) } catch (_: Exception) { }
                            bitmap = BitmapFactory.decodeByteArray(bytes, 0, bytes.size)
                            connection.disconnect()
                            if (bitmap != null) break
                        }
                    }
                    connection.disconnect()
                } catch (_: Exception) { }
            }
            if (bitmap != null) {
                bitmap.density = android.graphics.Bitmap.DENSITY_NONE
                val ready = bitmap
                mainHandler.post {
                    if (!isFinishing && !isDestroyed) view.setImageBitmap(ready)
                }
            }
        }
    }

    private fun loadGen1Artwork(view: ImageView, pokemon: Gen1Pokemon) {
        view.setImageDrawable(null)
        val dex = gen1DexFromInternalIndex(pokemon.species) ?: return
        val cacheDir = File(filesDir, "artwork_cache").apply { mkdirs() }
        val cacheFile = File(cacheDir, "official_$dex.png")
        if (cacheFile.exists() && cacheFile.length() > 0) {
            BitmapFactory.decodeFile(cacheFile.absolutePath)?.let { bitmap -> bitmap.density = android.graphics.Bitmap.DENSITY_NONE; view.setImageBitmap(bitmap); return }
        }
        imageExecutor.execute {
            val urls = listOf(
                "https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/$dex.png",
                "https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/home/$dex.png",
                "https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/$dex.png"
            )
            var bitmap: android.graphics.Bitmap? = null
            for (urlText in urls) {
                try {
                    val connection = URL(urlText).openConnection() as HttpsURLConnection
                    connection.connectTimeout = 7000; connection.readTimeout = 7000; connection.instanceFollowRedirects = true; connection.connect()
                    if (connection.responseCode in 200..299) {
                        val bytes = connection.inputStream.use { it.readBytes() }
                        if (bytes.isNotEmpty()) { try { cacheFile.writeBytes(bytes) } catch (_: Exception) {} ; bitmap = BitmapFactory.decodeByteArray(bytes,0,bytes.size) }
                    }
                    connection.disconnect(); if (bitmap != null) break
                } catch (_: Exception) {}
            }
            bitmap?.let { ready -> ready.density = android.graphics.Bitmap.DENSITY_NONE; mainHandler.post { if (!isFinishing && !isDestroyed) view.setImageBitmap(ready) } }
        }
    }

    private fun verifyGen1SaveIntegrity(data: ByteArray): Pair<Boolean,String> {
        if(data.size!=SIZE_G1||detectGen2ChecksumProfile(data)!=null)return false to "The candidate data is not a Generation 1 save."
        if (!hasValidGen1MainChecksum(data)) return false to "The Gen 1 main checksum is invalid."
        gen1CurrentBoxStatusError(data)?.let{return false to it}
        gen1PartyStructureError(data)?.let{return false to it}
        if(gen1StoredBoxesInitialised(data)){
            if(!gen1StoredBankChecksumsValid(data,1))return false to "The Gen 1 Box 1-6 bank checksums are invalid."
            if(!gen1StoredBankChecksumsValid(data,7))return false to "The Gen 1 Box 7-12 bank checksums are invalid."
        }
        for (box in 1..12) {
            if(box!=gen1CurrentBoxNumber(data)&&!gen1StoredBoxesInitialised(data))continue
            gen1BoxStructureError(data,box)?.let{return false to it}
        }
        return true to "Gen 1 party, box structure and checksums verified."
    }

