    private fun prepareGen1Evolution(p:Gen1Pokemon,location:String,party:Boolean){
        val live=loadFreshGen1Selection(p,location,party,"Evolve Pokémon")?:return
        val source=live.second
        val dex=gen1DexFromInternalIndex(source.species)?:return showDialog("Evolve Pokémon","This is not a normal Generation 1 species.")
        val choices=gen1EvolutionChoices(dex)
        if(choices.isEmpty())return showDialog("Evolve Pokémon","${gen1SpeciesNameFromInternal(source.species)} has no evolution in Red/Blue/Yellow.")
        fun choose(c:Gen1EvolutionChoice){
            val targetName=GEN1_NATIONAL_NAMES.getOrElse(c.targetDex-1){"Species #${c.targetDex}"}
            AlertDialog.Builder(this).setTitle("Evolve into $targetName?")
                .setMessage("Generation 1 method: ${c.method}.\n\nPSE will change the species in its working copy, preserve this Pokémon's identity, moves, DVs and Stat Exp, rebuild party battle stats when needed, update every affected checksum, re-read the result and roll back automatically if verification fails.")
                .setNegativeButton("Cancel",null)
                .setPositiveButton("Evolve"){_,_->applyGen1Evolution(source,location,party,c)}.show()
        }
        if(choices.size==1)choose(choices[0]) else AlertDialog.Builder(this).setTitle("Choose Gen 1 evolution")
            .setItems(choices.map{c->"${GEN1_NATIONAL_NAMES[c.targetDex-1]} • ${c.method}"}.toTypedArray()){_,i->choose(choices[i])}
            .setNegativeButton("Cancel",null).show()
    }

    private fun applyGen1Evolution(p:Gen1Pokemon,location:String,party:Boolean,choice:Gen1EvolutionChoice){
        val targetInternal=gen1InternalIndexForDex(choice.targetDex)?:return showDialog("Evolve Pokémon","PSE could not map the target species to a Gen 1 internal index.")
        loadGen1SpeciesMetaAsync(choice.targetDex){meta->
            if(meta==null){showDialog("Evolve Pokémon","PSE could not load the target Gen 1 species data needed for a safe evolution.");return@loadGen1SpeciesMetaAsync}
            val oldDex=gen1DexFromInternalIndex(p.species)
            val oldDefault=oldDex?.let{GEN1_NATIONAL_NAMES.getOrNull(it-1)}
            val targetName=GEN1_NATIONAL_NAMES.getOrElse(choice.targetDex-1){meta.name}
            val newNickname=if(oldDefault!=null && p.nickname.equals(oldDefault,true))targetName else p.nickname
            applyGen1PokemonEditFull(p,location,party,meta,targetInternal,newNickname,p.otName,p.tid,p.level,p.experience,p.moves.copyOf(),p.movePP.copyOf(),p.dvs.copyOf(),p.statExp.copyOf()){q->
                val qDex=gen1DexFromInternalIndex(q.species)
                if(qDex!=choice.targetDex){showDialog("Evolve Pokémon","The evolved Pokémon did not verify as $targetName.");return@applyGen1PokemonEditFull}
                Toast.makeText(this,"Evolved to $targetName and verified",Toast.LENGTH_LONG).show()
                showGen1PokemonDetails(q,location,party)
            }
        }
    }

    private fun gen1BoxNameKey(box:Int):String{
        require(box in 1..12){"Gen 1 PC box number must be between 1 and 12."}
        return "gen1_box_$box"
    }
    private fun normaliseGen1BoxCustomName(raw:String):String=raw.trim().take(24)
    private fun gen1BoxCustomName(box:Int):String{
        val stored=getSharedPreferences("pse_box_names",MODE_PRIVATE).getString(gen1BoxNameKey(box),"").orEmpty()
        return normaliseGen1BoxCustomName(stored)
    }
    private fun saveGen1BoxCustomName(box:Int,raw:String){
        val key=gen1BoxNameKey(box);val name=normaliseGen1BoxCustomName(raw)
        val edit=getSharedPreferences("pse_box_names",MODE_PRIVATE).edit()
        if(name.isBlank())edit.remove(key)else edit.putString(key,name)
        edit.apply()
    }
    private fun gen1BoxLabel(box:Int):String{val n=gen1BoxCustomName(box);return if(n.isBlank()) "Box $box" else "Box $box • $n"}
    private fun editGen1BoxName(box:Int){
        gen1BoxNameKey(box)
        val input=EditText(this).apply{setText(gen1BoxCustomName(box));hint="e.g. Team, Training, Trades";setSingleLine(true)}
        AlertDialog.Builder(this).setTitle("Name Box $box").setView(input).setPositiveButton("Save"){_,_->
            saveGen1BoxCustomName(box,input.text.toString())
            showGen1PokemonViewer("boxes",box)
        }.setNeutralButton("Clear name"){_,_->
            saveGen1BoxCustomName(box,"")
            showGen1PokemonViewer("boxes",box)
        }.setNegativeButton("Cancel",null).show()
    }

    private fun loadFreshGen1Selection(p:Gen1Pokemon,location:String,party:Boolean,title:String):Pair<ByteArray,Gen1Pokemon>?{
        val file=importedFile?:run{showDialog(title,"No working save is loaded. Nothing was changed.");return null}
        val data=runCatching{file.readBytes()}.getOrElse{showDialog(title,"The working Gen 1 save could not be read. Nothing was changed.");return null}
        val integrity=verifyGen1SaveIntegrity(data)
        if(!integrity.first){showDialog(title,integrity.second+" Nothing was changed.");return null}
        val box=gen1BoxNumberFromLocation(location)
        val current=if(party)parseGen1Party(data).firstOrNull{it.slot==p.slot}else box?.let{parseGen1Box(data,it).pokemon.firstOrNull{q->q.slot==p.slot}}
        if(current==null||!sameGen1TransferRecord(current,p,party)){showDialog(title,"The selected Pokémon changed after this screen was opened. Reopen My Pokémon and try again. Nothing was changed.");return null}
        return data to current
    }

