    private fun gen1RawMonOffset(data:ByteArray,p:Gen1Pokemon,location:String,party:Boolean):Int {
        if(party)return GEN1_PARTY_MONS+p.slot*GEN1_PARTY_MON_SIZE
        val box=gen1BoxNumberFromLocation(location)?:return -1
        val base=gen1BoxDataOffset(data,box)
        return if(base<0)-1 else base+GEN1_BOX_MONS+p.slot*GEN1_BOX_MON_SIZE
    }

    private fun gen1LegalityIntegrityProblems(data:ByteArray,p:Gen1Pokemon,location:String,party:Boolean,meta:Gen1SpeciesMeta?):List<String>{
        val out=mutableListOf<String>()
        val verify=verifyGen1SaveIntegrity(data)
        if(!verify.first)out+=verify.second
        val box=gen1BoxNumberFromLocation(location)
        val current=if(party)parseGen1Party(data).firstOrNull{it.slot==p.slot}else box?.let{parseGen1Box(data,it).pokemon.firstOrNull{q->q.slot==p.slot}}
        if(current==null||!sameGen1TransferRecord(current,p,party))out+="The selected Pokémon changed while the legality check was running."
        val mon=gen1RawMonOffset(data,p,location,party)
        if(mon<0||mon+GEN1_BOX_MON_SIZE>data.size){out+="The Pokémon record is outside the Gen 1 save.";return out}
        val listed=if(party) GEN1_PARTY_SPECIES+p.slot else {
            val b=gen1BoxNumberFromLocation(location)
            if(b==null)-1 else gen1BoxDataOffset(data,b)+GEN1_BOX_SPECIES_LIST+p.slot
        }
        if(listed !in data.indices || (data[listed].toInt() and 0xFF)!=p.species)out+="The species list and Pokémon record disagree."
        val derivedHp=((p.dvs[1] and 1) shl 3) or ((p.dvs[2] and 1) shl 2) or ((p.dvs[3] and 1) shl 1) or (p.dvs[4] and 1)
        if(p.dvs[0]!=derivedHp)out+="HP DV does not match the four stored DVs."
        var emptySeen=false
        for(i in 0..3){if(p.moves[i]==0)emptySeen=true else if(emptySeen)out+="Move ${i+1} appears after an empty move slot."}
        if(meta!=null&&party){
            val expected=gen1CalculatedStats(meta,p.level,p.dvs,p.statExp)
            if(p.maxHp!=expected[0])out+="Party Max HP does not match the Gen 1 stat formula."
            val raw=intArrayOf(readU16BE(data,mon+36),readU16BE(data,mon+38),readU16BE(data,mon+40),readU16BE(data,mon+42))
            for(i in 0..3)if(raw[i]!=expected[i+1])out+="Party ${listOf("Attack","Defense","Speed","Special")[i]} does not match the Gen 1 stat formula."
        }
        return out.distinct()
    }

    private fun gen1DocumentedEventMoveAllowed(p:Gen1Pokemon,dex:Int,moveId:Int):Boolean {
        // International Pokemon Stadium Amnesia Psyduck. Keep the exception identity-specific
        // so an ordinary Psyduck with Amnesia still fails the normal R/B/Y learnability check.
        return dex==54 && p.level==15 && p.otName.equals("STADIUM",true) && p.tid==2000 &&
            p.moves.getOrElse(0){0}==10 && p.moves.getOrElse(1){0}==133 && moveId==133
    }

    private fun showGen1LegalityCheck(p: Gen1Pokemon, location: String, party: Boolean) {
        val dex = gen1DexFromInternalIndex(p.species)
        if (dex == null) {
            showDialog("Deep Legality Report", "PSE cannot run move legality because internal species #${p.species} is not one of the normal 151 Gen 1 Pokémon.")
            return
        }

        val loading = AlertDialog.Builder(this)
            .setTitle("Deep Legality Check")
            .setMessage("Checking ${gen1SpeciesNameFromInternal(p.species)} against Red / Blue / Yellow learnsets…")
            .setCancelable(false)
            .create()
        loading.show()

        loadGen1MoveSourcesAsync(dex) { moveSources ->
            loadGen1MoveNamesAsync(p.moves.toList()) { moveNames ->
                loadGen1SpeciesMetaAsync(dex) { loadedMeta ->
                    if (loading.isShowing) loading.dismiss()

                    val problems = mutableListOf<String>()
                    val warnings = mutableListOf<String>()
                    val speciesName = gen1SpeciesNameFromInternal(p.species)

                    // Core structure.
                    if (p.level !in 1..100) problems += "Level is outside 1–100."
                    if (loadedMeta != null && gen1LevelForExperience(loadedMeta.growth, p.experience) != p.level) {
                        problems += "EXP does not match Lv.${p.level} for ${loadedMeta.name}."
                    }
                    if (p.nickname.length > 10) problems += "Nickname exceeds the Gen 1 limit."
                    if (p.otName.length > 10) problems += "OT name exceeds the Gen 1 limit."
                    if (p.tid !in 0..65535) problems += "Trainer ID is outside 0–65535."
                    if (p.dvs.any { it !in 0..15 }) problems += "One or more DVs are outside 0–15."
                    if (p.statExp.any { it !in 0..65535 }) problems += "One or more Stat Exp values are outside 0–65535."

                    if (party) {
                        if (p.maxHp <= 0) problems += "Party maximum HP is invalid."
                        if (p.currentHp < 0 || p.currentHp > p.maxHp) problems += "Party current HP is invalid."
                    }

                    val liveData=importedFile?.let{runCatching{it.readBytes()}.getOrNull()}
                    val checksumOk=liveData?.let{verifyGen1SaveIntegrity(it).first}==true
                    if(liveData==null) problems += "The working Gen 1 save could not be read."
                    else problems.addAll(gen1LegalityIntegrityProblems(liveData,p,location,party,loadedMeta))
                    if (!checksumOk) problems += "The Gen 1 main save checksum is invalid."

                    val seen = mutableSetOf<Int>()
                    for (i in p.moves.indices) {
                        val moveId = p.moves[i]
                        val pp = p.movePP[i]

                        if (moveId !in 0..165) {
                            problems += "Move ${i + 1} (#$moveId) is outside the Gen 1 move range."
                            continue
                        }

                        if (pp !in 0..63) {
                            problems += "Move ${i + 1} PP is outside 0–63."
                        }

                        if (moveId == 0) {
                            if (pp != 0) warnings += "Move ${i + 1} is empty but has PP $pp."
                            continue
                        }

                        val moveName = moveNames[moveId] ?: moveSources?.get(moveId)?.name ?: "Move #$moveId"

                        if (!seen.add(moveId)) {
                            problems += "$moveName (#$moveId) appears more than once in the active moveset."
                        }

                        if (moveSources != null) {
                            val source = moveSources[moveId]
                            if (source == null) {
                                if (!gen1DocumentedEventMoveAllowed(p,dex,moveId)) {
                                    problems += "$moveName (#$moveId) cannot be learned by $speciesName or its pre-evolutions in Red/Blue/Yellow, and no matching documented event template was found."
                                }
                            } else {
                                val levelOk = source.nonLevelSource ||
                                    (source.minimumLevel != null && source.minimumLevel <= p.level)

                                if (!levelOk) {
                                    problems += "$moveName (#$moveId) is a Gen 1 move for this evolution line, but its earliest level-up source is Lv.${source.minimumLevel}; this Pokémon is only Lv.${p.level}."
                                }
                            }
                        }
                    }

                    if (moveSources == null) {
                        warnings += "R/B/Y move-learnset data could not be loaded. Structural checks ran, but move legality was not verified."
                    }

                    val report = buildString {
                        if (problems.isEmpty() && moveSources != null) {
                            append("✓ No legality problems found.\n\n")
                            append("$speciesName • Species #$dex • Lv.${p.level}\n")
                            append("$location\n\n")
                            append("✓ R/B/Y move learnability + documented event moves checked\n")
                            if(p.moves.any{gen1DocumentedEventMoveAllowed(p,dex,it)}) append("✓ Matching Pokémon Stadium event template recognized\n")
                            append("✓ Level/EXP consistency checked")
                            append("\n✓ DV / Stat Exp structure checked")
                            if(party)append("\n✓ Party derived stats checked")
                            if (checksumOk) append("\n✓ Working save and box checksums valid")
                        } else if (problems.isEmpty()) {
                            append("✓ No structural problems found.\n\n")
                            append("$speciesName • Species #$dex • Lv.${p.level}\n$location")
                        } else {
                            append("✗ PSE found ${problems.size} legality issue")
                            if (problems.size != 1) append("s")
                            append(":\n\n• ")
                            append(problems.joinToString("\n• "))
                        }

                        if (warnings.isNotEmpty()) {
                            append("\n\nWarnings:\n• ")
                            append(warnings.joinToString("\n• "))
                        }

                        append("\n\nMove legality accepts legal Red, Blue or Yellow acquisition methods, retained pre-evolution moves, and identity-matched documented event moves.")
                    }

                    val builder = AlertDialog.Builder(this)
                        .setTitle("Deep Legality Report")
                        .setMessage(report)
                        .setPositiveButton("Close", null)

                    if (problems.isNotEmpty() && moveSources != null && loadedMeta != null) {
                        val plan = buildGen1LegalFixPlan(p, moveSources, moveNames, loadedMeta)
                        if (plan.changes.isNotEmpty()) {
                            builder.setNeutralButton("Make Legal") { _, _ ->
                                showGen1LegalisationReview(
                                    p, location, party, moveSources, moveNames, loadedMeta, plan
                                )
                            }
                        }
                    }

                    builder.show()
                }
            }
        }
    }

    private fun gen1BoxNumberFromLocation(location: String): Int? {
        if (!location.startsWith("Box ")) return null
        return location.removePrefix("Box ").substringBefore(" ").toIntOrNull()?.coerceIn(1, 12)
    }

    private fun showGen1PokemonEditor(p: Gen1Pokemon, location: String, party: Boolean) {
        val boxNumber = gen1BoxNumberFromLocation(location)
        val file = importedFile ?: return
        val liveSelection=loadFreshGen1Selection(p,location,party,"Edit Pokémon")?:return
        val liveData=liveSelection.first
        if (!party && (boxNumber == null || !gen1BoxIsWritable(liveData, boxNumber))) {
            showDialog("Edit Pokémon", "This Gen 1 box is not safe to write yet. Uninitialised or checksum-invalid stored boxes remain protected.")
            return
        }
        phoneBackAction = { showGen1PokemonDetails(p, location, party) }
        val scroll = ScrollView(this).apply { setBackgroundColor(BG) }
        val root = LinearLayout(this).apply { orientation=LinearLayout.VERTICAL; setPadding(dp(16),dp(58),dp(16),dp(100)); setBackgroundColor(BG) }
        scroll.addView(root)
        root.addView(TextView(this).apply { text="Edit ${p.nickname.ifBlank { gen1SpeciesNameFromInternal(p.species) }}"; textSize=27f; typeface=Typeface.DEFAULT_BOLD; setTextColor(TEXT) })
        addMutedLine(root, "$location • Gen 1 / RBY Pokémon editor")
        addButton(root, "←  Cancel") { showGen1PokemonDetails(p,location,party) }

        addSectionTitle(root,"BASIC")
        val nickname=inputField("Nickname (max 10 Gen 1 characters)",p.nickname).also { root.addView(it.first) }.second
        var selectedDex=gen1DexFromInternalIndex(p.species) ?: 1
        var selectedInternal=p.species
        var selectedMeta: Gen1SpeciesMeta?=gen1MetaMemory[selectedDex]
        val speciesButton=selectorButton("Species","${GEN1_NATIONAL_NAMES[selectedDex-1]} (#$selectedDex)").also { root.addView(it.first) }.second
        loadGen1SpeciesMetaAsync(selectedDex) { m -> if (m?.dex==selectedDex) selectedMeta=m }
        speciesButton.setOnClickListener {
            val choices=GEN1_NATIONAL_NAMES.mapIndexed { i,n -> NamedChoice(i+1,n) }
            showSearchableChoiceDialog("Choose Generation 1 Species",choices) { chosen ->
                val internal=gen1InternalIndexForDex(chosen.id)
                if (internal==null) showDialog("Species","PSE could not map that Pokémon to a normal Gen 1 internal index.") else {
                    selectedDex=chosen.id; selectedInternal=internal; selectedMeta=null; speciesButton.text=chosen.toString()
                    loadGen1SpeciesMetaAsync(chosen.id) { m -> if (selectedDex==chosen.id) selectedMeta=m }
                }
            }
        }
        val level=inputField("Level (1–100)",p.level.toString(),true).also { root.addView(it.first) }.second
        val exp=inputField("Experience",p.experience.toString(),true).also { root.addView(it.first) }.second
        addMutedLine(root,"Species and level changes use original Red/Blue base stats, types, catch rate and growth formulas. Party stats are recalculated automatically.")

        addSectionTitle(root,"TRAINER")
        val ot=inputField("Original Trainer name",p.otName).also { root.addView(it.first) }.second
        val tid=inputField("Trainer ID (0–65535)",p.tid.toString(),true).also { root.addView(it.first) }.second

        addSectionTitle(root,"MOVES / PP")
        val moveIds=p.moves.copyOf(); val ppFields=ArrayList<EditText>()
        for (i in 0..3) {
            val selector=selectorButton("Move ${i+1}",if(p.moves[i]==0) "None" else "Move #${p.moves[i]}").also { root.addView(it.first) }.second
            if (p.moves[i]!=0) { val oldId=p.moves[i]; resolvePokeApiNameAsync("move",oldId) { n -> if(n!=null && moveIds[i]==oldId) selector.text="$n (#$oldId)" } }
            val pp=inputField("Move ${i+1} PP (0–63)",p.movePP[i].toString(),true).also { root.addView(it.first) }.second; ppFields.add(pp)
            selector.setOnClickListener { openCatalogPicker("move","Choose Gen 1 Move ${i+1}",false) { chosen ->
                if(chosen.id !in 1..165) showDialog("Gen 1 move","${chosen.name} (#${chosen.id}) did not exist in Generation 1.") else {
                    moveIds[i]=chosen.id; selector.text=chosen.toString(); resolveMovePpAsync(chosen.id) { base -> if(base!=null) pp.setText(base.coerceAtMost(63).toString()) }
                }
            } }
        }

        addSectionTitle(root,"DVs")
        val dvNames=arrayOf("Attack","Defense","Speed","Special"); val dvFields=ArrayList<EditText>()
        for(i in 0..3) dvFields.add(inputField("${dvNames[i]} DV (0–15)",p.dvs[i+1].toString(),true).also { root.addView(it.first) }.second)
        addMutedLine(root,"HP DV is derived automatically from Attack, Defense, Speed and Special. The same DV pattern determines Gen 2 shininess when transferred forward.")

        addSectionTitle(root,"STAT EXP")
        val seNames=arrayOf("HP","Attack","Defense","Speed","Special"); val seFields=ArrayList<EditText>()
        for(i in 0..4) seFields.add(inputField("${seNames[i]} Stat Exp (0–65535)",p.statExp[i].toString(),true).also { root.addView(it.first) }.second)

        if(party) { addSectionTitle(root,"PARTY STATUS"); addDetailLine(root,"Current HP",p.currentHp.toString()); addDetailLine(root,"Max HP",p.maxHp.toString()); addMutedLine(root,"PSE recalculates Max HP, Attack, Defense, Speed and Special after stat-affecting edits.") }

        addButton(root,"💾  Save Changes") {
            val meta=selectedMeta
            if(meta==null || meta.dex!=selectedDex) { showDialog("Species data still loading","PSE needs the original Gen 1 species data before it can safely recalculate this Pokémon. Check your connection and try again.") }
            else {
                val nn=nickname.text.toString().trim(); val no=ot.text.toString().trim(); val nt=tid.text.toString().toIntOrNull(); val nl=level.text.toString().toIntOrNull(); val ne=exp.text.toString().toLongOrNull()
                val pp=IntArray(4) { ppFields[it].text.toString().toIntOrNull() ?: -1 }; val core=IntArray(4) { dvFields[it].text.toString().toIntOrNull() ?: -1 }
                val ndv=intArrayOf(((core[0] and 1) shl 3) or ((core[1] and 1) shl 2) or ((core[2] and 1) shl 1) or (core[3] and 1),core[0],core[1],core[2],core[3])
                val nse=IntArray(5) { seFields[it].text.toString().toIntOrNull() ?: -1 }
                when {
                    nn.length>10 || no.length>10 -> showDialog("Invalid values","Nickname and OT must be 10 characters or fewer.")
                    nn.any { encodeGen1Char(it)==null } || no.any { encodeGen1Char(it)==null } -> showDialog("Invalid values","Nickname/OT contains characters Gen 1 cannot store.")
                    nt==null || nt !in 0..65535 -> showDialog("Invalid values","Trainer ID must be 0–65535.")
                    nl==null || nl !in 1..100 -> showDialog("Invalid values","Level must be 1–100.")
                    ne==null || ne !in 0..0xFFFFFF -> showDialog("Invalid values","Experience is outside the Gen 1 24-bit range.")
                    moveIds.any { it !in 0..165 } || pp.any { it !in 0..63 } -> showDialog("Invalid values","Move or PP value is outside Gen 1 limits.")
                    core.any { it !in 0..15 } -> showDialog("Invalid values","DVs must be 0–15.")
                    nse.any { it !in 0..65535 } -> showDialog("Invalid values","Stat Exp must be 0–65535.")
                    else -> {
                        val minExp=gen1ExperienceForLevel(meta.growth,nl); val next=if(nl<100) gen1ExperienceForLevel(meta.growth,nl+1) else Long.MAX_VALUE
                        fun commit(xp:Long) { AlertDialog.Builder(this).setTitle("Save Pokémon changes?").setMessage("PSE will recalculate derived stats, rebuild every affected checksum, re-read the Pokémon and roll back automatically if verification fails.").setPositiveButton("Save") { _,_-> applyGen1PokemonEditFull(p,location,party,meta,selectedInternal,nn,no,nt,nl,xp,moveIds.copyOf(),pp,ndv,nse) }.setNegativeButton("Cancel",null).show() }
                        if(ne<minExp || ne>=next) AlertDialog.Builder(this).setTitle("Level and EXP do not match").setMessage("Set EXP to $minExp, the minimum for Lv.$nl ${meta.name}?").setPositiveButton("Set EXP & Continue") { _,_-> exp.setText(minExp.toString()); commit(minExp) }.setNegativeButton("Cancel",null).show() else commit(ne)
                    }
                }
            }
        }
        addMutedLine(root,"Gen 1 editor v0.36.1 • Species, Level/EXP, Moves/PP, DVs, Stat Exp, trainer data and nickname are editable with post-write verification.")
        setContentView(scroll)
    }

    private fun applyGen1PokemonEditFull(p:Gen1Pokemon,location:String,party:Boolean,meta:Gen1SpeciesMeta,speciesInternal:Int,nickname:String,otName:String,tid:Int,level:Int,experience:Long,moves:IntArray,pp:IntArray,dvs:IntArray,statExp:IntArray,ppUps:IntArray=p.movePpUps,afterSave:((Gen1Pokemon)->Unit)?=null) {
        val file=importedFile ?: return
        val fresh=runCatching { file.readBytes() }.getOrElse { showDialog("Gen 1 edit failed","The fresh Gen 1 save could not be read. Nothing was changed.");return }
        val data=fresh.copyOf()
        fun sameStored(a:Gen1Pokemon,b:Gen1Pokemon)=a.species==b.species&&a.tid==b.tid&&a.nickname==b.nickname&&a.otName==b.otName&&a.level==b.level&&a.currentHp==b.currentHp&&a.maxHp==b.maxHp&&a.experience==b.experience&&a.moves.contentEquals(b.moves)&&a.movePP.contentEquals(b.movePP)&&a.movePpUps.contentEquals(b.movePpUps)&&a.statExp.contentEquals(b.statExp)&&a.dvs.contentEquals(b.dvs)
        try {
            val integrity=verifyGen1SaveIntegrity(fresh);require(integrity.first){integrity.second}
            require(data.size==SIZE_G1 && hasValidGen1MainChecksum(data)) { "The fresh Gen 1 save did not pass its main checksum." }
            require(gen1DexFromInternalIndex(speciesInternal)==meta.dex) { "The target species data does not match the Gen 1 species index." }
            require(nickname.length<=10 && otName.length<=10 && nickname.all { encodeGen1Char(it)!=null } && otName.all { encodeGen1Char(it)!=null }) { "The nickname or OT name cannot be stored in Gen 1." }
            require(tid in 0..65535 && level in 1..100 && experience in 0..0xFFFFFF) { "A Gen 1 identity, level or experience value is invalid." }
            require(moves.size==4 && pp.size==4 && ppUps.size==4 && dvs.size==5 && statExp.size==5 && moves.all { it in 0..165 } && pp.all { it in 0..63 } && ppUps.all { it in 0..3 } && dvs.all { it in 0..15 } && statExp.all { it in 0..65535 }) { "A Gen 1 move, PP, PP Up, DV or Stat Exp value is invalid." }
            val box=gen1BoxNumberFromLocation(location); val mon:Int; val nick:Int; val ot:Int; val list:Int
            if(party) { mon=GEN1_PARTY_MONS+p.slot*GEN1_PARTY_MON_SIZE; nick=GEN1_PARTY_NICKS+p.slot*11; ot=GEN1_PARTY_OT_NAMES+p.slot*11; list=GEN1_PARTY_SPECIES+p.slot }
            else { require(box!=null && gen1BoxIsWritable(data,box)); val base=gen1BoxDataOffset(data,box); mon=base+GEN1_BOX_MONS+p.slot*GEN1_BOX_MON_SIZE; nick=base+GEN1_BOX_NICKS+p.slot*11; ot=base+GEN1_BOX_OT_NAMES+p.slot*11; list=base+GEN1_BOX_SPECIES_LIST+p.slot }
            val source=if(party)parseGen1Party(data).firstOrNull { it.slot==p.slot } else parseGen1Box(data,requireNotNull(box)).pokemon.firstOrNull { it.slot==p.slot }
            require(source!=null && sameStored(source,p)) { "The selected Pokémon changed before the edit was applied. Nothing was changed." }
            data[mon]=speciesInternal.toByte(); data[list]=speciesInternal.toByte(); data[mon+3]=level.toByte(); data[mon+5]=meta.type1.toByte(); data[mon+6]=meta.type2.toByte(); data[mon+7]=meta.catchRate.toByte()
            writeGen1Text(data,nick,11,nickname); writeGen1Text(data,ot,11,otName); writeU16BE(data,mon+12,tid); writeU24BE(data,mon+14,experience)
            for(i in 0..4) writeU16BE(data,mon+17+i*2,statExp[i])
            data[mon+27]=(((dvs[1] and 15) shl 4) or (dvs[2] and 15)).toByte(); data[mon+28]=(((dvs[3] and 15) shl 4) or (dvs[4] and 15)).toByte()
            for(i in 0..3) { data[mon+8+i]=moves[i].toByte(); data[mon+29+i]=((ppUps[i] shl 6) or pp[i]).toByte() }
            if(party) { data[mon+33]=level.toByte(); val stats=gen1CalculatedStats(meta,level,dvs,statExp); val max=stats[0].coerceAtLeast(1); val cur=when{p.currentHp<=0->0;p.maxHp<=0->max;p.currentHp>=p.maxHp->max;else->((p.currentHp.toLong()*max+p.maxHp/2)/p.maxHp).toInt().coerceIn(1,max)}; writeU16BE(data,mon+1,cur); writeU16BE(data,mon+34,max); for(i in 1..4) writeU16BE(data,mon+34+i*2,stats[i]); updateGen1MainChecksum(data) }
            else updateGen1ChecksumsAfterBoxChange(data,requireNotNull(box))
            val precheck=verifyGen1WriteState(data,if(party)null else requireNotNull(box)); require(precheck.first){precheck.second}
            if(party){val partyPre=verifyGen1PartyDerivedStats(data,p.slot,meta);require(partyPre.first){partyPre.second}}
            file.writeBytes(data); val verify=file.readBytes(); require(verify.contentEquals(data)){"The save changed while the Gen 1 Pokémon edit was being written."}; val postcheck=verifyGen1WriteState(verify,if(party)null else requireNotNull(box));require(postcheck.first){postcheck.second};
            if(party){val partyPost=verifyGen1PartyDerivedStats(verify,p.slot,meta);require(partyPost.first){partyPost.second}}
            val q=if(party) parseGen1Party(verify).firstOrNull { it.slot==p.slot } else parseGen1Box(verify,requireNotNull(box)).pokemon.firstOrNull { it.slot==p.slot }
            require(q!=null && q.species==speciesInternal && q.nickname==nickname && q.otName==otName && q.tid==tid && q.level==level && q.experience==experience && q.moves.contentEquals(moves) && q.movePP.contentEquals(pp) && q.movePpUps.contentEquals(ppUps) && q.dvs.contentEquals(dvs) && q.statExp.contentEquals(statExp)) { "Edited values did not verify." }
            Toast.makeText(this,"Gen 1 Pokémon updated, recalculated and verified",Toast.LENGTH_LONG).show(); if(afterSave!=null) afterSave(q) else showGen1PokemonDetails(q,location,party)
        } catch(e:Exception) { runCatching { file.writeBytes(fresh) }; showDialog("Gen 1 edit failed","No changes were kept. ${e.message ?: "Unknown error"}") }
    }

    private fun gen1CopyBlock(data:ByteArray,src:Int,dst:Int,size:Int) { if(size>0 && src!=dst) data.copyOfRange(src,src+size).copyInto(data,dst) }
    private fun gen1ClearBlock(data:ByteArray,start:Int,size:Int,textBlock:Boolean=false) { java.util.Arrays.fill(data,start,start+size,if(textBlock)0x50.toByte() else 0.toByte()) }
    private fun gen1RawPokemonParts(data:ByteArray,p:Gen1Pokemon,location:String,party:Boolean):Triple<ByteArray,ByteArray,ByteArray> {
        if(party) { val m=GEN1_PARTY_MONS+p.slot*GEN1_PARTY_MON_SIZE; val o=GEN1_PARTY_OT_NAMES+p.slot*11; val n=GEN1_PARTY_NICKS+p.slot*11; return Triple(data.copyOfRange(m,m+GEN1_BOX_MON_SIZE),data.copyOfRange(o,o+11),data.copyOfRange(n,n+11)) }
        val b=requireNotNull(gen1BoxNumberFromLocation(location)); val base=gen1BoxDataOffset(data,b); val m=base+GEN1_BOX_MONS+p.slot*GEN1_BOX_MON_SIZE; val o=base+GEN1_BOX_OT_NAMES+p.slot*11; val n=base+GEN1_BOX_NICKS+p.slot*11; return Triple(data.copyOfRange(m,m+GEN1_BOX_MON_SIZE),data.copyOfRange(o,o+11),data.copyOfRange(n,n+11))
    }
    private fun appendGen1BoxPokemon(data:ByteArray,box:Int,monRaw:ByteArray,otRaw:ByteArray,nickRaw:ByteArray):Int {
        require(gen1BoxIsWritable(data,box)); val base=gen1BoxDataOffset(data,box); val count=(data[base].toInt() and 0xFF).coerceIn(0,GEN1_BOX_CAPACITY); require(count<GEN1_BOX_CAPACITY) { "Box $box is full." }
        data[base]=(count+1).toByte(); data[base+GEN1_BOX_SPECIES_LIST+count]=monRaw[0]; data[base+GEN1_BOX_SPECIES_LIST+count+1]=0xFF.toByte(); monRaw.copyInto(data,base+GEN1_BOX_MONS+count*GEN1_BOX_MON_SIZE); otRaw.copyInto(data,base+GEN1_BOX_OT_NAMES+count*11); nickRaw.copyInto(data,base+GEN1_BOX_NICKS+count*11); updateGen1ChecksumsAfterBoxChange(data,box); return count
    }
    private fun availableGen1BoxTargets(data:ByteArray):List<Pair<Int,Int>> { val out=ArrayList<Pair<Int,Int>>(); for(b in 1..12) if(gen1BoxIsWritable(data,b)) { val base=gen1BoxDataOffset(data,b); val c=(data[base].toInt() and 0xFF).coerceIn(0,GEN1_BOX_CAPACITY); if(c<GEN1_BOX_CAPACITY) out.add(b to GEN1_BOX_CAPACITY-c) }; return out }
    private fun confirmGen1Duplicate(p:Gen1Pokemon,location:String,party:Boolean) {
        val live=loadFreshGen1Selection(p,location,party,"Duplicate Pokémon")?:return
        val targets=availableGen1BoxTargets(live.first)
        if(targets.isEmpty()){showDialog("Duplicate Pokémon","No writable Gen 1 PC box has an empty slot.");return}
        AlertDialog.Builder(this).setTitle("Duplicate to…").setItems(targets.map{(box,empty)->"Box $box • $empty empty"}.toTypedArray()){_,which->duplicateGen1Pokemon(live.second,location,party,targets[which].first)}.setNegativeButton("Cancel",null).show()
    }
    private fun duplicateGen1Pokemon(p:Gen1Pokemon,location:String,party:Boolean,target:Int) {
        val f=importedFile?:return
        val fresh=runCatching{f.readBytes()}.getOrElse{showDialog("Duplicate failed","The fresh Gen 1 save could not be read. Nothing was changed.");return}
        try {
            val integrity=verifyGen1SaveIntegrity(fresh);require(integrity.first){integrity.second}
            require(fresh.size==SIZE_G1 && hasValidGen1MainChecksum(fresh)){"The fresh Gen 1 save failed validation."}
            val sourceBox=if(party)null else requireNotNull(gen1BoxNumberFromLocation(location))
            val source=if(party)parseGen1Party(fresh).firstOrNull{it.slot==p.slot}else parseGen1Box(fresh,sourceBox!!).pokemon.firstOrNull{it.slot==p.slot}
            require(source!=null && source.species==p.species && source.tid==p.tid && source.nickname==p.nickname && source.otName==p.otName && source.level==p.level && source.experience==p.experience && source.moves.contentEquals(p.moves) && source.movePP.contentEquals(p.movePP) && source.movePpUps.contentEquals(p.movePpUps) && source.statExp.contentEquals(p.statExp) && source.dvs.contentEquals(p.dvs)){"The selected Pokémon changed before duplication. Nothing was changed."}
            require(gen1BoxIsWritable(fresh,target)){"Box $target is not writable."}
            val before=parseGen1Box(fresh,target).pokemon
            require(before.size<GEN1_BOX_CAPACITY){"Box $target is full."}
            val parts=gen1RawPokemonParts(fresh,source,location,party)
            val d=fresh.copyOf()
            val slot=appendGen1BoxPokemon(d,target,parts.first,parts.second,parts.third)
            val pre=verifyGen1WriteState(d,target);require(pre.first){pre.second}
            val staged=parseGen1Box(d,target).pokemon
            require(staged.size==before.size+1){"The staged destination count did not increase by one."}
            val stagedCopy=staged.firstOrNull{it.slot==slot}
            require(stagedCopy!=null && stagedCopy.species==source.species && stagedCopy.tid==source.tid && stagedCopy.nickname==source.nickname && stagedCopy.otName==source.otName && stagedCopy.level==source.level && stagedCopy.experience==source.experience && stagedCopy.moves.contentEquals(source.moves) && stagedCopy.movePP.contentEquals(source.movePP) && stagedCopy.movePpUps.contentEquals(source.movePpUps) && stagedCopy.statExp.contentEquals(source.statExp) && stagedCopy.dvs.contentEquals(source.dvs)){"The staged duplicate did not preserve every stored field."}
            f.writeBytes(d)
            val written=f.readBytes();require(written.contentEquals(d)){"The save changed while the Gen 1 duplicate was being written."};val post=verifyGen1WriteState(written,target);require(post.first){post.second}
            val after=parseGen1Box(written,target).pokemon;require(after.size==before.size+1){"The persisted destination count did not increase by one."}
            val q=after.firstOrNull{it.slot==slot}
            require(q!=null && q.species==source.species && q.tid==source.tid && q.nickname==source.nickname && q.otName==source.otName && q.level==source.level && q.experience==source.experience && q.moves.contentEquals(source.moves) && q.movePP.contentEquals(source.movePP) && q.movePpUps.contentEquals(source.movePpUps) && q.statExp.contentEquals(source.statExp) && q.dvs.contentEquals(source.dvs)){"The duplicate did not verify after re-reading the save."}
            val preserved=if(party)parseGen1Party(written).firstOrNull{it.slot==source.slot}else parseGen1Box(written,sourceBox!!).pokemon.firstOrNull{it.slot==source.slot}
            require(preserved!=null && sameGen1TransferRecord(preserved,source,party)){"The original Pokémon changed during duplication."}
            Toast.makeText(this,"Duplicate created in Box $target • Slot ${slot+1}",Toast.LENGTH_LONG).show();showGen1PokemonViewer("boxes",target)
        } catch(e:Exception) {
            runCatching{f.writeBytes(fresh)};showDialog("Duplicate failed",e.message?:"Unknown error")
        }
    }

    private fun removeGen1PartySlot(data:ByteArray,slot:Int) { val c=(data[GEN1_PARTY_COUNT].toInt() and 0xFF).coerceIn(0,6); require(slot in 0 until c); for(i in slot until c-1){data[GEN1_PARTY_SPECIES+i]=data[GEN1_PARTY_SPECIES+i+1];gen1CopyBlock(data,GEN1_PARTY_MONS+(i+1)*GEN1_PARTY_MON_SIZE,GEN1_PARTY_MONS+i*GEN1_PARTY_MON_SIZE,GEN1_PARTY_MON_SIZE);gen1CopyBlock(data,GEN1_PARTY_OT_NAMES+(i+1)*11,GEN1_PARTY_OT_NAMES+i*11,11);gen1CopyBlock(data,GEN1_PARTY_NICKS+(i+1)*11,GEN1_PARTY_NICKS+i*11,11)}; val n=c-1; data[GEN1_PARTY_COUNT]=n.toByte(); data[GEN1_PARTY_SPECIES+n]=0xFF.toByte(); gen1ClearBlock(data,GEN1_PARTY_MONS+n*GEN1_PARTY_MON_SIZE,GEN1_PARTY_MON_SIZE);gen1ClearBlock(data,GEN1_PARTY_OT_NAMES+n*11,11,true);gen1ClearBlock(data,GEN1_PARTY_NICKS+n*11,11,true);updateGen1MainChecksum(data) }
    private fun removeGen1BoxSlot(data:ByteArray,box:Int,slot:Int) { require(gen1BoxIsWritable(data,box)); val base=gen1BoxDataOffset(data,box); val c=(data[base].toInt() and 0xFF).coerceIn(0,GEN1_BOX_CAPACITY); require(slot in 0 until c); for(i in slot until c-1){data[base+GEN1_BOX_SPECIES_LIST+i]=data[base+GEN1_BOX_SPECIES_LIST+i+1];gen1CopyBlock(data,base+GEN1_BOX_MONS+(i+1)*GEN1_BOX_MON_SIZE,base+GEN1_BOX_MONS+i*GEN1_BOX_MON_SIZE,GEN1_BOX_MON_SIZE);gen1CopyBlock(data,base+GEN1_BOX_OT_NAMES+(i+1)*11,base+GEN1_BOX_OT_NAMES+i*11,11);gen1CopyBlock(data,base+GEN1_BOX_NICKS+(i+1)*11,base+GEN1_BOX_NICKS+i*11,11)};val n=c-1;data[base]=n.toByte();data[base+GEN1_BOX_SPECIES_LIST+n]=0xFF.toByte();gen1ClearBlock(data,base+GEN1_BOX_MONS+n*GEN1_BOX_MON_SIZE,GEN1_BOX_MON_SIZE);gen1ClearBlock(data,base+GEN1_BOX_OT_NAMES+n*11,11,true);gen1ClearBlock(data,base+GEN1_BOX_NICKS+n*11,11,true);updateGen1ChecksumsAfterBoxChange(data,box) }
    private fun deleteGen1PokemonFromData(data:ByteArray,p:Gen1Pokemon,location:String,party:Boolean){
        if(party){removeGen1PartySlot(data,p.slot);return}
        val box=requireNotNull(gen1BoxNumberFromLocation(location));removeGen1BoxSlot(data,box,p.slot)
    }

    private fun confirmGen1Delete(p:Gen1Pokemon,location:String,party:Boolean) {
        val live=loadFreshGen1Selection(p,location,party,"Delete Pokémon")?:return
        if(party&&parseGen1Party(live.first).size<=1){showDialog("Delete Pokémon","PSE will not delete the final party Pokémon. Move it to the PC first.");return}
        AlertDialog.Builder(this).setTitle("Delete Pokémon?").setMessage("This removes ${live.second.nickname} from $location in PSE's working copy.").setNegativeButton("Cancel",null).setPositiveButton("Delete"){_,_->deleteGen1Pokemon(live.second,location,party)}.show()
    }
    private fun deleteGen1Pokemon(p:Gen1Pokemon,location:String,party:Boolean,quiet:Boolean=false):Boolean {
        val f=importedFile?:return false
        val fresh=runCatching{f.readBytes()}.getOrElse{if(!quiet)showDialog("Delete failed","The fresh Gen 1 save could not be read. Nothing was changed.");return false}
        fun sameStored(a:Gen1Pokemon,b:Gen1Pokemon)=a.species==b.species&&a.tid==b.tid&&a.nickname==b.nickname&&a.otName==b.otName&&a.level==b.level&&a.currentHp==b.currentHp&&a.maxHp==b.maxHp&&a.experience==b.experience&&a.moves.contentEquals(b.moves)&&a.movePP.contentEquals(b.movePP)&&a.movePpUps.contentEquals(b.movePpUps)&&a.statExp.contentEquals(b.statExp)&&a.dvs.contentEquals(b.dvs)
        return try {
            val integrity=verifyGen1SaveIntegrity(fresh);require(integrity.first){integrity.second}
            require(fresh.size==SIZE_G1 && hasValidGen1MainChecksum(fresh)){"The fresh Gen 1 save failed validation."}
            val sourceBox=if(party)null else requireNotNull(gen1BoxNumberFromLocation(location))
            val before=if(party)parseGen1Party(fresh)else parseGen1Box(fresh,sourceBox!!).pokemon
            val source=before.firstOrNull{it.slot==p.slot}
            require(source!=null && sameStored(source,p)){"The selected Pokémon changed before deletion. Nothing was changed."}
            if(party)require(before.size>1){"PSE will not delete the final party Pokémon. Move it to the PC first."}
            val d=fresh.copyOf()
            if(party)removeGen1PartySlot(d,source.slot)else removeGen1BoxSlot(d,sourceBox!!,source.slot)
            val affected=if(party)null else sourceBox
            val pre=verifyGen1WriteState(d,affected);require(pre.first){pre.second}
            val staged=if(party)parseGen1Party(d)else parseGen1Box(d,sourceBox!!).pokemon
            require(staged.size==before.size-1){"The staged source count did not decrease by one."}
            for(i in staged.indices){val expected=before[if(i<source.slot)i else i+1];require(staged[i].slot==i && sameStored(staged[i],expected)){"The staged source did not compact every remaining record correctly."}}
            f.writeBytes(d)
            val written=f.readBytes();require(written.contentEquals(d)){"The save changed while the Gen 1 deletion was being written."};val post=verifyGen1WriteState(written,affected);require(post.first){post.second}
            val after=if(party)parseGen1Party(written)else parseGen1Box(written,sourceBox!!).pokemon
            require(after.size==before.size-1){"The persisted source count did not decrease by one."}
            for(i in after.indices){val expected=before[if(i<source.slot)i else i+1];require(after[i].slot==i && sameStored(after[i],expected)){"A remaining Pokémon changed after deletion was persisted."}}
            if(!quiet){Toast.makeText(this,"Gen 1 Pokémon deleted and verified",Toast.LENGTH_LONG).show();showGen1PokemonViewer(if(party)"party" else "boxes",sourceBox)}
            true
        } catch(e:Exception) {
            runCatching{f.writeBytes(fresh)};if(!quiet)showDialog("Delete failed",e.message?:"Unknown error");false
        }
    }

    private fun buildGen1BankPayload(data:ByteArray,p:Gen1Pokemon,location:String,party:Boolean):ByteArray { val a=gen1RawPokemonParts(data,p,location,party);val out=ByteArray(GEN1_BANK_FILE_SIZE);out[0]='P'.code.toByte();out[1]='S'.code.toByte();out[2]='E'.code.toByte();out[3]='1'.code.toByte();out[4]=1;out[5]=if(party)1 else 0;a.first.copyInto(out,GEN1_BANK_HEADER_SIZE);a.second.copyInto(out,GEN1_BANK_HEADER_SIZE+GEN1_BOX_MON_SIZE);a.third.copyInto(out,GEN1_BANK_HEADER_SIZE+GEN1_BOX_MON_SIZE+11);return out }
    private fun parseGen1BankPayload(raw:ByteArray):Gen1Pokemon? {
        if(raw.size!=GEN1_BANK_FILE_SIZE)return null
        if(raw[0]!='P'.code.toByte() || raw[1]!='S'.code.toByte() || raw[2]!='E'.code.toByte() || raw[3]!='1'.code.toByte())return null
        if((raw[4].toInt() and 0xFF)!=1)return null
        if((raw[5].toInt() and 0xFF) !in 0..1)return null
        val o=GEN1_BANK_HEADER_SIZE
        val s=raw[o].toInt() and 0xFF
        if(gen1DexFromInternalIndex(s)==null)return null
        return Gen1Pokemon(0,s,readGen1Text(raw,o+GEN1_BOX_MON_SIZE+11,11),readGen1Text(raw,o+GEN1_BOX_MON_SIZE,11),raw[o+3].toInt() and 0xFF,readU16BE(raw,o+1),0,IntArray(4){raw[o+8+it].toInt() and 0xFF},IntArray(4){raw[o+29+it].toInt() and 0x3F},readU24BE(raw,o+14),readU16BE(raw,o+12),IntArray(5){readU16BE(raw,o+17+it*2)},gen1ReadDvs(raw,o+27),IntArray(4){(raw[o+29+it].toInt() ushr 6) and 3})
    }
    private fun confirmGen1DepositToBank(p:Gen1Pokemon,location:String,party:Boolean) {
        val live=loadFreshGen1Selection(p,location,party,"Move to PSE Bank")?:return
        if(party&&parseGen1Party(live.first).size<=1){showDialog("Move to PSE Bank","Cannot bank the final party Pokémon.");return}
        AlertDialog.Builder(this).setTitle("Move to PSE Bank?").setMessage("PSE will preserve the original Gen 1 record and remove this Pokémon from $location in the working copy.").setNegativeButton("Cancel",null).setPositiveButton("Move"){_,_->depositGen1ToBank(live.second,location,party)}.show()
    }
    private fun depositGen1ToBank(p:Gen1Pokemon,location:String,party:Boolean) {
        val f=importedFile?:return
        val old=runCatching{f.readBytes()}.getOrNull()?:return
        var bf:File?=null
        try {
            val integrity=verifyGen1SaveIntegrity(old);require(integrity.first){integrity.second}
            require(old.size==SIZE_G1 && hasValidGen1MainChecksum(old)){"The fresh Gen 1 save is invalid."}
            val affected=if(party)null else requireNotNull(gen1BoxNumberFromLocation(location))
            val before=if(party)parseGen1Party(old).sortedBy{it.slot} else parseGen1Box(old,requireNotNull(affected)).pokemon.sortedBy{it.slot}
            val source=before.firstOrNull{it.slot==p.slot}
            require(source!=null && sameGen1TransferRecord(source,p,party)){"The selected Pokémon changed before the Bank deposit. Nothing was changed."}
            if(party)require(before.size>1){"Cannot bank the final party Pokémon."}
            val bankCountBefore=gen1BankEntryCountForDeposit()
            requireGen1BankCapacity(bankCountBefore,1)
            val payload=buildGen1BankPayload(old,source,location,party)
            require(gen1BankEntryCountForDeposit()==bankCountBefore){"PSE Bank changed while the Gen 1 deposit was being staged. Nothing was changed."}
            bf=File.createTempFile("pse1_${gen1DexFromInternalIndex(source.species)?:source.species}_",".pse1",bankDir())
            bf.writeBytes(payload)
            val stored=bf.readBytes();require(stored.contentEquals(payload)){"The staged Bank record changed while it was being written."}
            val staged=parseGen1BankPayload(stored)?:error("The staged Bank record did not parse.")
            require(sameGen1TransferRecord(staged,source)){"The staged Bank record did not preserve the selected Pokémon."}
            require(gen1BankEntryCountForDeposit()==bankCountBefore+1){"PSE Bank changed before the Gen 1 deposit could commit. Nothing was changed."}
            val expectedRemaining=before.filterNot{it.slot==source.slot}
            val d=old.copyOf()
            if(party)removeGen1PartySlot(d,source.slot)else removeGen1BoxSlot(d,requireNotNull(affected),source.slot)
            val pre=verifyGen1WriteState(d,affected);require(pre.first){pre.second}
            val stagedRemaining=if(party)parseGen1Party(d).sortedBy{it.slot} else parseGen1Box(d,requireNotNull(affected)).pokemon.sortedBy{it.slot}
            require(stagedRemaining.size==expectedRemaining.size && stagedRemaining.zip(expectedRemaining).all{(a,b)->sameGen1TransferRecord(a,b,party)}){"A remaining Pokémon changed during Bank deposit staging."}
            f.writeBytes(d)
            val written=f.readBytes();require(written.contentEquals(d)){"The source save changed while the Gen 1 Bank deposit was being written."};val post=verifyGen1WriteState(written,affected);require(post.first){post.second}
            val remaining=if(party)parseGen1Party(written).sortedBy{it.slot} else parseGen1Box(written,requireNotNull(affected)).pokemon.sortedBy{it.slot}
            require(remaining.size==expectedRemaining.size && remaining.zip(expectedRemaining).all{(a,b)->sameGen1TransferRecord(a,b,party)}){"A remaining Pokémon changed after Bank deposit persistence."}
            val committed=bf?:error("The staged Bank record was lost.");val committedBytes=committed.readBytes();require(committed.exists() && committedBytes.contentEquals(payload) && parseGen1BankPayload(committedBytes)?.let{sameGen1TransferRecord(it,source)}==true){"The staged Bank record changed before commit completion."}
            Toast.makeText(this,"Moved to PSE Bank and verified",Toast.LENGTH_LONG).show();showBank()
        } catch(e:Exception) {
            runCatching{f.writeBytes(old)};runCatching{bf?.delete()};showDialog("PSE Bank move failed",e.message?:"Unknown error")
        }
    }
    private fun gen1BankGridCell(slot:Int,pair:Pair<File,Gen1Pokemon>?):LinearLayout { val w=((resources.displayMetrics.widthPixels-dp(44))/6).coerceAtLeast(dp(50));return LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;gravity=Gravity.CENTER;setPadding(dp(2),dp(4),dp(2),dp(4));setBackgroundColor(if(pair==null)Color.rgb(27,27,27)else if(bankMultiSelectMode && selectedBankFiles.contains(pair.first.absolutePath))Color.rgb(25,105,145)else CARD);layoutParams=GridLayout.LayoutParams().apply{width=w;height=dp(82);setMargins(dp(1),dp(1),dp(1),dp(1))};if(pair!=null){isClickable=true;setOnClickListener{if(bankMultiSelectMode){if(!selectedBankFiles.add(pair.first.absolutePath))selectedBankFiles.remove(pair.first.absolutePath);showBank()}else showGen1BankEntry(pair.first,pair.second)};val iv=ImageView(this@MainActivity).apply{scaleType=ImageView.ScaleType.FIT_CENTER};addView(iv,LinearLayout.LayoutParams(dp(52),dp(52)));loadGen1Sprite(iv,pair.second)}else addView(TextView(this@MainActivity).apply{text="○";textSize=24f;gravity=Gravity.CENTER;setTextColor(Color.rgb(80,80,80))},LinearLayout.LayoutParams(dp(52),dp(52)));addView(TextView(this@MainActivity).apply{text=(slot+1).toString();textSize=10f;gravity=Gravity.CENTER;setTextColor(MUTED)})} }
    private fun deleteGen1BankEntry(bankFile:File,openedRaw:ByteArray,opened:Gen1Pokemon) {
        var staged:File?=null
        var fresh:ByteArray?=null
        val failure=runCatching{
            require(bankFile.isFile){"The selected Gen 1 Bank record no longer exists."}
            val current=bankFile.readBytes();fresh=current
            val parsed=parseGen1BankPayload(current)?:error("The selected Gen 1 Bank record is invalid. Nothing was deleted.")
            require(current.contentEquals(openedRaw)&&sameGen1TransferRecord(parsed,opened)){"The selected Gen 1 Bank record changed before deletion. Reopen PSE Bank and try again."}
            val pending=File.createTempFile("pse1_delete_",".pending",bankDir())
            require(pending.delete()){"PSE could not prepare a recoverable Bank deletion."}
            require(bankFile.renameTo(pending)){"PSE could not stage the Bank deletion."};staged=pending
            require(!bankFile.exists()&&pending.isFile&&pending.readBytes().contentEquals(current)){"The staged Bank deletion did not preserve the exact record."}
            require(pending.delete()){"PSE could not commit the Bank deletion."}
        }.exceptionOrNull()
        if(failure!=null){
            val bytes=fresh;val pending=staged
            if(bytes!=null){
                pending?.let{candidate->if(!bankFile.exists()&&candidate.isFile)runCatching{require(candidate.renameTo(bankFile))}}
                if(!bankFile.exists())runCatching{bankFile.writeBytes(bytes)}
                runCatching{pending?.delete()}
            }
            showDialog("PSE Bank",(failure.message?:"The Bank entry could not be deleted.")+" The preserved record was kept where possible.")
            return
        }
        Toast.makeText(this,"Bank entry deleted",Toast.LENGTH_SHORT).show();showBank()
    }

    private fun showGen1BankEntry(bankFile:File,p:Gen1Pokemon) {
        val openedRaw=runCatching{bankFile.readBytes()}.getOrElse{showDialog("PSE Bank","The selected Gen 1 Bank record could not be read.");return}
        val opened=parseGen1BankPayload(openedRaw)
        if(opened==null||!sameGen1TransferRecord(opened,p)){showDialog("PSE Bank","The selected Gen 1 Bank record changed. Reopen PSE Bank and try again.");return}
        val currentGen = importedFile?.let { generationForSize(it.length().toInt()) } ?: 0

        val message = buildString {
            append("Lv.${opened.level} • OT ${opened.otName.ifBlank { "—" }} • Original RBY record preserved")
            append("\n\n")
            when (currentGen) {
                1 -> append("A Gen 1 save is loaded. You can withdraw this Pokémon back into an initialized PC box.")
                2 -> append("A Gen 2 save is loaded. You can transfer this preserved Gen 1 Pokémon into a Gold, Silver or Crystal PC box using the Generation I → II Time Capsule record conversion.")
                4 -> append("A Gen 4 save is loaded. You can create a native PK4 conversion and place it in validated PC storage.")
                5 -> append("A Gen 5 save is loaded. You can create a native PK5 conversion and place it in validated PC storage.")
                7 -> append("A Gen 7 save is loaded. You can transfer this preserved Gen 1 Pokémon forward using the Virtual Console → Poké Transporter / Bank conversion path.")
                6 -> append("A Gen 6 save is loaded. You can create a PSE native PK6 direct re-home and place it in validated PC storage.")
                else -> append("Load a Gen 1 save to withdraw it, a Gen 2 save for Time Capsule conversion, or a Gen 7 save for the Virtual Console transfer path.")
            }
        }

        val builder = AlertDialog.Builder(this)
            .setTitle("${opened.nickname.ifBlank { gen1SpeciesNameFromInternal(opened.species) }} • Gen 1 Bank")
            .setMessage(message)
            .setNegativeButton("Close", null)
            .setNeutralButton("Delete") { _, _ ->
                AlertDialog.Builder(this)
                    .setTitle("Delete Bank entry?")
                    .setMessage("This permanently removes the preserved Gen 1 Bank copy.")
                    .setNegativeButton("Cancel", null)
                    .setPositiveButton("Delete") { _, _ ->
                        deleteGen1BankEntry(bankFile,openedRaw,opened)
                    }
                    .show()
            }

        when (currentGen) {
            1 -> builder.setPositiveButton("Withdraw to Save") { _, _ ->
                withdrawGen1BankToBox(bankFile,openedRaw,opened)
            }
            2 -> builder.setPositiveButton("Transfer to Gen 2") { _, _ ->
                chooseGen1BankToGen2Destination(bankFile, p)
            }
            3 -> builder.setPositiveButton("Convert to Gen 3") { _, _ ->
                chooseGen1BankToGen3Destination(bankFile, p)
            }
            4 -> builder.setPositiveButton("Convert to Gen 4") { _, _ ->
                chooseGen1BankToGen4Destination(bankFile, p)
            }
            5 -> builder.setPositiveButton("Convert to Gen 5") { _, _ ->
                chooseGen1BankToGen5Destination(bankFile, p)
            }
            6 -> builder.setPositiveButton("Convert to Gen 6") { _, _ ->
                chooseGen1BankToGen6Destination(bankFile, p)
            }
            7 -> builder.setPositiveButton("Transfer to Gen 7") { _, _ ->
                prepareGen1ForwardTransfer(bankFile, p)
            }
        }

        builder.show()
    }

    private fun withdrawGen1BankToBox(bankFile:File,openedRaw:ByteArray,p:Gen1Pokemon) {
        val f=importedFile?:return
        val initial=runCatching{f.readBytes()}.getOrElse{showDialog("Withdraw","The loaded Gen 1 save could not be read. Nothing was changed.");return}
        val initialIntegrity=verifyGen1SaveIntegrity(initial)
        if(!initialIntegrity.first){showDialog("Withdraw",initialIntegrity.second+" Nothing was changed.");return}
        val targets=availableGen1BoxTargets(initial)
        if(targets.isEmpty()){showDialog("Withdraw","No writable Gen 1 box has room.");return}
        AlertDialog.Builder(this).setTitle("Withdraw to…").setItems(targets.map{(b,e)->"Box $b • $e empty"}.toTypedArray()){_,which->
            val box=targets[which].first
            val fresh=runCatching{f.readBytes()}.getOrElse{showDialog("Withdraw failed","The fresh Gen 1 save could not be read. Nothing was changed.");return@setItems}
            val raw=runCatching{bankFile.readBytes()}.getOrElse{showDialog("Withdraw failed","The selected Bank record could not be read. Nothing was changed.");return@setItems}
            val parsed=parseGen1BankPayload(raw)?:run{showDialog("Withdraw failed","The selected Bank record is invalid. Nothing was changed.");return@setItems}
            try {
                val freshIntegrity=verifyGen1SaveIntegrity(fresh);require(freshIntegrity.first){freshIntegrity.second}
                val available=availableGen1BoxTargets(fresh).firstOrNull{it.first==box}?.second?:0
                require(available>0){"Box $box is no longer writable or has become full."}
                require(raw.contentEquals(openedRaw)&&sameGen1TransferRecord(parsed,p)){"The selected Bank record changed before withdrawal. Nothing was changed."}
                val before=parseGen1Box(fresh,box).pokemon.sortedBy{it.slot}
                val d=fresh.copyOf();val o=GEN1_BANK_HEADER_SIZE
                val slot=appendGen1BoxPokemon(d,box,raw.copyOfRange(o,o+GEN1_BOX_MON_SIZE),raw.copyOfRange(o+GEN1_BOX_MON_SIZE,o+GEN1_BOX_MON_SIZE+11),raw.copyOfRange(o+GEN1_BOX_MON_SIZE+11,GEN1_BANK_FILE_SIZE))
                val dex=gen1DexFromInternalIndex(parsed.species)?:error("Withdrawn Pokémon species could not be mapped to the Gen 1 Pokédex.")
                markGen1PokedexCaught(d,dex);updateGen1MainChecksum(d)
                val bit=dex-1;val mask=1 shl(bit%8);require((d[0x25A3+bit/8].toInt() and mask)!=0&&(d[0x25B6+bit/8].toInt() and mask)!=0){"Withdrawn Pokémon Pokédex registration was not staged."}
                val pre=verifyGen1WriteState(d,box);require(pre.first){pre.second}
                val staged=parseGen1Box(d,box).pokemon.sortedBy{it.slot}
                require(staged.size==before.size+1 && staged.take(before.size).zip(before).all{(a,b)->sameGen1TransferRecord(a,b)}){"The staged destination changed an existing Pokémon."}
                val stagedAdded=staged.firstOrNull{it.slot==slot};require(stagedAdded!=null && sameGen1TransferRecord(stagedAdded,parsed)){"The staged withdrawn Pokémon did not preserve every supported field."}
                f.writeBytes(d)
                val written=f.readBytes();require(written.contentEquals(d)){"The destination save changed while the Gen 1 Bank withdrawal was being written."};val post=verifyGen1WriteState(written,box);require(post.first){post.second}
                val after=parseGen1Box(written,box).pokemon.sortedBy{it.slot}
                require(after.size==before.size+1 && after.take(before.size).zip(before).all{(a,b)->sameGen1TransferRecord(a,b)}){"An existing destination Pokémon changed after Bank withdrawal persistence."}
                val q=after.firstOrNull{it.slot==slot};require(q!=null && sameGen1TransferRecord(q,parsed)){"The withdrawn Pokémon did not verify after re-reading the save."}
                val bit2=dex-1;val mask2=1 shl(bit2%8);require((written[0x25A3+bit2/8].toInt() and mask2)!=0&&(written[0x25B6+bit2/8].toInt() and mask2)!=0){"Withdrawn Pokémon did not register Seen + Caught after the save was re-read."}
                val committedRaw=bankFile.readBytes();require(committedRaw.contentEquals(raw) && parseGen1BankPayload(committedRaw)?.let{sameGen1TransferRecord(it,parsed)}==true){"The selected Bank record changed before cleanup. The destination save was restored."}
                if(!bankFile.delete()){f.writeBytes(fresh);error("The Pokémon was written, but the Bank entry could not be removed. The save was restored to avoid duplication.")}
                Toast.makeText(this,"Withdrawn to Box $box and verified",Toast.LENGTH_LONG).show();showGen1PokemonViewer("boxes",box)
            } catch(e:Exception) {
                runCatching{f.writeBytes(fresh)};showDialog("Withdraw failed","${e.message?:"Unknown error"}\n\nThe fresh working save was restored and the Bank entry was kept where possible.")
            }
        }.setNegativeButton("Cancel",null).show()
    }

    private fun gen1GridTile(p: Gen1Pokemon?, location: String, party: Boolean): LinearLayout {
        return LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            gravity = Gravity.CENTER
            setPadding(dp(4), dp(7), dp(4), dp(7))
            background = roundedBg(
                if (p == null) Color.rgb(9, 29, 39) else Color.rgb(12, 42, 57),
                if (p == null) Color.rgb(31, 58, 70) else Color.rgb(22, 137, 190),
                1
            )
            val sprite = ImageView(this@MainActivity).apply {
                scaleType = ImageView.ScaleType.FIT_CENTER
                contentDescription = p?.nickname ?: "Empty slot"
            }
            addView(sprite, LinearLayout.LayoutParams(-1, dp(58)))
            if (p != null) loadGen1Sprite(sprite, p)
            addView(TextView(this@MainActivity).apply {
                text = p?.nickname?.ifBlank { "Pokémon" } ?: "EMPTY"
                textSize = 10.5f
                typeface = Typeface.DEFAULT_BOLD
                gravity = Gravity.CENTER
                setTextColor(if (p == null) Color.rgb(94, 119, 132) else TEXT)
                maxLines = 1
                ellipsize = android.text.TextUtils.TruncateAt.END
            }, LinearLayout.LayoutParams(-1, dp(24)))
            addView(TextView(this@MainActivity).apply {
                text = if (p == null) "—" else "Lv.${p.level}"
                textSize = 10f
                gravity = Gravity.CENTER
                setTextColor(MUTED)
            }, LinearLayout.LayoutParams(-1, dp(20)))
            if (p != null) {
                isClickable = true
                isFocusable = true
                if(party && gen1PartyMultiSelectMode && selectedGen1PartySlots.contains(p.slot)) background=roundedBg(Color.rgb(25,105,145),Color.rgb(70,190,255),1)
                if(!party && gen1BoxMultiSelectMode && selectedGen1BoxSlots.contains(p.slot)) background=roundedBg(Color.rgb(25,105,145),Color.rgb(70,190,255),1)
                setOnClickListener {
                    if(party && gen1PartyMultiSelectMode){
                        if(!selectedGen1PartySlots.add(p.slot)) selectedGen1PartySlots.remove(p.slot)
                        showGen1PokemonViewer("party")
                    } else if(!party && gen1BoxMultiSelectMode){
                        if(!selectedGen1BoxSlots.add(p.slot)) selectedGen1BoxSlots.remove(p.slot)
                        val b=gen1BoxNumberFromLocation(location) ?: gen1CurrentBoxNumber(importedFile?.readBytes() ?: ByteArray(0))
                        showGen1PokemonViewer("boxes",b)
                    } else showGen1PokemonDetails(p, location, party)
                }
            }
        }
    }

    private fun addGen1Grid(root: LinearLayout, pokemon: List<Gen1Pokemon>, capacity: Int, columns: Int, locationPrefix: String, party: Boolean) {
        val rows = (capacity + columns - 1) / columns
        for (row in 0 until rows) {
            val line = LinearLayout(this).apply {
                orientation = LinearLayout.HORIZONTAL
                gravity = Gravity.CENTER
            }
            for (col in 0 until columns) {
                val slot = row * columns + col
                if (slot >= capacity) break
                val p = pokemon.firstOrNull { it.slot == slot }
                val location = if (party) "Party • Slot ${slot + 1}" else "$locationPrefix • Slot ${slot + 1}"
                line.addView(
                    gen1GridTile(p, location, party),
                    LinearLayout.LayoutParams(0, dp(118), 1f).apply {
                        leftMargin = if (col == 0) 0 else dp(3)
                        rightMargin = if (col == columns - 1) 0 else dp(3)
                        topMargin = dp(3)
                        bottomMargin = dp(3)
                    }
                )
            }
            root.addView(line, LinearLayout.LayoutParams(-1, -2))
        }
    }

    private fun showGen1PokemonViewer(tab: String = "party", requestedBox: Int? = null) {
