            if(gen1PartyMultiSelectMode) partySelectBar.addView(Button(this).apply{text="Move (${selectedGen1PartySlots.size})";setAllCaps(false);setTextColor(Color.WHITE);setBackgroundColor(Color.rgb(35,150,75));setOnClickListener{moveSelectedGen1PartyPokemonToBox(party.filter{selectedGen1PartySlots.contains(it.slot)})}},LinearLayout.LayoutParams(0,dp(48),1f))
