                        .setPositiveButton("Initialise") { _, _ -> initialiseGen1Box(boxNumber) }
                        .setNegativeButton("Cancel", null)
                        .show()
                }
            } else {
                val selectBar=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL;gravity=Gravity.CENTER_VERTICAL}
                selectBar.addView(Button(this).apply{text=if(gen1BoxMultiSelectMode)"Cancel" else "Multi-select • Move Pokémon";setAllCaps(false);setTextColor(Color.WHITE);if(!gen1BoxMultiSelectMode)setBackgroundColor(Color.rgb(35,150,75));setOnClickListener{gen1BoxMultiSelectMode=!gen1BoxMultiSelectMode;selectedGen1BoxSlots.clear();showGen1PokemonViewer("boxes",boxNumber)}},LinearLayout.LayoutParams(0,dp(48),1f))
                if(gen1BoxMultiSelectMode) selectBar.addView(Button(this).apply{text="Move (${selectedGen1BoxSlots.size})";setAllCaps(false);setTextColor(Color.WHITE);setBackgroundColor(Color.rgb(35,150,75));setOnClickListener{
                    val chosen=box.pokemon.filter{selectedGen1BoxSlots.contains(it.slot)}
