                    AlertDialog.Builder(this@MainActivity).setTitle("Move ${chosen.size} selected Pokémon")
                        .setItems(arrayOf("Move to Party","Move to another PC Box","Move to PSE Bank")){_,which->
                            when(which){0->moveSelectedGen1BoxPokemonToParty(boxNumber,chosen);1->moveSelectedGen1BoxPokemonToBox(boxNumber,chosen);else->moveSelectedGen1BoxPokemonToBank(boxNumber,chosen)}
                        }.setNegativeButton("Cancel",null).show()
                }},LinearLayout.LayoutParams(0,dp(48),1f))
                if(gen1BoxMultiSelectMode) selectBar.addView(Button(this).apply{text="Delete (${selectedGen1BoxSlots.size})";setAllCaps(false);setTextColor(Color.WHITE);setBackgroundColor(Color.rgb(35,150,75));setOnClickListener{confirmDeleteSelectedGen1Box(boxNumber,box.pokemon.filter{selectedGen1BoxSlots.contains(it.slot)})}},LinearLayout.LayoutParams(0,dp(48),1f))
                if(gen1BoxMultiSelectMode) selectBar.addView(Button(this).apply{text="Duplicate (${selectedGen1BoxSlots.size})";setAllCaps(false);setTextColor(Color.WHITE);setBackgroundColor(Color.rgb(35,150,75));setOnClickListener{duplicateSelectedGen1Box(boxNumber,box.pokemon.filter{selectedGen1BoxSlots.contains(it.slot)})}},LinearLayout.LayoutParams(0,dp(48),1f))
                root.addView(selectBar,LinearLayout.LayoutParams(-1,-2).apply{bottomMargin=dp(6)})
