                addMutedLine(root, "Tap a Pokémon to view details. Empty slots stay visible so the layout matches the in-game 20-slot Gen 1 box.")
            }
        }

        addButton(root, "←  Back to Home") { showHome() }
        scroll.addView(root)
        setContentView(scroll)
    }

    private fun initialiseGen1Box(boxNumber:Int) {
        val file=importedFile ?: return
        val original=runCatching { file.readBytes() }.getOrNull() ?: return
        if(original.size!=SIZE_G1){showDialog("Initialise Box","The working save is not a 32 KB Generation 1 save.");return}
        val originalIntegrity=verifyGen1SaveIntegrity(original)
        if(!originalIntegrity.first){showDialog("Initialise Box",originalIntegrity.second+" Nothing was changed.");return}
        if(boxNumber !in 1..12){showDialog("Initialise Box","That Gen 1 box number is invalid.");return}
        if(boxNumber==gen1CurrentBoxNumber(original)){showDialog("Initialise Box","The current Gen 1 box is already initialised by the game.");return}
        val before=runCatching { parseGen1Box(original,boxNumber) }.getOrNull()
        if(before?.checksumValid!=null){showDialog("Initialise Box","Box $boxNumber already contains stored-box data, so PSE left it unchanged.");return}
        try {
            require(hasValidGen1MainChecksum(original)){"The original Gen 1 main checksum is invalid."}
            require(boxNumber!=gen1CurrentBoxNumber(original)){"The current Gen 1 box cannot be reinitialised."}
            require(parseGen1Box(original,boxNumber).checksumValid==null){"Box $boxNumber is no longer uninitialised."}
            val work=original.copyOf()
            val offset=gen1StoredBoxOffset(boxNumber)
            require(offset>=0 && offset+GEN1_BOX_SIZE<=work.size){"Box $boxNumber storage is outside the save."}
            // A Gen 1 empty box is not all-zero: count=0, species list starts with FF,
            // and every nickname/OT fixed-width string is terminated with 50. Fill the
            // complete record with 50 first, then overwrite structural fields.
            java.util.Arrays.fill(work,offset,offset+GEN1_BOX_SIZE,0x50.toByte())
            work[offset]=0
            work[offset+1]=0xFF.toByte()
            // Clear the 20 fixed-size boxed-Pokemon records; unused species-list bytes
            // remain terminators and unused name fields remain valid Gen 1 terminators.
            val monStart=offset+22
            java.util.Arrays.fill(work,monStart,monStart+(20*GEN1_BOX_MON_SIZE),0.toByte())
            updateGen1StoredBankChecksums(work,boxNumber)
            val allChecksum=if(boxNumber<=6) GEN1_BANK2_ALL_CHECKSUM else GEN1_BANK3_ALL_CHECKSUM
            val individualStart=if(boxNumber<=6) GEN1_BANK2_INDIVIDUAL_CHECKSUMS else GEN1_BANK3_INDIVIDUAL_CHECKSUMS
            require(work.indices.all{it in offset until offset+GEN1_BOX_SIZE||it==allChecksum||it in individualStart until individualStart+6||work[it]==original[it]}){"Initialising the box changed unrelated save data."}
            val prepared=parseGen1Box(work,boxNumber)
            require(prepared.checksumValid==true && prepared.pokemon.isEmpty()){"The new empty box did not pass pre-write verification."}
            val pre=verifyGen1WriteState(work,boxNumber);require(pre.first){pre.second}
            file.writeBytes(work)
            val written=file.readBytes()
            require(written.contentEquals(work)){"The save changed while the Gen 1 box was being initialised."}
            val verified=parseGen1Box(written,boxNumber)
            require(verified.checksumValid==true && verified.pokemon.isEmpty()){"Box $boxNumber did not verify after re-reading the save."}
            val post=verifyGen1WriteState(written,boxNumber);require(post.first){post.second}
            require(hasValidGen1MainChecksum(written)){"The Gen 1 main checksum changed unexpectedly."}
            if(gen1StoredBoxesInitialised(written)) require(gen1StoredBankChecksumsValid(written,boxNumber)){"The Gen 1 stored-box bank checksum did not verify."}
            Toast.makeText(this,"Box $boxNumber initialised and verified",Toast.LENGTH_LONG).show()
            showGen1PokemonViewer("boxes",boxNumber)
        } catch(e:Exception) {
            runCatching { file.writeBytes(original) }
            showDialog("Initialise Box failed","${e.message?:"Unknown error"}\n\nThe original working save was restored.")
        }
    }

    private fun parsePk6(data: ByteArray, offset: Int, size: Int, party: Boolean, maxSpecies: Int = 721): PokemonEntry? {
        if (offset < 0 || offset + size > data.size) return null
        val raw = data.copyOfRange(offset, offset + size)
        if (raw.all { it.toInt() == 0 }) return null
        val pk = decryptPk6IfNeeded(raw)
        val species = readU16LE(pk, 0x08)
        if (species !in 1..maxSpecies) return null

        val heldItem = readU16LE(pk, 0x0A)
        val tid = readU16LE(pk, 0x0C)
        val sid = readU16LE(pk, 0x0E)
        val experience = readU32LE(pk, 0x10)
        val ability = pk[0x14].toInt() and 0xFF
        val abilityNumber = pk[0x15].toInt() and 0x07
        val pid = readU32LE(pk, 0x18)
        val nature = pk[0x1C].toInt() and 0xFF
        val genderForm = pk[0x1D].toInt() and 0xFF
        val gender = (genderForm ushr 1) and 0x3
        val form = genderForm ushr 3
        val evs = intArrayOf(
            pk[0x1E].toInt() and 0xFF,
            pk[0x1F].toInt() and 0xFF,
            pk[0x20].toInt() and 0xFF,
            pk[0x21].toInt() and 0xFF,
            pk[0x22].toInt() and 0xFF,
            pk[0x23].toInt() and 0xFF
        )
        val pokerusState = pk[0x2B].toInt() and 0xFF
        val pokerusDays = pokerusState and 0xF
        val pokerusStrain = pokerusState ushr 4
        val nickname = readGen6String(pk, 0x40, 26)
        val moves = intArrayOf(
            readU16LE(pk, 0x5A), readU16LE(pk, 0x5C), readU16LE(pk, 0x5E), readU16LE(pk, 0x60)
        )
        val movePP = intArrayOf(
            pk[0x62].toInt() and 0xFF, pk[0x63].toInt() and 0xFF,
            pk[0x64].toInt() and 0xFF, pk[0x65].toInt() and 0xFF
        )
        val iv32 = readU32LE(pk, 0x74)
        val ivs = intArrayOf(
            ((iv32 ushr 0) and 0x1F).toInt(),
            ((iv32 ushr 5) and 0x1F).toInt(),
            ((iv32 ushr 10) and 0x1F).toInt(),
            ((iv32 ushr 15) and 0x1F).toInt(),
            ((iv32 ushr 20) and 0x1F).toInt(),
            ((iv32 ushr 25) and 0x1F).toInt()
        )
        val isEgg = (iv32 and 0x40000000L) != 0L
        val isNicknamed = (iv32 and 0x80000000L) != 0L
        val currentHandler = pk[0x93].toInt() and 0xFF
        val friendship = if (currentHandler == 0) pk[0xCA].toInt() and 0xFF else pk[0xA2].toInt() and 0xFF
        val otName = readGen6String(pk, 0xB0, 26)
        val language = pk[0xE3].toInt() and 0xFF
        val markingValue = if (maxSpecies <= 721) pk[0x2A].toInt() and 0xFF else readU16LE(pk, 0x16)
        val fatefulEncounter = (pk[0x1D].toInt() and 0x01) != 0
        val relearnMoves = intArrayOf(
            readU16LE(pk, 0x6A), readU16LE(pk, 0x6C), readU16LE(pk, 0x6E), readU16LE(pk, 0x70)
        )
        val eggYear = pk[0xD1].toInt() and 0xFF
        val eggMonth = pk[0xD2].toInt() and 0xFF
        val eggDay = pk[0xD3].toInt() and 0xFF
        val metYear = pk[0xD4].toInt() and 0xFF
        val metMonth = pk[0xD5].toInt() and 0xFF
        val metDay = pk[0xD6].toInt() and 0xFF
        val eggLocation = readU16LE(pk, 0xD8)
        val metLocation = readU16LE(pk, 0xDA)
        val ball = pk[0xDC].toInt() and 0xFF
        val metLevelGender = pk[0xDD].toInt() and 0xFF
        val metLevel = metLevelGender and 0x7F
        val otGender = (metLevelGender ushr 7) and 1
        val hyperTrainFlags = pk[0xDE].toInt() and 0xFF
        val originGame = pk[0xDF].toInt() and 0xFF
        val country = pk[0xE0].toInt() and 0xFF
        val region = pk[0xE1].toInt() and 0xFF
        val consoleRegion = pk[0xE2].toInt() and 0xFF

        val expectedChecksum = readU16LE(pk, 0x06)
        var calc = 0
        var pos = 0x08
        while (pos + 1 < PK6_STORED_SIZE) {
            calc = (calc + readU16LE(pk, pos)) and 0xFFFF
            pos += 2
        }
        val level = if (party && pk.size > 0xEC) pk[0xEC].toInt() and 0xFF else null
        val shinyValue = tid xor sid xor (pid.toInt() and 0xFFFF) xor ((pid.toInt() ushr 16) and 0xFFFF)
        val shiny = shinyValue < 16

        return PokemonEntry(
            species, nickname, isNicknamed, level, calc == expectedChecksum,
            heldItem, tid, sid, experience, ability, abilityNumber, pid, nature, gender, form,
            evs, moves, movePP, ivs, isEgg, otName, friendship, currentHandler,
            pokerusDays, pokerusStrain, shiny, language, markingValue,
            fatefulEncounter, relearnMoves, eggLocation, metLocation, ball, metLevel, otGender,
            originGame, country, region, consoleRegion, eggYear, eggMonth, eggDay,
            metYear, metMonth, metDay, hyperTrainFlags
        )
    }

    private fun decryptPk6IfNeeded(input: ByteArray): ByteArray {
        val data = input.copyOf()
        if (data.size < PK6_STORED_SIZE) return data
        val encrypted = readU16LE(data, 0xC8) != 0 || readU16LE(data, 0x58) != 0
        if (!encrypted) return data

        val ec = readU32LE(data, 0).toLong() and 0xFFFFFFFFL
        cryptPk6Range(data, 0x08, PK6_STORED_SIZE, ec)
        if (data.size > PK6_STORED_SIZE) cryptPk6Range(data, PK6_STORED_SIZE, data.size, ec)

        val sv = ((ec ushr 13) and 31).toInt()
        shufflePk6(data, 0x08, sv)
        return data
    }

    private fun cryptPk6Range(data: ByteArray, start: Int, end: Int, initialSeed: Long) {
        var seed = initialSeed
        var p = start
        while (p + 1 < end) {
            seed = (0x41C64E6DL * seed + 0x6073L) and 0xFFFFFFFFL
            val xor = ((seed ushr 16) and 0xFFFF).toInt()
            val value = readU16LE(data, p) xor xor
            data[p] = (value and 0xFF).toByte()
            data[p + 1] = ((value ushr 8) and 0xFF).toByte()
            p += 2
        }
    }

    private fun shufflePk6(data: ByteArray, start: Int, sv: Int) {
        if (sv == 0) return
        val order = BLOCK_POSITION
        val base = sv * 4
        val perm = intArrayOf(0, 1, 2, 3)
        val slotOf = intArrayOf(0, 1, 2, 3)
        for (i in 0 until 3) {
            val desired = order[base + i]
            val j = slotOf[desired]
            if (j == i) continue
            swapPk6Blocks(data, start + i * PK6_BLOCK_SIZE, start + j * PK6_BLOCK_SIZE)
            val blockAtI = perm[i]
            perm[j] = blockAtI
            slotOf[blockAtI] = j
        }
    }

    private fun swapPk6Blocks(data: ByteArray, a: Int, b: Int) {
        for (i in 0 until PK6_BLOCK_SIZE) {
            val t = data[a + i]
            data[a + i] = data[b + i]
            data[b + i] = t
        }
    }

    private fun loadGen3Artwork(view: ImageView, species: Int, shiny: Boolean) {
        view.setImageDrawable(null)
        val cacheDir = File(filesDir, "gen3_artwork_cache").apply { mkdirs() }
        val cacheFile = File(cacheDir, "${species}_${if (shiny) "shiny" else "normal"}.png")
        if (cacheFile.exists() && cacheFile.length() > 0) {
            BitmapFactory.decodeFile(cacheFile.absolutePath)?.let {
                it.density = android.graphics.Bitmap.DENSITY_NONE
                view.setImageBitmap(it)
                return
            }
        }
        imageExecutor.execute {
            val urls = buildList {
                if (shiny) add("https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/shiny/$species.png")
                add("https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/$species.png")
                if (shiny) add("https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/shiny/$species.png")
                else add("https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/$species.png")
            }
            var bitmap: android.graphics.Bitmap? = null
            for (urlText in urls) {
                try {
                    val connection = URL(urlText).openConnection() as HttpsURLConnection
                    connection.connectTimeout = 7000
                    connection.readTimeout = 7000
                    connection.instanceFollowRedirects = true
                    connection.connect()
                    if (connection.responseCode in 200..299) {
                        val bytes = connection.inputStream.use { it.readBytes() }
                        if (bytes.isNotEmpty()) {
                            runCatching { cacheFile.writeBytes(bytes) }
                            bitmap = BitmapFactory.decodeByteArray(bytes, 0, bytes.size)
                        }
                    }
                    connection.disconnect()
                    if (bitmap != null) break
                } catch (_: Exception) { }
            }
            bitmap?.let {
                it.density = android.graphics.Bitmap.DENSITY_NONE
                val ready = it
                mainHandler.post { if (!isFinishing && !isDestroyed) view.setImageBitmap(ready) }
            }
        }
    }

    private fun loadPokemonSprite(view: ImageView, species: Int, shiny: Boolean) {
        view.setImageDrawable(null)
        val cacheDir = File(filesDir, "sprite_cache").apply { mkdirs() }
        val cacheFile = File(cacheDir, "${species}_${if (shiny) "shiny" else "normal"}.png")
        if (cacheFile.exists() && cacheFile.length() > 0) {
            val bitmap = BitmapFactory.decodeFile(cacheFile.absolutePath)
            if (bitmap != null) {
                bitmap.density = android.graphics.Bitmap.DENSITY_NONE
                view.setImageBitmap(bitmap)
                return
            }
        }

        imageExecutor.execute {
            val urls = buildList {
                if (shiny) {
                    add("https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/versions/generation-vi/omegaruby-alphasapphire/shiny/$species.png")
                    add("https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/shiny/$species.png")
                } else {
                    add("https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/versions/generation-vi/omegaruby-alphasapphire/$species.png")
                    add("https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/$species.png")
                }
            }
            var bitmap: android.graphics.Bitmap? = null
            for (urlText in urls) {
                try {
                    val connection = URL(urlText).openConnection() as HttpsURLConnection
                    connection.connectTimeout = 7000
                    connection.readTimeout = 7000
                    connection.instanceFollowRedirects = true
                    connection.connect()
                    if (connection.responseCode in 200..299) {
                        val bytes = connection.inputStream.use { it.readBytes() }
                        if (bytes.isNotEmpty()) {
                            try { cacheFile.writeBytes(bytes) } catch (_: Exception) { }
                            bitmap = BitmapFactory.decodeByteArray(bytes, 0, bytes.size)
                            connection.disconnect()
                            if (bitmap != null) break
                        }
                    }
                    connection.disconnect()
                } catch (_: Exception) { }
            }
            if (bitmap != null) {
                bitmap.density = android.graphics.Bitmap.DENSITY_NONE
                val ready = bitmap
                mainHandler.post {
                    if (!isFinishing && !isDestroyed) view.setImageBitmap(ready)
                }
            }
        }
    }


    private fun boxedLocationToGlobalIndex(location: String): Int? {
        val match = Regex("Box (\\d+) • Slot (\\d+)").matchEntire(location) ?: return null
        val box = match.groupValues[1].toIntOrNull()?.minus(1) ?: return null
        val slot = match.groupValues[2].toIntOrNull()?.minus(1) ?: return null
        val maxBox = if (isCurrentGen7()) 31 else 30
        if (box !in 0..maxBox || slot !in 0..29) return null
        return box * 30 + slot
    }

    private fun partyLocationToSlot(location: String): Int? {
        val match = Regex("Slot (\\d+)").matchEntire(location) ?: return null
        val slot = match.groupValues[1].toIntOrNull()?.minus(1) ?: return null
        return slot.takeIf { it in 0..5 }
    }

    private data class PartyStorageInfo(val offset: Int, val blockId: Int, val blockLength: Int, val maxSpecies: Int)

    private fun partyStorageInfo(data: ByteArray): PartyStorageInfo? = when (data.size) {
        SIZE_G6_XY, SIZE_G6_ORAS -> PartyStorageInfo(PARTY_OFFSET, 18, 0x61C, 721)
        SIZE_G7_SM -> PartyStorageInfo(PARTY_OFFSET_SM, 4, 0x61C, 807)
        SIZE_G7_USUM -> PartyStorageInfo(PARTY_OFFSET_USUM, 4, 0x61C, 807)
        else -> null
    }

    private fun readPartyCount(data: ByteArray, info: PartyStorageInfo): Int {
        val pos = info.offset + 6 * PK6_PARTY_SIZE
        return if (pos in data.indices) (data[pos].toInt() and 0xFF).coerceIn(0, 6) else 0
    }

    private fun writePartyCount(data: ByteArray, info: PartyStorageInfo, count: Int) {
        val pos = info.offset + 6 * PK6_PARTY_SIZE
        require(pos in data.indices) { "Party count is outside the save" }
        data[pos] = count.coerceIn(0, 6).toByte()
    }

    private fun updatePartyChecksum(data: ByteArray, info: PartyStorageInfo) {
        updateSaveBlockChecksum(data, info.blockId, info.offset, info.blockLength)
    }

