    private fun generationMetadataNameFor(gen7: Boolean, kind: String, id: Int): String? {
        if (kind != "item") return null
        return if (gen7) GEN7_USUM_ITEM_NAMES[id] else GEN6_ORAS_ITEM_NAMES[id]
    }

    private fun loadResourceChoicesAsync(kind: String, gen7: Boolean, done: (List<NamedChoice>?) -> Unit) {
        val maxId = when (kind) {
            "item" -> if (gen7) 959 else 775
            "move" -> if (gen7) 728 else 621
            "ability" -> if (gen7) 233 else 191
            else -> 0
        }
        val cacheKey = "${kind}_${if (gen7) 7 else 6}_$maxId"
        choiceCatalogCache[cacheKey]?.let { done(it); return }
        imageExecutor.execute {
            val list = try {
                val json = fetchJson("https://pokeapi.co/api/v2/$kind?limit=2000&offset=0")
                val results = json?.optJSONArray("results")
                val byId = linkedMapOf<Int, String>()
                if (results != null) {
                    for (i in 0 until results.length()) {
                        val obj = results.optJSONObject(i) ?: continue
                        val url = obj.optString("url")
                        val id = url.trimEnd('/').substringAfterLast('/').toIntOrNull() ?: continue
                        if (id !in 1..maxId) continue
                        val raw = obj.optString("name")
                        if (raw.isNotBlank()) byId[id] = prettyApiName(raw)
                    }
                }
                if (kind == "item") {
                    val fixes = if (gen7) GEN7_USUM_ITEM_NAMES else GEN6_ORAS_ITEM_NAMES
                    for ((id, name) in fixes) if (id in 1..maxId) byId[id] = name
                }
                val out = byId.entries.sortedBy { it.key }.map { NamedChoice(it.key, it.value) }.toMutableList()
                if (kind == "item" || kind == "move") out.add(0, NamedChoice(0, "None"))
                out
            } catch (_: Exception) { null }
            mainHandler.post {
                if (!isFinishing && !isDestroyed) {
                    if (list != null) choiceCatalogCache[cacheKey] = list
                    done(list)
                }
            }
        }
    }

    private fun loadSpeciesAbilityChoicesAsync(species: Int, currentAbility: Int, gen7: Boolean, done: (List<NamedChoice>?) -> Unit) {
        imageExecutor.execute {
            val result = try {
                val json = fetchJson("https://pokeapi.co/api/v2/pokemon/$species")
                val arr = json?.optJSONArray("abilities")
                val list = mutableListOf<NamedChoice>()
                if (arr != null) {
                    for (i in 0 until arr.length()) {
                        val abilityObj = arr.optJSONObject(i)?.optJSONObject("ability") ?: continue
                        val url = abilityObj.optString("url")
                        val id = url.trimEnd('/').substringAfterLast('/').toIntOrNull() ?: continue
                        if (id > (if (gen7) 233 else 191)) continue
                        val name = prettyApiName(abilityObj.optString("name"))
                        if (name.isNotBlank()) list.add(NamedChoice(id, name))
                    }
                }
                if (currentAbility > 0 && list.none { it.id == currentAbility }) {
                    val currentName = generationMetadataNameFor(gen7, "ability", currentAbility)
                        ?: metaPrefs.getString("name_ability_$currentAbility", null)
                        ?: "Current ability"
                    list.add(NamedChoice(currentAbility, currentName))
                }
                list.distinctBy { it.id }.sortedBy { it.id }
            } catch (_: Exception) { null }
            mainHandler.post { if (!isFinishing && !isDestroyed) done(result) }
        }
    }

    private fun showSearchableChoiceDialog(title: String, choices: List<NamedChoice>, onSelected: (NamedChoice) -> Unit) {
        val container = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(dp(16), dp(8), dp(16), 0)
        }
        val search = EditText(this).apply {
            hint = "Search by name or ID"
            setSingleLine(true)
        }
        val listView = ListView(this)
        container.addView(search, LinearLayout.LayoutParams(-1, -2))
        container.addView(listView, LinearLayout.LayoutParams(-1, dp(420)))

        var filtered = choices
        fun refresh(query: String) {
            val q = query.trim().lowercase(Locale.US)
            filtered = if (q.isBlank()) choices else choices.filter {
                it.name.lowercase(Locale.US).contains(q) || it.id.toString() == q || "#${it.id}" == q
            }
            listView.adapter = ArrayAdapter(this, android.R.layout.simple_list_item_1, filtered.map { it.toString() })
        }
        refresh("")
        val dialog = android.app.AlertDialog.Builder(this)
            .setTitle(title)
            .setView(container)
            .setNegativeButton("Cancel", null)
            .create()
        listView.setOnItemClickListener { _, _, position, _ ->
            filtered.getOrNull(position)?.let {
                dialog.dismiss()
                onSelected(it)
            }
        }
        search.addTextChangedListener(object : android.text.TextWatcher {
            override fun beforeTextChanged(s: CharSequence?, start: Int, count: Int, after: Int) {}
            override fun onTextChanged(s: CharSequence?, start: Int, before: Int, count: Int) { refresh(s?.toString().orEmpty()) }
            override fun afterTextChanged(s: android.text.Editable?) {}
        })
        dialog.show()
    }

    private val EFFECTIVE_HELD_ITEM_CATEGORIES = listOf(
        "held-items",
        // Evolution stones/items are intentionally selectable in PSE because
        // the evolution workflow uses a held item as the explicit authorization
        // to consume a normally bag-used evolution item.
        "evolution",
        "choice",
        "effort-training",
        "bad-held-items",
        "training",
        "plates",
        "species-specific",
        "type-enhancement",
        "mega-stones",
        "z-crystals",
        "memories",
        "jewels"
    )

    private fun loadEffectiveHeldItemChoicesAsync(gen7: Boolean, done: (List<NamedChoice>?) -> Unit) {
        val maxId = if (gen7) 959 else 775
        val cacheKey = "effective_held_item_${if (gen7) 7 else 6}_v3_$maxId"
        choiceCatalogCache[cacheKey]?.let { done(it); return }

        imageExecutor.execute {
            val list = try {
                val byId = linkedMapOf<Int, String>()

                // PSE intentionally uses a whitelist here rather than PokeAPI's broad
                // `holdable` attribute. In the games many ordinary bag items (Poké Balls,
                // Potions, status medicine, etc.) can technically be given to a Pokémon,
                // but they are not meaningful held items. These categories are the actual
                // battle/training/species held-item families we want in the editor.
                for (category in EFFECTIVE_HELD_ITEM_CATEGORIES) {
                    val json = fetchJson("https://pokeapi.co/api/v2/item-category/$category") ?: continue
                    val items = json.optJSONArray("items") ?: continue
                    for (i in 0 until items.length()) {
                        val obj = items.optJSONObject(i) ?: continue
                        val url = obj.optString("url")
                        val id = url.trimEnd('/').substringAfterLast('/').toIntOrNull() ?: continue
                        if (id !in 1..maxId) continue
                        val raw = obj.optString("name")
                        if (raw.isNotBlank()) byId[id] = prettyApiName(raw)
                    }
                }

                // Berries are real held items with in-battle effects, but PokeAPI splits
                // them across berry-specific categories. Berry resource IDs 1..64 map to
                // the Gen 6/7 item table at 126..189.
                val berries = fetchJson("https://pokeapi.co/api/v2/berry?limit=100")?.optJSONArray("results")
                if (berries != null) {
                    for (i in 0 until berries.length()) {
                        val obj = berries.optJSONObject(i) ?: continue
                        val url = obj.optString("url")
                        val berryId = url.trimEnd('/').substringAfterLast('/').toIntOrNull() ?: continue
                        val itemId = 125 + berryId
                        if (itemId !in 126..189 || itemId > maxId) continue
                        val raw = obj.optString("name")
                        if (raw.isNotBlank()) byId[itemId] = "${prettyApiName(raw)} Berry"
                    }
                }

                // Generation-specific indexes above the common catalog need local names
                // because modern PokeAPI resource IDs are not always one-for-one with the
                // Gen 6/7 save-table indexes.
                if (gen7) {
                    for (id in 904..932) {
                        GEN7_USUM_ITEM_NAMES[id]?.let { byId[id] = it }
                    }
                } else {
                    val orasMegaStones = (752..764) + (767..770)
                    for (id in orasMegaStones) {
                        GEN6_ORAS_ITEM_NAMES[id]?.let { byId[id] = it }
                    }
                }

                byId.entries
                    .sortedBy { it.key }
                    .map { NamedChoice(it.key, it.value) }
                    .toMutableList()
                    .apply { add(0, NamedChoice(0, "None")) }
            } catch (_: Exception) { null }

            mainHandler.post {
                if (!isFinishing && !isDestroyed) {
                    if (list != null) choiceCatalogCache[cacheKey] = list
                    done(list)
                }
            }
        }
    }

    private fun openCatalogPicker(kind: String, title: String, gen7: Boolean, onSelected: (NamedChoice) -> Unit) {
        if (kind == "move" && isCurrentGen3Save()) {
            showSearchableChoiceDialog(title, canonicalGen3MoveChoices(), onSelected)
            return
        }
        if (kind == "item" && isCurrentGen3Save()) {
            showSearchableChoiceDialog(title, canonicalGen3ItemChoices(), onSelected)
            return
        }
        val progress = android.app.AlertDialog.Builder(this)
            .setTitle(title)
            .setMessage("Loading Pokémon data…")
            .setCancelable(false)
            .create()
        progress.show()
        val callback: (List<NamedChoice>?) -> Unit = { choices ->
            progress.dismiss()
            if (choices.isNullOrEmpty()) {
                showDialog("Could not load $title", "PSE could not load the name list. Check your internet connection and try again.")
            } else {
                showSearchableChoiceDialog(title, choices, onSelected)
            }
        }
        if (kind == "item") loadEffectiveHeldItemChoicesAsync(gen7, callback)
        else loadResourceChoicesAsync(kind, gen7, callback)
    }

    private fun resolveMovePpAsync(moveId: Int, done: (Int?) -> Unit) {
        if (moveId == 0) { done(0); return }
        if (isCurrentGen3Save()) { done(canonicalGen3MovePp(moveId)); return }
        val cached = metaPrefs.getInt("pp_move_$moveId", -1)
        if (cached >= 0) { done(cached); return }
        imageExecutor.execute {
            val pp = try { fetchJson("https://pokeapi.co/api/v2/move/$moveId")?.optInt("pp", -1)?.takeIf { it >= 0 } } catch (_: Exception) { null }
            if (pp != null) metaPrefs.edit().putInt("pp_move_$moveId", pp).apply()
            mainHandler.post { if (!isFinishing && !isDestroyed) done(pp) }
        }
    }

    private fun showPokemonEditor(location: String, p: PokemonEntry) {
        phoneBackAction = { showPokemonDetails(location, p) }
        val global = boxedLocationToGlobalIndex(location)
        if (global == null) {
            showDialog("Edit Pokémon", "Only boxed Pokémon can be edited. Party editing remains locked while the boxed editor is being tested.")
            return
        }
        val gen7 = isCurrentGen7()
        val scroll = ScrollView(this).apply { setBackgroundColor(BG) }
        val root = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(dp(16), dp(58), dp(16), dp(28))
            setBackgroundColor(BG)
        }
        scroll.addView(root)
        root.addView(TextView(this).apply {
            text = "Edit ${p.nickname.ifBlank { "Species #${p.species}" }}"
            textSize = 27f
            typeface = Typeface.DEFAULT_BOLD
            setTextColor(TEXT)
        })
        addMutedLine(root, "$location • ${if (gen7) "PK7 / Gen 7" else "PK6 / Gen 6"} boxed Pokémon editor")
        addButton(root, "←  Cancel") { showPokemonDetails(location, p) }

        val nickname = inputField("Nickname (max 12 characters)", p.nickname).also { root.addView(it.first) }.second
        var loadedLevel: Int? = p.level
        val levelField = inputField("Level (1–100; changing this adjusts EXP)", p.level?.toString() ?: "", true).also { root.addView(it.first) }.second
        if (p.level == null) {
            levelField.hint = "Calculating…"
            resolveBoxedLevelAsync(p.species, p.experience) { level ->
                loadedLevel = level
                if (level != null && levelField.text.isNullOrBlank()) levelField.setText(level.toString())
            }
        }
        val exp = inputField("Experience", p.experience.toString(), true).also { root.addView(it.first) }.second

        addSectionTitle(root, "TRAITS")
        val natureNames = listOf("Hardy", "Lonely", "Brave", "Adamant", "Naughty", "Bold", "Docile", "Relaxed", "Impish", "Lax", "Timid", "Hasty", "Serious", "Jolly", "Naive", "Modest", "Mild", "Quiet", "Bashful", "Rash", "Calm", "Gentle", "Sassy", "Careful", "Quirky")
        val natureSpinner = spinnerField("Nature", natureNames, p.nature).also { root.addView(it.first) }.second

        val shinyToggle = CheckBox(this).apply {
            text = "Shiny"
            isChecked = p.shiny
            textSize = 16f
            setTextColor(TEXT)
            setPadding(dp(10), dp(10), dp(10), dp(10))
        }
        root.addView(shinyToggle)

        val genderNames = listOf("Male", "Female", "Genderless")
        val genderSpinner = spinnerField("Gender", genderNames, p.gender.coerceIn(0, 2)).also { root.addView(it.first) }.second

        val formField = inputField("Form ID (0–31)", p.form.toString(), true).also { root.addView(it.first) }.second
        addMutedLine(root, "Form IDs are species-specific. PSE validates the storage range, but unusual forms may still be illegal for that species/game.")

        val languageIds = if (gen7) intArrayOf(1, 2, 3, 4, 5, 7, 8, 9, 10) else intArrayOf(1, 2, 3, 4, 5, 7, 8)
        val languageNames = languageIds.map { pokemonLanguageName(it) }
        val currentLanguageIndex = languageIds.indexOf(p.language).takeIf { it >= 0 } ?: languageIds.indexOf(2).coerceAtLeast(0)
        val languageSpinner = spinnerField("Language", languageNames, currentLanguageIndex).also { root.addView(it.first) }.second

        addSectionTitle(root, "POKÉRUS")
        val pokerusStatusNames = listOf("None", "Active", "Cured")
        val initialPokerusStatus = when { p.pokerusStrain == 0 -> 0; p.pokerusDays > 0 -> 1; else -> 2 }
        val pokerusStatusSpinner = spinnerField("Pokérus status", pokerusStatusNames, initialPokerusStatus).also { root.addView(it.first) }.second
        val pokerusStrainField = inputField("Pokérus strain (1–15 when infected)", p.pokerusStrain.toString(), true).also { root.addView(it.first) }.second
        val pokerusDaysField = inputField("Pokérus days (1–15 active; 0 cured)", p.pokerusDays.toString(), true).also { root.addView(it.first) }.second

        addSectionTitle(root, "MARKINGS")
        val markingNames = arrayOf("Circle", "Triangle", "Square", "Heart", "Star", "Diamond")
        val markingChecks = ArrayList<CheckBox>()
        for (i in markingNames.indices) {
            val marked = if (gen7) ((p.markingValue ushr (i * 2)) and 3) != 0 else ((p.markingValue ushr i) and 1) != 0
            val check = CheckBox(this).apply {
                text = markingNames[i]
                isChecked = marked
                textSize = 15f
                setTextColor(TEXT)
                setPadding(dp(10), dp(4), dp(10), dp(4))
            }
            markingChecks.add(check)
            root.addView(check)
        }
        if (gen7) addMutedLine(root, "Gen 7 supports marking colours. PSE currently treats markings as on/off and writes enabled markings using the default colour.")

        addSectionTitle(root, "ABILITY / ITEM")
        var abilityId = p.ability
        val abilitySelector = selectorButton("Ability", "Ability #${p.ability}").also { root.addView(it.first) }.second
        resolvePokeApiNameAsync("ability", p.ability) { name -> if (name != null && abilityId == p.ability) abilitySelector.text = "$name (#${p.ability})" }
        abilitySelector.setOnClickListener {
            val progress = android.app.AlertDialog.Builder(this).setTitle("Choose Ability").setMessage("Loading valid abilities for this Pokémon…").setCancelable(false).create()
            progress.show()
            loadSpeciesAbilityChoicesAsync(p.species, abilityId, gen7) { choices ->
                progress.dismiss()
                if (choices.isNullOrEmpty()) {
                    openCatalogPicker("ability", "Choose Ability", gen7) { chosen -> abilityId = chosen.id; abilitySelector.text = chosen.toString() }
                } else {
                    showSearchableChoiceDialog("Choose Ability", choices) { chosen -> abilityId = chosen.id; abilitySelector.text = chosen.toString() }
                }
            }
        }

        val slotValues = listOf("Ability 1", "Ability 2", "Hidden Ability")
        val slotIds = intArrayOf(1, 2, 4)
        val slotIndex = slotIds.indexOf(p.abilityNumber).takeIf { it >= 0 } ?: 0
        val abilitySlotSpinner = spinnerField("Ability slot", slotValues, slotIndex).also { root.addView(it.first) }.second

        var itemId = p.heldItem
        val initialItem = if (p.heldItem == 0) "None" else "Item #${p.heldItem}"
        val itemSelector = selectorButton("Held item", initialItem).also { root.addView(it.first) }.second
        if (p.heldItem != 0) resolvePokeApiNameAsync("item", p.heldItem) { name -> if (name != null && itemId == p.heldItem) itemSelector.text = "$name (#${p.heldItem})" }
        itemSelector.setOnClickListener {
            openCatalogPicker("item", "Choose Held Item", gen7) { chosen -> itemId = chosen.id; itemSelector.text = chosen.toString() }
        }

        val friendship = inputField("Friendship (0–255)", p.friendship.toString(), true).also { root.addView(it.first) }.second

        addSectionTitle(root, "MOVES / PP")
        val moveIds = p.moves.copyOf()
        val moveSelectors = ArrayList<Button>()
        val ppFields = ArrayList<EditText>()
        for (i in 0..3) {
            val initialMove = if (p.moves[i] == 0) "None" else "Move #${p.moves[i]}"
            val selector = selectorButton("Move ${i + 1}", initialMove).also { root.addView(it.first) }.second
            moveSelectors.add(selector)
            if (p.moves[i] != 0) {
                val originalId = p.moves[i]
                resolvePokeApiNameAsync("move", originalId) { name -> if (name != null && moveIds[i] == originalId) selector.text = "$name (#$originalId)" }
            }
            val pp = inputField("Move ${i + 1} PP", p.movePP[i].toString(), true).also { root.addView(it.first) }.second
            ppFields.add(pp)
            selector.setOnClickListener {
                openCatalogPicker("move", "Choose Move ${i + 1}", gen7) { chosen ->
                    moveIds[i] = chosen.id
                    selector.text = chosen.toString()
                    resolveMovePpAsync(chosen.id) { basePp -> if (basePp != null) pp.setText(basePp.toString()) }
                }
            }
        }
        addMutedLine(root, "Choosing a move automatically loads its base PP. You can still adjust PP manually if needed.")

        addSectionTitle(root, "IVs")
        val ivFields = ArrayList<EditText>()
        val statLabels = arrayOf("HP", "Attack", "Defense", "Speed", "Sp. Atk", "Sp. Def")
        for (i in 0..5) ivFields.add(inputField("${statLabels[i]} IV (0–31)", p.ivs[i].toString(), true).also { root.addView(it.first) }.second)

        addSectionTitle(root, "EVs")
        val evFields = ArrayList<EditText>()
        for (i in 0..5) evFields.add(inputField("${statLabels[i]} EV (0–252)", p.evs[i].toString(), true).also { root.addView(it.first) }.second)
        addMutedLine(root, "Total EVs must be 510 or less.")

        addButton(root, "💾  Save Changes") {
            val values = try {
                val newNickname = nickname.text.toString().trim()
                val newExp = exp.text.toString().toLong()
                val newNature = natureSpinner.selectedItemPosition
                val newGender = genderSpinner.selectedItemPosition.coerceIn(0, 2)
                val newForm = formField.text.toString().toInt()
                val newLanguage = languageIds[languageSpinner.selectedItemPosition.coerceIn(0, languageIds.lastIndex)]
                val pokerusMode = pokerusStatusSpinner.selectedItemPosition
                val enteredStrain = pokerusStrainField.text.toString().toInt()
                val enteredDays = pokerusDaysField.text.toString().toInt()
                val newPokerusStrain = if (pokerusMode == 0) 0 else enteredStrain
                val newPokerusDays = when (pokerusMode) { 0 -> 0; 1 -> enteredDays; else -> 0 }
                var newMarkingValue = p.markingValue
                if (gen7) {
                    newMarkingValue = newMarkingValue and 0xF000
                    for (i in markingChecks.indices) if (markingChecks[i].isChecked) newMarkingValue = newMarkingValue or (1 shl (i * 2))
                } else {
                    newMarkingValue = newMarkingValue and 0xFFC0
                    for (i in markingChecks.indices) if (markingChecks[i].isChecked) newMarkingValue = newMarkingValue or (1 shl i)
                }
                val newAbilitySlot = slotIds[abilitySlotSpinner.selectedItemPosition.coerceIn(0, slotIds.lastIndex)]
                val newFriendship = friendship.text.toString().toInt()
                val newPP = IntArray(4) { ppFields[it].text.toString().toInt() }
                val newIVs = IntArray(6) { ivFields[it].text.toString().toInt() }
                val newEVs = IntArray(6) { evFields[it].text.toString().toInt() }
                PokemonEditValues(newNickname, newExp, newNature, shinyToggle.isChecked, newGender, newForm, newLanguage, newPokerusStrain, newPokerusDays, newMarkingValue, abilityId, newAbilitySlot, itemId, newFriendship, moveIds.copyOf(), newPP, newIVs, newEVs)
            } catch (_: Exception) {
                showDialog("Invalid values", "One or more fields are not valid numbers.")
                return@addButton
            }
            val error = validatePokemonEdit(values, gen7)
            if (error != null) {
                showDialog("Invalid values", error)
            } else {
                val requestedLevel = levelField.text.toString().toIntOrNull()
                if (requestedLevel == null || requestedLevel !in 1..100) {
                    showDialog("Invalid level", "Level must be between 1 and 100.")
                } else if (loadedLevel != null && requestedLevel != loadedLevel) {
                    resolveExperienceForLevelAsync(p.species, requestedLevel) { targetExp ->
                        if (targetExp == null) showDialog("Could not set level", "PSE could not resolve this species' growth curve. Check your internet connection and try again.")
                        else confirmPokemonEdit(location, global, p, values.copy(experience = targetExp))
                    }
                } else {
                    confirmPokemonEdit(location, global, p, values)
                }
            }
        }
        addMutedLine(root, if (gen7) "PSE edits only the working copy here. A safety backup of the emulator save is created later when you use Save & Replace Current Save. The PK7 checksum/encryption and Gen 7 BoxPokemon block checksum are rebuilt and verified." else "PSE edits only the working copy here. A safety backup of the emulator save is created later when you use Save & Replace Current Save. The PK6 checksum/encryption and Gen 6 box checksum are rebuilt and verified.")
        setContentView(scroll)
    }

    private data class PartyPokemonEditValues(
        val nickname: String,
        val ability: Int,
        val abilityNumber: Int,
        val heldItem: Int,
        val friendship: Int,
        val moves: IntArray,
        val pp: IntArray
    )

    private fun showPartyPokemonEditor(location: String, slot: Int, p: PokemonEntry) {
        phoneBackAction = { showPokemonDetails(location, p) }
        val gen7 = isCurrentGen7()
        val scroll = ScrollView(this).apply { setBackgroundColor(BG) }
        val root = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(dp(16), dp(58), dp(16), dp(28))
            setBackgroundColor(BG)
        }
        scroll.addView(root)
        root.addView(TextView(this).apply {
            text = "Edit ${p.nickname.ifBlank { "Species #${p.species}" }}"
            textSize = 27f
            typeface = Typeface.DEFAULT_BOLD
            setTextColor(TEXT)
        })
        addMutedLine(root, "$location • ${if (gen7) "PK7 / Gen 7" else "PK6 / Gen 6"} party-safe editor")
        addMutedLine(root, "Level, EXP, Nature, IVs and EVs are intentionally read-only here because party records cache battle stats. PSE leaves those cached values untouched.")
        addButton(root, "←  Cancel") { showPokemonDetails(location, p) }

        val nickname = inputField("Nickname (max 12 characters)", p.nickname).also { root.addView(it.first) }.second

        addSectionTitle(root, "TRAITS")
        var abilityId = p.ability
        val abilitySelector = selectorButton("Ability", "Ability #${p.ability}").also { root.addView(it.first) }.second
        resolvePokeApiNameAsync("ability", p.ability) { name -> if (name != null && abilityId == p.ability) abilitySelector.text = "$name (#${p.ability})" }
        abilitySelector.setOnClickListener {
            val progress = AlertDialog.Builder(this).setTitle("Choose Ability").setMessage("Loading valid abilities for this Pokémon…").setCancelable(false).create()
            progress.show()
            loadSpeciesAbilityChoicesAsync(p.species, abilityId, gen7) { choices ->
                progress.dismiss()
                if (choices.isNullOrEmpty()) openCatalogPicker("ability", "Choose Ability", gen7) { chosen -> abilityId = chosen.id; abilitySelector.text = chosen.toString() }
                else showSearchableChoiceDialog("Choose Ability", choices) { chosen -> abilityId = chosen.id; abilitySelector.text = chosen.toString() }
            }
        }

        val slotValues = listOf("Ability 1", "Ability 2", "Hidden Ability")
        val slotIds = intArrayOf(1, 2, 4)
        val abilitySlotSpinner = spinnerField("Ability slot", slotValues, slotIds.indexOf(p.abilityNumber).takeIf { it >= 0 } ?: 0).also { root.addView(it.first) }.second

        var itemId = p.heldItem
        val itemSelector = selectorButton("Held item", if (p.heldItem == 0) "None" else "Item #${p.heldItem}").also { root.addView(it.first) }.second
        if (p.heldItem != 0) resolvePokeApiNameAsync("item", p.heldItem) { name -> if (name != null && itemId == p.heldItem) itemSelector.text = "$name (#${p.heldItem})" }
        itemSelector.setOnClickListener { openCatalogPicker("item", "Choose Held Item", gen7) { chosen -> itemId = chosen.id; itemSelector.text = chosen.toString() } }

        val friendship = inputField("Friendship (0–255)", p.friendship.toString(), true).also { root.addView(it.first) }.second

        addSectionTitle(root, "MOVES / PP")
        val moveIds = p.moves.copyOf()
        val ppFields = ArrayList<EditText>()
        for (i in 0..3) {
            val selector = selectorButton("Move ${i + 1}", if (p.moves[i] == 0) "None" else "Move #${p.moves[i]}").also { root.addView(it.first) }.second
            if (p.moves[i] != 0) {
                val originalId = p.moves[i]
                resolvePokeApiNameAsync("move", originalId) { name -> if (name != null && moveIds[i] == originalId) selector.text = "$name (#$originalId)" }
            }
            val pp = inputField("Move ${i + 1} PP", p.movePP[i].toString(), true).also { root.addView(it.first) }.second
            ppFields.add(pp)
            selector.setOnClickListener {
                openCatalogPicker("move", "Choose Move ${i + 1}", gen7) { chosen ->
                    moveIds[i] = chosen.id
                    selector.text = chosen.toString()
                    resolveMovePpAsync(chosen.id) { basePp -> if (basePp != null) pp.setText(basePp.toString()) }
                }
            }
        }

        addButton(root, "💾  Save Party Changes") {
            val values = try {
                PartyPokemonEditValues(
                    nickname.text.toString().trim(),
                    abilityId,
                    slotIds[abilitySlotSpinner.selectedItemPosition.coerceIn(0, slotIds.lastIndex)],
                    itemId,
                    friendship.text.toString().toInt(),
                    moveIds.copyOf(),
                    IntArray(4) { ppFields[it].text.toString().toInt() }
                )
            } catch (_: Exception) {
                showDialog("Invalid values", "One or more fields are not valid numbers.")
                return@addButton
            }
            val maxAbility = if (gen7) 233 else 191
            val maxItem = if (gen7) 959 else 775
            val maxMove = if (gen7) 728 else 621
            val error = when {
                values.nickname.length > 12 -> "Nickname must be 12 characters or fewer."
                values.ability !in 0..maxAbility -> "Ability ID is outside the supported range."
                values.abilityNumber !in intArrayOf(1,2,4) -> "Ability slot must be 1, 2 or 4."
                values.heldItem !in 0..maxItem -> "Held item ID is outside the supported range."
                values.friendship !in 0..255 -> "Friendship must be between 0 and 255."
                values.moves.any { it !in 0..maxMove } -> "A move ID is outside the supported range."
                values.pp.any { it !in 0..64 } -> "Move PP must be between 0 and 64."
                else -> null
            }
            if (error != null) showDialog("Invalid values", error)
            else confirmPartyPokemonEdit(location, slot, p, values)
        }
        addMutedLine(root, "PSE rewrites the complete encrypted party record, rebuilds the Gen 6/7 PokePartySave checksum and verifies the edited values before keeping them.")
        setContentView(scroll)
    }

    private fun confirmPartyPokemonEdit(location: String, slot: Int, p: PokemonEntry, v: PartyPokemonEditValues) {
        AlertDialog.Builder(this)
            .setTitle("Save party Pokémon changes?")
            .setMessage("This changes only PSE's working copy. The emulator save is unchanged until Save & Replace Current Save.")
            .setNegativeButton("Cancel", null)
            .setPositiveButton("Save") { _, _ -> writePartyPokemonEdit(location, slot, p, v) }
            .show()
    }

    private fun writePartyPokemonEdit(location: String, slot: Int, old: PokemonEntry, v: PartyPokemonEditValues) {
        val file = importedFile ?: return
        val originalSave = try { file.readBytes() } catch (e: Exception) { showDialog("Edit failed", "Could not read save: ${e.message}"); return }
        val save = originalSave.copyOf()
        val info = partyStorageInfo(save) ?: return
        if (slot !in 0 until readPartyCount(save, info)) { showDialog("Edit stopped", "That party slot is no longer active."); return }
        val offset = info.offset + slot * PK6_PARTY_SIZE
        val current = parsePk6(save, offset, PK6_PARTY_SIZE, true, info.maxSpecies)
        if (current == null || current.species != old.species || current.pid != old.pid) { showDialog("Edit stopped", "The Pokémon in this party slot changed since the editor was opened."); return }
        try {
            val raw = save.copyOfRange(offset, offset + PK6_PARTY_SIZE)
            val pk = decryptPk6IfNeeded(raw)
            writeGen6String(pk, 0x40, 26, v.nickname)
            pk[0x14] = v.ability.toByte()
            pk[0x15] = v.abilityNumber.toByte()
            writeU16LE(pk, 0x0A, v.heldItem)
            if (old.currentHandler == 0) pk[0xCA] = v.friendship.toByte() else pk[0xA2] = v.friendship.toByte()
            for (i in 0..3) { writeU16LE(pk, 0x5A + i * 2, v.moves[i]); pk[0x62 + i] = v.pp[i].toByte() }
            var iv32 = readU32LE(pk, 0x74)
            val shouldBeNicknamed = if (v.nickname == old.nickname) old.isNicknamed else v.nickname.isNotBlank()
            iv32 = if (shouldBeNicknamed) iv32 or 0x80000000L else iv32 and 0x7FFFFFFFL
            writeU32LE(pk, 0x74, iv32)
            updatePk6Checksum(pk)
            encryptPk6(pk).copyInto(save, offset)
            updatePartyChecksum(save, info)
            file.writeBytes(save)

            val verifyBytes = file.readBytes()
            val verified = parsePk6(verifyBytes, offset, PK6_PARTY_SIZE, true, info.maxSpecies)
            val ok = verified != null && verified.checksumValid && verified.species == old.species && verified.pid == old.pid &&
                verified.nickname == v.nickname && verified.ability == v.ability && verified.abilityNumber == v.abilityNumber &&
                verified.heldItem == v.heldItem && verified.friendship == v.friendship && verified.moves.contentEquals(v.moves) && verified.movePP.contentEquals(v.pp)
            if (!ok) {
                file.writeBytes(originalSave)
                showDialog("Verification failed", "PSE restored the original working save because the party Pokémon did not verify after editing.")
                return
            }
            Toast.makeText(this, "Party Pokémon updated and verified", Toast.LENGTH_LONG).show()
            showPokemonDetails(location, verified!!)
        } catch (e: Exception) {
            runCatching { file.writeBytes(originalSave) }
            showDialog("Edit failed", (e.message ?: "Unknown error") + " The original working copy was restored.")
        }
    }

    private fun confirmDeletePartyPokemon(location: String, slot: Int, p: PokemonEntry) {
        val file = importedFile ?: return
        val data = runCatching { file.readBytes() }.getOrNull() ?: return
        val info = partyStorageInfo(data) ?: return
        if (readPartyCount(data, info) <= 1) {
            showDialog("Cannot remove Pokémon", "PSE will not leave the party empty. Keep at least one Pokémon in the party.")
            return
        }
        AlertDialog.Builder(this)
            .setTitle("Remove ${p.nickname.ifBlank { "Pokémon" }} from party?")
            .setMessage("The remaining party Pokémon will shift up automatically. This changes only PSE's working copy.")
            .setNegativeButton("Cancel", null)
            .setPositiveButton("Remove") { _, _ -> deletePartyPokemon(slot, p) }
            .show()
    }

    private fun deletePartyPokemon(slot: Int, expected: PokemonEntry) {
        val file = importedFile ?: return
        val original = try { file.readBytes() } catch (e: Exception) { showDialog("Remove failed", e.message ?: "Could not read save"); return }
        val work = original.copyOf()
        val info = partyStorageInfo(work) ?: return
        val count = readPartyCount(work, info)
        if (count <= 1 || slot !in 0 until count) { showDialog("Remove stopped", "Party layout changed or only one Pokémon remains."); return }
        val source = parsePk6(work, info.offset + slot * PK6_PARTY_SIZE, PK6_PARTY_SIZE, true, info.maxSpecies)
        if (source == null || source.species != expected.species || source.pid != expected.pid) { showDialog("Remove stopped", "The party Pokémon changed since this screen was opened."); return }
        try {
            for (i in slot until count - 1) {
                val src = info.offset + (i + 1) * PK6_PARTY_SIZE
                val dst = info.offset + i * PK6_PARTY_SIZE
                work.copyInto(work, dst, src, src + PK6_PARTY_SIZE)
            }
            java.util.Arrays.fill(work, info.offset + (count - 1) * PK6_PARTY_SIZE, info.offset + count * PK6_PARTY_SIZE, 0.toByte())
            writePartyCount(work, info, count - 1)
            updatePartyChecksum(work, info)
            file.writeBytes(work)
            val verify = file.readBytes()
            val verifyInfo = partyStorageInfo(verify) ?: error("Party block missing after write")
            if (readPartyCount(verify, verifyInfo) != count - 1) error("Party count verification failed")
            for (i in 0 until count - 1) if (parsePk6(verify, verifyInfo.offset + i * PK6_PARTY_SIZE, PK6_PARTY_SIZE, true, verifyInfo.maxSpecies) == null) error("Party compaction verification failed")
            Toast.makeText(this, "Pokémon removed from party and verified", Toast.LENGTH_LONG).show()
            showPokemonViewer("party", 0)
        } catch (e: Exception) {
            runCatching { file.writeBytes(original) }
            showDialog("Remove failed", (e.message ?: "Unknown error") + " The original working copy was restored.")
        }
    }

    private fun confirmMovePartyPokemonToPc(location: String, slot: Int, p: PokemonEntry) {
        val file = importedFile ?: return
        val data = runCatching { file.readBytes() }.getOrNull() ?: return
        val info = partyStorageInfo(data) ?: return
        if (readPartyCount(data, info) <= 1) { showDialog("Cannot move Pokémon", "PSE will not leave the party empty. Keep at least one Pokémon in the party."); return }
        val boxInfo = boxStorageInfo(data) ?: return
        val target = findFirstEmptyBoxSlot(data, boxInfo.first, boxInfo.second, boxInfo.third)
        if (target == null) { showDialog("Move to PC", "No empty PC slot was found."); return }
        AlertDialog.Builder(this)
            .setTitle("Move ${p.nickname.ifBlank { "Pokémon" }} to PC?")
            .setMessage("Destination: Box ${target / 30 + 1} • Slot ${target % 30 + 1}\n\nThe party will be compacted automatically and both save blocks will be verified.")
            .setNegativeButton("Cancel", null)
            .setPositiveButton("Move") { _, _ -> movePartyPokemonToPc(slot, p, target) }
            .show()
    }

    private fun movePartyPokemonToPc(slot: Int, expected: PokemonEntry, targetGlobal: Int) {
        val file = importedFile ?: return
        val original = try { file.readBytes() } catch (e: Exception) { showDialog("Move failed", e.message ?: "Could not read save"); return }
        val work = original.copyOf()
        val party = partyStorageInfo(work) ?: return
        val box = boxStorageInfo(work) ?: return
        val count = readPartyCount(work, party)
        if (count <= 1 || slot !in 0 until count) { showDialog("Move stopped", "Party layout changed or only one Pokémon remains."); return }
        val partyOffset = party.offset + slot * PK6_PARTY_SIZE
        val current = parsePk6(work, partyOffset, PK6_PARTY_SIZE, true, party.maxSpecies)
        if (current == null || current.species != expected.species || current.pid != expected.pid) { showDialog("Move stopped", "The party Pokémon changed since this screen was opened."); return }
        val boxOffset = box.first + targetGlobal * PK6_STORED_SIZE
        if (parsePk6(work, boxOffset, PK6_STORED_SIZE, false, box.third) != null) { showDialog("Move stopped", "The destination PC slot is no longer empty."); return }
        try {
            work.copyOfRange(partyOffset, partyOffset + PK6_STORED_SIZE).copyInto(work, boxOffset)
            for (i in slot until count - 1) {
                val src = party.offset + (i + 1) * PK6_PARTY_SIZE
                val dst = party.offset + i * PK6_PARTY_SIZE
                work.copyInto(work, dst, src, src + PK6_PARTY_SIZE)
            }
            java.util.Arrays.fill(work, party.offset + (count - 1) * PK6_PARTY_SIZE, party.offset + count * PK6_PARTY_SIZE, 0.toByte())
            writePartyCount(work, party, count - 1)
            updatePartyChecksum(work, party)
            if (generationForSize(work.size) == 7) updateGen7BoxChecksum(work) else updateGen6BoxChecksum(work)
            file.writeBytes(work)
            val verify = file.readBytes()
            val moved = parsePk6(verify, boxOffset, PK6_STORED_SIZE, false, box.third)
            val verifyParty = partyStorageInfo(verify) ?: error("Party block missing after write")
            if (moved == null || !moved.checksumValid || moved.species != expected.species || moved.pid != expected.pid || readPartyCount(verify, verifyParty) != count - 1) error("Post-write verification did not pass")
            Toast.makeText(this, "Pokémon moved to Box ${targetGlobal / 30 + 1} • Slot ${targetGlobal % 30 + 1} and verified", Toast.LENGTH_LONG).show()
            showPokemonViewer("boxes", targetGlobal / 30)
        } catch (e: Exception) {
            runCatching { file.writeBytes(original) }
            showDialog("Move failed", (e.message ?: "Unknown error") + " The original working copy was restored.")
        }
    }

    private data class LegalityFinding(val severity: Int, val text: String)

    private data class LegalisationPlan(
        val values: PokemonEditValues,
        val changes: List<String>,
        val remainingIssues: List<String>
    )

    private data class DeepLegalityData(
        val abilitySlots: Map<Int, Int> = emptyMap(),
        val genderRate: Int? = null,
        val learnableMoves: Set<Int> = emptySet(),
        val moveMethods: Map<Int, Set<String>> = emptyMap(),
        val moveNames: Map<Int, String> = emptyMap(),
        val moveBasePp: Map<Int, Int> = emptyMap(),
        val growthLevel: Int? = null,
        val reportedFormCount: Int? = null,
        val onlineOk: Boolean = false,
        val partial: Boolean = false
    )

    private fun originGameName(id: Int): String = when (id) {
        1 -> "Sapphire"; 2 -> "Ruby"; 3 -> "Emerald"; 4 -> "FireRed"; 5 -> "LeafGreen"
        7 -> "HeartGold"; 8 -> "SoulSilver"; 10 -> "Diamond"; 11 -> "Pearl"; 12 -> "Platinum"
        15 -> "Colosseum/XD"; 20 -> "White"; 21 -> "Black"; 22 -> "White 2"; 23 -> "Black 2"
        24 -> "X"; 25 -> "Y"; 26 -> "Alpha Sapphire"; 27 -> "Omega Ruby"
        30 -> "Sun"; 31 -> "Moon"; 32 -> "Ultra Sun"; 33 -> "Ultra Moon"
        35 -> "Red VC"; 36 -> "Blue/Green VC"; 37 -> "Blue VC"; 38 -> "Yellow VC"
        39 -> "Gold VC"; 40 -> "Silver VC"; 41 -> "Crystal VC"
        else -> "Game #$id"
    }

    private fun validOriginGameForFormat(id: Int, gen7: Boolean): Boolean {
        val classic = id in setOf(1,2,3,4,5,7,8,10,11,12,15,20,21,22,23,24,25,26,27)
        if (!gen7) return classic
        return classic || id in setOf(30,31,32,33,35,36,37,38,39,40,41)
    }

    private fun versionGroupGeneration(name: String): Int = when (name) {
        "red-blue", "yellow" -> 1
        "gold-silver", "crystal" -> 2
        "ruby-sapphire", "emerald", "firered-leafgreen" -> 3
        "diamond-pearl", "platinum", "heartgold-soulsilver" -> 4
        "black-white", "black-2-white-2" -> 5
        "x-y", "omega-ruby-alpha-sapphire" -> 6
        "sun-moon", "ultra-sun-ultra-moon" -> 7
        else -> 99
    }

    private fun validDateParts(year: Int, month: Int, day: Int): Boolean {
        if (year == 0 && month == 0 && day == 0) return true
        if (year !in 0..99 || month !in 1..12 || day !in 1..31) return false
        return try {
            java.time.LocalDate.of(2000 + year, month, day)
            true
        } catch (_: Exception) { false }
    }

    private fun checkGen3PokemonLegality(location: String, p: PokemonEntry) {
        val findings = mutableListOf<LegalityFinding>()
        fun error(text: String) = findings.add(LegalityFinding(2, text))
        fun warn(text: String) = findings.add(LegalityFinding(1, text))

        if (!p.checksumValid) error("PK3 checksum is invalid.")
        if (p.species !in 1..386) error("Species #${p.species} is not available in Generation 3.")
        if (p.nature !in 0..24) error("Nature ID ${p.nature} is invalid.")
        if (p.language !in setOf(1,2,3,4,5,7)) error("Language value ${p.language} is not valid for Generation 3.")
        if (p.abilityNumber !in setOf(1,2)) error("Gen 3 ability slot ${p.abilityNumber} is invalid.")
        if (p.heldItem !in 0..376) error("Held item #${p.heldItem} is outside the Generation 3 range.")
        p.moves.forEachIndexed { i, move -> if (move !in 0..354) error("Move ${i + 1} (#$move) is outside the Generation 3 range.") }
        val activeMoves = p.moves.filter { it != 0 }
        if (activeMoves.size != activeMoves.distinct().size) error("The same move appears more than once in the active moveset.")
        if (p.movePP.any { it !in 0..63 }) error("One or more current move PP values are outside the Gen 3 stored range 0–63.")
        p.moves.forEachIndexed { i, move -> if (move == 0 && p.movePP[i] != 0) error("Move ${i + 1} is empty but still has ${p.movePP[i]} PP stored.") }
        if (p.ivs.any { it !in 0..31 }) error("One or more IVs are outside 0–31.")
        if (p.evs.any { it !in 0..255 }) error("One or more EV bytes are outside 0–255.")
        if (p.evs.sum() > 510) error("EV total is ${p.evs.sum()}, above the Generation 3 maximum of 510.")
        if (p.friendship !in 0..255) error("Friendship is outside 0–255.")
        if (p.pokerusStrain !in 0..15 || p.pokerusDays !in 0..15) error("Pokérus data is outside the stored range.")
        if (p.pokerusStrain == 0 && p.pokerusDays != 0) error("Pokérus has remaining days but no strain.")
        if (p.nickname.length > 10) error("Nickname exceeds the Generation 3 limit of 10 characters.")
        if (p.otName.length > 7) error("Original Trainer name exceeds the Generation 3 limit of 7 characters.")
        if (p.otName.isBlank()) warn("Original Trainer name is blank.")

        val shinyValue = p.tid xor p.sid xor (p.pid.toInt() and 0xFFFF) xor ((p.pid.toInt() ushr 16) and 0xFFFF)
        if ((shinyValue < 8) != p.shiny) error("Shiny state does not match the Gen 3 PID/TID/SID rule.")
        if ((p.pid % 25L).toInt() != p.nature) error("Nature does not match PID modulo 25.")

        if (p.originGame !in setOf(1,2,3,4,5,15)) error("Origin game ${originGameName(p.originGame)} (${p.originGame}) cannot produce a native PK3 Pokémon.")
        if (p.metLevel !in 0..100) error("Met level ${p.metLevel} is outside the Generation 3 stored range.")
        if (p.ball !in 1..12) error("Poké Ball ID ${p.ball} is outside the Generation 3 range.")
        if (p.metLocation !in 0..255) error("Met location is outside the PK3 stored range.")

        val loading = AlertDialog.Builder(this)
            .setTitle("Gen 3 deep legality check…")
            .setMessage("Checking PK3 structure, PID rules, Generation 3 learnsets, PP limits, growth/level consistency and historical ability data.")
            .setCancelable(false)
            .create()
        loading.show()

        loadDeepLegalityDataForGenerationAsync(p, 3) { deep ->
            if (loading.isShowing) loading.dismiss()
            if (deep.onlineOk) {
                val normalAbilities = deep.abilitySlots.filterValues { it == 1 || it == 2 }
                val slots = normalAbilities.values.toSet()
                if (slots.size >= 2 && p.abilityNumber !in slots) {
                    error("Ability slot ${p.abilityNumber} is not available to this species in Generation 3 according to historical ability data.")
                }
                // PK3 stores only the ability bit, not the resolved ability ID. A species with
                // one normal ability legally resolves both bit values to the same ability.

                p.moves.forEachIndexed { index, move ->
                    if (move != 0 && deep.learnableMoves.isNotEmpty() && move !in deep.learnableMoves) {
                        val name = deep.moveNames[move] ?: "Move"
                        error("Move ${index + 1}: $name (#$move) is not obtainable by this species in the Generation 3 games according to the loaded learnset data.")
                    }
                }
                p.moves.forEachIndexed { i, move ->
                    if (move == 0) return@forEachIndexed
                    val base = deep.moveBasePp[move] ?: return@forEachIndexed
                    val maxPp = base + (base * 3 / 5)
                    if (p.movePP[i] > maxPp) error("Move ${i + 1} (#$move) has ${p.movePP[i]} PP, above its maximum of $maxPp.")
                }
                deep.growthLevel?.let { level ->
                    if (level !in 1..100) error("Experience does not map to a valid level for this species' growth rate.")
                    if (p.metLevel > level && !p.isEgg) error("Met level ${p.metLevel} is higher than level $level implied by the stored experience.")
                    if (p.level != null && p.level != level) error("Party level ${p.level} does not match level $level implied by experience.")
                }
            } else {
                warn("Online species/move legality data could not be loaded. Offline PK3 structural, PID, stat, origin and checksum checks still ran.")
            }
            if (deep.partial) warn("Some online legality lookups were incomplete; unavailable checks were not treated as failures.")

            val errors = findings.filter { it.severity == 2 }
            val warnings = findings.filter { it.severity == 1 }
            val status = when {
                errors.isNotEmpty() -> "❌ INVALID / ILLEGAL"
                warnings.isNotEmpty() -> "⚠️ PASSED WITH WARNINGS"
                else -> "✅ PASSED DEEP CHECKS"
            }
            val body = buildString {
                append(status).append("\n\n")
                append(p.nickname.ifBlank { canonicalGen3SpeciesName(p.species) ?: "Species #${p.species}" }).append(" • ").append(location)
                append("\nPK3 • ").append(canonicalGen3SpeciesName(p.species) ?: "Species #${p.species}").append(" (#").append(p.species).append(")")
                append("\nAbility: ").append(canonicalGen3AbilityLabel(p.species,p.abilityNumber) ?: "Unknown Gen 3 ability (slot ${p.abilityNumber})")
                append("\nOrigin: ").append(originGameName(p.originGame)).append(" • Met Lv. ").append(p.metLevel).append(" • Ball #").append(p.ball)
                if (errors.isNotEmpty()) {
                    append("\n\nProblems\n")
                    errors.forEach { append("• ").append(it.text).append('\n') }
                }
                if (warnings.isNotEmpty()) {
                    append("\nWarnings\n")
                    warnings.forEach { append("• ").append(it.text).append('\n') }
                }
                if (errors.isEmpty() && warnings.isEmpty()) append("\n\nNo problems were found by PSE's Gen 3 structural and species checks.\n")
                append("\nChecked in this build")
                append("\n• PK3 checksum and Generation 3 field ranges")
                append("\n• species / origin-game compatibility")
                append("\n• PID → nature and shiny rules")
                append("\n• historical Gen 3 ability-slot sanity")
                append("\n• IV / EV limits and EV total")
                append("\n• Gen 3 move learnability and duplicate moves")
                append("\n• move PP upper limits")
                append("\n• EXP growth curve / level consistency")
                append("\n• language, Pokérus and nickname/OT structure")
                append("\n• basic Poké Ball / met-data sanity")
                append("\n\nNot fully certifiable without exact Gen 3 encounter/event databases")
                append("\n• exact encounter slot/location and met-level match")
                append("\n• Mystery Gift / event distribution identity")
                append("\n• exact encounter-method PID/IV correlation")
                append("\n• GameCube purification / ribbon provenance")
            }
            val reportBuilder = AlertDialog.Builder(this)
                .setTitle("Gen 3 Deep Legality Report")
                .setMessage(body.trim())
                .setPositiveButton("OK", null)
            val boxedGlobal = boxedLocationToGlobalIndex(location)
            if (errors.isNotEmpty() && boxedGlobal != null && p.checksumValid) {
                val plan = buildGen3LegalisationPlan(p, deep, errors)
                if (plan.changes.isNotEmpty()) {
                    reportBuilder.setNeutralButton("Fix illegal Pokémon") { _, _ ->
                        showGen3LegalisationReview(location, boxedGlobal, p, plan)
                    }
                }
            }
            reportBuilder.show()
        }
    }

    private data class Gen3LegalisationPlan(
        val values: Gen3EditValues,
        val changes: List<String>,
        val remainingIssues: List<String>
    )

    private fun buildGen3LegalisationPlan(
        p: PokemonEntry,
        deep: DeepLegalityData,
        currentErrors: List<LegalityFinding>
    ): Gen3LegalisationPlan {
        val changes = mutableListOf<String>()
        val fixedPrefixes = mutableSetOf<String>()
        val moves = p.moves.copyOf()
        val pp = p.movePP.copyOf()
        val seen = mutableSetOf<Int>()

        for (i in moves.indices) {
            val move = moves[i]
            var remove = false
            if (move !in 0..354) {
                remove = true
                fixedPrefixes += "Move ${i + 1} (#"
            }
            if (move != 0 && deep.learnableMoves.isNotEmpty() && move !in deep.learnableMoves) {
                remove = true
                fixedPrefixes += "Move ${i + 1}:"
            }
            if (move != 0 && !seen.add(move)) {
                remove = true
                fixedPrefixes += "The same move appears more than once"
            }
            if (remove) {
                val moveName = deep.moveNames[move] ?: "Move #$move"
                moves[i] = 0
                pp[i] = 0
                changes += "Move ${i + 1} ($moveName) removed because PSE could not validate it for Generation 3."
            } else if (move == 0) {
                if (pp[i] != 0) {
                    pp[i] = 0
                    changes += "Move ${i + 1} PP cleared because the slot is empty."
                    fixedPrefixes += "Move ${i + 1} is empty"
                }
            } else {
                val base = deep.moveBasePp[move]
                val maxPp = if (base != null) base + (base * 3 / 5) else 63
                if (pp[i] > maxPp) {
                    pp[i] = maxPp.coerceAtMost(63)
                    changes += "Move ${i + 1} PP reduced to ${pp[i]}."
                    fixedPrefixes += "Move ${i + 1} (#"
                }
            }
        }

        val evs = p.evs.map { it.coerceIn(0,255) }.toIntArray()
        if (evs.sum() > 510) {
            var excess = evs.sum() - 510
            for (i in evs.indices.reversed()) {
                if (excess <= 0) break
                val cut = minOf(evs[i], excess)
                evs[i] -= cut
                excess -= cut
            }
            changes += "EV total reduced to 510."
            fixedPrefixes += "EV total is"
        }

        val ivs = p.ivs.map { it.coerceIn(0,31) }.toIntArray()
        if (!ivs.contentEquals(p.ivs)) {
            changes += "IVs clamped to 0–31."
            fixedPrefixes += "One or more IVs"
        }

        if (currentErrors.any { it.text.startsWith("Nature does not match PID") } ||
            currentErrors.any { it.text.startsWith("Shiny state does not match") }) {
            changes += "PID regenerated to match the stored nature and shiny state."
            fixedPrefixes += "Nature does not match PID"
            fixedPrefixes += "Shiny state does not match"
        }

        val friendship = p.friendship.coerceIn(0,255)
        if (friendship != p.friendship) {
            changes += "Friendship clamped to 0–255."
            fixedPrefixes += "Friendship is outside"
        }

        val abilitySlot = if (p.abilityNumber in 1..2) p.abilityNumber else 1
        if (abilitySlot != p.abilityNumber) {
            changes += "Ability slot reset to Ability 1."
            fixedPrefixes += "Ability slot"
        }

        val nickname = p.nickname.take(10)
        if (nickname != p.nickname) {
            changes += "Nickname shortened to 10 characters."
            fixedPrefixes += "Nickname exceeds"
        }
        val ot = p.otName.take(7)
        if (ot != p.otName) {
            changes += "OT name shortened to 7 characters."
            fixedPrefixes += "Original Trainer name exceeds"
        }

        val values = Gen3EditValues(
            nickname = nickname,
            ot = ot,
            tid = p.tid.coerceIn(0,65535),
            sid = p.sid.coerceIn(0,65535),
            exp = p.experience.coerceIn(0,0xFFFFFF),
            held = p.heldItem.coerceIn(0,65535),
            friendship = friendship,
            nature = p.nature.coerceIn(0,24),
            shiny = p.shiny,
            moves = moves,
            pp = pp,
            ivs = ivs,
            evs = evs,
            abilitySlot = abilitySlot
        )
        val remaining = currentErrors.map { it.text }.filter { text ->
            fixedPrefixes.none { prefix -> text.startsWith(prefix) }
        }
        return Gen3LegalisationPlan(values, changes.distinct(), remaining.distinct())
    }

    private fun showGen3LegalisationReview(location:String, global:Int, p:PokemonEntry, plan:Gen3LegalisationPlan) {
        val message = buildString {
            append("PSE can safely fix these detected Gen 3 issues:\n\n")
            plan.changes.forEach { append("• ").append(it).append("\n") }
            if (plan.remainingIssues.isNotEmpty()) {
                append("\nNot changed automatically\n")
                plan.remainingIssues.forEach { append("• ").append(it).append("\n") }
                append("\nPSE will not guess at encounter/event-specific or unsupported fields.")
            }
            append("\n\nPSE will rebuild the encrypted PK3, refresh every affected Gen 3 PC-section checksum, verify the full save, then run Deep Legality again. The original working copy is restored if verification fails.")
        }
        AlertDialog.Builder(this)
            .setTitle("Fix illegal Pokémon")
            .setMessage(message)
            .setNegativeButton("Cancel", null)
            .setPositiveButton("Apply safe fixes") { _, _ ->
                applyGen3PokemonLegalisation(location, global, p, plan.values)
            }.show()
    }

    private fun applyGen3PokemonLegalisation(location:String, global:Int, old:PokemonEntry, v:Gen3EditValues) {
        val file = importedFile ?: return
        val original = try { file.readBytes() } catch (e:Exception) {
            showDialog("Fix failed", e.message ?: "Could not read save")
            return
        }
        try {
            val save = original.copyOf()
            if (!gen3SaveValid(save)) throw IllegalStateException("Gen 3 save did not pass pre-fix validation")
            val pc = gen3PcBuffer(save) ?: throw IllegalStateException("Could not reconstruct Gen 3 PC storage")
            val off = 4 + global * 80
            val current = parsePk3(pc, off, false) ?: throw IllegalStateException("Pokémon is no longer in that box slot")
            if (current.pid != old.pid || current.species != old.species) throw IllegalStateException("The box slot changed since the legality report was opened")
            if (!current.checksumValid) throw IllegalStateException("Source PK3 checksum is invalid")

            val raw = pc.copyOfRange(off, off + 80)
            mutatePk3(raw, false, v).copyInto(pc, off)
            val staged = parsePk3(pc, off, false) ?: throw IllegalStateException("Fixed PK3 could not be parsed")
            if (!staged.checksumValid || staged.species != old.species) throw IllegalStateException("Fixed PK3 failed verification")

            writeGen3PcBuffer(save, pc)
            if (!gen3SaveValid(save)) throw IllegalStateException("Gen 3 section checksum verification failed")
            file.writeBytes(save)

            val verify = file.readBytes()
            if (!gen3SaveValid(verify)) throw IllegalStateException("Written save failed verification")
            val verifyPc = gen3PcBuffer(verify) ?: throw IllegalStateException("Could not re-read Gen 3 PC storage")
            val fixed = parsePk3(verifyPc, off, false) ?: throw IllegalStateException("Fixed PK3 could not be re-read")
            if (!fixed.checksumValid || fixed.species != old.species) throw IllegalStateException("Fixed Pokémon failed verification")

            Toast.makeText(this, "Gen 3 safe fixes applied and verified", Toast.LENGTH_LONG).show()
            checkGen3PokemonLegality(location, fixed)
        } catch (e:Exception) {
            runCatching { file.writeBytes(original) }
            showDialog("Fix failed", "${e.message ?: "Unknown error"}. The original working copy was restored.")
        }
    }

    private fun checkGen4PokemonLegality(location: String, p: PokemonEntry) {
        val findings = mutableListOf<LegalityFinding>()
        fun error(text: String) = findings.add(LegalityFinding(2, text))
        fun warn(text: String) = findings.add(LegalityFinding(1, text))

        if (!p.checksumValid) error("PK4 checksum is invalid.")
        if (p.species !in 1..493) error("Species #${p.species} is not available in Generation 4.")
        if (p.nature !in 0..24) error("Nature ID ${p.nature} is invalid.")
        if (p.gender !in 0..2) error("Gender value ${p.gender} is invalid.")
        if (p.form !in 0..31) error("Form value ${p.form} is outside the PK4 supported range.")
        if (p.language !in setOf(1,2,3,4,5,7,8)) error("Language value ${p.language} is not valid for Generation 4.")
        if (p.ability !in 1..123) error("Ability #${p.ability} is outside the Generation 4 range.")
        if (p.abilityNumber !in setOf(1,2)) error("Gen 4 ability slot ${p.abilityNumber} is invalid (expected 1 or 2 from PID parity).")
        if (p.heldItem !in 0..536) error("Held item #${p.heldItem} is outside the Generation 4 range.")
        p.moves.forEachIndexed { i, move -> if (move !in 0..467) error("Move ${i + 1} (#$move) is outside the Generation 4 range.") }
        val usedMoves = p.moves.filter { it != 0 }
        if (usedMoves.size != usedMoves.distinct().size) error("The same move appears more than once in the active moveset.")
        if (p.movePP.any { it !in 0..64 }) error("One or more current move PP values are outside the stored range.")
        p.moves.forEachIndexed { i, move -> if (move == 0 && p.movePP[i] != 0) error("Move ${i + 1} is empty but still has ${p.movePP[i]} PP stored.") }
        if (p.ivs.any { it !in 0..31 }) error("One or more IVs are outside 0–31.")
        if (p.evs.any { it !in 0..255 }) error("One or more stored EV bytes are outside 0–255.")
        if (p.evs.any { it > 252 }) error("One or more EVs are above the legal per-stat maximum of 252.")
        if (p.evs.sum() > 510) error("EV total is ${p.evs.sum()}, above the legal maximum of 510.")
        if (p.friendship !in 0..255) error("Friendship is outside 0–255.")
        if (p.pokerusStrain !in 0..15 || p.pokerusDays !in 0..15) error("Pokérus data is outside the valid stored range.")
        if (p.pokerusStrain == 0 && p.pokerusDays != 0) error("Pokérus has remaining days but no strain.")
        if (p.nickname.length > 10) error("Nickname exceeds the Generation 4 limit of 10 characters.")
        if (p.otName.length > 7) error("Original Trainer name exceeds the Generation 4 limit of 7 characters.")
        if (p.isNicknamed && p.nickname.isBlank()) warn("Pokémon is flagged as nicknamed but its nickname is blank.")
        if (p.otName.isBlank()) warn("Original Trainer name is blank.")
        if (p.otGender !in 0..1) error("Original Trainer gender value is invalid.")

        val shinyValue = p.tid xor p.sid xor (p.pid.toInt() and 0xFFFF) xor ((p.pid.toInt() ushr 16) and 0xFFFF)
        if ((shinyValue < 8) != p.shiny) error("Shiny state does not match the Gen 4 PID/TID/SID rule.")
        if ((p.pid % 25L).toInt() != p.nature) error("Nature does not match PID modulo 25.")
        val pidAbilitySlot = if ((p.pid and 1L) == 0L) 1 else 2
        if (p.abilityNumber != pidAbilitySlot) error("Ability slot does not match the Gen 4 PID ability bit.")

        val validOriginGames = setOf(1,2,3,4,5,7,8,10,11,12,15)
        if (p.originGame !in validOriginGames) error("Origin game ${originGameName(p.originGame)} (${p.originGame}) cannot produce a PK4 Pokémon.")
        if (p.metLevel !in 0..100) error("Met level ${p.metLevel} is outside the Generation 4 stored range.")
        if (!p.isEgg && p.metLevel == 0 && p.originGame in setOf(7,8,10,11,12)) warn("Met level is 0 for a native Gen 4 Pokémon; PSE could not confirm the encounter.")
        if (p.ball !in 1..24) error("Poké Ball ID ${p.ball} is outside the Generation 4 ball range.")
        if (p.ball == 16 && !p.fatefulEncounter) warn("Cherish Ball usually belongs to an event Pokémon, but Fateful Encounter is not set.")
        if (p.metLocation == 0) warn("Met location is zero; this may be valid for transfers/events, but exact encounter legality is not confirmed.")
        if (!validDateParts(p.metYear, p.metMonth, p.metDay)) error("Met date contains an invalid calendar date.")
        if (!validDateParts(p.eggYear, p.eggMonth, p.eggDay)) error("Egg received date contains an invalid calendar date.")
        if (p.eggLocation != 0 && p.eggMonth == 0) warn("Egg location is set but the egg received date is blank.")
        if (p.eggLocation == 0 && (p.eggYear != 0 || p.eggMonth != 0 || p.eggDay != 0)) warn("Egg received date is present but Egg Location is zero.")
        if (p.eggLocation != 0 && p.metYear != 0 && p.eggYear != 0 && validDateParts(p.metYear,p.metMonth,p.metDay) && validDateParts(p.eggYear,p.eggMonth,p.eggDay)) {
            val metDate = java.time.LocalDate.of(2000+p.metYear,p.metMonth,p.metDay)
            val eggDate = java.time.LocalDate.of(2000+p.eggYear,p.eggMonth,p.eggDay)
            if (metDate.isBefore(eggDate)) error("Met/hatched date is earlier than the egg received date.")
        }

        val loading = android.app.AlertDialog.Builder(this)
            .setTitle("Gen 4 deep legality check…")
            .setMessage("PSE is checking PK4 structure, PID rules, Gen 4 move learnability, PP limits, growth/level consistency and species metadata.")
            .setCancelable(false)
            .create()
        loading.show()

        loadDeepLegalityDataForGenerationAsync(p, 4) { deep ->
            loading.dismiss()
            if (deep.onlineOk) {
                val gen4Abilities = deep.abilitySlots.filterValues { it == 1 || it == 2 }
                val reportedSlot = gen4Abilities[p.ability]
                if (gen4Abilities.isNotEmpty() && reportedSlot == null) {
                    error("Ability #${p.ability} is not available to this species in Generation 4 according to the historical ability data.")
                } else if (reportedSlot != null && gen4Abilities.size > 1 && reportedSlot != p.abilityNumber) {
                    error("Ability #${p.ability} belongs to Gen 4 slot $reportedSlot, but this PK4's PID selects slot ${p.abilityNumber}.")
                }
                // With only one normal ability in Gen 4, both PID parities are legal and resolve to
                // that sole ability. Do not flag an odd PID merely because the API labels it slot 1.

                when (deep.genderRate) {
                    -1 -> if (p.gender != 2) error("This species is genderless, but the PK4 is marked ${pokemonGenderName(p.gender)}.")
                    0 -> if (p.gender != 0) error("This species is male-only.")
                    8 -> if (p.gender != 1) error("This species is female-only.")
                }

                p.moves.forEachIndexed { index, move ->
                    if (move != 0 && deep.learnableMoves.isNotEmpty() && move !in deep.learnableMoves) {
                        val name = deep.moveNames[move] ?: "Move"
                        error("Move ${index + 1}: $name (#$move) is not obtainable by this species in Generation 4 or an earlier compatible game according to the loaded learnset data.")
                    }
                }
                p.moves.forEachIndexed { i, move ->
                    if (move == 0) return@forEachIndexed
                    val base = deep.moveBasePp[move] ?: return@forEachIndexed
                    val maxPp = base + (base * 3 / 5)
                    if (p.movePP[i] > maxPp) error("Move ${i + 1} (#$move) has ${p.movePP[i]} PP, above its maximum of $maxPp.")
                }

                deep.growthLevel?.let { level ->
                    if (level !in 1..100) error("Experience does not map to a valid level for this species' growth rate.")
                    if (p.metLevel > level && !p.isEgg) error("Met level ${p.metLevel} is higher than level $level implied by the stored experience.")
                    if (p.level != null && p.level != level) error("Party level ${p.level} does not match level $level implied by experience.")
                }
                deep.reportedFormCount?.let { count ->
                    if (p.form > 0 && count <= 1) warn("Form ${p.form} is set, but public species data did not expose an alternate form. Species-specific Gen 4 form mapping is needed to certify it.")
                }
            } else {
                warn("Online species/move legality data could not be loaded. Offline PK4 structural, PID, origin, stat and date checks still ran.")
            }
            if (deep.partial) warn("Some online legality lookups were incomplete; unavailable checks were not treated as failures.")

            val unresolved = listOf(
                "exact encounter slot/location and met-level match",
                "Mystery Gift/event distribution identity and redemption window",
                "exact encounter-specific ability restrictions where historical API data is incomplete",
                "exact Poké Ball legality for each encounter/event",
                "ribbon/contest provenance",
                "Gen 3 → Gen 4 Pal Park migration history and encounter-method PID correlation"
            )
            val errors = findings.filter { it.severity == 2 }
            val warnings = findings.filter { it.severity == 1 }
            val status = when {
                errors.isNotEmpty() -> "❌ INVALID / ILLEGAL"
                warnings.isNotEmpty() -> "⚠️ PASSED WITH WARNINGS"
                else -> "✅ PASSED DEEP CHECKS"
            }
            val body = buildString {
                append(status).append("\n\n")
                append(p.nickname.ifBlank { "Species #${p.species}" }).append(" • ").append(location)
                append("\nPK4 • Species #").append(p.species)
                append("\nOrigin: ").append(originGameName(p.originGame))
                append(" • Met Lv. ").append(p.metLevel).append(" • Ball #").append(p.ball).append("\n\n")
                if (errors.isNotEmpty()) {
                    append("Problems\n")
                    errors.forEach { append("• ").append(it.text).append("\n") }
                    append("\n")
                }
                if (warnings.isNotEmpty()) {
                    append("Warnings\n")
                    warnings.forEach { append("• ").append(it.text).append("\n") }
                    append("\n")
                }
                if (errors.isEmpty() && warnings.isEmpty()) append("No problems were found by PSE's Gen 4 structural and species checks.\n\n")
                append("Checked in this build\n")
                append("• PK4 checksum and Gen 4 field ranges\n")
                append("• species / origin-game compatibility\n")
                append("• PID → nature, shiny and Gen 4 historical ability-slot rules\n")
                append("• IV / EV limits and EV total\n")
                append("• species gender restrictions\n")
                append("• Gen 4 + earlier move learnability\n")
                append("• move PP upper limits\n")
                append("• EXP growth curve / level consistency\n")
                append("• met level, dates and egg-date ordering\n")
                append("• language, Pokérus and nickname/OT structure\n")
                append("• basic Poké Ball and form sanity\n\n")
                append("Not fully certifiable without exact Gen 4 encounter/event databases\n")
                unresolved.forEach { append("• ").append(it).append("\n") }
                append("\nPSE does not modify the Pokémon during a legality check.")
            }
            val reportBuilder = android.app.AlertDialog.Builder(this)
                .setTitle("Gen 4 Deep Legality Report")
                .setMessage(body)
                .setPositiveButton("OK", null)

            val boxedGlobal = boxedLocationToGlobalIndex(location)
            if (errors.isNotEmpty() && boxedGlobal != null && p.checksumValid) {
                val plan = buildGen4LegalisationPlan(p, deep, errors)
                if (plan.changes.isNotEmpty()) {
                    reportBuilder.setNeutralButton("Fix illegal Pokémon") { _, _ ->
                        showGen4LegalisationReview(location, boxedGlobal, p, plan)
                    }
                }
            }
            reportBuilder.show()
        }
    }

    private data class Gen4LegalisationPlan(
        val values: Gen4EditValues,
        val changes: List<String>,
        val remainingIssues: List<String>
    )

    private fun buildGen4LegalisationPlan(
        p: PokemonEntry,
        deep: DeepLegalityData,
        currentErrors: List<LegalityFinding>
    ): Gen4LegalisationPlan {
        val changes = mutableListOf<String>()
        val fixed = mutableSetOf<String>()

        val moves = p.moves.copyOf()
        val pp = p.movePP.copyOf()
        val seen = mutableSetOf<Int>()
        for (i in moves.indices) {
            val move = moves[i]
            var remove = false
            if (move !in 0..467) { remove = true; fixed += "Move ${i + 1} (#" }
            if (move != 0 && deep.learnableMoves.isNotEmpty() && move !in deep.learnableMoves) { remove = true; fixed += "Move ${i + 1}:" }
            if (move != 0 && !seen.add(move)) { remove = true; fixed += "The same move appears more than once" }
            if (remove) {
                val moveName = deep.moveNames[move] ?: "Move #$move"
                moves[i] = 0; pp[i] = 0
                changes += "Move ${i + 1} ($moveName) removed because PSE could not validate it for Generation 4."
            } else if (move == 0) {
                if (pp[i] != 0) { pp[i] = 0; changes += "Move ${i + 1} PP cleared because the slot is empty."; fixed += "Move ${i + 1} is empty" }
            } else {
                val base = deep.moveBasePp[move]
                val maxPp = if (base != null) base + (base * 3 / 5) else 63
                if (pp[i] > maxPp) { pp[i] = maxPp.coerceAtMost(63); changes += "Move ${i + 1} PP reduced to ${pp[i]}."; fixed += "Move ${i + 1} (#"; fixed += "One or more current move PP values" }
            }
        }

        val evs = p.evs.map { it.coerceIn(0, 252) }.toIntArray()
        if (!evs.contentEquals(p.evs)) { changes += "Individual EVs clamped to the legal maximum of 252."; fixed += "One or more EVs" }
        if (evs.sum() > 510) {
            var excess = evs.sum() - 510
            for (i in evs.indices.reversed()) {
                if (excess <= 0) break
                val cut = minOf(evs[i], excess); evs[i] -= cut; excess -= cut
            }
            changes += "EV total reduced to 510."; fixed += "EV total is"
        }

        // Rebuilding the PK4 through mutatePk4 regenerates a PID that matches the
        // stored nature and shiny state while preserving the original ability parity.
        val pidNatureBad = currentErrors.any { it.text.startsWith("Nature does not match PID") }
        val pidShinyBad = currentErrors.any { it.text.startsWith("Shiny state does not match") }
        if (pidNatureBad || pidShinyBad) {
            changes += "PID regenerated to match the stored nature and shiny state."
            fixed += "Nature does not match PID"; fixed += "Shiny state does not match"
        }

        val held = p.heldItem.coerceIn(0, 536)
        if (held != p.heldItem) { changes += "Invalid held item removed."; fixed += "Held item #" }
        val friendship = p.friendship.coerceIn(0, 255)
        if (friendship != p.friendship) { changes += "Friendship clamped to 0–255."; fixed += "Friendship is outside" }

        val values = Gen4EditValues(
            nickname = p.nickname.take(10), ot = p.otName.take(7), tid = p.tid, sid = p.sid,
            exp = p.experience, held = held, friendship = friendship, nature = p.nature.coerceIn(0,24),
            shiny = p.shiny, moves = moves, pp = pp, ivs = p.ivs.map { it.coerceIn(0,31) }.toIntArray(), evs = evs
        )
        if (!values.ivs.contentEquals(p.ivs)) { changes += "IVs clamped to 0–31."; fixed += "One or more IVs" }
        if (p.nickname.length > 10) { changes += "Nickname shortened to 10 characters."; fixed += "Nickname exceeds" }
        if (p.otName.length > 7) { changes += "OT name shortened to 7 characters."; fixed += "Original Trainer name exceeds" }

        val remaining = currentErrors.map { it.text }.filter { text -> fixed.none { text.startsWith(it) } }
        return Gen4LegalisationPlan(values, changes.distinct(), remaining.distinct())
    }

    private fun showGen4LegalisationReview(location:String, global:Int, p:PokemonEntry, plan:Gen4LegalisationPlan) {
        val message = buildString {
            append("PSE can safely fix these detected Gen 4 issues:\n\n")
            plan.changes.forEach { append("• ").append(it).append("\n") }
            if (plan.remainingIssues.isNotEmpty()) {
                append("\nNot changed automatically\n")
                plan.remainingIssues.forEach { append("• ").append(it).append("\n") }
                append("\nPSE will not guess at encounter/event-specific or unsupported fields.")
            }
            append("\n\nPSE will rebuild the encrypted PK4, refresh the active Gen 4 storage CRC, verify the save, then run Deep Legality again. The original working copy is restored if verification fails.")
        }
        android.app.AlertDialog.Builder(this)
            .setTitle("Fix illegal Pokémon")
            .setMessage(message)
            .setNegativeButton("Cancel", null)
            .setPositiveButton("Apply safe fixes") { _, _ ->
                applyGen4PokemonEditForLegalisation(location, global, p, plan.values)
            }.show()
    }

    private fun applyGen4PokemonEditForLegalisation(location:String, global:Int, old:PokemonEntry, v:Gen4EditValues) {
        val file=importedFile?:return
        val original=try{file.readBytes()}catch(e:Exception){showDialog("Fix failed",e.message?:"Could not read save");return}
        try {
            val save=original.copyOf()
            val profile=detectGen4Profile(save) ?: throw IllegalStateException("Could not detect Gen 4 save layout")
            val before=gen4Validation(save,profile)
            if(!before.generalChecksum || !before.storageChecksum || before.badPk4!=0) throw IllegalStateException("Gen 4 save did not pass pre-fix validation")
            val off=gen4BoxSlotOffset(save,profile,global)
            val current=parsePk4(save.copyOfRange(off,off+136),false) ?: throw IllegalStateException("Pokémon is no longer in that box slot")
            if(current.pid!=old.pid || current.species!=old.species) throw IllegalStateException("The box slot changed since the legality report was opened")
            val changed=mutatePk4(save.copyOfRange(off,off+136),v); changed.copyInto(save,off)
            val activeStorage=gen4ActiveBlock(save,profile.storageStart,profile.storageSize)
            updateGen4BlockChecksum(save,activeStorage*0x40000+profile.storageStart,profile.storageSize,profile)
            val after=gen4Validation(save,profile)
            if(!after.generalChecksum || !after.storageChecksum || after.badPk4!=0) throw IllegalStateException("Gen 4 checksum verification failed")
            file.writeBytes(save)
            val verify=file.readBytes(); val vp=detectGen4Profile(verify) ?: throw IllegalStateException("Written save could not be re-read")
            val voff=gen4BoxSlotOffset(verify,vp,global)
            val fixed=parsePk4(verify.copyOfRange(voff,voff+136),false) ?: throw IllegalStateException("Fixed PK4 could not be re-read")
            val vv=gen4Validation(verify,vp)
            if(!fixed.checksumValid || fixed.species!=old.species || !vv.generalChecksum || !vv.storageChecksum || vv.badPk4!=0) throw IllegalStateException("Fixed Pokémon failed verification")
            Toast.makeText(this,"Gen 4 safe fixes applied and verified",Toast.LENGTH_LONG).show()
            checkGen4PokemonLegality(location,fixed)
        } catch(e:Exception) {
            runCatching{file.writeBytes(original)}
            showDialog("Fix failed","${e.message?:"Unknown error"}. The original working copy was restored.")
        }
    }

    private fun checkPokemonLegality(location: String, p: PokemonEntry) {
        val gen7 = isCurrentGen7()
        val generation = if (gen7) 7 else 6
        val findings = mutableListOf<LegalityFinding>()
        fun error(text: String) = findings.add(LegalityFinding(2, text))
        fun warn(text: String) = findings.add(LegalityFinding(1, text))

        if (!p.checksumValid) error("PK$generation checksum is invalid.")
        val maxSpecies = if (gen7) 807 else 721
        if (p.species !in 1..maxSpecies) error("Species #${p.species} is not available in Generation $generation.")
        if (p.nature !in 0..24) error("Nature ID ${p.nature} is invalid.")
        if (p.gender !in 0..2) error("Gender value ${p.gender} is invalid.")
        if (p.form !in 0..31) error("Form value ${p.form} is outside the PK6/PK7 supported range.")
        val validLanguages = if (gen7) setOf(1,2,3,4,5,7,8,9,10) else setOf(1,2,3,4,5,7,8)
        if (p.language !in validLanguages) error("Language value ${p.language} is not valid for Generation $generation.")
        if (p.abilityNumber !in setOf(1,2,4)) error("Ability slot ${p.abilityNumber} is invalid (expected 1, 2 or 4).")
        val maxAbility = if (gen7) 233 else 191
        if (p.ability !in 1..maxAbility) error("Ability #${p.ability} is outside the Generation $generation range.")
        val maxItem = if (gen7) 959 else 775
        if (p.heldItem !in 0..maxItem) error("Held item #${p.heldItem} is outside the Generation $generation range.")
        val maxMove = if (gen7) 728 else 621
        p.moves.forEachIndexed { i, move -> if (move !in 0..maxMove) error("Move ${i + 1} (#$move) is outside the Generation $generation range.") }
        p.relearnMoves.forEachIndexed { i, move -> if (move !in 0..maxMove) error("Relearn move ${i + 1} (#$move) is outside the Generation $generation range.") }
        val nonZeroMoves = p.moves.filter { it != 0 }
        if (nonZeroMoves.size != nonZeroMoves.distinct().size) error("The same move appears more than once in the active moveset.")
        val nonZeroRelearn = p.relearnMoves.filter { it != 0 }
        if (nonZeroRelearn.size != nonZeroRelearn.distinct().size) warn("The same move appears more than once in the relearn move list.")
        if (p.movePP.any { it !in 0..64 }) error("One or more current move PP values are outside the supported range.")
        p.moves.forEachIndexed { i, move -> if (move == 0 && p.movePP[i] != 0) error("Move ${i + 1} is empty but still has ${p.movePP[i]} PP stored.") }
        if (p.ivs.any { it !in 0..31 }) error("One or more IVs are outside 0–31.")
        if (p.evs.any { it !in 0..252 }) error("One or more EVs are above 252.")
        if (p.evs.sum() > 510) error("EV total is ${p.evs.sum()}, above the legal maximum of 510.")
        if (p.friendship !in 0..255) error("Friendship is outside 0–255.")
        if (p.pokerusStrain !in 0..15 || p.pokerusDays !in 0..15) error("Pokérus data is outside the valid stored range.")
        if (p.pokerusStrain == 0 && p.pokerusDays != 0) error("Pokérus has remaining days but no strain.")
        if (p.isNicknamed && p.nickname.isBlank()) warn("Pokémon is flagged as nicknamed but its nickname is blank.")
        if (p.nickname.length > 12) error("Nickname exceeds 12 characters.")
        if (p.otName.isBlank()) warn("Original Trainer name is blank.")
        if (p.otGender !in 0..1) error("Original Trainer gender value is invalid.")

        val shinyValue = p.tid xor p.sid xor (p.pid.toInt() and 0xFFFF) xor ((p.pid.toInt() ushr 16) and 0xFFFF)
        if ((shinyValue < 16) != p.shiny) error("Shiny state does not match PID/TID/SID.")

        val pseGen1DirectRehome = !gen7 && p.originGame == 35 && p.metLocation == 30013
        val pseGen2DirectRehome = !gen7 && p.originGame in 39..41 && p.metLocation == 30017
        if (!validOriginGameForFormat(p.originGame, gen7) && !pseGen1DirectRehome && !pseGen2DirectRehome) {
            error("Origin game ${originGameName(p.originGame)} (${p.originGame}) cannot produce a PK$generation Pokémon.")
        }
        if (!gen7 && p.originGame in 30..41 && !pseGen1DirectRehome && !pseGen2DirectRehome) error("A Generation 6 Pokémon cannot originate from a Generation 7/VC title.")
        if (p.metLevel !in 1..100) error("Met level ${p.metLevel} is outside 1–100.")
        if (p.ball !in 1..(if (gen7) 26 else 25)) error("Poké Ball ID ${p.ball} is outside the Generation $generation ball range.")
        if (p.ball == 26 && p.originGame !in 30..33) error("Beast Ball is only valid for a Generation 7 origin game.")
        if (p.ball == 16 && !p.fatefulEncounter) warn("Cherish Ball usually belongs to event Pokémon, but Fateful Encounter is not set.")
        if (p.metLocation == 0) warn("Met location is zero; this can be valid for special transfers, but PSE could not confirm the encounter.")
        if (!validDateParts(p.metYear, p.metMonth, p.metDay)) error("Met date contains an invalid calendar date.")
        if (!validDateParts(p.eggYear, p.eggMonth, p.eggDay)) error("Egg received date contains an invalid calendar date.")
        if (p.eggLocation != 0 && p.eggMonth == 0) warn("Egg location is set but the egg received date is blank.")
        if (p.eggLocation == 0 && (p.eggYear != 0 || p.eggMonth != 0 || p.eggDay != 0)) warn("Egg received date is present but Egg Location is zero.")
        if (p.eggLocation != 0 && p.metYear != 0 && p.eggYear != 0 && validDateParts(p.metYear,p.metMonth,p.metDay) && validDateParts(p.eggYear,p.eggMonth,p.eggDay)) {
            val metDate = java.time.LocalDate.of(2000+p.metYear,p.metMonth,p.metDay)
            val eggDate = java.time.LocalDate.of(2000+p.eggYear,p.eggMonth,p.eggDay)
            if (metDate.isBefore(eggDate)) error("Met/hatched date is earlier than the egg received date.")
        }
        if (gen7 && p.hyperTrainFlags != 0 && p.experience == 0L) warn("Hyper Training flags are set but experience data is zero.")
        if (!gen7 && p.hyperTrainFlags != 0) warn("Generation 6 record has non-zero data in the Gen 7 Hyper Training byte.")
        if (p.country == 0 && (p.region != 0 || p.consoleRegion != 0)) warn("Region metadata is partially populated while Country is zero.")

        val loading = android.app.AlertDialog.Builder(this)
            .setTitle("Deep legality check…")
            .setMessage("PSE is checking species, ability slots, move learnability, PP limits, growth/level consistency and form metadata. This can take a few seconds.")
            .setCancelable(false)
            .create()
        loading.show()

        loadDeepLegalityDataAsync(p, gen7) { deep ->
            loading.dismiss()
            if (deep.onlineOk) {
                val expectedSlot = deep.abilitySlots[p.ability]
                if (deep.abilitySlots.isNotEmpty() && expectedSlot == null) {
                    error("Ability #${p.ability} is not available to this species.")
                } else if (expectedSlot != null && expectedSlot != p.abilityNumber) {
                    error("Ability #${p.ability} belongs to slot $expectedSlot for this species, but the Pokémon stores slot ${p.abilityNumber}.")
                }

                when (deep.genderRate) {
                    -1 -> if (p.gender != 2) error("This species is genderless, but the Pokémon is marked ${pokemonGenderName(p.gender)}.")
                    0 -> if (p.gender != 0) error("This species is male-only.")
                    8 -> if (p.gender != 1) error("This species is female-only.")
                }

                p.moves.forEachIndexed { index, move ->
                    if (move != 0 && deep.learnableMoves.isNotEmpty() && move !in deep.learnableMoves) {
                        val name = deep.moveNames[move] ?: "Move"
                        error("Move ${index + 1}: $name (#$move) cannot be learned by ${p.nickname.ifBlank { "this species" }} in Generation $generation or any earlier compatible game.")
                    }
                }
                p.relearnMoves.forEachIndexed { index, move ->
                    if (move != 0 && deep.learnableMoves.isNotEmpty() && move !in deep.learnableMoves) {
                        val name = deep.moveNames[move] ?: "Move"
                        error("Relearn move ${index + 1}: $name (#$move) is not obtainable by ${p.nickname.ifBlank { "this species" }} up to Generation $generation.")
                    }
                }

                p.moves.forEachIndexed { i, move ->
                    if (move == 0) return@forEachIndexed
                    val base = deep.moveBasePp[move] ?: return@forEachIndexed
                    val maxPp = base + (base * 3 / 5)
                    if (p.movePP[i] > maxPp) error("Move ${i + 1} (#$move) has ${p.movePP[i]} PP, above its maximum of $maxPp.")
                }

                deep.growthLevel?.let { level ->
                    if (level !in 1..100) error("Experience does not map to a valid level for this species' growth rate.")
                    if (p.metLevel > level && !p.isEgg) error("Met level ${p.metLevel} is higher than the level $level implied by the stored experience.")
                    if (gen7 && p.hyperTrainFlags != 0 && level < 100) error("Hyper Training flags are set, but this Pokémon is only level $level. Gen 7 Hyper Training requires level 100.")
                    if (p.level != null && p.level != level) error("Party level ${p.level} does not match level $level implied by experience.")
                }

                deep.reportedFormCount?.let { count ->
                    if (p.form > 0 && count <= 1) warn("Form ${p.form} is set, but the public species data did not expose alternate forms. Species-specific encounter data is needed to confirm it.")
                    if (count > 1 && p.form >= count && p.species !in setOf(201, 412, 413, 421, 422, 423, 479, 487, 492, 493, 550, 555, 585, 586, 641, 642, 645, 646, 647, 648, 649, 666, 669, 670, 671, 676, 681, 710, 711, 718, 720, 741, 745, 746, 773, 774, 778, 800, 801)) {
                        warn("Form ${p.form} is higher than the ${count} forms reported by the public species API; PSE could not fully map this species' internal form IDs.")
                    }
                }
            } else {
                warn("Online species/move legality data could not be loaded. All offline structural/origin checks still ran.")
            }
            if (deep.partial) warn("Some online legality lookups were incomplete; unavailable checks were not treated as failures.")

            // Encounter/event legality needs exact encounter tables rather than a permissive web API.
            // Do not falsely certify these fields; surface them as explicit unverified coverage.
            val unresolved = mutableListOf<String>()
            unresolved += "exact encounter slot/location + met-level match"
            unresolved += "Mystery Gift/event distribution identity and redemption window"
            unresolved += "exact Poké Ball legality for each encounter/event"
            unresolved += "ribbon/contest-memory provenance"
            unresolved += "full transfer-chain history (Gen 3→4→5→Bank/Transporter)"
            unresolved += "PID/EC generation-method correlation for encounter-specific RNG methods"
            unresolved += "country/sub-region/3DS-region geographic pairing"

            val errors = findings.filter { it.severity == 2 }
            val warnings = findings.filter { it.severity == 1 }
            val status = when {
                errors.isNotEmpty() -> "❌ ILLEGAL"
                warnings.isNotEmpty() -> "⚠️ PASSED WITH WARNINGS"
                else -> "✅ PASSED DEEP CHECKS"
            }
            val body = buildString {
                append(status).append("\n\n")
                append(p.nickname.ifBlank { "Species #${p.species}" })
                    .append(" • ").append(location)
                    .append("\nPK").append(generation)
                    .append(" • Species #").append(p.species)
                    .append("\nOrigin: ").append(if(generation==6 && p.originGame==35 && p.metLocation==30013) "Generation 1 • PSE Gen 1 → Gen 6" else if(generation==6 && p.originGame in 39..41 && p.metLocation==30017) "${pseGen2SourceName(p.originGame)} • PSE Gen 2 → Gen 6" else originGameName(p.originGame))
                    .append(" • Met Lv. ").append(p.metLevel)
                    .append(" • Ball #").append(p.ball).append("\n\n")
                if (errors.isNotEmpty()) {
                    append("Problems\n")
                    errors.forEach { append("• ").append(it.text).append("\n") }
                    append("\n")
                }
                if (warnings.isNotEmpty()) {
                    append("Warnings\n")
                    warnings.forEach { append("• ").append(it.text).append("\n") }
                    append("\n")
                }
                if (errors.isEmpty() && warnings.isEmpty()) append("No problems were found by PSE's deep structural and species checks.\n\n")
                append("Checked in this build\n")
                append("• PK checksum and field ranges\n")
                append("• species/generation/origin-game compatibility\n")
                append("• shiny PID/TID/SID relationship\n")
                append("• IV/EV limits and EV total\n")
                append("• ability + exact ability slot\n")
                append("• gender restrictions\n")
                append("• current and relearn move availability\n")
                append("• move PP upper limits\n")
                append("• EXP growth curve / level consistency\n")
                append("• met level, dates and egg-date ordering\n")
                append("• language, Pokérus and nickname structure\n")
                append("• basic ball/origin rules\n")
                append("• Gen 7 Hyper Training level requirement\n")
                append("• basic form metadata sanity\n\n")
                append("Still database-dependent / not fully certifiable\n")
                unresolved.forEach { append("• ").append(it).append("\n") }
                append("\nPSE intentionally will not call those areas legal without exact encounter/event databases. This check never modifies the Pokémon.")
            }
            val reportBuilder = android.app.AlertDialog.Builder(this)
                .setTitle("Deep Legality Report")
                .setMessage(body)
                .setPositiveButton("OK", null)

            val boxedGlobal = boxedLocationToGlobalIndex(location)
            if (errors.isNotEmpty() && boxedGlobal != null) {
                val plan = buildLegalisationPlan(p, deep, gen7, errors)
                if (plan.changes.isNotEmpty()) {
                    reportBuilder.setNeutralButton("Fix detected issues") { _, _ ->
                        showLegalisationReview(location, boxedGlobal, p, deep, plan)
                    }
                }
            }
            reportBuilder.show()
        }
    }

    private fun buildLegalisationPlan(
        p: PokemonEntry,
        deep: DeepLegalityData,
        gen7: Boolean,
        currentErrors: List<LegalityFinding>
    ): LegalisationPlan {
        val generation = if (gen7) 7 else 6
        val changes = mutableListOf<String>()
        val fixablePrefixes = mutableSetOf<String>()

        var nickname = p.nickname
        if (nickname.length > 12) {
            nickname = nickname.take(12)
            changes += "Nickname shortened to 12 characters."
            fixablePrefixes += "Nickname exceeds"
        }

        var nature = p.nature
        if (nature !in 0..24) {
            nature = 0
            changes += "Nature reset to Hardy because the stored nature ID was invalid."
            fixablePrefixes += "Nature ID"
        }

        var gender = p.gender
        if (gender !in 0..2) {
            gender = 0
            changes += "Invalid gender value reset to Male."
            fixablePrefixes += "Gender value"
        }
        when (deep.genderRate) {
            -1 -> if (gender != 2) {
                gender = 2
                changes += "Gender changed to Genderless to match the species."
                fixablePrefixes += "This species is genderless"
            }
            0 -> if (gender != 0) {
                gender = 0
                changes += "Gender changed to Male because this species is male-only."
                fixablePrefixes += "This species is male-only"
            }
            8 -> if (gender != 1) {
                gender = 1
                changes += "Gender changed to Female because this species is female-only."
                fixablePrefixes += "This species is female-only"
            }
        }

        var form = p.form
        if (form !in 0..31) {
            form = 0
            changes += "Form reset to the base form because the stored form value was invalid."
            fixablePrefixes += "Form value"
        } else if (deep.reportedFormCount != null && deep.reportedFormCount <= 1 && form != 0) {
            form = 0
            changes += "Form reset to the base form because this species has no alternate form in the loaded legality data."
        }

        val validLanguages = if (gen7) setOf(1,2,3,4,5,7,8,9,10) else setOf(1,2,3,4,5,7,8)
        var language = p.language
        if (language !in validLanguages) {
            language = 2
            changes += "Invalid language changed to English."
            fixablePrefixes += "Language value"
        }

        var pokerusStrain = p.pokerusStrain.coerceIn(0, 15)
        var pokerusDays = p.pokerusDays.coerceIn(0, 15)
        if (pokerusStrain != p.pokerusStrain || pokerusDays != p.pokerusDays) {
            changes += "Pokérus values clamped to their valid storage range."
            fixablePrefixes += "Pokérus data"
        }
        if (pokerusStrain == 0 && pokerusDays != 0) {
            pokerusDays = 0
            changes += "Pokérus days cleared because no Pokérus strain is stored."
            fixablePrefixes += "Pokérus has remaining days"
        }

        var ability = p.ability
        var abilityNumber = p.abilityNumber
        if (deep.abilitySlots.isNotEmpty()) {
            val expectedSlot = deep.abilitySlots[ability]
            if (expectedSlot == null) {
                val replacement = deep.abilitySlots.entries.sortedWith(compareBy<Map.Entry<Int, Int>> { when (it.value) { 1 -> 0; 2 -> 1; 4 -> 2; else -> 3 } }.thenBy { it.key }).firstOrNull()
                if (replacement != null) {
                    ability = replacement.key
                    abilityNumber = replacement.value
                    changes += "Ability changed to a valid species ability (#$ability, slot $abilityNumber)."
                    fixablePrefixes += "Ability #"
                }
            } else if (abilityNumber != expectedSlot) {
                abilityNumber = expectedSlot
                changes += "Ability slot corrected to slot $expectedSlot for ability #$ability."
                fixablePrefixes += "Ability #"
            }
        } else if (abilityNumber !in setOf(1,2,4)) {
            abilityNumber = 1
            changes += "Invalid ability slot reset to Ability 1."
            fixablePrefixes += "Ability slot"
        }

        val maxItem = if (gen7) 959 else 775
        var heldItem = p.heldItem
        if (heldItem !in 0..maxItem) {
            heldItem = 0
            changes += "Invalid held item removed."
            fixablePrefixes += "Held item #"
        }

        val maxMove = if (gen7) 728 else 621
        val moves = p.moves.copyOf()
        val pp = p.movePP.copyOf()
        val seen = mutableSetOf<Int>()
        for (i in moves.indices) {
            val move = moves[i]
            var remove = false
            if (move !in 0..maxMove) {
                remove = true
                fixablePrefixes += "Move ${i + 1} (#"
            }
            if (move != 0 && deep.learnableMoves.isNotEmpty() && move !in deep.learnableMoves) {
                remove = true
                fixablePrefixes += "Move ${i + 1}:"
            }
            if (move != 0 && !seen.add(move)) {
                remove = true
                fixablePrefixes += "The same move appears more than once"
            }
            if (remove) {
                val moveName = deep.moveNames[move] ?: "Move #$move"
                moves[i] = 0
                pp[i] = 0
                changes += "Move ${i + 1} ($moveName) removed because PSE could not validate it for this Pokémon."
                continue
            }
            if (move == 0) {
                if (pp[i] != 0) {
                    pp[i] = 0
                    changes += "Move ${i + 1} PP cleared because the move slot is empty."
                    fixablePrefixes += "Move ${i + 1} is empty"
                }
            } else {
                val base = deep.moveBasePp[move]
                val maxPp = if (base != null) base + (base * 3 / 5) else 64
                val fixedPp = pp[i].coerceIn(0, maxPp)
                if (fixedPp != pp[i]) {
                    pp[i] = fixedPp
                    changes += "Move ${i + 1} PP reduced to its legal maximum of $maxPp."
                    fixablePrefixes += "Move ${i + 1} (#"
                    fixablePrefixes += "One or more current move PP values"
                }
            }
        }

        val ivs = p.ivs.map { it.coerceIn(0, 31) }.toIntArray()
        if (!ivs.contentEquals(p.ivs)) {
            changes += "IVs clamped to 0–31."
            fixablePrefixes += "One or more IVs"
        }

        val evs = p.evs.map { it.coerceIn(0, 252) }.toIntArray()
        if (!evs.contentEquals(p.evs)) {
            changes += "Individual EVs clamped to 252."
            fixablePrefixes += "One or more EVs"
        }
        var total = evs.sum()
        if (total > 510) {
            var excess = total - 510
            for (i in evs.indices.reversed()) {
                if (excess <= 0) break
                val reduce = minOf(evs[i], excess)
                evs[i] -= reduce
                excess -= reduce
            }
            changes += "EV total reduced to 510 by trimming excess EVs from the later stats."
            fixablePrefixes += "EV total is"
            total = evs.sum()
        }

        val friendship = p.friendship.coerceIn(0, 255)
        if (friendship != p.friendship) {
            changes += "Friendship clamped to 0–255."
            fixablePrefixes += "Friendship is outside"
        }

        val values = PokemonEditValues(
            nickname = nickname,
            experience = p.experience,
            nature = nature,
            shiny = p.shiny,
            gender = gender,
            form = form,
            language = language,
            pokerusStrain = pokerusStrain,
            pokerusDays = pokerusDays,
            markingValue = p.markingValue,
            ability = ability,
            abilityNumber = abilityNumber,
            heldItem = heldItem,
            friendship = friendship,
            moves = moves,
            pp = pp,
            ivs = ivs,
            evs = evs
        )

        val remaining = currentErrors.map { it.text }.filter { text ->
            fixablePrefixes.none { prefix -> text.startsWith(prefix) }
        }
        return LegalisationPlan(values, changes.distinct(), remaining.distinct())
    }

    private fun showLegalisationReview(
        location: String,
        global: Int,
        p: PokemonEntry,
        deep: DeepLegalityData,
        plan: LegalisationPlan
    ) {
        val message = buildString {
            append("PSE can safely fix the following detected issues in its working copy:\n\n")
            plan.changes.forEach { append("• ").append(it).append("\n") }
            if (plan.remainingIssues.isNotEmpty()) {
                append("\nNot changed automatically\n")
                plan.remainingIssues.forEach { append("• ").append(it).append("\n") }
                append("\nThose issues need encounter/event-specific data or a manual decision, so PSE will not guess.")
            }
            append("\n\nAfter applying the fixes, PSE will rebuild PK${if (isCurrentGen7()) 7 else 6}, refresh the save-block checksum, verify the slot, and automatically run the legality check again.")
        }
        android.app.AlertDialog.Builder(this)
            .setTitle("Legalise Pokémon")
            .setMessage(message)
            .setNegativeButton("Cancel", null)
            .setPositiveButton("Apply safe fixes") { _, _ ->
                writePokemonEdit(location, global, p, plan.values) { verified ->
                    checkPokemonLegality(location, verified)
                }
            }
            .show()
    }

    private fun loadDeepLegalityDataAsync(p: PokemonEntry, gen7: Boolean, done: (DeepLegalityData) -> Unit) {
        loadDeepLegalityDataForGenerationAsync(p, if (gen7) 7 else 6, done)
    }

    private fun loadDeepLegalityDataForGenerationAsync(p: PokemonEntry, generation: Int, done: (DeepLegalityData) -> Unit) {
        val gen7 = generation >= 7
        val maxAbilityForGeneration = when {
            generation <= 4 -> 123
            generation == 5 -> 164
            generation == 6 -> 191
            else -> 233
        }
        imageExecutor.execute {
            var partial = false
            var ok = false
            val abilitySlots = linkedMapOf<Int, Int>()
            var genderRate: Int? = null
            val learnableMoves = mutableSetOf<Int>()
            val moveMethods = linkedMapOf<Int, MutableSet<String>>()
            val moveNames = linkedMapOf<Int, String>()
            val moveBasePp = linkedMapOf<Int, Int>()
            var growthLevel: Int? = null
            var reportedFormCount: Int? = null
            try {
                fun addCompatibleMoves(pokemonJson: JSONObject) {
                    val moves = pokemonJson.optJSONArray("moves") ?: return
                    for (i in 0 until moves.length()) {
                        val row = moves.optJSONObject(i) ?: continue
                        val m = row.optJSONObject("move") ?: continue
                        val moveId = m.optString("url").trimEnd('/').substringAfterLast('/').toIntOrNull() ?: continue
                        val details = row.optJSONArray("version_group_details") ?: continue
                        var legal = false
                        val methods = mutableSetOf<String>()
                        for (j in 0 until details.length()) {
                            val d = details.optJSONObject(j) ?: continue
                            val vg = d.optJSONObject("version_group")?.optString("name").orEmpty()
                            val vgGeneration = versionGroupGeneration(vg)
                            val compatible = if (generation == 3) vgGeneration == 3 else vgGeneration <= generation
                            if (compatible) {
                                legal = true
                                d.optJSONObject("move_learn_method")?.optString("name")?.takeIf { it.isNotBlank() }?.let { methods.add(it) }
                            }
                        }
                        if (legal) {
                            learnableMoves.add(moveId)
                            moveMethods.getOrPut(moveId) { mutableSetOf() }.addAll(methods)
                        }
                    }
                }

                val pokemon = fetchJson("https://pokeapi.co/api/v2/pokemon/${p.species}")
                if (pokemon != null) {
                    ok = true
                    fun readAbilitySlots(rows: org.json.JSONArray?, includeHidden: Boolean): LinkedHashMap<Int, Int> {
                        val out = linkedMapOf<Int, Int>()
                        if (rows == null) return out
                        for (i in 0 until rows.length()) {
                            val row = rows.optJSONObject(i) ?: continue
                            val hidden = row.optBoolean("is_hidden", false)
                            if (hidden && !includeHidden) continue
                            val a = row.optJSONObject("ability") ?: continue
                            val id = a.optString("url").trimEnd('/').substringAfterLast('/').toIntOrNull() ?: continue
                            val slot = row.optInt("slot", 0)
                            val storedSlot = when (slot) { 1 -> 1; 2 -> 2; 3 -> 4; else -> 0 }
                            if (storedSlot != 0 && id <= maxAbilityForGeneration) out[id] = storedSlot
                        }
                        return out
                    }

                    abilitySlots.putAll(readAbilitySlots(pokemon.optJSONArray("abilities"), generation >= 5))

                    // PokéAPI exposes historical ability sets in `past_abilities`. Each row applies
                    // up to and including its listed generation. Select the nearest historical row
                    // whose range still contains the requested generation, then use those slots
                    // instead of today's ability list. This matters for Gen 4 Pokémon whose species
                    // gained/changed abilities later.
                    val pastAbilities = pokemon.optJSONArray("past_abilities")
                    if (pastAbilities != null && generation < 9) {
                        var chosenGeneration = Int.MAX_VALUE
                        var chosenRows: org.json.JSONArray? = null
                        for (i in 0 until pastAbilities.length()) {
                            val row = pastAbilities.optJSONObject(i) ?: continue
                            val genName = row.optJSONObject("generation")?.optString("name").orEmpty()
                            val roman = genName.substringAfter("generation-", "")
                            val pastGen = when (roman) {
                                "i" -> 1; "ii" -> 2; "iii" -> 3; "iv" -> 4; "v" -> 5
                                "vi" -> 6; "vii" -> 7; "viii" -> 8; "ix" -> 9
                                else -> Int.MAX_VALUE
                            }
                            if (pastGen >= generation && pastGen < chosenGeneration) {
                                chosenGeneration = pastGen
                                chosenRows = row.optJSONArray("abilities")
                            }
                        }
                        if (chosenRows != null) {
                            abilitySlots.clear()
                            abilitySlots.putAll(readAbilitySlots(chosenRows, generation >= 5))
                        }
                    }
                    reportedFormCount = pokemon.optJSONArray("forms")?.length()
                    addCompatibleMoves(pokemon)
                } else partial = true

                val species = fetchJson("https://pokeapi.co/api/v2/pokemon-species/${p.species}")
                if (species != null) {
                    ok = true
                    genderRate = species.optInt("gender_rate", -99).takeIf { it != -99 }
                    val growthUrl = species.optJSONObject("growth_rate")?.optString("url").orEmpty()
                    if (growthUrl.isNotBlank()) {
                        val growth = fetchJson(growthUrl)
                        val levels = growth?.optJSONArray("levels")
                        if (levels != null) {
                            var best = 1
                            for (i in 0 until levels.length()) {
                                val row = levels.optJSONObject(i) ?: continue
                                val exp = row.optLong("experience", Long.MAX_VALUE)
                                val level = row.optInt("level", 0)
                                if (level in 1..100 && exp <= p.experience) best = maxOf(best, level)
                            }
                            growthLevel = best
                        } else partial = true
                    } else partial = true
                    val varieties = species.optJSONArray("varieties")
                    if (varieties != null && varieties.length() > (reportedFormCount ?: 0)) reportedFormCount = varieties.length()

                    // A Pokémon can legally retain moves learned before it evolved. Include the
                    // complete pre-evolution path so, for example, an Eevee that knows Bite does
                    // not become falsely illegal immediately after PSE evolves it into Leafeon.
                    val chainUrl = species.optJSONObject("evolution_chain")?.optString("url").orEmpty()
                    if (chainUrl.isNotBlank()) {
                        val chain = fetchJson(chainUrl)
                        val root = chain?.optJSONObject("chain")
                        if (root != null) {
                            val path = mutableListOf<Int>()
                            fun findEvolutionPath(node: JSONObject): Boolean {
                                val id = node.optJSONObject("species")?.optString("url")
                                    ?.trimEnd('/')?.substringAfterLast('/')?.toIntOrNull() ?: return false
                                path.add(id)
                                if (id == p.species) return true
                                val children = node.optJSONArray("evolves_to")
                                if (children != null) {
                                    for (i in 0 until children.length()) {
                                        val child = children.optJSONObject(i) ?: continue
                                        if (findEvolutionPath(child)) return true
                                    }
                                }
                                path.removeAt(path.lastIndex)
                                return false
                            }
                            if (findEvolutionPath(root)) {
                                for (ancestor in path.dropLast(1).distinct()) {
                                    fetchJson("https://pokeapi.co/api/v2/pokemon/$ancestor")?.let { addCompatibleMoves(it) }
                                }
                            }
                        } else partial = true
                    }
                } else partial = true

                val relevantMoves = (p.moves.asList() + p.relearnMoves.asList()).filter { it != 0 }.distinct()
                for (moveId in relevantMoves) {
                    val move = fetchJson("https://pokeapi.co/api/v2/move/$moveId")
                    val pp = if (generation == 2) gen2MoveBasePp(moveId) else move?.optInt("pp", -1)?.takeIf { it >= 0 }
                    val rawName = move?.optString("name").orEmpty()
                    if (rawName.isNotBlank()) moveNames[moveId] = rawName.split('-').joinToString(" ") { part -> part.replaceFirstChar { c -> c.uppercase() } }
                    if (pp != null) moveBasePp[moveId] = pp else partial = true
                }
            } catch (_: Exception) {
                partial = true
            }
            val result = DeepLegalityData(
                abilitySlots = abilitySlots,
                genderRate = genderRate,
                learnableMoves = learnableMoves,
                moveMethods = moveMethods.mapValues { it.value.toSet() },
                moveNames = moveNames,
                moveBasePp = moveBasePp,
                growthLevel = growthLevel,
                reportedFormCount = reportedFormCount,
                onlineOk = ok,
                partial = partial
            )
            mainHandler.post { if (!isFinishing && !isDestroyed) done(result) }
        }
    }

    private data class Gen7EvolutionOption(
        val targetSpecies:Int, val targetName:String, val trigger:String, val requirement:String,
        val met:Boolean, val consumeHeldItem:Boolean, val targetForm:Int,
        val abilityId:Int?, val abilityNumber:Int?
    )

    private fun apiIdFromUrl(url:String):Int? = url.trimEnd('/').substringAfterLast('/').toIntOrNull()

    private fun gen7EvolutionDetailAvailable(source:Int,target:Int,trigger:String,itemId:Int?,heldId:Int?,locationName:String):Boolean {
        // PokeAPI evolution chains mix methods from multiple game generations.  A Gen 7
        // save must only expose methods that actually existed in Sun/Moon/Ultra Sun/Ultra Moon.
        if((itemId != null && itemId > 959) || (heldId != null && heldId > 959)) return false

        // Some old species received new stone-based methods in later generations.
        // These item IDs themselves are old, so they need species-specific filtering.
        val postGen7LegacyItemMethods=setOf(
            Triple(133,470,85),  // Eevee -> Leafeon with Leaf Stone (Gen 8+)
            Triple(133,471,849), // Eevee -> Glaceon with Ice Stone (Gen 8+)
            Triple(82,462,83),   // Magneton -> Magnezone with Thunder Stone (Gen 8+)
            Triple(299,476,83),  // Nosepass -> Probopass with Thunder Stone (Gen 8+)
            Triple(737,738,83),  // Charjabug -> Vikavolt with Thunder Stone (Gen 8+)
            Triple(739,740,849)  // Crabrawler -> Crabominable with Ice Stone (post Gen 7)
        )
        if(itemId != null && Triple(source,target,itemId) in postGen7LegacyItemMethods) return false

        // Location-based evolution details are also cumulative in PokeAPI.  Keep only Alola
        // locations that can legitimately satisfy a location evolution in Generation 7.
        if(locationName.isNotBlank()) {
            val gen7Locations=setOf(
                "lush-jungle",      // Moss Rock: Eevee -> Leafeon
                "mount-lanakila",   // Ice Rock / Crabrawler evolutions
                "vast-poni-canyon", // special magnetic field
                "blush-mountain"    // special magnetic field (US/UM)
            )
            if(locationName !in gen7Locations) return false
        }

        return true
    }

    private data class Gen7EvolutionContext(
        val zoneId:Int,
        val mapId:Long,
        val specialLocation:Int,
        val locationName:String?,
        val resumeHour:Int?,
        val gameHour:Int?
    )

    private fun gen7LocationNameFromId(id:Int):String? = when(id) {
        86 -> "brooklet-hill"
        90 -> "lush-jungle" // legacy/table id fallback
        105 -> "lush-jungle" // USUM saved LastZoneID at the Moss Rock (confirmed on-device)
        106 -> "route-10"
        108 -> "route-11"
        110 -> "secluded-shore"
        112 -> "route-13"
        114 -> "tapu-village"
        120 -> "route-17"
        122 -> "route-12"
        126 -> "route-14"
        132 -> "malie-city"
        134 -> "malie-garden"
        138 -> "blush-mountain"
        146 -> "mount-lanakila"
        174 -> "vast-poni-canyon"
        184 -> "exeggutor-island"
        else -> null
    }

    private fun gen7EvolutionContext(save:ByteArray, gameId:Int?):Gen7EvolutionContext {
        // Situation block: map at 0x1000, last zone at 0x1074. GameTime resume hour at 0x4A0B.
        // Alola time at 0x4A48 is 86400 for normal/Sun time and 43200 for inverted/Moon time.
        // Situation.M is an 8-byte map identifier, not a 16-bit Alola location index.
        // Keep the full value so we can identify exact USUM sub-maps (Moss/Ice Rock etc.).
        val mapId=if(save.size>0x1007) {
            var v=0L
            for(i in 0 until 8) v = v or ((save[0x1000+i].toLong() and 0xFFL) shl (8*i))
            v
        } else -1L
        val specialLocation=if(save.size>0x1024) save[0x1024].toInt() and 0xFF else -1
        val zoneId=if(save.size>0x1075)readU16LE(save,0x1074) else -1
        val resumeHour=if(save.size>0x4A0B){(save[0x4A0B].toInt() and 0xFF).takeIf{it in 0..23}}else null
        val alolaTime=if(save.size>0x4A4B)readU32LE(save,0x4A48) else -1L
        val inverted=when(alolaTime){
            43200L -> true
            86400L -> false
            else -> gameId in setOf(31,33) // Moon / Ultra Moon fallback
        }
        val gameHour=resumeHour?.let{(it+(if(inverted)12 else 0))%24}
        // LastZoneID is retained as a separate field. Do not pretend the 64-bit map ID
        // is a PokeAPI/location-table number; that was the v0.43.31 false assumption.
        val name=gen7LocationNameFromId(zoneId)
        return Gen7EvolutionContext(zoneId,mapId,specialLocation,name,resumeHour,gameHour)
    }

    private fun gen7LocationRequirementMet(ctx:Gen7EvolutionContext, required:String):Boolean {
        if(required.isBlank())return true
        val wanted=when(required){
            "lush-jungle"->105
            "blush-mountain"->138
            "mount-lanakila"->146
            "vast-poni-canyon"->174
            else->return false
        }
        return ctx.zoneId==wanted || ctx.locationName==required
    }

    private fun gen7TimeRequirementMet(ctx:Gen7EvolutionContext, required:String):Boolean {
        val h=ctx.gameHour ?: return false
        val r=required.lowercase()
        return when {
            r.startsWith("day") -> h in 6..17
            r.startsWith("night") -> h !in 6..17
            r.startsWith("evening") -> h==17
            else -> false
        }
    }

    private fun gen7OverworldRainDetected(ctx:Gen7EvolutionContext):Boolean {
        val loc=ctx.locationName ?: return false
        val h=ctx.gameHour
        if(loc=="route-17")return true
        if(loc=="exeggutor-island" && h!=null)return h in 10..15 || h in 18..23
        if(h==17 && loc in setOf("lush-jungle","brooklet-hill","malie-city","malie-garden","route-10","route-11","route-12","route-13","blush-mountain","secluded-shore"))return true
        // Tapu Village / Route 14 weather can vary by day, so PSE deliberately does not guess.
        return false
    }

    private fun gen7ContextSuffix(ctx:Gen7EvolutionContext):String {
        val parts=mutableListOf<String>()
        ctx.locationName?.let{parts += "save: ${it.replace('-', ' ')}"}
        // Raw Situation values are intentionally exposed while calibrating exact USUM
        // evolution sub-maps. This lets a known-good in-game save identify the correct
        // Moss Rock / Ice Rock / magnetic-field map without guessing.
        parts += "zone ${ctx.zoneId}, map ${ctx.mapId}, special ${ctx.specialLocation}"
        ctx.gameHour?.let{parts += "in-game ${it.toString().padStart(2,'0')}:xx"}
        return if(parts.isEmpty())"" else " (${parts.joinToString(", ")})"
    }

    private fun gen7BoxAffection(save:ByteArray, global:Int):Int? {
        val boxOffset=if(save.size==SIZE_G7_SM)BOX_OFFSET_SM else if(save.size==SIZE_G7_USUM)BOX_OFFSET_USUM else return null
        val slotCount=32*30
        if(global !in 0 until slotCount)return null
        val off=boxOffset+global*PK6_STORED_SIZE
        if(off<0||off+PK6_STORED_SIZE>save.size)return null
        val pk=decryptPk6IfNeeded(save.copyOfRange(off,off+PK6_STORED_SIZE))
        val handler=pk[0x93].toInt() and 0xFF
        return if(handler==0) pk[0xCB].toInt() and 0xFF else pk[0xA3].toInt() and 0xFF
    }

    private fun gen6BoxAffection(save:ByteArray, global:Int):Int? {
        val boxOffset=when(save.size){SIZE_G6_XY->BOX_OFFSET_XY;SIZE_G6_ORAS->BOX_OFFSET_ORAS;else->return null}
        if(global !in 0 until 31*30)return null
        val off=boxOffset+global*PK6_STORED_SIZE
        if(off<0||off+PK6_STORED_SIZE>save.size)return null
        val pk=decryptPk6IfNeeded(save.copyOfRange(off,off+PK6_STORED_SIZE))
        val handler=pk[0x93].toInt() and 0xFF
        return if(handler==0) pk[0xCB].toInt() and 0xFF else pk[0xA3].toInt() and 0xFF
    }

    private fun gen6EvolutionDetailAvailable(source:Int,target:Int,itemId:Int?,heldId:Int?,minHappy:Int?):Boolean {
        if(target !in 1..721)return false
        if((itemId!=null&&itemId>775)||(heldId!=null&&heldId>775))return false
        // PokeAPI evolution chains are cumulative; these are later-generation methods for Gen 6 species.
        if(source==133&&target==470&&itemId==85)return false // Leaf Stone Leafeon is Gen 8+
        if(source==133&&target==471&&itemId==849)return false // Ice Stone method is post-Gen 6
        if(source==133&&target==700&&minHappy!=null)return false // friendship Sylveon is Gen 8+
        if(source==82&&target==462&&itemId==83)return false // Thunder Stone Magnezone is later
        if(source==299&&target==476&&itemId==83)return false // Thunder Stone Probopass is later
        return true
    }

    private fun prepareGen6Evolution(location:String, global:Int, p:PokemonEntry) {
        val file=importedFile?:return
        val save=runCatching{file.readBytes()}.getOrNull()?:return showDialog("Evolve Pokémon","Could not read the working copy.")
        if(generationForSize(save.size)!=6)return showDialog("Evolve Pokémon","This evolution path is for Generation 6 boxed Pokémon.")
        if(p.isEgg)return showDialog("Evolve Pokémon","Eggs cannot evolve.")
        val currentAffection=gen6BoxAffection(save,global)
        val loading=AlertDialog.Builder(this).setTitle("Check evolution").setMessage("Loading the Generation 6 evolution requirements…").setCancelable(false).create();loading.show()
        imageExecutor.execute {
            var loadError:String?=null
            val options=mutableListOf<Gen7EvolutionOption>()
            try{
                val species=fetchJson("https://pokeapi.co/api/v2/pokemon-species/${p.species}/")?:error("Could not load species data.")
                val chainUrl=species.optJSONObject("evolution_chain")?.optString("url").orEmpty()
                val growthUrl=species.optJSONObject("growth_rate")?.optString("url").orEmpty()
                var currentLevel=p.level?:1
                fetchJson(growthUrl)?.optJSONArray("levels")?.let{levels->for(i in 0 until levels.length()){val x=levels.optJSONObject(i)?:continue;if(p.experience>=x.optLong("experience",Long.MAX_VALUE))currentLevel=maxOf(currentLevel,x.optInt("level",1))}}
                val chain=fetchJson(chainUrl)?:error("Could not load evolution-chain data.")
                fun walk(node:JSONObject){
                    val nodeId=apiIdFromUrl(node.optJSONObject("species")?.optString("url").orEmpty())
                    if(nodeId==p.species){
                        val evolves=node.optJSONArray("evolves_to")?:JSONArray()
                        for(i in 0 until evolves.length()){
                            val child=evolves.optJSONObject(i)?:continue
                            val target=apiIdFromUrl(child.optJSONObject("species")?.optString("url").orEmpty())?:continue
                            if(target>721)continue
                            val targetName=child.optJSONObject("species")?.optString("name").orEmpty().replace('-',' ').split(' ').joinToString(" "){it.replaceFirstChar{c->c.uppercase()}}
                            val details=child.optJSONArray("evolution_details")?:JSONArray()
                            for(d in 0 until details.length()){
                                val e=details.optJSONObject(d)?:continue
                                val trigger=e.optJSONObject("trigger")?.optString("name").orEmpty()
                                val minLevel=if(e.isNull("min_level"))null else e.optInt("min_level")
                                val minHappy=if(e.isNull("min_happiness"))null else e.optInt("min_happiness")
                                val minAffection=if(e.isNull("min_affection"))null else e.optInt("min_affection")
                                val knownMove=apiIdFromUrl(e.optJSONObject("known_move")?.optString("url").orEmpty())
                                val knownMoveType=e.optJSONObject("known_move_type")?.optString("name").orEmpty()
                                val heldObj=e.optJSONObject("held_item");val heldId=apiIdFromUrl(heldObj?.optString("url").orEmpty());val heldName=heldObj?.optString("name").orEmpty().replace('-',' ')
                                val itemObj=e.optJSONObject("item");val itemId=apiIdFromUrl(itemObj?.optString("url").orEmpty());val itemName=itemObj?.optString("name").orEmpty().replace('-',' ')
                                if(!gen6EvolutionDetailAvailable(p.species,target,itemId,heldId,minHappy))continue
                                val gender=if(e.isNull("gender"))null else e.optInt("gender")
                                val time=e.optString("time_of_day")
                                val locationReq=e.optJSONObject("location")?.optString("name").orEmpty()
                                val tradeSpecies=apiIdFromUrl(e.optJSONObject("trade_species")?.optString("url").orEmpty())
                                val partySpecies=apiIdFromUrl(e.optJSONObject("party_species")?.optString("url").orEmpty())
                                val partyType=e.optJSONObject("party_type")?.optString("name").orEmpty()
                                val minBeauty=if(e.isNull("min_beauty"))null else e.optInt("min_beauty")
                                val rain=e.optBoolean("needs_overworld_rain",false)
                                val upside=e.optBoolean("turn_upside_down",false)
                                val relative=if(e.isNull("relative_physical_stats"))null else e.optInt("relative_physical_stats")
                                var met=true;var consume=false;val req=mutableListOf<String>()
                                if(minLevel!=null){req+="Lv.$minLevel+ (current Lv.$currentLevel)";if(currentLevel<minLevel)met=false}
                                if(minHappy!=null){req+="friendship $minHappy+";if(p.friendship<minHappy)met=false}
                                if(minAffection!=null){req+="affection $minAffection+${currentAffection?.let{" (current $it)"}?:""}";if(currentAffection==null||currentAffection<minAffection)met=false}
                                if(knownMove!=null){req+="knows move #$knownMove";if(knownMove !in p.moves)met=false}
                                if(knownMoveType.isNotBlank()){
                                    var knows=false
                                    for(m in p.moves.filter{it>0}){if(fetchJson("https://pokeapi.co/api/v2/move/$m/")?.optJSONObject("type")?.optString("name").orEmpty().equals(knownMoveType,true)){knows=true;break}}
                                    req+="knows a ${knownMoveType.replace('-',' ')}-type move";if(!knows)met=false
                                }
                                if(gender!=null){val need=if(gender==1)"female" else "male";req+="$need only";val actual=if(p.gender==1)1 else 2;if(actual!=gender)met=false}
                                if(heldId!=null){req+="holding ${heldName.ifBlank{"item #$heldId"}}";if(p.heldItem!=heldId)met=false;consume=true}
                                if(itemId!=null){req+="use ${itemName.ifBlank{"item #$itemId"}} (hold it in PSE)";if(p.heldItem!=itemId)met=false;consume=true}
                                if(time.isNotBlank()){req+=time;met=false}
                                if(locationReq.isNotBlank()){req+="at ${locationReq.replace('-',' ')}";met=false}
                                if(tradeSpecies!=null){req+="trade partner species #$tradeSpecies";met=false}
                                if(partySpecies!=null){req+="party contains species #$partySpecies";met=false}
                                if(partyType.isNotBlank()){req+="party contains a ${partyType.replace('-',' ')}-type Pokémon";met=false}
                                if(minBeauty!=null){req+="beauty $minBeauty+";met=false}
                                if(rain){req+="overworld rain";met=false}
                                if(upside){req+="device upside-down";met=false}
                                if(relative!=null){req+="physical-stat condition";met=false}
                                if(trigger=="trade")req+="trade (PSE substitutes the trade)"
                                if(trigger=="level-up"&&minLevel==null&&minHappy==null&&minAffection==null&&knownMove==null&&knownMoveType.isBlank()&&time.isBlank()&&locationReq.isBlank()&&partySpecies==null&&partyType.isBlank()&&minBeauty==null&&!rain&&!upside&&relative==null)req+="level-up"
                                val targetPokemon=fetchJson("https://pokeapi.co/api/v2/pokemon/$target/")
                                val abilities=targetPokemon?.optJSONArray("abilities");var ability:Int?=null;var abilityNumber:Int?=null
                                if(abilities!=null){
                                    val wanted=if(p.abilityNumber==4)3 else p.abilityNumber
                                    for(a in 0 until abilities.length()){val x=abilities.optJSONObject(a)?:continue;if(x.optInt("slot")==wanted){ability=apiIdFromUrl(x.optJSONObject("ability")?.optString("url").orEmpty());abilityNumber=when(wanted){1->1;2->2;3->4;else->null};break}}
                                    if(ability==null&&abilities.length()>0){val x=abilities.optJSONObject(0);ability=apiIdFromUrl(x?.optJSONObject("ability")?.optString("url").orEmpty());abilityNumber=when(x?.optInt("slot")){1->1;2->2;3->4;else->null}}
                                }
                                options+=Gen7EvolutionOption(target,targetName,trigger,req.joinToString(" • ").ifBlank{"Evolution requirement met"},met,consume,0,ability,abilityNumber)
                            }
                        }
                    }
                    val arr=node.optJSONArray("evolves_to")?:return
                    for(i in 0 until arr.length())arr.optJSONObject(i)?.let{walk(it)}
                }
                walk(chain.getJSONObject("chain"))
            }catch(e:Exception){loadError=e.message?:"Could not load evolution data."}
            val unique=options.distinctBy{listOf(it.targetSpecies,it.trigger,it.requirement,it.met,it.consumeHeldItem).joinToString("|")}
            mainHandler.post{if(!isFinishing&&!isDestroyed){loading.dismiss();if(loadError!=null)showDialog("Evolve Pokémon",loadError!!)else showGen6EvolutionChoices(location,global,p,unique)}}
        }
    }

    private fun showGen6EvolutionChoices(location:String,global:Int,p:PokemonEntry,options:List<Gen7EvolutionOption>){
        if(options.isEmpty())return showDialog("Evolve Pokémon","This Pokémon has no further Generation 6 evolution.")
        val labels=options.map{"${if(it.met)"✓" else "🔒"} ${it.targetName} (#${it.targetSpecies})\n${it.requirement}"}.toTypedArray()
        AlertDialog.Builder(this).setTitle("Evolve ${p.nickname.ifBlank{"Pokémon #${p.species}"}}").setItems(labels){_,which->
            val o=options[which]
            if(!o.met)showDialog("Requirements not met","PSE will not evolve this Pokémon yet.\n\n${o.requirement}\n\nGen 6 location, time, weather, party-partner, beauty and upside-down conditions stay locked until PSE can prove them rather than guessing.")
            else AlertDialog.Builder(this).setTitle("Evolve into ${o.targetName}?").setMessage("Requirement met: ${o.requirement}.${if(o.consumeHeldItem)"\n\nThe required held/evolution item will be consumed." else ""}\n\nPSE will update the PK6, register the evolved species in the Gen 6 Pokédex, rebuild the affected save-block checksums and verify the result before keeping the change.").setNegativeButton("Cancel",null).setPositiveButton("Evolve"){_,_->performGen6Evolution(location,global,p,o)}.show()
        }.setNegativeButton("Cancel",null).show()
    }

    private fun performGen6Evolution(location:String,global:Int,old:PokemonEntry,o:Gen7EvolutionOption){
        val file=importedFile?:return
        val original=runCatching{file.readBytes()}.getOrNull()?:return showDialog("Evolution failed","Could not read the working copy.")
        if(generationForSize(original.size)!=6)return
        val boxOffset=if(original.size==SIZE_G6_XY)BOX_OFFSET_XY else BOX_OFFSET_ORAS
        val off=boxOffset+global*PK6_STORED_SIZE
        val current=parsePk6(original,off,PK6_STORED_SIZE,false,721)
        if(current==null||current.species!=old.species||current.pid!=old.pid)return showDialog("Evolution stopped","The Pokémon in this slot changed. Nothing was written.")
        val work=original.copyOf();val pk=decryptPk6IfNeeded(work.copyOfRange(off,off+PK6_STORED_SIZE))
        try{
            writeU16LE(pk,0x08,o.targetSpecies)
            if(o.consumeHeldItem)writeU16LE(pk,0x0A,0)
            o.abilityId?.let{pk[0x14]=it.toByte()};o.abilityNumber?.let{pk[0x15]=((pk[0x15].toInt() and 0xF8) or (it and 7)).toByte()}
            pk[0x1D]=(pk[0x1D].toInt() and 0x07).toByte()
            if(!old.isNicknamed)writeGen6String(pk,0x40,26,o.targetName)
            updatePk6Checksum(pk);encryptPk6(pk).copyInto(work,off)
            updateGen6BoxChecksum(work)
            registerGen6Dex(work,o.targetSpecies,old.gender,old.shiny,old.language)
            updateGen6DexChecksum(work)
            file.writeBytes(work)
            val verify=file.readBytes();val q=parsePk6(verify,off,PK6_STORED_SIZE,false,721)
            require(q!=null&&q.checksumValid&&q.species==o.targetSpecies&&q.pid==old.pid&&(o.abilityId==null||q.ability==o.abilityId)&&(o.abilityNumber==null||q.abilityNumber==o.abilityNumber)){"The evolved PK6 species/ability did not verify."}
            require(gen6DexCaught(verify,o.targetSpecies)){"The evolved species was not registered as caught in the Gen 6 Pokédex."}
            require(gen6BlockChecksumValid(verify,20)){"The Gen 6 Pokédex block checksum did not verify."}
            require(gen6BoxChecksumValid(verify)){"The Gen 6 box checksum did not verify."}
            Toast.makeText(this,"${o.targetName} evolved, Pokédex registered and verified",Toast.LENGTH_LONG).show();showPokemonDetails(location,q)
        }catch(e:Exception){runCatching{file.writeBytes(original)};showDialog("Evolution failed","${e.message?:"Unknown error"}\n\nPSE restored the original working save.")}
    }

    private fun gen6BlockInfo(data:ByteArray,blockId:Int):Pair<Int,Int>?=when(data.size){
        SIZE_G6_XY->when(blockId){20->0x15000 to 0x006A0;53->BOX_OFFSET_XY to 0x34AD0;else->null}
        SIZE_G6_ORAS->when(blockId){20->0x15000 to 0x011CC;56->BOX_OFFSET_ORAS to 0x34AD0;else->null}
        else->null
    }

    private fun gen6ChecksumOffset(data:ByteArray,blockId:Int):Int=data.size-0x200+0x14+(blockId*8)+6
    private fun updateGen6BlockChecksum(data:ByteArray,blockId:Int){val info=gen6BlockInfo(data,blockId)?:return;val crc=crc16Ccitt(data,info.first,info.second);val o=gen6ChecksumOffset(data,blockId);data[o]=(crc and 255).toByte();data[o+1]=((crc ushr 8) and 255).toByte()}
    private fun gen6BlockChecksumValid(data:ByteArray,blockId:Int):Boolean{val info=gen6BlockInfo(data,blockId)?:return false;return readU16LEAt(data,gen6ChecksumOffset(data,blockId))==crc16Ccitt(data,info.first,info.second)}
    private fun updateGen6DexChecksum(data:ByteArray)=updateGen6BlockChecksum(data,20)
    private fun gen6BoxChecksumValid(data:ByteArray):Boolean{val id=if(data.size==SIZE_G6_XY)53 else if(data.size==SIZE_G6_ORAS)56 else return false;return gen6BlockChecksumValid(data,id)}

    private fun registerGen6Dex(data:ByteArray,species:Int,gender:Int,shiny:Boolean,language:Int){
        if(species !in 1..721)return
        val base=0x15000
        // Gen 6 Zukan species flags use 0x60-byte padded regions: caught, four seen variants,
        // then four displayed variants. This registers the evolved species without touching form-only data.
        val bit=species-1;val bd=bit ushr 3;val mask=1 shl(bit and 7);val region=0x60
        data[base+0x08+bd]=(data[base+0x08+bd].toInt() or mask).toByte()
        val shift=(gender.coerceIn(0,1)) or ((if(shiny)1 else 0) shl 1)
        data[base+0x08+region*(1+shift)+bd]=(data[base+0x08+region*(1+shift)+bd].toInt() or mask).toByte()
        var displayed=false
        for(i in 5..8)if((data[base+0x08+region*i+bd].toInt() and mask)!=0)displayed=true
        if(!displayed)data[base+0x08+region*(5+shift)+bd]=(data[base+0x08+region*(5+shift)+bd].toInt() or mask).toByte()
    }
    private fun gen6DexCaught(data:ByteArray,species:Int):Boolean{if(data.size!=SIZE_G6_XY&&data.size!=SIZE_G6_ORAS)return false;val bit=species-1;return (data[0x15000+0x08+(bit ushr 3)].toInt() and (1 shl(bit and 7)))!=0}

    private fun prepareGen7Evolution(location:String, global:Int, p:PokemonEntry) {
        val file=importedFile ?: return
        val save=runCatching{file.readBytes()}.getOrNull() ?: return showDialog("Evolve Pokémon","Could not read the working copy.")
        if(generationForSize(save.size)!=7)return showDialog("Evolve Pokémon","This first evolution build is for Generation 7 boxed Pokémon.")
        if(p.isEgg)return showDialog("Evolve Pokémon","Eggs cannot evolve.")
        val currentAffection=gen7BoxAffection(save,global)
        val gameId=gen7SaveGameId(save)
        val evolutionContext=gen7EvolutionContext(save,gameId)
        val loading=AlertDialog.Builder(this).setTitle("Check evolution").setMessage("Loading the Generation 7 evolution requirements…").setCancelable(false).create();loading.show()
        imageExecutor.execute {
            var loadError:String?=null
            val options=mutableListOf<Gen7EvolutionOption>()
            try {
                val species=fetchJson("https://pokeapi.co/api/v2/pokemon-species/${p.species}/") ?: error("Could not load species data.")
                val chainUrl=species.optJSONObject("evolution_chain")?.optString("url").orEmpty()
                val growthUrl=species.optJSONObject("growth_rate")?.optString("url").orEmpty()
                var currentLevel=p.level ?: 1
                fetchJson(growthUrl)?.optJSONArray("levels")?.let { levels ->
                    for(li in 0 until levels.length()){val lv=levels.optJSONObject(li)?:continue;val xp=lv.optLong("experience",Long.MAX_VALUE);if(p.experience>=xp)currentLevel=maxOf(currentLevel,lv.optInt("level",1))}
                }
                val chain=fetchJson(chainUrl) ?: error("Could not load evolution-chain data.")
                fun walk(node:JSONObject) {
                    val nodeId=apiIdFromUrl(node.optJSONObject("species")?.optString("url").orEmpty())
                    if(nodeId==p.species) {
                        val evolves=node.optJSONArray("evolves_to") ?: JSONArray()
                        for(i in 0 until evolves.length()) {
                            val child=evolves.optJSONObject(i) ?: continue
                            val target=apiIdFromUrl(child.optJSONObject("species")?.optString("url").orEmpty()) ?: continue
                            if(target>807)continue
                            // Cosmoem has version-exclusive evolutions in Gen 7. Never offer the opposite mascot.
                            if(p.species==790 && ((target==791 && gameId in setOf(31,33)) || (target==792 && gameId in setOf(30,32)))) continue
                            // Own Tempo Rockruff's Dusk evolution exists only in Ultra Sun/Ultra Moon.
                            if(p.species==744 && p.ability==20 && gameId in setOf(30,31)) continue
                            val baseTargetName=child.optJSONObject("species")?.optString("name").orEmpty().replace('-', ' ').split(' ').joinToString(" "){it.replaceFirstChar{c->c.uppercase()}}
                            val details=child.optJSONArray("evolution_details") ?: JSONArray()
                            for(d in 0 until details.length()) {
                                val e=details.optJSONObject(d) ?: continue
                                val trigger=e.optJSONObject("trigger")?.optString("name").orEmpty()
                                val minLevel=if(e.isNull("min_level"))null else e.optInt("min_level")
                                val minHappy=if(e.isNull("min_happiness"))null else e.optInt("min_happiness")
                                val minAffection=if(e.isNull("min_affection"))null else e.optInt("min_affection")
                                val knownMoveType=e.optJSONObject("known_move_type")?.optString("name").orEmpty()
                                val heldObj=e.optJSONObject("held_item"); val heldId=apiIdFromUrl(heldObj?.optString("url").orEmpty()); val heldName=heldObj?.optString("name").orEmpty().replace('-', ' ')
                                val itemObj=e.optJSONObject("item"); val itemId=apiIdFromUrl(itemObj?.optString("url").orEmpty()); val itemName=itemObj?.optString("name").orEmpty().replace('-', ' ')
                                // PokeAPI evolution chains are cumulative. Eevee's Leaf/Ice Stone methods
                                // and friendship-based Sylveon are Gen 8+, so never expose them in Gen 7.
                                if(p.species==133 && target==470 && itemName.equals("leaf stone",true))continue
                                if(p.species==133 && target==471 && itemName.equals("ice stone",true))continue
                                if(p.species==133 && target==700 && minHappy!=null)continue
                                val locationReq=e.optJSONObject("location")?.optString("name").orEmpty()
                                if(!gen7EvolutionDetailAvailable(p.species,target,trigger,itemId,heldId,locationReq)) continue
                                val knownMove=apiIdFromUrl(e.optJSONObject("known_move")?.optString("url").orEmpty())
                                val gender=if(e.isNull("gender"))null else e.optInt("gender")
                                val time=e.optString("time_of_day")
                                val tradeSpecies=apiIdFromUrl(e.optJSONObject("trade_species")?.optString("url").orEmpty())
                                val partySpecies=apiIdFromUrl(e.optJSONObject("party_species")?.optString("url").orEmpty())
                                val partyType=e.optJSONObject("party_type")?.optString("name").orEmpty()
                                val minBeauty=if(e.isNull("min_beauty"))null else e.optInt("min_beauty")
                                val rain=e.optBoolean("needs_overworld_rain",false)
                                val upside=e.optBoolean("turn_upside_down",false)
                                val relative=if(e.isNull("relative_physical_stats"))null else e.optInt("relative_physical_stats")
                                var met=true; val req=mutableListOf<String>(); var consume=false
                                if(minLevel!=null){req += "Lv.$minLevel+ (current Lv.$currentLevel)"; if(currentLevel<minLevel)met=false}
                                if(minHappy!=null){req += "friendship $minHappy+"; if(p.friendship<minHappy)met=false}
                                if(minAffection!=null){
                                    val affection=currentAffection
                                    req += "affection $minAffection+${if(affection!=null)" (current $affection)" else ""}"
                                    if(affection==null||affection<minAffection)met=false
                                }
                                if(knownMoveType.isNotBlank()){
                                    var knowsType=false
                                    for(moveId in p.moves.filter{it>0}){
                                        val moveType=fetchJson("https://pokeapi.co/api/v2/move/$moveId/")?.optJSONObject("type")?.optString("name").orEmpty()
                                        if(moveType.equals(knownMoveType,true)){knowsType=true;break}
                                    }
                                    req += "knows a ${knownMoveType.replace('-', ' ')}-type move"
                                    if(!knowsType)met=false
                                }
                                if(heldId!=null){req += "holding ${heldName.ifBlank{"item #$heldId"}}"; if(p.heldItem!=heldId)met=false; consume=true}
                                if(itemId!=null){req += "use ${itemName.ifBlank{"item #$itemId"}} (hold it in PSE)"; if(p.heldItem!=itemId)met=false; consume=true}
                                if(knownMove!=null){req += "knows move #$knownMove"; if(knownMove !in p.moves)met=false}
                                if(gender!=null){val wanted=if(gender==1)1 else 0; req += if(wanted==1)"female" else "male"; if(p.gender!=wanted)met=false}
                                var effectiveTime=time
                                // Alolan Rattata and Cubone require nighttime for their regional evolutions in Gen 7.
                                if((p.species==19 && p.form==1 && target==20) || (p.species==104 && target==105)) effectiveTime="night"
                                // Rockruff is version/form specific in Gen 7. PokeAPI's cumulative rows can
                                // describe multiple eras, so make the Gen 7 rule explicit here.
                                if(p.species==744 && target==745){
                                    effectiveTime=when{
                                        p.ability==20 && gameId in setOf(32,33)->"evening (5:00–5:59 in-game)"
                                        gameId in setOf(31,33)->"night"
                                        else->"day"
                                    }
                                }
                                if(effectiveTime.isNotBlank()){
                                    req += effectiveTime + gen7ContextSuffix(evolutionContext)
                                    if(!gen7TimeRequirementMet(evolutionContext,effectiveTime))met=false
                                }
                                if(locationReq.isNotBlank()){
                                    req += "at ${locationReq.replace('-', ' ')}" + gen7ContextSuffix(evolutionContext)
                                    if(!gen7LocationRequirementMet(evolutionContext,locationReq))met=false
                                }
                                if(tradeSpecies!=null){req += "trade partner species #$tradeSpecies"; met=false}
                                if(partySpecies!=null){req += "party contains species #$partySpecies"; met=false}
                                if(partyType.isNotBlank()){req += "party contains a ${partyType.replace('-', ' ')}-type Pokémon"; met=false}
                                if(minBeauty!=null){req += "beauty $minBeauty+"; met=false}
                                if(rain){
                                    val rainMet=gen7OverworldRainDetected(evolutionContext)
                                    req += "overworld rain" + gen7ContextSuffix(evolutionContext)
                                    if(!rainMet)met=false
                                }
                                if(upside){req += "device upside-down"; met=false}
                                if(relative!=null){req += "physical-stat condition"; met=false}
                                if(trigger=="trade") req += "trade (PSE substitutes the trade)"
                                if(trigger=="level-up" && minLevel==null && minHappy==null && minAffection==null && knownMove==null && knownMoveType.isBlank() && effectiveTime.isBlank() && partySpecies==null && partyType.isBlank() && minBeauty==null && !rain && !upside && relative==null) req += "level-up"
                                val targetForm=gen7EvolutionTargetForm(p.species,p.form,target,gameId,p.ability)
                                val targetName=gen7EvolutionDisplayName(target,targetForm,baseTargetName)
                                val targetPokemon=gen7EvolutionPokemonJson(target,targetForm)
                                val abilities=targetPokemon?.optJSONArray("abilities")
                                var ability:Int?=null
                                var abilityNumber:Int?=null
                                if(abilities!=null){
                                    val wantedApiSlot=if(p.abilityNumber==4)3 else p.abilityNumber
                                    for(a in 0 until abilities.length()){
                                        val x=abilities.optJSONObject(a)?:continue
                                        val slot=x.optInt("slot")
                                        if(slot==wantedApiSlot){
                                            ability=apiIdFromUrl(x.optJSONObject("ability")?.optString("url").orEmpty())
                                            abilityNumber=when(slot){1->1;2->2;3->4;else->null}
                                            break
                                        }
                                    }
                                    if(ability==null&&abilities.length()>0){
                                        val x=abilities.optJSONObject(0)
                                        ability=apiIdFromUrl(x?.optJSONObject("ability")?.optString("url").orEmpty())
                                        abilityNumber=when(x?.optInt("slot")){1->1;2->2;3->4;else->null}
                                    }
                                }
                                options += Gen7EvolutionOption(target,targetName,trigger,req.joinToString(" • ").ifBlank{"Evolution requirement met"},met,consume,targetForm,ability,abilityNumber)
                            }
                        }
                    }
                    val arr=node.optJSONArray("evolves_to")?:return
                    for(i in 0 until arr.length())arr.optJSONObject(i)?.let{walk(it)}
                }
                walk(chain.getJSONObject("chain"))
            } catch(e:Exception){loadError=e.message?:"Could not load evolution data."}
            // PokeAPI can contain multiple historical evolution-detail rows that resolve to
            // the same Gen 7 result. Collapse exact Gen 7 choices before presenting them.
            val uniqueOptions=options.distinctBy { o ->
                listOf(o.targetSpecies,o.targetForm,o.trigger,o.requirement,o.met,o.consumeHeldItem).joinToString("|")
            }
            mainHandler.post { if(!isFinishing&&!isDestroyed){loading.dismiss();if(loadError!=null)showDialog("Evolve Pokémon",loadError!!) else showGen7EvolutionChoices(location,global,p,uniqueOptions)} }
        }
    }

    private fun gen7EvolutionTargetForm(source:Int, form:Int, target:Int, gameId:Int?, abilityId:Int):Int {
        // Native Alola evolutions. Regional forms are stored in the PK7 form field.
        if(source==744 && target==745){
            // Own Tempo Rockruff is the special USUM-only Dusk evolution (form 2).
            // Ordinary Rockruff is version-bound in Gen 7: Midday (form 0) in Sun/US,
            // Midnight (form 1) in Moon/UM. The time requirement is checked separately.
            if(abilityId==20 && gameId in setOf(32,33)) return 2
            return if(gameId in setOf(31,33)) 1 else 0
        }
        if(form==0)return if(source==102&&target==103)1 else if(source==104&&target==105)1 else if(source==25&&target==26)1 else 0
        val carries=setOf(19 to 20,27 to 28,37 to 38,50 to 51,52 to 53,74 to 75,75 to 76,88 to 89)
        return if((source to target) in carries)1 else 0
    }

    private fun gen7EvolutionDisplayName(targetSpecies:Int,targetForm:Int,baseName:String):String {
        if(targetSpecies==745)return when(targetForm){1->"Midnight Form Lycanroc";2->"Dusk Form Lycanroc";else->"Midday Form Lycanroc"}
        if(targetForm!=1)return baseName
        val alolanSpecies=setOf(20,26,28,38,51,53,76,89,103,105)
        return if(targetSpecies in alolanSpecies) "Alolan $baseName" else baseName
    }

    private fun gen7EvolutionPokemonJson(targetSpecies:Int,targetForm:Int):JSONObject? {
        if(targetForm==0)return fetchJson("https://pokeapi.co/api/v2/pokemon/$targetSpecies/")
        val species=fetchJson("https://pokeapi.co/api/v2/pokemon-species/$targetSpecies/") ?: return null
        val varieties=species.optJSONArray("varieties") ?: return null
        for(i in 0 until varieties.length()){
            val v=varieties.optJSONObject(i)?:continue
            val p=v.optJSONObject("pokemon")?:continue
            val name=p.optString("name")
            if(targetForm==1 && name.endsWith("-alola")){
                return fetchJson(p.optString("url"))
            }
        }
        return fetchJson("https://pokeapi.co/api/v2/pokemon/$targetSpecies/")
    }

    private fun gen7SaveGameId(save:ByteArray):Int? {
        val status=when(save.size){SIZE_G7_SM->STATUS_OFFSET_SM;SIZE_G7_USUM->STATUS_OFFSET_USUM;else->return null}
        if(status+4>=save.size)return null
        return save[status+4].toInt() and 0xFF
    }

    private fun showGen7EvolutionChoices(location:String,global:Int,p:PokemonEntry,options:List<Gen7EvolutionOption>){
        if(options.isEmpty())return showDialog("Evolve Pokémon","This Pokémon has no further Generation 7 evolution.")
        val labels=options.map{ o -> "${if(o.met)"✓" else "🔒"} ${o.targetName} (#${o.targetSpecies})\n${o.requirement}" }.toTypedArray()
        AlertDialog.Builder(this).setTitle("Evolve ${p.nickname.ifBlank{"Pokémon #${p.species}"}}").setItems(labels){_,which->
            val o=options[which]
            if(!o.met)showDialog("Requirements not met","PSE will not evolve this Pokémon yet.\n\n${o.requirement}\n\nPSE now checks saved Gen 7 location, in-game time and deterministic overworld rain. Partner-species and any condition the save cannot prove stay locked rather than guessed.")
            else AlertDialog.Builder(this).setTitle("Evolve into ${o.targetName}?").setMessage("Requirement met: ${o.requirement}.${if(o.consumeHeldItem)"\n\nThe required held/evolution item will be consumed." else ""}\n\nPSE will update the PK7, register the evolved species as caught/seen in the Gen 7 Pokédex, rebuild both save-block checksums and verify everything before keeping the change.").setNegativeButton("Cancel",null).setPositiveButton("Evolve"){_,_->performGen7Evolution(location,global,p,o)}.show()
        }.setNegativeButton("Cancel",null).show()
    }

    private fun performGen7Evolution(location:String,global:Int,old:PokemonEntry,o:Gen7EvolutionOption){
        val file=importedFile?:return
        val original=runCatching{file.readBytes()}.getOrNull()?:return showDialog("Evolution failed","Could not read the working copy.")
        if(generationForSize(original.size)!=7)return
        val boxOffset=if(original.size==SIZE_G7_SM)BOX_OFFSET_SM else BOX_OFFSET_USUM
        val off=boxOffset+global*PK6_STORED_SIZE
        val current=parsePk6(original,off,PK6_STORED_SIZE,false,807)
        if(current==null||current.species!=old.species||current.pid!=old.pid)return showDialog("Evolution stopped","The Pokémon in this slot changed. Nothing was written.")
        val work=original.copyOf(); val pk=decryptPk6IfNeeded(work.copyOfRange(off,off+PK6_STORED_SIZE))
        try{
            writeU16LE(pk,0x08,o.targetSpecies)
            if(o.consumeHeldItem)writeU16LE(pk,0x0A,0)
            o.abilityId?.let{pk[0x14]=it.toByte()}
            o.abilityNumber?.let{pk[0x15]=((pk[0x15].toInt() and 0xF8) or (it and 0x07)).toByte()}
            pk[0x1D]=((pk[0x1D].toInt() and 0x07) or ((o.targetForm and 0x1F) shl 3)).toByte()
            if(!old.isNicknamed)writeGen6String(pk,0x40,26,o.targetName)
            updatePk6Checksum(pk);encryptPk6(pk).copyInto(work,off)
            updateGen7SaveBlockChecksum(work,14,boxOffset,0x36600)
            registerGen7Dex(work,o.targetSpecies,o.targetForm,old.gender,old.shiny,old.language)
            val dexInfo=gen7BlockInfo(work,6)?:error("Gen 7 Pokédex block layout is unavailable.")
            updateGen7SaveBlockChecksum(work,6,dexInfo.first,dexInfo.second)
            finalizeGen7Save(work)
            file.writeBytes(work)
            val verify=file.readBytes();val q=parsePk6(verify,off,PK6_STORED_SIZE,false,807)
            require(q!=null&&q.checksumValid&&q.species==o.targetSpecies&&q.form==o.targetForm&&q.pid==old.pid&&
                (o.abilityId==null||q.ability==o.abilityId)&&(o.abilityNumber==null||q.abilityNumber==o.abilityNumber)){"The evolved PK7 species/form/ability did not verify."}
            require(gen7DexCaught(verify,o.targetSpecies)){"The evolved species was not registered as caught in the Pokédex."}
            val(ok,msg)=validateGen7CoreChecksums(verify);require(ok){msg}
            Toast.makeText(this,"${o.targetName} evolved, Pokédex registered and verified",Toast.LENGTH_LONG).show();showPokemonDetails(location,q)
        }catch(e:Exception){runCatching{file.writeBytes(original)};showDialog("Evolution failed","${e.message?:"Unknown error"}\n\nPSE restored the original working save.")}
    }

    private fun registerGen7Dex(data:ByteArray,species:Int,form:Int,gender:Int,shiny:Boolean,language:Int){
        if(species !in 1..807)return
        val dexBase=if(data.size==SIZE_G7_SM)0x02A00 else 0x02C00
        // Caught and language flags are species-level in SM/USUM. Seen/displayed always gets
        // a valid species entry too; this prevents an Alolan evolution from being absent from
        // the in-game dex even when a form-specific display bit was not previously selected.
        val bit=species-1;val bd=bit ushr 3;val bm=bit and 7;val mask=1 shl bm
        data[dexBase+0x88+bd]=(data[dexBase+0x88+bd].toInt() or mask).toByte() // caught
        val shift=(gender.coerceIn(0,1)) or ((if(shiny)1 else 0) shl 1);val br=0x8C;val flags=dexBase+0xF0
        data[flags+shift*br+bd]=(data[flags+shift*br+bd].toInt() or mask).toByte() // seen species
        var displayed=false;for(i in 4..7)if((data[flags+i*br+bd].toInt() and mask)!=0)displayed=true
        if(!displayed)data[flags+(4+shift)*br+bd]=(data[flags+(4+shift)*br+bd].toInt() or mask).toByte()
        var lang=language;if(lang in 1..10&&lang!=6){if(lang>=7)lang--;lang--;val lbit=bit*9+lang;if((lbit ushr 3)<920){val lo=dexBase+0x550+(lbit ushr 3);data[lo]=(data[lo].toInt() or (1 shl (lbit and 7))).toByte()}}
    }

    private fun gen7DexCaught(data:ByteArray,species:Int):Boolean{
        val dexBase=if(data.size==SIZE_G7_SM)0x02A00 else if(data.size==SIZE_G7_USUM)0x02C00 else return false
        val bit=species-1;return (data[dexBase+0x88+(bit ushr 3)].toInt() and (1 shl(bit and 7)))!=0
    }

    private fun gen7DexRegistered(data:ByteArray,p:PokemonEntry):Boolean{
        if(p.species !in 1..807||!gen7DexCaught(data,p.species))return false
        val dexBase=if(data.size==SIZE_G7_SM)0x02A00 else if(data.size==SIZE_G7_USUM)0x02C00 else return false
        val bit=p.species-1;val byte=bit ushr 3;val mask=1 shl(bit and 7);val planeSize=0x8C;val flags=dexBase+0xF0
        val shift=p.gender.coerceIn(0,1) or ((if(p.shiny)1 else 0) shl 1)
        if((data[flags+shift*planeSize+byte].toInt() and mask)==0)return false
        if((4..7).none{plane->(data[flags+plane*planeSize+byte].toInt() and mask)!=0})return false
        var language=p.language
        if(language in 1..10&&language!=6){if(language>=7)language--;language--;val languageBit=bit*9+language;val languageByte=languageBit ushr 3;if(languageByte>=920)return false;if((data[dexBase+0x550+languageByte].toInt() and (1 shl(languageBit and 7)))==0)return false}
        return true
    }

    data class PokemonEditValues(
        val nickname: String, val experience: Long, val nature: Int,
        val shiny: Boolean, val gender: Int, val form: Int, val language: Int,
        val pokerusStrain: Int, val pokerusDays: Int, val markingValue: Int,
        val ability: Int, val abilityNumber: Int, val heldItem: Int, val friendship: Int,
        val moves: IntArray, val pp: IntArray, val ivs: IntArray, val evs: IntArray
    )

    private fun validatePokemonEdit(v: PokemonEditValues, gen7: Boolean): String? {
        if (v.nickname.length > 12) return "Nickname must be 12 characters or fewer."
        if (v.experience !in 0..0xFFFFFFFFL) return "Experience is outside the supported range."
        if (v.nature !in 0..24) return "Nature ID must be between 0 and 24."
        if (v.gender !in 0..2) return "Gender must be Male, Female or Genderless."
        if (v.form !in 0..31) return "Form ID must be between 0 and 31."
        val validLanguages = if (gen7) setOf(1,2,3,4,5,7,8,9,10) else setOf(1,2,3,4,5,7,8)
        if (v.language !in validLanguages) return "That language is not valid for Gen ${if (gen7) 7 else 6}."
        if (v.pokerusStrain !in 0..15 || v.pokerusDays !in 0..15) return "Pokérus strain and days must be between 0 and 15."
        if (v.pokerusStrain == 0 && v.pokerusDays != 0) return "Pokérus days must be 0 when status is None."
        if (v.pokerusDays > 0 && v.pokerusStrain == 0) return "Active Pokérus needs a strain between 1 and 15."
        if (v.markingValue !in 0..(if(gen7)0x0FFF else 0x3F)) return "Marking value is outside the native Gen ${if(gen7)7 else 6} range."
        val maxAbility = if (gen7) 233 else 191
        val maxItem = if (gen7) 959 else 775
        val maxMove = if (gen7) 728 else 621
        if (v.ability !in 0..maxAbility) return "Ability ID must be between 0 and $maxAbility for Gen ${if (gen7) 7 else 6}."
        if (v.abilityNumber !in intArrayOf(1,2,4)) return "Ability slot must be 1, 2 or 4."
        if (v.heldItem !in 0..maxItem) return "Held item ID must be between 0 and $maxItem for Gen ${if (gen7) 7 else 6}."
        if (v.friendship !in 0..255) return "Friendship must be between 0 and 255."
        if (v.moves.any { it !in 0..maxMove }) return "Move IDs must be between 0 and $maxMove for Gen ${if (gen7) 7 else 6}."
        if (v.pp.any { it !in 0..64 }) return "Move PP must be between 0 and 64."
        if (v.ivs.any { it !in 0..31 }) return "Every IV must be between 0 and 31."
        if (v.evs.any { it !in 0..252 }) return "Every EV must be between 0 and 252."
        if (v.evs.sum() > 510) return "EV total cannot exceed 510."
        return null
    }

    private fun confirmPokemonEdit(location: String, global: Int, p: PokemonEntry, v: PokemonEditValues) {
        android.app.AlertDialog.Builder(this)
            .setTitle("Save Pokémon changes?")
            .setMessage("This changes only PSE's working copy. Save & Replace Current Save creates the safety backup before the emulator save is overwritten.")
            .setNegativeButton("Cancel", null)
            .setPositiveButton("Save") { _, _ -> writePokemonEdit(location, global, p, v) }
            .show()
    }

    private fun writePokemonEdit(location: String, global: Int, old: PokemonEntry, v: PokemonEditValues, afterSuccess: ((PokemonEntry) -> Unit)? = null) {
        val file = importedFile ?: return
        val save = try { file.readBytes() } catch (e: Exception) {
            showDialog("Edit failed", "Could not read save: ${e.message}"); return
        }
        val gen7 = generationForSize(save.size) == 7
        val boxOffset = when (save.size) {
            SIZE_G6_XY -> BOX_OFFSET_XY
            SIZE_G6_ORAS -> BOX_OFFSET_ORAS
            SIZE_G7_SM -> BOX_OFFSET_SM
            SIZE_G7_USUM -> BOX_OFFSET_USUM
            else -> -1
        }
        val slotCount = if (gen7) 32 * 30 else BOX_SLOT_COUNT
        val maxSpecies = if (gen7) 807 else 721
        if (boxOffset < 0 || global !in 0 until slotCount) return
        val offset = boxOffset + global * PK6_STORED_SIZE
        val current = parsePk6(save, offset, PK6_STORED_SIZE, false, maxSpecies)
        if (current == null || current.species != old.species || current.pid != old.pid) {
            showDialog("Edit stopped", "The Pokémon in this slot changed since the editor was opened. Nothing was written.")
            return
        }
        val originalRaw = save.copyOfRange(offset, offset + PK6_STORED_SIZE)
        val pk = decryptPk6IfNeeded(originalRaw)
        var backupCreated = false
        try {
            // PK6 and PK7 share this core stored layout. Keep species/trainer IDs intact,
            // but rebuild the editable identity fields and verify them after encryption.
            writeGen6String(pk, 0x40, 26, v.nickname)
            writeU32LE(pk, 0x10, v.experience)
            pk[0x1C] = v.nature.toByte()
            pk[0x14] = v.ability.toByte()
            pk[0x15] = ((pk[0x15].toInt() and 0xF8) or (v.abilityNumber and 0x07)).toByte()
            writeU16LE(pk, 0x0A, v.heldItem)

            // Gender + form share byte 0x1D; preserve the fateful-encounter bit.
            pk[0x1D] = ((pk[0x1D].toInt() and 0x01) or ((v.gender and 0x03) shl 1) or ((v.form and 0x1F) shl 3)).toByte()
            pk[0xE3] = v.language.toByte()
            pk[0x2B] = (((v.pokerusStrain and 0x0F) shl 4) or (v.pokerusDays and 0x0F)).toByte()
            if(gen7)writeU16LE(pk,0x16,v.markingValue) else pk[0x2A]=v.markingValue.toByte()

            // Shininess is derived from TID/SID/PID. Preserve the PID low word and only
            // adjust the high word when the requested shiny state differs.
            val currentPid = readU32LE(pk, 0x18)
            val lowPid = currentPid.toInt() and 0xFFFF
            val highPid = ((currentPid ushr 16) and 0xFFFF).toInt()
            val currentSv = old.tid xor old.sid xor lowPid xor highPid
            val currentlyShiny = currentSv < 16
            var newPid = currentPid
            if (v.shiny != currentlyShiny) {
                val newHigh = if (v.shiny) {
                    (old.tid xor old.sid xor lowPid) and 0xFFFF
                } else {
                    (highPid xor 0x10) and 0xFFFF
                }
                newPid = (lowPid.toLong() and 0xFFFFL) or ((newHigh.toLong() and 0xFFFFL) shl 16)
                writeU32LE(pk, 0x18, newPid)
            }
            if (old.currentHandler == 0) pk[0xCA] = v.friendship.toByte() else pk[0xA2] = v.friendship.toByte()
            for (i in 0..3) {
                writeU16LE(pk, 0x5A + i * 2, v.moves[i])
                pk[0x62 + i] = v.pp[i].toByte()
            }
            for (i in 0..5) pk[0x1E + i] = v.evs[i].toByte()
            var iv32 = readU32LE(pk, 0x74)
            // Preserve only the egg bit; rebuild IV and nickname bits from requested values.
            iv32 = iv32 and 0x40000000L
            for (i in 0..5) iv32 = iv32 or ((v.ivs[i].toLong() and 31L) shl (i * 5))
            val shouldBeNicknamed = if (v.nickname == old.nickname) old.isNicknamed else v.nickname.isNotBlank()
            if (shouldBeNicknamed) iv32 = iv32 or 0x80000000L
            writeU32LE(pk, 0x74, iv32)
            updatePk6Checksum(pk) // same additive stored-PKM checksum used by PK6/PK7
            val encrypted = encryptPk6(pk) // Gen 6/7 share the same stored-PKM crypto path

            createEditBackup(file)
            backupCreated = true
            encrypted.copyInto(save, offset)
            if (gen7) updateGen7BoxChecksum(save) else updateGen6BoxChecksum(save)
            file.writeBytes(save)

            val verifyBytes = file.readBytes()
            val verified = parsePk6(verifyBytes, offset, PK6_STORED_SIZE, false, maxSpecies)
            val verifiedRaw = verifyBytes.copyOfRange(offset, offset + PK6_STORED_SIZE)
            val slotChanged = !verifiedRaw.contentEquals(originalRaw)
            if (verified == null || !slotChanged || !verified.checksumValid || verified.species != old.species || verified.pid != newPid ||
                verified.experience != v.experience || verified.nature != v.nature ||
                verified.shiny != v.shiny || verified.gender != v.gender || verified.form != v.form ||
                verified.language != v.language || verified.pokerusStrain != v.pokerusStrain || verified.pokerusDays != v.pokerusDays ||
                verified.markingValue != v.markingValue ||
                verified.ability != v.ability || verified.abilityNumber != v.abilityNumber ||
                verified.heldItem != v.heldItem || verified.friendship != v.friendship ||
                !verified.moves.contentEquals(v.moves) || !verified.movePP.contentEquals(v.pp) ||
                !verified.ivs.contentEquals(v.ivs) || !verified.evs.contentEquals(v.evs) ||
                verified.nickname != v.nickname) {
                originalRaw.copyInto(save, offset)
                if (gen7) updateGen7BoxChecksum(save) else updateGen6BoxChecksum(save)
                file.writeBytes(save)
                showDialog("Verification failed", "PSE restored the original Pokémon because the post-write verification did not pass.")
                return
            }
            Toast.makeText(this, if (gen7) "PK7 updated, save checksum refreshed and verified" else "Pokémon updated and verified", Toast.LENGTH_LONG).show()
            if (afterSuccess != null) afterSuccess(verified) else showPokemonDetails(location, verified)
        } catch (e: Exception) {
            if (backupCreated) {
                try {
                    originalRaw.copyInto(save, offset)
                    if (gen7) updateGen7BoxChecksum(save) else updateGen6BoxChecksum(save)
                    file.writeBytes(save)
                } catch (_: Exception) { }
            }
            showDialog("Edit failed", e.message ?: "Unknown error")
        }
    }

    private fun confirmDeletePokemon(location: String, global: Int, p: PokemonEntry) {
        val name = p.nickname.ifBlank { "Species #${p.species}" }
        android.app.AlertDialog.Builder(this)
            .setTitle("Delete $name?")
            .setMessage("This will clear $location from PSE's working copy. The emulator save will not be touched until Save & Replace Current Save is used.")
            .setNegativeButton("Cancel", null)
            .setPositiveButton("Delete") { _, _ -> deleteBoxedPokemon(location, global, p) }
            .show()
    }

    private fun deleteBoxedPokemon(location: String, global: Int, expected: PokemonEntry) {
        val file = importedFile ?: return
        val save = try { file.readBytes() } catch (e: Exception) {
            showDialog("Delete failed", "Could not read save: ${e.message}")
            return
        }
        val gen7 = generationForSize(save.size) == 7
        val boxOffset = when (save.size) {
            SIZE_G6_XY -> BOX_OFFSET_XY
            SIZE_G6_ORAS -> BOX_OFFSET_ORAS
            SIZE_G7_SM -> BOX_OFFSET_SM
            SIZE_G7_USUM -> BOX_OFFSET_USUM
            else -> -1
        }
        val slotCount = if (gen7) 32 * 30 else BOX_SLOT_COUNT
        val maxSpecies = if (gen7) 807 else 721
        if (boxOffset < 0 || global !in 0 until slotCount) {
            showDialog("Delete failed", "This PC slot is outside the supported save area.")
            return
        }
        val offset = boxOffset + global * PK6_STORED_SIZE
        val current = parsePk6(save, offset, PK6_STORED_SIZE, false, maxSpecies)
        if (current == null || current.species != expected.species || current.pid != expected.pid) {
            showDialog("Delete stopped", "The Pokémon in this slot changed since the editor was opened. Nothing was deleted.")
            return
        }
        val originalRaw = save.copyOfRange(offset, offset + PK6_STORED_SIZE)
        try {
            ByteArray(PK6_STORED_SIZE).copyInto(save, offset)
            if (gen7) updateGen7BoxChecksum(save) else updateGen6BoxChecksum(save)
            file.writeBytes(save)

            val verifyBytes = file.readBytes()
            val cleared = verifyBytes.copyOfRange(offset, offset + PK6_STORED_SIZE).all { it == 0.toByte() }
            val parsed = parsePk6(verifyBytes, offset, PK6_STORED_SIZE, false, maxSpecies)
            if (!cleared || parsed != null) {
                originalRaw.copyInto(save, offset)
                if (gen7) updateGen7BoxChecksum(save) else updateGen6BoxChecksum(save)
                file.writeBytes(save)
                showDialog("Verification failed", "PSE restored the Pokémon because the cleared slot did not verify correctly.")
                return
            }
            Toast.makeText(this, "Pokémon deleted from working copy and verified", Toast.LENGTH_LONG).show()
            showPokemonViewer()
        } catch (e: Exception) {
            try {
                originalRaw.copyInto(save, offset)
                if (gen7) updateGen7BoxChecksum(save) else updateGen6BoxChecksum(save)
                file.writeBytes(save)
            } catch (_: Exception) { }
            showDialog("Delete failed", e.message ?: "Unknown error")
        }
    }

    private fun boxStorageInfo(data: ByteArray): Triple<Int, Int, Int>? = when (data.size) {
        SIZE_G6_XY -> Triple(BOX_OFFSET_XY, 31 * 30, 721)
        SIZE_G6_ORAS -> Triple(BOX_OFFSET_ORAS, 31 * 30, 721)
        SIZE_G7_SM -> Triple(BOX_OFFSET_SM, 32 * 30, 807)
        SIZE_G7_USUM -> Triple(BOX_OFFSET_USUM, 32 * 30, 807)
        else -> null
    }

    private fun refreshBoxChecksum(data: ByteArray) {
        if (generationForSize(data.size) == 7) updateGen7BoxChecksum(data) else updateGen6BoxChecksum(data)
    }

    private fun selectedRawRecords(data: ByteArray): List<Pair<Int, ByteArray>>? {
        val (boxOffset, slotCount, maxSpecies) = boxStorageInfo(data) ?: return null
        val selected = selectedPokemonSlots.toList().sorted()
        if (selected.isEmpty()) return emptyList()
        val out = ArrayList<Pair<Int, ByteArray>>()
        for (global in selected) {
            if (global !in 0 until slotCount) return null
            val offset = boxOffset + global * PK6_STORED_SIZE
            val parsed = parsePk6(data, offset, PK6_STORED_SIZE, false, maxSpecies) ?: return null
            val raw = data.copyOfRange(offset, offset + PK6_STORED_SIZE)
            if (!parsed.checksumValid) return null
            out.add(global to raw)
        }
        return out
    }

    private fun chooseBulkMoveDestination(returnBox: Int) {
        val file = importedFile ?: return
        val data = try { file.readBytes() } catch (e: Exception) {
            showDialog("Move failed", "Could not read save: ${e.message}")
            return
        }
        val info = boxStorageInfo(data) ?: return
        val (boxOffset, slotCount, maxSpecies) = info
        val records = selectedRawRecords(data)
        if (records == null || records.isEmpty()) {
            showDialog("Move stopped", "One or more selected Pokémon changed. Re-select them and try again.")
            return
        }
        val selectedSet = records.map { it.first }.toSet()
        val needed = records.size
        val boxCount = slotCount / 30
        val labels = ArrayList<String>()
        val targets = ArrayList<Int>()
        var totalAfterClear = 0
        for (global in 0 until slotCount) {
            val offset = boxOffset + global * PK6_STORED_SIZE
            if (global in selectedSet || parsePk6(data, offset, PK6_STORED_SIZE, false, maxSpecies) == null) totalAfterClear++
        }
        if (totalAfterClear >= needed) {
            labels.add("First available slots across PC")
            targets.add(-1)
        }
        for (box in 0 until boxCount) {
            var emptyAfterClear = 0
            for (slot in 0 until 30) {
                val global = box * 30 + slot
                val offset = boxOffset + global * PK6_STORED_SIZE
                if (global in selectedSet || parsePk6(data, offset, PK6_STORED_SIZE, false, maxSpecies) == null) emptyAfterClear++
            }
            if (emptyAfterClear >= needed) {
                labels.add("Box ${box + 1} • $emptyAfterClear spaces after move")
                targets.add(box)
            }
        }
        if (labels.isEmpty()) {
            showDialog("Move Pokémon", "No destination has enough space for $needed selected Pokémon.")
            return
        }
        AlertDialog.Builder(this)
            .setTitle("Move $needed Pokémon to…")
            .setItems(labels.toTypedArray()) { _, which -> confirmBulkMove(targets[which], returnBox) }
            .setNegativeButton("Cancel", null)
            .show()
    }

    private fun confirmBulkMove(targetBox: Int, returnBox: Int) {
        val count = selectedPokemonSlots.size
        val destination = if (targetBox < 0) "the first available PC slots" else "Box ${targetBox + 1}"
        AlertDialog.Builder(this)
            .setTitle("Move $count Pokémon?")
            .setMessage("The selected Pokémon will be moved together to $destination in PSE's working copy. Their complete stored PK data will be preserved and the operation will be verified before it is accepted.")
            .setNegativeButton("Cancel", null)
            .setPositiveButton("Move") { _, _ -> bulkMoveSelected(targetBox, returnBox) }
            .show()
    }

    private fun bulkMoveSelected(targetBox: Int, returnBox: Int) {
        val file = importedFile ?: return
        val original = try { file.readBytes() } catch (e: Exception) {
            showDialog("Move failed", "Could not read save: ${e.message}")
            return
        }
        val (boxOffset, slotCount, maxSpecies) = boxStorageInfo(original) ?: return
        val records = selectedRawRecords(original)
        if (records == null || records.isEmpty()) {
            showDialog("Move stopped", "One or more selected Pokémon changed. Nothing was moved.")
            return
        }
        val work = original.copyOf()
        val sourceSet = records.map { it.first }.toSet()
        try {
            for ((global, _) in records) {
                java.util.Arrays.fill(work, boxOffset + global * PK6_STORED_SIZE, boxOffset + (global + 1) * PK6_STORED_SIZE, 0.toByte())
            }
            val range: IntRange = if (targetBox < 0) 0 until slotCount else (targetBox * 30) until (targetBox * 30 + 30)
            val empty = range.filter { global ->
                parsePk6(work, boxOffset + global * PK6_STORED_SIZE, PK6_STORED_SIZE, false, maxSpecies) == null
            }
            if (empty.size < records.size) {
                showDialog("Move stopped", "The destination no longer has enough empty slots. Nothing was moved.")
                return
            }
            val destinations = empty.take(records.size)
            for (i in records.indices) records[i].second.copyInto(work, boxOffset + destinations[i] * PK6_STORED_SIZE)
            refreshBoxChecksum(work)
            file.writeBytes(work)

            val verify = file.readBytes()
            val destinationSet = destinations.toSet()
            var ok = true
            for (i in records.indices) {
                val off = boxOffset + destinations[i] * PK6_STORED_SIZE
                val actual = verify.copyOfRange(off, off + PK6_STORED_SIZE)
                if (!actual.contentEquals(records[i].second)) { ok = false; break }
            }
            if (ok) {
                for (source in sourceSet) {
                    if (source !in destinationSet) {
                        val off = boxOffset + source * PK6_STORED_SIZE
                        if (!verify.copyOfRange(off, off + PK6_STORED_SIZE).all { it == 0.toByte() }) { ok = false; break }
                    }
                }
            }
            if (!ok) {
                file.writeBytes(original)
                showDialog("Verification failed", "PSE restored the original working copy because the bulk move did not verify correctly.")
                return
            }
            val showBox = destinations.firstOrNull()?.div(30) ?: returnBox
            resetPokemonSelection()
            Toast.makeText(this, "${records.size} Pokémon moved and verified", Toast.LENGTH_LONG).show()
            showPokemonViewer("boxes", showBox)
        } catch (e: Exception) {
            try { file.writeBytes(original) } catch (_: Exception) { }
            showDialog("Move failed", e.message ?: "Unknown error. The original working copy was restored.")
        }
    }

    private fun chooseBulkDuplicateDestination(returnBox: Int) {
        val file = importedFile ?: return
        val data = try { file.readBytes() } catch (_: Exception) { return }
        val (boxOffset, slotCount, maxSpecies) = boxStorageInfo(data) ?: return
        val records = selectedRawRecords(data)
        if (records == null || records.isEmpty()) {
            showDialog("Duplicate stopped", "One or more selected Pokémon changed. Re-select them and try again.")
            return
        }
        val needed = records.size
        val labels = ArrayList<String>()
        val targets = ArrayList<Int>()
        var totalEmpty = 0
        for (global in 0 until slotCount) {
            if (parsePk6(data, boxOffset + global * PK6_STORED_SIZE, PK6_STORED_SIZE, false, maxSpecies) == null) totalEmpty++
        }
        if (totalEmpty >= needed) { labels.add("First available slots across PC • $totalEmpty empty"); targets.add(-1) }
        for (box in 0 until slotCount / 30) {
            var empty = 0
            for (slot in 0 until 30) {
                val global = box * 30 + slot
                if (parsePk6(data, boxOffset + global * PK6_STORED_SIZE, PK6_STORED_SIZE, false, maxSpecies) == null) empty++
            }
            if (empty >= needed) { labels.add("Box ${box + 1} • $empty empty slots"); targets.add(box) }
        }
        if (labels.isEmpty()) {
            showDialog("Duplicate Pokémon", "There are not enough empty PC slots for $needed duplicates.")
            return
        }
        AlertDialog.Builder(this)
            .setTitle("Duplicate $needed Pokémon to…")
            .setItems(labels.toTypedArray()) { _, which -> confirmBulkDuplicate(targets[which], returnBox) }
            .setNegativeButton("Cancel", null)
            .show()
    }

    private fun confirmBulkDuplicate(targetBox: Int, returnBox: Int) {
        val count = selectedPokemonSlots.size
        val destination = if (targetBox < 0) "the first available PC slots" else "Box ${targetBox + 1}"
        AlertDialog.Builder(this)
            .setTitle("Duplicate $count Pokémon?")
            .setMessage("PSE will copy all selected Pokémon to $destination, preserve the originals, rebuild the box checksum and verify every new slot.")
            .setNegativeButton("Cancel", null)
            .setPositiveButton("Duplicate") { _, _ -> bulkDuplicateSelected(targetBox, returnBox) }
            .show()
    }

    private fun bulkDuplicateSelected(targetBox: Int, returnBox: Int) {
        val file = importedFile ?: return
        val original = try { file.readBytes() } catch (_: Exception) { return }
        val (boxOffset, slotCount, maxSpecies) = boxStorageInfo(original) ?: return
        val records = selectedRawRecords(original) ?: return
        if (records.isEmpty()) return
        val work = original.copyOf()
        try {
            val range: IntRange = if (targetBox < 0) 0 until slotCount else (targetBox * 30) until (targetBox * 30 + 30)
            val empty = range.filter { parsePk6(work, boxOffset + it * PK6_STORED_SIZE, PK6_STORED_SIZE, false, maxSpecies) == null }
            if (empty.size < records.size) {
                showDialog("Duplicate stopped", "The destination no longer has enough empty slots. Nothing was duplicated.")
                return
            }
            val destinations = empty.take(records.size)
            for (i in records.indices) records[i].second.copyInto(work, boxOffset + destinations[i] * PK6_STORED_SIZE)
            refreshBoxChecksum(work)
            file.writeBytes(work)
            val verify = file.readBytes()
            var ok = true
            for (i in records.indices) {
                val off = boxOffset + destinations[i] * PK6_STORED_SIZE
                val raw = verify.copyOfRange(off, off + PK6_STORED_SIZE)
                val parsed = parsePk6(raw, 0, PK6_STORED_SIZE, false, maxSpecies)
                if (!raw.contentEquals(records[i].second) || parsed == null || !parsed.checksumValid) { ok = false; break }
            }
            if (!ok) {
                file.writeBytes(original)
                showDialog("Verification failed", "PSE restored the original working copy because one or more duplicates did not verify.")
                return
            }
            val showBox = destinations.firstOrNull()?.div(30) ?: returnBox
            resetPokemonSelection()
            Toast.makeText(this, "${records.size} Pokémon duplicated and verified", Toast.LENGTH_LONG).show()
            showPokemonViewer("boxes", showBox)
        } catch (e: Exception) {
            try { file.writeBytes(original) } catch (_: Exception) { }
            showDialog("Duplicate failed", e.message ?: "Unknown error. The original working copy was restored.")
        }
    }

    private fun confirmBulkDelete(returnBox: Int) {
        val count = selectedPokemonSlots.size
        if (count <= 0) return
        AlertDialog.Builder(this)
            .setTitle("Delete $count Pokémon?")
            .setMessage("This will clear all selected PC slots from PSE's working copy. The emulator save will not be touched until Save & Replace Current Save is used. The entire bulk delete will roll back if verification fails.")
            .setNegativeButton("Cancel", null)
            .setPositiveButton("Delete") { _, _ -> bulkDeleteSelected(returnBox) }
            .show()
    }

    private fun bulkDeleteSelected(returnBox: Int) {
        val file = importedFile ?: return
        val original = try { file.readBytes() } catch (_: Exception) { return }
        val (boxOffset, _, _) = boxStorageInfo(original) ?: return
        val records = selectedRawRecords(original)
        if (records == null || records.isEmpty()) {
            showDialog("Delete stopped", "One or more selected Pokémon changed. Nothing was deleted.")
            return
        }
        val work = original.copyOf()
        try {
            for ((global, _) in records) {
                java.util.Arrays.fill(work, boxOffset + global * PK6_STORED_SIZE, boxOffset + (global + 1) * PK6_STORED_SIZE, 0.toByte())
            }
            refreshBoxChecksum(work)
            file.writeBytes(work)
            val verify = file.readBytes()
            val ok = records.all { (global, _) ->
                val off = boxOffset + global * PK6_STORED_SIZE
                verify.copyOfRange(off, off + PK6_STORED_SIZE).all { it == 0.toByte() }
            }
            if (!ok) {
                file.writeBytes(original)
                showDialog("Verification failed", "PSE restored the original working copy because the bulk delete did not verify correctly.")
                return
            }
            resetPokemonSelection()
            Toast.makeText(this, "${records.size} Pokémon deleted and verified", Toast.LENGTH_LONG).show()
            showPokemonViewer("boxes", returnBox)
        } catch (e: Exception) {
            try { file.writeBytes(original) } catch (_: Exception) { }
            showDialog("Delete failed", e.message ?: "Unknown error. The original working copy was restored.")
        }
    }

    private fun confirmBulkDepositToBank(returnBox: Int) {
        val count = selectedPokemonSlots.size
        if (count <= 0) return
        AlertDialog.Builder(this)
            .setTitle("Move $count Pokémon to PSE Bank?")
            .setMessage("PSE will first verify every Bank entry, then clear the selected PC slots as one transaction. If any verification fails, the working save is restored and the new Bank entries are removed.")
            .setNegativeButton("Cancel", null)
            .setPositiveButton("Move to Bank") { _, _ -> bulkDepositToBank(returnBox) }
            .show()
    }

    private fun bulkDepositToBank(returnBox: Int) {
        val file = importedFile ?: return
        val original = try { file.readBytes() } catch (_: Exception) { return }
        val generation = generationForSize(original.size)
        val (boxOffset, _, maxSpecies) = boxStorageInfo(original) ?: return
        val records = selectedRawRecords(original)
        if (records == null || records.isEmpty()) {
            showDialog("PSE Bank", "One or more selected Pokémon changed. Nothing was moved.")
            return
        }
        val created = ArrayList<File>()
        val work = original.copyOf()
        try {
            val stamp = System.currentTimeMillis()
            val ext = if (generation == 7) "pk7" else "pk6"
            for ((index, pair) in records.withIndex()) {
                val (global, raw) = pair
                val parsed = parsePk6(raw, 0, PK6_STORED_SIZE, false, maxSpecies) ?: error("A selected Pokémon could not be validated.")
                if (!parsed.checksumValid) error("A selected Pokémon failed its stored-Pokémon checksum.")
                val bankFile = File(bankDir(), "${stamp}_${index}_${parsed.species}.$ext")
                bankFile.writeBytes(raw)
                if (!bankFile.readBytes().contentEquals(raw)) error("A PSE Bank entry could not be verified.")
                created.add(bankFile)
                java.util.Arrays.fill(work, boxOffset + global * PK6_STORED_SIZE, boxOffset + (global + 1) * PK6_STORED_SIZE, 0.toByte())
            }
            refreshBoxChecksum(work)
            file.writeBytes(work)
            val verify = file.readBytes()
            val saveOk = records.all { (global, _) ->
                val off = boxOffset + global * PK6_STORED_SIZE
                verify.copyOfRange(off, off + PK6_STORED_SIZE).all { it == 0.toByte() }
            }
            val bankOk = created.size == records.size && created.indices.all { created[it].readBytes().contentEquals(records[it].second) }
            if (!saveOk || !bankOk) error("Post-write verification did not pass.")
            resetPokemonSelection()
            Toast.makeText(this, "${records.size} Pokémon moved to PSE Bank and verified", Toast.LENGTH_LONG).show()
            showBank()
        } catch (e: Exception) {
            try { file.writeBytes(original) } catch (_: Exception) { }
            created.forEach { try { it.delete() } catch (_: Exception) { } }
            showDialog("Bank move failed", (e.message ?: "Unknown error") + " The original working copy was restored.")
            if (pokemonMultiSelectMode) showPokemonViewer("boxes", returnBox)
        }
    }

    private fun updatePk6Checksum(pk: ByteArray) {
        var sum = 0
        var pos = 0x08
        while (pos + 1 < PK6_STORED_SIZE) {
            sum = (sum + readU16LE(pk, pos)) and 0xFFFF
            pos += 2
        }
        writeU16LE(pk, 0x06, sum)
    }

    private fun encryptPk6(decrypted: ByteArray): ByteArray {
        val data = decrypted.copyOf()
        if (data.size < PK6_STORED_SIZE) return data
        val ec = readU32LE(data, 0) and 0xFFFFFFFFL
        val sv = ((ec ushr 13) and 31).toInt()
        val invert = BLOCK_POSITION_INVERT[sv]
        shufflePk6(data, 0x08, invert)
        cryptPk6Range(data, 0x08, PK6_STORED_SIZE, ec)
        if (data.size > PK6_STORED_SIZE) cryptPk6Range(data, PK6_STORED_SIZE, data.size, ec)
        return data
    }

    private fun chooseDuplicateDestination(location: String, p: PokemonEntry) {
        val sourceGlobal = boxedLocationToGlobalIndex(location) ?: return
        val file = importedFile ?: return
        val data = try { file.readBytes() } catch (_: Exception) { ByteArray(0) }
        val (boxOffset, slotCount, maxSpecies) = boxStorageInfo(data) ?: return
        val firstEmpty = findFirstEmptyBoxSlot(data, boxOffset, slotCount, maxSpecies)
        if (firstEmpty == null) { showDialog("Duplicate Pokémon", "No empty PC slot was found."); return }
        val labels = ArrayList<String>()
        labels.add("First empty slot (Box ${firstEmpty / 30 + 1} • Slot ${firstEmpty % 30 + 1})")
        for (box in 0 until slotCount / 30) labels.add("Box ${box + 1} • ${countEmptySlotsInBox(data, boxOffset, box, maxSpecies)} empty slots")
        AlertDialog.Builder(this)
            .setTitle("Duplicate ${p.nickname.ifBlank { "Pokémon" }} to…")
            .setItems(labels.toTypedArray()) { _, which ->
                if (which == 0) duplicatePokemon(sourceGlobal, p, firstEmpty)
                else showDuplicateSlotGrid(sourceGlobal, p, which - 1)
            }
            .setNegativeButton("Cancel", null)
            .show()
    }

    private fun showDuplicateSlotGrid(sourceGlobal: Int, p: PokemonEntry, boxIndex: Int) {
        val file = importedFile ?: return
        val data = try { file.readBytes() } catch (_: Exception) { ByteArray(0) }
        val (boxOffset, slotCount, maxSpecies) = boxStorageInfo(data) ?: return
        if (boxIndex !in 0 until (slotCount / 30)) return
        val wrapper = LinearLayout(this).apply { orientation = LinearLayout.VERTICAL; setPadding(dp(12),dp(8),dp(12),dp(8)) }
        addMutedLine(wrapper, "Tap an empty destination. The original Pokémon stays where it is.")
        val grid = GridLayout(this).apply { columnCount=6; rowCount=5; alignmentMode=GridLayout.ALIGN_BOUNDS; useDefaultMargins=false }
        val cellWidth=((resources.displayMetrics.widthPixels-dp(90))/6).coerceAtLeast(dp(42))
        for (slot in 0 until 30) {
            val target=boxIndex*30+slot
            val occupied=parsePk6(data,boxOffset+target*PK6_STORED_SIZE,PK6_STORED_SIZE,false,maxSpecies)!=null
            val cell=TextView(this).apply {
                text=if(occupied) "●\n${slot+1}" else "○\n${slot+1}"
                gravity=Gravity.CENTER; textSize=13f
                setTextColor(if(occupied) Color.rgb(105,105,105) else TEXT)
                setBackgroundColor(if(occupied) Color.rgb(35,35,35) else Color.rgb(55,55,55))
                isEnabled=!occupied
                if(!occupied) setOnClickListener { duplicatePokemon(sourceGlobal,p,target) }
            }
            grid.addView(cell,GridLayout.LayoutParams().apply { width=cellWidth;height=dp(58);setMargins(dp(2),dp(2),dp(2),dp(2)) })
        }
        wrapper.addView(grid)
        AlertDialog.Builder(this).setTitle("Box ${boxIndex+1} • duplicate to slot").setView(wrapper).setNegativeButton("Cancel",null).show()
    }

    private fun duplicatePokemon(sourceGlobal: Int, p: PokemonEntry, targetGlobal: Int) {
        if (sourceGlobal == targetGlobal) return
        val file=importedFile ?: return
        val original=try { file.readBytes() } catch (_:Exception){ ByteArray(0) }
        val (boxOffset, slotCount, maxSpecies)=boxStorageInfo(original) ?: return
        if(sourceGlobal !in 0 until slotCount || targetGlobal !in 0 until slotCount) return
        val sourceOffset=boxOffset+sourceGlobal*PK6_STORED_SIZE
        val targetOffset=boxOffset+targetGlobal*PK6_STORED_SIZE
        if(parsePk6(original,targetOffset,PK6_STORED_SIZE,false,maxSpecies)!=null){ showDialog("Duplicate stopped","The destination is no longer empty.");return }
        val raw=original.copyOfRange(sourceOffset,sourceOffset+PK6_STORED_SIZE)
        val sourceCheck=parsePk6(raw,0,PK6_STORED_SIZE,false,maxSpecies)
        if(sourceCheck==null || !sourceCheck.checksumValid){ showDialog("Duplicate stopped","The source Pokémon did not pass its stored-Pokémon checksum.");return }
        AlertDialog.Builder(this)
            .setTitle("Create duplicate?")
            .setMessage("The original stays in place. PSE will copy ${p.nickname.ifBlank{"this Pokémon"}} to Box ${targetGlobal/30+1} • Slot ${targetGlobal%30+1} in the working copy.")
            .setNegativeButton("Cancel",null)
            .setPositiveButton("Duplicate") { _, _ ->
                try {
                    val work = original.copyOf()
                    raw.copyInto(work,targetOffset)
                    refreshBoxChecksum(work)
                    file.writeBytes(work)
                    val verifyData=file.readBytes()
                    val actual=verifyData.copyOfRange(targetOffset,targetOffset+PK6_STORED_SIZE)
                    val verify=parsePk6(actual,0,PK6_STORED_SIZE,false,maxSpecies)
                    if(!actual.contentEquals(raw) || verify==null || !verify.checksumValid || verify.species!=p.species || verify.pid!=p.pid){
                        file.writeBytes(original)
                        showDialog("Duplicate verification failed","PSE restored the original working copy because the duplicate could not be verified.")
                    } else {
                        Toast.makeText(this,"Duplicate created in Box ${targetGlobal/30+1} • Slot ${targetGlobal%30+1}",Toast.LENGTH_LONG).show()
                        showPokemonViewer("boxes",targetGlobal/30)
                    }
                } catch(e:Exception){
                    try { file.writeBytes(original) } catch (_:Exception) { }
                    showDialog("Duplicate failed",(e.message?:"Unknown error") + " The original working copy was restored.")
                }
            }.show()
    }

    private fun bankDir(): File = File(filesDir, "pse_bank").apply { mkdirs() }

    private data class Gen1BankInventory(
        val validEntries:List<Pair<File,Gen1Pokemon>>,
        val invalidFiles:List<File>
    )

    private fun gen1BankInventory():Gen1BankInventory {
        val valid=ArrayList<Pair<File,Gen1Pokemon>>()
        val invalid=ArrayList<File>()
        val files=bankDir().listFiles()?.filter{it.isFile&&it.extension.equals("pse1",true)}?.sortedBy{it.name}?:emptyList()
        for(file in files){
            val parsed=runCatching{parseGen1BankPayload(file.readBytes())}.getOrNull()
            if(parsed==null) invalid.add(file) else valid.add(file to parsed)
        }
        return Gen1BankInventory(valid,invalid)
    }

    private fun gen1BankEntryCountForDeposit():Int {
        val inventory=gen1BankInventory()
        require(inventory.invalidFiles.isEmpty()){"PSE Bank contains an unreadable or invalid Gen 1 record. It was preserved unchanged; quarantine it before depositing another Pokémon."}
        return inventory.validEntries.size
    }

    private fun gen1BankQuarantineDir():File=File(filesDir,"pse_bank_quarantine").apply{mkdirs()}

    private fun gen1BankQuarantineTarget(source:File):File{
        val dir=gen1BankQuarantineDir()
        val stem=source.nameWithoutExtension.ifBlank{"gen1_record"}
        var target=File(dir,source.name)
        var suffix=1
        while(target.exists()){target=File(dir,"${stem}_$suffix.pse1");suffix++}
        return target
    }

    private fun quarantineInvalidGen1BankRecords(opened:List<File>){
        val moved=ArrayList<Triple<File,File,ByteArray>>()
        val failure=runCatching{
            require(opened.isNotEmpty()){"There are no invalid Gen 1 Bank records to quarantine."}
            val bankRoot=bankDir().canonicalFile
            val fresh=gen1BankInventory().invalidFiles.sortedBy{it.name}
            require(fresh.map{it.canonicalPath}==opened.sortedBy{it.name}.map{it.canonicalPath}){"The invalid Gen 1 Bank inventory changed. Reopen PSE Bank and try again."}
            for(source in fresh){
                require(source.parentFile?.canonicalFile==bankRoot&&source.extension.equals("pse1",true)){"An invalid record was outside the Gen 1 Bank."}
                val bytes=source.readBytes()
                require(parseGen1BankPayload(bytes)==null){"${source.name} became a valid Gen 1 Bank record and was not quarantined."}
                val target=gen1BankQuarantineTarget(source)
                require(source.renameTo(target)){"PSE could not quarantine ${source.name}."}
                moved.add(Triple(source,target,bytes))
                require(!source.exists()&&target.isFile&&target.readBytes().contentEquals(bytes)){"${source.name} did not verify byte-for-byte after quarantine."}
            }
            require(gen1BankInventory().invalidFiles.isEmpty()){"Another invalid Gen 1 Bank record appeared during quarantine."}
        }.exceptionOrNull()
        if(failure!=null){
            var rollbackOk=true
            for((source,target,bytes) in moved.asReversed()){
                val restored=runCatching{
                    if(source.exists())require(source.readBytes().contentEquals(bytes))
                    else require(target.renameTo(source)||runCatching{source.writeBytes(bytes);target.delete();true}.getOrDefault(false))
                    require(source.isFile&&source.readBytes().contentEquals(bytes)&&!target.exists())
                }.isSuccess
                if(!restored)rollbackOk=false
            }
            val suffix=if(rollbackOk)" Every moved record was restored byte-for-byte." else " One or more records could not be restored automatically; their preserved copies remain in PSE's quarantine folder."
            showDialog("Gen 1 Bank quarantine",(failure.message?:"The invalid records could not be quarantined.")+suffix)
            return
        }
        selectedBankFiles.clear()
        Toast.makeText(this,"Quarantined ${moved.size} invalid Gen 1 Bank record${if(moved.size==1)"" else "s"}",Toast.LENGTH_LONG).show()
        showBank()
    }

    private fun gen1BankQuarantinedFiles():List<File> =
        gen1BankQuarantineDir().listFiles()?.filter{it.isFile&&it.extension.equals("pse1",true)}?.sortedBy{it.name}?:emptyList()

    private fun gen1BankRestoreTarget(source:File):File{
        val dir=bankDir()
        val stem=source.nameWithoutExtension.ifBlank{"gen1_record"}
        var target=File(dir,source.name)
        var suffix=1
        while(target.exists()){target=File(dir,"${stem}_restored_$suffix.pse1");suffix++}
        return target
    }

    private fun restoreGen1BankQuarantineRecord(source:File,openedRaw:ByteArray){
        var target:File?=null
        val failure=runCatching{
            require(source.parentFile?.canonicalFile==gen1BankQuarantineDir().canonicalFile&&source.extension.equals("pse1",true)){"The selected record is outside PSE's Gen 1 quarantine."}
            require(source.isFile){"The selected quarantined record no longer exists."}
            val current=source.readBytes()
            require(current.contentEquals(openedRaw)){"The quarantined record changed. Reopen the recovery list and try again."}
            val destination=gen1BankRestoreTarget(source);target=destination
            require(source.renameTo(destination)){"PSE could not restore ${source.name} to the active Gen 1 Bank."}
            require(!source.exists()&&destination.isFile&&destination.readBytes().contentEquals(current)){"The restored record did not verify byte-for-byte."}
        }.exceptionOrNull()
        if(failure!=null){
            val destination=target
            val rollbackOk=if(destination!=null&&destination.isFile&&!source.exists())runCatching{
                require(destination.renameTo(source)||runCatching{source.writeBytes(openedRaw);destination.delete();true}.getOrDefault(false))
                require(source.isFile&&source.readBytes().contentEquals(openedRaw)&&!destination.exists())
            }.isSuccess else source.isFile&&runCatching{source.readBytes().contentEquals(openedRaw)}.getOrDefault(false)
            val suffix=if(rollbackOk)" The quarantined record remains preserved byte-for-byte." else " PSE could not fully restore the quarantine state; preserved copies were left in place where possible."
            showDialog("Gen 1 Bank recovery",(failure.message?:"The quarantined record could not be restored.")+suffix)
            return
        }
        selectedBankFiles.clear()
        Toast.makeText(this,"Restored ${target?.name?:source.name} to the active Gen 1 Bank",Toast.LENGTH_LONG).show()
        showBank()
    }

    private fun showGen1BankQuarantineRecovery(){
        val files=gen1BankQuarantinedFiles()
        if(files.isEmpty()){showDialog("Gen 1 Bank recovery","There are no quarantined Gen 1 Bank records.");return}
        AlertDialog.Builder(this).setTitle("Quarantined Gen 1 records (${files.size})")
            .setItems(files.map{it.name}.toTypedArray()){_,which->
                val source=files[which]
                val opened=runCatching{source.readBytes()}.getOrElse{showDialog("Gen 1 Bank recovery","${source.name} could not be read. It was left unchanged.");return@setItems}
                AlertDialog.Builder(this).setTitle("Restore ${source.name}?")
                    .setMessage("PSE will restore this exact file to the active Gen 1 Bank without overwriting an existing record. If it is still malformed, it will be reported again and safe deposits will remain blocked until it is quarantined again.")
                    .setNegativeButton("Cancel",null)
                    .setPositiveButton("Restore"){_,_->restoreGen1BankQuarantineRecord(source,opened)}.show()
            }.setNegativeButton("Close",null).show()
    }

    private fun requireGen1BankCapacity(current:Int,additional:Int) {
        require(additional>0&&current in 0..GEN1_BANK_CAPACITY&&current<=GEN1_BANK_CAPACITY-additional){"PSE Bank has room for ${GEN1_BANK_CAPACITY-current} more Gen 1 Pokémon, but $additional were selected. Its ${GEN1_BANK_BOX_COUNT} boxes hold ${GEN1_BANK_CAPACITY} Pokémon."}
    }

    private fun bankDisplayBoxCount(total:Int,generation:Int):Int {
        require(total>=0){"Bank entry count cannot be negative."}
        val occupiedBoxes=(total+GEN1_BANK_BOX_CAPACITY-1)/GEN1_BANK_BOX_CAPACITY
        return if(generation==1) maxOf(GEN1_BANK_BOX_COUNT,occupiedBoxes) else maxOf(10,occupiedBoxes)
    }

    private fun resolveSelectedGen1BankFiles():List<File> {
        require(selectedBankFiles.isNotEmpty()){"Select one or more Gen 1 Bank Pokémon first."}
        val selected=selectedBankFiles.map{File(it)}
        require(selected.all{it.isFile}){"One or more selected Gen 1 Bank records no longer exist. Reopen PSE Bank and select the complete batch again."}
        require(selected.all{it.extension.equals("pse1",true)}){"The selection contains a record from another Bank generation. Reopen the Gen 1 Bank and select the batch again."}
        require(selected.all{file->runCatching{parseGen1BankPayload(file.readBytes())}.getOrNull()!=null}){"The selection contains an invalid Gen 1 Bank record. Nothing was moved."}
        return selected
    }

    private fun bankDisplayBoxLabel(boxIndex:Int,boxCount:Int,generation:Int):String =
        if(generation==1&&boxIndex>=GEN1_BANK_BOX_COUNT) "Legacy overflow ${boxIndex-GEN1_BANK_BOX_COUNT+1}"
        else "Bank Box ${boxIndex+1} / ${if(generation==1) GEN1_BANK_BOX_COUNT else boxCount}"

    private fun showBank() {
        val batchDestination=importedFile;val batchDestinationUri=currentSourceUri;val batchDestinationLabel=currentSourceLabel
        phoneBackAction = { showHome() }
        val currentGen = importedFile?.let { generationForSize(it.length().toInt()) }
        val scroll = ScrollView(this).apply { setBackgroundColor(BG) }
        val root = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(dp(16), dp(58), dp(16), dp(28))
            setBackgroundColor(BG)
        }
        scroll.addView(root)
        root.addView(TextView(this).apply { text = "PSE Bank"; textSize = 28f; typeface = Typeface.DEFAULT_BOLD; setTextColor(TEXT) })
        root.addView(TextView(this).apply { text = "Generation-preserved storage • 30 Pokémon per box"; textSize = 14f; setTextColor(MUTED); setPadding(0,4,0,12) })
        addButton(root, "←  Back to PSE") { showHome() }
        addMutedLine(root, "Choose a generation, then move through its Bank Boxes. PSE keeps the original generation record and only converts it when you explicitly transfer forward.")

        val tabsRow = LinearLayout(this).apply { orientation = LinearLayout.HORIZONTAL; gravity = Gravity.CENTER_VERTICAL }
        for (g in 1..9) {
            tabsRow.addView(TextView(this).apply {
                text = "Gen $g"; gravity = Gravity.CENTER; textSize = 13f; typeface = Typeface.DEFAULT_BOLD
                setTextColor(if (bankViewGeneration == g) Color.WHITE else MUTED)
                setBackgroundColor(if (bankViewGeneration == g) Color.rgb(35,125,210) else Color.rgb(28,38,46))
                setPadding(dp(13),dp(12),dp(13),dp(12)); isClickable = true; isFocusable = true
                setOnClickListener { bankViewGeneration = g; bankViewBox = 0; selectedBankFiles.clear(); showBank() }
            }, LinearLayout.LayoutParams(dp(72),dp(46)).apply { setMargins(dp(1),0,dp(1),0) })
        }
        val tabsScroller = HorizontalScrollView(this).apply {
            isHorizontalScrollBarEnabled = false
            addView(tabsRow, FrameLayout.LayoutParams(-2,-2))
        }
        root.addView(tabsScroller, LinearLayout.LayoutParams(-1,-2).apply { topMargin=dp(14); bottomMargin=dp(12) })

        val gen1Inventory = gen1BankInventory()
        val gen1Entries = gen1Inventory.validEntries
        val gen2Inventory=gen2BankInventory()
        val gen2Entries=gen2Inventory.validEntries
        val standardFiles = bankDir().listFiles()?.filter { it.isFile && (it.extension.equals("pk3", true) || it.extension.equals("pk4", true) || it.extension.equals("pk5", true) || it.extension.equals("pk6", true) || it.extension.equals("pk7", true)) }?.sortedBy { it.name } ?: emptyList()
        val standardEntries = standardFiles.mapNotNull { f ->
            val bg = when { f.extension.equals("pk3", true) -> 3; f.extension.equals("pk4", true) -> 4; f.extension.equals("pk5", true) -> 5; f.extension.equals("pk7", true) -> 7; else -> 6 }
            val bytes = runCatching { f.readBytes() }.getOrDefault(ByteArray(0))
            val pkm = when(bg) {
                3 -> if (bytes.size == 80) parsePk3(bytes,0,false) else null
                4 -> if (bytes.size == 136) parsePk4(bytes,false) else null
                5 -> if (bytes.size == 136) parsePk5(bytes,false) else null
                6 -> if (bytes.size == PK6_STORED_SIZE) parsePk6(bytes,0,PK6_STORED_SIZE,false,721) else null
                7 -> if (bytes.size == PK6_STORED_SIZE) parsePk6(bytes,0,PK6_STORED_SIZE,false,807) else null
                else -> null
            }
            if (pkm == null || !pkm.checksumValid) null else Triple(bg,f,pkm)
        }
        val total = when(bankViewGeneration){ 1->gen1Entries.size; 2->gen2Entries.size; 3,4,5,6,7->standardEntries.count{it.first==bankViewGeneration}; else->0 }
        // Gen 1 has exactly ten configured Bank Boxes. If an older build left overflow
        // records behind, keep them visible as recovery pages without treating them as boxes.
        val boxCount = bankDisplayBoxCount(total,bankViewGeneration)
        if (bankViewBox >= boxCount) bankViewBox = boxCount - 1

        addSectionTitle(root, "GEN ${bankViewGeneration} BANK")
        if(bankViewGeneration==1&&gen1Inventory.invalidFiles.isNotEmpty()){
            val count=gen1Inventory.invalidFiles.size
            addMutedLine(root,"PSE preserved $count unreadable or invalid Gen 1 Bank record${if(count==1) "" else "s"} unchanged. Invalid records are hidden from transfers, and new Gen 1 deposits remain blocked until they are quarantined.")
            addButton(root,"Quarantine invalid Gen 1 record${if(count==1) "" else "s"}"){
                val opened=gen1Inventory.invalidFiles.toList()
                AlertDialog.Builder(this).setTitle("Quarantine invalid records?")
                    .setMessage("PSE will move $count unreadable or malformed Gen 1 Bank record${if(count==1) "" else "s"} out of the active Bank without changing their bytes. This makes safe deposits available again. If any move or verification fails, PSE will restore the complete batch where possible.")
                    .setNegativeButton("Cancel",null)
                    .setPositiveButton("Quarantine"){_,_->quarantineInvalidGen1BankRecords(opened)}.show()
            }
        }
        if(bankViewGeneration==1){
            val quarantinedCount=gen1BankQuarantinedFiles().size
            if(quarantinedCount>0)addButton(root,"Review quarantined Gen 1 records ($quarantinedCount)"){showGen1BankQuarantineRecovery()}
        }
        if(bankViewGeneration==2&&gen2Inventory.invalidFiles.isNotEmpty()){
            val count=gen2Inventory.invalidFiles.size
            addMutedLine(root,"PSE preserved $count unreadable or invalid Gen 2 Bank record${if(count==1) "" else "s"} unchanged. Invalid records are hidden from transfers, and new Gen 2 deposits remain blocked until they are quarantined.")
            addButton(root,"Quarantine invalid Gen 2 record${if(count==1) "" else "s"}"){
                confirmGen2BankQuarantine(gen2Inventory.invalidFiles.toList())
            }
        }
        if(bankViewGeneration==2){val quarantinedCount=gen2BankQuarantinedFiles().size;if(quarantinedCount>0)addButton(root,"Review quarantined Gen 2 records ($quarantinedCount)"){showGen2BankQuarantineRecovery()}}
        if(bankViewGeneration==5&&bankMultiSelectMode){bankMultiSelectMode=false;selectedBankFiles.clear()}
        val selectBar=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL;gravity=Gravity.CENTER_VERTICAL}
        val selectToggle=Button(this).apply{text=if(bankMultiSelectMode)"Cancel" else "Multi-select";setAllCaps(false);setOnClickListener{bankMultiSelectMode=!bankMultiSelectMode;selectedBankFiles.clear();showBank()}}
        selectBar.addView(selectToggle,LinearLayout.LayoutParams(0,dp(48),1f))
        if(bankMultiSelectMode){
            selectBar.addView(Button(this).apply{text="Move selected";setAllCaps(false);setOnClickListener{
                val chosen=try {
                    if(bankViewGeneration==1) resolveSelectedGen1BankFiles()
                    else selectedBankFiles.map{File(it)}.also{files->
                        require(files.isNotEmpty()){"Select one or more Pokémon first."}
                        require(files.all{it.isFile}){"One or more selected Bank records no longer exist. Reopen PSE Bank and select the complete batch again."}
                    }
                } catch(e:Exception) { showDialog("Move selected",e.message?:"The selected Bank records could not be validated.");return@setOnClickListener }
                if(chosen.isEmpty()) showDialog("PSE Bank","Select one or more Pokémon first.")
                else if(bankViewGeneration==1 && importedFile?.let{f->val g=generationForSize(f.length().toInt());g==1 || (g==2 && runCatching{detectGen2Profile(f.readBytes())}.getOrNull()!=null) || (g==3 && runCatching{gen3SaveValid(f.readBytes())}.getOrDefault(false)) || g==4 || g==5 || g==6 || g==7}==true) moveSelectedGen1BankPokemon(chosen)
                else if(bankViewGeneration==2 && importedFile?.let{generationForSize(it.length().toInt())}==1){
                    if(batchDestination==null||importedFile?.absolutePath!=batchDestination.absolutePath||currentSourceUri!=batchDestinationUri||currentSourceLabel!=batchDestinationLabel){showDialog("Gen 2 → Gen 1 multi-transfer","The destination identity changed since this Bank selection opened. Reopen PSE Bank. Nothing was changed.");return@setOnClickListener}
                    prepareSelectedGen2BankToGen1(chosen)
                }
                else if(bankViewGeneration==2 && importedFile?.let{generationForSize(it.length().toInt())}==2){
                    if(batchDestination==null||importedFile?.absolutePath!=batchDestination.absolutePath||currentSourceUri!=batchDestinationUri||currentSourceLabel!=batchDestinationLabel){showDialog("Gen 2 Bank multi-withdrawal","The destination identity changed since this Bank selection opened. Reopen PSE Bank. Nothing was changed.");return@setOnClickListener}
                    chooseSelectedGen2BankDestination(chosen)
                }
                else if(bankViewGeneration==2 && importedFile?.let{f->generationForSize(f.length().toInt())==3&&runCatching{gen3SaveValid(f.readBytes())}.getOrDefault(false)}==true){
                    if(batchDestination==null||importedFile?.absolutePath!=batchDestination.absolutePath||currentSourceUri!=batchDestinationUri||currentSourceLabel!=batchDestinationLabel){showDialog("Gen 2 → Gen 3 multi-transfer","The destination identity changed since this Bank selection opened. Reopen PSE Bank. Nothing was changed.");return@setOnClickListener}
                    prepareSelectedGen2BankToGen3(chosen)
                }
                else if(bankViewGeneration==2 && importedFile?.let{generationForSize(it.length().toInt())}==4){
                    if(batchDestination==null||importedFile?.absolutePath!=batchDestination.absolutePath||currentSourceUri!=batchDestinationUri||currentSourceLabel!=batchDestinationLabel){showDialog("Gen 2 → Gen 4 multi-transfer","The destination identity changed since this Bank selection opened. Reopen PSE Bank. Nothing was changed.");return@setOnClickListener}
                    prepareSelectedGen2BankToGen4(chosen)
                }
                else if(bankViewGeneration==2 && importedFile?.let{generationForSize(it.length().toInt())}==5){
                    if(batchDestination==null||importedFile?.absolutePath!=batchDestination.absolutePath||currentSourceUri!=batchDestinationUri||currentSourceLabel!=batchDestinationLabel){showDialog("Gen 2 → Gen 5 multi-transfer","The destination identity changed since this Bank selection opened. Reopen PSE Bank. Nothing was changed.");return@setOnClickListener}
                    prepareSelectedGen2BankToGen5(chosen)
                }
                else if(bankViewGeneration==2 && importedFile?.let{generationForSize(it.length().toInt())}==6){
                    if(batchDestination==null||importedFile?.absolutePath!=batchDestination.absolutePath||currentSourceUri!=batchDestinationUri||currentSourceLabel!=batchDestinationLabel){showDialog("Gen 2 → Gen 6 multi-transfer","The destination identity changed since this Bank selection opened. Reopen PSE Bank. Nothing was changed.");return@setOnClickListener}
                    prepareSelectedGen2BankToGen6(chosen)
                }
                else if(bankViewGeneration==2 && importedFile?.let{generationForSize(it.length().toInt())}==7){
                    if(batchDestination==null||importedFile?.absolutePath!=batchDestination.absolutePath||currentSourceUri!=batchDestinationUri||currentSourceLabel!=batchDestinationLabel){showDialog("Gen 2 → Gen 7 multi-transfer","The destination identity changed since this Bank selection opened. Reopen PSE Bank. Nothing was changed.");return@setOnClickListener}
                    prepareSelectedGen2BankToGen7(chosen)
                }
                else if(bankViewGeneration==3 && importedFile?.let{f->generationForSize(f.length().toInt())==3&&runCatching{gen3SaveValid(f.readBytes())}.getOrDefault(false)}==true){
                    if(batchDestination==null||importedFile?.absolutePath!=batchDestination.absolutePath||currentSourceUri!=batchDestinationUri||currentSourceLabel!=batchDestinationLabel){showDialog("Gen 3 Bank multi-withdrawal","The destination identity changed since this Bank selection opened. Reopen PSE Bank. Nothing was changed.");return@setOnClickListener}
                    chooseSelectedGen3BankDestination(chosen,batchDestination,batchDestinationUri,batchDestinationLabel)
                }
                else if(bankViewGeneration in 6..7 && importedFile?.let{generationForSize(it.length().toInt())}==bankViewGeneration) chooseSelectedStandardBankDestination(chosen,bankViewGeneration)
                else showDialog("Move selected","Load a matching supported save for this Bank generation before moving the selected Pokémon together.")
            }},LinearLayout.LayoutParams(0,dp(48),1f))
        }
        if(bankViewGeneration!=5)root.addView(selectBar,LinearLayout.LayoutParams(-1,-2).apply{bottomMargin=dp(6)})
        else addMutedLine(root,"Open one Gen 5 Bank record to review its exact Gen 4 compatibility and destination before conversion.")
        if (bankMultiSelectMode && bankViewGeneration == 3 && currentGen == 3 && batchDestination != null) {
            fun reviewBankParty(copyOnly: Boolean) {
                if (importedFile?.absolutePath != batchDestination.absolutePath ||
                    currentSourceUri != batchDestinationUri || currentSourceLabel != batchDestinationLabel) {
                    showDialog("Bank to Party", "The loaded destination changed. Reopen PSE Bank.")
                } else {
                    prepareGen3BankPartyWithdrawal(
                        selectedBankFiles.map { File(it) },
                        batchDestination, batchDestinationUri, batchDestinationLabel, copyOnly
                    )
                }
            }
            addButton(root, "👥  Withdraw selected to Gen 3 Party") { reviewBankParty(false) }
            addButton(root, "🛡  Copy selected to Gen 3 Party") { reviewBankParty(true) }
        }
        val nav = LinearLayout(this).apply { orientation=LinearLayout.HORIZONTAL; gravity=Gravity.CENTER_VERTICAL }
        fun bankNavButton(label:String, enabled:Boolean, click:()->Unit): TextView = TextView(this).apply {
            text=label; gravity=Gravity.CENTER; textSize=28f; typeface=Typeface.DEFAULT_BOLD
            setTextColor(if(enabled) TEXT else Color.rgb(70,80,88))
            setBackgroundColor(Color.rgb(29,54,68)); isClickable=enabled; isFocusable=enabled
            if(enabled) setOnClickListener { click() }
        }
        nav.addView(bankNavButton("‹", bankViewBox>0) { bankViewBox--; showBank() }, LinearLayout.LayoutParams(dp(58),dp(58)).apply { setMargins(0,0,dp(6),0) })
        nav.addView(TextView(this).apply {
            text=bankDisplayBoxLabel(bankViewBox,boxCount,bankViewGeneration); gravity=Gravity.CENTER; textSize=17f; typeface=Typeface.DEFAULT_BOLD; setTextColor(TEXT)
            setBackgroundColor(Color.rgb(29,54,68))
        },LinearLayout.LayoutParams(0,dp(58),1f))
        nav.addView(bankNavButton("›", bankViewBox+1<boxCount) { bankViewBox++; showBank() }, LinearLayout.LayoutParams(dp(58),dp(58)).apply { setMargins(dp(6),0,0,0) })
        root.addView(nav,LinearLayout.LayoutParams(-1,-2))

        val grid = GridLayout(this).apply { columnCount=6; rowCount=5; alignmentMode=GridLayout.ALIGN_BOUNDS; useDefaultMargins=false }
        val start=bankViewBox*30
        for(local in 0 until 30){
            val idx=start+local
            when(bankViewGeneration){
                1 -> grid.addView(gen1BankGridCell(local,gen1Entries.getOrNull(idx)))
                2 -> grid.addView(gen2BankGridCell(local,gen2Entries.getOrNull(idx)))
                3,4,5,6,7 -> {
                    val e=standardEntries.filter{it.first==bankViewGeneration}.getOrNull(idx)
                    grid.addView(bankGridCell(local,e?.let{Pair(it.second,it.third)}))
                }
                else -> grid.addView(bankGridCell(local,null))
            }
        }
        root.addView(grid,LinearLayout.LayoutParams(-1,-2))
        val occupied=(total-start).coerceIn(0,30)
        addMutedLine(root,"$occupied / 30 occupied • $total total preserved Gen ${bankViewGeneration} Pokémon${if(currentGen==bankViewGeneration) " • current save Gen $currentGen" else ""}.")
        if(bankViewGeneration in 8..9) addMutedLine(root,"Gen ${bankViewGeneration} storage has 30-slot Bank Boxes ready. Deposits will appear here as this generation's save engine is enabled.")
        when {
            bankViewGeneration==1&&total>GEN1_BANK_CAPACITY -> addMutedLine(root,"Legacy Gen 1 overflow is visible for recovery. New Gen 1 deposits remain blocked until fewer than ${GEN1_BANK_CAPACITY} records remain in the configured ${GEN1_BANK_BOX_COUNT} Bank Boxes.")
            bankViewGeneration==1&&total==GEN1_BANK_CAPACITY -> addMutedLine(root,"Gen 1 Bank is full: all ${GEN1_BANK_BOX_COUNT} Bank Boxes contain ${GEN1_BANK_CAPACITY} Pokémon. Withdraw or delete a Pokémon before depositing another.")
            bankViewGeneration!=1&&total>=boxCount*30 -> addMutedLine(root,"Another Bank Box will be created automatically when this generation needs more storage.")
        }

        val shell=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setBackgroundColor(BG)}
        shell.addView(scroll,LinearLayout.LayoutParams(-1,0,1f));shell.addView(buildBottomNav("bank"),LinearLayout.LayoutParams(-1,-2));setContentView(shell)
    }

    private fun bankGridCell(slot: Int, pair: Pair<File, PokemonEntry>?): LinearLayout {
        val cellWidth = ((resources.displayMetrics.widthPixels - dp(44)) / 6).coerceAtLeast(dp(50))
        return LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL; gravity = Gravity.CENTER; setPadding(dp(2),dp(4),dp(2),dp(4))
            setBackgroundColor(if (pair == null) Color.rgb(27,27,27) else if(bankMultiSelectMode && pair!=null && selectedBankFiles.contains(pair.first.absolutePath)) Color.rgb(25,105,145) else CARD)
            layoutParams = GridLayout.LayoutParams().apply { width=cellWidth; height=dp(82); setMargins(dp(1),dp(1),dp(1),dp(1)) }
            if (pair != null) {
                val (file,p) = pair; isClickable=true; isFocusable=true
                setOnClickListener {
                    if(bankMultiSelectMode){
                        if(!selectedBankFiles.add(file.absolutePath)) selectedBankFiles.remove(file.absolutePath)
                        showBank()
                    } else when { file.extension.equals("pk3",true) -> showGen3BankEntry(file,p); file.extension.equals("pk4",true) -> showGen4BankEntry(file,p); file.extension.equals("pk5",true) -> showGen5BankEntry(file,p); file.extension.equals("pk6",true) -> showGen6BankEntry(file,p); file.extension.equals("pk7",true) -> showGen7BankEntry(file,p); else -> chooseWithdrawDestination(file,p) }
                }
                val sprite=ImageView(this@MainActivity).apply { scaleType=ImageView.ScaleType.FIT_CENTER; contentDescription=p.nickname }
                addView(sprite, LinearLayout.LayoutParams(dp(52),dp(52))); loadPokemonSprite(sprite,p.species,p.shiny)
            } else addView(TextView(this@MainActivity).apply { text="○"; textSize=24f; gravity=Gravity.CENTER; setTextColor(Color.rgb(80,80,80)) }, LinearLayout.LayoutParams(dp(52),dp(52)))
            addView(TextView(this@MainActivity).apply { text=(slot+1).toString(); textSize=10f; gravity=Gravity.CENTER; setTextColor(if(pair==null) Color.rgb(100,100,100) else MUTED) })
        }
    }

    private fun canBankTransfer(sourceGen: Int, targetGen: Int, species: Int): Boolean {
        if (sourceGen == targetGen && sourceGen in 6..7) return true
        return false
    }

    private fun bankTransferBlockReason(sourceGen: Int, targetGen: Int, species: Int): String = when {
        targetGen !in 6..7 -> "The loaded destination save is Generation $targetGen. PSE Bank conversion currently supports Gen 6 and Gen 7 box formats; earlier-generation conversion will be added as those save engines are implemented."
        sourceGen in 6..7&&targetGen in 6..7 -> "Use the reviewed Gen $sourceGen PSE Bank entry flow for this adjacent-generation conversion."
        else -> "PSE cannot safely convert this Gen $sourceGen Bank entry into the loaded Gen $targetGen save."
    }

    private fun convertBankPokemonForGeneration(raw: ByteArray, sourceGen: Int, targetGen: Int): ByteArray {
        if (sourceGen == targetGen) return raw.copyOf()
        throw IllegalArgumentException(bankTransferBlockReason(sourceGen, targetGen, 0))
    }

    private fun chooseWithdrawDestination(bankFile: File, p: PokemonEntry) {
        val file = importedFile ?: run {
            showDialog("Withdraw", "Import the destination save first.")
            return
        }
        val data = try { file.readBytes() } catch (_: Exception) { ByteArray(0) }
        val currentGen = generationForSize(data.size)
        val bankGen = if (bankFile.extension.equals("pk7", true)) 7 else 6
        if (!canBankTransfer(bankGen, currentGen, p.species)) {
            showDialog("Withdraw blocked", bankTransferBlockReason(bankGen, currentGen, p.species))
            return
        }
        val (boxOffset, slotCount, maxSpecies) = boxStorageInfo(data) ?: run {
            showDialog("Withdraw", "The current save does not have supported PC box storage.")
            return
        }
        val firstEmpty = findFirstEmptyBoxSlot(data, boxOffset, slotCount, maxSpecies)
        if (firstEmpty == null) {
            showDialog("Withdraw", "No empty PC box slot was found.")
            return
        }

        val labels = ArrayList<String>()
        labels.add("First empty slot (Box ${firstEmpty / 30 + 1} • Slot ${firstEmpty % 30 + 1})")
        for (box in 0 until slotCount / 30) {
            val emptyCount = countEmptySlotsInBox(data, boxOffset, box, maxSpecies)
            labels.add("Box ${box + 1} • $emptyCount empty slot${if (emptyCount == 1) "" else "s"}")
        }

        AlertDialog.Builder(this)
            .setTitle("Withdraw ${p.nickname.ifBlank { "Pokémon" }} to…")
            .setItems(labels.toTypedArray()) { _, which ->
                if (which == 0) withdrawFromBank(bankFile, p, firstEmpty)
                else showWithdrawSlotGrid(bankFile, p, which - 1)
            }
            .setNegativeButton("Cancel", null)
            .show()
    }

    private fun showWithdrawSlotGrid(bankFile: File, p: PokemonEntry, boxIndex: Int) {
        val file = importedFile ?: return
        val data = try { file.readBytes() } catch (_: Exception) { ByteArray(0) }
        val currentGen = generationForSize(data.size)
        val bankGen = if (bankFile.extension.equals("pk7", true)) 7 else 6
        if (!canBankTransfer(bankGen, currentGen, p.species)) { showDialog("Withdraw blocked", bankTransferBlockReason(bankGen, currentGen, p.species)); return }
        val (boxOffset, slotCount, maxSpecies) = boxStorageInfo(data) ?: return
        if (boxIndex !in 0 until (slotCount / 30)) return

        val wrapper = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(dp(12), dp(8), dp(12), dp(8))
        }
        wrapper.addView(TextView(this).apply {
            text = "Tap an empty slot. Occupied slots are disabled."
            textSize = 14f
            setTextColor(MUTED)
            setPadding(0, 0, 0, dp(8))
        })

        val grid = GridLayout(this).apply {
            columnCount = 6
            rowCount = 5
            alignmentMode = GridLayout.ALIGN_BOUNDS
            useDefaultMargins = false
        }
        val cellWidth = ((resources.displayMetrics.widthPixels - dp(90)) / 6).coerceAtLeast(dp(42))
        var emptyCount = 0
        for (slot in 0 until 30) {
            val global = boxIndex * 30 + slot
            val offset = boxOffset + global * PK6_STORED_SIZE
            val occupied = parsePk6(data, offset, PK6_STORED_SIZE, party = false, maxSpecies = maxSpecies) != null
            if (!occupied) emptyCount++
            val cell = TextView(this).apply {
                text = if (occupied) "●\n${slot + 1}" else "○\n${slot + 1}"
                textSize = 13f
                gravity = Gravity.CENTER
                setTextColor(if (occupied) Color.rgb(105, 105, 105) else TEXT)
                setBackgroundColor(if (occupied) Color.rgb(35, 35, 35) else Color.rgb(55, 55, 55))
                isEnabled = !occupied
                if (!occupied) setOnClickListener { withdrawFromBank(bankFile, p, global) }
            }
            grid.addView(cell, GridLayout.LayoutParams().apply {
                width = cellWidth
                height = dp(58)
                setMargins(dp(2), dp(2), dp(2), dp(2))
            })
        }
        wrapper.addView(grid)
        wrapper.addView(TextView(this).apply {
            text = "$emptyCount empty slot${if (emptyCount == 1) "" else "s"} in Box ${boxIndex + 1}"
            textSize = 13f
            setTextColor(MUTED)
            setPadding(0, dp(8), 0, 0)
        })

        AlertDialog.Builder(this)
            .setTitle("Box ${boxIndex + 1} • choose slot")
            .setView(wrapper)
            .setNegativeButton("Back") { _, _ -> chooseWithdrawDestination(bankFile, p) }
            .setNeutralButton("Cancel", null)
            .show()
    }

    private fun findFirstEmptyBoxSlot(data: ByteArray, boxOffset: Int, slotCount: Int, maxSpecies: Int): Int? {
        for (i in 0 until slotCount) {
            val offset = boxOffset + i * PK6_STORED_SIZE
            if (offset + PK6_STORED_SIZE <= data.size && parsePk6(data, offset, PK6_STORED_SIZE, party = false, maxSpecies = maxSpecies) == null) return i
        }
        return null
    }

    private fun countEmptySlotsInBox(data: ByteArray, boxOffset: Int, boxIndex: Int, maxSpecies: Int): Int {
        var count = 0
        for (slot in 0 until 30) {
            val offset = boxOffset + (boxIndex * 30 + slot) * PK6_STORED_SIZE
            if (offset + PK6_STORED_SIZE <= data.size && parsePk6(data, offset, PK6_STORED_SIZE, party = false, maxSpecies = maxSpecies) == null) count++
        }
        return count
    }

    private fun confirmDepositToBank(location: String, p: PokemonEntry) {
        android.app.AlertDialog.Builder(this)
            .setTitle("Move to PSE Bank?")
            .setMessage("${p.nickname.ifBlank { "Species #${p.species}" }} will be removed from $location and stored in PSE Bank in the working copy. Save & Replace creates the safety backup later.")
            .setNegativeButton("Cancel", null)
            .setPositiveButton("Move") { _, _ -> depositToBank(location, p) }
            .show()
    }

    private fun depositToBank(location: String, p: PokemonEntry) {
        val match = Regex("Box (\\d+) • Slot (\\d+)").matchEntire(location) ?: return
        val box = match.groupValues[1].toInt() - 1
        val slot = match.groupValues[2].toInt() - 1
        val file = importedFile ?: return
        val original = try { file.readBytes() } catch (e: Exception) {
            Toast.makeText(this, "Could not read save: ${e.message}", Toast.LENGTH_LONG).show(); return
        }
        val generation = generationForSize(original.size)
        val (boxOffset, slotCount, maxSpecies) = boxStorageInfo(original) ?: return
        val global = box * 30 + slot
        if (global !in 0 until slotCount) return
        val offset = boxOffset + global * PK6_STORED_SIZE
        if (offset + PK6_STORED_SIZE > original.size) return
        val raw = original.copyOfRange(offset, offset + PK6_STORED_SIZE)
        val parsed = parsePk6(raw, 0, PK6_STORED_SIZE, false, maxSpecies)
        if (parsed == null || !parsed.checksumValid) {
            showDialog("PSE Bank", "This Pokémon did not pass its stored-Pokémon checksum, so it was not moved.")
            return
        }
        var bankFile: File? = null
        try {
            val ext = if (generation == 7) "pk7" else "pk6"
            bankFile = File(bankDir(), "${System.currentTimeMillis()}_${p.species}.$ext")
            bankFile.writeBytes(raw)
            if (!bankFile.readBytes().contentEquals(raw)) error("Bank entry verification failed.")
            val work = original.copyOf()
            java.util.Arrays.fill(work, offset, offset + PK6_STORED_SIZE, 0.toByte())
            refreshBoxChecksum(work)
            file.writeBytes(work)
            val verify = file.readBytes()
            val slotCleared = verify.copyOfRange(offset, offset + PK6_STORED_SIZE).all { it == 0.toByte() }
            if (!slotCleared || !bankFile.readBytes().contentEquals(raw)) error("Post-write verification failed.")
            Toast.makeText(this, "Moved to PSE Bank and verified", Toast.LENGTH_LONG).show()
            showBank()
        } catch (e: Exception) {
            try { file.writeBytes(original) } catch (_: Exception) { }
            try { bankFile?.delete() } catch (_: Exception) { }
            showDialog("Bank move failed", (e.message ?: "Unknown error") + " The original working copy was restored.")
        }
    }

    private fun withdrawFromBank(bankFile: File, p: PokemonEntry, target: Int) {
        val file=importedFile ?: return
        val original=try { file.readBytes() } catch (_:Exception) { ByteArray(0) }
        val currentGen = generationForSize(original.size)
        val bankGen = if (bankFile.extension.equals("pk7", true)) 7 else 6
        if (!canBankTransfer(bankGen, currentGen, p.species)) {
            showDialog("Withdraw blocked", bankTransferBlockReason(bankGen, currentGen, p.species))
            return
        }
        val (boxOffset, slotCount, maxSpecies)=boxStorageInfo(original) ?: return
        if(target !in 0 until slotCount) return
        val offset=boxOffset+target*PK6_STORED_SIZE
        if (parsePk6(original, offset, PK6_STORED_SIZE, party = false, maxSpecies = maxSpecies) != null) {
            showDialog("Withdraw", "That destination slot is no longer empty. Nothing was overwritten.")
            return
        }
        val raw=try { bankFile.readBytes() } catch (_:Exception) { ByteArray(0) }
        val sourceMaxSpecies = if (bankGen == 7) 807 else 721
        val bankPokemon = if (raw.size == PK6_STORED_SIZE) parsePk6(raw, 0, PK6_STORED_SIZE, false, sourceMaxSpecies) else null
        if(bankPokemon == null || !bankPokemon.checksumValid){ showDialog("Withdraw", "This Bank entry is not a valid PK$bankGen stored record."); return }
        val targetRaw = try { convertBankPokemonForGeneration(raw, bankGen, currentGen) } catch (e: Exception) {
            showDialog("Transfer conversion failed", e.message ?: "PSE could not convert this Bank Pokémon for the destination generation.")
            return
        }
        try {
            val work = original.copyOf()
            targetRaw.copyInto(work,offset)
            refreshBoxChecksum(work)
            file.writeBytes(work)
            val verifyData = file.readBytes()
            val actual = verifyData.copyOfRange(offset, offset + PK6_STORED_SIZE)
            val verifyPokemon = parsePk6(actual, 0, PK6_STORED_SIZE, false, maxSpecies)
            if (!actual.contentEquals(targetRaw) || verifyPokemon == null || !verifyPokemon.checksumValid) {
                file.writeBytes(original)
                showDialog("Withdraw verification failed", "PSE restored the original working copy because the withdrawn Pokémon did not verify.")
                return
            }
            if (!bankFile.delete()) {
                file.writeBytes(original)
                showDialog("Withdraw stopped", "PSE could not remove the verified Bank entry, so the save was restored to avoid creating an unintended duplicate.")
                return
            }
            val box=target/30+1; val slot=target%30+1
            val transferNote = if (bankGen != currentGen) " (Gen $bankGen → Gen $currentGen)" else ""
            Toast.makeText(this,"${p.nickname.ifBlank{"Pokémon"}} moved to Box $box • Slot $slot$transferNote and verified",Toast.LENGTH_LONG).show()
            showPokemonViewer("boxes",box-1)
        } catch(e:Exception){
            try { file.writeBytes(original) } catch (_:Exception) { }
            showDialog("Withdraw failed", (e.message ?: "Unknown error") + " The original working copy was restored.")
        }
    }

    private fun createEditBackup(file: File) {
        // v0.22.5: edits only change PSE's working copy.
        // Do not create an EDIT backup for every Pokémon edit; Save & Replace creates the single rollback backup.
