    private fun updateGen6BoxChecksum(data: ByteArray) {
        val (blockId, boxOffset, boxLength) = when (data.size) {
            SIZE_G6_XY -> Triple(53, BOX_OFFSET_XY, 0x34AD0)
            SIZE_G6_ORAS -> Triple(56, BOX_OFFSET_ORAS, 0x34AD0)
            else -> return
        }
        val crc = crc16Ccitt(data, boxOffset, boxLength)
        val metadata = data.size - 0x200
        val checksumOffset = metadata + 0x14 + (blockId * 8) + 6
        if (checksumOffset + 1 < data.size) {
            data[checksumOffset] = (crc and 0xFF).toByte()
            data[checksumOffset + 1] = ((crc ushr 8) and 0xFF).toByte()
        }
    }


    private fun crc16CcittGen7(data: ByteArray, offset: Int, length: Int): Int {
        require(offset >= 0 && length >= 0 && offset + length <= data.size) {
            "Invalid Gen 7 CRC range."
        }

        // Sun/Moon and Ultra Sun/Ultra Moon do NOT use the Gen 6 CCITT
        // save-block CRC. Gen 7 uses the reversed Modbus polynomial 0xA001,
        // starts at 0xFFFF, then inverts the 16-bit result.
        //
        // Verified against an untouched 0x6CC00 Ultra Moon save:
        // block 0  -> stored 0x695C
        // block 1  -> stored 0xA5AF
        // block 2  -> stored 0xAFBC
        // block 14 -> stored 0xA8AB
        var crc = 0xFFFF
        val end = offset + length
        for (i in offset until end) {
            crc = crc xor (data[i].toInt() and 0xFF)
            repeat(8) {
                crc = if ((crc and 1) != 0)
                    ((crc ushr 1) xor 0xA001) and 0xFFFF
                else
                    (crc ushr 1) and 0xFFFF
            }
        }
        return crc xor 0xFFFF
    }

    private fun gen7ChecksumOffset(data: ByteArray, blockId: Int): Int {
        val metadata = data.size - 0x200
        return metadata + 0x14 + (blockId * 8) + 6
    }

    private fun readU16LEAt(data: ByteArray, offset: Int): Int {
        if (offset < 0 || offset + 1 >= data.size) return -1
        return (data[offset].toInt() and 0xFF) or
            ((data[offset + 1].toInt() and 0xFF) shl 8)
    }

    private fun gen7BlockInfo(data: ByteArray, blockId: Int): Pair<Int, Int>? {
        return when (data.size) {
            SIZE_G7_SM -> when (blockId) {
                0 -> 0x00000 to 0x00E28
                3 -> 0x01200 to 0x000C0
                4 -> 0x01400 to 0x0061C
                6 -> 0x02A00 to 0x00F78
                9 -> 0x03C00 to 0x00200
                13 -> 0x04800 to 0x005E6
                14 -> 0x04E00 to 0x36600
                else -> null
            }
            SIZE_G7_USUM -> when (blockId) {
                0 -> 0x00000 to 0x00E28
                3 -> 0x01400 to 0x000C0
                4 -> 0x01600 to 0x0061C
                6 -> 0x02C00 to 0x00F78
                9 -> 0x04400 to 0x001FC
                13 -> 0x04C00 to 0x005E6
                14 -> 0x05200 to 0x36600
                else -> null
            }
            else -> null
        }
    }

    private fun gen7BlockChecksumValid(data: ByteArray, blockId: Int): Boolean {
        val info = gen7BlockInfo(data, blockId) ?: return false
        val checksumOffset = gen7ChecksumOffset(data, blockId)
        val stored = readU16LEAt(data, checksumOffset)
        if (stored < 0) return false
        val actual = crc16CcittGen7(data, info.first, info.second)
        return stored == actual
    }

    private fun updateGen7SaveBlockChecksum(
        data: ByteArray,
        blockId: Int,
        offset: Int,
        length: Int
    ) {
        require(
            data.size == SIZE_G7_SM || data.size == SIZE_G7_USUM
        ) { "Not a supported Gen 7 save." }
        require(offset >= 0 && length > 0 && offset + length <= data.size) {
            "Invalid Gen 7 save-block range."
        }

        // Verify that PSE's metadata layout matches the untouched file before
        // changing the checksum. Block 0 is never edited by current PSE features.
        require(gen7BlockChecksumValid(data, 0)) {
            "Gen 7 checksum metadata could not be validated with the native Gen 7 CRC. PSE stopped the write to protect the save."
        }

        val crc = crc16CcittGen7(data, offset, length)
        val checksumOffset = gen7ChecksumOffset(data, blockId)
        require(checksumOffset >= 0 && checksumOffset + 1 < data.size) {
            "Invalid Gen 7 checksum location."
        }
        data[checksumOffset] = (crc and 0xFF).toByte()
        data[checksumOffset + 1] = ((crc ushr 8) and 0xFF).toByte()

        val known = gen7BlockInfo(data, blockId)
        if (known != null && known.first == offset && known.second == length) {
            require(gen7BlockChecksumValid(data, blockId)) {
                "Gen 7 block $blockId checksum did not verify after rebuilding."
            }
        }
    }

    private fun validateGen7CoreChecksums(data: ByteArray): Pair<Boolean, String> {
        if (data.size != SIZE_G7_SM && data.size != SIZE_G7_USUM)
            return false to "Not a supported Gen 7 save."

        val important = intArrayOf(0, 3, 4, 6, 9, 13, 14)
        val bad = important.filterNot { gen7BlockChecksumValid(data, it) }
        return if (bad.isEmpty()) {
            true to "Gen 7 core save-block checksums valid."
        } else {
            false to "Invalid Gen 7 save-block checksum(s): ${bad.joinToString(", ")}"
        }
    }


