    private fun checkGen5PokemonLegality(location:String,p:PokemonEntry){
        val findings=mutableListOf<LegalityFinding>()
        fun error(t:String)=findings.add(LegalityFinding(2,t))
        fun warn(t:String)=findings.add(LegalityFinding(1,t))
        if(!p.checksumValid)error("PK5 checksum is invalid.")
        if(p.species !in 1..649)error("Species #${p.species} is not available in Generation 5.")
        if(p.abilityNumber !in setOf(1,2,4))error("Ability slot ${p.abilityNumber} is invalid.")
        if(p.ability !in 1..164)error("Ability #${p.ability} is outside the Generation 5 range.")
        if(p.nature !in 0..24)error("Nature ID ${p.nature} is invalid.")
        if(p.ivs.any{it !in 0..31})error("One or more IVs are outside 0–31.")
        if(p.evs.any{it !in 0..255})error("One or more EVs are outside the stored Generation 5 range.")
        if(p.evs.sum()>510)error("EV total ${p.evs.sum()} exceeds 510. PSE will not auto-reduce EVs because choosing which stats to lower would be ambiguous.")
        val shinyValue=p.tid xor p.sid xor (p.pid.toInt() and 0xFFFF) xor ((p.pid.toInt() ushr 16) and 0xFFFF)
        if((shinyValue<8)!=p.shiny)error("Shiny state does not match the Gen 5 PID/TID/SID rule.")
        if(p.metLevel !in 0..100)error("Met level ${p.metLevel} is outside the Gen 5 stored range.")
        if(p.ball !in 1..25)error("Poké Ball ID ${p.ball} is outside the Generation 5 range.")
        val nativeGen5Origin=p.originGame in 20..23
        if(!nativeGen5Origin && p.originGame !in 1..19)error("Origin game #${p.originGame} is not a recognized Generation 5-or-earlier origin value.")
        if(nativeGen5Origin){
            val bw=p.originGame==20 || p.originGame==21
            val nativeLocationOk=if(bw) p.metLocation in 1..116 else (p.metLocation in 1..153 || p.metLocation==30015)
            if(!nativeLocationOk)error("Met location #${p.metLocation} is not defined for ${gen5OriginGameName(p.originGame)}.")
            if(p.eggLocation!=0){
                val eggLocationOk=if(bw) p.eggLocation in 1..116 else (p.eggLocation in 1..153 || p.eggLocation==30015 || p.eggLocation in 60001..65535)
                if(!eggLocationOk)error("Egg location #${p.eggLocation} is not defined for ${gen5OriginGameName(p.originGame)}.")
            }
        }else if(p.metLocation !in 30001..30008)error("A Pokémon transferred from an earlier generation should use a Generation 5 transfer-region met location; found #${p.metLocation}.")
        // Exact native encounter table: B2W2 Route 19 (PK5 location 124).
        // Evolved species are accepted through their wild ancestor because PK5 met data is retained after evolution.
        if(p.originGame in 22..23){
            // Major B2W2 cave/dungeon wild-encounter locations. PK5 preserves the
            // location but not enough sub-area/method detail to safely choose a single
            // room/table, so these ranges are conservative unions across legitimate
            // wild encounter methods for that location.
            val majorAreaRange:IntRange?=when(p.metLocation){
                35 -> 18..65  // Relic Castle
                37 -> 24..31  // Chargestone Cave
                38 -> 54..80  // Twist Mountain
                39 -> 55..70  // Dragonspiral Tower
                53 -> 10..65  // Wellspring Cave
                54 -> 27..65  // Mistralton Cave
                56 -> 47..58  // Celestial Tower
                61 -> 45..70  // Giant Chasm
                129 -> 14..70 // Castelia Sewers
                132 -> 32..65 // Reversal Mountain
                134 -> 36..70 // Victory Road B2W2
                136 -> 16..65 // Relic Passage
                137 -> 54..65 // Clay Tunnel
                141 -> 34..70 // Seaside Cave
                149 -> 55..65 // Underground Ruins
                150 -> 65..65 // Rock Peak Chamber
                151 -> 65..65 // Iceberg Chamber
                152 -> 65..65 // Iron Chamber
                else -> null
            }
            if(majorAreaRange!=null && p.metLevel !in majorAreaRange)
                error("Met level ${p.metLevel} is outside the conservative certified Black 2/White 2 encounter-level union for met location #${p.metLocation} (${majorAreaRange.first}–${majorAreaRange.last}).")
        }

        if(p.originGame in 22..23){
            // All numbered Unova routes used by B2W2 are covered here.  The PK5 stores
            // the met location but not grass/surf/fishing method, so these are deliberately
            // conservative unions of the certified encounter-level ranges for each route.
            // Route 10 is programmed in the Gen V location table but has no B2W2 encounters.
            val numberedRouteRange:IntRange?=when(p.metLocation){
                14 -> 40..70 // Route 1
                15 -> 40..70 // Route 2
                16 -> 40..70 // Route 3
                17 -> 5..70  // Route 4, including Surf/Super Rod
                18 -> 21..26 // Route 5
                19 -> 23..70 // Route 6, including fishing
                20 -> 30..36 // Route 7
                21 -> 45..60 // Route 8
                22 -> 36..40 // Route 9
                23 -> 0..0   // Route 10 has no native B2W2 encounter table
                24 -> 35..70 // Route 11
                25 -> 36..42 // Route 12
                26 -> 34..70 // Route 13
                27 -> 34..70 // Route 14
                28 -> 55..60 // Route 15
                29 -> 21..26 // Route 16
                30 -> 45..60 // Route 17
                31 -> 45..70 // Route 18
                124 -> 2..60 // Route 19, grass + water/fishing union
                125 -> 2..60 // Route 20, grass + water/fishing union
                126 -> 30..70 // Route 21
                127 -> 15..60 // Route 22, grass + water/fishing union
                128 -> 40..70 // Route 23, grass + water/fishing + special union
                else -> null
            }
            if(numberedRouteRange!=null){
                val routeNo=when(p.metLocation){in 14..31->p.metLocation-13;124->19;125->20;126->21;127->22;else->23}
                if(p.metLocation==23)error("Route 10 has no native wild Pokémon encounters in Black 2/White 2.")
                else if(p.metLevel !in numberedRouteRange)error("Met level ${p.metLevel} is outside the certified Black 2/White 2 Route $routeNo encounter-level union (${numberedRouteRange.first}–${numberedRouteRange.last}).")
            }
        }

        if(p.originGame in 22..23){
            val exactEncounter:Pair<Set<Int>,IntRange>?=when(p.metLocation){
                124 -> setOf(504,505,509,510) to (2..4) // Route 19
                125 -> setOf(504,505,505,509,510,519,520,521,540,541,542,191,192) to (2..4) // Route 20 early grass
                130 -> setOf(504,505,506,507,508,519,520,521,179,180,181,298,183,184,54,55,447,448) to (4..7) // Floccesy Ranch
                131 -> setOf(81,82,462,239,125,466,240,126,467,504,505,519,520,521,109,110,58,59) to (10..14) // Virbank Complex grass/dark grass
                else -> null
            }
            if(exactEncounter!=null){
                val areaName=when(p.metLocation){124->"Route 19";125->"Route 20";130->"Floccesy Ranch";else->"Virbank Complex"}
                val family=exactEncounter.first
                val levels=exactEncounter.second
                if(p.species !in family)error("Species #${p.species} does not belong to a certified wild Pokémon family for $areaName in Black 2/White 2.")
                else if(p.metLevel !in levels)error("Met level ${p.metLevel} does not match the certified $areaName Black 2/White 2 wild encounter range (${levels.first}–${levels.last}).")
            }
        }
        val loading=AlertDialog.Builder(this).setTitle("Gen 5 deep legality check…").setMessage("Checking Generation 5 ability slots, moves, PP and growth data…").setCancelable(false).create();loading.show()
        loadDeepLegalityDataForGenerationAsync(p,5){deep->
            loading.dismiss()
            var replacement:Pair<Int,Int>?=null
            if(deep.onlineOk){
                val expected=deep.abilitySlots[p.ability]
                if(deep.abilitySlots.isNotEmpty() && expected==null){
                    error("Ability #${p.ability} is not available to this species.")
                    replacement=deep.abilitySlots.entries.sortedWith(compareBy<Map.Entry<Int,Int>>{it.value}.thenBy{it.key}).firstOrNull()?.let{it.key to it.value}
                }else if(expected!=null && expected!=p.abilityNumber){
                    error("Ability #${p.ability} belongs to slot $expected, but this PK5 stores slot ${p.abilityNumber}.")
                    replacement=p.ability to expected
                }
                p.moves.forEachIndexed{i,m->if(m==0 && p.movePP[i]!=0)error("Move ${i+1} is empty but still stores ${p.movePP[i]} PP.") else if(m!=0 && deep.learnableMoves.isNotEmpty() && m !in deep.learnableMoves)error("Move ${i+1} (#$m) is not available to this species in Generation 5 or an earlier compatible game.")}
                p.moves.forEachIndexed{i,m->if(m!=0){val base=deep.moveBasePp[m];if(base!=null && p.movePP[i]>base+(base*3/5))error("Move ${i+1} (#$m) has PP above its maximum.")}}
                deep.growthLevel?.let{lv->
                    if(p.level!=null && p.level!=lv)error("Party level ${p.level} does not match level $lv implied by EXP.")
                    if(p.metLevel>lv)error("Met level ${p.metLevel} is higher than level $lv implied by current EXP.")
                }
            }else warn("Online Generation 5 species data could not be loaded; structural checks still ran.")
            val errors=findings.filter{it.severity==2};val warnings=findings.filter{it.severity==1}
            val body=buildString{
                append(if(errors.isNotEmpty())"❌ ILLEGAL" else if(warnings.isNotEmpty())"⚠️ PASSED WITH WARNINGS" else "✅ PASSED DEEP CHECKS")
                append("\n\n${p.nickname.ifBlank{"Species #${p.species}"}} • $location\nPK5 • Species #${p.species}\nOrigin: ${gen5OriginGameName(p.originGame)} • Met Lv. ${p.metLevel} • Ball #${p.ball}\n")
                if(errors.isNotEmpty()){append("\nProblems\n");errors.forEach{append("• ${it.text}\n")}}
                if(warnings.isNotEmpty()){append("\nWarnings\n");warnings.forEach{append("• ${it.text}\n")}}
                append("\nChecked as Generation 5\n• PK5 checksum and field ranges\n• shiny PID/TID/SID relationship\n• species ability + exact ability slot\n• move learnability and PP limits\n• EXP / Party level consistency\n• origin-game/location compatibility\n• met-level / current-EXP consistency\n• ball and egg-location metadata sanity\n• exact species-family + met-level encounter table where certified\n• all B2W2 numbered-route location + encounter-level coverage\n• major B2W2 cave/dungeon location + encounter-level coverage")
            }
            val b=AlertDialog.Builder(this).setTitle("Gen 5 Deep Legality Report").setMessage(body).setPositiveButton("OK",null)
            val global=boxedLocationToGlobalIndex(location)
            val fixedMoves=p.moves.copyOf();val fixedPp=p.movePP.copyOf();var moveFixes=0;var ppFixes=0;var emptyPpFixes=0
            p.moves.forEachIndexed{i,m->if(m==0 && fixedPp[i]!=0){fixedPp[i]=0;emptyPpFixes++}}
            if(deep.onlineOk){
                p.moves.forEachIndexed{i,m->
                    if(m!=0 && deep.learnableMoves.isNotEmpty() && m !in deep.learnableMoves){fixedMoves[i]=0;fixedPp[i]=0;moveFixes++}
                    else if(m!=0){deep.moveBasePp[m]?.let{base->val max=base+(base*3/5);if(fixedPp[i]>max){fixedPp[i]=max;ppFixes++}}}
                }
            }
            // Exact certified encounter repair: only offer a deterministic correction when the
            // species family/location table is known. For B2W2 Route 19, keep any legal 2–4 value;
            // otherwise clamp to the nearest legal boundary instead of guessing another field.
            val encounterMetFix=if(p.originGame in 22..23 && p.metLocation==124 && p.species in setOf(504,505,509,510) && p.metLevel !in 2..4) p.metLevel.coerceIn(2,4) else null
            val canFix=global!=null && errors.isNotEmpty() && (replacement!=null || moveFixes>0 || ppFixes>0 || emptyPpFixes>0 || encounterMetFix!=null)
            if(canFix){
                b.setNeutralButton("Fix Detected Issues"){_,_->
                    val fixAbility=replacement
                    val abilityId=fixAbility?.first ?: p.ability
                    val abilitySlot=fixAbility?.second ?: p.abilityNumber
                    val v=Gen5EditValues(p.nickname,p.otName,p.experience,p.heldItem,p.friendship,p.nature,fixedMoves,fixedPp,p.ivs.copyOf(),p.evs.copyOf(),p.shiny,abilityId,abilitySlot,p.form,p.originGame,p.eggLocation,p.metLocation,p.ball,encounterMetFix ?: p.metLevel,p.otGender,p.fatefulEncounter)
                    val changes=mutableListOf<String>()
                    if(fixAbility!=null)changes.add("replace invalid ability with Ability #$abilityId in slot $abilitySlot")
                    if(moveFixes>0)changes.add("clear $moveFixes illegal move${if(moveFixes==1)"" else "s"} and its PP")
                    if(ppFixes>0)changes.add("clamp PP on $ppFixes move${if(ppFixes==1)"" else "s"} to the Gen 5 maximum")
                    if(emptyPpFixes>0)changes.add("clear PP from $emptyPpFixes empty move slot${if(emptyPpFixes==1)"" else "s"}")
                    if(encounterMetFix!=null)changes.add("change met level from ${p.metLevel} to $encounterMetFix for the certified Route 19 encounter")
                    AlertDialog.Builder(this).setTitle("Fix safe Gen 5 issues?").setMessage("PSE will ${changes.joinToString(", ")}. Other Pokémon data will be preserved. PSE will verify PK5/save checksums and then run Deep Legality again.").setNegativeButton("Cancel",null).setPositiveButton("Apply safe fix"){_,_->gen5LegalityRecheckAfterEdit=true;applyGen5PokemonEdit(location,p,v,null)}.show()
                }
            }
            b.show()
        }
    }

}
